/**
 * SigilOS — Dofus Ladder Scraper Worker
 * Deployed on Cloudflare Workers (edge network)
 *
 * Purpose: Fetch success points from the official Dofus ladder
 * Route:   GET /?server_id=295&name=Pseudo
 *
 * Auth: X-SigilOS-Key header required
 */

export default {
    async fetch(request, env, ctx) {
        if (request.method === "OPTIONS") {
            return new Response(null, {
                headers: {
                    "Access-Control-Allow-Origin": "*",
                    "Access-Control-Allow-Methods": "GET",
                    "Access-Control-Allow-Headers": "X-SigilOS-Key",
                }
            });
        }

        if (request.method !== "GET") {
            return new Response("Method not allowed", { status: 405 });
        }

        // 🔐 Secret check
        const workerSecret = env.WORKER_SECRET;
        if (workerSecret) {
            const providedSecret = request.headers.get("X-SigilOS-Key");
            if (providedSecret !== workerSecret) {
                return new Response(JSON.stringify({ error: "Unauthorized" }), {
                    status: 401,
                    headers: { "Content-Type": "application/json" }
                });
            }
        }

        const url = new URL(request.url);
        const serverId = url.searchParams.get("server_id") || "295";
        const name = url.searchParams.get("name");
        const type = url.searchParams.get("type") || "succes";

        if (!name) {
            return new Response(JSON.stringify({ error: "Character name is required" }), {
                status: 400,
                headers: { "Content-Type": "application/json" }
            });
        }

        const validTypes = ["succes", "general"];
        if (!validTypes.includes(type)) {
            return new Response(JSON.stringify({ error: "Invalid type param" }), { status: 400 });
        }

        const ladderUrl = `https://www.dofus.com/fr/mmorpg/communaute/ladder/${type}?server_id=${serverId}&name=${encodeURIComponent(name)}`;

        try {
            // --- MANUALLY HANDLE REDIRECTS TO CAPTURE COOKIES (ANKAMA SSO BYPASS) ---
            let currentUrl = ladderUrl;
            let cookies = "";
            let response;
            let redirectCount = 0;
            const maxRedirects = 10;

            const baseHeaders = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,all;q=0.8",
                "Accept-Language": "fr-FR,fr;q=0.9",
                "Cache-Control": "no-cache",
                "Connection": "keep-alive",
            };

            while (redirectCount < maxRedirects) {
                response = await fetch(currentUrl, {
                    method: "GET",
                    headers: {
                        ...baseHeaders,
                        ...(cookies ? { "Cookie": cookies } : {}),
                        "Referer": "https://www.dofus.com/fr/mmorpg/communaute/ladder/succes",
                    },
                    redirect: "manual"
                });

                // Extract new cookies
                const setCookieHeaders = response.headers.getSetCookie ? response.headers.getSetCookie() : [response.headers.get("Set-Cookie")].filter(Boolean);
                if (setCookieHeaders.length > 0) {
                    const newCookies = setCookieHeaders.map(c => c.split(';')[0]).join('; ');
                    cookies = cookies ? `${cookies}; ${newCookies}` : newCookies;
                }

                if (response.status >= 300 && response.status < 400) {
                    const location = response.headers.get("Location");
                    if (!location) break;
                    
                    // Handle relative locations
                    currentUrl = new URL(location, currentUrl).href;
                    redirectCount++;
                } else {
                    break;
                }
            }

            if (!response || !response.ok) {
                return new Response(JSON.stringify({ 
                    error: `Dofus.com returned ${response ? response.status : 'no response'}`,
                    debug_url: currentUrl 
                }), {
                    status: response ? response.status : 500,
                    headers: { "Content-Type": "application/json" }
                });
            }

            const html = await response.text();

            // Scoping to the table body to avoid false positives
            const tableBodyMatch = html.match(/<tbody[^>]*>([\s\S]*?)<\/tbody>/i);
            const tableBody = tableBodyMatch ? tableBodyMatch[1] : html;

            // --- ROBUST PARSING STRATEGY ---
            // 1. Split by <tr> to isolate rows
            const rows = html.split(/<tr[^>]*>/i);
            let targetRow = "";
            
            const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const nameRegex = new RegExp(`<span[^>]*class="ak-nickname"[^>]*>\\s*${escapedName}\\s*<\\/span>`, "i");

            for (const row of rows) {
                if (nameRegex.test(row)) {
                    targetRow = row;
                    break;
                }
            }

            if (!targetRow) {
                // FALLBACK: maybe the span class is different or missing
                const simpleNameRegex = new RegExp(`>\\s*${escapedName}\\s*<`, "i");
                for (const row of rows) {
                    if (simpleNameRegex.test(row)) {
                        targetRow = row;
                        break;
                    }
                }
            }

            if (!targetRow) {
                return new Response(JSON.stringify({ 
                    found: false, 
                    error: `Character "${name}" not found in any table row.`,
                    name,
                    serverId,
                    debug: "Row not found"
                }), {
                    status: 200,
                    headers: { "Content-Type": "application/json" }
                });
            }

            // 2. Extract cells from the target row
            const cells = targetRow.split(/<td[^>]*>/i).slice(1).map(c => c.split(/<\/td>/i)[0]); 
            
            // According to inspection:
            // 0: Rank, 1: Name, 2: Class, 3: Server, 4: Level, 5: Points
            if (cells.length < 6) {
                return new Response(JSON.stringify({ 
                    found: false, 
                    error: "Character found but table structure is unexpected.",
                    cellsFound: cells.length,
                    targetRowSnippet: targetRow.substring(0, 200)
                }), {
                    status: 200,
                    headers: { "Content-Type": "application/json" }
                });
            }

            const rawLevel = cells[4].replace(/<[^>]*>/g, "").trim();
            const rawValue = cells[5].replace(/<[^>]*>/g, "").trim();

            const level = parseInt(rawLevel.replace(/\s/g, ""), 10);
            
            // In 'general' it's Total XP, in 'succes' it's Points.
            const valueAsNumber = parseInt(rawValue.replace(/\s/g, ""), 10);

            if (isNaN(level) || isNaN(valueAsNumber)) {
                 return new Response(JSON.stringify({ 
                    found: false, 
                    error: "Could not parse numeric values for level or points/xp.",
                    rawLevel,
                    rawValue
                }), {
                    status: 200,
                    headers: { "Content-Type": "application/json" }
                });
            }

            const responsePayload = {
                found: true,
                success: true,
                name,
                serverId,
                level,
                timestamp: new Date().toISOString()
            };

            if (type === "succes") {
                responsePayload.points = valueAsNumber;
            } else if (type === "general") {
                // Remove everything that's not a digit to avoid trailing page content/scripts
                responsePayload.totalXp = rawValue.replace(/\D/g, ""); 
                responsePayload.classe = cells[2].replace(/<[^>]*>/g, "").trim();
            }

            return new Response(JSON.stringify(responsePayload), {
                status: 200,
                headers: {
                    "Content-Type": "application/json",
                    "Access-Control-Allow-Origin": "*",
                    "Cache-Control": "public, max-age=3600",
                }
            });

        } catch (err) {
            return new Response(
                JSON.stringify({ error: "Worker fetch failed", details: err.message }),
                { status: 500, headers: { "Content-Type": "application/json" } }
            );
        }
    }
};

/**
 * SigilOS — Dofusbook Proxy Worker
 * Deployed on Cloudflare Workers (edge network)
 *
 * Purpose: Fetch Dofusbook build data from CF edge IPs (not blocked like our VPS)
 * Route:   GET /:id  → https://www.dofusbook.net/api/stuffs/dofus/public/:id
 *
 * Auth: X-SigilOS-Key header required (set WORKER_SECRET in CF env vars)
 *       Protects against quota abuse while keeping Dofusbook calls clean.
 */

export default {
    async fetch(request, env, ctx) {
        if (request.method === "OPTIONS") {
            return new Response(null, {
                headers: {
                    "Access-Control-Allow-Origin": "*",
                    "Access-Control-Allow-Methods": "GET",
                    "Access-Control-Allow-Headers": "X-SigilOS-Key",
                }
            });
        }

        if (request.method !== "GET") {
            return new Response("Method not allowed", { status: 405 });
        }

        // 🔐 Secret check — only our Next.js server can call this
        // WORKER_SECRET is set in Cloudflare Dashboard → Worker → Settings → Variables
        const workerSecret = env.WORKER_SECRET;
        if (workerSecret) {
            const providedSecret = request.headers.get("X-SigilOS-Key");
            if (providedSecret !== workerSecret) {
                return new Response(JSON.stringify({ error: "Unauthorized" }), {
                    status: 401,
                    headers: { "Content-Type": "application/json" }
                });
            }
        }

        const url = new URL(request.url);
        const pathParts = url.pathname.split("/").filter(Boolean);
        const buildId = pathParts[pathParts.length - 1];

        if (!buildId || !/^\d+$/.test(buildId)) {
            return new Response(JSON.stringify({ error: "Invalid build ID" }), {
                status: 400,
                headers: { "Content-Type": "application/json" }
            });
        }

        const dofusbookUrl = `https://www.dofusbook.net/api/stuffs/dofus/public/${buildId}`;

        try {
            // NOTE: Do NOT forward the X-SigilOS-Key to Dofusbook — only used between us and the Worker
            const response = await fetch(dofusbookUrl, {
                headers: {
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
                    "Accept": "application/json, text/plain, */*",
                    "Accept-Language": "fr-FR,fr;q=0.9",
                    "Referer": `https://www.dofusbook.net/fr/equipement/${buildId}`,
                    "Origin": "https://www.dofusbook.net",
                    "Sec-Fetch-Dest": "empty",
                    "Sec-Fetch-Mode": "cors",
                    "Sec-Fetch-Site": "same-origin",
                }
            });

            const body = await response.text();

            return new Response(body, {
                status: response.status,
                headers: {
                    "Content-Type": response.headers.get("Content-Type") || "application/json",
                    "Access-Control-Allow-Origin": "*",
                    "Cache-Control": "public, max-age=86400",
                    "X-Proxied-By": "SigilOS-CF-Worker",
                    "X-Dofusbook-Status": String(response.status),
                }
            });

        } catch (err) {
            return new Response(
                JSON.stringify({ error: "Worker fetch failed", details: err.message }),
                { status: 500, headers: { "Content-Type": "application/json" } }
            );
        }
    }
};

