const token = process.env.DISCORD_BOT_TOKEN;

if (!token) {
    console.error('[Discord Bot] ❌ DISCORD_BOT_TOKEN not found in environment variables');
    process.exit(1);
}

client.login(token).catch((error) => {
    console.error('[Discord Bot] ❌ Failed to login:', error);
    process.exit(1);
});

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { isSuperAdmin } from "@/server/actions/super-admin-actions";
import { db } from "@/lib/prisma";
import { redis } from "@/lib/redis";

/**
 * Admin-only endpoint: force re-warm all Dofusbook Redis caches for a guild.
 * GET /api/admin/warm-dofusbook?guildId=xxx
 */
export async function GET(request: Request) {
    const session = await auth();
    if (!session?.user?.id) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const isGod = await isSuperAdmin();
    if (!isGod) {
        return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const { searchParams } = new URL(request.url);
    const guildId = searchParams.get("guildId");
    if (!guildId) {
        return NextResponse.json({ error: "guildId required" }, { status: 400 });
    }

    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true }
    });

    if (!guildConfig) {
        return NextResponse.json({ error: "Guild not found" }, { status: 404 });
    }

    // Collect all Dofusbook URLs from the guild
    const profiles = await db.userProfile.findMany({
        where: { guildId: guildConfig.id, status: "ACTIVE" },
        select: { dofusBookLinks: true }
    });

    const urlIdPairs: { url: string; id: string }[] = [];
    profiles.forEach(p => {
        const links = (p.dofusBookLinks as any[]) || [];
        links.forEach(link => {
            if (link?.url) {
                const m = link.url.match(
                    /(?:equipement\/(?:[a-z]+\/)?(\d+)|d-bk\.net\/(?:fr\/)?d\/([a-zA-Z0-9]+))/i
                );
                const id = m ? (m[1] || m[2]) : null;
                if (id) urlIdPairs.push({ url: link.url, id });
            }
        });
    });

    // Check which ones are NOT in Redis
    const uncached: string[] = [];
    for (const pair of urlIdPairs) {
        const exists = await redis.exists(`dofusbook:build:${pair.id}`);
        if (!exists) uncached.push(pair.id);
    }

    const baseUrl = process.env.NEXTAUTH_URL || "http://localhost:3000";
    const results: { id: string; status: number; cache: string | null }[] = [];

    // Sequentially fetch (with delay) to avoid rate limits
    for (const id of uncached) {
        try {
            const res = await fetch(`${baseUrl}/api/dofusbook/proxy/${id}`, {
                headers: { "x-internal-warm": "1" }
            });
            results.push({ id, status: res.status, cache: res.headers.get("X-Cache") });
            // 600ms delay between each fetch
            await new Promise(r => setTimeout(r, 600));
        } catch (e) {
            results.push({ id, status: 0, cache: "ERROR" });
        }
    }

    return NextResponse.json({
        total: urlIdPairs.length,
        alreadyCached: urlIdPairs.length - uncached.length,
        warmed: results.length,
        results
    });
}

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import redis from "@/lib/redis";
import { NextRequest, NextResponse } from "next/server";
import { chatOnlineUsersKey, chatPubSubChannel, CHAT_TTL_SECONDS } from "@/lib/chat-helpers";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * PATCH /api/chat/guild/[guildId]/presence
 * Updates the isActive status of a specific connection in Redis.
 * Called when the user minimizes or re-opens the chat widget.
 */
export async function PATCH(
    req: NextRequest,
    { params }: { params: Promise<{ guildId: string }> }
) {
    const session = await auth();
    if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const { guildId: discordGuildId } = await params;

    let body: { connectionId?: string; isActive?: boolean };
    try {
        body = await req.json();
    } catch {
        return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
    }

    const { connectionId, isActive } = body;
    if (!connectionId || typeof isActive !== "boolean") {
        return NextResponse.json({ error: "Missing connectionId or isActive" }, { status: 400 });
    }

    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId },
        select: { id: true },
    });
    if (!guild) return NextResponse.json({ error: "Guild not found" }, { status: 404 });

    const profile = await (db.userProfile as any).findFirst({
        where: { guildId: guild.id, userId: session.user.id, status: "ACTIVE" },
        select: { id: true, discordNickname: true, pseudoDofus: true, user: { select: { image: true, name: true } } },
    });
    if (!profile) return NextResponse.json({ error: "Forbidden" }, { status: 403 });

    const onlineKey = chatOnlineUsersKey(discordGuildId);
    const fieldId = `${session.user.id}:${connectionId}`;

    // Read current value
    const current = await redis.hget(onlineKey, fieldId);
    if (!current) {
        // Connection not found (expired or never registered) — no-op
        return NextResponse.json({ ok: true, note: "connection_not_found" });
    }

    try {
        const parsed = JSON.parse(current);
        const wasActive = parsed.isActive === true;

        // Update isActive in Redis
        await redis.hset(onlineKey, fieldId, JSON.stringify({
            ...parsed,
            isActive,
            lastSeen: Date.now(),
        }));
        await redis.expire(onlineKey, CHAT_TTL_SECONDS);

        // If active status changed, broadcast updated presence list
        if (wasActive !== isActive) {
            const all = await redis.hgetall(onlineKey);
            const now = Date.now();
            const CONNECTION_TTL_SECONDS = 60;
            const activeUsers: Record<string, { id: string; name: string; image?: string }> = {};

            for (const [_fId, val] of Object.entries(all)) {
                try {
                    const p = JSON.parse(val);
                    const age = (now - (p.lastSeen || 0)) / 1000;
                    if (p.isActive === true && age < CONNECTION_TTL_SECONDS) {
                        activeUsers[p.id] = { id: p.id, name: p.name, image: p.image };
                    }
                } catch { }
            }

            const onlineUsers = Object.values(activeUsers);
            const presenceMsg = {
                id: `presence-update-${Date.now()}-${session.user.id}`,
                type: "presence",
                text: isActive
                    ? `${parsed.name} a rejoint le chat de guilde`
                    : `${parsed.name} a quitté le chat`,
                authorId: "system",
                authorName: "Système",
                createdAt: new Date().toISOString(),
                onlineUsers,
            };

            await redis.publish(chatPubSubChannel(discordGuildId), JSON.stringify(presenceMsg));
        }

        return NextResponse.json({ ok: true });
    } catch (e) {
        console.error("[PATCH presence] Error:", e);
        return NextResponse.json({ error: "Internal error" }, { status: 500 });
    }
}

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import redis from "@/lib/redis";
import { NextRequest } from "next/server";
import { chatKey, chatPubSubChannel, CHAT_TTL_SECONDS, chatOnlineUsersKey, CHAT_HISTORY_LIMIT } from "@/lib/chat-helpers";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

// TTL des connexions dans Redis — si le heartbeat s'arrête (tab crash, réseau), le champ expire
const CONNECTION_TTL_SECONDS = 60; // 3× le heartbeat interval (20s)

/**
 * SSE endpoint — streams live chat messages for a guild.
 * GET /api/chat/guild/[guildId]/stream
 */
export async function GET(
    req: NextRequest,
    { params }: { params: Promise<{ guildId: string }> }
) {
    const session = await auth();
    if (!session?.user?.id) return new Response("Unauthorized", { status: 401 });

    const { guildId: discordGuildId } = await params;

    // Guild membership check
    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId },
        select: { id: true },
    });
    if (!guild) return new Response("Guild not found", { status: 404 });

    const profile = await (db.userProfile as any).findFirst({
        where: { guildId: guild.id, userId: session.user.id, status: "ACTIVE" },
        select: { id: true, discordNickname: true, pseudoDofus: true, user: { select: { image: true, name: true } } },
    });
    if (!profile) return new Response("Forbidden", { status: 403 });

    // Module chat supprimé — accès libre si membre authentifié

    const encoder = new TextEncoder();
    let closed = false;

    // Presence Data
    const searchParams = req.nextUrl.searchParams;
    const connectionId = searchParams.get("connectionId") || Math.random().toString(36).slice(2);
    const isActive = searchParams.get("active") === "true";

    const userData = {
        id: session.user.id,
        name: profile.discordNickname || profile.pseudoDofus || profile.user?.name || session.user.name || "Inconnu",
        image: profile.user?.image || session.user.image || undefined,
    };
    const onlineKey = chatOnlineUsersKey(discordGuildId);
    const pubChannel = chatPubSubChannel(discordGuildId);

    // One-time fix: Delete if old non-hash type exists
    const keyTypeBefore = await redis.type(onlineKey);
    if (keyTypeBefore !== "hash" && keyTypeBefore !== "none") await redis.del(onlineKey);

    // Field: userId:connectionId — unique per browser tab
    const fieldId = `${userData.id}:${connectionId}`;
    const fieldValue = JSON.stringify({ ...userData, lastSeen: Date.now(), isActive, ttl: CONNECTION_TTL_SECONDS });

    // Helper: Get all unique users who are ACTIVELY in the chat (isActive=true, lastSeen recent)
    const getAllOnlineUsers = async (): Promise<{ id: string; name: string; image?: string }[]> => {
        try {
            const all = await redis.hgetall(onlineKey);
            const now = Date.now();
            const activeUsers: Record<string, { id: string; name: string; image?: string }> = {};

            for (const [_fId, val] of Object.entries(all)) {
                try {
                    const p = JSON.parse(val);
                    // Must be active AND have been seen within CONNECTION_TTL_SECONDS
                    const age = (now - (p.lastSeen || 0)) / 1000;
                    if (p.isActive === true && age < CONNECTION_TTL_SECONDS) {
                        activeUsers[p.id] = { id: p.id, name: p.name, image: p.image };
                    }
                } catch { }
            }
            return Object.values(activeUsers);
        } catch { return []; }
    };

    // Helper: Get active connections for a specific user (excluding stale ones)
    const getActiveConnectionsForUser = async (userId: string) => {
        const all = await redis.hgetall(onlineKey);
        const now = Date.now();
        return Object.entries(all).filter(([fId, val]) => {
            if (!fId.startsWith(`${userId}:`)) return false;
            try {
                const p = JSON.parse(val);
                const age = (now - (p.lastSeen || 0)) / 1000;
                return p.isActive === true && age < CONNECTION_TTL_SECONDS;
            } catch { return false; }
        });
    };

    // Check if user was already active before this connection
    const activeConnectionsBefore = await getActiveConnectionsForUser(userData.id);
    const wasAlreadyActive = activeConnectionsBefore.length > 0;

    // Register this connection in Redis
    await redis.hset(onlineKey, fieldId, fieldValue);
    await redis.expire(onlineKey, CHAT_TTL_SECONDS);

    // Subscribe to the guild's pub/sub channel
    const subscriber = redis.duplicate();
    await subscriber.subscribe(pubChannel);

    const stream = new ReadableStream({
        async start(controller) {

            // Heartbeat every 20s: refreshes lastSeen AND isActive in Redis
            const heartbeat = setInterval(async () => {
                if (closed) { clearInterval(heartbeat); return; }
                try {
                    controller.enqueue(encoder.encode(": ping\n\n"));
                    // CRITICAL: persist isActive on every heartbeat so stale detection works
                    await redis.hset(onlineKey, fieldId, JSON.stringify({
                        ...userData,
                        lastSeen: Date.now(),
                        isActive,  // preserve original active state
                    }));
                    await redis.expire(onlineKey, CHAT_TTL_SECONDS);
                } catch { clearInterval(heartbeat); }
            }, 20_000);

            // Sweep stale connections every 45s and broadcast updated user list
            const staleSweep = setInterval(async () => {
                if (closed) { clearInterval(staleSweep); return; }
                try {
                    const all = await redis.hgetall(onlineKey);
                    const now = Date.now();
                    const staleFields: string[] = [];

                    for (const [fId, val] of Object.entries(all)) {
                        try {
                            const p = JSON.parse(val);
                            const age = (now - (p.lastSeen || 0)) / 1000;
                            if (age >= CONNECTION_TTL_SECONDS) staleFields.push(fId);
                        } catch {
                            staleFields.push(fId); // invalid entry, remove
                        }
                    }

                    if (staleFields.length > 0) {
                        await redis.hdel(onlineKey, ...staleFields);
                        const freshUsers = await getAllOnlineUsers();
                        const sweepMsg = {
                            id: `presence-sweep-${Date.now()}`,
                            type: "presence",
                            text: "Presence updated",
                            authorId: "system",
                            authorName: "Système",
                            createdAt: new Date().toISOString(),
                            onlineUsers: freshUsers,
                        };
                        await redis.publish(pubChannel, JSON.stringify(sweepMsg));
                    }
                } catch { }
            }, 45_000);

            // 1. Initial ping
            controller.enqueue(encoder.encode(": ping\n\n"));

            // 2. Initial presence list — send to connecting client
            const currentOnlineUsers = await getAllOnlineUsers();
            controller.enqueue(encoder.encode(`data: ${JSON.stringify({
                id: "presence-init",
                type: "presence",
                text: "Initial presence",
                authorId: "system",
                authorName: "Système",
                createdAt: new Date().toISOString(),
                onlineUsers: currentOnlineUsers
            })}\n\n`));

            // 3. Join Message — broadcast to others if user becomes newly active
            if (isActive && !wasAlreadyActive) {
                const updatedUsers = await getAllOnlineUsers();
                const joinMsg = {
                    id: `presence-join-${Date.now()}-${userData.id}`,
                    type: "presence",
                    text: `${userData.name} a rejoint le chat de guilde`,
                    authorId: "system",
                    authorName: "Système",
                    createdAt: new Date().toISOString(),
                    onlineUsers: updatedUsers,
                };

                const listKey = chatKey(discordGuildId);
                await redis.rpush(listKey, JSON.stringify(joinMsg));
                await redis.ltrim(listKey, -CHAT_HISTORY_LIMIT, -1);
                await redis.publish(pubChannel, JSON.stringify(joinMsg));

                controller.enqueue(encoder.encode(`data: ${JSON.stringify(joinMsg)}\n\n`));
            }

            // 4. Subscribe to new messages
            subscriber.on("message", (_channel, data) => {
                if (closed) return;
                try { controller.enqueue(encoder.encode(`data: ${data}\n\n`)); } catch { }
            });

            // 5. Cleanup on client disconnect (tab close, navigation, minimize→close)
            req.signal.addEventListener("abort", async () => {
                if (closed) return;
                closed = true;
                clearInterval(heartbeat);
                clearInterval(staleSweep);

                try {
                    // Remove this specific connection from Redis immediately
                    await redis.hdel(onlineKey, fieldId);

                    // Small delay to allow multi-tab: check if any active connections remain
                    await new Promise(resolve => setTimeout(resolve, 1000));

                    const remainingActive = await getActiveConnectionsForUser(userData.id);

                    // Only broadcast "leave" if user had NO other active tab open
                    if (isActive && remainingActive.length === 0) {
                        const updatedUsers = await getAllOnlineUsers();
                        const leaveMsg = {
                            id: `presence-leave-${Date.now()}-${userData.id}`,
                            type: "presence",
                            text: `${userData.name} a quitté le chat`,
                            authorId: "system",
                            authorName: "Système",
                            createdAt: new Date().toISOString(),
                            onlineUsers: updatedUsers,
                        };

                        const listKey = chatKey(discordGuildId);
                        // Use a fresh redis client — subscriber may be closing
                        await redis.rpush(listKey, JSON.stringify(leaveMsg));
                        await redis.ltrim(listKey, -CHAT_HISTORY_LIMIT, -1);
                        await redis.publish(pubChannel, JSON.stringify(leaveMsg));
                    }
                } catch (e) {
                    console.error("[SSE] Error during cleanup:", e);
                } finally {
                    try { await subscriber.unsubscribe(); subscriber.disconnect(); } catch { }
                    try { controller.close(); } catch { }
                }
            });
        },
    });

    return new Response(stream, {
        headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
            "Content-Encoding": "identity",
        },
    });
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/prisma";
import { unlink } from "fs/promises";
import { existsSync } from "fs";
import path from "path";
import { sendChannelMessage } from "@/server/discord";
import { logger } from "@/lib/logger";

// ---------------------------------------------------------------------------
// CLEANUP: supprime les screenshots de preuve
//  - Prêts/Coffre : après 7 jours
//  - Missions / Succès / Kamas PENDING : après 24h (auto-suppression si non validé)
// Route sécurisée par CRON_SECRET (appelée par le cron nightly du serveur)
//
// Appel depuis maintenance.sh (crontab 4h00):
//   curl -s -X POST https://sigilos.fr/api/cron/cleanup-proofs \
//     -H "Authorization: Bearer $CRON_SECRET"
// ---------------------------------------------------------------------------

const UPLOAD_BASE_DIR = path.join(process.cwd(), "public", "uploads", "guilds");
const PROOF_EXPIRY_DAYS = 7;
const PENDING_EXPIRY_HOURS = 24;

// Safely delete a local file from /uploads/guilds/{guildId}/proofs/{filename}
async function deleteLocalProof(proofUrl: string, internalGuildId: string): Promise<boolean> {
    try {
        const expectedPrefix = `/uploads/guilds/${internalGuildId}/proofs/`;
        if (!proofUrl.startsWith(expectedPrefix)) return false;

        const filename = proofUrl.slice(expectedPrefix.length);
        // Security: only allow UUID.webp filenames
        if (!/^[a-f0-9-]{36}\.webp$/.test(filename)) return false;

        const filePath = path.join(UPLOAD_BASE_DIR, internalGuildId, "proofs", filename);
        const normalizedPath = path.normalize(filePath);
        const expectedBase = path.normalize(path.join(UPLOAD_BASE_DIR, internalGuildId, "proofs"));
        if (!normalizedPath.startsWith(expectedBase)) return false;

        if (existsSync(filePath)) {
            await unlink(filePath);
        }
        return true;
    } catch {
        return false;
    }
}

// Safely delete a mission/achievement proof from /uploads/proofs/{discordGuildId}/{filename}
async function deleteMissionProof(proofUrl: string): Promise<boolean> {
    try {
        if (!proofUrl.startsWith("/uploads/proofs/")) return false;
        const parts = proofUrl.replace("/uploads/proofs/", "").split("/");
        if (parts.length !== 2) return false;
        const [discordGuildId, filename] = parts;
        // Security: only safe filename chars
        if (!/^[a-f0-9-]{36}\.webp$/.test(filename)) return false;
        if (!/^\d{17,20}$/.test(discordGuildId)) return false;

        const filePath = path.join(process.cwd(), "public", "uploads", "proofs", discordGuildId, filename);
        const safeBase = path.join(process.cwd(), "public", "uploads", "proofs", discordGuildId);
        if (!path.normalize(filePath).startsWith(path.normalize(safeBase))) return false;

        if (existsSync(filePath)) await unlink(filePath);
        return true;
    } catch {
        return false;
    }
}

// Get Discord user ID from NextAuth account
async function getDiscordId(userId: string): Promise<string | null> {
    const account = await db.account.findFirst({
        where: { userId, provider: "discord" },
        select: { providerAccountId: true },
    });
    return account?.providerAccountId ?? null;
}

export async function POST(request: NextRequest) {
    // Security: validate cron secret
    const cronSecret = process.env.CRON_SECRET;
    if (!cronSecret) {
        logger.error("[cleanup-proofs] CRON_SECRET not configured");
        return NextResponse.json({ error: "Not configured" }, { status: 500 });
    }

    const authHeader = request.headers.get("authorization");
    if (!authHeader || authHeader !== `Bearer ${cronSecret}`) {
        logger.warn("[cleanup-proofs] Unauthorized cron attempt");
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - PROOF_EXPIRY_DAYS);

    const stats = {
        loansProcessed: 0,
        vaultProcessed: 0,
        filesDeleted: 0,
        notificationsSent: 0,
        errors: [] as string[],
    };

    // ---------------------------------------------------------------------------
    // 1. LOANS — proofUrl et returnProofUrl expirés
    // ---------------------------------------------------------------------------
    try {
        const expiredLoans = await db.guildLoan.findMany({
            where: {
                lentAt: { lt: cutoff },
                proofUrl: { not: null },
            },
            select: {
                id: true,
                proofUrl: true,
                returnProofUrl: true,
                description: true,
                guildId: true,
                guild: {
                    select: {
                        discordGuildId: true,
                        loansNotifyChannelId: true,
                    },
                },
                lender: {
                    select: {
                        userId: true,
                        pseudoDofus: true,
                        discordNickname: true,
                        user: { select: { name: true } },
                    },
                },
                borrower: {
                    select: {
                        userId: true,
                        pseudoDofus: true,
                        discordNickname: true,
                        user: { select: { name: true } },
                    },
                },
            },
        });

        for (const loan of expiredLoans) {
            stats.loansProcessed++;
            const urlsToDelete = [loan.proofUrl, loan.returnProofUrl].filter(Boolean) as string[];

            try {
                // Delete files
                for (const url of urlsToDelete) {
                    const deleted = await deleteLocalProof(url, loan.guildId);
                    if (deleted) stats.filesDeleted++;
                }

                // Clear URLs in DB
                await db.guildLoan.update({
                    where: { id: loan.id },
                    data: { proofUrl: null, returnProofUrl: null },
                });

                // Discord ping notification
                if (loan.guild.loansNotifyChannelId) {
                    const lenderDiscordId = await getDiscordId(loan.lender.userId);
                    const borrowerDiscordId = await getDiscordId(loan.borrower.userId);

                    const lenderName = loan.lender.pseudoDofus || loan.lender.discordNickname || loan.lender.user.name || "Prêteur";
                    const borrowerName = loan.borrower.pseudoDofus || loan.borrower.discordNickname || loan.borrower.user.name || "Emprunteur";

                    const mentions = [
                        lenderDiscordId ? `<@${lenderDiscordId}>` : lenderName,
                        borrowerDiscordId ? `<@${borrowerDiscordId}>` : borrowerName,
                    ].join(" ");

                    await sendChannelMessage(
                        loan.guild.loansNotifyChannelId,
                        mentions,
                        {
                            embedTitle: "🗑️ Screenshot de preuve expiré",
                            embedColor: 0x71717a, // zinc
                            embedFooter: "SigilOS • Rétention 7 jours",
                            fields: [
                                { name: "📋 Prêt", value: loan.description, inline: false },
                                { name: "📎 Prêteur", value: lenderName, inline: true },
                                { name: "🏦 Emprunteur", value: borrowerName, inline: true },
                                { name: "⏰ Info", value: `Le screenshot a été automatiquement supprimé après ${PROOF_EXPIRY_DAYS} jours. Si un litige subsiste, contactez un admin.`, inline: false },
                            ],
                        }
                    );
                    stats.notificationsSent++;
                }
            } catch (err) {
                stats.errors.push(`Loan ${loan.id}: ${err}`);
            }
        }
    } catch (err) {
        stats.errors.push(`Loans batch error: ${err}`);
    }

    // ---------------------------------------------------------------------------
    // 2. VAULT — proofUrl expirés
    // ---------------------------------------------------------------------------
    try {
        const expiredVault = await db.vaultEntry.findMany({
            where: {
                createdAt: { lt: cutoff },
                proofUrl: { not: null },
            },
            select: {
                id: true,
                proofUrl: true,
                itemName: true,
                action: true,
                guildId: true,
                guild: {
                    select: {
                        discordGuildId: true,
                        loansNotifyChannelId: true,
                    },
                },
                profile: {
                    select: {
                        userId: true,
                        pseudoDofus: true,
                        discordNickname: true,
                        user: { select: { name: true } },
                    },
                },
            },
        });

        for (const entry of expiredVault) {
            stats.vaultProcessed++;
            try {
                if (entry.proofUrl) {
                    const deleted = await deleteLocalProof(entry.proofUrl, entry.guildId);
                    if (deleted) stats.filesDeleted++;
                }

                await db.vaultEntry.update({
                    where: { id: entry.id },
                    data: { proofUrl: null },
                });

                // Discord ping notification
                if (entry.guild.loansNotifyChannelId) {
                    const memberDiscordId = await getDiscordId(entry.profile.userId);
                    const memberName = entry.profile.pseudoDofus || entry.profile.discordNickname || entry.profile.user.name || "Membre";
                    const mention = memberDiscordId ? `<@${memberDiscordId}>` : memberName;
                    const actionLabel = entry.action === "DEPOSIT" ? "Dépôt" : "Retrait";

                    await sendChannelMessage(
                        entry.guild.loansNotifyChannelId,
                        mention,
                        {
                            embedTitle: "🗑️ Screenshot coffre expiré",
                            embedColor: 0x71717a,
                            embedFooter: "SigilOS • Rétention 7 jours",
                            fields: [
                                { name: "📦 Item", value: entry.itemName, inline: true },
                                { name: "⚡ Action", value: actionLabel, inline: true },
                                { name: "👤 Membre", value: memberName, inline: true },
                                { name: "⏰ Info", value: `Screenshot supprimé automatiquement après ${PROOF_EXPIRY_DAYS} jours.`, inline: false },
                            ],
                        }
                    );
                    stats.notificationsSent++;
                }
            } catch (err) {
                stats.errors.push(`VaultEntry ${entry.id}: ${err}`);
            }
        }
    } catch (err) {
        stats.errors.push(`Vault batch error: ${err}`);
    }

    // ---------------------------------------------------------------------------
    // 3. LOANS ARCHIVÉS — suppression hard après 30 jours
    //    Cible : status RETURNED ou CANCELLED avec returnedAt (ou lentAt) > 30j
    // ---------------------------------------------------------------------------
    const ARCHIVE_EXPIRY_DAYS = 30;
    const archiveCutoff = new Date();
    archiveCutoff.setDate(archiveCutoff.getDate() - ARCHIVE_EXPIRY_DAYS);

    const extraStats = { loansDeleted: 0, archiveNotifsSent: 0 };

    try {
        const expiredArchivedLoans = await db.guildLoan.findMany({
            where: {
                status: { in: ["RETURNED", "CANCELLED"] },
                OR: [
                    { returnedAt: { lt: archiveCutoff } },
                    { lentAt: { lt: archiveCutoff }, returnedAt: null },
                ],
            },
            select: {
                id: true,
                description: true,
                status: true,
                proofUrl: true,
                returnProofUrl: true,
                guildId: true,
                guild: {
                    select: {
                        discordGuildId: true,
                        loansNotifyChannelId: true,
                    },
                },
                lender: {
                    select: {
                        userId: true,
                        pseudoDofus: true,
                        discordNickname: true,
                        user: { select: { name: true } },
                    },
                },
                borrower: {
                    select: {
                        userId: true,
                        pseudoDofus: true,
                        discordNickname: true,
                        user: { select: { name: true } },
                    },
                },
            },
        });

        for (const loan of expiredArchivedLoans) {
            try {
                // 1. Cleanup fichiers physiques résiduels
                const residualUrls = [loan.proofUrl, loan.returnProofUrl].filter(Boolean) as string[];
                for (const url of residualUrls) {
                    const deleted = await deleteLocalProof(url, loan.guildId);
                    if (deleted) stats.filesDeleted++;
                }

                // 2. Suppression hard en DB
                await db.guildLoan.delete({ where: { id: loan.id } });
                extraStats.loansDeleted++;

                // 3. Ping Discord optionnel (non-bloquant)
                if (loan.guild.loansNotifyChannelId) {
                    const lenderName = loan.lender.pseudoDofus || loan.lender.discordNickname || loan.lender.user.name || "Prêteur";
                    const borrowerName = loan.borrower.pseudoDofus || loan.borrower.discordNickname || loan.borrower.user.name || "Emprunteur";
                    const lenderDiscordId = await getDiscordId(loan.lender.userId).catch(() => null);
                    const borrowerDiscordId = await getDiscordId(loan.borrower.userId).catch(() => null);
                    const mentions = [
                        lenderDiscordId ? `<@${lenderDiscordId}>` : lenderName,
                        borrowerDiscordId ? `<@${borrowerDiscordId}>` : borrowerName,
                    ].join(" ");

                    await sendChannelMessage(
                        loan.guild.loansNotifyChannelId,
                        mentions,
                        {
                            embedTitle: "🗂️ Prêt archivé supprimé",
                            embedColor: 0x52525b,
                            embedFooter: `SigilOS • Rétention archives ${ARCHIVE_EXPIRY_DAYS} jours`,
                            fields: [
                                { name: "📋 Prêt", value: loan.description, inline: false },
                                { name: "📎 Prêteur", value: lenderName, inline: true },
                                { name: "🏦 Emprunteur", value: borrowerName, inline: true },
                                { name: "✅ Statut", value: loan.status === "RETURNED" ? "Rendu" : "Annulé", inline: true },
                                { name: "ℹ️ Info", value: `Ce prêt a été purgé automatiquement après ${ARCHIVE_EXPIRY_DAYS} jours d'archivage.`, inline: false },
                            ],
                        }
                    ).catch(() => { }); // Non-bloquant
                    extraStats.archiveNotifsSent++;
                }
            } catch (err) {
                stats.errors.push(`ArchiveLoan ${loan.id}: ${err}`);
            }
        }
    } catch (err) {
        stats.errors.push(`Archive loans batch error: ${err}`);
    }

    // ---------------------------------------------------------------------------
    // 4. KAMA DONATIONS — auto-suppress PENDING donations after 24h
    // ---------------------------------------------------------------------------
    const kamaCutoff = new Date();
    kamaCutoff.setHours(kamaCutoff.getHours() - PENDING_EXPIRY_HOURS);

    const kamaStats = { kamaExpired: 0 };

    try {
        const kamaDb = db as any;

        const expiredKamaDonations = await kamaDb.kamaDonation.findMany({
            where: { status: "PENDING", createdAt: { lt: kamaCutoff } },
            select: {
                id: true, proofUrl: true, guildId: true,
                profile: { select: { userId: true, pseudoDofus: true, discordNickname: true, user: { select: { name: true } } } },
            },
        });

        for (const donation of expiredKamaDonations) {
            try {
                if (donation.proofUrl) { await deleteLocalProof(donation.proofUrl, donation.guildId); stats.filesDeleted++; }
                await (db as any).imageHash.deleteMany({ where: { guildId: donation.guildId, sourceType: "KAMA_DONATION", sourceId: donation.id } });
                await kamaDb.kamaDonation.delete({ where: { id: donation.id } });
                kamaStats.kamaExpired++;
            } catch (err) { stats.errors.push(`KamaDonation ${donation.id}: ${err}`); }
        }
    } catch (err) { stats.errors.push(`Kama donations batch error: ${err}`); }

    // ---------------------------------------------------------------------------
    // 5. MISSION SUBMISSIONS — auto-suppress PENDING after 24h
    // ---------------------------------------------------------------------------
    const missionStats = { missionsExpired: 0 };

    try {
        const expiredSubmissions = await db.submission.findMany({
            where: { status: "PENDING", createdAt: { lt: kamaCutoff } },
            select: { id: true, proofUrl: true },
        });

        for (const sub of expiredSubmissions) {
            try {
                if (sub.proofUrl) { await deleteMissionProof(sub.proofUrl); stats.filesDeleted++; }
                await (db as any).imageHash.deleteMany({ where: { sourceType: "MISSION", sourceId: sub.id } });
                await db.submission.delete({ where: { id: sub.id } });
                missionStats.missionsExpired++;
            } catch (err) { stats.errors.push(`Submission ${sub.id}: ${err}`); }
        }
    } catch (err) { stats.errors.push(`Mission submissions batch error: ${err}`); }

    // ---------------------------------------------------------------------------
    // 6. ACHIEVEMENT SUBMISSIONS — auto-suppress PENDING after 24h
    // ---------------------------------------------------------------------------
    const achievementStats = { achievementsExpired: 0 };

    try {
        const expiredAchievements = await (db as any).achievementSubmission.findMany({
            where: { status: "PENDING", createdAt: { lt: kamaCutoff } },
            select: { id: true, proofUrl: true, guildId: true },
        });

        for (const sub of expiredAchievements) {
            try {
                if (sub.proofUrl) {
                    // achievementSubmission proofs use /uploads/proofs/{discordGuildId}/ path
                    // or /uploads/guilds/{internalId}/proofs/ — try both
                    const deleted = await deleteMissionProof(sub.proofUrl) || await deleteLocalProof(sub.proofUrl, sub.guildId);
                    if (deleted) stats.filesDeleted++;
                }
                await (db as any).imageHash.deleteMany({ where: { sourceType: "ACHIEVEMENT", sourceId: sub.id } });
                await (db as any).achievementSubmission.delete({ where: { id: sub.id } });
                achievementStats.achievementsExpired++;
            } catch (err) { stats.errors.push(`Achievement ${sub.id}: ${err}`); }
        }
    } catch (err) { stats.errors.push(`Achievement submissions batch error: ${err}`); }

    logger.info("[cleanup-proofs] Done", { stats: { ...stats, ...extraStats, ...kamaStats, ...missionStats, ...achievementStats } });
    return NextResponse.json({ success: true, ...stats, ...extraStats, ...kamaStats, ...missionStats, ...achievementStats });
}

import { NextResponse } from "next/server";
import { db } from "@/lib/prisma";
import { sendDailySummaryReport } from "@/server/actions/daily-report-actions";
import { verifyCronSecret } from "@/lib/cron-auth";

/**
 * 🛰️ API CRON pour le rapport quotidien global.
 * Parcoure toutes les guildes actives et envoie le résumé.
 *
 * ✅ Protégé par x-cron-secret (fail-closed si secret absent)
 */
export async function GET(req: Request) {
    // CRIT-02 FIX : verifyCronSecret() refuse si CRON_SECRET absent (fail-closed)
    if (!verifyCronSecret(req)) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    try {
        const activeGuilds = await db.guildConfig.findMany({
            where: { isActive: true, systemNotifyChannelId: { not: null } },
            select: { discordGuildId: true, name: true }
        });

        const results = {
            total: activeGuilds.length,
            success: 0,
            failed: 0,
            errors: [] as string[]
        };

        for (const guild of activeGuilds) {
            try {
                const res = await sendDailySummaryReport(guild.discordGuildId, false);
                if (res.success) results.success++;
                else throw new Error(res.error);
            } catch (e: any) {
                results.failed++;
                results.errors.push(`${guild.name}: ${e.message}`);
            }
        }

        return NextResponse.json({ 
            success: true, 
            summary: results 
        });

    } catch (error: any) {
        console.error("[DailySummaryCron] Global Error:", error);
        return NextResponse.json({ error: "Internal Error" }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { sendGlobalStatusPing } from "@/server/actions/status-actions";
import { verifyCronSecret } from "@/lib/cron-auth";

// ---------------------------------------------------------------------------
// DISC-2 — Discord Status Channel (Consolidated)
// Triggers the living status update in the configured Discord channel.
// ✅ Protégé par x-cron-secret (fail-closed si secret absent)
// ---------------------------------------------------------------------------

export async function GET(req: Request) {
    // CRIT-02 FIX
    if (!verifyCronSecret(req)) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    try {
        const result = await sendGlobalStatusPing(false);

        if (!result.success) {
            return NextResponse.json({ error: result.error }, { status: 500 });
        }

        return NextResponse.json({ 
            success: true, 
            action: result.action,
            stats: result.stats 
        });
    } catch (error: any) {
        console.error("[DiscordStatusCron] Error:", error);
        return NextResponse.json({ error: "Internal error" }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/prisma";
import { sendGuildatonWeeklyReport, sendGuildatonAdminReminder } from "@/server/discord";
import { verifyCronSecret } from "@/lib/cron-auth";

export const maxDuration = 300; // 5 mins max pour le cron
export const dynamic = 'force-dynamic';

export async function GET(req: Request) {
    try {
        // [AUDIT 2026] CRIT-02: Use header-based auth instead of URL tokens (querystring leaks)
        if (!verifyCronSecret(req)) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { searchParams } = new URL(req.url);
        const forceGuild = searchParams.get('forceGuild');

        const guilds = await db.guildConfig.findMany({
            where: {
                OR: [
                    { guildatonNotifyChannelId: { not: null } },
                    { guildatonAdminChannelId: { not: null } }
                ],
                ...(forceGuild ? { discordGuildId: forceGuild } : {})
            },
            include: {
                guildatonRecords: true,
            }
        });

        const now = new Date();
        const currentDay = now.getDay();
        const currentHour = now.getHours();
        const currentMinute = now.getMinutes();
        const timeStr = `${currentHour.toString().padStart(2, '0')}:${currentMinute.toString().padStart(2, '0')}`;

        let executedCount = 0;

        for (const guild of guilds) {
            // --- 1. RAPPORT HEBDOMADAIRE PUBLIC ---
            if (guild.guildatonNotifyChannelId && guild.guildatonWeeklyQuota > 0) {
                const sevenDaysAgo = new Date();
                sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

                // Fetch histories for all members to calculate delta
                const pastHistories = await db.guildatonHistory.findMany({
                    where: {
                        guildId: guild.id,
                        createdAt: { lte: sevenDaysAgo }
                    },
                    orderBy: { createdAt: "desc" }
                });

                const userPastValueMap = new Map<string, number>();
                pastHistories.forEach(h => {
                    if (!userPastValueMap.has(h.discordId)) {
                        userPastValueMap.set(h.discordId, h.value);
                    }
                });

                const slackers = [];
                const masters = [];

                for (const record of guild.guildatonRecords) {
                    const pastValue = userPastValueMap.get(record.discordId) || 0;
                    const delta = record.value - pastValue;
                    if (delta < guild.guildatonWeeklyQuota) {
                        slackers.push({ discordId: record.discordId, username: record.username || "Inconnu", delta });
                    } else {
                        masters.push({ discordId: record.discordId, username: record.username || "Inconnu", delta });
                    }
                }

                if (slackers.length > 0 || masters.length > 0) {
                    await sendGuildatonWeeklyReport({
                        guildId: guild.discordGuildId,
                        channelId: guild.guildatonNotifyChannelId,
                        quota: guild.guildatonWeeklyQuota,
                        slackers,
                        masters
                    });
                    executedCount++;
                }
            }

            // --- 2. RAPPEL ADMIN HEBDOMADAIRE (NOUVEAU) ---
            if (guild.guildatonAdminChannelId && (guild.guildatonReminderDay === currentDay || forceGuild)) {
                // Si on est à l'heure pile (ou si forceGuild pour test)
                if (guild.guildatonReminderTime === timeStr || forceGuild) {
                    await sendGuildatonAdminReminder(guild.guildatonAdminChannelId, guild.discordGuildId);
                    executedCount++;
                }
            }
        }

        return NextResponse.json({ success: true, executedCount });
    } catch (error: any) {
        console.error("Guildaton cron error:", error);
        return NextResponse.json({ success: false, error: error.message }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/prisma";
import { verifyCronSecret } from "@/lib/cron-auth";

// Wait function to avoid spamming the worker / Ankama
const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

export async function GET(req: Request) {
    try {
        // CRIT-02 FIX — suppression du fallback ?token= (secret dans l'URL = fuite dans les logs)
        if (!verifyCronSecret(req)) {
            return new NextResponse("Unauthorized", { status: 401 });
        }

        const workerUrl = process.env.DOFUS_LADDER_WORKER_URL;
        const workerSecret = process.env.DOFUS_LADDER_WORKER_SECRET;

        if (!workerUrl) {
            return new NextResponse("Worker URL not configured", { status: 500 });
        }

        // 2. Fetch profiles that need updating
        // Cutoff time: older than 12 hours
        const cutoff = new Date(Date.now() - 12 * 60 * 60 * 1000);
        
        // Let's process 5 members per run to be safe
        const profiles = await db.userProfile.findMany({
            where: {
                status: "ACTIVE",
                pseudoDofus: { not: null },
                OR: [
                    { lastLadderUpdate: null },
                    { lastLadderUpdate: { lt: cutoff } }
                ]
            },
            take: 5,
            orderBy: {
                lastLadderUpdate: 'asc'
            },
            select: { 
                id: true, 
                pseudoDofus: true, 
                guildId: true,
                guild: {
                    select: { dofusServerId: true }
                }
            }
        });

        if (profiles.length === 0) {
            return NextResponse.json({ message: "No profiles to update.", count: 0 });
        }

        const results = [];

        // 3. Process each profile sequentially
        for (const profile of profiles) {
            const pseudo = profile.pseudoDofus as string;
            const serverId = profile.guild?.dofusServerId || "295"; // Default to Draconiros
            
            try {
                const headers: any = {};
                if (workerSecret) headers["X-SigilOS-Key"] = workerSecret;

                // --- FETCH SUCCES ---
                const succesRes = await fetch(`${workerUrl}?type=succes&server_id=${serverId}&name=${encodeURIComponent(pseudo)}`, { headers });
                const succesData = await succesRes.json();
                
                // Be gentle with the target server
                await delay(2000);

                // --- FETCH GENERAL ---
                const generalRes = await fetch(`${workerUrl}?type=general&server_id=${serverId}&name=${encodeURIComponent(pseudo)}`, { headers });
                const generalData = await generalRes.json();

                // Wait between members
                await delay(3000);

                // Check if we found them
                if (succesData.success || generalData.success) {
                    const updateData: any = {
                        lastLadderUpdate: new Date()
                    };

                    if (succesData.success && typeof succesData.points === 'number') {
                        updateData.successPoints = succesData.points;
                        if (succesData.level) updateData.dofusLevel = succesData.level;
                    }

                    if (generalData.success) {
                        if (generalData.level) updateData.dofusLevel = generalData.level;
                        if (generalData.totalXp) updateData.totalXp = BigInt(generalData.totalXp);
                        if (generalData.classe) updateData.classe = generalData.classe;
                    }

                    await db.userProfile.update({
                        where: { id: profile.id },
                        data: updateData
                    });

                    results.push({ pseudo, success: true, points: succesData.points, level: generalData.level || succesData.level });
                } else {
                    // Character not found or API error.
                    // We still update the lastLadderUpdate so we don't infinitely retry them in the next 12h
                    await db.userProfile.update({
                        where: { id: profile.id },
                        data: { lastLadderUpdate: new Date() }
                    });
                    results.push({ pseudo, success: false, reason: "Not found on ladder" });
                }

            } catch (err) {
                console.error(`Error updating ladder for ${pseudo}:`, err);
                results.push({ pseudo, success: false, error: String(err) });
            }
        }

        const summary = `Synchronisation effectuée sur ${profiles.length} profils.\n- Réussis : ${results.filter(r => r.success).length}\n- Échecs : ${results.filter(r => !r.success).length}`;

        // SEND NOTIFICATION TO GOD DASHBOARD & DISCORD
        const { notifyGod } = await import("@/server/actions/god-notif-actions");
        await notifyGod({
            title: "Ladder General/Succès Sync",
            message: summary,
            type: "WORKER_SYNC",
            success: results.some(r => r.success) || profiles.length === 0, // Success if at least one worked or nothing to do
            metadata: { 
                batch_size: profiles.length,
                success_count: results.filter(r => r.success).length,
                fail_count: results.filter(r => !r.success).length
            }
        });

        return NextResponse.json({
            message: "Batch completed",
            count: profiles.length,
            results
        });

    } catch (error: any) {
        console.error("Cron Ladder Sync Error:", error);
        
        // Notify of fatal failure
        const { notifyGod } = await import("@/server/actions/god-notif-actions");
        await notifyGod({
            title: "CRITICAL: Ladder Sync Failed",
            message: `Erreur fatale dans le cron ladder sync : ${error.message || String(error)}`,
            type: "WORKER_SYNC",
            success: false,
            ping: true // Fatal failure should ping discord
        });

        return new NextResponse("Internal Server Error", { status: 500 });
    }
}

