import { NextRequest, NextResponse } from "next/server";
import { isSuperAdmin } from "@/server/actions/super-admin-actions";
import { readdir } from "fs/promises";
import { join, normalize } from "path";

const IMAGE_EXTENSIONS = [".png", ".jpg", ".jpeg", ".webp", ".gif"];

export async function GET(req: NextRequest) {
    try {
        // 1. Check super admin
        const isAdmin = await isSuperAdmin();
        if (!isAdmin) {
            return NextResponse.json(
                { success: false, error: "Unauthorized: Super admin only" },
                { status: 403 }
            );
        }

        // 2. Get type from query
        const { searchParams } = new URL(req.url);
        const type = searchParams.get("type") || "achievement";

        // Validate type
        const validTypes = ["achievement", "monster", "dungeon", "item"];
        if (!validTypes.includes(type)) {
            return NextResponse.json(
                { success: false, error: "Invalid type" },
                { status: 400 }
            );
        }

        // 3. Build path - String concatenation to bypass Turbopack's static analysis
        const root = process.cwd();
        let subPath = "";
        switch (type) {
            case "achievement": subPath = "game-data/achievements"; break;
            case "monster": subPath = "game-data/monsters"; break;
            case "dungeon": subPath = "game-data/dungeons"; break;
            case "item": subPath = "game-data/items"; break;
        }
        const dirPath = normalize(root + "/public/" + subPath);

        // 4. Read directory
        const files = await readdir(dirPath, { withFileTypes: true });

        // 5. Filter images and map to response format
        const images = files
            .filter(file => {
                if (!file.isFile()) return false;
                const ext = file.name.toLowerCase().match(/\.[^.]+$/)?.[0];
                return ext && IMAGE_EXTENSIONS.includes(ext);
            })
            .map(file => ({
                filename: file.name,
                path: `/game-data/${type}s/${file.name}`,
                name: file.name.replace(/\.[^.]+$/, "") // Remove extension for display
            }));

        return NextResponse.json({
            success: true,
            images,
            count: images.length
        });

    } catch (error: any) {
        console.error("[ListLocalImages API] Error:", error);
        return NextResponse.json(
            { success: false, error: error.message || "Internal server error" },
            { status: 500 }
        );
    }
}

import { NextResponse } from "next/server";
import { notifyGod } from "@/server/actions/god-notif-actions";

/**
 * API: External God Notification Receiver
 * Used by VPS maintenance scripts, backups, and other external jobs.
 * 
 * Usage from Curl:
 * curl -X POST https://sigilos.fr/api/god/notify \
 *   -H "Authorization: Bearer YOUR_CRON_SECRET" \
 *   -H "Content-Type: application/json" \
 *   -d '{
 *     "title": "[VPS] Maintenance Terminée",
 *     "message": "Le script maintenance.sh a fini de purger Docker et les logs.",
 *     "type": "VPS_MAINTENANCE",
 *     "success": true,
 *     "metadata": { "docker_pruned": "3.5GB", "logs_cleared": "120MB" }
 *   }'
 */
export async function POST(req: Request) {
    console.log(`[API_GOD_NOTIFY] ☁️ Received incoming notification request...`);
    try {
        const authHeader = req.headers.get("authorization");
        const cronSecret = process.env.CRON_SECRET;

        if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
            return new NextResponse("Unauthorized", { status: 401 });
        }

        const data = await req.json();

        // Validate basic fields
        if (!data.title || !data.message || !data.type) {
            return new NextResponse("Missing required fields (title, message, type)", { status: 400 });
        }

        // Validate type (basic enum check)
        const validTypes: string[] = [
            "VPS_MAINTENANCE",
            "BACKUP",
            "WORKER_SYNC",
            "TICKET",
            "GEOGUESSER_REPORT",
            "SECURITY_ALERT",
            "SYSTEM"
        ];

        if (!validTypes.includes(data.type)) {
            return new NextResponse(`Invalid notification type. Must be one of: ${validTypes.join(", ")}`, { status: 400 });
        }

        const result = await notifyGod({
            title: data.title,
            message: data.message,
            type: data.type,
            success: data.success ?? true,
            metadata: data.metadata,
            ping: data.success === false // Ping on Discord only if it failed
        });

        if (!result.success) {
            return NextResponse.json({ error: result.error }, { status: 500 });
        }

        return NextResponse.json({ success: true });

    } catch (error: any) {
        console.error("[API_GOD_NOTIFY] Error:", error);
        return new NextResponse(`Internal Server Error: ${error.message}`, { status: 500 });
    }
}

