                            </CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 space-y-4">
                            <div className="space-y-3">
                                <div className="flex gap-3">
                                    <div className="w-5 h-5 rounded-full bg-red-500/20 text-red-400 flex items-center justify-center text-[10px] font-black shrink-0 mt-0.5">1</div>
                                    <p className="text-xs text-zinc-400 leading-relaxed font-medium">
                                        Créez ou choisissez un salon dédié aux signalements sur votre Discord.
                                    </p>
                                </div>
                                <div className="flex gap-3">
                                    <div className="w-5 h-5 rounded-full bg-red-500/20 text-red-400 flex items-center justify-center text-[10px] font-black shrink-0 mt-0.5">2</div>
                                    <p className="text-xs text-zinc-400 leading-relaxed font-medium">
                                        Saisissez son ID ici. Le Bot SigilOS doit avoir accès en <span className="text-white">lecture/écriture</span>.
                                    </p>
                                </div>
                                <div className="flex gap-3">
                                    <div className="w-5 h-5 rounded-full bg-red-500/20 text-red-400 flex items-center justify-center text-[10px] font-black shrink-0 mt-0.5">3</div>
                                    <p className="text-xs text-zinc-400 leading-relaxed font-medium">
                                        Postez n&apos;importe quoi dans ce salon : SigilOS le capturera et l&apos;ajoutera à la blacklist dashboard !
                                    </p>
                                </div>
                            </div>

                            <div className="pt-4 border-t border-white/5">
                                <div className="p-3 rounded-xl bg-amber-500/5 border border-amber-500/10 flex items-start gap-3">
                                    <AlertTriangle className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
                                    <p className="text-[10px] text-amber-200/70 italic leading-relaxed font-medium">
                                        Note: Seuls les messages textuels sont synchronisés. Les images/fichiers ne sont pas importés.
                                    </p>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Loader2, Save, Hash, Users, Bell, Sparkles, Send, Megaphone } from "lucide-react";
import { toast } from "sonner";
import { getMissionConfig, updateMissionNotifySettings } from "@/server/actions/admin-actions";
import { getDiscordRolesAction } from "@/server/actions/user-actions";
import { RoleSelector } from "@/components/admin/role-selector";
import { cn } from "@/lib/utils";

interface DiscordSettingsClientProps {
    guildId: string;
}

export function DiscordSettingsClient({ guildId }: DiscordSettingsClientProps) {
    const [newsEnabled, setNewsEnabled] = useState<boolean>(false);
    
    // We fetch existing data to keep other fields intact
    const [fullConfig, setFullConfig] = useState<any>(null);
    const [roles, setRoles] = useState<{ id: string; name: string }[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();

    useEffect(() => {
        async function loadData() {
            const [configRes, rolesRes] = await Promise.all([
                getMissionConfig(guildId),
                getDiscordRolesAction(guildId)
            ]);

            if (configRes.success && configRes.data) {
                setFullConfig(configRes.data);
                setNewsEnabled(configRes.data.newsBroadcastEnabled || false);
            }

            if (rolesRes.success && rolesRes.roles) {
                setRoles(rolesRes.roles);
            }

            setIsLoading(false);
        }
        loadData();
    }, [guildId]);

    const handleSave = () => {
        if (!fullConfig) return;

        startTransition(async () => {
            const result = await updateMissionNotifySettings(guildId, {
                // Keep existing mission settings
                channelId: fullConfig.missionChannelId,
                roleId: fullConfig.missionNotifyRoleId,
                validationChannelId: fullConfig.missionValidationChannelId,
                validationRoleId: fullConfig.missionValidationNotifyRoleId,
                kamaNotifyChannelId: fullConfig.kamaNotifyChannelId,
                kamaNotifyRoleId: fullConfig.kamaNotifyRoleId,
                achievementNotifyChannelId: fullConfig.achievementNotifyChannelId,
                achievementNotifyRoleId: fullConfig.achievementNotifyRoleId,
                // Important: Keep weekly management reminder settings!
                missionManagementNotifyChannelId: fullConfig.missionManagementNotifyChannelId,
                missionManagementNotifyRoleId: fullConfig.missionManagementNotifyRoleId,
                // New setting
                newsBroadcastEnabled: newsEnabled,
            });

            if (result.success) {
                toast.success("Paramètres Discord mis à jour !");
                // Update local fullConfig
                setFullConfig({
                    ...fullConfig,
                    newsBroadcastEnabled: newsEnabled,
                });
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[200px]">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-500/50" />
            </div>
        );
    }

    return (
        <div className="space-y-8 max-w-5xl mx-auto pb-8">
            {/* ── SECTION: NEWS BROADCAST (New) ── */}
            <div className="animate-in fade-in slide-in-from-top-4 duration-500">
                <h3 className="text-xs font-black uppercase tracking-[0.2em] text-zinc-600 mb-4 pl-1 flex items-center gap-2">
                    <Megaphone className="w-3.5 h-3.5" />
                    Flux d'actualités Dofus
                </h3>
                
                <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative">
                    <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                    
                    <CardContent className="p-6">
                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
                            <div className="space-y-1">
                                <h4 className="text-sm font-black text-white flex items-center gap-2">
                                    <Bell className="w-4 h-4 text-emerald-400" />
                                    Partage manuel vers Discord
                                </h4>
                                <p className="text-[11px] text-zinc-500 leading-relaxed max-w-md">
                                    Affiche un bouton sur chaque actualité (News, Devblog, Patch Notes) permettant aux administrateurs de poster directement l'info dans le salon système de la guilde.
                                </p>
                            </div>
                            <div className="flex items-center sm:flex-col sm:items-end gap-3 shrink-0 bg-black/20 sm:bg-transparent p-3 sm:p-0 rounded-xl">
                                <Switch 
                                    checked={newsEnabled}
                                    onCheckedChange={setNewsEnabled}
                                    className="data-[state=checked]:bg-emerald-500"
                                />
                                <span className={cn(
                                    "text-[9px] font-black uppercase tracking-widest",
                                    newsEnabled ? "text-emerald-400" : "text-zinc-600"
                                )}>
                                    {newsEnabled ? "Activé" : "Désactivé"}
                                </span>
                            </div>
                        </div>
                        
                        {newsEnabled && (
                            <div className="mt-4 p-3 rounded-xl bg-emerald-500/5 border border-emerald-500/10 flex items-start gap-3">
                                <div className="p-1.5 rounded-lg bg-emerald-500/20 shrink-0">
                                    <Sparkles className="w-3 h-3 text-emerald-400" />
                                </div>
                                <p className="text-[10px] text-zinc-400 italic">
                                    Une cloche apparaîtra désormais en haut à droite de chaque carte de news sur le dashboard pour les administrateurs.
                                </p>
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>


            {/* ACTION FOOTER */}
            <div className="sticky bottom-0 z-30 flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-4 rounded-2xl bg-zinc-900/90 backdrop-blur-md border border-white/10 shadow-2xl">
                <div className="flex items-start gap-4 max-w-md hidden sm:flex">
                    <div className="p-2 rounded-lg bg-indigo-500/10 border border-indigo-500/20 text-indigo-400">
                        <Sparkles className="w-4 h-4" />
                    </div>
                    <p className="text-[11px] text-zinc-500 leading-relaxed font-medium">
                        Ces réglages automatisent la communication plateforme/discord. Assurez-vous que le bot a les droits d&apos;écriture dans le salon sélectionné.
                    </p>
                </div>
                <Button
                    onClick={handleSave}
                    disabled={isPending}
                    className={cn(
                        "w-full sm:w-auto bg-indigo-600 hover:bg-indigo-500 text-white font-black px-8 h-12 shadow-lg shadow-indigo-900/20 rounded-xl transition-all",
                        "hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50"
                    )}
                >
                    {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                    SAUVEGARDER LES MODIFICATIONS
                </Button>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { 
    Loader2, Save, AlertTriangle, Hash, Clock, Calendar, 
    Trophy, Bell, ShieldCheck, Camera, Users, Info
} from "lucide-react";
import { toast } from "sonner";
import { getGuildatonData, updateGuildatonSettings, type GuildatonSettings } from "@/server/actions/guildaton-actions";
import { cn } from "@/lib/utils";

interface GuildatonSettingsClientProps {
    guildId: string;
}

const DAYS = [
    { id: 1, label: "Lundi" },
    { id: 2, label: "Mardi" },
    { id: 3, label: "Mercredi" },
    { id: 4, label: "Jeudi" },
    { id: 5, label: "Vendredi" },
    { id: 6, label: "Samedi" },
    { id: 0, label: "Dimanche" },
];

export function GuildatonSettingsClient({ guildId }: GuildatonSettingsClientProps) {
    const [settings, setSettings] = useState<GuildatonSettings | null>(null);
    const [availableChannels, setAvailableChannels] = useState<{id: string, name: string}[]>([]);
    const [availableRoles, setAvailableRoles] = useState<{id: string, name: string, color: number}[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();

    useEffect(() => {
        async function load() {
            try {
                const res = await getGuildatonData(guildId);
                if (res.success && res.data) {
                    setSettings(res.data.settings || {
                        trackedRoles: [],
                        notifyChannelId: null,
                        adminNotifyChannelId: null,
                        weeklyQuota: 0,
                        reminderDay: 0,
                        reminderTime: "18:00"
                    });
                    setAvailableChannels(res.data.availableChannels || []);
                    setAvailableRoles(res.data.availableRoles || []);
                } else {
                    toast.error(res.error || "Erreur lors du chargement des données");
                    // On définit quand même des settings par défaut pour débloquer l'UI
                    setSettings({
                        trackedRoles: [],
                        notifyChannelId: null,
                        adminNotifyChannelId: null,
                        weeklyQuota: 0,
                        reminderDay: 0,
                        reminderTime: "18:00"
                    });
                }
            } catch (err) {
                toast.error("Erreur de connexion au serveur");
            } finally {
                setIsLoading(false);
            }
        }
        load();
    }, [guildId]);

    const toggleTrackedRole = (roleId: string) => {
        if (!settings) return;
        const roles = settings.trackedRoles.includes(roleId)
            ? settings.trackedRoles.filter(r => r !== roleId)
            : [...settings.trackedRoles, roleId];
        setSettings({ ...settings, trackedRoles: roles });
    };

    const handleSave = () => {
        if (!settings) return;
        startTransition(async () => {
            const res = await updateGuildatonSettings(guildId, settings);
            if (res.success) {
                toast.success("Paramètres Guildaton mis à jour !");
            } else {
                toast.error(res.error || "Erreur de sauvegarde");
            }
        });
    };

    if (isLoading || !settings) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-violet-500" />
            </div>
        );
    }

    const activeDayLabel = DAYS.find(d => d.id === settings.reminderDay)?.label || "Lundi";

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Configuration Panel */}
                <Card className="lg:col-span-2 bg-zinc-900/40 border-white/5 backdrop-blur-xl">
                    <CardHeader>
                        <div className="flex items-center justify-between">
                            <CardTitle className="flex items-center gap-3 italic uppercase font-black text-xl tracking-tighter">
                                <span className="bg-violet-500/20 text-violet-400 p-2 rounded-xl border border-violet-500/20 shadow-[0_0_15px_rgba(139,92,246,0.2)]">
                                    <Trophy className="w-5 h-5" />
                                </span>
                                Rappels <span className="text-violet-500">Guildaton</span>
                            </CardTitle>
                            {settings.adminNotifyChannelId ? (
                                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 px-3 py-1 font-black uppercase tracking-widest text-[9px]">
                                    Reminders ON
                                </Badge>
                            ) : (
                                <Badge variant="outline" className="text-zinc-600 border-white/5 px-3 py-1 font-black uppercase tracking-widest text-[9px]">
                                    Désactivé
                                </Badge>
                            )}
                        </div>
                        <CardDescription className="text-zinc-500 font-medium">
                            Configurez le ciblage des membres et les rappels automatiques.
                        </CardDescription>
                    </CardHeader>

                    <CardContent className="space-y-10 pb-10">
                        {/* 1. Ciblage des membres */}
                        <div className="space-y-6">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-violet-600/10 rounded-lg">
                                    <Users className="w-4 h-4 text-violet-400" />
                                </div>
                                <h3 className="text-sm font-black uppercase tracking-widest text-white italic">1. Ciblage & Quota</h3>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pl-4 border-l-2 border-white/5">
                                <div className="space-y-4">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Rôles trackés par le bot</label>
                                    <div className="flex flex-wrap gap-2 max-h-[200px] overflow-y-auto no-scrollbar pr-2">
                                        {availableRoles.map((r) => {
                                            const isActive = settings.trackedRoles.includes(r.id);
                                            return (
                                                <Badge 
                                                    key={r.id}
                                                    onClick={() => toggleTrackedRole(r.id)}
                                                    className={cn(
                                                        "cursor-pointer transition-all px-3 py-1.5 text-[10px] font-bold uppercase",
                                                        isActive 
                                                            ? "bg-violet-600/20 text-violet-300 border-violet-500/40 shadow-[0_0_10px_rgba(139,92,246,0.1)]" 
                                                            : "bg-zinc-900/50 text-zinc-600 border-white/5 hover:border-white/10"
                                                    )}
                                                    variant="outline"
                                                >
                                                    {r.name}
                                                </Badge>
                                            )
                                        })}
                                    </div>
                                    <p className="text-[10px] text-zinc-600 italic">
                                        Seuls les membres avec au moins un de ces rôles apparaîtront dans le tableau.
                                    </p>
                                </div>

                                <div className="space-y-4">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Objectif Hebdomadaire</label>
                                    <div className="relative group">
                                        <Trophy className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 group-focus-within:text-amber-400 transition-colors" />
                                        <Input
                                            type="number"
                                            value={settings.weeklyQuota}
                                            onChange={(e) => setSettings({ ...settings, weeklyQuota: parseInt(e.target.value) || 0 })}
                                            className="pl-12 h-12 bg-black/40 border-white/5 rounded-2xl text-white font-black italic focus:ring-violet-500/20"
                                            placeholder="Ex: 50"
                                        />
                                        <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] font-black text-zinc-600 uppercase">Points / Semaine</span>
                                    </div>
                                    <p className="text-[10px] text-zinc-600 italic">
                                        Le quota utilisé pour le badge de retardataires (Slackers).
                                    </p>
                                </div>
                            </div>

                            {/* Canal Public */}
                            <div className="mt-8 pt-8 border-t border-white/5 space-y-4">
                                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 flex items-center gap-2">
                                    <Bell className="w-4 h-4 text-violet-400" /> Canal de Notification Public (Membres)
                                </label>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <select
                                        value={settings.notifyChannelId || ""}
                                        onChange={(e) => setSettings({ ...settings, notifyChannelId: e.target.value || null })}
                                        className="h-12 px-4 rounded-xl bg-black/40 border border-white/5 text-xs font-bold text-white focus:outline-none focus:ring-2 focus:ring-violet-500/20"
                                    >
                                        <option value="">Sélectionnez un salon...</option>
                                        {availableChannels.map(c => (
                                            <option key={c.id} value={c.id}># {c.name}</option>
                                        ))}
                                    </select>
                                    <div className="flex items-center gap-3 p-3 bg-white/[0.02] border border-white/5 rounded-xl">
                                        <Info className="w-4 h-4 text-zinc-500 shrink-0" />
                                        <p className="text-[9px] text-zinc-500 font-bold uppercase leading-tight">
                                            Salon où les membres recevront le rapport hebdomadaire et les pings de rappel.
                                        </p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* 2. Rappel Admin */}
                        <div className="space-y-6">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-emerald-600/10 rounded-lg">
                                    <Bell className="w-4 h-4 text-emerald-400" />
                                </div>
                                <h3 className="text-sm font-black uppercase tracking-widest text-white italic">2. Rappel Administrateur</h3>
                            </div>
                            
                            <div className="pl-4 border-l-2 border-white/5 space-y-8">
                                {/* Étape 1 */}
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 flex items-center gap-2">
                                        <ShieldCheck className="w-3 h-3 text-emerald-500" /> Salon Admin (Discord ID)
                                    </label>
                                    <Input
                                        value={settings.adminNotifyChannelId || ""}
                                        onChange={(e) => setSettings({ ...settings, adminNotifyChannelId: e.target.value })}
                                        placeholder="Ex: 1234567890..."
                                        className="font-mono bg-black/40 border-white/5 h-12 rounded-2xl focus:ring-violet-500/20"
                                    />
                                    <p className="text-[11px] text-zinc-500 italic">
