"use client";

import { useState } from "react";
import { Trash2, Loader2 } from "lucide-react";
import { wipeUserProfile } from "@/server/actions/lifecycle-actions";
import { toast } from "sonner";

interface HistoryWipeButtonProps {
    profileId: string;
    guildId: string;
    nickname: string;
}

export function HistoryWipeButton({ profileId, guildId, nickname }: HistoryWipeButtonProps) {
    const [isWiping, setIsWiping] = useState(false);

    const handleWipe = async () => {
        if (!confirm(`Es-tu sûr de vouloir nettoyer définitivement les données de ${nickname} ? Cette action est irréversible.`)) {
            return;
        }

        setIsWiping(true);
        try {
            const res = await wipeUserProfile(profileId, guildId);
            if (res.success) {
                toast.success("Profil nettoyé avec succès");
            } else {
                toast.error(res.error || "Erreur lors du nettoyage");
            }
        } catch (e) {
            toast.error("Erreur réseau");
        } finally {
            setIsWiping(false);
        }
    };

    return (
        <button
            onClick={handleWipe}
            disabled={isWiping}
            className="p-2 text-zinc-500 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-all group"
            title="Nettoyer les données (Wipe RGPD)"
        >
            {isWiping ? (
                <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
                <Trash2 className="w-4 h-4" />
            )}
        </button>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, Hash, AlertTriangle } from "lucide-react";
import { toast } from "sonner";
import { getLoansConfig, updateLoansChannel, getServicesStatusConfig, updateServicesStatusConfig } from "@/server/actions/admin-actions";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";

interface LoansSettingsClientProps {
    guildId: string;
}

export function LoansSettingsClient({ guildId }: LoansSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);

    // Maintenance States
    const [marketplaceEnabled, setMarketplaceEnabled] = useState(true);
    const [marketplaceMessage, setMarketplaceMessage] = useState("");
    const [loansEnabled, setLoansEnabled] = useState(true);
    const [loansMessage, setLoansMessage] = useState("");
    const [vaultEnabled, setVaultEnabled] = useState(true);
    const [vaultMessage, setVaultMessage] = useState("");

    useEffect(() => {
        async function loadConfig() {
            const [loansRes, servicesRes] = await Promise.all([
                getLoansConfig(guildId),
                getServicesStatusConfig(guildId)
            ]);

            if (loansRes.success && loansRes.data) {
                setChannelId(loansRes.data.loansNotifyChannelId || "");
                setIsConfigured(!!loansRes.data.loansNotifyChannelId);
            }

            if (servicesRes.success && servicesRes.data) {
                setMarketplaceEnabled(servicesRes.data.serviceMarketplaceEnabled);
                setMarketplaceMessage(servicesRes.data.serviceMarketplaceMessage || "");
                setLoansEnabled(servicesRes.data.serviceLoansEnabled);
                setLoansMessage(servicesRes.data.serviceLoansMessage || "");
                setVaultEnabled(servicesRes.data.serviceVaultEnabled);
                setVaultMessage(servicesRes.data.serviceVaultMessage || "");
            }

            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSaveChannel = () => {
        startTransition(async () => {
            const result = await updateLoansChannel(guildId, channelId.trim() || null);
            if (result.success) {
                toast.success("Salon configuré !");
                setIsConfigured(!!channelId.trim());
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    const handleSaveMaintenance = () => {
        startTransition(async () => {
            const result = await updateServicesStatusConfig(guildId, {
                serviceMarketplaceEnabled: marketplaceEnabled,
                serviceMarketplaceMessage: marketplaceMessage.trim() || null,
                serviceLoansEnabled: loansEnabled,
                serviceLoansMessage: loansMessage.trim() || null,
                serviceVaultEnabled: vaultEnabled,
                serviceVaultMessage: vaultMessage.trim() || null,
            });

            if (result.success) {
                toast.success("Statuts des services mis à jour !");
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <Card className="lg:col-span-2 bg-zinc-900/60 border-white/5">
                    <CardHeader>
                        <div className="flex items-center justify-between">
                            <CardTitle className="flex items-center gap-2 text-base">
                                <span className="bg-emerald-500/20 text-emerald-400 p-2 rounded-lg">
                                    <Hash className="w-4 h-4" />
                                </span>
                                Salon de notifications
                            </CardTitle>
                            {isConfigured ? (
                                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20">Actif</Badge>
                            ) : (
                                <Badge variant="outline" className="text-zinc-500">Inactif</Badge>
                            )}
                        </div>
                        <CardDescription>
                            Quand un prêt est créé/rendu ou qu&apos;un mouvement de coffre est enregistré, le bot postera un message récapitulatif dans ce salon.
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div className="space-y-2">
                            <p className="text-xs text-zinc-500">
                                Mode développeur Discord → Clic droit sur le salon → <span className="text-zinc-300">Copier l&apos;identifiant</span>
                            </p>
                            <div className="flex gap-2">
                                <Input
                                    value={channelId}
                                    onChange={(e) => setChannelId(e.target.value)}
                                    placeholder="Ex: 123456789012345678"
                                    className="font-mono bg-black/20 border-white/10"
                                />
                                <Button onClick={handleSaveChannel} disabled={isPending} className="min-w-[120px] bg-emerald-600 hover:bg-emerald-500">
                                    {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                    Sauvegarder
                                </Button>
                            </div>
                            {isConfigured && (
                                <div className="flex justify-end">
                                    <Button
                                        variant="ghost" size="sm"
                                        onClick={() => { setChannelId(""); handleSaveChannel(); }}
                                        disabled={isPending}
                                        className="text-rose-400 hover:text-rose-300 hover:bg-rose-900/20 text-xs"
                                    >
                                        Désactiver
                                    </Button>
                                </div>
                            )}
                        </div>
                    </CardContent>
                </Card>

                <Card className="bg-blue-500/5 border-blue-500/10 h-fit">
                    <CardContent className="p-4 flex gap-3">
                        <div className="p-2 bg-blue-500/20 rounded-lg shrink-0 h-fit">
                            <AlertTriangle className="w-4 h-4 text-blue-400" />
                        </div>
                        <div className="space-y-1">
                            <h4 className="text-sm font-medium text-blue-200">Permissions requises</h4>
                            <p className="text-xs text-blue-300/70 leading-relaxed">
                                Le bot <strong>SigilOS</strong> doit avoir les droits <em>Voir le salon</em> et <em>Envoyer des messages</em> dans le salon cible.
                            </p>
                        </div>
                    </CardContent>
                </Card>
            </div>

            <Card className="bg-zinc-900/60 border-white/5 overflow-hidden relative">
                <div className="absolute top-0 right-0 p-4">
                    <Button onClick={handleSaveMaintenance} disabled={isPending} className="bg-emerald-600 hover:bg-emerald-500">
                        {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                        Enregistrer les statuts
                    </Button>
                </div>
                <CardHeader>
                    <CardTitle className="text-base flex items-center gap-2">
                        <AlertTriangle className="w-4 h-4 text-amber-500" />
                        Maintenance & Accès aux Services
                    </CardTitle>
                    <CardDescription>
                        Désactivez temporairement des onglets spécifiques et affichez un message personnalisé aux membres.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        {/* Marketplace */}
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label className="text-sm font-bold">Services (Marketplace)</Label>
                                    <p className="text-[10px] text-zinc-500 uppercase tracking-widest">Onglet principal</p>
                                </div>
                                <Switch
                                    checked={marketplaceEnabled}
                                    onCheckedChange={setMarketplaceEnabled}
                                />
                            </div>
                            {!marketplaceEnabled && (
                                <div className="space-y-1.5 animate-in slide-in-from-top-1 duration-200">
                                    <Label className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">Message d&apos;indisponibilité</Label>
                                    <Textarea
                                        value={marketplaceMessage}
                                        onChange={(e) => setMarketplaceMessage(e.target.value)}
                                        placeholder="Ex: Le marketplace est en maintenance..."
                                        className="h-20 bg-black/40 border-white/10 text-xs resize-none"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Loans */}
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label className="text-sm font-bold">Prêts</Label>
                                    <p className="text-[10px] text-zinc-500 uppercase tracking-widest">Emprunts & Retours</p>
                                </div>
                                <Switch
                                    checked={loansEnabled}
                                    onCheckedChange={setLoansEnabled}
                                />
                            </div>
                            {!loansEnabled && (
                                <div className="space-y-1.5 animate-in slide-in-from-top-1 duration-200">
                                    <Label className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">Message d&apos;indisponibilité</Label>
                                    <Textarea
                                        value={loansMessage}
                                        onChange={(e) => setLoansMessage(e.target.value)}
                                        placeholder="Ex: Les prêts sont suspendus pour inventaire..."
                                        className="h-20 bg-black/40 border-white/10 text-xs resize-none"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Vault */}
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label className="text-sm font-bold">Coffre</Label>
                                    <p className="text-[10px] text-zinc-500 uppercase tracking-widest">Historique & Trésorerie</p>
                                </div>
                                <Switch
                                    checked={vaultEnabled}
                                    onCheckedChange={setVaultEnabled}
                                />
                            </div>
                            {!vaultEnabled && (
                                <div className="space-y-1.5 animate-in slide-in-from-top-1 duration-200">
                                    <Label className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">Message d&apos;indisponibilité</Label>
                                    <Textarea
                                        value={vaultMessage}
                                        onChange={(e) => setVaultMessage(e.target.value)}
                                        placeholder="Ex: Le coffre est inaccessible suite à une réorganisation..."
                                        className="h-20 bg-black/40 border-white/10 text-xs resize-none"
                                    />
                                </div>
                            )}
                        </div>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Loader2, Save, Hash, Target, Users, Bell, Search, ShieldCheck, Coins, Trophy, Clock } from "lucide-react";
import { toast } from "sonner";
import { getMissionConfig, updateMissionNotifySettings } from "@/server/actions/admin-actions";
import { getDiscordRolesAction } from "@/server/actions/user-actions";
import { RoleSelector } from "@/components/admin/role-selector";

interface MissionSettingsClientProps {
    guildId: string;
}

export function MissionSettingsClient({ guildId }: MissionSettingsClientProps) {
    // Publication (missions hebdo)
    const [channelId, setChannelId] = useState<string>("");
    const [roleId, setRoleId] = useState<string | null>(null);

    // Validation Missions
    const [validationChannelId, setValidationChannelId] = useState<string>("");
    const [validationRoleId, setValidationRoleId] = useState<string | null>(null);

    // Validation Succès
    const [achievementChannelId, setAchievementChannelId] = useState<string>("");
    const [achievementRoleId, setAchievementRoleId] = useState<string | null>(null);

    // Contributions Kamas
    const [kamaChannelId, setKamaChannelId] = useState<string>("");
    const [kamaRoleId, setKamaRoleId] = useState<string | null>(null);
    
    // Rappel Reset Staff (Mardi 8h00)
    const [managementChannelId, setManagementChannelId] = useState<string>("");
    const [managementRoleId, setManagementRoleId] = useState<string | null>(null);

    const [roles, setRoles] = useState<{ id: string; name: string }[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();

    useEffect(() => {
        async function loadData() {
            const [configRes, rolesRes] = await Promise.all([
                getMissionConfig(guildId),
                getDiscordRolesAction(guildId)
            ]);

            if (configRes.success && configRes.data) {
                setChannelId(configRes.data.missionChannelId || "");
                setValidationChannelId(configRes.data.missionValidationChannelId || "");
                setKamaChannelId(configRes.data.kamaNotifyChannelId || "");
                setAchievementChannelId(configRes.data.achievementNotifyChannelId || "");
                setRoleId(configRes.data.missionNotifyRoleId || null);
                setValidationRoleId(configRes.data.missionValidationNotifyRoleId || null);
                // New fields (may not exist in older configs, graceful fallback)
                setAchievementRoleId((configRes.data as any).achievementNotifyRoleId || null);
                setKamaRoleId((configRes.data as any).kamaNotifyRoleId || null);
                setManagementChannelId(configRes.data.missionManagementNotifyChannelId || "");
                setManagementRoleId(configRes.data.missionManagementNotifyRoleId || null);
            }

            if (rolesRes.success && rolesRes.roles) {
                setRoles(rolesRes.roles);
            }

            setIsLoading(false);
        }
        loadData();
    }, [guildId]);

    const handleSave = () => {
        startTransition(async () => {
            const result = await updateMissionNotifySettings(guildId, {
                channelId: channelId.trim() || null,
                roleId: roleId,
                validationChannelId: validationChannelId.trim() || null,
                validationRoleId: validationRoleId,
                kamaNotifyChannelId: kamaChannelId.trim() || null,
                kamaNotifyRoleId: kamaRoleId,
                achievementNotifyChannelId: achievementChannelId.trim() || null,
                achievementNotifyRoleId: achievementRoleId,
                missionManagementNotifyChannelId: managementChannelId.trim() || null,
                missionManagementNotifyRoleId: managementRoleId,
            });
            if (result.success) {
                toast.success("Paramètres mis à jour !");
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[200px]">
                <Loader2 className="w-8 h-8 animate-spin text-amber-500/50" />
            </div>
        );
    }

    /** Composant réutilisable pour un bloc salon + rôle uniforme */
    const NotifBlock = ({
        accentClass,
        focusClass,
        channelValue,
        onChannelChange,
        channelHint,
        roleValue,
        onRoleChange,
        timer24h,
    }: {
        accentClass: string;
        focusClass: string;
        channelValue: string;
        onChannelChange: (v: string) => void;
        channelHint: string;
        roleValue: string | null;
        onRoleChange: (v: string | null) => void;
        timer24h?: true;
    }) => (
        <div className="space-y-3">
            {/* Salon */}
            <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 flex items-center gap-2">
                    <Hash className="w-3 h-3" /> Salon
                </label>
                <Input
                    value={channelValue}
                    onChange={(e) => onChannelChange(e.target.value)}
                    placeholder="ID du salon..."
                    className={`font-mono bg-black/40 border-white/10 text-white h-10 text-sm ${focusClass} rounded-xl`}
                />
                <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">{channelHint}</p>
            </div>

            {/* Rôle */}
            <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 flex items-center gap-2">
                    <Users className="w-3 h-3" /> Staff à Alerter
                </label>
                <RoleSelector
                    value={roleValue}
                    onChange={onRoleChange}
                    roles={roles}
                    className={`h-10 border-${accentClass}-500/20`}
                />
                <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">
                    Rôle mentionné dans l&apos;embed Discord.
                </p>
            </div>

            {/* 24h badge */}
            <div className={`p-2.5 rounded-xl bg-${accentClass}-500/5 border border-${accentClass}-500/10`}>
                <div className="flex gap-2 items-start">
                    <Clock className={`w-3 h-3 text-${accentClass}-400 shrink-0 mt-0.5`} />
                    <p className="text-[10px] text-zinc-500 leading-relaxed italic">
                        <span className={`text-${accentClass}-400 font-bold not-italic`}>24h</span> — Suppression automatique de la preuve si non validée.
                        {timer24h && <span className="ml-1">Un compte à rebours est visible dans le dashboard admin.</span>}
                    </p>
                </div>
            </div>
        </div>
    );

    return (
        <div className="space-y-8 max-w-5xl mx-auto">
            {/* ── SECTION 1: PUBLICATION (full width) ── */}
            <div>
                <h3 className="text-xs font-black uppercase tracking-[0.2em] text-zinc-600 mb-3 pl-1">
                    📢 Publication hebdomadaire
                </h3>
                <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative">
                    <div className="absolute inset-0 bg-gradient-to-br from-amber-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                    <CardContent className="p-6 relative z-10">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 flex items-center gap-2">
                                    <Hash className="w-3 h-3" /> Salon de Publication
                                </label>
                                <Input
                                    value={channelId}
                                    onChange={(e) => setChannelId(e.target.value)}
                                    placeholder="ID du salon..."
                                    className="font-mono bg-black/40 border-white/10 text-white h-11 focus:ring-amber-500/20 focus:border-amber-500/50 rounded-xl"
                                />
                                <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">
                                    Salon pour l&apos;annonce des 12 missions hebdomadaires.
                                </p>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 flex items-center gap-2">
                                    <Users className="w-3 h-3" /> Rôle à Mentionner
                                </label>
                                <RoleSelector
                                    value={roleId}
                                    onChange={setRoleId}
                                    roles={roles}
                                    className="h-11"
                                />
                                <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">
                                    Envoyé chaque lundi matin (auto ou manuellement).
                                </p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* ── SECTION 2: VALIDATION CHANNELS (3 cards) ── */}
            <div>
                <h3 className="text-xs font-black uppercase tracking-[0.2em] text-zinc-600 mb-3 pl-1">
                    🔔 Salons de notification uploads
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">

                    {/* VALIDATION MISSIONS */}
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative">
                        <div className="absolute inset-0 bg-gradient-to-br from-purple-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        <CardHeader className="pb-2">
                            <CardTitle className="flex items-center gap-2 text-purple-400 text-sm">
                                <ShieldCheck className="w-4 h-4" />
                                Validation Missions
                            </CardTitle>
                            <CardDescription className="text-[10px] font-medium leading-relaxed">
                                Embed + boutons ✅❌ envoyés quand un membre soumet une preuve de mission.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="relative z-10 pt-0">
                            <NotifBlock
                                accentClass="purple"
                                focusClass="focus:ring-purple-500/20 focus:border-purple-500/50"
                                channelValue={validationChannelId}
                                onChannelChange={setValidationChannelId}
                                channelHint="Vide = salon de publication."
                                roleValue={validationRoleId}
                                onRoleChange={setValidationRoleId}
                                timer24h
                            />
                        </CardContent>
                    </Card>

                    {/* VALIDATION SUCCÈS */}
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative">
                        <div className="absolute inset-0 bg-gradient-to-br from-sky-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        <CardHeader className="pb-2">
                            <CardTitle className="flex items-center gap-2 text-sky-400 text-sm">
                                <Trophy className="w-4 h-4" />
                                Validation Succès
                            </CardTitle>
                            <CardDescription className="text-[10px] font-medium leading-relaxed">
                                Embed + boutons ✅❌ envoyés quand un membre upload une preuve de points succès.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="relative z-10 pt-0">
                            <NotifBlock
                                accentClass="sky"
                                focusClass="focus:ring-sky-500/20 focus:border-sky-500/50"
                                channelValue={achievementChannelId}
                                onChannelChange={setAchievementChannelId}
                                channelHint="Vide = salon validation missions."
                                roleValue={achievementRoleId}
                                onRoleChange={setAchievementRoleId}
                                timer24h
                            />
                        </CardContent>
                    </Card>

                    {/* CONTRIBUTIONS KAMAS */}
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative">
                        <div className="absolute inset-0 bg-gradient-to-br from-yellow-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        <CardHeader className="pb-2">
                            <CardTitle className="flex items-center gap-2 text-yellow-400 text-sm">
                                <Coins className="w-4 h-4" />
                                Contributions Kamas
                            </CardTitle>
                            <CardDescription className="text-[10px] font-medium leading-relaxed">
                                Embed + boutons ✅❌ envoyés quand un membre soumet un don de kamas.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="relative z-10 pt-0">
                            <NotifBlock
                                accentClass="yellow"
                                focusClass="focus:ring-yellow-500/20 focus:border-yellow-500/50"
                                channelValue={kamaChannelId}
                                onChannelChange={setKamaChannelId}
                                channelHint="Vide = pas de notification."
                                roleValue={kamaRoleId}
                                onRoleChange={setKamaRoleId}
                                timer24h
                            />
                        </CardContent>
                    </Card>

                    {/* RAPPEL RESET HEBDO (STAFF) */}
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative md:col-span-3">
                        <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        <CardHeader className="pb-2">
                            <CardTitle className="flex items-center gap-2 text-indigo-400 text-sm">
                                <Bell className="w-4 h-4" />
                                Rappel Reset Hebdo (Staff)
                            </CardTitle>
                            <CardDescription className="text-[10px] font-medium leading-relaxed">
                                Ping automatique envoyé **chaque mardi matin à 08h00** pour rappeler aux officiers de générer les missions et purger les attentes.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="relative z-10 pt-0">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 flex items-center gap-2">
                                        <Hash className="w-3 h-3" /> Salon de Rappel
                                    </label>
                                    <Input
                                        value={managementChannelId}
                                        onChange={(e) => setManagementChannelId(e.target.value)}
                                        placeholder="ID du salon..."
                                        className="font-mono bg-black/40 border-white/10 text-white h-10 focus:ring-indigo-500/20 focus:border-indigo-500/50 rounded-xl"
                                    />
                                    <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">
                                        Laisse vide pour désactiver ce rappel.
                                    </p>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 flex items-center gap-2">
                                        <Users className="w-3 h-3" /> Rôle (Officiers / Mission Managers)
                                    </label>
                                    <RoleSelector
                                        value={managementRoleId}
                                        onChange={setManagementRoleId}
                                        roles={roles}
                                        className="h-10 border-indigo-500/10"
                                    />
                                    <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">
                                        Le rôle qui possède les droits de validation / création.
                                    </p>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>

            {/* ACTION FOOTER */}
            <div className="sticky bottom-4 z-30 flex flex-col sm:flex-row items-center justify-between gap-4 p-4 rounded-2xl bg-zinc-900/80 backdrop-blur-xl border border-white/10 shadow-[0_-20px_40px_-15px_rgba(0,0,0,0.5)] mt-8">
                <div className="flex items-start gap-4 max-w-lg">
                    <div className="p-2.5 rounded-xl bg-amber-500/10 border border-amber-500/20 shrink-0 shadow-inner">
                        <Search className="w-4 h-4 text-amber-400" />
                    </div>
                    <p className="text-[11px] text-zinc-400 leading-relaxed font-medium">
                        Ces réglages s&apos;appliquent à l&apos;ensemble de la guilde. Assurez-vous que le bot SigilOS a les permissions d&apos;écrire dans les salons choisis.
                    </p>
                </div>
                <Button
                    onClick={handleSave}
                    disabled={isPending}
                    className="w-full sm:w-auto bg-amber-600 hover:bg-amber-500 text-white font-black px-8 h-12 shadow-[0_0_20px_rgba(217,119,6,0.2)] rounded-xl transition-all hover:scale-[1.02] active:scale-[0.98]"
                >
                    {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                    {isPending ? "SAUVEGARDE EN COURS..." : "SAUVEGARDER LES MODIFICATIONS"}
                </Button>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import {
    Sparkles,
    Bell,
    Save,
    Loader2,
    Info,
    LayoutDashboard,
    Eye,
    ShieldCheck,
    MessageSquareText,
    HelpCircle,
    Copy,
    ChevronRight,
    Trophy,
    UserPlus
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Card } from "@/components/ui/card";
import {
    getOnboardingSettings,
    updateWelcomeSettings,
    updateWelcomeBadgeName
} from "@/server/actions/onboarding-admin-actions";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import ReactMarkdown from "react-markdown";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";
import { RoleSelector } from "@/components/admin/role-selector";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";

interface OnboardingSettingsClientProps {
    guildId: string;
}

export function OnboardingSettingsClient({ guildId }: OnboardingSettingsClientProps) {
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const router = useRouter();

    const switchTabParam = (tabId: string) => {
        router.push(`/dashboard/${guildId}/admin/settings?tab=${tabId}`);
    };

    const [welcomeEnabled, setWelcomeEnabled] = useState(false);
    const [welcomeChannelId, setWelcomeChannelId] = useState<string>("");
    const [welcomeTemplate, setWelcomeTemplate] = useState<string>("");
    const [welcomeDiscordTemplate, setWelcomeDiscordTemplate] = useState<string>("");
    const [welcomeMentionRoleId, setWelcomeMentionRoleId] = useState<string>("");
    const [welcomeDashboardEnabled, setWelcomeDashboardEnabled] = useState(true);
    const [welcomeDiscordEnabled, setWelcomeDiscordEnabled] = useState(false);
    const [availableRoles, setAvailableRoles] = useState<{ id: string; name: string }[]>([]);

    const [welcomeBadgeName, setWelcomeBadgeName] = useState("Nouveau");

    useEffect(() => {
        const load = async () => {
            const res = await getOnboardingSettings(guildId);
            if (res.success && res.data) {
                setWelcomeEnabled(res.data.enabled);
                setWelcomeChannelId(res.data.channelId || "");
                setWelcomeTemplate(res.data.template || "");
                setWelcomeDiscordTemplate(res.data.discordTemplate || "");
                setWelcomeMentionRoleId(res.data.mentionRoleId || "");
                setWelcomeDashboardEnabled(res.data.dashboardEnabled);
                setWelcomeDiscordEnabled(res.data.discordEnabled);
                setWelcomeBadgeName(res.data.welcomeBadgeName || "Nouveau");
                if (res.data.availableRoles) setAvailableRoles(res.data.availableRoles);
            }
            setLoading(false);
        };
        load();
    }, [guildId]);

    const handleSaveWelcome = async () => {
        setSaving(true);
        try {
            const res = await updateWelcomeSettings({
                guildId,
                enabled: welcomeEnabled,
                channelId: welcomeChannelId || null,
                template: welcomeTemplate || null,
                discordTemplate: welcomeDiscordTemplate || null,
                mentionRoleId: welcomeMentionRoleId || null,
                dashboardEnabled: welcomeDashboardEnabled,
                discordEnabled: welcomeDiscordEnabled,
            });
            if (res.success) toast.success("Paramètres d'accueil enregistrés");
            else toast.error(res.error || "Erreur");
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setSaving(false);
        }
    };

    const handleSaveBadge = async () => {
        setSaving(true);
        try {
            const res = await updateWelcomeBadgeName({
                guildId,
                badgeName: welcomeBadgeName,
            });
            if (res.success) toast.success("Nom du badge mis à jour");
            else toast.error(res.error || "Erreur");
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center p-12">
                <Loader2 className="w-6 h-6 animate-spin text-zinc-500" />
            </div>
        );
    }

    const previewUser = "Voyageur";
    const previewGuild = "SigilOS";

    const insertVariable = (variable: string, target: 'dash' | 'discord') => {
        if (target === 'dash') {
            setWelcomeTemplate(prev => prev + variable);
        } else {
            setWelcomeDiscordTemplate(prev => prev + variable);
        }
        toast.info(`Variable ${variable} ajoutée !`);
    };

    const renderPreview = (content: string, isDiscord: boolean) => {
        if (!content || !content.trim()) {
            return <p className="text-zinc-600 italic text-sm">Le message apparaîtra ici...</p>;
        }

        const processed = content
            .replace(/{member}|{user}|{nickname}/g, isDiscord ? `**@${previewUser}**` : `**${previewUser}**`)
            .replace(/{guild}|{server}/g, `**${previewGuild}**`);

        return (
            <div className={cn(
                "prose prose-invert max-w-none text-zinc-300",
                isDiscord ? "font-sans leading-relaxed text-[13px]" : "font-sans leading-relaxed text-sm"
            )}>
                <ReactMarkdown>{processed}</ReactMarkdown>
            </div>
        );
    };

    return (
        <TooltipProvider>
            <div className="space-y-10 max-w-6xl pb-20">
                {/* --- HEADER --- */}
                <div className="flex flex-col gap-1">
                    <h2 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
                        <UserPlus className="w-8 h-8 text-indigo-400" /> Centre d&apos;Accueil
                    </h2>
                    <p className="text-zinc-500 text-sm">Configurez l&apos;arrivée de vos nouveaux membres et l&apos;automatisation des messages.</p>
                </div>

                {/* --- AIDE AUX VARIABLES --- */}
                <Card className="p-6 bg-indigo-500/5 border-indigo-500/20 relative overflow-hidden ring-1 ring-indigo-500/10">
                    <div className="space-y-4 relative z-10">
                        <div className="flex items-center gap-2">
                            <Info className="w-5 h-5 text-indigo-400" />
                            <h3 className="text-sm font-bold text-white uppercase tracking-wider">Variables de personnalisation</h3>
                        </div>
                        
                        <p className="text-xs text-zinc-400 leading-relaxed max-w-2xl">
                            Utilisez ces balises dans vos messages. Elles seront remplacées par les informations réelles du membre.
                        </p>

                        <div className="flex flex-wrap gap-4">
                            <button 
                                onClick={() => { navigator.clipboard.writeText("{nickname}"); toast.success("Copié !"); }}
                                className="group flex items-center gap-4 p-4 rounded-2xl bg-zinc-950/60 border border-white/5 hover:border-indigo-500/50 transition-all text-left"
                            >
                                <div className="w-10 h-10 rounded-xl bg-indigo-500/10 flex items-center justify-center shrink-0 group-hover:scale-105 transition-transform">
                                    <Copy className="w-4 h-4 text-indigo-400" />
                                </div>
                                <div>
                                    <code className="text-lg font-bold text-indigo-400 block">{`{nickname}`}</code>
                                    <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-tight">Nom du membre</p>
                                </div>
                            </button>

                            <button 
                                onClick={() => { navigator.clipboard.writeText("{server}"); toast.success("Copié !"); }}
                                className="group flex items-center gap-4 p-4 rounded-2xl bg-zinc-950/60 border border-white/5 hover:border-indigo-500/50 transition-all text-left"
                            >
                                <div className="w-10 h-10 rounded-xl bg-indigo-500/10 flex items-center justify-center shrink-0 group-hover:scale-105 transition-transform">
                                    <Copy className="w-4 h-4 text-indigo-400" />
                                </div>
                                <div>
                                    <code className="text-lg font-bold text-indigo-400 block">{`{server}`}</code>
                                    <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-tight">Nom de la guilde</p>
                                </div>
                            </button>
                        </div>
                    </div>
                </Card>

                {/* --- BADGE SECTION --- */}
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-stretch">
                    <Card className="lg:col-span-2 p-6 bg-zinc-900/40 border-white/5 flex flex-col justify-between gap-6 relative overflow-hidden group">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                                <Trophy className="w-5 h-5 text-amber-500" />
                            </div>
                            <div>
                                <h4 className="text-sm font-bold text-white uppercase tracking-wider">Badge Temporaire Automatique</h4>
                                <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-wider">Distinction visuelle sur SigilOS</p>
                            </div>
                        </div>

                        <div className="space-y-6">
                            <div className="space-y-3">
                                <label className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500">Nom du Badge (ex: Nouveau, Recrue, Test...)</label>
                                <div className="flex gap-4">
                                    <Input 
                                        value={welcomeBadgeName}
                                        onChange={(e) => setWelcomeBadgeName(e.target.value)}
                                        className="bg-black/40 border-white/10 h-12 text-white font-bold uppercase tracking-wider text-center rounded-xl focus:ring-amber-500/20 text-md"
                                    />
                                    <Button onClick={handleSaveBadge} disabled={saving} className="bg-amber-600 hover:bg-amber-500 text-white font-bold h-12 px-6 rounded-xl uppercase tracking-wider text-xs transition-all active:scale-95">
                                        {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : "Appliquer"}
                                    </Button>
                                </div>
                            </div>

                            <div className="p-5 rounded-3xl bg-amber-500/5 border border-amber-500/10 flex items-start gap-4">
                                <HelpCircle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                                <div className="space-y-1">
                                    <p className="text-[11px] text-zinc-300 font-bold uppercase tracking-tight">À quoi ça sert ?</p>
                                    <p className="text-[10px] text-zinc-500 font-medium leading-relaxed uppercase tracking-tight opacity-80">
                                        Ce badge s&apos;affiche sur le profil SigilOS des membres à qui vous l&apos;attribuez manuellement (via l&apos;onglet Membres). Il disparaît automatiquement après la durée que vous aurez choisie. Très utile pour repérer les nouveaux sans toucher aux vrais rôles Discord.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </Card>

                    <Card className="p-6 bg-zinc-950/80 border-white/10 flex flex-col items-center justify-center gap-4 relative overflow-hidden shadow-2xl rounded-3xl">
                        <div className="absolute top-3 right-4 text-[8px] font-bold text-zinc-800 uppercase tracking-widest">Aperçu Profil</div>
                        <div className="relative">
                            <Avatar className="w-20 h-20 border-2 border-white/10 ring-4 ring-amber-500/10">
                                <AvatarFallback className="bg-zinc-900 text-sm font-bold text-zinc-600 text-zinc-700">USER</AvatarFallback>
                            </Avatar>
                            <div className="absolute -bottom-1 -right-1 bg-amber-600 text-white px-3 py-1 rounded-full text-[9px] font-bold uppercase tracking-wider shadow-lg border border-amber-400/20">
                                <ShieldCheck className="w-3 h-3 inline mr-1" /> {welcomeBadgeName}
                            </div>
                        </div>
                        <div className="text-center">
                             <p className="text-md font-bold text-white italic tracking-tight uppercase">Voyageur X</p>
                             <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">Membre</p>
                        </div>
                    </Card>
                </div>

                {/* --- MAIN MODULE BLOCK --- */}
                <Card className="p-6 bg-zinc-900/40 border-white/5 space-y-8 relative overflow-hidden">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-white/5">
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center">
                                <Bell className="w-6 h-6 text-indigo-400" />
                            </div>
                            <div>
                                <h3 className="text-xl font-bold text-white tracking-wide uppercase italic">Notifications d&apos;arrivée</h3>
                                <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-[0.15em] opacity-80 flex items-center gap-2">
                                    Automatisation Dashboard + Discord
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4 p-2 pl-4 rounded-xl border border-white/5 bg-black/40">
                             <span className={cn("text-[9px] font-bold uppercase tracking-wider transition-colors", welcomeEnabled ? "text-green-500" : "text-zinc-600")}>{welcomeEnabled ? "Actif" : "Inactif"}</span>
                            <Switch checked={welcomeEnabled} onCheckedChange={setWelcomeEnabled} className="data-[state=checked]:bg-green-500" />
                        </div>
                    </div>

                    <div className={cn("space-y-10 transition-all duration-500", !welcomeEnabled && "opacity-30 pointer-events-none grayscale blur-sm")}>
                        <Tabs defaultValue="dashboard" className="w-full">
                            <TabsList className="grid w-full grid-cols-2 bg-black/40 border border-white/5 p-1 rounded-2xl h-14">
                                <TabsTrigger value="dashboard" className="data-[state=active]:bg-indigo-600 data-[state=active]:text-white font-bold text-xs uppercase tracking-wider gap-2 rounded-xl transition-all">
                                    <LayoutDashboard className="w-4 h-4" /> Mur Social SigilOS
                                </TabsTrigger>
                                <TabsTrigger value="discord" className="data-[state=active]:bg-indigo-600 data-[state=active]:text-white font-bold text-xs uppercase tracking-wider gap-2 rounded-xl transition-all">
                                    <Bell className="w-4 h-4" /> Alerte Discord
                                </TabsTrigger>
                            </TabsList>

                             {/* --- TAB DASHBOARD --- */}
                             <TabsContent value="dashboard" className="mt-8 space-y-8 animate-in fade-in zoom-in-95 duration-300">
                                <div className="flex flex-col md:flex-row items-center justify-between p-6 bg-white/5 rounded-3xl border border-white/5 gap-6">
                                    <div className="flex items-center gap-4 text-left mr-auto">
                                        <Switch checked={welcomeDashboardEnabled} onCheckedChange={setWelcomeDashboardEnabled} className="data-[state=checked]:bg-indigo-500 mr-2" />
                                        <div>
                                            <p className="text-sm font-bold uppercase tracking-wider text-white">Activer sur le Dashboard</p>
                                            <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-tight">Le message sera visible dans l&apos;onglet &quot;Bienvenue&quot;.</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <Button variant="outline" size="sm" onClick={() => insertVariable("{nickname}", "dash")} className="h-10 px-4 rounded-xl border-white/10 bg-zinc-900 shadow-xl hover:bg-indigo-500/10 hover:border-indigo-500/40 text-[10px] font-bold uppercase tracking-wider text-indigo-400">
                                            + {`nickname`}
                                        </Button>
                                        <Button variant="outline" size="sm" onClick={() => insertVariable("{server}", "dash")} className="h-10 px-4 rounded-xl border-white/10 bg-zinc-900 shadow-xl hover:bg-indigo-500/10 hover:border-indigo-500/40 text-[10px] font-bold uppercase tracking-wider text-indigo-400">
                                            + {`server`}
                                        </Button>
                                    </div>
                                </div>
                                
                                 <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
                                    <div className="lg:col-span-3 space-y-4">
                                        <div className="flex items-center gap-2 ml-2">
                                            <MessageSquareText className="w-4 h-4 text-indigo-400" />
                                            <h4 className="text-[10px] font-bold uppercase tracking-widest text-indigo-400">Modèle du message</h4>
                                        </div>
                                        <Textarea
                                            value={welcomeTemplate}
                                            onChange={(e) => setWelcomeTemplate(e.target.value)}
                                            placeholder="Tapez le message ici..."
                                            className="min-h-[220px] bg-black/40 border-white/10 font-sans text-md rounded-2xl p-6 resize-none focus:ring-indigo-500/10"
                                        />
                                    </div>
                                    <div className="lg:col-span-2 space-y-4">
                                        <div className="flex items-center gap-2 ml-2">
                                            <Eye className="w-4 h-4 text-zinc-500" />
                                            <h4 className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">Aperçu Dashboard</h4>
                                        </div>
                                        <div className="bg-zinc-950/90 border border-white/10 rounded-3xl p-8 min-h-[220px] h-full shadow-inner relative flex flex-col justify-center">
                                            <div className="flex gap-4">
                                                <div className="w-12 h-12 rounded-full bg-indigo-500/10 shrink-0 border border-indigo-500/20" />
                                                <div className="flex-1 space-y-3">
                                                    <div className="h-3 w-1/2 bg-zinc-900 rounded-full" />
                                                    <div className="p-5 rounded-2xl bg-white/5 border border-white/5 backdrop-blur-xl">
                                                        {renderPreview(welcomeTemplate, false)}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </TabsContent>

                             {/* --- TAB DISCORD --- */}
                             <TabsContent value="discord" className="mt-8 space-y-8 animate-in fade-in zoom-in-95 duration-300 text-left">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6 bg-indigo-600/5 rounded-3xl border border-indigo-600/20">
                                    <div className="flex items-center gap-4">
                                        <Switch checked={welcomeDiscordEnabled} onCheckedChange={setWelcomeDiscordEnabled} className="data-[state=checked]:bg-indigo-500" />
                                        <div>
                                            <p className="text-sm font-bold uppercase tracking-wider text-white">Activer l&apos;Alerte Discord</p>
                                            <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-tight">Utilise le format Embed Premium automatiquement.</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4 md:justify-end md:border-l border-white/10 md:pl-8">
                                        <div className="flex flex-col items-end">
                                            <span className="text-[10px] font-bold uppercase tracking-wider text-indigo-400 mb-2">Pinger un rôle ?</span>
                                            <RoleSelector
                                                value={welcomeMentionRoleId || null}
                                                onChange={(val) => setWelcomeMentionRoleId(val || "")}
                                                roles={availableRoles}
                                            />
                                        </div>
                                    </div>
                                </div>

                                 <div className="space-y-3 max-w-xl">
                                    <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-indigo-400 flex items-center gap-2 ml-2">
                                         ID SALON DISCORD
                                        <Tooltip>
                                            <TooltipTrigger asChild>
                                                <HelpCircle className="w-3 h-3 text-zinc-600 hover:text-white cursor-help" />
                                            </TooltipTrigger>
                                            <TooltipContent className="bg-zinc-900 border-white/20 p-4 max-w-sm rounded-xl">
                                                <p className="text-xs font-bold text-white mb-2 flex items-center gap-2">
                                                    <Info className="w-3 h-3 text-indigo-400" /> Tuto Rapide
                                                </p>
                                                <ol className="text-[10px] text-zinc-400 space-y-1 list-decimal ml-4">
                                                    <li>Active le <strong>Mode Développeur</strong> dans Discord.</li>
                                                    <li>Fais un <strong>clic droit</strong> sur le salon.</li>
                                                    <li>Clique sur <strong>Copier l&apos;identifiant</strong> et colle le ici.</li>
                                                </ol>
                                            </TooltipContent>
                                        </Tooltip>
                                    </label>
                                    <Input
                                        value={welcomeChannelId}
                                        onChange={(e) => setWelcomeChannelId(e.target.value)}
                                        placeholder="Ex: 1234..."
                                        className="bg-black/40 border-white/10 h-12 font-mono text-md rounded-xl focus:ring-indigo-500/20 px-6"
                                    />
                                </div>

                                 <div className="grid grid-cols-1 lg:grid-cols-5 gap-8 pt-4">
                                    <div className="lg:col-span-3 space-y-4">
                                        <div className="flex justify-between items-center px-2">
                                             <label className="text-[10px] font-bold uppercase tracking-widest text-indigo-400 flex items-center gap-2">
                                                <MessageSquareText className="w-4 h-4" /> Message Alerte
                                             </label>
                                             <div className="flex gap-2">
                                                <button onClick={() => insertVariable("{nickname}", "discord")} className="text-[9px] font-bold bg-zinc-800 hover:bg-zinc-700 px-3 py-1.5 rounded-xl border border-white/5 transition-all shadow-lg active:scale-95">+ {`nickname`}</button>
                                                <button onClick={() => insertVariable("{server}", "discord")} className="text-[9px] font-bold bg-zinc-800 hover:bg-zinc-700 px-3 py-1.5 rounded-xl border border-white/5 transition-all shadow-lg active:scale-95">+ {`server`}</button>
                                             </div>
                                        </div>
                                        <Textarea
                                            value={welcomeDiscordTemplate}
                                            onChange={(e) => setWelcomeDiscordTemplate(e.target.value)}
                                            placeholder="Tapez le message ici..."
                                            className="min-h-[200px] bg-black/40 border-white/10 font-sans text-md rounded-2xl p-6 resize-none focus:ring-indigo-500/10"
                                        />
                                        <div className="p-4 rounded-xl bg-indigo-500/5 border border-indigo-500/10 flex items-start gap-4">
                                            <Sparkles className="w-5 h-5 text-indigo-400 shrink-0 mt-0.5" />
                                            <p className="text-[10px] text-zinc-500 leading-relaxed font-bold uppercase tracking-tight italic">
                                                Le texte sera intégré dans un **Rich-Embed Premium** automatique (Avatar, Logo, Bannière...).
                                            </p>
                                        </div>
                                    </div>
                                    
                                     <div className="lg:col-span-2 space-y-4">
                                        <div className="flex items-center gap-2 ml-2">
                                            <Eye className="w-4 h-4 text-zinc-500" />
                                            <h4 className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">Rendu Discord</h4>
                                        </div>
                                        <div className="bg-[#2b2d31] rounded-3xl p-8 border-l-[6px] border-amber-500 shadow-3xl relative min-h-[300px] flex flex-col h-full group/discord">
                                            <div className="flex items-center gap-4 mb-6">
                                                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-indigo-500 to-indigo-700 flex items-center justify-center border border-white/10">
                                                    <Sparkles className="w-5 h-5 text-white" />
                                                </div>
                                                <span className="font-bold text-white text-sm tracking-tight uppercase italic group-hover/discord:text-amber-400 transition-colors">NOUVELLE ARRIVÉE !</span>
                                            </div>
                                            <div className="text-zinc-200 text-sm leading-relaxed flex-1 px-1 mb-8">
                                                {renderPreview(welcomeDiscordTemplate || welcomeTemplate, true)}
                                            </div>
                                            <div className="mt-auto pt-4 border-t border-white/5 opacity-40 flex justify-between items-center">
                                                <span className="text-[8px] font-bold uppercase tracking-widest text-zinc-400 italic">Authored by SigilOS Orchestrator</span>
                                                <MessageSquareText className="w-3 h-3 text-white" />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </TabsContent>
                        </Tabs>
                    </div>

                     <div className="flex justify-end pt-8 border-t border-white/5">
                        <Button
                            onClick={handleSaveWelcome}
                            disabled={saving}
                            className="bg-indigo-600 hover:bg-indigo-500 text-white font-bold h-14 px-10 rounded-xl gap-3 shadow-lg transition-all active:scale-95 flex items-center group/save"
                        >
                            {saving ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5 group-hover/save:rotate-12 transition-transform" />}
                             <span className="text-md uppercase tracking-tight">Enregistrer la configuration</span>
                        </Button>
                    </div>
                </Card>
            </div>
        </TooltipProvider>
    );
}

"use client";

import { useState, useTransition, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { updateRBACMapping } from "@/server/actions/admin-actions";
import { PERMISSIONS, PERMISSION_DETAILS, PERMISSION_MODULES, MODULE_ORDER as PERM_MODULE_ORDER, type PermissionId, type PermissionModule } from "@/lib/permissions";
import { PermissionCard } from "./permission-card";
import { cn } from "@/lib/utils";
import { Save, Filter, ChevronDown, ChevronRight, Search, X, Users, ShieldAlert, Loader2 } from "lucide-react";
import { Input } from "@/components/ui/input";

type Role = {
    id: string;
    name: string;
    color: number;
};

type Props = {
    guildId: string;
    roles: Role[];
    members: any[];
    currentMapping: Record<string, PermissionId[]>;
    currentUsersMapping: Record<string, PermissionId[]>;
};

const MODULE_ORDER = PERM_MODULE_ORDER;

export function PermissionsManager({ guildId, roles, members, currentMapping, currentUsersMapping }: Props) {
    // Transform: DB (Role -> Perms)  ==>  UI (Perm -> Roles)
    const initialPermState: Record<PermissionId, string[]> = Object.values(PERMISSIONS).reduce((acc, perm) => {
        acc[perm] = [];
        return acc;
    }, {} as Record<PermissionId, string[]>);

    Object.entries(currentMapping).forEach(([roleId, perms]) => {
        perms.forEach(perm => {
            // Only include permissions that still exist in the new system
            if (initialPermState[perm]) {
                initialPermState[perm].push(roleId);
            }
        });
    });

    // Transform: DB (User -> Perms) ==> UI (Perm -> Users)
    const initialUserState: Record<PermissionId, string[]> = Object.values(PERMISSIONS).reduce((acc, perm) => {
        acc[perm] = [];
        return acc;
    }, {} as Record<PermissionId, string[]>);

    Object.entries(currentUsersMapping).forEach(([discordUserId, perms]) => {
        perms.forEach(perm => {
            // Only include permissions that still exist in the new system
            if (initialUserState[perm]) {
                initialUserState[perm].push(discordUserId);
            }
        });
    });

    const [permState, setPermState] = useState(initialPermState);
    const [userState, setUserState] = useState(initialUserState);
    const [isPending, startTransition] = useTransition();
    const [activeModule, setActiveModule] = useState<PermissionModule | "all">("all");
    const [searchQuery, setSearchQuery] = useState("");
    // Track which module sections are collapsed (only relevant in "all" view)
    const [collapsed, setCollapsed] = useState<Record<PermissionModule, boolean>>({} as Record<PermissionModule, boolean>);

    // Roles that currently have DASHBOARD_ACCESS assigned
    const rolesWithDashboardAccess = new Set(permState[PERMISSIONS.DASHBOARD_LOGIN] || []);

    const handlePermChange = (permId: PermissionId, newRoleIds: string[]) => {
        setPermState(prev => {
            const next = { ...prev, [permId]: newRoleIds };
            // Auto-add DASHBOARD_ACCESS when any permission is granted to a role
            if (permId !== PERMISSIONS.DASHBOARD_LOGIN && newRoleIds.length > 0) {
                const currentAccess = new Set(prev[PERMISSIONS.DASHBOARD_LOGIN] || []);
                newRoleIds.forEach(roleId => currentAccess.add(roleId));
                next[PERMISSIONS.DASHBOARD_LOGIN] = Array.from(currentAccess);
            }
            return next;
        });
    };

    const handleUserChange = (permId: PermissionId, newUserIds: string[]) => {
        setUserState(prev => ({ ...prev, [permId]: newUserIds }));
    };

    const handleSave = () => {
        startTransition(async () => {
            // Reconstruct rolesMapping
            const rolesMapping: Record<string, PermissionId[]> = {};
            Object.entries(permState).forEach(([permId, roleIds]) => {
                roleIds.forEach(roleId => {
                    if (!rolesMapping[roleId]) rolesMapping[roleId] = [];
                    if (!rolesMapping[roleId].includes(permId as PermissionId)) {
                        rolesMapping[roleId].push(permId as PermissionId);
                    }
                });
            });

            // Reconstruct usersMapping
            const usersMapping: Record<string, PermissionId[]> = {};
            Object.entries(userState).forEach(([permId, userIds]) => {
                userIds.forEach(userId => {
                    const discordUserId = userId; // The ID passed should be the discord provider account ID
                    if (!usersMapping[discordUserId]) usersMapping[discordUserId] = [];
                    if (!usersMapping[discordUserId].includes(permId as PermissionId)) {
                        usersMapping[discordUserId].push(permId as PermissionId);
                    }
                });
            });

            const res = await updateRBACMapping(guildId, rolesMapping, usersMapping);
            if (res.success) {
                toast.success("Permissions sauvegardées");
            } else {
                toast.error(res.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    const toggleCollapse = (mod: PermissionModule) => {
        setCollapsed(prev => ({ ...prev, [mod]: !prev[mod] }));
    };

    const roleOptions = roles.map(r => ({ label: r.name, value: r.id, color: r.color }));
    const memberOptions = members.map(m => {
        // Find discord account ID
        const discordAccount = m.user.accounts.find((a: any) => a.provider === "discord");
        return {
            label: m.pseudoDofus || m.discordNickname || m.user.name || "Inconnu",
            value: discordAccount?.providerAccountId || m.userId,
            image: m.user.image
        };
    });

    const permissionsByModule = useMemo(() => {
        const grouped = {} as Record<PermissionModule, PermissionId[]>;
        MODULE_ORDER.forEach(m => grouped[m] = []);
        Object.entries(PERMISSION_DETAILS).forEach(([permId, details]) => {
            grouped[details.module].push(permId as PermissionId);
        });
        return grouped;
    }, []);

    const visiblePermissions = useMemo(() => {
        const base = activeModule === "all"
            ? Object.keys(PERMISSION_DETAILS) as PermissionId[]
            : permissionsByModule[activeModule] || [];

        if (!searchQuery.trim()) return base;

        const q = searchQuery.toLowerCase().trim();
        return base.filter(permId => {
            const detail = PERMISSION_DETAILS[permId];
            // Match on permission label
            if (detail.label.toLowerCase().includes(q)) return true;
            // Match on description
            if (detail.description.toLowerCase().includes(q)) return true;
            // Match on permission ID (technical)
            if (permId.toLowerCase().includes(q)) return true;
            // Match on assigned role names
            const assignedRoleIds = permState[permId] || [];
            const assignedRoleNames = assignedRoleIds
                .map(id => roles.find(r => r.id === id)?.name || "")
                .join(" ");
            if (assignedRoleNames.toLowerCase().includes(q)) return true;
            return false;
        });
    }, [activeModule, permissionsByModule, searchQuery, permState, roles]);

    const isSearchActive = searchQuery.trim().length > 0;

    const moduleStats = useMemo(() => {
        const stats = {} as Record<PermissionModule, number>;
        MODULE_ORDER.forEach(m => stats[m] = 0);
        Object.entries(permState).forEach(([permId, roleIds]) => {
            const module = PERMISSION_DETAILS[permId as PermissionId]?.module;
            if (module && roleIds.length > 0) stats[module]++;
        });
        return stats;
    }, [permState]);

    const totalConfigured = useMemo(() => Object.values(permState).filter(r => r.length > 0).length, [permState]);

    // Roles that have any permission but are missing DASHBOARD_ACCESS (need migration)
    const rolesNeedingMigration = useMemo(() => {
        const allMappedRoles = new Set<string>();
        Object.entries(permState).forEach(([permId, roleIds]) => {
            if (permId !== PERMISSIONS.DASHBOARD_LOGIN && roleIds.length > 0) {
                roleIds.forEach(id => allMappedRoles.add(id));
            }
        });
        const withAccess = new Set(permState[PERMISSIONS.DASHBOARD_LOGIN] || []);
        return [...allMappedRoles].filter(rId => !withAccess.has(rId));
    }, [permState]);

    return (
        <div className="space-y-8 relative">
            {/* Background Ambient Glow */}
            <div className="absolute -top-40 -right-40 w-96 h-96 bg-primary/5 blur-[120px] rounded-full pointer-events-none" />
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-white/[0.02] radial-gradient blur-[160px] rounded-full pointer-events-none" />

            {/* ⚠️ Warning Banner: roles missing DASHBOARD_ACCESS */}
            {rolesNeedingMigration.length > 0 && (
                <div className="flex items-start gap-4 bg-amber-500/10 border border-amber-500/30 rounded-2xl px-6 py-4">
                    <span className="text-2xl mt-0.5">⚠️</span>
                    <div>
                        <p className="text-amber-400 font-black uppercase tracking-widest text-sm">
                            Accès non explicite détecté
                        </p>
                        <p className="text-amber-400/80 text-xs mt-1 leading-relaxed">
                            {rolesNeedingMigration.length > 0 && (
                                <>
                                    {rolesNeedingMigration.map(rId => roles.find(r => r.id === rId)?.name || rId).join(", ")} — 
                                    {" "}Ces rôles ont des permissions mais n'ont pas <strong>🚪 Accès Dashboard</strong> coché.
                                    Les nouvelles permissions cochées ci-dessus l'ont automatiquement ajouté.
                                    <strong> Pensez à sauvegarder.</strong>
                                </>
                            )}
                        </p>
                    </div>
                </div>
            )}

            {/* Sticky Action Bar — Sigma 2026 Style */}
            <div className="flex flex-col sm:flex-row justify-between items-center bg-zinc-800/90 backdrop-blur-2xl px-6 py-5 rounded-[2rem] border border-white/20 sticky top-4 z-20 gap-4 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.7)]">
                <div className="flex items-center gap-5">
                    <div className="p-3 bg-primary/20 rounded-2xl border border-primary/40 shadow-[0_0_20px_rgba(var(--primary),0.3)]">
                        <ShieldAlert className="w-6 h-6 text-primary" />
                    </div>
                    <div>
                        <h2 className="text-base font-black text-white leading-none tracking-tight uppercase">Matrice des Droits</h2>
                        <div className="flex items-center gap-3 mt-2">
                            <div className="h-2 w-48 bg-white/10 rounded-full overflow-hidden border border-white/5">
                                <div 
                                    className="h-full bg-primary transition-all duration-700"
                                    style={{ 
                                        width: `${(totalConfigured / Object.values(PERMISSIONS).length) * 100}%`,
                                        boxShadow: `0 0 15px var(--primary)`
                                    }}
                                />
                            </div>
                            <span className="text-[10px] font-black text-white tracking-widest uppercase">
                                {totalConfigured} / {Object.values(PERMISSIONS).length} Activés
                            </span>
                        </div>
                    </div>
                </div>
                
                <div className="flex items-center gap-3 w-full sm:w-auto">
                    <div className="relative flex-1 sm:w-72">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-300" />
                        <Input
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            placeholder="Search nodes..."
                            className="pl-11 bg-black/40 border-white/10 h-12 rounded-2xl text-sm focus-visible:ring-primary/40 w-full placeholder:text-zinc-500 text-white"
                        />
                    </div>
                    <Button
                        onClick={handleSave}
                        disabled={isPending}
                        className="bg-white hover:bg-primary text-black font-black rounded-2xl h-12 px-8 transition-all hover:scale-[1.05] active:scale-95 shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                    >
                        {isPending ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5 mr-3" />}
                        {isPending ? "SYNCHRONIZING..." : "SAUVEGARDER"}
                    </Button>
                </div>
            </div>

            {/* Module Filter Island */}
            <div className="flex flex-wrap gap-2.5 p-2.5 bg-zinc-800/40 backdrop-blur-md rounded-2xl border border-white/10 overflow-x-auto no-scrollbar shadow-xl">
                <button
                    onClick={() => setActiveModule("all")}
                    className={cn(
                        "px-5 py-2.5 rounded-xl text-[11px] font-black tracking-widest uppercase transition-all whitespace-nowrap border",
                        activeModule === "all"
                            ? "bg-white text-black border-white shadow-[0_0_25px_rgba(255,255,255,0.25)]"
                            : "bg-transparent text-zinc-400 border-transparent hover:text-white hover:bg-white/10"
                    )}
                >
                    ALL MODULES
                </button>
                {MODULE_ORDER.map(moduleKey => {
                    const module = PERMISSION_MODULES[moduleKey];
                    const isActive = activeModule === moduleKey;
                    return (
                        <button
                            key={moduleKey}
                            onClick={() => setActiveModule(moduleKey)}
                            className={cn(
                                "px-5 py-2.5 rounded-xl text-[11px] font-black tracking-widest uppercase transition-all whitespace-nowrap flex items-center gap-2.5 border",
                                isActive
                                    ? "text-white shadow-lg border-white/20"
                                    : "text-zinc-400 border-transparent hover:text-white hover:bg-white/10"
                            )}
                            style={{ 
                                backgroundColor: isActive ? `${module.color}40` : undefined,
                                borderColor: isActive ? `${module.color}80` : undefined,
                                boxShadow: isActive ? `0 0 25px ${module.color}30` : undefined
                            }}
                        >
                            <span className="text-sm">{module.icon}</span>
                            <span>{module.label}</span>
                        </button>
                    );
                })}
            </div>

            {/* Content Area */}
            {isSearchActive ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {visiblePermissions.length === 0 ? (
                        <div className="col-span-full py-32 text-center bg-zinc-800/20 rounded-[2rem] border border-dashed border-white/20">
                            <Search className="w-12 h-12 text-zinc-700 mx-auto mb-4" />
                            <p className="text-zinc-400 font-extrabold uppercase tracking-widest text-sm">No assignments found for "{searchQuery}"</p>
                        </div>
                    ) : (
                        visiblePermissions.map(permId => (
                            <PermissionCard
                                key={permId}
                                permissionId={permId}
                                allRoles={roleOptions}
                                allUsers={memberOptions}
                                selectedRoleIds={permState[permId] || []}
                                selectedUserIds={userState[permId] || []}
                                onRolesChange={(ids) => handlePermChange(permId, ids)}
                                onUsersChange={(ids) => handleUserChange(permId, ids)}
                                onSave={handleSave}
                                moduleColor={PERMISSION_MODULES[PERMISSION_DETAILS[permId].module].color}
                                locked={permId !== PERMISSIONS.DASHBOARD_LOGIN && rolesWithDashboardAccess.size === 0}
                                hideUsers={permId === PERMISSIONS.DASHBOARD_LOGIN}
                            />
                        ))
                    )}
                </div>
            ) : activeModule === "all" ? (
                <div className="space-y-20">
                    {MODULE_ORDER.map(moduleKey => {
                        const module = PERMISSION_MODULES[moduleKey];
                        const modulePerms = permissionsByModule[moduleKey];
                        if (modulePerms.length === 0) return null;
                        const configuredCount = moduleStats[moduleKey];

                        return (
                            <section key={moduleKey} className="space-y-8">
                                <div className="flex items-center justify-between px-4">
                                    <div className="flex items-center gap-4">
                                        <div 
                                            className="w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shadow-2xl relative overflow-hidden group"
                                            style={{ backgroundColor: `${module.color}20`, border: `1px solid ${module.color}40` }}
                                        >
                                            <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform" />
                                            <span className="relative z-10">{module.icon}</span>
                                        </div>
                                        <div>
                                            <h2 className="text-2xl font-black tracking-tighter uppercase italic" style={{ color: module.color }}>
                                                {module.label}
                                            </h2>
                                            <div className="flex items-center gap-2 mt-1">
                                                <span className="px-2 py-0.5 bg-zinc-800 text-zinc-300 text-[9px] font-black rounded uppercase tracking-tighter border border-white/10">
                                                    {modulePerms.length} NODES
                                                </span>
                                                <span className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest">
                                                    Protocol Matrix Ready
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    
                                    <div className="hidden md:flex flex-col items-end gap-2">
                                        <div className="text-[10px] font-black text-white tracking-[0.2em] uppercase opacity-40">Validation Status</div>
                                        <div className="flex gap-2">
                                            {Array.from({ length: modulePerms.length }).map((_, i) => (
                                                <div 
                                                    key={i}
                                                    className="h-2 w-7 rounded-[2px] transition-all duration-500 border border-white/5"
                                                    style={{ 
                                                        backgroundColor: i < configuredCount ? module.color : 'rgba(255,255,255,0.08)',
                                                        boxShadow: i < configuredCount ? `0 0 12px ${module.color}50` : 'none'
                                                    }}
                                                />
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                    {modulePerms.map(permId => (
                                        <PermissionCard
                                            key={permId}
                                            permissionId={permId}
                                            allRoles={roleOptions}
                                            allUsers={memberOptions}
                                            selectedRoleIds={permState[permId] || []}
                                            selectedUserIds={userState[permId] || []}
                                            onRolesChange={(ids) => handlePermChange(permId, ids)}
                                            onUsersChange={(ids) => handleUserChange(permId, ids)}
                                            onSave={handleSave}
                                            moduleColor={module.color}
                                            locked={permId !== PERMISSIONS.DASHBOARD_LOGIN && rolesWithDashboardAccess.size === 0}
                                            hideUsers={permId === PERMISSIONS.DASHBOARD_LOGIN}
                                        />
                                    ))}
                                </div>
                                
                                {moduleKey !== MODULE_ORDER[MODULE_ORDER.length - 1] && (
                                    <div className="h-px w-full bg-gradient-to-r from-transparent via-white/5 to-transparent pt-12" />
                                )}
                            </section>
                        );
                    })}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {visiblePermissions.map(permId => (
                        <PermissionCard
                            key={permId}
                            permissionId={permId}
                            allRoles={roleOptions}
                            allUsers={memberOptions}
                            selectedRoleIds={permState[permId] || []}
                            selectedUserIds={userState[permId] || []}
                            onRolesChange={(ids) => handlePermChange(permId, ids)}
                            onUsersChange={(ids) => handleUserChange(permId, ids)}
                            onSave={handleSave}
                            moduleColor={PERMISSION_MODULES[PERMISSION_DETAILS[permId].module].color}
                            locked={permId !== PERMISSIONS.DASHBOARD_LOGIN && rolesWithDashboardAccess.size === 0}
                            hideUsers={permId === PERMISSIONS.DASHBOARD_LOGIN}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, AlertTriangle, Hash, Bell, Users } from "lucide-react";
import { toast } from "sonner";
import { getPollSettings, updatePollSettings } from "@/server/actions/poll-actions";
import { cn } from "@/lib/utils";

interface PollSettingsClientProps {
    guildId: string;
}

export function PollSettingsClient({ guildId }: PollSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [roleId, setRoleId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);

    useEffect(() => {
        async function loadConfig() {
            const result = await getPollSettings(guildId);
            if (result.success && result.data) {
                setChannelId(result.data.pollsNotifyChannelId || "");
                setRoleId(result.data.pollsNotifyRoleId || "");
                setIsConfigured(!!result.data.pollsNotifyChannelId);
            }
            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSave = () => {
        startTransition(async () => {
            const result = await updatePollSettings(guildId, {
                pollsNotifyChannelId: channelId.trim() || null,
                pollsNotifyRoleId: roleId.trim() || null
            });
            if (result.success) {
                toast.success("Configuration des sondages sauvegardée !");
                setIsConfigured(!!channelId.trim());
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[300px]">
                <Loader2 className="w-8 h-8 animate-spin text-cyan-500" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <Card className="bg-zinc-900/60 border-white/5">
                <CardHeader>
                    <div className="flex items-center justify-between">
                        <CardTitle className="flex items-center gap-2">
                            <span className="bg-cyan-500/20 text-cyan-400 p-2 rounded-lg">
                                <Bell className="w-5 h-5" />
                            </span>
                            Notifications de Sondages
                        </CardTitle>
                        {isConfigured ? (
                            <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20">
                                Connecté à Discord
                            </Badge>
                        ) : (
                            <Badge variant="outline" className="text-zinc-500">
                                Mode Manuel
                            </Badge>
                        )}
                    </div>
                    <CardDescription>
                        Configurez les paramètres par défaut pour la publication de vos sondages sur Discord.
                    </CardDescription>
                </CardHeader>

                <CardContent className="space-y-6">
                    {/* Channel ID */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 flex items-center gap-2">
                            <Hash className="w-3.5 h-3.5" />
                            Salon d'annonce par défaut
                        </Label>
                        <Input
                            value={channelId}
                            onChange={(e) => setChannelId(e.target.value)}
                            placeholder="ID du salon Discord (ex: 123456789...)"
                            className="font-mono bg-black/20 border-white/10 focus:border-cyan-500/50"
                        />
                        <p className="text-[10px] text-zinc-500 italic">
                            Le salon où les nouveaux sondages seront publiés automatiquement si l'option est cochée lors de la création.
                        </p>
                    </div>

                    {/* Role ID */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 flex items-center gap-2">
                            <Users className="w-3.5 h-3.5" />
                            Rôle à mentionner par défaut
                        </Label>
                        <Input
                            value={roleId}
                            onChange={(e) => setRoleId(e.target.value)}
                            placeholder="ID du rôle (laisser vide pour ne mentionner personne)"
                            className="font-mono bg-black/20 border-white/10 focus:border-cyan-500/50"
                        />
                        <p className="text-[10px] text-zinc-500 italic">
                            Identifiant du rôle Discord à notifier (pings) lors de la publication d'un sondage.
                        </p>
                    </div>

                    <div className="pt-4 flex items-center justify-between border-t border-white/5">
                        <div className="flex items-center gap-2 text-amber-500/80">
                            <AlertTriangle className="w-4 h-4" />
                            <span className="text-[10px] font-medium uppercase tracking-wider">
                                Vérifiez que le bot a les droits d'écriture
                            </span>
                        </div>
                        <Button
                            onClick={handleSave}
                            disabled={isPending}
                            className="bg-cyan-600 hover:bg-cyan-500 text-white min-w-[140px]"
                        >
                            {isPending ? (
                                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                            ) : (
                                <Save className="w-4 h-4 mr-2" />
                            )}
                            Sauvegarder
                        </Button>
                    </div>
                </CardContent>
            </Card>

            {/* Help Card */}
            <Card className="bg-blue-500/5 border-blue-500/10">
                <CardContent className="p-4 flex gap-3">
                    <div className="p-2 bg-blue-500/20 rounded-lg shrink-0 h-fit">
                        <Hash className="w-4 h-4 text-blue-400" />
                    </div>
                    <div className="space-y-1">
                        <h4 className="text-sm font-medium text-blue-200">Comment obtenir les IDs ?</h4>
                        <p className="text-xs text-blue-300/70 leading-relaxed">
                            Activez le <strong>Mode Développeur</strong> dans vos paramètres Discord (Apparence {'>'} Avancé).
                            Ensuite, faites un clic droit sur un salon ou un rôle et choisissez <strong>"Copier l'identifiant"</strong>.
                        </p>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import {
    Sparkles,
    Calendar,
    ShieldCheck,
    Loader2,
    Info
} from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { grantWelcomeBadge } from "@/server/actions/onboarding-admin-actions";

interface WelcomeBadgeDialogProps {
    guildId: string;
    profileId: string;
    memberName: string;
    roleName: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSuccess?: () => void;
}

export function WelcomeBadgeDialog({
    guildId,
    profileId,
    memberName,
    roleName,
    open,
    onOpenChange,
    onSuccess
}: WelcomeBadgeDialogProps) {
    const [days, setDays] = useState(30);
    const [loading, setLoading] = useState(false);

    const handleGrant = async () => {
        setLoading(true);
        try {
            const res = await grantWelcomeBadge({
                guildId,
                profileId,
                days
            });
            if (res.success) {
                toast.success(`Le badge "${roleName}" a été attribué à ${memberName} pour ${days} jours.`);
                onOpenChange(false);
                onSuccess?.();
            } else {
                toast.error(res.error || "Erreur");
            }
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[425px] bg-zinc-950 border-white/10 text-white">
                <DialogHeader>
                    <div className="w-12 h-12 rounded-2xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center mb-4">
                        <Sparkles className="w-6 h-6 text-amber-400" />
                    </div>
                    <DialogTitle className="text-xl font-black tracking-tight flex items-center gap-2">
                        Attribuer un badge spécial
                    </DialogTitle>
                    <DialogDescription className="text-zinc-500 italic">
                        Le membre recevra le badge "{roleName}" sur son profil pendant la durée choisie.
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-6 py-4">
                    <div className="p-4 rounded-xl bg-white/5 border border-white/10 flex items-center gap-4">
                        <div className="flex-1">
                            <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Membre ciblé</p>
                            <p className="text-sm font-bold text-white">{memberName}</p>
                        </div>
                        <div className="text-right">
                            <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Badge</p>
                            <p className="text-sm font-bold text-amber-400">{roleName}</p>
                        </div>
                    </div>

                    <div className="space-y-3">
                        <label className="text-xs font-bold text-amber-400 flex items-center gap-2">
                            <Calendar className="w-3 h-3" /> Durée (en jours)
                        </label>
                        <div className="flex gap-2">
                            {[7, 14, 30, 60].map((d) => (
                                <Button
                                    key={d}
                                    type="button"
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setDays(d)}
                                    className={`flex-1 font-bold h-9 transition-all ${days === d ? "bg-amber-500/20 border-amber-500 text-amber-400" : "bg-zinc-900 border-white/5 text-zinc-500 hover:text-zinc-300"}`}
                                >
                                    {d}j
                                </Button>
                            ))}
                        </div>
                        <Input
                            type="number"
                            value={days}
                            onChange={(e) => setDays(parseInt(e.target.value) || 0)}
                            className="bg-zinc-900 border-white/10 text-center font-bold text-lg"
                        />
                    </div>

                    <div className="p-3 rounded-xl bg-blue-500/5 border border-blue-500/10 flex items-start gap-3">
                        <Info className="w-4 h-4 text-blue-400 shrink-0 mt-0.5" />
                        <p className="text-[10px] text-zinc-500 leading-relaxed italic">
                            Ce badge est purement visuel sur SigilOS et n'affecte pas les permissions Discord. Il sera automatiquement retiré à l'expiration.
                        </p>
                    </div>
                </div>

                <DialogFooter className="gap-2 sm:gap-0">
                    <Button
                        variant="ghost"
                        onClick={() => onOpenChange(false)}
                        className="font-bold text-zinc-500 hover:text-white"
                    >
                        Annuler
                    </Button>
                    <Button
                        onClick={handleGrant}
                        disabled={loading || days <= 0}
                        className="bg-amber-600 hover:bg-amber-500 text-white font-black px-8 gap-2"
                    >
                        {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4 h-4" />}
                        Appliquer le badge
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

