                backHref={`/dashboard/${guildId}/admin/settings`}
            />

            {/* Divider */}
            <div className="border-b border-white/10" />

            {/* Info Card */}
            <div className="p-4 rounded-lg bg-blue-500/5 border border-blue-500/20 flex gap-3">
