    );
}

"use client";

import { useState, useEffect } from "react";
import { BonusType, MentionType } from "@prisma/client";
import { BonusCard } from "@/components/admin/BonusCard";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import {
    getGuildBonuses,
    getActiveBonus,
    purchaseBonus,
    cancelBonus,
} from "@/server/actions/bonus-actions";
import { Loader2, AlertCircle, XCircle } from "lucide-react";

interface BonusManagerClientProps {
    guildId: string;
}

const ALL_BONUSES: Array<{
    type: BonusType;
    name: string;
    description: string;
    cost: number;
    icon: string;
}> = [
        {
            type: BonusType.FORTUNE,
            name: "Oracle de Fortune",
            description: "+50% chances de loot sur les monstres",
            cost: 20,
            icon: "/bonus_guilde/oracle_de_fortune.png",
        },
        {
            type: BonusType.GLADIATOR,
            name: "Oracle de Gladiateur",
            description: "+50% gains en Kolizéum",
            cost: 20,
            icon: "/bonus_guilde/oracle_de_gladiateur.png",
        },
        {
            type: BonusType.HARVESTER,
            name: "Oracle de Récolteur",
            description: "Possibilité d'obtenir des Rékloots en récolte",
            cost: 50,
            icon: "/bonus_guilde/oracle_de_recolteur.png",
        },
        {
            type: BonusType.WISDOM,
            name: "Oracle de Savoir",
            description: "+50% d'expérience sur toutes les missions",
            cost: 20,
            icon: "/bonus_guilde/oracle_de_savoir.png",
        },
        {
            type: BonusType.DIVINE,
            name: "Oracle Divin",
            description: "Déclenche l'événement Moissonneuse Batteuse",
            cost: 200,
            icon: "/bonus_guilde/oracle_divin.png",
        },
    ];

export function BonusManagerClient({ guildId }: BonusManagerClientProps) {
    const [activeBonus, setActiveBonus] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [purchasing, setPurchasing] = useState(false);
    const [cancelling, setCancelling] = useState(false);
    const [activating, setActivating] = useState(false);

    // Purchase form state
    const [selectedBonus, setSelectedBonus] = useState<BonusType | null>(null);
    const [channelId, setChannelId] = useState("");
    const [mentionType, setMentionType] = useState<MentionType>(MentionType.NONE);
    const [roleId, setRoleId] = useState("");

    useEffect(() => {
        loadActiveBonus();
    }, [guildId]);

    const loadActiveBonus = async () => {
        setLoading(true);
        const result = await getActiveBonus(guildId);
        if (result.success) {
            setActiveBonus(result.data);
        }
        setLoading(false);
    };

    const handlePurchaseClick = (bonusType: BonusType) => {
        setSelectedBonus(bonusType);
    };

    const handleCancelBonus = async () => {
        if (!activeBonus) return;

        setCancelling(true);
        try {
            const result = await cancelBonus(activeBonus.id, guildId);
            if (result.success) {
                toast.success("Bonus annulé avec succès !");
                await loadActiveBonus();
            } else {
                toast.error(result.error || "Échec de l'annulation");
            }
        } catch (error: any) {
            toast.error(error.message || "Erreur lors de l'annulation");
        } finally {
            setCancelling(false);
        }
    };

    const handlePurchaseSubmit = async () => {
        if (!selectedBonus) return;

        setPurchasing(true);
        try {
            const result = await purchaseBonus(
                guildId,
                selectedBonus,
                channelId || undefined,
                mentionType,
                roleId || undefined
            );

            if (result.success) {
                toast.success("Bonus acheté avec succès ! Il est dispo en jeu pendant 24h.");
                setSelectedBonus(null);
                setChannelId("");
                setMentionType(MentionType.NONE);
                setRoleId("");
                await loadActiveBonus();
            } else {
                toast.error(result.error || "Échec de l'achat");
            }
        } catch (error: any) {
            toast.error(error.message || "Erreur lors de l'achat");
        } finally {
            setPurchasing(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-500" />
            </div>
        );
    }

    const isAnyBonusActive = activeBonus !== null;
    const canCancel = activeBonus?.status === "PURCHASED";

    return (
        <div className="space-y-8">
            {/* Active Bonus Warning */}
            {isAnyBonusActive && (
                <div className="bg-orange-500/10 border border-orange-500/30 rounded-lg p-4 flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-orange-400 flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                        <h3 className="font-bold text-orange-400 mb-1">Bonus actuellement disponible</h3>
                        <p className="text-sm text-orange-300/80">
                            Vous ne pouvez acheter qu'un seul bonus à la fois. N'importe quel membre de la guilde peut activer le bonus **en jeu** pendant ce délai de 24h.
                        </p>
                        <div className="mt-2 text-xs text-orange-400">
                            <strong>Bonus actuel :</strong> {activeBonus?.config?.name || "Inconnu"}
                            <br />
                            <strong>Statut :</strong> {activeBonus?.status === "PURCHASED" ? "Disponible en jeu (24h)" : "Actif (en cours)"}
                        </div>
                    </div>
                    <div className="flex flex-col gap-2">
                        {canCancel && (
                            <Button
                                onClick={handleCancelBonus}
                                disabled={cancelling}
                                variant="outline"
                                size="sm"
                                className="border-red-500/50 text-red-400 hover:bg-red-500/10"
                            >
                                {cancelling ? (
                                    <>
                                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                        Annulation...
                                    </>
                                ) : (
                                    <>
                                        <XCircle className="w-4 h-4 mr-2" />
                                        Annuler l'achat
                                    </>
                                )}
                            </Button>
                        )}
                    </div>
                </div>
            )}

            {/* Bonus Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {ALL_BONUSES.map((bonus) => (
                    <BonusCard
                        key={bonus.type}
                        type={bonus.type}
                        name={bonus.name}
                        description={bonus.description}
                        cost={bonus.cost}
                        iconPath={bonus.icon}
                        isPurchased={activeBonus?.bonusType === bonus.type && activeBonus?.status === "PURCHASED"}
                        isActive={activeBonus?.bonusType === bonus.type && activeBonus?.status === "ACTIVE"}
                        onPurchase={() => handlePurchaseClick(bonus.type)}
                    />
                ))}
            </div>

            {/* Purchase Modal */}
            {selectedBonus && (
                <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4">
                    <div className="bg-slate-900 border border-slate-700 rounded-lg max-w-md w-full p-6">
                        <h2 className="text-2xl font-bold text-white mb-4">
                            Acheter {ALL_BONUSES.find(b => b.type === selectedBonus)?.name}
                        </h2>

                        <div className="space-y-4">
                            {/* Channel ID */}
                            <div>
                                <Label className="text-white">Canal Discord (ID)</Label>
                                <input
                                    type="text"
                                    value={channelId}
                                    onChange={(e) => setChannelId(e.target.value)}
                                    placeholder="1234567890"
                                    className="w-full mt-2 px-4 py-2 bg-slate-800 border border-slate-700 rounded-md text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                                />
                                <p className="text-xs text-slate-500 mt-1">Optionnel - Canal où envoyer la notification</p>
                            </div>

                            {/* Mention Type */}
                            <div>
                                <Label className="text-white">Mentionner</Label>
                                <div className="mt-2 space-y-2">
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="mention"
                                            checked={mentionType === MentionType.NONE}
                                            onChange={() => {
                                                setMentionType(MentionType.NONE);
                                                setRoleId("");
                                            }}
                                            className="text-indigo-500"
                                        />
                                        <span className="text-white">Personne</span>
                                    </label>
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="mention"
                                            checked={mentionType === MentionType.EVERYONE}
                                            onChange={() => {
                                                setMentionType(MentionType.EVERYONE);
                                                setRoleId("");
                                            }}
                                            className="text-indigo-500"
                                        />
                                        <span className="text-white">@everyone</span>
                                    </label>
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="mention"
                                            checked={mentionType === MentionType.ROLE}
                                            onChange={() => setMentionType(MentionType.ROLE)}
                                            className="text-indigo-500"
                                        />
                                        <span className="text-white">Un rôle spécifique</span>
                                    </label>
                                </div>
                            </div>

                            {/* Role ID (conditional) */}
                            {mentionType === MentionType.ROLE && (
                                <div>
                                    <Label className="text-white">Rôle Discord (ID)</Label>
                                    <input
                                        type="text"
                                        value={roleId}
                                        onChange={(e) => setRoleId(e.target.value)}
                                        placeholder="1234567890"
                                        className="w-full mt-2 px-4 py-2 bg-slate-800 border border-slate-700 rounded-md text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                                    />
                                </div>
                            )}

                            {/* Cost */}
                            <div className="bg-slate-800/50 border border-slate-700 rounded-lg p-4">
                                <div className="flex items-center justify-between">
                                    <span className="text-slate-400">Coût total</span>
                                    <div className="flex items-center gap-2">
                                        <span className="text-3xl font-bold text-yellow-400">
                                            {ALL_BONUSES.find(b => b.type === selectedBonus)?.cost}
                                        </span>
                                        <span className="text-sm text-slate-400">kamas</span>
                                    </div>
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="flex gap-3 pt-2">
                                <Button
                                    onClick={() => setSelectedBonus(null)}
                                    disabled={purchasing}
                                    variant="outline"
                                    className="flex-1"
                                >
                                    Annuler
                                </Button>
                                <Button
                                    onClick={handlePurchaseSubmit}
                                    disabled={purchasing}
                                    className="flex-1 bg-indigo-600 hover:bg-indigo-700"
                                >
                                    {purchasing ? (
                                        <>
                                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                            Achat...
                                        </>
                                    ) : (
                                        "Confirmer l'achat"
                                    )}
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { 
    Search, Save, Info, Sparkles, Coins, ShieldAlert, 
    ArrowLeft, Loader2, Edit3, Image as ImageIcon 
} from "lucide-react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

import { getAllBounties, updateBountyRecord } from "@/server/actions/admin-actions";

export default function BountiesAdminPage({ params }: { params: { guildId: string } }) {
    const router = useRouter();
    const [bounties, setBounties] = useState<any[]>([]);
    const [filteredBounties, setFilteredBounties] = useState<any[]>([]);
    const [search, setSearch] = useState("");
    const [loading, setLoading] = useState(true);
    const [selectedBounty, setSelectedBounty] = useState<any>(null);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        setLoading(true);
        getAllBounties().then(data => {
            setBounties(data);
            setFilteredBounties(data);
            setLoading(false);
        });
    }, []);

    useEffect(() => {
        const filtered = bounties.filter(b => 
            b.name.toLowerCase().includes(search.toLowerCase()) ||
            (b.zoneName && b.zoneName.toLowerCase().includes(search.toLowerCase()))
        );
        setFilteredBounties(filtered);
    }, [search, bounties]);

    const handleSave = async () => {
        if (!selectedBounty) return;
        setSaving(true);
        try {
            const res = await updateBountyRecord(params.guildId, selectedBounty.id, selectedBounty);
            if (res.success) {
                toast.success("Avis mis à jour avec succès");
                // Refresh local list
                setBounties(prev => prev.map(b => b.id === selectedBounty.id ? selectedBounty : b));
            } else {
                toast.error(res.error || "Erreur lors de la sauvegarde");
            }
        } catch (e) {
            toast.error("Erreur technique lors de la sauvegarde");
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex-1 flex items-center justify-center">
                <Loader2 className="animate-spin text-rose-500" size={48} />
            </div>
        );
    }

    return (
        <div className="flex-1 flex flex-col h-full bg-[#080a10]">
            {/* Header */}
            <header className="p-8 border-b border-white/5 flex items-center justify-between bg-black/20 backdrop-blur-xl">
                <div>
                    <button 
                        onClick={() => router.back()}
                        className="flex items-center gap-2 text-white/40 hover:text-white transition-colors text-[10px] font-black uppercase italic mb-2"
                    >
                        <ArrowLeft size={14} /> Retour Admin
                    </button>
                    <h1 className="text-4xl font-black text-white uppercase italic tracking-tighter flex items-center gap-4">
                        <ShieldAlert className="text-rose-500" size={32} />
                        Gestion des Avis <span className="text-rose-500/10">GOD MODE</span>
                    </h1>
                </div>

                <div className="relative w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-white/20" size={18} />
                    <Input 
                        placeholder="Chercher un avis ou une zone..." 
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-12 bg-white/5 border-white/10 text-white font-bold italic"
                    />
                </div>
            </header>

            <div className="flex-1 flex overflow-hidden">
                {/* Bounty List */}
                <div className="w-1/3 border-r border-white/5 overflow-y-auto p-4 space-y-2 bg-black/10">
                    {filteredBounties.map(b => (
                        <button
                            key={b.id}
                            onClick={() => setSelectedBounty({ ...b })}
                            className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all text-left ${
                                selectedBounty?.id === b.id 
                                    ? 'bg-rose-500/20 border border-rose-500/40' 
                                    : 'bg-white/5 border border-white/5 hover:bg-white/10'
                            }`}
                        >
                            <div className="w-12 h-12 rounded-xl bg-black flex items-center justify-center overflow-hidden border border-white/10">
                                <img src={b.imageUrl} alt="" className="w-10 h-10 object-contain" />
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-sm font-black text-white truncate uppercase italic">{b.name}</p>
                                <p className="text-[10px] font-bold text-white/40 truncate">{b.zoneName || "Zone Inconnue"}</p>
                            </div>
                        </button>
                    ))}
                </div>

                {/* Editor Section */}
                <div className="flex-1 overflow-y-auto p-12">
                    {selectedBounty ? (
                        <div className="max-w-4xl mx-auto space-y-12">
                            {/* Visual Preview */}
                            <div className="grid grid-cols-2 gap-12">
                                <div className="space-y-6">
                                    <div className="aspect-video rounded-[2rem] bg-black border border-white/5 flex items-center justify-center overflow-hidden relative group">
                                        <img src={selectedBounty.imageUrl} alt="" className="w-full h-full object-contain" />
                                        <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                            <Button variant="outline" className="gap-2 bg-white/10 border-white/20">
                                                <ImageIcon size={16} /> Changer l'image
                                            </Button>
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-8">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-rose-500/60 uppercase tracking-widest italic">Nom de l'avis</label>
                                        <Input 
                                            value={selectedBounty.name} 
                                            onChange={(e) => setSelectedBounty({...selectedBounty, name: e.target.value})}
                                            className="text-2xl font-black bg-white/5 border-white/10 h-16 uppercase italic" 
                                        />
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-rose-500/60 uppercase tracking-widest italic">Niveau</label>
                                            <Input 
                                                type="number"
                                                value={selectedBounty.level} 
                                                onChange={(e) => setSelectedBounty({...selectedBounty, level: parseInt(e.target.value)})}
                                                className="bg-white/5 border-white/10 font-bold" 
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-rose-500/60 uppercase tracking-widest italic">Zone(s)</label>
                                            <Input 
                                                value={selectedBounty.zoneName} 
                                                onChange={(e) => setSelectedBounty({...selectedBounty, zoneName: e.target.value})}
                                                className="bg-white/5 border-white/10 font-bold" 
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Rewards & Mechanics */}
                            <div className="grid grid-cols-2 gap-8">
                                <div className="p-8 rounded-[2rem] bg-white/5 border border-white/10 space-y-6">
                                    <h3 className="text-lg font-black text-white uppercase italic flex items-center gap-3">
                                        <Coins className="text-amber-500" size={20} /> Récompenses
                                    </h3>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-white/40 uppercase tracking-widest italic">Quantité</label>
                                            <Input 
                                                type="number"
                                                value={selectedBounty.doplons} 
                                                onChange={(e) => setSelectedBounty({...selectedBounty, doplons: parseInt(e.target.value)})}
                                                className="bg-white/5 border-white/10 font-black h-12" 
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-white/40 uppercase tracking-widest italic">Type</label>
                                            <select 
                                                value={selectedBounty.rewardType}
                                                onChange={(e) => setSelectedBounty({...selectedBounty, rewardType: e.target.value})}
                                                className="w-full h-12 bg-white/5 border border-white/10 rounded-xl px-4 text-white font-black uppercase italic"
                                            >
                                                <option value="Doplon">Doplons</option>
                                                <option value="Aliton">Alitons (PVP)</option>
                                                <option value="Aviton">Avitons</option>
                                                <option value="Kama de glace">Kamas de glace</option>
                                            </select>
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-white/40 uppercase tracking-widest italic">Milice / Ordre</label>
                                        <Input 
                                            value={selectedBounty.milice} 
                                            onChange={(e) => setSelectedBounty({...selectedBounty, milice: e.target.value})}
                                            className="bg-white/5 border-white/10 font-bold" 
                                        />
                                    </div>
                                </div>

                                <div className="p-8 rounded-[2rem] bg-white/5 border border-white/10 space-y-6">
                                    <h3 className="text-lg font-black text-white uppercase italic flex items-center gap-3">
                                        <Sparkles className="text-blue-400" size={20} /> Mécaniques
                                    </h3>
                                    <div className="space-y-2 h-full flex flex-col">
                                        <label className="text-[10px] font-black text-white/40 uppercase tracking-widest italic">Résumé Tactique</label>
                                        <Textarea 
                                            value={selectedBounty.mechanics} 
                                            onChange={(e) => setSelectedBounty({...selectedBounty, mechanics: e.target.value})}
                                            className="flex-1 min-h-[150px] bg-white/5 border-white/10 font-medium text-white/60 leading-relaxed" 
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="flex items-center justify-end gap-4 p-8 border-t border-white/5">
                                <Button 
                                    variant="ghost" 
                                    className="text-white/40 uppercase italic font-black"
                                    onClick={() => setSelectedBounty(null)}
                                >
                                    Annuler
                                </Button>
                                <Button 
                                    onClick={handleSave}
                                    disabled={saving}
                                    className="bg-rose-500 hover:bg-rose-600 text-white font-black uppercase italic px-12 h-16 rounded-2xl shadow-xl shadow-rose-500/20"
                                >
                                    {saving ? <Loader2 className="animate-spin" /> : <Save className="mr-2" size={20} />}
                                    Sauvegarder les modifications
                                </Button>
                            </div>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-center space-y-6 opacity-20">
                            <Edit3 size={80} />
                            <div className="space-y-2">
                                <p className="text-2xl font-black uppercase italic italic">Sélectionnez un avis</p>
                                <p className="text-sm font-bold uppercase italic italic tracking-widest">Pour modifier ses caractéristiques</p>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { getUserContext } from "@/server/actions/user-actions";
import { getGettingStartedProgress } from "@/server/actions/onboarding-actions";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { Sparkles, CheckCircle2, Circle, ArrowRight, Rocket, Shield, Puzzle, BookOpen, Swords, Users } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { cn } from "@/lib/utils";
import { AuroraBackground } from "@/components/ui/aurora-background";

export default async function GettingStartedPage({
    params,
}: {
    params: Promise<{ guildId: string }>;
}) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;
    const user = await getUserContext(guildId);

    if (!user.isAdmin) {
        redirect(`/dashboard/${guildId}`);
    }

    const progress = await getGettingStartedProgress(guildId);
    const percent = Math.round((progress.totalPoints / progress.maxPoints) * 100);

    const iconMap: Record<string, any> = {
        discord: Shield,
        modules: Puzzle,
        presentation: BookOpen,
        missions: Swords,
        members: Users,
    };

    return (
        <div className="relative min-h-full pb-20 space-y-10">
            {/* Ambient Background */}
            <AuroraBackground className="absolute inset-0 z-0 opacity-10 pointer-events-none" />

            <div className="relative z-10 space-y-10">
                <UnifiedModuleHeader
                    title="Mise en route"
                    description="Configurez votre guilde en 5 étapes clés"
                    icon={Rocket}
                    backHref={`/dashboard/${guildId}/admin`}
                />

                {/* Main Progress Card */}
                <div className="relative group mx-1">
                    <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500/20 via-purple-500/20 to-emerald-500/20 rounded-2xl blur-xl opacity-50" />
                    <div className="relative glass-premium p-8 rounded-2xl border border-white/10 overflow-hidden">
                        <div className="flex flex-col md:flex-row items-center gap-8">
                            <div className="relative flex-shrink-0">
                                <div className="w-24 h-24 rounded-full border-4 border-white/5 flex items-center justify-center relative">
                                    <svg className="w-full h-full transform -rotate-90">
                                        <circle
                                            cx="48"
                                            cy="48"
                                            r="44"
                                            fill="transparent"
                                            stroke="currentColor"
                                            strokeWidth="4"
                                            className="text-white/5"
                                        />
                                        <circle
                                            cx="48"
                                            cy="48"
                                            r="44"
                                            fill="transparent"
                                            stroke="currentColor"
                                            strokeWidth="4"
                                            strokeDasharray="276"
                                            strokeDashoffset={276 - (276 * percent) / 100}
                                            className="text-emerald-500 transition-all duration-1000 ease-out"
                                            strokeLinecap="round"
                                        />
                                    </svg>
                                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                                        <span className="text-2xl font-black text-white">{percent}%</span>
                                    </div>
                                </div>
                            </div>
                            <div className="flex-1 space-y-2 text-center md:text-left">
                                <h2 className="text-2xl font-black text-white tracking-tight uppercase">Progression de l'installation</h2>
                                <p className="text-zinc-400 font-medium">
                                    {percent === 100
                                        ? "Votre guilde est parfaitement configurée ! Vous êtes prêt à dominer le Monde des Douze."
                                        : "Suivez ces étapes pour débloquer tout le potentiel de SigilOS pour vos membres."}
                                </p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Steps List */}
                <div className="grid grid-cols-1 gap-4 mx-1">
                    {progress.steps.map((step, idx) => {
                        const Icon = iconMap[step.id] || Sparkles;
                        const isCompleted = step.status === "COMPLETED";
                        const isInProgress = step.status === "IN_PROGRESS";

                        return (
                            <div
                                key={step.id}
                                className={cn(
                                    "group relative glass-premium p-6 rounded-xl border transition-all duration-300",
                                    isCompleted ? "border-emerald-500/20 bg-emerald-500/5 shadow-[0_0_20px_rgba(16,185,129,0.05)]" : "border-white/10 hover:border-white/20"
                                )}
                            >
                                <div className="flex items-start gap-6">
                                    <div className={cn(
                                        "w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0 transition-transform group-hover:scale-110",
                                        isCompleted ? "bg-emerald-500/10 text-emerald-400" : "bg-white/5 text-zinc-400"
                                    )}>
                                        <Icon className="w-6 h-6" />
                                    </div>
                                    <div className="flex-1 space-y-1">
                                        <div className="flex items-center gap-3">
                                            <h3 className={cn(
                                                "text-lg font-black tracking-tight uppercase",
                                                isCompleted ? "text-emerald-400" : "text-white"
                                            )}>
                                                {idx + 1}. {step.title}
                                            </h3>
                                            {isCompleted && (
                                                <Badge variant="outline" className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 text-[8px] font-black uppercase">Terminé</Badge>
                                            )}
                                        </div>
                                        <p className="text-sm text-zinc-400 font-medium leading-relaxed max-w-2xl">
                                            {step.description}
                                        </p>
                                    </div>
                                    <div className="flex flex-col items-end justify-center h-full pt-2">
                                        <Button
                                            asChild
                                            variant={isCompleted ? "outline" : "default"}
                                            className={cn(
                                                "font-black uppercase tracking-widest text-[10px] px-6 h-10",
                                                isCompleted ? "border-emerald-500/20 text-emerald-500 hover:bg-emerald-500/5" : "bg-white text-black hover:bg-zinc-200"
                                            )}
                                        >
                                            <Link href={step.href}>
                                                {isCompleted ? "Revoir" : "Configurer"}
                                                <ArrowRight className="ml-2 w-3 h-3 group-hover:translate-x-1 transition-transform" />
                                            </Link>
                                        </Button>
                                    </div>
                                </div>

                                {isCompleted && (
                                    <div className="absolute top-4 right-4 text-emerald-500/20">
                                        <CheckCircle2 className="w-12 h-12 rotate-12" />
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
}

function Badge({ children, className, variant }: any) {
    return (
        <span className={cn(
            "px-2 py-0.5 rounded-full text-[10px]",
            className
        )}>
            {children}
        </span>
    );
}

