    { value: "POLL_CREATED,POLL_CLOSED,POLL_DELETED,POLL_CREATOR_ROLE_ACQUIRED", label: "📊 Sondages & Micro" },
    { value: "MEMBER_PURGED,MEMBER_BANNED,MEMBER_ARCHIVED,MEMBER_LEFT,WEBHOOK_MEMBER_ADD,WEBHOOK_MEMBER_REMOVE,PLATFORM_ARRIVAL,PLATFORM_DEPARTURE,PROFILE_ARCHIVED,PROFILE_REACTIVATED,MEMBER_PSEUDO_UPDATE,MEMBER_ANKAMA_ID_UPDATE", label: "🔄 Mouvements" },
    { value: "CONFIG_UPDATED,SETTINGS_UPDATED", label: "⚙️ Configuration" },
    { value: "ADMIN_FULL_DENIED,SECURITY_ALERT", label: "🛡️ Sécurité" },
    { value: "CHAT_BLOCKED_ATTEMPT", label: "💬 Modération Chat" },
    { value: "USER_GDPR_DELETE", label: "🗑️ Suppressions RGPD" },
];

type PermissionChange = {
    roleId: string;
    roleName?: string;
    added: Array<{ permission: string; label: string; module: string }>;
    removed: Array<{ permission: string; label: string; module: string }>;
};

type AuditMetadata = {
    rolesAffected?: number;
    changes?: PermissionChange[];
    timestamp?: string;
    description?: string;
    reason?: string;
    fileName?: string;
    missionTitle?: string;
    scores?: any[];
    // Chat
    message?: string;
    strikes?: number;
    threshold?: number;
    // GDPR
    discordId?: string;
    guildName?: string;
};

// ... (inside component render)

type AuditLog = {
    id: string;
    actorName: string;
    action: string;
    targetType: string;
    targetId: string | null;
    metadata: AuditMetadata | null;
    createdAt: string;
};

type Props = {
    guildId: string;
    initialLogs: AuditLog[];
    initialTotal: number;
    roleNames: Record<string, string>;
};

const ITEMS_PER_PAGE = 20;

function formatDate(date: string): string {
    return new Intl.DateTimeFormat("fr-FR", {
        day: "2-digit",
        month: "short",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
    }).format(new Date(date));
}

function PermissionChangesDisplay({
    metadata,
    roleNames
}: {
    metadata: AuditMetadata;
    roleNames: Record<string, string>;
}) {
    if (!metadata.changes || metadata.changes.length === 0) {
        return null;
    }

    return (
        <div className="mt-3 space-y-2">
            {metadata.changes.map((change, idx) => {
                const roleName = change.roleName || roleNames[change.roleId] || `Rôle inconnu`;
                return (
                    <div key={idx} className="bg-zinc-800/50 rounded-lg p-3 border border-white/5">
                        <div className="text-xs text-muted-foreground mb-2">
                            Rôle: <span className="font-semibold text-foreground">{roleName}</span>
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                            {change.added.map((perm, i) => (
                                <Badge key={`add-${i}`} variant="outline" className="bg-emerald-500/10 text-emerald-400 border-emerald-500/30 text-xs">
                                    <Plus className="w-3 h-3 mr-1" />
                                    {perm.label}
                                    <span className="ml-1 text-emerald-400/60 text-[10px]">({perm.module})</span>
                                </Badge>
                            ))}
                            {change.removed.map((perm, i) => (
                                <Badge key={`rem-${i}`} variant="outline" className="bg-red-500/10 text-red-400 border-red-500/30 text-xs">
                                    <Minus className="w-3 h-3 mr-1" />
                                    {perm.label}
                                    <span className="ml-1 text-red-400/60 text-[10px]">({perm.module})</span>
                                </Badge>
                            ))}
                        </div>
                    </div>
                );
            })}
        </div>
    );
}

export function AuditLogsClient({ guildId, initialLogs, initialTotal, roleNames }: Props) {
    const [logs, setLogs] = useState<AuditLog[]>(initialLogs);
    const [total, setTotal] = useState(initialTotal);
    const [page, setPage] = useState(1);
    const [loading, setLoading] = useState(false);

    // Filters
    const [actionFilter, setActionFilter] = useState<string>("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");

    const totalPages = Math.ceil(total / ITEMS_PER_PAGE);

    // Debounce search
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(searchQuery);
        }, 300);
        return () => clearTimeout(timer);
    }, [searchQuery]);

    // Fetch logs when filters or page change
    const fetchLogs = useCallback(async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                page: page.toString(),
                limit: ITEMS_PER_PAGE.toString(),
            });

            if (actionFilter && actionFilter !== "all") {
                params.set("action", actionFilter);
            }
            if (debouncedSearch) {
                params.set("search", debouncedSearch);
            }

            const res = await fetch(`/api/guild/${guildId}/audit-logs?${params.toString()}`);
            if (res.ok) {
                const data = await res.json();
                setLogs(data.logs);
                setTotal(data.total);
            }
        } catch (error) {
            console.error("Failed to fetch logs:", error);
        } finally {
            setLoading(false);
        }
    }, [guildId, page, actionFilter, debouncedSearch]);

    useEffect(() => {
        // Skip initial fetch since we have initialLogs
        if (page === 1 && actionFilter === "all" && !debouncedSearch) {
            return;
        }
        fetchLogs();
    }, [page, actionFilter, debouncedSearch, fetchLogs]);

    // Reset page when filters change
    useEffect(() => {
        setPage(1);
    }, [actionFilter, debouncedSearch]);

    const clearFilters = () => {
        setActionFilter("all");
        setSearchQuery("");
        setDebouncedSearch("");
        setPage(1);
    };

    const hasActiveFilters = actionFilter !== "all" || debouncedSearch;

    return (
        <Card className="bg-zinc-900/60 border-white/5">
            <CardHeader className="pb-2">
                <CardTitle className="flex items-center gap-2 text-base">
                    <Clock className="h-4 w-4 text-muted-foreground" />
                    Historique
                    <Badge variant="secondary" className="ml-2">
                        {total} entrées
                    </Badge>
                </CardTitle>
            </CardHeader>

            {/* Filters Toolbar */}
            <div className="overflow-x-auto no-scrollbar border-b border-white/5">
                <div className="px-6 py-3 flex items-center gap-3 min-w-max">
                    <div className="flex items-center gap-2">
                        <Filter className="h-4 w-4 text-muted-foreground" />
                        <span className="text-sm text-muted-foreground">Filtres</span>
                    </div>

                    <Select value={actionFilter} onValueChange={setActionFilter}>
                        <SelectTrigger className="w-[180px] h-8 text-xs bg-zinc-800 border-white/10">
                            <SelectValue placeholder="Type d'action" />
                        </SelectTrigger>
                        <SelectContent>
                            {ACTION_OPTIONS.map(opt => (
                                <SelectItem key={opt.value} value={opt.value} className="text-xs">
                                    {opt.label}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>

                    <div className="relative">
                        <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground" />
                        <input
                            type="text"
                            placeholder="Rechercher..."
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            className="h-8 w-[160px] pl-7 pr-2 rounded-md border border-white/10 bg-zinc-800 text-xs text-white placeholder:text-zinc-500 focus:outline-none focus:ring-1 focus:ring-white/20 transition-all"
                        />
                    </div>

                    {hasActiveFilters && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={clearFilters}
                            className="h-8 text-xs text-muted-foreground hover:text-foreground"
                        >
                            <X className="h-3 w-3 mr-1" />
                            Effacer
                        </Button>
                    )}

                    <div className="flex items-center gap-2 ml-4">
                        <span className="text-xs text-muted-foreground whitespace-nowrap">
                            Page {page} / {totalPages || 1}
                        </span>
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                            disabled={page === 1 || loading}
                            className="h-8 w-8 p-0"
                        >
                            <ChevronLeft className="h-4 w-4" />
                        </Button>
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                            disabled={page >= totalPages || loading}
                            className="h-8 w-8 p-0"
                        >
                            <ChevronRight className="h-4 w-4" />
                        </Button>
                    </div>
                </div>
            </div>

            <CardContent className="pt-4">
                {loading ? (
                    <div className="space-y-4">
                        {[...Array(5)].map((_, i) => (
                            <div key={i} className="h-16 bg-zinc-800/30 rounded-lg animate-pulse" />
                        ))}
                    </div>
                ) : logs.length === 0 ? (
                    <p className="text-center text-muted-foreground py-8">
                        {hasActiveFilters ? "Aucun résultat pour ces filtres." : "Aucune action enregistrée."}
                    </p>
                ) : (
                    <div className="space-y-4">
                        {logs.map((log) => {
                            const metadata = (log.metadata || {}) as AuditMetadata;

                            // Format message for display (truncation)
                            const displayMsg = metadata.message && metadata.message.length > 100
                                ? metadata.message.substring(0, 100) + "..."
                                : metadata.message;

                            return (
                                <div key={log.id} className="relative pl-6 border-l-2 border-white/10 pb-4 last:pb-0">
                                    <div className="absolute left-[-5px] top-1 w-2 h-2 rounded-full bg-primary" />
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-2 flex-wrap">
                                                <User className="h-4 w-4 text-muted-foreground shrink-0" />
                                                <span className="font-semibold text-foreground">
                                                    {log.actorName}
                                                </span>
                                                <Badge
                                                    variant="outline"
                                                    className={ACTION_COLORS[log.action] || "bg-zinc-500/20 text-zinc-400"}
                                                >
                                                    {ACTION_LABELS[log.action] || log.action}
                                                </Badge>
                                            </div>
                                            <div className="text-sm text-muted-foreground mt-1">
                                                {log.targetType === "PERMISSION" && "Modification des permissions RBAC"}
                                                {log.targetType === "ROLE" && "Modification d'un rôle Discord"}
                                                {log.targetType === "CONFIG" && "Modification de la configuration"}
                                                {log.targetType === "CHANNEL" && "Modification d'un canal"}
                                                {log.targetType === "ACCESS_ATTEMPT" && (
                                                    <span className="text-red-400">
                                                        Tentative d'accès non autorisé à <code className="bg-red-900/30 px-1 rounded">{log.targetId}</code>
                                                    </span>
                                                )}
                                                {log.targetType === "PROFILE" && (
                                                    <span>
                                                        Action sur le profil de <span className="font-medium text-foreground">{metadata.description || log.targetId}</span>
                                                        {metadata.reason && <span className="text-xs ml-2 opacity-70">({metadata.reason})</span>}
                                                    </span>
                                                )}
                                                {log.targetType === "USER" && log.action === "USER_GDPR_DELETE" && (
                                                    <span className="text-red-300">
                                                        Compte supprimé (RGPD)
                                                        {metadata.discordId && (
                                                            <code className="ml-1.5 bg-red-900/30 px-1.5 py-0.5 rounded text-[10px] font-mono">
                                                                Discord #{metadata.discordId}
                                                            </code>
                                                        )}
                                                    </span>
                                                )}
                                                {log.targetType === "CONTENT_SAFETY" && (
                                                    <div className="text-red-300 font-medium space-y-1">
                                                        <div>{metadata.description || "Alerte de sécurité"}</div>
                                                        {metadata.missionTitle && (
                                                            <div className="text-xs opacity-80">Mission : {metadata.missionTitle}</div>
                                                        )}
                                                        {metadata.fileName && (
                                                            <div className="text-xs opacity-80">Fichier : {metadata.fileName}</div>
                                                        )}
                                                        {metadata.reason && (
                                                            <div className="text-xs mt-1 bg-red-950/30 p-1.5 rounded border border-red-500/20">
                                                                Raison : {metadata.reason}
                                                            </div>
                                                        )}
                                                    </div>
                                                )}
                                                {log.targetType === "MISSION" && (
                                                    <div className="space-y-1.5 mt-1">
                                                        <div className="flex items-center gap-2 flex-wrap text-sm">
                                                            <span className="font-bold text-zinc-100 italic">
                                                                {(metadata as any).missionTitle || "Mission"}
                                                            </span>
                                                            <span className="text-zinc-500">pour</span>
                                                            <span className="font-bold text-zinc-300">
                                                                {(metadata as any).submitterName || "un membre"}
                                                            </span>
                                                            
                                                            {(metadata as any).source && (
                                                                <Badge variant="outline" className={cn(
                                                                    "text-[9px] px-1.5 py-0 h-4 font-black uppercase tracking-widest",
                                                                    (metadata as any).source === "discord_button" 
                                                                        ? "bg-indigo-500/10 text-indigo-400 border-indigo-500/20" 
                                                                        : "bg-blue-500/10 text-blue-400 border-blue-500/20"
                                                                )}>
                                                                    {(metadata as any).source === "discord_button" ? "Discord" : "Dashboard"}
                                                                </Badge>
                                                            )}
                                                        </div>
                                                        
                                                        {log.action === "MISSION_VALIDATED" && (
                                                            <div className="flex items-center gap-3">
                                                                {(metadata as any).xpReward > 0 && (
                                                                    <span className="text-[10px] font-black text-emerald-400 flex items-center gap-1">
                                                                        <Plus className="w-2.5 h-2.5" /> {(metadata as any).xpReward} XP
                                                                    </span>
                                                                )}
                                                                {(metadata as any).guildatonsReward > 0 && (
                                                                    <span className="text-[10px] font-black text-amber-500 flex items-center gap-1">
                                                                        <Plus className="w-2.5 h-2.5" /> {(metadata as any).guildatonsReward} Guildatons
                                                                    </span>
                                                                )}
                                                                {(metadata as any).helpersCount > 0 && (
                                                                    <span className="text-[10px] font-black text-indigo-400 flex items-center gap-1">
                                                                        <Plus className="w-2.5 h-2.5" /> {(metadata as any).helpersCount} Helpers
                                                                    </span>
                                                                )}
                                                            </div>
                                                        )}
                                                    </div>
                                                )}

                                                {log.targetType === "PROFILE" && (
                                                    <div className="space-y-1.5 mt-1">
                                                        <div className="flex items-center gap-2 flex-wrap text-sm">
                                                            <span className="text-zinc-500">Mise à jour pour</span>
                                                            <span className="font-bold text-zinc-300">
                                                                {(metadata as any).submitterName || metadata.description || log.targetId}
                                                            </span>
                                                            
                                                            {(metadata as any).source && (
                                                                <Badge variant="outline" className={cn(
                                                                    "text-[9px] px-1.5 py-0 h-4 font-black uppercase tracking-widest",
                                                                    (metadata as any).source === "discord_button" 
                                                                        ? "bg-indigo-500/10 text-indigo-400 border-indigo-500/20" 
                                                                        : "bg-blue-500/10 text-blue-400 border-blue-500/20"
                                                                )}>
                                                                    {(metadata as any).source === "discord_button" ? "Discord" : "Dashboard"}
                                                                </Badge>
                                                            )}
                                                        </div>
                                                        
                                                        {(metadata as any).points !== undefined && (
                                                            <div className="flex items-center gap-3">
                                                                <span className="text-[10px] font-black text-emerald-400 flex items-center gap-1">
                                                                    <Plus className="w-2.5 h-2.5" /> {(metadata as any).points} Points Succès
                                                                </span>
                                                            </div>
                                                        )}
                                                    </div>
                                                )}

                                                {log.targetType === "GUILD" && (
                                                    <span className="text-sm">
                                                        {(metadata as any).bonusName && (
                                                            <span className="font-medium text-cyan-300">{(metadata as any).bonusName}</span>
                                                        )}
                                                        {(metadata as any).cost && (
                                                            <span className="text-xs opacity-70 ml-2">{(metadata as any).cost} Guildatons</span>
                                                        )}
                                                        {(metadata as any).field === "bonusNotifyChannelId" && (
                                                            <span className="text-xs opacity-70">Canal de notification bonus mis à jour</span>
                                                        )}
                                                    </span>
                                                )}
                                            </div>

                                            {log.action === "RBAC_UPDATE" && metadata.changes && (
                                                <PermissionChangesDisplay metadata={metadata} roleNames={roleNames} />
                                            )}

                                            {log.action === "CHAT_BLOCKED_ATTEMPT" && (
                                                <div className="mt-2 bg-red-950/20 border border-red-500/10 rounded-lg p-2.5 text-xs">
                                                    <div className="flex items-center justify-between mb-1.5">
                                                        <span className="text-red-300/80 font-medium">Contenu bloqué détecté</span>
                                                        <Badge variant="outline" className="text-[10px] h-4 bg-red-500/5 text-red-400 border-red-500/20 uppercase tracking-tighter">
                                                            {metadata.strikes} / {metadata.threshold} strikes
                                                        </Badge>
                                                    </div>
                                                    <div className="bg-black/20 rounded border border-white/5 p-2 italic text-red-200/60 break-all">
                                                        "{displayMsg}"
                                                    </div>
                                                    {metadata.strikes === metadata.threshold && (
                                                        <div className="mt-1.5 text-[10px] text-red-400 font-bold flex items-center gap-1">
                                                            <Shield className="w-2.5 h-2.5" />
                                                            UTILISATEUR BANNI TEMPORAIREMENT (15 MIN)
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                        <div className="text-xs text-muted-foreground whitespace-nowrap">
                                            {formatDate(log.createdAt)}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import AccessDenied from "@/components/access-denied";
import { getUserContext } from "@/server/actions/user-actions";
import { getAuditLogs, logAdminAccessDenied, cleanupOldAuditLogs } from "@/server/actions/audit-actions";
import { fetchGuildRoles } from "@/server/discord";
import { FileText, Shield } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { AuditLogsClient } from "./_components/audit-logs-client";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";

type Props = {
    params: Promise<{ guildId: string }>;
};

export default async function AdminLogsPage({ params }: Props) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;

    // Security: Verify admin access + Audit Log
    const user = await getUserContext(guildId);
    if (!user.canViewAuditLogs) {
        await logAdminAccessDenied(guildId, "/admin/logs");
        return <AccessDenied />;
    }

    // Lazy Cleanup: Trigger automatic cleanup of old logs (fire & forget)
    // Retention policy is exactly 30 days (consistent with UI notice)
    cleanupOldAuditLogs(guildId).catch(err =>
        console.error("[LazyCleanup] Failed to clean old logs:", err)
    );

    // Fetch audit logs (initial page)
    const logsResult = await getAuditLogs(guildId, { limit: 20, page: 1 });
    const logs = logsResult.success && logsResult.data ? logsResult.data.logs : [];
    const total = logsResult.success && logsResult.data ? logsResult.data.total : 0;

    // Fetch Discord roles to get role names
    const roleNames: Record<string, string> = {};
    try {
        const roles = await fetchGuildRoles(guildId);
        roles.forEach(role => {
            roleNames[role.id] = role.name;
        });
    } catch (error) {
        console.error("[AdminLogs] Failed to fetch role names:", error);
    }

    // Convert dates and BigInts for client component
    const serializedLogs = logs.map(log => {
        // Handle BigInts in metadata/oldValue/newValue (Prisma Json fields)
        const stringify = (val: any) => {
            if (!val) return val;
            return JSON.parse(JSON.stringify(val, (_, v) => 
                typeof v === 'bigint' ? v.toString() : v
            ));
        };

        return {
            ...log,
            createdAt: log.createdAt.toISOString(),
            metadata: stringify(log.metadata),
            oldValue: stringify(log.oldValue),
            newValue: stringify(log.newValue),
        };
    });

    return (
        <div className="space-y-6 pb-12">
            <UnifiedModuleHeader
                title="Logs d'Audit"
                description="Historique des modifications administratives"
                icon={FileText}
                backHref={`/dashboard/${guildId}/admin`}
            />

            {/* Security Notice */}
                <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-6 flex items-start gap-4 mb-8">
                    <Shield className="w-6 h-6 text-amber-500 shrink-0 mt-1" />
                    <div>
                        <h2 className="text-amber-500 font-black uppercase tracking-wider mb-1">Journal de Transparence</h2>
                        <p className="text-zinc-400 text-sm leading-relaxed">
                            Ces entrées sont enregistrées pour garantir la sécurité de la guilde et la traçabilité des actions administratives. 
                            Conformément à notre politique de confidentialité, ces journaux sont <strong>automatiquement supprimés après 30 jours</strong>.
                        </p>
                    </div>
                </div>

            {/* Logs Timeline - Client Component */}
            <AuditLogsClient
                guildId={guildId}
                initialLogs={serializedLogs}
                initialTotal={total}
                roleNames={roleNames}
            />
        </div>
    );
}

import { Suspense } from "react";
import { getUserContext, getGuildMemberStats, getGuildMembers } from "@/server/actions/user-actions";
import { redirect } from "next/navigation";
import MemberManagement from "@/components/admin/members/member-management";
import { db } from "@/lib/prisma";
import { fetchGuildChannels, fetchGuildRoles } from "@/server/discord";
import { getRelanceHistory } from "@/server/actions/relance-actions";

export const metadata = {
    title: "Gestion des Membres | SigilOS",
    description: "Audit, réconciliation et gestion des profils membres.",
};

interface AdminMembersPageProps {
    params: Promise<{
        guildId: string;
    }>;
}

export default async function AdminMembersPage({ params }: AdminMembersPageProps) {
    const { guildId } = await params;
    
    let ctx, stats, members, guildConfig, channels, roles, historyRes;
    
    try {
        // Parallel fetching for performance
        [ctx, stats, members, guildConfig, channels, roles, historyRes] = await Promise.all([
            getUserContext(guildId),
            getGuildMemberStats(guildId),
            getGuildMembers(guildId),
            db.guildConfig.findUnique({
                where: { discordGuildId: guildId },
                select: { welcomeBadgeName: true }
            }),
            fetchGuildChannels(guildId),
            fetchGuildRoles(guildId),
            getRelanceHistory(guildId)
        ]);
    } catch (err) {
        console.error("[CRITICAL] Members Page Fetch Error:", err);
        throw err; // Re-throw to trigger boundary
    }

    const textChannels = (channels || []).filter(c => c.type === 0 || c.type === 5);
    const history = historyRes.success ? historyRes.data : [];

    // RBAC: Need Admin, Member Manage, or Relance Manage permission
    if (!ctx.isAdmin && !ctx.canManageMembers && !ctx.canManageRelance) {
        redirect(`/dashboard/${guildId}`);
    }

    return (
        <div className="container max-w-7xl mx-auto py-6 lg:py-10 px-4">
            <Suspense fallback={<AdminMembersSkeleton />}>
                <MemberManagement 
                    guildId={guildId} 
                    initialStats={stats}
                    initialMembers={members}
                    welcomeBadgeName={guildConfig?.welcomeBadgeName || "Nouveau"}
                    isSuperAdmin={ctx.isSuperAdmin}
                    channels={textChannels as any}
                    roles={roles || []}
                    initialHistory={history || []}
                    canManageMembers={ctx.canManageMembers || ctx.isAdmin}
                    canManageRelance={ctx.canManageRelance}
                />
            </Suspense>
        </div>
    );
}

