import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { fetchGuildRoles } from "@/server/discord";
import { PermissionsManager } from "@/app/dashboard/[guildId]/admin/_components/permissions-manager";
import { onboardGuild } from "@/server/actions/admin-actions";
import { redirect } from "next/navigation";
import AccessDenied from "@/components/access-denied";
import { getUserContext, getGuildMembers } from "@/server/actions/user-actions";
import { logAdminAccessDenied } from "@/server/actions/audit-actions";
import { type PermissionId } from "@/lib/permissions";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { Shield, AlertTriangle } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

export default async function PermissionsPage({
    params,
}: {
    params: Promise<{ guildId: string }>;
}) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;

    const user = await getUserContext(guildId);
    if (!user.isDiscordAdmin) {
        await logAdminAccessDenied(guildId, "/admin/permissions");
        return <AccessDenied />;
    }

    let config = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
    });

    if (!config) {
        const res = await onboardGuild(guildId);
        if (!res.success) {
            return (
                <div className="p-6 text-red-500">
                    <h2 className="text-xl font-bold">Onboarding Failed</h2>
                    <p>{res.error}</p>
                </div>
            );
        }
        config = await db.guildConfig.findUnique({ where: { discordGuildId: guildId } });
    }

    if (!config) return <div>Fatal: Configuration not found after onboarding.</div>;

    let roles: any[] = [];
    let membersData: any = { members: [] };
    try {
        roles = await fetchGuildRoles(guildId);
        membersData = await getGuildMembers(guildId);
    } catch (e) {
        return (
            <div className="p-6 flex flex-col gap-4">
                <h1 className="text-2xl font-bold text-red-500">Discord Connection Failed</h1>
                <p>Could not fetch roles from Discord. Please verify:</p>
                <ul className="list-disc list-inside text-muted-foreground">
                    <li><code>DISCORD_BOT_TOKEN</code> is correct in .env</li>
                    <li>Bot is invited to the server</li>
                </ul>
                <pre className="bg-neutral-900 text-neutral-100 p-4 rounded mt-4 overflow-auto">
                    {String(e)}
                </pre>
            </div>
        );
    }

    const currentMapping = (config.rolesMapping || {}) as Record<string, PermissionId[]>;
    const currentUsersMapping = ((config as any).usersMapping || {}) as Record<string, PermissionId[]>;

    return (
        <div className="space-y-8 pb-12">
            <UnifiedModuleHeader
                title="Permissions"
                description={`Attribuez les droits aux rôles Discord et aux membres de ${config.name}`}
                icon={Shield}
                backHref={`/dashboard/${guildId}/admin`}
            />

            <Alert className="bg-amber-500/10 border-amber-500/20 text-amber-500 shadow-lg mb-8">
                <AlertTriangle className="h-5 w-5 !text-amber-500" />
                <AlertTitle className="pl-8 font-black uppercase tracking-widest text-amber-500">Accès Restreint : Administrateurs Discord</AlertTitle>
                <AlertDescription className="pl-8 mt-2 leading-relaxed text-amber-500/90 font-medium">
                    L'accès à cette page de gestion des permissions (RBAC) est <strong>strictement réservé au Propriétaire du serveur Discord et à ses Administrateurs</strong> (permission native Discord). Il n'est pas possible d'assigner l'accès à ce système via la matrice ci-dessous afin de prévenir toute usurpation de privilèges.
                </AlertDescription>
            </Alert>

            <PermissionsManager
                guildId={guildId}
                roles={roles}
                members={membersData.members || []}
                currentMapping={currentMapping}
                currentUsersMapping={currentUsersMapping}
            />
        </div>
    );
}

"use client";

import * as React from "react";
import { Check, ChevronsUpDown, Search, User, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { DiscordMemberOption } from "@/server/actions/presentation-actions";

interface MemberSelectorProps {
    value?: string;
    onChange: (value: string) => void;
    members: DiscordMemberOption[];
    placeholder?: string;
    className?: string;
    error?: boolean;
}

export function MemberSelector({
    value = "",
    onChange,
    members = [],
    placeholder = "Sélectionner un membre...",
    className,
    error
}: MemberSelectorProps) {
    const [open, setOpen] = React.useState(false);
    const [inputValue, setInputValue] = React.useState("");

    // Find selected member object if it matches a Discord member
    const selectedMember = members.find((member) => member.name === value);

    const handleSelect = (currentValue: string) => {
        onChange(currentValue);
        setOpen(false);
    };

    // Handle custom input when pressing enter or blurring if no match found
    const handleCustomInput = () => {
        if (!inputValue) return;

        // Only block HTML injection characters - everything else is allowed
        const hasHtmlChars = /[<>"'&]/.test(inputValue);

        if (hasHtmlChars) {
            // Block HTML injection attempts
            return;
        }

        if (inputValue !== value) {
            onChange(inputValue);
            setOpen(false);
        }
    };

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className={cn(
                        "w-full justify-between bg-zinc-900/50 border-white/10 hover:bg-zinc-800 hover:text-white",
                        !value && "text-zinc-500",
                        error && "border-red-500/50 text-red-400",
                        className
                    )}
                >
                    <div className="flex items-center gap-2 truncate">
                        {selectedMember ? (
                            <>
                                <Avatar className="h-5 w-5">
                                    <AvatarImage src={selectedMember.avatar || undefined} />
                                    <AvatarFallback className="text-[10px] bg-indigo-500/20 text-indigo-300">
                                        {(selectedMember.name || "??").substring(0, 2).toUpperCase()}
                                    </AvatarFallback>
                                </Avatar>
                                <span className="truncate">{selectedMember.name}</span>
                            </>
                        ) : value ? (
                            <span className="truncate">{value}</span>
                        ) : (
                            <span className="truncate">{placeholder}</span>
                        )}
                    </div>
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[calc(100vw-2rem)] sm:w-[300px] p-0 bg-zinc-950 border-white/10" align="start">
                <Command shouldFilter={false}>
                    <div className="flex items-center border-b border-white/10 px-3" cmdk-input-wrapper="">
                        <Search className="mr-2 h-4 w-4 shrink-0 opacity-50" />
                        <input
                            className="flex h-11 w-full rounded-md bg-transparent py-3 text-sm outline-none placeholder:text-zinc-500 disabled:cursor-not-allowed disabled:opacity-50 text-white"
                            placeholder="Rechercher ou saisir un pseudo..."
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            onKeyDown={(e) => {
                                if (e.key === "Enter") {
                                    handleCustomInput();
                                }
                            }}
                        />
                    </div>
                    <CommandList>
                        <CommandEmpty className="py-2 px-2 text-sm text-zinc-500 text-center">
                            {inputValue ? (
                                !/[<>"'&]/.test(inputValue) ? (
                                    <button
                                        type="button"
                                        className="w-full text-left p-3 rounded-xl hover:bg-white/5 text-indigo-400 flex items-center gap-3 transition-colors border border-dashed border-indigo-500/20"
                                        onClick={(e) => {
                                            e.preventDefault();
                                            handleCustomInput();
                                        }}
                                    >
                                        <div className="w-8 h-8 rounded-full bg-indigo-500/10 flex items-center justify-center">
                                            <User className="h-4 w-4" />
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-sm font-bold">Utiliser "{inputValue}"</span>
                                            <span className="text-[10px] text-zinc-500 uppercase tracking-widest">Saisie manuelle</span>
                                        </div>
                                    </button>
                                ) : (
                                    <span className="text-red-400 text-xs flex items-center gap-2 justify-center py-2">
                                        <X className="h-3 w-3" />
                                        Caractères HTML interdits (&lt; &gt; " ' &amp;)
                                    </span>
                                )
                            ) : (
                                "Aucun résultat."
                            )}
                        </CommandEmpty>
                        <CommandGroup heading="Membres Discord">
                            {members
                                .filter((member) =>
                                    member.name.toLowerCase().includes(inputValue.toLowerCase())
                                )
                                .slice(0, 50) // Limit results for performance
                                .map((member) => (
                                    <CommandItem
                                        key={member.id}
                                        value={member.name}
                                        onSelect={handleSelect}
                                        className="gap-2 cursor-pointer aria-selected:bg-zinc-900 aria-selected:text-white"
                                    >
                                        <Avatar className="h-6 w-6">
                                            <AvatarImage src={member.avatar || undefined} />
                                            <AvatarFallback className="text-[10px] bg-indigo-500/20 text-indigo-300">
                                                {(member.name || "??").substring(0, 2).toUpperCase()}
                                            </AvatarFallback>
                                        </Avatar>
                                        <span className="truncate">{member.name}</span>
                                        <Check
                                            className={cn(
                                                "ml-auto h-4 w-4",
                                                value === member.name ? "opacity-100" : "opacity-0"
                                            )}
                                        />
                                    </CommandItem>
                                ))}
                        </CommandGroup>
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    );
}

