export default async function FeatureSettingsPage({
    params,
    searchParams,
}: {
    params: Promise<{ guildId: string }>;
    searchParams: Promise<{ tab?: string }>;
}) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;
    const { tab } = await searchParams;
    const activeTab = tab || "absences";

    const user = await getUserContext(guildId);
    if (!user.canViewSettings) {
        await logAdminAccessDenied(guildId, "/admin/settings");
        return <AccessDenied />;
    }

    const onboardingRes = await getOnboardingSettings(guildId);
    const welcomeBadgeName = onboardingRes.success ? (onboardingRes.data as any).welcomeBadgeName : "Nouveau";

    const navItems = buildNavItems();
    const activeItem = navItems.find(n => n.id === activeTab) ?? navItems[0];
    const a = ACCENT[activeItem.accent] ?? ACCENT.slate;

    return (
        <div className="space-y-6 pb-12 w-full max-w-[1600px] mx-auto">
            <UnifiedModuleHeader
                title="Paramètres"
                description="Intégrations Discord, Metamob, Dofus et gestion des membres"
                icon={Settings}
                backHref={`/dashboard/${guildId}/admin`}
            />

            <div className="flex flex-col lg:flex-row gap-8 items-start relative">
                {/* ── SIDEBAR NAVIGATION ── */}
                <nav className={cn(
                    "w-full lg:w-72 shrink-0 lg:sticky lg:top-4 z-20 space-y-1 lg:space-y-1.5 p-2 rounded-2xl border border-white/8 bg-zinc-900/40 backdrop-blur-xl",
                    "flex lg:flex-col items-center lg:items-stretch overflow-x-auto lg:overflow-visible no-scrollbar hide-scrollbar"
                )}>
                    {/* Shadow indicators for mobile horizontal scroll (Standard 2026) */}
                    <div className="absolute right-0 top-0 bottom-0 w-8 bg-gradient-to-l from-zinc-950/50 to-transparent pointer-events-none lg:hidden z-30" />
                    
                    {navItems.map((item) => {
                        const isActive = item.id === activeTab;
                        const ac = ACCENT[item.accent] ?? ACCENT.slate;
                        const Icon = item.icon;
                        return (
                            <Link
                                key={item.id}
                                href={`/dashboard/${guildId}/admin/settings?tab=${item.id}`}
                                className={cn(
                                    "group flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 whitespace-nowrap lg:whitespace-normal",
                                    isActive
                                        ? `${ac.bg} ${ac.border} border shadow-[0_0_20px_rgba(0,0,0,0.2)]`
                                        : "border border-transparent hover:bg-white/[0.03] hover:border-white/8 text-zinc-400 hover:text-white"
                                )}
                            >
                                <div className={cn(
                                    "w-8 h-8 rounded-lg flex items-center justify-center shrink-0 transition-all duration-500",
                                    isActive ? ac.bg : "bg-white/5 group-hover:bg-white/10 group-hover:scale-110"
                                )}>
                                    <Icon className={cn("w-4 h-4", isActive ? ac.text : "text-zinc-500 group-hover:text-zinc-200")} />
                                </div>
                                <div className="min-w-0 flex-1 hidden lg:block">
                                    <p className={cn("text-xs font-black uppercase tracking-widest leading-none mb-1", isActive ? ac.text : "text-zinc-400 group-hover:text-white")}>
                                        {item.label}
                                    </p>
                                    <p className="text-[10px] text-zinc-500 truncate font-medium group-hover:text-zinc-400 transition-colors">
                                        {item.description}
                                    </p>
                                </div>
                                {/* Mobile display: only label */}
                                <span className={cn("text-xs font-black uppercase tracking-widest lg:hidden", isActive ? ac.text : "")}>
                                    {item.label}
                                </span>
                                {isActive && <ChevronRight className={cn("w-4 h-4 shrink-0 hidden lg:block", ac.text)} />}
                            </Link>
                        );
                    })}
                </nav>

                {/* ── CONTENT AREA ── */}
                <div className="flex-1 w-full min-w-0 animate-in fade-in slide-in-from-bottom-4 duration-700 delay-150">
                    {/* Section visual header */}
                    <div className={cn(
                        "relative flex flex-col sm:flex-row sm:items-center gap-5 mb-8 p-6 rounded-3xl border overflow-hidden",
                        a.border, a.bg
                    )}>
                        <div className={cn(
                            "relative w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 border shadow-2xl transition-transform duration-500 hover:scale-105",
                            a.bg, a.border
                        )}>
                            {(() => { const Icon = activeItem.icon; return <Icon className={cn("w-7 h-7", a.text)} />; })()}
                            <div className={cn("absolute inset-0 blur-xl opacity-20", a.bg)} />
                        </div>
                        <div className="space-y-1">
                            <div className={cn("inline-flex items-center px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] mb-1 share-glass-strong", a.pill)}>
                                Section Configuration
                            </div>
                            <h2 className={cn("text-2xl font-black tracking-tighter uppercase leading-none", a.text)}>
                                {activeItem.label}
                            </h2>
                            <p className="text-sm text-zinc-500 font-medium max-w-xl opacity-80">
                                {activeItem.description} — Gérez les paramètres de ce module pour votre guilde.
                            </p>
                        </div>
                        
                        {/* Decorative background glow */}
                        <div className={cn("absolute -top-10 -right-10 w-40 h-40 blur-[100px] opacity-10 pointer-events-none", a.bg)} />
                    </div>

                    {/* Content pane */}
                    {activeTab === "annonces" && <SystemSettingsClient guildId={guildId} />}
                    {activeTab === "absences" && <AbsenceSettingsClient guildId={guildId} />}
                    {activeTab === "songes" && <SongesSettingsClient guildId={guildId} />}
                    {activeTab === "calendrier" && <CalendarSettingsClient guildId={guildId} />}
                    {activeTab === "donjons" && <DjSettingsClient guildId={guildId} />}
                    {activeTab === "missions" && <MissionSettingsClient guildId={guildId} />}
                    {activeTab === "bonus" && <BonusSettingsClient guildId={guildId} />}
                    {activeTab === "prets" && <LoansSettingsClient guildId={guildId} />}
                    {activeTab === "metamob" && (
                        <div className="space-y-8">
                            <OcreSettingsClient guildId={guildId} />
                            <div className="pt-6 border-t border-white/5 max-w-4xl">
                                <h3 className="text-base font-bold text-white mb-1 flex items-center gap-2">
                                    <ShieldAlert className="w-4 h-4 text-amber-400" />
                                    Zone de Maintenance
                                </h3>
                                <p className="text-sm text-zinc-500 mb-4">Outils de dépannage pour les cas particuliers.</p>
                                <MetamobUnlocker guildId={guildId} />
                            </div>
                        </div>
                    )}
                    {activeTab === "dofus" && <DofusSettingsClient guildId={guildId} />}
                    {activeTab === "sondages" && <PollSettingsClient guildId={guildId} />}
                    {activeTab === "onboarding" && <OnboardingSettingsClient guildId={guildId} />}
                    { activeTab === "discord" && <DiscordSettingsClient guildId={guildId} /> }
                    { activeTab === "guildaton" && <GuildatonSettingsClient guildId={guildId} /> }
                    { activeTab === "blacklist" && <BlacklistSettingsClient guildId={guildId} /> }
                    { activeTab === "gallery" && <GallerySettingsClient guildId={guildId} /> }


                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, AlertTriangle, Hash, ArrowLeft, Moon } from "lucide-react";
import { toast } from "sonner";
import Link from "next/link";
import { getSongesConfig, updateSongesChannel } from "@/server/actions/admin-actions";

interface SongesSettingsClientProps {
    guildId: string;
}

export function SongesSettingsClient({ guildId }: SongesSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);

    useEffect(() => {
        async function loadConfig() {
            const result = await getSongesConfig(guildId);
            if (result.success && result.data) {
                setChannelId(result.data.songesChannelId || "");
                setIsConfigured(!!result.data.songesChannelId);
            }
            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSave = () => {
        startTransition(async () => {
            const result = await updateSongesChannel(guildId, channelId.trim() || null);
            if (result.success) {
                toast.success("Configuration sauvegardée !");
                setIsConfigured(!!channelId.trim());
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    const handleClear = () => {
        startTransition(async () => {
            const result = await updateSongesChannel(guildId, null);
            if (result.success) {
                setChannelId("");
                setIsConfigured(false);
                toast.success("Notifications Songes désactivées");
            } else {
                toast.error(result.error || "Erreur lors de la désactivation");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="space-y-8">

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Configuration Panel */}
                <Card className="lg:col-span-2 bg-zinc-900/60 border-white/5">
                    <CardHeader>
                        <div className="flex items-center justify-between">
                            <CardTitle className="flex items-center gap-2">
                                <span className="bg-purple-500/20 text-purple-400 p-2 rounded-lg">
                                    <Hash className="w-5 h-5" />
                                </span>
                                Salon Discord
                            </CardTitle>
                            {isConfigured ? (
                                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 hover:bg-emerald-500/20">
                                    Actif
                                </Badge>
                            ) : (
                                <Badge variant="outline" className="text-zinc-500">
                                    Inactif
                                </Badge>
                            )}
                        </div>
                        <CardDescription>
                            Les leaders seront notifiés ici quand un joueur postule à leur run Songes.
                        </CardDescription>
                    </CardHeader>

                    <CardContent className="space-y-6">
                        {/* Step 1 */}
                        <div className="relative pl-6 border-l-2 border-white/5 pb-6 last:pb-0">
                            <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-zinc-800 border-2 border-zinc-950 flex items-center justify-center">
                                <div className="w-1.5 h-1.5 rounded-full bg-zinc-400" />
                            </div>
                            <h3 className="text-sm font-medium text-white mb-2">1. Récupérer l'ID du salon</h3>
                            <p className="text-xs text-zinc-500 mb-3">
                                Activez le mode développeur Discord, puis faites <span className="text-zinc-300">Clic Droit</span> sur le salon voulu {'>'} <span className="text-zinc-300">Copier l'identifiant</span>.
                            </p>
                        </div>

                        {/* Step 2 */}
                        <div className="relative pl-6 border-l-2 border-purple-500/50">
                            <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-purple-500 border-2 border-zinc-950 shadow-[0_0_10px_rgba(168,85,247,0.5)]" />
                            <h3 className="text-sm font-medium text-white mb-4">2. Coller l'identifiant</h3>

                            <div className="space-y-4">
                                <div className="flex gap-2">
                                    <Input
                                        value={channelId}
                                        onChange={(e) => setChannelId(e.target.value)}
                                        placeholder="Ex: 123456789012345678"
                                        className="font-mono bg-black/20 border-white/10"
                                    />
                                    <Button onClick={handleSave} disabled={isPending} className="min-w-[120px] bg-purple-600 hover:bg-purple-500">
                                        {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                        Sauvegarder
                                    </Button>
                                </div>
                                {isConfigured && (
                                    <div className="flex justify-end">
                                        <Button variant="ghost" size="sm" onClick={handleClear} disabled={isPending} className="text-red-400 hover:text-red-300 hover:bg-red-900/20 h-auto py-1 px-3 text-xs">
                                            Désactiver l'intégration
                                        </Button>
                                    </div>
                                )}
                            </div>
                        </div>
                    </CardContent>
                </Card>

                {/* Preview Panel */}
                <div className="space-y-6">
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden">
                        <CardHeader className="bg-white/5 pb-4">
                            <CardTitle className="text-sm text-zinc-300">Aperçu du message</CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 relative">
                            {/* Discord Message Mockup */}
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 rounded-full bg-purple-500 flex items-center justify-center shrink-0">
                                    <Moon className="w-5 h-5 text-white" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-baseline gap-2 mb-1">
                                        <span className="font-medium text-purple-400">SigilOS</span>
                                        <span className="bg-purple-500/20 text-purple-300 text-[10px] px-1 rounded">BOT</span>
                                        <span className="text-xs text-zinc-500">Maintenant</span>
                                    </div>

                                    {/* Embed */}
                                    <div className="bg-[#2b2d31] rounded border-l-4 border-purple-400 p-4 max-w-sm">
                                        <div className="flex items-center gap-2 mb-2">
                                            <span className="text-lg">🌙</span>
                                            <h4 className="font-semibold text-white text-sm">Nouvelle candidature</h4>
                                        </div>

                                        <p className="text-zinc-300 text-sm mb-4">
                                            <span className="text-purple-400 font-medium hover:underline cursor-pointer">Wylan</span> veut rejoindre votre run <span className="text-amber-400">Rêve III</span>.
                                        </p>

                                        <div className="flex gap-6">
                                            <div>
                                                <div className="text-[#b5bac1] text-xs font-bold uppercase tracking-wider mb-1">Classe</div>
                                                <div className="text-zinc-200 text-sm">Cra</div>
                                            </div>
                                            <div>
                                                <div className="text-[#b5bac1] text-xs font-bold uppercase tracking-wider mb-1">Message</div>
                                                <div className="text-zinc-200 text-sm">Opti dispo 21h</div>
                                            </div>
                                        </div>

                                        <div className="mt-3 pt-3 border-t border-[#3f4147] flex items-center gap-2">
                                            <div className="w-4 h-4 rounded-full bg-zinc-700" />
                                            <span className="text-[#949ba4] text-xs">SigilOS • Songes Infinis</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    <Card className="bg-blue-500/5 border-blue-500/10">
                        <CardContent className="p-4 flex gap-3">
                            <div className="p-2 bg-blue-500/20 rounded-lg shrink-0 h-fit">
                                <AlertTriangle className="w-4 h-4 text-blue-400" />
                            </div>
                            <div className="space-y-1">
                                <h4 className="text-sm font-medium text-blue-200">Permissions requises</h4>
                                <p className="text-xs text-blue-300/70 leading-relaxed">
                                    Le bot <strong>SigilOS</strong> doit avoir les droits "Voir le salon" et "Envoyer des messages".
                                </p>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { getUserContext } from "@/server/actions/user-actions";
import AccessDenied from "@/components/access-denied";
import { SongesSettingsClient } from "./_components/songes-settings-client";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { Moon } from "lucide-react";

export default async function SongesAdminPage({ params }: { params: Promise<{ guildId: string }> }) {
    const session = await auth();
    if (!session?.user) redirect("/");
    const { guildId } = await params;

    const user = await getUserContext(guildId);
    if (!user.isAdmin) return <AccessDenied />;

    return (
        <div className="space-y-6 pb-12">
            <UnifiedModuleHeader
                title="Notifications Songes"
                description="Configurez les notifications Discord pour les nouveaux étages de Songes."
                imageSrc="/assets/ui/icons/songes.png"
                backHref={`/dashboard/${guildId}/admin/settings`}
            />
            <SongesSettingsClient guildId={guildId} />
        </div>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { getUserContext } from "@/server/actions/user-actions";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import Link from "next/link";
import { 
    Users, 
    Sparkles, 
    BookOpen, 
    Hammer, 
    ArrowRight, 
    Info,
    FileText,
    Library
} from "lucide-react";
import { cn } from "@/lib/utils";

type HubCard = {
    href: string;
    icon: any;
    title: string;
    description: string;
    accent: "emerald" | "amber" | "indigo" | "violet" | "rose" | "cyan" | "slate";
