            accent: "cyan",
            visible: !!(user.isMember && user.canViewDocs),
        },
        {
            href: `/dashboard/${guildId}/members`,
            icon: Users,
            title: "Annuaire des Membres",
            description: "Liste complète des membres, leurs métiers et leur date d'arrivée.",
            accent: "violet",
            visible: !!(user.isMember && user.canViewRoster),
        }
    ];

    return (
        <div className="space-y-16 pb-32 max-w-[1600px] mx-auto pt-10 px-6">
            <UnifiedModuleHeader
                title="Annuaire & Information"
                description="Centre de connaissances de la guilde • Tout ce qu'il faut savoir pour bien s'intégrer."
                icon={Info}
                iconColor="#10b981"
                backHref={`/dashboard/${guildId}`}
            />

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
                {cards.map((card) => {
                    const Icon = card.icon;
                    const a = ACCENT[card.accent];
                    
                    if (!card.visible) return null;

                    return (
                        <Link key={card.href} href={card.href} className="group outline-none">
                            <div className={cn(
                                "relative flex flex-col h-full rounded-[2.5rem] border border-border bg-foreground/[0.02] p-8 transition-all duration-700 hover:border-border hover:bg-foreground/[0.04] hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.1)] overflow-hidden",
                                "before:absolute before:inset-0 before:bg-gradient-to-br before:from-foreground/[0.05] before:to-transparent before:opacity-0 group-hover:before:opacity-100 before:transition-opacity before:duration-700"
                            )}>
                                <div className={cn(
                                    "absolute -top-24 -right-24 w-48 h-48 blur-[100px] opacity-0 group-hover:opacity-20 transition-opacity duration-700 rounded-full z-0",
                                    a.bg
                                )} />

                                <div className="relative z-10 flex flex-col h-full">
                                    <div className="flex items-center justify-between mb-8">
                                        <div className={cn(
                                            "w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 border group-hover:scale-110 group-hover:rotate-3 shadow-xl",
                                            a.bg,
                                            a.border.replace("hover:", "")
                                        )}>
                                            <Icon className={cn("w-7 h-7", a.text)} strokeWidth={1.5} />
                                        </div>
                                    </div>

                                    <div className="space-y-4 flex-1">
                                        <h3 className="text-xl font-black text-foreground tracking-tighter uppercase leading-tight">
                                            {card.title}
                                        </h3>
                                        <p className="text-[13px] text-muted-foreground font-black leading-relaxed group-hover:text-foreground transition-colors italic">
                                            {card.description}
                                        </p>
                                    </div>

                                    <div className="mt-8 pt-6 border-t border-border flex items-center justify-between">
                                        <div className={cn(
                                            "flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] transition-all",
                                            a.text,
                                            "opacity-40 group-hover:opacity-100"
                                        )}>
                                            <span className="group-hover:translate-x-1 transition-transform">Consulter</span>
                                            <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-1.5 transition-transform" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </Link>
                    );
                })}
            </div>
        </div>
    );
}

import { redirect } from "next/navigation";
import { auth } from "@/auth";
import { getUserContext } from "@/server/actions/user-actions";
import { CalendarDashboard } from "@/components/calendar/calendar-dashboard";
import { Calendar as CalendarIcon } from "lucide-react";
import Link from "next/link";
import AccessDenied from "@/components/access-denied";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { isModuleEnabled } from "@/server/actions/module-actions";

interface CalendarPageProps {
    params: Promise<{ guildId: string }>;
}

export default async function CalendarPage({ params }: CalendarPageProps) {
    const { guildId } = await params;
    const session = await auth();

    if (!session?.user?.id) {
        redirect("/login");
    }

    // Module guard
    if (!await isModuleEnabled(guildId, "calendar")) {
        redirect(`/dashboard/${guildId}`);
    }

    const ctx = await getUserContext(guildId);

    // Check view permission
    if (!ctx.canViewCalendar) {
        return <AccessDenied />;
    }

    const canManage = ctx.canManageCalendar;

    // Fetch Discord Config for the guild
    const { db } = await import("@/lib/prisma");
    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { calendarNotifyChannelId: true }
    });
    const isDiscordConfigured = !!guildConfig?.calendarNotifyChannelId;

    return (
        <div className="flex flex-col h-full bg-foreground/[0.02] pb-12">
            <main className="flex-1 overflow-auto">
                <div className="max-w-[1600px] mx-auto space-y-8">
                    <UnifiedModuleHeader
                        title="Calendrier des Événements"
                        description="Ne manquez aucun rendez-vous important de la vie de guilde."
                        imageSrc="/assets/ui/icons/calendar.png"
                        backHref={`/dashboard/${guildId}`}
                    />

                    {/* Main Dashboard */}
                    <CalendarDashboard
                        guildId={guildId}
                        currentUserId={session.user.id}
                        canManage={canManage}
                        isDiscordConfigured={isDiscordConfigured}
                    />
                </div>
            </main>
        </div>
    );
}

"use client";

import { useState, useCallback, useEffect } from "react";
import { Link2, Search, ShieldCheck, ExternalLink, ChevronDown, Loader2, RefreshCw, ChevronRight, Copy, Star, Sword, Sparkles, Info, Mars, Venus, Megaphone, Send } from "lucide-react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { DofusbookPreview } from "@/components/dofus/dofusbook-preview";
import { DO_TAGS } from "@/lib/dofus-tags";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { getStuffGalleryPage, getSkinGalleryPage, refreshBuildMetadata, toggleSkinVote, type GalleryBuild, type GallerySkin } from "@/server/actions/gallery-actions";
import { toggleBuildVote } from "@/server/actions/vote-actions";
import { useDebounce } from "@/hooks/use-debounce";
import { toast } from "sonner";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import NextImage from "next/image";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { shareGalleryItemOnDiscord } from "@/server/actions/gallery-actions";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { ClassFilter, GenderFilter, AdvancedTagFilter, getNumericClassId } from "@/components/gallery/gallery-filters";

const ADVANCED_TAG_IDS = ["tank","soin","pp","dopou","docrit","ini","retpa","retpm","terrefeu","terreeau","terreair","feueau","feuair","eauair","multinocrit","sagesse","leveling","songes"];

interface GalleryClientProps {
    initialBuilds: GalleryBuild[];
    initialTotal: number;
    initialHasMore: boolean;
    initialStuffShareConfigured: boolean;
    initialSkinTotal: number;
    guildId: string;
    currentProfileId?: string;
}

export function GalleryClient({ 
    initialBuilds, 
    initialTotal, 
    initialHasMore, 
    initialStuffShareConfigured,
    initialSkinTotal,
    guildId,
    currentProfileId
}: GalleryClientProps) {
    // Current Gallery State
    const [activeTab, setActiveTab] = useState<"STUFF" | "SKIN">("STUFF");
    
    // Stuff Tab State
    const [stuffBuilds, setStuffBuilds] = useState<GalleryBuild[]>(initialBuilds);
    const [stuffTotal, setStuffTotal] = useState(initialTotal);
    const [stuffHasMore, setStuffHasMore] = useState(initialHasMore);
    const [stuffShareConfigured, setStuffShareConfigured] = useState(initialStuffShareConfigured);
    const [stuffPage, setStuffPage] = useState(1);
    
    // Skin Tab State
    const [skinBuilds, setSkinBuilds] = useState<GallerySkin[]>([]);
    const [skinTotal, setSkinTotal] = useState(initialSkinTotal);
    const [skinHasMore, setSkinHasMore] = useState(false);
    const [skinShareConfigured, setSkinShareConfigured] = useState(false);
    const [skinPage, setSkinPage] = useState(1);
    
    // Global Filter State
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedTag, setSelectedTag] = useState<string | null>(null);
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [selectedGender, setSelectedGender] = useState<string | null>(null);
    const [sortBy, setSortBy] = useState<"newest" | "votes">("newest");
    
    const [refreshingIds, setRefreshingIds] = useState<Set<string>>(new Set());
    const [votingIds, setVotingIds] = useState<Set<string>>(new Set());
    const [sharingIds, setSharingIds] = useState<Set<string>>(new Set());
    const [isLoading, setIsLoading] = useState(false);
    const [selectedSkin, setSelectedSkin] = useState<GallerySkin | null>(null);

    // Debounced search - triggers server-side re-fetch after 300ms
    const debouncedSearch = useDebounce(searchQuery, 300);

    // Reset and re-fetch from page 1 when filters change
    const applyFilters = useCallback((query: string, tag: string | null, classId: string | null, gender: string | null, sortKey: "newest" | "votes", tab: "STUFF" | "SKIN") => {
        const runFilters = async () => {
            setIsLoading(true);
            try {
                if (tab === "STUFF") {
                    const res = await getStuffGalleryPage(guildId, 1, query || undefined, tag || undefined, classId || undefined, sortKey);
                    if (res.success && res.data) {
                        setStuffBuilds(res.data.builds);
                        setStuffTotal(res.data.total);
                        setStuffHasMore(res.data.hasMore);
                        setStuffShareConfigured(res.data.isDiscordShareConfigured);
                        setStuffPage(1);
                    }
                } else {
                    const res = await getSkinGalleryPage(guildId, 1, query || undefined, classId || undefined, gender || undefined, sortKey);
                    if (res.success && res.data) {
                        setSkinBuilds(res.data.skins);
                        setSkinTotal(res.data.total);
                        setSkinHasMore(res.data.hasMore);
                        setSkinShareConfigured(res.data.isDiscordShareConfigured);
                        setSkinPage(1);
                    }
                }
            } finally {
                setIsLoading(false);
            }
        };
        runFilters();
    }, [guildId]);

    const handleSearchChange = (value: string) => {
        setSearchQuery(value);
    };

    // Use debounced search to trigger filtering
    useEffect(() => {
        if (debouncedSearch !== undefined) {
            applyFilters(debouncedSearch, selectedTag, selectedClass, selectedGender, sortBy, activeTab);
        }
    }, [debouncedSearch, selectedTag, selectedClass, selectedGender, sortBy, activeTab, applyFilters]);

    const handleTagChange = (tag: string | null) => {
        setSelectedTag(tag);
        applyFilters(searchQuery, tag, selectedClass, selectedGender, sortBy, activeTab);
    };

    const handleClassChange = (classId: string | number | null) => {
        const idStr = classId !== null ? String(classId) : null;
        setSelectedClass(idStr);
        applyFilters(searchQuery, selectedTag, idStr, selectedGender, sortBy, activeTab);
    };

    const handleGenderChange = (gender: string | null) => {
        setSelectedGender(gender);
        applyFilters(searchQuery, selectedTag, selectedClass, gender, sortBy, activeTab);
    };
    
    const handleSortChange = (newSort: "newest" | "votes") => {
        setSortBy(newSort);
        applyFilters(searchQuery, selectedTag, selectedClass, selectedGender, newSort, activeTab);
    };

    const handleTabChange = (newTab: "STUFF" | "SKIN") => {
        setActiveTab(newTab);
        // Reseting filters when changing tab to avoid confusing state
        setSelectedTag(null);
        setSelectedClass(null);
        setSelectedGender(null);
        applyFilters(searchQuery, null, null, null, sortBy, newTab);
    };

    // Infinite scroll: load next page
    const loadMore = () => {
        const runLoadMore = async () => {
            setIsLoading(true);
            try {
                if (activeTab === "STUFF") {
                    const nextPage = stuffPage + 1;
                    const res = await getStuffGalleryPage(
                        guildId, 
                        nextPage, 
                        searchQuery || undefined, 
                        selectedTag || undefined,
                        selectedClass || undefined,
                        sortBy
                    );
                    if (res.success && res.data) {
                        setStuffBuilds(prev => [...prev, ...res.data!.builds]);
                        setStuffHasMore(res.data.hasMore);
                        setStuffPage(nextPage);
                    }
                } else {
                    const nextPage = skinPage + 1;
                    const res = await getSkinGalleryPage(
                        guildId,
                        nextPage,
                        searchQuery || undefined,
                        selectedClass || undefined,
                        selectedGender || undefined,
                        sortBy
                    );
                    if (res.success && res.data) {
                        setSkinBuilds(prev => [...prev, ...res.data!.skins]);
                        setSkinHasMore(res.data.hasMore);
                        setSkinPage(nextPage);
                    }
                }
            } finally {
                setIsLoading(false);
            }
        };
        runLoadMore();
    };

    const handleRefresh = async (build: GalleryBuild) => {
        if (refreshingIds.has(build.id)) return;
        
        setRefreshingIds(prev => new Set(prev).add(build.id));
        toast.info(`Rafraîchissement de "${build.name}"...`);

        try {
            const res = await refreshBuildMetadata(guildId, build.author.id, build.url);
            if (res.success) {
                toast.success("Build mis à jour !");
                applyFilters(searchQuery, selectedTag, selectedClass, selectedGender, sortBy, activeTab);
            } else {
                toast.error(res.error || "Échec du rafraîchissement");
            }
        } catch (e) {
            toast.error("Erreur serveur");
        } finally {
            setRefreshingIds(prev => {
                const next = new Set(prev);
                next.delete(build.id);
                return next;
            });
        }
    };

    const handleVoteStuff = async (build: GalleryBuild) => {
        if (votingIds.has(build.id)) return;
        setVotingIds(prev => new Set(prev).add(build.id));

        const originalVoted = build.hasVoted;
        const offset = originalVoted ? -1 : 1;
        
        setStuffBuilds(current => current.map(b =>
            b.id === build.id
                ? { ...b, hasVoted: !originalVoted, votesCount: Math.max(0, b.votesCount + offset) }
                : b
        ));

        try {
            const res = await toggleBuildVote(guildId, build.id);
            if (!res.success) throw new Error(res.error);
        } catch (error) {
            setStuffBuilds(current => current.map(b =>
                b.id === build.id
                    ? { ...b, hasVoted: originalVoted, votesCount: build.votesCount }
                    : b
            ));
            toast.error("Erreur lors du vote");
        } finally {
            setVotingIds(prev => {
                const next = new Set(prev);
                next.delete(build.id);
                return next;
            });
        }
    };

    const handleVoteSkin = async (skin: GallerySkin) => {
        if (votingIds.has(skin.id)) return;
        setVotingIds(prev => new Set(prev).add(skin.id));

        const originalVoted = skin.hasVoted;
        const offset = originalVoted ? -1 : 1;
        
        setSkinBuilds(current => current.map(s =>
            s.id === skin.id
                ? { ...s, hasVoted: !originalVoted, votesCount: Math.max(0, s.votesCount + offset) }
                : s
        ));

        try {
            const res = await toggleSkinVote(guildId, skin.id);
            if (!res.success) throw new Error(res.error);
        } catch (error: any) {
            setSkinBuilds(current => current.map(s =>
                s.id === skin.id
                    ? { ...s, hasVoted: originalVoted, votesCount: skin.votesCount }
                    : s
            ));
            toast.error(error.message || "Erreur lors du vote");
        } finally {
            setVotingIds(prev => {
                const next = new Set(prev);
                next.delete(skin.id);
                return next;
            });
        }
    };

    const handleShare = async (id: string, type: "STUFF" | "SKIN", authorId?: string) => {
        if (sharingIds.has(id)) return;
        setSharingIds(prev => new Set(prev).add(id));
        
        try {
            const res = await shareGalleryItemOnDiscord(guildId, id, type, authorId);
            if (res.success) {
                toast.success("Partagé sur Discord ! 🚀");
            } else {
                toast.error(res.error || "Erreur lors du partage");
            }
        } catch (e) {
            toast.error("Erreur serveur lors du partage");
        } finally {
            setSharingIds(prev => {
                const next = new Set(prev);
                next.delete(id);
                return next;
            });
        }
    };

    const handleCopyLink = (url: string) => {
        navigator.clipboard.writeText(url);
        toast.success("Lien copié dans le presse-papier ! 📋");
    };

    return (
        <div className="space-y-6 pb-20">
            {/* Hero Header */}
            <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-zinc-900/40 backdrop-blur-xl p-8 lg:p-10">
                <div className={cn(
                    "absolute top-0 right-0 w-96 h-96 blur-[120px] rounded-full -mr-20 -mt-20 shrink-0 transition-colors duration-500",
                    activeTab === "STUFF" ? "bg-emerald-500/10" : "bg-sky-500/10"
                )} />
                <div className={cn(
                    "absolute bottom-0 left-0 w-64 h-64 blur-[100px] rounded-full -ml-20 -mb-20 shrink-0 transition-colors duration-500",
                    activeTab === "STUFF" ? "bg-indigo-500/10" : "bg-purple-500/10"
                )} />

                <div className="relative z-10 flex flex-col lg:flex-row lg:items-center justify-between gap-8">
                    <div className="space-y-4">
                        <div className="flex flex-col sm:flex-row sm:items-center gap-6">
                            <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/5 border border-white/10 text-white/50 text-[10px] font-black uppercase tracking-widest shrink-0 w-fit">
                                <ShieldCheck className="w-3.5 h-3.5 text-zinc-500" />
                                Galerie de Guilde 2026
                            </div>
                            
                            <Tabs value={activeTab} onValueChange={(v) => handleTabChange(v as any)} className="w-full sm:w-auto">
                                <TabsList className="bg-black/60 border border-white/10 h-14 p-1.5 rounded-2xl shadow-2xl">
                                    <TabsTrigger 
                                        value="STUFF" 
                                        className="rounded-xl px-6 h-full text-[12px] font-black uppercase tracking-widest gap-3 data-[state=active]:bg-emerald-500 data-[state=active]:text-white transition-all duration-300"
                                    >
                                        <Sword className={cn("w-4 h-4 transition-transform", activeTab === "STUFF" ? "scale-110" : "opacity-40")} />
                                        ÉQUIPEMENTS
                                        <span className={cn(
                                            "ml-1 px-1.5 py-0.5 rounded-md text-[9px] font-black",
                                            activeTab === "STUFF" ? "bg-white/20 text-white" : "bg-white/5 text-zinc-600"
                                        )}>
                                            {stuffTotal}
                                        </span>
                                    </TabsTrigger>
                                    <TabsTrigger 
                                        value="SKIN" 
                                        className="rounded-xl px-6 h-full text-[12px] font-black uppercase tracking-widest gap-3 data-[state=active]:bg-sky-500 data-[state=active]:text-white transition-all duration-300"
                                    >
                                        <Sparkles className={cn("w-4 h-4 transition-transform", activeTab === "SKIN" ? "scale-110" : "opacity-40")} />
                                        SKINS & LOOKS
                                        <span className={cn(
                                            "ml-1 px-1.5 py-0.5 rounded-md text-[9px] font-black",
                                            activeTab === "SKIN" ? "bg-white/20 text-white" : "bg-white/5 text-zinc-600"
                                        )}>
                                            {skinTotal}
                                        </span>
                                    </TabsTrigger>
                                </TabsList>
                            </Tabs>
                        </div>

                        <div>
                            <h1 className="text-4xl lg:text-5xl font-black text-white tracking-tight mb-2">
                                Galerie <span className={cn(
                                    "text-transparent bg-clip-text bg-gradient-to-r transition-all duration-500",
                                    activeTab === "STUFF" ? "from-emerald-400 to-indigo-400" : "from-sky-400 to-purple-400"
                                )}>Guilde</span>
                            </h1>
                            <p className="text-zinc-400 max-w-xl text-base leading-relaxed">
                                {activeTab === "STUFF" 
                                    ? "Découvrez les meilleurs builds optis partagés par les membres de la guilde."
                                    : "L'élégance à l'état pur. Explorez les plus beaux looks et skins de la communauté."}
                            </p>
                        </div>
                    </div>

                    {/* Search bar */}
                    <div className="relative group w-full lg:w-96">
                        <Search className={cn(
                            "absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 transition-colors",
                            activeTab === "STUFF" ? "group-focus-within:text-emerald-400" : "group-focus-within:text-sky-400"
                        )} />
                        <Input
                            placeholder={activeTab === "STUFF" ? "Rechercher un build, un pseudo..." : "Rechercher un skin, un auteur..."}
                            value={searchQuery}
                            onChange={(e) => handleSearchChange(e.target.value)}
                            className="bg-zinc-950/80 border-white/10 pl-11 h-14 rounded-2xl focus:ring-emerald-500/20 focus:border-emerald-500/50 transition-all text-sm text-white placeholder:text-zinc-600 shadow-2xl"
                        />
                        {isLoading && (
                            <Loader2 className={cn(
                                "absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin",
                                activeTab === "STUFF" ? "text-emerald-500" : "text-sky-500"
                            )} />
                        )}
                    </div>
                </div>
            </div>

            {/* Premium Filter Bar */}
            <div className="sticky top-0 z-30 pt-2">
                <div className="bg-zinc-950/80 backdrop-blur-2xl border border-white/10 rounded-[1.5rem] px-5 py-4 shadow-2xl flex flex-col xl:flex-row xl:items-center justify-between gap-4">
                    {/* Left: Filters */}
                    <div className="flex items-center gap-3 flex-wrap">
                        {/* 1. Class Filter */}
                        <div className="flex items-center gap-2 bg-black/40 p-1 rounded-2xl border border-white/5">
                            <ClassFilter selectedClass={selectedClass} onSelectClass={handleClassChange} />
                        </div>

                        {activeTab === "SKIN" && (
                            <GenderFilter selectedGender={selectedGender} onSelectGender={handleGenderChange} />
                        )}

                        {activeTab === "STUFF" && (
                            <>
                                <div className="w-px h-6 bg-white/10 shrink-0 hidden sm:block" />

                                {/* 2. Primary Elements */}
                                <div className="flex items-center gap-1.5 bg-black/40 p-1 rounded-2xl border border-white/5">
                                    <button
                                        onClick={() => handleTagChange(null)}
                                        className={cn(
                                            "h-8 px-4 rounded-xl text-[11px] font-black transition-all shrink-0",
                                            !selectedTag || ADVANCED_TAG_IDS.includes(selectedTag) ? "bg-white text-black shadow-md" : "text-zinc-500 hover:text-white hover:bg-white/10"
                                        )}
                                    >
                                        Tous
                                    </button>

                                    {["eau","feu","terre","air","multi"].map(id => {
                                        const tag = DO_TAGS.find(t => t.id === id)!;
                                        return (
                                            <button
                                                key={id}
                                                onClick={() => handleTagChange(selectedTag === id ? null : id)}
                                                className={cn(
                                                    "h-8 px-3 rounded-xl text-[11px] font-bold transition-all shrink-0",
                                                    selectedTag === id ? `${tag.className} shadow-lg ring-1 ring-white/20` : "text-zinc-500 hover:text-white hover:bg-white/10"
                                                )}
                                            >
                                                {tag.text}
                                            </button>
                                        );
                                    })}
                                </div>

                                <div className="w-px h-6 bg-white/10 shrink-0 hidden sm:block" />

                                {/* 3. Advanced / Specialities */}
                                <div className="flex items-center bg-black/40 p-1 rounded-2xl border border-white/5">
                                    <AdvancedTagFilter selectedTag={selectedTag} onSelectTag={handleTagChange} />
                                </div>
                            </>
                        )}
                    </div>

                    {/* Right: Count & Reset & Sort */}
                    <div className="flex items-center gap-4 text-sm w-full xl:w-auto shrink-0 justify-between xl:justify-end border-t border-white/5 pt-4 xl:border-0 xl:pt-0 flex-wrap">
                        <div className="flex items-center gap-2 bg-black/40 p-1 rounded-2xl border border-white/5 mr-2">
                            <button
                                onClick={() => handleSortChange("newest")}
                                className={cn(
                                    "flex items-center gap-1.5 h-8 px-3 rounded-xl text-[11px] font-bold transition-all shrink-0",
                                    sortBy === "newest" ? "bg-white text-black shadow-md" : "text-zinc-500 hover:text-white hover:bg-white/10"
                                )}
                            >
                                <RefreshCw className="w-3.5 h-3.5" /> Récents
                            </button>
                            <button
                                onClick={() => handleSortChange("votes")}
                                className={cn(
                                    "flex items-center gap-1.5 h-8 px-3 rounded-xl text-[11px] font-bold transition-all shrink-0",
                                    sortBy === "votes" ? "bg-yellow-500 text-black shadow-md shadow-yellow-500/20" : "text-zinc-500 hover:text-yellow-400 hover:bg-white/10"
                                )}
                            >
                                <Star className={cn("w-3.5 h-3.5", sortBy === "votes" && "fill-black")} /> Favoris
                            </button>
                        </div>
                        
                        <div className="flex items-center gap-3">
                            <p className="text-[11px] text-zinc-500 flex items-center gap-2">
                                <span className={cn(
                                    "w-2 h-2 rounded-full animate-pulse shrink-0",
                                    activeTab === "STUFF" ? "bg-emerald-500/50" : "bg-sky-500/50"
                                )} />
                                <span className="text-white font-black">{activeTab === "STUFF" ? stuffBuilds.length : skinBuilds.length}</span>
                                <span> sur {activeTab === "STUFF" ? stuffTotal : skinTotal} item{ (activeTab === "STUFF" ? stuffTotal : skinTotal) !== 1 ? "s" : ""}</span>
                            </p>
                            {(searchQuery || selectedTag || selectedClass || selectedGender) ? (
                                <>
                                    <div className="w-px h-4 bg-white/10 shrink-0" />
                                    <button
                                        onClick={() => { setSearchQuery(""); setSelectedTag(null); setSelectedClass(null); setSelectedGender(null); applyFilters("", null, null, null, sortBy, activeTab); }}
                                        className="text-[10px] text-zinc-400 hover:text-white transition-colors font-bold uppercase tracking-widest flex items-center gap-1 shrink-0"
                                    >
                                        <RefreshCw className="w-3 h-3" /> Reset
                                    </button>
                                </>
                            ) : null}
                        </div>
                    </div>
                </div>
            </div>

            {/* Grid */}
            <div className={cn(
                "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8",
                isLoading && "opacity-50 pointer-events-none transition-opacity"
            )}>
                {activeTab === "STUFF" ? (
                    stuffBuilds.length > 0 ? (
                        stuffBuilds.map((build) => (
                            <div key={build.id} className="group/card flex flex-col gap-3">
                                <div className="relative">
                                    <DofusbookPreview url={build.url} title={build.name} tags={build.tags} classId={build.classId ? Number(build.classId) : undefined} initialData={build.previewData} />
                                    
                                    <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent transition-all duration-300 rounded-2xl flex flex-col justify-end p-4 z-10 pointer-events-none">
                                        <div className="flex items-center justify-end gap-2">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); handleRefresh(build); }}
                                                disabled={refreshingIds.has(build.id)}
                                                className="p-1.5 bg-zinc-800/90 rounded-lg text-white hover:bg-zinc-700 transition-colors shadow-lg pointer-events-auto disabled:opacity-50"
                                                title="Actualiser depuis Dofusbook"
                                            >
                                                <RefreshCw className={cn("w-3.5 h-3.5", refreshingIds.has(build.id) && "animate-spin")} />
                                            </button>
                                            <button
                                                onClick={(e) => { e.stopPropagation(); handleVoteStuff(build); }}
                                                disabled={votingIds.has(build.id)}
                                                className={cn(
                                                    "p-1.5 rounded-lg transition-colors shadow-lg pointer-events-auto disabled:opacity-50 flex items-center justify-center gap-1.5",
                                                    build.hasVoted 
                                                        ? "bg-yellow-500/20 text-yellow-400 border border-yellow-500/30 hover:bg-yellow-500/30" 
                                                        : "bg-zinc-800/90 text-zinc-400 hover:text-yellow-400 hover:bg-zinc-700"
                                                )}
                                                title={build.hasVoted ? "Retirer mon vote" : "Voter pour ce stuff !"}
                                            >
                                                <Star className={cn("w-3.5 h-3.5", build.hasVoted && "fill-current")} />
                                                {build.votesCount > 0 && (
                                                    <span className="text-[10px] font-bold">{build.votesCount}</span>
                                                )}
                                            </button>
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    navigator.clipboard.writeText(build.url);
                                                    toast.success("Lien copié !");
                                                }}
                                                className="p-1.5 bg-zinc-800/90 rounded-lg text-zinc-300 hover:text-white hover:bg-zinc-700 transition-colors shadow-lg pointer-events-auto"
                                            >
                                                <Copy className="w-3.5 h-3.5" />
                                            </button>
                                            {currentProfileId === build.author.id && (
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); handleShare(build.id, "STUFF", build.author.id); }}
                                                    disabled={sharingIds.has(build.id) || !stuffShareConfigured}
                                                    className={cn(
                                                        "p-1.5 rounded-lg transition-colors shadow-lg pointer-events-auto disabled:opacity-40 disabled:grayscale disabled:cursor-not-allowed",
                                                        "bg-indigo-500 text-white hover:bg-indigo-400"
                                                    )}
                                                    title={stuffShareConfigured ? "Propulser sur Discord !" : "Non configuré (Admin)"}
                                                >
                                                    {sharingIds.has(build.id) ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Megaphone className="w-3.5 h-3.5" />}
                                                </button>
                                            )}
                                            <a 
                                                href={build.url} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="p-1.5 bg-emerald-500 rounded-lg text-white hover:bg-emerald-400 transition-colors shadow-lg pointer-events-auto"
                                            >
                                                <ExternalLink className="w-3.5 h-3.5" />
                                            </a>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center justify-between px-2">
                                    <div className="flex items-center gap-2.5">
                                        <Avatar className="w-6 h-6 border border-white/10">
                                            <AvatarImage src={build.author.image || undefined} />
                                            <AvatarFallback className="text-[9px] bg-zinc-900 text-zinc-500">
                                                {build.author.name.substring(0, 2).toUpperCase()}
                                            </AvatarFallback>
                                        </Avatar>
                                        <span className="text-[11px] text-zinc-500">
                                            Par <span className="text-zinc-300 font-bold">{build.author.name}</span>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        ))
                    ) : !isLoading && (
                        <EmptyState guildId={guildId} tab="STUFF" searchQuery={searchQuery} onReset={() => handleTabChange("STUFF")} />
                    )
                ) : (
                    skinBuilds.length > 0 ? (
                        skinBuilds.map((skin) => (
                            <div key={skin.id} className="group/card flex flex-col gap-3">
                                <div 
                                    onClick={() => setSelectedSkin(skin)}
                                    className="relative aspect-[4/3] rounded-2xl overflow-hidden border border-white/10 bg-zinc-900 group-hover/card:border-sky-500/50 transition-all cursor-pointer"
                                >
                                    {skin.thumbnailUrl ? (
                                        <NextImage 
                                            src={skin.thumbnailUrl} 
                                            alt={skin.name} 
                                            fill 
                                            className="object-contain group-hover/card:scale-105 transition-transform duration-500 bg-zinc-950/30" 
                                        />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center bg-zinc-950">
                                            <NextImage src="/assets/dofus/logo-sigil.png" alt="Sigil" width={64} height={64} className="opacity-10 grayscale" />
                                        </div>
                                    )}

                                    <div className="absolute inset-0 bg-gradient-to-t from-black/95 via-black/20 to-transparent p-4 flex flex-col justify-end">
                                        <div className="flex items-center justify-between mb-2">
                                            <h3 className="text-sm font-black text-white truncate max-w-[150px]">{skin.name}</h3>
                                            <div className="flex items-center gap-1">
                                                <span className="text-[9px] px-1.5 py-0.5 rounded-md bg-white/10 text-white/60 font-black uppercase tracking-tighter">
                                                    {skin.provider}
                                                </span>
                                            </div>
                                        </div>

                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-1.5">
                                                {skin.metadata?.class && DOFUS_CLASSES.find(c => getNumericClassId(c) === Number(skin.metadata?.class))?.icon && (
                                                    <div className="w-6 h-6 rounded-lg bg-black/50 border border-white/10 flex items-center justify-center" title={DOFUS_CLASSES.find(c => getNumericClassId(c) === Number(skin.metadata?.class))?.name || skin.metadata.class}>
                                                        <NextImage 
                                                            src={DOFUS_CLASSES.find(c => getNumericClassId(c) === Number(skin.metadata?.class))?.icon || ""} 
                                                            alt="" width={14} height={14} 
                                                        />
                                                    </div>
                                                )}
                                                {skin.metadata?.gender && (
                                                    <div className="w-6 h-6 rounded-lg bg-black/50 border border-white/10 flex items-center justify-center">
                                                        {skin.metadata.gender === "M" ? <Mars className="w-3 h-3 text-blue-400" /> : <Venus className="w-3 h-3 text-pink-400" />}
                                                    </div>
                                                )}
                                            </div>

                                            <div className="flex items-center gap-2">
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); handleVoteSkin(skin); }}
                                                    disabled={votingIds.has(skin.id)}
                                                    className={cn(
                                                        "p-1.5 rounded-lg transition-colors shadow-lg disabled:opacity-50 flex items-center justify-center gap-1.5",
                                                        skin.hasVoted 
                                                            ? "bg-yellow-500 text-black" 
                                                            : "bg-zinc-800/90 text-zinc-400 hover:text-yellow-400 hover:bg-zinc-700"
                                                    )}
                                                >
                                                    <Star className={cn("w-3.5 h-3.5", skin.hasVoted && "fill-current")} />
                                                    {skin.votesCount > 0 && (
                                                        <span className="text-[10px] font-black">{skin.votesCount}</span>
                                                    )}
                                                </button>
                                                {currentProfileId === skin.author.id && (
                                                    <button
                                                        onClick={(e) => { e.stopPropagation(); handleShare(skin.id, "SKIN"); }}
                                                        disabled={sharingIds.has(skin.id) || !skinShareConfigured}
                                                        className={cn(
                                                            "p-1.5 rounded-lg transition-colors shadow-lg disabled:opacity-40 disabled:grayscale disabled:cursor-not-allowed",
                                                            "bg-indigo-500 text-white hover:bg-indigo-400"
                                                        )}
                                                        title={skinShareConfigured ? "Partager sur Discord" : "Non configuré (Admin)"}
                                                    >
                                                        {sharingIds.has(skin.id) ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Megaphone className="w-3.5 h-3.5" />}
                                                    </button>
                                                )}
                                                <a 
                                                    href={skin.url} 
                                                    target="_blank" 
                                                    rel="noopener noreferrer"
                                                    className="p-1.5 bg-sky-500 rounded-lg text-white hover:bg-sky-400 transition-colors shadow-lg"
                                                >
                                                    <ExternalLink className="w-3.5 h-3.5" />
                                                </a>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center justify-between px-2">
                                    <div className="flex items-center gap-2.5">
                                        <Avatar className="w-6 h-6 border border-white/10">
                                            <AvatarImage src={skin.author.image || undefined} />
                                            <AvatarFallback className="text-[9px] bg-zinc-900 text-zinc-500">
                                                {skin.author.name.substring(0, 2).toUpperCase()}
                                            </AvatarFallback>
                                        </Avatar>
                                        <span className="text-[11px] text-zinc-500">
                                            Par <span className="text-zinc-300 font-bold">{skin.author.name}</span>
                                        </span>
                                    </div>
                                    <span className="text-[9px] text-zinc-600 font-medium">
                                        {new Date(skin.createdAt).toLocaleDateString()}
                                    </span>
                                </div>
                            </div>
                        ))
                    ) : !isLoading && (
                        <EmptyState guildId={guildId} tab="SKIN" searchQuery={searchQuery} onReset={() => handleTabChange("SKIN")} />
                    )
                )}
            </div>

            {/* Load More button */}
            {((activeTab === "STUFF" && stuffHasMore) || (activeTab === "SKIN" && skinHasMore)) && !isLoading && (
                <div className="flex justify-center mt-12">
                    <Button
                        onClick={loadMore}
                        variant="outline"
                        className={cn(
                            "gap-2 border-white/10 hover:bg-white/5 transition-all px-12 h-12 rounded-2xl font-black text-xs uppercase tracking-widest",
                            activeTab === "STUFF" ? "hover:border-emerald-500/30 hover:text-emerald-400" : "hover:border-sky-500/30 hover:text-sky-400"
                        )}
                    >
                        <ChevronDown className="w-4 h-4" />
                        Charger plus {activeTab === "STUFF" ? "de builds" : "de skins"}
                        <span className="text-[10px] text-zinc-500 ml-1">
                            ({(activeTab === "STUFF" ? stuffTotal - stuffBuilds.length : skinTotal - skinBuilds.length)} restants)
                        </span>
                    </Button>
                </div>
            )}

            {/* Skin Detail Modal */}
            <Dialog open={!!selectedSkin} onOpenChange={(open) => !open && setSelectedSkin(null)}>
                <DialogContent className="bg-zinc-950/95 backdrop-blur-2xl border-white/10 text-white sm:max-w-xl w-[95vw] h-auto max-h-[90vh] p-0 rounded-[2rem] overflow-hidden shadow-2xl">
                    <DialogTitle className="sr-only">Détails du Look</DialogTitle>
                    <DialogDescription className="sr-only">Aperçu et métadonnées du skin partagé par la guilde.</DialogDescription>
                    {selectedSkin && (
                        <div className="flex flex-col h-full max-h-[90vh]">
                            {/* Visual Header */}
                            <div className="relative aspect-video bg-black/40 flex items-center justify-center shrink-0 border-b border-white/5">
                                {selectedSkin.thumbnailUrl ? (
                                    <NextImage 
                                        src={selectedSkin.thumbnailUrl} 
                                        alt={selectedSkin.name}
                                        fill
                                        className="object-contain p-6"
                                        unoptimized
                                    />
                                ) : (
                                    <Sparkles className="w-16 h-16 text-zinc-800" />
                                )}
                                
                                <div className="absolute top-4 left-4 flex flex-col gap-2">
                                    <div className="bg-sky-500/20 backdrop-blur-xl px-3 py-1 rounded-full border border-sky-500/30 w-fit">
                                        <span className="text-[10px] font-black text-sky-400 tracking-widest uppercase">
                                            {selectedSkin.provider}
                                        </span>
                                    </div>
                                    <div className="bg-zinc-950/80 backdrop-blur-xl px-3 py-1 rounded-xl border border-white/10 w-fit shadow-2xl flex items-center gap-2">
                                        <Avatar className="w-4 h-4 border border-white/10">
                                            <AvatarImage src={selectedSkin.author.image || undefined} />
                                            <AvatarFallback className="text-[6px] bg-zinc-900">{selectedSkin.author.name.substring(0,2)}</AvatarFallback>
                                        </Avatar>
                                        <span className="text-[10px] font-black text-zinc-400 tracking-tighter uppercase">
                                            Partagé par <span className="text-white">{selectedSkin.author.name}</span>
                                        </span>
                                    </div>
                                </div>
                            </div>
 
                            {/* Scrollable Content */}
                            <div className="flex-1 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10 hover:scrollbar-thumb-white/20">
                                <div className="p-6 space-y-8">
                                    <div>
                                        <h2 className="text-2xl font-black text-white uppercase tracking-tight leading-none">
                                            {selectedSkin.name}
                                        </h2>
                                        <div className="flex flex-wrap items-center gap-3 mt-4">
                                            {selectedSkin.metadata?.class && (
                                                <div className="flex items-center gap-2 px-3 py-1.5 bg-sky-500/10 text-sky-400 border border-sky-500/20 rounded-xl shadow-inner">
                                                    <span className="text-[10px] font-black uppercase tracking-widest">
                                                        {(() => {
                                                            const classData = DOFUS_CLASSES.find(c => getNumericClassId(c) === Number(selectedSkin.metadata!.class));
                                                            return classData ? classData.name : selectedSkin.metadata.class;
                                                        })()}
                                                    </span>
                                                </div>
                                            )}
                                            {selectedSkin.metadata?.gender && (
                                                <div className="flex items-center gap-2 px-3 py-1.5 bg-purple-500/10 text-purple-400 border border-purple-500/20 rounded-xl shadow-inner">
                                                     <span className="text-[10px] font-black uppercase tracking-widest">
                                                        {selectedSkin.metadata.gender === "M" ? "Mâle" : "Femelle"}
                                                    </span>
                                                </div>
                                            )}
                                            {selectedSkin.metadata?.head && (
                                                <div className="flex items-center gap-2 px-1 py-1 pr-3 bg-zinc-900/80 text-zinc-300 border border-white/5 rounded-xl shadow-inner group/head">
                                                    <div className="w-6 h-6 rounded-lg overflow-hidden bg-black/40 border border-white/5">
                                                        {String(selectedSkin.metadata.head).startsWith('http') ? (
                                                            <NextImage src={selectedSkin.metadata.head} alt="Head" width={24} height={24} className="object-cover group-hover/head:scale-110 transition-transform" unoptimized />
                                                        ) : (
                                                            <div className="w-full h-full flex items-center justify-center text-[8px] font-bold text-zinc-600">
                                                                #{selectedSkin.metadata.head}
                                                            </div>
                                                        )}
                                                    </div>
                                                    <span className="text-[9px] font-black uppercase tracking-widest opacity-70">
                                                        Visage {String(selectedSkin.metadata.head).startsWith('http') ? "" : selectedSkin.metadata.head}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Colors */}
                                    {selectedSkin.colors && Object.keys(selectedSkin.colors).length > 0 && (
                                        <div className="space-y-4">
                                            <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.3em] flex items-center gap-2">
                                                <div className="w-1 h-1 rounded-full bg-sky-500" />
                                                Harmonie de Couleurs
                                            </h3>
                                            <div className="grid grid-cols-2 gap-2">
                                                {Object.entries(selectedSkin.colors).map(([label, hex]) => (
                                                    <div key={label} className="bg-white/5 border border-white/5 rounded-xl p-2 flex items-center gap-3 hover:bg-white/10 transition-colors">
                                                        <div 
                                                            className="w-8 h-8 rounded-lg shadow-inner border border-white/10 shrink-0"
                                                            style={{ backgroundColor: hex as string }}
                                                        />
                                                        <div className="min-w-0">
                                                            <p className="text-[9px] font-bold text-zinc-500 truncate uppercase tracking-tighter">{label}</p>
                                                            <p className="text-[11px] font-black text-white uppercase font-mono">{hex as string}</p>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Equipment */}
                                    {selectedSkin.equipment && Array.isArray(selectedSkin.equipment) && selectedSkin.equipment.length > 0 && (
                                        <div className="space-y-4 pb-4">
                                            <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.3em] flex items-center gap-2">
                                                <div className="w-1 h-1 rounded-full bg-purple-500" />
                                                Composition du Look
                                            </h3>
                                            <div className="grid grid-cols-1 gap-2">
                                                {selectedSkin.equipment.map((item: any, idx: number) => (
                                                    <div key={idx} className="bg-zinc-900/40 border border-white/5 rounded-xl p-2.5 flex items-center justify-between group/item hover:bg-zinc-900/80 transition-all">
                                                        <div className="flex items-center gap-3">
                                                            <div className="w-10 h-10 bg-black/40 rounded-lg flex items-center justify-center p-1 border border-white/5">
                                                                {item.icon ? (
                                                                    <NextImage src={item.icon} alt={item.name} width={32} height={32} unoptimized />
                                                                ) : (
                                                                    <Sparkles className="w-5 h-5 text-zinc-800" />
                                                                )}
                                                            </div>
                                                            <div>
                                                                <p className="text-[12px] font-bold text-white group-hover/item:text-sky-400 transition-colors leading-tight">{item.name}</p>
                                                                <p className="text-[9px] text-zinc-500 font-medium uppercase tracking-wider">{item.type}</p>
                                                            </div>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Sticky Footer */}
                            <div className="p-4 bg-zinc-900/80 backdrop-blur-lg border-t border-white/5 grid grid-cols-2 gap-3 shrink-0">
                                <Button 
                                    asChild
                                    variant="outline" 
                                    className="rounded-xl border-white/5 bg-white/5 hover:bg-white/10 hover:border-white/10 h-12 text-xs"
                                >
                                    <a href={selectedSkin.url} target="_blank" rel="noopener noreferrer" className="gap-2">
                                        <ExternalLink className="w-4 h-4" />
                                        Voir Source
                                    </a>
                                </Button>
                                <Button 
                                    variant="outline" 
                                    className="rounded-xl border-white/5 bg-sky-500/10 text-sky-400 hover:bg-sky-500 hover:text-white h-12 text-xs font-black uppercase tracking-widest"
                                    onClick={() => handleCopyLink(selectedSkin.url)}
                                >
                                    <Copy className="w-4 h-4 mr-2" />
                                    Copier Lien
                                </Button>
                                {currentProfileId === selectedSkin.author.id && (
                                    <Button 
                                        variant="outline" 
                                        className="rounded-xl border-indigo-500/30 bg-indigo-500/5 text-indigo-400 hover:bg-indigo-500 hover:text-white h-12 text-xs font-black uppercase tracking-widest col-span-2"
                                        onClick={() => handleShare(selectedSkin.id, "SKIN", selectedSkin.author.id)}
                                        disabled={sharingIds.has(selectedSkin.id) || !skinShareConfigured}
                                    >
                                        <Megaphone className="w-4 h-4 mr-2" />
                                        {sharingIds.has(selectedSkin.id) ? "Envoi..." : "Propulser sur Discord"}
                                    </Button>
                                )}
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}

function EmptyState({ guildId, tab, searchQuery, onReset }: { guildId: string, tab: "STUFF"|"SKIN", searchQuery: string, onReset: () => void }) {
    return (
        <div className="col-span-full py-20 bg-zinc-950/20 rounded-3xl border border-dashed border-white/5 flex flex-col items-center justify-center text-center gap-4">
            <div className="w-16 h-16 rounded-full bg-zinc-900/50 flex items-center justify-center border border-white/5">
                <Search className="w-8 h-8 text-zinc-700" />
            </div>
            <div className="space-y-1">
                <h3 className="text-zinc-300 font-semibold text-lg">Aucun {tab === "STUFF" ? "build" : "skin"} trouvé</h3>
                <p className="text-zinc-500 text-sm max-w-md mx-auto">
                    {tab === "STUFF" 
                        ? "Importez vos stuffs DofusBook depuis votre profil pour qu'ils s'affichent ici."
                        : "Importez vos skins Barbofus ou SkinManga depuis votre profil pour inspirer la guilde !"}
                </p>
            </div>
            <div className="flex items-center gap-3 mt-2">
                {searchQuery && (
                    <Button variant="outline" size="sm" onClick={onReset} className="border-white/10 hover:bg-white/5 text-zinc-400">
                        <RefreshCw className="w-4 h-4 mr-2" />
                        Réinitialiser
                    </Button>
                )}
                <a href={`/dashboard/${guildId}/profile?tab=${tab === "STUFF" ? "combat" : "skins"}`}>
                    <Button size="sm" className={cn("font-bold text-white", tab === "STUFF" ? "bg-emerald-600 hover:bg-emerald-500" : "bg-sky-600 hover:bg-sky-500")}>
                        Mon Profil
                        <ChevronRight className="w-4 h-4 ml-1" />
                    </Button>
                </a>
            </div>
        </div>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { Suspense } from "react";
import AccessDenied from "@/components/access-denied";
import { getUserContext } from "@/server/actions/user-actions";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Sparkles, BookOpen, BarChart3, MessageSquare } from "lucide-react";
import { getWelcomePosts } from "@/server/actions/onboarding-admin-actions";
import { WelcomeFeedClient } from "../welcome/_components/welcome-feed-client";
import { getGuildPresentation } from "@/server/actions/presentation-actions";
import PresentationContent from "./_components/presentation-content";
import { getGuildStats } from "@/server/actions/guild-stats-actions";
import StatsClient from "../stats/_components/stats-client";
import { isModuleEnabled } from "@/server/actions/module-actions";
import { GuildHubTabs } from "./_components/guild-hub-tabs";

type Props = { 
    params: Promise<{ guildId: string }>;
    searchParams: Promise<{ tab?: string }>;
};

export default async function GuildHubPage({ params, searchParams }: Props) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;
    const { tab } = await searchParams;
    const initialTab = tab || "welcome";

    const user = await getUserContext(guildId);
    
    // Check if user has access to at least one of the tabs
    const canViewAny = user.canViewWelcome || user.canViewPresentation || user.canViewStats;
    if (!canViewAny) return <AccessDenied />;

    return (
        <div className="space-y-12 pb-24">
            <UnifiedModuleHeader
                title="La Guilde"
                description="Espace communautaire • Vie interne, histoire et performances."
                icon={Sparkles}
                iconColor="#ffffff"
                backHref={`/dashboard/${guildId}`}
            />

            <Tabs value={initialTab} className="w-full">
                <GuildHubTabs 
                    initialTab={initialTab}
                    canViewWelcome={!!user.canViewWelcome}
                    canViewPresentation={!!user.canViewPresentation}
                    canViewStats={!!user.canViewStats}
                />

                {/* --- Welcome Tab --- */}
                {user.canViewWelcome && (
                    <TabsContent value="welcome" className="mt-6 border-none p-0 outline-none animate-in fade-in zoom-in-95 duration-200">
                        <Suspense fallback={<div className="h-64 rounded-2xl bg-white/5 animate-pulse" />}>
                            <WelcomeTabContent guildId={guildId} user={user} />
                        </Suspense>
                    </TabsContent>
                )}

                {/* --- Presentation Tab --- */}
                {user.canViewPresentation && (
                    <TabsContent value="presentation" className="mt-6 border-none p-0 outline-none animate-in fade-in zoom-in-95 duration-200">
                        <Suspense fallback={<div className="h-64 rounded-2xl bg-white/5 animate-pulse" />}>
                            <PresentationTabContent guildId={guildId} user={user} />
                        </Suspense>
                    </TabsContent>
                )}

                {/* --- Stats Tab --- */}
                {user.canViewStats && (
                    <TabsContent value="stats" className="mt-6 border-none p-0 outline-none animate-in fade-in zoom-in-95 duration-200">
                        <Suspense fallback={<div className="h-64 rounded-2xl bg-white/5 animate-pulse" />}>
                            <StatsTabContent guildId={guildId} user={user} />
                        </Suspense>
                    </TabsContent>
                )}
            </Tabs>
        </div>
    );
}

async function WelcomeTabContent({ guildId, user }: { guildId: string, user: any }) {
    const { posts, reactorNames } = await getWelcomePosts(guildId);
    
    if (posts.length === 0) {
        return (
            <div className="p-12 rounded-2xl border border-white/5 bg-zinc-900/40 text-center space-y-4 max-w-3xl mx-auto">
                <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center mx-auto">
                    <MessageSquare className="w-6 h-6 text-zinc-500" />
                </div>
                <div className="space-y-1">
                    <p className="text-zinc-400 font-bold">Aucun message de bienvenue</p>
                    <p className="text-xs text-zinc-600">Les nouveaux membres s'afficheront ici quand ils rejoindront la guilde.</p>
                </div>
            </div>
        );
    }

    return (
        <div className="max-w-3xl mx-auto">
            <WelcomeFeedClient
                initialPosts={posts}
                reactorNames={reactorNames}
                currentProfileId={user.profileId || ""}
                guildId={guildId}
            />
        </div>
    );
}

async function PresentationTabContent({ guildId, user }: { guildId: string, user: any }) {
    const guild = await getGuildPresentation(guildId, false);
    if (!guild) return null;

    return <PresentationContent guild={guild} user={user} guildId={guildId} />;
}

async function StatsTabContent({ guildId, user }: { guildId: string, user: any }) {
    const enabled = await isModuleEnabled(guildId, "stats");
    if (!user.isAdmin && !enabled) return <AccessDenied />;

    const result = await getGuildStats(guildId);
    if (!result.success || !result.stats) {
        return (
            <div className="p-12 text-center text-zinc-500 bg-white/5 rounded-2xl border border-white/5">
                Erreur lors du chargement des statistiques.
            </div>
        );
    }

    return <StatsClient stats={result.stats} />;
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import Image from "next/image";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { TrendingUp, Clock, Trophy, Loader2, ShieldCheck, CheckSquare, HandHeart, Zap, AlertTriangle, ChevronLeft, ChevronRight, MessageSquare } from "lucide-react";
import { LeaderboardCard } from "./leaderboard-card";
import {
    getActivityLadder,
    getSeniorityLadder,
    getSuccessLadder,
    getContributionLadder,
    getGuildatonsLadder,
    getGeneralLadder,
    getPresenceLadder,
    type LadderEntry,
    type ActivityView
} from "@/server/actions/ladder-actions";
import { formatSeniority } from "@/lib/ladder-utils";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";

type Props = {
    guildId: string;
    canValidate?: boolean;
    hasPseudoIssue?: boolean;
    pseudoDofus?: string | null;
};

export function LadderClient({ guildId, canValidate, hasPseudoIssue, pseudoDofus }: Props) {
    const [activeTab, setActiveTab] = useState<"activity" | "contribution" | "seniority" | "success" | "general" | "guildatons" | "discord">("activity");
    const [discordMetric, setDiscordMetric] = useState<"messages" | "voice">("messages");
    const [activityView, setActivityView] = useState<ActivityView>("weekly");
    const [ladder, setLadder] = useState<LadderEntry[]>([]);
    const [pagination, setPagination] = useState<{ totalPages: number; totalCount: number } | null>(null);
    const [currentPage, setCurrentPage] = useState(1);
    const [loading, setLoading] = useState(true);

    // Reset page when switching tabs or timeframes
    useEffect(() => {
        setCurrentPage(1);
    }, [activeTab, activityView, discordMetric]);

    useEffect(() => {
        async function loadLadder() {
            setLoading(true);
            let result;

            switch (activeTab) {
                case "activity":
                    result = await getActivityLadder(guildId, activityView, currentPage);
                    break;
                case "contribution":
                    result = await getContributionLadder(guildId, currentPage);
                    break;
                case "seniority":
                    result = await getSeniorityLadder(guildId, currentPage);
                    break;
                case "success":
                    result = await getSuccessLadder(guildId, currentPage);
                    break;
                case "general":
                    result = await getGeneralLadder(guildId, currentPage);
                    break;
                case "guildatons":
                    result = await getGuildatonsLadder(guildId, activityView, currentPage);
                    break;
                case "discord":
                    result = await getPresenceLadder(guildId, discordMetric, activityView, currentPage);
                    break;
            }

            if (result.success && result.data) {
                setLadder(result.data.entries);
                setPagination({
                    totalPages: result.data.totalPages,
                    totalCount: result.data.totalCount
                });
            } else {
                setLadder([]);
                setPagination(null);
            }
            setLoading(false);
        }

        loadLadder();
    }, [guildId, activeTab, activityView, currentPage]);

    const getValueLabel = (entry: LadderEntry): React.ReactNode => {
        switch (activeTab) {
            case "activity":
                return (
                    <div className="flex items-center gap-1.5 font-black">
                        <span>{entry.value.toLocaleString()}</span>
                        <Image src="/PA.png" alt="PA" width={16} height={16} className="object-contain" />
                    </div>
                );
            case "contribution":
                return `${entry.value.toLocaleString()} pts`;
            case "seniority":
                return formatSeniority(entry.value);
            case "success":
                return `${entry.value.toLocaleString()} pts`;
            case "general":
                return (
                    <div className="flex items-center gap-1.5 font-black">
                        <span>{Number(entry.totalXpBigInt || 0).toLocaleString()}</span>
                        <Image src="/PA.png" alt="PA" width={16} height={16} className="object-contain" />
                    </div>
                );
            case "guildatons":
                return (
                    <div className="flex items-center gap-1.5 font-black text-yellow-500">
                        <span>{entry.value.toLocaleString()}</span>
                        <Image src="/guildaton.png" alt="G" width={16} height={16} className="object-contain" />
                    </div>
                );
            case "discord":
                if (discordMetric === "messages") {
                    return (
                        <div className="flex items-center gap-2 font-black text-indigo-400">
                            <Zap className="w-3.5 h-3.5 fill-indigo-400" />
                            <span>{entry.value.toLocaleString()} messages</span>
                        </div>
                    );
                } else {
                    const totalMinutes = entry.value;
                    const months = Math.floor(totalMinutes / (30 * 24 * 60));
                    const days = Math.floor((totalMinutes % (30 * 24 * 60)) / (24 * 60));
                    const hours = Math.floor((totalMinutes % (24 * 60)) / 60);
                    const mins = totalMinutes % 60;

                    return (
                        <div className="flex items-center gap-2 font-black text-cyan-400">
                            <Clock className="w-3.5 h-3.5" />
                            <div className="flex gap-1 items-baseline">
                                {months > 0 && <span>{months}<span className="text-[10px] text-zinc-500 font-medium ml-0.5">M</span></span>}
                                {days > 0 && <span>{days}<span className="text-[10px] text-zinc-500 font-medium ml-0.5">J</span></span>}
                                {hours > 0 && <span>{hours}<span className="text-[10px] text-zinc-500 font-medium ml-0.5">H</span></span>}
                                <span>{mins}<span className="text-[10px] text-zinc-500 font-medium ml-0.5">m</span></span>
                            </div>
                        </div>
                    );
                }
            default:
                return entry.value.toString();
        }
    };

    const categories = [
        { id: "activity", label: "Activité", icon: "/PA.png", isImage: true, color: "#10b981" },
        { id: "guildatons", label: "Guildatons", icon: "/guildaton.png", isImage: true, color: "#eab308" },
        { id: "discord", label: "Discord", icon: MessageSquare, isImage: false, color: "#818cf8" },
        { id: "contribution", label: "Contribution", icon: HandHeart, isImage: false, color: "#a855f7" },
        { id: "seniority", label: "Ancienneté", icon: Clock, isImage: false, color: "#06b6d4" },
        { id: "success", label: "Succès", icon: Trophy, isImage: false, color: "#f59e0b" },
        { id: "general", label: "Général", icon: TrendingUp, isImage: false, color: "#3b82f6" },
    ] as const;

    return (
        <div className="space-y-12">
            {/* Modern Tab Navigation (Glassmorphism 2026) */}
            <div className="relative sticky top-0 z-50 py-2 sm:py-4 -mt-4 bg-black/40 backdrop-blur-3xl border-b border-white/5 shadow-2xl transition-all duration-500">
                <div className="max-w-7xl mx-auto px-4 sm:px-6">
                    <div className="flex items-center justify-between">
                        {/* Tab Container with Scroll Mask */}
                        <div className="relative flex-1 min-w-0">
                            <div className="flex items-center gap-1 overflow-x-auto no-scrollbar mask-horizontal-scroll premium-scrollbar lg:mask-none -mb-[1px] pb-1">
                                {categories.map((cat) => {
                                    const isActive = activeTab === cat.id;
                                    return (
                                        <button
                                            key={cat.id}
                                            onClick={() => setActiveTab(cat.id)}
                                            className={cn(
                                                "relative z-10 flex items-center gap-2.5 px-5 sm:px-6 py-3.5 sm:py-4 border-b-2 transition-all duration-500 group whitespace-nowrap",
                                                isActive 
                                                  ? "text-white" 
                                                  : "border-transparent text-zinc-500 hover:text-zinc-300"
                                            )}
                                            style={isActive ? { borderColor: cat.color } : {}}
                                        >
                                            {cat.isImage ? (
                                                <div 
                                                    className={cn(
                                                        "w-5 h-5 transition-all duration-500 group-hover:scale-110 relative",
                                                        isActive ? "scale-110" : "opacity-40 grayscale group-hover:opacity-100 group-hover:grayscale-0"
                                                    )}
                                                    style={isActive ? { 
                                                        filter: `drop-shadow(0 0 8px ${cat.color}80)` 
                                                    } : {}}
                                                >
                                                    <Image src={cat.icon as string} fill alt="" className="object-contain" />
                                                </div>
                                            ) : (
                                                <cat.icon 
                                                    className={cn(
                                                        "w-4 h-4 transition-all duration-500 group-hover:scale-110", 
                                                        isActive ? "scale-110" : "text-zinc-600 group-hover:text-zinc-400"
                                                    )} 
                                                    style={isActive ? { 
                                                        color: cat.color,
                                                        filter: `drop-shadow(0 0 10px ${cat.color}60)` 
                                                    } : {}}
                                                />
                                            )}
                                            <span className={cn(
                                                "text-[10px] sm:text-[11px] font-black uppercase tracking-[0.2em] transition-all duration-500",
                                                isActive ? "opacity-100" : "group-hover:text-white"
                                            )}
                                            style={isActive ? { 
                                                color: cat.color,
                                                textShadow: `0 0 20px ${cat.color}40`
                                            } : {}}
                                            >
                                                {cat.label}
                                            </span>

                                            {/* Active Hover Background */}
                                            {isActive && (
                                                <div 
                                                    className="absolute inset-0 -z-10 opacity-30 blur-2xl animate-pulse"
                                                    style={{ background: `radial-gradient(circle, ${cat.color} 0%, transparent 80%)` }}
                                                />
                                            )}
                                        </button>
                                    );
                                })}
                            </div>
                            
                            {/* Fading Edge for Scroll */}
                            <div className="absolute right-0 top-0 bottom-0 w-24 bg-gradient-to-l from-black/80 to-transparent pointer-events-none md:hidden" />
                        </div>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 space-y-8">
                {/* Explicative Card (2026 Style) */}
                <div className="relative overflow-hidden rounded-3xl border border-white/5 bg-zinc-900/40 p-8 backdrop-blur-xl">
                    <div 
                        className="absolute top-0 right-0 w-64 h-64 blur-[100px] opacity-20 pointer-events-none"
                        style={{ background: categories.find(c => c.id === activeTab)?.color || "#10b981" }}
                    />
                    
                    <div className="relative flex flex-col md:flex-row items-start md:items-center gap-6">
                        <div 
                            className="w-16 h-16 rounded-2xl flex items-center justify-center shrink-0 border border-white/10"
                            style={{ backgroundColor: `${categories.find(c => c.id === activeTab)?.color}15` }}
                        >
                            {(() => {
                                const cat = categories.find(c => c.id === activeTab);
                                if (!cat) return <Trophy className="w-8 h-8" />;
                                if (cat.isImage) {
                                    return (
                                        <div className="relative w-8 h-8">
                                            <Image src={cat.icon as string} fill alt="" className="object-contain" />
                                        </div>
                                    );
                                }
                                const Icon = cat.icon as any;
                                return <Icon className="w-8 h-8" style={{ color: cat.color }} />;
                            })()}
                        </div>
                        
                        <div className="space-y-2 flex-1 relative">
                            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                <h2 className="text-2xl font-black text-white tracking-tighter uppercase flex items-center gap-3">
                                    {categories.find(c => c.id === activeTab)?.label}
                                    {activeTab === 'activity' && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]" />}
                                    {activeTab === 'guildatons' && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse shadow-[0_0_8px_rgba(245,158,11,0.8)]" />}
                                </h2>

                                {/* Contextual Period Selector */}
                                {(activeTab === "activity" || activeTab === "guildatons" || activeTab === "discord") && (
                                    <div className="flex items-center gap-3 animate-in fade-in slide-in-from-right-4 duration-500">
                                        {activeTab === "discord" && (
                                            <div className="flex bg-white/[0.03] border border-white/10 rounded-xl p-1 shadow-xl backdrop-blur-3xl">
                                                <button
                                                    onClick={() => setDiscordMetric("messages")}
                                                    className={cn(
                                                        "px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all",
                                                        discordMetric === "messages" 
                                                            ? "bg-indigo-500/20 text-indigo-400 border border-indigo-500/30" 
                                                            : "text-zinc-500 hover:text-zinc-300 border border-transparent"
                                                    )}
                                                >
                                                    Messages
                                                </button>
                                                <button
                                                    onClick={() => setDiscordMetric("voice")}
                                                    className={cn(
                                                        "px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all",
                                                        discordMetric === "voice" 
                                                            ? "bg-cyan-500/20 text-cyan-400 border border-cyan-500/30" 
                                                            : "text-zinc-500 hover:text-zinc-300 border border-transparent"
                                                    )}
                                                >
                                                    Vocal
                                                </button>
                                            </div>
                                        )}
                                        <Select value={activityView} onValueChange={(v) => setActivityView(v as ActivityView)}>
                                            <SelectTrigger className="w-full sm:w-[200px] h-9 sm:h-10 bg-white/[0.03] border-white/10 text-[9px] sm:text-[10px] font-black uppercase tracking-[0.2em] text-zinc-300 rounded-xl hover:bg-white/[0.06] transition-all shadow-xl backdrop-blur-3xl focus:ring-1 focus:ring-white/20">
                                                <div className="flex items-center gap-2">
                                                    <Clock className="w-3.5 h-3.5 text-zinc-500" />
                                                    <SelectValue placeholder="Période" />
                                                </div>
                                            </SelectTrigger>
                                            <SelectContent className="bg-zinc-950/98 backdrop-blur-3xl border-white/10 p-1 rounded-xl shadow-[0_30px_60px_-12px_rgba(0,0,0,0.8)]">
                                                <SelectItem value="weekly" className="text-[10px] uppercase font-black tracking-widest rounded-lg focus:bg-white/5">📅 Cette semaine</SelectItem>
                                                <SelectItem value="monthly" className="text-[10px] uppercase font-black tracking-widest rounded-lg focus:bg-white/5">📅 Ce mois-ci</SelectItem>
                                                <SelectItem value="alltime" className="text-[10px] uppercase font-black tracking-widest rounded-lg focus:bg-white/5 text-amber-500">🏆 Global (All-Time)</SelectItem>
                                            </SelectContent>
                                        </Select>
                                    </div>
                                )}
                            </div>
                            
                            <p className="text-zinc-400 text-sm leading-relaxed max-w-2xl">
                                {activeTab === 'activity' && "Ce classement mesure votre engagement direct dans la guilde via la validation de missions et les dons de kamas. Seul l'XP gagné sur la période sélectionnée est comptabilisé."}
                                {activeTab === 'contribution' && "Récompense les membres qui s'impliquent dans la vie de la guilde (aide aux succès, présence aux événements, parrainage). Ces points sont attribués manuellement par les officiers."}
                                {activeTab === 'seniority' && "L'ordre de prestige basé sur votre date d'intégration au serveur de guilde. Plus vous êtes fidèle, plus vous montez dans ce panthéon d'honneur."}
                                {activeTab === 'success' && "Le score de prestige Dofus par excellence. Ce ladder synchronise vos points de succès réels directement depuis les serveurs officiels d'Ankama."}
                                {activeTab === 'general' && "L'expérience totale (XP) accumulée par votre personnage sur Dofus. Une mesure brute de puissance et de temps passé à parcourir le Monde des Douze."}
                                {activeTab === 'guildatons' && "La richesse monétaire interne de la guilde. Le Guildaton est la monnaie virtuelle utilisée pour les échanges, les récompenses et la boutique exclusive."}
                                {activeTab === 'discord' && (
                                    discordMetric === "messages" 
                                        ? "Le volume de discussion sur Discord. Vos messages contribuent à l'animation de la guilde et à l'entraide communautaire."
                                        : "Le temps passé en vocal pour jouer ensemble, coordonner des activités ou simplement discuter. Le cœur battant de la guilde."
                                )}
                            </p>
                            
                            {(activeTab === 'success' || activeTab === 'general') && hasPseudoIssue && (
                                <div className="mt-4 p-4 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-500 text-xs font-medium flex items-center gap-3 animate-in fade-in slide-in-from-left-4">
                                    <AlertTriangle className="h-4 w-4 shrink-0" />
                                    <span>
                                        Vous n'apparaissez peut-être pas dans ce classement car votre 
                                        <strong> pseudo Dofus</strong> {!pseudoDofus ? "n'est pas renseigné" : `("${pseudoDofus}") est invalide`}.
                                        Rendez-vous sur <Link href={`/dashboard/${guildId}/profile`} className="underline font-black hover:text-amber-400">votre profil</Link> pour le corriger.
                                    </span>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

            <div className="flex flex-wrap items-center justify-between gap-4 border-b border-white/5 pb-4">
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-3">
                        <div className={cn(
                            "w-2 h-2 rounded-full animate-pulse",
                            activeTab === 'activity' ? 'bg-emerald-400' : activeTab === 'contribution' ? 'bg-purple-400' : activeTab === 'seniority' ? 'bg-cyan-400' : activeTab === 'guildatons' ? 'bg-yellow-400' : 'bg-amber-400'
                        )} />
                        <h2 className="text-sm font-black uppercase tracking-[0.2em] text-zinc-400">
                             CLASSEMENT {
                                activeTab === 'activity' ? 'D\'ACTIVITÉ' : 
                                activeTab === 'contribution' ? 'DE CONTRIBUTION' : 
                                activeTab === 'seniority' ? 'D\'ANCIENNETÉ' : 
                                activeTab === 'guildatons' ? 'DE RICHESSE' : 
                                activeTab === 'discord' ? (discordMetric === 'messages' ? 'DE DISCUSSION' : 'DE PRÉSENCE VOCALE') :
                                (activeTab === 'general' ? 'D\'XP GÉNÉRALE' : 'DE PRESTIGE')
                             }
                        </h2>
                    </div>

                    {canValidate && (
                        <Button
                            asChild
                            variant="outline"
                            size="sm"
                            className="h-8 border-white/10 bg-white/5 hover:bg-white/10 text-[10px] font-black uppercase tracking-wider gap-2 px-3"
                        >
                            <Link href={`/dashboard/${guildId}/admin/validation?tab=achievements`}>
                                <CheckSquare className="w-3.5 h-3.5 text-emerald-400" />
                                Validation Preuves
                            </Link>
                        </Button>
                    )}
                </div>
            </div>

            {/* Ladder Results */}
            <div className="relative min-h-[400px]">
                {loading ? (
                    <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 text-zinc-600">
                        <Loader2 className="h-8 w-8 animate-spin" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Calcul du classement...</span>
                    </div>
                ) : ladder.length === 0 ? (
                    <div className="absolute inset-0 flex items-center justify-center text-zinc-600">
                        <p className="text-xs font-medium italic">Aucune donnée disponible pour ce classement.</p>
                    </div>
                ) : (
                    <div className="space-y-8">
                        <div className="max-w-4xl mx-auto grid grid-cols-1 gap-2 animate-in fade-in slide-in-from-bottom-2 duration-500">
                            {ladder.map((entry) => (
                                <LeaderboardCard
                                    key={entry.profileId}
                                    entry={entry}
                                    valueLabel={getValueLabel(entry)}
                                    accentColor={
                                        activeTab === 'activity' ? 'emerald' : 
                                        activeTab === 'contribution' ? 'purple' : 
                                        activeTab === 'seniority' ? 'cyan' : 
                                        activeTab === 'guildatons' ? 'yellow' : 
                                        activeTab === 'discord' ? (discordMetric === 'messages' ? 'indigo' : 'cyan') :
                                        (activeTab === 'general' ? 'blue' : 'amber')
                                    }
                                />
                            ))}
                        </div>

                        {/* Pagination UI */}
                        {pagination && pagination.totalPages > 1 && (
                            <div className="flex flex-col sm:flex-row items-center justify-center gap-6 py-8 border-t border-white/5 animate-in fade-in slide-in-from-bottom-4 duration-700">
                                <div className="flex items-center gap-2">
                                    <Button
                                        variant="outline"
                                        size="icon"
                                        onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                                        disabled={currentPage === 1}
                                        className="w-10 h-10 rounded-xl bg-white/5 border-white/10 hover:bg-white/10 disabled:opacity-30 transition-all"
                                    >
                                        <ChevronLeft className="w-5 h-5 text-zinc-400" />
                                    </Button>

                                    <div className="flex items-center gap-1.5 px-4 h-10 rounded-xl bg-white/5 border border-white/10">
                                        <span className="text-[10px] font-black text-white">{currentPage}</span>
                                        <span className="text-[10px] font-black text-zinc-600">/</span>
                                        <span className="text-[10px] font-black text-zinc-400">{pagination.totalPages}</span>
                                    </div>

                                    <Button
                                        variant="outline"
                                        size="icon"
                                        onClick={() => setCurrentPage(p => Math.min(pagination.totalPages, p + 1))}
                                        disabled={currentPage === pagination.totalPages}
                                        className="w-10 h-10 rounded-xl bg-white/5 border-white/10 hover:bg-white/10 disabled:opacity-30 transition-all"
                                    >
                                        <ChevronRight className="w-5 h-5 text-zinc-400" />
                                    </Button>
                                </div>
                                <div className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-600">
                                    Total: {pagination.totalCount.toLocaleString()} membres
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { TrendingUp, Clock, Trophy, HandHeart } from "lucide-react";
import { LeaderboardCard } from "./leaderboard-card";
import {
    getActivityLadder,
    getSeniorityLadder,
    getSuccessLadder,
    getContributionLadder,
    getGeneralLadder,
    type LadderEntry,
    type ActivityView
} from "@/server/actions/ladder-actions";
import { formatSeniority } from "@/lib/ladder-utils";

type Props = {
    guildId: string;
};

export function LadderTabs({ guildId }: Props) {
    const [activeTab, setActiveTab] = useState<"activity" | "contribution" | "seniority" | "success" | "general">("activity");
    const [activityView, setActivityView] = useState<ActivityView>("weekly");
    const [ladder, setLadder] = useState<LadderEntry[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function loadLadder() {
            setLoading(true);
            let result;

            switch (activeTab) {
                case "activity":
                    result = await getActivityLadder(guildId, activityView);
                    break;
                case "contribution":
                    result = await getContributionLadder(guildId);
                    break;
                case "seniority":
                    result = await getSeniorityLadder(guildId);
                    break;
                case "success":
                    result = await getSuccessLadder(guildId);
                    break;
                case "general":
                    result = await getGeneralLadder(guildId);
                    break;
            }

            if (result.success && result.data) {
                setLadder(result.data.entries);
            } else {
                setLadder([]);
            }
            setLoading(false);
        }

        loadLadder();
    }, [guildId, activeTab, activityView]);

    const getValueLabel = (entry: LadderEntry): string => {
        switch (activeTab) {
            case "activity":
                return `${entry.value.toLocaleString()} XP`;
            case "contribution":
                return `${entry.value.toLocaleString()} pts`;
            case "seniority":
                return formatSeniority(entry.value);
            case "success":
                return `${entry.value.toLocaleString()} pts`;
            case "general":
                return `${Number(entry.totalXpBigInt || 0).toLocaleString()} XP`;
            default:
                return entry.value.toString();
        }
    };

    const categories = [
        { id: "activity", label: "Activité", icon: TrendingUp, color: "purple" },
        { id: "contribution", label: "Contribution", icon: HandHeart, color: "emerald" },
        { id: "seniority", label: "Ancienneté", icon: Clock, color: "cyan" },
        { id: "success", label: "Succès", icon: Trophy, color: "amber" },
        { id: "general", label: "Général", icon: TrendingUp, color: "blue" },
    ] as const;

    return (
        <div className="space-y-6">
            <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
                <div className="flex flex-col gap-6">
                    {/* Responsive Tabs Header */}
                    <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                        {/* Scrollable container for tabs */}
                        <div className="relative w-full overflow-hidden border-b border-white/10">
                            <TabsList className="flex w-full h-auto bg-transparent p-0 justify-start overflow-x-auto overflow-y-hidden no-scrollbar scroll-smooth rounded-none">
                                {categories.map((cat) => (
                                    <TabsTrigger
                                        key={cat.id}
                                        value={cat.id}
                                        className={`flex-shrink-0 gap-2 px-6 py-4 text-sm font-bold uppercase tracking-wider transition-all duration-300 rounded-none border-b-2 border-transparent shadow-none
                                            data-[state=active]:border-${cat.color}-500 data-[state=active]:text-${cat.color}-400 data-[state=active]:bg-transparent
                                            text-zinc-500 hover:text-white hover:bg-white/5 bg-transparent`}
                                    >
                                        <cat.icon className="h-4 w-4" />
                                        {cat.label}
                                    </TabsTrigger>
                                ))}
                            </TabsList>
                            {/* Mobile visual hint for scrolling */}
                            <div className="absolute right-0 top-0 bottom-0 w-8 bg-gradient-to-l from-[#0a0a0a] to-transparent pointer-events-none lg:hidden" />
                        </div>

                        {/* View Toggle for Activity */}
                        {activeTab === "activity" && (
                            <div className="flex justify-end">
                                <Select value={activityView} onValueChange={(v) => setActivityView(v as ActivityView)}>
                                    <SelectTrigger className="w-full sm:w-[220px] bg-black/40 border-white/10 text-white rounded-xl backdrop-blur-md">
                                        <SelectValue placeholder="Période" />
                                    </SelectTrigger>
                                    <SelectContent className="bg-zinc-900 border-white/10 text-white">
                                        <SelectItem value="weekly">📅 Hebdomadaire (RESET MARDI)</SelectItem>
                                        <SelectItem value="monthly">📅 Mensuel</SelectItem>
                                        <SelectItem value="alltime">🏆 Historique Global</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        )}
                    </div>
                </div>

                <TabsContent value="activity" className="mt-6">
                    <LeaderboardList
                        ladder={ladder}
                        loading={loading}
                        getValueLabel={getValueLabel}
                        emptyMessage="Aucune activité enregistrée pour cette période."
                        accentColor="purple"
                    />
                </TabsContent>

                <TabsContent value="contribution" className="mt-6">
                    <LeaderboardList
                        ladder={ladder}
                        loading={loading}
                        getValueLabel={getValueLabel}
                        emptyMessage="Aucun point de contribution enregistré."
                        accentColor="emerald"
                    />
                </TabsContent>

                <TabsContent value="seniority" className="mt-6">
                    <LeaderboardList
                        ladder={ladder}
                        loading={loading}
                        getValueLabel={getValueLabel}
                        emptyMessage="Aucun membre avec date d'arrivée."
                        accentColor="cyan"
                    />
                </TabsContent>

                <TabsContent value="success" className="mt-6">
                    <LeaderboardList
                        ladder={ladder}
                        loading={loading}
                        getValueLabel={getValueLabel}
                        emptyMessage="Aucun score de succès enregistré."
                        accentColor="amber"
                    />
                </TabsContent>

                <TabsContent value="general" className="mt-6">
                    <LeaderboardList
                        ladder={ladder}
                        loading={loading}
                        getValueLabel={getValueLabel}
                        emptyMessage="Aucune donnée d'EXP Ankama synchronisée."
                        accentColor="blue"
                    />
                </TabsContent>
            </Tabs>
        </div>
    );
}

// Leaderboard List Component
function LeaderboardList({
    ladder,
    loading,
    getValueLabel,
    emptyMessage,
    accentColor
}: {
    ladder: LadderEntry[];
    loading: boolean;
    getValueLabel: (entry: LadderEntry) => string;
    emptyMessage: string;
    accentColor: "purple" | "cyan" | "amber" | "emerald" | "blue";
}) {
    if (loading) {
        return (
            <div className="grid grid-cols-1 gap-3">
                {[...Array(5)].map((_, i) => (
                    <div key={i} className="h-20 bg-muted/10 rounded-xl animate-pulse" />
                ))}
            </div>
        );
    }

    if (ladder.length === 0) {
        return (
            <div className="text-center py-12 text-muted-foreground">
                <p>{emptyMessage}</p>
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 gap-3">
            {ladder.map((entry) => (
                <LeaderboardCard
                    key={entry.profileId}
                    entry={entry}
                    valueLabel={getValueLabel(entry)}
                    accentColor={accentColor}
                />
            ))}
        </div>
    );
}

"use client";

