import { getMyWeeklyKamaStatus, getKamaStats } from "@/server/actions/kama-actions";
import { MissionBoard } from "@/components/missions/mission-board";
import { redirect } from "next/navigation";
import { ScrollText, Info } from "lucide-react";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import AccessDenied from "@/components/access-denied";
import { MissionsErrorState } from "@/components/missions/missions-error-state";
import { GuildProgressBar } from "@/components/missions/guild-progress-bar";
import { isModuleEnabled } from "@/server/actions/module-actions";
import { ActivitiesNav } from "@/components/layout/activities-nav";
import { getDofusWeek } from "@/lib/date-utils";
import { WeeklyGuildatonCounter } from "@/components/missions/weekly-guildaton-counter";

export const dynamic = 'force-dynamic';


export default async function MissionsPage({ params }: { params: Promise<{ guildId: string }> }) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;

    if (!await isModuleEnabled(guildId, "missions")) {
        redirect(`/dashboard/${guildId}`);
    }

    const user = await getUserContext(guildId);
    if (!user.canViewMissions) {
        return <AccessDenied />;
    }

    const { week, year } = getDofusWeek();

    // Fetch all data in parallel
    const [response, overrideRes, kamaRes, kamaStatsRes, weeklyGuildatons] = await Promise.all([
        getWeekMissions(guildId, week, year),
        getGuildMissionXpOverride(guildId),
        getMyWeeklyKamaStatus(guildId),
        getKamaStats(guildId), // Fetch total guild stats for kama XP calculation
        getWeeklyGuildatons(user.profileId!, week, year),
    ]);

    // 24h Restriction Check
    const HOURS_RESIDENCY = 24;
    const profileCreatedAt = user.createdAt ? new Date(user.createdAt) : new Date();
    const diffMs = Date.now() - profileCreatedAt.getTime();
    const isRestricted = (diffMs / (1000 * 60 * 60)) < HOURS_RESIDENCY && !user.isAdmin;
    const availableAt = new Date(profileCreatedAt.getTime() + (HOURS_RESIDENCY * 60 * 60 * 1000)).toISOString();

    if (!response.success) {
        if (response.error?.includes("Member not found") || response.error?.includes("Insufficient Permissions")) {
            return <AccessDenied />;
        }
        return <MissionsErrorState error={response.error || "Une erreur inconnue est survenue."} />;
    }

    const missions = response.data || [];

    // [MIS-1] XP Override
    const xpOverride = (overrideRes.success && overrideRes.data) ? overrideRes.data.xpOverride : null;
    const missionXP = missions.reduce((acc: number, mission: any) => {
        const validatedCount = (mission as any)._count?.submissions || 0;
        return acc + ((mission as any).xpReward || 0) * validatedCount;
    }, 0);

    // [KAM-XP] Add validated kama donations XP this week (guild-wide)
    let kamaXP = 0;
    if (kamaStatsRes.success && kamaStatsRes.data) {
        const { KAMA_TRANCHE, REWARDS_PER_TRANCHE } = await import("@/lib/kama-constants");
        const validatedWeeklyKamas = kamaStatsRes.data.weeklyTotal || 0; // The whole guild's valid kamas this week
        const validatedTranches = Math.floor(validatedWeeklyKamas / KAMA_TRANCHE);
        kamaXP = validatedTranches * REWARDS_PER_TRANCHE.xp;
    }

    const dynamicXP = missionXP + kamaXP;
    // [MIS-1] Override already includes the generated dynamic XP if it is set.
    const currentXP = xpOverride !== null ? xpOverride : dynamicXP;


    // [MIS-1 FIX] targetTier from published missions, fallback 3
    const missionTierFromPublished = missions.length > 0 ? (missions[0] as any)?.tier ?? null : null;
    const targetTier = missionTierFromPublished !== null ? missionTierFromPublished : 3;

    // Kama status for the widget
    const kamaStatus = (kamaRes.success && kamaRes.data) ? kamaRes.data : null;

    return (
        <div className="space-y-6 pb-12">
            <ActivitiesNav guildId={guildId} />
            <UnifiedModuleHeader
                title="Missions de Guilde"
                description={`Semaine ${week} • Année ${year} | Relevez les défis pour faire briller votre guilde.`}
                icon={ScrollText}
                iconColor="#ef4444"
                backHref={`/dashboard/${guildId}`}
            />

            {/* Dashboard Row 1: XP Progress & Weekly Rewards */}
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 px-1">
                <div className="xl:col-span-2">
                    <GuildProgressBar
                        currentXP={currentXP}
                        targetTier={targetTier}
                        guildId={guildId}
                        kamaStatus={kamaStatus}
                    />
                </div>
                <div className="space-y-6">
                    <WeeklyGuildatonCounter current={weeklyGuildatons || 0} />
                    
                    {/* Placeholder for other stats/widgets if needed */}
                    <div className="p-5 rounded-2xl bg-foreground/[0.03] border border-border flex flex-col items-center justify-center gap-3 text-center">
                         <div className="p-2.5 rounded-xl bg-primary/10 border border-primary/20">
                             <Info className="w-5 h-5 text-primary" />
                         </div>
                         <div>
                             <p className="text-xs font-black text-foreground uppercase tracking-widest italic">Information</p>
                             <p className="text-[10px] text-muted-foreground font-bold leading-relaxed mt-1 italic">
                                Pensez à lier vos stuffs Dofusbook dans votre Profil (onglet Stuff) pour plus de visibilité.
                             </p>
                         </div>
                    </div>
                </div>
            </div>

            <MissionBoard
                missions={missions}
                currentUserId={session.user.id!}
                guildId={guildId}
                isRestricted={isRestricted}
                availableAt={availableAt}
            />
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { getUnreadNotifications, markAsRead, markAllAsRead } from "@/server/actions/notification-actions";
import { NotificationType, NotificationCategory } from "@prisma/client";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { Bell, CheckCircle2, Info, AlertTriangle, Shield, X, Check, Target, Trophy, Flame, Calendar, PieChart, ShieldCheck } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import Link from "next/link";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

// Type definition tailored for UI
type Notification = {
    id: string;
    title: string;
    message: string;
    type: NotificationType;
    category: NotificationCategory;
    read: boolean;
    link: string | null;
    createdAt: Date;
};

export default function NotificationsPage() {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [activeTab, setActiveTab] = useState<NotificationCategory | "ALL">("ALL");
    const [loading, setLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const router = useRouter();

    async function loadNotifications() {
        setLoading(true);
        const result = await getUnreadNotifications();
        if (result.success && result.data) {
            setNotifications(result.data as any);
        }
        setLoading(false);
    }

    useEffect(() => {
        loadNotifications();
    }, []);

    const handleDismiss = async (id: string) => {
        setNotifications((prev) => prev.filter((n) => n.id !== id));
        try {
            await markAsRead(id);
        } catch (error) {
            toast.error("Erreur lors de la mise à jour");
        }
    };

    const handleDismissAll = async () => {
        if (filteredNotifications.length === 0) return;

        const idsToRemove = new Set(filteredNotifications.map(n => n.id));
        setNotifications((prev) => prev.filter((n) => !idsToRemove.has(n.id)));

        try {
            if (activeTab === "ALL") {
                await markAllAsRead();
            } else {
                // Future: add markCategoryAsRead if needed, for now individual marks or all
                // Simulating markAll for filtered if we wanted, but action doesn't support filter yet.
                // For simplicity, we mark all in UI but only call global markAll or loop marks.
                await markAllAsRead();
            }
            toast.success("Notifications marquées comme lues");
        } catch (error) {
            toast.error("Erreur lors de la mise à jour");
        }
    };

    const getIcon = (category: NotificationCategory) => {
        switch (category) {
            case "MISSION": return <Target className="w-5 h-5 text-blue-400" />;
            case "SUCCESS": return <Trophy className="w-5 h-5 text-yellow-400" />;
            case "SONGES": return <Flame className="w-5 h-5 text-emerald-400" />;
            case "EVENT": return <Calendar className="w-5 h-5 text-purple-400" />;
            case "POLL": return <PieChart className="w-5 h-5 text-orange-400" />;
            case "ADMIN_ALERT": return <ShieldCheck className="w-5 h-5 text-rose-400" />;
            default: return <Bell className="w-5 h-5 text-zinc-400" />;
        }
    };

    const getCategoryLabel = (category: NotificationCategory) => {
        switch (category) {
            case "MISSION": return "Missions";
            case "SUCCESS": return "Succès";
            case "SONGES": return "Songes";
            case "EVENT": return "Événements";
            case "POLL": return "Sondages";
            case "ADMIN_ALERT": return "Administration";
            default: return "Système";
        }
    };

    const filteredNotifications = notifications.filter(n =>
        activeTab === "ALL" || n.category === activeTab
    );

    const categories: { id: NotificationCategory | "ALL", label: string }[] = [
        { id: "ALL", label: "Toutes" },
        { id: "MISSION", label: "Missions" },
        { id: "SUCCESS", label: "Succès" },
        { id: "SONGES", label: "Songes" },
        { id: "EVENT", label: "Events" },
        { id: "POLL", label: "Sondages" },
        { id: "ADMIN_ALERT", label: "Admin" },
    ];

    return (
        <div className="container max-w-4xl mx-auto py-8 px-4">
            <div className="flex flex-col md:flex-row md:items-end justify-between mb-8 gap-4">
                <div className="flex flex-col gap-1">
                    <h1 className="text-3xl font-black italic uppercase tracking-tighter text-white">
                        Centre de Notifications
                    </h1>
                    <p className="text-zinc-400">
                        {notifications.length > 0
                            ? `Vous avez ${notifications.length} notifications non lues.`
                            : "Aucune nouvelle notification."}
                    </p>
                </div>
                <div className="flex items-center gap-3">
                    {filteredNotifications.length > 0 && (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="text-zinc-400 hover:text-white hover:bg-white/5"
                            onClick={handleDismissAll}
                        >
                            <Check className="mr-2 h-4 w-4" />
                            Tout marquer
                        </Button>
                    )}
                </div>
            </div>

            {/* Filter Tabs */}
            <div className="flex items-center gap-1 mb-6 p-1 bg-zinc-900/50 border border-white/5 rounded-xl overflow-x-auto no-scrollbar">
                {categories.map((cat) => {
                    const count = cat.id === "ALL"
                        ? notifications.length
                        : notifications.filter(n => n.category === cat.id).length;

                    if (cat.id !== "ALL" && count === 0) return null;

                    return (
                        <button
                            key={cat.id}
                            onClick={() => setActiveTab(cat.id)}
                            className={cn(
                                "flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap transition-all",
                                activeTab === cat.id
                                    ? "bg-white text-black shadow-lg shadow-white/10"
                                    : "text-zinc-500 hover:text-zinc-300 hover:bg-white/5"
                            )}
                        >
                            {cat.label}
                            {count > 0 && (
                                <span className={cn(
                                    "px-1.5 py-0.5 rounded-full text-[10px]",
                                    activeTab === cat.id ? "bg-black/10 text-black" : "bg-white/10 text-zinc-400"
                                )}>
                                    {count}
                                </span>
                            )}
                        </button>
                    );
                })}
            </div>

            {loading ? (
                <div className="space-y-3">
                    {[1, 2, 3].map((i) => (
                        <div key={i} className="h-24 bg-zinc-900/50 rounded-xl animate-pulse" />
                    ))}
                </div>
            ) : filteredNotifications.length === 0 ? (
                <Card className="flex flex-col items-center justify-center py-20 bg-zinc-900/30 border-white/5 border-dashed">
                    <div className="h-16 w-16 rounded-full bg-zinc-800/50 flex items-center justify-center mb-4">
                        <CheckCircle2 className="w-8 h-8 text-emerald-500/50" />
                    </div>
                    <p className="text-zinc-500 font-medium">
                        {activeTab === "ALL"
                            ? "Vous êtes à jour !"
                            : `Aucune notification dans la catégorie ${getCategoryLabel(activeTab as NotificationCategory)}.`}
                    </p>
                    {activeTab !== "ALL" && (
                        <Button
                            variant="link"
                            className="text-primary mt-2"
                            onClick={() => setActiveTab("ALL")}
                        >
                            Voir toutes les notifications
                        </Button>
                    )}
                </Card>
            ) : (
                <div className="grid gap-3">
                    {filteredNotifications.map((notif) => (
                        <div
                            key={notif.id}
                            className="group relative flex items-start gap-4 p-4 rounded-xl bg-zinc-900/50 hover:bg-zinc-900 border border-white/5 hover:border-indigo-500/20 transition-all duration-300 shadow-sm"
                        >
                            {/* Category-colored border-left hint */}
                            <div className={cn(
                                "absolute left-0 top-4 bottom-4 w-1 rounded-r-full opacity-50",
                                notif.category === "MISSION" && "bg-blue-500",
                                notif.category === "SUCCESS" && "bg-yellow-500",
                                notif.category === "SONGES" && "bg-emerald-500",
                                notif.category === "EVENT" && "bg-purple-500",
                                notif.category === "POLL" && "bg-orange-500",
                                notif.category === "ADMIN_ALERT" && "bg-rose-500",
                                notif.category === "SYSTEM" && "bg-zinc-500",
                            )} />

                            {/* Icon Box */}
                            <div className="shrink-0 h-10 w-10 rounded-lg bg-black/40 border border-white/5 flex items-center justify-center group-hover:scale-105 transition-transform">
                                {getIcon(notif.category)}
                            </div>

                            {/* Content */}
                            <div className="flex-1 min-w-0 pt-0.5 pr-8">
                                <div className="flex items-center gap-2 mb-1">
                                    <span className="text-[10px] font-black uppercase tracking-wider text-zinc-500 group-hover:text-zinc-400">
                                        {getCategoryLabel(notif.category)}
                                    </span>
                                    <span className="text-[10px] text-zinc-600">
                                        • {format(new Date(notif.createdAt), "d MMMM 'à' HH:mm", { locale: fr })}
                                    </span>
                                </div>
                                <h3 className="font-bold text-sm text-zinc-200 group-hover:text-white transition-colors">
                                    {notif.title}
                                </h3>
                                <p className="text-sm text-zinc-400 mt-0.5 line-clamp-2 group-hover:text-zinc-300">
                                    {notif.message}
                                </p>

                                {notif.link && (
                                    <Link
                                        href={notif.link}
                                        className="inline-flex items-center gap-1.5 text-xs font-bold text-indigo-400 mt-3 hover:text-indigo-300 transition-colors"
                                    >
                                        Accéder
                                        <div className="w-4 h-4 rounded-full bg-indigo-500/10 flex items-center justify-center">
                                            <Check className="w-2.5 h-2.5" />
                                        </div>
                                    </Link>
                                )}
                            </div>

                            {/* Actions (Hover) */}
                            <div className="absolute right-2 top-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-8 w-8 text-zinc-500 hover:text-white hover:bg-white/10 rounded-full"
                                    onClick={() => handleDismiss(notif.id)}
                                    title="Marquer comme lu"
                                >
                                    <X className="h-4 w-4" />
                                </Button>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

import { AuroraBackground } from "@/components/ui/aurora-background";
import { getUserContext } from "@/server/actions/user-actions";
import { getGuildStats } from "@/server/actions/guild-stats-actions";
import { getActivityLadder } from "@/server/actions/ladder-actions";
import { getDashboardFocus } from "@/server/actions/intelligence-actions";
import { getMyOcreProgress } from "@/server/actions/ocre-actions";
import { getUserProfile } from "@/server/actions/profile-actions";
import { getUpcomingAlmanax } from "@/server/actions/resources-actions";
import { getDjPosts } from "@/server/actions/dungeon-finder-actions";
import { getStuffGalleryPage } from "@/server/actions/gallery-actions";
import { getModuleLogs } from "@/server/actions/activity-log-actions";

import { MissionsHero } from "./_components/missions-hero";
import { RecentDjPosts } from "./_components/recent-dj-posts";
import { RecentStuffGallery } from "./_components/recent-stuff-gallery";
import { AlmanaxWidget } from "./_components/almanax-widget";
import { GuildActivityFeed } from "./_components/guild-activity-feed";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
    ArrowRight,
    Users,
    InfinityIcon,
    Sparkles,
    Target,
    Bug,
    CircleDashed,
    Flame,
    ScrollText
} from "lucide-react";
import Link from "next/link";
import { AccessDenied } from "@/components/layout/access-denied";
import { OnboardingBanner } from "@/components/dashboard/onboarding-banner";
import { SignOutButton } from "@/components/auth/sign-out-button";
import { GuidePulse } from "@/components/dashboard/guide-pulse";
import { WelcomeModal } from "@/components/dashboard/welcome-modal";
import { MemberWelcomeModal } from "@/components/dashboard/member-welcome-modal";

export default async function DashboardPage({
    params,
}: {
    params: Promise<{ guildId: string }>;
}) {
    const { guildId } = await params;
    const user = await getUserContext(guildId);

    // RBAC: Must be authenticated member of the guild
    if (!user.isAuthenticated || !user.isMember) {
        return <AccessDenied />;
    }

    // CAPACITY CHECK
    if (user.isCapacityFull) {
        return (
            <AccessDenied
                title="Guilde Pleine"
                message="Désolé, cette guilde a atteint sa capacité maximale sur SigilOS (350 membres)."
                variant="lock"
                action={<SignOutButton />}
            />
        );
    }

    // Parallel Data Fetching
    const [
        weeklyLadder, 
        monthlyLadder,
        profileResult, 
        ocreProgress, 
        guildStatsResult, 
        almanaxItems,
        djPostsResult,
        stuffResult,
        guildLogs
    ] = await Promise.all([
        getActivityLadder(guildId, "weekly"),
        getActivityLadder(guildId, "monthly"),
        getUserProfile(guildId),
        user.canViewOcre ? getMyOcreProgress(guildId) : Promise.resolve({ success: false, data: undefined }),
        getGuildStats(guildId),
        getUpcomingAlmanax().catch(() => null),
        getDjPosts(guildId, { status: ["OPEN", "FULL"] }),
        getStuffGalleryPage(guildId, 1, undefined, undefined, undefined, "newest"),
        getModuleLogs(guildId, undefined, 10).catch(() => [])
    ]);

    // Derived Data
    const focusData = await getDashboardFocus(guildId, user, ocreProgress.success ? ocreProgress.data : undefined);
    const topWeeklyEntries = weeklyLadder.success && weeklyLadder.data ? weeklyLadder.data.entries : [];
    const topMonthlyEntries = monthlyLadder.success && monthlyLadder.data ? monthlyLadder.data.entries : [];
    const guildStats = guildStatsResult.success && guildStatsResult.stats ? guildStatsResult.stats : null;
    const profile = profileResult.success && profileResult.data ? profileResult.data : null;
    const activeDjPosts = djPostsResult.success ? djPostsResult.data || [] : [];
    const latestBuilds = stuffResult.success && stuffResult.data ? stuffResult.data.builds : [];

    return (
        <div className="relative w-full min-h-full pb-20">
            {/* Background Decorators */}
            <div className="fixed inset-0 z-0 pointer-events-none opacity-[0.03] bg-[radial-gradient(circle_at_50%_50%,var(--primary),transparent_70%)]" />
            <AuroraBackground className="absolute inset-0 z-0 h-full w-full pointer-events-none opacity-[0.02] dark:opacity-[0.04] saturate-100 blur-3xl scale-125 transition-opacity duration-1000" />

            {/* Modals */}
            {user.isAdmin && profile && !profile.hasSeenWelcome && (
                <WelcomeModal guildId={guildId} show={true} />
            )}
            {!user.isAdmin && profile && !profile.hasSeenWelcome && (
                <MemberWelcomeModal
                    guildId={guildId}
                    guildName={user.guildName || "ta guilde"}
                    userName={profile.pseudoDofus || user.name || "Aventurier"}
                    show={true}
                />
            )}

            <div className="relative z-10 p-4 md:p-6 space-y-8 max-w-[1600px] mx-auto">
                <header className="flex items-end justify-between gap-6 animate-in fade-in slide-in-from-top-4 duration-1000">
                    <h1 className="text-4xl md:text-5xl font-black tracking-tighter text-foreground/5 drop-shadow-sm uppercase italic select-none">
                        Dashboard
                    </h1>
                </header>

                {/* --- 1. HERO SECTION: MISSIONS --- */}
                <section className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-100">
                    <MissionsHero 
                        guildId={guildId} 
                        totalMissionsValidated={guildStats?.totalMissionsValidated}
                        totalXp={guildStats?.totalXp}
                    />
                </section>

                {/* --- 2. MAIN BENTO GRID --- */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                    
                    {/* LEFT COLUMN: Activity & Community (span 8) */}
                    <div className="lg:col-span-8 space-y-6">
                        
                        {/* Upper Row: Recruitment & Creations */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <section className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-200 min-h-[400px]">
                                <RecentDjPosts guildId={guildId} posts={activeDjPosts} />
                            </section>
                            <section className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-300 min-h-[400px]">
                                <RecentStuffGallery guildId={guildId} builds={latestBuilds} />
                            </section>
                        </div>


                        {/* Balanced Row: Songes & Monthly Overview */}
                        <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                            <div className="md:col-span-12 lg:col-span-7">
                                 <Link href={`/dashboard/${guildId}/songes`} className="block h-full">
                                    <Card className="glass-premium border-border/50 hover:border-emerald-500/20 transition-all overflow-hidden relative group h-full min-h-[160px] flex flex-col justify-center">
                                        <CardHeader className="pb-2">
                                            <CardTitle className="text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground/60 flex items-center gap-2">
                                                <InfinityIcon className="w-3 h-3 text-emerald-500" />
                                                Progression Songes
                                            </CardTitle>
                                        </CardHeader>
                                        <CardContent>
                                            <div className="flex items-end gap-2">
                                                <span className="text-4xl font-black text-foreground">{guildStats?.totalSongesCompleted || 0}</span>
                                                <span className="text-[10px] text-emerald-500 font-black uppercase mb-1">Runs complétées</span>
                                            </div>
                                        </CardContent>
                                        <div className="absolute top-0 right-0 p-4 opacity-[0.02] group-hover:scale-125 transition-transform duration-700">
                                            <InfinityIcon className="w-20 h-20 text-emerald-500" />
                                        </div>
                                    </Card>
                                </Link>
                            </div>
                            <div className="md:col-span-12 lg:col-span-5 text-center">
                                <Card className="glass-premium border-border/50 overflow-hidden p-6 text-center space-y-4 h-full flex flex-col justify-center">
                                    <p className="text-[10px] font-black uppercase text-muted-foreground/60 tracking-widest">Aperçu Mensuel</p>
                                    <div className="flex justify-center -space-x-2">
                                        {topMonthlyEntries.slice(0, 5).map((e) => (
                                            <Avatar key={e.profileId} className="h-8 w-8 ring-2 ring-background">
                                                <AvatarImage src={e.discordImage ?? undefined} />
                                                <AvatarFallback className="text-[10px] bg-muted text-muted-foreground">{e.pseudoDofus?.[0]}</AvatarFallback>
