"use client";

import { useEffect, useState } from "react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { History, ShieldCheck } from "lucide-react";
import { getActivityLogs } from "@/server/actions/activity-log-actions";

type LogEntry = Awaited<ReturnType<typeof getActivityLogs>>[number];

const ACTION_STYLES: Record<string, { color: string; label: string; icon: string }> = {
    CREATED: { color: "text-emerald-400", label: "Créé", icon: "✨" },
    UPDATED: { color: "text-cyan-400", label: "Modifié", icon: "📝" },
    DELETED: { color: "text-rose-400", label: "Supprimé", icon: "🗑" },
    STATUS_CHANGE: { color: "text-amber-400", label: "Statut", icon: "🔄" },
    RETURNED: { color: "text-emerald-400", label: "Rendu", icon: "✅" },
    PARTIAL_RETURN: { color: "text-amber-400", label: "Partiel", icon: "⏳" },
    CANCELLED: { color: "text-zinc-400", label: "Annulé", icon: "❌" },
};

function getName(a: LogEntry["actor"]) {
    return a.pseudoDofus || a.discordNickname || a.user?.name || "Membre";
}

interface ActivityTimelineProps {
    entityId: string;
    guildId: string;
    trigger?: React.ReactNode;
}

export function ActivityTimeline({ entityId, guildId, trigger }: ActivityTimelineProps) {
    const [open, setOpen] = useState(false);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (!open) return;
        setLoading(true);
        getActivityLogs(guildId, entityId)
            .then(setLogs)
            .finally(() => setLoading(false));
    }, [open, guildId, entityId]);

    return (
        <>
            {trigger ? (
                <div onClick={() => setOpen(true)} className="cursor-pointer">{trigger}</div>
            ) : (
                <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => setOpen(true)}
                    className="h-7 text-xs text-zinc-500 hover:text-cyan-400 gap-1"
                >
                    <History className="h-3 w-3" />
                    Historique
                </Button>
            )}

            <Dialog open={open} onOpenChange={setOpen}>
                <DialogContent className="max-w-md bg-zinc-950 border-white/10 text-white">
                    <DialogHeader>
                        <DialogTitle className="text-sm font-black flex items-center gap-2">
                            <ShieldCheck className="h-4 w-4 text-cyan-400" />
                            Journal d&apos;activité
                        </DialogTitle>
                        <p className="text-[11px] text-zinc-500 mt-1">
                            Enregistrement immuable — ne peut être ni modifié ni supprimé.
                        </p>
                    </DialogHeader>

                    <div className="max-h-[400px] overflow-y-auto space-y-0 py-2">
                        {loading ? (
                            <div className="text-center py-8 text-zinc-500 text-xs">Chargement...</div>
                        ) : logs.length === 0 ? (
                            <div className="text-center py-8 text-zinc-500 text-xs">Aucun historique.</div>
                        ) : (
                            logs.map((log, i) => {
                                const style = ACTION_STYLES[log.action] || ACTION_STYLES.CREATED;
                                const name = getName(log.actor);
                                const isLast = i === logs.length - 1;

                                return (
                                    <div key={log.id} className="flex gap-3 relative">
                                        {/* Timeline line */}
                                        {!isLast && (
                                            <div className="absolute left-[11px] top-8 bottom-0 w-px bg-white/5" />
                                        )}

                                        {/* Dot */}
                                        <div className="shrink-0 mt-1.5">
                                            <div className={`w-[22px] h-[22px] rounded-full border ${style.color.replace("text-", "border-")}/30 bg-zinc-900 flex items-center justify-center text-[10px]`}>
                                                {style.icon}
                                            </div>
                                        </div>

                                        {/* Content */}
                                        <div className="flex-1 pb-4">
                                            <div className="flex items-center gap-2">
                                                <span className={`text-xs font-bold ${style.color}`}>{style.label}</span>
                                                <span className="text-[10px] text-zinc-600">
                                                    {new Date(log.createdAt).toLocaleDateString("fr-FR", {
                                                        day: "numeric",
                                                        month: "short",
                                                        hour: "2-digit",
                                                        minute: "2-digit",
                                                    })}
                                                </span>
                                            </div>
                                            <p className="text-[11px] text-zinc-300 mt-0.5">{log.summary}</p>
                                            <div className="flex items-center gap-1.5 mt-1">
                                                <Avatar className="h-4 w-4 rounded">
                                                    <AvatarImage src={log.actor.user?.image || undefined} />
                                                    <AvatarFallback className="text-[7px] bg-zinc-800">
                                                        {name.slice(0, 2).toUpperCase()}
                                                    </AvatarFallback>
                                                </Avatar>
                                                <span className="text-[10px] text-zinc-500">{name}</span>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })
                        )}
                    </div>
                </DialogContent>
            </Dialog>
        </>
    );
}

"use client";

import { useEffect, useState } from "react";
import { getMyAvailability } from "@/server/actions/availability-actions";
import { Clock } from "lucide-react";
import { getISOWeek, getYear, startOfWeek, addWeeks } from "date-fns";

const JOURS = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"] as const;
type Jour = (typeof JOURS)[number];

const JOUR_COURTS: Record<string, string> = {
    lundi: "Lun", mardi: "Mar", mercredi: "Mer", jeudi: "Jeu",
    vendredi: "Ven", samedi: "Sam", dimanche: "Dim",
};

type SlotColors = { pill: string };
const SLOT_STYLE: Record<string, SlotColors & { emoji: string; label: string }> = {
    matin: { pill: "bg-orange-500/20 text-orange-300 border-orange-500/30", emoji: "🌅", label: "Matin" },
    midi: { pill: "bg-amber-500/20 text-amber-300 border-amber-500/30", emoji: "☀️", label: "Aprèm" },
    soir: { pill: "bg-violet-500/20 text-violet-300 border-violet-500/30", emoji: "🌙", label: "Soir" },
    nuit: { pill: "bg-indigo-500/20 text-indigo-300 border-indigo-500/30", emoji: "🌃", label: "Nuit" },
};

/** Résout le contenu d'un GlobalAvailability ou AvailabilityMap en map simple jour→slots[] */
function resolveSimpleMap(raw: any): Record<string, string[]> {
    if (!raw || typeof raw !== "object") return {};

    // Nouveau format GlobalAvailability : { template: {...}, weeks: {...} }
    if ("template" in raw || "weeks" in raw) {
        const now = new Date();
        const monday = startOfWeek(now, { weekStartsOn: 1 });
        const weekKey = `${getYear(monday)}-W${getISOWeek(monday)}`;

        // Priorité : semaine courante > template
        const weekData = raw.weeks?.[weekKey] || raw.template || {};
        return weekData as Record<string, string[]>;
    }

    // Ancien format direct : { lundi: ["matin","soir"], ... }
    return raw as Record<string, string[]>;
}

interface AvailabilityPreviewProps {
    guildId: string;
}

export function AvailabilityPreview({ guildId }: AvailabilityPreviewProps) {
    const [map, setMap] = useState<Record<string, string[]> | null>(null);
    const [loaded, setLoaded] = useState(false);

    useEffect(() => {
        getMyAvailability(guildId).then((res) => {
            if (res.success) setMap(resolveSimpleMap(res.data));
            setLoaded(true);
        });
    }, [guildId]);

    if (!loaded) return null;

    const activeDays = JOURS.filter((j) => (map?.[j]?.length ?? 0) > 0);

    if (activeDays.length === 0) {
        return (
            <div className="flex items-center gap-2 rounded-lg border border-white/8 bg-white/[0.02] px-3 py-2">
                <Clock className="h-3.5 w-3.5 text-zinc-600 shrink-0" />
                <p className="text-xs text-zinc-600 italic">
                    Aucune dispo renseignée dans ton profil —{" "}
                    <a
                        href={`/dashboard/${guildId}/profile`}
                        className="underline hover:text-zinc-400 transition-colors"
                        target="_blank"
                    >
                        compléter le profil
                    </a>
                </p>
            </div>
        );
    }

    return (
        <div className="rounded-lg border border-white/8 bg-white/[0.02] px-3 py-2.5 space-y-2">
            <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest text-zinc-500">
                <Clock className="h-3 w-3" />
                Dispos du profil (semaine courante)
            </div>
            <div className="flex flex-wrap gap-y-1.5 gap-x-4">
                {activeDays.map((jour) => (
                    <div key={jour} className="flex items-center gap-1.5">
                        <span className="text-[10px] font-black text-zinc-400 w-7">{JOUR_COURTS[jour]}</span>
                        <div className="flex gap-1 flex-wrap">
                            {(map![jour] || []).map((slot) => {
                                const style = SLOT_STYLE[slot] || {
                                    pill: "bg-zinc-700/40 text-zinc-400 border-zinc-600/40",
                                    emoji: "🕐",
                                    label: slot,
                                };
                                return (
                                    <span
                                        key={slot}
                                        className={`text-[9px] px-1.5 py-0.5 rounded border font-bold whitespace-nowrap ${style.pill}`}
                                    >
                                        {style.emoji} {style.label}
                                    </span>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Check, X, Clock, ArrowRight, Coins, History, Package } from "lucide-react";
import { type LoanWithProfiles } from "@/server/actions/loan-actions";
import { LOAN_TYPE_LABELS, LOAN_STATUS_LABELS } from "@/server/actions/services-constants";
import { markLoanReturned, cancelLoan } from "@/server/actions/loan-actions";
import { ProofThumbnail } from "./proof-thumbnail";
import { ActivityTimeline } from "./activity-timeline";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { useState } from "react";
import Image from "next/image";

const STATUS_COLORS: Record<string, string> = {
    ACTIVE: "border-cyan-500/30 bg-cyan-500/10 text-cyan-400",
    RETURNED: "border-emerald-500/30 bg-emerald-500/10 text-emerald-400",
    PARTIAL: "border-amber-500/30 bg-amber-500/10 text-amber-400",
    CANCELLED: "border-zinc-500/30 bg-zinc-500/10 text-zinc-400",
};

interface LoanCardProps {
    loan: LoanWithProfiles;
    guildId: string;
    currentProfileId?: string;
    isAdmin?: boolean;
}

function getName(p: { pseudoDofus?: string | null; discordNickname?: string | null; user?: { name?: string | null } }) {
    return p.pseudoDofus || p.discordNickname || p.user?.name || "Membre";
}

export function LoanCard({ loan, guildId, currentProfileId, isAdmin }: LoanCardProps) {
    const router = useRouter();
    const [returnLoading, setReturnLoading] = useState(false);
    const [cancelLoading, setCancelLoading] = useState(false);
    const isLender = loan.lender.id === currentProfileId;
    const isBorrower = loan.borrower.id === currentProfileId;
    const canManage = isLender || isAdmin;
    const isActive = loan.status === "ACTIVE" || loan.status === "PARTIAL";

    const handleReturn = async () => {
        if (!confirm("Marquer ce prêt comme entièrement rendu ?")) return;
        setReturnLoading(true);
        const result = await markLoanReturned(guildId, loan.id, undefined, false);
        if (result.success) {
            toast.success("Prêt marqué comme rendu !");
            router.refresh();
        } else {
            toast.error(result.error || "Erreur.");
        }
        setReturnLoading(false);
    };

    const handleCancel = async () => {
        if (!confirm("Annuler ce prêt ?")) return;
        setCancelLoading(true);
        const result = await cancelLoan(guildId, loan.id);
        if (result.success) {
            toast.success("Prêt annulé.");
            router.refresh();
        } else {
            toast.error(result.error || "Erreur.");
        }
        setCancelLoading(false);
    };

    const lenderName = getName(loan.lender);
    const borrowerName = getName(loan.borrower);

    return (
        <div className={`rounded-xl border ${isActive ? "border-white/12 hover:border-cyan-500/25" : "border-white/5 opacity-70"} bg-zinc-900/80 hover:bg-zinc-800/80 p-4 transition-all duration-300 space-y-3 shadow-sm`}>
            {/* Header: Status + Type */}
            <div className="flex items-center justify-between">
                <Badge variant="outline" className={`${STATUS_COLORS[loan.status]} text-[10px] font-black uppercase tracking-wider px-2 py-0.5`}>
                    {LOAN_STATUS_LABELS[loan.status]}
                </Badge>
                <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-wider">
                    {LOAN_TYPE_LABELS[loan.type]}
                </span>
            </div>

            {/* Description */}
            <p className="text-base font-black text-white leading-snug">{loan.description}</p>

            {/* Amount */}
            {loan.amount && (
                <div className="flex items-center gap-2 text-sm text-amber-400">
                    <Coins className="h-4 w-4 shrink-0" />
                    <span className="font-black text-base">{loan.amount}</span>
                </div>
            )}

            {/* Lender → Borrower */}
            <div className="flex items-center gap-2 py-2">
                <div className="flex items-center gap-2">
                    <Avatar className="h-6 w-6 rounded-md border border-white/10">
                        <AvatarImage src={loan.lender.user?.image || undefined} />
                        <AvatarFallback className="text-[9px] bg-zinc-800">{lenderName.slice(0, 2).toUpperCase()}</AvatarFallback>
                    </Avatar>
                    <span className="text-xs font-bold text-emerald-400">{lenderName}</span>
                </div>
                <ArrowRight className="h-3 w-3 text-zinc-600" />
                <div className="flex items-center gap-2">
                    <Avatar className="h-6 w-6 rounded-md border border-white/10">
                        <AvatarImage src={loan.borrower.user?.image || undefined} />
                        <AvatarFallback className="text-[9px] bg-zinc-800">{borrowerName.slice(0, 2).toUpperCase()}</AvatarFallback>
                    </Avatar>
                    <span className="text-xs font-bold text-orange-400">{borrowerName}</span>
                </div>
            </div>

            {/* Due date */}
            {loan.dueDate && (
                <div className="flex items-center gap-2 text-[11px] text-zinc-400">
                    <Clock className="h-3 w-3 shrink-0" />
                    <span>Échéance : {new Date(loan.dueDate).toLocaleDateString("fr-FR")}</span>
                </div>
            )}

            {/* Item lié (Stuff/Ressources) */}
            {loan.linkedItemName && (
                <div className="flex items-center gap-3 rounded-xl border border-white/10 bg-white/[0.04] px-4 py-3">
                    {loan.linkedItemIconUrl ? (
                        <div className="relative h-12 w-12 shrink-0">
                            <Image src={loan.linkedItemIconUrl} alt={loan.linkedItemName} fill className="object-contain" />
                        </div>
                    ) : (
                        <Package className="h-6 w-6 text-zinc-500 shrink-0" />
                    )}
                    <div className="min-w-0">
                        <p className="text-sm font-black text-white truncate">{loan.linkedItemName}</p>
                        <p className="text-xs text-zinc-500">Item associé</p>
                    </div>
                </div>
            )}

            {/* Proof principale — taille card */}
            {loan.proofUrl && (
                <div className="rounded-lg overflow-hidden border border-white/10">
                    <ProofThumbnail src={loan.proofUrl} alt="Preuve de prêt" size="card" />
                </div>
            )}

            {/* Proof retour + Timeline */}
            <div className="flex items-center gap-2">
                <ProofThumbnail src={loan.returnProofUrl} alt="Preuve de retour" />
                <div className="flex-1" />
                <ActivityTimeline entityId={loan.id} guildId={guildId} />
            </div>

            {/* Actions */}
            {canManage && isActive && (
                <div className="flex items-center gap-2 pt-2 border-t border-white/5">
                    <Button
                        size="sm"
                        onClick={handleReturn}
                        disabled={returnLoading || cancelLoading}
                        className="h-7 text-xs bg-emerald-600/20 text-emerald-400 hover:bg-emerald-600/30 border border-emerald-500/20"
                    >
                        {returnLoading
                            ? <span className="h-3 w-3 rounded-full border-2 border-emerald-400 border-t-transparent animate-spin" />
                            : <Check className="h-3 w-3 mr-1" />}
                        Rendu
                    </Button>
                    <Button
                        size="sm"
                        variant="ghost"
                        onClick={handleCancel}
                        disabled={returnLoading || cancelLoading}
                        className="h-7 text-xs text-zinc-500 hover:text-rose-400 ml-auto"
                    >
                        {cancelLoading
                            ? <span className="h-3 w-3 rounded-full border-2 border-zinc-500 border-t-transparent animate-spin" />
                            : <X className="h-3 w-3" />}
                    </Button>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog";

interface ProofThumbnailProps {
    src: string | null | undefined;
    alt?: string;
    size?: "sm" | "md" | "card";
}

export function ProofThumbnail({ src, alt = "Preuve", size = "sm" }: ProofThumbnailProps) {
    const [open, setOpen] = useState(false);

    if (!src) return null;

    const sizeClasses =
        size === "card" ? "h-28 w-full" :
            size === "md" ? "h-16 w-16" :
                "h-10 w-10";

    return (
        <>
            <button
                onClick={() => setOpen(true)}
                className={`${sizeClasses} relative rounded-lg overflow-hidden border border-white/10 hover:border-cyan-500/50 transition-all cursor-pointer group shrink-0`}
            >
                <img
                    src={src}
                    alt={alt}
                    className="absolute inset-0 w-full h-full object-cover group-hover:scale-110 transition-transform"
                />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
                    <span className="text-white opacity-0 group-hover:opacity-100 text-[10px] font-bold">🔍</span>
                </div>
            </button>

            <Dialog open={open} onOpenChange={setOpen}>
                <DialogContent className="max-w-2xl bg-zinc-950 border-white/10 p-2">
                    <div className="relative w-full aspect-video">
                        <img
                            src={src}
                            alt={alt}
                            className="absolute inset-0 w-full h-full object-contain rounded-lg"
                        />
                    </div>
                </DialogContent>
            </Dialog>
        </>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Loader2, Pencil, Swords, ScrollText, CheckSquare, MessageSquare, Gamepad2 } from "lucide-react";
import { updateServiceListing } from "@/server/actions/service-actions";
import { type ServiceListingWithProfile } from "@/server/actions/service-actions";
import { toast } from "sonner";
import Image from "next/image";
import { getAchievementIconUrl } from "@/lib/achievement-icon";

interface ServiceEditDialogProps {
    listing: ServiceListingWithProfile;
    guildId: string;
}

export function ServiceEditDialog({ listing, guildId }: ServiceEditDialogProps) {
    const router = useRouter();
    const [open, setOpen] = useState(false);
    const [loading, setLoading] = useState(false);

    const [title, setTitle] = useState(listing.title);
    const [price, setPrice] = useState(listing.price || "");
    const [availability, setAvailability] = useState(listing.availability || "");
    // Parse existing contactMethod to checkboxes
    const existingContact = listing.contactMethod || "";
    const [contactDiscord, setContactDiscord] = useState(
        existingContact.includes("Discord") || (!existingContact.includes("En jeu") && existingContact !== "")
    );
    const [contactIngame, setContactIngame] = useState(existingContact.includes("En jeu"));

    const handleOpen = () => {
        // Reset to current values
        setTitle(listing.title);
        setPrice(listing.price || "");
        setAvailability(listing.availability || "");
        const c = listing.contactMethod || "";
        setContactDiscord(c.includes("Discord") || (!c.includes("En jeu") && c !== ""));
        setContactIngame(c.includes("En jeu"));
        setOpen(true);
    };

    const handleSave = async () => {
        if (!title.trim()) {
            toast.error("Le titre est requis.");
            return;
        }
        setLoading(true);
        try {
            const result = await updateServiceListing(guildId, listing.id, {
                title: title.trim(),
                price: price.trim() || undefined,
                availability: availability.trim() || undefined,
                contactMethod: [contactDiscord && "Discord", contactIngame && "En jeu"].filter(Boolean).join(" + ") || undefined,
            });
            if (result.success) {
                toast.success("Annonce mise à jour !");
                setOpen(false);
                router.refresh();
            } else {
                toast.error(result.error || "Erreur.");
            }
        } catch {
            toast.error("Erreur inattendue.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <Button
                size="icon"
                variant="ghost"
                onClick={handleOpen}
                className="h-7 w-7 text-zinc-500 hover:text-cyan-400"
                title="Modifier l'annonce"
            >
                <Pencil className="h-3.5 w-3.5" strokeWidth={2.5} />
            </Button>

            <Dialog open={open} onOpenChange={setOpen}>
                <DialogContent className="max-w-lg bg-zinc-950 border border-white/10 shadow-2xl rounded-2xl text-white p-0 gap-0">
                    <div className="p-5 pb-4 border-b border-white/5 bg-slate-900/30">
                        <DialogTitle className="text-base font-black flex items-center gap-3">
                            <div className="w-8 h-8 rounded-xl bg-cyan-500/20 border border-cyan-500/30 flex items-center justify-center shrink-0 shadow-inner">
                                <Pencil className="w-4 h-4 text-cyan-400" strokeWidth={2.5} />
                            </div>
                            Modifier l'annonce
                        </DialogTitle>
                    </div>

                    <div className="p-6 space-y-5">

                        {/* Contexte en lecture seule — donjon / succès / quête */}
                        {(listing.dungeonName || listing.questName) && (
                            <div className="rounded-lg border border-white/8 bg-white/[0.025] p-3 space-y-2">
                                {listing.dungeonName && (
                                    <div className="flex items-center gap-2">
                                        {listing.dungeonImageUrl ? (
                                            <div className="relative h-8 w-8 rounded-lg shrink-0 overflow-hidden border border-cyan-500/20 shadow-inner">
                                                <Image src={listing.dungeonImageUrl} alt={listing.dungeonName} fill className="object-cover" />
                                            </div>
                                        ) : (
                                            <div className="h-8 w-8 rounded-lg shrink-0 bg-cyan-500/10 flex items-center justify-center border border-cyan-500/20 shadow-inner">
                                                <Swords className="h-4 w-4 text-cyan-400" />
                                            </div>
                                        )}
                                        <div>
                                            <p className="text-xs font-bold text-cyan-300">{listing.dungeonName}</p>
                                            <p className="text-[10px] text-zinc-500">Donjon sélectionné</p>
                                        </div>
                                    </div>
                                )}
                                {listing.selectedAchievementNames && (listing.selectedAchievementNames as string[]).length > 0 && (
                                    <div className="flex flex-wrap gap-1.5 pt-2">
                                        {(listing.selectedAchievementNames as string[]).map((name) => {
                                            const slug = name.toLowerCase()
                                                .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
                                                .replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");
                                            const iconUrl = getAchievementIconUrl(slug);
                                            return (
                                                <span key={name} className="flex items-center gap-1.5 text-[10px] px-2 py-1 rounded-lg bg-cyan-500/10 border border-cyan-500/20 text-cyan-300 font-bold">
                                                    {iconUrl && (
                                                        <div className="relative h-4 w-4 shrink-0">
                                                            <Image
                                                                src={iconUrl}
                                                                alt={name}
                                                                fill
                                                                className="object-contain"
                                                                onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
                                                            />
                                                        </div>
                                                    )}
                                                    {name}
                                                </span>
                                            );
                                        })}
                                    </div>
                                )}
                                {listing.questName && (
                                    <div className="flex items-center gap-2">
                                        <div className="h-8 w-8 rounded shrink-0 bg-violet-500/10 flex items-center justify-center border border-violet-500/20">
                                            <ScrollText className="h-4 w-4 text-violet-400" />
                                        </div>
                                        <div>
                                            <p className="text-xs font-bold text-violet-300">{listing.questName}</p>
                                            <p className="text-[10px] text-zinc-500">Quête sélectionnée</p>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}
                        <div className="space-y-2">
                            <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Titre *</Label>
                            <Input
                                value={title}
                                onChange={(e) => setTitle(e.target.value)}
                                className="bg-white/5 border-white/10"
                                maxLength={100}
                            />
                        </div>



                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-2">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Tarif</Label>
                                <Input
                                    value={price}
                                    onChange={(e) => setPrice(e.target.value)}
                                    className="bg-white/5 border-white/10"
                                    placeholder="Ex: 500k kamas"
                                    maxLength={100}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Disponibilité</Label>
                                <Input
                                    value={availability}
                                    onChange={(e) => setAvailability(e.target.value)}
                                    className="bg-white/5 border-white/10"
                                    placeholder="Ex: Soir / WE"
                                    maxLength={100}
                                />
                            </div>
                        </div>

                        {/* Contact — checkboxes */}
                        <div className="space-y-2">
                            <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Contact préféré</Label>
                            <div className="flex gap-3">
                                <button
                                    type="button"
                                    onClick={() => setContactDiscord(v => !v)}
                                    className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-bold transition-all ${contactDiscord
                                        ? "border-indigo-500/60 bg-indigo-500/15 text-indigo-300"
                                        : "border-white/10 bg-white/5 text-zinc-500 hover:border-white/20"
                                        }`}
                                >
                                    <MessageSquare className="h-3.5 w-3.5" />
                                    Ping Discord
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setContactIngame(v => !v)}
                                    className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-bold transition-all ${contactIngame
                                        ? "border-cyan-500/60 bg-cyan-500/15 text-cyan-300"
                                        : "border-white/10 bg-white/5 text-zinc-500 hover:border-white/20"
                                        }`}
                                >
                                    <Gamepad2 className="h-3.5 w-3.5" />
                                    Ping en jeu
                                </button>
                            </div>
                        </div>
                    </div>

                    <div className="px-6 pb-6 flex gap-3 border-t border-white/5 pt-5 bg-slate-900/30">
                        <Button
                            variant="ghost"
                            onClick={() => setOpen(false)}
                            className="flex-1 border border-white/10 bg-white/5 text-slate-300 hover:text-white hover:bg-white/10 font-bold h-12 transition-all"
                        >
                            Annuler
                        </Button>
                        <Button
                            onClick={handleSave}
                            disabled={loading || !title.trim()}
                            className="flex-1 bg-cyan-600 hover:bg-cyan-500 text-white font-black h-12 shadow-md shadow-cyan-900/20"
                        >
                            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Enregistrer"}
                        </Button>
                    </div>
                </DialogContent>
            </Dialog>
        </>
    );
}

"use client";

import { useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Loader2, Plus, X, Sword, ScrollText, Hammer, Crown, Wrench, MessageSquare, Gamepad2 } from "lucide-react";
import { createServiceListing } from "@/server/actions/service-actions";
import { ServiceCategory } from "@prisma/client";
import { toast } from "sonner";
import { DungeonPicker, type DungeonSelection } from "./dungeon-picker";
import { QuestPicker, type QuestSelection } from "./quest-picker";
import { DofusItemSearch } from "./dofus-item-search";
import { DOFUS_JOBS, type DofusItem } from "@/lib/dofusdude-client";
import { DOFUS_JOBS as _ALL_JOBS_MAP, JOB_CATEGORIES } from "@/lib/dofus-assets";
import Image from "next/image";
import { AvailabilityPreview } from "./availability-preview";

// Forgemagie-only jobs (flat list)
export const FM_JOBS = (_ALL_JOBS_MAP[JOB_CATEGORIES.FORGEMAGIE] as ReadonlyArray<{ id: string; name: string; icon: string }>)
    .map((j, i) => ({ id: i + 1, name: j.name, iconUrl: j.icon }));

// ---------------------------------------------------------------------------
// TYPES & CONSTANTS
// ---------------------------------------------------------------------------

interface ServiceFormProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    guildId: string;
}

type PriceTier = { label: string; price: string };
type OcrePack = "boss" | "boss_archi" | "archi";

const OCRE_PACKS: { value: OcrePack; label: string }[] = [
    { value: "boss", label: "Pack Boss" },
    { value: "boss_archi", label: "Pack Boss + Archi" },
    { value: "archi", label: "Pack Archi" },
];

// Catégories affichées (AUTRE supprimé per spec)
const VISIBLE_CATEGORIES: { key: ServiceCategory; label: string; icon: React.ReactNode; color: string; accent: string }[] = [
    { key: "PASSAGE_DONJON", label: "Donjon", icon: <Sword className="h-5 w-5" />, color: "from-cyan-500/20 to-transparent", accent: "border-cyan-500/60 bg-cyan-500/15 text-cyan-300" },
    { key: "FORGEMAGIE", label: "Forgemagie", icon: <Hammer className="h-5 w-5" />, color: "from-amber-500/20 to-transparent", accent: "border-amber-500/60 bg-amber-500/15 text-amber-300" },
    { key: "METIER", label: "Métier", icon: <Wrench className="h-5 w-5" />, color: "from-emerald-500/20 to-transparent", accent: "border-emerald-500/60 bg-emerald-500/15 text-emerald-300" },
    { key: "QUETE", label: "Quête", icon: <ScrollText className="h-5 w-5" />, color: "from-violet-500/20 to-transparent", accent: "border-violet-500/60 bg-violet-500/15 text-violet-300" },
    { key: "OCRE", label: "Quête Ocre 🥚", icon: <Crown className="h-5 w-5" />, color: "from-yellow-500/20 to-transparent", accent: "border-yellow-500/60 bg-yellow-500/15 text-yellow-300" },
];

const CATEGORY_ACCENT: Record<ServiceCategory, string> = {
    PASSAGE_DONJON: "border-cyan-500/60 bg-cyan-500/10 text-cyan-300",
    FORGEMAGIE: "border-amber-500/60 bg-amber-500/10 text-amber-300",
    METIER: "border-emerald-500/60 bg-emerald-500/10 text-emerald-300",
    QUETE: "border-violet-500/60 bg-violet-500/10 text-violet-300",
    OCRE: "border-yellow-500/60 bg-yellow-500/10 text-yellow-300",
    AUTRE: "border-zinc-500/60 bg-zinc-500/10 text-zinc-300",
};

// ---------------------------------------------------------------------------
// MAIN COMPONENT
// ---------------------------------------------------------------------------

export function ServiceForm({ open, onOpenChange, guildId }: ServiceFormProps) {
    const router = useRouter();
    const [loading, setLoading] = useState(false);

    // Common
    const [category, setCategory] = useState<ServiceCategory>("PASSAGE_DONJON");
    const [title, setTitle] = useState("");
    const [description, setDescription] = useState("");
    const [price, setPrice] = useState("");
    const [availability, setAvailability] = useState("");
    const [contactDiscord, setContactDiscord] = useState(true);
    const [contactIngame, setContactIngame] = useState(false);

    // PASSAGE_DONJON
    const [dungeonSelection, setDungeonSelection] = useState<DungeonSelection | null>(null);
    const [priceTiers, setPriceTiers] = useState<PriceTier[]>([]);

    // QUETE
    const [questSelection, setQuestSelection] = useState<QuestSelection | null>(null);

    // FORGEMAGIE
    const [selectedJobs, setSelectedJobs] = useState<string[]>([]);
    const [fmItem, setFmItem] = useState("");
    const [passTrans, setPassTrans] = useState("");
    const [commandeExo, setCommandeExo] = useState(false); // OUI/NON toggle
    const [fmLinkedItem, setFmLinkedItem] = useState<DofusItem | null>(null);

    // OCRE
    const [ocrePack, setOcrePack] = useState<OcrePack>("boss");
    const [ocrePrice, setOcrePrice] = useState("");

    // METIER
    const [metierMode, setMetierMode] = useState<"craft" | "pack">("craft");
    const [selectedMetierJob, setSelectedMetierJob] = useState<string>("");

    const resetForm = () => {
        setCategory("PASSAGE_DONJON");
        setTitle(""); setDescription(""); setPrice(""); setAvailability("");
        setContactDiscord(true); setContactIngame(false);
        setDungeonSelection(null); setPriceTiers([]);
        setQuestSelection(null);
        setSelectedJobs([]); setFmItem(""); setPassTrans(""); setCommandeExo(false); setFmLinkedItem(null);
        setOcrePack("boss"); setOcrePrice("");
        setMetierMode("craft"); setSelectedMetierJob("");
    };

    function addPriceTier() {
        if (priceTiers.length >= 6) return;
        setPriceTiers([...priceTiers, { label: "", price: "" }]);
    }
    function updatePriceTier(i: number, f: keyof PriceTier, v: string) {
        const n = [...priceTiers]; n[i] = { ...n[i], [f]: v }; setPriceTiers(n);
    }
    function removePriceTier(i: number) { setPriceTiers(priceTiers.filter((_, idx) => idx !== i)); }

    function toggleJob(name: string) {
        setSelectedJobs((prev) => prev.includes(name) ? prev.filter((j) => j !== name) : [...prev, name]);
    }

    const handleSubmit = async () => {
        if (!title.trim()) { toast.error("Le titre est requis."); return; }
        setLoading(true);
        try {
            const toJson = (v: unknown) => v as import("@prisma/client").Prisma.InputJsonValue;
            // Résoudre les labels combo (JSON d'IDs → noms lisibles)
            const allAchievements = dungeonSelection?.dungeon.achievements ?? [];
            const resolvedTiers = priceTiers.map(t => {
                try {
                    const ids = JSON.parse(t.label);
                    if (Array.isArray(ids) && ids.every((id: unknown) => typeof id === "string")) {
                        const names = allAchievements
                            .filter(a => ids.includes(a.id))
                            .map(a => a.challenge.name);
                        return { label: names.length > 0 ? names.join(" + ") : "Combo", price: t.price };
                    }
                } catch { /* label texte normal */ }
                return t;
            });
            const validTiers = resolvedTiers.filter((t) => t.label && t.price);

            const result = await createServiceListing(guildId, {
                category,
                title: title.trim(),
                description: description.trim() || null,
                price: (category === "OCRE" ? OCRE_PACKS.find(p => p.value === ocrePack)?.label : price.trim()) || null,
                availability: availability.trim() || null,
                contactMethod: [contactDiscord && "Discord", contactIngame && "En jeu"].filter(Boolean).join(" + ") || null,
                publishToDiscord: true,
                dungeonId: dungeonSelection?.dungeon.id || null,
                dungeonName: dungeonSelection?.dungeon.name || null,
                dungeonImageUrl: dungeonSelection?.dungeon.imageUrl || null,
                selectedAchievements: dungeonSelection?.selectedAchievementIds?.length ? dungeonSelection.selectedAchievementIds : null,
                selectedAchievementNames: dungeonSelection?.selectedAchievementIds?.length && dungeonSelection.dungeon.achievements.length
                    ? dungeonSelection.dungeon.achievements
                        .filter(a => dungeonSelection.selectedAchievementIds.includes(a.id))
                        .map(a => a.challenge.name)
                    : null,
                questId: questSelection?.questId ? String(questSelection.questId) : null,
                questName: questSelection?.questName || null,
                dofusItemAnkamaId: fmLinkedItem?.ankamaId || null,
                dofusItemName: fmLinkedItem?.name || null,
                dofusItemIconUrl: fmLinkedItem?.iconUrl || null,
                priceTiers: category === "OCRE" && ocrePrice.trim()
                    ? toJson([{ label: OCRE_PACKS.find(p => p.value === ocrePack)?.label ?? ocrePack, price: ocrePrice.trim() }]) as unknown as PriceTier[]
                    : validTiers.length ? toJson(validTiers) as unknown as PriceTier[] : null,
                craftMeta: category === "FORGEMAGIE"
                    ? toJson({ fmItems: fmItem || undefined, passTrans: passTrans || undefined, commandeExo: commandeExo ? "oui" : undefined }) as unknown as { fmItems?: string; passTrans?: string; commandeExo?: string }
                    : null,
                professions: selectedJobs.length ? selectedJobs : null,
            });

            if (result.success) {
                toast.success("Annonce publiée !");
                resetForm(); onOpenChange(false); router.refresh();
            } else {
                toast.error(result.error || "Erreur lors de la publication.");
            }
        } catch {
            toast.error("Erreur inattendue.");
        } finally {
            setLoading(false);
        }
    };

    const cat = VISIBLE_CATEGORIES.find(c => c.key === category);

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-xl bg-zinc-950 border border-white/10 shadow-2xl rounded-2xl text-white max-h-[92vh] overflow-y-auto p-0 gap-0">
                {/* Gradient header */}
                <div className={`bg-gradient-to-r ${cat?.color ?? ""} px-6 pt-6 pb-4 border-b border-white/5`}>
                    <DialogTitle className="text-lg font-black flex items-center gap-2.5">
                        <span className={`p-1.5 rounded-lg border shadow-inner ${cat?.accent ?? ""}`}>{cat?.icon}</span>
                        Publier un service
                    </DialogTitle>

                    {/* Category pills */}
                    <div className="flex flex-wrap gap-2 mt-4">
                        {VISIBLE_CATEGORIES.map((c) => (
                            <button
                                key={c.key}
                                onClick={() => { setCategory(c.key); setDungeonSelection(null); setQuestSelection(null); }}
                                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold border transition-all duration-200 ${category === c.key
                                    ? c.accent
                                    : "border-white/10 bg-white/5 text-zinc-400 hover:border-white/20 hover:text-zinc-200"
                                    }`}
                            >
                                {c.icon}
                                {c.label}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="space-y-5 px-6 py-5">
                    {/* === PASSAGE_DONJON specific === */}
                    {category === "PASSAGE_DONJON" && (
                        <div className="space-y-2">
                            <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Donjon</Label>
                            <DungeonPicker guildId={guildId} onSelect={setDungeonSelection} value={dungeonSelection} />
                        </div>
                    )}

                    {/* === QUETE specific === */}
                    {category === "QUETE" && (
                        <div className="space-y-2">
                            <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Quête <span className="text-violet-400 font-normal">via DofusDB</span></Label>
                            <QuestPicker onSelect={setQuestSelection} value={questSelection} showSubCategory />
                        </div>
                    )}

                    {/* === OCRE specific === */}
                    {category === "OCRE" && (
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Pack proposé</Label>
                                <div className="flex gap-2">
                                    {OCRE_PACKS.map((p) => (
                                        <button
                                            key={p.value}
                                            type="button"
                                            onClick={() => setOcrePack(p.value)}
                                            className={`flex-1 px-3 py-2.5 rounded-lg text-xs font-bold border transition-all ${ocrePack === p.value
                                                ? "border-yellow-500/60 bg-yellow-500/15 text-yellow-300"
                                                : "border-white/10 bg-white/5 text-zinc-400 hover:border-white/20"
                                                }`}
                                        >
                                            {p.label}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            {/* Tarif kamas */}
                            <div className="space-y-2">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Tarif <span className="text-zinc-600 font-normal">(kamas — optionnel)</span></Label>
                                <div className="relative">
                                    <div className="absolute left-3 top-1/2 -translate-y-1/2 flex items-center">
                                        <img src="/assets/icons/kama.png" alt="kamas" className="w-4 h-4 object-contain" />
                                    </div>
                                    <Input
                                        value={ocrePrice}
                                        onChange={(e) => setOcrePrice(e.target.value)}
                                        placeholder="Ex: 50M ou 50 000 000"
                                        className="bg-white/5 border-white/10 pl-9 font-semibold"
                                        maxLength={50}
                                    />
                                </div>
                                <p className="text-[10px] text-zinc-600">Affiché sur ta carte de service.</p>
                            </div>
                        </div>
                    )}

                    {/* === FORGEMAGIE specific === */}
                    {category === "FORGEMAGIE" && (
                        <div className="space-y-4">
                            {/* Jobs FM avec icônes locales */}
                            <div className="space-y-2">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Métiers FM</Label>
                                <div className="grid grid-cols-3 gap-2">
                                    {FM_JOBS.map((job) => (
                                        <button
                                            key={job.id}
                                            type="button"
                                            onClick={() => toggleJob(job.name)}
                                            title={job.name}
                                            className={`flex flex-col items-center gap-1 p-2 rounded-lg border transition-all text-[10px] font-medium ${selectedJobs.includes(job.name)
                                                ? "border-amber-500/60 bg-amber-500/15 text-amber-300"
                                                : "border-white/8 bg-white/3 text-zinc-500 hover:border-white/20 hover:text-zinc-300"
                                                }`}
                                        >
                                            <div className="relative h-10 w-10">
                                                <Image
                                                    src={job.iconUrl}
                                                    alt={job.name}
                                                    fill
                                                    className="object-contain"
                                                    onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
                                                />
                                            </div>
                                            <span className="leading-tight text-center">{job.name}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Item lié (optionnel) */}
                            <div className="space-y-2">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">
                                    Item lié <span className="text-zinc-600 font-normal">(optionnel)</span>
                                </Label>
                                <DofusItemSearch
                                    category="equipment"
                                    onSelect={setFmLinkedItem}
                                    value={fmLinkedItem}
                                    onClear={() => setFmLinkedItem(null)}
                                    placeholder="Rechercher un item à forgemager..."
                                />
                            </div>

                            {/* Tarifs FM */}
                            <div className="grid grid-cols-1 gap-3">
                                <div className="space-y-1">
                                    <Label className="text-zinc-500 text-xs">Tarif FM Items <span className="text-zinc-600">(kamas)</span></Label>
                                    <Input
                                        type="number" value={fmItem}
                                        onChange={(e) => setFmItem(e.target.value)}
                                        placeholder="Ex: 200000"
                                        className="bg-white/5 border-white/10 h-8 text-sm"
                                        min={0} max={10000000}
                                    />
                                </div>
                                <div className="space-y-1">
                                    <Label className="text-zinc-500 text-xs">Passage Trans <span className="text-zinc-600">(kamas)</span></Label>
                                    <Input
                                        type="number" value={passTrans}
                                        onChange={(e) => setPassTrans(e.target.value)}
                                        placeholder="Ex: 500000"
                                        className="bg-white/5 border-white/10 h-8 text-sm"
                                        min={0} max={10000000}
                                    />
                                </div>
                                {/* Commande Exo — OUI/NON */}
                                <div className="flex items-center justify-between rounded-lg border border-white/10 bg-white/5 px-3 py-2.5">
                                    <div>
                                        <p className="text-xs font-bold text-zinc-300">Prendre commandes Exo / Over</p>
                                        <p className="text-[10px] text-zinc-600">Acceptez-vous les commandes exo ?</p>
                                    </div>
                                    <button
                                        type="button"
                                        onClick={() => setCommandeExo(v => !v)}
                                        className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${commandeExo ? "bg-amber-500" : "bg-zinc-700"
                                            }`}
                                    >
                                        <span className={`inline-block h-4 w-4 transform rounded-full bg-white shadow transition-transform ${commandeExo ? "translate-x-6" : "translate-x-1"
                                            }`} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Title */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Titre *</Label>
                        <Input
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            placeholder={
                                category === "PASSAGE_DONJON" ? "Ex: Passage Duo + Statue" :
                                    category === "FORGEMAGIE" ? "Ex: FM Cordomage / Forgemage" :
                                        category === "QUETE" ? "Ex: Aide Quête Dimensionnelle Xélor" :
                                            category === "OCRE" ? "Ex: Pack Complet pour Quête Ocre" :
                                                category === "METIER" ? "Ex: Craft Forgeron sur commande" :
                                                    "Titre de votre service"
                            }
                            className="bg-white/5 border-white/10"
                            maxLength={100}
                        />
                    </div>

                    {/* ── Tarifs pour DONJON (intelligent) ── */}
                    {category === "PASSAGE_DONJON" && (() => {
                        const selAchs = dungeonSelection?.dungeon.achievements
                            .filter(a => dungeonSelection.selectedAchievementIds.includes(a.id)) || [];
                        const hasAchs = selAchs.length > 0;

                        // Lignes auto par succès individuel + ligne Simple
                        const soloLabels: string[] = hasAchs
                            ? ["Simple (sans succès)", ...selAchs.map(a => a.challenge.name)]
                            : [];
                        // comboTiers: priceTiers dont le label est un JSON d'IDs (commence par "[")
                        // Distingue les combos des labels texte solo
                        const comboTiers = priceTiers.filter(t => {
                            if (soloLabels.includes(t.label)) return false;
                            try { const p = JSON.parse(t.label); return Array.isArray(p); }
                            catch { return false; }
                        });

                        type ComboMeta = { ids: string[]; price: string };
                        const comboMetas: ComboMeta[] = comboTiers.map((t: typeof priceTiers[number]) => {
                            try { return { ids: JSON.parse(t.label), price: t.price }; }
                            catch { return { ids: [], price: t.price }; }
                        });

                        const addComboTier = () => {
                            if (priceTiers.length >= 8) return;
                            // Démarrer avec les 2 premiers achievements auto-sélectionnés
                            const defaultIds = selAchs.slice(0, 2).map(a => a.id);
                            setPriceTiers(prev => [...prev, { label: JSON.stringify(defaultIds), price: "" }]);
                        };

                        return (
                            <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                    <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Tarifs par succès</Label>
                                    <div className="flex items-center gap-2">
                                        {hasAchs && selAchs.length >= 2 && (
                                            <button
                                                type="button"
                                                onClick={addComboTier}
                                                className="flex items-center gap-1 text-xs text-violet-400 hover:text-violet-300 transition-colors"
                                            >
                                                <Plus className="h-3 w-3" /> Combo
                                            </button>
                                        )}
                                        {!hasAchs && priceTiers.length < 6 && (
                                            <button type="button" onClick={addPriceTier} className="flex items-center gap-1 text-xs text-cyan-400 hover:text-cyan-300 transition-colors">
                                                <Plus className="h-3 w-3" /> Ajouter
                                            </button>
                                        )}
                                    </div>
                                </div>

                                {hasAchs ? (
                                    <div className="space-y-2 rounded-xl border border-cyan-500/15 bg-cyan-500/5 p-3">
                                        <p className="text-[10px] text-cyan-400 font-bold">Prix par configuration :</p>

                                        {/* Lignes solo */}
                                        {soloLabels.map((lbl, i) => {
                                            const existing = priceTiers.find(t => t.label === lbl);
                                            return (
                                                <div key={lbl} className="flex gap-2 items-center">
                                                    <span className={`text-xs font-bold shrink-0 w-44 truncate ${i === 0 ? "text-zinc-400" : "text-cyan-300"}`}>
                                                        {i === 0 ? "⚪" : "✨"} {lbl}
                                                    </span>
                                                    <Input
                                                        value={existing?.price ?? ""}
                                                        onChange={(e) => {
                                                            const val = e.target.value;
                                                            setPriceTiers(prev => {
                                                                const filtered = prev.filter(t => t.label !== lbl);
                                                                return val ? [...filtered, { label: lbl, price: val }] : filtered;
                                                            });
                                                        }}
                                                        placeholder="Ex: 200k"
                                                        className="bg-white/5 border-white/10 h-8 text-sm flex-1"
                                                        maxLength={50}
                                                    />
                                                </div>
                                            );
                                        })}

                                        {/* Lignes combo avec icônes cliquables */}
                                        {comboTiers.length > 0 && (
                                            <div className="mt-2 pt-2 border-t border-white/8 space-y-3">
                                                <p className="text-[9px] font-black uppercase tracking-widest text-violet-400">Combos multi-succès</p>
                                                {comboMetas.map((meta, ci) => {
                                                    const comboTier = comboTiers[ci];
                                                    const tierIdx = priceTiers.indexOf(comboTier);
                                                    // Label lisible : noms des achievements sélectionnés
                                                    const selectedAchNames = selAchs
                                                        .filter(a => meta.ids.includes(a.id))
                                                        .map(a => a.challenge.name);

                                                    const toggleAchInCombo = (achId: string) => {
                                                        const newIds = meta.ids.includes(achId)
                                                            ? meta.ids.filter(id => id !== achId)
                                                            : [...meta.ids, achId];
                                                        updatePriceTier(tierIdx, "label", JSON.stringify(newIds));
                                                    };

                                                    return (
                                                        <div key={tierIdx} className="rounded-lg border border-violet-500/20 bg-violet-500/5 p-2.5 space-y-2">
                                                            {/* Icônes cliquables */}
                                                            <div className="flex flex-wrap gap-1.5 items-center">
                                                                <span className="text-[9px] text-violet-400 font-black uppercase tracking-widest mr-1">Succès :</span>
                                                                {selAchs.map((ach) => {
                                                                    const isOn = meta.ids.includes(ach.id);
                                                                    const iconUrl = `/game-data/achievements/${ach.challenge.slug || ach.challenge.name.toLowerCase().replace(/\s+/g, "-")}.png`;
                                                                    return (
                                                                        <button
                                                                            key={ach.id}
                                                                            type="button"
                                                                            title={ach.challenge.name}
                                                                            onClick={() => toggleAchInCombo(ach.id)}
                                                                            className={`relative w-9 h-9 rounded-lg border-2 transition-all duration-150 overflow-hidden ${isOn
                                                                                ? "border-violet-400 shadow-[0_0_8px_rgba(167,139,250,0.6)] scale-110"
                                                                                : "border-white/10 opacity-40 hover:opacity-70 hover:border-white/30"
                                                                                }`}
                                                                        >
                                                                            <img
                                                                                src={iconUrl}
                                                                                alt={ach.challenge.name}
                                                                                className="w-full h-full object-contain p-0.5"
                                                                                onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}
                                                                            />
                                                                            {isOn && (
                                                                                <span className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-violet-500 rounded-full flex items-center justify-center">
                                                                                    <span className="text-[7px] text-white font-black">✓</span>
                                                                                </span>
                                                                            )}
                                                                        </button>
                                                                    );
                                                                })}
                                                            </div>
                                                            {/* Label auto-généré + prix */}
                                                            <div className="flex gap-2 items-center">
                                                                <span className="text-xs text-violet-300 font-bold truncate flex-1 min-w-0">
                                                                    {selectedAchNames.length > 0 ? selectedAchNames.join(" + ") : <span className="text-zinc-600 italic">Aucun succès sélectionné</span>}
                                                                </span>
                                                                <Input
                                                                    value={comboTier.price}
                                                                    onChange={(e) => updatePriceTier(tierIdx, "price", e.target.value)}
                                                                    placeholder="Ex: 350k"
                                                                    className="bg-white/5 border-white/10 w-24 text-sm h-7"
                                                                    maxLength={50}
                                                                />
                                                                <button type="button" onClick={() => removePriceTier(tierIdx)} className="text-zinc-600 hover:text-rose-400 transition-colors shrink-0">
                                                                    <X className="h-4 w-4" />
                                                                </button>
                                                            </div>
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        )}
                                    </div>
                                ) : (
                                    /* Mode manuel sans achievements */
                                    <div className="space-y-1.5">
                                        {priceTiers.length === 0 ? (
                                            <div className="space-y-1.5">
                                                <Input value={price} onChange={(e) => setPrice(e.target.value)} placeholder="Ex: 100k / passage" className="bg-white/5 border-white/10" maxLength={100} />
                                                <p className="text-xs text-zinc-600">Sélectionne des succès pour générer les paliers auto, ou &quot;Ajouter&quot; pour des paliers libres.</p>
                                            </div>
                                        ) : (
                                            <div className="space-y-2">
                                                {priceTiers.map((tier, i) => (
                                                    <div key={i} className="flex gap-2 items-center">
                                                        <Input value={tier.label} onChange={(e) => updatePriceTier(i, "label", e.target.value)} placeholder="Ex: Full succès" className="bg-white/5 border-white/10 flex-1 text-sm h-8" maxLength={100} />
                                                        <Input value={tier.price} onChange={(e) => updatePriceTier(i, "price", e.target.value)} placeholder="Ex: 200k" className="bg-white/5 border-white/10 w-28 text-sm h-8" maxLength={100} />
                                                        <button type="button" onClick={() => removePriceTier(i)} className="text-zinc-600 hover:text-rose-400 transition-colors"><X className="h-4 w-4" /></button>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })()}

                    {/* Paliers libres pour QUETE */}
                    {category === "QUETE" && (
                        <div className="space-y-2">
                            <div className="flex items-center justify-between">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Paliers de prix</Label>
                                {priceTiers.length < 6 && (
                                    <button type="button" onClick={addPriceTier} className="flex items-center gap-1 text-xs text-violet-400 hover:text-violet-300 transition-colors">
                                        <Plus className="h-3 w-3" /> Ajouter
                                    </button>
                                )}
                            </div>
                            {priceTiers.length === 0 ? (
                                <Input value={price} onChange={(e) => setPrice(e.target.value)} placeholder="Ex: 100k / passage" className="bg-white/5 border-white/10" maxLength={100} />
                            ) : (
                                <div className="space-y-2">
                                    {priceTiers.map((tier, i) => (
                                        <div key={i} className="flex gap-2 items-center">
                                            <Input value={tier.label} onChange={(e) => updatePriceTier(i, "label", e.target.value)} placeholder="Ex: Full succès" className="bg-white/5 border-white/10 flex-1 text-sm h-8" maxLength={100} />
                                            <Input value={tier.price} onChange={(e) => updatePriceTier(i, "price", e.target.value)} placeholder="Ex: 200k" className="bg-white/5 border-white/10 w-28 text-sm h-8" maxLength={100} />
                                            <button type="button" onClick={() => removePriceTier(i)} className="text-zinc-600 hover:text-rose-400 transition-colors"><X className="h-4 w-4" /></button>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {/* ========== METIER ========== */}
                    {category === "METIER" && (
                        <div className="space-y-4">
                            {/* Mode */}
                            <div className="flex gap-2">
                                {(["craft", "pack"] as const).map((mode) => (
                                    <button
                                        key={mode}
                                        type="button"
                                        onClick={() => setMetierMode(mode)}
                                        className={`flex-1 py-2 text-xs font-bold rounded-lg border transition-all ${metierMode === mode
                                            ? "border-emerald-500/60 bg-emerald-500/15 text-emerald-300"
                                            : "border-white/10 bg-white/3 text-zinc-500 hover:border-white/20"
                                            }`}
                                    >
                                        {mode === "craft" ? "🛠️ Craft sur commande" : "📦 Pack montée 1→200"}
                                    </button>
                                ))}
                            </div>

                            {/* Sélection du métier */}
                            <div className="space-y-2">
                                <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Métier</Label>
                                <div className="grid grid-cols-4 gap-2">
                                    {DOFUS_JOBS.map((job) => (
                                        <button
                                            key={job.id}
                                            type="button"
                                            onClick={() => setSelectedMetierJob(job.name === selectedMetierJob ? "" : job.name)}
                                            title={job.name}
                                            className={`flex flex-col items-center gap-1 p-2 rounded-lg border transition-all text-[10px] font-medium ${selectedMetierJob === job.name
                                                ? "border-emerald-500/60 bg-emerald-500/15 text-emerald-300"
                                                : "border-white/8 bg-white/3 text-zinc-500 hover:border-white/20 hover:text-zinc-300"
                                                }`}
                                        >
                                            <div className="relative h-8 w-8">
                                                <Image src={job.iconUrl} alt={job.name} fill className="object-contain"
                                                    onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
                                                />
                                            </div>
                                            <span className="leading-tight text-center">{job.name}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Pack auto 1→200 */}
                            {metierMode === "pack" && (
                                <div className="rounded-lg border border-emerald-500/20 bg-emerald-500/5 p-3 space-y-2">
                                    <p className="text-xs font-bold text-emerald-400">📦 Pack montée automatique</p>
                                    <p className="text-[11px] text-zinc-400">Définissez un tarif par palier de progression :</p>
                                    <div className="space-y-2">
                                        {[["1 → 50", ""], ["50 → 100", ""], ["100 → 150", ""], ["150 → 200", ""], ["1 → 200 (complet)", ""]].map(([label], i) => {
                                            const tier = priceTiers[i] ?? { label, price: "" };
                                            return (
                                                <div key={i} className="flex gap-2 items-center">
                                                    <span className="text-xs text-zinc-400 w-28 shrink-0">{label}</span>
                                                    <Input
                                                        value={priceTiers[i]?.price ?? ""}
                                                        onChange={(e) => {
                                                            const next = [...priceTiers];
                                                            while (next.length <= i) next.push({ label: [["1 → 50", ""], ["50 → 100", ""], ["100 → 150", ""], ["150 → 200", ""], ["1 → 200 (complet)", ""]][next.length]?.[0] ?? "", price: "" });
                                                            next[i] = { label: tier.label, price: e.target.value };
                                                            setPriceTiers(next.filter(t => t.price));
                                                        }}
                                                        placeholder="Ex: 5M"
                                                        className="bg-white/5 border-white/10 h-8 text-sm"
                                                        maxLength={50}
                                                    />
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            )}

                            {/* Prix libre si craft */}
                            {metierMode === "craft" && (
                                <div className="space-y-2">
                                    <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Tarif <span className="text-zinc-600 font-normal">(kamas)</span></Label>
                                    <Input
                                        type="number" value={price}
                                        onChange={(e) => setPrice(e.target.value)}
                                        placeholder="Ex: 100000"
                                        className="bg-white/5 border-white/10"
                                        min={0} max={10000000}
                                    />
                                </div>
                            )}
                        </div>
                    )}

                    {/* Simple price for AUTRE (not FM, not OCRE, not METIER, not DJ/Quete) */}
                    {category === "AUTRE" && (
                        <div className="space-y-2">
                            <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Tarif</Label>
                            <Input value={price} onChange={(e) => setPrice(e.target.value)} placeholder="Ex: 100k / heure" className="bg-white/5 border-white/10" maxLength={100} />
                        </div>
                    )}



                    {/* Dispo — depuis le profil */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Disponibilité</Label>
                        <AvailabilityPreview guildId={guildId} />
                        <Input
                            value={availability}
                            onChange={(e) => setAvailability(e.target.value)}
                            placeholder="Précision optionnelle (ex: sauf mercredi)"
                            className="bg-white/5 border-white/10 text-xs"
                            maxLength={200}
                        />
                    </div>

                    {/* Contact préféré — checkboxes */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Contact préféré</Label>
                        <div className="flex gap-3">
                            <button
                                type="button"
                                onClick={() => setContactDiscord(v => !v)}
                                className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-bold transition-all ${contactDiscord
                                    ? "border-indigo-500/60 bg-indigo-500/15 text-indigo-300"
                                    : "border-white/10 bg-white/5 text-zinc-500 hover:border-white/20"
                                    }`}
                            >
                                <MessageSquare className="h-3.5 w-3.5" />
                                Ping Discord
                            </button>
                            <button
                                type="button"
                                onClick={() => setContactIngame(v => !v)}
                                className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-bold transition-all ${contactIngame
                                    ? "border-cyan-500/60 bg-cyan-500/15 text-cyan-300"
                                    : "border-white/10 bg-white/5 text-zinc-500 hover:border-white/20"
                                    }`}
                            >
                                <Gamepad2 className="h-3.5 w-3.5" />
                                Ping en jeu
                            </button>
                        </div>
                    </div>
                </div>

                <div className="px-6 py-5 bg-slate-900/40 border-t border-white/5 flex gap-3 sticky bottom-0 z-10 mt-2">
                    <Button variant="ghost" onClick={() => onOpenChange(false)} className="flex-1 border border-white/10 bg-white/5 text-slate-300 hover:text-white hover:bg-white/10 font-bold h-12 transition-all">Annuler</Button>
                    <Button
                        onClick={handleSubmit}
                        disabled={loading || !title.trim()}
                        className={`flex-1 font-black h-12 text-white shadow-lg ${CATEGORY_ACCENT[category].includes("cyan") ? "bg-cyan-600 hover:bg-cyan-500 shadow-cyan-900/20" : CATEGORY_ACCENT[category].includes("amber") ? "bg-amber-600 hover:bg-amber-500 shadow-amber-900/20" : CATEGORY_ACCENT[category].includes("violet") ? "bg-violet-600 hover:bg-violet-500 shadow-violet-900/20" : CATEGORY_ACCENT[category].includes("yellow") ? "bg-yellow-600 hover:bg-yellow-500 shadow-yellow-900/20" : "bg-emerald-600 hover:bg-emerald-500 shadow-emerald-900/20"}`}
                    >
                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Publier"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useRef, useCallback, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Loader2, Upload, X, Package, TrendingDown, TrendingUp, Send } from "lucide-react";
import { createVaultEntry } from "@/server/actions/vault-actions";
import { VaultAction } from "@prisma/client";
import { toast } from "sonner";
import Image from "next/image";
import { DofusItemSearch } from "./dofus-item-search";
import type { DofusItem } from "@/lib/dofusdude-client";

interface VaultFormProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    guildId: string;
}

export function VaultForm({ open, onOpenChange, guildId }: VaultFormProps) {
    const router = useRouter();
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [loading, setLoading] = useState(false);
    const [action, setAction] = useState<VaultAction>("DEPOSIT");
    const [itemName, setItemName] = useState("");
    const [selectedItem, setSelectedItem] = useState<DofusItem | null>(null);
    const [quantity, setQuantity] = useState("1");
    const [description, setDescription] = useState("");
    const [proofFile, setProofFile] = useState<File | null>(null);
    const [proofPreview, setProofPreview] = useState<string | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [notifyDiscord, setNotifyDiscord] = useState(false);

    const resetForm = () => {
        setAction("DEPOSIT");
        setItemName("");
        setSelectedItem(null);
        setQuantity("1");
        setDescription("");
        setProofFile(null);
        setProofPreview(null);
        setNotifyDiscord(false);
    };

    const processFile = async (file: File) => {
        if (!file.type.startsWith("image/")) { 
            toast.error("Seules les images sont acceptées."); 
            return; 
        }
        if (file.size > 5 * 1024 * 1024) {
            toast.error("Fichier trop volumineux (max 5MB).");
            return;
        }

        // 🛡️ NSFW Safety Check
        const { analyzeImageSafety } = await import("@/lib/safety-client");
        const safety = await analyzeImageSafety(file);
        if (!safety.isSafe) {
            toast.error(safety.reason || "Contenu inapproprié détecté. L'image a été bloquée.");
            return;
        }

        setProofFile(file);
        setProofPreview(URL.createObjectURL(file));
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) processFile(file);
    };

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const file = e.dataTransfer.files?.[0];
        if (file) processFile(file);
    }, []);

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        if (!open) return;

        const handlePaste = (e: ClipboardEvent) => {
            if (e.clipboardData && e.clipboardData.files.length > 0) {
                const file = e.clipboardData.files[0];
                if (file.type.startsWith("image/")) {
                    e.preventDefault();
                    processFile(file);
                    toast.info("Image collée depuis le presse-papier ! 📋");
                }
            }
        };

        window.addEventListener("paste", handlePaste);
        return () => window.removeEventListener("paste", handlePaste);
    }, [open]);

    const handleSubmit = async () => {
        const resolvedName = selectedItem?.name || itemName.trim();
        if (!resolvedName) {
            toast.error("Le nom de l'objet est requis.");
            return;
        }

        setLoading(true);
        try {
            let proofFormData: FormData | undefined;
            if (proofFile) {
                proofFormData = new FormData();
                proofFormData.set("file", proofFile);
            }

            const result = await createVaultEntry(
                guildId,
                {
                    action,
                    itemName: selectedItem?.name || itemName.trim(),
                    quantity: parseInt(quantity) || 1,
                    description: description.trim() || null,
                    linkedItemIconUrl: selectedItem?.iconUrl || null,
                    notifyDiscord,
                },
                proofFormData
            );

            if (result.success) {
                toast.success(action === "DEPOSIT" ? "Dépôt enregistré !" : "Retrait enregistré !");
                resetForm();
                onOpenChange(false);
                router.refresh();
            } else {
                toast.error(result.error || "Erreur.");
            }
        } catch {
            toast.error("Erreur inattendue.");
        } finally {
            setLoading(false);
        }
    };

    if (!open) return null;

    const isDeposit = action === "DEPOSIT";

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            {/* Backdrop */}
            <div
                className="absolute inset-0 bg-black/70 backdrop-blur-sm"
                onClick={() => onOpenChange(false)}
            />

            {/* Panel */}
            <div className="relative z-10 w-full max-w-lg bg-zinc-950 rounded-2xl border border-white/10 shadow-2xl overflow-hidden">

                {/* Header coloré selon l'action */}
                <div className={`px-6 pt-6 pb-4 border-b border-white/5 bg-gradient-to-r ${isDeposit ? "from-emerald-500/15 to-transparent" : "from-orange-500/15 to-transparent"}`}>
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className={`p-2.5 rounded-xl border ${isDeposit ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-400" : "border-orange-500/40 bg-orange-500/15 text-orange-400"}`}>
                                {isDeposit ? <TrendingDown className="h-5 w-5" /> : <TrendingUp className="h-5 w-5" />}
                            </div>
                            <div>
                                <h2 className="text-lg font-black text-white">Coffre de guilde</h2>
                                <p className="text-xs text-zinc-500">Enregistrer un mouvement</p>
                            </div>
                        </div>
                        <button
                            onClick={() => onOpenChange(false)}
                            className="text-zinc-500 hover:text-white transition-colors p-1"
                        >
                            <X className="h-5 w-5" />
                        </button>
                    </div>

                    {/* Toggle Dépôt / Retrait */}
                    <div className="flex gap-2 mt-4">
                        {(["DEPOSIT", "WITHDRAW"] as VaultAction[]).map((a) => (
                            <button
                                key={a}
                                type="button"
                                onClick={() => setAction(a)}
                                className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider border transition-all ${action === a
                                    ? a === "DEPOSIT"
                                        ? "border-emerald-500/60 bg-emerald-500/20 text-emerald-300"
                                        : "border-orange-500/60 bg-orange-500/20 text-orange-300"
                                    : "border-white/10 bg-white/5 text-zinc-500 hover:border-white/20"
                                    }`}
                            >
                                {a === "DEPOSIT" ? <TrendingDown className="h-3.5 w-3.5" /> : <TrendingUp className="h-3.5 w-3.5" />}
                                {a === "DEPOSIT" ? "Dépôt" : "Retrait"}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="space-y-4 px-6 py-5">
                    {/* Objet */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">
                            Objet * <span className="text-zinc-600 font-normal">via Dofusdude ou saisie libre</span>
                        </Label>
                        <DofusItemSearch
                            category="all"
                            onSelect={(item) => { setSelectedItem(item); setItemName(item.name); }}
                            value={selectedItem}
                            onClear={() => { setSelectedItem(null); setItemName(""); }}
                            placeholder="Ex: Gelano, Abyssal Bouclier..."
                        />
                        {!selectedItem && (
                            <Input
                                value={itemName}
                                onChange={(e) => setItemName(e.target.value)}
                                placeholder="Ou saisir le nom manuellement"
                                className="bg-white/5 border-white/10 text-sm"
                                maxLength={100}
                            />
                        )}
                        {selectedItem && (
                            <div className="flex items-center gap-3 rounded-xl border border-white/10 bg-white/5 px-3 py-2">
                                {selectedItem.iconUrl && (
                                    <div className="relative h-10 w-10 shrink-0">
                                        <Image src={selectedItem.iconUrl} alt={selectedItem.name} fill className="object-contain" />
                                    </div>
                                )}
                                <div>
                                    <p className="text-sm font-black text-white">{selectedItem.name}</p>
                                    <p className="text-[10px] text-zinc-500">Item Dofus sélectionné</p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Quantité */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">
                            Quantité <span className="text-zinc-600 font-normal">(max 200 millions)</span>
                        </Label>
                        <Input
                            type="number"
                            value={quantity}
                            onChange={(e) => setQuantity(e.target.value)}
                            min={1}
                            max={200000000}
                            className="bg-white/5 border-white/10"
                        />
                    </div>

                    {/* Note */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Note <span className="text-zinc-600 font-normal">(optionnel)</span></Label>
                        <Input
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Détail optionnel..."
                            className="bg-white/5 border-white/10"
                            maxLength={500}
                        />
                    </div>

                    {/* Proof Upload */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 text-xs font-bold uppercase tracking-wider">Screenshot preuve</Label>
                        {proofPreview ? (
                            <div className="relative h-48 rounded-xl overflow-hidden border border-white/10">
                                <Image src={proofPreview} alt="Preuve" fill className="object-cover" />
                                <Button size="icon" variant="ghost" onClick={() => { setProofFile(null); setProofPreview(null); }} className="absolute top-2 right-2 h-7 w-7 bg-black/60 hover:bg-black/80 text-white">
                                    <X className="h-3.5 w-3.5" />
                                </Button>
                            </div>
                        ) : (
                            <div
                                onDrop={handleDrop}
                                onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                                onDragLeave={() => setIsDragging(false)}
                                className={`w-full h-32 border-2 border-dashed rounded-xl flex flex-col items-center justify-center gap-2 transition-all duration-200 ${isDragging ? "border-emerald-500/60 bg-emerald-500/5 text-emerald-400" : "border-white/10 hover:border-emerald-500/30 hover:text-emerald-400 text-zinc-500"}`}
                            >
                                <Upload className="h-5 w-5" />
                                <p className="text-xs font-medium">
                                    {isDragging ? "Relâcher pour ajouter" : (
                                        <>
                                            Glisser-déposer, coller ou <button type="button" onClick={() => fileInputRef.current?.click()} className="text-emerald-400 hover:text-emerald-300 underline font-black">cliquer</button>
                                        </>
                                    )}
                                </p>
                                <p className="text-[10px] text-zinc-600">PNG, JPEG, WebP — max 5MB</p>
                            </div>
                        )}
                        <input ref={fileInputRef} type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={handleFileSelect} />
                    </div>

                    {/* Notif Discord */}
                    <div className="flex items-center justify-between rounded-xl border border-white/10 bg-white/5 px-4 py-3">
                        <div className="flex items-center gap-2.5">
                            <Send className="h-4 w-4 text-indigo-400" />
                            <div>
                                <p className="text-xs font-bold text-zinc-300">Notifier sur Discord</p>
                                <p className="text-[10px] text-zinc-600">Envoyer un embed dans le salon coffre</p>
                            </div>
                        </div>
                        <button
                            type="button"
                            onClick={() => setNotifyDiscord(v => !v)}
                            className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${notifyDiscord ? "bg-indigo-500" : "bg-zinc-700"}`}
                        >
                            <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white shadow transition-transform ${notifyDiscord ? "translate-x-4" : "translate-x-1"}`} />
                        </button>
                    </div>
                </div>

                {/* Footer */}
                <div className="flex items-center justify-between px-6 pb-5 pt-0 border-t border-white/5">
                    <button onClick={() => onOpenChange(false)} className="text-sm text-zinc-500 hover:text-white transition-colors font-medium">
                        Annuler
                    </button>
                    <Button
                        onClick={handleSubmit}
                        disabled={loading || (!selectedItem && !itemName.trim())}
                        className={`font-black text-white px-6 ${isDeposit ? "bg-emerald-600 hover:bg-emerald-500" : "bg-orange-600 hover:bg-orange-500"}`}
                    >
                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : (isDeposit ? "📥 Déposer" : "📤 Retirer")}
                    </Button>
                </div>
            </div>
        </div>
    );
}

"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Trash2, ArrowDownCircle, ArrowUpCircle, Package, TrendingDown, TrendingUp, ArrowDown, ArrowUp } from "lucide-react";
import { type VaultEntryWithProfile } from "@/server/actions/vault-actions";
import { type VaultSummaryItem } from "@/server/actions/vault-actions";
import { deleteVaultEntry } from "@/server/actions/vault-actions";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { useState, useMemo } from "react";
import Image from "next/image";

interface VaultTableProps {
    entries: VaultEntryWithProfile[];
    summary: VaultSummaryItem[];
    guildId: string;
    currentProfileId?: string;
    isAdmin?: boolean;
}

function getName(p: { pseudoDofus?: string | null; discordNickname?: string | null; user?: { name?: string | null } }) {
    return p.pseudoDofus || p.discordNickname || p.user?.name || "Membre";
}

function formatQty(n: number): string {
    if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n % 1_000_000 === 0 ? 0 : 1)}M`;
    if (n >= 1_000) return `${(n / 1_000).toFixed(n % 1_000 === 0 ? 0 : 1)}k`;
    return String(n);
}

export function VaultTable({ entries, summary, guildId, currentProfileId, isAdmin }: VaultTableProps) {
    const router = useRouter();
    const [loadingId, setLoadingId] = useState<string | null>(null);
    const [sortOrder, setSortOrder] = useState<"desc" | "asc">("desc"); // desc = plus récent en premier
    const [actionFilter, setActionFilter] = useState<"ALL" | "DEPOSIT" | "WITHDRAW">("ALL");

    // Tri + filtre des entrées
    const displayedEntries = useMemo(() => {
        let result = [...entries];
        // Filtre action
        if (actionFilter !== "ALL") {
            result = result.filter(e => e.action === actionFilter);
        }
        // Tri date
        result.sort((a, b) => {
            const diff = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
            return sortOrder === "desc" ? -diff : diff;
        });
        return result;
    }, [entries, sortOrder, actionFilter]);

    const handleDelete = async (entryId: string) => {
        if (!confirm("Supprimer cette entrée ?")) return;
        setLoadingId(entryId);
        const result = await deleteVaultEntry(guildId, entryId);
        if (result.success) {
            toast.success("Entrée supprimée.");
            router.refresh();
        } else {
            toast.error(result.error || "Erreur.");
        }
        setLoadingId(null);
    };

    return (
        <div className="space-y-8">

            {/* ── Solde du coffre ─────────────────────────────── */}
            {summary.length > 0 && (
                <div className="space-y-3">
                    <h3 className="text-xs font-black uppercase tracking-widest text-zinc-500">
                        Solde du coffre
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                        {summary.map((item) => {
                            const isPositive = item.balance >= 0;
                            return (
                                <div
                                    key={item.itemName}
                                    className={`rounded-xl border p-4 flex items-start gap-3 ${isPositive
                                        ? "border-emerald-500/25 bg-emerald-500/5"
                                        : "border-red-500/25 bg-red-500/5"
                                        }`}
                                >
                                    {item.iconUrl ? (
                                        <div className="relative h-12 w-12 shrink-0 mt-0.5">
                                            <Image
                                                src={item.iconUrl}
                                                alt={item.itemName}
                                                fill
                                                className="object-contain drop-shadow-sm"
                                                onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}
                                            />
                                        </div>
                                    ) : (
                                        <div className={`h-10 w-10 shrink-0 rounded-lg flex items-center justify-center border ${isPositive ? "border-emerald-500/20 bg-emerald-500/10 text-emerald-400" : "border-red-500/20 bg-red-500/10 text-red-400"
                                            }`}>
                                            <Package className="h-5 w-5" />
                                        </div>
                                    )}
                                    <div className="flex-1 min-w-0">
                                        <p className="text-sm font-black text-white truncate capitalize">{item.itemName}</p>
                                        <p className={`text-2xl font-black mt-1 ${isPositive ? "text-emerald-400" : "text-red-400"}`}>
                                            {isPositive ? "+" : ""}{formatQty(item.balance)}
                                        </p>
                                        <div className="flex items-center gap-3 mt-2 text-[10px] text-zinc-500">
                                            <span className="flex items-center gap-1">
                                                <TrendingDown className="h-3 w-3 text-emerald-500" />
                                                {formatQty(item.totalDeposited)} déposés
                                            </span>
                                            <span className="flex items-center gap-1">
                                                <TrendingUp className="h-3 w-3 text-orange-400" />
                                                {formatQty(item.totalWithdrawn)} retirés
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* ── Historique ──────────────────────────────────── */}
            <div className="space-y-3">
                {/* Barre de contrôles tri + filtre */}
                <div className="flex items-center justify-between gap-2 flex-wrap">
                    <h3 className="text-xs font-black uppercase tracking-widest text-zinc-500">Historique</h3>
                    <div className="flex items-center gap-1.5">
                        {/* Filtre action */}
                        {(["ALL", "DEPOSIT", "WITHDRAW"] as const).map((f) => (
                            <button
                                key={f}
                                onClick={() => setActionFilter(f)}
                                className={`flex items-center gap-1 text-[10px] font-black uppercase tracking-wider px-2.5 py-1 rounded-lg border transition-all ${actionFilter === f
                                    ? f === "ALL"
                                        ? "border-zinc-500/60 bg-zinc-500/15 text-zinc-300"
                                        : f === "DEPOSIT"
                                            ? "border-emerald-500/50 bg-emerald-500/10 text-emerald-400"
                                            : "border-orange-500/50 bg-orange-500/10 text-orange-400"
                                    : "border-white/8 bg-white/3 text-zinc-600 hover:text-zinc-400 hover:border-white/15"
                                    }`}
                            >
                                {f === "ALL" ? <><Package className="h-3 w-3" /> Tout</> : f === "DEPOSIT" ? <><ArrowDownCircle className="h-3 w-3" /> Dépôts</> : <><ArrowUpCircle className="h-3 w-3" /> Retraits</>}
                            </button>
                        ))}

                        {/* Séparateur */}
                        <span className="w-px h-4 bg-white/10 mx-1" />

                        {/* Tri date */}
                        <button
                            onClick={() => setSortOrder(o => o === "desc" ? "asc" : "desc")}
                            className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-wider px-2.5 py-1 rounded-lg border border-white/8 bg-white/3 text-zinc-400 hover:text-zinc-200 hover:border-white/20 transition-all"
                        >
                            {sortOrder === "desc" ? <ArrowDown className="h-3 w-3 text-cyan-400" /> : <ArrowUp className="h-3 w-3 text-cyan-400" />}
                            {sortOrder === "desc" ? "Plus récent" : "Plus ancien"}
                        </button>
                    </div>
                </div>

                {displayedEntries.length === 0 ? (
                    <div className="rounded-xl border border-white/5 bg-white/[0.02] py-16 text-center">
                        <Package className="h-8 w-8 text-zinc-700 mx-auto mb-3" />
                        <p className="text-sm text-zinc-500">Aucune entrée dans le coffre.</p>
                    </div>
                ) : (
                    <div className="space-y-1.5">
                        {displayedEntries.map((entry) => {
                            const name = getName(entry.profile);
                            const isDeposit = entry.action === "DEPOSIT";
                            const isOwner = entry.profileId === currentProfileId;
                            const canDelete = isOwner || isAdmin;

                            return (
                                <div
                                    key={entry.id}
                                    className="group flex items-start gap-4 rounded-xl border border-white/8 bg-zinc-900/60 px-4 py-3 hover:bg-zinc-800/60 transition-colors"
                                >
                                    {/* Indicateur action */}
                                    <div className={`shrink-0 p-2 rounded-lg border ${isDeposit
                                        ? "border-emerald-500/20 bg-emerald-500/10 text-emerald-400"
                                        : "border-orange-500/20 bg-orange-500/10 text-orange-400"
                                        }`}>
                                        {isDeposit
                                            ? <ArrowDownCircle className="h-4 w-4" />
                                            : <ArrowUpCircle className="h-4 w-4" />
                                        }
                                    </div>

                                    {/* Icône item si dispo */}
                                    {entry.linkedItemIconUrl && (
                                        <div className="relative h-9 w-9 shrink-0 rounded-lg overflow-hidden border border-white/10 bg-white/[0.03]">
                                            <Image
                                                src={entry.linkedItemIconUrl}
                                                alt={entry.itemName}
                                                fill
                                                className="object-contain p-0.5"
                                                onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}
                                            />
                                        </div>
                                    )}

                                    {/* Contenu principal */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 flex-wrap">
                                            <span className="text-sm font-black text-white">
                                                {entry.quantity && entry.quantity > 1
                                                    ? <span className="text-zinc-400 font-bold">{formatQty(entry.quantity)}× </span>
                                                    : null
                                                }
                                                {entry.itemName}
                                            </span>
                                            <Badge
                                                variant="outline"
                                                className={`text-[9px] px-1.5 py-0 border font-black ${isDeposit
                                                    ? "border-emerald-500/30 text-emerald-400 bg-emerald-500/5"
                                                    : "border-orange-500/30 text-orange-400 bg-orange-500/5"
                                                    }`}
                                            >
                                                {isDeposit ? "Dépôt" : "Retrait"}
                                            </Badge>
                                        </div>
                                        <div className="flex items-center gap-2 mt-1">
                                            <Avatar className="h-4 w-4 rounded">
                                                <AvatarImage src={entry.profile.user?.image || undefined} />
                                                <AvatarFallback className="text-[7px] bg-zinc-800">
                                                    {name.slice(0, 2).toUpperCase()}
                                                </AvatarFallback>
                                            </Avatar>
                                            <span className="text-xs text-zinc-400 font-medium">{name}</span>
                                            <span className="text-[10px] text-zinc-600">·</span>
                                            <span className="text-[10px] text-zinc-600">
                                                {new Date(entry.createdAt).toLocaleDateString("fr-FR", {
                                                    day: "numeric",
                                                    month: "short",
                                                    hour: "2-digit",
                                                    minute: "2-digit",
                                                })}
                                            </span>
                                        </div>
                                        {entry.description && (
                                            <p className="text-[10px] text-zinc-500 mt-0.5 truncate">{entry.description}</p>
                                        )}
                                    </div>

                                    {/* Preuve screenshot — grande preview cliquable */}
                                    {entry.proofUrl && (
                                        <a
                                            href={entry.proofUrl}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            title="Voir la preuve"
                                            className="shrink-0 relative h-20 w-28 rounded-lg overflow-hidden border border-white/15 hover:border-white/40 hover:scale-105 transition-all shadow-lg opacity-90 hover:opacity-100"
                                        >
                                            <img src={entry.proofUrl} alt="Preuve" className="absolute inset-0 w-full h-full object-cover" />
                                            <div className="absolute inset-0 bg-black/0 hover:bg-black/10 transition-colors flex items-end justify-center pb-1">
                                                <span className="text-[9px] text-white/0 hover:text-white/80 font-bold bg-black/40 px-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">
                                                    ↗ Ouvrir
                                                </span>
                                            </div>
                                        </a>
                                    )}

                                    {/* Supprimer */}
                                    {canDelete && (
                                        <Button
                                            size="icon"
                                            variant="ghost"
                                            onClick={() => handleDelete(entry.id)}
                                            disabled={loadingId === entry.id}
                                            className="h-8 w-8 opacity-0 group-hover:opacity-100 text-zinc-600 hover:text-red-400 hover:bg-red-500/10 transition-all shrink-0"
                                        >
                                            <Trash2 className="h-3.5 w-3.5" />
                                        </Button>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
}

import { getUserContext } from "@/server/actions/user-actions";
import { redirect } from "next/navigation";
import AccessDenied from "@/components/access-denied";
import { isModuleEnabled } from "@/server/actions/module-actions";
import { getPoll, checkUserHasPollRole, getPollSettings } from "@/server/actions/poll-actions";
import { PollDetail } from "@/components/sondages/poll-detail";
import { auth } from "@/auth";

export default async function PollDetailPage({
    params,
}: {
    params: Promise<{ guildId: string; pollId: string }>;
}) {
    const { guildId, pollId } = await params;

    const user = await getUserContext(guildId);
    if (!user.canViewPolls) {
        return <AccessDenied />;
    }

    if (!user.isAdmin && !await isModuleEnabled(guildId, "polls")) {
        redirect(`/dashboard/${guildId}`);
    }

    const result = await getPoll(guildId, pollId);
    const session = await auth();
    const hasMicro = session?.user?.id ? await checkUserHasPollRole(guildId, session.user.id) : false;

    const settings = await getPollSettings(guildId);
    const isDiscordConfigured = !!settings.success && !!settings.data?.pollsNotifyChannelId;

    if (!result.success || !result.data) {
        redirect(`/dashboard/${guildId}/sondages`);
    }

    return (
        <div className="pb-12">
            <PollDetail
                poll={result.data as any}
                guildId={guildId}
                isAdmin={user.isAdmin}
                currentProfileId={user.profileId}
                hasMicro={hasMicro}
                isDiscordConfigured={isDiscordConfigured}
            />
        </div>
    );
}

