import { Activity } from "lucide-react";
import { getUserContext } from "@/server/actions/user-actions";
import { redirect } from "next/navigation";
import AccessDenied from "@/components/access-denied";
import { isModuleEnabled } from "@/server/actions/module-actions";
import { getPolls, checkCanCreatePoll, getMicroStatus } from "@/server/actions/poll-actions";
import { PollList } from "@/components/sondages/poll-list";
import { PollCreator } from "@/components/sondages/poll-creator";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { fetchGuildChannels, fetchGuildRoles } from "@/server/discord";

export default async function PollsPage({ params }: { params: Promise<{ guildId: string }> }) {
    const { guildId } = await params;

    const user = await getUserContext(guildId);
    if (!user.canViewPolls) {
        return <AccessDenied />;
    }

    const isAdmin = user.isAdmin;
    if (!isAdmin && !await isModuleEnabled(guildId, "polls")) {
        redirect(`/dashboard/${guildId}`);
    }

    // Fetch everything in parallel
    const [pollsResult, canCreateResult, microStatusResult, channels, roles] = await Promise.all([
        getPolls(guildId),
        checkCanCreatePoll(guildId),
        getMicroStatus(guildId),
        fetchGuildChannels(guildId).catch(() => [] as { id: string; name: string; type: number; position: number }[]),
        fetchGuildRoles(guildId, { excludeManaged: true }).catch(() => [] as { id: string; name: string; color: number }[]),
    ]);

    const polls = pollsResult.success ? (pollsResult.data as any[]) : [];
    const canCreate = canCreateResult.data?.canCreate || false;
    const microStatus = microStatusResult.success && microStatusResult.data ? {
        holder: microStatusResult.data.holder,
        expiresAt: microStatusResult.data.expiresAt,
        isMicroHolder: microStatusResult.data.isMicroHolder,
        isAdmin: microStatusResult.data.isAdmin,
        isSuperAdmin: microStatusResult.data.isSuperAdmin,
    } : null;

    // Text channels only (type 0) for Discord publish
    const textChannels = channels
        .filter((c) => c.type === 0)
        .map((c) => ({ id: c.id, name: c.name }));

    // Filter @everyone role
    const discordRoles = roles
        .filter((r) => r.name !== "@everyone")
        .map((r) => ({ id: r.id, name: r.name, color: (r as any).color ?? 0 }));

    return (
        <div className="space-y-6 pb-12">
            <UnifiedModuleHeader
                title="Sondages"
                description="Votez et donnez votre avis sur les décisions de la guilde."
                icon={Activity}
                iconColor="#06b6d4"
                backHref={`/dashboard/${guildId}`}
                actions={
                    canCreate && (
                        <PollCreator
                            guildId={guildId}
                            discordChannels={textChannels}
                            discordRoles={discordRoles}
                            initialMicroStatus={microStatus}
                        />
                    )
                }
            />

            <PollList polls={polls} guildId={guildId} />
        </div>
    );
}

"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import { useParams, useRouter } from "next/navigation";
import { getDreamRunById, updateCurrentFloor, getMemberProfiles } from "@/server/actions/songes/dream-run-actions";
import { getUserContext } from "@/server/actions/user-actions";
import { EmptyState } from "@/components/ui/empty-state";
import { Moon, BookOpen } from "lucide-react";
import { BossGuide } from "@/components/songes/BossGuide";
import { RunDetailHeader } from "@/components/songes/RunDetailHeader";
import { RunStatsPanel } from "@/components/songes/RunStatsPanel";
import { BonusInventory } from "@/components/songes/BonusInventory";
import { JoinRequestsPanel } from "@/components/songes/JoinRequestsPanel";
import { RunTree } from "@/components/songes/RunTree";
import { RunLeaderActions } from "@/components/songes/RunLeaderActions";
import { RunCandidacyBox } from "@/components/songes/RunCandidacyBox";
import type { DreamRun, DreamRunMember, DreamWaitlist, DreamFloor, DreamRunBonus, DreamJoinRequest } from "@prisma/client";

type RunWithRelations = DreamRun & {
    members: DreamRunMember[];
    waitlist: DreamWaitlist[];
    floors: DreamFloor[];
    bonuses: DreamRunBonus[];
    joinRequests?: DreamJoinRequest[];
};


export default function RunDetailPage() {
    const params = useParams();
    const router = useRouter();
    const guildId = params.guildId as string;
    const runId = params.runId as string;

    const [run, setRun] = useState<RunWithRelations | null>(null);
    const [profiles, setProfiles] = useState<any[]>([]); // Store profiles
    const [currentUserId, setCurrentUserId] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [optimisticStatus, setOptimisticStatus] = useState<string | null>(null);
    const [bossGuideOpen, setBossGuideOpen] = useState(false);
    const [canJoinSonges, setCanJoinSonges] = useState<boolean>(true);
    const [currentUserContext, setCurrentUserContext] = useState<any>(null);
    const [isDiscordConfigured, setIsDiscordConfigured] = useState<boolean>(false);

    const loadData = useCallback(async () => {
        if (!guildId) return;

        const [runResult, userContext] = await Promise.all([
            getDreamRunById(guildId, runId),
            getUserContext(guildId),
        ]);

        if (runResult.success && runResult.run) {
            setRun(runResult.run);
            setOptimisticStatus(runResult.run.status);
            setCurrentUserContext(userContext);
            setCanJoinSonges(userContext.canJoinSonges);
            setCurrentUserId(userContext.id || null);
            const userIds = runResult.run.members.map((m: any) => m.userId);
            if (userIds.length > 0) {
                const profilesResult = await getMemberProfiles(guildId, userIds);
                if (profilesResult.success) {
                    setProfiles(profilesResult.profiles || []);
                }
            }
            setIsDiscordConfigured(!!(runResult as any).songesNotifyChannelId);

        } else {
            setError(runResult.error || "Run non trouvée");
        }

        if (userContext.isAuthenticated && userContext.id) {
            setCurrentUserId(userContext.id);
            setCanJoinSonges(userContext.canJoinSonges);
        }

        setLoading(false);
    }, [runId, guildId]);

    // Initial load only - no polling to reduce server load
    // Data refreshes after user actions (floor select, etc.)
    useEffect(() => {
        loadData();
    }, [loadData]);

    // Sync optimistic status when real run data updates
    useEffect(() => {
        if (run) {
            setOptimisticStatus(run.status);
        }
    }, [run]);

    // Check for run existence when window regains focus (detect deleted runs)
    useEffect(() => {
        const handleFocus = () => {
            if (!loading) loadData();
        };
        window.addEventListener('focus', handleFocus);
        return () => window.removeEventListener('focus', handleFocus);
    }, [loadData, loading]);

    // Helper to get name
    const getLeaderName = () => {
        if (!run) return "Inconnu";
        const profile = profiles.find(p => p.userId === run.leaderId);
        // Prioritize Discord Nickname as requested by user
        return profile?.discordNickname || profile?.pseudoDofus || "Meneur";
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[500px] space-y-4">
                <div className="relative">
                    <div className="w-16 h-16 rounded-full border-2 border-primary/20 border-t-primary animate-spin" />
                    <Moon className="absolute inset-0 m-auto w-6 h-6 text-primary animate-pulse" />
                </div>
                <div className="text-zinc-500 font-medium animate-pulse">🌙 Synchronisation des Songes...</div>
            </div>
        );
    }

    if (error || !run) {
        return (
            <div className="flex items-center justify-center min-h-[600px] p-6">
                <EmptyState
                    icon={Moon}
                    title="Cette run a disparu"
                    description={error || "Il semblerait que cette run n'existe plus ou qu'elle ait été terminée par son meneur."}
                    variant="premium"
                    action={{
                        label: "Retour aux Songes",
                        onClick: () => router.push(`/dashboard/${guildId}/songes`)
                    }}
                    className="max-w-md w-full"
                />
            </div>
        );
    }

    const isLeader = currentUserId === run.leaderId;

    return (
        <div className="space-y-6">
            <RunDetailHeader
                run={run}
                guildId={guildId}
                isLeader={isLeader}
                leaderName={getLeaderName()}
                optimisticStatus={optimisticStatus || run.status}
                onStatusChange={setOptimisticStatus}
                onOpenBossGuide={() => setBossGuideOpen(true)}
            />

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2">
                    <RunTree
                        guildId={guildId}
                        currentFloor={run.currentFloor}
                        runId={run.id}
                        isLeader={isLeader}
                        runStatus={optimisticStatus || run.status}
                        leaderName={getLeaderName()}
                        onStatusChange={setOptimisticStatus}
                        onUpdate={loadData}
                    />
                </div>

                {/* Side Panel */}
                <div className="space-y-4">
                    {/* Leader Actions */}
                    {isLeader && (run.status === "RECRUITING" || run.status === "IN_PROGRESS") && (
                        <RunLeaderActions 
                            guildId={guildId} 
                            runId={run.id} 
                            isDiscordConfigured={isDiscordConfigured}
                        />
                    )}

                    {/* Candidacy Box */}
                    <RunCandidacyBox
                        guildId={guildId}
                        runId={run.id}
                        status={optimisticStatus || run.status}
                        membersCount={run.members.length}
                        isMember={run.members.some(m => m.userId === currentUserId)}
                        isLeader={isLeader}
                        canJoinSonges={canJoinSonges}
                    />

                    {/* Join Requests Panel */}
                    {(optimisticStatus === "RECRUITING" || optimisticStatus === "IN_PROGRESS") && (
                        <JoinRequestsPanel guildId={guildId} runId={run.id} isLeader={isLeader} />
                    )}

                    {/* Stats */}
                    <RunStatsPanel guildId={guildId} run={run} currentUserId={currentUserId ?? undefined} isLeader={isLeader} />

                    {/* Bonus Inventory */}
                    <BonusInventory guildId={guildId} bonuses={run.bonuses} runId={run.id} isLeader={isLeader} onUpdate={loadData} />
                </div>
            </div>
            {/* Boss Guide Drawer */}
            <BossGuide isOpen={bossGuideOpen} onClose={() => setBossGuideOpen(false)} />
        </div>
    );
}

import { useState, useEffect } from "react";
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from "recharts";

interface MissionsStatsProps {
    categories: { category: string; count: number; validated: number }[];
    topValidators: { name: string; value: number }[];
    topDonors: { name: string; value: number }[];
}

const CATEGORY_LABELS: Record<string, string> = {
    DONJON: "Donjon",
    REGULATION: "Régulation",
    ANOMALIE: "Anomalie",
    SONGES: "Songes",
    EXPEDITION: "Expedition",
    EVENT: "Événement",
};

const COLORS = ["#8b5cf6", "#14b8a6", "#f59e0b", "#ef4444", "#06b6d4", "#ec4899"];

export default function MissionsStats({ categories, topValidators, topDonors }: MissionsStatsProps) {
    const [mounted, setMounted] = useState(false);
    useEffect(() => { setMounted(true); }, []);
    const pieData = categories.map(c => ({
        name: CATEGORY_LABELS[c.category] || c.category,
        value: c.count,
    }));

    const barDataValidators = topValidators.map(v => ({
        name: v.name.length > 15 ? v.name.slice(0, 15) + "…" : v.name,
        missions: v.value,
    }));

    const barDataDonors = topDonors.map(v => ({
        name: v.name.length > 15 ? v.name.slice(0, 15) + "…" : v.name,
        kamas: v.value,
    }));

    const CustomTooltip = ({ active, payload, label, unit }: any) => {
        if (active && payload && payload.length) {
            return (
                <div className="bg-zinc-900/95 border border-white/10 p-3 rounded-lg shadow-2xl backdrop-blur-md">
                    <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-wider mb-1">{label}</p>
                    <p className="text-sm font-bold text-white">
                        {unit === "kamas" 
                            ? `${(payload[0].value / 1000000).toFixed(1)}M kamas` 
                            : `${payload[0].value} missions`}
                    </p>
                </div>
            );
        }
        return null;
    };

    return (
        <div className="space-y-12">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Répartition */}
                <div className="flex flex-col">
                    <h4 className="text-[10px] font-bold text-zinc-500 mb-6 uppercase tracking-widest flex items-center gap-2">
                        <span className="w-1 h-1 rounded-full bg-emerald-500" />
                        Répartition par catégorie
                    </h4>
                    {!mounted || pieData.length === 0 ? (
                        <div className="flex-1 flex items-center justify-center text-zinc-600 text-xs italic bg-white/[0.01] rounded-2xl border border-dashed border-white/5 min-h-[200px]">
                            {!mounted ? "Chargement..." : "Aucune donnée"}
                        </div>
                    ) : (
                        <div className="h-[220px] relative">
                            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                                <PieChart>
                                    <Pie
                                        data={pieData}
                                        cx="50%"
                                        cy="50%"
                                        innerRadius={60}
                                        outerRadius={85}
                                        paddingAngle={5}
                                        dataKey="value"
                                        stroke="none"
                                        animationDuration={1500}
                                    >
                                        {pieData.map((_, i) => (
                                            <Cell key={i} fill={COLORS[i % COLORS.length]} className="focus:outline-none" />
                                        ))}
                                    </Pie>
                                    <Tooltip content={<CustomTooltip />} />
                                </PieChart>
                            </ResponsiveContainer>
                            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center">
                                <span className="text-2xl font-black text-white leading-none">
                                    {pieData.reduce((acc, curr) => acc + curr.value, 0)}
                                </span>
                                <span className="text-[10px] text-zinc-500 uppercase font-bold tracking-tighter">Total</span>
                            </div>
                        </div>
                    )}
                    <div className="flex flex-wrap gap-x-4 gap-y-2 justify-center mt-6">
                        {pieData.map((entry, i) => (
                            <div key={entry.name} className="flex items-center gap-1.5 no-wrap">
                                <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
                                <span className="text-[11px] font-medium text-zinc-400">{entry.name}</span>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Top Validations */}
                <div className="flex flex-col">
                    <h4 className="text-[10px] font-bold text-zinc-500 mb-6 uppercase tracking-widest flex items-center gap-2">
                        <span className="w-1 h-1 rounded-full bg-violet-500" />
                        Efficacité du Staff
                    </h4>
                    <div className="h-[220px]">
                        {!mounted ? (
                            <div className="w-full h-full flex items-center justify-center text-zinc-600 text-xs italic">Chargement...</div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                                <BarChart data={barDataValidators} layout="vertical" margin={{ left: -10, right: 30, top: 0, bottom: 0 }}>
                                <defs>
                                    <linearGradient id="barGradient" x1="0" y1="0" x2="1" y2="0">
                                        <stop offset="0%" stopColor="#8b5cf6" stopOpacity={0.8} />
                                        <stop offset="100%" stopColor="#a78bfa" stopOpacity={1} />
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="rgba(255,255,255,0.03)" />
                                <XAxis type="number" hide />
                                <YAxis
                                    type="category"
                                    dataKey="name"
                                    tick={{ fill: "#71717a", fontSize: 11, fontVariant: "small-caps" }}
                                    axisLine={false}
                                    tickLine={false}
                                    width={100}
                                />
                                <Tooltip cursor={{ fill: 'rgba(255,255,255,0.03)' }} content={<CustomTooltip />} />
                                <Bar
                                    dataKey="missions"
                                    fill="url(#barGradient)"
                                    radius={[0, 4, 4, 0]}
                                    barSize={16}
                                />
                            </BarChart>
                        </ResponsiveContainer>
                    )}
                </div>
            </div>
        </div>

            {/* Top Donors */}
            <div className="pt-8 border-t border-white/5">
                <h4 className="text-[10px] font-bold text-zinc-500 mb-8 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-1 h-1 rounded-full bg-amber-500" />
                    Grands Philanthropes (Kamas)
                </h4>
                <div className="h-[180px]">
                    {!mounted ? (
                        <div className="w-full h-full flex items-center justify-center text-zinc-600 text-xs italic">Chargement...</div>
                    ) : (
                        <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                            <BarChart data={barDataDonors} layout="vertical" margin={{ left: -10, right: 40, top: 0, bottom: 0 }}>
                            <defs>
                                <linearGradient id="kamaGradient" x1="0" y1="0" x2="1" y2="0">
                                    <stop offset="0%" stopColor="#f59e0b" stopOpacity={0.8} />
                                    <stop offset="100%" stopColor="#fbbf24" stopOpacity={1} />
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="rgba(255,255,255,0.03)" />
                            <XAxis type="number" hide />
                            <YAxis
                                type="category"
                                dataKey="name"
                                tick={{ fill: "#71717a", fontSize: 11, fontVariant: "small-caps" }}
                                axisLine={false}
                                tickLine={false}
                                width={100}
                            />
                            <Tooltip cursor={{ fill: 'rgba(255,255,255,0.03)' }} content={<CustomTooltip unit="kamas" />} />
                            <Bar
                                dataKey="kamas"
                                fill="url(#kamaGradient)"
                                radius={[0, 4, 4, 0]}
                                barSize={16}
                            />
                        </BarChart>
                    </ResponsiveContainer>
                )}
            </div>
            </div>
        </div>
    );
}

"use client";

import { Timer, Zap, LayoutDashboard, Target } from "lucide-react";
import type { GuildStats } from "@/server/actions/guild-stats-actions";

interface PerformanceStatsProps {
    performance: GuildStats["performance"];
}

export default function PerformanceStats({ performance }: PerformanceStatsProps) {
    const avgHours = performance.avgValidationHours || 0;
    const performanceRating = avgHours <= 1 ? "Éclair ⚡" : avgHours <= 4 ? "Rapide 🚀" : avgHours <= 24 ? "Correct ✅" : "Peut mieux faire 🐢";
    const ratingColor = avgHours <= 4 ? "text-amber-400" : avgHours <= 24 ? "text-emerald-400" : "text-rose-400";

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Temps de validation */}
