'use client';

import { useState, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { ChangelogCategory } from '@prisma/client';
import { Plus, Trash2, Edit, Eye, Save, X, Terminal, Rocket, Layout, FileText, Settings2, Sparkles, ChevronRight, Activity, Send, Globe, Settings } from 'lucide-react';
import {
    createChangelogEntry,
    getChangelogEntries,
    deleteChangelogEntry,
    updateChangelogEntry,
    sendChangelogToDiscord,
    broadcastChangelogToGuilds,
    getPlatformConfig,
    updatePlatformConfig,
    testStatusPing,
} from '@/server/actions/changelog-actions';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';
import { fr } from 'date-fns/locale';
import { DocContent } from '@/components/doc/doc-content';
import { AdvancedEditor } from '@/components/editor/advanced-editor';
import { cn } from '@/lib/utils';
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable";

const categoryLabels: Record<ChangelogCategory, string> = {
    FEATURE: 'Fonctionnalité',
    BUGFIX: 'Correction',
    SECURITY: 'Sécurité',
    PERFORMANCE: 'Performance',
    DOCUMENTATION: 'Documentation',
};

const categoryColors: Record<ChangelogCategory, string> = {
    FEATURE: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
    BUGFIX: 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    SECURITY: 'bg-red-500/10 text-red-400 border-red-500/20',
    PERFORMANCE: 'bg-blue-500/10 text-blue-400 border-blue-500/20',
    DOCUMENTATION: 'bg-purple-500/10 text-purple-400 border-purple-500/20',
};

export default function GODChangelogPage() {
    const [entries, setEntries] = useState<any[]>([]);
    const [isCreating, setIsCreating] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [previewMode, setPreviewMode] = useState(false);
    const [loading, setLoading] = useState(false);
    const [filterCategory, setFilterCategory] = useState<ChangelogCategory | undefined>(undefined);
    const [publishingId, setPublishingId] = useState<string | null>(null);
    const [broadcastingId, setBroadcastingId] = useState<string | null>(null);

    // Settings state
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [hubChannelId, setHubChannelId] = useState('');
    const [serviceStatusChannelId, setServiceStatusChannelId] = useState('');
    const [isSavingSettings, setIsSavingSettings] = useState(false);
    const [isTestingPing, setIsTestingPing] = useState(false);

    const filteredEntries = filterCategory
        ? entries.filter(e => e.category === filterCategory)
        : entries;

    // Form state
    const [form, setForm] = useState({
        version: '',
        title: '',
        summary: '',
        content: '',
        category: 'FEATURE' as ChangelogCategory,
        isInternal: false,
    });

    useEffect(() => {
        loadEntries();
        loadSettings();
    }, []);

    async function loadSettings() {
        const res = await getPlatformConfig();
        if (res.success && res.config) {
            setHubChannelId(res.config.hubChannelId || '');
            setServiceStatusChannelId(res.config.serviceStatusChannelId || '');
        }
    }

    async function handleSaveSettings() {
        setIsSavingSettings(true);
        const res = await updatePlatformConfig({ hubChannelId, serviceStatusChannelId });
        if (res.success) {
            toast.success("Paramètres sauvegardés");
            setIsSettingsOpen(false);
        } else {
            toast.error(res.error || "Erreur de sauvegarde");
        }
        setIsSavingSettings(false);
    }

    async function handleTestPing() {
        if (!serviceStatusChannelId) {
            toast.error("Veuillez sauvegarder un ID de salon d'abord");
            return;
        }
        setIsTestingPing(true);
        const res = await testStatusPing();
        if (res.success) {
            toast.success("Ping envoyé avec succès !");
        } else {
            toast.error(res.error || "Erreur lors de l'envoi du ping");
        }
        setIsTestingPing(false);
    }

    async function loadEntries() {
        const data = await getChangelogEntries();
        setEntries(data);
    }

    const handleChange = (field: string, value: any) => {
        setForm(prev => ({ ...prev, [field]: value }));
    };

    async function handleSubmit() {
        if (!form.version || !form.title || !form.summary || !form.content) {
            toast.error('Version, titre, résumé et contenu sont requis');
            return;
        }

        setLoading(true);
        if (editingId) {
            const result = await updateChangelogEntry(editingId, form);
            if (result.success) {
                toast.success('Changelog mis à jour');
                resetForm();
                loadEntries();
            } else {
                toast.error(result.error || 'Erreur');
            }
        } else {
            const result = await createChangelogEntry(form);
            if (result.success) {
                toast.success('Changelog créé');
                resetForm();
                loadEntries();
            } else {
                toast.error(result.error || 'Erreur');
            }
        }
        setLoading(false);
    }

    async function handleDelete(id: string) {
        if (!confirm('Supprimer cette entrée ?')) return;

        const result = await deleteChangelogEntry(id);
        if (result.success) {
            toast.success('Changelog supprimé');
            loadEntries();
        } else {
            toast.error(result.error || 'Erreur');
        }
    }

    function handlePublishDiscord(id: string) {
        if (!confirm('Publier cette release sur le Discord Principal (Webhook Hub) ?')) return;
        setPublishingId(id);
        sendChangelogToDiscord(id).then((result) => {
            if (result.success) {
                toast.success('📢 Publié sur le Hub (Discord Officiel) !');
            } else {
                toast.error(result.error || 'Erreur Discord');
            }
        }).finally(() => setPublishingId(null));
    }

    function handleBroadcast(id: string) {
        if (!confirm('Voulez-vous vraiment diffuser cette annonce à TOUTES les guildes actives ?')) return;
        setBroadcastingId(id);
        broadcastChangelogToGuilds(id).then((result) => {
            if (result.success) {
                toast.success(`Diffusion terminée ! (${result.results?.success} guildes)`);
            } else {
                toast.error(result.error || 'Échec de la diffusion');
            }
        }).catch(() => {
            toast.error("Erreur inattendue");
        }).finally(() => setBroadcastingId(null));
    }

    function handleEdit(entry: any) {
        setEditingId(entry.id);
        setForm({
            version: entry.version,
            title: entry.title,
            summary: entry.summary,
            content: entry.content,
            category: entry.category,
            isInternal: entry.isInternal ?? false,
        });
        setIsCreating(true);
    }

    function resetForm() {
        setForm({
            version: '',
            title: '',
            summary: '',
            content: '',
            category: 'FEATURE',
            isInternal: false,
        });
        setIsCreating(false);
        setEditingId(null);
        setPreviewMode(false);
    }

    return (
        <div className="flex-1 flex flex-col h-full bg-zinc-950 font-sans selection:bg-amber-500/30 overflow-hidden">

            {/* 🚀 FIXED TOP BAR */}
            <div className="z-30 h-20 shrink-0 flex items-center justify-between px-8 border-b border-white/5 bg-zinc-900/60 backdrop-blur-2xl">
                <div className="flex items-center gap-6">
                    <div className="h-12 w-12 rounded-2xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center shadow-lg shadow-amber-500/5">
                        <Terminal className="w-6 h-6 text-amber-500" />
                    </div>
                    <div>
                        <h1 className="text-xl font-black text-white uppercase tracking-widest leading-none flex items-center gap-3">
                            Changelog Engine
                            {!isCreating && <Badge variant="outline" className="bg-amber-500/5 text-amber-500 border-amber-500/20 ml-2">{entries.length} Logs</Badge>}
                        </h1>
                        <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-tighter mt-1 italic">Signature Numérique & Orchestration des Versions</p>
                    </div>
                </div>

                <div className="flex items-center gap-4">
                    {isCreating ? (
                        <>
                            <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => setPreviewMode(!previewMode)}
                                className={cn("rounded-xl border border-white/5 h-10 px-4", previewMode ? "bg-amber-500/10 text-amber-400" : "text-zinc-500 hover:text-white")}
                            >
                                <Eye className="w-4 h-4 mr-2" />
                                {previewMode ? 'Reprendre l\'édition' : 'Mode Aperçu'}
                            </Button>
                            <div className="w-px h-6 bg-white/5 mx-1" />
                            <Button type="button" variant="ghost" onClick={resetForm} className="text-zinc-500 hover:text-white font-bold h-10 px-6 rounded-xl">
                                <X className="w-4 h-4 mr-2" />
                                Annuler
                            </Button>
                            <Button onClick={handleSubmit} disabled={loading} className="bg-amber-500 hover:bg-amber-400 text-black font-black h-10 px-8 rounded-xl shadow-xl shadow-amber-500/20 uppercase tracking-widest text-[10px]">
                                {loading ? <Activity className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
                                {editingId ? 'Envoyer Mise à Jour' : 'Déployer Version'}
                            </Button>
                        </>
                    ) : (
                        <>
                            <Dialog open={isSettingsOpen} onOpenChange={setIsSettingsOpen}>
                                <DialogTrigger asChild>
                                    <Button variant="ghost" className="h-12 w-12 p-0 rounded-2xl bg-white/5 hover:bg-white/10 text-zinc-400 hover:text-white transition-colors">
                                        <Settings className="w-5 h-5" />
                                    </Button>
                                </DialogTrigger>
                                <DialogContent className="bg-zinc-950 border-white/5 sm:max-w-md">
                                    <DialogHeader>
                                        <DialogTitle className="text-xl font-black text-white uppercase tracking-widest flex items-center gap-3">
                                            <Settings className="w-5 h-5 text-amber-500" />
                                            Configuration GOD
                                        </DialogTitle>
                                    </DialogHeader>
                                    <div className="space-y-6 pt-4">
                                        <div className="space-y-2">
                                            <Label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">ID Salon Discord (Hub)</Label>
                                            <Input
                                                value={hubChannelId}
                                                onChange={e => setHubChannelId(e.target.value)}
                                                placeholder="Ex: 123456789012345678"
                                                className="h-12 bg-zinc-900/50 border-white/10 rounded-xl font-mono text-amber-500 px-4"
                                            />
                                            <p className="text-[10px] text-zinc-500 mt-2 ml-1">Ce salon recevra les annonces du changelog via le bouton de publication (Hub).</p>
                                        </div>
                                        <div className="space-y-2">
                                            <Label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">ID Salon État des Services</Label>
                                            <Input
                                                value={serviceStatusChannelId}
                                                onChange={e => setServiceStatusChannelId(e.target.value)}
                                                placeholder="Ex: 123456789012345678"
                                                className="h-12 bg-zinc-900/50 border-white/10 rounded-xl font-mono text-amber-500 px-4"
                                            />
                                            <p className="text-[10px] text-zinc-500 mt-2 ml-1">Salon où pinguer automatiquement les maintenances et uptime.</p>
                                        </div>
                                        <div className="flex gap-2 pt-2">
                                            <Button 
                                                onClick={handleTestPing} 
                                                disabled={isTestingPing || !serviceStatusChannelId} 
                                                variant="outline"
                                                className="w-1/3 bg-zinc-900 border-white/10 text-white font-bold h-12 rounded-xl text-xs hover:bg-zinc-800"
                                            >
                                                {isTestingPing ? <Activity className="w-4 h-4 animate-spin" /> : "Ping Test"}
                                            </Button>
                                            <Button 
                                                onClick={handleSaveSettings} 
                                                disabled={isSavingSettings} 
                                                className="w-2/3 bg-amber-500 hover:bg-amber-400 text-black font-black h-12 rounded-xl"
                                            >
                                                {isSavingSettings ? <Activity className="w-4 h-4 animate-spin" /> : "Sauvegarder"}
                                            </Button>
                                        </div>
                                    </div>
                                </DialogContent>
                            </Dialog>
                            <Button onClick={() => setIsCreating(true)} className="bg-amber-500 hover:bg-amber-400 text-black font-black h-12 px-8 rounded-2xl shadow-xl shadow-amber-500/20 uppercase tracking-widest">
                                <Plus className="w-5 h-5 mr-3" />
                                Nouvelle Release
                            </Button>
                        </>
                    )}
                </div>
            </div>

            {/* 🛠️ MAIN VIEWPORT */}
            <div className="flex-1 flex overflow-hidden min-h-0">
                {!isCreating ? (
                    /* LIST VIEW */
                    <div className="flex-1 flex overflow-hidden min-h-0 min-w-0">
                        {/* ── Sidebar filtre catégorie ── */}
                        <div className="w-56 shrink-0 border-r border-white/5 p-6 flex flex-col gap-2 bg-zinc-950/60 overflow-y-auto">
                            <p className="text-[9px] font-black text-zinc-600 uppercase tracking-[0.3em] mb-3">Filtrer par</p>
                            {([undefined, ...Object.keys(categoryLabels)] as (ChangelogCategory | undefined)[]).map((cat) => {
                                const isActive = filterCategory === cat;
                                const color = cat ? categoryColors[cat] : "bg-white/5 text-zinc-400 border-white/5";
                                return (
                                    <button
                                        key={cat ?? "ALL"}
                                        onClick={() => setFilterCategory(cat)}
                                        className={cn(
                                            "flex items-center gap-2 px-3 py-2 rounded-xl border text-left text-xs font-bold transition-all",
                                            isActive ? color + " ring-1 ring-white/10" : "border-transparent text-zinc-500 hover:bg-white/5 hover:text-zinc-300"
                                        )}
                                    >
                                        <span className={cn("w-2 h-2 rounded-full shrink-0", cat ? color.replace(/text-\S+/g, "").replace(/bg-\S+\/\d+/g, m => m) : "bg-zinc-600")} />
                                        {cat ? categoryLabels[cat] : "Toutes les versions"}
                                        <span className="ml-auto text-[9px] text-zinc-600 font-black">
                                            {cat ? entries.filter(e => e.category === cat).length : entries.length}
                                        </span>
                                    </button>
                                );
                            })}
                        </div>

                        {/* ── Timeline ── */}
                        <div className="flex-1 overflow-y-auto min-h-0 min-w-0 scrollbar-thin scrollbar-thumb-white/10 p-10">
                            <div className="max-w-3xl mx-auto space-y-6">
                                <div className="space-y-2 mb-10">
                                    <h2 className="text-4xl font-black text-white tracking-tighter">
                                        Flux d&apos;Activité <span className="text-amber-500">Core</span>
                                    </h2>
                                    <p className="text-zinc-500 text-sm">Historique complet des transformations de SigilOS.</p>
                                </div>

                                {filteredEntries.length === 0 && (
                                    <div className="flex flex-col items-center justify-center py-24 text-zinc-600">
                                        <Activity className="w-12 h-12 mb-4 opacity-30" />
                                        <p className="text-sm font-bold">Aucune entrée pour cette catégorie</p>
                                    </div>
                                )}

                                {/* Grouper par mois */}
                                {Object.entries(
                                    filteredEntries.reduce((acc: Record<string, typeof entries>, e) => {
                                        const month = new Date(e.publishedAt).toLocaleDateString("fr-FR", { month: "long", year: "numeric" });
                                        if (!acc[month]) acc[month] = [];
                                        acc[month].push(e);
                                        return acc;
                                    }, {})
                                ).map(([month, monthEntries]) => (
                                    <div key={month} className="space-y-4">
                                        {/* Month label */}
                                        <div className="flex items-center gap-4 sticky top-0 z-10 py-2">
                                            <div className="h-px flex-1 bg-white/5" />
                                            <span className="text-[9px] font-black text-zinc-600 uppercase tracking-[0.4em] bg-zinc-950 px-3 py-1 rounded-full border border-white/5">
                                                {month}
                                            </span>
                                            <div className="h-px flex-1 bg-white/5" />
                                        </div>

                                        {/* Timeline entries */}
                                        <div className="relative pl-8 space-y-5 before:absolute before:left-2.5 before:top-2 before:bottom-2 before:w-px before:bg-white/5">
                                            {(monthEntries as any[]).map((entry) => {
                                                const catColor = categoryColors[entry.category as ChangelogCategory];
                                                return (
                                                    <div key={entry.id} className="relative group">
                                                        {/* Timeline dot */}
                                                        <div className={cn(
                                                            "absolute -left-[23px] top-5 w-3 h-3 rounded-full border-2 border-zinc-950 transition-all group-hover:scale-125",
                                                            entry.category === "FEATURE" ? "bg-emerald-500" :
                                                                entry.category === "BUGFIX" ? "bg-amber-500" :
                                                                    entry.category === "SECURITY" ? "bg-red-500" :
                                                                        entry.category === "PERFORMANCE" ? "bg-blue-500" :
                                                                            "bg-purple-500"
                                                        )} />

                                                        {/* Card */}
                                                        <div className="flex items-start gap-4 p-5 rounded-2xl border border-white/5 bg-zinc-900/30 hover:bg-zinc-900/60 hover:border-amber-500/20 transition-all duration-200">
                                                            <div className="flex-1 min-w-0 space-y-2">
                                                                <div className="flex items-center gap-2 flex-wrap">
                                                                    <Badge variant="outline" className={cn("text-[9px] font-black uppercase tracking-widest shrink-0", catColor)}>
                                                                        {categoryLabels[entry.category as ChangelogCategory]}
                                                                    </Badge>
                                                                    <span className="font-mono text-amber-500 text-[10px] font-black tracking-widest">{entry.version}</span>
                                                                    <span className="text-[9px] text-zinc-600 font-bold ml-auto shrink-0">
                                                                        {formatDistanceToNow(new Date(entry.publishedAt), { addSuffix: true, locale: fr })}
                                                                    </span>
                                                                </div>
                                                                <h3 className="font-black text-white text-base leading-tight uppercase tracking-tight group-hover:text-amber-200 transition-colors">
                                                                    {entry.title}
                                                                </h3>
                                                                {entry.summary && (
                                                                    <p className="text-xs text-zinc-500 leading-relaxed line-clamp-2">{entry.summary}</p>
                                                                )}
                                                            </div>

                                                            {/* Actions */}
                                                            <div className="flex gap-1.5 shrink-0 opacity-0 group-hover:opacity-100 transition-all translate-x-1 group-hover:translate-x-0">
                                                                <Button size="icon" variant="ghost" onClick={() => handlePublishDiscord(entry.id)} disabled={publishingId === entry.id || broadcastingId === entry.id} title="Publier sur le Hub (Webhook)" className="h-8 w-8 rounded-xl bg-white/5 hover:bg-indigo-500/10 text-zinc-400 hover:text-indigo-400">
                                                                    {publishingId === entry.id ? <Activity className="w-3.5 h-3.5 animate-spin" /> : <Send className="w-3.5 h-3.5" />}
                                                                </Button>
                                                                <Button size="icon" variant="ghost" onClick={() => handleBroadcast(entry.id)} disabled={publishingId === entry.id || broadcastingId === entry.id} title="Diffuser à TOUTES les guildes" className="h-8 w-8 rounded-xl bg-white/5 hover:bg-amber-500/10 text-zinc-400 hover:text-amber-400">
                                                                    {broadcastingId === entry.id ? <Activity className="w-3.5 h-3.5 animate-spin" /> : <Globe className="w-3.5 h-3.5" />}
                                                                </Button>
                                                                <Button size="icon" variant="ghost" onClick={() => handleEdit(entry)} className="h-8 w-8 rounded-xl bg-white/5 hover:bg-zinc-500/10 text-zinc-400 hover:text-white">
                                                                    <Edit className="w-3.5 h-3.5" />
                                                                </Button>
                                                                <Button size="icon" variant="ghost" onClick={() => handleDelete(entry.id)} className="h-8 w-8 rounded-xl bg-white/5 hover:bg-red-500/10 text-zinc-400 hover:text-red-400">
                                                                    <Trash2 className="w-3.5 h-3.5" />
                                                                </Button>
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                ) : (
                    /* EDITING INTERFACE */
                    <ResizablePanelGroup orientation="horizontal" className="h-full">
                        {/* FORM SIDE */}
                        <ResizablePanel defaultSize={previewMode ? 35 : 100} minSize={20} className="flex-1 flex flex-col bg-zinc-950">
                            <div className="flex-1 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10 p-8 space-y-12 pb-32">
                                <div className="max-w-4xl mx-auto space-y-12">
                                    {/* 📋 Section 1: Metadata */}
                                    <div className="space-y-6">
                                        <div className="flex items-center gap-3">
                                            <Settings2 className="w-5 h-5 text-amber-500" />
                                            <h3 className="text-sm font-black text-white uppercase tracking-[0.2em]">Données de Déploiement</h3>
                                        </div>
                                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                            <div className="space-y-2">
                                                <Label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Archive ID (vX.Y.Z)</Label>
                                                <Input
                                                    value={form.version}
                                                    onChange={e => handleChange('version', e.target.value)}
                                                    placeholder="v1.3.0"
                                                    className="h-14 bg-zinc-900/50 border-white/10 rounded-2xl font-mono text-amber-500 px-6 brightness-110"
                                                />
                                            </div>
                                            <div className="md:col-span-2 space-y-2">
                                                <Label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Désignation de la Release</Label>
                                                <Input
                                                    value={form.title}
                                                    onChange={e => handleChange('title', e.target.value)}
                                                    placeholder="Focus: UI Engine & Security..."
                                                    className="h-14 bg-zinc-900/50 border-white/10 rounded-2xl font-black px-6 text-lg"
                                                />
                                            </div>
                                            <div className="md:col-span-3 space-y-2">
                                                <Label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Classification Principale</Label>
                                                <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                                                    {(Object.keys(categoryLabels) as ChangelogCategory[]).map((cat) => (
                                                        <button
                                                            key={cat}
                                                            type="button"
                                                            onClick={() => handleChange('category', cat)}
                                                            className={cn(
                                                                "flex flex-col items-center justify-center p-4 rounded-2xl border transition-all gap-2",
                                                                form.category === cat
                                                                    ? "bg-amber-500/10 border-amber-500/40 text-amber-400 shadow-xl shadow-amber-500/5"
                                                                    : "bg-white/5 border-transparent text-zinc-500 hover:bg-white/10"
                                                            )}
                                                        >
                                                            <span className="text-[9px] font-black uppercase tracking-tighter text-center">{categoryLabels[cat]}</span>
                                                        </button>
                                                    ))}
                                                </div>
                                            </div>

                                            {/* Visibility toggle */}
                                            <div className="md:col-span-3 flex items-center gap-4 mt-2">
                                                <button
                                                    type="button"
                                                    onClick={() => handleChange('isInternal', !form.isInternal)}
                                                    className={cn(
                                                        "flex items-center gap-3 px-6 py-3 rounded-2xl border transition-all text-sm font-bold",
                                                        form.isInternal
                                                            ? "bg-red-500/10 border-red-500/30 text-red-400"
                                                            : "bg-emerald-500/10 border-emerald-500/30 text-emerald-400"
                                                    )}
                                                >
                                                    {form.isInternal ? '🔒 Interne uniquement (membres connectés)' : '🌍 Public (visible par tous)'}
                                                </button>
                                            </div>

                                            {/* 📝 Summary Field */}
                                            <div className="md:col-span-3 space-y-2 pt-4">
                                                <Label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Résumé Marketing (Public)</Label>
                                                <Input
                                                    value={form.summary}
                                                    onChange={e => handleChange('summary', e.target.value)}
                                                    placeholder="Une phrase courte pour l'accueil et le public..."
                                                    className="h-14 bg-zinc-900/50 border-white/10 rounded-2xl px-6 text-zinc-300 italic"
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    {/* 📝 Content Editor (Unified) */}
                                    <div className="space-y-6 pt-12 border-t border-white/5">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <FileText className="w-5 h-5 text-purple-500" />
                                                <h3 className="text-sm font-black text-purple-500 uppercase tracking-[0.2em]">Contenu du Changelog</h3>
                                            </div>
                                        </div>
                                        <div className="relative group p-1 bg-gradient-to-br from-purple-500/20 to-transparent rounded-[2.5rem]">
                                            <div className="bg-zinc-950 rounded-[2.4rem] overflow-hidden">
                                                <AdvancedEditor
                                                    initialContent={form.content}
                                                    onChange={(html) => handleChange('content', html)}
                                                />
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2 px-6 py-3 bg-purple-500/5 rounded-2xl border border-purple-500/10">
                                            <Rocket className="w-4 h-4 text-purple-400 shrink-0" />
                                            <p className="text-[10px] text-purple-500/70 font-bold italic tracking-wide">✍️ Écrivez le contenu complet de cette release. Visible selon le toggle Public/Interne.</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </ResizablePanel>

                        {previewMode && (
                            <>
                                <ResizableHandle withHandle className="bg-white/5 w-1.5 hover:bg-amber-500/20 transition-colors" />
                                <ResizablePanel defaultSize={65} minSize={30} className="hidden lg:flex flex-col bg-zinc-900/40">
                                    <div className="flex-1 flex flex-col h-full">
                                        <div className="h-14 flex items-center px-8 border-b border-white/5 bg-zinc-950/40">
                                            <Eye className="w-4 h-4 text-zinc-500 mr-3" />
                                            <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">Digital Twin Render (Pro-Preview)</span>
                                        </div>
                                        <div className="flex-1 overflow-y-auto p-12 md:p-24 scrollbar-thin scrollbar-thumb-white/10 dark">
                                            <div className="max-w-3xl mx-auto space-y-16">
                                                {/* Preview Content */}
                                                <div className="space-y-8">
                                                    <div className="inline-flex items-center gap-4">
                                                        <span className="text-5xl font-black text-white font-heading tracking-tighter">{form.title || 'Titre de la Release'}</span>
                                                        <Badge variant="outline" className={cn("px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-[0.2em]", categoryColors[form.category])}>
                                                            {categoryLabels[form.category]}
                                                        </Badge>
                                                    </div>
                                                    <div className="flex items-center gap-4 text-zinc-500 font-bold uppercase tracking-widest text-[11px]">
                                                        <span className="text-amber-500 px-3 py-1 bg-amber-500/10 border border-amber-500/20 rounded-lg">{form.version || 'vX.X.X'}</span>
                                                        <span className="w-1.5 h-1.5 rounded-full bg-zinc-800" />
                                                        <span>Aujourd'hui</span>
                                                    </div>
                                                </div>

                                                <div className="space-y-12">
                                                    <div className="p-8 bg-zinc-800/20 border border-white/5 rounded-[2.5rem] relative overflow-hidden group">
                                                        <div className="absolute top-0 right-0 p-8 opacity-10">
                                                            <Sparkles className="w-16 h-16 text-emerald-400" />
                                                        </div>
                                                        <p className="text-xs font-black text-emerald-400 uppercase tracking-[0.3em] mb-6">Marketing Snapshot</p>
                                                        <DocContent content={form.summary} />
                                                    </div>

                                                    <div className="space-y-6">
                                                        <div className="flex items-center gap-4">
                                                            <div className="h-px flex-1 bg-white/5" />
                                                            <p className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.4em]">Log Technique Complet</p>
                                                            <div className="h-px flex-1 bg-white/5" />
                                                        </div>
                                                        <DocContent content={form.content} />
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </ResizablePanel>
                            </>
                        )}
                    </ResizablePanelGroup>
                )}
            </div>
        </div>
    );
}

"use client";

import ReactMarkdown from "react-markdown";
import { cn } from "@/lib/utils";

import { useState, useTransition } from "react";
import {
    Megaphone,
    Radio,
    AlertTriangle,
    Info,
    Wrench,
    Send,
    X,
    Rocket,
    Loader2,
    CheckCircle2,
} from "lucide-react";
import {
    setSystemAnnouncement,
    clearSystemAnnouncement,
    broadcastDiscordAnnouncement,
    getStelliumChannels,
} from "@/server/actions/announcement-actions";
import { useEffect } from "react";
import type { SystemAnnouncement } from "@/server/actions/announcement-actions";

interface AnnouncementPanelProps {
    currentAnnouncement: SystemAnnouncement | null;
}

export function AnnouncementPanel({ currentAnnouncement }: AnnouncementPanelProps) {
    // Banner state
    const [bannerMessage, setBannerMessage] = useState("");
    const [bannerType, setBannerType] = useState<"info" | "warning" | "maintenance">("maintenance");
    const [bannerExpiry, setBannerExpiry] = useState<number>(60); // minutes
    const [bannerPending, startBannerTransition] = useTransition();
    const [bannerResult, setBannerResult] = useState<string | null>(null);

    // Discord broadcast state
    const [discordMessage, setDiscordMessage] = useState("");
    const [discordType, setDiscordType] = useState<"maintenance" | "update" | "info">("maintenance");
    const [mentionEveryone, setMentionEveryone] = useState(false);
    const [discordPending, startDiscordTransition] = useTransition();
    const [discordResult, setDiscordResult] = useState<string | null>(null);

    // Active announcement
    const [activeAnnouncement, setActiveAnnouncement] = useState(currentAnnouncement);

    // Stellium Specific
    const [stelliumChannels, setStelliumChannels] = useState<{ id: string; name: string }[]>([]);
    const [stelliumChannelId, setStelliumChannelId] = useState<string>("");

    useEffect(() => {
        getStelliumChannels().then(setStelliumChannels);
    }, []);

    const handleSetBanner = () => {
        if (!bannerMessage.trim()) return;
        startBannerTransition(async () => {
            const result = await setSystemAnnouncement(bannerMessage, bannerType, bannerExpiry || undefined);
            if (result.success) {
                setBannerResult("✅ Bandeau activé !");
                setActiveAnnouncement({
                    message: bannerMessage,
                    type: bannerType,
                    createdAt: new Date().toISOString(),
                    expiresAt: bannerExpiry ? new Date(Date.now() + bannerExpiry * 60000).toISOString() : undefined,
                });
                setBannerMessage("");
            } else {
                setBannerResult(`❌ ${result.error}`);
            }
            setTimeout(() => setBannerResult(null), 3000);
        });
    };

    const handleClearBanner = () => {
        startBannerTransition(async () => {
            const result = await clearSystemAnnouncement();
            if (result.success) {
                setBannerResult("✅ Bandeau désactivé");
                setActiveAnnouncement(null);
            } else {
                setBannerResult(`❌ ${result.error}`);
            }
            setTimeout(() => setBannerResult(null), 3000);
        });
    };

    const handleBroadcast = () => {
        if (!discordMessage.trim()) return;
        startDiscordTransition(async () => {
            const result = await broadcastDiscordAnnouncement(
                discordMessage,
                discordType,
                mentionEveryone,
                stelliumChannelId || undefined
            );
            if (result.success) {
                setDiscordResult(`✅ Envoyé à ${result.sent} guilde(s)${result.failed ? ` (${result.failed} échec)` : ""}`);
                setDiscordMessage("");
            } else {
                setDiscordResult(`❌ ${result.error}`);
            }
            setTimeout(() => setDiscordResult(null), 5000);
        });
    };

    const typeIcons = {
        info: <Info className="w-4 h-4" />,
        warning: <AlertTriangle className="w-4 h-4" />,
        maintenance: <Wrench className="w-4 h-4" />,
    };

    const typeColors = {
        info: "text-blue-400 border-blue-500/20 bg-blue-500/10",
        warning: "text-amber-400 border-amber-500/20 bg-amber-500/10",
        maintenance: "text-orange-400 border-orange-500/20 bg-orange-500/10",
    };

    return (
        <div className="space-y-12">
            {/* Header */}
            <div className="flex items-center gap-4 border-b border-white/5 pb-8">
                <div className="p-3 rounded-2xl bg-amber-500/10 border border-amber-500/20 shadow-lg shadow-amber-500/5">
                    <Megaphone className="w-8 h-8 text-amber-400" />
                </div>
                <div>
                    <h2 className="text-3xl font-black text-white uppercase tracking-tight">
                        Communication
                    </h2>
                    <p className="text-zinc-500 text-sm font-medium">Bandeaux dashboard et annonces globales discord.</p>
                </div>
            </div>

            <div className="space-y-8">
                {/* 1. DASHBOARD BANNER SECTION */}
                <div className="bg-zinc-900/40 border border-white/5 rounded-[2.5rem] p-6 md:p-10 space-y-8 overflow-hidden relative group">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-teal-500/5 blur-[100px] -translate-y-1/2 translate-x-1/2 pointer-events-none" />
                    
                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-teal-500/10 border border-teal-500/20 flex items-center justify-center">
                                <Radio className="w-5 h-5 text-teal-400" />
                            </div>
                            <h3 className="text-lg font-black text-white uppercase tracking-widest">
                                Bandeau Dashboard
                            </h3>
                        </div>
                        {activeAnnouncement && (
                            <div className="flex items-center gap-2 px-4 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/20">
                                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                                <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">
                                    Diffusion en cours
                                </span>
                            </div>
                        )}
                    </div>

                    {/* Active banner preview/control */}
                    {activeAnnouncement && (
                        <div className={cn(
                            "p-6 rounded-3xl border flex flex-col md:flex-row items-start md:items-center justify-between gap-6 transition-all shadow-xl",
                            typeColors[activeAnnouncement.type]
                        )}>
                            <div className="flex items-start gap-4 flex-1">
                                <div className="p-2 rounded-lg bg-white/10">
                                    {typeIcons[activeAnnouncement.type]}
                                </div>
                                <div className="space-y-1">
                                    <p className="text-sm md:text-base font-bold leading-tight">{activeAnnouncement.message}</p>
                                    {activeAnnouncement.expiresAt && (
                                        <p className="text-[10px] font-black uppercase tracking-widest opacity-60">
                                            Expiration : {new Date(activeAnnouncement.expiresAt).toLocaleString("fr-FR")}
                                        </p>
                                    )}
                                </div>
                            </div>
                            <button
                                onClick={handleClearBanner}
                                disabled={bannerPending}
                                className="w-full md:w-auto px-6 py-3 bg-white/10 hover:bg-rose-500 text-white rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 group/btn"
                            >
                                <X className="w-4 h-4 group-hover/btn:rotate-90 transition-transform" />
                                Couper la diffusion
                            </button>
                        </div>
                    )}

                    <div className="grid grid-cols-1 lg:grid-cols-1 gap-8 mt-4">
                        <div className="space-y-6">
                            <textarea
                                value={bannerMessage}
                                onChange={(e) => setBannerMessage(e.target.value)}
                                placeholder="Écrivez le message qui apparaîtra sur tous les dashboards..."
                                className="w-full bg-black/40 border border-white/5 rounded-3xl p-6 text-base text-white placeholder:text-zinc-700 resize-none h-32 focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500/30 transition-all font-medium"
                                maxLength={200}
                            />
                            
                            <div className="flex flex-wrap items-center gap-4">
                                <div className="flex flex-wrap gap-2 p-1.5 bg-black/40 rounded-2xl border border-white/5">
                                    {(["info", "warning", "maintenance"] as const).map((t) => (
                                        <button
                                            key={t}
                                            onClick={() => setBannerType(t)}
                                            className={cn(
                                                "px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all",
                                                bannerType === t
                                                    ? typeColors[t]
                                                    : "border-transparent text-zinc-500 hover:text-white"
                                            )}
                                        >
                                            {t}
                                        </button>
                                    ))}
                                </div>

                                <div className="flex items-center gap-3 ml-auto">
                                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Durée :</span>
                                    <select
                                        value={bannerExpiry}
                                        onChange={(e) => setBannerExpiry(Number(e.target.value))}
                                        className="bg-black/40 border border-white/5 rounded-xl px-4 py-2.5 text-xs font-bold text-white focus:outline-none focus:ring-2 focus:ring-teal-500/20"
                                    >
                                        <option value={30}>30 min</option>
                                        <option value={60}>1h</option>
                                        <option value={120}>2h</option>
                                        <option value={360}>6h</option>
                                        <option value={720}>12h</option>
                                        <option value={0}>Permanent</option>
                                    </select>
                                </div>
                            </div>

                            <button
                                onClick={handleSetBanner}
                                disabled={bannerPending || !bannerMessage.trim()}
                                className="w-full py-5 bg-teal-500 hover:bg-teal-400 text-white rounded-3xl text-sm font-black uppercase tracking-[0.2em] transition-all shadow-lg shadow-teal-500/20 flex items-center justify-center gap-3 active:scale-[0.98] disabled:opacity-20 disabled:grayscale"
                            >
                                {bannerPending ? (
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                ) : (
                                    <Radio className="w-5 h-5" />
                                )}
                                <span>Activer le bandeau</span>
                            </button>
                        </div>
                        
                        <div className="bg-black/20 rounded-3xl p-6 border border-white/5 space-y-4">
                            <h4 className="text-[10px] font-black text-zinc-600 uppercase tracking-widest text-center">Aperçu Dashboard</h4>
                            <div className="flex items-center justify-center min-h-[100px]">
                                {bannerMessage ? (
                                    <div className={cn("w-full p-4 rounded-xl border-l-4 shadow-lg", typeColors[bannerType])}>
                                        <div className="flex items-center gap-3">
                                            {typeIcons[bannerType]}
                                            <p className="text-xs font-bold line-clamp-3">{bannerMessage}</p>
                                        </div>
                                    </div>
                                ) : (
                                    <p className="text-xs text-zinc-600 font-medium italic text-center px-8">Tapez un message pour voir l'aperçu...</p>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                {/* 2. DISCORD BROADCAST SECTION */}
                <div className="bg-zinc-900/40 border border-white/5 rounded-[2.5rem] p-6 md:p-10 space-y-8 overflow-hidden relative group">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 blur-[100px] -translate-y-1/2 translate-x-1/2 pointer-events-none" />

                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center">
                                <Send className="w-5 h-5 text-indigo-400" />
                            </div>
                            <h3 className="text-lg font-black text-white uppercase tracking-widest">
                                Broadcast Discord
                            </h3>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-8">
                        <div className="space-y-6">
                            <textarea
                                value={discordMessage}
                                onChange={(e) => setDiscordMessage(e.target.value)}
                                placeholder="Le message sera envoyé sur tous les salons d'annonces des guildes..."
                                className="w-full bg-black/40 border border-white/5 rounded-3xl p-6 text-base text-white placeholder:text-zinc-700 resize-none h-48 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500/30 transition-all font-medium"
                                maxLength={500}
                            />

                            <div className="flex flex-wrap items-center gap-4">
                                <div className="flex flex-wrap gap-2 p-1.5 bg-black/40 rounded-2xl border border-white/5">
                                    {(["maintenance", "update", "info"] as const).map((t) => (
                                        <button
                                            key={t}
                                            onClick={() => setDiscordType(t)}
                                            className={cn(
                                                "px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all flex items-center gap-2",
                                                discordType === t
                                                    ? "border-indigo-500/30 text-indigo-400 bg-indigo-500/10"
                                                    : "border-transparent text-zinc-500 hover:text-white"
                                            )}
                                        >
                                            <div className={cn("w-1.5 h-1.5 rounded-full", 
                                                t === "maintenance" ? "bg-amber-500" : t === "update" ? "bg-emerald-500" : "bg-indigo-500"
                                            )} />
                                            {t}
                                        </button>
                                    ))}
                                </div>

                                <label className="flex items-center gap-3 p-3 bg-black/40 rounded-2xl border border-white/5 cursor-pointer hover:bg-white/5 transition-all ml-auto">
                                    <input
                                        type="checkbox"
                                        checked={mentionEveryone}
                                        onChange={() => setMentionEveryone(!mentionEveryone)}
                                        className="w-5 h-5 rounded-lg border-white/10 bg-zinc-900 text-indigo-500 focus:ring-indigo-500/30"
                                    />
                                    <span className="text-xs font-black text-zinc-500 uppercase tracking-widest">
                                        @everyone
                                    </span>
                                </label>
                            </div>

                            {stelliumChannels.length > 0 && (
                                <div className="p-6 rounded-3xl bg-violet-500/5 border border-violet-500/10 space-y-4">
                                    <div className="flex items-center gap-2">
                                        <div className="w-2 h-2 rounded-full bg-violet-500 animate-pulse" />
                                        <span className="text-xs font-black text-violet-400 uppercase tracking-widest">
                                            Destination Stellium
                                        </span>
                                    </div>
                                    <select
                                        value={stelliumChannelId}
                                        onChange={(e) => setStelliumChannelId(e.target.value)}
                                        className="w-full bg-black/40 border border-white/5 rounded-2xl px-4 py-3 text-sm font-bold text-white focus:outline-none focus:border-violet-500/30 transition-all"
                                    >
                                        <option value="">Par défaut (Config Guilde)</option>
                                        {stelliumChannels.map(c => (
                                            <option key={c.id} value={c.id}># {c.name}</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            <button
                                onClick={handleBroadcast}
                                disabled={discordPending || !discordMessage.trim()}
                                className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-3xl text-sm font-black uppercase tracking-[0.2em] transition-all shadow-lg shadow-indigo-500/20 flex items-center justify-center gap-3 active:scale-[0.98] disabled:opacity-20 disabled:grayscale"
                            >
                                {discordPending ? (
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                ) : (
                                    <Send className="w-5 h-5" />
                                )}
                                <span>Envoyer globalement</span>
                            </button>
                        </div>

                        <div className="bg-[#313338] rounded-3xl p-6 md:p-10 border border-black/50 shadow-2xl relative">
                             <div className="absolute top-4 left-6 text-[10px] font-black text-white/20 uppercase tracking-widest">Aperçu Discord</div>
                             <div className="mt-8 flex gap-4">
                                <div className="w-10 h-10 rounded-full bg-[#5865f2] flex-shrink-0 flex items-center justify-center font-bold text-white text-lg">S</div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 flex-wrap">
                                        <span className="text-white font-bold text-sm">SigilBot</span>
                                        <span className="bg-[#5865f2] text-white text-[10px] font-bold px-1 rounded uppercase">Bot</span>
                                        <span className="text-white/20 text-[10px] font-medium">Aujourd'hui à {new Date().getHours()}:{new Date().getMinutes().toString().padStart(2, '0')}</span>
                                    </div>
                                    <div className={cn(
                                        "rounded-lg overflow-hidden border-l-4 mt-2",
                                        discordType === "maintenance" ? "border-amber-500 bg-[#2b2d31]" : 
                                        discordType === "update" ? "border-emerald-500 bg-[#2b2d31]" : 
                                        "border-indigo-500 bg-[#2b2d31]"
                                    )}>
                                        <div className="p-4 space-y-2">
                                            <div className="text-xs text-white/40 font-bold uppercase tracking-wider">SigilOS Platform</div>
                                            <div className="text-sm font-bold text-white">
                                                {discordType === "maintenance" ? "🛠️ Maintenance Programmée" : 
                                                 discordType === "update" ? "🚀 Mise à Jour SigilOS" : 
                                                 "📢 Annonce SigilOS"}
                                            </div>
                                            <div className="text-sm text-zinc-300 break-words">
                                                {discordMessage ? <ReactMarkdown>{discordMessage}</ReactMarkdown> : "Le contenu de votre message apparaîtra ici avec le formatage Markdown..."}
                                            </div>
                                        </div>
                                    </div>
                                    {mentionEveryone && <div className="text-xs text-[#00a8fc] mt-1 font-medium">@everyone</div>}
                                </div>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Search, Shield, Filter, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

const ACTION_COLORS: Record<string, string> = {
    RBAC_UPDATE: "bg-amber-500/20 text-amber-400 border-amber-500/30",
    RBAC_ROLE_ADD: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30",
    RBAC_ROLE_REMOVE: "bg-red-500/20 text-red-400 border-red-500/30",
    CONFIG_UPDATED: "bg-blue-500/20 text-blue-400 border-blue-500/30",
    SETTINGS_UPDATED: "bg-blue-500/20 text-blue-400 border-blue-500/30",
    SECURITY_ALERT: "bg-red-600/20 text-red-300 border-red-600/30 animate-pulse",
    ACCESS_ATTEMPT: "bg-red-600/20 text-red-300 border-red-600/30 animate-pulse",
    ADMIN_FULL_DENIED: "bg-orange-500/20 text-orange-400 border-orange-500/30",
    MEMBER_LEFT: "bg-zinc-500/20 text-zinc-400 border-white/5",
    MEMBER_ARCHIVED: "bg-amber-500/20 text-amber-400 border-amber-500/30",
    MEMBER_BANNED: "bg-red-500/20 text-red-400 border-red-500/30",
    MEMBER_PURGED: "bg-rose-500/20 text-rose-400 border-rose-500/30",
    WEBHOOK_MEMBER_ADD: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30",
    WEBHOOK_MEMBER_REMOVE: "bg-zinc-500/20 text-zinc-400 border-white/5",
    MISSION_CREATED: "bg-violet-500/20 text-violet-400 border-violet-500/30",
    MISSION_DELETED: "bg-rose-500/20 text-rose-400 border-rose-500/30",
    MISSION_VALIDATED: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30",
    MISSION_REJECTED: "bg-red-500/20 text-red-400 border-red-500/30",
    BONUS_PURCHASED: "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",
    BONUS_CANCELLED: "bg-zinc-500/20 text-zinc-400 border-white/5",
    POLL_CREATED: "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",
    POLL_CLOSED: "bg-orange-500/20 text-orange-400 border-orange-500/30",
    POLL_DELETED: "bg-rose-500/20 text-rose-400 border-rose-500/30",
    POLL_CREATOR_ROLE_ACQUIRED: "bg-cyan-400/10 text-cyan-300 border-cyan-400/20",
    CHAT_BLOCKED_ATTEMPT: "bg-red-500/20 text-red-400 border-red-500/30",
    USER_GDPR_DELETE: "bg-red-600/20 text-red-300 border-red-600/30",
    GOD_ACTION: "bg-blue-600/20 text-blue-300 border-blue-500/30",
};

const ACTION_OPTIONS = [
    { value: "all", label: "Toutes les actions" },
    { value: "SECURITY_ALERT,ACCESS_ATTEMPT", label: "🚨 Alertes Sécurité & Accès (IP)" },
    { value: "RBAC_UPDATE", label: "Permissions modifiées" },
    { value: "MISSION_CREATED,MISSION_DELETED,MISSION_VALIDATED,MISSION_REJECTED", label: "⚔️ Missions" },
    { value: "BONUS_PURCHASED,BONUS_CANCELLED", label: "🔮 Bonus" },
    { value: "POLL_CREATED,POLL_CLOSED,POLL_DELETED,POLL_CREATOR_ROLE_ACQUIRED", label: "📊 Sondages & Micro" },
    { value: "MEMBER_PURGED,MEMBER_BANNED,MEMBER_ARCHIVED,MEMBER_LEFT,WEBHOOK_MEMBER_ADD,WEBHOOK_MEMBER_REMOVE", label: "🔄 Mouvements" },
    { value: "CONFIG_UPDATED,SETTINGS_UPDATED", label: "⚙️ Configuration" },
    { value: "CHAT_BLOCKED_ATTEMPT", label: "💬 Modération Chat" },
    { value: "USER_GDPR_DELETE", label: "🗑️ Suppressions RGPD" },
];

export function AuditFeedPanel({ logs, total }: { logs: any[]; total: number }) {
    const [search, setSearch] = useState("");
    const [actionFilter, setActionFilter] = useState("all");

    const filteredLogs = logs.filter(log => {
        // Text Search
        const s = search.toLowerCase();
        let textMatch = true;
        if (s) {
            const metadataStr = log.metadata ? JSON.stringify(log.metadata).toLowerCase() : "";
            textMatch = (
                log.action?.toLowerCase().includes(s) ||
                log.actorName?.toLowerCase().includes(s) ||
                log.targetType?.toLowerCase().includes(s) ||
                (log.guild?.name || "").toLowerCase().includes(s) ||
                metadataStr.includes(s) // Includes IPs, descriptions, reasons mapped in metadata
            );
        }

        // Action Filter
        let actionMatch = true;
        if (actionFilter !== "all") {
            const wantedActions = actionFilter.split(",");
            actionMatch = wantedActions.includes(log.action);
        }

        return textMatch && actionMatch;
    });

    return (
        <div className="p-8 flex flex-col h-full max-h-[800px]">
            <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4 mb-6 pb-4 border-b border-white/5 shrink-0">
                <div className="flex items-center gap-3 shrink-0">
                    <span className="text-xs text-zinc-500 font-black uppercase tracking-widest">
                        Security Feed ({total})
                    </span>
                    <span className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
                </div>
                
                <div className="flex items-center gap-3 flex-wrap">
                    <div className="flex items-center gap-2">
                        <Filter className="w-3.5 h-3.5 text-zinc-600" />
                    </div>
                    
                    <Select value={actionFilter} onValueChange={setActionFilter}>
                        <SelectTrigger className="w-[200px] h-9 text-xs bg-zinc-900/50 border-white/5 text-zinc-300">
                            <SelectValue placeholder="Catégorie d'action..." />
                        </SelectTrigger>
                        <SelectContent className="bg-zinc-900 border-white/10">
                            {ACTION_OPTIONS.map(opt => (
                                <SelectItem key={opt.value} value={opt.value} className="text-xs text-zinc-300 focus:bg-zinc-800">
                                    {opt.label}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>

                    <div className="relative w-[200px]">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-zinc-600" />
                        <Input
                            value={search}
                            onChange={e => setSearch(e.target.value)}
                            placeholder="Chercher acteur, IP, guilde..."
                            className="w-full h-9 pl-9 pr-4 text-xs bg-zinc-900/50 border-white/5 text-white placeholder:text-zinc-700 focus:border-blue-500/40"
                        />
                    </div>
                    
                    {(search || actionFilter !== "all") && (
                        <button onClick={() => { setSearch(""); setActionFilter("all"); }} className="text-zinc-500 hover:text-white px-2 cursor-pointer transition-colors border border-white/5 h-9 rounded-xl flex items-center justify-center">
                            <X className="w-3.5 h-3.5" />
                        </button>
                    )}
                </div>
            </div>

            <div className="space-y-3 font-mono text-[11px] overflow-y-auto pr-2 pb-4 flex-1 styling-scrollbar">
                {filteredLogs.length === 0 ? (
                    <div className="text-center py-12 text-zinc-600 text-[10px] uppercase tracking-widest font-bold">
                        Aucun log ne correspond
                    </div>
                ) : (
                    filteredLogs.map(log => {
                        const metadata = log.metadata || {};
                        const displayMsg = metadata.message && metadata.message.length > 80 ? metadata.message.substring(0, 80) + "..." : metadata.message;

                        return (
                            <div key={log.id} className="flex flex-col justify-center gap-1.5 p-3.5 rounded-xl bg-black/40 border border-white/5 hover:border-blue-500/30 transition-all group relative">
                                <div className="flex items-center gap-2 flex-wrap">
                                    <span className="text-zinc-600 whitespace-nowrap shrink-0">
                                        {new Date(log.createdAt).toLocaleTimeString()}
                                    </span>
                                    
                                    <Badge variant="outline" className={cn("text-[9px] px-2 py-0.5 h-auto uppercase font-black", ACTION_COLORS[log.action] || "bg-zinc-800 text-zinc-400 border-white/5")}>
                                        {log.action}
                                    </Badge>

                                    <span className="text-zinc-300 ml-1">@{log.actorName}</span>
                                    
                                    {log.guild?.name && (
                                        <span className="text-[9px] text-zinc-500 bg-zinc-900 px-1.5 py-0.5 rounded ml-auto">
                                            {log.guild.name}
                                        </span>
                                    )}
                                </div>
                                
                                <div className="text-zinc-500 flex flex-col gap-0.5 pl-[68px]">
                                    <div className="flex items-center gap-2 flex-wrap text-[10px]">
                                        <span className="opacity-70 font-semibold">{log.targetType}</span>
                                        {log.targetId && <span>({log.targetId})</span>}
                                        
                                        {metadata.ip && (
                                            <span className="text-red-400/80 bg-red-500/10 px-1 py-0.5 rounded font-black tracking-widest ml-2 flex items-center gap-1">
                                                <Shield className="w-2.5 h-2.5" /> IP: {metadata.ip}
                                            </span>
                                        )}
                                        {metadata.reason && <span className="text-amber-500/70 italic">- {metadata.reason}</span>}
                                    </div>
                                    
                                    {displayMsg && (
                                        <div className="mt-1 bg-black/50 border border-white/5 p-1.5 rounded italic break-all max-w-[80%]">
                                            "{displayMsg}"
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { scanGhostGuilds, forceBotLeaveGuild } from "@/server/actions/god-discord-actions";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { Radar, Skull, Server, ShieldAlert, Loader2, Play } from "lucide-react";

export function GhostRadarPanel() {
    const [isScanning, setIsScanning] = useState(false);
    const [ghosts, setGhosts] = useState<{ id: string; name: string; icon: string | null }[] | null>(null);
    const [kickingIds, setKickingIds] = useState<Set<string>>(new Set());

    const handleScan = async () => {
        setIsScanning(true);
        try {
            const res = await scanGhostGuilds();
            if (res.success && res.ghosts) {
                setGhosts(res.ghosts);
                if (res.ghosts.length === 0) {
                    toast.success("Aucun serveur fantôme détecté !");
                } else {
                    toast.warning(`${res.ghosts.length} serveurs fantômes trouvés !`);
                }
            } else {
                toast.error(res.error || "Erreur lors du scan");
            }
        } catch (e) {
            toast.error("Erreur inattendue");
        } finally {
            setIsScanning(false);
        }
    };

    const handleKick = async (guildId: string, guildName: string) => {
        if (!confirm(`Forcer le bot à quitter "${guildName}" ?`)) return;

        setKickingIds(new Set([...kickingIds, guildId]));
        try {
            const res = await forceBotLeaveGuild(guildId);
            if (res.success) {
                toast.success(`Le bot a quitté ${guildName}`);
                setGhosts(ghosts?.filter(g => g.id !== guildId) || null);
            } else {
                toast.error(res.error || "Erreur lors de l'expulsion");
            }
        } catch (e) {
            toast.error("Erreur inattendue");
        } finally {
            const newKickingIds = new Set(kickingIds);
            newKickingIds.delete(guildId);
            setKickingIds(newKickingIds);
        }
    };

    return (
        <div className="bg-zinc-900/30 border border-white/5 rounded-3xl p-8 backdrop-blur-xl">
            <div className="flex items-start justify-between mb-8">
                <div>
                    <h3 className="text-xl font-black text-rose-500 flex items-center gap-3 uppercase tracking-widest">
                        <Radar className="w-6 h-6 animate-pulse" />
                        Radar Anti-Fantômes
                    </h3>
                    <p className="text-zinc-500 mt-2 text-sm">
                        Détecte les serveurs Discord qui ont invité le bot mais qui ne sont pas sur liste blanche.
                    </p>
                </div>
                <Button
                    onClick={handleScan}
                    disabled={isScanning}
                    size="lg"
                    className="bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white transition-all font-bold uppercase tracking-widest border border-rose-500/20"
                >
                    {isScanning ? (
                        <Loader2 className="w-5 h-5 mr-2 animate-spin" />
                    ) : (
                        <Play className="w-5 h-5 mr-2" />
                    )}
                    {isScanning ? "Scan en cours..." : "Lancer le scan"}
                </Button>
            </div>

            {ghosts !== null && (
                <div className="space-y-4">
                    {ghosts.length === 0 ? (
                        <div className="flex flex-col items-center justify-center p-12 border border-white/5 rounded-2xl bg-black/20 text-emerald-500">
                            <ShieldAlert className="w-12 h-12 mb-4 opacity-50" />
                            <p className="font-bold uppercase tracking-widest text-sm">Secteur Sécurisé</p>
                            <p className="text-xs text-zinc-500 mt-2">Aucune anomalie détectée sur le réseau Discord.</p>
                        </div>
                    ) : (
                        <div className="grid gap-4">
                            {ghosts.map((guild) => (
                                <div key={guild.id} className="flex items-center justify-between p-4 bg-black/40 border border-white/5 rounded-2xl hover:border-rose-500/30 transition-colors">
                                    <div className="flex items-center gap-4">
                                        {guild.icon ? (
                                            <img
                                                src={`https://cdn.discordapp.com/icons/${guild.id}/${guild.icon}.png?size=128`}
                                                alt={guild.name}
                                                className="w-12 h-12 rounded-xl grayscale opacity-70"
                                            />
                                        ) : (
                                            <div className="w-12 h-12 rounded-xl bg-zinc-800 flex items-center justify-center border border-white/5">
                                                <Server className="w-5 h-5 text-zinc-500" />
                                            </div>
                                        )}
                                        <div>
                                            <h4 className="font-bold text-white">{guild.name}</h4>
                                            <code className="text-[10px] text-zinc-500">{guild.id}</code>
                                        </div>
                                    </div>
                                    <Button
                                        variant="destructive"
                                        size="sm"
                                        className="font-bold uppercase tracking-widest text-[10px]"
                                        onClick={() => handleKick(guild.id, guild.name)}
                                        disabled={kickingIds.has(guild.id)}
                                    >
                                        {kickingIds.has(guild.id) ? (
                                            <Loader2 className="w-4 h-4 animate-spin mr-2" />
                                        ) : (
                                            <Skull className="w-4 h-4 mr-2" />
                                        )}
                                        Expulser le bot
                                    </Button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { 
    Bell, 
    CheckCircle2, 
    XCircle, 
    Clock, 
    ExternalLink, 
    Search,
    ShieldAlert,
    Terminal,
    Database,
    Ticket,
    Bug,
    Info,
    RefreshCw
} from "lucide-react";
import { markGodNotificationRead } from "@/server/actions/god-notif-actions";
import { toast } from "sonner";

interface GodNotification {
    id: string;
    title: string;
    message: string;
    type: string;
    success: boolean;
    isRead: boolean;
    metadata: any;
    createdAt: Date;
}

interface GodNotificationPanelProps {
    notifications: GodNotification[];
}

export function GodNotificationPanel({ notifications: initialNotifications }: GodNotificationPanelProps) {
    const [notifications, setNotifications] = useState(initialNotifications);
    const [searchTerm, setSearchTerm] = useState("");
    const [isPending, startTransition] = useTransition();

    const filteredNotifications = notifications.filter(n => 
        n.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        n.message.toLowerCase().includes(searchTerm.toLowerCase()) ||
        n.type.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleMarkRead = (id: string) => {
        startTransition(async () => {
            const res = await markGodNotificationRead(id);
            if (res.success) {
                setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
            } else {
                toast.error("Erreur lors du marquage en lu");
            }
        });
    };

    const getTypeIcon = (type: string) => {
        switch (type) {
            case "VPS_MAINTENANCE": return <Terminal className="w-4 h-4 text-blue-400" />;
            case "BACKUP": return <Database className="w-4 h-4 text-emerald-400" />;
            case "WORKER_SYNC": return <RefreshCw className="w-4 h-4 text-amber-400" />;
            case "TICKET": return <Ticket className="w-4 h-4 text-indigo-400" />;
            case "GEOGUESSER_REPORT": return <Bug className="w-4 h-4 text-rose-400" />;
            case "SECURITY_ALERT": return <ShieldAlert className="w-4 h-4 text-red-500" />;
            default: return <Info className="w-4 h-4 text-zinc-400" />;
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-700">
            {/* Header & Filter */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 pb-8 border-b border-white/5">
                <div className="space-y-1">
                    <h2 className="text-3xl font-black text-white uppercase tracking-tight flex items-center gap-3">
                        <Bell className="w-8 h-8 text-rose-500" />
                        Alertes Système
                    </h2>
                    <p className="text-zinc-500 font-medium">Notifications temps-réel de l'infrastructure et des services.</p>
                </div>

                <div className="relative w-full md:w-96">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
                    <input 
                        type="text"
                        placeholder="Filtrer les notifications..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-12 pr-4 py-3 bg-zinc-900/50 border border-white/5 rounded-2xl text-sm text-zinc-300 focus:outline-none focus:border-rose-500/30 transition-all shadow-inner"
                    />
                </div>
            </div>

            {/* Notifications List */}
            <div className="grid gap-4">
                {filteredNotifications.length === 0 ? (
                    <div className="py-20 text-center space-y-4 bg-zinc-900/20 border border-white/5 rounded-3xl">
                        <div className="inline-flex p-4 rounded-full bg-zinc-900 border border-white/5">
                            <Bell className="w-8 h-8 text-zinc-700" />
                        </div>
                        <p className="text-zinc-600 font-medium italic">Aucune notification trouvée.</p>
                    </div>
                ) : (
                    filteredNotifications.map((notif) => (
                        <div 
                            key={notif.id}
                            className={`group relative overflow-hidden p-6 bg-zinc-900/40 border border-white/5 rounded-3xl transition-all hover:bg-zinc-900/60 ${!notif.isRead ? 'ring-1 ring-rose-500/30 bg-rose-500/5' : ''}`}
                        >
                            <div className="flex items-start gap-6">
                                {/* Success/Fail Indicator */}
                                <div className={`shrink-0 p-3 rounded-2xl border ${notif.success ? 'bg-emerald-500/10 border-emerald-500/20' : 'bg-rose-500/10 border-rose-500/20'}`}>
                                    {notif.success ? 
                                        <CheckCircle2 className="w-5 h-5 text-emerald-400" /> : 
                                        <XCircle className="w-5 h-5 text-rose-400" />
                                    }
                                </div>

                                <div className="flex-1 space-y-2">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <span className="px-2 py-0.5 rounded-md bg-white/5 text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-1.5">
                                                {getTypeIcon(notif.type)}
                                                {notif.type.replace('_', ' ')}
                                            </span>
                                            <span className="text-zinc-600 text-[10px] flex items-center gap-1.5 font-bold">
                                                <Clock className="w-3 h-3" />
                                                {format(new Date(notif.createdAt), "d MMMM HH:mm", { locale: fr })}
                                            </span>
                                        </div>
                                        {!notif.isRead && (
                                            <button 
                                                onClick={() => handleMarkRead(notif.id)}
                                                className="text-[10px] font-black text-rose-400 uppercase tracking-widest hover:text-rose-300 transition-colors"
                                            >
                                                Marquer comme lu
                                            </button>
                                        )}
                                    </div>

                                    <h4 className="text-lg font-bold text-white group-hover:text-rose-100 transition-colors tracking-tight">
                                        {notif.title}
                                    </h4>
                                    
                                    <p className="text-zinc-400 text-sm leading-relaxed max-w-4xl">
                                        {notif.message}
                                    </p>

                                    {notif.metadata && (
                                        <div className="mt-4 pt-4 border-t border-white/5 grid grid-cols-2 md:grid-cols-4 gap-4">
                                            {Object.entries(notif.metadata).map(([key, value]) => (
                                                <div key={key} className="space-y-0.5">
                                                    <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">{key}</div>
                                                    <div className="text-xs text-zinc-300 font-mono truncate">{String(value)}</div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Unread Glow */}
                            {!notif.isRead && (
                                <div className="absolute top-0 right-0 w-24 h-24 bg-rose-500/5 blur-[50px] -translate-y-1/2 translate-x-1/2" />
                            )}
                        </div>
                    ))
                )}
            </div>
        </div>
    );
}

/**
 * 🏰 GOD Dashboard - Guild Table Component  
 * 
 * Premium guild management with:
 * - Advanced filters (search, status, sort)
 * - Bulk actions (archive, delete)
 * - Smooth animations
 * - Inline actions
 */

'use client';

import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Search, Filter, ChevronDown, MoreVertical, Check, Users, Calendar, ExternalLink, Trash2, Archive, Eye, ShieldAlert, ShieldCheck, RotateCcw, Plus, UserPlus, FileText, Hash, Copy
} from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { fr } from 'date-fns/locale';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
    DialogDescription,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { softDeleteGuild, reactivateGuild, hardDeleteGuild } from '@/server/actions/god-lifecycle-actions';
import { addAllowedGuild, removeAllowedGuild } from "@/server/actions/super-admin-actions";
import { toast } from 'sonner';
import Link from 'next/link';
import { z } from 'zod';

const whitelistSchema = z.object({
    discordGuildId: z.string().min(17, "ID Discord trop court").max(20, "ID Discord trop long").regex(/^\d+$/, "L'ID doit être numérique"),
    name: z.string().min(2, "Nom trop court").optional().or(z.literal('')),
    notes: z.string().optional().or(z.literal('')),
});

interface Guild {
    id: string;
    name: string;
    discordGuildId: string;
    iconUrl: string | null;
    isActive: boolean;
    deletedAt: Date | null;
    deletionReason: string | null;
    scheduledDeletion: Date | null;
    createdAt: Date;
    maxMembers: number;
    isWhitelistOnly?: boolean;
    notes?: string | null;
    tier?: string; // Restore tier
    _count: {
        profiles: number;
    };
}

interface GuildTableProps {
    guilds: Guild[];
}

type FilterStatus = 'all' | 'active' | 'inactive' | 'deleted';
type SortBy = 'name' | 'members' | 'createdAt';

export function GuildTable({ guilds }: GuildTableProps) {
    const [search, setSearch] = useState('');
    const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
    const [sortBy, setSortBy] = useState<SortBy>('name');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
    const [selected, setSelected] = useState<Set<string>>(new Set());

    // Whitelist Modal State
    const [isAddOpen, setIsAddOpen] = useState(false);
    const [newGuildId, setNewGuildId] = useState("");
    const [newGuildName, setNewGuildName] = useState("");
    const [newGuildNotes, setNewGuildNotes] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Filtered & sorted guilds
    const filteredGuilds = useMemo(() => {
        const result = guilds.filter(guild => {
            // Search filter
            const matchesSearch =
                guild.name.toLowerCase().includes(search.toLowerCase()) ||
                guild.discordGuildId.includes(search);

            // Status filter
            const matchesStatus =
                filterStatus === 'all' ||
                (filterStatus === 'active' && guild.isActive && !guild.deletedAt && !guild.isWhitelistOnly) ||
                (filterStatus === 'inactive' && guild.isActive && guild._count.profiles === 0 && !guild.isWhitelistOnly) ||
                (filterStatus === 'deleted' && !guild.isActive && guild.deletedAt);

            return matchesSearch && matchesStatus;
        });

        // Sort
        result.sort((a, b) => {
            let comparison = 0;

            if (sortBy === 'name') {
                comparison = a.name.localeCompare(b.name);
            } else if (sortBy === 'members') {
                comparison = a._count.profiles - b._count.profiles;
            } else if (sortBy === 'createdAt') {
                comparison = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
            }

            return sortOrder === 'asc' ? comparison : -comparison;
        });

        return result;
    }, [guilds, search, filterStatus, sortBy, sortOrder]);

    const toggleSelect = (id: string) => {
        const newSelected = new Set(selected);
        if (newSelected.has(id)) {
            newSelected.delete(id);
        } else {
            newSelected.add(id);
        }
        setSelected(newSelected);
    };

    const handleAdd = async () => {
        const result = whitelistSchema.safeParse({
            discordGuildId: newGuildId.trim(),
            name: newGuildName.trim(),
            notes: newGuildNotes.trim(),
        });

        if (!result.success) {
            toast.error(result.error.errors[0].message);
            return;
        }

        setIsSubmitting(true);
        try {
            await addAllowedGuild(result.data);
            setIsAddOpen(false);
            setNewGuildId("");
            setNewGuildName("");
            setNewGuildNotes("");
            toast.success("Guilde ajoutée à la liste blanche. Rechargement...");
            window.location.reload(); // Refresh to show the new whitelisted guild
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "Erreur lors de l'ajout");
        } finally {
            setIsSubmitting(false);
        }
    };

    const selectAll = () => {
        if (selected.size === filteredGuilds.length) {
            setSelected(new Set());
        } else {
            setSelected(new Set(filteredGuilds.map(g => g.id)));
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold bg-gradient-to-r from-violet-200 to-violet-500 bg-clip-text text-transparent">
                        Gestion des Guildes
                    </h2>
                    <p className="text-sm text-zinc-500 mt-1">
                        {filteredGuilds.length} guilde{filteredGuilds.length > 1 ? 's' : ''}
                        {search && ` · Recherche: "${search}"`}
                    </p>
                </div>

                <div className="flex gap-2">
                    <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
                        <DialogTrigger asChild>
                            <Button className="bg-violet-600 hover:bg-violet-700 text-white font-black uppercase tracking-widest text-[10px] px-6 py-5 rounded-xl shadow-lg shadow-violet-500/10 gap-2 border border-violet-400/20 active:scale-95 transition-all">
                                <UserPlus className="w-4 h-4" />
                                Whitelist New Guild
                            </Button>
                        </DialogTrigger>
                        <DialogContent className="bg-zinc-950 border-white/5 text-white max-w-md rounded-3xl p-8 backdrop-blur-2xl">
                            <DialogHeader>
                                <DialogTitle className="text-2xl font-black uppercase tracking-tighter">Autoriser une Guilde</DialogTitle>
                                <DialogDescription className="text-zinc-500 text-sm font-medium">
                                    L'autorisation de première connexion permet au bot de rejoindre le serveur.
                                </DialogDescription>
                            </DialogHeader>

                            <div className="space-y-6 mt-8">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                                        <Hash className="w-3 h-3" /> Discord Guild ID *
                                    </label>
                                    <Input
                                        placeholder="Ex: 1234567890..."
                                        value={newGuildId}
                                        onChange={(e) => setNewGuildId(e.target.value)}
                                        className="bg-zinc-900/50 border-white/5 rounded-xl h-12 font-mono text-sm focus:ring-violet-500"
                                    />
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                                        <Filter className="w-3 h-3" /> Nom de la guilde
                                    </label>
                                    <Input
                                        placeholder="Nom mémoriel"
                                        value={newGuildName}
                                        onChange={(e) => setNewGuildName(e.target.value)}
                                        className="bg-zinc-900/50 border-white/5 rounded-xl h-12"
                                    />
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                                        <FileText className="w-3 h-3" /> Notes (Interne)
                                    </label>
                                    <Input
                                        placeholder="Ex: Guilde de test, Premium..."
                                        value={newGuildNotes}
                                        onChange={(e) => setNewGuildNotes(e.target.value)}
                                        className="bg-zinc-900/50 border-white/5 rounded-xl h-12"
                                    />
                                </div>

                                <Button
                                    onClick={handleAdd}
                                    disabled={isSubmitting}
                                    className="w-full bg-violet-600 hover:bg-violet-700 h-14 rounded-2xl font-black uppercase tracking-[0.2em] shadow-xl shadow-violet-500/20"
                                >
                                    {isSubmitting ? "Traitement..." : "Valider l'autorisation"}
                                </Button>
                            </div>
                        </DialogContent>
                    </Dialog>
                </div>
            </div>

            {/* Filters Bar */}
            <div className="bg-zinc-900/30 backdrop-blur-sm border border-zinc-800/60 rounded-xl p-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    {/* Search */}
                    <div className="md:col-span-2 relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                        <input
                            type="text"
                            placeholder="Recherche..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="w-full pl-10 pr-4 py-2.5 bg-zinc-900 border border-zinc-800 rounded-lg text-sm focus:border-violet-500 focus:ring-1 focus:ring-violet-500 transition-colors"
                        />
                    </div>

                    {/* Status Filter */}
                    <select
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value as FilterStatus)}
                        className="px-4 py-2 bg-zinc-900 border border-zinc-800 rounded-lg text-sm focus:border-violet-500 focus:ring-1 focus:ring-violet-500 transition-colors"
                    >
                        <option value="all">Toutes les guildes</option>
                        <option value="active">✅ Actives</option>
                        <option value="inactive">⚠️ Inactives (0 membre)</option>
                        <option value="deleted">🗑️ Supprimées</option>
                    </select>

                    {/* Sort */}
                    <select
                        value={`${sortBy}-${sortOrder}`}
                        onChange={(e) => {
                            const [by, order] = e.target.value.split('-');
                            setSortBy(by as SortBy);
                            setSortOrder(order as 'asc' | 'desc');
                        }}
                        className="px-4 py-2 bg-zinc-900 border border-zinc-800 rounded-lg text-sm focus:border-violet-500 focus:ring-1 focus:ring-violet-500 transition-colors"
                    >
                        <option value="name-asc">Nom (A-Z)</option>
                        <option value="name-desc">Nom (Z-A)</option>
                        <option value="members-desc">Plus de membres</option>
                        <option value="members-asc">Moins de membres</option>
                        <option value="createdAt-desc">Plus récentes</option>
                        <option value="createdAt-asc">Plus anciennes</option>
                    </select>
                </div>
            </div>

            {/* Table */}
            <div className="bg-zinc-900/30 backdrop-blur-sm border border-zinc-800/60 rounded-xl overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead>
                            <tr className="border-b border-zinc-800">
                                <th className="p-4 text-left">
                                    <input
                                        type="checkbox"
                                        checked={selected.size === filteredGuilds.length && filteredGuilds.length > 0}
                                        onChange={selectAll}
                                        className="w-4 h-4 rounded border-zinc-700 bg-zinc-900 checked:bg-violet-500 checked:border-violet-500 cursor-pointer"
                                    />
                                </th>
                                <th className="p-4 text-left text-xs font-medium text-zinc-500 uppercase tracking-wider">
                                    Guilde
                                </th>
                                <th className="p-4 text-left text-xs font-medium text-zinc-500 uppercase tracking-wider hidden md:table-cell">
                                    Membres
                                </th>
                                <th className="p-4 text-left text-xs font-medium text-zinc-500 uppercase tracking-wider hidden sm:table-cell">
                                    Status
                                </th>
                                <th className="p-4 text-left text-xs font-medium text-zinc-500 uppercase tracking-wider hidden lg:table-cell">
                                    Créée
                                </th>
                                <th className="p-4 text-right text-xs font-medium text-zinc-500 uppercase tracking-wider">
                                    Actions
                                </th>
                            </tr>
                        </thead>
                        <tbody>
                            <AnimatePresence mode="popLayout">
                                {filteredGuilds.map((guild) => (
                                    <GuildRow
                                        key={guild.id}
                                        guild={guild}
                                        selected={selected.has(guild.id)}
                                        onSelect={() => toggleSelect(guild.id)}
                                    />
                                ))}
                            </AnimatePresence>
                        </tbody>
                    </table>

                    {filteredGuilds.length === 0 && (
                        <div className="p-12 text-center text-zinc-500">
                            Aucune guilde trouvée
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

function GuildRow({ guild, selected, onSelect }: {
    guild: Guild;
    selected: boolean;
    onSelect: () => void;
}) {
    const [isUpdating, setIsUpdating] = useState(false);

    const handleSoftDelete = async () => {
        if (!confirm(`Soft delete guild "${guild.name}"? This will archive it for 30 days.`)) return;
        setIsUpdating(true);
        try {
            await softDeleteGuild(guild.id, "GOD_ADMIN_SOFT_DELETE");
            toast.success("Guilde mise en pause (archivée)");
        } catch (e) {
            toast.error("Échec de l'action");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleReactivate = async () => {
        setIsUpdating(true);
        try {
            await reactivateGuild(guild.id);
            toast.success("Guilde réactivée");
        } catch (e) {
            toast.error("Échec de l'action");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleHardDelete = async () => {
        if (!confirm(`⚠️ HARD DELETE guild "${guild.name}"? This is irreversible.`)) return;
        const confirmText = prompt("Type DELETE to confirm:");
        if (confirmText !== 'DELETE') return;

        setIsUpdating(true);
        try {
            await hardDeleteGuild(guild.id);
            toast.success("Guilde supprimée définitivement");
        } catch (e) {
            toast.error("Échec de l'action");
        } finally {
            setIsUpdating(false);
        }
    };

    const statusConfig = guild.isWhitelistOnly
        ? {
            label: '🛡️ Whitelist',
            color: 'text-blue-400 bg-blue-500/10 border-blue-500/30',
            tooltip: 'Guilde autorisée mais pas encore connectée (Onboarding en attente).'
        }
        : guild.deletedAt
            ? {
                label: '🗑️ Supprimée',
                color: 'text-red-400 bg-red-500/10 border-red-500/30',
                tooltip: 'Guilde en cours de suppression. Accès au dashboard BLOQUÉ.'
            }
            : guild._count.profiles === 0
                ? {
                    label: '⚠️ Inactive',
                    color: 'text-amber-400 bg-amber-500/10 border-amber-500/30',
                    tooltip: 'Aucun membre n\'a encore créé de compte.'
                }
                : {
                    label: '✅ Active',
                    color: 'text-green-400 bg-green-500/10 border-green-500/30',
                    tooltip: 'Accès autorisé et membres actifs.'
                };

    const handleRevokeWhitelist = async () => {
        if (!confirm("Révoquer l'autorisation de cette guilde ?")) return;
        setIsUpdating(true);
        try {
            await removeAllowedGuild(guild.discordGuildId);
            toast.success("Autorisation révoquée");
            window.location.reload();
        } catch (e) {
            toast.error("Échec de la révocation");
        } finally {
            setIsUpdating(false);
        }
    };

    return (
        <motion.tr
            layout
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className={`border-b border-zinc-800/50 hover:bg-zinc-800/30 transition-colors group ${isUpdating ? 'opacity-50 pointer-events-none' : ''}`}
        >
            <td className="p-4">
                <input
                    type="checkbox"
                    checked={selected}
                    onChange={onSelect}
                    className="w-4 h-4 rounded border-zinc-700 bg-zinc-900 checked:bg-violet-500 checked:border-violet-500 cursor-pointer"
                />
            </td>

            <td className="p-4">
                <div className="flex items-center gap-3">
                    <div className="relative group/icon">
                        {guild.iconUrl && guild.iconUrl.length > 5 ? (
                            <img
                                src={`https://cdn.discordapp.com/icons/${guild.discordGuildId}/${guild.iconUrl}.png?size=128`}
                                alt=""
                                className="w-10 h-10 rounded-xl border border-white/10 group-hover/icon:scale-110 transition-transform bg-zinc-800"
                                onError={(e) => {
                                    (e.target as HTMLImageElement).style.display = 'none';
                                    (e.target as HTMLImageElement).parentElement?.querySelector('.fallback-icon')?.classList.remove('hidden');
                                }}
                            />
                        ) : null}
                        <div className={`${guild.iconUrl && guild.iconUrl.length > 5 ? 'hidden' : ''} fallback-icon w-10 h-10 rounded-xl bg-gradient-to-br from-violet-500 to-violet-700 flex items-center justify-center text-white font-bold text-lg border border-white/10`}>
                            {guild.name[0]}
                        </div>
                    </div>
                    <div>
                        <div className="flex items-center gap-2">
                            <div className="font-medium">{guild.name}</div>
                            {guild.tier && (
                                <span className={`text-[9px] px-1.5 py-0.5 rounded font-black uppercase tracking-widest ${guild.tier === 'PREMIUM' ? 'bg-amber-500/20 text-amber-500 border border-amber-500/20' : 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20'
                                    }`}>
                                    {guild.tier}
                                </span>
                            )}
                        </div>
                        <div className="text-xs text-zinc-500 font-mono flex items-center gap-2">
                            {guild.discordGuildId}
                            {guild.notes && (
                                <span className="text-[10px] text-zinc-600 italic truncate max-w-[150px]">
                                    — {guild.notes}
                                </span>
                            )}
                        </div>
                    </div>
                </div>
            </td>

            <td className="p-4 hidden md:table-cell">
                <div className="space-y-1.5 min-w-[100px]">
                    <div className="flex items-center justify-between text-[10px]">
                        <div className="flex items-center gap-1 font-medium">
                            <Users className="w-3 h-3 text-zinc-500" />
                            <span>{guild._count.profiles}</span>
                        </div>
                        <span className="text-zinc-500 font-mono">/{guild.maxMembers}</span>
                    </div>
                    {/* Capacity Bar */}
                    <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden">
                        <div
                            className={`h-full rounded-full transition-all duration-1000 ${(guild._count.profiles / guild.maxMembers) >= 0.95 ? "bg-red-500" :
                                (guild._count.profiles / guild.maxMembers) >= 0.8 ? "bg-amber-500" :
                                    "bg-emerald-500"
                                }`}
                            style={{ width: `${Math.min(100, (guild._count.profiles / guild.maxMembers) * 100)}%` }}
                        />
                    </div>
                </div>
            </td>

            <td className="p-4 hidden sm:table-cell">
                <span
                    title={statusConfig.tooltip}
                    className={`inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-medium border ${statusConfig.color} cursor-help whitespace-nowrap`}
                >
                    {statusConfig.label}
                </span>
            </td>

            <td className="p-4 text-[10px] text-zinc-400 hidden lg:table-cell">
                {formatDistanceToNow(new Date(guild.createdAt), { addSuffix: true, locale: fr })}
            </td>

            <td className="p-4">
                <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    {/* SECURITY: Super admin should NOT have direct access to guild dashboards */}
                    {/* TODO: Create /god/guilds/[id] for read-only admin inspection */}
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <button className="p-2 hover:bg-zinc-800 rounded-lg transition-colors text-zinc-400 hover:text-white">
                                <MoreVertical className="w-4 h-4" />
                            </button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end" className="w-56 bg-zinc-950 border-white/10 text-zinc-300 shadow-2xl">
                            <DropdownMenuLabel className="text-xs text-zinc-500 uppercase tracking-widest p-3">Actions God Mode</DropdownMenuLabel>
                            <DropdownMenuSeparator className="bg-white/5" />

                            {!guild.isWhitelistOnly && (
                                <>
                                    <DropdownMenuItem asChild className="gap-3 p-3 cursor-pointer focus:bg-violet-500/10 focus:text-violet-400">
                                        <Link href={`/god/guilds/${guild.id}`}>
                                            <Eye className="w-4 h-4" />
                                            Voir le Roster
                                        </Link>
                                    </DropdownMenuItem>

                                </>
                            )}

                            {guild.isWhitelistOnly ? (
                                <>
                                    <DropdownMenuItem
                                        onClick={() => {
                                            navigator.clipboard.writeText(guild.discordGuildId);
                                            toast.success("ID Discord copié");
                                        }}
                                        className="gap-3 p-3 cursor-pointer focus:bg-blue-500/10 focus:text-blue-400"
                                    >
                                        <Copy className="w-4 h-4" />
                                        Copier ID Discord
                                    </DropdownMenuItem>
                                    <DropdownMenuItem
                                        onClick={handleRevokeWhitelist}
                                        className="gap-3 p-3 cursor-pointer focus:bg-red-500/10 focus:text-red-400 font-bold"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                        Révoquer Permission
                                    </DropdownMenuItem>
                                </>
                            ) : (
                                <>
                                    {!guild.deletedAt ? (
                                        <DropdownMenuItem
                                            onClick={handleSoftDelete}
                                            className="gap-3 p-3 cursor-pointer focus:bg-amber-500/10 focus:text-amber-400"
                                        >
                                            <Archive className="w-4 h-4" />
                                            Mettre en pause
                                        </DropdownMenuItem>
                                    ) : (
                                        <DropdownMenuItem
                                            onClick={handleReactivate}
                                            className="gap-3 p-3 cursor-pointer focus:bg-emerald-500/10 focus:text-emerald-400"
                                        >
                                            <RotateCcw className="w-4 h-4" />
                                            Réactiver
                                        </DropdownMenuItem>
                                    )}

                                    <DropdownMenuItem
                                        onClick={handleHardDelete}
                                        className="gap-3 p-3 cursor-pointer focus:bg-red-500/10 focus:text-red-400"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                        Hard Delete
                                    </DropdownMenuItem>
                                </>
                            )}
                        </DropdownMenuContent>
                    </DropdownMenu>
                </div>
            </td>
        </motion.tr >
    );
}

/**
 * ♻️ GOD Dashboard - Lifecycle Management Panel
 * 
 * Manage soft-deleted entities + Platform Bans:
 * - Tab 1: Guilds pending deletion
 * - Tab 2: Profiles pending deletion
 * - Tab 3: Archived profiles (orphans) with filters
 * - Tab 4: Platform bans (guilds + users)
 */

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    AlertTriangle, RefreshCw, Trash2, Clock, Building2, User,
    ShieldBan, Filter, Archive, Ban, UserX, Info, Search, Copy, Calendar, MousePointer2, CalendarCheck, Loader2
} from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { cleanupGhostUsers, deleteGhostUser } from "@/server/actions/super-admin-actions";
import { JanitorButton } from '../janitor-button';
import { formatDistanceToNow, differenceInDays } from 'date-fns';
import { fr } from 'date-fns/locale';

// ====================
// Types
// ====================

interface SoftDeletedGuild {
    id: string;
    name: string;
    deletedAt: Date;
    deletionReason: string;
    scheduledDeletion: Date;
    _count: {
        profiles: number;
    };
}

interface SoftDeletedProfile {
    id: string;
    archivedAt: Date | null;
    archiveReason: string | null;
    scheduledDeletion: Date | null;
    guild: { name: string };
    user: { name: string | null };
}

interface ArchivedProfile {
    id: string;
    archivedAt: Date | null;
    archiveReason: string | null;
    scheduledDeletion: Date | null;
    guild: { name: string };
    user: { name: string | null };
}

interface PlatformBanItem {
    id: string;
    entityType: string;
    discordId: string;
    reason: string;
    bannedBy: string;
    createdAt: Date;
}

interface ActiveGuild {
    id: string;
    name: string;
}

interface GhostUser {
    id: string;
    name: string | null;
    image: string | null;
    createdAt: Date;
    _count: {
        sessions: number;
        guildEvents: number;
    };
    memberInWhitelists?: string[];
}

type TabId = 'guilds' | 'profiles' | 'orphans' | 'bans' | 'ghosts' | 'unauthorized';

interface LifecyclePanelProps {
    guilds: SoftDeletedGuild[];
    profiles: SoftDeletedProfile[];
    archivedProfiles: ArchivedProfile[];
    bans: PlatformBanItem[];
    activeGuilds: ActiveGuild[];
    ghostUsers: GhostUser[];
    unauthorizedConnections: Array<{ id: string; name: string; icon: string | null }>;
}

// ====================
// Main Panel
// ====================

export function LifecyclePanel({
    guilds,
    profiles,
    archivedProfiles,
    bans,
    activeGuilds,
    ghostUsers,
    unauthorizedConnections = []
}: LifecyclePanelProps) {
    const [activeTab, setActiveTab] = useState<TabId>('guilds');

    const totalPending = guilds.length + profiles.length + unauthorizedConnections.length;

    const tabs: { id: TabId; label: string; icon: React.ReactNode; count: number; color: string }[] = [
        { id: 'guilds', label: 'Guildes', icon: <Building2 className="w-4 h-4" />, count: guilds.length, color: 'text-amber-400' },
        { id: 'profiles', label: 'Profils', icon: <User className="w-4 h-4" />, count: profiles.length, color: 'text-rose-400' },
        { id: 'unauthorized', label: 'Suspects', icon: <ShieldBan className="w-4 h-4" />, count: unauthorizedConnections.length, color: 'text-orange-500' },
        { id: 'ghosts', label: 'Fantômes', icon: <UserX className="w-4 h-4" />, count: ghostUsers.length, color: 'text-purple-400' },
        { id: 'orphans', label: 'Orphelins', icon: <Archive className="w-4 h-4" />, count: archivedProfiles.length, color: 'text-zinc-400' },
        { id: 'bans', label: 'Bannis', icon: <ShieldBan className="w-4 h-4" />, count: bans.length, color: 'text-red-500' },
    ];

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-bold bg-gradient-to-r from-amber-200 to-amber-500 bg-clip-text text-transparent uppercase tracking-tighter">
                        🛠️ State & Maintenance
                    </h2>
                    <p className="text-sm text-zinc-500 mt-1 uppercase text-[10px] font-bold tracking-widest leading-relaxed">
                        Gestion centralisée du cycle de vie des données, des fantômes et de la sécurité plateforme.
                    </p>
                </div>

                <div className="flex items-center gap-3">
                    {totalPending > 0 && (
                        <div className="flex items-center gap-2 px-3 py-1.5 bg-rose-500/10 border border-rose-500/30 rounded-lg animate-pulse">
                            <AlertTriangle className="w-3.5 h-3.5 text-rose-400" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-rose-400">
                                Attention ({totalPending} Anomalies)
                            </span>
                        </div>
                    )}
                    {/* The sidebar is now part of the content flow or available via tabs */}
                </div>
            </div>

            {/* Tabs */}
            <div className="flex gap-1 border-b border-zinc-800 overflow-x-auto">
                {tabs.map((tab) => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        className={`px-4 py-2 -mb-px border-b-2 transition-colors whitespace-nowrap ${activeTab === tab.id
                            ? 'border-violet-500 text-violet-400'
                            : 'border-transparent text-zinc-500 hover:text-zinc-300'
                            }`}
                    >
                        <div className="flex items-center gap-2">
                            {tab.icon}
                            {tab.label} ({tab.count})
                        </div>
                    </button>
                ))}
            </div>

            {/* Content */}
            <AnimatePresence mode="wait">
                    <TabContent key="guilds">
                        <div className="p-4 bg-amber-500/5 border border-amber-500/10 rounded-xl mb-4 flex items-start gap-4">
                            <Info className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                            <div className="space-y-1">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-amber-500">Hygiène des Guildes</h4>
                                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium">
                                    <strong>Réactiver :</strong> Restaure l'accès immédiat et annule le compte à rebours. <br/>
                                    <strong>Supprimer :</strong> Efface PHYSIQUEMENT toutes les données (Missions, Stocks, Roster) de la base. Action IRRÉVERSIBLE.
                                </p>
                            </div>
                        </div>
                        {guilds.length === 0 ? (
                            <EmptyState>✅ Aucune guilde en attente de suppression</EmptyState>
                        ) : (
                            guilds.map((guild) => (
                                <GuildLifecycleCard key={guild.id} guild={guild} />
                            ))
                        )}
                    </TabContent>

                {activeTab === 'profiles' && (
                    <TabContent key="profiles">
                        {profiles.length === 0 ? (
                            <EmptyState>✅ Aucun profil en attente de suppression</EmptyState>
                        ) : (
                            profiles.map((profile) => (
                                <ProfileLifecycleCard key={profile.id} profile={profile} />
                            ))
                        )}
                    </TabContent>
                )}

                {activeTab === 'unauthorized' && (
                    <TabContent key="unauthorized">
                         <div className="p-4 bg-orange-500/5 border border-orange-500/10 rounded-xl mb-4 flex items-start gap-4">
                            <ShieldBan className="w-5 h-5 text-orange-500 shrink-0 mt-0.5" />
                            <div className="space-y-1">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-orange-500">Connexions non autorisées</h4>
                                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium">
                                    Ces serveurs Discord ont ajouté le bot mais ne sont PAS dans la liste blanche (Whitelist). 
                                    Le bot est inactif sur ces serveurs mais consomme des ressources de gateway.
                                </p>
                            </div>
                        </div>
                        {unauthorizedConnections.length === 0 ? (
                            <EmptyState>✅ Aucune connexion parasite détectée</EmptyState>
                        ) : (
                            <div className="space-y-2">
                                {unauthorizedConnections.map(g => (
                                    <div key={g.id} className="flex items-center justify-between p-4 bg-orange-500/5 border border-orange-500/10 rounded-xl">
                                        <div className="flex items-center gap-3">
                                            {g.icon ? (
                                                <img src={`https://cdn.discordapp.com/icons/${g.id}/${g.icon}.png`} className="w-10 h-10 rounded-lg" alt="" />
                                            ) : (
                                                <div className="w-10 h-10 bg-zinc-800 rounded-lg flex items-center justify-center text-xs font-bold text-zinc-600">?</div>
                                            )}
                                            <div>
                                                <div className="font-bold text-sm text-zinc-200">{g.name}</div>
                                                <div className="text-[10px] font-mono text-zinc-500">{g.id}</div>
                                            </div>
                                        </div>
                                        <button 
                                            onClick={async () => {
                                                if(!confirm(`Bannir cette guilde (${g.name}) de la plateforme ?`)) return;
                                                const { banEntity } = await import('@/server/actions/god-lifecycle-actions');
                                                await banEntity('GUILD', g.id, "Connexion non autorisée détectée");
                                                window.location.reload();
                                            }}
                                            className="px-3 py-1.5 bg-red-500/10 hover:bg-red-500/20 text-red-500 rounded-lg text-xs font-black uppercase tracking-widest"
                                        >
                                            Bannir
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </TabContent>
                )}

                {activeTab === 'ghosts' && (
                    <TabContent key="ghosts">
                         <div className="p-4 bg-purple-500/5 border border-purple-500/10 rounded-xl mb-4 flex items-start gap-4">
                            <Info className="w-5 h-5 text-purple-500 shrink-0 mt-0.5" />
                            <div className="space-y-1">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-purple-400">Nettoyage des Fantômes</h4>
                                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium">
                                    Comptes Discord sans profil de guilde (vieux de <strong>&gt;24h</strong> - GDPR). 
                                    La purge supprime l'entrée "User" et les sessions de connexion. 
                                    Aucune perte de progression métier/xp possible ici.
                                </p>
                            </div>
                            <div className="ml-auto">
                                <JanitorButton />
                            </div>
                        </div>
                        <GhostPurgeTab users={ghostUsers} />
                    </TabContent>
                )}

                {activeTab === 'orphans' && (
                    <TabContent key="orphans">
                         <div className="p-4 bg-zinc-500/5 border border-zinc-500/10 rounded-xl mb-4 flex items-start gap-4">
                            <Archive className="w-5 h-5 text-zinc-500 shrink-0 mt-0.5" />
                            <div className="space-y-1">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Nettoyage technique</h4>
                                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium">
                                    Profils existants sans compte Discord lié (suite à une désynchronisation ou suppression manuelle brute).
                                </p>
                            </div>
                            <div className="ml-auto">
                                <JanitorButton />
                            </div>
                        </div>
                        <OrphanPanel profiles={archivedProfiles} activeGuilds={activeGuilds} />
                    </TabContent>
                )}

                {activeTab === 'bans' && (
                    <TabContent key="bans">
                        <section className="p-4 bg-red-500/5 border border-red-500/10 rounded-xl mb-4 flex items-start gap-4">
                            <ShieldBan className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                            <div className="space-y-1">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-red-500">Zone de Bannissement</h4>
                                <p className="text-[10px] text-zinc-500 leading-relaxed font-medium">
                                   Le ban plateforme bloque l'accès au BOT sur TOUTES les guildes pour l'ID spécifié. 
                                   Pour une guilde bannie, le bot ne répondra plus à aucune commande sur ce serveur.
                                </p>
                            </div>
                        </section>
                        <BanPanel bans={bans} />
                    </TabContent>
                )}
            </AnimatePresence>
        </div>
    );
}

// ====================
// Shared Components
// ====================

function TabContent({ children, ...props }: { children: React.ReactNode } & Record<string, unknown>) {
    return (
        <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-3"
            {...props}
        >
            {children}
        </motion.div>
    );
}

function EmptyState({ children }: { children: React.ReactNode }) {
    return (
        <div className="p-12 text-center text-zinc-500 bg-zinc-900/30 backdrop-blur-sm border border-zinc-800/60 rounded-xl">
            {children}
        </div>
    );
}

// ====================
// Guild Card (unchanged behavior)
// ====================

function GuildLifecycleCard({ guild }: { guild: SoftDeletedGuild }) {
    const [loading, setLoading] = useState(false);

    const daysRemaining = guild.scheduledDeletion
        ? differenceInDays(new Date(guild.scheduledDeletion), new Date())
        : null;
    const isUrgent = daysRemaining !== null && daysRemaining <= 7;

    const reasonLabel = {
        'SERVER_DELETED': '🏰 Serveur Discord supprimé',
        'BOT_REMOVED': '🤖 Bot retiré du serveur',
        'ADMIN_REQUEST': '👮 Demande administrateur',
    }[guild.deletionReason] || guild.deletionReason;

    const handleReactivate = async () => {
        setLoading(true);
        try {
            const { reactivateGuild } = await import('@/server/actions/god-lifecycle-actions');
            const result = await reactivateGuild(guild.id);
            if (result.success) {
                window.location.reload();
            } else {
                alert(result.error || 'Erreur lors de la réactivation');
            }
        } catch (error) {
            console.error('[LifecyclePanel] Reactivate error:', error);
            alert('Erreur lors de la réactivation');
        } finally {
            setLoading(false);
        }
    };

    const handleHardDelete = async () => {
        if (!confirm(`Supprimer définitivement "${guild.name}" et ses ${guild._count.profiles} profils ?\n\n⚠️ CETTE ACTION EST IRRÉVERSIBLE`)) return;
        setLoading(true);
        try {
            const { hardDeleteGuild } = await import('@/server/actions/god-lifecycle-actions');
            const result = await hardDeleteGuild(guild.id);
            if (result.success) {
                window.location.reload();
            } else {
                alert(result.error || 'Erreur lors de la suppression');
            }
        } catch (error) {
            console.error('[LifecyclePanel] Hard delete error:', error);
            alert('Erreur lors de la suppression');
        } finally {
            setLoading(false);
        }
    };

    return (
        <motion.div
            layout
            className={`
        relative overflow-hidden rounded-xl p-5
        bg-zinc-900/30 backdrop-blur-sm
        border ${isUrgent ? 'border-red-500/30' : 'border-zinc-800/60'}
        ${isUrgent ? 'shadow-lg shadow-red-500/10' : ''}
      `}
        >
            {isUrgent && (
                <div className="absolute inset-0 bg-gradient-to-r from-red-500/5 via-transparent to-transparent" />
            )}

            <div className="relative z-10 flex items-start justify-between gap-4">
                <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                        <h3 className="font-bold text-lg">{guild.name}</h3>
                        {isUrgent && (
                            <div className="px-2 py-1 bg-red-500/20 border border-red-500/30 rounded text-xs text-red-400 font-medium">
                                ⚠️ Urgent
                            </div>
                        )}
                    </div>

                    <div className="grid grid-cols-2 gap-4 text-sm">
                        <div>
                            <div className="text-zinc-500">Raison</div>
                            <div className="font-medium">{reasonLabel}</div>
                        </div>
                        <div>
                            <div className="text-zinc-500">Membres affectés</div>
                            <div className="font-medium">{guild._count.profiles}</div>
                        </div>
                        <div>
                            <div className="text-zinc-500">Supprimé</div>
                            <div className="font-medium">
                                {formatDistanceToNow(new Date(guild.deletedAt), { addSuffix: true, locale: fr })}
                            </div>
                        </div>
                        <div>
                            <div className="text-zinc-500">Suppression définitive</div>
                            <div className={`font-medium flex items-center gap-1 ${isUrgent ? 'text-red-400' : 'text-amber-400'}`}>
                                <Clock className="w-3 h-3" />
                                {daysRemaining !== null ? `Dans ${daysRemaining}j` : 'Non planifiée'}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex gap-2">
                    <button
                        onClick={handleReactivate}
                        disabled={loading}
                        className="px-4 py-2 bg-green-500/10 hover:bg-green-500/20 border border-green-500/30 rounded-lg text-green-400 font-medium text-sm transition-colors disabled:opacity-50 flex items-center gap-2"
                    >
                        <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
                        Réactiver
                    </button>
                    <button
                        onClick={handleHardDelete}
                        disabled={loading}
                        className="px-4 py-2 bg-red-500/10 hover:bg-red-500/20 border border-red-500/30 rounded-lg text-red-400 font-medium text-sm transition-colors disabled:opacity-50 flex items-center gap-2"
                    >
                        <Trash2 className="w-4 h-4" />
                        Supprimer
                    </button>
                </div>
            </div>
        </motion.div>
    );
}

// ====================
// Profile Card (unchanged behavior)
// ====================

function ProfileLifecycleCard({ profile }: { profile: SoftDeletedProfile }) {
    const [loading, setLoading] = useState(false);

    const daysRemaining = profile.scheduledDeletion
        ? differenceInDays(new Date(profile.scheduledDeletion), new Date())
        : null;
    const isUrgent = daysRemaining !== null && daysRemaining <= 3;

    const reasonLabel = (profile.archiveReason ? (({
        'KICKED': '👢 Kick du Discord',
        'BANNED': '🔨 Ban du Discord',
        'LEFT': '🚪 Départ volontaire',
        'GUILD_DELETED': '🏰 Guilde supprimée',
    } as any)[profile.archiveReason]) : 'Raison inconnue') || profile.archiveReason;

    return (
        <motion.div
            layout
            className={`
        flex items-center justify-between p-4
        bg-zinc-900/30 backdrop-blur-sm
        border ${isUrgent ? 'border-red-500/30' : 'border-zinc-800/60'}
        rounded-lg
      `}
        >
            <div className="flex-1 grid grid-cols-4 gap-4 text-sm">
                <div>
                    <div className="font-medium text-zinc-200">{profile.user.name || 'Inconnu'}</div>
                    <div className="text-xs text-zinc-500">{profile.guild.name}</div>
                </div>
                <div>
                    <div className="text-zinc-500">Raison</div>
                    <div>{reasonLabel}</div>    </div>
                <div>
                    <div className="text-zinc-500">Supprimé</div>
                    <div>{profile.archivedAt ? formatDistanceToNow(new Date(profile.archivedAt), { addSuffix: true, locale: fr }) : '—'}</div>
                </div>
                <div>
                    <div className="text-zinc-500">Dans</div>
                    <div className={isUrgent ? 'text-red-400 font-medium' : ''}>
                        {daysRemaining !== null ? `${daysRemaining}j` : 'Non planifiée'}
                    </div>
                </div>
            </div>

            <div className="flex gap-2">
                <button
                    onClick={async () => {
                        setLoading(true);
                        try {
                            const { reactivateProfile } = await import('@/server/actions/god-lifecycle-actions');
                            const result = await reactivateProfile(profile.id);
                            if (result.success) {
                                window.location.reload();
                            } else {
                                alert(result.error || 'Erreur lors de la réactivation');
                            }
                        } catch (error) {
                            console.error('[LifecyclePanel] Reactivate profile error:', error);
                            alert('Erreur lors de la réactivation');
                        } finally {
                            setLoading(false);
                        }
                    }}
                    disabled={loading}
                    className="p-2 hover:bg-green-500/10 rounded-lg text-green-400 transition-colors disabled:opacity-50"
                    title="Réactiver"
                >
                    <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
                </button>

                <button
                    onClick={async () => {
                        if (!confirm(`Supprimer définitivement le profil de ${profile.user.name || 'cet utilisateur'} ?\n\n⚠️ CETTE ACTION EST IRRÉVERSIBLE`)) return;
                        setLoading(true);
                        try {
                            const { hardDeleteProfile } = await import('@/server/actions/god-lifecycle-actions');
                            const result = await hardDeleteProfile(profile.id);
                            if (result.success) {
                                window.location.reload();
                            } else {
                                alert(result.error || 'Erreur lors de la suppression');
                            }
                        } catch (error) {
                            console.error('[LifecyclePanel] Hard delete profile error:', error);
                            alert('Erreur lors de la suppression');
                        } finally {
                            setLoading(false);
                        }
                    }}
                    disabled={loading}
                    className="p-2 hover:bg-red-500/10 rounded-lg text-red-400 transition-colors disabled:opacity-50"
                    title="Supprimer"
                >
                    <Trash2 className="w-4 h-4" />
                </button>
            </div>
        </motion.div>
    );
}

// ====================
// Orphan Panel (NEW - filtered archived profiles)
// ====================

function OrphanPanel({
    profiles,
    activeGuilds,
}: {
    profiles: ArchivedProfile[];
    activeGuilds: ActiveGuild[];
}) {
    const [filterGuild, setFilterGuild] = useState<string>('');
    const [filterReason, setFilterReason] = useState<string>('');

    const filtered = profiles.filter((p) => {
        if (filterGuild && p.guild.name !== filterGuild) return false;
        if (filterReason && p.archiveReason !== filterReason) return false;
        return true;
    });

    return (
        <div className="space-y-4">
            {/* Filters */}
            <div className="flex items-center gap-3 flex-wrap">
                <div className="flex items-center gap-2 text-sm text-zinc-500">
                    <Filter className="w-4 h-4" />
                    Filtres :
                </div>

                <select
                    value={filterGuild}
                    onChange={(e) => setFilterGuild(e.target.value)}
                    className="px-3 py-1.5 bg-zinc-900/50 border border-zinc-700/50 rounded-lg text-sm text-zinc-300 focus:outline-none focus:border-violet-500/50"
                >
                    <option value="">Toutes les guildes</option>
                    {activeGuilds.map((g) => (
                        <option key={g.id} value={g.name}>{g.name}</option>
                    ))}
                </select>

                <select
                    value={filterReason}
                    onChange={(e) => setFilterReason(e.target.value)}
                    className="px-3 py-1.5 bg-zinc-900/50 border border-zinc-700/50 rounded-lg text-sm text-zinc-300 focus:outline-none focus:border-violet-500/50"
                >
                    <option value="">Toutes les raisons</option>
                    <option value="LEFT">🚪 Départ</option>
                    <option value="KICKED">👢 Kick</option>
                    <option value="BANNED">🔨 Ban</option>
                    <option value="GUILD_DELETED">🏰 Guilde supprimée</option>
                </select>

                {(filterGuild || filterReason) && (
                    <button
                        onClick={() => { setFilterGuild(''); setFilterReason(''); }}
                        className="text-xs text-zinc-500 hover:text-zinc-300 underline"
                    >
                        Réinitialiser
                    </button>
                )}
            </div>

            {/* Results */}
            <div className="text-xs text-zinc-600 mb-2">
                {filtered.length} profil{filtered.length > 1 ? 's' : ''} archivé{filtered.length > 1 ? 's' : ''}
            </div>

            {filtered.length === 0 ? (
                <EmptyState>✅ Aucun profil orphelin</EmptyState>
            ) : (
                <div className="space-y-2">
                    {filtered.map((profile) => (
                        <div
                            key={profile.id}
                            className="flex items-center justify-between p-3 bg-zinc-900/30 border border-zinc-800/60 rounded-lg text-sm"
                        >
                            <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-full bg-zinc-800 border border-zinc-700/50 flex items-center justify-center text-zinc-500 text-xs shadow-inner">
                                    <Archive className="w-4 h-4" />
                                </div>
                                <div>
                                    <div className="font-medium text-zinc-200">{profile.user.name || 'Inconnu'}</div>
                                    <div className="text-xs text-zinc-500">{profile.guild.name}</div>
                                </div>
                            </div>

                            <div className="flex items-center gap-4">
                                <div className="text-zinc-500 text-xs">
                                    {{
                                        'LEFT': '🚪 Départ',
                                        'KICKED': '👢 Kick',
                                        'BANNED': '🔨 Ban',
                                        'GUILD_DELETED': '🏰 Guilde',
                                    }[profile.archiveReason || ''] || profile.archiveReason}
                                </div>
                                <div className="flex flex-col items-end gap-1">
                                    <div className="text-zinc-600 text-[10px] font-medium">
                                        {profile.archivedAt
                                            ? formatDistanceToNow(new Date(profile.archivedAt), { addSuffix: true, locale: fr })
                                            : '—'}
                                    </div>
                                    {profile.scheduledDeletion && (
                                        <div className={`flex items-center gap-1 text-[9px] font-black uppercase tracking-tighter px-1.5 py-0.5 rounded ${
                                            differenceInDays(new Date(profile.scheduledDeletion), new Date()) <= 3
                                                ? 'bg-red-500/10 text-red-500 animate-pulse'
                                                : 'bg-amber-500/10 text-amber-500'
                                        }`}>
                                            <Clock className="w-2.5 h-2.5" />
                                            J-{differenceInDays(new Date(profile.scheduledDeletion), new Date())}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

// ====================
// Ban Panel (NEW - platform bans)
// ====================

function BanPanel({ bans }: { bans: PlatformBanItem[] }) {
    const [loading, setLoading] = useState<string | null>(null);
    const [showBanForm, setShowBanForm] = useState(false);
    const [banType, setBanType] = useState<'GUILD' | 'USER'>('GUILD');
    const [banDiscordId, setBanDiscordId] = useState('');
    const [banReason, setBanReason] = useState('');

    const handleUnban = async (banId: string) => {
        if (!confirm('Lever ce ban plateforme ?')) return;
        setLoading(banId);
        try {
            const { unbanEntity } = await import('@/server/actions/god-lifecycle-actions');
            const result = await unbanEntity(banId);
            if (result.success) {
                window.location.reload();
            } else {
                alert(result.error || 'Erreur');
            }
        } catch (error) {
            console.error('[BanPanel] Unban error:', error);
            alert('Erreur lors du débannissement');
        } finally {
            setLoading(null);
        }
    };

    const handleBan = async () => {
        if (!banDiscordId.trim() || !banReason.trim()) return;
        if (!confirm(`Bannir ${banType === 'GUILD' ? 'la guilde' : "l'utilisateur"} ${banDiscordId} de SigilOS ?\n\nRaison : ${banReason}`)) return;

        setLoading('new');
        try {
            const { banEntity } = await import('@/server/actions/god-lifecycle-actions');
            const result = await banEntity(banType, banDiscordId.trim(), banReason.trim());
            if (result.success) {
                window.location.reload();
            } else {
                alert(result.error || 'Erreur');
            }
        } catch (error) {
            console.error('[BanPanel] Ban error:', error);
            alert('Erreur lors du bannissement');
        } finally {
            setLoading(null);
        }
    };

    return (
        <div className="space-y-4">
            {/* Add Ban */}
            <div className="flex justify-end">
                <button
                    onClick={() => setShowBanForm(!showBanForm)}
                    className="px-4 py-2 bg-red-500/10 hover:bg-red-500/20 border border-red-500/30 rounded-lg text-red-400 font-medium text-sm transition-colors flex items-center gap-2"
                >
                    <Ban className="w-4 h-4" />
                    {showBanForm ? 'Annuler' : 'Nouveau ban'}
                </button>
            </div>

            {/* Ban Form */}
            <AnimatePresence>
                {showBanForm && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="overflow-hidden"
                    >
                        <div className="p-4 bg-red-500/5 border border-red-500/20 rounded-xl space-y-3">
                            <div className="flex gap-3">
                                <select
                                    value={banType}
                                    onChange={(e) => setBanType(e.target.value as 'GUILD' | 'USER')}
                                    className="px-3 py-2 bg-zinc-900/50 border border-zinc-700/50 rounded-lg text-sm text-zinc-300 focus:outline-none focus:border-red-500/50"
                                >
                                    <option value="GUILD">🏰 Guilde</option>
                                    <option value="USER">👤 Utilisateur</option>
                                </select>

                                <input
                                    type="text"
                                    value={banDiscordId}
                                    onChange={(e) => setBanDiscordId(e.target.value)}
                                    placeholder="Discord ID"
                                    className="flex-1 px-3 py-2 bg-zinc-900/50 border border-zinc-700/50 rounded-lg text-sm text-zinc-300 placeholder:text-zinc-600 focus:outline-none focus:border-red-500/50"
                                />
                            </div>

                            <input
                                type="text"
                                value={banReason}
                                onChange={(e) => setBanReason(e.target.value)}
                                placeholder="Raison du ban..."
                                className="w-full px-3 py-2 bg-zinc-900/50 border border-zinc-700/50 rounded-lg text-sm text-zinc-300 placeholder:text-zinc-600 focus:outline-none focus:border-red-500/50"
                            />

                            <button
                                onClick={handleBan}
                                disabled={!banDiscordId.trim() || !banReason.trim() || loading === 'new'}
                                className="w-full px-4 py-2 bg-red-600 hover:bg-red-700 rounded-lg text-white font-medium text-sm transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                <ShieldBan className="w-4 h-4" />
                                Bannir de SigilOS
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Ban List */}
            {bans.length === 0 ? (
                <EmptyState>✅ Aucun ban plateforme actif</EmptyState>
            ) : (
                <div className="space-y-2">
                    {bans.map((ban) => (
                        <div
                            key={ban.id}
                            className="flex items-center justify-between p-4 bg-zinc-900/30 border border-red-500/10 rounded-lg"
                        >
                            <div className="flex items-center gap-4">
                                <div className={`px-2 py-1 rounded text-xs font-medium ${ban.entityType === 'GUILD'
                                    ? 'bg-violet-500/20 text-violet-400'
                                    : 'bg-blue-500/20 text-blue-400'
                                    }`}>
                                    {ban.entityType === 'GUILD' ? '🏰 Guilde' : '👤 User'}
                                </div>
                                <div>
                                    <div className="font-mono text-sm text-zinc-300">{ban.discordId}</div>
                                    <div className="text-xs text-zinc-500">{ban.reason}</div>
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <div className="text-xs text-zinc-600">
                                    {formatDistanceToNow(new Date(ban.createdAt), { addSuffix: true, locale: fr })}
                                </div>
                                <button
                                    onClick={() => handleUnban(ban.id)}
                                    disabled={loading === ban.id}
                                    className="px-3 py-1.5 bg-green-500/10 hover:bg-green-500/20 border border-green-500/30 rounded-lg text-green-400 text-xs font-medium transition-colors disabled:opacity-50"
                                >
                                    Lever le ban
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

// ====================
// Ghost Purge Sub-Panel (Integrated)
// ====================

function GhostPurgeTab({ users }: { users: GhostUser[] }) {
    const [isPurgingAll, setIsPurgingAll] = useState(false);
    const [purgingId, setPurgingId] = useState<string | null>(null);
    const [search, setSearch] = useState("");

    const filtered = users.filter(u => 
        !search || u.name?.toLowerCase().includes(search.toLowerCase()) || u.id.toLowerCase().includes(search.toLowerCase())
    );

    const handlePurgeAll = async () => {
        if (!confirm("Voulez-vous purger TOUS les fantômes (comptes sans profil) vieux de plus de 24h ?")) return;
        setIsPurgingAll(true);
        try {
            const res = await cleanupGhostUsers();
            if (res.success) toast.success(`${res.count} fantômes purgés.`);
            else toast.error("Erreur.");
        } finally { setIsPurgingAll(false); }
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between gap-4">
                <div className="relative group flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
                    <Input 
                        placeholder="Rechercher Fantôme..." 
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-10 bg-zinc-900/50 border-zinc-800"
                    />
                </div>
                <Button variant="destructive" size="sm" onClick={handlePurgeAll} disabled={isPurgingAll || users.length === 0}>
                    <Trash2 className="w-4 h-4 mr-2" /> Tout Purger
                </Button>
            </div>

            <div className="space-y-2">
                {filtered.map(user => (
                    <div key={user.id} className="flex items-center justify-between p-3 bg-zinc-900/30 border border-zinc-800/60 rounded-lg">
                        <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-lg bg-zinc-800 flex items-center justify-center">
                                <UserX className="w-4 h-4 text-zinc-500" />
                            </div>
                            <div>
                                <div className="text-sm font-bold text-zinc-300">{user.name || 'Fantôme Inconnu'}</div>
                                <div className="text-[10px] text-zinc-600 font-mono tracking-tighter">{user.id}</div>
                            </div>
                        </div>
                        <Button 
                            variant="ghost" 
                            size="icon" 
                            onClick={async () => {
                                if(!confirm('Supprimer ce compte Discord ?')) return;
                                setPurgingId(user.id);
                                try {
                                    await deleteGhostUser(user.id);
                                } finally {
                                    setPurgingId(null);
                                }
                            }}
                            disabled={purgingId === user.id}
                        >
                            {purgingId === user.id ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4 text-zinc-600 hover:text-red-500" />}
                        </Button>
                    </div>
                ))}
            </div>
        </div>
    );
}

/**
 * 🎨 GOD Dashboard - Live Stats Component (Refactored for Clarity)
 */

'use client';

import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { TrendingUp, TrendingDown, Minus } from 'lucide-react';

interface PlatformStats {
    guilds: number;
    guildsTrend: number;
    activeGuilds: number;
    users: number;
    usersTrend: number;
    profiles: number;
    activeProfiles: number;
    missions: number;
    missionsTrend: number;
    weeklyActiveUsers: number;
    retentionRate: number;
    density: number;
}

interface StatCardProps {
    label: string;
    value: number;
    trend?: number;
    suffix?: string;
    color: 'violet' | 'green' | 'amber' | 'cyan' | 'blue';
    icon: string;
    realtime?: boolean;
    description?: string;
}

export function LiveStats({ initialStats }: { initialStats: PlatformStats }) {
    const [stats, setStats] = useState(initialStats);

    useEffect(() => {
        const eventSource = new EventSource('/api/god/stats/stream');

        eventSource.onmessage = (event) => {
            const newStats = JSON.parse(event.data);
            setStats(newStats);
        };

        eventSource.onerror = () => {
            eventSource.close();
        };

        return () => eventSource.close();
    }, []);

    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 md:gap-6">
            <StatCard
                label="Guildes"
                value={stats.guilds}
                trend={stats.guildsTrend}
                color="violet"
                icon="🏰"
                description="Total des guildes enregistrées"
                realtime
            />

            <StatCard
                label="Aventuriers"
                value={stats.users}
                trend={stats.usersTrend}
                color="blue"
                icon="👥"
                description="Membres totaux SigilOS"
                realtime
            />

            <StatCard
                label="Actifs (7j)"
                value={stats.weeklyActiveUsers}
                color="green"
                icon="⚡"
                description="Utilisateurs uniques sur 7 jours"
                realtime
            />

            <StatCard
                label="Missions"
                value={stats.missions}
                trend={stats.missionsTrend}
                color="amber"
                icon="📋"
                description="Total des quêtes validées"
                realtime
            />

            <StatCard
                label="Engagement"
                value={stats.retentionRate}
                suffix="%"
                color="cyan"
                icon="📊"
                description="Adhésion profil / compte"
            />
        </div>
    );
}

function StatCard({ label, value, trend, suffix = "", color, icon, realtime, description }: StatCardProps) {
    const [displayValue, setDisplayValue] = useState(value);

    useEffect(() => {
        if (displayValue === value) return;
        const duration = 1000;
        const steps = 30;
        const stepValue = (value - displayValue) / steps;
        let currentStep = 0;

        const interval = setInterval(() => {
            currentStep++;
            setDisplayValue(prev => {
                const newValue = prev + stepValue;
                return currentStep >= steps ? value : newValue;
            });
            if (currentStep >= steps) clearInterval(interval);
        }, duration / steps);

        return () => clearInterval(interval);
    }, [value, displayValue]);

    const colorConfig = {
        violet: 'border-violet-500/30 text-violet-400 shadow-violet-500/20 from-violet-500/20',
        green: 'border-green-500/30 text-green-400 shadow-green-500/20 from-green-500/20',
        amber: 'border-amber-500/30 text-amber-400 shadow-amber-500/20 from-amber-500/20',
        cyan: 'border-cyan-500/30 text-cyan-400 shadow-cyan-500/20 from-cyan-500/20',
        blue: 'border-blue-500/30 text-blue-400 shadow-blue-500/20 from-blue-500/20'
    }[color];

    return (
        <motion.div
            whileHover={{ scale: 1.02, y: -5 }}
            className={`relative overflow-hidden rounded-3xl bg-zinc-900/40 backdrop-blur-xl border ${colorConfig.split(' ')[0]} shadow-2xl p-6 group transition-all duration-500`}
        >
            <div className={`absolute inset-0 bg-gradient-to-br ${colorConfig.split(' ').pop()} via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500`} />

            <div className="relative z-10 flex flex-col h-full justify-between">
                <div className="flex items-center justify-between mb-4">
                    <div className="text-3xl filter drop-shadow-md group-hover:scale-110 transition-transform">
                        {icon}
                    </div>
                    {realtime && (
                        <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-emerald-500/10 border border-emerald-500/20">
                            <motion.div animate={{ opacity: [0.3, 1, 0.3] }} transition={{ repeat: Infinity, duration: 2 }} className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                            <span className="text-[8px] font-black text-emerald-400 uppercase tracking-widest">Live</span>
                        </div>
                    )}
                </div>

                <div>
                    <div className={`text-4xl font-black ${colorConfig.split(' ')[1]} mb-1 tracking-tighter leading-none`}>
                        {isNaN(displayValue) ? '0' : Math.round(displayValue).toLocaleString()}{suffix}
                    </div>
                    <div className="text-[10px] font-black text-zinc-300 uppercase tracking-widest mb-1">{label}</div>
                    {description && <div className="text-[9px] text-zinc-500 font-medium leading-none">{description}</div>}
                </div>

                {trend !== undefined && trend !== 0 && (
                    <div className="mt-4 flex items-center gap-1 text-[10px] font-bold">
                        {trend > 0 ? <TrendingUp className="w-3 h-3 text-green-400" /> : <TrendingDown className="w-3 h-3 text-red-400" />}
                        <span className={trend > 0 ? "text-green-400" : "text-red-400"}>
                            {trend > 0 ? '+' : ''}{trend} (24h)
                        </span>
                    </div>
                )}
            </div>
        </motion.div>
    );
}

