"use client";

import { useEffect, useState } from "react";
import { getGuildsStorageStats } from "@/server/actions/god-storage-actions";
import { HardDrive, Activity, Image as ImageIcon, Loader2 } from "lucide-react";

export function StoragePanel() {
    const [stats, setStats] = useState<any[] | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        getGuildsStorageStats().then((data) => {
            setStats(data);
            setIsLoading(false);
        });
    }, []);

    const formatBytes = (bytes: number) => {
        if (bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    };

    if (isLoading) {
        return (
            <div className="bg-zinc-900/30 border border-white/5 rounded-3xl p-8 backdrop-blur-xl flex items-center justify-center min-h-[300px]">
                <Loader2 className="w-8 h-8 animate-spin text-zinc-500" />
            </div>
        );
    }

    return (
        <div className="bg-zinc-900/30 border border-white/5 rounded-3xl p-8 backdrop-blur-xl space-y-8">
            <div className="flex items-center gap-3">
                <HardDrive className="w-6 h-6 text-blue-500" />
                <h3 className="text-xl font-black text-white uppercase tracking-widest">
                    Ressources Disque & Captures
                </h3>
            </div>

            <div className="grid gap-4">
                {stats?.map((guild) => (
                    <div key={guild.id} className="bg-black/40 border border-white/5 rounded-2xl p-6">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h4 className="font-bold text-lg text-white">{guild.name}</h4>
                                <p className="text-xs text-zinc-500">{guild.members} membres inscrits</p>
                            </div>
                            <div className="text-right">
                                <p className="font-mono text-xl text-blue-400 font-bold">{formatBytes(guild.sizeBytes)}</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4 mt-6">
                            <div className="bg-zinc-900/50 rounded-xl p-4 border border-white/5 flex items-center gap-4">
                                <div className="p-3 bg-amber-500/10 rounded-lg">
                                    <ImageIcon className="w-5 h-5 text-amber-500" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                                        Captures en attente
                                    </p>
                                    <p className="text-xl font-black text-white">{guild.pendingSubmissions}</p>
                                </div>
                            </div>

                            <div className="bg-zinc-900/50 rounded-xl p-4 border border-white/5 flex items-center gap-4">
                                <div className="p-3 bg-emerald-500/10 rounded-lg">
                                    <Activity className="w-5 h-5 text-emerald-500" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                                        Captures (/jour)
                                    </p>
                                    <p className="text-xl font-black text-white">{guild.submissionsToday} ajoutées ajd.</p>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}

                {stats?.length === 0 && (
                    <div className="text-center text-zinc-500 py-12 border border-white/5 rounded-2xl bg-black/20">
                        Aucune guilde active pour les statistiques.
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { 
    Database, 
    Zap, 
    ShieldCheck, 
    RefreshCw, 
    CheckCircle2, 
    AlertTriangle, 
    Loader2,
    Clock,
    TerminalSquare,
    Cpu
} from "lucide-react";
import { getInternalSystemStatus } from "@/server/actions/god-system-actions";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";

interface SystemStatus {
    database: { 
        status: string; 
        latency: number; 
        insights?: { auditLogs: number; profiles: number; missions: number } 
    };
    cache: { status: string; latency: number };
    backup: { status: string; lastAt: Date | null };
    worker: { 
        status: string; 
        lastAt: Date | null; 
        queues?: { 
            metamob: { waiting: number; active: number; failed: number };
            ladder: { waiting: number; active: number; failed: number };
        } 
    };
    maintenance: { status: string; lastAt: Date | null; metrics?: any };
    disk?: { totalMb: number; freeMb: number; usagePercent: number };
    ram?: { totalMb: number; freeMb: number; usagePercent: number };
}

export function SystemHealthDashboard() {
    const [status, setStatus] = useState<SystemStatus | null>(null);
    const [loading, setLoading] = useState(true);

    const fetchStatus = async () => {
        const res = await getInternalSystemStatus();
        if (res) setStatus(res as SystemStatus);
        setLoading(false);
    };

    useEffect(() => {
        fetchStatus();
        const interval = setInterval(fetchStatus, 30000); // Poll every 30s
        return () => clearInterval(interval);
    }, []);

    if (loading) return (
        <div className="flex items-center justify-center p-12 bg-zinc-900/20 border border-white/5 rounded-3xl animate-pulse">
            <div className="flex flex-col items-center gap-4">
                <Loader2 className="w-6 h-6 text-zinc-600 animate-spin" />
                <span className="text-[10px] font-black text-zinc-700 uppercase tracking-widest">Analyse des systèmes...</span>
            </div>
        </div>
    );

    if (!status) return (
        <div className="p-12 bg-rose-500/5 border border-rose-500/10 rounded-3xl text-center space-y-4">
            <AlertTriangle className="w-8 h-8 text-rose-500 mx-auto" />
            <div className="space-y-1">
                <p className="text-sm font-bold text-white uppercase tracking-tight">Erreur de Diagnostic</p>
                <p className="text-xs text-zinc-500 max-w-sm mx-auto">Le serveur n'a pas pu renvoyer l'état de santé. Vérifiez les logs ou réessayez.</p>
            </div>
            <button onClick={() => { setLoading(true); fetchStatus(); }} className="px-4 py-2 bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all">
                Réessayer la connexion
            </button>
        </div>
    );

    const getDiskDisplay = () => {
        if (!status.disk || status.disk.totalMb === 0) return "Jamais";
        const totalGb = (status.disk.totalMb / 1024).toFixed(1);
        const freeGb = (status.disk.freeMb / 1024).toFixed(1);
        return `${freeGb}Go libres / ${totalGb}Go`;
    };

    const getRamDisplay = () => {
        if (!status.ram || status.ram.totalMb === 0) return "Jamais";
        const totalGb = (status.ram.totalMb / 1024).toFixed(1);
        const freeGb = (status.ram.freeMb / 1024).toFixed(1);
        return `${freeGb}Go libres / ${totalGb}Go`;
    };

    const totalWaitingJobs = (status.worker.queues?.metamob.waiting || 0) + (status.worker.queues?.ladder.waiting || 0);

    const cards = [
        {
            label: "Base de données",
            subLabel: "PostgreSQL Prisma",
            value: status.database.status === "ONLINE" ? `${status.database.latency}ms` : "OFFLINE",
            status: status.database.status,
            icon: Database,
            color: "emerald",
            footer: status.database.insights ? `${(status.database.insights.auditLogs / 1000).toFixed(1)}k logs / ${status.database.insights.profiles} profils` : null
        },
        {
            label: "Moteur Cache",
            subLabel: "Redis WebSocket",
            value: status.cache.status === "ONLINE" ? `${status.cache.latency}ms` : "OFFLINE",
            status: status.cache.status,
            icon: Zap,
            color: "amber"
        },
        {
            label: "Stockage Système",
            subLabel: "/dev/root OS Disk",
            value: getDiskDisplay(),
            status: status.disk && status.disk.usagePercent < 85 ? "ONLINE" : "OFFLINE",
            icon: TerminalSquare,
            color: status.disk && status.disk.usagePercent >= 85 ? "rose" : "cyan"
        },
        {
            label: "Mémoire Vive (RAM)",
            subLabel: "OS Node Allocation",
            value: getRamDisplay(),
            status: status.ram && status.ram.usagePercent < 90 ? "ONLINE" : "OFFLINE",
            icon: Cpu,
            color: status.ram && status.ram.usagePercent >= 90 ? "rose" : "violet"
        },
        {
            label: "Worker Platforms",
            subLabel: "Ladder & Metamob",
            value: status.worker.lastAt ? formatDistanceToNow(new Date(status.worker.lastAt), { addSuffix: true, locale: fr }) : "En attente",
            status: status.worker.status === "IDLE" ? "ONLINE" : "OFFLINE",
            icon: RefreshCw,
            color: "rose",
            footer: status.worker.queues ? `${totalWaitingJobs} tâches en attente` : null
        },
        {
            label: "Dernier Backup",
            subLabel: "Cloudflare R2 Storage",
            value: status.backup.lastAt ? formatDistanceToNow(new Date(status.backup.lastAt), { addSuffix: true, locale: fr }) : "Aucun",
            status: status.backup.status === "SUCCESS" ? "ONLINE" : "OFFLINE",
            icon: ShieldCheck,
            color: status.backup.status === "SUCCESS" ? "indigo" : "rose",
            footer: status.backup.status === "FAILED" ? "La sauvegarde a échoué" : (status.backup.status === "SUCCESS" ? "Stockage R2 OK" : "Non configuré")
        }
    ];

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4 mb-8">
            {cards.map((card, i) => (
                <div key={i} className="group relative overflow-hidden bg-zinc-900/40 border border-white/5 p-5 rounded-3xl transition-all hover:bg-zinc-900/60 hover:border-white/10">
                    {/* Background Glow */}
                    <div className={`absolute top-0 right-0 w-24 h-24 bg-${card.color}-500/5 blur-[40px] -translate-y-1/2 translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity`} />
                    
                    <div className="flex items-start justify-between mb-4">
                        <div className={`p-2 rounded-xl bg-zinc-900 border border-white/5 text-zinc-400 group-hover:text-${card.color}-400 group-hover:border-${card.color}-500/20 transition-all`}>
                            <card.icon className="w-4 h-4" />
                        </div>
                        <div className={`flex items-center gap-1.5 px-2 py-1 rounded-full bg-zinc-900/50 border border-white/5`}>
                            <div className={`w-1.5 h-1.5 rounded-full ${card.status === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-rose-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]'}`} />
                            <span className="text-[8px] font-black uppercase tracking-widest text-zinc-500">
                                {card.status === 'ONLINE' ? 'Ok' : 'Err'}
                            </span>
                        </div>
                    </div>

                    <div className="space-y-1">
                        <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest leading-none">
                            {card.subLabel}
                        </div>
                        <div className="text-sm font-bold text-white group-hover:tracking-wide transition-all truncate">
                            {card.label}
                        </div>
                    </div>

                    <div className="mt-4 flex items-end justify-between">
                        <div className="space-y-1">
                            <div className="text-lg font-black text-zinc-400 group-hover:text-white transition-colors">
                                {card.value}
                            </div>
                            {card.footer && (
                                <div className="text-[8px] font-black text-zinc-600 uppercase tracking-widest whitespace-nowrap">
                                    {card.footer}
                                </div>
                            )}
                        </div>
                        <Clock className="w-3.5 h-3.5 text-zinc-800" />
                    </div>
                </div>
            ))}
        </div>
    );
}

"use client";

import { useState, useMemo } from "react";
import { deleteGhostUser, cleanupGhostUsers } from "@/server/actions/super-admin-actions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Trash2, AlertTriangle, UserX, Loader2, CheckCircle2, Search, Copy, Clock, Calendar, MousePointer2, CalendarCheck } from "lucide-react";
import { cn } from "@/lib/utils";

interface TargetPurgePanelProps {
    ghostUsers: any[];
}

export function TargetPurgePanel({ ghostUsers }: TargetPurgePanelProps) {
    const [isPurgingAll, setIsPurgingAll] = useState(false);
    const [purgingId, setPurgingId] = useState<string | null>(null);
    const [search, setSearch] = useState("");

    const filteredUsers = useMemo(() => {
        if (!search) return ghostUsers;
        const s = search.toLowerCase();
        return ghostUsers.filter(u => 
            u.name?.toLowerCase().includes(s) || 
            u.id.toLowerCase().includes(s) || 
            u.accounts?.[0]?.providerAccountId?.includes(s)
        );
    }, [ghostUsers, search]);

    const handlePurgeAll = async () => {
        if (!confirm("Voulez-vous purger TOUS les comptes orphelins vieux de plus de 24h ?")) return;
        setIsPurgingAll(true);
        try {
            const res = await cleanupGhostUsers();
            if (res.success) {
                toast.success(`${res.count} comptes purgés !`);
            } else {
                toast.error("Erreur lors de la purge.");
            }
        } catch (e: any) {
            toast.error(e.message || "Erreur inattendue");
        } finally {
            setIsPurgingAll(false);
        }
    };

    const handleDeleteUser = async (user: any) => {
        if (!confirm(`Purger définitivement le compte de ${user.name || "Inconnu"} ?`)) return;
        setPurgingId(user.id);
        try {
            const res = await deleteGhostUser(user.id);
            if (res.success) {
                toast.success(`Compte ${user.name || user.id} purgé avec succès.`);
            }
        } catch (e: any) {
            toast.error(e.message || "Impossible de purger l'utilisateur.");
        } finally {
            setPurgingId(null);
        }
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        toast.success("ID copié !");
    };

    return (
        <div className="bg-zinc-900/10 border border-white/5 rounded-3xl p-8 backdrop-blur-xl h-full flex flex-col gap-6 shadow-2xl relative overflow-hidden">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 relative z-10">
                <div className="space-y-1">
                    <h3 className="text-xs font-black text-amber-500 uppercase tracking-[0.3em] flex items-center gap-3">
                        <AlertTriangle className="w-4 h-4" />
                        Target Purge Zone
                    </h3>
                    <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">Identification & Nettoyage des Ghost Users</p>
                </div>
                
                <div className="flex flex-wrap items-center gap-4">
                    <div className="relative group flex-1 min-w-[200px]">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600 group-focus-within:text-amber-500 transition-colors" />
                        <Input 
                            placeholder="Rechercher (Nom, ID, Discord)..." 
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="pl-12 h-12 bg-black/40 border-white/5 focus:border-amber-500/50 rounded-2xl text-xs font-bold uppercase tracking-widest transition-all"
                        />
                    </div>

                    <div className="flex items-center gap-6 bg-black/40 px-6 py-3 rounded-2xl border border-white/5 shadow-inner">
                        <div className="flex flex-col items-center">
                            <span className="text-3xl font-black text-rose-500 leading-none">{ghostUsers.length}</span>
                            <span className="text-[8px] font-black text-rose-500/50 uppercase tracking-tighter mt-1">Total</span>
                        </div>
                        {ghostUsers.length > 0 && (
                            <Button
                                variant="destructive"
                                size="sm"
                                disabled={isPurgingAll}
                                onClick={handlePurgeAll}
                                className="bg-rose-500 text-white hover:bg-rose-600 font-black uppercase tracking-widest text-[9px] h-10 px-5 shadow-[0_0_20px_rgba(244,63,94,0.3)]"
                            >
                                {isPurgingAll ? <Loader2 className="w-3 h-3 mr-2 animate-spin" /> : <Trash2 className="w-3 h-3 mr-2" />}
                                Purge Globale
                            </Button>
                        )}
                    </div>
                </div>
            </div>

            {/* Explanatory Banner */}
            <div className="bg-amber-500/5 border border-amber-500/10 rounded-2xl p-5 flex gap-4 items-start relative z-10">
                <div className="p-2.5 rounded-xl bg-amber-500/10 text-amber-500 shrink-0">
                    <UserX className="w-5 h-5" />
                </div>
                <div className="space-y-1">
                    <h4 className="text-[10px] font-black text-amber-500 uppercase tracking-widest leading-none">Aide au Diagnostic</h4>
                    <p className="text-[10px] text-zinc-500 leading-relaxed font-bold uppercase tracking-tight">
                        Ces utilisateurs ont un compte mais **aucun** profil de guilde. 
                        Vérifie l'activité (sessions) avant de purger. Un utilisateur avec 0 session est probablement un robot ou une erreur de connexion.
                    </p>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 space-y-3 custom-scrollbar relative z-10">
                {filteredUsers.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-16 border border-dashed border-white/5 rounded-[2.5rem] bg-black/20 text-zinc-600 mt-2">
                        {search ? (
                            <p className="font-black uppercase tracking-widest text-xs">Aucun résultat pour "{search}"</p>
                        ) : (
                            <>
                                <CheckCircle2 className="w-12 h-12 mb-4 opacity-20" />
                                <p className="font-black uppercase tracking-widest text-xs">Aucune cible détectée</p>
                            </>
                        )}
                    </div>
                ) : (
                    filteredUsers.map((user) => {
                        const discordId = user.accounts?.[0]?.providerAccountId;
                        const lastActivity = user.sessions?.[0]?.expires;
                        
                        return (
                            <div key={user.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-black/40 border border-white/5 rounded-2xl hover:bg-black/60 hover:border-white/10 transition-all group gap-4">
                                <div className="flex items-center gap-4">
                                    <div className="relative shrink-0">
                                        {user.image ? (
                                            <img src={user.image} alt="" className="w-12 h-12 rounded-xl opacity-80 group-hover:opacity-100 transition-opacity" />
                                        ) : (
                                            <div className="w-12 h-12 rounded-xl bg-zinc-800 flex items-center justify-center border border-white/5">
                                                <UserX className="w-5 h-5 text-zinc-600" />
                                            </div>
                                        )}
                                        {user._count?.sessions > 0 && (
                                            <div className="absolute -top-1 -right-1 w-3 h-3 bg-emerald-500 rounded-full border-2 border-black animate-pulse" title="Session active" />
                                        )}
                                    </div>
                                    
                                    <div className="space-y-1.5 overflow-hidden">
                                        <div className="flex items-center gap-3">
                                            <h4 className="font-black text-sm text-white tracking-tight truncate uppercase italic">{user.name || "Utilisateur"}</h4>
                                            {discordId && (
                                                <button 
                                                    onClick={() => copyToClipboard(discordId)}
                                                    className="p-1.5 rounded-md hover:bg-white/5 text-zinc-600 hover:text-white transition-all"
                                                    title="Copier Discord ID"
                                                >
                                                    <Copy className="w-3 h-3" />
                                                </button>
                                            )}
                                        </div>
                                        
                                        <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                                            <div className="flex items-center gap-1.5 text-zinc-500">
                                                <Calendar className="w-3 h-3" />
                                                <span className="text-[9px] font-bold uppercase tracking-tighter">Créé: {new Date(user.createdAt).toLocaleDateString()}</span>
                                            </div>
                                            
                                            <div className="flex items-center gap-1.5 text-zinc-500">
                                                <MousePointer2 className="w-3 h-3" />
                                                <span className="text-[9px] font-bold uppercase tracking-tighter">{user._count?.sessions} sessions</span>
                                            </div>

                                            {user._count?.guildEvents > 0 && (
                                                <div className="flex items-center gap-1.5 text-amber-500">
                                                    <CalendarCheck className="w-3 h-3" />
                                                    <span className="text-[9px] font-bold uppercase tracking-tighter text-amber-500/80">{user._count.guildEvents} events</span>
                                                </div>
                                            )}

                                            {lastActivity && (
                                                <div className="flex items-center gap-1.5 text-blue-400/70 italic">
                                                    <Clock className="w-3 h-3" />
                                                    <span className="text-[9px] font-bold uppercase tracking-tighter">Actif: {new Date(lastActivity).toLocaleDateString()}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2 justify-end shrink-0">
                                    <div className="flex flex-col items-end mr-4 hidden md:flex gap-1.5">
                                         <span className={cn(
                                             "text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md border",
                                             user._count?.sessions > 0 ? "text-emerald-500 border-emerald-500/20 bg-emerald-500/5" : "text-zinc-600 border-white/5 bg-white/5"
                                         )}>
                                             {user._count?.sessions > 0 ? "Interactif" : "Visiteur"}
                                         </span>
                                         
                                         {/* New indicator for Whitelist membership */}
                                         {user.memberInWhitelists && user.memberInWhitelists.length > 0 && (
                                             <div className="flex flex-col items-end gap-1">
                                                 <span className="text-[7px] font-black uppercase tracking-tighter text-amber-500/80 bg-amber-500/5 border border-amber-500/10 px-1.5 rounded-sm">
                                                     Sur Whitelist
                                                 </span>
                                                 <div className="flex flex-wrap gap-1 justify-end max-w-[150px]">
                                                     {user.memberInWhitelists.map((gName: string, idx: number) => (
                                                         <span key={idx} className="text-[7px] text-zinc-500 whitespace-nowrap">{gName}</span>
                                                     ))}
                                                 </div>
                                             </div>
                                         )}
                                     </div>

                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => handleDeleteUser(user)}
                                        disabled={purgingId === user.id || isPurgingAll}
                                        className="h-10 w-10 text-zinc-600 hover:text-rose-400 hover:bg-rose-500/10 rounded-xl transition-all"
                                    >
                                        {purgingId === user.id ? <Loader2 className="w-4 h-4 animate-spin text-rose-500" /> : <Trash2 className="w-4 h-4" />}
                                    </Button>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
            
            <div className="absolute bottom-0 right-0 w-64 h-64 bg-rose-500/5 blur-[120px] rounded-full -mr-32 -mb-32 pointer-events-none" />
        </div>
    );
}

"use client";

import { useState, useTransition, useEffect } from "react";
import {
    Ticket,
    Search,
    Send,
    X,
    ChevronDown,
    Clock,
    CheckCircle2,
    AlertCircle,
    MessageSquare,
    Hash,
    ExternalLink,
    ShieldCheck,
    Loader2,
    Trash2,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";

// =============================================================================
// TYPES
// =============================================================================

interface SupportTicket {
    id: string;
    ticketNumber: number;
    discordThreadId: string | null;
    discordGuildId: string;
    category: "ACCESS_REQUEST" | "BUG_REPORT" | "FEATURE_REQUEST" | "OTHER";
    status: "OPEN" | "IN_PROGRESS" | "WAITING_RESPONSE" | "CLOSED";
    subject: string;
    description: string;
    creatorDiscordId: string;
    creatorDiscordName: string;
    assignedToId: string | null;
    createdAt: string;
    updatedAt: string;
    closedAt: string | null;
    closedBy: string | null;
    closedReason: string | null;
    targetGuildId: string | null;
    targetGuildName: string | null;
    targetGuildMemberCount: number | null;
}

interface TicketStats {
    open: number;
    inProgress: number;
    waitingResponse: number;
    closedRecent: number;
    total: number;
}

interface TicketDashboardProps {
    initialTickets: SupportTicket[];
    initialTotal: number;
    initialStats: TicketStats | null;
}

// =============================================================================
// CONSTANTS
// =============================================================================

const CATEGORY_CONFIG = {
    ACCESS_REQUEST: { label: "Demande d'Accès", color: "text-emerald-400", bg: "bg-emerald-500/10", border: "border-emerald-500/20", emoji: "🔑" },
    BUG_REPORT: { label: "Bug Report", color: "text-red-400", bg: "bg-red-500/10", border: "border-red-500/20", emoji: "🐛" },
    FEATURE_REQUEST: { label: "Feature Request", color: "text-purple-400", bg: "bg-purple-500/10", border: "border-purple-500/20", emoji: "💡" },
    OTHER: { label: "Autre", color: "text-zinc-400", bg: "bg-zinc-500/10", border: "border-zinc-500/20", emoji: "📩" },
};

const STATUS_CONFIG = {
    OPEN: { label: "Nouveau (Open)", color: "text-amber-400", bg: "bg-amber-500/10", border: "border-amber-500/20", icon: AlertCircle },
    IN_PROGRESS: { label: "En cours", color: "text-blue-400", bg: "bg-blue-500/10", border: "border-blue-500/20", icon: Clock },
    WAITING_RESPONSE: { label: "En attente", color: "text-violet-400", bg: "bg-violet-500/10", border: "border-violet-500/20", icon: MessageSquare },
    CLOSED: { label: "Fermé", color: "text-zinc-500", bg: "bg-zinc-500/10", border: "border-zinc-500/20", icon: CheckCircle2 },
};

// =============================================================================
// MAIN COMPONENT
// =============================================================================

export function TicketDashboard({ initialTickets, initialTotal, initialStats }: TicketDashboardProps) {
    const [tickets, setTickets] = useState(initialTickets);
    const [total, setTotal] = useState(initialTotal);
    const [statusFilter, setStatusFilter] = useState<string>("ALL");
    const [categoryFilter, setCategoryFilter] = useState<string>("ALL");
    const [search, setSearch] = useState("");
    const [selectedTicket, setSelectedTicket] = useState<SupportTicket | null>(null);
    const [replyText, setReplyText] = useState("");
    const [isPending, startTransition] = useTransition();
    const [panelChannelId, setPanelChannelId] = useState("");
    const [panelGuildId, setPanelGuildId] = useState("");
    const [botGuilds, setBotGuilds] = useState<any[]>([]);
    const [availableChannels, setAvailableChannels] = useState<any[]>([]);
    const [supportGuildRoles, setSupportGuildRoles] = useState<any[]>([]);
    const [selectedRoleId, setSelectedRoleId] = useState<string>("");

    // Fetch bot guilds on mount
    useEffect(() => {
        async function loadGuilds() {
            const { getBotGuilds } = await import("@/server/actions/ticket-actions");
            const res = await getBotGuilds();
            if (res.success && res.guilds) setBotGuilds(res.guilds);
        }
        loadGuilds();
    }, []);

    // Fetch channels when guild changes
    useEffect(() => {
        if (!panelGuildId) {
            setAvailableChannels([]);
            return;
        }
        async function loadChannels() {
            const { getChannelsForGuild } = await import("@/server/actions/ticket-actions");
            const res = await getChannelsForGuild(panelGuildId);
            if (res.success && res.channels) setAvailableChannels(res.channels);
        }
        loadChannels();
    }, [panelGuildId]);

    // Fetch roles when a ticket is selected (for role assignment)
    useEffect(() => {
        if (!selectedTicket) {
            setSupportGuildRoles([]);
            setSelectedRoleId("");
            return;
        }
        
        async function loadRoles() {
            const { getSupportGuildRoles } = await import("@/server/actions/ticket-actions");
            const res = await getSupportGuildRoles(selectedTicket!.discordGuildId);
            if (res.success && res.roles) {
                setSupportGuildRoles(res.roles);
                // Pre-select first valid role if none
                if (res.roles.length > 0 && !selectedRoleId) {
                    // Try to find a role containing "Sigil" or "Membre"
                    const sigilRole = res.roles.find((r: any) => r.name.toLowerCase().includes("sigil") || r.name.toLowerCase().includes("membre"));
                    if (sigilRole) setSelectedRoleId(sigilRole.id);
                }
            }
        }
        loadRoles();
    }, [selectedTicket]);

    const stats = initialStats;

    // Auto-refresh every 30s
    useEffect(() => {
        if (typeof window === "undefined") return;
        const interval = setInterval(() => {
            refreshTickets();
        }, 30000);
        return () => clearInterval(interval);
    }, []);

    // Refresh tickets with filters
    async function refreshTickets(customFilters?: { status?: string; category?: string }) {
        startTransition(async () => {
            const { getSupportTickets } = await import("@/server/actions/ticket-actions");
            const result = await getSupportTickets({
                status: (customFilters?.status || statusFilter) === "ALL" ? undefined : (customFilters?.status || statusFilter) as any,
                category: (customFilters?.category || categoryFilter) === "ALL" ? undefined : (customFilters?.category || categoryFilter) as any,
                search: search || undefined,
            });
            setTickets(result.tickets as unknown as SupportTicket[]);
            setTotal(result.total);
        });
    }

    // Auto-refresh on filter change (UX 2026)
    const handleStatusFilterChange = (val: string) => {
        setStatusFilter(val);
        refreshTickets({ status: val });
    };

    const handleCategoryFilterChange = (val: string) => {
        setCategoryFilter(val);
        refreshTickets({ category: val });
    };

    // Close ticket
    async function handleClose(ticketId: string) {
        startTransition(async () => {
            const { closeSupportTicket } = await import("@/server/actions/ticket-actions");
            const res = await closeSupportTicket(ticketId, "DASHBOARD", "Admin SigilOS", "Fermé via le GOD Dashboard");
            if (res.success) {
                toast.success("Ticket fermé !");
                await refreshTickets();
                setSelectedTicket(null);
            } else {
                toast.error(res.error || "Erreur de fermeture");
            }
        });
    }

    // Delete ticket
    async function handleDeleteTicket(ticketId: string) {
        if (!confirm("⚠️ Supprimer ce ticket définitivement ? (Action irréversible, le thread Discord sera supprimé)")) return;

        startTransition(async () => {
            const { deleteSupportTicket } = await import("@/server/actions/ticket-actions");
            const res = await deleteSupportTicket(ticketId);
            if (res.success) {
                toast.success("Ticket supprimé définitivement.");
                await refreshTickets();
                setSelectedTicket(null);
            } else {
                toast.error(res.error || "Erreur de suppression");
            }
        });
    }

    // Update status
    async function handleStatusChange(ticketId: string, status: string) {
        startTransition(async () => {
            const { updateTicketStatus } = await import("@/server/actions/ticket-actions");
            const res = await updateTicketStatus(ticketId, status as any);
            if (res.success) {
                toast.success("Statut mis à jour");
                await refreshTickets();
            } else {
                toast.error(res.error || "Erreur");
            }
        });
    }

    // Validate Guild Access
    async function handleValidateGuild(ticketId: string, discordGuildId: string, notes?: string) {
        startTransition(async () => {
            const { validateGuildAccess } = await import("@/server/actions/ticket-actions");
            const res = await validateGuildAccess(ticketId, discordGuildId, notes, selectedRoleId || undefined);
            if (res.success) {
                toast.success("Guilde validée et whiteliste créée !");
                await refreshTickets();
                setSelectedTicket(null);
            } else {
                toast.error(res.error || "Échec de la validation");
            }
        });
    }

    // Reject Guild Access
    async function handleRejectGuild(ticketId: string, reason: string) {
        if (!reason.trim()) return;
        
        startTransition(async () => {
            const { rejectGuildAccess } = await import("@/server/actions/ticket-actions");
            const res = await rejectGuildAccess(ticketId, reason);
            if (res.success) {
                toast.success("Demande refusée et ticket fermé.");
                await refreshTickets();
                setSelectedTicket(null);
            } else {
                toast.error(res.error || "Échec du rejet");
            }
        });
    }

    // Send reply
    async function handleReply(ticketId: string) {
        if (!replyText.trim()) return;
        startTransition(async () => {
            const { sendTicketReply } = await import("@/server/actions/ticket-actions");
            const res = await sendTicketReply(ticketId, replyText);
            if (res.success) {
                toast.success("Réponse envoyée");
                setReplyText("");
                await refreshTickets();
            } else {
                toast.error(res.error || "Erreur");
            }
        });
    }

    // Post panel
    async function handlePostPanel() {
        if (!panelChannelId.trim() || !panelGuildId.trim()) return;
        startTransition(async () => {
            const { postTicketPanel } = await import("@/server/actions/ticket-actions");
            const result = await postTicketPanel(panelChannelId, panelGuildId);
            if (result.success) {
                setPanelChannelId("");
                setPanelGuildId("");
                toast.success("Panel posté !");
            } else {
                toast.error(result.error);
            }
        });
    }

    return (
        <div className="space-y-8 pb-32">
            {/* Stats */}
            {stats && (
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <StatCard label="Nouveaux" value={stats.open} color="amber" />
                    <StatCard label="En cours" value={stats.inProgress} color="blue" />
                    <StatCard label="En attente" value={stats.waitingResponse} color="violet" />
                    <StatCard label="Fermés (7j)" value={stats.closedRecent} color="emerald" />
                    <StatCard label="Total" value={stats.total} color="zinc" />
                </div>
            )}

            {/* Toolbar */}
            <div className="flex flex-col md:flex-row gap-3">
                {/* Search */}
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
                    <input
                        type="text"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        onKeyDown={(e) => e.key === "Enter" && refreshTickets()}
                        placeholder="Rechercher par sujet, auteur ou #numéro..."
                        className="w-full pl-10 pr-4 py-3 bg-zinc-900/50 border border-white/5 rounded-2xl text-sm text-white placeholder:text-zinc-600 focus:outline-none focus:border-indigo-500/30 transition-all shadow-xl shadow-black/20"
                    />
                </div>

                {/* Status filter */}
                <Select value={statusFilter} onValueChange={handleStatusFilterChange}>
                    <SelectTrigger className="w-[200px] h-[52px] bg-zinc-900/50 border-white/5 rounded-2xl text-zinc-400">
                        <SelectValue placeholder="Tous les statuts" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="ALL">Tous les statuts</SelectItem>
                        <SelectItem value="OPEN">🆕 Nouveaux (Open)</SelectItem>
                        <SelectItem value="IN_PROGRESS">⏳ En cours</SelectItem>
                        <SelectItem value="WAITING_RESPONSE">📩 En attente de réponse</SelectItem>
                        <SelectItem value="CLOSED">🔒 Archivés / Fermés</SelectItem>
                    </SelectContent>
                </Select>

                {/* Category filter */}
                <Select value={categoryFilter} onValueChange={handleCategoryFilterChange}>
                    <SelectTrigger className="w-[220px] h-[52px] bg-zinc-900/50 border-white/5 rounded-2xl text-zinc-400">
                        <SelectValue placeholder="Toutes catégories" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="ALL">Toutes catégories</SelectItem>
                        <SelectItem value="ACCESS_REQUEST">🔑 Demandes d'accès</SelectItem>
                        <SelectItem value="BUG_REPORT">🐛 Signalements Bugs</SelectItem>
                        <SelectItem value="FEATURE_REQUEST">💡 Suggestions Features</SelectItem>
                        <SelectItem value="OTHER">📩 Autres demandes</SelectItem>
                    </SelectContent>
                </Select>

                <button
                    onClick={() => refreshTickets()}
                    disabled={isPending}
                    className="px-6 py-3 bg-indigo-500 hover:bg-indigo-400 rounded-2xl text-sm font-black text-black transition-all disabled:opacity-50 flex items-center justify-center min-w-[100px]"
                >
                    {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : "Filtrer"}
                </button>
            </div>

            {/* Tickets Table */}
            <div className="bg-zinc-900/30 border border-white/5 rounded-3xl overflow-hidden shadow-2xl">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead>
                            <tr className="border-b border-white/5 bg-white/[0.02]">
                                <th className="text-left px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Ticket</th>
                                <th className="text-left px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Utilisateur</th>
                                <th className="text-left px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Objet</th>
                                <th className="text-left px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Catégorie</th>
                                <th className="text-left px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Statut</th>
                                <th className="text-left px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Ancienneté</th>
                            </tr>
                        </thead>
                        <tbody>
                            {tickets.length === 0 && (
                                <tr>
                                    <td colSpan={6} className="px-6 py-16 text-center">
                                        <div className="flex flex-col items-center gap-3 opacity-30">
                                            <Ticket className="w-12 h-12" />
                                            <p className="text-sm font-bold uppercase tracking-widest">Aucun ticket en vue</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                            {tickets.map((ticket) => {
                                const cat = CATEGORY_CONFIG[ticket.category];
                                const status = STATUS_CONFIG[ticket.status];
                                const StatusIcon = status.icon;
                                return (
                                    <tr
                                        key={ticket.id}
                                        className="border-b border-white/[0.03] hover:bg-white/[0.04] transition-all cursor-pointer group"
                                        onClick={() => setSelectedTicket(ticket)}
                                    >
                                        <td className="px-6 py-4">
                                            <span className="text-amber-500 font-mono font-black text-xs">#{ticket.ticketNumber}</span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex flex-col">
                                                <span className="text-white font-black uppercase text-[11px] tracking-tight">{ticket.creatorDiscordName}</span>
                                                <span className="text-[9px] text-zinc-600 font-mono">{ticket.creatorDiscordId}</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className="text-zinc-300 font-bold truncate max-w-[250px] block group-hover:text-amber-200 transition-colors">
                                                {ticket.subject}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-[10px] font-black uppercase">
                                            <span className={cn("px-2.5 py-1 rounded-lg border", cat.bg, cat.border, cat.color)}>
                                                {cat.label}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className={cn("inline-flex items-center gap-1.5 text-[10px] font-black px-2.5 py-1 rounded-lg border uppercase", status.bg, status.border, status.color)}>
                                                <StatusIcon className="w-3.5 h-3.5" />
                                                {status.label}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className="text-zinc-500 text-[10px] font-black uppercase">
                                                {new Date(ticket.createdAt).toLocaleDateString("fr-FR")}
                                            </span>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Tools Area */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Manual Post Panel */}
                <div className="bg-zinc-900/30 border border-white/5 rounded-3xl p-8 space-y-6">
                    <div className="flex items-center gap-3">
                        <Send className="w-5 h-5 text-indigo-400" />
                        <h3 className="text-sm font-black text-white uppercase tracking-widest">Panel de Tickets</h3>
                    </div>
                    <div className="space-y-4">
                        <div className="grid grid-cols-2 gap-3">
                            <Select
                                value={panelGuildId}
                                onValueChange={(val) => {
                                    setPanelGuildId(val);
                                    setPanelChannelId(""); 
                                }}
                            >
                                <SelectTrigger className="h-[52px] bg-zinc-950 border-white/10 rounded-xl text-xs text-white">
                                    <SelectValue placeholder="Sélect. Serveur" />
                                </SelectTrigger>
                                <SelectContent>
                                    {botGuilds.map((g) => (
                                        <SelectItem key={g.id} value={g.id}>{g.name}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>

                            <Select
                                value={panelChannelId}
                                onValueChange={setPanelChannelId}
                                disabled={!panelGuildId}
                            >
                                <SelectTrigger className="h-[52px] bg-zinc-950 border-white/10 rounded-xl text-xs text-white disabled:opacity-50">
                                    <SelectValue placeholder="Sélect. Salon" />
                                </SelectTrigger>
                                <SelectContent>
                                    {availableChannels.map((c) => (
                                        <SelectItem key={c.id} value={c.id}># {c.name}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <button
                            onClick={handlePostPanel}
                            disabled={isPending || !panelChannelId || !panelGuildId}
                            className="w-full py-3 bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/20 rounded-xl text-xs font-black text-emerald-400 uppercase tracking-widest transition-all"
                        >
                            Poster le panel (Discord)
                        </button>
                    </div>
                </div>

                {/* Automation Info */}
                <div className="bg-amber-500/5 border border-amber-500/10 rounded-3xl p-8 flex items-center gap-6">
                    <div className="w-16 h-16 rounded-2xl bg-amber-500/10 flex items-center justify-center shrink-0">
                        <ShieldCheck className="w-8 h-8 text-amber-500" />
                    </div>
                    <div>
                        <h4 className="text-white font-black uppercase text-xs tracking-widest mb-1">SigilOS Guard 2026</h4>
                        <p className="text-xs text-zinc-500 leading-relaxed font-bold">
                            Le système de tickets prend en charge la validation automatique des guildes. 
                            Activez le mode <span className="text-amber-500">ACCESS_REQUEST</span> pour tester.
                        </p>
                    </div>
                </div>
            </div>

            {/* Detail Modal */}
            {selectedTicket && (
                <TicketDetailModal
                    ticket={selectedTicket}
                    onClose={() => setSelectedTicket(null)}
                    onReply={handleReply}
                    onCloseTicket={handleClose}
                    onDeleteTicket={handleDeleteTicket}
                    onValidateGuild={handleValidateGuild}
                    onRejectGuild={handleRejectGuild}
                    onStatusChange={handleStatusChange}
                    replyText={replyText}
                    setReplyText={setReplyText}
                    isPending={isPending}
                    guildRoles={supportGuildRoles}
                    selectedRoleId={selectedRoleId}
                    setSelectedRoleId={setSelectedRoleId}
                />
            )}
        </div>
    );
}

// =============================================================================
// SUB-COMPONENTS
// =============================================================================

function StatCard({ label, value, color }: { label: string; value: number; color: string }) {
    const colorMap: Record<string, string> = {
        amber: "text-amber-400 bg-amber-500/10 border-amber-500/20 ring-amber-500/5",
        blue: "text-blue-400 bg-blue-500/10 border-blue-500/20 ring-blue-500/5",
        violet: "text-violet-400 bg-violet-500/10 border-violet-500/20 ring-violet-500/5",
        emerald: "text-emerald-400 bg-emerald-500/10 border-emerald-500/20 ring-emerald-500/5",
        zinc: "text-zinc-400 bg-zinc-500/10 border-zinc-500/20 ring-zinc-500/5",
    };

    return (
        <div className={cn("rounded-3xl border p-6 space-y-2 ring-1 shadow-lg", colorMap[color])}>
            <div className="text-4xl font-black tracking-tighter">{value}</div>
            <div className="text-[10px] font-black uppercase tracking-[0.2em] opacity-50">{label}</div>
        </div>
    );
}

function TicketDetailModal({
    ticket,
    onClose,
    onReply,
    onCloseTicket,
    onDeleteTicket,
    onValidateGuild,
    onRejectGuild,
    onStatusChange,
    replyText,
    setReplyText,
    isPending,
    guildRoles,
    selectedRoleId,
    setSelectedRoleId,
}: {
    ticket: SupportTicket;
    onClose: () => void;
    onReply: (id: string) => void;
    onCloseTicket: (id: string) => void;
    onDeleteTicket: (id: string) => void;
    onValidateGuild: (ticketId: string, discordGuildId: string, notes?: string) => void;
    onRejectGuild: (ticketId: string, reason: string) => void;
    onStatusChange: (id: string, status: string) => void;
    replyText: string;
    setReplyText: (v: string) => void;
    isPending: boolean;
    guildRoles: any[];
    selectedRoleId: string;
    setSelectedRoleId: (v: string) => void;
}) {
    const [rejectionMode, setRejectionMode] = useState(false);
    const [rejectionReason, setRejectionReason] = useState("");
    const [validationNotes, setValidationNotes] = useState("");
    
    const cat = CATEGORY_CONFIG[ticket.category];
    const status = STATUS_CONFIG[ticket.status];

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-in fade-in duration-200">
            <div className="absolute inset-0 bg-zinc-950/90 backdrop-blur-md" onClick={onClose} />
            <div className="relative w-full max-w-2xl bg-zinc-900 border border-white/10 rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                {/* Header */}
                <div className="px-10 py-8 border-b border-white/5 bg-white/[0.02]">
                    <div className="flex items-center gap-4 mb-4">
                        <span className="text-amber-500 font-mono font-black text-lg underline decoration-amber-500/30 decoration-4">#{ticket.ticketNumber}</span>
                        <div className="h-4 w-px bg-white/10" />
                        <span className={cn("text-[10px] font-black uppercase px-3 py-1 rounded-full border", cat.bg, cat.border, cat.color)}>
                            {cat.emoji} {cat.label}
                        </span>
                        <Select
                            value={ticket.status}
                            onValueChange={(val) => onStatusChange(ticket.id, val)}
                        >
                            <SelectTrigger className={cn("h-8 text-[10px] font-black uppercase px-3 py-1 rounded-full border bg-zinc-950 outline-none w-fit", status.color, status.border)}>
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="OPEN">Nouveau</SelectItem>
                                <SelectItem value="IN_PROGRESS">En cours</SelectItem>
                                <SelectItem value="WAITING_RESPONSE">En attente</SelectItem>
                                <SelectItem value="CLOSED">Archiver</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tight leading-tight">{ticket.subject}</h3>
                    <div className="flex items-center gap-4 mt-4">
                        <div className="flex items-center gap-2">
                            <div className="w-6 h-6 rounded-full bg-zinc-800 border border-white/10 flex items-center justify-center text-[10px] font-black">
                                {ticket.creatorDiscordName[0]}
                            </div>
                            <span className="text-zinc-400 font-bold text-xs">{ticket.creatorDiscordName}</span>
                        </div>
                        <span className="text-zinc-600 font-mono text-[10px]">ID: {ticket.creatorDiscordId}</span>
                    </div>
                </div>

                {/* Body */}
                <div className="px-10 py-8 space-y-8 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10">
                    {/* Description */}
                    <div className="space-y-3">
                        <h4 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest pl-1">Détails de la demande</h4>
                        <div className="text-sm text-white/80 leading-relaxed whitespace-pre-wrap bg-zinc-950 p-6 rounded-3xl border border-white/5 font-medium italic">
                            {ticket.description}
                        </div>
                    </div>

                    {/* Quick Access Actions */}
                    <div className="flex flex-wrap gap-3">
                        {ticket.discordThreadId && (
                            <a
                                href={`https://discord.com/channels/${ticket.discordGuildId}/${ticket.discordThreadId}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center gap-2 px-5 py-3 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 rounded-2xl text-[11px] font-black text-indigo-400 uppercase tracking-widest transition-all"
                            >
                                <ExternalLink className="w-4 h-4" />
                                Ouvrir Fil Discord
                            </a>
                        )}

                        {/* 🛠️ SPECIFIC TRIGGER: ACCESS VALIDATION */}
                        {ticket.category === "ACCESS_REQUEST" && ticket.status !== "CLOSED" && (
                            <div className="w-full space-y-6 pt-6 mt-6 border-t border-white/5">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 rounded-xl bg-emerald-500/10 border border-emerald-500/20">
                                        <ShieldCheck className="w-4 h-4 text-emerald-400" />
                                    </div>
                                    <h4 className="text-xs font-black text-white uppercase tracking-widest">Décision d'Accès Technique</h4>
                                </div>

                                {!rejectionMode ? (
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-zinc-950/50 p-6 rounded-[2rem] border border-white/5 shadow-inner">
                                        <div className="space-y-4">
                                            <div className="space-y-2">
                                                <label className="text-[10px] font-black text-zinc-600 uppercase tracking-widest ml-1">Rôle Discord (Incentive)</label>
                                                <Select value={selectedRoleId} onValueChange={setSelectedRoleId}>
                                                    <SelectTrigger className="w-full h-12 bg-zinc-950 border-white/5 rounded-xl text-[10px] font-black uppercase text-zinc-400 focus:ring-1 focus:ring-emerald-500/30">
                                                        <SelectValue placeholder="Sélect. Rôle..." />
                                                    </SelectTrigger>
                                                    <SelectContent className="bg-zinc-900 border-white/10 text-white z-[200]">
                                                        <SelectItem value="SKIP">❌ Aucun rôle</SelectItem>
                                                        {guildRoles.map((role) => (
                                                            <SelectItem key={role.id} value={role.id} className="text-xs font-bold font-mono">
                                                                {role.name}
                                                            </SelectItem>
                                                        ))}
                                                    </SelectContent>
                                                </Select>
                                            </div>
                                            
                                            <div className="space-y-2">
                                                <label className="text-[10px] font-black text-zinc-600 uppercase tracking-widest ml-1">Message Additionnel (Optionnel)</label>
                                                <input 
                                                    type="text" 
                                                    value={validationNotes}
                                                    onChange={(e) => setValidationNotes(e.target.value)}
                                                    placeholder="Contraintes spécifiques, bienvenue..."
                                                    className="w-full h-12 px-4 bg-zinc-950 border border-white/5 rounded-xl text-xs text-zinc-300 focus:outline-none focus:border-emerald-500/30 transition-all font-medium"
                                                />
                                            </div>
                                        </div>

                                        <div className="flex flex-col justify-end gap-3">
                                            <button
                                                onClick={() => onValidateGuild(ticket.id, ticket.targetGuildId!, validationNotes)} 
                                                disabled={isPending || !ticket.targetGuildId}
                                                className="w-full py-4 bg-emerald-500 hover:bg-emerald-400 text-black rounded-2xl text-xs font-black uppercase tracking-[0.2em] transition-all disabled:opacity-50 shadow-xl shadow-emerald-500/10 flex items-center justify-center gap-2"
                                            >
                                                {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4 h-4" />}
                                                Valider la Guilde
                                            </button>
                                            <button
                                                onClick={() => setRejectionMode(true)}
                                                className="w-full py-3 bg-red-500/5 hover:bg-red-500/10 border border-red-500/20 rounded-2xl text-[10px] font-black text-red-500 uppercase tracking-widest transition-all"
                                            >
                                                Refuser la demande
                                            </button>
                                            <p className="text-[9px] text-zinc-600 italic text-center font-medium">
                                                L'utilisateur recevra un guide d'installation complet.
                                            </p>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="bg-rose-500/5 p-6 rounded-[2rem] border border-rose-500/10 space-y-4 animate-in slide-in-from-top-2 duration-300">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-rose-500 uppercase tracking-widest ml-1">Motif du Refus (Sera envoyé par MP)</label>
                                            <textarea 
                                                value={rejectionReason}
                                                onChange={(e) => setRejectionReason(e.target.value)}
                                                placeholder="Ex: Guilde trop petite, leader absent, serveur ne respectant pas les CGU..."
                                                rows={3}
                                                className="w-full p-4 bg-zinc-950 border border-rose-500/20 rounded-xl text-sm text-zinc-300 focus:outline-none focus:border-rose-500/40 transition-all resize-none font-medium"
                                            />
                                        </div>
                                        <div className="flex gap-3">
                                            <button
                                                onClick={() => onRejectGuild(ticket.id, rejectionReason)}
                                                disabled={isPending || !rejectionReason.trim()}
                                                className="flex-1 py-4 bg-rose-500 hover:bg-rose-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all disabled:opacity-50"
                                            >
                                                {isPending ? "Refus en cours..." : "Confirmer le Refus"}
                                            </button>
                                            <button
                                                onClick={() => setRejectionMode(false)}
                                                className="px-6 py-4 bg-white/5 hover:bg-white/10 rounded-2xl text-xs font-black text-zinc-400 uppercase tracking-widest transition-all"
                                            >
                                                Annuler
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Reply Section */}
                    {ticket.status !== "CLOSED" && (
                        <div className="space-y-3 pt-4 border-t border-white/5">
                            <h4 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest pl-1">Réponse directe</h4>
                            <textarea
                                value={replyText}
                                onChange={(e) => setReplyText(e.target.value)}
                                placeholder="Tape ta réponse pour l'envoyer directement dans le thread Discord..."
                                rows={4}
                                className="w-full px-6 py-4 bg-zinc-950 border border-white/10 rounded-[2rem] text-sm text-white placeholder:text-zinc-800 focus:outline-none focus:border-indigo-500/30 transition-all resize-none font-medium"
                            />
                            <div className="flex justify-between items-center bg-zinc-950/50 p-2 rounded-[2.5rem] border border-white/5">
                                <span className="text-[9px] text-zinc-600 font-bold uppercase ml-4">
                                    {isPending ? "Traitement en cours..." : "Le bot répondra en ton nom"}
                                </span>
                                <button
                                    onClick={() => onReply(ticket.id)}
                                    disabled={isPending || !replyText.trim()}
                                    className="px-6 py-3 bg-indigo-500 hover:bg-indigo-400 rounded-full text-[10px] font-black text-black uppercase tracking-widest transition-all disabled:opacity-50 flex items-center gap-2"
                                >
                                    {isPending ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Send className="w-3.5 h-3.5" />}
                                    Envoyer la réponse
                                </button>
                            </div>
                        </div>
                    )}

                    {/* Archive Info */}
                    {ticket.status === "CLOSED" && (
                        <div className="bg-white/5 border border-white/10 rounded-3xl p-6 space-y-3">
                            <h4 className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em] flex items-center gap-2">
                                <Hash className="w-3.5 h-3.5" /> Métadonnées de Fermeture
                            </h4>
                            <div className="grid grid-cols-2 gap-4 text-[11px] font-medium text-zinc-500">
                                <div>📅 Fermé le : <span className="text-zinc-300 font-mono">{ticket.closedAt ? new Date(ticket.closedAt).toLocaleString() : "N/A"}</span></div>
                                <div>👤 Par : <span className="text-zinc-300">{ticket.closedBy || "Anonyme"}</span></div>
                                <div className="col-span-2 mt-2">💬 Raison : <span className="text-zinc-300 italic">"{ticket.closedReason || "Aucune"}"</span></div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Main Action Footer */}
                {ticket.status !== "CLOSED" && (
                    <div className="px-10 py-6 border-t border-white/5 bg-zinc-950/50 flex justify-between items-center group/footer">
                        <div className="flex items-center gap-6">
                            <p className="text-[10px] text-zinc-600 font-black uppercase tracking-widest">SigilOS Support Engine v2.6</p>
                            <button
                                onClick={() => onDeleteTicket(ticket.id)}
                                disabled={isPending}
                                className="opacity-0 group-hover/footer:opacity-100 transition-opacity flex items-center gap-1.5 text-[9px] font-black text-red-500/50 hover:text-red-500 uppercase tracking-widest"
                            >
                                <Trash2 className="w-3 h-3" />
                                Détruire Définitivement
                            </button>
                        </div>
                        <button
                            onClick={() => onCloseTicket(ticket.id)}
                            disabled={isPending}
                            className="inline-flex items-center gap-2 px-6 py-3 bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 rounded-2xl text-[10px] font-black text-red-500 uppercase tracking-[0.2em] transition-all disabled:opacity-50"
                        >
                            <X className="w-3.5 h-3.5" />
                            Archiver Ticket
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { triggerGlobalMetamobSync, triggerGlobalLadderSync, testLadderFetch } from "@/server/actions/super-admin-actions";
import { Download, Trophy, Loader2, Beaker, Play, Terminal } from "lucide-react";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

export function WorkerTester() {
    const [isMetamobLoading, setIsMetamobLoading] = useState(false);
    const [isLadderLoading, setIsLadderLoading] = useState(false);
    
    // Test API State
    const [testPseudo, setTestPseudo] = useState("");
    const [testServerId, setTestServerId] = useState("295"); // Imagiro by default
    const [isTestLoading, setIsTestLoading] = useState(false);
    const [testResult, setTestResult] = useState<any>(null);

    const handleTestLadder = async () => {
        if (!testPseudo) return toast.error("Entrez un pseudo.");
        setIsTestLoading(true);
        setTestResult(null);
        const res = await testLadderFetch(testPseudo, testServerId);
        setTestResult(res);
        if (!res.success) toast.error(res.error);
        else toast.success("Test terminé.");
        setIsTestLoading(false);
    };

    return (
        <div className="bg-zinc-900/40 border border-white/5 rounded-3xl p-8 backdrop-blur-xl shadow-2xl relative overflow-hidden group hover:bg-zinc-900/60 transition-all">
            <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/5 blur-[60px] -translate-y-1/2 translate-x-1/2" />
            <h3 className="text-sm font-black text-zinc-500 mb-6 uppercase tracking-[0.3em] flex items-center gap-3">
                <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" />
                Service Workers & API
            </h3>
            
            <Tabs defaultValue="api" className="w-full">
                <TabsList className="mb-6 bg-black/40 border border-white/5">
                    <TabsTrigger value="api" className="text-xs uppercase font-bold tracking-widest data-[state=active]:bg-zinc-800 data-[state=active]:text-white">
                        <Beaker className="w-4 h-4 mr-2" />
                        API Playground
                    </TabsTrigger>
                    <TabsTrigger value="queue" className="text-xs uppercase font-bold tracking-widest data-[state=active]:bg-zinc-800 data-[state=active]:text-white">
                        <Terminal className="w-4 h-4 mr-2" />
                        Queues System
                    </TabsTrigger>
                </TabsList>

                {/* API TESTING ZONE */}
                <TabsContent value="api" className="space-y-4">
                    <p className="text-xs text-zinc-500 mb-4">
                        Test direct de l'API Cloudflare (Ladder). Aucune DB impactée, aucun job créé. Permet de vérifier la validité du Token et du format Dofus.com en live.
                    </p>
                    <div className="flex flex-col md:flex-row gap-4 items-stretch md:items-end">
                        <div className="space-y-2 flex-1">
                            <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Pseudo Dofus</label>
                            <Input 
                                placeholder="ex: Klyx" 
                                value={testPseudo} 
                                onChange={e => setTestPseudo(e.target.value)} 
                                className="bg-black/50 border-white/10 text-white"
                            />
                        </div>
                        <div className="space-y-2 w-full md:w-32">
                            <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Server ID</label>
                            <Input 
                                placeholder="295" 
                                value={testServerId} 
                                onChange={e => setTestServerId(e.target.value)} 
                                className="bg-black/50 border-white/10 text-white"
                            />
                        </div>
                        <Button 
                            onClick={handleTestLadder} 
                            disabled={isTestLoading}
                            className="bg-emerald-500 hover:bg-emerald-600 text-white font-bold tracking-wide transition-all w-full md:w-auto"
                        >
                            {isTestLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Play className="w-4 h-4 mr-2" />}
                            LANCER TEST
                        </Button>
                    </div>

                    {/* API RESULT TERMINAL */}
                    {testResult && (
                        <div className="mt-6 bg-black/80 border border-white/10 rounded-xl p-4 font-mono text-[11px] overflow-auto max-h-64">
                            <div className="flex gap-2 items-center text-xs mb-2 border-b border-white/10 pb-2">
                                <span className={testResult.success ? "text-emerald-400" : "text-rose-400"}>
                                    {testResult.success ? "✅ Fetch & Data OK" : `❌ Erreur (Status Code: ${testResult.statusSucces})`}
                                </span>
                            </div>
                            <pre className="text-zinc-300 whitespace-pre-wrap">
                                {JSON.stringify(testResult, null, 2)}
                            </pre>
                        </div>
                    )}
                </TabsContent>

                {/* QUEUES ZONE */}
                <TabsContent value="queue" className="space-y-6">
                    <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-xl text-rose-400 text-xs my-4">
                        <strong>⚠️ ATTENTION:</strong> Injecter des jobs manuellement ici déclenchera l'opération sur tout le système. Utilisez ces boutons uniquement en cas de blocage d'un worker ou pour reset un cycle de test.
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Button 
                            onClick={async () => {
                                setIsMetamobLoading(true);
                                const res = await triggerGlobalMetamobSync();
                                if (res.success) toast.success(res.message);
                                else toast.error(res.error);
                                setIsMetamobLoading(false);
                            }} 
                            disabled={isMetamobLoading}
                            variant="outline"
                            className="h-auto py-4 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-300 border-emerald-500/20"
                        >
                            <div className="flex flex-col items-center gap-2">
                                {isMetamobLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Download className="w-5 h-5" />}
                                <span className="font-bold tracking-wider text-xs uppercase">Force Metamob Queue</span>
                            </div>
                        </Button>

                        <Button 
                            onClick={async () => {
                                setIsLadderLoading(true);
                                const res = await triggerGlobalLadderSync();
                                if (res.success) toast.success(res.message);
                                else toast.error(res.error);
                                setIsLadderLoading(false);
                            }} 
                            disabled={isLadderLoading}
                            variant="outline"
                            className="h-auto py-4 bg-amber-500/10 hover:bg-amber-500/20 text-amber-300 border-amber-500/20"
                        >
                            <div className="flex flex-col items-center gap-2">
                                {isLadderLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Trophy className="w-5 h-5" />}
                                <span className="font-bold tracking-wider text-xs uppercase">Force Ladder Queue</span>
                            </div>
                        </Button>
                    </div>
                </TabsContent>
            </Tabs>
        </div>
    );
}

import { auth } from "@/auth";
import { DocEditor } from "../_components/doc-editor";
import { db } from "@/lib/prisma";

export default async function AdminDocEditPage({ params }: { params: Promise<{ id: string }> }) {
    const session = await auth();
    const { id } = await params;

    let doc = null;
    if (id !== "new") {
        doc = await db.docPage.findUnique({ where: { id } });
    }

    return (
        <div className="flex-1 flex flex-col h-full font-sans selection:bg-purple-500/30 overflow-hidden">
            <DocEditor initialData={doc as any} />
        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { saveDoc, type DocPageData, type CreateDocInput } from "@/server/actions/doc-actions";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { AdvancedEditor } from "@/components/editor/advanced-editor";
import { DocContent } from "@/components/doc/doc-content";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Shield, Globe, Save, X, Eye, Settings2, FileText, HelpCircle } from "lucide-react";
import { cn } from "@/lib/utils";

export function DocEditor({ initialData }: { initialData?: DocPageData }) {
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [isPreviewOpen, setIsPreviewOpen] = useState(true);

    const [formData, setFormData] = useState<CreateDocInput>({
        slug: initialData?.slug || "",
        title: initialData?.title || "",
        content: initialData?.content || "",
        category: initialData?.category || "Général",
        order: initialData?.order ?? 0,
        isPublished: initialData?.isPublished ?? true,
        accessLevel: initialData?.accessLevel || "PUBLIC",
    });

    const handleChange = (field: keyof CreateDocInput, value: any) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleSubmit = async (e?: React.FormEvent) => {
        e?.preventDefault();
        setLoading(true);
        const res = await saveDoc({ ...formData, id: initialData?.id });
        if (res.success) {
            toast.success("Page sauvegardée avec succès !");
            router.push("/god/docs");
            router.refresh();
        } else {
            toast.error("Erreur de sauvegarde: " + res.error);
        }
        setLoading(false);
    };

    return (
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-zinc-950/20 pt-2">
            {/* 🚀 TOP ACTION BAR (Fixed) */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-white/5 bg-zinc-900/40 backdrop-blur-xl z-30">
                <div className="flex items-center gap-4">
                    <div className="h-10 w-10 rounded-xl bg-indigo-600/20 border border-indigo-500/30 flex items-center justify-center">
                        <FileText className="w-5 h-5 text-indigo-400" />
                    </div>
                    <div>
                        <h2 className="text-sm font-black text-white uppercase tracking-widest leading-none mb-1">
                            {initialData?.id ? "Mise à jour d'Archive" : "Nouvelle Entrée Documentaire"}
                        </h2>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-tighter">Status:</span>
                            <Badge status={formData.isPublished ? "online" : "draft"} />
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setIsPreviewOpen(!isPreviewOpen)}
                        className={cn("rounded-xl border border-white/5", isPreviewOpen ? "bg-indigo-500/10 text-indigo-400" : "text-zinc-500")}
                    >
                        <Eye className="w-4 h-4 mr-2" />
                        {isPreviewOpen ? "Masquer l'aperçu" : "Afficher l'aperçu"}
                    </Button>
                    <div className="w-px h-6 bg-white/5 mx-2" />
                    <Button
                        type="button"
                        variant="ghost"
                        onClick={() => router.back()}
                        className="rounded-xl text-zinc-500 hover:text-white hover:bg-white/5 font-bold px-4"
                    >
                        <X className="w-4 h-4 mr-2" />
                        Annuler
                    </Button>
                    <Button
                        onClick={() => handleSubmit()}
                        disabled={loading}
                        className="rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-black px-6 shadow-lg shadow-indigo-500/20"
                    >
                        {loading ? (
                            <div className="h-4 w-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        ) : (
                            <>
                                <Save className="w-4 h-4 mr-2" />
                                Publier les Changements
                            </>
                        )}
                    </Button>
                </div>
            </div>

            {/* 🛠️ MAIN EDITOR INTERFACE */}
            <div className="flex-1 overflow-hidden">
                <ResizablePanelGroup orientation="horizontal" className="h-full">
                    {/* LEFT: FORM & EDITOR */}
                    <ResizablePanel defaultSize={60} minSize={30} className="flex flex-col bg-zinc-950/40">
                        <div className="flex-1 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10 p-8 space-y-12">

                            {/* Metadata Grid */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6 rounded-3xl border border-white/5 bg-white/[0.02]">
                                {/* TITRE */}
                                <div className="space-y-4 md:col-span-2">
                                    <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">Titre de la page</Label>
                                    <Input
                                        value={formData.title}
                                        onChange={(e) => handleChange("title", e.target.value)}
                                        placeholder="Ex: Quête de l'Ocre"
                                        className="bg-black/40 border-white/5 h-14 text-lg font-bold focus:border-teal-500/50 transition-all rounded-xl"
                                    />
                                </div>

                                {/* SLUG */}
                                <div className="space-y-4">
                                    <div className="flex items-center justify-between">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">Lien d'accès (URL Slug)</Label>
                                        <span className="text-[9px] text-teal-500/60 font-bold uppercase tracking-tighter">Unique</span>
                                    </div>
                                    <div className="relative">
                                        <div className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600 text-sm font-bold">/docs/</div>
                                        <Input
                                            value={formData.slug}
                                            onChange={(e) => handleChange("slug", e.target.value)}
                                            placeholder="intro-ocre"
                                            className="bg-black/40 border-white/5 h-12 pl-16 font-mono text-sm focus:border-teal-500/50 transition-all rounded-xl"
                                        />
                                    </div>
                                </div>


                                {/* CATEGORY (Classification) */}
                                <div className="space-y-4">
                                    <div className="flex items-center justify-between">
                                        <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">Catégorie (Classification)</Label>
                                        <div className="group relative">
                                            <HelpCircle className="w-3.5 h-3.5 text-zinc-600 cursor-help" />
                                            <div className="absolute right-0 bottom-full mb-2 w-48 p-2 bg-zinc-900 border border-white/10 rounded text-[9px] text-zinc-400 opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none shadow-2xl">
                                                Ex: <strong>Guides Utilisateurs</strong>, <strong>Administration</strong> ou <strong>Documentation Technique</strong>.
                                            </div>
                                        </div>
                                    </div>
                                    <Input
                                        value={formData.category}
                                        onChange={(e) => handleChange("category", e.target.value)}
                                        placeholder="Ex: Guides Utilisateurs"
                                        className="bg-black/40 border-white/5 h-12 font-bold focus:border-teal-500/50 transition-all rounded-xl"
                                    />
                                </div>

                                {/* ACCESS LEVEL */}
                                <div className="space-y-4">
                                    <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">Niveau d'Accès</Label>
                                    <Select
                                        value={formData.accessLevel}
                                        onValueChange={(val: any) => handleChange("accessLevel", val)}
                                    >
                                        <SelectTrigger className="bg-black/40 border-white/5 h-12 rounded-xl focus:ring-teal-500/20 px-4">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent className="bg-zinc-900 border-white/10">
                                            <SelectItem value="PUBLIC" className="focus:bg-teal-500/20 py-3">
                                                <div className="flex items-center gap-2">
                                                    <Globe className="w-4 h-4 text-teal-400" />
                                                    <div className="flex flex-col text-left">
                                                        <span className="font-bold text-xs uppercase tracking-widest text-white">Public</span>
                                                        <span className="text-[9px] text-zinc-500 font-medium">Visible par tous les membres</span>
                                                    </div>
                                                </div>
                                            </SelectItem>
                                            <SelectItem value="ADMIN" className="focus:bg-amber-500/20 py-3">
                                                <div className="flex items-center gap-2">
                                                    <Shield className="w-4 h-4 text-amber-500" />
                                                    <div className="flex flex-col text-left">
                                                        <span className="font-bold text-xs uppercase tracking-widest text-white">Administration</span>
                                                        <span className="text-[9px] text-zinc-500 font-medium">Réservé aux Officiers / Staff</span>
                                                    </div>
                                                </div>
                                            </SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>


                                {/* PUBLICATION SWITCH */}
                                <div className="space-y-4 flex flex-col justify-end">
                                    <div className="bg-black/40 border border-white/5 rounded-xl p-3 flex items-center justify-between h-12">
                                        <div className="flex items-center gap-2">
                                            <div className={cn("w-1.5 h-1.5 rounded-full shadow-[0_0_8px]", formData.isPublished ? "bg-teal-500 shadow-teal-500/50" : "bg-zinc-600 shadow-transparent")} />
                                            <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Visibilité publique</span>
                                        </div>
                                        <button
                                            onClick={() => handleChange("isPublished", !formData.isPublished)}
                                            className={cn(
                                                "relative inline-flex h-5 w-9 items-center rounded-full transition-colors focus:outline-none",
                                                formData.isPublished ? "bg-teal-600" : "bg-zinc-800"
                                            )}
                                        >
                                            <span className={cn(
                                                "inline-block h-3 w-3 transform rounded-full bg-white transition-transform",
                                                formData.isPublished ? "translate-x-5" : "translate-x-1"
                                            )} />
                                        </button>
                                    </div>
                                </div>

                            </div>

                            {/* Content Editor */}
                            <div className="space-y-4">
                                <div className="flex items-center justify-between border-b border-white/5 pb-2">
                                    <Label className="text-sm font-black uppercase tracking-widest text-zinc-500">Contenu (Rich Text)</Label>
                                    <span className="text-[10px] text-zinc-600 font-mono italic">Markdown supporté</span>
                                </div>
                                <AdvancedEditor
                                    initialContent={formData.content}
                                    onChange={(html) => handleChange("content", html)}
                                />
                            </div>
                        </div>
                    </ResizablePanel>

                    {isPreviewOpen && (
                        <>
                            <ResizableHandle withHandle className="bg-white/5 w-1.5 hover:bg-teal-500/20 transition-colors" />
                            {/* RIGHT: PREVIEW */}
                            <ResizablePanel defaultSize={40} minSize={20} className="hidden lg:flex flex-col bg-zinc-900/20 dark">
                                <div className="h-full flex flex-col">
                                    <div className="p-4 border-b border-white/5 bg-white/[0.02] flex items-center justify-between">
                                        <div className="flex items-center gap-2">
                                            <Eye className="w-3 h-3 text-teal-400" />
                                            <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em]">Rendu Temps Réel</span>
                                        </div>
                                    </div>
                                    <div className="flex-1 overflow-y-auto p-12 scrollbar-thin scrollbar-thumb-white/10">
                                        <div className="max-w-3xl mx-auto">
                                            <DocContent content={formData.content} />
                                        </div>
                                    </div>
                                </div>
                            </ResizablePanel>
                        </>
                    )}


                </ResizablePanelGroup>
            </div>
        </div>
    );
}

function Badge({ status }: { status: "online" | "draft" }) {
    return (
        <div className={cn(
            "inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider border",
            status === "online"
                ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20"
                : "bg-amber-500/10 text-amber-500 border-amber-500/20"
        )}>
            <div className={cn("w-1.5 h-1.5 rounded-full", status === "online" ? "bg-emerald-400 animate-pulse" : "bg-amber-400")} />
            {status === "online" ? "En ligne" : "Brouillon / Scan"}
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { DragDropContext, Droppable, Draggable, DropResult, DroppableProvided, DraggableProvided, DraggableStateSnapshot, DroppableStateSnapshot } from "@hello-pangea/dnd";
import { Plus, Trash2, Save, X, GripVertical, Navigation, Info, Database, Sword, Package, Globe, Link as LinkIcon, Edit3 } from "lucide-react";
import { toast } from "sonner";
import { upsertOptimizedGuide, deleteOptimizedGuide } from "@/server/actions/optimized-guide-actions";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

// Local types
type ObjectiveType = 'QUEST' | 'DUNGEON' | 'RESOURCE' | 'BOSS' | 'OTHER';

type Objective = {
    id: string;
    type: ObjectiveType;
    name: string;
    quantity?: number;
    link?: string;
    imageUrl?: string;
};

type GuideStep = {
    id: string; // local temp ids for dnd
    order: number;
    title: string;
    description: string;
    questIds: string[]; // Legacy support
    objectives: Objective[]; // New structured data
};

type GuideForm = {
    id?: string;
    slug: string;
    name: string;
    description: string;
    imageUrl: string;
    isActive: boolean;
    steps: GuideStep[];
};

export default function OptimizedGuideAdminClient({ initialGuides, dofusItems }: { initialGuides: any[], dofusItems: any[] }) {
    const [guides, setGuides] = useState(initialGuides);
    const [selectedGuide, setSelectedGuide] = useState<GuideForm | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    
    // Custom Objective Modal/Form state
    const [isAddingObjective, setIsAddingObjective] = useState<{stepIdx: number} | null>(null);
    const [newObjective, setNewObjective] = useState<Partial<Objective>>({ type: 'DUNGEON', quantity: 1 });

    // Dofus items map for easy lookup
    const availableQuests = dofusItems.flatMap(d => d.questChains.flatMap((c: any) => c.entries.map((e: any) => ({ 
        ...e, 
        dofusColor: d.color, 
        dofusImage: d.localImageUrl || d.imageUrl 
    }))));
    
    const getQuestDetails = (id: string) => availableQuests.find(q => q.id === id);

    const handleCreateNew = () => {
        setSelectedGuide({
            slug: "nouvelle-route",
            name: "Nouvelle Route",
            description: "",
            imageUrl: "",
            isActive: false,
            steps: []
        });
    };

    const handleSelectGuide = (guide: any) => {
        const parsedSteps = guide.steps.map((s: any) => {
            // Migration logic: if objectives is missing, build it from questIds
            let objectives = s.objectives as Objective[] || [];
            if (objectives.length === 0 && s.questIds && s.questIds.length > 0) {
                objectives = s.questIds.map((qid: string) => {
                    const qData = getQuestDetails(qid);
                    return {
                        id: qid,
                        type: 'QUEST',
                        name: qData?.name || "Quête",
                        imageUrl: qData?.dofusImage
                    };
                });
            }

            return {
                id: s.id,
                order: s.order,
                title: s.title,
                description: s.description || "",
                questIds: s.questIds || [],
                objectives: objectives
            };
        });

        setSelectedGuide({
            id: guide.id,
            slug: guide.slug,
            name: guide.name,
            description: guide.description || "",
            imageUrl: guide.imageUrl || "",
            isActive: guide.isActive,
            steps: parsedSteps,
        });
    };

    const handleAddStep = () => {
        if (!selectedGuide) return;
        const newStepId = `temp_${Date.now()}`;
        const newSteps = [...selectedGuide.steps, {
            id: newStepId,
            order: selectedGuide.steps.length,
            title: `Étape ${selectedGuide.steps.length + 1}`,
            description: "",
            questIds: [],
            objectives: []
        }];
        setSelectedGuide({ ...selectedGuide, steps: newSteps });
    };

    const handleDeleteStep = (stepId: string) => {
        if (!selectedGuide) return;
        const newSteps = selectedGuide.steps.filter(s => s.id !== stepId).map((s, idx) => ({ ...s, order: idx }));
        setSelectedGuide({ ...selectedGuide, steps: newSteps });
    };

    const handleSave = async () => {
        if (!selectedGuide) return;
        setIsSaving(true);
        try {
            // Prep data: ensure questIds is synced with objectives for compatibility
            const dataToSave = {
                ...selectedGuide,
                steps: selectedGuide.steps.map(s => ({
                    ...s,
                    questIds: s.objectives.filter(o => o.type === 'QUEST').map(o => o.id)
                }))
            };

            const res = await upsertOptimizedGuide(undefined, dataToSave as any);
            if (res.success) {
                toast.success("Guide sauvegardé avec succès !");
                window.location.reload();
            } else {
                toast.error((res as any).error || "Erreur lors de la sauvegarde");
            }
        } catch (e: any) {
            toast.error(e.message);
        }
        setIsSaving(false);
    };

    // DofusDB Link Parser
    const parseDofusDBLink = (url: string) => {
        if (!url) return;
        
        // Items (Resources, Gear)
        const itemMatch = url.match(/\/item\/(\d+)/i) || url.match(/\/items\/view\/(\d+)/i);
        if (itemMatch) {
            setNewObjective(prev => ({
                ...prev,
                imageUrl: `https://static.dofusdb.fr/items/${itemMatch[1]}.png`,
                link: url
            }));
            return;
        }

        // Monsters (Bosses)
        const monsterMatch = url.match(/\/monster\/(\d+)/i) || url.match(/\/monsters\/view\/(\d+)/i);
        if (monsterMatch) {
            setNewObjective(prev => ({
                ...prev,
                imageUrl: `https://static.dofusdb.fr/monsters/${monsterMatch[1]}.png`,
                link: url
            }));
            return;
        }
    };

    const handleConfirmObjective = () => {
        if (!selectedGuide || isAddingObjective === null || !newObjective.name) return;

        const updatedSteps = [...selectedGuide.steps];
        const step = updatedSteps[isAddingObjective.stepIdx];
        
        const obj: Objective = {
            id: newObjective.id || `custom_${Date.now()}`,
            type: newObjective.type as ObjectiveType,
            name: newObjective.name,
            quantity: newObjective.quantity,
            link: newObjective.link,
            imageUrl: newObjective.imageUrl
        };

        step.objectives.push(obj);
        setSelectedGuide({ ...selectedGuide, steps: updatedSteps });
        setIsAddingObjective(null);
        setNewObjective({ type: 'DUNGEON', quantity: 1 });
    };

    const onDragEnd = (result: DropResult) => {
        if (!selectedGuide || !result.destination) return;

        const { source, destination } = result;
        const newSteps = [...selectedGuide.steps];

        // 1. Moving a Step
        if (source.droppableId === "steps-board" && destination.droppableId === "steps-board") {
            const [moved] = newSteps.splice(source.index, 1);
            newSteps.splice(destination.index, 0, moved);
            const reordered = newSteps.map((s, idx) => ({ ...s, order: idx }));
            setSelectedGuide({ ...selectedGuide, steps: reordered });
            return;
        }

        // 2. Moving an Objective between Drawer (Quests) and a Step
        if (source.droppableId === "drawer-quests" && destination.droppableId.startsWith("step-")) {
            const destStepIdx = newSteps.findIndex(s => `step-${s.id}` === destination.droppableId);
            if (destStepIdx === -1) return;

            const targetQuestId = result.draggableId.replace("drawer-", "");
            const qData = getQuestDetails(targetQuestId);
            
            // Prevent duplicate quests in the same step
            if (!newSteps[destStepIdx].objectives.find(o => o.id === targetQuestId)) {
                const newObj: Objective = {
                    id: targetQuestId,
                    type: 'QUEST',
                    name: qData?.name || "Quête",
                    imageUrl: qData?.dofusImage
                };
                newSteps[destStepIdx].objectives.splice(destination.index, 0, newObj);
                setSelectedGuide({ ...selectedGuide, steps: newSteps });
            }
            return;
        }

        // 3. Moving an Objective internally within/between Steps
        if (source.droppableId.startsWith("step-") && destination.droppableId.startsWith("step-")) {
            const sourceIdx = newSteps.findIndex(s => `step-${s.id}` === source.droppableId);
            const destIdx = newSteps.findIndex(s => `step-${s.id}` === destination.droppableId);
            
            if (sourceIdx === -1 || destIdx === -1) return;

            const [moved] = newSteps[sourceIdx].objectives.splice(source.index, 1);
            newSteps[destIdx].objectives.splice(destination.index, 0, moved);

            setSelectedGuide({ ...selectedGuide, steps: newSteps });
            return;
        }
        
        // 4. Removing from Step
        if (source.droppableId.startsWith("step-") && destination.droppableId === "drawer-quests") {
             const sourceIdx = newSteps.findIndex(s => `step-${s.id}` === source.droppableId);
             if (sourceIdx !== -1) {
                 newSteps[sourceIdx].objectives.splice(source.index, 1);
                 setSelectedGuide({ ...selectedGuide, steps: newSteps });
             }
        }
    };

    return (
        <div className="flex w-full min-h-[70vh] gap-6">
            {/* List Selection Panel */}
            <div className="w-1/4 bg-zinc-900 border border-white/10 rounded-3xl p-4 flex flex-col gap-4">
                <div className="flex justify-between items-center px-2">
                    <h3 className="font-bold text-white uppercase text-xs tracking-widest opacity-50">Vos Routes</h3>
                    <button onClick={handleCreateNew} className="p-2 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 rounded-xl transition-colors">
                        <Plus className="w-4 h-4" />
                    </button>
                </div>
                
                <div className="flex flex-col gap-2 overflow-y-auto custom-scrollbar flex-1 pr-1">
                    {guides.map(g => (
                        <button 
                            key={g.id} 
                            onClick={() => handleSelectGuide(g)}
                            className={`p-4 rounded-2xl text-left transition-all group ${selectedGuide?.id === g.id ? 'bg-emerald-600 shadow-xl' : 'bg-black/20 hover:bg-white/5 border border-white/5'}`}
                        >
                            <div className="font-bold text-white mb-1 group-hover:translate-x-1 transition-transform">{g.name}</div>
                            <div className="text-[10px] uppercase font-black opacity-40">{g.steps.length} Étapes</div>
                        </button>
                    ))}
                    {guides.length === 0 && (
                        <div className="text-center text-zinc-500 text-sm p-8 opacity-40 italic">
                            Aucune route configurée
                        </div>
                    )}
                </div>
            </div>

            {/* Editing Panel */}
            {selectedGuide ? (
                <div className="flex-1 flex flex-col bg-zinc-900/50 border border-white/10 rounded-3xl p-6">
                     <div className="flex justify-between flex-wrap gap-4 items-start mb-8 pb-6 border-b border-white/5">
                        <div className="flex-1 space-y-4">
                            <input 
                                value={selectedGuide.name}
                                onChange={e => setSelectedGuide({...selectedGuide, name: e.target.value})}
                                className="w-full bg-transparent text-4xl font-black text-white outline-none placeholder-zinc-800" 
                                placeholder="Nom de la Route"
                            />
                            <div className="flex gap-4">
                                <div className="flex items-center gap-2 px-3 py-1.5 bg-black/40 border border-white/10 rounded-xl">
                                     <Globe className="w-3.5 h-3.5 text-zinc-500" />
                                     <input 
                                        value={selectedGuide.slug}
                                        onChange={e => setSelectedGuide({...selectedGuide, slug: e.target.value})}
                                        className="bg-transparent text-xs text-zinc-300 outline-none w-32" 
                                        placeholder="slug-url"
                                    />
                                </div>
                            </div>
                        </div>

                        <div className="flex gap-3">
                            <button onClick={() => setSelectedGuide(null)} className="px-6 py-2.5 bg-white/5 hover:bg-white/10 text-white rounded-2xl transition-colors text-sm font-bold">
                                Annuler
                            </button>
                            <button onClick={handleSave} disabled={isSaving} className="px-6 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl transition-colors text-sm font-bold inline-flex items-center gap-2 shadow-lg shadow-emerald-900/20">
                                <Save className="w-4 h-4" /> {isSaving ? "Sauvegarde..." : "Sauvegarder"}
                            </button>
                        </div>
                     </div>

                     <DragDropContext onDragEnd={onDragEnd}>
                        <div className="flex flex-1 gap-6 min-h-0">
                            
                            {/* Drawer: Quêtes disponibles */}
                            <div className="w-80 flex flex-col bg-black/40 border border-white/5 rounded-2xl p-4">
                                <h4 className="font-black text-[10px] uppercase tracking-widest text-zinc-500 mb-6 flex items-center gap-2">
                                    <Database className="w-3.5 h-3.5 text-emerald-500" /> Bibliothèque de quêtes
                                </h4>
                                <Droppable droppableId="drawer-quests" isDropDisabled={true} type="objective">
                                    {(provided: DroppableProvided) => (
                                        <div ref={provided.innerRef} {...provided.droppableProps} className="flex-1 overflow-y-auto custom-scrollbar space-y-4 pr-3">
                                            {dofusItems.map(dof => (
                                                <div key={dof.id} className="bg-white/[0.02] p-3 rounded-2xl border border-white/5">
                                                    <div className="text-[9px] font-black uppercase tracking-[0.2em] mb-3 px-1" style={{ color: dof.color || "#fff"}}>
                                                        {dof.name}
                                                    </div>
                                                    <div className="space-y-1.5">
                                                        {dof.questChains.flatMap((c:any) => c.entries).map((quest: any, index: number) => (
                                                            <Draggable key={`drawer-${quest.id}`} draggableId={`drawer-${quest.id}`} index={index}>
                                                                {(provided: DraggableProvided, snapshot: DraggableStateSnapshot) => (
                                                                    <div 
                                                                        ref={provided.innerRef} 
                                                                        {...provided.draggableProps} 
                                                                        {...provided.dragHandleProps}
                                                                        className={`p-2.5 rounded-xl text-[11px] font-bold transition-all shadow-sm flex items-center gap-2 ${snapshot.isDragging ? 'bg-emerald-600 text-white shadow-2xl z-50' : 'bg-black/40 text-zinc-400 hover:bg-white/5 border border-white/5'}`}
                                                                    >
                                                                        <div className="w-4 h-4 rounded-md bg-white/5 flex items-center justify-center text-[8px] opacity-40 shrink-0">L.{quest.level}</div>
                                                                        <span className="truncate">{quest.name}</span>
                                                                    </div>
                                                                )}
                                                            </Draggable>
                                                        ))}
                                                    </div>
                                                </div>
                                            ))}
                                            {provided.placeholder}
                                        </div>
                                    )}
                                </Droppable>
                            </div>

                            {/* Steps Board */}
                            <Droppable droppableId="steps-board" direction="vertical" type="step">
                                {(provided: DroppableProvided) => (
                                    <div ref={provided.innerRef} {...provided.droppableProps} className="flex-1 overflow-y-auto custom-scrollbar space-y-6 pr-3">
                                        {selectedGuide.steps.map((step, index) => (
                                            <Draggable key={step.id} draggableId={step.id} index={index}>
                                                {(provided: DraggableProvided, snapshot: DraggableStateSnapshot) => (
                                                    <div
                                                        ref={provided.innerRef}
                                                        {...provided.draggableProps}
                                                        className={`bg-zinc-800/40 border border-white/10 rounded-[2rem] p-6 transition-all ${snapshot.isDragging ? 'shadow-2xl ring-2 ring-emerald-500 bg-zinc-800' : ''}`}
                                                    >
                                                        <div className="flex justify-between items-center mb-6 group/step">
                                                            <div className="flex gap-4 items-center flex-1">
                                                                <div {...provided.dragHandleProps} className="cursor-grab p-2 text-zinc-600 hover:text-white transition-colors">
                                                                    <GripVertical className="w-5 h-5" />
                                                                </div>
                                                                <div className="flex flex-col flex-1">
                                                                    <input 
                                                                        value={step.title}
                                                                        onChange={e => {
                                                                            const copy = [...selectedGuide.steps];
                                                                            copy[index].title = e.target.value;
                                                                            setSelectedGuide({...selectedGuide, steps: copy});
                                                                        }}
                                                                        className="bg-transparent text-xl font-black text-white outline-none w-full placeholder-zinc-700"
                                                                    />
                                                                    <input 
                                                                        value={step.description}
                                                                        onChange={e => {
                                                                            const copy = [...selectedGuide.steps];
                                                                            copy[index].description = e.target.value;
                                                                            setSelectedGuide({...selectedGuide, steps: copy});
                                                                        }}
                                                                        placeholder="Description courte de l'étape..."
                                                                        className="bg-transparent text-xs text-zinc-500 outline-none w-full"
                                                                    />
                                                                </div>
                                                            </div>
                                                            
                                                            <div className="flex items-center gap-2 opacity-0 group-hover/step:opacity-100 transition-all">
                                                                <button 
                                                                    onClick={() => setIsAddingObjective({ stepIdx: index })}
                                                                    className="p-2 text-emerald-500 hover:bg-emerald-500/10 rounded-xl transition-all flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest"
                                                                >
                                                                    <Plus className="w-4 h-4" /> Ajouter Objectif
                                                                </button>
                                                                <button onClick={() => handleDeleteStep(step.id)} className="p-2 text-rose-500/50 hover:bg-rose-500/20 hover:text-rose-400 rounded-xl transition-all">
                                                                    <Trash2 className="w-4 h-4" />
                                                                </button>
                                                            </div>
                                                        </div>

                                                        {/* Droppable Zone for Objectives inside this step */}
                                                        <Droppable droppableId={`step-${step.id}`} type="objective">
                                                            {(provided: DroppableProvided, snapshot: DroppableStateSnapshot) => (
                                                                <div 
                                                                    ref={provided.innerRef} 
                                                                    {...provided.droppableProps}
                                                                    className={`min-h-[80px] rounded-2xl p-3 transition-all ${snapshot.isDraggingOver ? 'bg-emerald-500/5 border-2 border-dashed border-emerald-500/30' : 'bg-black/20 border-2 border-dashed border-white/[0.03]'}`}
                                                                >
                                                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                                                                        {step.objectives.map((obj, oIdx) => (
                                                                            <Draggable key={`${step.id}-${obj.id}-${oIdx}`} draggableId={`${step.id}-${obj.id}-${oIdx}`} index={oIdx}>
                                                                                {(provided: DraggableProvided, snapshot: DraggableStateSnapshot) => (
                                                                                    <div
                                                                                        ref={provided.innerRef}
                                                                                        {...provided.draggableProps}
                                                                                        {...provided.dragHandleProps}
                                                                                        className={`p-3 rounded-xl bg-zinc-900/80 border border-white/5 text-sm font-medium text-zinc-300 flex items-center justify-between group/obj transition-all ${snapshot.isDragging ? 'shadow-2xl ring-2 ring-emerald-500 z-50' : 'hover:border-white/20'}`}
                                                                                    >
                                                                                        <div className="flex items-center gap-3 truncate">
                                                                                            <div className="w-8 h-8 rounded-lg bg-black/40 flex items-center justify-center border border-white/5 shrink-0 overflow-hidden">
                                                                                                {obj.imageUrl ? <img src={obj.imageUrl} className="w-6 h-6 object-contain" /> : (
                                                                                                    obj.type === 'QUEST' ? <Database className="w-4 h-4 opacity-40" /> : <Sword className="w-4 h-4 opacity-40" />
                                                                                                )}
                                                                                            </div>
                                                                                            <div className="flex flex-col truncate">
                                                                                                <span className="text-[10px] uppercase font-black tracking-widest text-zinc-600 leading-none mb-1">{obj.type}</span>
                                                                                                <span className="truncate font-bold">{obj.name} {obj.quantity && obj.quantity > 1 ? `(x${obj.quantity})` : ''}</span>
                                                                                            </div>
                                                                                        </div>
                                                                                        
                                                                                        <button 
                                                                                            onClick={() => {
                                                                                                const copy = [...selectedGuide.steps];
                                                                                                copy[index].objectives.splice(oIdx, 1);
                                                                                                setSelectedGuide({...selectedGuide, steps: copy});
                                                                                            }}
                                                                                            className="p-1.5 text-zinc-600 hover:text-rose-500 transition-colors opacity-0 group-hover/obj:opacity-100"
                                                                                        >
                                                                                            <X className="w-3.5 h-3.5" />
                                                                                        </button>
                                                                                    </div>
                                                                                )}
                                                                            </Draggable>
                                                                        ))}
                                                                    </div>
                                                                    {provided.placeholder}
                                                                    {step.objectives.length === 0 && !snapshot.isDraggingOver && (
                                                                        <div className="text-center text-[10px] font-black uppercase tracking-widest text-zinc-700 py-6">
                                                                            Glissez des quêtes ou ajoutez des objectifs
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            )}
                                                        </Droppable>
                                                    </div>
                                                )}
                                            </Draggable>
                                        ))}
                                        {provided.placeholder}

                                        <button onClick={handleAddStep} className="w-full flex items-center justify-center gap-2 py-6 mt-4 border-2 border-dashed border-white/5 hover:border-emerald-500/30 hover:bg-emerald-500/5 hover:text-emerald-400 text-zinc-600 rounded-[2rem] transition-all font-black uppercase text-xs tracking-widest">
                                            <Plus className="w-5 h-5" /> Ajouter une Étape
                                        </button>
                                    </div>
                                )}
                            </Droppable>

                        </div>
                     </DragDropContext>
                </div>
            ) : (
                <div className="flex-1 flex flex-col items-center justify-center bg-black/20 border border-white/5 rounded-[3rem] p-12 text-zinc-600">
                    <Navigation className="w-20 h-20 mb-6 opacity-5" />
                    <h2 className="text-2xl font-black text-white opacity-40 mb-2">Centre de contrôle des routes</h2>
                    <p className="max-w-sm text-center text-sm">Sélectionnez une route pour commencer à forger la progression de vos membres.</p>
                </div>
            )}

            {/* Objective Modal */}
            {isAddingObjective !== null && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
                    <div className="bg-zinc-900 border border-white/10 rounded-[2.5rem] p-8 w-full max-w-lg shadow-2xl space-y-8 animate-in zoom-in-95 duration-300">
                        <div className="flex justify-between items-center">
                            <h3 className="text-2xl font-black text-white">Nouvel Objectif</h3>
                            <button onClick={() => setIsAddingObjective(null)} className="p-2 hover:bg-white/5 rounded-full"><X className="w-6 h-6 text-zinc-500" /></button>
                        </div>

                        <div className="space-y-6">
                            <div className="grid grid-cols-2 gap-4">
                                {(['DUNGEON', 'RESOURCE', 'BOSS', 'OTHER'] as ObjectiveType[]).map(t => (
                                    <button 
                                        key={t}
                                        onClick={() => setNewObjective({...newObjective, type: t})}
                                        className={`flex items-center gap-3 p-4 rounded-2xl border transition-all ${newObjective.type === t ? 'bg-emerald-500/10 border-emerald-500/50 text-white' : 'bg-black/20 border-white/5 text-zinc-500 hover:border-white/10'}`}
                                    >
                                        {t === 'DUNGEON' && <Sword className="w-5 h-5" />}
                                        {t === 'RESOURCE' && <Package className="w-5 h-5" />}
                                        {t === 'BOSS' && <Database className="w-5 h-5" />}
                                        {t === 'OTHER' && <Info className="w-5 h-5" />}
                                        <span className="text-xs font-bold uppercase tracking-widest">{t}</span>
                                    </button>
                                ))}
                            </div>

                            <div className="space-y-4">
                                <Label className="text-[10px] uppercase font-black tracking-widest text-zinc-600 ml-1">Configuration</Label>
                                <Input 
                                    placeholder="Nom de l'objectif (ex: Battez le Comte Harebourg)" 
                                    value={newObjective.name || ''} 
                                    onChange={e => setNewObjective({...newObjective, name: e.target.value})}
                                    className="bg-black/40 border-white/10 rounded-xl h-12"
                                />
                                <div className="flex gap-4">
                                    <div className="flex-1">
                                        <div className="relative">
                                            <Input 
                                                placeholder="Lien DofusDB" 
                                                value={newObjective.link || ''} 
                                                onChange={e => {
                                                    setNewObjective({...newObjective, link: e.target.value});
                                                    parseDofusDBLink(e.target.value);
                                                }}
                                                className="bg-black/40 border-white/10 rounded-xl h-12 pl-10"
                                            />
                                            <Globe className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                                        </div>
                                    </div>
                                    <div className="w-24">
                                        <Input 
                                            type="number" 
                                            placeholder="Qté" 
                                            value={newObjective.quantity || 1} 
                                            onChange={e => setNewObjective({...newObjective, quantity: parseInt(e.target.value)})}
                                            className="bg-black/40 border-white/10 rounded-xl h-12 text-center"
                                        />
                                    </div>
                                </div>
                            </div>

                            {newObjective.imageUrl && (
                                <div className="p-4 bg-emerald-500/5 border border-emerald-500/10 rounded-2xl flex items-center justify-between">
                                    <div className="flex items-center gap-4">
                                        <img src={newObjective.imageUrl} className="w-10 h-10 object-contain" />
                                        <span className="text-xs font-bold text-emerald-400">Miniature détectée !</span>
                                    </div>
                                    <button onClick={() => setNewObjective({...newObjective, imageUrl: undefined})} className="text-[10px] font-black uppercase text-zinc-500 hover:text-white transition-colors">Retirer</button>
                                </div>
                            )}
                        </div>

                        <button 
                            onClick={handleConfirmObjective}
                            disabled={!newObjective.name}
                            className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-30 disabled:hover:bg-emerald-600 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl shadow-emerald-900/20"
                        >
                            Valider l'objectif
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

import { redirect } from "next/navigation";
import { auth } from "@/auth";
import { isSuperAdmin } from "@/server/actions/super-admin-actions";
import { db } from "@/lib/prisma";
import { Route, Navigation } from "lucide-react";
import OptimizedGuideAdminClient from "./OptimizedGuideAdminClient";

export const metadata = {
    title: "GOD | Guides Optimisés — Constructeur de Routes",
    description: "Interface super-admin pour construire les routes optimisées Dofus",
};

export default async function DofusGuidesGodPage() {
    const session = await auth();
    

    if (!session?.user?.id) redirect("/");
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) redirect("/");

    // Load existing guides
    const guides = await db.optimizedGuide.findMany({
        include: {
            steps: {
                orderBy: { order: "asc" },
            },
        },
        orderBy: { createdAt: "asc" },
    });

    // Load available Dofus items and their quests (for the drawer)
    const dofusItems = await db.dofusItem.findMany({
        include: {
            questChains: {
                include: {
                    entries: {
                        select: {
                            id: true,
                            name: true,
                            level: true,
                            zone: true,
                            stepOrder: true,
                            localImageUrl: true,
                        },
                        orderBy: { stepOrder: "asc" },
                    },
                },
                orderBy: { chainOrder: "asc" },
            },
        },
        orderBy: { displayOrder: "asc" },
    });

    return (
        <div className="h-full overflow-y-auto custom-scrollbar p-8 md:p-12 md:pt-16 space-y-12">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 border-b border-white/5 pb-10">
                <div className="space-y-4">
                    <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-xs font-black text-emerald-400 uppercase tracking-widest">
                        <Navigation className="w-4 h-4" />
                        <span>Routes Planifiées</span>
                    </div>
                    <h1 className="text-5xl md:text-7xl font-black text-white font-heading tracking-tighter leading-none">
                        Guides Optimisés <br />
                        <span className="text-transparent bg-clip-text bg-gradient-to-r from-emerald-200 via-emerald-400 to-emerald-600">
                            Constructeur de Routes
                        </span>
                    </h1>
                    <p className="text-xl md:text-2xl text-zinc-500 max-w-2xl leading-relaxed font-medium">
                        Créez des itinéraires parfaits pour les joueurs. Regroupez les quêtes de différents Dofus dans des Étapes logiques et ordonnées.
                    </p>
                </div>

                <div className="flex gap-4">
                    <div className="text-center">
                        <div className="text-2xl font-black text-emerald-400 tabular-nums">{guides.length}</div>
                        <div className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">Guides</div>
                    </div>
                </div>
            </div>

            <div className="min-h-[600px]">
                <OptimizedGuideAdminClient initialGuides={guides} dofusItems={dofusItems} />
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import {
    Search, Save, Info, Sparkles, Coins, ShieldAlert,
    ArrowLeft, Loader2, Edit3, Image as ImageIcon,
    Plus, Trash2, Map as MapIcon, SwatchBook,
    Layers, Crosshair
} from "lucide-react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";
import ReactMarkdown from "react-markdown";

import { getAllBounties } from "@/server/actions/admin-actions";
import { updateGodBountyRecord } from "@/server/actions/game-data-actions";

const REWARD_TYPES = [
    { id: "Aliton", label: "Alitons", icon: "/assets/avis/aliton.png" },
    { id: "Aviton", label: "Avitons", icon: "/assets/avis/avitons.png" },
    { id: "Kama de glace", label: "Kamas de glace", icon: "/assets/avis/kamas_de_glace.png" },
];

export default function GodBountiesPage() {
    const router = useRouter();
    const [bounties, setBounties] = useState<any[]>([]);
    const [filteredBounties, setFilteredBounties] = useState<any[]>([]);
    const [search, setSearch] = useState("");
    const [loading, setLoading] = useState(true);
    const [selectedBounty, setSelectedBounty] = useState<any>(null);
    const [saving, setSaving] = useState(false);
    const [previewMode, setPreviewMode] = useState(false);

    useEffect(() => {
        setLoading(true);
        getAllBounties().then(data => {
            setBounties(data);
            setFilteredBounties(data);
            setLoading(false);
        });
    }, []);

    useEffect(() => {
        const filtered = bounties.filter(b =>
            b.name.toLowerCase().includes(search.toLowerCase()) ||
            (b.zoneName && b.zoneName.toLowerCase().includes(search.toLowerCase()))
        );
        setFilteredBounties(filtered);
    }, [search, bounties]);

    const handleSelectBounty = (b: any) => {
        let rewards = b.rewards;
        if (!Array.isArray(rewards) || rewards.length === 0) {
            rewards = [{ type: b.rewardType || "Aliton", amount: b.doplons || 0 }];
        }
        setSelectedBounty({ ...b, rewards });
    };

    const handleSave = async () => {
        if (!selectedBounty) return;
        setSaving(true);
        try {
            const primaryReward = selectedBounty.rewards?.[0];
            const dataToSave = {
                ...selectedBounty,
                doplons: primaryReward?.amount || 0,
                rewardType: primaryReward?.type || "Aliton"
            };

            const res = await updateGodBountyRecord(selectedBounty.id, dataToSave);
            if (res.success) {
                toast.success("Avis mis à jour avec succès");
                setBounties(prev => prev.map(b => b.id === selectedBounty.id ? { ...b, ...dataToSave } : b));
            } else {
                toast.error(res.error || "Erreur lors de la sauvegarde");
            }
        } catch (e) {
            toast.error("Erreur technique lors de la sauvegarde");
        } finally {
            setSaving(false);
        }
    };

    const addReward = () => {
        const newRewards = [...(selectedBounty.rewards || []), { type: "Aliton", amount: 0 }];
        setSelectedBounty({ ...selectedBounty, rewards: newRewards });
    };

    const removeReward = (index: number) => {
        const newRewards = selectedBounty.rewards.filter((_: any, i: number) => i !== index);
        setSelectedBounty({ ...selectedBounty, rewards: newRewards });
    };

    const updateReward = (index: number, field: string, value: any) => {
        const newRewards = selectedBounty.rewards.map((r: any, i: number) =>
            i === index ? { ...r, [field]: value } : r
        );
        setSelectedBounty({ ...selectedBounty, rewards: newRewards });
    };

    if (loading) {
        return (
            <div className="flex-1 flex items-center justify-center min-h-screen bg-[#050505]">
                <div className="flex flex-col items-center gap-6">
                    <div className="relative">
                        <Loader2 className="animate-spin text-amber-500" size={48} />
                        <div className="absolute inset-0 blur-2xl bg-amber-500/20 animate-pulse" />
                    </div>
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em]">Chargement des Archives...</span>
                </div>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full bg-[#050505] overflow-hidden">
            {/* Header */}
            <header className="p-8 border-b border-white/5 flex items-center justify-between bg-black/40 backdrop-blur-2xl shrink-0 z-10">
                <div className="flex items-center gap-8">
                    <div className="flex flex-col">
                        <h1 className="text-3xl font-black text-white uppercase italic tracking-tighter flex items-center gap-4 leading-none">
                            <ShieldAlert className="text-amber-500" size={28} />
                            Avis de Recherche
                        </h1>
                        <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mt-2 ml-1">
                            Base de données tactique · {bounties.length} Records
                        </p>
                    </div>
                </div>

                <div className="relative w-96 group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600 group-focus-within:text-amber-500 transition-colors" size={18} />
                    <Input
                        placeholder="Rechercher une cible..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-12 bg-white/5 border-white/5 text-white font-bold italic h-12 rounded-2xl focus-visible:ring-amber-500/50 group-hover:bg-white/[0.07] transition-all"
                    />
                </div>
            </header>

            <div className="flex-1 flex overflow-hidden">
                {/* Bounty List */}
                <div className="w-[380px] border-r border-white/5 overflow-y-auto p-6 space-y-3 bg-black/20 shrink-0 custom-scrollbar">
                    {filteredBounties.map(b => (
                        <button
                            key={b.id}
                            onClick={() => handleSelectBounty(b)}
                            className={cn(
                                "w-full flex items-center gap-4 p-4 rounded-2xl transition-all text-left group border relative overflow-hidden",
                                selectedBounty?.id === b.id
                                    ? 'bg-amber-500/10 border-amber-500/40 shadow-[0_0_30px_rgba(245,158,11,0.05)]'
                                    : 'bg-white/[0.02] border-white/5 hover:bg-white/5 hover:border-white/10'
                            )}
                        >
                            <div className="w-14 h-14 rounded-xl bg-black/60 flex items-center justify-center overflow-hidden border border-white/10 shrink-0 group-hover:scale-105 transition-transform relative z-10">
                                {b.imageUrl ? (
                                    <img src={b.imageUrl} alt="" className="w-12 h-12 object-contain" />
                                ) : (
                                    <ShieldAlert size={24} className="text-zinc-800" />
                                )}
                            </div>
                            <div className="flex-1 min-w-0 relative z-10">
                                <p className={cn(
                                    "text-sm font-black uppercase italic truncate tracking-tight",
                                    selectedBounty?.id === b.id ? "text-amber-400" : "text-zinc-200"
                                )}>
                                    {b.name}
                                </p>
                                <p className="text-[10px] font-bold text-zinc-500 truncate mt-1 flex items-center gap-2">
                                    <MapIcon size={10} /> {b.zoneName || "Zone Inconnue"}
                                </p>
                            </div>
                            {b.mechanics && (
                                <div className="w-1 h-1 rounded-full bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.8)] relative z-10" />
                            )}
                            {selectedBounty?.id === b.id && (
                                <div className="absolute right-0 top-0 bottom-0 w-1 bg-amber-500 shadow-[0_0_20px_rgba(245,158,11,1)]" />
                            )}
                        </button>
                    ))}
                </div>

                {/* Editor Section */}
                <div className="flex-1 overflow-y-auto bg-[#080808] custom-scrollbar">
                    {selectedBounty ? (
