"use client";

import { useState, useEffect } from "react";
import { io, Socket } from "socket.io-client";
import { buildWsUrl } from "../../lib/socket-utils";
import { GamePhase, PublicPlayer } from "../../types/socket-events";

// Global connection state so we don't spam reconnections across unmounts 
// in development mode thanks to React Strict Mode
let socketInstance: Socket | null = null;

export interface GarticGameState {
    id: string;
    phase: GamePhase;
    players: (PublicPlayer & { hasSubmitted?: boolean })[];
    currentRound: number;
    maxRounds: number;
    timer: number;
    maxTimer: number;
    hostId?: string;
    task?: {
        type: "text" | "drawing";
        content: string;
    } | null;
    albums?: any[]; // The final results
}

export function useGarticSocket() {
    const [socket, setSocket] = useState<Socket | null>(socketInstance);
    const [isConnected, setIsConnected] = useState(false);
    const [gameState, setGameState] = useState<GarticGameState | null>(null);

    useEffect(() => {
        if (!socketInstance) {
            socketInstance = io(buildWsUrl(), {
                path: "/socket.io/",
            });
        }

        setSocket(socketInstance);

        const onConnect = () => setIsConnected(true);
        const onDisconnect = () => setIsConnected(false);
        const onStateUpdate = (state: GarticGameState) => {
             // For the sake of simplicity right now we just drop it into the global store
             setGameState(state);
        }

        socketInstance.on("connect", onConnect);
        socketInstance.on("disconnect", onDisconnect);
        socketInstance.on("gartic:state:update", onStateUpdate);
        socketInstance.on("gartic:reveal:ready", ({ albums }) => {
            setGameState(prev => prev ? { ...prev, albums } : null);
        });

        return () => {
             // Cleanup listeners when unmounting so we don't leak memory, 
             // but keep the connection open.
             if(socketInstance) {
                  socketInstance.off("connect", onConnect);
                  socketInstance.off("disconnect", onDisconnect);
                  socketInstance.off("gartic:state:update", onStateUpdate);
             }
        };
    }, []);

    // Helper functions for easy emittion
    const createRoom = (config: any) => socket?.emit("gartic:room:create", config);
    const joinRoom = (roomId: string, psuedo: string) => socket?.emit("gartic:room:join", { roomId, userName: psuedo });
    const startGame = () => socket?.emit("gartic:game:start");
    const leaveRoom = () => {
        socket?.emit("gartic:room:leave");
        setGameState(null);
    };
    const submitText = (text: string) => socket?.emit("gartic:text:submit", { text });
    const submitDraw = (dataUrl: string) => socket?.emit("gartic:draw:submit", { dataUrl });

    return {
        socket,
        isConnected,
        gameState,
        
        createRoom,
        joinRoom,
        startGame,
        leaveRoom,
        submitText,
        submitDraw
    };
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { Clock, Sparkles } from "lucide-react";

interface ActiveBonusBarProps {
    guildId: string;
}

interface BonusData {
    id: string;
    bonusType: string;
    status: "PURCHASED" | "ACTIVE";
    activatesAt: string;
    expiresAt?: string | null;
    purchaserName?: string;
    config: {
        name: string;
        description: string;
    };
}

// Map bonus type to icon filename
const ICON_MAP: Record<string, string> = {
    FORTUNE: "oracle_de_fortune",
    GLADIATOR: "oracle_de_gladiateur",
    HARVESTER: "oracle_de_recolteur",
    WISDOM: "oracle_de_savoir",
    DIVINE: "oracle_divin",
};

function getCountdown(bonus: BonusData) {
    const now = new Date();

    if (bonus.status === "PURCHASED") {
        const expiresAt = new Date(bonus.activatesAt); // activatesAt in DB is actually the 24h deadline
        const totalDuration = 24 * 60 * 60 * 1000;
        const timeLeft = expiresAt.getTime() - now.getTime();

        if (timeLeft <= 0) return { text: "Expiré", progress: 100 };

        const hours = Math.floor(timeLeft / (60 * 60 * 1000));
        const minutes = Math.floor((timeLeft % (60 * 60 * 1000)) / (60 * 1000));
        return {
            text: `${hours}h ${String(minutes).padStart(2, "0")}m`,
            progress: 100 - ((timeLeft / totalDuration) * 100),
        };
    }

    if (bonus.status === "ACTIVE" && bonus.expiresAt) {
        const expiresAt = new Date(bonus.expiresAt);
        const totalDuration = 2 * 60 * 60 * 1000;
        const timeLeft = expiresAt.getTime() - now.getTime();

        if (timeLeft <= 0) return { text: "Expiré", progress: 100 };

        const hours = Math.floor(timeLeft / (60 * 60 * 1000));
        const minutes = Math.floor((timeLeft % (60 * 60 * 1000)) / (60 * 1000));
        return {
            text: `${hours}h ${String(minutes).padStart(2, "0")}m`,
            progress: ((totalDuration - timeLeft) / totalDuration) * 100,
        };
    }

    return { text: "", progress: 0 };
}

function BonusBarItem({ bonus }: { bonus: BonusData }) {
    const [countdown, setCountdown] = useState(() => getCountdown(bonus));
    const isActive = bonus.status === "ACTIVE";
    const iconFile = ICON_MAP[bonus.bonusType] || "oracle_de_fortune";

    useEffect(() => {
        const interval = setInterval(() => {
            setCountdown(getCountdown(bonus));
        }, 30000); // Refresh every 30s
        return () => clearInterval(interval);
    }, [bonus]);

    return (
        <div className="flex items-center gap-3 rounded-lg border-2 px-3 py-2 transition-all border-green-500/50 bg-green-500/5">
            {/* Icon + Info */}
            <div className="flex items-center gap-2 min-w-0">
                <img
                    src={`/bonus_guilde/${iconFile}.png`}
                    alt={bonus.config.name}
                    className="w-8 h-8 rounded-full bg-slate-900/50 p-0.5 flex-shrink-0"
                    onError={(e) => {
                        e.currentTarget.src = "/bonus_guilde/oracle_de_fortune.png";
                    }}
                />
                <div className="min-w-0">
                    <div className="flex items-center gap-1.5">
                        <h4 className="font-bold text-white text-xs truncate uppercase">{bonus.config.name}</h4>
                        <Sparkles className="w-3 h-3 text-green-400 animate-pulse flex-shrink-0" />
                    </div>
                    <p className="text-[10px] text-slate-400 truncate">
                        Acheté par {bonus.purchaserName || "un membre"}
                    </p>
                </div>
            </div>

            {/* Progress Bar + Counter */}
            <div className="flex-1 min-w-[100px]">
                <div className="relative h-1.5 bg-slate-800 rounded-full overflow-hidden mb-0.5">
                    <div
                        className="h-full transition-all duration-1000 rounded-full bg-gradient-to-r from-green-500 to-emerald-400"
                        style={{ width: `${countdown.progress}%` }}
                    />
                </div>
                <div className="flex items-center justify-between text-[10px]">
                    <span className="text-green-400">
                        Expire dans
                    </span>
                    <span className="font-mono font-bold text-white">{countdown.text}</span>
                </div>
            </div>

            {/* Status Badge */}
            <div className="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase whitespace-nowrap flex-shrink-0 bg-green-500/20 text-green-400">
                ✨ DISPONIBLE
            </div>
        </div>
    );
}

export function ActiveBonusBar({ guildId }: ActiveBonusBarProps) {
    const [bonuses, setBonuses] = useState<BonusData[]>([]);

    const loadBonuses = useCallback(async () => {
        try {
            const res = await fetch(`/api/guild/${guildId}/active-bonus`);
            if (res.ok) {
                const data = await res.json();
                setBonuses(data.bonuses || []);
            }
        } catch {
            // Silently fail
        }
    }, [guildId]);

    useEffect(() => {
        loadBonuses();
        const interval = setInterval(loadBonuses, 60000);
        return () => clearInterval(interval);
    }, [loadBonuses]);

    if (bonuses.length === 0) return null;

    return (
        <div className="space-y-2">
            {bonuses.map((bonus) => (
                <BonusBarItem key={bonus.id} bonus={bonus} />
            ))}
        </div>
    );
}

"use client";

import { BonusType } from "@prisma/client";
import { Button } from "@/components/ui/button";
import { CheckCircle2, Clock } from "lucide-react";

interface BonusCardProps {
    type: BonusType;
    name: string;
    description: string;
    cost: number;
    iconPath?: string;
    isPurchased: boolean;
    isActive: boolean;
    onPurchase: () => void;
}

export function BonusCard({
    type,
    name,
    description,
    cost,
    iconPath = "/game-data/bonuses/default.png",
    isPurchased,
    isActive,
    onPurchase,
}: BonusCardProps) {
    const getTypeColor = (type: BonusType) => {
        switch (type) {
            case "FORTUNE":
                return "border-yellow-500/50 bg-yellow-500/5";
            case "GLADIATOR":
                return "border-red-500/50 bg-red-500/5";
            case "HARVESTER":
                return "border-green-500/50 bg-green-500/5";
            case "WISDOM":
                return "border-blue-500/50 bg-blue-500/5";
            case "DIVINE":
                return "border-purple-500/50 bg-purple-500/5";
            default:
                return "border-slate-700 bg-slate-800/30";
        }
    };

    const getTypeGlow = (type: BonusType) => {
        switch (type) {
            case "FORTUNE":
                return "shadow-yellow-500/20";
            case "GLADIATOR":
                return "shadow-red-500/20";
            case "HARVESTER":
                return "shadow-green-500/20";
            case "WISDOM":
                return "shadow-blue-500/20";
            case "DIVINE":
                return "shadow-purple-500/20";
            default:
                return "";
        }
    };

    return (
        <div
            className={`
                relative overflow-hidden rounded-lg border-2 p-4 transition-all
                ${getTypeColor(type)}
                ${!isPurchased && !isActive ? "hover:shadow-lg hover:scale-105 " + getTypeGlow(type) : ""}
                ${isPurchased || isActive ? "opacity-60" : ""}
            `}
        >
            {/* Status Badge */}
            {isActive && (
                <div className="absolute top-2 right-2 flex items-center gap-1 bg-green-500/20 border border-green-500/50 rounded-full px-2 py-0.5">
                    <CheckCircle2 className="w-3 h-3 text-green-400" />
                    <span className="text-xs font-bold text-green-400">ACTIF</span>
                </div>
            )}
            {isPurchased && !isActive && (
                <div className="absolute top-2 right-2 flex items-center gap-1 bg-orange-500/20 border border-orange-500/50 rounded-full px-2 py-0.5">
                    <Clock className="w-3 h-3 text-orange-400" />
                    <span className="text-xs font-bold text-orange-400">EN ATTENTE</span>
                </div>
            )}

            {/* Icon */}
            <div className="flex justify-center mb-3">
                <div className="w-16 h-16 rounded-full bg-slate-900/50 p-2 flex items-center justify-center">
                    <img src={iconPath} alt={name} className="w-full h-full object-contain" onError={(e) => {
                        e.currentTarget.src = "/game-data/bonuses/default.png";
                    }} />
                </div>
            </div>

            {/* Content */}
            <h3 className="text-lg font-bold text-white text-center mb-2">{name}</h3>
            <p className="text-sm text-slate-400 text-center mb-4 min-h-[40px]">{description}</p>

            {/* Cost & Button */}
            <div className="flex items-center justify-between gap-3">
                <div className="flex items-center gap-1">
                    <span className="text-2xl font-bold text-yellow-400">{cost}</span>
                    <span className="text-xs text-slate-400 uppercase">kamas</span>
                </div>
                <Button
                    onClick={onPurchase}
                    disabled={isPurchased || isActive}
                    size="sm"
                    className="bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50"
                >
                    {isPurchased || isActive ? "Indisponible" : "Acheter"}
                </Button>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { BonusType, MentionType } from "@prisma/client";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import {
    getActiveBonuses,
    purchaseBonus,
    cancelBonus,
    getGuildRoles,
} from "@/server/actions/bonus-actions";
import { Loader2, AlertCircle, XCircle, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";
import Image from "next/image";

interface BonusMenuButtonProps {
    guildId: string;
}

const ALL_BONUSES: Array<{
    type: BonusType;
    name: string;
    description: string;
    icon: string;
}> = [
        {
            type: BonusType.FORTUNE,
            name: "Oracle de Fortune",
            description: "+50% chances de loot sur les monstres",
            icon: "/bonus_guilde/oracle_de_fortune.png",
        },
        {
            type: BonusType.GLADIATOR,
            name: "Oracle de Gladiateur",
            description: "+50% gains en Kolizéum",
            icon: "/bonus_guilde/oracle_de_gladiateur.png",
        },
        {
            type: BonusType.HARVESTER,
            name: "Oracle de Récolteur",
            description: "Possibilité d'obtenir des Rékloots en récolte",
            icon: "/bonus_guilde/oracle_de_recolteur.png",
        },
        {
            type: BonusType.WISDOM,
            name: "Oracle de Savoir",
            description: "+50% d'expérience sur toutes les missions",
            icon: "/bonus_guilde/oracle_de_savoir.png",
        },
        {
            type: BonusType.DIVINE,
            name: "Oracle Divin",
            description: "Déclenche l'événement Moissonneuse Batteuse",
            icon: "/bonus_guilde/oracle_divin.png",
        },
    ];

export function BonusMenuButton({ guildId }: BonusMenuButtonProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [activeBonuses, setActiveBonuses] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [purchasing, setPurchasing] = useState(false);
    const [cancellingId, setCancellingId] = useState<string | null>(null);

    // Purchase form state
    const [selectedBonus, setSelectedBonus] = useState<BonusType | null>(null);
    const [publishToDiscord, setPublishToDiscord] = useState(true);
    const [mentionType, setMentionType] = useState<MentionType>(MentionType.NONE);
    const [roleId, setRoleId] = useState("");
    const [guildRoles, setGuildRoles] = useState<any[]>([]);
    const [loadingRoles, setLoadingRoles] = useState(false);

    useEffect(() => {
        loadActiveBonuses();
    }, [guildId]);

    const loadActiveBonuses = async () => {
        setLoading(true);
        try {
            const result = await getActiveBonuses(guildId);
            if (result.success) {
                setActiveBonuses(result.data || []);
            }
        } catch {
            toast.error("Erreur lors du chargement des bonus actifs");
        } finally {
            setLoading(false);
        }
    };

    // Helper: check if a specific bonus type is already active/pending
    const getBonusForType = (type: BonusType) =>
        activeBonuses.find((b) => b.bonusType === type);

    const handleBonusSelect = async (bonusType: BonusType) => {
        if (getBonusForType(bonusType)) return; // Already active for this type
        setSelectedBonus(bonusType);

        // Lazy-load Discord roles once
        if (guildRoles.length === 0) {
            setLoadingRoles(true);
            try {
                const result = await getGuildRoles(guildId);
                if (result.success && result.data) {
                    setGuildRoles(result.data);
                }
            } catch {
                // Non-blocking
            } finally {
                setLoadingRoles(false);
            }
        }
    };

    const handleCancelBonus = async (bonusId: string) => {
        setCancellingId(bonusId);
        try {
            const result = await cancelBonus(bonusId, guildId);
            if (result.success) {
                toast.success("Bonus annulé avec succès !");
                await loadActiveBonuses();
            } else {
                toast.error(result.error || "Échec de l'annulation");
            }
        } catch {
            toast.error("Erreur lors de l'annulation");
        } finally {
            setCancellingId(null);
        }
    };

    const handlePurchaseSubmit = async () => {
        if (!selectedBonus) return;

        setPurchasing(true);
        try {
            const result = await purchaseBonus(
                guildId,
                selectedBonus,
                undefined,
                publishToDiscord ? mentionType : MentionType.NONE,
                publishToDiscord && mentionType === MentionType.ROLE ? (roleId || undefined) : undefined,
            );

            if (result.success) {
                toast.success("Bonus acheté avec succès ! Il est dispo en jeu pendant 24h.");
                setSelectedBonus(null);
                setMentionType(MentionType.NONE);
                setRoleId("");
                await loadActiveBonuses();
                setIsOpen(false);
            } else {
                toast.error(result.error || "Échec de l'achat");
            }
        } catch {
            toast.error("Erreur lors de l'achat");
        } finally {
            setPurchasing(false);
        }
    };

    const hasAnyBonus = activeBonuses.length > 0;

    return (
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
            <DialogTrigger asChild>
                <Button
                    variant="outline"
                    size="sm"
                    className="gap-2 border-purple-500/50 text-purple-400 hover:bg-purple-500/10 hover:border-purple-500"
                >
                    <Sparkles className="w-4 h-4" />
                    Acheter Bonus
                </Button>
            </DialogTrigger>
            <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-0 gap-0 bg-zinc-950 border-zinc-800">
                <DialogHeader className="p-6 pb-2 border-b border-white/5">
                    <DialogTitle className="text-xl flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-purple-400" />
                        Bonus de Guilde
                    </DialogTitle>
                    <DialogDescription>
                        Achetez des bonus pour votre guilde. N'importe quel membre pourra l'activer en jeu pendant les 24h qui suivent !
                    </DialogDescription>
                </DialogHeader>

                {loading ? (
                    <div className="flex items-center justify-center py-12">
                        <Loader2 className="w-8 h-8 animate-spin text-purple-500" />
                    </div>
                ) : (
                    <div className="flex-1 overflow-hidden p-6 space-y-6">
                        {/* Active Bonuses List */}
                        {hasAnyBonus && (
                            <div className="space-y-2">
                                {activeBonuses.map((bonus) => (
                                    <div key={bonus.id} className="bg-orange-500/10 border border-orange-500/30 rounded-lg p-3 flex items-center gap-3">
                                        <AlertCircle className="w-4 h-4 text-orange-400 flex-shrink-0" />
                                        <div className="flex-1 min-w-0">
                                            <span className="text-sm font-bold text-orange-400">
                                                {bonus.config?.name || "Bonus"}
                                            </span>
                                            <span className="text-xs text-orange-300/60 ml-2">
                                                ⏳ Dispo en jeu (24h max)
                                            </span>
                                        </div>
                                        {bonus.status === "PURCHASED" && (
                                            <Button
                                                onClick={() => handleCancelBonus(bonus.id)}
                                                disabled={cancellingId === bonus.id}
                                                variant="outline"
                                                size="sm"
                                                className="border-red-500/50 text-red-400 hover:bg-red-500/10 h-7 text-xs"
                                            >
                                                {cancellingId === bonus.id ? (
                                                    <Loader2 className="w-3 h-3 animate-spin" />
                                                ) : (
                                                    <><XCircle className="w-3 h-3 mr-1" />Annuler</>
                                                )}
                                            </Button>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}

                        {/* Bonus Selection Grid */}
                        {!selectedBonus ? (
                            <ScrollArea className="h-[50vh] pr-4">
                                <div className="grid grid-cols-2 md:grid-cols-3 gap-4 pb-4">
                                    {ALL_BONUSES.map((bonus) => {
                                        const existing = getBonusForType(bonus.type);
                                        const isActive = existing?.status === "ACTIVE";
                                        const isPurchased = existing?.status === "PURCHASED";
                                        const isDisabled = !!existing; // Only block same type

                                        return (
                                            <button
                                                key={bonus.type}
                                                onClick={() => !isDisabled && handleBonusSelect(bonus.type)}
                                                disabled={isDisabled}
                                                className={cn(
                                                    "group relative flex flex-col items-center justify-center p-6 rounded-xl border-2 transition-all duration-300",
                                                    isActive && "border-green-500 bg-green-500/10 shadow-[0_0_20px_-5px_rgba(34,197,94,0.3)]",
                                                    isPurchased && "border-orange-500 bg-orange-500/10 shadow-[0_0_20px_-5px_rgba(249,115,22,0.3)]",
                                                    !isActive && !isPurchased && !isDisabled && "border-zinc-800 bg-zinc-900/30 hover:border-purple-700 hover:bg-purple-900/20",
                                                    isDisabled && !isActive && !isPurchased && "opacity-40 cursor-not-allowed border-zinc-900 bg-zinc-950"
                                                )}
                                            >
                                                <div className="mb-4 transform transition-transform group-hover:scale-110 duration-300 relative">
                                                    <Image
                                                        src={bonus.icon}
                                                        alt={bonus.name}
                                                        width={64}
                                                        height={64}
                                                        className="rounded-lg"
                                                    />
                                                </div>
                                                <span className={cn(
                                                    "text-sm font-bold text-center mb-2",
                                                    isActive && "text-green-400",
                                                    isPurchased && "text-orange-400",
                                                    !isActive && !isPurchased && "text-white"
                                                )}>
                                                    {bonus.name}
                                                </span>
                                                <p className="text-xs text-zinc-400 text-center line-clamp-2">
                                                    {bonus.description}
                                                </p>
                                                {isActive && (
                                                    <div className="absolute top-2 right-2 px-2 py-1 rounded-md bg-green-500 text-white text-[10px] font-bold uppercase">
                                                        Actif
                                                    </div>
                                                )}
                                                {isPurchased && (
                                                    <div className="absolute top-2 right-2 px-2 py-1 rounded-md bg-orange-500 text-white text-[10px] font-bold uppercase">
                                                        24h
                                                    </div>
                                                )}
                                            </button>
                                        );
                                    })}
                                </div>
                            </ScrollArea>
                        ) : (
                            /* Purchase Form */
                            <div className="space-y-4">
                                <div className="flex items-center justify-between">
                                    <h3 className="text-lg font-bold text-white">
                                        Acheter {ALL_BONUSES.find(b => b.type === selectedBonus)?.name}
                                    </h3>
                                    <Button
                                        onClick={() => setSelectedBonus(null)}
                                        variant="ghost"
                                        size="sm"
                                        className="text-zinc-400"
                                    >
                                        Retour
                                    </Button>
                                </div>

                                {/* Discord Publishing Toggle */}
                                <div className="flex items-center justify-between p-4 rounded-lg bg-zinc-900 border border-zinc-800">
                                    <div>
                                        <Label className="text-white font-semibold">Publier sur Discord</Label>
                                        <p className="text-xs text-zinc-500 mt-1">Annonce automatique dans le salon configuré dans les Paramètres</p>
                                    </div>
                                    <Switch
                                        checked={publishToDiscord}
                                        onCheckedChange={setPublishToDiscord}
                                    />
                                </div>

                                {/* Mention Type - Only if Discord publishing is ON */}
                                {publishToDiscord && (
                                    <div>
                                        <Label className="text-white">Mentionner</Label>
                                        <div className="mt-2 space-y-2">
                                            <label className="flex items-center gap-2 cursor-pointer">
                                                <input
                                                    type="radio"
                                                    name="mention"
                                                    checked={mentionType === MentionType.NONE}
                                                    onChange={() => {
                                                        setMentionType(MentionType.NONE);
                                                        setRoleId("");
                                                    }}
                                                    className="text-purple-500"
                                                />
                                                <span className="text-white">Personne</span>
                                            </label>
                                            <label className="flex items-center gap-2 cursor-pointer">
                                                <input
                                                    type="radio"
                                                    name="mention"
                                                    checked={mentionType === MentionType.EVERYONE}
                                                    onChange={() => {
                                                        setMentionType(MentionType.EVERYONE);
                                                        setRoleId("");
                                                    }}
                                                    className="text-purple-500"
                                                />
                                                <span className="text-white">@everyone</span>
                                            </label>
                                            <label className="flex items-center gap-2 cursor-pointer">
                                                <input
                                                    type="radio"
                                                    name="mention"
                                                    checked={mentionType === MentionType.ROLE}
                                                    onChange={() => setMentionType(MentionType.ROLE)}
                                                    className="text-purple-500"
                                                />
                                                <span className="text-white">Un rôle spécifique</span>
                                            </label>
                                        </div>
                                    </div>
                                )}

                                {/* Role Dropdown - Only if ROLE mention type + Discord publishing */}
                                {publishToDiscord && mentionType === MentionType.ROLE && (
                                    <div>
                                        <Label className="text-white">Rôle à mentionner</Label>
                                        {loadingRoles ? (
                                            <div className="flex items-center gap-2 mt-2 p-3 rounded-md bg-zinc-800 text-zinc-400">
                                                <Loader2 className="w-4 h-4 animate-spin" />
                                                Chargement des rôles...
                                            </div>
                                        ) : (
                                            <select
                                                value={roleId}
                                                onChange={(e) => setRoleId(e.target.value)}
                                                className="w-full mt-2 px-4 py-2 bg-zinc-800 border border-zinc-700 rounded-md text-white focus:ring-2 focus:ring-purple-500 outline-none"
                                            >
                                                <option value="">Sélectionnez un rôle</option>
                                                {guildRoles.map(role => (
                                                    <option key={role.id} value={role.id}>
                                                        {role.name}
                                                    </option>
                                                ))}
                                            </select>
                                        )}
                                    </div>
                                )}

                                {/* Actions */}
                                <div className="flex gap-3 pt-2">
                                    <Button
                                        onClick={() => setSelectedBonus(null)}
                                        disabled={purchasing}
                                        variant="outline"
                                        className="flex-1"
                                    >
                                        Annuler
                                    </Button>
                                    <Button
                                        onClick={handlePurchaseSubmit}
                                        disabled={purchasing}
                                        className="flex-1 bg-purple-600 hover:bg-purple-700"
                                    >
                                        {purchasing ? (
                                            <>
                                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                                Achat...
                                            </>
                                        ) : (
                                            "Confirmer l'achat"
                                        )}
                                    </Button>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    getChallenges,
    createChallenge,
    updateChallenge,
    deleteChallenge,
} from "@/server/actions/game-data-admin-actions";
import { Trophy, Trash2, Edit2, Plus, Search, MoreHorizontal, ImageIcon } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { ImageDownloader } from "./ImageDownloader";
import { LocalImagePicker } from "./LocalImagePicker";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { motion } from "framer-motion";

interface Challenge {
    id: string;
    name: string;
    slug: string;
    description?: string | null;
    iconUrl?: string | null;
    _count?: { dungeonAchievements: number };
}

export default function ChallengeManager() {
    const [challenges, setChallenges] = useState<Challenge[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");

    const [formData, setFormData] = useState({
        name: "",
        slug: "",
        description: "",
        iconUrl: "",
    });

    useEffect(() => {
        loadChallenges();
    }, []);

    async function loadChallenges() {
        setLoading(true);
        const result = await getChallenges();
        if (result.success && result.data) {
            setChallenges(result.data);
        }
        setLoading(false);
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();
        const result = editing
            ? await updateChallenge(editing, formData)
            : await createChallenge(formData);

        if (result.success) {
            toast.success(editing ? "Challenge mis à jour" : "Challenge créé");
            resetForm();
            setIsDialogOpen(false);
            loadChallenges();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Supprimer ce challenge ?")) return;
        const result = await deleteChallenge(id);
        if (result.success) {
            toast.success("Challenge supprimé");
            loadChallenges();
        }
    }

    function resetForm() {
        setFormData({ name: "", slug: "", description: "", iconUrl: "" });
        setEditing(null);
    }

    function startEdit(challenge: Challenge) {
        setEditing(challenge.id);
        setFormData({
            name: challenge.name,
            slug: challenge.slug,
            description: challenge.description || "",
            iconUrl: challenge.iconUrl || "",
        });
        setIsDialogOpen(true);
    }

    const filteredChallenges = challenges.filter(c =>
        c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.slug.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center gap-4 bg-slate-900/50 p-4 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <Input
                        placeholder="Rechercher un challenge..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500 focus:ring-indigo-500/50"
                    />
                </div>
                <Button
                    onClick={() => { resetForm(); setIsDialogOpen(true); }}
                    className="w-full md:w-auto bg-indigo-600 hover:bg-indigo-700 shadow-lg shadow-indigo-900/20 transition-all font-medium"
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nouveau Challenge
                </Button>
            </div>

            {/* Grid List */}
            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement des challenges...</div>
            ) : filteredChallenges.length === 0 ? (
                <div className="p-12 text-center text-slate-500 bg-slate-900/30 rounded-lg border border-dashed border-slate-700">
                    Aucun challenge trouvé
                </div>
            ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                    {filteredChallenges.map((challenge) => (
                        <div
                            key={challenge.id}
                            className="group relative bg-slate-900/40 border border-slate-800 rounded-xl p-4 hover:border-indigo-500/30 hover:shadow-lg hover:shadow-indigo-900/10 transition-all duration-300"
                        >
                            <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon" className="h-6 w-6 bg-slate-950/80 hover:bg-slate-800 text-slate-400">
                                            <MoreHorizontal className="w-3 h-3" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                        <DropdownMenuItem onClick={() => startEdit(challenge)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                            <Edit2 className="w-3 h-3 mr-2 text-indigo-400" /> Modifier
                                        </DropdownMenuItem>
                                        <DropdownMenuItem onClick={() => handleDelete(challenge.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                            <Trash2 className="w-3 h-3 mr-2" /> Supprimer
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </div>

                            <div className="flex flex-col items-center text-center gap-3">
                                <div className="w-12 h-12 rounded-lg bg-slate-800 border border-slate-700 flex items-center justify-center p-1 group-hover:border-indigo-500/50 transition-colors">
                                    {challenge.iconUrl ? (
                                        <img src={challenge.iconUrl} alt={challenge.name} className="w-full h-full object-contain" />
                                    ) : (
                                        <Trophy className="w-6 h-6 text-slate-600" />
                                    )}
                                </div>

                                <div className="space-y-1 w-full">
                                    <h4 className="font-semibold text-slate-200 text-sm truncate" title={challenge.name}>{challenge.name}</h4>
                                    <div className="text-[10px] text-slate-500 font-mono truncate bg-slate-950/50 rounded px-1.5 py-0.5 mx-auto w-max max-w-full">
                                        {challenge.slug}
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Form Dialog */}
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent draggable className="w-[95vw] max-w-7xl max-h-[95vh] bg-slate-950 border-slate-800 p-0 overflow-hidden shadow-2xl flex flex-col h-full">
                    {/* Header Draggable */}
                    <div className="p-8 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between shrink-0">
                        <DialogHeader>
                            <DialogTitle className="text-3xl font-black text-white flex items-center gap-4">
                                <Trophy className="w-8 h-8 text-indigo-500" />
                                {editing ? "Modifier le challenge" : "Nouveau challenge"}
                            </DialogTitle>
                            <DialogDescription className="text-slate-400 text-lg">
                                Configurez les détails du challenge et son icône représentative.
                            </DialogDescription>
                        </DialogHeader>
                    </div>

                    <div className="p-10 overflow-y-auto flex-1 custom-scrollbar">
                        <form onSubmit={handleSubmit} className="space-y-10 pb-6">
                            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                                {/* Left Column: Info */}
                                <div className="lg:col-span-7 space-y-10">
                                    <div className="space-y-8 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50">
                                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-2">Configuration du Challenge</h3>

                                        <div className="space-y-6">
                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Nom du Challenge <span className="text-rose-500 text-lg">*</span></label>
                                                <Input
                                                    value={formData.name}
                                                    onChange={(e) => {
                                                        const name = e.target.value;
                                                        if (!editing) {
                                                            const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
                                                            setFormData({ ...formData, name, slug });
                                                        } else {
                                                            setFormData({ ...formData, name });
                                                        }
                                                    }}
                                                    required
                                                    placeholder="Ex: Misanthrope"
                                                    className="h-16 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                                />
                                            </div>

                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Identifiant (Slug)</label>
                                                <Input
                                                    value={formData.slug}
                                                    readOnly={!!editing}
                                                    onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                                                    placeholder="identifiant-unique"
                                                    className={`h-12 bg-slate-950/50 border-slate-800 text-slate-500 font-mono text-sm rounded-xl ${editing ? 'opacity-50 cursor-not-allowed' : ''}`}
                                                />
                                            </div>

                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Description</label>
                                                <textarea
                                                    value={formData.description || ""}
                                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                                    rows={4}
                                                    placeholder="Expliquez les conditions de réussite du challenge..."
                                                    className="w-full px-5 py-4 bg-slate-950 border border-slate-800 rounded-2xl text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500/50 resize-none text-lg transition-all"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* Right Column: Icon */}
                                <div className="lg:col-span-5 space-y-8">
                                    <div className="bg-slate-950/50 p-8 rounded-3xl border border-slate-800 shadow-inner flex flex-col h-full">
                                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-6">Icône du Challenge</h3>

                                        <ImageDownloader
                                            type="achievement"
                                            imageUrl={formData.iconUrl}
                                            identifier={formData.name || formData.slug}
                                            onImageDownloaded={(path) => setFormData({ ...formData, iconUrl: path })}
                                            className="w-full"
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-4 pt-6 border-t border-slate-800 sticky bottom-0 bg-slate-950 py-4 shrink-0">
                                <Button type="submit" className="flex-[3] bg-indigo-600 hover:bg-indigo-500 h-14 text-lg font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 transition-all rounded-xl active:scale-[0.98]">
                                    {editing ? "💾 Enregistrer" : "➕ Créer le Challenge"}
                                </Button>
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => setIsDialogOpen(false)}
                                    className="flex-1 h-14 border-white/10 hover:bg-white/5 text-slate-300 text-sm font-bold uppercase tracking-widest transition-all rounded-xl"
                                >
                                    Fermer
                                </Button>
                            </div>
                        </form>
                    </div>
                </DialogContent>
            </Dialog>

        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { exportGameData, importGameData, exportGameDataToGit } from "@/server/actions/game-data-admin-actions";

export default function DataExportImport() {
    const [exporting, setExporting] = useState(false);
    const [exportingGit, setExportingGit] = useState(false);
    const [importing, setImporting] = useState(false);

    async function handleExport() {
        setExporting(true);
        const result = await exportGameData();

        if (result.success && result.data) {
            const blob = new Blob([JSON.stringify(result.data, null, 2)], {
                type: "application/json",
            });
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `game-data-backup-${new Date().toISOString().split("T")[0]}.json`;
            a.click();
            URL.revokeObjectURL(url);
            toast.success("Export réussi");
        } else {
            toast.error(result.error || "Erreur d'export");
        }

        setExporting(false);
    }

    async function handleExportToGit() {
        setExportingGit(true);
        const result = await exportGameDataToGit();

        if (result.success) {
            toast.success(result.data || "Export Git réussi", { duration: 5000 });
        } else {
            toast.error(result.error || "Erreur d'export Git");
        }

        setExportingGit(false);
    }

    async function handleImport(e: React.ChangeEvent<HTMLInputElement>) {
        const file = e.target.files?.[0];
        if (!file) return;

        setImporting(true);

        try {
            const text = await file.text();
            const result = await importGameData(text);

            if (result.success) {
                toast.success(result.data || "Import réussi");
            } else {
                toast.error(result.error || "Erreur d'import");
            }
        } catch (error) {
            toast.error("Fichier invalide");
        }

        setImporting(false);
        e.target.value = "";
    }

    return (
        <div className="space-y-6">
            <div className="bg-gradient-to-r from-indigo-600/20 to-purple-600/20 p-6 rounded-lg border border-indigo-500/30">
                <h3 className="text-lg font-semibold text-white mb-2">📦 Export / Import</h3>
                <p className="text-sm text-slate-300">
                    Utilisez ces fonctions pour synchroniser les données entre environnements (local → beta → prod)
                </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Export */}
                <div className="bg-slate-800/30 p-6 rounded-lg border border-slate-700/30 space-y-4">
                    <div>
                        <h4 className="font-semibold text-white mb-2">📤 Export</h4>
                        <p className="text-sm text-slate-400 mb-4">
                            Télécharger toutes les données (familles, challenges, donjons) en JSON
                        </p>
                    </div>

                    <Button
                        onClick={handleExport}
                        disabled={exporting}
                        className="w-full bg-indigo-600 hover:bg-indigo-700"
                    >
                        {exporting ? "⏳ Export en cours..." : "📥 Télécharger l'export JSON"}
                    </Button>

                    <div className="text-xs text-slate-500 space-y-1">
                        <p>✅ Inclut toutes les familles de monstres</p>
                        <p>✅ Inclut tous les challenges</p>
                        <p>✅ Inclut tous les donjons + succès associés</p>
                    </div>
                </div>

                {/* Export to Git (Development Only) */}
                <div className="bg-gradient-to-br from-green-900/20 to-emerald-900/20 p-6 rounded-lg border border-green-500/30 space-y-4">
                    <div>
                        <h4 className="font-semibold text-white mb-2 flex items-center gap-2">
                            🌱 Export vers Git
                            <span className="text-xs bg-green-600 px-2 py-0.5 rounded-full">DEV ONLY</span>
                        </h4>
                        <p className="text-sm text-slate-400 mb-4">
                            Sauvegarder directement dans <code className="px-1.5 py-0.5 bg-slate-900 rounded text-green-400">prisma/seed-data/game-data.json</code>
                        </p>
                    </div>

                    <Button
                        onClick={handleExportToGit}
                        disabled={exportingGit}
                        className="w-full bg-green-600 hover:bg-green-700"
                    >
                        {exportingGit ? "⏳ Export en cours..." : "📦 Sauvegarder dans Git"}
                    </Button>

                    <div className="text-xs text-green-400/80 space-y-1">
                        <p>✅ Sauvegarde dans le fichier de seed</p>
                        <p>✅ Prêt pour commit Git</p>
                        <p>✅ Auto-deployed via deploy.sh</p>
                    </div>
                </div>

                {/* Import */}
                <div className="bg-slate-800/30 p-6 rounded-lg border border-slate-700/30 space-y-4">
                    <div>
                        <h4 className="font-semibold text-white mb-2">📥 Import</h4>
                        <p className="text-sm text-slate-400 mb-4">
                            Importer des données depuis un fichier JSON (upsert)
                        </p>
                    </div>

                    <label className="block">
                        <input
                            type="file"
                            accept=".json"
                            onChange={handleImport}
                            disabled={importing}
                            className="hidden"
                            id="import-file"
                        />
                        <Button
                            onClick={() => document.getElementById("import-file")?.click()}
                            disabled={importing}
                            className="w-full bg-purple-600 hover:bg-purple-700"
                            type="button"
                        >
                            {importing ? "⏳ Import en cours..." : "📤 Choisir un fichier JSON"}
                        </Button>
                    </label>

                    <div className="text-xs text-orange-400/80 space-y-1">
                        <p>⚠️ Les données existantes seront mises à jour (upsert)</p>
                        <p>⚠️ Pas de suppression, seulement ajout/modification</p>
                    </div>
                </div>
            </div>

            {/* Instructions */}
            <div className="bg-slate-800/30 p-6 rounded-lg border border-slate-700/30">
                <h4 className="font-semibold text-white mb-3">🔄 Workflow Local → Beta → Prod</h4>
                <ol className="space-y-2 text-sm text-slate-300">
                    <li>
                        <span className="inline-block w-6 text-indigo-400">1.</span>
                        Saisir les données en local via cette interface
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">2.</span>
                        Exporter le JSON en local
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">3.</span>
                        Déployer le code sur beta (<code className="px-2 py-1 bg-slate-900 rounded">./scripts/deploy.sh beta</code>)
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">4.</span>
                        Importer le JSON sur <code className="px-2 py-1 bg-slate-900 rounded">beta.sigilos.fr/god/game-data</code>
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">5.</span>
                        Tester sur beta, puis merger vers main
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">6.</span>
                        Déployer sur prod et importer le même JSON
                    </li>
                </ol>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { getDofusHealthReport, compileDofusChain, compileAllDofus } from "@/server/actions/dofus-quest-admin-actions";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { 
    Activity, AlertCircle, CheckCircle2, 
    RefreshCw, ImageOff, Link2, Search, Zap
} from "lucide-react";
import { toast } from "sonner";

export default function DofusHealthChecker() {
    const [report, setReport] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [compiling, setCompiling] = useState<string | null>(null);
    const [isBulkCompiling, setIsBulkCompiling] = useState(false);

    const loadReport = async () => {
        setLoading(true);
        const res = await getDofusHealthReport();
        if (res.success && res.data) {
            setReport(res.data);
        }
        setLoading(false);
    };

    useEffect(() => { loadReport(); }, []);

    const handleCompile = async (slug: string) => {
        setCompiling(slug);
        const res = await compileDofusChain(slug);
        if (res.success) {
            toast.success(`Compilation de ${slug} terminée`);
            loadReport();
        } else {
            toast.error(res.error);
        }
        setCompiling(null);
    };

    const handleBulkCompile = async () => {
        if (!confirm("Attention : Cela va re-compiler TOUS les Dofus (26+). Temps estimé: 1-2 min. Continuer ?")) return;
        setIsBulkCompiling(true);
        const res = await compileAllDofus();
        if (res.success) {
            toast.success("Toute la matrice a été re-compilée.");
            loadReport();
        } else {
            toast.error(res.error);
        }
        setIsBulkCompiling(false);
    };

    const emptyCount = report.filter(d => d.status === "EMPTY").length;
    const criticalCount = report.filter(d => d.status === "CRITICAL").length;

    return (
        <div className="space-y-8 animate-in fade-in duration-700">
            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-zinc-950/40 backdrop-blur-xl border border-white/5 p-6 rounded-3xl flex items-center justify-between">
                    <div>
                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-1">Dofus Opérationnels</p>
                        <h4 className="text-3xl font-black text-white italic">{report.length - emptyCount - criticalCount}</h4>
                    </div>
                    <div className="w-12 h-12 rounded-2xl bg-emerald-500/10 flex items-center justify-center text-emerald-400">
                        <CheckCircle2 className="w-6 h-6" />
                    </div>
                </div>
                <div className="bg-zinc-950/40 backdrop-blur-xl border border-white/5 p-6 rounded-3xl flex items-center justify-between">
                    <div>
                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-1">Vides (0 Quêtes)</p>
                        <h4 className="text-3xl font-black text-amber-500 italic">{emptyCount}</h4>
                    </div>
                    <div className="w-12 h-12 rounded-2xl bg-amber-500/10 flex items-center justify-center text-amber-500">
                        <Search className="w-6 h-6" />
                    </div>
                </div>
                <div className="bg-zinc-950/40 backdrop-blur-xl border border-white/5 p-6 rounded-3xl flex items-center justify-between shadow-[0_0_50px_rgba(239,68,68,0.1)]">
                    <div>
                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-1">Données Critiques</p>
                        <h4 className="text-3xl font-black text-rose-500 italic">{criticalCount}</h4>
                    </div>
                    <div className="w-12 h-12 rounded-2xl bg-rose-500/10 flex items-center justify-center text-rose-500">
                        <AlertCircle className="w-6 h-6" />
                    </div>
                </div>
            </div>

            {/* Detailed Table */}
            <div className="bg-zinc-950/40 backdrop-blur-xl border border-white/5 rounded-3xl overflow-hidden">
                <div className="p-6 border-b border-white/5 bg-zinc-900/20 flex items-center justify-between">
                    <h3 className="text-sm font-black text-white uppercase tracking-widest italic flex items-center gap-2">
                        <Activity className="w-4 h-4 text-indigo-400" />
                        Rapport de Santé
                    </h3>
                    <div className="flex items-center gap-3">
                        <Button 
                            onClick={handleBulkCompile} 
                            size="sm" 
                            variant="outline" 
                            disabled={isBulkCompiling}
                            className="bg-indigo-500/10 border-indigo-500/20 text-indigo-400 hover:bg-indigo-500/20 rounded-xl h-9"
                        >
                            <Zap className={`w-4 h-4 mr-2 ${isBulkCompiling ? 'animate-pulse' : ''}`} />
                            {isBulkCompiling ? 'Compilation...' : 'Re-Seed All'}
                        </Button>
                        <Button 
                            onClick={loadReport} 
                            size="sm" 
                            variant="outline" 
                            className="bg-black/40 border-white/5 text-zinc-400 hover:text-white rounded-xl h-9"
                        >
                            <RefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                            Rafraîchir
                        </Button>
                    </div>

                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-black/20">
                                <th className="p-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">Dofus</th>
                                <th className="p-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">État</th>
                                <th className="p-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">Contenu</th>
                                <th className="p-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">Image</th>
                                <th className="p-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {report.sort((a, b) => b.totalQuests === 0 ? 1 : -1).map((dofus) => (
                                <tr key={dofus.id} className="hover:bg-white/[0.02] transition-colors group">
                                    <td className="p-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-zinc-950 border border-white/5 p-1">
                                                <img src={dofus.imageUrl} alt="" className="w-full h-full object-contain" />
                                            </div>
                                            <div>
                                                <div className="text-sm font-black text-white">{dofus.name}</div>
                                                <div className="text-[10px] text-zinc-600 uppercase font-bold tracking-widest">{dofus.slug}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="p-4">
                                        {dofus.status === "EMPTY" ? (
                                            <Badge className="bg-amber-500/10 text-amber-500 border-amber-500/20 uppercase font-black text-[9px]">Vide</Badge>
                                        ) : dofus.status === "CRITICAL" ? (
                                            <Badge className="bg-rose-500/10 text-rose-500 border-rose-500/20 uppercase font-black text-[9px]">Critique</Badge>
                                        ) : (
                                            <Badge className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20 uppercase font-black text-[9px]">OK</Badge>
                                        )}
                                    </td>
                                    <td className="p-4">
                                        <div className="text-xs font-bold text-zinc-400">
                                            {dofus.chainsCount} sections • {dofus.totalQuests} quêtes
                                        </div>
                                    </td>
                                    <td className="p-4">
                                        {dofus.imageUrl?.includes("api.dofusdb.fr") ? (
                                            <div className="flex items-center gap-2 text-rose-500 text-[10px] font-bold uppercase">
                                                <ImageOff className="w-3 h-3" /> URL Morte
                                            </div>
                                        ) : !dofus.imageUrl ? (
                                            <div className="flex items-center gap-2 text-zinc-600 text-[10px] font-bold uppercase">
                                                Manquante
                                            </div>
                                        ) : (
                                            <div className="flex items-center gap-2 text-zinc-400 text-[10px] font-bold uppercase">
                                                <Link2 className="w-3 h-3" /> OK
                                            </div>
                                        )}
                                    </td>
                                    <td className="p-4 text-right">
                                        <Button 
                                            size="sm" 
                                            variant="ghost" 
                                            disabled={compiling === dofus.slug}
                                            onClick={() => handleCompile(dofus.slug)}
                                            className="h-8 text-[10px] font-black uppercase bg-indigo-500/10 text-indigo-400 hover:bg-indigo-500/20 rounded-lg"
                                        >
                                            {compiling === dofus.slug ? 'Compiles...' : 'Re-Seed'}
                                        </Button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useParams } from "next/navigation";
import { 
