                                            <Skull className="w-4 h-4" />
                                            <span className="text-[11px] font-black uppercase tracking-[0.1em] tabular-nums">
                                                {(() => {
                                                    const djs = (dofus.chains || []).flatMap(c => (c.entries || []).flatMap(e => (e.dungeonsRequired ?? []) as any[]));
