    type GuildatonSettings 
} from "@/server/actions/guildaton-actions";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { Bell, History, BarChart3 } from "lucide-react";

interface GuildatonManagementProps {
    guildId: string;
}

export function GuildatonManagement({ guildId }: GuildatonManagementProps) {
    const [loading, setLoading] = useState(true);
    const [mounted, setMounted] = useState(false);
    const [sending, setSending] = useState(false);
    const [validating, setValidating] = useState(false);
    const [data, setData] = useState<{ 
        members: GuildatonMember[], 
        history: any[],
        settings?: GuildatonSettings,
        availableRoles?: { id: string, name: string, color: number }[],
        availableChannels?: { id: string, name: string }[]
    }>({ members: [], history: [] });
    const [search, setSearch] = useState("");
    const [roleFilter, setRoleFilter] = useState("ALL");
    const [importOpen, setImportOpen] = useState(false);
    const [manualOpen, setManualOpen] = useState(false);
    const [importData, setImportData] = useState<any[]>([]);

    // Manual Form
    const [manualForm, setManualForm] = useState({
        discordId: "",
        username: "",
        ankamaId: "",
        value: 0
    });

    const fetchData = async () => {
        setLoading(true);
        const res = await getGuildatonData(guildId);
        if (res.success && res.data) {
            setData(res.data);
        } else {
            toast.error(res.error || "Erreur de chargement");
        }
        setLoading(false);
    };

    useEffect(() => {
        setMounted(true);
        fetchData();
    }, [guildId]);

    const filteredMembers = useMemo(() => {
        return data.members.filter(m => {
            const matchSearch = m.displayName.toLowerCase().includes(search.toLowerCase()) || 
                                m.discordId.includes(search) ||
                                (m.ankamaId && m.ankamaId.toLowerCase().includes(search.toLowerCase()));
            const matchRole = roleFilter === "ALL" || m.discordRoleName === roleFilter;
            return matchSearch && matchRole;
        });
    }, [data.members, search, roleFilter]);

    const refreshData = () => fetchData();

    const handleValidateWeek = async () => {
        if (!confirm("Voulez-vous valider la semaine en cours ? Cela créera un point d'historique pour tous les membres pour permettre de voir leur évolution.")) return;
        
        setValidating(true);
        const res = await validateWeeklyGuildaton(guildId);
        setValidating(false);
        
        if (res.success) {
            toast.success("Semaine validée !");
            fetchData();
        } else {
            toast.error(res.error || "Erreur lors de la validation");
        }
    };

    const handleSendReminder = async () => {
        setSending(true);
        const res = await sendManualGuildatonReport(guildId);
        setSending(false);
        if (res.success) {
            toast.success("Rapport Discord envoyé !");
        } else {
            toast.error(res.error || "Erreur lors de l'envoi");
        }
    };

    const handleUpdateValue = async (m: GuildatonMember, newValue: number) => {
        const val = Math.min(Math.max(0, newValue), 999999);
        if (val === m.currentValue) return;

        try {
            const res = await updateGuildatonValue(guildId, {
                discordId: m.discordId,
                value: val,
                username: m.displayName,
                ankamaId: m.ankamaId || undefined
            });

            if (res.success) {
                toast.success(`Guildaton mis à jour pour ${m.displayName}`);
                // Optimistic update
                setData(prev => ({
                    ...prev,
                    members: prev.members.map(member => 
                        member.discordId === m.discordId ? { ...member, currentValue: val } : member
                    )
                }));
            } else {
                toast.error(res.error);
            }
        } catch (error) {
            toast.error("Erreur de connexion");
        }
    };

    const handleCsvImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const text = event.target?.result as string;
            const allRows = text.split(/\r?\n/).map(r => r.trim()).filter(r => r.length > 2);
            if (allRows.length === 0) {
                toast.error("Le fichier semble vide.");
                return;
            }

            // Universal Parser: Try to find a number and a name in each line regardless of separator
            const parsed = allRows.map((line) => {
                // Try common separators
                const parts = line.split(/[;,\t|]/).map(p => p.trim().replace(/"/g, ''));
                
                let name = "";
                let score = 0;
                let discordId = "";

                if (parts.length >= 2) {
                    // Search for a part that is purely numeric or ends with common suffixes
                    const scoreIdx = parts.findIndex(p => /^\d+$/.test(p.replace(/[^\d]/g, '')));
                    if (scoreIdx !== -1) {
                        score = parseInt(parts[scoreIdx].replace(/[^\d]/g, '')) || 0;
                        // The rest is probably the name
                        name = parts.filter((_, i) => i !== scoreIdx).join(" ").trim();
                    } else {
                        // Fallback: first col name, second col score
                        name = parts[0];
                        score = parseInt(parts[1].replace(/[^\d]/g, '')) || 0;
                    }
                } else {
                    // Single column case: search for number at the end or beginning
                    const matches = line.match(/(\d+)/);
                    if (matches) {
                        score = parseInt(matches[0]);
                        name = line.replace(matches[0], "").trim().replace(/^[:\s-]+|[:\s-]+$/g, "");
                    }
                }

                // If name is a snowflake, use it as discordId
                if (/^\d{17,20}$/.test(name)) {
                    discordId = name;
                } else {
                    discordId = name; // Server will fuzzy match
                }

                return { 
                    discordId: discordId || name, 
                    value: score, 
                    username: name || "Membre", 
                    ankamaId: "" 
                };
            }).filter(r => r.username && r.username.length > 1 && !r.username.toLowerCase().includes("pseudo") && !r.username.toLowerCase().includes("name"));

            if (parsed.length === 0) {
                toast.error("Format de données non reconnu (Pseudo + Points attendus).");
            } else {
                setImportData(parsed);
                toast.success(`${parsed.length} membres détectés.`);
            }
        };
        reader.onerror = () => toast.error("Erreur lors de la lecture du fichier.");
        reader.readAsText(file);
        e.target.value = '';
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        const file = e.dataTransfer.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const text = event.target?.result as string;
            const allRows = text.split(/\r?\n/).map(r => r.trim()).filter(r => r.length > 2);
            if (allRows.length === 0) {
                toast.error("Le fichier semble vide.");
                return;
            }

            const parsed = allRows.map((line) => {
                const parts = line.split(/[;,\t|]/).map(p => p.trim().replace(/"/g, ''));
                let name = "";
                let score = 0;
                let discordId = "";

                if (parts.length >= 2) {
                    const scoreIdx = parts.findIndex(p => /^\d+$/.test(p.replace(/[^\d]/g, '')));
                    if (scoreIdx !== -1) {
                        score = parseInt(parts[scoreIdx].replace(/[^\d]/g, '')) || 0;
                        name = parts.filter((_, i) => i !== scoreIdx).join(" ").trim();
                    } else {
                        name = parts[0];
                        score = parseInt(parts[1].replace(/[^\d]/g, '')) || 0;
                    }
                } else {
                    const matches = line.match(/(\d+)/);
                    if (matches) {
                        score = parseInt(matches[0]);
                        name = line.replace(matches[0], "").trim().replace(/^[:\s-]+|[:\s-]+$/g, "");
                    }
                }

                if (/^\d{17,20}$/.test(name)) {
                    discordId = name;
                } else {
                    discordId = name;
                }

                return { 
                    discordId: discordId || name, 
                    value: score, 
                    username: name || "Membre", 
                    ankamaId: "" 
                };
            }).filter(r => r.username && r.username.length > 1 && !r.username.toLowerCase().includes("pseudo") && !r.username.toLowerCase().includes("name"));

            if (parsed.length === 0) {
                toast.error("Format de données non reconnu (Pseudo + Points attendus).");
            } else {
                setImportData(parsed);
                toast.success(`${parsed.length} membres détectés.`);
            }
        };
        reader.readAsText(file);
    };

    const confirmImport = async () => {
        if (importData.length === 0) return;
        setSending(true);
        const res = await importGuildatonCsv(guildId, importData);
        if (res.success) {
            toast.success(`${importData.length} records importés avec succès`);
            setImportOpen(false);
            fetchData();
        } else {
            toast.error(res.error);
        }
        setSending(false);
    };

    const handleManualAdd = async () => {
        if (!manualForm.discordId && !manualForm.username) return toast.error("Discord ID ou Pseudo obligatoire");
        // Auto convert to manual_id if no ID is passed but a Username is passed.
        const idToLog = manualForm.discordId || `manual_${manualForm.username.toLowerCase().replace(/\s+/g, "_")}`;
        
        setSending(true);
        const res = await updateGuildatonValue(guildId, { ...manualForm, discordId: idToLog });
        if (res.success) {
            toast.success("Membre ajouté");
            setManualOpen(false);
            fetchData();
            setManualForm({ discordId: "", username: "", ankamaId: "", value: 0 });
        } else {
            toast.error(res.error);
        }
        setSending(false);
    };


    const handleDeleteRecord = async (discordId: string) => {
        if (!confirm("Supprimer ce membre du Guildaton ? Les points et l'historique seront effacés.")) return;
        
        setLoading(true);
        try {
            const res = await deleteGuildatonRecord(guildId, discordId);
            if (res.success) {
                toast.success("Enregistrement supprimé");
                fetchData();
            } else {
                toast.error(res.error);
                setLoading(false);
            }
        } catch (error) {
            toast.error("Erreur de connexion");
            setLoading(false);
        }
    };


    // Graph Data processing
    const graphData = useMemo(() => {
        const daily = new Map();
        data.history.forEach(h => {
            const date = format(new Date(h.createdAt), "dd/MM");
            daily.set(date, (daily.get(date) || 0) + h.value);
        });

        // Current month evolution
        return Array.from(daily.entries()).map(([date, value]) => ({
            date,
            total: value
        })).slice(-15);
    }, [data.history]);

    const totalGuildatons = data.members.reduce((acc, m) => acc + m.currentValue, 0);
    const avgGuildaton = data.members.length > 0 ? Math.round(totalGuildatons / data.members.length) : 0;

    return (
        <div className="space-y-8 pb-10">
            {/* --- ANALYTICS SECTION --- */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
                <Card className="bg-zinc-900/40 border-white/5 backdrop-blur-xl rounded-[24px] overflow-hidden p-6 relative group">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-violet-600/10 blur-[40px] rounded-full translate-x-12 -translate-y-12" />
                    <div className="flex items-center gap-3 mb-4">
                        <div className="p-2.5 bg-violet-600/10 rounded-xl">
                            <img src="/guildaton.png" alt="Guildaton" className="w-5 h-5 object-contain" />
                        </div>
                        <span className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em]">Total Guilde</span>
                    </div>
                    <div className="flex items-end gap-2">
                        <span className="text-4xl font-black text-white">{totalGuildatons.toLocaleString()}</span>
                        <span className="text-[10px] font-black text-violet-500 mb-2 uppercase italic font-black">Points</span>
                    </div>
                    <p className="text-[10px] text-zinc-500 font-bold mt-2 uppercase tracking-widest italic opacity-60">Volume cumulé des membres</p>
                </Card>

                <Card className="bg-zinc-900/40 border-white/5 backdrop-blur-xl rounded-[24px] p-6 relative group">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="p-2.5 bg-emerald-600/20 rounded-xl">
                            <TrendingUp className="w-5 h-5 text-emerald-400" />
                        </div>
                        <span className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em]">Moyenne</span>
                    </div>
                    <div className="flex items-end gap-2">
                        <span className="text-4xl font-black text-white">{avgGuildaton.toLocaleString()}</span>
                        <span className="text-[10px] font-black text-emerald-500 mb-2 uppercase italic font-black">Pts/membre</span>
                    </div>
                </Card>

                <Card className="lg:col-span-2 bg-black/40 border-white/5 backdrop-blur-xl rounded-[24px] p-4 flex flex-col h-[180px]">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] flex items-center gap-2">
                            <Clock className="w-4 h-4 text-indigo-400" />
                            Évolution (15 jours)
                        </span>
                        <Badge variant="outline" className="text-[8px] border-white/5 text-zinc-500 uppercase font-black">Analyses site</Badge>
                    </div>
                    <div className="flex-1 w-full min-h-[120px]">
                        {!mounted ? (
                            <div className="w-full h-full flex items-center justify-center">
                                <Loader2 className="w-4 h-4 animate-spin text-zinc-800" />
                            </div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%" minHeight={120} minWidth={0}>
                                <AreaChart data={graphData}>
                                    <defs>
                                        <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.3}/>
                                            <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                                        </linearGradient>
                                    </defs>
                                    <XAxis 
                                        dataKey="date" 
                                        hide 
                                    />
                                    <YAxis hide />
                                    <RechartsTooltip 
                                        contentStyle={{ backgroundColor: "#09090b", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "12px", fontSize: "10px", fontWeight: "bold" }}
                                    />
                                    <Area 
                                        type="monotone" 
                                        dataKey="total" 
                                        stroke="#8b5cf6" 
                                        fillOpacity={1} 
                                        fill="url(#colorTotal)" 
                                        strokeWidth={3}
                                    />
                                </AreaChart>
                            </ResponsiveContainer>
                        )}
                    </div>
                </Card>
            </div>

            {/* --- DOWNLOAD SOFTWARE SECTION --- */}
            <Card className="bg-gradient-to-br from-violet-600/10 via-zinc-900/40 to-emerald-500/5 border-white/5 backdrop-blur-xl overflow-hidden group">
                <CardContent className="p-4 flex flex-col sm:flex-row items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-zinc-950 flex items-center justify-center border border-white/5 shadow-2xl group-hover:scale-110 transition-transform duration-500">
                            <Camera className="w-6 h-6 text-violet-400" />
                        </div>
                        <div className="space-y-1">
                            <h3 className="text-sm font-black uppercase italic tracking-tighter text-white flex items-center gap-2">
                                Logiciel <span className="text-violet-500">SigilOCR</span>
                                <Badge className="bg-violet-500/20 text-violet-400 border-violet-500/30 text-[8px] px-1.5 py-0">v3.2 Stable</Badge>
                            </h3>
                            <p className="text-[10px] text-zinc-500 font-medium max-w-sm">
                                Outil de scan automatique des points de guilde. Compatible Windows 10/11.
                            </p>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <Button 
                            variant="outline"
                            className="h-10 bg-black/40 border-white/5 hover:border-violet-500/30 hover:bg-violet-600/10 text-[10px] font-black uppercase tracking-widest rounded-xl px-4 text-zinc-400 hover:text-white transition-all"
                            onClick={() => window.open('https://github.com/Klyx04/SigilOCR/releases/latest', '_blank')}
                        >
                            <FileJson className="w-4 h-4 mr-2" /> Release Notes
                        </Button>
                        <Button 
                            className="h-10 bg-violet-600 hover:bg-violet-500 text-white text-[10px] font-black uppercase tracking-widest rounded-xl px-6 shadow-[0_0_20px_rgba(139,92,246,0.2)] hover:scale-105 transition-all"
                            onClick={() => window.open('https://download.sigilos.fr/sigilocr-latest.exe', '_blank')}
                        >
                            <Download className="w-4 h-4 mr-2" /> Télécharger (Win)
                        </Button>
                    </div>
                </CardContent>
                
                {/* Decorative glow */}
                <div className="absolute -top-10 -right-10 w-32 h-32 bg-violet-600/10 blur-[50px] pointer-events-none" />
            </Card>

            {/* --- UTILITIES TABLE SECTION --- */}
            <div className="space-y-4">
                <div className="flex flex-wrap items-center justify-between gap-4">
                    <div className="flex flex-1 gap-2 w-full lg:max-w-md">
                        <div className="relative flex-1 group">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 group-focus-within:text-violet-400 transition-colors" />
                            <Input 
                                placeholder="Rechercher par pseudo, Discord ID..." 
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                className="pl-12 h-12 bg-black/40 border-white/5 text-white rounded-2xl focus:ring-violet-500/20 focus:border-violet-500/50 transition-all"
                            />
                        </div>
                        <select 
                            value={roleFilter}
                            onChange={(e) => setRoleFilter(e.target.value)}
                            className="h-12 px-4 rounded-2xl bg-black/40 border border-white/5 text-white text-xs font-bold focus:outline-none"
                        >
                            <option value="ALL">Tous les rôles</option>
                            {Array.from(new Set(data.members.map(m => m.discordRoleName))).filter(Boolean).map(rn => (
                                <option key={rn} value={rn!}>{rn}</option>
                            ))}
                        </select>
                    </div>
                    <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto">
                        <Button 
                            onClick={handleValidateWeek}
                            disabled={validating}
                            className="h-12 bg-emerald-600/20 border border-emerald-500/30 hover:bg-emerald-600/40 text-emerald-400 rounded-2xl px-6 text-[10px] font-black uppercase tracking-widest backdrop-blur-xl group"
                        >
                            {validating ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <CheckCircle2 className="w-4 h-4 mr-2 group-hover:scale-110 transition-transform" />}
                            Valider la Semaine
                        </Button>

                        <Button 
                            onClick={handleSendReminder}
                            disabled={sending || !data?.settings?.notifyChannelId}
                            variant="outline"
                            className="h-12 bg-zinc-900/60 border-white/10 hover:bg-zinc-800 hover:border-violet-500/30 rounded-2xl px-6 text-[10px] font-black uppercase tracking-widest backdrop-blur-xl group disabled:opacity-40 disabled:cursor-not-allowed"
                        >
                            {sending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Bell className="w-4 h-4 mr-2 text-violet-400 group-hover:scale-110 transition-transform" />}
                            Envoyer Rappel Discord
                        </Button>
                        <Dialog open={manualOpen} onOpenChange={setManualOpen}>
                            <DialogTrigger asChild>
                                <Button variant="outline" className="h-12 bg-zinc-900/60 border-white/10 hover:bg-zinc-800 hover:border-violet-500/30 rounded-2xl px-6 text-[10px] font-black uppercase tracking-widest backdrop-blur-xl">
                                    <Plus className="w-4 h-4 mr-2" />
                                    Ajouter Manuellement
                                </Button>
                            </DialogTrigger>
                            <DialogContent className="bg-zinc-950 border-white/10 rounded-[32px] max-w-md text-white">
                                <DialogHeader>
                                    <DialogTitle className="text-xl font-black uppercase italic italic text-white">Ajout <span className="text-violet-500">Manuel</span></DialogTitle>
                                    <DialogDescription className="text-zinc-500 text-xs font-bold uppercase tracking-widest">Inscrire un membre non présent sur le site.</DialogDescription>
                                </DialogHeader>
                                <div className="space-y-4 py-4">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase text-zinc-500 ml-1">Discord ID (Requis si connu)</label>
                                        <Input 
                                            placeholder="Ex: 283..." 
                                            value={manualForm.discordId}
                                            onChange={e => setManualForm({...manualForm, discordId: e.target.value})}
                                            className="bg-black/40 border-white/5 rounded-xl h-11"
                                        />
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black uppercase text-zinc-500 ml-1">Pseudo Discord</label>
                                            <Input 
                                                placeholder="Pseudo" 
                                                value={manualForm.username}
                                                onChange={e => setManualForm({...manualForm, username: e.target.value})}
                                                className="bg-black/40 border-white/5 rounded-xl h-11"
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black uppercase text-zinc-500 ml-1">Ankama ID</label>
                                            <Input 
                                                placeholder="Pseudo#1234" 
                                                value={manualForm.ankamaId}
                                                onChange={e => setManualForm({...manualForm, ankamaId: e.target.value})}
                                                className="bg-black/40 border-white/5 rounded-xl h-11"
                                            />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase text-zinc-500 ml-1">Guildaton Initial</label>
                                        <Input 
                                            type="number"
                                            value={manualForm.value}
                                            onChange={e => setManualForm({...manualForm, value: parseInt(e.target.value) || 0})}
                                            className="bg-black/40 border-white/5 rounded-xl h-11"
                                        />
                                    </div>
                                </div>
                                <DialogFooter>
                                    <Button onClick={handleManualAdd} disabled={sending} className="w-full bg-violet-600 hover:bg-violet-500 text-white rounded-xl h-11 font-black uppercase tracking-widest">
                                        {sending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : "Enregistrer"}
                                    </Button>
                                </DialogFooter>
                            </DialogContent>
                        </Dialog>

                        <Dialog open={importOpen} onOpenChange={setImportOpen}>
                            <DialogTrigger asChild>
                                <Button variant="outline" className="h-12 bg-indigo-900/40 border-indigo-500/20 hover:bg-indigo-800 hover:border-indigo-400 rounded-2xl px-6 text-[10px] font-black uppercase tracking-widest backdrop-blur-xl group">
                                    <Upload className="w-4 h-4 mr-2 group-hover:animate-bounce" />
                                    Importer CSV (OCR)
                                </Button>
                            </DialogTrigger>
                            <DialogContent className="bg-zinc-950 border-white/10 rounded-[32px] max-w-2xl text-white">
                                <DialogHeader>
                                    <DialogTitle className="text-xl font-black uppercase italic text-white flex items-center gap-3">
                                        <FileJson className="w-6 h-6 text-indigo-400" />
                                        Importation <span className="text-indigo-400">OCR Bot</span>
                                    </DialogTitle>
                                    <DialogDescription className="text-zinc-500 text-xs font-bold uppercase tracking-widest">Uploadez le fichier généré par votre bot OCR.</DialogDescription>
                                </DialogHeader>
                                <div className="space-y-6 py-6" onDrop={handleDrop} onDragOver={(e) => e.preventDefault()}>
                                    <div className="p-8 border-2 border-dashed border-white/5 rounded-3xl bg-white/[0.02] flex flex-col items-center justify-center gap-4 text-center group hover:border-indigo-500/30 hover:bg-white/[0.05] transition-all relative">
                                        <div className="p-4 bg-indigo-500/10 rounded-2xl group-hover:scale-110 transition-transform">
                                            <Upload className="w-8 h-8 text-indigo-400" />
                                        </div>
                                        <div>
                                            <p className="text-sm font-black text-white italic">Cliquez Libre ou Glissez-Déposez</p>
                                            <p className="text-[10px] text-zinc-500 font-bold mt-1 uppercase tracking-tighter">Le robot trouvera automatiquement les fautes dans les noms.</p>
                                        </div>
                                        <Input type="file" accept=".csv" title="Upload" onChange={handleCsvImport} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full z-50 block" />
                                    </div>

                                    {importData.length > 0 && (
                                        <div className="max-h-[300px] overflow-y-auto rounded-2xl border border-white/5 p-4 space-y-2 bg-black/40">
                                            <div className="flex items-center justify-between mb-2 pb-2 border-b border-white/5 text-[10px] font-black uppercase text-zinc-500 tracking-widest">
                                                <span>Aperçu des données ({importData.length} lignes)</span>
                                            </div>
                                            {importData.slice(0, 10).map((row, i) => (
                                                <div key={i} className="flex items-center justify-between text-xs py-1.5 border-b border-white/[0.02] last:border-none">
                                                    <span className="text-zinc-400 font-medium">@{row.username || row.discordId}</span>
                                                    <span className="font-black text-indigo-400 italic">{row.value} Pts</span>
                                                </div>
                                            ))}
                                            {importData.length > 10 && (
                                                <p className="text-[10px] text-zinc-600 text-center pt-2 italic">... et {importData.length - 10} autres membres</p>
                                            )}
                                        </div>
                                    )}
                                </div>
                                <DialogFooter className="gap-2">
                                    <Button variant="ghost" onClick={() => { setImportOpen(false); setImportData([]); }} className="text-white hover:bg-white/5">Annuler</Button>
                                    <Button onClick={confirmImport} disabled={sending || importData.length === 0} className="bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl px-8 font-black uppercase tracking-widest">
                                        {sending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : `Importer ${importData.length} membres`}
                                    </Button>
                                </DialogFooter>
                            </DialogContent>
                        </Dialog>
                    </div>
                </div>

                <div className="rounded-[32px] border border-white/10 bg-zinc-900/40 backdrop-blur-2xl overflow-hidden shadow-2xl overflow-x-auto no-scrollbar">
                    <Table className="min-w-[800px]">
                        <TableHeader className="bg-white/[0.02] border-b border-white/5">
                            <TableRow className="border-none hover:bg-transparent">
                                <TableHead className="pl-8 py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] whitespace-nowrap">Membre</TableHead>
                                <TableHead className="py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] whitespace-nowrap">Discord ID / Ankama</TableHead>
                                <TableHead className="py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] whitespace-nowrap">Inscrit</TableHead>
                                <TableHead className="py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] w-[200px] whitespace-nowrap">Guildaton (Edit)</TableHead>
                                <TableHead className="pr-8 text-right py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] whitespace-nowrap">Action</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {loading ? (
                                <TableRow>
                                    <TableCell colSpan={5} className="h-64 text-center">
                                        <div className="flex flex-col items-center gap-4 py-10 opacity-40">
                                            <Loader2 className="w-8 h-8 text-violet-500 animate-spin" />
                                            <p className="text-xs font-black uppercase tracking-widest text-white italic">Synchronisation Guildaton...</p>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            ) : filteredMembers.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={5} className="h-32 text-center text-zinc-500 text-xs font-bold uppercase italic">Aucun membre trouvé</TableCell>
                                </TableRow>
                            ) : (
                                filteredMembers.map(m => (
                                    <TableRow key={m.discordId} className="group border-b border-white/[0.03] hover:bg-white/[0.02] transition-colors">
                                        <TableCell className="pl-8 py-4">
                                            <div className="flex items-center gap-4">
                                                <div className="w-10 h-10 rounded-xl bg-zinc-800 border border-white/5 flex items-center justify-center font-black text-sm text-zinc-400 group-hover:border-violet-500/50 transition-all uppercase italic rotate-3 group-hover:rotate-0">
                                                    {m.displayName.charAt(0)}
                                                </div>
                                                <div className="flex flex-col leading-tight gap-1">
                                                    <span className="font-black text-zinc-200 group-hover:text-white transition-colors flex items-center gap-2">
                                                        {m.displayName}
                                                        {m.isRegistered && m.currentValue < (data.settings?.weeklyQuota || 0) && (
                                                            <div className="flex items-center gap-1 bg-red-500/10 text-red-400 px-1.5 py-[2px] rounded-sm text-[8px] uppercase font-black">
                                                                <AlertCircle className="w-3 h-3" /> Glandeur
                                                            </div>
                                                        )}
                                                    </span>
                                                    <span className="text-[9px] text-zinc-500 font-black uppercase tracking-widest">{m.discordRoleName || "Membre de guilde"}</span>
                                                    
                                                    {/* Petit graphique d'évolution */}
                                                    <div className="h-8 w-32 mt-2 opacity-30 group-hover:opacity-100 transition-opacity">
                                                        <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                                                            <AreaChart data={data.history?.filter(h => h.discordId === m.discordId).map(h => ({ value: h.value })) || []}>
                                                                <Area 
                                                                    type="monotone" 
                                                                    dataKey="value" 
                                                                    stroke="#8b5cf6" 
                                                                    fill="url(#colorVal)" 
                                                                    strokeWidth={2}
                                                                    isAnimationActive={false}
                                                                />
                                                                <defs>
                                                                    <linearGradient id="colorVal" x1="0" y1="0" x2="0" y2="1">
                                                                        <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.3}/>
                                                                        <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                                                                    </linearGradient>
                                                                </defs>
                                                            </AreaChart>
                                                        </ResponsiveContainer>
                                                    </div>
                                                </div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex flex-col gap-1">
                                                <span className="text-[10px] font-black text-zinc-500 bg-white/5 px-2 py-0.5 rounded-md w-fit tabular-nums">{m.discordId}</span>
                                                {m.ankamaId && <span className="text-[10px] font-black text-violet-400/70">{m.ankamaId}</span>}
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex flex-col gap-1.5">
                                                {m.isRegistered ? (
                                                    <Badge className="bg-emerald-500/10 text-emerald-500 border-none text-[9px] font-black uppercase tracking-widest w-fit">Inscrit site</Badge>
                                                ) : (
                                                    <Badge variant="outline" className="border-zinc-800 text-zinc-600 text-[9px] font-black uppercase tracking-widest w-fit">Non-inscrit</Badge>
                                                )}
                                                {!m.isOnDiscord && (
                                                    <Badge variant="outline" className="border-amber-500/30 text-amber-500/80 text-[8px] font-black uppercase tracking-tighter w-fit">Pas sur Discord</Badge>
                                                )}
                                                {m.discordId.startsWith("manual_") && (
                                                    <Badge variant="outline" className="border-violet-500/30 text-violet-500/80 text-[8px] font-black uppercase tracking-tighter w-fit italic">Ligne Manuelle</Badge>
                                                )}
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="relative w-[140px] group/input">
                                                <div className="absolute left-3 top-1/2 -translate-y-1/2 p-1 rounded-md bg-zinc-800/50">
                                                    <img src="/guildaton.png" alt="Icon" className="w-3 h-3 object-contain opacity-70 group-focus-within/input:opacity-100 transition-opacity" />
                                                </div>
                                                <Input 
                                                    type="number" 
                                                    value={m.currentValue}
                                                    onChange={(e) => {
                                                        const newVal = parseInt(e.target.value) || 0;
                                                        setData(prev => ({
                                                            ...prev,
                                                            members: prev.members.map(member => 
                                                                member.discordId === m.discordId ? { ...member, currentValue: newVal } : member
                                                            )
                                                        }));
                                                    }}
                                                    onBlur={() => handleUpdateValue(m, m.currentValue)}
                                                    className="pl-10 h-10 bg-black/40 border-white/5 focus:border-violet-500/50 rounded-xl font-black text-zinc-200 w-full tabular-nums"
                                                />
                                            </div>
                                        </TableCell>
                                        <TableCell className="pr-8 text-right">
                                            <div className="flex items-center justify-end gap-1">
                                                {m.profileId && (
                                                    <Button variant="ghost" size="sm" className="w-8 h-8 p-0 rounded-lg hover:bg-violet-600/20 hover:text-violet-400 transition-all" asChild>
                                                        <a href={`/dashboard/${guildId}/members/${m.profileId}`} target="_blank">
                                                            <ArrowUpRight className="w-4 h-4" />
                                                        </a>
                                                    </Button>
                                                )}
                                                <Button 
                                                    variant="ghost" 
                                                    size="sm" 
                                                    onClick={() => handleDeleteRecord(m.discordId)}
                                                    className="w-8 h-8 p-0 rounded-lg hover:bg-red-600/20 hover:text-red-400 text-zinc-600 transition-all"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useTransition } from "react";
import { 
    Ban, 
    Search, 
    Plus, 
    Trash2, 
    Calendar, 
    User, 
    Clock, 
    AlertCircle,
    Loader2,
    ShieldAlert,
    Ban as BanIcon,
    HelpCircle,
    Pencil,
    Check,
    X
} from "lucide-react";
import { 
    Tooltip, 
    TooltipContent, 
    TooltipProvider, 
    TooltipTrigger 
} from "@/components/ui/tooltip";
import { 
    Card, 
    CardContent, 
    CardDescription, 
    CardHeader, 
    CardTitle 
} from "@/components/ui/card";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { 
    Table, 
    TableBody, 
    TableCell, 
    TableHead, 
    TableHeader, 
    TableRow 
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { motion, AnimatePresence } from "framer-motion";
import { toast } from "sonner";
import { 
    addBlacklistEntry, 
    getBlacklistEntries, 
    deleteBlacklistEntry,
    editBlacklistEntry 
} from "@/server/actions/blacklist-actions";

interface BlacklistEntry {
    id: string;
    content: string;
    addedByName: string;
    createdAt: Date;
}

interface MemberBlacklistProps {
    guildId: string;
}

export function MemberBlacklist({ guildId }: MemberBlacklistProps) {
    const [entries, setEntries] = useState<BlacklistEntry[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [newContent, setNewContent] = useState("");
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editContent, setEditContent] = useState("");
    const [isPending, startTransition] = useTransition();

    const renderFormattedContent = (text: string) => {
        const pseudoRegex = /([a-zA-Z0-9_-]+)(#\d{4})/g;
        const guildRegex = /(Guilde\s+)(\[.*?\])/g;

        const parts: (string | React.ReactNode)[] = [text];

        const mappedParts = parts.flatMap(part => {
            if (typeof part !== 'string') return part;
            const subParts: (string | React.ReactNode)[] = [];
            let lastIndex = 0;
            let match;
            const regex = new RegExp(pseudoRegex);
            while ((match = regex.exec(part)) !== null) {
                subParts.push(part.substring(lastIndex, match.index));
                subParts.push(<span key={`p-${match.index}`} className="text-red-400 font-black">{match[1]}</span>);
                subParts.push(<span key={`t-${match.index}`} className="text-zinc-500 font-medium">{match[2]}</span>);
                lastIndex = regex.lastIndex;
            }
            subParts.push(part.substring(lastIndex));
            return subParts;
        });

        const finalParts = mappedParts.flatMap(part => {
            if (typeof part !== 'string') return part;
            const subParts: (string | React.ReactNode)[] = [];
            let lastIndex = 0;
            let match;
            const regex = new RegExp(guildRegex);
            while ((match = regex.exec(part)) !== null) {
                subParts.push(part.substring(lastIndex, match.index));
                subParts.push(<span key={`g-${match.index}`} className="text-amber-500 font-black uppercase tracking-tighter">{match[1]}</span>);
                subParts.push(<span key={`gn-${match.index}`} className="text-amber-200 font-bold italic">{match[2]}</span>);
                lastIndex = regex.lastIndex;
            }
            subParts.push(part.substring(lastIndex));
            return subParts;
        });

        return finalParts;
    };

    const fetchEntries = async (query?: string) => {
        setLoading(true);
        try {
            const res = await getBlacklistEntries(guildId, query);
            if (res.success && res.data) {
                setEntries(res.data);
            }
        } catch (error) {
            toast.error("Erreur de chargement");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchEntries();
    }, [guildId]);

    const handleSearch = (val: string) => {
        setSearch(val);
        fetchEntries(val);
    };

    const handleAdd = () => {
        if (!newContent.trim()) {
            toast.error("Le contenu ne peut pas être vide");
            return;
        }

        startTransition(async () => {
            const res = await addBlacklistEntry({ guildId, content: newContent });
            if (res.success) {
                toast.success("Entrée ajoutée à la blacklist");
                setNewContent("");
                fetchEntries(search);
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        });
    };

    const handleDelete = (id: string) => {
        if (!confirm("Voulez-vous vraiment supprimer cette entrée ?")) return;

        startTransition(async () => {
            const res = await deleteBlacklistEntry(guildId, id);
            if (res.success) {
                toast.success("Entrée supprimée");
                fetchEntries(search);
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        });
    };

    const handleStartEdit = (entry: BlacklistEntry) => {
        setEditingId(entry.id);
        setEditContent(entry.content);
    };

    const handleSaveEdit = () => {
        if (!editingId) return;
        if (!editContent.trim()) {
            toast.error("Le contenu ne peut pas être vide");
            return;
        }

        startTransition(async () => {
            const res = await editBlacklistEntry(guildId, editingId, editContent);
            if (res.success) {
                toast.success("Entrée modifiée");
                setEditingId(null);
                fetchEntries(search);
            } else {
                toast.error(res.error || "Erreur lors de la modification");
            }
        });
    };

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Header / Add Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <Card className="lg:col-span-1 bg-zinc-900/40 backdrop-blur-xl border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl h-fit border-t border-t-white/10">
                    <CardHeader className="bg-white/[0.02] border-b border-white/5 px-6 py-5">
                        <div className="flex items-center gap-3">
                            <div className="p-2.5 bg-red-500/10 border border-red-500/20 rounded-2xl">
                                <Plus className="w-5 h-5 text-red-500" />
                            </div>
                            <CardTitle className="text-sm font-black uppercase tracking-[0.2em] text-white italic">Ajouter une entrée</CardTitle>
                        </div>
                    </CardHeader>
                    <CardContent className="p-6 space-y-4">
                        <div className="space-y-2">
                            <div className="flex items-center justify-between px-1">
                                <label className="text-[10px] font-black uppercase text-zinc-500 tracking-widest">Détails de l&apos;individu</label>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <div className="p-1.5 cursor-help bg-white/5 hover:bg-red-500/20 rounded-lg transition-all group/tooltip border border-white/5 hover:border-red-500/20">
                                            <HelpCircle className="w-4 h-4 text-zinc-400 group-hover/tooltip:text-red-400 transition-colors" />
                                        </div>
                                    </TooltipTrigger>
                                    <TooltipContent side="right" sideOffset={15} className="bg-zinc-950 border border-white/10 p-5 max-w-[300px] space-y-3 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] animate-in zoom-in-95 duration-200 z-[100]">
                                        <div className="flex items-center gap-3 mb-1">
                                            <div className="w-1.5 h-4 bg-red-600 rounded-full shadow-[0_0_10px_rgba(239,68,68,0.5)]" />
                                            <p className="text-xs font-black uppercase text-white tracking-widest">Comment remplir ?</p>
                                        </div>
                                        <div className="space-y-2">
                                            <p className="text-[11px] text-zinc-300 leading-relaxed italic">
                                                Tapez <span className="text-red-400 font-black italic">/whois pseudo</span> en jeu ou cliquez sur un joueur <span className="text-white font-bold">&gt; Informations &gt; Détails</span>.
                                            </p>
                                            <p className="text-[11px] text-zinc-400 leading-relaxed">
                                                Copiez ensuite <span className="text-white font-medium">toute la ligne</span> de log et collez-la ici. SigilOS s&apos;occupe du reste !
                                            </p>
                                        </div>
                                    </TooltipContent>
                                </Tooltip>
                            </div>
                            <Textarea 
                                placeholder="Pseudo, compte Dofus, raison... (Pas de liens autorisés)"
                                value={newContent}
                                onChange={(e) => setNewContent(e.target.value)}
                                className="min-h-[120px] bg-black/40 border-white/5 text-white rounded-3xl focus:ring-red-500/20 focus:border-red-500/50 transition-all placeholder:text-zinc-600 font-medium resize-none p-4"
                            />
                        </div>
                        <Button 
                            className="w-full h-12 bg-red-600 hover:bg-red-500 text-white rounded-2xl font-black uppercase tracking-widest gap-2 shadow-lg shadow-red-600/20"
                            onClick={handleAdd}
                            disabled={isPending}
                        >
                            {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Ban className="w-4 h-4" />}
                            Inscrire à la Blacklist
                        </Button>
                        <p className="text-[9px] text-zinc-600 italic text-center px-4 leading-relaxed">
                            Cette liste est purement informative et n&apos;influence pas l&apos;accès automatique au dashboard.
                        </p>

                        {/* Discord Sync Promo */}
                        <Link 
                            href={`/dashboard/${guildId}/admin/settings?tab=blacklist`}
                            className="block group/sync mt-4"
                        >
                            <div className="p-4 rounded-2xl bg-white/[0.03] border border-white/5 hover:border-red-500/30 hover:bg-red-500/5 transition-all duration-300">
                                <div className="flex items-center gap-3 mb-2">
                                    <div className="p-1.5 rounded-lg bg-zinc-800 border border-white/5 group-hover/sync:bg-red-500/20 group-hover/sync:border-red-500/30 transition-colors">
                                        <ShieldAlert className="w-3.5 h-3.5 text-zinc-500 group-hover/sync:text-red-400" />
                                    </div>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-zinc-400 group-hover/sync:text-white transition-colors">Synchro Discord</p>
                                </div>
                                <p className="text-[10px] text-zinc-500 group-hover/sync:text-zinc-300 leading-loose">
                                    Les administrateurs peuvent <span className="text-zinc-300 font-bold">coupler un salon Discord</span> pour une synchro en temps réel.
                                </p>
                                <div className="mt-3 flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest text-red-500/60 group-hover/sync:text-red-400 transition-colors">
                                    Configurer maintenant
                                    <Plus className="w-3 h-3 group-hover/sync:translate-x-0.5 transition-transform" />
                                </div>
                            </div>
                        </Link>
                    </CardContent>
                </Card>

                <div className="lg:col-span-2 space-y-6">
                    {/* Search Bar */}
                    <div className="relative group">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 group-focus-within:text-red-400 transition-colors" />
                        <Input 
                            placeholder="Rechercher dans la blacklist..." 
                            value={search}
                            onChange={(e) => handleSearch(e.target.value)}
                            className="pl-12 h-14 bg-zinc-900/40 backdrop-blur-xl border-white/5 text-white rounded-[1.5rem] focus:ring-red-500/20 focus:border-red-500/50 transition-all placeholder:text-zinc-600 font-medium shadow-2xl"
                        />
                    </div>

                    {/* Entries List */}
                    <div className="rounded-[2.5rem] border border-white/10 bg-zinc-900/40 backdrop-blur-2xl overflow-hidden shadow-2xl relative group">
                        <div className="absolute inset-0 bg-gradient-to-br from-red-500/5 to-transparent pointer-events-none" />
                        <Table>
                            <TableHeader className="bg-white/[0.02] border-b border-white/5 relative z-10">
                                <TableRow className="hover:bg-transparent border-none">
                                    <TableHead className="pl-8 py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em]">Détails du Signalement</TableHead>
                                    <TableHead className="py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] w-[200px]">Auteur & Date</TableHead>
                                    <TableHead className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] pr-8 text-right py-6 w-[80px]"></TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody className="relative z-10">
                                <AnimatePresence mode="popLayout">
                                    {loading ? (
                                        <TableRow>
                                            <TableCell colSpan={3} className="h-64 text-center">
                                                <div className="flex flex-col items-center gap-4">
                                                    <Loader2 className="w-8 h-8 text-red-500 animate-spin" />
                                                    <span className="text-xs font-black uppercase tracking-widest text-zinc-500">Chargement de la blacklist...</span>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    ) : entries.length === 0 ? (
                                        <TableRow>
                                            <TableCell colSpan={3} className="h-64 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <BanIcon className="w-12 h-12 text-zinc-600" />
                                                    <div className="space-y-1">
                                                        <p className="text-sm font-black uppercase tracking-widest text-zinc-300">Blacklist vide</p>
                                                        <p className="text-[10px] text-zinc-500 italic">Aucun signalement ne correspond à votre recherche.</p>
                                                    </div>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    ) : (
                                        entries.map((entry) => (
                                            <motion.tr 
                                                layout
                                                key={entry.id} 
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                exit={{ opacity: 0, scale: 0.95 }}
                                                className="group border-b border-white/[0.03] hover:bg-white/[0.02] transition-colors"
                                            >
                                                <TableCell className="pl-8 py-6">
                                                    {editingId === entry.id ? (
                                                        <div className="space-y-3 animate-in fade-in zoom-in-95 duration-200">
                                                            <Textarea 
                                                                value={editContent}
                                                                onChange={(e) => setEditContent(e.target.value)}
                                                                className="bg-black/60 border-white/10 text-zinc-200 text-sm font-medium rounded-2xl min-h-[80px]"
                                                            />
                                                            <div className="flex items-center gap-2">
                                                                <Button 
                                                                    size="sm" 
                                                                    className="bg-emerald-600 hover:bg-emerald-500 text-white h-8 px-4 font-black uppercase tracking-widest text-[10px] rounded-lg"
                                                                    onClick={handleSaveEdit}
                                                                    disabled={isPending}
                                                                >
                                                                    {isPending ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5 mr-2" />}
                                                                    Valider
                                                                </Button>
                                                                <Button 
                                                                    size="sm" 
                                                                    variant="ghost"
                                                                    className="text-zinc-500 hover:text-white h-8 px-4 font-black uppercase tracking-widest text-[10px] rounded-lg"
                                                                    onClick={() => setEditingId(null)}
                                                                    disabled={isPending}
                                                                >
                                                                    Annuler
                                                                </Button>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <div className="space-y-1">
                                                            <div className="text-sm font-bold text-zinc-200 group-hover:text-white transition-colors leading-relaxed whitespace-pre-wrap break-words italic">
                                                                &ldquo;{renderFormattedContent(entry.content)}&rdquo;
                                                            </div>
                                                        </div>
                                                    )}
                                                </TableCell>
                                                <TableCell className="py-6">
                                                    <div className="flex flex-col gap-1.5 justify-center h-full">
                                                        <div className="flex items-center gap-2 text-zinc-400 group-hover:text-red-400 transition-colors">
                                                            <User className="w-3 h-3" />
                                                            <span className="text-[10px] font-black uppercase tracking-wider">{entry.addedByName}</span>
                                                        </div>
                                                        <div className="flex items-center gap-2 text-zinc-500">
                                                            <Clock className="w-3 h-3" />
                                                            <span className="text-[9px] font-bold tabular-nums">
                                                                {format(new Date(entry.createdAt), "dd MMM yyyy, HH:mm", { locale: fr })}
                                                            </span>
                                                        </div>
                                                    </div>
                                                </TableCell>
                                                <TableCell className="pr-8 text-right">
                                                    <div className="flex items-center justify-end gap-1">
                                                        <Button 
                                                            variant="ghost" 
                                                            size="sm" 
                                                            className="h-9 w-9 p-0 rounded-xl text-zinc-600 hover:text-amber-500 hover:bg-amber-500/10 transition-all opacity-0 group-hover:opacity-100"
                                                            onClick={() => handleStartEdit(entry)}
                                                            disabled={editingId === entry.id}
                                                        >
                                                            <Pencil className="w-4 h-4" />
                                                        </Button>
                                                        <Button 
                                                            variant="ghost" 
                                                            size="sm" 
                                                            className="h-9 w-9 p-0 rounded-xl text-zinc-600 hover:text-red-500 hover:bg-red-500/10 transition-all opacity-0 group-hover:opacity-100"
                                                            onClick={() => handleDelete(entry.id)}
                                                            disabled={editingId === entry.id}
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </Button>
                                                    </div>
                                                </TableCell>
                                            </motion.tr>
                                        ))
                                    )}
                                </AnimatePresence>
                            </TableBody>
                        </Table>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React from "react";
import { 
    BarChart, 
    Bar, 
    XAxis, 
    YAxis, 
    CartesianGrid, 
    Tooltip, 
    ResponsiveContainer, 
    Cell,
    PieChart,
    Pie
} from "recharts";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { MessageSquare, Mic, Activity, Ghost } from "lucide-react";
import { MemberReconciliationData } from "@/server/actions/member-actions";

interface MemberDiscordChartsProps {
    members: MemberReconciliationData[];
}

export function MemberDiscordCharts({ members }: MemberDiscordChartsProps) {
    const [mounted, setMounted] = React.useState(false);

    React.useEffect(() => {
        setMounted(true);
    }, []);

    // 1. Calculate general activity status
    const activeCount = members.filter(m => (m.discordMessageCountWeekly || 0) > 0 || (m.discordVoiceTimeWeekly || 0) > 0).length;
    const silentCount = Math.max(0, members.length - activeCount);

    const activityData = [
        { name: "Actifs", value: activeCount, color: "#8b5cf6" }, // Violet
        { name: "Silencieux", value: silentCount, color: "#3f3f46" } // Zinc-700
    ];

    if (!mounted) {
        return (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[300px]">
                {[1, 2, 3].map(i => (
                    <Card key={i} className="bg-zinc-900/30 border-white/5 animate-pulse rounded-[32px] overflow-hidden shadow-2xl" />
                ))}
            </div>
        );
    }

    // 2. Top Talkers
    const topTalkers = [...members]
        .sort((a, b) => (b.discordMessageCountWeekly || 0) - (a.discordMessageCountWeekly || 0))
        .slice(0, 5)
        .map(m => ({
            name: m.displayName.split(" ")[0],
            value: m.discordMessageCountWeekly || 0
        }));

    // 3. Top Vocal
    const topVocal = [...members]
        .sort((a, b) => (b.discordVoiceTimeWeekly || 0) - (a.discordVoiceTimeWeekly || 0))
        .slice(0, 5)
        .map(m => ({
            name: m.displayName.split(" ")[0],
            value: Math.round((m.discordVoiceTimeWeekly || 0) / 60) // Convert to hours for chart
        }));

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Activity Overview */}
            <Card className="bg-zinc-900/30 border-white/5 backdrop-blur-xl rounded-[32px] overflow-hidden shadow-2xl relative">
                <CardHeader className="pb-2">
                    <CardTitle className="text-sm font-black uppercase tracking-[0.2em] text-white italic flex items-center gap-2">
                        <Activity className="w-4 h-4 text-violet-400" />
                        État d&apos;activité
                    </CardTitle>
                    <CardDescription className="text-[10px] uppercase font-bold text-zinc-500">Membres ayant participé cette semaine</CardDescription>
                </CardHeader>
                <CardContent className="h-[250px] relative min-h-[250px]">
                    <ResponsiveContainer width="100%" height="100%" minHeight={200} minWidth={0}>
                        <PieChart>
                            <Pie
                                data={activityData}
                                cx="50%"
                                cy="50%"
                                innerRadius={60}
                                outerRadius={80}
                                paddingAngle={5}
                                dataKey="value"
                            >
                                {activityData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                                ))}
                            </Pie>
                            <Tooltip 
                                contentStyle={{ backgroundColor: "#09090b", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "12px", fontSize: "10px", fontWeight: "bold" }}
                                itemStyle={{ color: "#fff" }}
                            />
                        </PieChart>
                    </ResponsiveContainer>
                    <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none mt-4">
                        <span className="text-3xl font-black text-white">{Math.round((activeCount / members.length) * 100)}%</span>
                        <span className="text-[10px] font-black text-violet-400 uppercase tracking-widest">Actif</span>
                    </div>
                </CardContent>
            </Card>

            {/* Top Messages */}
            <Card className="bg-zinc-900/30 border-white/5 backdrop-blur-xl rounded-[32px] overflow-hidden shadow-2xl">
                <CardHeader className="pb-2">
                    <CardTitle className="text-sm font-black uppercase tracking-[0.2em] text-white italic flex items-center gap-2">
                        <MessageSquare className="w-4 h-4 text-blue-400" />
                        Top Bavards
                    </CardTitle>
                    <CardDescription className="text-[10px] uppercase font-bold text-zinc-500">Volume de messages par membre</CardDescription>
                </CardHeader>
                <CardContent className="h-[250px] pt-4 min-h-[250px]">
                    <ResponsiveContainer width="100%" height="100%" minHeight={200} minWidth={0}>
                        <BarChart data={topTalkers} margin={{ top: 0, right: 30, left: -20, bottom: 0 }}>
                            <XAxis 
                                dataKey="name" 
                                axisLine={false} 
                                tickLine={false} 
                                tick={{ fill: "#71717a", fontSize: 10, fontWeight: "bold" }} 
                            />
                            <YAxis hide />
                            <Tooltip 
                                cursor={{ fill: "rgba(255,255,255,0.03)" }}
                                contentStyle={{ backgroundColor: "#09090b", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "12px", fontSize: "10px", fontWeight: "bold" }}
                            />
                            <Bar 
                                dataKey="value" 
                                fill="#3b82f6" 
                                radius={[8, 8, 8, 8]} 
                                barSize={25}
                            />
                        </BarChart>
                    </ResponsiveContainer>
                </CardContent>
            </Card>

            {/* Top Vocal */}
            <Card className="bg-zinc-900/30 border-white/5 backdrop-blur-xl rounded-[32px] overflow-hidden shadow-2xl">
                <CardHeader className="pb-2">
                    <CardTitle className="text-sm font-black uppercase tracking-[0.2em] text-white italic flex items-center gap-2">
                        <Mic className="w-4 h-4 text-emerald-400" />
                        Top Vidéo/Vocal
                    </CardTitle>
                    <CardDescription className="text-[10px] uppercase font-bold text-zinc-500">Temps de parole (heures cumulées)</CardDescription>
                </CardHeader>
                <CardContent className="h-[250px] pt-4 min-h-[250px]">
                    <ResponsiveContainer width="100%" height="100%" minHeight={200} minWidth={0}>
                        <BarChart data={topVocal} margin={{ top: 0, right: 30, left: -20, bottom: 0 }}>
                            <XAxis 
                                dataKey="name" 
                                axisLine={false} 
                                tickLine={false} 
                                tick={{ fill: "#71717a", fontSize: 10, fontWeight: "bold" }} 
                            />
                            <YAxis hide />
                            <Tooltip 
                                cursor={{ fill: "rgba(255,255,255,0.03)" }}
                                contentStyle={{ backgroundColor: "#09090b", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "12px", fontSize: "10px", fontWeight: "bold" }}
                            />
                            <Bar 
                                dataKey="value" 
                                fill="#10b981" 
                                radius={[8, 8, 8, 8]} 
                                barSize={25}
                            />
                        </BarChart>
                    </ResponsiveContainer>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

