import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue
} from "@/components/ui/select";
import { Search, AlertTriangle, Package, Gift, Bug, RefreshCw, MapPin, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Toggle } from "@/components/ui/toggle";
import {
    forceRefreshOcre,
    getGuildExchangeMap,
    type OcreProgressData,
    type GuildExchangeMapData,
} from "@/server/actions/ocre-actions";
import type { OcreMonster } from "@/lib/metamob-client";
import { toast } from "sonner";


interface ArchiHubProps {
    data: OcreProgressData;
    guildId: string;
}

export function ArchiHub({ data, guildId }: ArchiHubProps) {
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedZone, setSelectedZone] = useState<string>("all");
    const [showExchangeableOnly, setShowExchangeableOnly] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);

    // Pre-loaded exchange availability map
    const [doublonsMap, setDoublonsMap] = useState<Record<number, number>>({});
    const [doublonsLoading, setDoublonsLoading] = useState(true);

    const loadDoublonsMap = async () => {
        setDoublonsLoading(true);
        const result = await getGuildExchangeMap(guildId);
        if (result.success && result.data) {
            setDoublonsMap(result.data.availableExchanges);
        }
        setDoublonsLoading(false);
    };

    // Load doublons map once on mount
    useEffect(() => {
        loadDoublonsMap();
    }, [guildId]);

    // Extract unique zones from monsters
    const zones = useMemo(() => {
        const uniqueZones = new Set<string>();
        data.monsters.forEach((m) => {
            if (m.zone) uniqueZones.add(m.zone);
        });
        return Array.from(uniqueZones).sort();
    }, [data.monsters]);

    // Categorize monsters
    const { manquants, possedes, doublons } = useMemo(() => {
        return {
            manquants: data.monsters.filter((m) => m.state === "MANQUANT"),
            possedes: data.monsters.filter((m) => m.state === "POSSEDE"),
            doublons: data.monsters.filter((m) => m.state === "DOUBLON"),
        };
    }, [data.monsters]);

    // Count monsters with available exchanges
    const monstersWithExchanges = useMemo(() => {
        return manquants.filter(m => doublonsMap[m.id] && doublonsMap[m.id] > 0).length;
    }, [manquants, doublonsMap]);

    // Filter monsters by search query, zone, and exchangeable
    const filterMonsters = (monsters: OcreMonster[], applyExchangeFilter = false) => {
        let filtered = monsters;

        // Filter by zone
        if (selectedZone !== "all") {
            filtered = filtered.filter((m) => m.zone === selectedZone);
        }

        // Filter by search query
        if (searchQuery.trim()) {
            const query = searchQuery.toLowerCase();
            filtered = filtered.filter(
                (m) =>
                    m.name.toLowerCase().includes(query) ||
                    (m.zone && m.zone.toLowerCase().includes(query)) ||
                    (m.subzone && m.subzone.toLowerCase().includes(query))
            );
        }

        // Filter exchangeable only (only for manquants tab)
        if (applyExchangeFilter && showExchangeableOnly) {
            filtered = filtered.filter(m => doublonsMap[m.id] && doublonsMap[m.id] > 0);
        }

        return filtered;
    };

    const handleRefresh = async () => {
        setIsRefreshing(true);
        const result = await forceRefreshOcre(guildId);
        if (result.success) {
            toast.success("Données actualisées ! Rechargez la page pour voir les changements.");
            // Also refresh the doublons map
            loadDoublonsMap();
        } else {
            toast.error(result.error || "Erreur lors du rafraîchissement");
        }
        setIsRefreshing(false);
    };

    const clearFilters = () => {
        setSearchQuery("");
        setSelectedZone("all");
        setShowExchangeableOnly(false);
    };

    const hasActiveFilters = searchQuery.trim() !== "" || selectedZone !== "all" || showExchangeableOnly;



    // Progress Calculation Helpers
    const getProgressColor = (current: number, total: number) => {
        if (current === total) return "bg-emerald-500";
        if (current > total * 0.7) return "bg-emerald-400";
        if (current > total * 0.3) return "bg-amber-400";
        return "bg-red-400";
    };

    const renderProgressBar = (label: string, category: { total: number; gathered: number }, max: number) => {
        const percent = Math.min(100, Math.round((category.gathered / max) * 100));
        return (
            <div className="space-y-1">
                <div className="flex items-center justify-between text-xs">
                    <span className="font-medium text-muted-foreground">{label}</span>
                    <span className="text-muted-foreground">
                        <span className={category.gathered === max ? "text-emerald-500 font-bold" : "text-foreground"}>
                            {category.gathered}
                        </span>
                        /{max}
                    </span>
                </div>
                <Progress value={percent} className="h-1.5" indicatorClassName={getProgressColor(category.gathered, max)} />
            </div>
        );
    };

    return (
        <div className="space-y-6">
            {/* Detailed Progress Section (Metamob Style) */}
            <Card className="border-border/50 bg-card/50 backdrop-blur-sm overflow-hidden">
                <CardContent className="p-6 space-y-4">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-full bg-amber-500/10 text-amber-500">
                            <span className="text-xl">🏆</span>
                        </div>
                        <div>
                            <h3 className="font-semibold text-lg">Quête de l'Éternelle Moisson</h3>
                            <p className="text-sm text-muted-foreground">Avancement détaillé par catégorie</p>
                        </div>
                    </div>

                    <div className="grid gap-6 md:grid-cols-3">
                        {renderProgressBar("Gardiens de Donjon", data.stats.bosses, data.stats.bosses.total)}
                        {renderProgressBar("Archimonstres", data.stats.archis, data.stats.archis.total)}
                    </div>
                </CardContent>
            </Card>

            {/* Stats Overview */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <StatCard
                    label="Gardiens & Archis"
                    value={data.stats.total}
                    icon={<Bug className="h-5 w-5" />}
                    color="text-primary"
                />
                <StatCard
                    label="Manquants"
                    value={manquants.length}
                    icon={<AlertTriangle className="h-5 w-5" />}
                    color="text-red-500"
                    subValue={!doublonsLoading && monstersWithExchanges > 0
                        ? `${monstersWithExchanges} échangeables`
                        : undefined
                    }
                    subColor="text-emerald-500"
                />
                <StatCard
                    label="Possédés"
                    value={possedes.length}
                    icon={<Package className="h-5 w-5" />}
                    color="text-emerald-500"
                />
                <StatCard
                    label="Doublons"
                    value={doublons.length}
                    icon={<Gift className="h-5 w-5" />}
                    color="text-amber-500"
                />
            </div>

            {/* Filters Bar */}
            <div className="flex flex-wrap items-center gap-3">
                {/* Search */}
                <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Rechercher un archimonstre..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10"
                    />
                </div>

                {/* Zone Filter */}
                <Select value={selectedZone} onValueChange={setSelectedZone}>
                    <SelectTrigger className="w-[180px]">
                        <MapPin className="h-4 w-4 mr-2 text-muted-foreground" />
                        <SelectValue placeholder="Toutes les zones" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Toutes les zones</SelectItem>
                        {zones.map((zone) => (
                            <SelectItem key={zone} value={zone}>
                                {zone}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>

                {/* Exchangeable Only Toggle */}
                <Toggle
                    pressed={showExchangeableOnly}
                    onPressedChange={setShowExchangeableOnly}
                    className="gap-2 data-[state=on]:bg-emerald-600 data-[state=on]:text-white"
                    disabled={doublonsLoading || monstersWithExchanges === 0}
                >
                    <Sparkles className="h-4 w-4" />
                    <span className="hidden sm:inline">Échangeables</span>
                    {monstersWithExchanges > 0 && (
                        <Badge variant="secondary" className="h-5 px-1.5 text-xs">
                            {monstersWithExchanges}
                        </Badge>
                    )}
                </Toggle>

                {/* Clear Filters */}
                {hasActiveFilters && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={clearFilters}
                        className="text-muted-foreground hover:text-foreground"
                    >
                        Effacer
                    </Button>
                )}

                {/* Refresh */}
                <Button
                    variant="outline"
                    size="icon"
                    onClick={handleRefresh}
                    disabled={isRefreshing}
                >
                    <RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
                </Button>
            </div>

            {/* Tabs */}
            <Tabs defaultValue="manquants" className="w-full">
                <TabsList className="grid w-full grid-cols-3">
                    <TabsTrigger value="manquants" className="gap-2">
                        <span className="hidden sm:inline">🔴</span>
                        Manquants
                        <Badge variant="secondary" className="ml-1 h-5 px-1.5">
                            {filterMonsters(manquants, true).length}
                        </Badge>
                    </TabsTrigger>
                    <TabsTrigger value="possedes" className="gap-2">
                        <span className="hidden sm:inline">🟢</span>
                        Possédés
                        <Badge variant="secondary" className="ml-1 h-5 px-1.5">
                            {filterMonsters(possedes).length}
                        </Badge>
                    </TabsTrigger>
                    <TabsTrigger value="doublons" className="gap-2">
                        <span className="hidden sm:inline">🟡</span>
                        Doublons
                        <Badge variant="secondary" className="ml-1 h-5 px-1.5">
                            {filterMonsters(doublons).length}
                        </Badge>
                    </TabsTrigger>
                </TabsList>

                <TabsContent value="manquants" className="mt-6">
                    <MonsterGrid
                        monsters={filterMonsters(manquants, true)}
                        guildId={guildId}
                        emptyMessage={hasActiveFilters
                            ? showExchangeableOnly
                                ? "Aucun monstre échangeable ne correspond aux filtres"
                                : "Aucun monstre manquant ne correspond aux filtres"
                            : "Vous avez tous les archimonstres ! 🎉"
                        }
                        showOwners
                        doublonsMap={doublonsMap}
                    />
                </TabsContent>

                <TabsContent value="possedes" className="mt-6">
                    <MonsterGrid
                        monsters={filterMonsters(possedes)}
                        guildId={guildId}
                        emptyMessage={hasActiveFilters
                            ? "Aucun monstre possédé ne correspond aux filtres"
                            : "Aucun archimonstre avec un seul exemplaire"
                        }
                        showOwners={false}
                        doublonsMap={{}}
                    />
                </TabsContent>

                <TabsContent value="doublons" className="mt-6">
                    <MonsterGrid
                        monsters={filterMonsters(doublons)}
                        guildId={guildId}
                        emptyMessage={hasActiveFilters
                            ? "Aucun doublon ne correspond aux filtres"
                            : "Vous n'avez pas de doublons à proposer"
                        }
                        showOwners={false}
                        doublonsMap={{}}
                    />
                </TabsContent>
            </Tabs>
        </div>
    );
}

// -----------------------------------------------------------------------------
// Sub-components
// -----------------------------------------------------------------------------

function StatCard({
    label,
    value,
    icon,
    color,
    subValue,
    subColor,
}: {
    label: string;
    value: number;
    icon: React.ReactNode;
    color: string;
    subValue?: string;
    subColor?: string;
}) {
    return (
        <Card className="border-border/50 bg-card/50 backdrop-blur-sm">
            <CardContent className="p-4">
                <div className="flex items-center gap-3">
                    <div className={`${color}`}>{icon}</div>
                    <div>
                        <p className="text-2xl font-bold">{value}</p>
                        <p className="text-xs text-muted-foreground">{label}</p>
                        {subValue && (
                            <p className={`text-xs font-medium ${subColor || "text-muted-foreground"}`}>
                                ✨ {subValue}
                            </p>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

function MonsterGrid({
    monsters,
    guildId,
    emptyMessage,
    showOwners,
    doublonsMap,
}: {
    monsters: OcreMonster[];
    guildId: string;
    emptyMessage: string;
    showOwners: boolean;
    doublonsMap: Record<number, number>;
}) {
    if (monsters.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-12 text-center">
                <Bug className="h-12 w-12 text-muted-foreground/30 mb-4" />
                <p className="text-muted-foreground">{emptyMessage}</p>
            </div>
        );
    }

    return (
        <ScrollArea className="h-[600px] pr-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {monsters.map((monster) => (
                    <MonsterCard
                        key={monster.id}
                        monster={monster}
                        guildId={guildId}
                        showOwners={showOwners}
                        availableHelpers={doublonsMap[monster.id] || 0}
                    />
                ))}
            </div>
        </ScrollArea>
    );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { Copy, Check, Loader2, MapPin, User, Users, Sparkles } from "lucide-react";
import type { OcreMonster } from "@/lib/metamob-client";
import { findMonsterOwnersAction, type ExchangePartner } from "@/server/actions/ocre-actions";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface MonsterCardProps {
    monster: OcreMonster;
    guildId: string;
    showOwners?: boolean;
    compact?: boolean;
    // Pre-computed number of available helpers (from doublonsMap)
    availableHelpers?: number;
    // Pre-loaded owners from parent (optional optimization)
    preloadedOwners?: ExchangePartner[];
}

export function MonsterCard({
    monster,
    guildId,
    showOwners = true,
    compact = false,
    availableHelpers = 0,
    preloadedOwners,
}: MonsterCardProps) {
    const [owners, setOwners] = useState<ExchangePartner[]>(preloadedOwners || []);
    const [loadingOwners, setLoadingOwners] = useState(false);
    const [ownersLoaded, setOwnersLoaded] = useState(!!preloadedOwners);
    const [showOwnersSection, setShowOwnersSection] = useState(false);
    const [copiedPseudo, setCopiedPseudo] = useState<string | null>(null);

    // Load owners on demand (not auto!)
    const loadOwners = async () => {
        if (ownersLoaded) {
            setShowOwnersSection(!showOwnersSection);
            return;
        }

        setLoadingOwners(true);
        setShowOwnersSection(true);
        const result = await findMonsterOwnersAction({ guildId, monsterId: monster.id });
        if (result.success && result.data) {
            setOwners(result.data);
        }
        setOwnersLoaded(true);
        setLoadingOwners(false);
    };

    const stateConfig: Record<string, { label: string; color: string; icon: string }> = {
        MANQUANT: {
            label: "Manquant",
            color: "bg-red-500/10 text-red-500 border-red-500/30",
            icon: "🔴",
        },
        POSSEDE: {
            label: "Possédé",
            color: "bg-emerald-500/10 text-emerald-500 border-emerald-500/30",
            icon: "🟢",
        },
        DOUBLON: {
            label: "Doublon",
            color: "bg-amber-500/10 text-amber-500 border-amber-500/30",
            icon: "🟡",
        },
    };

    const config = stateConfig[monster.state];
    const hasAvailableExchange = availableHelpers > 0;

    const handleCopyMP = (owner: ExchangePartner, e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        const message = `/w ${owner.characterName} Salut ! Tu aurais ${monster.name} en doublon à échanger ? :)`;
        navigator.clipboard.writeText(message);
        setCopiedPseudo(owner.username);
        toast.success("Message copié !");
        setTimeout(() => setCopiedPseudo(null), 2000);
    };

    if (compact) {
        return (
            <div className="flex items-center gap-3 p-2 rounded-lg bg-card/50 border border-border/50">
                {monster.image && (
                    <div className="relative w-10 h-10 shrink-0 rounded overflow-hidden bg-black/20">
                        <Image
                            src={monster.image}
                            alt={monster.name}
                            fill
                            className="object-contain"
                            sizes="40px"
                        />
                    </div>
                )}
                <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium truncate">{monster.name}</p>
                    <p className="text-xs text-muted-foreground truncate">{monster.zone}</p>
                </div>
                <Badge variant="outline" className={cn("shrink-0", config.color)}>
                    x{monster.owned}
                </Badge>
            </div>
        );
    }

    return (
        <Card className={cn(
            "overflow-hidden border-border/50 bg-card/50 backdrop-blur-sm transition-colors",
            hasAvailableExchange
                ? "border-emerald-500/50 hover:border-emerald-500/70 ring-1 ring-emerald-500/20"
                : "hover:border-primary/30"
        )}>
            <CardContent className="p-4">
                <div className="flex gap-4">
                    {/* Monster Image */}
                    {monster.image && (
                        <div className="relative w-16 h-16 shrink-0 rounded-lg overflow-hidden bg-black/20 border border-border/30">
                            <Image
                                src={monster.image}
                                alt={monster.name}
                                fill
                                className="object-contain"
                                sizes="64px"
                            />
                            {/* Exchange available indicator */}
                            {hasAvailableExchange && (
                                <div className="absolute -top-1 -right-1 bg-emerald-500 rounded-full p-0.5">
                                    <Sparkles className="h-3 w-3 text-white" />
                                </div>
                            )}
                        </div>
                    )}

                    {/* Monster Info */}
                    <div className="flex-1 min-w-0 space-y-1">
                        <div className="flex items-start justify-between gap-2">
                            <h3 className="font-medium text-sm leading-tight line-clamp-2">
                                {monster.name}
                            </h3>
                            <Badge variant="outline" className={cn("shrink-0", config.color)}>
                                {config.icon} x{monster.owned}
                            </Badge>
                        </div>

                        <div className="flex items-center gap-1 text-xs text-muted-foreground">
                            <MapPin className="h-3 w-3" />
                            <span className="truncate">{monster.zone}</span>
                            {monster.subzone && (
                                <span className="truncate text-muted-foreground/60">
                                    • {monster.subzone}
                                </span>
                            )}
                        </div>

                        {/* Exchange available badge */}
                        {hasAvailableExchange && !showOwnersSection && (
                            <Badge
                                variant="outline"
                                className="text-[10px] px-1.5 py-0 h-4 bg-emerald-500/10 text-emerald-500 border-emerald-500/30"
                            >
                                <Sparkles className="h-2.5 w-2.5 mr-1" />
                                {availableHelpers} membre{availableHelpers > 1 ? "s" : ""}
                            </Badge>
                        )}
                    </div>
                </div>

                {/* Find helpers button - only for MANQUANT monsters */}
                {showOwners && monster.state === "MANQUANT" && (
                    <div className="mt-3 pt-3 border-t border-border/30">
                        {!showOwnersSection ? (
                            <Button
                                variant={hasAvailableExchange ? "default" : "ghost"}
                                size="sm"
                                className={cn(
                                    "w-full h-8 text-xs gap-2",
                                    hasAvailableExchange && "bg-emerald-600 hover:bg-emerald-700"
                                )}
                                onClick={loadOwners}
                                disabled={loadingOwners}
                            >
                                {loadingOwners ? (
                                    <Loader2 className="h-3 w-3 animate-spin" />
                                ) : hasAvailableExchange ? (
                                    <Sparkles className="h-3 w-3" />
                                ) : (
                                    <Users className="h-3 w-3" />
                                )}
                                {hasAvailableExchange
                                    ? `${availableHelpers} peut échanger !`
                                    : "Qui peut m'aider ?"
                                }
                            </Button>
                        ) : loadingOwners ? (
                            <div className="flex items-center gap-2 text-xs text-muted-foreground">
                                <Loader2 className="h-3 w-3 animate-spin" />
                                Recherche...
                            </div>
                        ) : owners.length === 0 ? (
                            <p className="text-xs text-muted-foreground/60 italic text-center py-1">
                                Aucun membre n&apos;a ce monstre en doublon
                            </p>
                        ) : (
                            <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                    <p className="text-xs text-muted-foreground">
                                        {owners.length} membre{owners.length > 1 ? "s" : ""} :
                                    </p>
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        className="h-6 px-2 text-xs text-muted-foreground"
                                        onClick={() => setShowOwnersSection(false)}
                                    >
                                        Masquer
                                    </Button>
                                </div>
                                <div className="flex flex-wrap gap-1.5">
                                    {owners.slice(0, 4).map((owner) => (
                                        <OwnerBadge
                                            key={owner.profileId}
                                            owner={owner}
                                            guildId={guildId}
                                            monsterName={monster.name}
                                            copiedPseudo={copiedPseudo}
                                            onCopy={(e) => handleCopyMP(owner, e)}
                                        />
                                    ))}
                                    {owners.length > 4 && (
                                        <Badge variant="outline" className="text-xs px-2 py-0.5">
                                            +{owners.length - 4}
                                        </Badge>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {/* Propose indicator for DOUBLON */}
                {monster.state === "DOUBLON" && (
                    <div className="mt-3 pt-3 border-t border-border/30">
                        <Badge variant="outline" className="w-full justify-center bg-amber-500/10 text-amber-500 border-amber-500/30">
                            Proposé à l&apos;échange sur Metamob
                        </Badge>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

// -----------------------------------------------------------------------------
// Owner Badge Component - Clickable badge linking to member profile
// -----------------------------------------------------------------------------

function OwnerBadge({
    owner,
    guildId,
    monsterName,
    copiedPseudo,
    onCopy,
}: {
    owner: ExchangePartner;
    guildId: string;
    monsterName: string;
    copiedPseudo: string | null;
    onCopy: (e: React.MouseEvent) => void;
}) {
    const isCopied = copiedPseudo === owner.username;

    return (
        <Tooltip>
            <TooltipTrigger asChild>
                <div className="group flex items-center gap-1 bg-primary/10 hover:bg-primary/20 border border-primary/30 rounded-full px-2 py-0.5 transition-colors">
                    <Link
                        href={`/dashboard/${guildId}/members/${owner.profileId}`}
                        className="flex items-center gap-1 text-xs font-medium text-primary hover:underline"
                    >
                        <User className="h-3 w-3" />
                        {owner.characterName}
                    </Link>
                    <span className="text-[10px] text-primary/70">x{owner.monstersTheyHave[0]?.available || 1}</span>
                    <button
                        onClick={onCopy}
                        className="ml-0.5 p-0.5 rounded hover:bg-primary/30 transition-colors"
                    >
                        {isCopied ? (
                            <Check className="h-3 w-3 text-emerald-500" />
                        ) : (
                            <Copy className="h-3 w-3 opacity-50 group-hover:opacity-100" />
                        )}
                    </button>
                </div>
            </TooltipTrigger>
            <TooltipContent>
                <p>Voir le profil de {owner.characterName}</p>
                <p className="text-xs text-muted-foreground">Cliquer sur 📋 pour copier le MP</p>
            </TooltipContent>
        </Tooltip>
    );
}

"use client";

import React, { useEffect, useState, useRef, useMemo, useLayoutEffect } from "react";
import { io, Socket } from "socket.io-client";
import { buildWsUrl } from "@/lib/socket-utils";
import { useSession } from "next-auth/react";
import { motion, AnimatePresence } from "framer-motion";
import { 
    Loader2, 
    Heart, 
    Zap, 
    Bomb, 
    Timer, 
    Users, 
    LayoutGrid, 
    Send,
    AlertCircle,
    Info,
    Trophy,
    Settings,
    Maximize2,
    Minimize2,
    Sparkles,
    CheckCircle2,
    XCircle,
    HelpCircle,
    Orbit,
    ArrowLeft,
    Mic,
    MicOff,
    LogOut
} from "lucide-react";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { AtmosphericParticles } from "../ui/AtmosphericParticles";
import { ShareRoomButton } from "../shared/ShareRoomButton";
import { useBombSounds } from "./useBombSounds";
import { useDiscordVoice } from "@/hooks/use-discord-voice";
import { DiscordVoiceOverlay } from "@/components/shared/DiscordVoiceOverlay";

export default function BombGame({ roomId: initialRoomId, guildId }: { roomId?: string, guildId: string }) {
    const { data: session, status: sessionStatus } = useSession();
    const [socket, setSocket] = useState<Socket | null>(null);
    const [gameState, setGameState] = useState<any>(null);
    const [wordInput, setWordInput] = useState("");
    const [isJoining, setIsJoining] = useState(false);
    const [lobbyRooms, setLobbyRooms] = useState<any[]>([]);
    const [explosionFlash, setExplosionFlash] = useState(false);
    const [shakeCount, setShakeCount] = useState(0);
    const [winnerData, setWinnerData] = useState<any>(null);
    const [leaderboard, setLeaderboard] = useState<any[]>([]);
    const [showGameEnd, setShowGameEnd] = useState(false);
    const triggerShake = () => setShakeCount(prev => prev + 1);
    const [isImmersive, setIsImmersive] = useState(false);
    const [showOptions, setShowOptions] = useState(false);
    const [showTutorial, setShowTutorial] = useState(false);
    const [bloodSplats, setBloodSplats] = useState<any[]>([]);
    const [winnerName, setWinnerName] = useState<string | null>(null);
    const [localTimeLeft, setLocalTimeLeft] = useState<number>(0);
    const [explosionPlayerId, setExplosionPlayerId] = useState<string | null>(null);
    const [typingMap, setTypingMap] = useState<Record<string, string>>({});
    // Mode selection: null = not yet chosen, 'solo' = solo vs bot, 'multi' = multiplayer
    const [selectedMode, setSelectedMode] = useState<'solo' | 'multi' | null>(initialRoomId ? 'multi' : null);
    
    const inputRef = useRef<HTMLInputElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const sessionRef = useRef(session);
    useEffect(() => { sessionRef.current = session; }, [session]);
    const { playTick, playUrgentTick, playExplosion, playSuccess } = useBombSounds();

    // Discord Voice Monitoring
    const { voiceUsers } = useDiscordVoice(guildId, socket);
    const [showVoiceOverlay, setShowVoiceOverlay] = useState(true);

    // Filter voice users to only show active participants (not spectators)
    const gamePlayerIds = useMemo(() => 
        gameState?.players
            ?.filter((p: any) => p.discordId && !p.isSpectator)
            .map((p: any) => p.discordId) || [],
        [gameState?.players]
    );

    const voiceUserIds = voiceUsers.map(u => u.userId);


    // WebSocket Connection — wait for session to fully load before connecting
    useEffect(() => {
        if (sessionStatus === 'loading') return; // Wait — don't connect until session is known
        if (!session?.user?.id) return;          // Not authenticated

        const s = io(buildWsUrl(), {
            path: "/socket.io/",
            transports: ["websocket", "polling"],
            query: { guildId }
        });
        setSocket(s);

        s.on("connect", () => {
            const user = sessionRef.current?.user;
            if (!user) return;
            if (initialRoomId) {
                s.emit("bomb:room:join", {
                    roomId: initialRoomId,
                    playerObj: { 
                        userId: user.id, 
                        discordId: (user as any).discordId,
                        userName: user.name, 
                        userAvatar: user.image, 
                        guildId 
                    }
                });
            } else {
                s.emit("bomb:room:list");
            }
        });

        s.on("bomb:sync", (state) => { 
            setIsJoining(false); 
            setGameState((prev: any) => {
                // Keep existing transition logic for toasts...
                return state;
            }); 
            setLocalTimeLeft(state.timeLeft);
            // We no longer automatically set showGameEnd(false) here to avoid racing with the results screen
            if (state.state === 'LOBBY') {
                setShowOptions(false); 
            }
        });
        s.on("bomb:game-end", (data) => {
            console.info("🎮 Game Ended event received:", data);
            setWinnerData(data);
            setWinnerName(data.winnerName || null);
            setLeaderboard(data.leaderboard || []);
            setShowGameEnd(true);
        });
        s.on("bomb:tick", (data) => {
            setLocalTimeLeft(data.timeLeft);
            if (data.timeLeft <= 3) playUrgentTick();
            else playTick();
        });
        s.on("bomb:room:list", (list) => setLobbyRooms(list));
        s.on("bomb:explosion", (data) => {
            setExplosionFlash(true);
            triggerShake();
            setExplosionPlayerId(data.playerId);
            playExplosion();
            const newSplats = Array.from({ length: 5 }).map(() => ({
                id: Math.random(),
                x: Math.random() * 100,
                y: Math.random() * 100,
                scale: 0.5 + Math.random() * 1.5,
                rotate: Math.random() * 360
            }));
            setBloodSplats(prev => [...prev.slice(-10), ...newSplats]);
            setTimeout(() => { setExplosionFlash(false); }, 800);
            setTimeout(() => { setBloodSplats([]); setExplosionPlayerId(null); }, 2500);
            if (data.hintWord) {
                toast(`💥 ${data.playerName || 'Le joueur'} a raté « ${data.syllable} » — on pouvait dire « ${data.hintWord} »`, { duration: 4000 });
            }
        });
        s.on("bomb:word-success", () => { 
            setWordInput(""); 
            setTypingMap({}); // Clear local typing on success
            playSuccess(); 
            triggerShake();
        });
        s.on("bomb:typing-update", (data: { playerId: string; text: string }) => {
            setTypingMap(prev => ({ ...prev, [data.playerId]: data.text }));
        });
        s.on("bomb:typing-reset", () => {
            setTypingMap({});
        });
        s.on("bomb:word-error", (data) => toast.error(data.message));
        s.on("bomb:bonus-life", (data) => {
            if (data.playerId === s.id) {
                toast("🔥 ALPHABET COMPLÉTÉ ! +1 VIE", { icon: <Sparkles className="text-yellow-500" /> });
            }
        });

        return () => { s.disconnect(); };
    }, [sessionStatus, session?.user?.id, initialRoomId, guildId]);

    const prevState = useRef<string | null>(null);
    useLayoutEffect(() => {
        if (gameState?.state === 'PLAYING') {
            const currentP = gameState?.players?.[gameState.currentTurnIndex];
            
            // Trigger turn-change shake for feedback — but NOT on the very first turn of the game
            if (prevState.current === 'PLAYING') {
                triggerShake();
            }

            if (currentP?.id === socket?.id && inputRef.current) {
                inputRef.current.focus();
            }
        }
        prevState.current = gameState?.state || null;
    }, [gameState?.currentTurnIndex, gameState?.state, socket?.id]);

    const handleCreateRoom = (isSolo = false) => {
        const id = Math.random().toString(36).substring(2, 9).toUpperCase();
        const user = sessionRef.current?.user;
        if (!user) return;
        socket?.emit("bomb:room:join", {
            roomId: id,
            playerObj: { 
                userId: user.id, 
                discordId: (user as any).discordId,
                userName: user.name, 
                userAvatar: user.image, 
                guildId,
                isSoloMode: isSolo  // Passed directly so server applies it synchronously on room creation
            }
        });
        window.history.replaceState(null, "", `?room=${id}`);
    };

    const handleSelectSolo = () => {
        setSelectedMode('solo');
        const id = Math.random().toString(36).substring(2, 9).toUpperCase();
        const user = sessionRef.current?.user;
        if (!user) return;
        socket?.emit("bomb:room:join", {
            roomId: id,
            playerObj: { 
                userId: user.id, 
                discordId: (user as any).discordId,
                userName: user.name, 
                userAvatar: user.image, 
                guildId,
                isSoloMode: true,
                autoStart: false // Request the server not to auto-start if possible
            }
        });
        window.history.replaceState(null, "", `?room=${id}`);
    };

    const handleSelectMulti = () => {
        setSelectedMode('multi');
        socket?.emit("bomb:room:list");
    };

    const handleJoinRoom = (id: string) => {
        const user = sessionRef.current?.user;
        if (!user) return;
        socket?.emit("bomb:room:join", {
            roomId: id,
            playerObj: { 
                userId: user.id, 
                discordId: (user as any).discordId,
                userName: user.name, 
                userAvatar: user.image, 
                guildId 
            }
        });
        window.history.replaceState(null, "", `?room=${id}`);
    };

    const handleStartGame = () => socket?.emit("bomb:start-game");
    const handleToggleReady = () => socket?.emit("bomb:toggle-ready");
    const handleUpdateConfig = (cfg: any) => socket?.emit("bomb:update-config", cfg);
    const handleRestart = (e?: React.MouseEvent) => {
        if (e) e.preventDefault();
        setShowGameEnd(false);
        setWinnerName(null); 
        setLeaderboard([]); 
        setGameState((prev: any) => prev ? { ...prev, currentSyllable: "" } : null);
        socket?.emit("bomb:restart"); 
    };
    const handleLeave = (e?: React.MouseEvent) => { 
        if (e) {
            e.preventDefault();
            e.stopPropagation();
        }
        
        // Force cleanup of all UI blockers
        setShowGameEnd(false);
        setShowOptions(false);
        setIsJoining(false);
        
        // Emit leave and disconnect socket to be sure
        socket?.emit("bomb:leave");
        socket?.disconnect();
        
        // Clear state
        setGameState(null);
        setSelectedMode(null);
        
        // Clean URL properly to prevent auto-rejoin logic from firing
        const url = new URL(window.location.href);
        url.searchParams.delete('room'); // legacy
        url.searchParams.delete('roomId');
        window.history.replaceState(null, "", url.pathname);
        
        // Hard redirect after short delay to ensure clean state if still stuck
        const doRedirect = () => { window.location.href = "/dashboard"; }; // nosemgrep
        setTimeout(doRedirect, 100);
    };
    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setWordInput(val);
        socket?.emit("bomb:typing", val);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const cleaned = wordInput.trim().replace(/\s\s+/g, ' ');
        if (!cleaned) return;
        socket?.emit("bomb:submit-word", cleaned);
        setWordInput("");
        setTypingMap({});
    };

    // Helper to highlight matching syllable in a word
    // Helper to highlight matching syllable in a word (now recursively handles multi-part words)
    const highlightCompoundWord = (word: string, syllable: string) => {
        if (!syllable || !word) return <span className="opacity-40 italic">...</span>;
        
        const stopWords = ['de', 'du', "d'", 'la', 'le', "l'", 'les', 'des', 'au', 'aux', 'en', 'sur', 'sous', 'vers', 'par', 'pour'];
        const parts = word.split(' ');
        
        return (
            <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                {parts.map((part, idx) => {
                    const normalizedPart = part.toUpperCase();
                    const normalizedSyllable = syllable.toUpperCase();
                    const index = normalizedPart.indexOf(normalizedSyllable);
                    const isStopWord = stopWords.includes(part.toLowerCase());

                    return (
                        <div 
                            key={`${part}-${idx}`}
                            className={cn(
                                "flex items-center gap-1 px-3 py-1.5 rounded-2xl border transition-all duration-300",
                                isStopWord 
                                    ? "bg-white/5 border-dashed border-white/20 opacity-60 scale-90" 
                                    : "bg-indigo-500/10 border-indigo-500/20 shadow-[0_0_20px_rgba(79,70,229,0.1)]"
                            )}
                        >
                            {index === -1 ? (
                                <span className={cn(isStopWord ? "text-[10px] lowercase font-medium opacity-60" : "text-lg font-black italic uppercase text-white/90")}>
                                    {part}
                                </span>
                            ) : (
                                <span className="text-lg font-black italic uppercase text-foreground">
                                    {part.substring(0, index)}
                                    <motion.span 
                                        initial={{ textShadow: "0 0 0px rgba(129,140,248,0)" }}
                                        animate={{ 
                                            textShadow: ["0 0 5px rgba(129,140,248,0.5)", "0 0 15px rgba(129,140,248,0.8)", "0 0 5px rgba(129,140,248,0.5)"],
                                            color: ["#818cf8", "#c7d2fe", "#818cf8"]
                                        }}
                                        transition={{ repeat: Infinity, duration: 2 }}
                                        className="font-[1000] underline decoration-indigo-500/50 underline-offset-4"
                                    >
                                        {part.substring(index, index + syllable.length)}
                                    </motion.span>
                                    {part.substring(index + syllable.length)}
                                </span>
                            )}
                        </div>
                    );
                })}
            </div>
        );
    };

    // Calculate player positions in circle (Responsive & Unified)
    const playerPositions = useMemo(() => {
        if (!gameState?.players) return [];
        const allPlayers = gameState.players;
        const activePlayers = allPlayers.filter((p: any) => !p.isSpectator);
        const spectators = allPlayers.filter((p: any) => p.isSpectator);
        
        const activeCount = activePlayers.length || 1;
        const specCount = spectators.length;

        return allPlayers.map((p: any, i: number) => {
            if (!p.isSpectator) {
                const activeIndex = activePlayers.findIndex((ap: any) => ap.id === p.id);
                const angle = (activeIndex / activeCount) * 2 * Math.PI - Math.PI / 2;
                const baseRadius = activeCount <= 4 ? 38 : 40; 
                return {
                    x: Math.cos(angle) * baseRadius,
                    y: Math.sin(angle) * baseRadius,
                    scale: activeCount > 6 ? 0.85 : 1.0,
                    opacity: 1,
                    isSpec: false
                };
            } else {
                // Spectators in an outer, wider circle, smaller
                const specIndex = spectators.findIndex((sp: any) => sp.id === p.id);
                const angle = (specIndex / (specCount || 1)) * 2 * Math.PI + Math.PI / 4;
                const specRadius = 46;
                return {
                    x: Math.cos(angle) * specRadius,
                    y: Math.sin(angle) * specRadius,
                    scale: 0.4,
                    opacity: 0.5,
                    isSpec: true
                };
            }
        });
    }, [gameState?.players?.length, gameState?.state]);

    // --- Session still loading ---
    if (sessionStatus === 'loading') {
        return (
            <div className="h-full w-full bg-[#0a0d14] flex flex-col items-center justify-center relative overflow-hidden">
                <AtmosphericParticles />
                <div className="z-10 flex flex-col items-center gap-6">
                    <Loader2 className="w-12 h-12 animate-spin text-indigo-500" />
                    <p className="text-zinc-500 font-bold uppercase tracking-widest text-[10px] italic">Authentification...</p>
                </div>
            </div>
        );
    }

    // Initial Loading / Joining
    if (!gameState) {
        if (initialRoomId) {
            return (
                <div className="h-full w-full bg-[#0a0d14] flex flex-col items-center justify-center relative overflow-hidden">
                    <AtmosphericParticles />
                    <div className="z-10 flex flex-col items-center gap-6">
                        <Loader2 className="w-12 h-12 animate-spin text-indigo-500" />
                        <div className="text-center">
                            <h2 className="text-2xl font-black text-white uppercase italic tracking-tighter">Connexion au salon...</h2>
                            <p className="text-zinc-500 font-bold uppercase tracking-widest text-[10px] italic mb-6">Syllaburation en cours</p>
                            <button 
                                onClick={(e) => handleLeave(e)}
                                className="px-4 py-2 rounded-xl bg-white/5 hover:bg-red-500/20 border border-white/10 text-white/40 hover:text-red-400 text-[10px] font-black uppercase italic tracking-widest transition-all"
                            >
                                Quitter (Annuler)
                            </button>
                        </div>
                    </div>
                </div>
            );
        }

        // ── MODE SELECTION SCREEN ────────────────────────────────────────────
        if (selectedMode === null) {
            return (
                <div className="h-full w-full bg-[#0a0614] flex flex-col items-center justify-center relative overflow-hidden">
                    <AtmosphericParticles />

                    {/* Ambient glow */}
                    <div className="absolute inset-0 pointer-events-none">
                        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-500/10 rounded-full blur-[120px]" />
                        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-violet-500/10 rounded-full blur-[120px]" />
                    </div>

                    <motion.div
                        initial={{ opacity: 0, y: 30 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.5 }}
                        className="z-10 flex flex-col items-center gap-10 px-4 w-full max-w-3xl"
                    >
                        {/* Back button */}
                        <button
                            onClick={() => window.location.href = `/dashboard/${guildId}/mini-jeux`}
                            className="self-start flex items-center gap-2 text-white/30 hover:text-white/70 transition-colors group"
                        >
                            <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
                            <span className="text-[10px] font-black uppercase italic tracking-widest">Retour aux jeux</span>
                        </button>

                        {/* Title */}
                        <div className="text-center space-y-3">
                            <div className="flex items-center justify-center gap-4 mb-2">
                                <img src="/assets/dofus/classes/13.png" className="w-16 h-16 object-contain drop-shadow-[0_0_20px_rgba(99,102,241,0.5)]" alt="" />
                            </div>
                            <h1 className="text-7xl font-black text-white uppercase italic tracking-tighter drop-shadow-[0_0_40px_rgba(99,102,241,0.3)]">Sigil-Bomb</h1>
                            <p className="text-white/30 font-bold uppercase tracking-[0.4em] text-[10px] italic">Le défi de la Reine des Voleurs</p>
                        </div>

                        {/* Mode cards */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5 w-full">
                            {/* SOLO */}
                            <motion.button
                                whileHover={{ scale: 1.02, y: -4 }}
                                whileTap={{ scale: 0.98 }}
                                onClick={handleSelectSolo}
                                className="group relative p-8 rounded-[2.5rem] bg-gradient-to-br from-emerald-500/20 to-teal-500/10 border border-emerald-500/30 hover:border-emerald-500/60 transition-all shadow-xl overflow-hidden flex flex-col items-center gap-5 text-center"
                            >
                                <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                                <div className="absolute -top-8 -right-8 w-32 h-32 bg-emerald-500/10 rounded-full blur-2xl group-hover:bg-emerald-500/20 transition-all" />
                                <div className="relative z-10 flex flex-col items-center gap-5">
                                    <div className="w-20 h-20 rounded-3xl bg-emerald-500/20 border border-emerald-500/30 flex items-center justify-center group-hover:bg-emerald-500/30 transition-all">
                                        <img src="/assets/dofus/classes/9.png" className="w-12 h-12 object-contain" alt="Bot" />
                                    </div>
                                    <div>
                                        <h2 className="text-2xl font-black text-white uppercase italic tracking-tighter">Solo vs Bot</h2>
                                        <p className="text-emerald-400/60 text-[10px] font-black uppercase tracking-widest mt-1 italic">Crâ-Mée t'attend !</p>
                                    </div>
                                    <p className="text-white/40 text-xs font-medium leading-relaxed">
                                        Affronte notre robot Crâ de manière autonome. Parfait pour s'entraîner et maîtriser le lore Dofus.
                                    </p>
                                    <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-emerald-500/20 border border-emerald-500/30">
                                        <Zap size={12} className="text-emerald-400" />
                                        <span className="text-emerald-400 text-[10px] font-black uppercase tracking-widest">Lancer immédiatement</span>
                                    </div>
                                </div>
                            </motion.button>

                            {/* MULTI */}
                            <motion.button
                                whileHover={{ scale: 1.02, y: -4 }}
                                whileTap={{ scale: 0.98 }}
                                onClick={handleSelectMulti}
                                className="group relative p-8 rounded-[2.5rem] bg-gradient-to-br from-indigo-500/20 to-violet-500/10 border border-indigo-500/30 hover:border-indigo-500/60 transition-all shadow-xl overflow-hidden flex flex-col items-center gap-5 text-center"
                            >
                                <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                                <div className="absolute -top-8 -right-8 w-32 h-32 bg-indigo-500/10 rounded-full blur-2xl group-hover:bg-indigo-500/20 transition-all" />
                                <div className="relative z-10 flex flex-col items-center gap-5">
                                    <div className="w-20 h-20 rounded-3xl bg-indigo-500/20 border border-indigo-500/30 flex items-center justify-center group-hover:bg-indigo-500/30 transition-all">
                                        <Users size={32} className="text-indigo-400" />
                                    </div>
                                    <div>
                                        <h2 className="text-2xl font-black text-white uppercase italic tracking-tighter">Multijoueur</h2>
                                        <p className="text-indigo-400/60 text-[10px] font-black uppercase tracking-widest mt-1 italic">Jusqu'à 8 joueurs</p>
                                    </div>
                                    <p className="text-white/40 text-xs font-medium leading-relaxed">
                                        Crée ou rejoins une salle et défie ta guilde. L'hôte configure les règles dans le lobby.
                                    </p>
                                    <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-indigo-500/20 border border-indigo-500/30">
                                        <Users size={12} className="text-indigo-400" />
                                        <span className="text-indigo-400 text-[10px] font-black uppercase tracking-widest">Créer / Rejoindre</span>
                                    </div>
                                </div>
                            </motion.button>
                        </div>

                        {/* Help hint */}
                        <p className="text-white/15 text-[10px] font-black uppercase tracking-[0.3em] italic">
                            Les règles se configurent dans le lobby — après le choix du mode
                        </p>
                    </motion.div>
                </div>
            );
        }

        // ── MULTI: ROOM LIST / CREATE SCREEN ────────────────────────────────
        return (
            <div className="h-full w-full bg-[#0a0614] flex flex-col items-center justify-center relative overflow-hidden">
                <AtmosphericParticles />
                <div className="absolute inset-0 pointer-events-none">
                    <div className="absolute top-1/3 left-1/3 w-96 h-96 bg-indigo-500/10 rounded-full blur-[120px]" />
                </div>
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="z-10 text-center space-y-8 p-12 bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-[3rem] shadow-2xl max-w-2xl w-full mx-4 relative">
                    {/* Back to mode selection */}
                    <button
                        onClick={() => setSelectedMode(null)}
                        className="absolute top-8 left-8 flex items-center gap-2 text-white/30 hover:text-white/70 transition-colors group"
                    >
                        <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
                        <span className="text-[10px] font-black uppercase italic tracking-widest hidden md:inline">Retour</span>
                    </button>
                    <div className="space-y-2">
                        <div className="flex items-center justify-center gap-3 mb-3">
                            <div className="px-3 py-1 rounded-full bg-indigo-500/20 border border-indigo-500/30">
                                <span className="text-indigo-400 text-[9px] font-black uppercase tracking-widest">Multijoueur</span>
                            </div>
                        </div>
                        <h1 className="text-5xl font-black text-white uppercase italic tracking-tighter">Sigil-Bomb</h1>
                        <p className="text-white/30 font-bold uppercase tracking-widest text-[10px] italic">Le défi de la Reine des Voleurs</p>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <button onClick={() => handleCreateRoom(false)} className="p-8 rounded-[2rem] bg-indigo-500 hover:bg-indigo-400 text-white transition-all border-b-[8px] border-black/20 flex flex-col items-center gap-4 group shadow-xl shadow-indigo-500/20">
                             <Zap className="w-10 h-10 group-hover:scale-110 transition-transform" />
                             <span className="font-black uppercase italic tracking-widest">Créer une salle</span>
                        </button>
                        <button onClick={() => socket?.emit("bomb:room:list")} className="p-8 rounded-[2rem] bg-white/5 hover:bg-white/10 text-white transition-all border border-white/10 hover:border-white/20 flex flex-col items-center gap-4 group">
                             <Users className="w-10 h-10 group-hover:scale-110 transition-transform" />
                             <span className="font-black uppercase italic tracking-widest">Voir les salons</span>
                        </button>
                    </div>
                    {lobbyRooms.length > 0 && (
                        <div className="space-y-4 pt-8 border-t border-white/10">
                            <h3 className="text-[10px] font-black text-white/20 uppercase tracking-widest italic">Salons disponibles</h3>
                            <div className="grid grid-cols-1 gap-3 max-h-[250px] overflow-y-auto pr-2 custom-scrollbar">
                                {lobbyRooms.map(room => (
                                    <button key={room.roomId} onClick={() => handleJoinRoom(room.roomId)} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/10 hover:border-indigo-500/50 hover:bg-white/10 transition-all group">
                                        <div className="flex flex-col items-start leading-none">
                                            <span className="font-black text-white italic">{room.hostName || room.roomId}</span>
                                            <span className="text-[8px] text-white/20 uppercase font-black tracking-widest mt-1">{room.playerCount} JOUEURS • {room.state}</span>
                                        </div>
                                        <LayoutGrid className="w-5 h-5 text-white/20 group-hover:text-indigo-500 transition-colors" />
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </motion.div>
            </div>
        );
    }


    const myPlayer = gameState.players?.find((p: any) => p.userId === session?.user?.id || p.id === socket?.id);
    const currentPlayer = gameState?.players?.[gameState?.currentTurnIndex];
    const isHost = myPlayer?.id === gameState.hostId || socket?.id === gameState.hostId || (gameState.players?.filter((p: any) => !p.isBot).length === 1 && !myPlayer?.isSpectator);
    if (!gameState || !gameState.players || !gameState.config) return <div className="h-full w-full bg-[#0a0d14] flex items-center justify-center"><Loader2 className="animate-spin text-indigo-500" /></div>;

    const isMyTurn = currentPlayer?.id === socket?.id;
    const bombTargetPos = playerPositions[gameState.currentTurnIndex] || { x: 0, y: 0 };
    const spectatorsCount = gameState.players?.filter((p: any) => p.isSpectator).length || 0;
    const activePlayers = gameState.players?.filter((p: any) => !p.isSpectator) || [];
    const activePlayersCount = activePlayers.length;
    const isSoloMode = gameState.config?.isSoloMode;
    const hasEnoughPlayers = activePlayersCount >= 2 || (activePlayersCount === 1 && isSoloMode);
    const allReady = hasEnoughPlayers && activePlayers.every((p: any) => p.isHost || p.isReady || p.isBot);

    const isLobby = gameState.state === 'LOBBY';
    const isPlaying = gameState.state === 'PLAYING';
    const isGameEnd = gameState.state === 'GAME_END';


    return (
        <div ref={containerRef} className={cn(
            "bg-[#0a0614] flex flex-col relative overflow-hidden transition-all duration-300",
            isImmersive ? "fixed inset-0 z-[100]" : "h-full w-full",
            shakeCount > 0 && "animate-shake"
        )}>
            <AtmosphericParticles />
            {showVoiceOverlay && (
                <DiscordVoiceOverlay 
                    users={voiceUsers} 
                    guildId={guildId}
                    gamePlayerIds={gamePlayerIds} 
                    currentUserId={(session?.user as any)?.discordId}
                />
            )}
            
            {/* QUEEN OF THIEVES BACKGROUND */}
            <div className="absolute inset-0 opacity-5 pointer-events-none">
                <img src="/images/sigil-king/incarnations/Roublard.png" className="absolute -right-20 -bottom-20 w-[800px] grayscale blur-sm" alt="" />
                <img src="/images/sigil-king/incarnations/Roublard.png" className="absolute -left-20 -top-20 w-[800px] grayscale blur-sm rotate-180" alt="" />
            </div>

            {/* CONTROLS */}
            <div className="absolute top-8 right-8 z-50 flex items-center gap-3">
                {gameState.state === 'LOBBY' && isHost && (
                    <button 
                        onClick={() => setShowOptions(!showOptions)}
                        className={cn(
                            "w-12 h-12 rounded-2xl flex items-center justify-center transition-all bg-white/5 border border-white/10 hover:bg-white/10 text-white/40 hover:text-white",
                            showOptions && "bg-indigo-500/20 border-indigo-500 text-indigo-400"
                        )}
                    >
                        <Settings size={20} />
                    </button>
                )}
                <button 
                    onClick={() => setShowVoiceOverlay(!showVoiceOverlay)}
                    className={cn(
                        "w-12 h-12 rounded-2xl flex items-center justify-center transition-all border",
                        showVoiceOverlay 
                            ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-500 hover:bg-emerald-500 hover:text-white" 
                            : "bg-slate-500/10 border-slate-500/20 text-slate-500 hover:bg-slate-500 hover:text-white"
                    )}
                    title={showVoiceOverlay ? "Masquer le vocal" : "Afficher le vocal"}
                >
                    {showVoiceOverlay ? <Mic size={20} /> : <MicOff size={20} />}
                </button>
                {/* Quit button — visible anytime for all players */}
                <button
                    onClick={(e) => handleLeave(e)}
                    className="w-12 h-12 rounded-2xl flex items-center justify-center bg-red-500/10 border border-red-500/20 hover:bg-red-500/20 text-red-400 hover:text-red-300 transition-all shadow-lg"
                    title="Quitter la partie"
                >
                    <XCircle size={20} />
                </button>
                <button 
                    onClick={() => setIsImmersive(!isImmersive)}
                    className="w-12 h-12 rounded-2xl flex items-center justify-center bg-white/5 border border-white/10 hover:bg-white/10 text-white/40 hover:text-white transition-all"
                >
                    {isImmersive ? <Minimize2 size={20} /> : <Maximize2 size={20} />}
                </button>
                        <button 
                            onClick={(e) => handleLeave(e)}
                            className="w-12 h-12 rounded-2xl flex items-center justify-center bg-muted border border-border hover:bg-muted/80 text-foreground/40 hover:text-foreground transition-all"
                            title="Quitter le salon"
                        >
                            <LogOut size={20} />
                        </button>
                        <button 
                            onClick={() => setShowTutorial(true)}
                            className="w-12 h-12 rounded-2xl flex items-center justify-center bg-muted border border-border hover:bg-muted/80 text-foreground/40 hover:text-foreground transition-all"
                        >
                            <HelpCircle size={20} />
                        </button>
            </div>

            {/* TOP STATS */}
            <div className="absolute top-8 left-8 z-50 flex flex-col gap-4">
                <ShareRoomButton roomId={gameState.id} />
                {spectatorsCount > 0 && (
                    <div className="flex items-center gap-2 text-[10px] font-black text-white/30 uppercase tracking-widest italic">
                        <Orbit size={12} className="text-indigo-500/50" />
                        {spectatorsCount} Spectateur{spectatorsCount > 1 ? 's' : ''}
                    </div>
                )}
            </div>

            <main className="flex-1 flex flex-col items-center pt-4 md:pt-[68px] pb-4 min-h-0 gap-2 overflow-hidden relative">
                {explosionFlash && <motion.div initial={{ opacity: 1, scale: 1.2 }} animate={{ opacity: 0, scale: 1 }} className="absolute inset-0 bg-red-600/20 z-[100] blur-3xl pointer-events-none" />}

                {/* HUD TOP: SYLLABE - MOVED TO CENTER ARENA TO AVOID AVATAR OVERLAP */}
                <div className="flex-shrink-0 h-4 flex flex-col items-center justify-end pointer-events-none" />

                {/* ─── ARENA CONTAINER — flex-1 so it fills remaining space ─── */}
                <div className="flex-1 min-h-0 w-full flex items-center justify-center p-2 relative">
                <div 
                    key={shakeCount}
                    className={cn(
                        "relative w-full max-w-[min(85vw,45vh,500px)] aspect-square flex items-center justify-center transition-all duration-500",
                        shakeCount > 0 && "animate-shake"
                    )}
                >
                    
                    {/* CENTER HUD — Lobby: just the Roublard image. Buttons moved below arena. */}
                    <div className="absolute z-40 flex flex-col items-center text-center">
                        <AnimatePresence mode="wait">
                             {gameState.state === 'LOBBY' ? (
                                <motion.div key="lobby" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex flex-col items-center">
                                    <div className="relative group">
                                        <div className="absolute -inset-6 bg-indigo-500/15 blur-3xl rounded-full" />
                                        <img src="/assets/dofus/classes/13.png" className="w-20 h-20 md:w-28 md:h-28 object-contain relative z-10 drop-shadow-2xl" alt="Roublard" />
                                    </div>
                                </motion.div>
                            ) : gameState.state === 'PLAYING' ? (
                                <motion.div key="playing" initial={{ opacity: 0 }} animate={{ opacity: 1 }} />
                            ) : (
                                <motion.div key="end" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="flex flex-col items-center gap-4 w-full px-4">
                                    {/* Trophy + Winner */}
                                    <motion.div className="flex flex-col items-center gap-1" initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: 'spring', bounce: 0.5 }}>
                                        <Trophy size={36} className="text-yellow-500 drop-shadow-[0_0_25px_rgba(250,204,21,0.5)]" />
                                        <p className="text-[9px] font-black text-foreground/30 uppercase tracking-[0.3em] italic">Gagnant</p>
                                        <h2 className="text-lg font-black text-foreground italic uppercase tracking-tighter">{winnerName || 'Personne'}</h2>
                                    </motion.div>

                                    {/* Leaderboard */}
                                    {leaderboard.length > 0 && (
                                        <div className="w-full max-w-xs space-y-1 scrollbar-hide">
                                            {leaderboard.map((entry: any, i: number) => (
                                                <motion.div
                                                    key={entry.id}
                                                    initial={{ opacity: 0, x: -10 }}
                                                    animate={{ opacity: 1, x: 0 }}
                                                    transition={{ delay: i * 0.08 }}
                                                    className={cn(
                                                        "flex items-center gap-2 px-2 py-1.5 rounded-xl border text-xs transition-colors",
                                                        i === 0 ? "bg-yellow-500/10 border-yellow-500/30 text-yellow-600 dark:text-yellow-400" :
                                                        i === 1 ? "bg-slate-400/10 border-slate-400/20 text-slate-500 dark:text-slate-400" :
                                                        i === 2 ? "bg-amber-700/10 border-amber-700/20 text-amber-700 dark:text-amber-500" :
                                                        "bg-muted border-border text-foreground/70"
                                                    )}
                                                >
                                                    <span className="text-sm w-5 text-center">
                                                        {i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `${i+1}.`}
                                                    </span>
                                                    <img src={entry.avatar || `https://ui-avatars.com/api/?name=${entry.name}`} className="w-6 h-6 rounded-lg object-cover aspect-square shrink-0" alt="" />
                                                    <span className={cn("font-black italic uppercase flex-1 truncate text-[10px]")}>{entry.name}</span>
                                                    <span className="font-black text-foreground/40 tabular-nums text-[10px]">{entry.wordsFound} <span className="text-foreground/20 font-medium">mots</span></span>
                                                    <div className="flex gap-0.5">
                                                        {[...Array(Math.max(0, entry.lives))].map((_, li) => (
                                                            <Heart key={li} size={7} fill="#ef4444" className="text-red-500" />
                                                        ))}
                                                    </div>
                                                </motion.div>
                                            ))}
                                        </div>
                                    )}

                                    {/* Actions */}
                                    <div className="flex gap-2 pt-2">
                                        {isHost ? (
                                            <button onClick={handleRestart} className="px-4 py-2 rounded-xl bg-indigo-500 hover:bg-indigo-400 text-white font-black italic uppercase tracking-widest text-[10px] transition-all shadow-xl shadow-indigo-500/20">
                                                Rejouer
                                            </button>
                                        ) : (
                                            <div className="px-4 py-2 rounded-xl bg-indigo-500/20 text-indigo-400 font-black italic uppercase tracking-widest text-[10px] flex items-center gap-2 border border-indigo-500/30">
                                                <Loader2 size={10} className="animate-spin" />
                                                Attente de l'hôte...
                                            </div>
                                        )}
                                        <button onClick={(e) => handleLeave(e)} className="px-5 py-2.5 rounded-xl bg-white/5 hover:bg-red-500/20 border border-white/10 hover:border-red-500/40 text-white/60 hover:text-red-400 font-black italic uppercase tracking-widest text-[10px] transition-all">
                                            Quitter
                                        </button>
                                    </div>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </div>
                {/* ─── MATCH INTERFACE (ARENA) ─── */}
                {isPlaying && (
                    <>
                    <div className="absolute inset-0 flex items-center justify-center p-4">
                        <div className="relative w-full aspect-square max-w-[min(80vh,800px)]">

                    {gameState.players.map((p: any, i: number) => {
                        const pos = playerPositions[i];
                        if (!pos) return null;

                        const isActive = p.id === currentPlayer?.id && gameState.state === 'PLAYING';
                        const isExploding = p.id === explosionPlayerId;
                        const count = gameState.players.filter((p: any) => !p.isSpectator).length;

                        return (
                            <motion.div 
                                key={p.id}
                                initial={false}
                                animate={{ 
                                    left: `${50 + pos.x}%`, 
                                    top: `${50 + pos.y}%`,
                                    scale: isExploding ? [1, 1.3, 0.8, 1.1, 1] : (isActive ? pos.scale * 1.1 : pos.scale),
                                    opacity: p.isConnected || p.isBot ? 1 : 0.4,
                                    x: isExploding ? [0, -8, 8, -5, 5, 0] : 0,
                                }}
                                transition={{ duration: isExploding ? 0.4 : 0.3, type: 'spring', damping: 15 }}
                                className="absolute -translate-x-1/2 -translate-y-1/2 flex flex-col items-center z-20"
                            >
                                <div className={cn(
                                    "w-14 h-14 md:w-18 md:h-18 aspect-square shrink-0 rounded-2xl border-2 p-0.5 transition-all duration-300 bg-zinc-950 shadow-xl relative group/avatar",
                                    isExploding ? "border-red-500 ring-2 ring-red-500/40 shadow-[0_0_20px_rgba(239,68,68,0.5)]" :
                                    isActive ? "border-indigo-500 ring-4 ring-indigo-500/30" : 
                                    (p.isReady ? "border-emerald-500/50" : "border-white/10"),
                                    (p.lives === 0 || p.isSpectator) && "grayscale opacity-30 border-red-500/50",
                                    p.isSpectator && "scale-50 opacity-40"
                                )}>
                                    <div className="absolute inset-0 bg-indigo-500/0 group-hover/avatar:bg-indigo-500/5 transition-colors rounded-xl" />
                                    <img src={p.userAvatar || `https://ui-avatars.com/api/?name=${p.userName}`} className="w-full h-full object-cover rounded-xl aspect-square shrink-0" alt="" />
                                    
                                    {/* STATUS INDICATORS */}
                                    {gameState.state === 'LOBBY' && !p.isSpectator && (
                                        <div className="absolute -right-2 -top-2 bg-background rounded-full p-0.5 z-30">
                                            {p.isReady ? <CheckCircle2 size={16} className="text-emerald-500" /> : <XCircle size={16} className="text-red-500/50" />}
                                        </div>
                                    )}

                                    {/* LIVES */}
                                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 flex gap-0.5 z-30">
                                        {[...Array(gameState.config?.startingLives || 3)].map((_, li) => (li < p.lives ? <Heart key={li} size={10} fill="#ef4444" className="text-red-500 drop-shadow-[0_0_5px_rgba(239,68,68,0.5)]" /> : <Heart key={li} size={10} className="text-white/10" />))}
                                    </div>
                                    
                                    {/* PLAYER NAME */}
                                    <div className="absolute -top-12 left-1/2 -translate-x-1/2 whitespace-nowrap z-30">
                                        <span className={cn(
                                            "text-[10px] font-black italic uppercase tracking-widest px-2 py-0.5 rounded-md",
                                            isActive ? "text-indigo-400 bg-indigo-500/10" : "text-white/40"
                                        )}>
                                            {p.userName}
                                        </span>
                                    </div>

                                    {/* DISCORD VOICE INDICATOR */}
                                    {p.discordId && voiceUserIds.includes(p.discordId) && (
                                        <div className="absolute -left-3 -top-3 z-40 bg-emerald-500 rounded-lg p-1 border border-black shadow-[0_0_10px_rgba(16,185,129,0.5)]">
                                            <Mic size={10} className="text-white" />
                                        </div>
                                    )}

                                    {/* Ghost typing removed from here to be moved to central HUD */}
                                </div>
                            </motion.div>
                        );
                    })}

                    {/* ANIMATED BOMB & DIRECTION ARROW */}
                    {gameState.state === 'PLAYING' && (
                        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                            {/* TURN POINTER (Laser pointing from bomb to current player) */}
                            {(() => {
                                const activePlayers = gameState.players.filter((p: any) => !p.isSpectator);
                                const currentIdx = activePlayers.findIndex((ap: any) => ap.id === currentPlayer?.id);
                                if (currentIdx === -1 || activePlayers.length === 0) return null;
                                
                                // Player 0 at Top = 0 degrees CSS rotation if laser div points up
                                const targetAngleDeg = (currentIdx / activePlayers.length) * 360;
                                
                                return (
                                    <motion.div
                                        className="absolute inset-0 flex items-center justify-center pointer-events-none"
                                        initial={false}
                                        animate={{ rotate: targetAngleDeg }}
                                        transition={{ type: 'spring', damping: 25, stiffness: 80 }}
                                    >
                                        {/* The Laser Beam */}
                                        <div className="absolute" style={{ 
                                            left: '50%', 
                                            top: '50%', 
                                            width: '2px', 
                                            height: '35%', // Increased length to reach players better
                                            background: 'linear-gradient(to top, transparent, rgba(99,102,241,0.8), #fff)',
                                            transform: 'translateX(-50%) translateY(-100%)', // Beam points up from center
                                            boxShadow: '0 0 15px rgba(99,102,241,0.6)'
                                        }}>
                                            {/* Glowing Arrowhead */}
                                            <motion.div 
                                                animate={{ 
                                                    scale: [1, 1.4, 1],
                                                    opacity: [0.7, 1, 0.7]
                                                }}
                                                transition={{ repeat: Infinity, duration: 0.8 }}
                                                className="absolute -top-4 left-1/2 -translate-x-1/2"
                                            >
                                                <svg width="32" height="32" viewBox="0 0 24 24" fill="none">
                                                    <path d="M12 2L20 12H16V22H8V12H4L12 2Z" fill="white" className="drop-shadow-[0_0_15px_rgba(255,255,255,1)]" />
                                                </svg>
                                            </motion.div>
                                        </div>
                                    </motion.div>
                                );
                            })()}
                        </div>
                    )}

                            {/* Bombe et HUD (Arena center only has bomb now) */}
                            {gameState.state === 'PLAYING' && (
                                <motion.div 
                                    initial={{ scale: 0, opacity: 0 }}
                                    animate={{ 
                                        scale: localTimeLeft <= 3 ? [0.8, 1.1, 0.8] : 0.8,
                                        rotate: localTimeLeft <= 3 ? [0, 10, -10, 0] : [0, 2, -2, 0],
                                        opacity: 1
                                    }}
                                    transition={{ 
                                        scale: { repeat: Infinity, duration: localTimeLeft <= 3 ? 0.2 : 1 },
                                        rotate: { repeat: Infinity, duration: localTimeLeft <= 3 ? 0.1 : 2 }
                                    }}
                                    className="relative z-10"
                                >
                                    <div className="relative group flex items-center justify-center">
                                        <div className={cn(
                                            "absolute inset-0 blur-[60px] rounded-full transition-colors duration-300",
                                            localTimeLeft <= 3 ? "bg-red-500/60" : "bg-indigo-500/30"
                                        )} />
                                        <div className={cn(
                                            "relative transition-all duration-500 flex items-center justify-center",
                                            gameState.players.filter((p: any) => !p.isSpectator).length > 6 ? "w-20 h-20 md:w-24 md:h-24" : "w-24 h-24 md:w-44 md:h-44"
                                        )}>
                                            <img src="/assets/dofus/classes/13.png" className={cn("w-full h-full object-contain drop-shadow-[0_0_30px_rgba(0,0,0,0.5)]", localTimeLeft <= 3 && "brightness-150")} alt="Bomb" />
                                            
                                            <div className="absolute top-1/4 right-[20%]">
                                                <motion.div 
                                                    animate={{ scale: [1, 2, 1], opacity: [0.5, 1, 0.5], x: [0, 2, -2, 0], y: [0, -2, 2, 0] }} 
                                                    transition={{ repeat: Infinity, duration: 0.1 }} 
                                                    className="w-3 h-3 bg-orange-500 rounded-full blur-[2px] shadow-[0_0_15px_#f97316]" 
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </motion.div>
                            )}
                        </div>
                    </div>
                    </>
                )}

                </div>
                </div>

                <div className="absolute inset-y-0 right-6 md:right-10 flex flex-col justify-center w-64 md:w-80 pointer-events-none z-[100]">
                    <AnimatePresence mode="wait">
                        {gameState.state === 'PLAYING' && (
                            <motion.div
                                initial={{ opacity: 0, x: 50 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: 50 }}
                                className="space-y-6"
                            >
                                <div className="bg-black/60 backdrop-blur-3xl border-2 border-white/10 rounded-[2rem] md:rounded-[3rem] p-6 md:p-8 flex flex-col items-center shadow-2xl relative overflow-hidden group">
                                    <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/10 to-transparent" />
                                    <div className="relative z-10 flex flex-col items-center">
                                        <div className="flex flex-col items-center">
                                            <span className={cn(
                                                "text-5xl md:text-7xl font-black italic tracking-tighter uppercase transition-all duration-300",
                                                localTimeLeft <= 3 ? "text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.8)]" : "text-white"
                                            )}>
                                                {gameState.currentSyllable}
                                            </span>
                                            
                                            {/* COMPOUND WORD INDICATOR */}
                                            {gameState.currentSyllablePartCount > 1 && (
                                                <motion.div 
                                                    initial={{ opacity: 0, y: 10 }}
                                                    animate={{ opacity: 1, y: 0 }}
                                                    className="mt-2 flex items-center gap-1.5 px-3 py-1 bg-indigo-500/20 rounded-full border border-indigo-500/30"
                                                >
                                                    <span className="text-[10px] font-black uppercase italic text-indigo-400 tracking-wider">
                                                        {gameState.currentSyllablePartCount} Mots
                                                    </span>
                                                    <div className="w-1 h-1 bg-indigo-400 rounded-full animate-pulse" />
                                                </motion.div>
                                            )}
                                        </div>

                                        {/* COMPOUND WORD PRE-COMPLETION HINTS */}
                                        {gameState.currentSyllablePartCount > 1 && gameState.currentSyllableHintParts && (
                                            <div className="mt-8 flex flex-wrap justify-center gap-2 w-full">
                                                {gameState.currentSyllableHintParts.map((hint: string | null, idx: number) => (
                                                    <div 
                                                        key={`hint-${idx}`}
                                                        className={cn(
                                                            "px-3 py-2 rounded-xl border transition-all duration-500",
                                                            hint 
                                                                ? "bg-indigo-500/20 border-indigo-500/40 shadow-[0_0_15px_rgba(99,102,241,0.2)]" 
                                                                : "bg-white/5 border-white/10 border-dashed opacity-40"
                                                        )}
                                                    >
                                                        {hint ? (
                                                            <span className="text-sm font-black italic uppercase text-indigo-300">
                                                                {hint}
                                                            </span>
                                                        ) : (
                                                            <div className="flex gap-1">
                                                                <div className="w-1 h-1 bg-white/20 rounded-full" />
                                                                <div className="w-1 h-1 bg-white/20 rounded-full" />
                                                                <div className="w-1 h-1 bg-white/20 rounded-full" />
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>


                                    {/* TYPING FEED */}
                                    <AnimatePresence>
                                        {(() => {
                                            const typingPlayerId = Object.keys(typingMap).find(id => typingMap[id]?.length > 0) || (wordInput?.length > 0 ? socket?.id : null);
                                            const text = typingPlayerId === socket?.id ? wordInput : (typingMap[typingPlayerId || ""] || "");
                                            const p = gameState.players.find((pl: any) => pl.id === typingPlayerId);
                                            
                                            if (!typingPlayerId || !text || !p) return null;

                                            return (
                                                <motion.div
                                                    initial={{ opacity: 0, y: 20, scale: 0.95 }}
                                                    animate={{ opacity: 1, y: 0, scale: 1 }}
                                                    exit={{ opacity: 0, y: -10, scale: 0.95 }}
                                                    className="bg-indigo-600/20 backdrop-blur-3xl border-2 border-indigo-500/40 rounded-3xl p-6 shadow-2xl"
                                                >
                                                    <div className="flex items-center gap-3 mb-4">
                                                        <div className="w-8 h-8 rounded-xl overflow-hidden border-2 border-indigo-400">
                                                            <img src={p.userAvatar} className="w-full h-full object-cover" alt="" />
                                                        </div>
                                                        <div className="flex flex-col">
                                                            <span className="text-xs font-black uppercase italic text-white">{p.userName}</span>
                                                            <span className="text-[8px] font-bold uppercase text-indigo-400/80 tracking-widest">En train d'écrire...</span>
                                                        </div>
                                                    </div>
                                                    <div className="bg-black/40 p-4 rounded-2xl border border-white/5 overflow-hidden">
                                                        {highlightCompoundWord(text, gameState.currentSyllable)}
                                                    </div>
                                                </motion.div>
                                            );
                                        })()}
                                    </AnimatePresence>
                                </motion.div>
                            )}
                    </AnimatePresence>
                </div>

