                                        <span className="text-[9px] bg-emerald-500/10 text-emerald-500 px-1.5 py-0.5 rounded uppercase font-black tracking-tighter">Success</span>
                                    </div>
                                    <div className="text-sm font-black tracking-tighter text-foreground italic">
                                        {highlightCompoundWord(found.word, gameState.currentSyllable)}
                                    </div>
                                </motion.div>
                            ))}
                        </AnimatePresence>
                    </div>
                    <div className="flex items-center justify-center gap-6 text-[10px] font-black uppercase tracking-[0.2em] text-white/60 italic">
                        {gameState.state === 'PLAYING' ? (
                            <>
                                <span className={cn("flex items-center gap-2", isMyTurn && "text-indigo-300")}>
                                    <Info size={12} />
                                    Contient{' '}
                                    <span className={cn("font-black text-sm", isMyTurn ? "text-indigo-300" : "text-white/40")}>&ldquo;{gameState.currentSyllable}&rdquo;</span>
                                </span>
                                {gameState.currentSyllableCategory && (
                                    <>
                                        <span className="w-px h-4 bg-white/10" />
                                        <span className="flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-300 shadow-[0_0_15px_rgba(79,70,229,0.1)] transition-all">
                                            <span className="text-[9px] font-black uppercase tracking-widest opacity-50">Indice :</span>
                                            <span className="text-[11px] font-black uppercase italic tracking-wider">{gameState.currentSyllableCategory}</span>
                                        </span>
                                    </>
                                )}
                                <span className="w-px h-4 bg-white/10" />
                                <span className="flex items-center gap-2 text-white/40">
                                    <AlertCircle size={12} />
                                    Dict. {gameState.config?.dictionaryMode === 'dofus' ? 'Dofus' : gameState.config?.dictionaryMode === 'mixed' ? 'Mixte' : 'FR'}
                                </span>
                            </>
                        ) : (
                            <span className="text-white/20 italic">Lance la partie pour commencer</span>
                        )}
                    </div>

                    {/* ALPHABET PROGRESS — visible pendant PLAYING */}
                    {gameState.state === 'PLAYING' && myPlayer && (
                        <div className="space-y-1.5">
                            <div className="flex items-center justify-between text-[9px] font-black uppercase tracking-widest text-white/30 italic px-1">
                                <span className="flex items-center gap-1.5">
                                    <Sparkles size={10} className="text-yellow-500/60" />
                                    Bonus Vie
                                </span>
                                <span className="tabular-nums">
                                    {myPlayer.alphabet?.length ?? 0}/26 lettres
                                </span>
                            </div>
                            <div className="flex flex-wrap justify-center gap-[3px]">
                                {"ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(char => (
                                    <span
                                        key={char}
                                        className={cn(
                                            "w-5 h-5 flex items-center justify-center rounded-[3px] text-[9px] font-black transition-all duration-200",
                                            myPlayer?.alphabet?.includes(char)
                                                ? "bg-indigo-500 text-white shadow-[0_0_8px_rgba(99,102,241,0.6)]"
                                                : "bg-white/5 text-white/15"
                                        )}
                                    >
                                        {char}
                                    </span>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* NEW LARGE HUD TIMER (BOTTOM LEFT) */}
                    <AnimatePresence>
                        {gameState.state === 'PLAYING' && localTimeLeft >= 0 && (
                            <motion.div
                                initial={{ opacity: 0, x: -50, scale: 0.8 }}
                                animate={{ 
                                    opacity: 1, 
                                    x: 0, 
                                    scale: 1,
                                    filter: localTimeLeft <= 3 ? ["blur(0px)", "blur(1px)", "blur(0px)"] : "blur(0px)" 
                                }}
                                exit={{ opacity: 0, transition: { duration: 0.2 } }}
                                className="fixed bottom-12 left-12 z-[200] pointer-events-none"
                            >
                                <div className="relative flex flex-col items-start select-none">
                                    <div className="flex items-center gap-3 mb-[-12px]">
                                        <Timer size={24} className={cn(localTimeLeft <= 3 ? "text-red-500 animate-pulse" : "text-indigo-500")} />
                                        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-white/20 italic">Temps Restant</span>
                                    </div>
                                    <span className={cn(
                                        "text-[120px] font-[1000] italic tabular-nums tracking-[-0.1em] leading-none transition-all duration-300 drop-shadow-[0_10px_30px_rgba(0,0,0,0.5)]",
                                        localTimeLeft <= 3 
                                            ? "text-red-500 animate-bounce shadow-red-500/50" 
                                            : "text-white"
                                    )}>
                                        {localTimeLeft}
                                    </span>
                                    {localTimeLeft <= 3 && (
                                        <motion.div 
                                            animate={{ opacity: [0, 1, 0] }}
                                            transition={{ repeat: Infinity, duration: 0.4 }}
                                            className="absolute -inset-8 bg-red-600/20 blur-[60px] rounded-full z-[-1]"
                                        />
                                    )}
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </footer>

            <style>{`
                @keyframes shake {
                    0%, 100% { transform: translateX(0); }
                    10%, 30%, 50%, 70%, 90% { transform: translateX(-10px); }
                    20%, 40%, 60%, 80% { transform: translateX(10px); }
                }
                .animate-shake {
                    animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
                }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.05); border-radius: 10px; }
            `}</style>
        </div>
    );
}

/**
 * useBombSounds — Web Audio API synthesis for Sigil Bomb
 * No external files needed, everything is synthesized on the fly.
 */
"use client";
import { useRef, useCallback } from "react";

export function useBombSounds() {
    const ctxRef = useRef<AudioContext | null>(null);

    const getCtx = () => {
        if (!ctxRef.current) {
            ctxRef.current = new AudioContext();
        }
        // Resume if suspended (browser policy)
        if (ctxRef.current.state === "suspended") {
            ctxRef.current.resume();
        }
        return ctxRef.current;
    };

    /** Normal tick — short, clean click */
    const playTick = useCallback(() => {
        try {
            const ctx = getCtx();
            const o = ctx.createOscillator();
            const g = ctx.createGain();
            o.connect(g);
            g.connect(ctx.destination);
            o.frequency.setValueAtTime(880, ctx.currentTime);
            o.frequency.exponentialRampToValueAtTime(440, ctx.currentTime + 0.08);
            g.gain.setValueAtTime(0.18, ctx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
            o.start(ctx.currentTime);
            o.stop(ctx.currentTime + 0.08);
        } catch (_) {}
    }, []);

    /** Urgent tick — deeper, harder, lower pitch for last 3 seconds */
    const playUrgentTick = useCallback(() => {
        try {
            const ctx = getCtx();
            // Main tick tone
            const o = ctx.createOscillator();
            const g = ctx.createGain();
            o.type = "square";
            o.connect(g);
            g.connect(ctx.destination);
            o.frequency.setValueAtTime(220, ctx.currentTime);
            o.frequency.exponentialRampToValueAtTime(110, ctx.currentTime + 0.12);
            g.gain.setValueAtTime(0.35, ctx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);
            o.start(ctx.currentTime);
            o.stop(ctx.currentTime + 0.15);

            // Click layer
            const buf = ctx.createBuffer(1, ctx.sampleRate * 0.02, ctx.sampleRate);
            const data = buf.getChannelData(0);
            for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
            const src = ctx.createBufferSource();
            src.buffer = buf;
            const gn = ctx.createGain();
            gn.gain.setValueAtTime(0.4, ctx.currentTime);
            src.connect(gn);
            gn.connect(ctx.destination);
            src.start(ctx.currentTime);
        } catch (_) {}
    }, []);

    /** Explosion — Roublard bomb bam */
    const playExplosion = useCallback(() => {
        try {
            const ctx = getCtx();
            const duration = 1.2;
            const bufLen = ctx.sampleRate * duration;
            const buf = ctx.createBuffer(2, bufLen, ctx.sampleRate);

            for (let ch = 0; ch < 2; ch++) {
                const data = buf.getChannelData(ch);
                for (let i = 0; i < bufLen; i++) {
                    // White noise decaying exponentially
                    data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufLen, 2.5);
                }
            }

            const src = ctx.createBufferSource();
            src.buffer = buf;

            // Low-pass filter for "boom" character
            const lp = ctx.createBiquadFilter();
            lp.type = "lowpass";
            lp.frequency.setValueAtTime(800, ctx.currentTime);
            lp.frequency.exponentialRampToValueAtTime(60, ctx.currentTime + duration);

            // Gain envelope
            const g = ctx.createGain();
            g.gain.setValueAtTime(1.5, ctx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);

            src.connect(lp);
            lp.connect(g);
            g.connect(ctx.destination);
            src.start(ctx.currentTime);
            src.stop(ctx.currentTime + duration);

            // Sub bass thump
            const sub = ctx.createOscillator();
            const subG = ctx.createGain();
            sub.type = "sine";
            sub.frequency.setValueAtTime(80, ctx.currentTime);
            sub.frequency.exponentialRampToValueAtTime(30, ctx.currentTime + 0.3);
            subG.gain.setValueAtTime(1.2, ctx.currentTime);
            subG.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
            sub.connect(subG);
            subG.connect(ctx.destination);
            sub.start(ctx.currentTime);
            sub.stop(ctx.currentTime + 0.3);
        } catch (_) {}
    }, []);

    /** Word success — bright chime */
    const playSuccess = useCallback(() => {
        try {
            const ctx = getCtx();
            [523, 659, 784].forEach((freq, i) => {
                const o = ctx.createOscillator();
                const g = ctx.createGain();
                o.type = "sine";
                o.frequency.value = freq;
                g.gain.setValueAtTime(0.12, ctx.currentTime + i * 0.07);
                g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.07 + 0.2);
                o.connect(g);
                g.connect(ctx.destination);
                o.start(ctx.currentTime + i * 0.07);
                o.stop(ctx.currentTime + i * 0.07 + 0.2);
            });
        } catch (_) {}
    }, []);

    return { playTick, playUrgentTick, playExplosion, playSuccess };
}

"use client";

/**
 * CalendarDashboard V2 - Premium Guild Calendar
 * Streamlined dashboard with grid/list toggle
 */

import { useRouter, useSearchParams } from "next/navigation";
import { useState, useEffect } from "react";
import {
    Calendar as CalendarIcon,
    Plus,
    List,
    LayoutGrid,
    Loader2,
    Sparkles,
    Swords,
    PartyPopper,
    Target,
    Wheat,
    Eye,
    Filter,
} from "lucide-react";
import { format, startOfMonth, endOfMonth, startOfWeek, endOfWeek, addMonths, subMonths, addWeeks, subWeeks } from "date-fns";
import { fr } from "date-fns/locale";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogTrigger, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { toast } from "sonner";
import {
    getCalendarEvents,
    getCalendarEventDetails,
    createCalendarEvent,
    deleteCalendarEvent,
    updateCalendarEvent,
    registerForEvent,
    unregisterFromEvent,
    publishEvent,
    completeEvent,
    sendEventReminder,
    autoCloseExpiredEvents,
    sendCalendarDiscordNotification,
    getDiscordRolesForCalendar,
    type GuildEventInput
} from "@/server/actions/calendar-actions";
import { CalendarGrid } from "./calendar-grid";
import { EventDetailModal } from "./event-detail-modal";
import { EventCard } from "./event-card";
import { EventForm } from "./event-form";
import { cn } from "@/lib/utils";

interface CalendarDashboardProps {
    guildId: string;
    currentUserId: string;
    canManage: boolean;
    isDiscordConfigured?: boolean;
}

type ViewMode = "grid" | "list";

interface DiscordRole {
    id: string;
    name: string;
    color?: number;
}

const FILTER_TYPES: Record<string, { label: string; icon: any; color: string; bg: string; border: string; }> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bg: "bg-red-500/15",
        border: "border-red-500/40",
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bg: "bg-purple-500/15",
        border: "border-purple-500/40",
    },
    SESSION_MISSIONS: {
        label: "Missions Guilde",
        icon: Target,
        color: "text-amber-400",
        bg: "bg-amber-500/15",
        border: "border-amber-500/40",
    },
    SORTIE_FARM: {
        label: "Sortie Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bg: "bg-emerald-500/15",
        border: "border-emerald-500/40",
    },
    KRALAMOURE: {
        label: "Kralamoure",
        icon: Eye,
        color: "text-pink-400",
        bg: "bg-pink-500/15",
        border: "border-pink-500/40",
    },
    OTHERS: {
        label: "Autres",
        icon: List,
        color: "text-zinc-400",
        bg: "bg-zinc-500/15",
        border: "border-zinc-500/40",
    },
};

export function CalendarDashboard({ guildId, currentUserId, canManage, isDiscordConfigured }: CalendarDashboardProps) {
    const [viewMode, setViewMode] = useState<ViewMode>("grid");
    const [currentDate, setCurrentDate] = useState(new Date());

    // Auto-switch to list mode on small screens
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 1024) {
                setViewMode("list");
            }
        };
        handleResize(); // Initial check
        window.addEventListener("resize", handleResize);
        return () => window.removeEventListener("resize", handleResize);
    }, []);

    const [events, setEvents] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isCreateOpen, setIsCreateOpen] = useState(false);
    const [prefilledDate, setPrefilledDate] = useState<Date | null>(null);
    const [editingEvent, setEditingEvent] = useState<any>(null);

    // Event detail modal
    const [selectedEventId, setSelectedEventId] = useState<string | null>(null);
    const [selectedEvent, setSelectedEvent] = useState<any>(null);
    const [loadingDetail, setLoadingDetail] = useState(false);
    const [hasMetamobKey, setHasMetamobKey] = useState(false);

    // Discord roles for notifications
    const [discordRoles, setDiscordRoles] = useState<DiscordRole[]>([]);

    // Filter state
    const [selectedFilter, setSelectedFilter] = useState<string | "ALL">("ALL");
    const [showFilters, setShowFilters] = useState(false);

    // Dynamic counts for filters
    const typeCounts = events.reduce((acc, e) => {
        acc[e.type] = (acc[e.type] || 0) + 1;
        return acc;
    }, {} as Record<string, number>);

    // Filter and group events
    const filteredEvents = events.filter(e => selectedFilter === "ALL" || e.type === selectedFilter)
        .sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());

    // Group by date for List View
    const groupedEvents = filteredEvents.reduce((groups, event) => {
        const start = event.startDate ? new Date(event.startDate) : null;
        if (!start || isNaN(start.getTime())) return groups;
        
        const dateKey = format(start, "yyyy-MM-dd");
        if (!groups[dateKey]) groups[dateKey] = [];
        groups[dateKey].push(event);
        return groups;
    }, {} as Record<string, any[]>);

    const sortedDates = Object.keys(groupedEvents).sort();

    const fetchEvents = async () => {
        setLoading(true);

        // Fetch events for the entire month (works for both week and month views)
        const monthStart = startOfMonth(currentDate);
        const monthEnd = endOfMonth(currentDate);
        // Also include previous and next week for week view edge cases
        const start = startOfWeek(subWeeks(monthStart, 1), { weekStartsOn: 1 });
        const end = endOfWeek(addWeeks(monthEnd, 1), { weekStartsOn: 1 });

        const result = await getCalendarEvents(guildId, start, end);
        if (result.success) {
            setEvents(result.events || []);
        } else {
            toast.error(result.error);
        }
        setLoading(false);
    };

    const fetchEventDetails = async (eventId: string) => {
        setLoadingDetail(true);
        const result = await getCalendarEventDetails(guildId, eventId);
        if (result.success && result.event) {
            setSelectedEvent(result.event);
            setHasMetamobKey(!!(result as any).hasMetamobKey);
        } else {
            toast.error(result.error || "Impossible de charger l'événement");
        }
        setLoadingDetail(false);
    };

    useEffect(() => {
        fetchEvents();
        // Fetch Discord roles if user can manage
        if (canManage) {
            getDiscordRolesForCalendar(guildId).then(setDiscordRoles);
        }
    }, [currentDate, guildId, canManage]);

    useEffect(() => {
        if (selectedEventId) {
            fetchEventDetails(selectedEventId);
        } else {
            setSelectedEvent(null);
        }
    }, [selectedEventId]);

    const handleCreate = async (data: GuildEventInput) => {
        const result = await createCalendarEvent(guildId, data);
        if (result.success) {
            toast.success("Événement créé !");
            setIsCreateOpen(false);
            fetchEvents();
        } else {
            toast.error(result.error);
        }
    };

    const handleUpdate = async (data: GuildEventInput) => {
        const result = await updateCalendarEvent(guildId, editingEvent.id, data);
        if (result.success) {
            toast.success("Événement modifié !");
            setEditingEvent(null);
            fetchEvents();
            if (selectedEventId === editingEvent.id) {
                fetchEventDetails(editingEvent.id);
            }
        } else {
            toast.error(result.error);
        }
    };

    const handleDelete = async () => {
        if (!selectedEventId) return;
        const result = await deleteCalendarEvent(guildId, selectedEventId);
        if (result.success) {
            toast.success("Événement supprimé");
            // Clear both event data AND selection simultaneously to prevent
            // the modal from rendering with stale/deleted event data (hydration error)
            setSelectedEvent(null);
            setSelectedEventId(null);
            fetchEvents();
        } else {
            toast.error(result.error);
        }
    };

    const handleRegister = async (data?: { classe?: string; comment?: string }) => {
        if (!selectedEventId) return;
        const result = await registerForEvent(guildId, selectedEventId, data);
        if (result.success) {
            // @ts-ignore - isReserve is present on success
            toast.success(result.isReserve ? "Ajouté à la file d'attente" : "Inscription réussie !");
            fetchEventDetails(selectedEventId);
            fetchEvents();
        } else {
            toast.error(result.error);
        }
    };

    const handleUnregister = async () => {
        if (!selectedEventId) return;
        const result = await unregisterFromEvent(guildId, selectedEventId);
        if (result.success) {
            toast.success("Désinscription effectuée");
            fetchEventDetails(selectedEventId);
            fetchEvents();
        } else {
            toast.error(result.error);
        }
    };

    const handleQuickRespond = async (eventId: string, status: "GOING" | "MAYBE" | "DECLINED") => {
        if (status === "MAYBE") {
            toast.info("L'option 'Peut-être' sera disponible prochainement");
        }

        // Find event to check status (using participants or attendees field depending on what's returned)
        const event = events.find(e => e.id === eventId);
        // Note: event object form fetchEvents usually has 'attendees' mapped from 'participants'
        const isRegistered = event?.attendees?.some((a: any) => a.userId === currentUserId);

        if (status === "GOING") {
            if (isRegistered) {
                const result = await unregisterFromEvent(guildId, eventId);
                if (result.success) {
                    toast.success("Désinscription effectuée");
                } else {
                    toast.error(result.error);
                }
            } else {
                const result = await registerForEvent(guildId, eventId);
                if (result.success) {
                    // @ts-ignore - isReserve is present on success
                    toast.success(result.isReserve ? "Ajouté à la file d'attente" : "Inscription validée !");
                } else {
                    toast.error(result.error);
                }
            }
        }

        fetchEvents();
    };

    const handlePublish = async () => {
        if (!selectedEventId) return;
        const result = await publishEvent(guildId, selectedEventId);
        if (result.success) {
            toast.success("Événement publié !");
            fetchEventDetails(selectedEventId);
            fetchEvents();
        } else {
            toast.error(result.error);
        }
    };

    const handleComplete = async () => {
        if (!selectedEventId) return;
        const result = await completeEvent(guildId, selectedEventId);
        if (result.success) {
            toast.success("Événement terminé !");
            fetchEventDetails(selectedEventId);
            fetchEvents();
        } else {
            toast.error(result.error);
        }
    };

    const handleSendReminder = async (roleId?: string) => {
        if (!selectedEventId) return { success: false, error: "Aucun événement" };
        return await sendEventReminder(guildId, selectedEventId, roleId);
    };

    const handleShareDiscord = async (roleId?: string) => {
        if (!selectedEventId) return { success: false, error: "Aucun événement" };
        return await sendCalendarDiscordNotification(guildId, selectedEventId, roleId);
    };

    const handleEventClick = (eventId: string) => {
        setSelectedEventId(eventId);
    };

    const handleDayClick = (date: Date) => {
        if (!canManage) return;
        setPrefilledDate(date);
        setIsCreateOpen(true);
    };

    return (
        <div className="space-y-6">
            {/* ============ VIEW TOGGLE (visible only when not loading) ============ */}
            {!loading && (
                <div className="flex items-center justify-end">
                    <div className="flex items-center gap-1 p-1 bg-foreground/[0.03] border border-border rounded-full backdrop-blur-sm">
                        <button
                            onClick={() => setViewMode("grid")}
                            className={cn(
                                "flex items-center gap-2 px-4 py-2 rounded-full text-sm font-black uppercase italic tracking-widest transition-all",
                                viewMode === "grid"
                                    ? "bg-foreground text-background shadow-inner"
                                    : "text-muted-foreground hover:text-foreground"
                            )}
                        >
                            <LayoutGrid className="h-4 w-4" />
                            <span className="hidden sm:inline">Grille</span>
                        </button>
                        <button
                            onClick={() => setViewMode("list")}
                            className={cn(
                                "flex items-center gap-2 px-4 py-2 rounded-full text-sm font-black uppercase italic tracking-widest transition-all",
                                viewMode === "list"
                                    ? "bg-foreground text-background shadow-inner"
                                    : "text-muted-foreground hover:text-foreground"
                            )}
                        >
                            <List className="h-4 w-4" />
                            <span className="hidden sm:inline">Liste</span>
                        </button>
                    </div>
                </div>
            )}

            {/* ============ MAIN CONTENT ============ */}
            {loading ? (
                <div className="flex flex-col items-center justify-center py-24 space-y-4">
                    <div className="relative">
                        <div className="h-16 w-16 rounded-full bg-amber-500/10 flex items-center justify-center animate-pulse">
                            <CalendarIcon className="h-8 w-8 text-amber-500/50" />
                        </div>
                        <Loader2 className="absolute -top-1 -right-1 h-6 w-6 text-amber-500 animate-spin" />
                    </div>
                    <p className="text-zinc-400 text-sm animate-pulse">Chargement de l'agenda...</p>
                </div>
            ) : viewMode === "grid" ? (
                // ============ GRID VIEW ============
                <CalendarGrid
                    events={events}
                    currentDate={currentDate}
                    onDateChange={setCurrentDate}
                    onEventClick={handleEventClick}
                    onDayClick={handleDayClick}
                    canManage={canManage}
                    onCreateClick={() => setIsCreateOpen(true)}
                />
            ) : (
                // ============ LIST VIEW ============
                <div className="space-y-8">
                    {/* Header + Filters */}
                    <div className="space-y-6">
                        {/* Title & Action */}
                        <div className="relative overflow-hidden rounded-2xl border border-border bg-foreground/[0.02] backdrop-blur-xl p-6">
                            <div className="absolute inset-0 bg-gradient-to-br from-amber-500/5 via-transparent to-primary/5 pointer-events-none" />

                            <div className="relative flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                                <div className="flex items-center gap-5">
                                    <div className="relative group shrink-0">
                                        <div className="absolute inset-0 bg-gradient-to-br from-amber-500/20 to-orange-600/20 rounded-xl blur-lg group-hover:blur-xl transition-all opacity-70" />
                                        <div className="relative h-12 w-12 md:h-14 md:w-14 rounded-xl bg-gradient-to-br from-amber-500/10 to-orange-600/10 flex items-center justify-center border border-amber-500/20 shrink-0">
                                            <CalendarIcon className="h-6 w-6 md:h-7 md:w-7 text-amber-600 dark:text-amber-400" />
                                        </div>
                                    </div>
                                    <div className="min-w-0">
                                        <h2 className="text-2xl md:text-3xl font-black italic uppercase tracking-tighter text-foreground truncate">Agenda</h2>
                                        <p className="text-muted-foreground font-bold text-xs md:text-sm mt-1">
                                            {filteredEvents.length} événements programmés
                                        </p>
                                    </div>
                                </div>



                                <div className="flex items-center gap-3">
                                    {/* Action Options */}
                                    <Button
                                        variant="outline"
                                        onClick={() => setShowFilters(!showFilters)}
                                        className={cn(
                                            "h-10 rounded-full px-5 text-sm font-black uppercase italic tracking-widest transition-all border-2",
                                            (showFilters || selectedFilter !== "ALL")
                                                ? "bg-foreground text-background border-foreground shadow-md"
                                                : "bg-foreground/[0.03] text-muted-foreground border-border hover:border-foreground/20 hover:text-foreground"
                                        )}
                                    >
                                        <Filter className={cn("h-4 w-4 mr-2", selectedFilter !== "ALL" && "text-amber-500 animate-pulse")} />
                                        Filtres
                                        {selectedFilter !== "ALL" && (
                                            <span className="ml-2 px-2 py-0.5 rounded-md text-xs font-bold bg-amber-500/20 text-amber-700">
                                                1
                                            </span>
                                        )}
                                    </Button>

                                    {canManage && (
                                        <Button
                                            onClick={() => setIsCreateOpen(true)}
                                            className="h-10 px-5 rounded-full bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-zinc-950 font-bold shadow-lg shadow-amber-500/25 transition-all hover:shadow-amber-500/40 hover:scale-105"
                                        >
                                            <Plus className="h-4 w-4 mr-2" />
                                            Nouvel évent
                                        </Button>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Filters Bar (Collapsible) */}
                        {showFilters && (
                            <div className="flex items-center gap-3 overflow-x-auto pb-4 scrollbar-hide animate-in slide-in-from-top-2 duration-300">
                                <button
                                    onClick={() => setSelectedFilter("ALL")}
                                    className={cn(
                                        "flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-black uppercase italic tracking-widest transition-all border-2 whitespace-nowrap",
                                        selectedFilter === "ALL"
                                            ? "bg-foreground text-background border-foreground shadow-md shadow-foreground/10"
                                            : "bg-foreground/[0.03] text-muted-foreground border-border hover:border-foreground/20 hover:text-foreground"
                                    )}
                                >
                                    Tous
                                    <span className={cn(
                                        "px-2 py-0.5 rounded-md text-xs font-black",
                                        selectedFilter === "ALL" ? "bg-background text-foreground" : "bg-foreground/10 text-muted-foreground"
                                    )}>
                                        {events.length}
                                    </span>
                                </button>

                                <div className="h-6 w-px bg-zinc-800/50 mx-1 shrink-0" />

                                {Object.entries(FILTER_TYPES).map(([type, config]) => {
                                    const count = typeCounts[type] || 0;
                                    const Icon = config.icon;
                                    const isActive = selectedFilter === type;

                                    return (
                                        <button
                                            key={type}
                                            onClick={() => setSelectedFilter(isActive ? "ALL" : type)}
                                            className={cn(
                                                "flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-black uppercase italic tracking-widest transition-all border-2 whitespace-nowrap",
                                                isActive
                                                    ? cn(config.bg, config.color, config.border, "shadow-md")
                                                    : "bg-foreground/[0.03] text-muted-foreground border-border hover:border-foreground/20"
                                            )}
                                        >
                                            <Icon className="h-4 w-4" />
                                            {config.label}
                                            <span className={cn(
                                                "px-2 py-0.5 rounded-md text-xs font-black",
                                                isActive ? "bg-current/10" : "bg-foreground/10"
                                            )}>
                                                {count}
                                            </span>
                                        </button>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                    {/* Events List Grouped */}
                    {sortedDates.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-20 border-2 border-dashed border-border rounded-2xl bg-foreground/[0.02] text-center px-4">
                            <Sparkles className="h-10 w-10 text-muted-foreground/20 mb-4" />
                            <p className="text-muted-foreground font-bold">Aucun événement ne correspond à vos filtres.</p>
                            {canManage && selectedFilter === "ALL" && (
                                <Button variant="link" onClick={() => setIsCreateOpen(true)} className="mt-2 text-amber-500">
                                    Créer un événement
                                </Button>
                            )}
                        </div>
                    ) : (
                        <div className="space-y-10">
                            {sortedDates.map(dateKey => (
                                <div key={dateKey} className="space-y-4">
                                    <div className="flex items-center gap-4">
                                        <div className="flex flex-col items-end shrink-0 min-w-[60px]">
                                            <span className="text-xs font-black text-muted-foreground uppercase tracking-widest">
                                                {format(new Date(dateKey), "MMM", { locale: fr }).replace(".", "")}
                                            </span>
                                            <span className="text-2xl font-black text-foreground leading-none">
                                                {format(new Date(dateKey), "dd")}
                                            </span>
                                        </div>
                                        <div className="h-px bg-border flex-1" />
                                        <span className="text-sm font-black text-muted-foreground uppercase tracking-widest italic">
                                            {format(new Date(dateKey), "EEEE", { locale: fr })}
                                        </span>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                                        {groupedEvents[dateKey].map((event: any) => (
                                            <div
                                                key={event.id}
                                                onClick={() => handleEventClick(event.id)}
                                                className="cursor-pointer transition-all hover:opacity-90"
                                            >
                                                <EventCard
                                                    event={event}
                                                    currentUserId={currentUserId}
                                                    canManage={canManage}
                                                    onRespond={(status) => handleQuickRespond(event.id, status)}
                                                    onEdit={() => setEditingEvent(event)}
                                                    onDelete={() => {
                                                        setSelectedEventId(event.id);
                                                        handleDelete();
                                                    }}
                                                />
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}

            <Dialog 
                open={isCreateOpen} 
                onOpenChange={(open) => {
                    setIsCreateOpen(open);
                    if (!open) setPrefilledDate(null);
                }}
            >
                <DialogContent draggable className="max-w-2xl max-h-[90vh] overflow-y-auto">
                    <DialogTitle className="text-xl font-black uppercase italic tracking-tighter text-foreground">
                        Créer un événement
                    </DialogTitle>
                    <DialogDescription className="text-muted-foreground font-bold">
                        Remplissez les informations pour créer un nouvel événement de guilde.
                    </DialogDescription>
                    <EventForm 
                        onSubmit={handleCreate} 
                        isDiscordConfigured={isDiscordConfigured}
                        initialData={prefilledDate ? { startDate: prefilledDate } : undefined}
                    />
                </DialogContent>
            </Dialog>

            {/* ============ DETAIL MODAL ============ */}
            <EventDetailModal
                event={selectedEvent}
                open={!!selectedEventId}
                onOpenChange={(open) => {
                    if (!open) {
                        setSelectedEventId(null);
                        // Optional: Clear URL param
                        const url = new URL(window.location.href);
                        url.searchParams.delete("event");
                        window.history.replaceState({}, "", url);
                    }
                }}
                currentUserId={currentUserId}
                guildId={guildId}
                canManage={canManage}
                discordRoles={discordRoles}
                hasMetamobKey={hasMetamobKey}
                onRegister={handleRegister}
                onUnregister={handleUnregister}
                onEdit={() => {
                    setEditingEvent(selectedEvent);
                    setSelectedEventId(null);
                }}
                onDelete={handleDelete}
                onPublish={handlePublish}
                onComplete={handleComplete}
                onSendReminder={handleSendReminder}
                onShareDiscord={handleShareDiscord}
            />

            {/* ============ EDIT DIALOG ============ */}
            <Dialog open={!!editingEvent} onOpenChange={(open) => !open && setEditingEvent(null)}>
                <DialogContent draggable className="max-w-2xl max-h-[90vh] overflow-y-auto">
                    <DialogTitle className="text-xl font-black uppercase italic tracking-tighter text-foreground">
                        Modifier l'événement
                    </DialogTitle>
                    <DialogDescription className="text-muted-foreground font-bold">
                        Modifiez les informations de l'événement.
                    </DialogDescription>
                    {editingEvent && (
                        <EventForm
                            initialData={editingEvent}
                            onSubmit={handleUpdate}
                            isDiscordConfigured={isDiscordConfigured}
                        />
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Loader2, Send, Share2, Bell, BellOff, AtSign, Check, Users } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface DiscordRole {
    id: string;
    name: string;
    color?: number;
}

interface CalendarDiscordDialogProps {
    isOpen: boolean;
    onOpenChange: (open: boolean) => void;
    guildId: string;
    eventId: string;
    roles: DiscordRole[];
    mode: "REMINDER" | "SHARE";
    onConfirm: (roleId?: string | "everyone") => Promise<{ success: boolean; sentCount?: number; discordSent?: boolean; error?: string }>;
}

type PingType = "EVERYONE" | "ROLE" | "NONE";

export function CalendarDiscordDialog({
    isOpen,
    onOpenChange,
    guildId,
    eventId,
    roles,
    mode,
    onConfirm
}: CalendarDiscordDialogProps) {
    const [pingType, setPingType] = useState<PingType>("NONE");
    const [selectedRoleId, setSelectedRoleId] = useState<string | null>(null);
    const [isPending, startTransition] = useTransition();

    const isReminder = mode === "REMINDER";

    const handleConfirm = () => {
        startTransition(async () => {
            const roleId = pingType === "EVERYONE" ? "everyone" : (pingType === "ROLE" ? selectedRoleId || undefined : undefined);
            const res = await onConfirm(roleId);

            if (res.success) {
                if (isReminder) {
                    let msg = `Rappel envoyé à ${res.sentCount} participants`;
                    if (res.discordSent) msg += " et publié sur Discord";
                    toast.success(msg);
                } else {
                    toast.success("Événement partagé sur Discord !");
                }
                onOpenChange(false);
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        });
    };

    return (
        <Dialog open={isOpen} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-xs sm:max-w-sm bg-zinc-950 border-white/10 shadow-2xl rounded-2xl p-0 overflow-hidden outline-none">
                {/* Header */}
                <div className="px-5 pt-5 pb-4 border-b border-white/5">
                    <DialogHeader>
                        <DialogTitle className="text-base font-black text-white flex items-center gap-2.5">
                            <div className={cn(
                                "p-1.5 rounded-xl",
                                isReminder ? "bg-amber-500/20 text-amber-400" : "bg-indigo-500/20 text-indigo-400"
                            )}>
                                {isReminder ? <Bell className="w-4 h-4" /> : <Share2 className="w-4 h-4" />}
                            </div>
                            {isReminder ? "Envoyer un rappel" : "Partager sur Discord"}
                        </DialogTitle>
                        <DialogDescription className="text-zinc-500 text-xs mt-1">
                            {isReminder
                                ? "Notifiez les participants avec un ping optionnel."
                                : "Qui mentionner pour cette annonce d'événement ?"
                            }
                        </DialogDescription>
                    </DialogHeader>
                </div>

                <div className="px-5 py-4 space-y-4">
                    {/* Mode: 2 compact buttons */}
                    <div className="grid grid-cols-2 gap-2">
                        {/* Option 1: Sans ping / Participants seulement */}
                        <button
                            onClick={() => { setPingType("NONE"); setSelectedRoleId(null); }}
                            className={cn(
                                "flex items-center gap-2.5 p-3 rounded-xl border transition-all text-left",
                                pingType === "NONE"
                                    ? isReminder
                                        ? "bg-amber-500/10 border-amber-500/40 text-amber-300"
                                        : "bg-indigo-500/10 border-indigo-500/40 text-indigo-300"
                                    : "bg-zinc-900 border-white/5 text-zinc-400 hover:border-white/20 hover:text-zinc-200"
                            )}
                        >
                            {isReminder ? <Users className="w-4 h-4 shrink-0" /> : <BellOff className="w-4 h-4 shrink-0" />}
                            <div>
                                <div className="text-xs font-black">{isReminder ? "Participants" : "Sans ping"}</div>
                                <div className="text-[10px] text-zinc-600 font-medium">{isReminder ? "App seulement" : "Discret"}</div>
                            </div>
                            {pingType === "NONE" && <Check className={cn("w-3.5 h-3.5 ml-auto", isReminder ? "text-amber-400" : "text-indigo-400")} />}
                        </button>

                        {/* Option 2: @everyone */}
                        <button
                            onClick={() => { setPingType("EVERYONE"); setSelectedRoleId(null); }}
                            className={cn(
                                "flex items-center gap-2.5 p-3 rounded-xl border transition-all text-left",
                                pingType === "EVERYONE"
                                    ? "bg-red-500/10 border-red-500/40 text-red-300"
                                    : "bg-zinc-900 border-white/5 text-zinc-400 hover:border-white/20 hover:text-zinc-200"
                            )}
                        >
                            <AtSign className="w-4 h-4 shrink-0" />
                            <div>
                                <div className="text-xs font-black">@everyone</div>
                                <div className="text-[10px] text-zinc-600 font-medium">{isReminder ? "App + Discord" : "Toute la guilde"}</div>
                            </div>
                            {pingType === "EVERYONE" && <Check className="w-3.5 h-3.5 ml-auto text-red-400" />}
                        </button>
                    </div>

                    {/* Role list */}
                    <div>
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black uppercase tracking-wider text-zinc-500">Ou un rôle spécifique</span>
                            {selectedRoleId && (
                                <button
                                    onClick={() => { setSelectedRoleId(null); if (pingType === "ROLE") setPingType("NONE"); }}
                                    className={cn(
                                        "text-[10px] font-bold transition-colors",
                                        isReminder ? "text-amber-400 hover:text-amber-300" : "text-indigo-400 hover:text-indigo-300"
                                    )}
                                >
                                    Effacer
                                </button>
                            )}
                        </div>

                        <div className="bg-zinc-900/80 border border-white/5 rounded-xl overflow-hidden max-h-40 overflow-y-auto custom-scrollbar">
                            {roles.length === 0 ? (
                                <div className="py-6 text-center text-xs text-zinc-600">Aucun rôle trouvé</div>
                            ) : (
                                <div className="p-1.5 space-y-0.5">
                                    {roles.map(role => {
                                        const hex = role.color ? `#${role.color.toString(16).padStart(6, "0")}` : "#71717a";
                                        const isSelected = selectedRoleId === role.id;
                                        return (
                                            <button
                                                key={role.id}
                                                onClick={() => { setPingType("ROLE"); setSelectedRoleId(role.id); }}
                                                className={cn(
                                                    "w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-left transition-all",
                                                    isSelected
                                                        ? isReminder
                                                            ? "bg-amber-500/10 text-amber-100"
                                                            : "bg-indigo-500/10 text-indigo-100"
                                                        : "text-zinc-400 hover:bg-white/5 hover:text-zinc-200"
                                                )}
                                            >
                                                <span className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: hex }} />
                                                <span className="text-sm font-bold truncate flex-1">@{role.name}</span>
                                                {isSelected && (
                                                    <Check className={cn("w-3.5 h-3.5 shrink-0", isReminder ? "text-amber-400" : "text-indigo-400")} />
                                                )}
                                            </button>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className="px-5 pb-5">
                    <Button
                        onClick={handleConfirm}
                        disabled={isPending}
                        className={cn(
                            "w-full h-10 font-black text-sm transition-all",
                            pingType === "EVERYONE"
                                ? "bg-red-600 hover:bg-red-500"
                                : isReminder
                                    ? "bg-amber-600 hover:bg-amber-500"
                                    : "bg-indigo-600 hover:bg-indigo-500"
                        )}
                    >
                        {isPending
                            ? <Loader2 className="w-4 h-4 animate-spin mr-2" />
                            : <Send className="w-4 h-4 mr-2" />
                        }
                        {isReminder ? "Envoyer le rappel" : "Envoyer sur Discord"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

/**
 * CalendarGrid V5 - BIGGER & CLEARER
 * Everything sized for comfortable reading
 */

import { useState, useMemo } from "react";
import {
    format,
    startOfWeek,
    endOfWeek,
    eachDayOfInterval,
    isToday,
    addWeeks,
    subWeeks,
    getWeek,
    startOfMonth,
    endOfMonth,
    addMonths,
    subMonths
} from "date-fns";
import { fr } from "date-fns/locale";
import {
    ChevronLeft,
    ChevronRight,
    Plus,
    Calendar as CalendarIcon,
    Users,
    Swords,
    PartyPopper,
    Target,
    Wheat,
    CalendarDays,
    LayoutGrid,
    Eye
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

// ============================================
// 4 EVENT TYPES
// ============================================

interface TypeConfig {
    label: string;
    icon: React.ElementType;
    color: string;
    bg: string;
    border: string;
    dot: string;
}

const TYPE_CONFIG: Record<string, TypeConfig> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bg: "bg-red-500/15",
        border: "border-red-500/40",
        dot: "bg-red-500"
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bg: "bg-purple-500/15",
        border: "border-purple-500/40",
        dot: "bg-purple-500"
    },
    SESSION_MISSIONS: {
        label: "Missions Guilde",
        icon: Target,
        color: "text-amber-400",
        bg: "bg-amber-500/15",
        border: "border-amber-500/40",
        dot: "bg-amber-500"
    },
    SORTIE_FARM: {
        label: "Sortie Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bg: "bg-emerald-500/15",
        border: "border-emerald-500/40",
        dot: "bg-emerald-500"
    },
    KRALAMOURE: {
        label: "Kralamoure",
        icon: Eye,
        color: "text-pink-400",
        bg: "bg-pink-500/15",
        border: "border-pink-500/40",
        dot: "bg-pink-500"
    },
};

// ============================================
// INTERFACES
// ============================================

interface CalendarEvent {
    id: string;
    title: string;
    type: string;
    status: string;
    startDate: Date | string;
    endDate: Date | string;
    maxParticipants?: number | null;
    _count?: { participants: number };
}

type ViewMode = "week" | "month";

interface CalendarGridProps {
    events: CalendarEvent[];
    currentDate: Date;
    onDateChange: (date: Date) => void;
    onEventClick: (eventId: string) => void;
    onDayClick?: (date: Date) => void;
    canManage?: boolean;
    onCreateClick?: () => void;
}

// ============================================
// COMPONENT
// ============================================

export function CalendarGrid({
    events,
    currentDate,
    onDateChange,
    onEventClick,
    onDayClick,
    canManage = false,
    onCreateClick
}: CalendarGridProps) {
    const [viewMode, setViewMode] = useState<ViewMode>("week");
    const [activeFilter, setActiveFilter] = useState<string | null>(null);

    // Filter events
    const filteredEvents = useMemo(() => {
        if (!activeFilter) return events;
        return events.filter(e => e.type === activeFilter);
    }, [events, activeFilter]);

    // Calendar days
    const calendarDays = useMemo(() => {
        if (viewMode === "week") {
            const weekStart = startOfWeek(currentDate, { weekStartsOn: 1 });
            const weekEnd = endOfWeek(currentDate, { weekStartsOn: 1 });
            return eachDayOfInterval({ start: weekStart, end: weekEnd });
        } else {
            const monthStart = startOfMonth(currentDate);
            const monthEnd = endOfMonth(currentDate);
            const calendarStart = startOfWeek(monthStart, { weekStartsOn: 1 });
            const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 1 });
            return eachDayOfInterval({ start: calendarStart, end: calendarEnd });
        }
    }, [currentDate, viewMode]);

    // Events by day
    const eventsByDay = useMemo(() => {
        const map = new Map<string, CalendarEvent[]>();
        filteredEvents.forEach(event => {
            const eventDate = new Date(event.startDate);
            const key = format(eventDate, "yyyy-MM-dd");
            const existing = map.get(key) || [];
            map.set(key, [...existing, event]);
        });
        return map;
    }, [filteredEvents]);

    // Type counts
    const typeCounts = useMemo(() => {
        const counts: Record<string, number> = {};
        events.forEach(e => { counts[e.type] = (counts[e.type] || 0) + 1; });
        return counts;
    }, [events]);

    const handlePrev = () => {
        if (viewMode === "week") onDateChange(subWeeks(currentDate, 1));
        else onDateChange(subMonths(currentDate, 1));
    };

    const handleNext = () => {
        if (viewMode === "week") onDateChange(addWeeks(currentDate, 1));
        else onDateChange(addMonths(currentDate, 1));
    };

    const weekDays = ["LUN", "MAR", "MER", "JEU", "VEN", "SAM", "DIM"];
    const currentWeek = getWeek(currentDate, { weekStartsOn: 1 });

    return (
        <div className="space-y-5">
            {/* ============ BIG HEADER ============ */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 p-4 sm:p-6 p-5 rounded-2xl bg-zinc-900/60 border border-zinc-800/50">
                {/* Left - Title */}
                <div className="flex items-center gap-4 min-w-0">
                    <div className="h-12 w-12 md:h-14 md:w-14 rounded-xl bg-gradient-to-br from-amber-500/20 to-orange-600/20 flex items-center justify-center border border-amber-500/30 shrink-0">
                        <CalendarIcon className="h-6 w-6 md:h-7 md:w-7 text-amber-400" />
                    </div>
                    <div className="min-w-0">
                        <h2 className="text-xl md:text-2xl font-bold text-zinc-100 truncate">
                            {viewMode === "week"
                                ? `Semaine ${currentWeek}`
                                : format(currentDate, "MMMM yyyy", { locale: fr })
                            }
                        </h2>
                        <p className="text-xs md:text-base text-zinc-400 truncate">
                            {format(startOfWeek(currentDate, { weekStartsOn: 1 }), "d", { locale: fr })}
                            {" - "}
                            {format(endOfWeek(currentDate, { weekStartsOn: 1 }), "d MMMM yyyy", { locale: fr })}
                        </p>
                    </div>
                </div>

                {/* Right - Controls */}
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
                    {/* View Toggle */}
                    <div className="flex items-center bg-zinc-950 border border-zinc-700 rounded-xl p-1 shrink-0">
                        <button
                            onClick={() => setViewMode("week")}
                            className={cn(
                                "flex-1 sm:flex-none flex items-center justify-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-lg text-xs md:text-sm font-semibold transition-all",
                                viewMode === "week"
                                    ? "bg-amber-500 text-zinc-950"
                                    : "text-zinc-400 hover:text-zinc-200"
                            )}
                        >
                            <CalendarDays className="h-4 w-4 md:h-5 md:w-5" />
                            <span>Semaine</span>
                        </button>
                        <button
                            onClick={() => setViewMode("month")}
                            className={cn(
                                "flex-1 sm:flex-none flex items-center justify-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-lg text-xs md:text-sm font-semibold transition-all",
                                viewMode === "month"
                                    ? "bg-amber-500 text-zinc-950"
                                    : "text-zinc-400 hover:text-zinc-200"
                            )}
                        >
                            <LayoutGrid className="h-4 w-4 md:h-5 md:w-5" />
                            <span>Mois</span>
                        </button>
                    </div>

                    {/* Navigation */}
                    <div className="flex items-center bg-zinc-950 border border-zinc-700 rounded-xl shrink-0">
                        <button
                            onClick={handlePrev}
                            className="p-2.5 md:p-3 hover:bg-zinc-800 rounded-l-xl transition-colors"
                        >
                            <ChevronLeft className="h-4 w-4 md:h-5 md:w-5 text-zinc-300" />
                        </button>
                        <button
                            onClick={() => onDateChange(new Date())}
                            className="flex-1 sm:flex-none px-3 md:px-4 py-2 md:py-2.5 text-xs md:text-sm font-semibold text-zinc-300 hover:text-white hover:bg-zinc-800 transition-colors"
                        >
                            Auj.
                        </button>
                        <button
                            onClick={handleNext}
                            className="p-2.5 md:p-3 hover:bg-zinc-800 rounded-r-xl transition-colors"
                        >
                            <ChevronRight className="h-4 w-4 md:h-5 md:w-5 text-zinc-300" />
                        </button>
                    </div>

                    {/* Create Button */}
                    {canManage && onCreateClick && (
                        <Button
                            onClick={onCreateClick}
                            size="lg"
                            className="h-10 md:h-12 px-4 md:px-5 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-zinc-950 font-bold text-sm md:text-base shadow-lg shadow-amber-500/25 shrink-0"
                        >
                            <Plus className="h-4 w-4 md:h-5 md:w-5 mr-2" />
                            Créer
                        </Button>
                    )}
                </div>
            </div>

            {/* ============ FILTER BAR (BIG PILLS) ============ */}
            <div className="flex items-center gap-3 flex-wrap">
                <button
                    onClick={() => setActiveFilter(null)}
                    className={cn(
                        "flex items-center gap-2 px-5 py-3 rounded-xl text-sm font-bold transition-all border-2",
                        !activeFilter
                            ? "bg-zinc-100 text-zinc-900 border-zinc-100"
                            : "bg-zinc-900 text-zinc-400 border-zinc-700 hover:border-zinc-600 hover:text-zinc-200"
                    )}
                >
                    Tous
                    <span className={cn(
                        "px-2 py-0.5 rounded-md text-xs font-bold",
                        !activeFilter ? "bg-zinc-800 text-zinc-100" : "bg-zinc-800 text-zinc-400"
                    )}>
                        {events.length}
                    </span>
                </button>

                {Object.entries(TYPE_CONFIG).map(([type, config]) => {
                    const count = typeCounts[type] || 0;
                    const Icon = config.icon;
                    const isActive = activeFilter === type;

                    return (
                        <button
                            key={type}
                            onClick={() => setActiveFilter(isActive ? null : type)}
                            className={cn(
                                "flex items-center gap-2 px-5 py-3 rounded-xl text-sm font-bold transition-all border-2",
                                isActive
                                    ? cn(config.bg, config.color, config.border)
                                    : "bg-zinc-900 text-zinc-400 border-zinc-700 hover:border-zinc-600"
                            )}
                        >
                            <Icon className="h-5 w-5" />
                            {config.label}
                            <span className={cn(
                                "px-2 py-0.5 rounded-md text-xs font-bold",
                                isActive ? "bg-white/10" : "bg-zinc-800"
                            )}>
                                {count}
                            </span>
                        </button>
                    );
                })}
            </div>

            {/* ============ CALENDAR GRID ============ */}
            <div className="rounded-2xl border border-zinc-800/50 bg-zinc-900/40 overflow-hidden">
                {/* Days Header - BIGGER */}
                <div className="grid grid-cols-7 bg-zinc-900 border-b border-zinc-800">
                    {weekDays.map((day, i) => (
                        <div key={day} className={cn(
                            "py-4 text-center text-sm font-bold tracking-wider",
                            i >= 5 ? "text-zinc-600" : "text-zinc-400"
                        )}>
                            {day}
                        </div>
                    ))}
                </div>

                {/* Days Grid */}
                <div className="grid grid-cols-7">
                    {calendarDays.map((day, index) => {
                        const dayKey = format(day, "yyyy-MM-dd");
                        const dayEvents = eventsByDay.get(dayKey) || [];
                        const isCurrentDay = isToday(day);
                        const isWeekend = index % 7 >= 5;
                        const minHeight = viewMode === "week" ? "min-h-[180px]" : "min-h-[120px]";
                        const maxEvents = viewMode === "week" ? 4 : 2;

                        return (
                            <div
                                key={dayKey}
                                className={cn(
                                    "relative border-b border-r border-zinc-800/40 p-0 transition-all flex flex-col",
                                    minHeight,
                                    canManage ? "cursor-pointer" : "cursor-default",
                                    isWeekend ? "bg-zinc-950/50" : "bg-zinc-900/40 hover:bg-zinc-800/40",
                                    index % 7 === 6 && "border-r-0"
                                )}
                                onClick={(e) => {
                                    // Only trigger if we clicked the cell itself, not an event button
                                    if (canManage && onDayClick) {
                                        onDayClick(day);
                                    }
                                }}
                            >
                                <div className="p-3 flex-1 flex flex-col">
                                {/* Day Number - BIG */}
                                <div className="flex items-center justify-between mb-2">
                                    <span className={cn(
                                        "h-8 w-8 flex items-center justify-center rounded-full text-base font-bold",
                                        isCurrentDay
                                            ? "bg-amber-500 text-zinc-950 shadow-lg shadow-amber-500/30"
                                            : "text-zinc-300"
                                    )}>
                                        {format(day, "d")}
                                    </span>
                                    {dayEvents.length > maxEvents && (
                                        <span className="text-sm text-zinc-400 font-semibold">
                                            +{dayEvents.length - maxEvents}
                                        </span>
                                    )}
                                </div>

                                {/* Events - BIGGER PILLS */}
                                <div className="space-y-1.5">
                                    {dayEvents.slice(0, maxEvents).map((event) => {
                                        const start = event.startDate ? new Date(event.startDate) : null;
                                        if (!start || isNaN(start.getTime())) return null;

                                        const config = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
                                        const Icon = config.icon;
                                        const time = format(start, "HH:mm");

                                        return (
                                            <TooltipProvider key={event.id}>
                                                <Tooltip delayDuration={100}>
                                                    <TooltipTrigger asChild>
                                                        <button
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                onEventClick(event.id);
                                                            }}
                                                            className={cn(
                                                                "w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-semibold transition-all text-left border",
                                                                config.bg, config.color, config.border,
                                                                "hover:scale-[1.02] hover:shadow-lg active:scale-[0.98]"
                                                            )}
                                                        >
                                                            <Icon className="h-4 w-4 shrink-0" />
                                                            <span className="font-bold">{time}</span>
                                                            <span className="truncate">{event.title}</span>
                                                        </button>
                                                    </TooltipTrigger>
                                                    <TooltipContent
                                                        side="right"
                                                        className="bg-zinc-900 border-zinc-700 p-3 max-w-[220px]"
                                                    >
                                                        <p className="font-bold text-zinc-100">{event.title}</p>
                                                        <p className="text-sm text-zinc-400 mt-1">
                                                            {time} → {format(new Date(event.endDate), "HH:mm")}
                                                        </p>
                                                        {event._count && (
                                                            <div className="flex items-center gap-1.5 mt-2 text-sm text-zinc-500">
                                                                <Users className="h-4 w-4" />
                                                                {event._count.participants}
                                                                {event.maxParticipants && ` / ${event.maxParticipants}`}
                                                            </div>
                                                        )}
                                                    </TooltipContent>
                                                </Tooltip>
                                            </TooltipProvider>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>

            {/* ============ LEGEND (BIG) ============ */}
            <div className="flex items-center justify-center gap-8 py-4">
                {Object.entries(TYPE_CONFIG).map(([type, config]) => (
                    <div key={type} className="flex items-center gap-3">
                        <div className={cn("h-4 w-4 rounded-full", config.dot)} />
                        <span className="text-base font-medium text-zinc-400">{config.label}</span>
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";

import { format } from "date-fns";
import { fr } from "date-fns/locale";
import {
    Users,
    MapPin,
    Calendar,
    Clock,
    CheckCircle2,
    HelpCircle,
    XCircle,
    Trash2,
    Edit,
    Target,
    Swords,
    PartyPopper,
    Wheat,
    Eye,
    Diamond
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

// Local type definitions
type AttendeeStatus = "GOING" | "MAYBE" | "DECLINED";

interface EventCardProps {
    event: any; // Using any for now to handle Prisma includes
    currentUserId: string;
    onRespond: (status: AttendeeStatus) => void;
    onEdit?: () => void;
    onDelete?: () => void;
    canManage: boolean;
}

const TYPE_THEMES: Record<string, { label: string; color: string; bg: string; border: string; icon: any; gradient: string }> = {
    RAID_OFFICIAL: { label: "Raid 3.6", color: "text-red-400", bg: "bg-red-500/10", border: "border-red-500/20", icon: Swords, gradient: "from-red-600 to-rose-600" },
    EVENT_GUILD: { label: "Event Guilde", color: "text-purple-400", bg: "bg-purple-500/10", border: "border-purple-500/20", icon: PartyPopper, gradient: "from-purple-600 to-fuchsia-600" },
    SESSION_MISSIONS: { label: "Missions Guilde", color: "text-amber-400", bg: "bg-amber-500/10", border: "border-amber-500/20", icon: Target, gradient: "from-amber-600 to-orange-600" },
    SORTIE_FARM: { label: "Sortie Farm", color: "text-emerald-400", bg: "bg-emerald-500/10", border: "border-emerald-500/20", icon: Wheat, gradient: "from-emerald-600 to-green-600" },
    KRALAMOURE: { label: "Kralamoure", color: "text-pink-400", bg: "bg-pink-500/10", border: "border-pink-500/20", icon: Eye, gradient: "from-pink-600 to-rose-600" },
    OTHERS: { label: "Autres", color: "text-slate-400", bg: "bg-slate-500/10", border: "border-slate-500/20", icon: Diamond, gradient: "from-slate-600 to-zinc-600" },
};

const EVENT_IMAGES: Record<string, string> = {
    "RAID_OFFICIAL": "/assets/calendar/calendar_raid_official.png",
    EVENT_GUILD: "/assets/calendar/calendar_event_guild.png",
    SESSION_MISSIONS: "/assets/calendar/calendar_session_missions.png",
    SORTIE_FARM: "/assets/calendar/calendar_boss_farm.png",
    KRALAMOURE: "/assets/calendar/calendar_kralamour.png",
    "GUILD_MISSION": "/assets/calendar/calendar_session_missions.png", // Fallback
    "SONGES_RUN": "/assets/calendar/calendar_songes_run.png",
    "DUNGEON_FARM": "/assets/calendar/calendar_dungeon_farm.png",
    "SOCIAL": "/assets/calendar/calendar_social.png",
    "ALMANAX_BONUS": "/assets/calendar/calendar_almanax_bonus.png",
    "OTHERS": "/assets/calendar/calendar_autres.png",
};

export function EventCard({
    event,
    currentUserId,
    onRespond,
    onEdit,
    onDelete,
    canManage,
    variant = "card"
}: EventCardProps & { variant?: "card" | "list" }) {
    const startDate = event.startDate ? new Date(event.startDate) : null;
    const endDate = event.endDate ? new Date(event.endDate) : (startDate || new Date());
    
    if (!startDate || isNaN(startDate.getTime())) return null;
    const validEndDate = (endDate && !isNaN(new Date(endDate).getTime())) ? new Date(endDate) : startDate;

    const theme = TYPE_THEMES[event.type] || TYPE_THEMES.SESSION_MISSIONS;
    const Icon = theme.icon;

    const myAttendance = event.participants?.find((a: any) => a.userId === currentUserId);
    const attendeeCount = event.participants?.length || 0;

    // Extract Metamob creator for Kralamoure events
    const isKralamoure = event.type === "KRALAMOURE";
    const eventMetadata = (event as any).metadata as any;
    const displayCreatorName = isKralamoure && eventMetadata?.metamobCreator
        ? eventMetadata.metamobCreator
        : event.creator?.name || "Inconnu";

    // For Kralamoure events, use Metamob participants from metadata
    // For other events, filter by REGISTERED status
    const metamobParticipants = isKralamoure && eventMetadata?.metamobParticipants
        ? eventMetadata.metamobParticipants
        : [];

    const attendeesGoing = isKralamoure
        ? metamobParticipants
        : (event.participants?.filter((a: any) => a.status === "REGISTERED") || []);

    // Override attendee count for Kralamoure events using metadata count if available
    const displayAttendeeCount = isKralamoure 
        ? (eventMetadata?.metamobParticipantsCount || attendeesGoing.length) 
        : (event.participants?.length || 0);

    // View: List (Horizontal Row)
    if (variant === "list") {
        return (
            <div className="group relative flex items-center gap-4 rounded-xl border border-zinc-800 bg-zinc-900/40 p-3 transition-all hover:bg-zinc-900/60 hover:border-zinc-700 hover:shadow-lg hover:shadow-black/20">
                {/* Left Accent Bar */}
                <div className={cn("absolute left-0 top-3 bottom-3 w-1 rounded-r-full opacity-60 group-hover:opacity-100 transition-opacity", theme.bg.replace("/10", "/80"))} />

                {/* Date Box */}
                <div className="flex h-14 w-14 shrink-0 flex-col items-center justify-center rounded-lg border border-zinc-800 bg-zinc-950/50 ml-2">
                    <span className="text-[10px] font-medium uppercase text-zinc-500">{format(startDate, "MMM", { locale: fr })}</span>
                    <span className="text-xl font-bold text-zinc-200">{format(startDate, "dd")}</span>
                </div>

                {/* Info Main */}
                <div className="mr-auto min-w-0 flex-1 space-y-1">
                    <div className="flex items-center gap-2">
                        <Badge variant="outline" className={cn("h-5 px-1.5 text-[10px] font-medium border-0", theme.bg, theme.color)}>
                            <Icon className="mr-1 h-3 w-3" />
                            {theme.label}
                        </Badge>
                        <div className="flex items-center gap-1 text-xs text-zinc-500">
                            <Clock className="h-3 w-3" />
                            <span>{format(startDate, "HH:mm")} - {format(validEndDate, "HH:mm")}</span>
                        </div>
                    </div>
                    <h3 className="truncate text-base font-bold text-zinc-100 group-hover:text-amber-400 transition-colors">
                        {event.title}
                    </h3>
                    <div className="flex items-center gap-4 text-xs text-zinc-400">
                        <div className="flex items-center gap-1.5">
                            <Users className="h-3.5 w-3.5 text-zinc-500" />
                            <span>{attendeeCount}{event.maxParticipants ? ` / ${event.maxParticipants}` : ""} participants</span>
                        </div>
                        {event.location && (
                            <div className="flex items-center gap-1.5 truncate max-w-[200px]">
                                <MapPin className="h-3.5 w-3.5 text-zinc-500" />
                                <span className="truncate">{event.location}</span>
                            </div>
                        )}
                    </div>
                </div>

                {/* Attendees Avatars (Hidden on very small screens) */}
                <div className="hidden md:flex items-center -space-x-2 mr-4">
                    {event.attendees?.slice(0, 4).map((a: any) => (
                        <div key={a.id} className="h-8 w-8 rounded-full border-2 border-zinc-900 bg-zinc-800 overflow-hidden" title={a.user.name}>
                            {a.user.image ? (
                                <img src={a.user.image} alt={a.user.name} className="h-full w-full object-cover" />
                            ) : (
                                <div className="h-full w-full flex items-center justify-center text-[10px] text-zinc-400">{a.user.name?.[0]}</div>
                            )}
                        </div>
                    ))}
                    {attendeeCount > 4 && (
                        <div className="h-8 w-8 rounded-full border-2 border-zinc-900 bg-zinc-800 flex items-center justify-center text-[10px] font-bold text-zinc-400">
                            +{attendeeCount - 4}
                        </div>
                    )}
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1">
                    {/* Can manage actions would go here (hidden in list usually, handled by parent) */}
                    <div className={cn(
                        "h-2 w-2 rounded-full",
                        myAttendance?.status === "GOING" ? "bg-green-500" :
                            myAttendance?.status === "MAYBE" ? "bg-amber-500" : "bg-zinc-800"
                    )} title={myAttendance?.status ? "Inscrit" : "Non inscrit"} />
                </div>
            </div>
        );
    }

    // View: Card (Vertical) - Modernized

    return (
        <Card className="h-full flex flex-col group relative overflow-hidden transition-all duration-300 hover:-translate-y-1 hover:shadow-xl border-zinc-800/50 bg-zinc-900/40 hover:bg-zinc-900/60 hover:border-zinc-700/50">
            {/* Top Image Background */}
            <div className="absolute top-0 left-0 right-0 h-32 overflow-hidden opacity-40 mask-image-gradient">
                <div className="absolute inset-0 bg-gradient-to-b from-transparent to-zinc-900/90 z-10" />
                <img
                    src={EVENT_IMAGES[event.type] || EVENT_IMAGES["EVENT_GUILD"]}
                    alt="Event type"
                    className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500 transform group-hover:scale-105"
                />
            </div>

            {/* Top Accent Line */}
            <div className={cn("h-1.5 w-full bg-gradient-to-r opacity-90 relative z-20", theme.gradient)} />

            <CardHeader className="p-5 flex-none space-y-4 pb-2">
                <div className="flex justify-between items-start gap-4">
                    <div className="flex items-center gap-2">
                        <Badge variant="outline" className={cn("rounded-md px-2.5 py-1 text-sm font-semibold border-opacity-50 transition-colors", theme.bg, theme.color, theme.border)}>
                            <Icon className="w-4 h-4 mr-2" />
                            {theme.label}
                        </Badge>

                        {/* Completed Event Badge */}
                        {event.status === "COMPLETED" && (
                            <Badge className="bg-zinc-700/50 text-zinc-300 border-zinc-600 px-2 py-0.5 text-xs font-semibold uppercase tracking-wider">
                                Terminé
                            </Badge>
                        )}
                    </div>

                    {/* Attendance Status Indicator */}
                    {myAttendance && (
                        <TooltipProvider>
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className={cn(
                                        "h-3 w-3 rounded-full ring-2 ring-zinc-950 shadow-lg",
                                        myAttendance.status === "REGISTERED" && "bg-green-500 shadow-green-500/50",
                                        myAttendance.status === "MAYBE" && "bg-amber-500 shadow-amber-500/50",
                                        myAttendance.status === "DECLINED" && "bg-red-500 shadow-red-500/50"
                                    )} />
                                </TooltipTrigger>
                                <TooltipContent className="bg-zinc-950 border-zinc-800 text-sm">
                                    <p>{myAttendance.status === "REGISTERED" ? "Vous participez" : myAttendance.status === "MAYBE" ? "Peut-être" : "Vous ne venez pas"}</p>
                                </TooltipContent>
                            </Tooltip>
                        </TooltipProvider>
                    )}
                </div>

                <div className="space-y-1">
                    <CardTitle className="text-xl font-bold text-zinc-100 leading-tight group-hover:text-white transition-colors line-clamp-2 min-h-[1.75rem] break-all">
                        {event.title}
                    </CardTitle>
                </div>
            </CardHeader>

            <CardContent className="p-5 pt-2 flex-1 space-y-5">
                {/* Info Grid */}
                <div className="space-y-3">
                    <div className="flex items-center text-base text-zinc-400 group-hover:text-zinc-300 transition-colors">
                        <Calendar className="w-5 h-5 mr-3 text-zinc-500 shrink-0" />
                        <span className="capitalize font-medium">
                            {format(startDate, "EEEE d MMMM", { locale: fr })}
                        </span>
                    </div>
                    <div className="flex items-center text-base text-zinc-400 group-hover:text-zinc-300 transition-colors">
                        <Clock className="w-5 h-5 mr-3 text-zinc-500 shrink-0" />
                        <span>
                            {format(startDate, "HH:mm")} - {format(validEndDate, "HH:mm")}
                        </span>
                    </div>
                    {event.location && (
                        <div className="flex items-center text-base text-zinc-400 group-hover:text-zinc-300 transition-colors">
                            <MapPin className="w-5 h-5 mr-3 text-zinc-500 shrink-0" />
                            <span className="truncate">{event.location}</span>
                        </div>
                    )}
                </div>

                <Separator className="bg-zinc-800/50" />

                {/* Creator */}
                {event.creator && (
                    <div className="flex items-center gap-3">
                        <Avatar className="h-8 w-8 ring-1 ring-zinc-800">
                            <AvatarImage src={event.creator.image} />
                            <AvatarFallback className="text-xs bg-zinc-800 text-zinc-400">
                                {event.creator.name?.[0]?.toUpperCase() || "?"}
                            </AvatarFallback>
                        </Avatar>
                        <div className="flex flex-col">
                            <span className="text-[11px] text-zinc-500 uppercase tracking-wider font-semibold">Organisé par</span>
                            <span className={cn("text-sm font-medium transition-colors", theme.color)}>{displayCreatorName}</span>
                        </div>
                    </div>
                )}
            </CardContent>

            <CardFooter className="p-5 pt-0 mt-auto">
                <div className="w-full flex flex-col gap-2 p-3 rounded-lg bg-zinc-950/30 border border-zinc-800/30 transition-colors hover:bg-zinc-950/50">
                    <div className="flex items-center justify-between mb-1">
                        <span className="text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">Participants</span>
                        <div className="flex items-center text-xs font-medium text-zinc-500">
                            <Users className="w-3 h-3 mr-1.5" />
                            {displayAttendeeCount}
                            {event.maxParticipants && <span className="mx-0.5 opacity-50">/</span>}
                            {event.maxParticipants && <span>{event.maxParticipants}</span>}
                        </div>
                    </div>

                    <div className="flex flex-col gap-2">
                        {attendeesGoing.length > 0 ? (
                            attendeesGoing.slice(0, 3).map((a: any, idx: number) => {
                                // For Kralamoure events, participants are objects { username, character_count } or strings
                                // For other events, participants have user objects
                                const participantName = isKralamoure
                                    ? (typeof a === 'string' ? a : a.username || a.name || 'Inconnu')
                                    : (a.user?.profiles?.[0]?.discordNickname || a.user?.name || 'Inconnu');
                                const participantInitial = participantName?.[0]?.toUpperCase() || '?';

                                return (
                                    <div key={isKralamoure ? `${idx}-${participantName}` : a.id} className="flex items-center gap-2.5">
                                        <Avatar className="h-6 w-6 border border-zinc-700/50 shadow-sm relative z-0">
                                            {!isKralamoure && a.user?.image && <AvatarImage src={a.user.image} />}
                                            <AvatarFallback className="text-[9px] bg-zinc-800 text-zinc-400">
                                                {participantInitial}
                                            </AvatarFallback>
                                        </Avatar>
                                        <span className="text-sm text-zinc-300 font-medium truncate">
                                            {participantName}
                                        </span>
                                    </div>
                                );
                            })
                        ) : (
                            <span className="text-sm text-zinc-600 italic">Aucun participant</span>
                        )}

                        {attendeesGoing.length > 3 && (
                            <div className="pl-9 text-xs text-zinc-500 font-medium">
                                +{attendeesGoing.length - 3} autres...
                            </div>
                        )}
                    </div>
                </div>
            </CardFooter>
        </Card>
    );
}

