    status: string;
    startDate: Date | string;
    endDate: Date | string;
    location?: string | null;
    maxParticipants?: number | null;
    creator: {
        id: string;
        name: string | null;
        image: string | null;
    };
    participants: Participant[];
    discordMessageId?: string | null;
}

interface DiscordRole {
    id: string;
    name: string;
    color?: number;
}

interface EventDetailModalProps {
    event: EventDetail | null;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    currentUserId: string;
    guildId: string;
    canManage?: boolean;
    discordRoles?: DiscordRole[];
    onRegister?: (data: { classe?: string; comment?: string }) => Promise<void>;
    onUnregister?: () => Promise<void>;
    onEdit?: () => void;
    onDelete?: () => Promise<void>;
    onPublish?: () => Promise<void>;
    onComplete?: () => Promise<void>;
    onSendReminder?: (roleId?: string) => Promise<{ success: boolean; sentCount?: number; discordSent?: boolean; error?: string }>;
    onShareDiscord?: (roleId?: string) => Promise<{ success: boolean; error?: string }>;
    hasMetamobKey?: boolean;
}

// ============================================
// COMPONENT
// ============================================

export function EventDetailModal({
    event,
    open,
    onOpenChange,
    currentUserId,
    guildId,
    canManage = false,
    discordRoles = [],
    onRegister,
    onUnregister,
    onEdit,
    onDelete,
    onPublish,
    onComplete,
    onSendReminder,
    onShareDiscord,
    hasMetamobKey = false
}: EventDetailModalProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [showRegistration, setShowRegistration] = useState(false);
    // Discord dialog state
    const [discordDialogOpen, setDiscordDialogOpen] = useState(false);
    const [discordDialogMode, setDiscordDialogMode] = useState<"REMINDER" | "SHARE">("SHARE");

    // Delete confirmation state
    const [isDeleteConfirming, setIsDeleteConfirming] = useState(false);

    if (!event) return null;

    const typeConfig = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
    const statusConfig = STATUS_CONFIG[event.status] || STATUS_CONFIG.DRAFT;

    const registeredCount = event.participants.filter(p => p.status === "REGISTERED").length;
    const reserveCount = event.participants.filter(p => p.status === "RESERVE").length;
    const isUserRegistered = event.participants.some(p => p.user.id === currentUserId && p.status !== "DECLINED");
    const userParticipant = event.participants.find(p => p.user.id === currentUserId);

    // Distinguish between direct Metamob events (krala-{id}) and imported events
    const isDirectKralamoure = event.id.startsWith("krala-");
    const isImportedKralamoure = event.type === "KRALAMOURE" && !isDirectKralamoure;
    const isExternal = isDirectKralamoure; // Only direct Kralamoure events are truly external

    const isOpen = event.status === "PUBLISHED";
    const isFull = event.maxParticipants ? registeredCount >= event.maxParticipants : false;
    const isCreator = event.creator.id === currentUserId;
    const isRegistered = isUserRegistered;
    const canRegister = isOpen && !isRegistered && !isExternal;

    // Extract Metamob creator from metadata or description for Kralamoure events
    const eventMetadata = (event as any).metadata as any;
    const metamobCreator = (isDirectKralamoure || isImportedKralamoure)
        ? (eventMetadata?.metamobCreator || event.creator.name)
        : null;

    const handleAction = async (action: () => Promise<void>) => {
        setIsLoading(true);
        try {
            await action();
        } catch (error) {
            toast.error("Une erreur est survenue");
        } finally {
            setIsLoading(false);
        }
    };

    const handleRegistration = async (data: { classe?: string; comment?: string }) => {
        if (onRegister) {
            await onRegister(data);
        }
    };

    const handleDelete = async () => {
        if (!onDelete) return;

        setIsLoading(true);
        try {
            await onDelete();
            onOpenChange(false);
            toast.success("Événement supprimé");
        } catch (error) {
            toast.error("Erreur lors de la suppression");
        } finally {
            setIsLoading(false);
        }
    };



    const TypeIcon = typeConfig.icon;

    return (
        <>
            <Dialog open={open} onOpenChange={onOpenChange}>
                <DialogContent
                    draggable
                    className="w-[95vw] sm:max-w-2xl bg-zinc-900/95 backdrop-blur-xl border-zinc-800 p-0 overflow-hidden max-h-[90vh] flex flex-col"
                >
                    {/* Header */}
                    <div className={cn("relative px-8 py-8 border-b border-zinc-800/50 overflow-hidden", typeConfig.bgColor)}>
                        <div className={cn("absolute inset-0 opacity-40 bg-gradient-to-br", typeConfig.gradient)} />

                        <div className="relative flex justify-between items-start z-10 w-full pr-8">
                            <div className="flex gap-5">
                                <div className={cn(
                                    "p-3.5 rounded-2xl shadow-inner shrink-0",
                                    "bg-black/20 text-white backdrop-blur-sm border border-white/10"
                                )}>
                                    <TypeIcon className="w-7 h-7" />
                                </div>

                                <div className="space-y-3">
                                    <div className="flex items-center gap-2">
                                        <Badge variant="outline" className={cn("text-xs font-black uppercase tracking-wider", typeConfig.color, "border-current/30 bg-current/5 px-2.5 py-0.5")}>
                                            {typeConfig.label}
                                        </Badge>
                                        <Badge className={cn("text-xs font-black uppercase tracking-wider px-2.5 py-0.5", statusConfig.bg)}>
                                            {statusConfig.label}
                                        </Badge>
                                    </div>
                                    <DialogHeader>
                                        <DialogTitle className="text-3xl font-black tracking-tight text-white uppercase italic">
                                            {event.title}
                                        </DialogTitle>
                                    </DialogHeader>
                                </div>
                            </div>

                            {/* Move Complete Button Here */}
                            {canManage && (
                                <div className="flex items-center gap-2 ml-4">
                                    {/* Delete button for imported Kralamoure events */}
                                    {isImportedKralamoure && onDelete && (
                                        <Button
                                            size="sm"
                                            variant={isDeleteConfirming ? "destructive" : "ghost"}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (isDeleteConfirming) {
                                                    handleDelete();
                                                } else {
                                                    setIsDeleteConfirming(true);
                                                    setTimeout(() => setIsDeleteConfirming(false), 3000);
                                                }
                                            }}
                                            disabled={isLoading}
                                            className={cn(
                                                "transition-all",
                                                isDeleteConfirming
                                                    ? "bg-red-600 hover:bg-red-700 text-white"
                                                    : "text-zinc-400 hover:text-red-400 hover:bg-red-950/20"
                                            )}
                                        >
                                            <Trash2 className="h-4 w-4 mr-1.5" />
                                            {isDeleteConfirming ? "Confirmer" : "Supprimer"}
                                        </Button>
                                    )}

                                    {event.status === "PUBLISHED" && onComplete && (
                                        <Button
                                            size="sm"
                                            onClick={() => handleAction(onComplete)}
                                            disabled={isLoading}
                                            className="bg-blue-600/80 hover:bg-blue-500 text-white shadow-sm border border-blue-500/50"
                                        >
                                            <Check className="h-4 w-4 mr-1.5" />
                                            Terminer l'event
                                        </Button>
                                    )}
                                    {event.status === "COMPLETED" && (
                                        <Badge variant="secondary" className="bg-zinc-950/50 text-zinc-400 border-zinc-700 px-3 py-1.5 text-xs font-semibold uppercase tracking-wider">
                                            Event terminé
                                        </Badge>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <InfoCard
                                icon={<Calendar className="h-4 w-4 text-amber-500" />}
                                label="Date"
                                value={format(new Date(event.startDate), "EEEE d MMMM", { locale: fr })}
                            />
                            <InfoCard
                                icon={<Clock className="h-4 w-4 text-blue-400" />}
                                label="Horaires"
                                value={`${format(new Date(event.startDate), "HH:mm")} - ${format(new Date(event.endDate), "HH:mm")}`}
                            />
                            <InfoCard
                                icon={<Users className="h-4 w-4 text-purple-400" />}
                                label="Participants"
                                value={
                                    <span>
                                        {registeredCount > 0 ? registeredCount : (
                                            (isDirectKralamoure || isImportedKralamoure) ? (eventMetadata?.metamobParticipantsCount || 0) : 0
                                        )}
                                        {event.maxParticipants && <span className="text-zinc-500"> / {event.maxParticipants}</span>}
                                        {reserveCount > 0 && <span className="text-amber-400 ml-2">+{reserveCount}</span>}
                                    </span>
                                }
                            />
                            <InfoCard
                                icon={<Crown className="h-4 w-4 text-yellow-500" />}
                                label="Organisé par"
                                value={
                                    (isDirectKralamoure || isImportedKralamoure) && metamobCreator ? (
                                        <div className="flex items-center gap-2">
                                            <span className="truncate max-w-[120px]" title={metamobCreator}>
                                                {metamobCreator}
                                            </span>
                                        </div>
                                    ) : event.creator ? (
                                        <div className="flex items-center gap-2">
                                            <Avatar className="h-5 w-5 border border-zinc-700">
                                                <AvatarImage src={event.creator.image || undefined} />
                                                <AvatarFallback className="text-[10px] bg-zinc-800">
                                                    {event.creator.name?.charAt(0) || "?"}
                                                </AvatarFallback>
                                            </Avatar>
                                            <span className="truncate max-w-[120px]" title={event.creator.name || "Inconnu"}>
                                                {event.creator.name || "Inconnu"}
                                            </span>
                                        </div>
                                    ) : (
                                        <span className="text-zinc-500">Inconnu</span>
                                    )
                                }
                            />
                        </div>



                        {/* Description */}
                        {event.description && (
                            <div className="p-3 rounded-lg bg-zinc-800/30 border border-zinc-700/30">
                                <p className="text-sm text-zinc-300 whitespace-pre-wrap">{event.description}</p>
                            </div>
                        )}

                        <Separator className="bg-zinc-800/50" />

                        {/* Roster */}
                        {(() => {
                            const isKrala = isDirectKralamoure || isImportedKralamoure;
                            const cachedCount = isKrala ? (eventMetadata?.metamobParticipantsCount || 0) : 0;
                            const displayCount = registeredCount > 0 ? registeredCount : cachedCount;

                            return (
                                <div>
                                    <h3 className="text-sm font-semibold text-zinc-300 mb-3 flex items-center gap-2">
                                        <Users className="h-4 w-4" />
                                        Participants{isKrala ? " Metamob" : ""} ({displayCount})
                                    </h3>

                                    <ScrollArea className="h-48">
                                        <div className="space-y-2">
                                            {/* Standard DB Participants */}
                                            {event.participants
                                                .filter(p => p.status === "REGISTERED")
                                                .sort((a, b) => a.position - b.position)
                                                .map((participant) => (
                                                    <ParticipantRow
                                                        key={participant.id}
                                                        participant={participant}
                                                        isCreator={participant.user.id === event.creator.id}
                                                        isCurrentUser={participant.user.id === currentUserId}
                                                        onUnregister={!isExternal && onUnregister ? () => handleAction(onUnregister) : undefined}
                                                    />
                                                ))}

                                            {/* Metamob Metadata Participants Fallback */}
                                            {isKrala && event.participants.length === 0 && (eventMetadata?.metamobParticipants || []).length > 0 && (
                                                (eventMetadata.metamobParticipants as any[]).map((p, i) => (
                                                    <div key={`meta-${i}`} className="flex items-center justify-between p-2.5 rounded-lg bg-zinc-800/30">
                                                        <div className="flex items-center gap-3 min-w-0">
                                                            <span className="h-6 w-6 rounded-full flex items-center justify-center text-xs font-bold shrink-0 bg-zinc-700 text-zinc-300">
                                                                {i + 1}
                                                            </span>
                                                            <Avatar className="h-8 w-8 border-2 border-zinc-700/50">
                                                                <AvatarFallback className="bg-zinc-700 text-zinc-300 text-xs">
                                                                    {p.username?.[0] || "?"}
                                                                </AvatarFallback>
                                                            </Avatar>
                                                            <div className="min-w-0">
                                                                <span className="text-sm font-medium text-zinc-200 truncate">
                                                                    {p.username || "Anonyme"} {p.character_count ? `(${p.character_count})` : ""}
                                                                </span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                ))
                                            )}

                                            {reserveCount > 0 && (
                                                <>
                                                    <div className="text-xs text-amber-400 font-medium mt-4 mb-2 flex items-center gap-2">
                                                        <div className="h-px bg-zinc-800/50 flex-1" />
                                                        <Clock className="h-3 w-3" />
                                                        File d&apos;attente ({reserveCount})
                                                        <div className="h-px bg-zinc-800/50 flex-1" />
                                                    </div>
                                                    {event.participants
                                                        .filter(p => p.status === "RESERVE")
                                                        .sort((a, b) => a.position - b.position)
                                                        .map((participant) => (
                                                            <ParticipantRow
                                                                key={participant.id}
                                                                participant={participant}
                                                                isReserve
                                                                isCurrentUser={participant.user.id === currentUserId}
                                                                onUnregister={onUnregister ? () => handleAction(onUnregister) : undefined}
                                                            />
                                                        ))}
                                                </>
                                            )}

                                            {event.participants.length === 0 && (!isKrala || (eventMetadata?.metamobParticipants || []).length === 0) && (
                                                <div className="text-center py-12 rounded-xl border-2 border-dashed border-zinc-800/50 bg-zinc-900/20">
                                                    <User className="h-10 w-10 mx-auto mb-3 text-zinc-600 opacity-50" />
                                                    <p className="text-zinc-400 font-medium">
                                                        {isKrala 
                                                            ? "Détails des participants indisponibles" 
                                                            : "Aucun participant inscrit"
                                                        }
                                                    </p>
                                                    {isKrala && (
                                                        <p className="text-xs text-zinc-500 mt-2 px-6">
                                                            Les inscrits sur Metamob ne sont pas encore synchronisés ou nécessitent une clé API valide.
                                                        </p>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    </ScrollArea>
                                </div>
                            );
                        })()}
                    </div>



                    {/* Footer */}
                    <div className="px-6 py-4 bg-zinc-950/50 border-t border-zinc-800/50 space-y-3">
                        {/* User Actions */}
                        <div className="flex items-center gap-2 flex-wrap">
                            {(isDirectKralamoure || isImportedKralamoure) ? (
                                <div className="flex flex-col gap-3 w-full">
                                    <div className="flex items-center gap-2">
                                        <Button
                                            asChild
                                            className="bg-pink-600 hover:bg-pink-500 text-white font-bold shadow-lg shadow-pink-500/20"
                                        >
                                            <a
                                                href="https://metamob.fr/kralove"
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="flex items-center w-full h-full px-4 py-2"
                                            >
                                                <ExternalLink className="h-4 w-4 mr-2" />
                                                S'inscrire sur Metamob
                                            </a>
                                        </Button>

                                        {!hasMetamobKey && (
                                            <Button
                                                asChild
                                                variant="outline"
                                                className="border-pink-500/30 text-pink-400 hover:bg-pink-500/10 hover:border-pink-500/50"
                                            >
                                                <a href={`/dashboard/${guildId}/profile`}>
                                                    Lier mon compte Metamob
                                                </a>
                                            </Button>
                                        )}
                                    </div>
                                    {!hasMetamobKey && (
                                        <p className="text-[11px] text-zinc-500 italic">
                                            Liez votre compte pour que SigilOS puisse synchroniser votre état de jeu.
                                        </p>
                                    )}
                                </div>
                            ) : (
                                <>
                                    {canRegister && (
                                        <Button
                                            size="lg"
                                            onClick={() => setShowRegistration(true)}
                                            disabled={isLoading}
                                            className={cn(
                                                "h-12 rounded-xl font-black text-sm uppercase tracking-wider transition-all duration-300 shadow-lg relative group overflow-hidden border-t border-white/10 px-8",
                                                isFull
                                                    ? "bg-amber-600 hover:bg-amber-500 shadow-amber-600/30 text-white"
                                                    : "bg-indigo-600 hover:bg-indigo-500 shadow-indigo-600/30 text-white"
                                            )}
                                        >
                                            <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                                            {isFull ? <Users className="h-4 w-4 mr-2.5" /> : <Check className="h-4 w-4 mr-2.5" />}
                                            {isFull ? "Rejoindre la file d'attente" : "S'inscrire à l'événement"}
                                        </Button>
                                    )}

                                    {isRegistered && onUnregister && (
                                        <Button
                                            size="lg"
                                            variant="outline"
                                            onClick={() => handleAction(onUnregister)}
                                            disabled={isLoading}
                                            className="h-12 rounded-xl font-bold text-sm border-zinc-700 bg-zinc-800/50 text-zinc-400 hover:bg-red-500/10 hover:text-red-400 hover:border-red-500/30 transition-all duration-300 px-6"
                                        >
                                            <X className="h-4 w-4 mr-2" />
                                            Se désinscrire
                                        </Button>
                                    )}
                                </>
                            )}
                        </div>

                        {/* Admin Actions */}
                        {canManage && !isExternal && (
                            <div className="flex items-center gap-2 flex-wrap pt-2 border-t border-zinc-800/30">
                                {onDelete && (
                                    <Button
                                        size="sm"
                                        variant={isDeleteConfirming ? "destructive" : "ghost"}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            if (isDeleteConfirming) {
                                                handleDelete();
                                            } else {
                                                setIsDeleteConfirming(true);
                                                setTimeout(() => setIsDeleteConfirming(false), 3000);
                                            }
                                        }}
                                        disabled={isLoading}
                                        className={cn(
                                            "mr-auto transition-all",
                                            isDeleteConfirming
                                                ? "bg-red-600 hover:bg-red-700 text-white px-4"
                                                : "text-zinc-500 hover:text-red-400 hover:bg-red-950/20"
                                        )}
                                    >
                                        <Trash2 className="h-4 w-4 mr-2" />
                                        {isDeleteConfirming ? "Confirmer la suppression" : "Supprimer l'event"}
                                    </Button>
                                )}

                                {canManage && !event.discordMessageId && onPublish && (
                                        <Button
                                            size="sm"
                                            onClick={() => handleAction(onPublish)}
                                            disabled={isLoading}
                                            className="bg-green-600 hover:bg-green-500 font-bold"
                                        >
                                            <Share2 className="w-3.5 h-3.5 mr-2" />
                                            Publier sur Discord
                                        </Button>
                                )}

                                {event.status === "PUBLISHED" && onSendReminder && event.participants.length > 0 && (
                                        <Button
                                            size="sm"
                                            variant="ghost"
                                            disabled={isLoading}
                                            onClick={() => {
                                                setDiscordDialogMode("REMINDER");
                                                setDiscordDialogOpen(true);
                                            }}
                                            className="text-amber-400 hover:bg-amber-500/10 rounded-full font-bold px-4 h-9"
                                        >
                                            <Bell className="h-4 w-4 mr-2" />
                                            Rappel inscrits
                                        </Button>
                                )}

                                {event.status === "PUBLISHED" && onShareDiscord && (
                                        <Button
                                            size="sm"
                                            variant="ghost"
                                            disabled={isLoading}
                                            onClick={() => {
                                                setDiscordDialogMode("SHARE");
                                                setDiscordDialogOpen(true);
                                            }}
                                            className="text-indigo-400 hover:bg-indigo-500/10 rounded-full font-bold px-4 h-9"
                                        >
                                            <Share2 className="h-4 w-4 mr-2" />
                                            Reposter l'annonce
                                        </Button>
                                )}

                                {onEdit && (
                                    <Button
                                        size="sm"
                                        variant="ghost"
                                        onClick={onEdit}
                                        className="text-zinc-400 hover:text-zinc-100"
                                    >
                                        <Edit className="h-4 w-4 mr-1" />
                                        Éditer
                                    </Button>
                                )}
                            </div>
                        )}
                    </div>
                </DialogContent>
            </Dialog>

            <RegistrationModal
                open={showRegistration}
                onOpenChange={setShowRegistration}
                eventTitle={event.title}
                isFull={isFull}
                onSubmit={handleRegistration}
            />

            <CalendarDiscordDialog
                isOpen={discordDialogOpen}
                onOpenChange={setDiscordDialogOpen}
                guildId={guildId}
                eventId={event.id}
                roles={discordRoles}
                mode={discordDialogMode}
                onConfirm={async (roleId) => {
                    if (discordDialogMode === "REMINDER" && onSendReminder) {
                        return await onSendReminder(roleId);
                    } else if (discordDialogMode === "SHARE" && onShareDiscord) {
                        return await onShareDiscord(roleId);
                    }
                    return { success: false, error: "Action non définie" };
                }}
            />
        </>
    );
}

// ============================================
// HELPER COMPONENTS
// ============================================

function InfoCard({ icon, label, value }: { icon: React.ReactNode; label: string; value: React.ReactNode }) {
    return (
        <div className="flex items-center gap-3 text-sm">
            <div className="h-9 w-9 rounded-lg bg-zinc-800/50 flex items-center justify-center shrink-0">
                {icon}
            </div>
            <div className="min-w-0">
                <p className="text-zinc-500 text-xs">{label}</p>
                <div className="text-zinc-100 font-medium truncate">{value}</div>
            </div>
        </div>
    );
}

function ParticipantRow({
    participant,
    isCreator = false,
    isReserve = false,
    isCurrentUser = false,
    onUnregister
}: {
    participant: Participant;
    isCreator?: boolean;
    isReserve?: boolean;
    isCurrentUser?: boolean;
    onUnregister?: () => void;
}) {
    const [isConfirming, setIsConfirming] = useState(false);

    return (
        <div className={cn(
            "flex items-center justify-between p-2.5 rounded-lg transition-colors group",
            isReserve ? "bg-amber-500/5 border border-amber-500/10" : "bg-zinc-800/30 hover:bg-zinc-800/50"
        )}>
            <div className="flex items-center gap-3 min-w-0">
                <span className={cn(
                    "h-6 w-6 rounded-full flex items-center justify-center text-xs font-bold shrink-0",
                    isReserve ? "bg-amber-500/20 text-amber-400" : "bg-zinc-700 text-zinc-300"
                )}>
                    {participant.position}
                </span>
                <Avatar className="h-8 w-8 border-2 border-zinc-700/50">
                    <AvatarImage src={participant.user.image || undefined} />
                    <AvatarFallback className="bg-zinc-700 text-zinc-300 text-xs">
                        {participant.user.name?.charAt(0) || "?"}
                    </AvatarFallback>
                </Avatar>
                <div className="min-w-0">
                    <div className="flex items-center gap-2">
                        <span className={cn("text-sm font-medium truncate", isCurrentUser ? "text-indigo-400" : "text-zinc-200")}>
                            {participant.user.profiles?.[0]?.discordNickname || participant.user.name || "Anonyme"}
                            {isCurrentUser && " (Moi)"}
                        </span>
                        {isCreator && (
                            <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger>
                                        <Crown className="h-3.5 w-3.5 text-amber-500" />
                                    </TooltipTrigger>
                                    <TooltipContent>Organisateur</TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        )}
                    </div>
                    <div className="flex items-center gap-2">
                        {participant.classe && (
                            <div
                                className="flex items-center gap-1.5 px-2 py-0.5 rounded text-xs font-medium"
                                style={{
                                    backgroundColor: `${getClassColor(participant.classe)}15`,
                                    color: getClassColor(participant.classe)
                                }}
                            >
                                <ClassIcon classId={participant.classe} size={16} showName />
                            </div>
                        )}
                        {participant.comment && (
                            <span className="text-[10px] text-zinc-500 italic truncate max-w-[100px]">
                                "{participant.comment}"
                            </span>
                        )}
                    </div>
                </div>
            </div>

            {/* Unregister Button (visible only for current user) */}
            {isCurrentUser && onUnregister && (
                <Button
                    size={isConfirming ? "sm" : "icon"}
                    variant={isConfirming ? "destructive" : "ghost"}
                    onClick={(e) => {
                        e.stopPropagation();
                        if (isConfirming) {
                            onUnregister();
                        } else {
                            setIsConfirming(true);
                            setTimeout(() => setIsConfirming(false), 3000); // Reset after 3s
                        }
                    }}
                    className={cn(
                        "shrink-0 transition-all",
                        isConfirming
                            ? "h-8 px-3 text-xs font-medium"
                            : "h-8 w-8 text-zinc-500 hover:text-red-400 hover:bg-red-500/10"
                    )}
                    title="Se désinscrire"
                >
                    {isConfirming ? (
                        <span className="flex items-center gap-1">
                            <X className="h-3 w-3" />
                            Confirmer
                        </span>
                    ) : (
                        <X className="h-4 w-4" />
                    )}
                </Button>
            )}
        </div>
    );
}

"use client";

/**
 * EventForm V3 - Fixed Date Handling + 4 Types
 * Types: RAID_OFFICIAL, EVENT_GUILD, SESSION_MISSIONS, SORTIE_FARM
 */

import { useState, useEffect } from "react";
import { z } from "zod";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { format, parse, addHours, isBefore } from "date-fns";
import { fr } from "date-fns/locale";
import {
    Calendar as CalendarIcon,
    Clock,
    Loader2,
    Users,
    Swords,
    PartyPopper,
    Target,
    Wheat,
    Info,
    AlertTriangle,
    Diamond
} from "lucide-react";
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import {
    Popover,
    PopoverContent,
    PopoverTrigger
} from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { cn } from "@/lib/utils";

// ============================================
// 4 EVENT TYPES (Almanax removed)
// ============================================

interface TypeConfig {
    label: string;
    shortLabel: string;
    icon: React.ElementType;
    gradient: string;
    bg: string;
    border: string;
    text: string;
    preset: {
        defaultDuration: number;
        maxParticipants?: number;
    };
}

const TYPE_CONFIG: Record<string, TypeConfig> = {
    RAID_OFFICIAL: {
        label: "Raid Officiel 3.6",
        shortLabel: "Raid 3.6",
        icon: Swords,
        gradient: "from-red-600 to-rose-600",
        bg: "bg-red-500/10",
        border: "border-red-500/30",
        text: "text-red-400",
        preset: { defaultDuration: 3, maxParticipants: 12 }
    },
    EVENT_GUILD: {
        label: "Event Guilde (Mini-jeux)",
        shortLabel: "Event Guilde",
        icon: PartyPopper,
        gradient: "from-purple-600 to-fuchsia-600",
        bg: "bg-purple-500/10",
        border: "border-purple-500/30",
        text: "text-purple-400",
        preset: { defaultDuration: 2 }
    },
    SESSION_MISSIONS: {
        label: "Missions Guilde",
        shortLabel: "Missions Guilde",
        icon: Target,
        gradient: "from-amber-600 to-orange-600",
        bg: "bg-amber-500/10",
        border: "border-amber-500/30",
        text: "text-amber-400",
        preset: { defaultDuration: 4, maxParticipants: 8 }
    },
    SORTIE_FARM: {
        label: "Sortie Farm / Drop",
        shortLabel: "Sortie Farm",
        icon: Wheat,
        gradient: "from-emerald-600 to-green-600",
        bg: "bg-emerald-500/10",
        border: "border-emerald-500/30",
        text: "text-emerald-400",
        preset: { defaultDuration: 2 }
    },
    OTHERS: {
        label: "Autres activités",
        shortLabel: "Autres",
        icon: Diamond,
        gradient: "from-slate-600 to-zinc-600",
        bg: "bg-slate-500/10",
        border: "border-slate-500/30",
        text: "text-slate-400",
        preset: { defaultDuration: 2 }
    },
};

const EVENT_TYPES = Object.keys(TYPE_CONFIG);

// ============================================
// ZOD SCHEMA with better date validation
// ============================================

const eventFormSchema = z.object({
    title: z.string().min(3, "Le titre doit faire au moins 3 caractères").max(100),
    description: z.string().max(2000).optional(),
    type: z.string(),
    date: z.date({ required_error: "Date requise" }),
    startTime: z.string().min(5, "Heure requise"),
    endTime: z.string().min(5, "Heure requise"),
    maxParticipants: z.coerce.number().min(1).optional().nullable(),
    publishOnDiscord: z.boolean().optional(),
}).refine((data) => {
    // Validate end time is after start time
    const start = parse(data.startTime, "HH:mm", new Date());
    const end = parse(data.endTime, "HH:mm", new Date());
    // Handle case where end is next day (e.g., 23:00 - 01:00)
    if (data.endTime < data.startTime) return true; // Considered next day
    return !isBefore(end, start);
}, {
    message: "L'heure de fin doit être après l'heure de début",
    path: ["endTime"]
});

type EventFormValues = z.infer<typeof eventFormSchema>;

// ============================================
// COMPONENT
// ============================================

interface EventFormProps {
    initialData?: any;
    onSubmit: (data: any) => Promise<void>;
    isDiscordConfigured?: boolean;
}

export function EventForm({ initialData, onSubmit, isDiscordConfigured }: EventFormProps) {
    const [submitting, setSubmitting] = useState(false);
    // Fallback to EVENT_GUILD for unknown types
    const validType = initialData?.type && TYPE_CONFIG[initialData.type] ? initialData.type : "EVENT_GUILD";
    const [selectedType, setSelectedType] = useState<string>(validType);

    const form = useForm<EventFormValues>({
        resolver: zodResolver(eventFormSchema),
        defaultValues: initialData ? {
            title: initialData.title || "",
            description: initialData.description || "",
            type: validType,
            date: initialData.startDate ? new Date(initialData.startDate) : new Date(),
            startTime: initialData.startDate 
                ? format(new Date(initialData.startDate), "HH:mm") 
                : "20:00",
            endTime: initialData.endDate 
                ? format(new Date(initialData.endDate), "HH:mm") 
                : "22:00",
            maxParticipants: initialData.maxParticipants || undefined,
            publishOnDiscord: false, // Default to false when editing
        } : {
            title: "",
            description: "",
            type: "EVENT_GUILD",
            date: new Date(),
            startTime: "20:00",
            endTime: "22:00",
            maxParticipants: undefined,
            publishOnDiscord: !!isDiscordConfigured,
        },
    });

    // Watch start time to auto-update end time
    const startTime = form.watch("startTime");

    // Apply preset when type changes
    const handleTypeChange = (type: string) => {
        setSelectedType(type);
        form.setValue("type", type);

        const config = TYPE_CONFIG[type];
        if (config && !initialData) {
            if (config.preset.maxParticipants) {
                form.setValue("maxParticipants", config.preset.maxParticipants);
            }
            // Auto-calculate end time based on duration
            updateEndTime(startTime, config.preset.defaultDuration);
        }
    };

    // Helper to update end time
    const updateEndTime = (start: string, durationHours: number) => {
        if (start) {
            const [hours, minutes] = start.split(":").map(Number);
            const startDate = new Date();
            startDate.setHours(hours, minutes, 0, 0);
            const endDate = addHours(startDate, durationHours);
            form.setValue("endTime", format(endDate, "HH:mm"));
        }
    };

    // Update end time when start time changes (only if not editing)
    useEffect(() => {
        if (!initialData && startTime) {
            const config = TYPE_CONFIG[selectedType];
            if (config) {
                updateEndTime(startTime, config.preset.defaultDuration);
            }
        }
    }, [startTime, selectedType, initialData]);

    const handleFormSubmit = async (values: EventFormValues) => {
        setSubmitting(true);
        try {
            // Build proper dates
            const dateStr = format(values.date, "yyyy-MM-dd");
            const startDate = new Date(`${dateStr}T${values.startTime}:00`);
            const endDate = new Date(`${dateStr}T${values.endTime}:00`);

            // If end time is before start time, assume next day
            if (endDate <= startDate) {
                endDate.setDate(endDate.getDate() + 1);
            }

            const submissionData = {
                title: values.title,
                description: values.description,
                type: values.type,
                startDate,
                endDate,
                maxParticipants: values.maxParticipants || null,
                publishOnDiscord: values.publishOnDiscord,
            };

            await onSubmit(submissionData);
        } catch (error) {
            console.error(error);
        } finally {
            setSubmitting(false);
        }
    };

    const currentConfig = TYPE_CONFIG[selectedType] || TYPE_CONFIG.EVENT_GUILD;

    return (
        <Form {...form}>
            <form onSubmit={form.handleSubmit(handleFormSubmit)} className="space-y-5">
                {/* ============ TYPE SELECTOR (4 types) ============ */}
                <div className="space-y-3">
                    <FormLabel className="text-sm font-medium text-zinc-300">
                        Type d'événement
                    </FormLabel>
                    <div className="grid grid-cols-5 gap-2">
                        {EVENT_TYPES.map((type) => {
                            const config = TYPE_CONFIG[type];
                            const Icon = config.icon;
                            const isSelected = selectedType === type;

                            return (
                                <button
                                    key={type}
                                    type="button"
                                    onClick={() => handleTypeChange(type)}
                                    className={cn(
                                        "relative flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all",
                                        isSelected
                                            ? cn(config.bg, config.border, "ring-2 ring-offset-2 ring-offset-zinc-900", config.border.replace("border-", "ring-"))
                                            : "bg-zinc-900/50 border-zinc-800 hover:border-zinc-700 hover:bg-zinc-800/50"
                                    )}
                                >
                                    <div className={cn(
                                        "h-10 w-10 rounded-lg flex items-center justify-center transition-all",
                                        isSelected
                                            ? cn("bg-gradient-to-br", config.gradient, "shadow-lg")
                                            : "bg-zinc-800"
                                    )}>
                                        <Icon className={cn(
                                            "h-5 w-5 transition-colors",
                                            isSelected ? "text-white" : "text-zinc-400"
                                        )} />
                                    </div>
                                    <span className={cn(
                                        "text-[11px] font-medium text-center leading-tight",
                                        isSelected ? config.text : "text-zinc-400"
                                    )}>
                                        {config.shortLabel}
                                    </span>
                                    {isSelected && (
                                        <div className={cn(
                                            "absolute -top-1 -right-1 h-3 w-3 rounded-full",
                                            "bg-gradient-to-br", config.gradient
                                        )} />
                                    )}
                                </button>
                            );
                        })}
                    </div>

                    {/* Preset badge */}
                    {currentConfig.preset.maxParticipants && (
                        <div className={cn(
                            "flex items-center gap-2 px-3 py-2 rounded-lg text-xs",
                            currentConfig.bg, currentConfig.border, "border"
                        )}>
                            <Info className={cn("h-3.5 w-3.5", currentConfig.text)} />
                            <span className="text-zinc-400">
                                <span className={currentConfig.text}>Preset :</span> {currentConfig.preset.maxParticipants} places
                            </span>
                        </div>
                    )}
                </div>

                {/* ============ TITLE ============ */}
                <FormField
                    control={form.control}
                    name="title"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel className="text-zinc-300">Titre</FormLabel>
                            <FormControl>
                                <Input
                                    placeholder="Ex: Raid Bethel - Farm clés"
                                    {...field}
                                    className="h-11 bg-zinc-900/50 border-zinc-800 text-zinc-100 focus:border-amber-500/50"
                                />
                            </FormControl>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                {/* ============ DATE & TIME (unified row) ============ */}
                <div className="space-y-2">
                    <FormLabel className="text-zinc-300">Date et horaires</FormLabel>
                    <div className="grid grid-cols-3 gap-3">
                        <FormField
                            control={form.control}
                            name="date"
                            render={({ field }) => (
                                <FormItem>
                                    <Popover>
                                        <PopoverTrigger asChild>
                                            <FormControl>
                                                <Button
                                                    variant="outline"
                                                    className={cn(
                                                        "h-11 w-full justify-start text-left font-normal bg-zinc-900/50 border-zinc-800 text-zinc-100 hover:bg-zinc-800/80",
                                                        !field.value && "text-muted-foreground"
                                                    )}
                                                >
                                                    <CalendarIcon className="mr-2 h-4 w-4 text-amber-500" />
                                                    {field.value ? format(field.value, "d MMM", { locale: fr }) : "Date"}
                                                </Button>
                                            </FormControl>
                                        </PopoverTrigger>
                                        <PopoverContent className="w-auto p-0 bg-zinc-900 border-zinc-800" align="start">
                                            <Calendar
                                                mode="single"
                                                selected={field.value}
                                                onSelect={field.onChange}
                                                disabled={(date) => date < new Date() && date.toDateString() !== new Date().toDateString()}
                                                initialFocus
                                                className="bg-zinc-900"
                                            />
                                        </PopoverContent>
                                    </Popover>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="startTime"
                            render={({ field }) => (
                                <FormItem>
                                    <FormControl>
                                        <div className="relative">
                                            <Clock className="absolute left-3 top-3.5 h-4 w-4 text-green-500" />
                                            <Input
                                                type="time"
                                                {...field}
                                                className="h-11 pl-10 bg-zinc-900/50 border-zinc-800 text-zinc-100"
                                            />
                                        </div>
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="endTime"
                            render={({ field }) => (
                                <FormItem>
                                    <FormControl>
                                        <div className="relative">
                                            <Clock className="absolute left-3 top-3.5 h-4 w-4 text-red-400" />
                                            <Input
                                                type="time"
                                                {...field}
                                                className="h-11 pl-10 bg-zinc-900/50 border-zinc-800 text-zinc-100"
                                            />
                                        </div>
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>
                </div>

                {/* ============ MAX PARTICIPANTS ============ */}
                <FormField
                    control={form.control}
                    name="maxParticipants"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel className="text-zinc-300">Places max</FormLabel>
                            <FormControl>
                                <div className="relative w-48">
                                    <Users className="absolute left-3 top-3.5 h-4 w-4 text-zinc-500" />
                                    <Input
                                        type="text"
                                        inputMode="numeric"
                                        pattern="[0-9]*"
                                        placeholder="∞"
                                        {...field}
                                        value={field.value || ""}
                                        onChange={(e) => {
                                            const value = e.target.value.replace(/[^0-9]/g, "");
                                            const numValue = value ? parseInt(value) : undefined;

                                            // Strict limit for Raids
                                            if (selectedType === "RAID_OFFICIAL" && numValue && numValue > 16) {
                                                field.onChange(16);
                                                return;
                                            }

                                            field.onChange(numValue);
                                        }}
                                        className="h-11 pl-10 bg-zinc-900/50 border-zinc-800 text-zinc-100"
                                    />
                                </div>
                            </FormControl>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                {/* ============ PUBLISH OPTION ============ */}
                <FormField
                    control={form.control}
                    name="publishOnDiscord"
                    render={({ field }) => (
                        <FormItem className="space-y-3">
                            <div className="flex flex-row items-center justify-between rounded-lg border border-border bg-background/50 p-4">
                                <div className="space-y-0.5">
                                    <FormLabel className="text-base text-zinc-100">
                                        Publier sur Discord
                                    </FormLabel>
                                    <div className="text-sm text-zinc-400">
                                        Envoie immédiatement l'annonce dans le canal configuré.
                                    </div>
                                </div>
                                <FormControl>
                                    <div className="flex items-center space-x-2">
                                        <Switch
                                            checked={field.value}
                                            onCheckedChange={field.onChange}
                                            disabled={!isDiscordConfigured}
                                        />
                                    </div>
                                </FormControl>
                            </div>
                            {!isDiscordConfigured && (
                                <p className="text-[10px] text-amber-500/80 font-bold uppercase tracking-tight italic px-2">
                                    ⚠️ Salon Discord non configuré par l'admin. Publication impossible.
                                </p>
                            )}
                        </FormItem>
                    )}
                />

                {/* ============ DESCRIPTION ============ */}
                <FormField
                    control={form.control}
                    name="description"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel className="text-zinc-300">Description</FormLabel>
                            <FormControl>
                                <Textarea
                                    placeholder="Détails, objectifs, pré-requis..."
                                    className="min-h-[70px] bg-zinc-900/50 border-zinc-800 text-zinc-100 resize-none"
                                    {...field}
                                    value={field.value || ""}
                                />
                            </FormControl>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                {/* ============ SUBMIT ============ */}
                <Button
                    type="submit"
                    disabled={submitting}
                    className={cn(
                        "w-full h-12 font-bold text-base transition-all",
                        "bg-gradient-to-r from-amber-500 to-orange-500",
                        "hover:from-amber-400 hover:to-orange-400",
                        "shadow-lg shadow-amber-500/20",
                        "text-zinc-950"
                    )}
                >
                    {submitting ? (
                        <>
                            <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                            Création...
                        </>
                    ) : (
                        <>
                            {currentConfig && <currentConfig.icon className="mr-2 h-5 w-5" />}
                            {initialData ? "Enregistrer" : "Créer l'événement"}
                        </>
                    )}
                </Button>
            </form>
        </Form>
    );
}

"use client";

import { useState, useEffect } from "react";
import { format, isToday, differenceInMinutes } from "date-fns";
import { fr } from "date-fns/locale";
import {
    Clock,
    Users,
    Swords,
    PartyPopper,
    Target,
    Wheat,
    Eye
} from "lucide-react";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";

const TYPE_CONFIG: Record<string, { label: string; icon: React.ElementType; color: string; bg: string }> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bg: "bg-red-500/10 border-red-500/20"
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bg: "bg-purple-500/10 border-purple-500/20"
    },
    SESSION_MISSIONS: {
        label: "Missions",
        icon: Target,
        color: "text-amber-400",
        bg: "bg-amber-500/10 border-amber-500/20"
    },
    SORTIE_FARM: {
        label: "Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bg: "bg-emerald-500/10 border-emerald-500/20"
    },
    KRALAMOURE: {
        label: "Kralamoure",
        icon: Eye,
        color: "text-pink-400",
        bg: "bg-pink-500/10 border-pink-500/20"
    }
};

interface FeaturedEventsCarouselProps {
    events: any[];
    onEventClick: (eventId: string) => void;
}

export function FeaturedEventsCarousel({ events, onEventClick }: FeaturedEventsCarouselProps) {
    const [currentIndex, setCurrentIndex] = useState(0);

    // Filter only future/today events and take next 5
    const upcoming = events
        .filter(e => new Date(e.startDate) >= new Date(new Date().setHours(0, 0, 0, 0)))
        .sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime())
        .slice(0, 5);

    useEffect(() => {
        if (upcoming.length <= 1) return;

        const interval = setInterval(() => {
            setCurrentIndex((prev) => (prev + 1) % upcoming.length);
        }, 5000);

        return () => clearInterval(interval);
    }, [upcoming.length]);

    if (upcoming.length === 0) return null;

    const event = upcoming[currentIndex];
    const config = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
    const startDate = new Date(event.startDate);

    // Participants logic
    const participantCount = event._count?.participants ||
        (event.participants ? event.participants.length : 0);
    const maxParticipants = event.maxParticipants;
    const isFull = maxParticipants && participantCount >= maxParticipants;

    return (
        <div className="flex justify-center w-full">
            <AnimatePresence mode="wait">
                <motion.button
                    key={event.id}
                    onClick={() => onEventClick(event.id)}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    transition={{ duration: 0.3 }}
                    className={cn(
                        "flex items-center gap-3 px-4 py-2 rounded-full border bg-zinc-900/50 backdrop-blur-md transition-all hover:bg-zinc-800/50 hover:scale-105 hover:border-zinc-700 group",
                        config.bg.replace("/10", "/20").replace("border-", "border-zinc-800/50 ")
                    )}
                >
                    {/* Status Dot */}
                    <div className={cn("h-2 w-2 rounded-full animate-pulse", config.color.replace("text-", "bg-"))} />

                    {/* Title */}
                    <span className="text-sm font-bold text-zinc-100 truncate max-w-[150px] group-hover:text-amber-400 transition-colors">
                        {event.title}
                    </span>

                    {/* Date */}
                    <span className="text-xs text-zinc-400 font-medium hidden sm:inline-block">
                        {isToday(startDate) ? "Aujourd'hui" : format(startDate, "dd MMM", { locale: fr })} {format(startDate, "HH:mm")}
                    </span>

                    {/* Participants */}
                    <span className={cn(
                        "text-xs font-medium px-2 py-0.5 rounded-full bg-zinc-950/30 border border-zinc-800 flex items-center gap-1",
                        isFull ? "text-red-400 border-red-900/30" : "text-zinc-500"
                    )}>
                        <Users className="h-3 w-3" />
                        {participantCount}{maxParticipants ? `/${maxParticipants}` : ""}
                    </span>
                </motion.button>
            </AnimatePresence>
        </div>
    );
}

"use client";

/**
 * Registration Modal - Class Selection & Signup
 * Uses existing ClassIcon from shared components
 */

import { useState } from "react";
import { Check, Loader2, User, MessageSquare } from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import { ClassIcon, getClassColor } from "@/components/shared/class-icon";

interface RegistrationModalProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    eventTitle: string;
    isFull: boolean;
    onSubmit: (data: { classe?: string; comment?: string }) => Promise<void>;
}

export function RegistrationModal({
    open,
    onOpenChange,
    eventTitle,
    isFull,
    onSubmit,
}: RegistrationModalProps) {
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [comment, setComment] = useState("");
    const [submitting, setSubmitting] = useState(false);

    const handleSubmit = async () => {
        setSubmitting(true);
        try {
            await onSubmit({
                classe: selectedClass || undefined,
                comment: comment || undefined,
            });
            onOpenChange(false);
            setSelectedClass(null);
            setComment("");
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent draggable className="max-w-lg bg-zinc-900/95 backdrop-blur-xl border-zinc-800">
                <DialogHeader>
                    <DialogTitle className="text-xl font-bold text-zinc-100">
                        {isFull ? "Rejoindre la file d'attente" : "S'inscrire à l'événement"}
                    </DialogTitle>
                    <DialogDescription className="text-zinc-400">
                        {eventTitle}
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-6 py-4 max-h-[60vh] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-zinc-700 scrollbar-track-transparent">
                    {/* Class Selection */}
                    <div className="space-y-3">
                        <Label className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                            <User className="h-4 w-4" />
                            Classe Dofus (optionnel)
                        </Label>

                        <div className="grid grid-cols-5 gap-2">
                            {DOFUS_CLASSES.map((classe) => {
                                const isSelected = selectedClass === classe.id;
                                const borderColor = isSelected ? classe.color : undefined;

                                return (
                                    <button
                                        key={classe.id}
                                        type="button"
                                        onClick={() => setSelectedClass(isSelected ? null : classe.id)}
                                        className={cn(
                                            "flex flex-col items-center gap-1 p-2 rounded-lg border-2 transition-all hover:bg-zinc-800/50",
                                            isSelected
                                                ? "ring-2 ring-offset-2 ring-offset-zinc-900"
                                                : "bg-zinc-900/50 border-zinc-800 hover:border-zinc-700"
                                        )}
                                        style={{
                                            borderColor: isSelected ? classe.color : undefined,
                                            boxShadow: isSelected ? `0 0 12px ${classe.color}40` : undefined,
                                            backgroundColor: isSelected ? `${classe.color}10` : undefined,
                                        }}
                                    >
                                        <ClassIcon classId={classe.id} size={28} />
                                        <span className={cn(
                                            "text-[10px] font-medium leading-tight",
                                            isSelected ? "text-white" : "text-zinc-500"
                                        )}>
                                            {classe.name}
                                        </span>
                                    </button>
                                );
                            })}
                        </div>

                        {selectedClass && (
                            <p className="text-xs text-zinc-500">
                                Sélection :{" "}
                                <span style={{ color: getClassColor(selectedClass) }}>
                                    {DOFUS_CLASSES.find(c => c.id === selectedClass)?.name}
                                </span>
                            </p>
                        )}
                    </div>

                    {/* Comment */}
                    <div className="space-y-2">
                        <Label className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                            <MessageSquare className="h-4 w-4" />
                            Note (optionnel)
                        </Label>
                        <Input
                            placeholder="Ex: Perso principal, Multi possible..."
                            value={comment}
                            onChange={(e) => setComment(e.target.value)}
                            className="bg-zinc-900/50 border-zinc-800 text-zinc-100"
                            maxLength={100}
                        />
                    </div>

                    {/* Warning if full */}
                    {isFull && (
                        <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/30">
                            <p className="text-sm text-amber-400">
                                ⚠️ L'événement est complet. Vous serez ajouté à la file d'attente et promu automatiquement en cas de désistement.
                            </p>
                        </div>
                    )}
                </div>

                <DialogFooter>
                    <Button
                        variant="ghost"
                        onClick={() => onOpenChange(false)}
                        disabled={submitting}
                        className="text-zinc-400"
                    >
                        Annuler
                    </Button>
                    <Button
                        onClick={handleSubmit}
                        disabled={submitting}
                        className={cn(
                            "font-bold",
                            isFull
                                ? "bg-amber-500 hover:bg-amber-400 text-zinc-950"
                                : "bg-green-600 hover:bg-green-500 text-white"
                        )}
                    >
                        {submitting ? (
                            <Loader2 className="h-4 w-4 animate-spin mr-2" />
                        ) : (
                            <Check className="h-4 w-4 mr-2" />
                        )}
                        {isFull ? "Rejoindre la file" : "Confirmer l'inscription"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

/**
 * UpcomingEventsWidget - Smart Events Preview
 * Shows next events with countdown and quick actions
 */

import { useState, useEffect, useMemo } from "react";
import { format, formatDistanceToNow, isPast, isFuture, isToday, differenceInHours, differenceInMinutes } from "date-fns";
import { fr } from "date-fns/locale";
import {
    Calendar,
    Clock,
    Users,
    ChevronRight,
    Bell,
    Flame,
    Swords,
    PartyPopper,
    Target,
    Wheat
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

// ============================================
// TYPES
// ============================================

interface UpcomingEvent {
    id: string;
    title: string;
    type: string;
    status: string;
    startDate: Date | string;
    endDate: Date | string;
    maxParticipants?: number | null;
    _count?: { participants: number };
}

interface UpcomingEventsWidgetProps {
    events: UpcomingEvent[];
    onEventClick: (eventId: string) => void;
    onViewAll?: () => void;
    maxEvents?: number;
    compact?: boolean;
}

// ============================================
// TYPE CONFIG
// ============================================

const TYPE_CONFIG: Record<string, { label: string; icon: React.ElementType; color: string; bg: string }> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bg: "bg-red-500/15 border-red-500/30"
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bg: "bg-purple-500/15 border-purple-500/30"
    },
    SESSION_MISSIONS: {
        label: "Missions Guilde",
        icon: Target,
        color: "text-amber-400",
        bg: "bg-amber-500/15 border-amber-500/30"
    },
    SORTIE_FARM: {
        label: "Sortie Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bg: "bg-emerald-500/15 border-emerald-500/30"
    },
};

// ============================================
// COMPONENT
// ============================================

export function UpcomingEventsWidget({
    events,
    onEventClick,
    onViewAll,
    maxEvents = 3,
    compact = false
}: UpcomingEventsWidgetProps) {
    const [now, setNow] = useState(new Date());

    // Update time every minute for countdown
    useEffect(() => {
        const interval = setInterval(() => setNow(new Date()), 60000);
        return () => clearInterval(interval);
    }, []);

    // Filter and sort upcoming events
    const upcomingEvents = useMemo(() => {
        return events
            .filter(e => {
                const startDate = new Date(e.startDate);
                return isFuture(startDate) || isToday(startDate);
            })
            .sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime())
            .slice(0, maxEvents);
    }, [events, maxEvents]);

    if (upcomingEvents.length === 0) {
        return null; // Don't show widget if no events
    }

    return (
        <div className={cn(
            "rounded-xl border border-zinc-800/50 overflow-hidden",
            compact ? "bg-zinc-900/40" : "bg-gradient-to-br from-zinc-900/80 to-zinc-950/80"
        )}>
            {/* Header */}
            <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800/30 bg-zinc-900/60">
                <div className="flex items-center gap-2">
                    <div className="h-8 w-8 rounded-lg bg-amber-500/10 flex items-center justify-center">
                        <Calendar className="h-4 w-4 text-amber-400" />
                    </div>
                    <div>
                        <h3 className="text-sm font-bold text-zinc-100">À venir</h3>
                        <p className="text-xs text-zinc-500">{upcomingEvents.length} événement{upcomingEvents.length > 1 ? "s" : ""}</p>
                    </div>
                </div>
                {onViewAll && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={onViewAll}
                        className="h-8 px-2 text-xs text-zinc-400 hover:text-amber-400"
                    >
                        Voir tout
                        <ChevronRight className="h-3 w-3 ml-1" />
                    </Button>
                )}
            </div>

            {/* Events List */}
            <div className="divide-y divide-zinc-800/30">
                {upcomingEvents.map((event) => (
                    <EventRow
                        key={event.id}
                        event={event}
                        now={now}
                        onClick={() => onEventClick(event.id)}
                        compact={compact}
                    />
                ))}
            </div>
        </div>
    );
}

// ============================================
// EVENT ROW
// ============================================

function EventRow({
    event,
    now,
    onClick,
    compact
}: {
    event: UpcomingEvent;
    now: Date;
    onClick: () => void;
    compact?: boolean;
}) {
    const config = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
    const Icon = config.icon;
    const startDate = new Date(event.startDate);
    const hoursUntil = differenceInHours(startDate, now);
    const minutesUntil = differenceInMinutes(startDate, now) % 60;

    // Determine urgency
    const isUrgent = hoursUntil < 2;
    const isTodays = isToday(startDate);

    // Format countdown
    const countdown = useMemo(() => {
        if (hoursUntil < 1) {
            return `${minutesUntil}min`;
        } else if (hoursUntil < 24) {
            return `${hoursUntil}h${minutesUntil > 0 ? minutesUntil : ""}`;
        } else {
            return formatDistanceToNow(startDate, { addSuffix: false, locale: fr });
        }
    }, [hoursUntil, minutesUntil, startDate]);

    return (
        <button
            onClick={onClick}
            className={cn(
                "w-full flex items-center gap-3 p-3 text-left transition-all hover:bg-zinc-800/30 group",
                compact && "p-2.5"
            )}
        >
            {/* Icon */}
            <div className={cn(
                "shrink-0 h-10 w-10 rounded-lg flex items-center justify-center border",
                config.bg,
                compact && "h-8 w-8"
            )}>
                <Icon className={cn("h-5 w-5", config.color, compact && "h-4 w-4")} />
            </div>

            {/* Content */}
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                    <span className={cn(
                        "font-semibold text-zinc-100 truncate text-sm",
                        compact && "text-xs"
                    )}>
                        {event.title}
                    </span>
                    {isUrgent && (
                        <Flame className="h-3.5 w-3.5 text-orange-500 animate-pulse shrink-0" />
                    )}
                </div>
                <div className={cn(
                    "flex items-center gap-2 text-xs text-zinc-500 mt-0.5",
                    compact && "text-[10px]"
                )}>
                    <Clock className="h-3 w-3" />
                    {isTodays ? (
                        <span>Aujourd'hui {format(startDate, "HH:mm")}</span>
                    ) : (
                        <span>{format(startDate, "EEE d MMM, HH:mm", { locale: fr })}</span>
                    )}
                    {event._count && (
                        <>
                            <span className="text-zinc-600">•</span>
                            <Users className="h-3 w-3" />
                            <span>
                                {event._count.participants}
                                {event.maxParticipants && `/${event.maxParticipants}`}
                            </span>
                        </>
                    )}
                </div>
            </div>

            {/* Countdown Badge */}
            <Badge
                variant="outline"
                className={cn(
                    "shrink-0 font-bold text-xs",
                    isUrgent
                        ? "bg-orange-500/10 border-orange-500/30 text-orange-400"
                        : isTodays
                            ? "bg-amber-500/10 border-amber-500/30 text-amber-400"
                            : "bg-zinc-800 border-zinc-700 text-zinc-400"
                )}
            >
                {countdown}
            </Badge>

            {/* Arrow */}
            <ChevronRight className="h-4 w-4 text-zinc-600 group-hover:text-zinc-400 transition-colors shrink-0" />
        </button>
    );
}

// ============================================
// COMPACT HEADER VERSION (for global header)
// ============================================

export function UpcomingEventsBadge({
    events,
    onClick
}: {
    events: UpcomingEvent[];
    onClick: () => void;
}) {
    const now = new Date();

    // Find next event
    const nextEvent = useMemo(() => {
        return events
            .filter(e => isFuture(new Date(e.startDate)) || isToday(new Date(e.startDate)))
            .sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime())[0];
    }, [events]);

    if (!nextEvent) return null;

    const startDate = new Date(nextEvent.startDate);
    const hoursUntil = differenceInHours(startDate, now);
    const isUrgent = hoursUntil < 2;
    const config = TYPE_CONFIG[nextEvent.type] || TYPE_CONFIG.EVENT_GUILD;
    const Icon = config.icon;

    return (
        <button
            onClick={onClick}
            className={cn(
                "flex items-center gap-2 px-3 py-1.5 rounded-full border transition-all",
                isUrgent
                    ? "bg-orange-500/10 border-orange-500/30 text-orange-400 animate-pulse"
                    : "bg-zinc-900/60 border-zinc-700/50 text-zinc-400 hover:border-zinc-600"
            )}
        >
            <Icon className="h-4 w-4" />
            <span className="text-xs font-medium truncate max-w-[120px]">
                {nextEvent.title}
            </span>
            <Badge
                variant="outline"
                className={cn(
                    "h-5 text-[10px] font-bold",
                    isUrgent ? "border-orange-500/50 text-orange-300" : "border-zinc-600 text-zinc-400"
                )}
            >
                {hoursUntil < 1 ? `${Math.max(1, differenceInMinutes(startDate, now))}min` : `${hoursUntil}h`}
            </Badge>
        </button>
    );
}

"use client";

import { useState, useEffect } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { ChevronRight, X } from "lucide-react";
import { checkChangelogVisibility, markChangelogAsSeen } from "@/server/actions/changelog-actions";
import { Badge } from "@/components/ui/badge";
import { DocContent } from "@/components/doc/doc-content";
import { cn } from "@/lib/utils";
import { ChangelogCategory } from "@prisma/client";

const categoryColors: Record<ChangelogCategory, string> = {
    FEATURE: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
    BUGFIX: "bg-amber-500/10 text-amber-500 border-amber-500/20",
    SECURITY: "bg-red-500/10 text-red-400 border-red-500/20",
    PERFORMANCE: "bg-blue-500/10 text-blue-400 border-blue-500/20",
    DOCUMENTATION: "bg-purple-500/10 text-purple-400 border-purple-500/20",
};

export function ChangelogModal() {
    const [isOpen, setIsOpen] = useState(false);
    const [changelog, setChangelog] = useState<any>(null);

    useEffect(() => {
        const checkVisibility = async () => {
            try {
                const res = await checkChangelogVisibility();
                if (res.show && res.changelog) {
                    setChangelog(res.changelog);
                    setIsOpen(true);
                }
            } catch (err) {
                console.error("Failed to check changelog visibility", err);
            }
        };
        checkVisibility();
    }, []);

    const handleClose = async () => {
        if (changelog?.id) {
            try {
                await markChangelogAsSeen(changelog.id);
            } catch (err) {
                console.error("Failed to mark changelog as seen", err);
            }
        }
        setIsOpen(false);
    };

    if (!changelog) return null;

    const catColor = categoryColors[changelog.category as ChangelogCategory] ?? "bg-zinc-500/10 text-zinc-400 border-zinc-500/20";

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && handleClose()}>
            <DialogContent className="max-w-xl bg-[#09090b] border-white/10 p-0 shadow-2xl focus:outline-none focus:ring-0 rounded-3xl max-h-[85vh] flex flex-col [&>button:first-of-type]:hidden">
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 via-transparent to-purple-500/5 pointer-events-none rounded-3xl" />

                {/* Close Button */}
                <button
                    onClick={handleClose}
                    className="absolute top-4 right-4 z-50 p-1.5 bg-black/40 hover:bg-black/60 border border-white/5 rounded-full text-zinc-400 hover:text-white transition-all backdrop-blur-md"
                >
                    <X className="w-4 h-4" />
                </button>

                {/* Header */}
                <div className="relative h-32 sm:h-40 w-full overflow-hidden flex items-center justify-center shrink-0">
                    <div className="absolute inset-0 z-0">
                        <div className="w-full h-full bg-gradient-to-br from-indigo-600/20 via-purple-600/15 to-pink-600/10 animate-pulse-slow" />
                        <div className="absolute inset-0 bg-gradient-to-t from-[#09090b] via-[#09090b]/40 to-transparent" />
                    </div>

                    <div className="relative z-10 flex flex-col items-center text-center px-6 mt-2 gap-2">
                        <div className="flex items-center gap-2">
                            <Badge variant="outline" className="bg-indigo-500/10 text-indigo-400 border-indigo-500/20 font-black tracking-widest uppercase py-0.5 px-2.5 text-[10px]">
                                Mise à jour {changelog.version}
                            </Badge>
                            {changelog.category && (
                                <Badge variant="outline" className={cn("font-black tracking-widest uppercase py-0.5 px-2.5 text-[10px]", catColor)}>
                                    {changelog.category}
                                </Badge>
                            )}
                        </div>
                        <DialogHeader>
                            <DialogTitle className="text-2xl sm:text-3xl font-black text-white tracking-tighter uppercase drop-shadow-2xl">
                                {changelog.title}
                            </DialogTitle>
                            <DialogDescription className="sr-only">
                                Nouveautés SigilOS {changelog.version}
                            </DialogDescription>
                        </DialogHeader>
                    </div>
                </div>

                {/* Content — uses DocContent to render TipTap HTML correctly */}
                <div className="px-6 pb-6 sm:px-8 sm:pb-8 flex flex-col flex-1 min-h-0 overflow-hidden relative z-10 -mt-2">
                    <div className="flex-1 overflow-y-auto pr-2 min-h-0 w-full overflow-x-hidden">
                        <DocContent
                            content={changelog.content}
                            className="
                                prose-p:text-sm prose-p:leading-relaxed
                                prose-headings:text-white prose-headings:font-black prose-headings:uppercase prose-headings:tracking-tight prose-headings:mb-3 prose-headings:mt-6
                                prose-h3:text-lg
                                prose-strong:text-indigo-400
                                prose-ul:list-disc prose-li:text-zinc-400 prose-li:text-sm prose-li:my-1
                                prose-hr:border-white/5 prose-hr:my-4
                                [&_.callout]:my-4 [&_.callout]:p-4
                                [&_img]:max-w-full [&_img]:h-auto [&_img]:object-contain
                                [&_figure]:my-4 [&_figure]:flex [&_figure]:flex-col [&_figure]:items-start
                            "
                        />
                    </div>

                    <div className="pt-4 flex items-center justify-end gap-3 mt-auto shrink-0 border-t border-white/5">
                        <div className="mr-auto hidden sm:flex flex-col">
                            <span className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em]">
                                SigilOS Platform
                            </span>
                            <span className="text-[9px] font-medium text-zinc-700 uppercase">
                                Build {changelog.version}
                            </span>
                        </div>
                        <Button
                            onClick={handleClose}
                            className="bg-white text-black hover:bg-zinc-200 font-black uppercase tracking-widest text-[10px] h-10 rounded-xl px-6 shadow-[0_0_20px_rgba(255,255,255,0.1)] group transition-all"
                        >
                            D&apos;accord
                            <ChevronRight className="w-3.5 h-3.5 ml-1.5 transition-transform group-hover:translate-x-0.5" />
                        </Button>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { motion, AnimatePresence } from "framer-motion";
import { Check, Shield, ScrollText, BookOpen, Sparkles, Zap, ArrowRight, CheckCircle2, Infinity as InfinityIcon, Users, AlertCircle, Rocket, X } from "lucide-react";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { BorderBeam } from "@/components/ui/border-beam";
import { useEffect, useState } from "react";

interface OnboardingStep {
    id: string;
    title: string;
    description: string;
    href: string;
    completed: boolean;
    icon: string;
}

export function OnboardingBanner({
    guildId,
    steps,
    title = "Administration",
    subtitle = "Configuration",
    checklistLabel = "Checklist de configuration",
    guideHref,
    variant = "admin",
    dismissible = false,
    storageKey
}: {
    guildId: string,
    steps: OnboardingStep[],
    title?: string,
    subtitle?: string,
    checklistLabel?: string,
    guideHref?: string,
    variant?: "admin" | "user",
    dismissible?: boolean,
    storageKey?: string
}) {
    const [isDismissed, setIsDismissed] = useState(false);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        if (storageKey) {
            const dismissed = localStorage.getItem(`sigilos-dismiss-${storageKey}`);
            if (dismissed === "true") setIsDismissed(true);
        }
    }, [storageKey]);

    const handleDismiss = () => {
        setIsDismissed(true);
        if (storageKey) {
            localStorage.setItem(`sigilos-dismiss-${storageKey}`, "true");
        }
    };

    const completedSteps = steps.filter(s => s.completed).length;
    const progress = (completedSteps / steps.length) * 100;
    const isFinished = completedSteps === steps.length;

    // Automatic dismissal if everything is done — don't show the banner anymore
    useEffect(() => {
        if (mounted && isFinished) {
            handleDismiss();
        }
    }, [isFinished, mounted]);

    const iconMap = {
        shield: Shield,
        "scroll-text": ScrollText,
        "book-open": BookOpen,
        infinity: InfinityIcon,
        users: Users,
        sparkles: Sparkles,
        zap: Zap,
        rocket: Rocket
    };

    if (isDismissed || !mounted) return null;

    return (
        <div className="relative group/onboarding w-full">
            {/* Animated Glow when incomplete */}
            {!isFinished && (
                <div className={cn(
                    "absolute -inset-[2px] rounded-2xl blur-md opacity-30 animate-pulse-slow",
                    variant === "user" ? "bg-gradient-to-r from-blue-500/40 via-indigo-500/40 to-blue-500/40" : "bg-gradient-to-r from-emerald-500/40 via-teal-500/40 to-emerald-500/40"
                )} />
            )}

            <div className={cn(
                "relative glass-premium p-6 md:p-8 rounded-2xl border border-white/10 overflow-hidden transition-all duration-500 group-hover/onboarding:border-white/20",
                variant === "user" ? "ring-1 ring-blue-500/20 shadow-[0_0_30px_rgba(59,130,246,0.1)]" : "ring-1 ring-emerald-500/20 shadow-[0_0_30px_rgba(16,185,129,0.1)]",
                !isFinished ? "opacity-100" : "opacity-90"
            )}>
                {dismissible && (
                    <button
                        onClick={handleDismiss}
                        className="absolute top-4 right-4 p-2 rounded-full hover:bg-white/10 text-zinc-500 hover:text-white transition-all z-20 group/close"
                    >
                        <X className="w-4 h-4 group-hover/close:rotate-90 transition-transform" />
                    </button>
                )}
                
                {!isFinished && (
                    <BorderBeam
                        size={200}
                        duration={6}
                        colorFrom={variant === "user" ? "#3b82f6" : "#10b981"}
                        colorTo={variant === "user" ? "#60a5fa" : "#34d399"}
                    />
                )}

                <div className="relative z-10 flex flex-col lg:flex-row lg:items-center justify-between gap-8">
                    <div className="space-y-6 flex-1 max-w-2xl">
                        <div className="flex items-start gap-4">
                            <div className={cn(
                                "p-3 rounded-2xl border transition-colors",
                                !isFinished
                                    ? (variant === "user" ? "bg-blue-500/20 border-blue-500/30 text-blue-400 group-hover/onboarding:scale-110 duration-500" : "bg-emerald-500/20 border-emerald-500/30 text-emerald-400 group-hover/onboarding:scale-110 duration-500")
                                    : "bg-zinc-500/10 border-white/10 text-zinc-400"
                            )}>
                                {isFinished ? (
                                    <CheckCircle2 className="w-6 h-6" />
                                ) : (
                                    variant === "user" ? <Sparkles className="w-6 h-6 animate-pulse" /> : <Rocket className="w-6 h-6 animate-bounce-subtle" />
                                )}
                            </div>
                            <div className="space-y-1">
                                <div className="flex items-center gap-2">
                                    <span className={cn(
                                        "text-[10px] font-black uppercase tracking-[0.4em] leading-none",
                                        variant === "user" ? "text-blue-400/80" : "text-emerald-400/80"
                                    )}>
                                        {isFinished ? (variant === "user" ? "Prêt pour l'aventure" : "Succès") : (variant === "user" ? "Préparation" : "Configuration Nécessaire")}
                                    </span>
                                    {!isFinished && (
                                        <div className={cn(
                                            "flex items-center gap-1 px-1.5 py-0.5 rounded-full border",
                                            variant === "user" ? "bg-blue-500/10 border-blue-500/20" : "bg-emerald-500/10 border-emerald-500/20"
                                        )}>
                                            <span className={cn(
                                                "w-1 h-1 rounded-full animate-ping",
                                                variant === "user" ? "bg-blue-400" : "bg-emerald-400"
                                            )} />
                                            <span className={cn(
                                                "text-[8px] font-black uppercase tracking-tighter",
                                                variant === "user" ? "text-blue-400" : "text-emerald-400"
                                            )}>Priorité</span>
                                        </div>
                                    )}
                                </div>
                                <h2 className="text-2xl md:text-3xl font-black tracking-tighter text-white">
                                    {isFinished
                                        ? (variant === "user" ? "Votre profil est prêt !" : "Votre Guilde est prête !")
                                        : title}
                                </h2>
                                <p className="text-zinc-400 text-sm font-medium leading-relaxed max-w-md">
                                    {isFinished
                                        ? (variant === "user"
                                            ? "Vous avez configuré les piliers essentiels de votre identité. Profitez pleinement de SigilOS !"
                                            : "Tous les systèmes sont opérationnels. Vos membres peuvent désormais profiter pleinement du dashboard.")
                                        : (variant === "user"
                                            ? "Suivez ces quelques étapes pour préparer votre profil et faciliter votre intégration dans l'écosystème de la guilde."
                                            : "Il reste quelques étapes pour que votre guilde bénéficie de l'expérience complète de SigilOS.")}
                                </p>
                            </div>
                        </div>

                        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-6 pt-2">
                            {guideHref && !isFinished && (
                                <Button asChild variant={variant === "user" ? "sigil" : "sigil-emerald"} className="h-12 px-8">
                                    <Link href={guideHref}>
                                        {variant === "user" ? "MON PARCOURS" : "AVANCEMENT"}
                                        <ArrowRight className="ml-2 w-5 h-5 group-hover/btn:translate-x-2 transition-transform" />
                                    </Link>
                                </Button>
                            )}

                            <div className="flex-1 min-w-[200px] space-y-2">
                                <div className="flex justify-between text-[10px] font-black uppercase tracking-widest">
                                    <span className="text-zinc-500">{checklistLabel}</span>
                                    <span className={variant === "user" ? "text-blue-400" : "text-emerald-400"}>{completedSteps} / {steps.length}</span>
                                </div>
                                <div className="h-2 w-full bg-zinc-900 rounded-full overflow-hidden border border-white/5">
                                    <motion.div
                                        initial={{ width: 0 }}
                                        animate={{ width: `${progress}%` }}
                                        transition={{ duration: 1, ease: "easeOut" }}
                                        className={cn(
                                            "h-full transition-all duration-500",
                                            variant === "user" ? "bg-gradient-to-r from-blue-600 to-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.5)]" : "bg-gradient-to-r from-emerald-600 to-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)]"
                                        )}
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-3 sm:flex items-center gap-4">
                        {steps.map((step, idx) => {
                            const Icon = iconMap[step.icon as keyof typeof iconMap] || Sparkles;
                            return (
                                <Link key={step.id} href={step.href} className="contents">
                                    <motion.div
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: 0.1 * idx }}
                                        className={cn(
                                            "relative p-4 rounded-2xl border transition-all hover:scale-110 active:scale-95 group/step flex flex-col items-center gap-3 min-w-[90px]",
                                            step.completed
                                                ? (variant === "user" ? "bg-blue-500/10 border-blue-500/30 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.1)]" : "bg-emerald-500/10 border-emerald-500/30 text-emerald-400")
                                                : "bg-white/5 border-white/10 text-zinc-500 hover:border-white/30 hover:bg-white/10"
                                        )}
                                    >
                                        <Icon className={cn("w-6 h-6", !step.completed && "grayscale opacity-50")} />
                                        <span className="text-[8px] font-black uppercase tracking-widest text-center leading-tight">{step.title}</span>

                                        {step.completed && (
                                            <div className={cn(
                                                "absolute -top-1.5 -right-1.5 rounded-full p-1 border-2 border-zinc-950 shadow-lg",
                                                variant === "user" ? "bg-blue-500" : "bg-emerald-500"
                                            )}>
                                                <Check className="w-2.5 h-2.5 text-white" />
                                            </div>
                                        )}

                                        <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 bg-zinc-900 border border-white/10 p-2 rounded-lg opacity-0 group-hover/step:opacity-100 pointer-events-none transition-all z-50 whitespace-nowrap scale-90 group-hover/step:scale-100 origin-top">
                                            <p className="text-[9px] font-black uppercase tracking-widest text-white">{step.description}</p>
                                        </div>
                                    </motion.div>
                                </Link>
                            );
                        })}
                    </div>
                </div>

                <div className="absolute -bottom-10 -right-10 p-8 opacity-[0.03] pointer-events-none group-hover/onboarding:opacity-[0.07] transition-opacity duration-1000 group-hover/onboarding:rotate-0 rotate-12">
                    {variant === "user" ? <Sparkles className="w-64 h-64 text-white" /> : <Shield className="w-64 h-64 text-white" />}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
