"use client";

import { useTransition } from "react";
import { useRouter, useSearchParams, usePathname } from "next/navigation";
import { User, Users, ChevronDown, Crown } from "lucide-react";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";

interface CharacterQuestSelectorProps {
    mainCharacter: {
        pseudo: string;
        classe?: string | null;
    };
    mules: {
        pseudo: string;
        classe?: string | null;
        level?: number | null;
    }[];
}

export function CharacterQuestSelector({ mainCharacter, mules }: CharacterQuestSelectorProps) {
    const router = useRouter();
    const pathname = usePathname();
    const searchParams = useSearchParams();
    const [isPending, startTransition] = useTransition();

    const selectedCharacter = searchParams.get("character") || "PRINCIPAL";

    const handleSelect = (char: string) => {
        const params = new URLSearchParams(searchParams.toString());
        if (char === "PRINCIPAL") {
            params.delete("character");
        } else {
            params.set("character", char);
        }
        startTransition(() => {
            router.push(`${pathname}?${params.toString()}`);
        });
    };

    const currentLabel = selectedCharacter === "PRINCIPAL" 
        ? `${mainCharacter.pseudo}${mainCharacter.classe ? ` (${mainCharacter.classe})` : ""}`
        : selectedCharacter;

    return (
        <div className="flex flex-col gap-2">
            <span className="text-[10px] font-black text-white/20 uppercase tracking-[0.2em] ml-1">
                Personnage de Quête
            </span>
            <DropdownMenu>
                <DropdownMenuTrigger asChild>
                    <Button 
                        variant="outline" 
                        role="combobox"
                        aria-expanded={false}
                        className="bg-zinc-900/40 backdrop-blur-md border-white/10 hover:bg-white/10 text-white justify-between min-w-[220px] transition-all rounded-xl h-11"
                        disabled={isPending}
                    >
                        <div className="flex items-center gap-2 truncate">
                            {selectedCharacter === "PRINCIPAL" ? (
                                <Crown className="w-4 h-4 text-amber-500" />
                            ) : (
                                <Users className="w-4 h-4 text-blue-400" />
                            )}
                            <span className="truncate font-semibold tracking-wide">{currentLabel}</span>
                        </div>
                        <ChevronDown className={`w-3.5 h-3.5 transition-transform opacity-30 ${isPending ? 'animate-pulse' : ''}`} />
                    </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start" className="bg-zinc-900/95 backdrop-blur-xl border-white/10 text-white min-w-[220px] rounded-xl p-1.5 shadow-2xl z-50">
                    <DropdownMenuItem 
                        onClick={() => handleSelect("PRINCIPAL")}
                        className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer transition-colors ${selectedCharacter === "PRINCIPAL" ? "bg-white/10" : "hover:bg-white/5"}`}
                    >
                        <div className="w-8 h-8 rounded-full bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                            <Crown className="w-4 h-4 text-amber-500" />
                        </div>
                        <div className="flex flex-col">
                            <span className="text-sm font-bold">{mainCharacter.pseudo}</span>
                            <span className="text-[10px] text-white/40 uppercase tracking-widest">{mainCharacter.classe || "Classe non définie"}</span>
                        </div>
                    </DropdownMenuItem>
                    
                    {mules.length > 0 && <div className="h-px bg-white/5 m-1.5" />}
                    
                    {mules.map((mule) => (
                        <DropdownMenuItem 
                            key={mule.pseudo}
                            onClick={() => handleSelect(mule.pseudo)}
                            className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer transition-colors ${selectedCharacter === mule.pseudo ? "bg-white/10" : "hover:bg-white/5"}`}
                        >
                            <div className="w-8 h-8 rounded-full bg-blue-500/10 flex items-center justify-center border border-blue-500/20">
                                <Users className="w-4 h-4 text-blue-400" />
                            </div>
                            <div className="flex flex-col">
                                <span className="text-sm font-bold">{mule.pseudo}</span>
                                <span className="text-[10px] text-white/40 uppercase tracking-widest">
                                    Mule {mule.classe ? `• ${mule.classe}` : ""}
                                </span>
                            </div>
                        </DropdownMenuItem>
                    ))}
                </DropdownMenuContent>
            </DropdownMenu>
        </div>
    );
}

"use client";

import React, { useState, useTransition } from "react";
import { motion } from "framer-motion";
import { BookOpen, CalendarDays, ExternalLink, Plus, Minus, CheckCircle2, Info } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";

// ─────────────────────────────────────────────────────────────────────────────
// Dolmanax Tracker — 365 Almanax pages declarative component
// The Dolmanax is obtained after collecting 365 Almanax pages via daily quests.
// No quest chain to track — just a simple progress declaration.
// ─────────────────────────────────────────────────────────────────────────────

const TOTAL_PAGES = 365;

interface DofusDolmanaxTrackerProps {
    guildId: string;
    /** Current saved page count for this member — from DB (can be null/0 if not set). */
    initialPages?: number;
    /** Callback to persist the value server-side */
    onSave?: (pages: number) => Promise<void>;
}

export function DofusDolmanaxTracker({ guildId, initialPages = 0, onSave }: DofusDolmanaxTrackerProps) {
    const [pages, setPages] = useState<number>(Math.min(Math.max(0, initialPages), TOTAL_PAGES));
    const [isSaving, startSave] = useTransition();
    const [saved, setSaved] = useState(false);

    const pct = Math.round((pages / TOTAL_PAGES) * 100);
    const isDone = pages >= TOTAL_PAGES;

    function adjust(delta: number) {
        setPages(p => Math.min(TOTAL_PAGES, Math.max(0, p + delta)));
        setSaved(false);
    }

    function handleSave() {
        if (!onSave) return;
        startSave(async () => {
            await onSave(pages);
            setSaved(true);
        });
    }

    return (
        <div className="space-y-6">
            {/* Header info */}
            <div className="p-5 bg-amber-500/5 border border-amber-500/15 rounded-3xl flex items-start gap-4">
                <div className="w-10 h-10 rounded-2xl bg-amber-500/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                    <Info className="w-5 h-5 text-amber-400" />
                </div>
                <div className="space-y-1">
                    <div className="text-[10px] font-black text-amber-400 uppercase tracking-[0.4em]">Comment obtenir le Dolmanax</div>
                    <p className="text-[13px] text-zinc-400 leading-relaxed">
                        Le <span className="text-white font-bold italic">Dolmanax</span> s&apos;obtient après avoir récupéré{" "}
                        <span className="text-amber-400 font-black">365 pages d&apos;Almanax</span> via les quêtes journalières dans n&apos;importe quel temple.
                        Chaque jour, parle au PNJ Almanzor dans un temple de la classe pour recevoir ta page.
                    </p>
                    <Link
                        href={`/dashboard/${guildId}/almanax`}
                        className="inline-flex items-center gap-1.5 text-[10px] font-black text-amber-500 hover:text-amber-300 mt-1 transition-colors"
                    >
                        <CalendarDays className="w-3.5 h-3.5" />
                        Voir le module Almanax →
                    </Link>
                </div>
            </div>

            {/* Progress bar */}
            <div className="space-y-3">
                <div className="flex items-center justify-between">
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Progression</span>
                    <span className="text-[13px] font-black text-white tabular-nums">
                        <span style={{ color: isDone ? "#10b981" : "#f59e0b" }}>{pages}</span>
                        <span className="text-zinc-600"> / {TOTAL_PAGES} pages</span>
                    </span>
                </div>
                <div className="w-full h-3 bg-white/5 rounded-full overflow-hidden">
                    <motion.div
                        className="h-full rounded-full relative"
                        style={{
                            background: isDone
                                ? "linear-gradient(90deg, #10b981, #34d399)"
                                : "linear-gradient(90deg, #f59e0b, #fbbf24)",
                            boxShadow: isDone ? "0 0 20px rgba(16,185,129,0.4)" : "0 0 20px rgba(245,158,11,0.3)",
                        }}
                        initial={{ width: 0 }}
                        animate={{ width: `${pct}%` }}
                        transition={{ duration: 0.5, ease: "easeOut" }}
                    />
                </div>
                <div className="flex items-center justify-between text-[9px] font-black uppercase tracking-widest">
                    <span className="text-zinc-700">0</span>
                    <span className={isDone ? "text-emerald-400 animate-pulse" : "text-zinc-600"}>
                        {isDone ? "✓ DOLMANAX OBTENU" : `${pct}% — ${TOTAL_PAGES - pages} jours restants`}
                    </span>
                    <span className="text-zinc-700">365</span>
                </div>
            </div>

            {/* Controls */}
            <div className="flex items-center gap-3">
                <div className="flex items-center bg-zinc-950/80 border border-white/5 rounded-2xl overflow-hidden">
                    <button
                        onClick={() => adjust(-10)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-r border-white/5 text-[10px] font-black"
                    >
                        -10
                    </button>
                    <button
                        onClick={() => adjust(-1)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-r border-white/5"
                    >
                        <Minus className="w-3.5 h-3.5" />
                    </button>
                    <div className="w-20 text-center">
                        <input
                            type="number"
                            min={0}
                            max={TOTAL_PAGES}
                            value={pages}
                            onChange={(e) => {
                                const v = parseInt(e.target.value, 10);
                                if (!isNaN(v)) { setPages(Math.min(TOTAL_PAGES, Math.max(0, v))); setSaved(false); }
                            }}
                            className="w-full bg-transparent text-center text-[16px] font-black text-white outline-none tabular-nums"
                        />
                    </div>
                    <button
                        onClick={() => adjust(+1)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-l border-white/5"
                    >
                        <Plus className="w-3.5 h-3.5" />
                    </button>
                    <button
                        onClick={() => adjust(+10)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-l border-white/5 text-[10px] font-black"
                    >
                        +10
                    </button>
                </div>

                {onSave && (
                    <Button
                        onClick={handleSave}
                        disabled={isSaving || saved}
                        className={`h-10 px-4 rounded-2xl font-black text-[11px] uppercase italic tracking-widest transition-all ${
                            saved
                                ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                                : "bg-white text-black hover:bg-zinc-200 shadow-[0_0_20px_rgba(255,255,255,0.1)]"
                        }`}
                    >
                        {saved ? <><CheckCircle2 className="w-4 h-4 mr-1.5 inline" /> Sauvegardé</> : isSaving ? "..." : "Sauvegarder"}
                    </Button>
                )}
            </div>

            {/* Milestones */}
            <div className="grid grid-cols-3 gap-3">
                {[
                    { label: "Quart", target: 91, emoji: "📖" },
                    { label: "Moitié", target: 183, emoji: "📚" },
                    { label: "Final", target: 365, emoji: "🏆" },
                ].map((milestone) => {
                    const reached = pages >= milestone.target;
                    return (
                        <div key={milestone.target}
                            className={`p-3 rounded-2xl border text-center transition-all ${
                                reached ? "bg-amber-500/10 border-amber-500/25" : "bg-white/[0.02] border-white/5"
                            }`}>
                            <div className="text-xl mb-1">{milestone.emoji}</div>
                            <div className="text-[9px] font-black uppercase tracking-widest text-zinc-500">{milestone.label}</div>
                            <div className={`text-[12px] font-black ${reached ? "text-amber-400" : "text-zinc-700"}`}>
                                {milestone.target} pages
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import Image from "next/image";
import Link from "next/link";
import { Crown, Gem, Lock, Sparkles } from "lucide-react";
import { DofusProgressRing } from "./DofusProgressRing";
import { DofusIcon } from "./DofusIcon";
import { toggleDofusObtained } from "@/server/actions/dofus-quest-actions";
import type { DofusItemWithProgress } from "@/server/actions/dofus-quest-actions";

interface DofusGemCardProps {
    dofus: DofusItemWithProgress;
    guildId: string;
    selectedCharacter?: string;
}

export function DofusGemCard({ dofus, guildId, selectedCharacter = "PRINCIPAL" }: DofusGemCardProps) {
    const [isObtained, setIsObtained] = useState(dofus.isObtained);
    const [isPending, startTransition] = useTransition();

    const color = dofus.color || "#6366f1";
    const hasChain = dofus.totalQuests > 0;
    const isLocked = !hasChain; // No quest data yet

    function handleToggleObtained(e: React.MouseEvent) {
        e.preventDefault();
        e.stopPropagation();
        if (isPending) return;

        const newVal = !isObtained;
        setIsObtained(newVal);
        startTransition(async () => {
            await toggleDofusObtained(guildId, dofus.id, newVal, selectedCharacter);
        });
    }

    return (
        <Link
            href={`/dashboard/${guildId}/quetes-dofus/${dofus.slug}${selectedCharacter !== "PRINCIPAL" ? `?character=${selectedCharacter}` : ""}`}
            className="group relative flex flex-col rounded-2xl overflow-hidden transition-all duration-300 hover:-translate-y-1"
            style={{
                background: `linear-gradient(145deg, rgba(255,255,255,0.04) 0%, rgba(255,255,255,0.02) 100%)`,
                border: `1px solid ${isObtained ? color + "66" : "rgba(255,255,255,0.08)"}`,
                boxShadow: isObtained
                    ? `0 0 20px ${color}22, 0 4px 24px rgba(0,0,0,0.4)`
                    : `0 4px 24px rgba(0,0,0,0.3)`,
            }}
        >
            {/* Glow overlay on hover */}
            <div
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none rounded-2xl"
                style={{
                    background: `radial-gradient(ellipse at 50% 0%, ${color}18 0%, transparent 70%)`,
                }}
            />

            {/* Tags Section */}
            <div className="absolute top-2 left-2 z-10 flex flex-wrap gap-1 max-w-[85%]">
                {/* Main Dynamic Tag (The one you edit in God Mode) */}
                {dofus.rarity && (
                    <span
                        className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider shadow-sm border"
                        style={{
                            background: `${color}15`,
                            color,
                            borderColor: `${color}30`,
                        }}
                    >
                        {dofus.rarity}
                    </span>
                )}

                {/* Functional Icons (Discrete indicators) */}
                {dofus.isPrimordial && (
                    <div className="w-5 h-5 rounded-md bg-amber-500/10 border border-amber-500/30 flex items-center justify-center text-amber-500 shadow-sm" title="Dofus Primordial">
                        <Crown className="w-3 h-3" />
                    </div>
                )}
                {dofus.isMeta && (
                    <div className="w-5 h-5 rounded-md bg-indigo-500/10 border border-indigo-500/30 flex items-center justify-center text-indigo-400 shadow-sm" title="Dofus Méta">
                        <Sparkles className="w-3 h-3" />
                    </div>
                )}
                {dofus.isSylvestreReq && (
                    <div className="w-5 h-5 rounded-md bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400 shadow-sm" title="Requis pour le Sylvestre">
                        <Gem className="w-3 h-3" />
                    </div>
                )}
            </div>

            {/* Obtained toggle button */}
            <button
                onClick={handleToggleObtained}
                disabled={isPending}
                className="absolute top-3 right-3 z-10 w-7 h-7 rounded-full flex items-center justify-center transition-all duration-200 hover:scale-110"
                style={{
                    background: isObtained ? color : "rgba(255,255,255,0.08)",
                    border: `1px solid ${isObtained ? color : "rgba(255,255,255,0.15)"}`,
                    boxShadow: isObtained ? `0 0 10px ${color}66` : "none",
                }}
                title={isObtained ? "Marquer comme non obtenu" : "Marquer comme obtenu"}
                aria-label={isObtained ? "Dofus obtenu — cliquer pour annuler" : "Marquer comme obtenu"}
            >
                {isObtained ? (
                    <span className="text-sm text-black font-bold">✓</span>
                ) : (
                    <span className="text-sm text-white/40">○</span>
                )}
            </button>

            {/* Image + Ring */}
            <div className="flex flex-col items-center pt-10 pb-4 px-4">
                <div className="relative">
                    <DofusProgressRing
                        percent={dofus.progressPercent}
                        size={90}
                        strokeWidth={5}
                        color={color}
                        isObtained={isObtained}
                    />
                    <div className="absolute inset-0 flex items-center justify-center">
                        <div className="relative flex items-center justify-center transition-all duration-500 group-hover:scale-110">
                            {dofus.imageUrl ? (
                                // eslint-disable-next-line @next/next/no-img-element
                                <img
                                    src={dofus.slug === "dofoozbz" ? "/module-dofus/Dofus_dofoozbz.png" : dofus.imageUrl.replace(/^\/public/, "")}
                                    alt={dofus.nameShort}
                                    width={56}
                                    height={56}
                                    className="object-contain"
                                    style={{
                                        filter: isObtained
                                            ? `drop-shadow(0 0 10px ${color}aa)`
                                            : `drop-shadow(0 0 4px ${color}44)`,
                                    }}
                                />
                            ) : dofus.nameShort ? (
                                <DofusIcon
                                    name={dofus.nameShort}
                                    size={56}
                                    color={color}
                                    isObtained={isObtained}
                                />
                            ) : (
                                <Gem className="w-8 h-8 opacity-40" style={{ color }} />
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Info */}
            <div className="flex flex-col px-4 pb-4 gap-1">
                <h3
                    className="text-sm font-bold text-center leading-tight"
                    style={{ color: isObtained ? color : "white" }}
                >
                    {dofus.nameShort}
                </h3>

                {hasChain ? (
                    <div className="flex items-center justify-center gap-1.5 mt-1">
                        <div
                            className="flex-1 h-1 rounded-full overflow-hidden"
                            style={{ background: "rgba(255,255,255,0.08)" }}
                        >
                            <div
                                className="h-full rounded-full transition-all duration-700"
                                style={{
                                    width: `${dofus.progressPercent}%`,
                                    background: isObtained
                                        ? `linear-gradient(90deg, ${color}, #fbbf24)`
                                        : color,
                                }}
                            />
                        </div>
                        <span className="text-[10px] tabular-nums font-black" style={{ color: dofus.progressPercent > 0 ? color : "rgba(255,255,255,0.2)" }}>
                            {dofus.progressPercent}%
                        </span>
                        <span className="text-[10px] tabular-nums text-white/20 whitespace-nowrap">
                            ({dofus.completedQuests}/{dofus.totalQuests})
                        </span>
                    </div>
                ) : (
                    <div className="flex items-center justify-center gap-1 mt-1">
                        <Lock className="w-3 h-3 text-white/25" />
                        <span className="text-[10px] text-white/25">Guide à venir</span>
                    </div>
                )}

                {dofus.levelRecommended > 0 && (
                    <p className="text-[10px] text-white/30 text-center mt-0.5">
                        Niveau {dofus.levelRecommended}+
                    </p>
                )}
            </div>

            {/* Bottom accent line */}
            <div
                className="h-0.5 w-full transition-all duration-300"
                style={{
                    background: isObtained
                        ? `linear-gradient(90deg, transparent, ${color}, transparent)`
                        : `linear-gradient(90deg, transparent, ${color}44, transparent)`,
                    opacity: isObtained ? 1 : 0.5,
                }}
            />
        </Link>
    );
}

"use client";

import React, { useMemo } from "react";
import { 
    Package, 
    ChevronDown, 
    Info,
    Sword,
    ScrollText
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { ItemInline, detectRealDungeons, filterQuestItemsFromResources, extractObjectiveText } from "./dofus-resolvers";
import { cn } from "@/lib/utils";

interface DofusGlobalLogisticsProps {
    chains: any[];
    dofusColor: string;
    completedIds?: Set<string>;
}

export function DofusGlobalLogistics({ chains, dofusColor, completedIds }: DofusGlobalLogisticsProps) {
    const [isExpanded, setIsExpanded] = React.useState(false);
    const [filteredItems, setFilteredItems] = React.useState<{id: string, amount: number, name: string, img?: string}[]>([]);
    const [isLoadingItems, setIsLoadingItems] = React.useState(true);

    const logistics = useMemo(() => {
        const items = new Map<string, { id: string; amount: number; name: string; img?: string }>();
        const dungeons = new Map<string, { id?: string; name: string; bossName?: string; level?: number; img?: string; idoleName?: string }>();
        let totalQuests = 0;

        // Collect data from ALL chains (including prerequisites) for a true global summary
        (chains || []).forEach(chain => {
            (chain.entries || []).forEach((quest: any) => {
                if (completedIds && completedIds.has(String(quest.id))) return;
                totalQuests++;
                
                // Collect Items from structured data
                (quest.itemsRequired || []).forEach((req: any) => {
                    const id = String(req.id);
                    if (items.has(id)) {
                        items.get(id)!.amount += (req.amount || 1);
                        if (req.img && !items.get(id)!.img) items.get(id)!.img = req.img;
                    } else {
                        items.set(id, { id, amount: req.amount || 1, name: req.name || "Objet", img: req.img });
                    }
                });

                // Detect Items from objective text patterns (V3 support)
                const objectives = Array.isArray(quest.objectives) ? quest.objectives : [];
                objectives.forEach((obj: any) => {
                    const text = extractObjectiveText(obj);
                    const regex = /(?:(\d+)\s*(?:[xX]\s*|de\s*)?)?\{item,\s*(\d+)(?:,(\d+))?\}/g;
                    let match;
                    while ((match = regex.exec(text)) !== null) {
                        const amountStr = match[1];
                        const amount = amountStr ? parseInt(amountStr, 10) : 1;
                        const id = match[2];
                        if (items.has(id)) {
                            items.get(id)!.amount += amount;
                        } else {
                            items.set(id, { id, amount, name: "Ressource" });
                        }
                    }
                });
                
                // Read dungeonsRequired directly from compiled data (V3)
                (quest.dungeonsRequired || []).forEach((d: any) => {
                    const key = d.name || `Dungeon-${d.id}`;
                    if (!dungeons.has(key)) {
                        dungeons.set(key, {
                            id: d.bossId ? String(d.bossId) : d.id ? String(d.id) : undefined,
                            name: d.name === "Risquer un œil" ? "Risquer un œil" : d.name,
                            level: d.level,
                            bossName: d.bossName,
                            img: d.img,
                            idoleName: d.idoleName
                        });
                    }
                });
                
                // Fallback: detect dungeons from objective text patterns
                const dungeonInfos = detectRealDungeons(objectives);
                for (const dungeonInfo of dungeonInfos) {
                    if (dungeonInfo.isDungeon && dungeonInfo.dungeonName) {
                        if (!dungeons.has(dungeonInfo.dungeonName)) {
                            dungeons.set(dungeonInfo.dungeonName, { 
                                name: dungeonInfo.dungeonName,
                                id: dungeonInfo.bossId ? String(dungeonInfo.bossId) : undefined,
                                img: dungeonInfo.mapImg
                            });
                        } else if (dungeonInfo.mapImg) {
                            // Merge the image if it wasn't provided by the compiler generated block!
                            const existing = dungeons.get(dungeonInfo.dungeonName)!;
                            if (!existing.img && dungeonInfo.mapImg) {
                                existing.img = dungeonInfo.mapImg;
                            }
                            if (!existing.id && dungeonInfo.bossId) {
                                existing.id = String(dungeonInfo.bossId);
                            }
                        }
                    }
                }
            });
        });

        return {
            items: Array.from(items.values()).sort((a,b) => b.amount - a.amount),
            dungeons: Array.from(dungeons.values()).sort((a,b) => (a.level || 0) - (b.level || 0) || a.name.localeCompare(b.name)),
            totalQuests
        };
    }, [chains]);

    React.useEffect(() => {
        if (!logistics.items.length) {
            setFilteredItems([]);
            setIsLoadingItems(false);
            return;
        }

        let isMounted = true;
        setIsLoadingItems(true);

        filterQuestItemsFromResources(logistics.items)
            .then(filtered => {
                if (isMounted) {
                    setFilteredItems(filtered.length > 0 ? filtered : logistics.items);
                    setIsLoadingItems(false);
                }
            })
            .catch(() => {
                if (isMounted) {
                    setFilteredItems(logistics.items);
                    setIsLoadingItems(false);
                }
            });

        return () => { isMounted = false; };
    }, [logistics.items]);

    if (!chains || chains.length === 0) return null;

    return (
        <div className="w-full relative z-10 isolate mb-12">
            <div 
                onClick={() => setIsExpanded(!isExpanded)}
                className={cn(
                    "w-full p-6 bg-white/[0.03] border border-white/10 rounded-[2.5rem] flex flex-col sm:flex-row items-center justify-between cursor-pointer hover:bg-white/[0.05] transition-all group gap-6",
                    isExpanded && "rounded-b-none border-b-0 bg-white/[0.05]"
                )}
            >
                <div className="flex flex-col sm:flex-row items-center gap-6 sm:gap-8 w-full sm:w-auto">
                    <div className={cn(
                        "w-12 h-12 rounded-2xl flex items-center justify-center border shadow-2xl transition-transform group-hover:scale-110 shrink-0",
                        isExpanded ? "bg-white text-black border-white" : "bg-white/5 border-white/10 text-zinc-500"
                    )}>
                        <Info className="w-6 h-6" />
                    </div>
                    <div className="flex flex-col sm:flex-row items-center sm:items-start gap-4 sm:gap-12 w-full text-center sm:text-left">
                        <div>
                            <div className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em] mb-1">RÉCAPITULATIF GLOBAL</div>
                            <div className="text-[18px] font-black text-white italic uppercase tracking-tighter">Logistique du Dofus</div>
                        </div>
                        <div className="flex flex-wrap justify-center sm:justify-start items-center gap-4 sm:gap-8 text-[11px] font-black uppercase tracking-widest text-zinc-500">
                            <div className="flex items-center gap-2"><ScrollText className="w-4 h-4" /> {logistics.totalQuests} Quêtes</div>
                            <div className="flex items-center gap-2"><Package className="w-4 h-4" /> {isLoadingItems ? "..." : filteredItems.length} Ressources</div>
                        </div>
                    </div>
                </div>
                
                <div className={cn(
                    "w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center transition-transform shrink-0",
                    isExpanded && "rotate-180 bg-white/10"
                )}>
                    <ChevronDown className="w-5 h-5 text-white/50" />
                </div>
            </div>

            <AnimatePresence>
                {isExpanded && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.3, ease: "easeInOut" }}
                        className="overflow-hidden bg-white/[0.02] border border-t-0 border-white/10 rounded-b-[2.5rem]"
                    >
                        <div className="p-8 grid grid-cols-1 lg:grid-cols-12 gap-12">
                            {/* Resources Column */}
                            <div className="lg:col-span-5 space-y-6">
                                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                    <h4 className="text-[11px] font-black text-zinc-400 uppercase tracking-[0.4em] flex items-center gap-3">
                                        <Package className="w-4 h-4" /> Ressources à prévoir
                                    </h4>
                                    <span className="text-[10px] font-black px-3 py-1 bg-white/5 rounded-full text-zinc-500">{filteredItems.length} TYPES</span>
                                </div>

                                {isLoadingItems ? (
                                    <div className="p-8 border border-dashed border-white/10 rounded-3xl text-center text-zinc-600 italic text-[13px] flex flex-col items-center gap-2">
                                        <div className="w-4 h-4 border-2 border-zinc-600 border-t-white rounded-full animate-spin"></div>
                                        Analyse logistique en cours...
                                    </div>
                                ) : filteredItems.length > 0 ? (
                                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2 gap-3 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
                                        {filteredItems.map((item) => (
                                            <div key={item.id} className="flex items-center gap-3 p-2 bg-black/40 border border-white/5 rounded-2xl hover:border-white/20 transition-all group">
                                                <div className="w-9 h-9 bg-zinc-900 rounded-xl flex items-center justify-center p-1.5 relative shrink-0">
                                                    <img 
                                                        src={item.img || `https://static.dofusdb.fr/items/${item.id}.png`} 
                                                        alt="" 
                                                        className="w-full h-full object-contain icon-glow group-hover:scale-110 transition-transform"
                                                        onError={(e) => (e.currentTarget.style.display = 'none')}
                                                    />
                                                    <div className="absolute -top-1.5 -right-1.5 bg-indigo-500 text-white text-[9px] font-black px-1.5 py-0.5 rounded-md shadow-lg border border-white/10">
                                                        x{item.amount}
                                                    </div>
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <span className="text-[11px] font-bold"><ItemInline itemId={item.id} /></span>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="p-8 border border-dashed border-white/10 rounded-3xl text-center text-zinc-600 italic text-[13px]">
                                        Aucune ressource spécifique listée.
                                    </div>
                                )}
                            </div>

                            {/* Dungeons Column - REFACTORED TO GRID */}
                            <div className="lg:col-span-7 space-y-6">
                                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                    <h4 className="text-[11px] font-black text-zinc-400 uppercase tracking-[0.4em] flex items-center gap-3">
                                        <Sword className="w-4 h-4" /> Donjons Requis
                                    </h4>
                                    <span className="text-[10px] font-black px-3 py-1 bg-white/5 rounded-full text-zinc-500">{logistics.dungeons.length} BOSS</span>
                                </div>

                                {logistics.dungeons.length > 0 ? (
                                    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar content-start">
                                        {logistics.dungeons.map((d, i) => (
                                            <div key={i} className="flex flex-col gap-2 p-3 bg-rose-500/5 border border-rose-500/10 rounded-2xl group hover:border-rose-500/30 transition-all relative overflow-hidden h-fit">
                                                {/* Idol Badge */}
                                                {d.idoleName && (
                                                    <div className="absolute top-0 right-0 px-2 py-0.5 bg-amber-500/20 border-b border-l border-amber-500/30 rounded-bl-lg text-[7px] font-black text-amber-500 uppercase tracking-widest z-10">
                                                        {d.idoleName}
                                                    </div>
                                                )}
                                                
                                                <div className="flex items-center gap-3">
                                                    <div className="w-10 h-10 rounded-xl bg-black/60 border border-white/5 flex items-center justify-center p-1 shrink-0 relative overflow-hidden group-hover:scale-105 transition-transform shadow-inner">
                                                        {(d.id || d.img) ? (
                                                            <img 
                                                                src={d.img || `https://static.dofusdb.fr/monsters/${d.id}.png`} 
                                                                className="w-full h-full object-contain relative z-10" 
                                                                onError={(e) => (e.currentTarget.style.display = 'none')}
                                                                alt={d.name}
                                                            />
                                                        ) : (
                                                            <span className="text-rose-500 text-base">🏰</span>
                                                        )}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <div className="text-[11px] font-black text-white italic truncate group-hover:text-rose-400 transition-colors uppercase leading-tight">
                                                            {d.name}
                                                        </div>
                                                        <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5 mt-0.5 opacity-50">
                                                            {d.level && d.level > 0 && (
                                                                <span className="text-[8px] text-zinc-500 font-bold uppercase tracking-wider whitespace-nowrap">Lvl {d.level}</span>
                                                            )}
                                                            {d.bossName && (
                                                                <span className="text-[8px] text-zinc-600 font-bold italic truncate">— {d.bossName}</span>
                                                            )}
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="p-8 border border-dashed border-white/10 rounded-3xl text-center text-zinc-600 italic text-[13px]">
                                        Aucun donjon requis.
                                    </div>
                                )}
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import Image from "next/image";
import { useState } from "react";
import { Gem } from "lucide-react";

interface DofusIconProps {
    name: string;
    size?: number;
    color?: string;
    isObtained?: boolean;
    className?: string;
}

export function DofusIcon({ 
    name, 
    size = 64, 
    color = "#6366f1", 
    isObtained = false,
    className = "" 
}: DofusIconProps) {
    const [error, setError] = useState(false);
    
    // 🛠️ ULTIMATE ROBUST FILENAME RESOLUTION
    const normalizeName = (str: string) => {
        const n = str.trim();
        
        // Specific alias mappings based on filesystem audit
        if (n === "Glaces") return "Des_Glaces";
        if (n === "Cauchemar") return "Du_Cauchemar";
        if (n === "Scintillant") return "Argente_Scintillant";
        
        if (n === "Argenté" || n === "Tacheté") return n;
        
        // Strip ALL accents for other Dofus (e.g., Ébène -> Ebene, Émeraude -> Emeraude)
        return n.normalize("NFD")
                .replace(/[\u0300-\u036f]/g, "") // Remove combining diacritics
                .replace(/\s+/g, '_');          // Spaces to underscores
    };

    const localSrc = `/module-dofus/Dofus_${normalizeName(name)}.png`;
    const fallbackSrc = "https://static.dofusdb.fr/items/19000.png";

    if (error) {
        return (
            <Image
                src={fallbackSrc}
                alt={name}
                width={size}
                height={size}
                className={`object-contain ${className}`}
                style={{
                    filter: isObtained
                        ? `drop-shadow(0 0 12px ${color}99)`
                        : `drop-shadow(0 0 6px ${color}44)`,
                }}
            />
        );
    }

    return (
        <Image
            src={localSrc}
            alt={name}
            width={size}
            height={size}
            className={`object-contain ${className}`}
            onError={() => setError(true)}
            style={{
                filter: isObtained
                    ? `drop-shadow(0 0 12px ${color}99)`
                    : `drop-shadow(0 0 6px ${color}44)`,
            }}
        />
    );
}

"use client";

import React, { useMemo, useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
    Check,
    Lock,
    ChevronRight,
    ChevronDown,
    MapPin,
    Target,
    BookOpen,
    Copy,
    Sword,
    Package,
    ArrowRight,
    ExternalLink,
} from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { MemberOnQuest } from "@/server/actions/dofus-quest-actions";
import {
    NpcName,
    ParsedObjective,
    ItemInline,
    copyWithToast,
    detectRealDungeons,
    filterQuestItemsFromResources,
    extractObjectiveText,
} from "./dofus-resolvers";
import { ScrollArea } from "@/components/ui/scroll-area";
import { DofusIcon } from "./DofusIcon";
import { QuestGuildStatus } from "./QuestGuildStatus";

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────
interface DofusNeuralTreeProps {
    guildId: string;
    dofus: any;
    chains: any[];
    synergy: Record<string, MemberOnQuest[]>;
    dofusColor: string;
    onToggleStatus: (questId: string, status: any) => void;
    completedIds: Set<string>;
}

// ─────────────────────────────────────────────────────────────────────────────
// Section type metadata
// ─────────────────────────────────────────────────────────────────────────────
const SECTION_META: Record<string, { label: string; accent: string }> = {
    PREREQUISITE: { label: "Prérequis",      accent: "#f59e0b" },
    MAIN_CHAIN:   { label: "Quêtes",         accent: "#6366f1" },
    OPTIONAL:     { label: "Optionnel",      accent: "#6b7280" },
};

function sectionMeta(type: string, dofusColor: string) {
    return SECTION_META[type] || { label: type, accent: dofusColor };
}

// ─────────────────────────────────────────────────────────────────────────────
// Quest card (inline in roadmap)
// ─────────────────────────────────────────────────────────────────────────────
function QuestCard({
    entry,
    guildId,
    dofusColor,
    completedIds,
    onToggle,
    index,
}: {
    entry: any;
    guildId: string;
    dofusColor: string;
    completedIds: Set<string>;
    onToggle: (id: string, status: any) => void;
    index: number;
}) {
    const [expanded, setExpanded] = useState(false);

    const isDone = useMemo(() => 
        completedIds.has(entry.id) || (entry.dofusdbId && completedIds.has(String(entry.dofusdbId))),
    [entry.id, entry.dofusdbId, completedIds]);

    const isLocked = useMemo(() => {
        const reqs = Array.isArray(entry.requirements) ? entry.requirements : [];
        if (reqs.length === 0) return false;
        return reqs.some((r: any) => {
            if (r?.type !== "QUEST") return false;
            const rid = r.id || r.dofusdbId;
            return !completedIds.has(String(rid));
        });
    }, [entry.requirements, completedIds]);

    // V3 structured dungeons
    const structuredDungeons: any[] = entry.dungeonsRequired ?? [];
    const dungeonInfos = useMemo(
        () => detectRealDungeons(Array.isArray(entry.objectives) ? entry.objectives : []),
        [entry]
    );
    const hasDungeons = structuredDungeons.length > 0 || dungeonInfos.length > 0;

    return (
        <motion.div
            initial={{ opacity: 0, x: -12 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: index * 0.04, duration: 0.3 }}
            className={`relative rounded-2xl border transition-all duration-300 overflow-hidden ${
                isDone
                    ? "bg-emerald-500/5 border-emerald-500/20"
                    : isLocked
                    ? "bg-zinc-900/20 border-white/5 opacity-40"
                    : expanded
                    ? "bg-white/5 border-white/20 shadow-lg"
                    : "bg-white/[0.02] border-white/5 hover:border-white/15"
            }`}
        >
            {/* Header row */}
            <div
                className="flex items-center gap-3 px-4 py-3 cursor-pointer select-none"
                onClick={() => !isLocked && setExpanded(!expanded)}
            >
                {/* Status bullet */}
                <button
                    className={`flex-shrink-0 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                        isDone
                            ? "bg-emerald-500 border-emerald-400"
                            : isLocked
                            ? "border-zinc-700 cursor-not-allowed"
                            : "border-white/20 hover:border-white/60"
                    }`}
                    onClick={(e) => {
                        e.stopPropagation();
                        if (isLocked && !isDone) return;
                        onToggle(entry.id, isDone ? "NOT_STARTED" : "COMPLETED");
                    }}
                    disabled={isLocked && !isDone}
                >
                    {isDone ? (
                        <Check className="w-3 h-3 text-black" />
                    ) : isLocked ? (
                        <Lock className="w-3 h-3 text-zinc-700" />
                    ) : null}
                </button>

                {/* Quest name + meta */}
                <div className="flex-1 min-w-0">
                    <span
                        className={`text-[13px] font-black italic tracking-tight ${
                            isDone ? "text-white/30 line-through" : "text-white"
                        }`}
                    >
                        {entry.name}
                    </span>
                    <div className="flex items-center gap-2 mt-0.5">
                        {entry.zone && (
                            <span className="text-[9px] text-zinc-600 font-bold uppercase tracking-widest">
                                {entry.zone}
                            </span>
                        )}
                        {entry.level != null && (
                            <span className="text-[9px] text-zinc-700 font-medium">
                                Lvl {entry.level}
                            </span>
                        )}
                    </div>
                </div>

                {/* Right badges */}
                <div className="flex items-center gap-2 flex-shrink-0">
                    {hasDungeons && (
                        <span className="text-[9px] text-rose-400/80 font-black uppercase">
                            🏰
                        </span>
                    )}
                    {entry.isLast && (
                        <span
                            className="text-[8px] font-black uppercase px-2 py-0.5 rounded-lg"
                            style={{ background: `${dofusColor}25`, color: dofusColor }}
                        >
                            🎯 Final
                        </span>
                    )}
                    {!isLocked && (
                        <ChevronDown
                            className={`w-3.5 h-3.5 text-zinc-600 transition-transform ${
                                expanded ? "rotate-180" : ""
                            }`}
                        />
                    )}
                </div>
            </div>

            {/* Expanded content */}
            <AnimatePresence>
                {expanded && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="overflow-hidden"
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div className="px-5 pb-5 pt-1 ml-9 border-l border-white/5 space-y-4">
                            {/* V3 Structured Dungeons */}
                            {structuredDungeons.map((d, dx) => (
                                <div
                                    key={`sd-${dx}`}
                                    className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3"
                                >
                                    <div className="w-12 h-12 rounded-xl bg-black/60 border border-rose-500/20 flex items-center justify-center p-1 shrink-0 overflow-hidden">
                                        {d.img ? (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img
                                                src={d.img}
                                                alt={d.name}
                                                className="w-full h-full object-contain"
                                                onError={(e) => {
                                                    (e.target as HTMLImageElement).style.display = "none";
                                                }}
                                            />
                                        ) : d.id ? (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img
                                                src={`https://static.dofusdb.fr/monsters/${d.id}.png`}
                                                alt={d.name}
                                                className="w-full h-full object-contain"
                                                onError={(e) => {
                                                    (e.target as HTMLImageElement).style.display = "none";
                                                }}
                                            />
                                        ) : (
                                            <span className="text-rose-400">🏰</span>
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="text-[9px] font-black text-rose-400 uppercase tracking-widest mb-0.5">
                                            🏰 Donjon requis
                                        </div>
                                        <div className="text-[13px] font-black text-white italic truncate">
                                            {d.name}
                                        </div>
                                        <div className="flex items-center gap-2 mt-0.5">
                                            {d.level && d.level > 0 && (
                                                <span className="text-[9px] text-zinc-500 font-bold uppercase">
                                                    Lvl {d.level}
                                                </span>
                                            )}
                                            {d.bossName && (
                                                <span className="text-[9px] text-zinc-600 italic">
                                                    — {d.bossName}
                                                </span>
                                            )}
                                            {d.idoleName && (
                                                <span className="text-[8px] font-black text-amber-500 bg-amber-500/10 px-1 py-0.5 rounded">
                                                    {d.idoleName}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            ))}

                            {/* Fallback text-parsed dungeons */}
                            {structuredDungeons.length === 0 &&
                                dungeonInfos.map((di, dx) => (
                                    <div
                                        key={`di-${dx}`}
                                        className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3"
                                    >
                                        {di.mapImg && (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img
                                                src={di.mapImg}
                                                alt={di.dungeonName}
                                                className="w-12 h-12 object-cover rounded-xl border border-rose-500/30"
                                                onError={(e) => {
                                                    (e.target as HTMLImageElement).style.display = "none";
                                                }}
                                            />
                                        )}
                                        <div className="flex-1 min-w-0">
                                            <div className="text-[9px] font-black text-rose-400 uppercase tracking-widest mb-0.5">
                                                🏰 Donjon
                                            </div>
                                            <div className="text-[13px] font-black text-white italic">
                                                {di.dungeonName}
                                            </div>
                                        </div>
                                        {di.x !== undefined && (
                                            <Link
                                                href={`/dashboard/${guildId}/worldmap?x=${di.x}&y=${di.y}&zoom=4&world=${di.worldId ?? 0}`}
                                                className="h-8 w-8 rounded-xl bg-rose-500 text-black flex items-center justify-center hover:scale-110 transition-transform flex-shrink-0"
                                                onClick={(e) => e.stopPropagation()}
                                            >
                                                <MapPin className="w-4 h-4" />
                                            </Link>
                                        )}
                                    </div>
                                ))}

                            {/* NPC GPS */}
                            {entry.coords && (
                                <div className="p-3 bg-indigo-500/5 border border-indigo-500/15 rounded-xl flex items-center justify-between">
                                    <div
                                        className="flex items-center gap-2 cursor-pointer group/travel"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            copyWithToast(`/travel ${entry.coords.x} ${entry.coords.y}`);
                                        }}
                                    >
                                        <div className="w-7 h-7 rounded-lg bg-indigo-500/10 flex items-center justify-center text-indigo-400">
                                            <MapPin className="w-3.5 h-3.5" />
                                        </div>
                                        <div>
                                            <div className="text-[9px] font-black text-zinc-600 uppercase tracking-widest group-hover/travel:text-indigo-400 transition-colors">
                                                PNJ OBJECTIF
                                            </div>
                                            <div className="text-[12px] font-bold text-white italic group-hover/travel:text-emerald-400 transition-colors">
                                                {(() => {
                                                    const objectives = Array.isArray(entry.objectives) ? entry.objectives : [];
                                                    const objWithNpc = objectives.find((o: any) =>
                                                        extractObjectiveText(o).includes("{npc,")
                                                    );
                                                    const match = extractObjectiveText(objWithNpc).match(/\{npc,(\d+)\}/);
                                                    return match ? (
                                                        <NpcName npcId={match[1]} />
                                                    ) : (
                                                        entry.npcName || "PNJ"
                                                    );
                                                })()}{" "}
                                                <span className="text-zinc-600 font-normal">
                                                    [{entry.coords.x}, {entry.coords.y}]
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    <Link
                                        href={`/dashboard/${guildId}/worldmap?x=${entry.coords.x}&y=${entry.coords.y}&zoom=4&world=${entry.coords.worldId ?? 0}`}
                                        className="h-7 w-7 rounded-lg bg-emerald-500 text-black flex items-center justify-center hover:scale-110 transition-transform shadow-[0_0_12px_rgba(16,185,129,0.3)]"
                                        onClick={(e) => e.stopPropagation()}
                                    >
                                        <MapPin className="w-3.5 h-3.5" />
                                    </Link>
                                </div>
                            )}

                            {/* Objectives */}
                            {Array.isArray(entry.objectives) && entry.objectives.length > 0 && (
                                <div className="space-y-1.5">
                                    <div className="text-[9px] font-black text-zinc-700 uppercase tracking-widest italic mb-2">
                                        Marche à suivre
                                    </div>
                                    {entry.objectives.map((obj: any, i: number) => {
                                        const text = extractObjectiveText(obj);
                                        const isReturn =
                                            text.toLowerCase().includes("retour") ||
                                            text.toLowerCase().includes("aller voir");
                                        return (
                                            <div key={i} className="flex gap-2 items-start py-0.5">
                                                <div
                                                    className={`w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5 text-[8px] font-black ${
                                                        isReturn ? "animate-pulse" : ""
                                                    }`}
                                                    style={{
                                                        background: isReturn
                                                            ? `${dofusColor}40`
                                                            : "rgba(255,255,255,0.05)",
                                                        color: isReturn ? "#fff" : "rgba(255,255,255,0.3)",
                                                    }}
                                                >
                                                    {i + 1}
                                                </div>
                                                <div
                                                    className={`text-[12px] font-medium leading-relaxed ${
                                                        isReturn ? "text-white" : "text-zinc-500"
                                                    }`}
                                                >
                                                    <ParsedObjective
                                                        text={obj}
                                                        guildId={guildId}
                                                        zone={entry.zone ?? undefined}
                                                    />
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}

                            {/* Quick links */}
                            <div className="flex items-center gap-2 pt-1">
                                <a
                                    href={`https://dofusdb.fr/fr/database/quest/${entry.dofusdbId || entry.id}`}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="text-[9px] font-black uppercase italic text-zinc-600 hover:text-white px-2.5 py-1 bg-white/5 rounded-lg border border-white/5 transition-all hover:bg-white/10 flex items-center gap-1"
                                    onClick={(e) => e.stopPropagation()}
                                >
                                    <Target className="w-2.5 h-2.5" /> DofusDB
                                </a>
                                <a
                                    href={`https://www.google.com/search?q=site:dofuspourlesnoobs.com+${encodeURIComponent(entry.name)}`}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="text-[9px] font-black uppercase italic text-zinc-600 hover:text-white px-2.5 py-1 bg-white/5 rounded-lg border border-white/5 transition-all hover:bg-white/10 flex items-center gap-1"
                                    onClick={(e) => e.stopPropagation()}
                                >
                                    <BookOpen className="w-2.5 h-2.5" /> Noobs
                                </a>
                                {entry.coords && (
                                    <button
                                        className="text-[9px] font-black uppercase italic text-zinc-600 hover:text-emerald-400 px-2.5 py-1 bg-white/5 rounded-lg border border-white/5 transition-all hover:bg-white/10 flex items-center gap-1"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            copyWithToast(`/travel ${entry.coords.x} ${entry.coords.y}`);
                                        }}
                                    >
                                        <Copy className="w-2.5 h-2.5" /> Travel
                                    </button>
                                )}
                            </div>

                            {/* Action terminal */}
                            <div className="flex flex-col gap-3">
                                <div className="grid grid-cols-2 gap-2">
                                    <a 
                                        href={`https://dofusdb.fr/fr/database/quest/${entry.dofusdbId || entry.id}`} 
                                        target="_blank" 
                                        className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-indigo-500/5 border border-indigo-500/10 hover:bg-indigo-500/15 hover:border-indigo-500/30 text-[10px] font-black text-indigo-400 uppercase tracking-widest transition-all shadow-lg shadow-indigo-900/10"
                                    >
                                        <Target className="w-5 h-5" /> DofusDB
                                    </a>
                                    
                                    <a 
                                        href={`https://www.google.com/search?q=site:dofuspourlesnoobs.com+${encodeURIComponent(entry.name)}`} 
                                        target="_blank" 
                                        className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-amber-500/5 border border-amber-500/10 hover:bg-amber-500/15 hover:border-amber-500/30 text-[10px] font-black text-amber-400 uppercase tracking-widest transition-all shadow-lg shadow-amber-900/10"
                                    >
                                        <BookOpen className="w-5 h-5" /> Noobs
                                    </a>

                                    {entry.coords && (
                                        <button 
                                            onClick={() => copyWithToast(`/travel ${entry.coords?.x} ${entry.coords?.y}`)}
                                            className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-emerald-500/5 border border-emerald-500/10 hover:bg-emerald-500/15 hover:border-emerald-500/30 text-[10px] font-black text-emerald-400 uppercase tracking-widest transition-all shadow-lg shadow-emerald-900/10"
                                        >
                                            <MapPin className="w-5 h-5" /> Travel
                                        </button>
                                    )}

                                    <QuestGuildStatus 
                                        guildId={guildId} 
                                        questId={entry.id} 
                                        dofusColor={dofusColor} 
                                        variant="action"
                                    />
                                </div>
                                <Button
                                    disabled={isLocked && !isDone}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        if (isLocked && !isDone) return;
                                        onToggle(entry.id, isDone ? "NOT_STARTED" : "COMPLETED");
                                    }}
                                    className={`w-full h-10 rounded-xl font-black italic uppercase text-[11px] tracking-widest transition-all ${
                                        isDone
                                            ? "bg-zinc-900 border border-white/10 text-zinc-500"
                                            : isLocked
                                            ? "bg-zinc-950 text-white/10 border border-white/5 cursor-not-allowed"
                                            : "bg-white text-black hover:bg-zinc-200 shadow-[0_0_20px_rgba(255,255,255,0.08)]"
                                    }`}
                                >
                                    {isDone ? "✓ Réinitialiser" : isLocked ? "🔒 Verrouillée" : "Valider l'étape"}
                                </Button>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </motion.div>
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Resources panel (identical logic to DofusGlobalLogistics)
// ─────────────────────────────────────────────────────────────────────────────
function RoadmapResources({ chains, dofusColor, completedIds }: { chains: any[]; dofusColor: string; completedIds: Set<string> }) {
    const raw = useMemo(() => {
        const items = new Map<string, { id: string; amount: number; name: string; img?: string }>();
        const dungeons = new Map<string, { id?: string; name: string; bossName?: string; level?: number; img?: string; idoleName?: string }>();

        chains.forEach((chain) => {
            (chain.entries || []).forEach((quest: any) => {
                if (completedIds.has(String(quest.id))) return;
                (quest.itemsRequired || []).forEach((req: any) => {
                    const id = String(req.id);
                    if (items.has(id)) {
                        items.get(id)!.amount += req.amount || 1;
                    } else {
                        items.set(id, { id, amount: req.amount || 1, name: req.name || "Objet", img: req.img });
                    }
                });
                (quest.dungeonsRequired || []).forEach((d: any) => {
                    const key = d.name;
                    if (!dungeons.has(key)) dungeons.set(key, { id: d.id ? String(d.id) : undefined, name: d.name, level: d.level, bossName: d.bossName, img: d.img, idoleName: d.idoleName });
                });
            });
        });

        return {
            items: Array.from(items.values()).sort((a, b) => b.amount - a.amount),
            dungeons: Array.from(dungeons.values()).sort((a, b) => (a.level || 0) - (b.level || 0)),
        };
    }, [chains, completedIds]);

    const [filteredItems, setFilteredItems] = useState<typeof raw.items>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!raw.items.length) { setFilteredItems([]); setLoading(false); return; }
        let mounted = true;
        setLoading(true);
        filterQuestItemsFromResources(raw.items).then((f) => {
            if (mounted) { setFilteredItems(f.length > 0 ? f : raw.items); setLoading(false); }
        }).catch(() => { if (mounted) { setFilteredItems(raw.items); setLoading(false); } });
        return () => { mounted = false; };
    }, [raw.items]);

    return (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
            {/* Resources */}
            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <h4 className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.4em] flex items-center gap-2">
                        <Package className="w-4 h-4" /> Ressources à prévoir
                    </h4>
                    <span className="text-[9px] font-black px-2 py-0.5 bg-white/5 rounded-full text-zinc-600">
                        {loading ? "..." : filteredItems.length} TYPES
                    </span>
                </div>
                {loading ? (
                    <div className="flex items-center gap-2 py-6 text-zinc-600 italic text-[12px]">
                        <div className="w-4 h-4 border-2 border-zinc-700 border-t-white rounded-full animate-spin" />
                        Analyse en cours…
                    </div>
                ) : filteredItems.length > 0 ? (
                    <div className="grid grid-cols-2 gap-2">
                        {filteredItems.map((item) => (
                            <div key={item.id} className="flex items-center gap-3 p-2.5 bg-black/40 border border-white/5 rounded-2xl hover:border-white/15 transition-all">
                                <div className="w-9 h-9 bg-white/5 rounded-xl flex items-center justify-center p-1 relative shrink-0">
                                    {/* eslint-disable-next-line @next/next/no-img-element */}
                                    <img
                                        src={item.img || `https://static.dofusdb.fr/items/${item.id}.png`}
                                        alt=""
                                        className="w-full h-full object-contain"
                                        onError={(e) => ((e.currentTarget.style.display = "none"))}
                                    />
                                    <div className="absolute -bottom-1.5 -right-1.5 bg-indigo-500 text-white text-[8px] font-black px-1 py-0.5 rounded-md">
                                        x{item.amount}
                                    </div>
                                </div>
                                <div className="flex-1 min-w-0">
                                    <ItemInline itemId={item.id} />
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="py-8 text-center text-zinc-700 italic text-[12px]">
                        Aucune ressource listée dans ce parcours.
                    </div>
                )}
            </div>

            {/* Dungeons */}
            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <h4 className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.4em] flex items-center gap-2">
                        <Sword className="w-4 h-4" /> Donjons Requis
                    </h4>
                    <span className="text-[9px] font-black px-2 py-0.5 bg-white/5 rounded-full text-zinc-600">
                        {raw.dungeons.length} BOSS
                    </span>
                </div>
                {raw.dungeons.length > 0 ? (
                    <div className="space-y-2">
                        {raw.dungeons.map((d, i) => (
                            <div key={i} className="flex items-center gap-3 p-2.5 bg-rose-500/5 border border-rose-500/10 rounded-2xl hover:border-rose-500/25 transition-all relative overflow-hidden">
                                {d.idoleName && (
                                    <div className="absolute top-0 right-0 px-2 py-0.5 bg-amber-500/20 border-b border-l border-amber-500/30 rounded-bl-lg text-[7px] font-black text-amber-500 uppercase z-10">
                                        {d.idoleName}
                                    </div>
                                )}
                                <div className="w-11 h-11 rounded-xl bg-black/60 border border-white/5 flex items-center justify-center p-1 shrink-0 overflow-hidden">
                                    {(d.id || d.img) ? (
                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img
                                            src={d.img || `https://static.dofusdb.fr/monsters/${d.id}.png`}
                                            className="w-full h-full object-contain"
                                            alt={d.name}
                                            onError={(e) => ((e.currentTarget.style.display = "none"))}
                                        />
                                    ) : (
                                        <span className="text-rose-500">🏰</span>
                                    )}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="text-[12px] font-black text-white italic truncate">{d.name}</div>
                                    <div className="flex items-center gap-2 mt-0.5">
                                        {d.level && d.level > 0 && (
                                            <span className="text-[9px] text-zinc-600 font-bold uppercase">Lvl {d.level}</span>
                                        )}
                                        {d.bossName && (
                                            <span className="text-[9px] text-zinc-700 italic">— {d.bossName}</span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="py-8 text-center text-zinc-700 italic text-[12px]">
                        Aucun donjon détecté dans ce parcours.
                    </div>
                )}
            </div>
        </div>
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Main export — renamed internally but keeping the export name for compatibility
// ─────────────────────────────────────────────────────────────────────────────
export function DofusNeuralTree({
    guildId,
    dofus,
    chains,
    dofusColor,
    onToggleStatus,
    completedIds,
    synergy,
}: DofusNeuralTreeProps) {
    const [activeTab, setActiveTab] = useState<"roadmap" | "resources">("roadmap");
    const [openChainId, setOpenChainId] = useState<string | null>(null);

    const stats = useMemo(() => {
        const total = chains.flatMap((c) => c.entries || []).length;
        const done = chains.flatMap((c) => c.entries || []).filter((e: any) => completedIds.has(e.id) || (e.dofusdbId && completedIds.has(String(e.dofusdbId)))).length;
        return { total, done, pct: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [chains, completedIds]);

    return (
        <div className="space-y-6">
            {/* Toolbar */}
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 bg-zinc-950/60 border border-white/5 rounded-2xl">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-white/5 rounded-2xl border border-white/10 flex items-center justify-center">
                        <DofusIcon name={dofus.nameShort || dofus.name} size={32} />
                    </div>
                    <div>
                        <div className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em] mb-0.5">
                            Feuille de Route
                        </div>
                        <div className="text-[16px] font-black text-white italic uppercase tracking-tighter">
                            {dofus.name}
                        </div>
                    </div>
                    <div className="hidden sm:flex flex-col items-end ml-4">
                        <div className="text-[11px] font-black text-zinc-500 tabular-nums">
                            {stats.done}/{stats.total} quêtes
                        </div>
                        <div className="w-32 h-1.5 bg-white/5 rounded-full overflow-hidden mt-1.5">
                            <motion.div
                                className="h-full rounded-full"
                                style={{ background: dofusColor }}
                                initial={{ width: 0 }}
                                animate={{ width: `${stats.pct}%` }}
                                transition={{ duration: 1 }}
                            />
                        </div>
                    </div>
                </div>

                {/* Tab switcher */}
                <div className="flex p-1 bg-zinc-950/80 rounded-xl border border-white/5">
                    {(["roadmap", "resources"] as const).map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={`h-8 px-3 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${
                                activeTab === tab
                                    ? "bg-white text-black shadow"
                                    : "text-zinc-500 hover:text-white"
                            }`}
                        >
                            {tab === "roadmap" ? "📋 Parcours" : "📦 Ressources Totales"}
                        </button>
                    ))}
                </div>
            </div>

            {/* Roadmap view */}
            {activeTab === "roadmap" && (
                <div className="space-y-6">
                    {chains.map((chain, ci) => {
                        const entries = chain.entries || [];
                        const done = entries.filter((e: any) => completedIds.has(e.id) || (e.dofusdbId && completedIds.has(String(e.dofusdbId)))).length;
                        const total = entries.length;
                        const allDone = done === total && total > 0;
                        const meta = sectionMeta(chain.sectionType, dofusColor);
                        const isOpen = openChainId === chain.id;

                        return (
                            <div key={chain.id} className="space-y-2">
                                {/* Chain header */}
                                <button
                                    onClick={() => setOpenChainId(isOpen ? null : chain.id)}
                                    className={`w-full flex items-center gap-4 p-4 rounded-2xl border text-left transition-all duration-200 group ${
                                        allDone
                                            ? "bg-emerald-500/5 border-emerald-500/20"
                                            : isOpen
                                            ? "bg-white/5 border-white/15"
                                            : "bg-white/[0.02] border-white/5 hover:border-white/15"
                                    }`}
                                >
                                    {/* Chain order indicator */}
                                    <div
                                        className="w-8 h-8 rounded-xl flex items-center justify-center text-[11px] font-black flex-shrink-0 transition-all"
                                        style={{
                                            background: allDone ? "#10b981" : isOpen ? `${dofusColor}30` : "rgba(255,255,255,0.04)",
                                            color: allDone ? "black" : isOpen ? dofusColor : "rgba(255,255,255,0.3)",
                                            border: `1px solid ${allDone ? "#10b98140" : isOpen ? `${dofusColor}50` : "rgba(255,255,255,0.06)"}`,
                                        }}
                                    >
                                        {allDone ? <Check className="w-4 h-4" /> : ci + 1}
                                    </div>

                                    {/* Name + badge */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 flex-wrap">
                                            <span
                                                className={`text-[14px] font-black italic tracking-tight ${
                                                    allDone ? "text-emerald-400" : "text-white"
                                                }`}
                                            >
                                                {chain.sectionName}
                                            </span>
                                            <span
                                                className="text-[8px] font-black uppercase px-2 py-0.5 rounded-full"
                                                style={{
                                                    background: `${meta.accent}20`,
                                                    color: meta.accent,
                                                    border: `1px solid ${meta.accent}30`,
                                                }}
                                            >
                                                {meta.label}
                                            </span>
                                        </div>
                                        {chain.description && !isOpen && (
                                            <div className="text-[10px] text-zinc-600 mt-0.5 truncate">
                                                {chain.description}
                                            </div>
                                        )}
                                    </div>

                                    {/* Progress + chevron */}
                                    <div className="flex items-center gap-3 flex-shrink-0">
                                        <span className="text-[10px] font-black text-zinc-600 tabular-nums">
                                            {done}/{total}
                                        </span>
                                        <div className="w-16 h-1 bg-white/5 rounded-full overflow-hidden hidden sm:block">
                                            <div
                                                className="h-full rounded-full transition-all duration-500"
                                                style={{
                                                    width: total > 0 ? `${Math.round((done / total) * 100)}%` : "0%",
                                                    background: allDone ? "#10b981" : dofusColor,
                                                }}
                                            />
                                        </div>
                                        <ChevronDown
                                            className={`w-4 h-4 text-zinc-600 transition-transform ${isOpen ? "rotate-180" : ""}`}
                                        />
                                    </div>
                                </button>

                                {/* Quest cards */}
                                <AnimatePresence>
                                    {isOpen && (
                                        <motion.div
                                            initial={{ opacity: 0, height: 0 }}
                                            animate={{ opacity: 1, height: "auto" }}
                                            exit={{ opacity: 0, height: 0 }}
                                            className="overflow-hidden"
                                        >
                                            <div className="ml-4 pl-4 border-l-2 border-dashed border-white/5 space-y-2 pt-2 pb-2">
                                                {entries.map((entry: any, ei: number) => (
                                                    <QuestCard
                                                        key={entry.id}
                                                        entry={entry}
                                                        guildId={guildId}
                                                        dofusColor={dofusColor}
                                                        completedIds={completedIds}
                                                        onToggle={onToggleStatus}
                                                        index={ei}
                                                    />
                                                ))}
                                                {entries.length === 0 && (
                                                    <div className="py-4 text-center text-zinc-700 italic text-[12px]">
                                                        Aucune entrée pour cette section.
                                                    </div>
                                                )}
                                            </div>
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </div>
                        );
                    })}
                </div>
            )}

            {/* Resources view */}
            {activeTab === "resources" && (
                <div className="bg-zinc-950/40 border border-white/5 rounded-3xl p-8">
                    <RoadmapResources chains={chains} dofusColor={dofusColor} completedIds={completedIds} />
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect, useTransition } from "react";
import { motion } from "framer-motion";
import { Shield, RefreshCw, Unlink, CheckCircle2, Zap, Info, Crown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { 
    getMyOcreProgress, 
    unlinkOcreAccount,
    OcreProgressData
} from "@/server/actions/ocre-actions";

interface DofusOcreMetamobProps {
    guildId: string;
    metamobUsername: string | null;
    onLinkMetamob: (pseudo: string) => Promise<any>;
}

export function DofusOcreMetamob({ guildId, metamobUsername, onLinkMetamob }: DofusOcreMetamobProps) {
    const [username, setUsername] = useState<string | null>(metamobUsername);
    const [isPending, startTransition] = React.useTransition();

    async function handleLink(u: string) {
        const res = await onLinkMetamob(u);
        if (res.success) {
            setUsername(u);
            toast.success("Compte Metamob lié !");
        } else {
            throw new Error(res.error ?? "Erreur de liaison");
        }
    }

    async function handleUnlink() {
        if (!confirm("Voulez-vous délier votre compte Metamob ?")) return;
        startTransition(async () => {
            const res = await unlinkOcreAccount({ guildId });
            if (res.success) {
                setUsername(null);
                toast.success("Compte délié");
            }
        });
    }

    return (
        <div className="w-full">
            {username ? (
                <MetamobProgressView 
                    guildId={guildId} 
                    username={username} 
                    onUnlink={handleUnlink} 
                />
            ) : (
                <MetamobLinkPrompt onLink={handleLink} />
            )}
        </div>
    );
}

function MetamobLinkPrompt({ onLink }: { onLink: (username: string) => Promise<void> }) {
    const [username, setUsername] = useState("");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    return (
        <div className="py-12 flex flex-col items-center text-center gap-6 max-w-sm mx-auto">
            <div className="w-16 h-16 rounded-3xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center">
                <Crown className="w-8 h-8 text-amber-400" />
            </div>
            <div>
                <h3 className="text-lg font-black text-white italic uppercase tracking-tighter">Lier ton Ocre</h3>
                <p className="text-[12px] text-zinc-500 leading-relaxed mt-1">
                    Connecte ton compte <span className="text-amber-400 font-bold">Metamob</span> pour synchroniser ta progression réelle.
                </p>
            </div>
            <form onSubmit={async (e) => {
                e.preventDefault();
                setLoading(true);
                setError(null);
                try { await onLink(username); }
                catch (err: any) { setError(err.message); }
                finally { setLoading(false); }
            }} className="w-full space-y-3">
                <input
                    type="text"
                    value={username}
                    onChange={e => setUsername(e.target.value)}
                    placeholder="Pseudo Metamob"
                    className="w-full h-11 bg-zinc-950/80 border border-white/10 rounded-2xl px-4 text-white text-sm font-bold focus:border-amber-500/40 outline-none transition-colors"
                />
                <Button disabled={loading || !username} className="w-full h-11 bg-amber-500 text-black font-black uppercase tracking-widest rounded-2xl">
                    {loading ? "Liaison..." : "Lier mon compte"}
                </Button>
                {error && <div className="text-rose-400 text-[10px] uppercase font-bold">{error}</div>}
            </form>
        </div>
    );
}

function MetamobProgressView({ guildId, username, onUnlink }: { guildId: string; username: string; onUnlink: () => void }) {
    const [data, setData] = useState<OcreProgressData | null>(null);
    const [loading, setLoading] = useState(true);

    async function refresh() {
        setLoading(true);
        const res = await getMyOcreProgress(guildId);
        if (res.success && res.data) setData(res.data);
        setLoading(false);
    }

    useEffect(() => { refresh(); }, [guildId]);

    const StatItem = ({ label, current, total, color }: { label: string; current: number; total: number; color: string }) => {
        const pct = total > 0 ? Math.min(100, Math.round((current / total) * 100)) : 0;
        return (
            <div className="space-y-2">
                <div className="flex justify-between text-[10px] font-black uppercase tracking-widest">
                    <span className="text-zinc-500">{label}</span>
                    <span className="text-white">{current} / {total}</span>
                </div>
                <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                    <motion.div 
                        initial={{ width: 0 }} 
                        animate={{ width: `${pct}%` }} 
                        className={`h-full rounded-full transition-all duration-500 ${color}`}
                    />
                </div>
            </div>
        );
    };

    if (loading && !data) return (
        <div className="py-12 flex flex-col items-center gap-3 opacity-50">
            <RefreshCw className="w-5 h-5 animate-spin text-amber-500" />
            <span className="text-[10px] font-black uppercase tracking-widest">Metamob Sync...</span>
        </div>
    );

    return (
        <div className="p-1 space-y-8 animate-in fade-in slide-in-from-top-4 duration-700">
            <div className="flex items-center justify-between gap-4 p-4 bg-zinc-950/40 border border-white/5 rounded-3xl backdrop-blur-md">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center">
                        <Shield className="w-5 h-5 text-amber-400" />
                    </div>
                </div>
                <div className="flex-1 min-w-0">
                    <div className="text-[9px] font-black text-amber-500/60 uppercase tracking-widest">Metamob Live</div>
                    <div className="flex items-center gap-2">
                        <div className="text-sm font-black text-white italic truncate">{username}</div>
                        <a 
                            href={`/dashboard/${guildId}/quete-ocre`} 
                            className="p-1 rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 transition-colors"
                        >
                            <Crown className="w-3 h-3 text-amber-400" />
                        </a>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <Button variant="ghost" size="icon" onClick={refresh} disabled={loading} className="w-8 h-8 rounded-xl text-zinc-500 hover:text-white">
                        <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} />
                    </Button>
                    <Button variant="ghost" size="sm" onClick={onUnlink} className="h-8 px-3 text-[9px] font-black uppercase text-zinc-700 hover:text-rose-400 rounded-xl">
                        <Unlink className="w-3 h-3" />
                    </Button>
                </div>
            </div>

            {data && (
                <div className="grid sm:grid-cols-3 gap-6 px-2">
                    <StatItem label="Étapes Quête" current={data.questInfo.currentStep} total={34} color="bg-amber-500" />
                    <StatItem label="Gardiens" current={data.stats.bosses.gathered} total={data.stats.bosses.total} color="bg-blue-500" />
                    <StatItem label="Archimonstres" current={data.stats.archis.gathered} total={data.stats.archis.total} color="bg-emerald-500" />
                </div>
            )}

            {data && data.stats.bosses.gathered < data.stats.bosses.total && (
                <div className="space-y-4 px-2">
                    <div className="flex items-center gap-2 text-[10px] font-black text-zinc-500 uppercase tracking-widest">
                        <Zap className="w-3 h-3 text-amber-400" /> Prochaines cibles (Boss)
                    </div>
                    <div className="grid grid-cols-3 sm:grid-cols-5 gap-3">
                        {data.monsters
                            .filter(m => m.type === "boss" && m.state === "MANQUANT")
                            .slice(0, 5)
                            .map(m => (
                                <div key={m.id} className="group relative flex flex-col items-center gap-2 p-3 bg-white/[0.02] border border-white/5 rounded-2xl hover:bg-white/[0.05] transition-all">
                                    <div className="relative w-12 h-12 grayscale opacity-40 group-hover:grayscale-0 group-hover:opacity-100 transition-all">
                                        <img 
                                            src={`https://www.metamob.fr/images/monstres/${m.id}.png`} 
                                            alt={m.name} 
                                            className="w-full h-full object-contain"
                                            onError={(e) => { 
                                                (e.target as HTMLImageElement).src = `https://static.dofusdb.fr/monsters/${m.id}.png`; 
                                            }}
                                        />
                                    </div>
                                    <div className="text-[8px] font-black text-zinc-600 text-center uppercase truncate w-full">{m.name}</div>
                                </div>
                            ))
                        }
                    </div>
                </div>
            )}

            <div className="flex items-start gap-2 p-3 bg-blue-500/5 rounded-2xl border border-blue-500/10">
                <Info className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
                <p className="text-[10px] text-zinc-600 italic leading-relaxed">
                    Données synchronisées avec Metamob. Mets à jour tes captures sur le site pour voir ta progression ici.
                </p>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams, useRouter, usePathname } from "next/navigation";
import { Gem, Users, Search, Crown, Sparkles } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { DofusGemCard } from "./DofusGemCard";
import { GuildDofusOverview } from "./GuildDofusOverview";
import { SylvestreDonut } from "./SylvestreDonut";
import { OptimizedGuideTab } from "./OptimizedGuideTab";
import type { DofusItemWithProgress, GuildDofusStats, MemberDofusSummary, WarRoomData } from "@/server/actions/dofus-quest-actions";

type Tab = "mes-dofus" | "routes" | "guilde";

interface DofusQuestHubProps {
    dofusList: DofusItemWithProgress[];
    guildStats: { stats: GuildDofusStats[]; topMembers: MemberDofusSummary[]; totalMembers: number } | null;
    guides?: any[];
    guildId: string;
    selectedCharacter?: string;
}

export function DofusQuestHub({ dofusList, guildStats, guides = [], guildId, selectedCharacter = "PRINCIPAL" }: DofusQuestHubProps) {
    const searchParams = useSearchParams();
    const router = useRouter();
    const pathname = usePathname();
    
    const [activeTab, setActiveTab] = useState<Tab>((searchParams.get("tab") as Tab) || "mes-dofus");
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<"Tous" | "Obtenus" | "En cours" | "À faire">("Tous");

    const handleTabChange = (tab: Tab) => {
        setActiveTab(tab);
        const params = new URLSearchParams(searchParams);
        params.set("tab", tab);
        router.push(`${pathname}?${params.toString()}`, { scroll: false });
    };

    useEffect(() => {
        const tab = searchParams.get("tab") as Tab;
        if (tab && tab !== activeTab) {
            setActiveTab(tab);
        }
    }, [searchParams]);

    const tabs: { id: Tab; label: string; icon: React.ElementType; desc: string }[] = [
        { id: "mes-dofus", label: "Mes Dofus", icon: Gem, desc: "État des reliques" },
        { id: "routes", label: "Guide Optimisé", icon: Sparkles, desc: "Routes stratégiques" },
        { id: "guilde", label: "Guilde", icon: Users, desc: "Progression commune" },
    ];

    const sylvestre = dofusList.find(d => d.isMeta);
    const totalObtained = dofusList.filter((d) => d.isObtained).length;
    const overallPercent = dofusList.length > 0
        ? Math.round(dofusList.reduce((sum, d) => sum + d.progressPercent, 0) / dofusList.length)
        : 0;

    const filtered = dofusList
        .filter((d) => {
            if (search) {
                return d.name.toLowerCase().includes(search.toLowerCase()) ||
                    d.nameShort.toLowerCase().includes(search.toLowerCase());
            }
            return true;
        })
        .filter((d) => {
            switch (statusFilter) {
                case "Obtenus": return d.isObtained;
                case "En cours": return !d.isObtained && d.progressPercent > 0;
                case "À faire": return !d.isObtained && d.progressPercent === 0;
                default: return true;
            }
        });

    return (
        <div className="flex flex-col gap-8">
            {/* ── PERSISTENT COMMAND HEADER ── */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">
                {/* Meta-Goal: Sylvestre */}
                <div className="lg:col-span-12 xl:col-span-5 h-full">
                    {sylvestre && (
                        <SylvestreDonut 
                            sylvestre={sylvestre} 
                            allDofus={dofusList} 
                            guildId={guildId} 
                        />
                    )}
                </div>

                {/* Personal Stats Hub */}
                <div className="lg:col-span-12 xl:col-span-7 grid grid-cols-1 md:grid-cols-2 gap-4 h-full">
                    <div className="group relative bg-zinc-950/40 backdrop-blur-xl border border-white/5 rounded-3xl p-6 flex flex-col justify-between overflow-hidden shadow-2xl">
                         <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                         <div className="relative flex items-center justify-between mb-4">
                            <div className="p-3 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 text-indigo-400">
                                <Crown className="w-6 h-6" />
                            </div>
                            <span className="text-4xl font-black text-white tabular-nums italic tracking-tighter">
                                {totalObtained}<span className="text-zinc-500 text-sm ml-2 font-black italic">/ {dofusList.length}</span>
                            </span>
                         </div>
                         <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 mb-1">Inventaire Personnel</p>
                            <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden border border-white/5 mt-2">
                                <motion.div 
                                    initial={{ width: 0 }}
                                    animate={{ width: `${(totalObtained / dofusList.length) * 100}%` }}
                                    className="h-full bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.5)]"
                                />
                            </div>
                         </div>
                    </div>

                    <div className="group relative bg-zinc-950/40 backdrop-blur-xl border border-white/5 rounded-3xl p-6 flex flex-col justify-between overflow-hidden shadow-2xl">
                         <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                         <div className="relative flex items-center justify-between mb-4">
                            <div className="p-3 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-400">
                                <Sparkles className="w-6 h-6" />
                            </div>
                            <span className="text-4xl font-black text-white tabular-nums italic tracking-tighter">
                                {overallPercent}<span className="text-emerald-500 text-sm ml-1 font-black italic">%</span>
                            </span>
                         </div>
                         <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 mb-1">Efficacité Globale</p>
                            <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden border border-white/5 mt-2">
                                <motion.div 
                                    initial={{ width: 0 }}
                                    animate={{ width: `${overallPercent}%` }}
                                    className="h-full bg-emerald-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]"
                                />
                            </div>
                         </div>
                    </div>
                </div>
            </div>

            {/* ── CORE MISSION LAYOUT ── */}
            <div className="flex flex-col lg:flex-row gap-8 items-start min-h-[700px]">
                {/* VERTICAL NAV SIDEBAR */}
                <div className="w-full lg:w-72 shrink-0 flex flex-col gap-2 p-3 bg-zinc-950/40 backdrop-blur-xl border border-white/5 rounded-[2.5rem] shadow-2xl">
                    <div className="px-5 py-4 mb-2 flex items-center justify-between">
                        <span className="text-[9px] font-black uppercase tracking-[0.4em] text-zinc-500">Navigation</span>
                        <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]" />
                    </div>
                    {tabs.map((tab) => {
                        const Icon = tab.icon;
                        const isActive = activeTab === tab.id;
                        return (
                            <button
                                key={tab.id}
                                onClick={() => handleTabChange(tab.id)}
                                className={`
                                    w-full group relative flex items-center gap-4 px-5 py-5 rounded-[1.5rem] transition-all duration-300
                                    ${isActive 
                                        ? "bg-white/[0.04] border border-white/5 shadow-inner" 
                                        : "hover:bg-white/[0.02] border border-transparent"}
                                `}
                            >
                                {isActive && (
                                    <motion.div 
                                        layoutId="active-nav-glow"
                                        className="absolute left-0 w-1.5 h-10 bg-indigo-500 rounded-full blur-[3px]" 
                                    />
                                )}
                                <div className={`p-3 rounded-2xl transition-all duration-500 ${isActive ? 'bg-indigo-500 text-white scale-110 shadow-[0_0_20px_rgba(99,102,241,0.4)]' : 'bg-black/60 text-zinc-600 group-hover:text-zinc-400 group-hover:bg-zinc-900'}`}>
                                    <Icon className="w-5 h-5" />
                                </div>
                                <div className="flex flex-col items-start text-left min-w-0">
                                    <span className={`text-[12px] font-black uppercase tracking-[0.1em] ${isActive ? 'text-white italic' : 'text-zinc-500'}`}>
                                        {tab.label}
                                    </span>
                                    <span className={`text-[10px] font-bold truncate w-full ${isActive ? 'text-indigo-400/70' : 'text-zinc-700'}`}>
                                        {tab.desc}
                                    </span>
                                </div>
                            </button>
                        );
                    })}

                    <div className="mt-auto px-5 py-6">
                        {/* Empty space for better balance or future character-specific stats */}
                    </div>
                </div>

                {/* MAIN DASHBOARD CONTENT */}
                <div className="flex-1 w-full flex flex-col gap-8">
                    {/* View Toolbar */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 px-1 border-b border-white/5 pb-8">
                        <div className="flex flex-col">
                            <h2 className="text-4xl font-black text-white italic uppercase tracking-tighter drop-shadow-2xl">
                                {tabs.find(t => t.id === activeTab)?.label}
                            </h2>
                        </div>

                        {activeTab === "mes-dofus" && (
                            <div className="flex flex-wrap items-center gap-4">
                                <div className="relative group">
                                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600 group-hover:text-indigo-400 transition-colors" />
                                    <input
                                        type="text"
                                        placeholder="Localiser un artefact..."
                                        value={search}
                                        onChange={(e) => setSearch(e.target.value)}
                                        className="bg-black/60 border border-white/5 rounded-2xl pl-12 pr-6 py-3.5 text-xs text-white placeholder:text-zinc-700 focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 w-full md:w-80 transition-all shadow-2xl shadow-black/40"
                                    />
                                </div>

                                <div className="flex items-center gap-1.5 p-1.5 bg-black/60 border border-white/5 rounded-2xl shadow-2xl">
                                    {["Tous", "Obtenus", "En cours", "À faire"].map((f) => (
                                        <button
                                            key={f}
                                            onClick={() => setStatusFilter(f as any)}
                                            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === f ? "bg-zinc-800 text-white shadow-xl shadow-black/60 ring-1 ring-white/10" : "text-zinc-600 hover:text-zinc-400"}`}
                                        >
                                            {f}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="relative">
                        <AnimatePresence mode="wait">
                            <motion.div
                                key={activeTab}
                                initial={{ opacity: 0, y: 15 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0, y: -15 }}
                                transition={{ duration: 0.4, ease: [0.23, 1, 0.32, 1] }}
                            >
                                {activeTab === "mes-dofus" && (
                                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                                        {filtered.length === 0 ? (
                                            <div className="col-span-full py-32 flex flex-col items-center justify-center gap-4 bg-zinc-950/20 border border-dashed border-white/5 rounded-[3rem]">
                                                <div className="p-6 rounded-full bg-white/5">
                                                    <Search className="w-12 h-12 text-zinc-800" />
                                                </div>
                                                <p className="text-zinc-600 font-black uppercase text-xs tracking-widest italic">Aucune transmission ne correspond à ce filtre</p>
                                            </div>
                                        ) : (
                                            filtered.map((dofus) => (
                                                <DofusGemCard 
                                                    key={dofus.id} 
                                                    dofus={dofus} 
                                                    guildId={guildId} 
                                                    selectedCharacter={selectedCharacter} 
                                                />
                                            ))
                                        )}
                                    </div>
                                )}

                                {activeTab === "routes" && (
                                    <div className="bg-zinc-950/20 rounded-[3rem] p-4 border border-white/5 shadow-2xl min-h-[500px]">
                                        <OptimizedGuideTab initialGuides={guides} guildId={guildId} />
                                    </div>
                                )}

                                {activeTab === "guilde" && (
                                    <div className="bg-zinc-950/20 rounded-[3rem] p-1 border border-white/5 shadow-2xl">
                                        <GuildDofusOverview 
                                            stats={guildStats?.stats || []} 
                                            topMembers={guildStats?.topMembers || []}
                                            totalMembers={guildStats?.totalMembers || 0}
                                            guildId={guildId}
                                        />
                                    </div>
                                )}
                            </motion.div>
                        </AnimatePresence>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition, useMemo } from "react";
import { 
    getGuildSynergyForDofus, 
    toggleQuestStatus,
    MemberOnQuest,
    GuildHeatmapData,
} from "@/server/actions/dofus-quest-actions";
import { DofusNeuralTree } from "./DofusNeuralTree";
import { DofusSuccessGrid } from "./DofusSuccessGrid";
import { DofusGlobalLogistics } from "./DofusGlobalLogistics";
import { QuestChecklist } from "./QuestChecklist";
import { GuildDofusHeatmap } from "./GuildDofusHeatmap";
import { Button } from "@/components/ui/button";
import { LayoutList, RefreshCw, Users, LayoutGrid, Flame, Route } from "lucide-react";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { DofusQuestStatus } from "@prisma/client";

interface DofusQuestManagerV3Props {
    guildId: string;
    dofus: any;
    chains: any[];
    dofusColor: string;
    heatmapData?: GuildHeatmapData | null;
    selectedCharacter?: string;
    initialGlobalCompletedIds?: string[];
}

type ViewMode = "tree" | "successes" | "heatmap";

export function DofusQuestManagerV3({ 
    guildId, 
    dofus, 
    chains, 
    dofusColor, 
    heatmapData,
    selectedCharacter = "PRINCIPAL",
    initialGlobalCompletedIds = []
}: DofusQuestManagerV3Props) {
    const [viewMode, setViewMode] = useState<ViewMode>("tree");
    const [synergy, setSynergy] = useState<Record<string, MemberOnQuest[]>>({});
    const [loadingSynergy, setLoadingSynergy] = useState(false);
    
    // ... existing local overrides logic
    const [localOverrides, setLocalOverrides] = useState<Map<string, DofusQuestStatus>>(new Map());
    const router = useRouter();
    const [, startTransition] = useTransition();

    useEffect(() => {
        setLocalOverrides(new Map());
    }, [chains]);

    const completedIds = useMemo(() => {
        // Start with ALL completed IDs from the platform
        const ids = new Set<string>(initialGlobalCompletedIds);
        
        // Apply current Dofus chains and local overrides
        chains.forEach(c => {
            (c?.entries || []).forEach((e: any) => {
                const override = localOverrides.get(e.id);
                // If override is NOT_STARTED, we must remove it if it was in the global list
                if (override === "NOT_STARTED") {
                    ids.delete(e.id);
                    if (e.dofusdbId) ids.delete(String(e.dofusdbId));
                } else if (override === "COMPLETED" || e.status === "COMPLETED") {
                    ids.add(e.id);
                    if (e.dofusdbId) ids.add(String(e.dofusdbId));
                }
            });
        });
        return ids;
    }, [chains, localOverrides, initialGlobalCompletedIds]);

    async function handleToggleStatus(questId: string, newStatus: DofusQuestStatus) {
        setLocalOverrides(prev => {
            const next = new Map(prev);
            next.set(questId, newStatus);
            return next;
        });

        startTransition(async () => {
            const res = await toggleQuestStatus(guildId, questId, newStatus, selectedCharacter);
            if (res.success) {
                router.refresh();
            } else {
                toast.error(res.error || "Erreur de mise à jour");
                setLocalOverrides(prev => {
                    const next = new Map(prev);
                    next.delete(questId);
                    return next;
                });
            }
        });
    }

    async function loadSynergy() {
        setLoadingSynergy(true);
        const res = await getGuildSynergyForDofus(guildId, dofus.id);
        if (res.success && res.data) setSynergy(res.data);
        setLoadingSynergy(false);
    }

    useEffect(() => {
        loadSynergy();
        const interval = setInterval(loadSynergy, 120000);
        return () => clearInterval(interval);
    }, [dofus.id, guildId]);

    const totalMembers = Object.values(synergy).reduce((acc, members) => {
        members.forEach(m => acc.add(m.profileId));
        return acc;
    }, new Set()).size;

    const views: { id: ViewMode; label: string; Icon: any }[] = [
        { id: "tree",      label: "Parcours",     Icon: Route },
        { id: "successes", label: "Succès",       Icon: LayoutGrid },
        { id: "heatmap",   label: "Guilde",        Icon: Flame },
    ];

    return (
        <div className="space-y-4">
            <DofusGlobalLogistics chains={chains} dofusColor={dofus.color} completedIds={completedIds} />

            <div className="flex flex-col md:flex-row items-center justify-between gap-4 p-4 bg-zinc-950/40 border border-white/5 rounded-[2rem] backdrop-blur-xl mb-8">
                <div className="flex flex-col sm:flex-row items-center gap-4 w-full md:w-auto">
                    <div className="flex p-1.5 bg-black/40 rounded-2xl border border-white/5 w-full sm:w-auto overflow-x-auto no-scrollbar">
                        {views.map(({ id, label, Icon }) => (
                            <button
                                key={id}
                                onClick={() => setViewMode(id)}
                                className={`
                                    flex-1 sm:flex-none flex items-center justify-center gap-2 h-10 px-5 text-[11px] font-black uppercase tracking-widset rounded-xl transition-all duration-300 whitespace-nowrap
                                    ${viewMode === id
                                        ? "bg-white text-black shadow-2xl scale-[1.02]"
                                        : "text-zinc-500 hover:text-white hover:bg-white/5"
                                    }
                                `}
                            >
                                <Icon className="w-4 h-4" />
                                <span>{label}</span>
                                {id === "heatmap" && heatmapData && heatmapData.members.length > 0 && (
                                    <span className={`ml-1 px-1.5 py-0.5 rounded-md text-[8px] font-black ${viewMode === id ? "bg-black/10 text-black" : "bg-indigo-500/20 text-indigo-400"}`}>
                                        {heatmapData.members.length}
                                    </span>
                                )}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex items-center gap-4 w-full md:w-auto justify-between md:justify-end border-t md:border-t-0 border-white/5 pt-4 md:pt-0">
                    <div className="flex items-center gap-3">
                        {totalMembers > 0 && (
                            <div className="flex items-center gap-2 px-3 py-2 bg-indigo-500/10 border border-indigo-500/20 rounded-xl">
                                <Users className="w-3.5 h-3.5 text-indigo-400" />
                                <span className="text-[9px] font-black text-indigo-400 uppercase italic">
                                    {totalMembers} ACTIF{totalMembers > 1 ? "S" : ""}
                                </span>
                            </div>
                        )}
                        <button
                            onClick={loadSynergy}
                            disabled={loadingSynergy}
                            className="p-2.5 bg-white/5 border border-white/10 text-zinc-500 hover:text-white rounded-xl transition-all hover:bg-white/10"
                        >
                            <RefreshCw className={`w-4 h-4 ${loadingSynergy ? "animate-spin" : ""}`} />
                        </button>
                    </div>
                    
                    <div className="h-10 px-4 bg-zinc-900/60 border border-emerald-500/20 rounded-2xl flex items-center gap-2.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]" />
                        <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest italic">Analyseur IA</span>
                    </div>
                </div>
            </div>


            {/* ── Content ──────────────────────────────────────────────── */}
            <div className="relative">
                {viewMode === "successes" && (
                    <DofusSuccessGrid
                        guildId={guildId}
                        dofus={dofus}
                        chains={chains}
                        synergy={synergy}
                        dofusColor={dofusColor}
                        onToggleStatus={handleToggleStatus}
                        completedIds={completedIds}
                    />
                )}
                {viewMode === "tree" && (
                    <DofusNeuralTree
                        guildId={guildId}
                        dofus={dofus}
                        chains={chains}
                        synergy={synergy}
                        dofusColor={dofusColor}
                        onToggleStatus={handleToggleStatus}
                        completedIds={completedIds}
                    />
                )}
                {viewMode === "heatmap" && (
                    <div className="glass-premium border border-border rounded-2xl p-5">
                        {heatmapData ? (
                            <GuildDofusHeatmap
                                data={heatmapData}
                                dofusColor={dofusColor}
                                dofusName={dofus.nameShort || dofus.name}
                            />
                        ) : (
                            <div className="flex flex-col items-center justify-center py-16 gap-3">
                                <Flame className="w-10 h-10 text-foreground/10" />
                                <p className="text-muted-foreground/40 text-sm font-bold uppercase tracking-widest">Données indisponibles</p>
                                <p className="text-muted-foreground/20 text-xs text-center max-w-xs">
                                    Lance le seed depuis l&apos;admin panel pour charger les étapes, puis reviens ici.
                                </p>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import React, { useState, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
    Check, 
    Lock, 
    ChevronRight, 
    X, 
    BookOpen, 
    Zap, 
    Map as MapIcon, 
    MapPin,
    Copy
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { MemberOnQuest } from "@/server/actions/dofus-quest-actions";
import Link from "next/link";
import { Badge } from "@/components/ui/badge";
import { NpcName, ParsedObjective, copyWithToast, detectRealDungeons, extractObjectiveText, ItemInline } from "./dofus-resolvers";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Package, Target, Navigation, Users, Sword } from "lucide-react";
import { QuestGuildStatus } from "./QuestGuildStatus";



interface DofusSuccessGridProps {
    guildId: string;
    dofus: any;
    chains: any[];
    synergy: Record<string, MemberOnQuest[]>;
    dofusColor: string;
    onToggleStatus: (questId: string, status: any) => void;
    completedIds: Set<string>;
}

const SECTION_TYPES: Record<string, { label: string; color: string; order: number }> = {
    PREREQUISITE:   { label: "Prérequis", color: "#f59e0b", order: 1 },
    MAIN_CHAIN:     { label: "Arc Principal", color: "#6366f1", order: 2 },
    RESOURCE_CHAIN: { label: "Donjons & Ressources", color: "#ec4899", order: 3 },
    OPTIONAL:       { label: "Optionnel", color: "#6b7280", order: 4 },
};

export function DofusSuccessGrid({
    guildId,
    dofus,
    chains,
    synergy,
    dofusColor,
    onToggleStatus,
    completedIds,
}: DofusSuccessGridProps) {
    const [selectedChainId, setSelectedChainId] = useState<string | null>(null);
    const [selectedQuestId, setSelectedQuestId] = useState<string | null>(null);

    const groups = useMemo(() => {
        const map = new Map<string, any[]>();
        for (const c of chains) {
            const type = c.sectionType || "OTHER";
            if (!map.has(type)) map.set(type, []);
            map.get(type)!.push(c);
        }
        return Array.from(map.entries()).sort((a, b) => {
            const orderA = SECTION_TYPES[a[0]]?.order || 99;
            const orderB = SECTION_TYPES[b[0]]?.order || 99;
            return orderA - orderB;
        });
    }, [chains]);

    const getChainStats = (chain: any) => {
        const entries = chain.entries ?? [];
        const done = entries.filter((e: any) => completedIds.has(e.id) || (e.dofusdbId && completedIds.has(String(e.dofusdbId)))).length;
        return { done, total: entries.length, pct: entries.length ? Math.round((done / entries.length) * 100) : 0 };
    };

    const isLocked = (entry: any) => {
        if (!entry.requirements || !Array.isArray(entry.requirements) || entry.requirements.length === 0) return false;
        return entry.requirements.some((req: any) => {
            if (!req || typeof req !== 'object' || req.type !== "QUEST") return false;
            const rid = req.id || req.dofusdbId;
            return !completedIds.has(String(rid));
        });
    };

    const selectedChain = chains.find(c => c.id === selectedChainId);

    return (
        <div className="space-y-12">
            {/* Phase-based Roadmap */}
            {groups.map(([sectionType, zoneChains]) => {
                const config = SECTION_TYPES[sectionType] || { label: "Divers", color: dofusColor };
                const zoneName = config.label;
                const zoneColor = config.color;
                
                if (zoneChains.length === 0) return null;

                const totalInZone = zoneChains.reduce((acc, c) => acc + getChainStats(c).total, 0);
                const doneInZone = zoneChains.reduce((acc, c) => acc + getChainStats(c).done, 0);
                const zonePct = totalInZone > 0 ? Math.round((doneInZone / totalInZone) * 100) : 0;

                return (
                    <div key={sectionType} className="space-y-8">
                        {/* Section Header */}
                        <div className="flex items-end justify-between border-b border-white/5 pb-6">
                            <div className="flex items-center gap-5">
                                <div className="w-14 h-14 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center relative overflow-hidden group">
                                    <span className="text-2xl font-black italic opacity-20" style={{ color: zoneColor }}>{zoneName[0]}</span>
                                    <div className="absolute inset-x-0 bottom-0 h-1" style={{ background: zoneColor }} />
                                </div>
                                <div>
                                    <div className="text-[10px] font-black uppercase tracking-[0.4em] opacity-40 mb-1">Phase d'aventure</div>
                                    <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter leading-none">{zoneName}</h2>
                                </div>
                            </div>
                            <div className="flex flex-col items-end gap-2">
                                <span className="text-[11px] font-black text-white/40 tabular-nums uppercase tracking-widest">{doneInZone}/{totalInZone} quêtes complétées</span>
                                <div className="w-64 h-1.5 bg-white/5 rounded-full overflow-hidden border border-white/5 shadow-inner">
                                    <motion.div 
                                        className="h-full rounded-full shadow-[0_0_15px_rgba(255,255,255,0.1)]"
                                        style={{ background: zoneColor }}
                                        initial={{ width: 0 }}
                                        animate={{ width: `${zonePct}%` }}
                                        transition={{ duration: 1.2, ease: "easeOut" }}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Chain Cards */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                            {zoneChains.map((chain) => {
                                const stats = getChainStats(chain);
                                const isComplete = stats.done === stats.total && stats.total > 0;
                                const nextInChain = chain.entries?.find((e: any) => e.status !== "COMPLETED" && !isLocked(e));

                                return (
                                    <motion.button
                                        key={chain.id}
                                        onClick={() => setSelectedChainId(chain.id)}
                                        whileHover={{ scale: 1.02, y: -4 }}
                                        whileTap={{ scale: 0.98 }}
                                        className={`p-5 rounded-[2rem] border transition-all duration-500 flex flex-col gap-4 text-left group overflow-hidden ${
                                            isComplete 
                                                ? "bg-emerald-500/5 border-emerald-500/20 shadow-[0_0_30px_rgba(16,185,129,0.1)]" 
                                                : "bg-[#0c0d10] border-white/5 hover:border-white/20 active:bg-white/[0.02]"
                                        }`}
                                    >
                                        <div className="flex items-center justify-between">
                                            <Badge 
                                                variant="outline" 
                                                className={`text-[9px] font-black py-0.5 px-2 rounded-lg border transition-all ${
                                                    isComplete 
                                                        ? "bg-emerald-500/20 text-emerald-400 border-emerald-500/30 shadow-[0_0_10px_rgba(16,185,129,0.2)]" 
                                                        : "bg-white/5 text-zinc-500 border-white/5"
                                                }`}
                                                style={isComplete ? {} : {}}
                                            >
                                                {isComplete ? "✓ Succès" : "Succès"}
                                            </Badge>
                                            {isComplete ? (
                                                <Check className="w-4 h-4 text-emerald-500" />
                                            ) : (
                                                <span className="text-[10px] font-black tabular-nums text-zinc-600">{stats.done}/{stats.total}</span>
                                            )}
                                        </div>
                                        <div>
                                            <h3 className={`text-lg font-black italic leading-tight uppercase tracking-tighter transition-colors ${
                                                isComplete ? "text-emerald-400" : "text-white group-hover:text-indigo-400"
                                            }`}>{chain.sectionName}</h3>
                                            {nextInChain && !isComplete && (
                                                <p className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mt-2 truncate">→ {nextInChain.name}</p>
                                            )}
                                        </div>
                                        <div className="h-1 bg-white/5 rounded-full overflow-hidden">
                                            <div className="h-full rounded-full transition-all duration-700" style={{ background: isComplete ? "#10b981" : zoneColor, width: `${stats.pct}%` }} />
                                        </div>
                                    </motion.button>
                                );
                            })}
                        </div>
                    </div>
                );
            })}

            {/* Centered Detail Modal */}
            <Dialog open={!!selectedChain} onOpenChange={(open) => !open && setSelectedChainId(null)}>
                <DialogContent className="max-w-4xl h-[90vh] bg-[#050608] border-white/10 p-0 overflow-hidden rounded-[2.5rem] flex flex-col">
                    {/* Header Section */}
                    <div className="p-8 border-b border-white/5 flex items-start justify-between bg-zinc-950/50 flex-shrink-0">
                        <div>
                            <div className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] mb-2">
                                {selectedChain ? (SECTION_TYPES[selectedChain.sectionType]?.label || "Exploration") : ""}
                            </div>
                            <h3 className="text-3xl font-black text-white italic uppercase tracking-tighter">
                                {selectedChain?.sectionName}
                            </h3>
                        </div>
                    </div>

                    <ScrollArea className="flex-1 w-full overflow-y-auto">
                        <div className="p-8 space-y-6">
                            {selectedChain?.entries?.map((entry: any, i: number) => {
                                    const done = completedIds.has(entry.id) || (entry.dofusdbId && completedIds.has(String(entry.dofusdbId)));
                                    const lock = isLocked(entry);
                                    const expanded = selectedQuestId === entry.id;

                                    // V3 structured dungeons & Fallback text-parsed dungeons
                                    const structuredDungeons: any[] = entry.dungeonsRequired ?? [];
                                    const dungeonInfos = detectRealDungeons(Array.isArray(entry.objectives) ? entry.objectives : []);
                                    const hasDungeons = structuredDungeons.length > 0 || dungeonInfos.length > 0;
                                    const itemsReq = Array.isArray(entry.itemsRequired) ? entry.itemsRequired : [];

                                    return (
                                        <div key={entry.id} className="space-y-4">
                                            <div
                                                onClick={() => setSelectedQuestId(expanded ? null : entry.id)}
                                                className={`w-full p-6 rounded-[2rem] border text-left transition-all duration-300 relative overflow-hidden cursor-pointer ${
                                                    done ? "bg-emerald-500/5 border-emerald-500/20 opacity-60" 
                                                    : lock ? "bg-zinc-900/30 border-white/5 opacity-40 grayscale"
                                                    : expanded ? "bg-white/5 border-white/30 shadow-2xl"
                                                    : "bg-zinc-900/50 border-white/5 hover:border-white/20"
                                                }`}
                                            >
                                                <div className="flex items-center gap-4">
                                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0 font-black text-[14px] ${
                                                        done ? "bg-emerald-500 text-black shadow-[0_0_20px_rgba(16,185,129,0.3)]" : "bg-white/5 text-zinc-500"
                                                    }`}>
                                                        {done ? <Check className="w-6 h-6" /> : lock ? <Lock className="w-5 h-5" /> : i + 1}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <div className={`text-[17px] font-black italic uppercase tracking-tighter truncate ${done ? "line-through text-zinc-600" : "text-white"}`}>
                                                            {entry.name}
                                                        </div>
                                                        <div className="flex items-center gap-3 mt-1.5 flex-wrap">
                                                            {entry.level && <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest bg-white/5 px-2.5 py-1 rounded-xl">Lvl {entry.level}</span>}
                                                            {hasDungeons && <span className="text-[10px] font-black text-rose-400 uppercase tracking-widest bg-rose-500/10 border border-rose-500/20 px-2.5 py-1 rounded-xl flex items-center gap-1"><Sword className="w-3 h-3" /> Donjon</span>}
                                                            {itemsReq.length > 0 && <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest bg-amber-500/10 border border-amber-500/20 px-2.5 py-1 rounded-xl flex items-center gap-1"><Package className="w-3 h-3" /> x{itemsReq.length}</span>}
                                                            {lock && !done && <span className="text-[9px] font-black text-amber-500 uppercase tracking-widest bg-amber-500/10 px-2.5 py-1 rounded-xl border border-amber-500/20">Quête verrouillée</span>}
                                                        </div>
                                                    </div>
                                                    <ChevronRight className={`w-6 h-6 text-zinc-700 transition-transform ${expanded ? "rotate-90 text-white" : ""}`} />
                                                </div>

                                                <AnimatePresence>
                                                    {expanded && (
                                                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                                                            <div className="pt-8 mt-6 border-t border-white/5 space-y-8">
                                                                {/* NPC Meta Card */}
                                                                <div className="p-5 bg-indigo-500/10 border border-indigo-500/20 rounded-3xl flex items-center gap-5">
                                                                    <div className="w-14 h-14 bg-indigo-500/20 rounded-2xl flex items-center justify-center text-indigo-400">
                                                                        <MapPin className="w-7 h-7" />
                                                                    </div>
                                                                    <div 
                                                                        className="flex-1 min-w-0 cursor-pointer group/travel"
                                                                        onClick={(e) => { 
                                                                            e.stopPropagation();
                                                                            if (entry.coords) copyWithToast(`/travel ${entry.coords.x} ${entry.coords.y}`);
                                                                        }}
                                                                    >
                                                                        <div className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.3em] mb-1 group-hover/travel:text-emerald-400 transition-colors">
                                                                            PNJ NARRATIF
                                                                            <span className="opacity-0 group-hover/travel:opacity-60 text-[9px] bg-white/5 px-2.5 py-1 rounded-lg ml-4">COPIER /TRAVEL</span>
                                                                        </div>
                                                                        <div className="text-[15px] font-black text-white italic group-hover/travel:text-emerald-400 transition-colors">
                                                                            {(() => {
                                                                                const objectives = Array.isArray(entry.objectives) ? entry.objectives : [];
                                                                                const objWithNpc = objectives.find((o: any) => extractObjectiveText(o).includes("{npc,"));
                                                                                const match = extractObjectiveText(objWithNpc).match(/\{npc,(\d+)\}/);
                                                                                return match ? <NpcName npcId={match[1]} /> : (entry.npcName || entry.npcSubArea || "PNJ Curation");
                                                                            })()} {entry.coords && <span className="text-zinc-600 font-normal">en [{entry.coords.x}, {entry.coords.y}]</span>}
                                                                        </div>
                                                                    </div>
                                                                    {entry.coords && (
                                                                         <Link 
                                                                            href={`/dashboard/${guildId}/worldmap?x=${entry.coords.x}&y=${entry.coords.y}&zoom=4&world=${
                                                                                (entry as any).coords.worldId ?? 
                                                                                (((entry as any).zone || "").toLowerCase().includes("incarnam") || ((entry as any).npcSubArea || "").toLowerCase().includes("incarnam") ? 1 : 0)
                                                                            }`}
                                                                            onClick={(e) => e.stopPropagation()}
                                                                            className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-black hover:scale-110 transition-transform shadow-[0_0_20px_rgba(16,185,129,0.4)]"
                                                                         >
                                                                             <MapPin className="w-6 h-6" />
                                                                         </Link>
                                                                    )}
                                                                </div>

                                                                {/* Step Logistics */}
                                                                {Array.isArray(entry.objectives) && entry.objectives.length > 0 && (
                                                                    <div className="space-y-4">
                                                                        <div className="text-[11px] font-black text-zinc-600 uppercase tracking-[0.4em] px-1 italic">Logique de l'étape</div>
                                                                        <div className="space-y-3">
                                                                            {entry.objectives.map((obj: any, idx: number) => {
                                                                                const stepText = extractObjectiveText(obj);
                                                                                const isReturn = stepText.toLowerCase().includes("retour") || stepText.toLowerCase().includes("aller voir");
                                                                                return (
                                                                                    <div key={idx} className="flex gap-5 p-5 bg-white/[0.02] border border-white/5 rounded-[1.5rem] text-[14px] text-zinc-400 leading-relaxed font-bold">
                                                                                        <div className={`w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 text-[11px] font-black ${isReturn ? "bg-indigo-500 text-white shadow-[0_0_15px_rgba(99,102,241,0.4)] animate-pulse" : "bg-white/10 text-white/40"}`}>
                                                                                            {idx + 1}
                                                                                        </div>
                                                                                        <div className={isReturn ? "text-white" : ""}>
                                                                                            <ParsedObjective text={obj} guildId={guildId} zone={selectedChain ? SECTION_TYPES[selectedChain.sectionType]?.label : undefined} />
                                                                                        </div>
                                                                                    </div>
                                                                                );
                                                                            })}
                                                                        </div>
                                                                    </div>
                                                                )}

                                                                {/* V3 Structured Dungeons & Detected Dungeons */}
                                                                {hasDungeons && (
                                                                    <div className="space-y-3">
                                                                        {structuredDungeons.map((d, dx) => (
                                                                            <div key={`sd-${dx}`} className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-[1.5rem] flex items-center gap-4">
                                                                                <div className="w-14 h-14 rounded-xl bg-black/60 border border-rose-500/20 flex items-center justify-center p-1 shrink-0 overflow-hidden">
                                                                                    {d.img ? (
                                                                                        // eslint-disable-next-line @next/next/no-img-element
                                                                                        <img src={d.img} alt={d.name} className="w-full h-full object-contain" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                                                                    ) : d.id ? (
                                                                                        // eslint-disable-next-line @next/next/no-img-element
                                                                                        <img src={`https://static.dofusdb.fr/monsters/${d.id}.png`} alt={d.name} className="w-full h-full object-contain" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                                                                    ) : <span className="text-rose-400">🏰</span>}
                                                                                </div>
                                                                                <div className="flex-1 min-w-0">
                                                                                    <div className="text-[10px] font-black text-rose-400 uppercase tracking-widest mb-0.5">🏰 Donjon requis</div>
                                                                                    <div className="text-[15px] font-black text-white italic truncate">{d.name}</div>
                                                                                    <div className="flex items-center gap-2 mt-1 block">
                                                                                        {d.level && d.level > 0 && <span className="text-[9px] text-zinc-500 font-bold uppercase">Lvl {d.level}</span>}
                                                                                        {d.bossName && <span className="text-[9px] text-zinc-600 italic">— {d.bossName}</span>}
                                                                                        {d.idoleName && <span className="text-[8px] font-black text-amber-500 bg-amber-500/10 px-1 py-0.5 rounded">{d.idoleName}</span>}
                                                                                    </div>
                                                                                </div>
                                                                            </div>
                                                                        ))}
                                                                        {structuredDungeons.length === 0 && dungeonInfos.map((di, dx) => (
                                                                            <div key={`di-${dx}`} className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-[1.5rem] flex items-center gap-4">
                                                                                {di.mapImg && (
                                                                                    // eslint-disable-next-line @next/next/no-img-element
                                                                                    <img src={di.mapImg} alt={di.dungeonName} className="w-14 h-14 object-cover rounded-xl border border-rose-500/30" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                                                                )}
                                                                                <div className="flex-1 min-w-0">
                                                                                    <div className="text-[10px] font-black text-rose-400 uppercase tracking-widest mb-0.5">🏰 Donjon</div>
                                                                                    <div className="text-[15px] font-black text-white italic">{di.dungeonName}</div>
                                                                                </div>
                                                                                {di.x !== undefined && (
                                                                                    <Link href={`/dashboard/${guildId}/worldmap?x=${di.x}&y=${di.y}&zoom=4&world=${di.worldId ?? 0}`} className="h-10 w-10 rounded-xl bg-rose-500 text-black flex items-center justify-center hover:scale-110 transition-transform flex-shrink-0" onClick={(e) => e.stopPropagation()}>
                                                                                        <MapPin className="w-5 h-5" />
                                                                                    </Link>
                                                                                )}
                                                                            </div>
                                                                        ))}
                                                                    </div>
                                                                )}

                                                                {/* Required Items Resource Block */}
                                                                {itemsReq.length > 0 && (
                                                                    <div className="p-5 bg-amber-500/5 border border-amber-500/20 rounded-3xl">
                                                                        <div className="flex items-center gap-3 mb-4">
                                                                            <div className="w-8 h-8 rounded-xl bg-amber-500/20 flex items-center justify-center text-amber-400">
                                                                                <Package className="w-4 h-4" />
                                                                            </div>
                                                                            <div>
                                                                                <div className="text-[10px] font-black text-amber-400/70 uppercase tracking-widest">A prévoir pour cette quête</div>
                                                                                <div className="text-sm font-bold text-amber-400 italic">Ressources requises</div>
                                                                            </div>
                                                                        </div>
                                                                        <div className="flex flex-wrap gap-2">
                                                                            {itemsReq.map((req: any, index: number) => (
                                                                                <div key={index} className="flex items-center gap-2 bg-amber-500/10 px-3 py-1.5 rounded-[1rem] border border-amber-500/20">
                                                                                    <span className="text-[12px] font-black text-amber-500">x{req.amount || 1}</span>
                                                                                    <ItemInline itemId={req.id || String(req.id)} />
                                                                                </div>
                                                                            ))}
                                                                        </div>
                                                                    </div>
                                                                )}

                                                                {/* Action Terminal */}
                                                                <div className="flex flex-col gap-4">
                                                                    <div className="grid grid-cols-2 gap-2">
                                                                        <a 
                                                                            href={`https://dofusdb.fr/fr/database/quest/${entry.dofusdbId || entry.id}`} 
                                                                            target="_blank" 
                                                                            className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-indigo-500/5 border border-indigo-500/10 hover:bg-indigo-500/15 hover:border-indigo-500/30 text-[10px] font-black text-indigo-400 uppercase tracking-widest transition-all shadow-lg shadow-indigo-900/10"
                                                                        >
                                                                            <Target className="w-5 h-5" /> DofusDB
                                                                        </a>
                                                                        
                                                                        <a 
                                                                            href={`https://www.google.com/search?q=site:dofuspourlesnoobs.com+${encodeURIComponent(entry.name)}`} 
                                                                            target="_blank" 
                                                                            className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-amber-500/5 border border-amber-500/10 hover:bg-amber-500/15 hover:border-amber-500/30 text-[10px] font-black text-amber-400 uppercase tracking-widest transition-all shadow-lg shadow-amber-900/10"
                                                                        >
                                                                            <BookOpen className="w-5 h-5" /> Noobs
                                                                        </a>

                                                                        {entry.coords && (
                                                                            <button 
                                                                                onClick={() => copyWithToast(`/travel ${entry.coords.x} ${entry.coords.y}`)}
                                                                                className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-emerald-500/5 border border-emerald-500/10 hover:bg-emerald-500/15 hover:border-emerald-500/30 text-[10px] font-black text-emerald-400 uppercase tracking-widest transition-all shadow-lg shadow-emerald-900/10"
                                                                            >
                                                                                <Navigation className="w-5 h-5" /> Travel
                                                                            </button>
                                                                        )}

                                                                        <QuestGuildStatus 
                                                                            guildId={guildId} 
                                                                            questId={entry.id} 
                                                                            dofusColor={dofusColor} 
                                                                            variant="action"
                                                                        />
                                                                    </div>

                                                                    <Button 
                                                                        disabled={lock && !done}
                                                                        onClick={(e) => { 
                                                                            e.stopPropagation(); 
                                                                            if (lock && !done) return;
                                                                            if (!done) setSelectedQuestId(null); // Auto-collapse on validation
                                                                            onToggleStatus(entry.id, done ? "NOT_STARTED" : "COMPLETED"); 
                                                                        }}
                                                                        className={`w-full h-14 rounded-2xl font-black italic uppercase text-[14px] transition-all tracking-widest ${
                                                                            done ? "bg-zinc-900 border border-white/10 text-zinc-400" 
                                                                            : lock ? "bg-zinc-950 text-white/10 border border-white/5 cursor-not-allowed"
                                                                            : "bg-white text-black hover:bg-zinc-200 shadow-[0_0_30px_rgba(255,255,255,0.1)]"
                                                                        }`}
                                                                    >
                                                                        {done ? "Réinitialiser la progression" : lock ? "Quête Verrouillée" : "Valider l'étape de quête"}
                                                                    </Button>
                                                                    <div className="grid grid-cols-3 gap-4">
                                                                        <a href={`https://dofusdb.fr/fr/database/quest/${entry.dofusdbId || entry.id}`} target="_blank" className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-white/5 border border-white/5 hover:bg-indigo-500/10 hover:border-indigo-500/30 text-[10px] font-black text-zinc-500 hover:text-indigo-400 uppercase tracking-widest transition-all"><Target className="w-5 h-5" /> DofusDB</a>
                                                                        <a href={entry.externalRef || `https://www.google.com/search?q=site:dofuspourlesnoobs.com+${encodeURIComponent(entry.name)}`} target="_blank" className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-white/5 border border-white/5 hover:bg-amber-500/10 hover:border-amber-500/30 text-[10px] font-black text-zinc-500 hover:text-amber-400 uppercase tracking-widest transition-all"><BookOpen className="w-5 h-5" /> Noobs</a>
                                                                        <Button 
                                                                            variant="ghost" 
                                                                            onClick={(e) => {
                                                                                e.stopPropagation();
                                                                                if (entry.coords) copyWithToast(`/travel ${entry.coords.x} ${entry.coords.y}`);
                                                                            }} 
                                                                            className="flex flex-col items-center justify-center gap-2 h-20 rounded-2xl bg-white/5 border border-white/5 hover:bg-emerald-500/10 hover:border-emerald-500/30 p-0 text-[10px] font-black text-zinc-500 hover:text-emerald-400 uppercase tracking-widest transition-all"
                                                                        >
                                                                            <Copy className="w-5 h-5" /> Travel
                                                                        </Button>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </motion.div>
                                                    )}
                                                </AnimatePresence>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </ScrollArea>
                    </DialogContent>
                </Dialog>
            </div>
    );
}

"use client";

import React, { useState, useMemo } from "react";
import {
    CheckCircle2, Circle, MinusCircle, Users,
    ChevronLeft, ChevronRight, Filter, Layers, Trophy,
} from "lucide-react";
import type { GuildHeatmapData } from "@/server/actions/dofus-quest-actions";

interface GuildDofusHeatmapProps {
    data: GuildHeatmapData;
    dofusColor?: string;
    dofusName?: string;
}

const STATUS_STYLES: Record<string, { bg: string; text: string; icon: React.ElementType; label: string }> = {
    COMPLETED: { bg: "#22c55e", text: "#fff", icon: CheckCircle2, label: "Complété" },
    IN_PROGRESS: { bg: "#f59e0b", text: "#fff", icon: MinusCircle, label: "En cours" },
    NOT_STARTED: { bg: "transparent", text: "rgba(255,255,255,0.12)", icon: Circle, label: "À faire" },
};

const PAGE_SIZE = 8; // members per page
const COLS_PER_PAGE = 12; // entries per page

// Section type badges
const SECTION_COLORS: Record<string, string> = {
    PREREQUISITE: "#a78bfa",
    MAIN_CHAIN: "#34d399",
    RESOURCE_CHAIN: "#fb923c",
    OPTIONAL: "#6b7280",
};

export function GuildDofusHeatmap({ data, dofusColor = "#6366f1", dofusName = "Dofus" }: GuildDofusHeatmapProps) {
    const [memberPage, setMemberPage] = useState(0);
    const [colPage, setColPage] = useState(0);
    const [showOptional, setShowOptional] = useState(false);

    const { entries, members } = data;

    const visibleEntries = useMemo(
        () => entries.filter(e => showOptional || !e.isOptional),
        [entries, showOptional]
    );

    // Pagination
    const memberStart = memberPage * PAGE_SIZE;
    const visibleMembers = members.slice(memberStart, memberStart + PAGE_SIZE);
    const memberPageCount = Math.ceil(members.length / PAGE_SIZE);

    const colStart = colPage * COLS_PER_PAGE;
    const visibleCols = visibleEntries.slice(colStart, colStart + COLS_PER_PAGE);
    const colPageCount = Math.ceil(visibleEntries.length / COLS_PER_PAGE);

    // Overall guild progress
    const guildAvg = members.length > 0
        ? Math.round(members.reduce((s, m) => s + m.completionPercent, 0) / members.length)
        : 0;

    if (entries.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-16 gap-3">
                <Layers className="w-10 h-10 text-white/10" />
                <p className="text-white/25 text-sm font-bold uppercase tracking-widest">Aucune étape disponible</p>
                <p className="text-white/15 text-xs">Lance le seed pour charger les données.</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col gap-4">
            {/* Header */}
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                    <div
                        className="w-9 h-9 rounded-xl flex items-center justify-center"
                        style={{ background: `${dofusColor}18`, border: `1px solid ${dofusColor}33` }}
                    >
                        <Users className="w-4 h-4" style={{ color: dofusColor }} />
                    </div>
                    <div>
                        <h3 className="text-sm font-black text-white uppercase tracking-tight">Heatmap Guilde</h3>
                        <p className="text-[10px] text-white/30 uppercase tracking-widest font-bold">
                            {members.length} membres · {visibleEntries.length} étapes · moy. {guildAvg}%
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    {/* Show optional toggle */}
                    <button
                        onClick={() => setShowOptional(v => !v)}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-wider transition-all"
                        style={{
                            background: showOptional ? `${dofusColor}22` : "rgba(255,255,255,0.04)",
                            color: showOptional ? dofusColor : "rgba(255,255,255,0.35)",
                            border: `1px solid ${showOptional ? dofusColor + "44" : "rgba(255,255,255,0.08)"}`,
                        }}
                    >
                        <Filter className="w-3 h-3" />
                        Optionnelles
                    </button>
                    {/* Legend */}
                    <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg" style={{ background: "rgba(255,255,255,0.03)" }}>
                        {Object.entries(STATUS_STYLES).map(([k, v]) => (
                            <div key={k} className="flex items-center gap-1">
                                <div className="w-2 h-2 rounded-sm" style={{ background: v.bg || "rgba(255,255,255,0.08)" }} />
                                <span className="text-[9px] text-white/25 font-bold uppercase">{v.label}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Heatmap table */}
            <div
                className="rounded-2xl overflow-hidden"
                style={{ border: "1px solid rgba(255,255,255,0.06)", background: "rgba(0,0,0,0.2)" }}
            >
                {/* Column headers */}
                <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                        <thead>
                            <tr>
                                {/* Member column */}
                                <th className="sticky left-0 z-20 px-3 py-2 text-left min-w-[140px]"
                                    style={{ background: "rgba(0,0,0,0.4)", borderRight: "1px solid rgba(255,255,255,0.05)" }}>
                                    <div className="flex items-center justify-between">
                                        <span className="text-[9px] text-white/25 font-black uppercase tracking-widest">
                                            Membre
                                        </span>
                                        <Trophy className="w-3 h-3 text-white/15" />
                                    </div>
                                </th>
                                {/* Progress column */}
                                <th className="sticky left-[140px] z-20 px-2 py-2 min-w-[56px]"
                                    style={{ background: "rgba(0,0,0,0.4)", borderRight: "1px solid rgba(255,255,255,0.08)" }}>
                                    <span className="text-[9px] text-white/20 font-black uppercase tracking-widest">%</span>
                                </th>
                                {/* Step columns */}
                                {visibleCols.map((entry, i) => (
                                    <th
                                        key={entry.id}
                                        className="px-1 py-2 text-center min-w-[32px] w-8"
                                        style={{ borderLeft: "1px solid rgba(255,255,255,0.03)" }}
                                        title={`${entry.name} (${entry.sectionName})`}
                                    >
                                        <div className="flex flex-col items-center gap-0.5">
                                            <div
                                                className="w-1 h-1 rounded-full mx-auto"
                                                style={{ background: SECTION_COLORS[entry.sectionType] || dofusColor }}
                                            />
                                            <span className="text-[7px] text-white/20 font-bold tabular-nums">
                                                {colStart + i + 1}
                                            </span>
                                        </div>
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {visibleMembers.map((member) => (
                                <tr
                                    key={member.profileId}
                                    className="group/row transition-colors hover:bg-white/[0.02]"
                                    style={{ borderTop: "1px solid rgba(255,255,255,0.03)" }}
                                >
                                    {/* Member name */}
                                    <td
                                        className="sticky left-0 z-10 px-3 py-1.5"
                                        style={{ background: "rgba(10,10,12,0.85)", borderRight: "1px solid rgba(255,255,255,0.05)" }}
                                    >
                                        <div className="flex items-center gap-2">
                                            <div
                                                className="w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center overflow-hidden text-[8px] font-black"
                                                style={{ background: `${dofusColor}22`, color: dofusColor }}
                                            >
                                                {member.image
                                                    ? <img src={member.image} alt={member.pseudo} className="w-full h-full object-cover" />
                                                    : member.pseudo.charAt(0).toUpperCase()
                                                }
                                            </div>
                                            <span className="text-[11px] font-bold text-white/70 truncate max-w-[80px]">{member.pseudo}</span>
                                        </div>
                                    </td>
                                    {/* Progress bar */}
                                    <td
                                        className="sticky left-[140px] z-10 px-2 py-1.5 text-center"
                                        style={{ background: "rgba(10,10,12,0.85)", borderRight: "1px solid rgba(255,255,255,0.08)" }}
                                    >
                                        <span
                                            className="text-[10px] font-black tabular-nums"
                                            style={{ color: member.completionPercent > 0 ? dofusColor : "rgba(255,255,255,0.2)" }}
                                        >
                                            {member.completionPercent}%
                                        </span>
                                    </td>
                                    {/* Step cells */}
                                    {visibleCols.map((entry) => {
                                        const status = member.statusMap[entry.id] ?? "NOT_STARTED";
                                        const style = STATUS_STYLES[status] || STATUS_STYLES.NOT_STARTED;
                                        const Icon = style.icon;
                                        return (
                                            <td
                                                key={entry.id}
                                                className="text-center py-1.5 px-1"
                                                title={`${member.pseudo} — ${entry.name}: ${style.label}`}
                                                style={{ borderLeft: "1px solid rgba(255,255,255,0.03)" }}
                                            >
                                                <div className="flex items-center justify-center">
                                                    <div
                                                        className="w-7 h-7 rounded-md flex items-center justify-center transition-all duration-200 group-hover/row:scale-110 shadow-lg"
                                                        style={{
                                                            background: status === "COMPLETED"
                                                                ? `${style.bg}22`
                                                                : status === "IN_PROGRESS"
                                                                    ? `${style.bg}18`
                                                                    : "rgba(255,255,255,0.03)",
                                                            border: `1px solid ${status === "NOT_STARTED" ? "rgba(255,255,255,0.05)" : style.bg + "44"}`,
                                                        }}
                                                    >
                                                        <Icon
                                                            className="w-4 h-4"
                                                            style={{ color: status === "NOT_STARTED" ? "rgba(255,255,255,0.08)" : style.bg }}
                                                        />
                                                    </div>
                                                </div>
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                {/* Column pagination */}
                {colPageCount > 1 && (
                    <div
                        className="flex items-center justify-between px-4 py-2"
                        style={{ borderTop: "1px solid rgba(255,255,255,0.04)" }}
                    >
                        <div className="flex gap-1">
                            {Array.from({ length: colPageCount }).map((_, i) => (
                                <div
                                    key={i}
                                    className="h-1 rounded-full cursor-pointer transition-all"
                                    style={{
                                        width: colPage === i ? "24px" : "6px",
                                        background: colPage === i ? dofusColor : "rgba(255,255,255,0.1)",
                                    }}
                                    onClick={() => setColPage(i)}
                                />
                            ))}
                        </div>
                        <div className="flex items-center gap-1">
                            <button
                                onClick={() => setColPage(p => Math.max(0, p - 1))}
                                disabled={colPage === 0}
                                className="p-1 rounded-lg hover:bg-white/5 disabled:opacity-20 transition-all"
                            >
                                <ChevronLeft className="w-3.5 h-3.5 text-white/40" />
                            </button>
                            <span className="text-[9px] text-white/20 font-bold uppercase px-1">
                                Étapes {colStart + 1}–{Math.min(colStart + COLS_PER_PAGE, visibleEntries.length)} / {visibleEntries.length}
                            </span>
                            <button
                                onClick={() => setColPage(p => Math.min(colPageCount - 1, p + 1))}
                                disabled={colPage >= colPageCount - 1}
                                className="p-1 rounded-lg hover:bg-white/5 disabled:opacity-20 transition-all"
                            >
                                <ChevronRight className="w-3.5 h-3.5 text-white/40" />
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Member pagination */}
            {memberPageCount > 1 && (
                <div className="flex items-center justify-between">
                    <button
                        onClick={() => setMemberPage(p => Math.max(0, p - 1))}
                        disabled={memberPage === 0}
                        className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-bold text-white/40 hover:text-white/70 hover:bg-white/5 disabled:opacity-20 transition-all"
                    >
                        <ChevronLeft className="w-3.5 h-3.5" /> Précédent
                    </button>
                    <span className="text-[10px] text-white/20 font-bold uppercase tracking-widest">
                        {memberStart + 1}–{Math.min(memberStart + PAGE_SIZE, members.length)} / {members.length} membres
                    </span>
                    <button
                        onClick={() => setMemberPage(p => Math.min(memberPageCount - 1, p + 1))}
                        disabled={memberPage >= memberPageCount - 1}
                        className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-bold text-white/40 hover:text-white/70 hover:bg-white/5 disabled:opacity-20 transition-all"
                    >
                        Suivant <ChevronRight className="w-3.5 h-3.5" />
                    </button>
                </div>
            )}

            {/* Section legend */}
            <div className="flex flex-wrap gap-2 pt-1">
                {Object.entries(SECTION_COLORS).map(([type, color]) => (
                    <div key={type} className="flex items-center gap-1.5">
                        <div className="w-2 h-2 rounded-sm" style={{ background: color }} />
                        <span className="text-[9px] font-bold text-white/25 uppercase tracking-wider">
                            {type === "PREREQUISITE" ? "Prérequis" :
                             type === "MAIN_CHAIN" ? "Arc Principal" :
                             type === "RESOURCE_CHAIN" ? "Ressources" : "Optionnel"}
                        </span>
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";
 
import { useState, useMemo } from "react";
import { Trophy, Users, TrendingUp, Crown, Search, Filter } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import type { GuildDofusStats, MemberDofusSummary } from "@/server/actions/dofus-quest-actions";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
 
interface GuildDofusOverviewProps {
    stats: GuildDofusStats[];
    topMembers: MemberDofusSummary[];
    totalMembers: number;
    guildId?: string;
}
 
export function GuildDofusOverview({ stats, topMembers, totalMembers }: GuildDofusOverviewProps) {
    const [search, setSearch] = useState("");
    const [categoryFilter, setCategoryFilter] = useState("Tous");
 
    // Get unique filter categories from stats
    const categories = useMemo(() => {
        const cats = new Set<string>();
        cats.add("Tous");
        stats.forEach(s => {
            // We use rarity or filterCategory if available. 
            // Since DofusItem has filterCategory, let's assume it's passed or use rarity as fallback.
            const cat = (s as any).filterCategory || "Autres";
            cats.add(cat);
        });
        return Array.from(cats);
    }, [stats]);
 
    const filteredStats = useMemo(() => {
        return stats.filter(s => {
            const matchesSearch = s.nameShort.toLowerCase().includes(search.toLowerCase()) || 
                                 s.name.toLowerCase().includes(search.toLowerCase());
            const matchesCat = categoryFilter === "Tous" || (s as any).filterCategory === categoryFilter;
            return matchesSearch && matchesCat;
        });
    }, [stats, search, categoryFilter]);
 
    return (
        <div className="flex flex-col gap-12 pt-4">
            {/* ── 👤 MEMBRES : CLASSEMENT DOFUS ── */}
            <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 items-start">
                
                {/* 🏆 TABLE D'HONNEUR */}
                <div className="xl:col-span-4 flex flex-col gap-4">
                    <div className="flex items-center gap-3 px-4">
                        <Trophy className="w-5 h-5 text-amber-500" />
                        <h3 className="text-base font-black text-white italic uppercase tracking-tighter">
                            Table d'Honneur
                        </h3>
                        <div className="h-px flex-1 bg-white/5" />
                        <span className="text-[10px] text-white/30 font-black uppercase tracking-widest flex items-center gap-2">
                            <Users className="w-3.5 h-3.5" />
                            {totalMembers} Actifs
                        </span>
                    </div>
 
                    <div className="flex flex-col gap-2.5">
                        {topMembers.slice(0, 10).map((member, index) => (
                            <motion.div
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: index * 0.05 }}
                                key={member.profileId}
                                className="group/member flex items-center gap-3 px-4 py-3 rounded-2xl bg-zinc-950/40 border border-white/5 hover:bg-white/[0.03] hover:border-white/10 transition-all duration-300"
                            >
                                <div className="w-6 flex-shrink-0 flex items-center justify-center">
                                    {index === 0 ? (
                                        <Crown className="w-5 h-5 text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.3)]" />
                                    ) : (
                                        <span className={`text-sm font-black italic tabular-nums ${index < 3 ? "text-white/60" : "text-white/20"}`}>
                                            #{index + 1}
                                        </span>
                                    )}
                                </div>
 
                                <div className="w-8 h-8 rounded-lg bg-orange-500/10 border border-orange-500/20 flex items-center justify-center flex-shrink-0 overflow-hidden">
                                    {member.image ? (
                                        <img src={member.image} alt={member.pseudo} />
                                    ) : (
                                        <span className="text-xs font-black text-orange-400 italic">{member.pseudo.charAt(0).toUpperCase()}</span>
                                    )}
                                </div>
 
                                <div className="flex-1 min-w-0">
                                    <p className="text-[11px] font-black text-white italic uppercase truncate tracking-tight">{member.pseudo}</p>
                                    <div className="flex flex-wrap gap-0.5 mt-1">
                                        {member.dofusList
                                            .filter((d) => d.isObtained)
                                            .slice(0, 12)
                                            .map((d) => (
                                                <div
                                                    key={d.slug}
                                                    className="w-1.5 h-1.5 rounded-full ring-1 ring-white/10"
                                                    style={{ backgroundColor: d.color || "#6366f1" }}
                                                    title={d.name}
                                                />
                                            ))}
                                    </div>
                                </div>
 
                                <div className="text-right flex-shrink-0">
                                    <div className="flex items-baseline gap-0.5">
                                        <span className={`text-base font-black italic tabular-nums ${index === 0 ? "text-amber-400" : "text-white/80"}`}>
                                            {member.dofusObtained}
                                        </span>
                                        <span className="text-[8px] text-white/30 font-black">/{member.dofusTotal}</span>
                                    </div>
                                </div>
                            </motion.div>
                        ))}
                    </div>
                </div>
 
                {/* ⚔️ PROGRESSION DES DOFUS */}
                <div className="xl:col-span-8 flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 px-4">
                        <div className="flex items-center gap-3">
                            <TrendingUp className="w-5 h-5 text-indigo-400" />
                            <h3 className="text-base font-black text-white italic uppercase tracking-tighter">
                                Progression Guilde
                            </h3>
                        </div>
 
                        <div className="flex items-center gap-3">
                            {/* Search */}
                            <div className="relative">
                                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-white/30" />
                                <input
                                    type="text"
                                    placeholder="Chercher Dofus..."
                                    value={search}
                                    onChange={(e) => setSearch(e.target.value)}
                                    className="pl-8 pr-3 py-1.5 text-[10px] font-bold uppercase tracking-widest bg-black/40 border border-white/10 rounded-xl text-white placeholder:text-white/20 focus:outline-none focus:border-white/30 transition-all min-w-[150px]"
                                />
                            </div>
 
                            {/* Category Filter */}
                            <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                                <SelectTrigger className="w-[140px] h-8 bg-black/40 border-white/10 text-[10px] font-bold uppercase tracking-widest rounded-xl">
                                    <SelectValue placeholder="Catégorie" />
                                </SelectTrigger>
                                <SelectContent className="bg-zinc-950 border-white/10 text-white rounded-xl shadow-2xl">
                                    {categories.map(cat => (
                                        <SelectItem key={cat} value={cat} className="text-[10px] font-bold uppercase tracking-wider focus:bg-white/10 focus:text-white cursor-pointer">
                                            {cat}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </div>
 
                    <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-3">
                        <AnimatePresence mode="popLayout">
                            {filteredStats.map((s) => (
                                <DofusGuildProgressCard key={s.dofusId} stat={s} />
                            ))}
                        </AnimatePresence>
                        
                        {filteredStats.length === 0 && (
                            <div className="col-span-full py-20 text-center">
                                <p className="text-white/20 font-black uppercase tracking-[0.3em] text-[10px]">Aucun Dofus trouvé</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
 
function DofusGuildProgressCard({ stat }: { stat: GuildDofusStats }) {
    const [isExpanded, setIsExpanded] = useState(false);
 
    return (
        <motion.div 
            layout
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className={`flex flex-col rounded-2xl border transition-all duration-300 overflow-hidden ${
                isExpanded ? "bg-zinc-900/80 border-white/30 shadow-2xl z-10" : "bg-zinc-950/40 border-white/5 hover:border-white/10"
            }`}
        >
            <div 
                className="p-3 flex items-center gap-3 cursor-pointer"
                onClick={() => setIsExpanded(!isExpanded)}
            >
                <div className="w-10 h-10 bg-black/60 rounded-xl border border-white/10 flex items-center justify-center flex-shrink-0 p-1 shadow-lg">
                    {stat.imageUrl ? (
                        <img src={stat.imageUrl} alt={stat.nameShort} className="w-full h-full object-contain" />
                    ) : (
                        <div className="w-full h-full rounded-lg" style={{ background: stat.color || "#6366f1" }} />
                    )}
                </div>
 
                <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-1">
                        <span className="text-[11px] font-black text-white italic uppercase tracking-wider truncate">{stat.nameShort}</span>
                        <div className="flex items-baseline gap-0.5">
                            <span className="text-[10px] font-black text-white italic tabular-nums">{stat.obtainedCount}</span>
                            <span className="text-[8px] text-white/30 font-black">/{stat.totalMembers}</span>
                        </div>
                    </div>
                    <div className="h-1 rounded-full bg-white/5 overflow-hidden">
                        <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${stat.obtainedPercent}%` }}
                            className="h-full rounded-full"
                            style={{
                                background: stat.color || "#6366f1",
                            }}
                        />
                    </div>
                </div>
 
                <div className="text-right flex-shrink-0">
                    <span className="text-[10px] font-black text-white italic tabular-nums">{stat.obtainedPercent}%</span>
                </div>
            </div>
 
            {isExpanded && (
                <div className="px-3 pb-3 border-t border-white/5 bg-black/20">
                    <div className="mt-3 space-y-2">
                        <div className="flex items-center justify-between mb-2">
                            <p className="text-[8px] font-black uppercase tracking-[0.2em] text-white/20">Membres et avancée</p>
                            <span className="text-[8px] font-black text-indigo-400/60 uppercase tracking-widest">Moy. {stat.avgPercent}%</span>
                        </div>
                        <div className="max-h-48 overflow-y-auto pr-1 custom-scrollbar space-y-1.5">
                            {stat.membersProgress.map((member) => (
                                <div key={member.profileId} className="flex items-center gap-2 p-1.5 rounded-lg bg-white/[0.02] border border-white/5">
                                    <div className="w-6 h-6 rounded-md overflow-hidden bg-zinc-800 flex-shrink-0 border border-white/5">
                                        {member.image ? <img src={member.image} alt={member.pseudo} /> : <span className="text-[8px] flex items-center justify-center h-full font-black uppercase text-white/40">{member.pseudo[0]}</span>}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center justify-between">
                                            <span className="text-[9px] font-bold text-white/70 truncate">{member.pseudo}</span>
                                            <span className={`text-[9px] font-black ${member.isObtained ? "text-emerald-400" : "text-white/40"}`}>{member.percent}%</span>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </motion.div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { Navigation, ChevronRight, Check, CheckCircle2, Circle, Sparkles, Users, Calendar, MapPin, Sword, Package, Info } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { getOptimizedGuideDetail, getGuildOptimizedGuideProgress } from "@/server/actions/optimized-guide-actions";
import { toast } from "sonner";
import { useSession } from "next-auth/react";

interface OptimizedGuideTabProps {
    initialGuides: any[];
    guildId: string;
}

export function OptimizedGuideTab({ initialGuides, guildId }: OptimizedGuideTabProps) {
    const { data: session } = useSession();
    const [selectedGuideSlug, setSelectedGuideSlug] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [guideData, setGuideData] = useState<any>(null);
    const [questsDetail, setQuestsDetail] = useState<any[]>([]);
    const [memberProgress, setMemberProgress] = useState<any[]>([]);
    const [selectedStepIndex, setSelectedStepIndex] = useState(0);

    const handleSelectGuide = async (slug: string) => {
        setSelectedGuideSlug(slug);
        setLoading(true);
        try {
            const [detailRes, progressRes] = await Promise.all([
                getOptimizedGuideDetail(slug, guildId),
                getGuildOptimizedGuideProgress(slug, guildId)
            ]);

            if (detailRes.success && detailRes.guide) {
                setGuideData(detailRes.guide);
                setQuestsDetail(detailRes.questsDetail || []);
                setSelectedStepIndex(0);
            }
            
            if (progressRes.success) {
                setMemberProgress(progressRes.memberProgress || []);
            }
        } catch (e) {
            toast.error("Erreur lors de la récupération du guide");
        } finally {
            setLoading(false);
        }
    };

    // Helper to get quest info
    const getQuestInfo = (id: string) => questsDetail.find(q => q.id === id);

    // Determines if a step is completed for the current user
    const isStepCompleted = (step: any) => {
        const objectives = step.objectives as any[] || [];
        const questIds = step.questIds || [];
        
        // Check quests
        const allQuestIds = [...new Set([...questIds, ...objectives.filter(o => o.type === 'QUEST').map(o => o.id)])];
        if (allQuestIds.length === 0) return true;

        return allQuestIds.every(qid => {
            const q = getQuestInfo(qid);
            return q?.playerProgress?.length > 0 && q.playerProgress[0].status === "COMPLETED";
        });
    };

    if (selectedGuideSlug && guideData) {
        // --- DETAIL VIEW ---
        const totalSteps = guideData.steps.length;
        const completedSteps = guideData.steps.filter((s: any) => isStepCompleted(s)).length;
        const progressPercent = totalSteps > 0 ? (completedSteps / totalSteps) * 100 : 0;

        return (
            <div className="flex flex-col gap-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
                {/* Header / Back */}
                <div className="flex items-center justify-between">
                    <button 
                        onClick={() => setSelectedGuideSlug(null)}
                        className="flex items-center gap-2 text-zinc-500 hover:text-white transition-colors group"
                    >
                        <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-white/10">
                             <ChevronRight className="w-4 h-4 rotate-180" />
                        </div>
                        <span className="text-sm font-bold uppercase tracking-widest">Retour aux guides</span>
                    </button>

                    <div className="flex items-center gap-4">
                        <div className="hidden md:flex flex-col items-end">
                            <span className="text-[10px] font-black uppercase text-zinc-500 tracking-tighter">Votre progression</span>
                            <span className="text-sm font-bold text-emerald-400">{completedSteps} / {totalSteps} Étapes</span>
                        </div>
                        <div className="w-32 h-2 bg-zinc-800 rounded-full overflow-hidden">
                            <motion.div 
                                initial={{ width: 0 }}
                                animate={{ width: `${progressPercent}%` }}
                                className="h-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]"
                            />
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
                    
                    {/* Left: The Roadmap (4 columns) */}
                    <div className="lg:col-span-5 space-y-6">
                        <div className="bg-zinc-900/50 border border-white/5 rounded-3xl p-6 relative overflow-hidden">
                             <div className="absolute top-0 right-0 p-8 opacity-5">
                                <Navigation className="w-32 h-32 rotate-12" />
                             </div>

                             <h2 className="text-3xl font-black text-white mb-2">{guideData.name}</h2>
                             <p className="text-zinc-500 text-sm leading-relaxed mb-8">{guideData.description || "Suivez cet itinéraire pour optimiser votre progression."}</p>

                             <div className="relative pl-8 space-y-12 pb-4">
                                {/* Vertical Line */}
                                <div className="absolute top-2 bottom-2 left-3 w-0.5 bg-zinc-800">
                                     <motion.div 
                                        initial={{ height: 0 }}
                                        animate={{ height: `${progressPercent}%` }}
                                        className="w-full bg-emerald-500"
                                     />
                                </div>

                                {guideData.steps.map((step: any, idx: number) => {
                                    const isDone = isStepCompleted(step);
                                    const active = selectedStepIndex === idx;
                                    const membersHere = memberProgress.filter(mp => mp.currentStepIndex === idx && !mp.isFinished);

                                    return (
                                        <div 
                                            key={step.id} 
                                            onClick={() => setSelectedStepIndex(idx)}
                                            className={`relative z-10 flex items-start gap-6 cursor-pointer group transition-all duration-300 ${active ? 'scale-105' : 'opacity-60 hover:opacity-100'}`}
                                        >
                                            {/* Node */}
                                            <div className={`w-6 h-6 rounded-full flex items-center justify-center transition-all duration-500 border-2 
                                                ${isDone ? 'bg-emerald-500 border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.4)]' : 'bg-zinc-900 border-zinc-700 group-hover:border-zinc-500'}
                                                ${active && !isDone ? 'ring-4 ring-emerald-500/20 border-emerald-500' : ''}`}>
                                                {isDone ? <Check className="w-3 h-3 text-emerald-950 font-black" /> : null}
                                            </div>

                                            <div className="flex-1">
                                                <div className="flex items-center gap-2">
                                                    <span className={`text-xs font-black uppercase tracking-widest ${isDone ? 'text-emerald-500' : 'text-zinc-500'}`}>Étape {idx + 1}</span>
                                                    {membersHere.length > 0 && (
                                                        <div className="flex -space-x-2 ml-2">
                                                            {membersHere.slice(0, 3).map((mp, i) => (
                                                                <Avatar key={mp.profile.id} className="w-5 h-5 border border-zinc-900 shadow-md">
                                                                    <AvatarImage src={mp.profile.user?.image} />
                                                                    <AvatarFallback>{mp.profile.user?.name?.[0]}</AvatarFallback>
                                                                </Avatar>
                                                            ))}
                                                            {membersHere.length > 3 && (
                                                                <div className="w-5 h-5 rounded-full bg-zinc-800 text-[8px] font-bold flex items-center justify-center border border-zinc-900 text-white">+{membersHere.length - 3}</div>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>
                                                <h3 className={`font-bold transition-colors ${active ? 'text-white' : 'text-zinc-300'}`}>{step.title}</h3>
                                            </div>
                                        </div>
                                    );
                                })}
                             </div>
                        </div>
                    </div>

                    {/* Right: Step Detail (7 columns) */}
                    <div className="lg:col-span-7">
                        <AnimatePresence mode="wait">
                            <motion.div 
                                key={selectedStepIndex}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="bg-gradient-to-br from-zinc-900 to-black border border-white/10 rounded-[2rem] p-8 shadow-2xl relative overflow-hidden min-h-[500px]"
                            >
                                <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                                    <Sparkles className="w-64 h-64 text-emerald-500" />
                                </div>

                                {guideData.steps[selectedStepIndex] ? (
                                    <div className="relative z-10 space-y-8">
                                        <div>
                                            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] mb-4">
                                                Détails de l'objectif
                                            </div>
                                            <h3 className="text-4xl font-black text-white leading-tight mb-4">{guideData.steps[selectedStepIndex].title}</h3>
                                            <p className="text-zinc-400 leading-relaxed text-lg">{guideData.steps[selectedStepIndex].description || "Terminez les objectifs suivants pour passer à l'étape suivante."}</p>
                                        </div>

                                        <div className="space-y-4">
                                            {/* Merged Objectives List */}
                                            {(() => {
                                                const step = guideData.steps[selectedStepIndex];
                                                const objectives = step.objectives as any[] || [];
                                                // Handle legacy questIds if not migrated yet
                                                const legacyQuests = (step.questIds || []).filter((id:string) => !objectives.find(o => o.id === id)).map((id:string) => ({ id, type: 'QUEST' }));
                                                const items = [...objectives, ...legacyQuests];

                                                if (items.length === 0) return (
                                                    <div className="py-12 border-2 border-dashed border-white/5 rounded-3xl flex flex-col items-center justify-center text-zinc-600 italic">
                                                        Aucun objectif spécifique pour cette étape.
                                                    </div>
                                                );

                                                return items.map((obj, i) => {
                                                    const isQuest = obj.type === 'QUEST';
                                                    const isDungeon = obj.type === 'DUNGEON';
                                                    const isResource = obj.type === 'RESOURCE';
                                                    
                                                    let name = obj.name;
                                                    let isDone = false;
                                                    let subtitle = "";
                                                    let img = obj.imageUrl;

                                                    if (isQuest) {
                                                        const info = getQuestInfo(obj.id);
                                                        name = info?.name || obj.name || "Quête inconnue";
                                                        isDone = info?.playerProgress?.[0]?.status === "COMPLETED";
                                                        subtitle = info?.chain?.dofus?.name || "Catégorie Quête";
                                                        img = img || info?.chain?.dofus?.localImageUrl || info?.chain?.dofus?.imageUrl;
                                                    } else {
                                                        // Manual completion for others for now, unless we check boss kills later
                                                        subtitle = obj.type === 'DUNGEON' ? 'Donjon' : obj.type === 'RESOURCE' ? `Ressource (${obj.quantity || 1}x)` : 'Objectif';
                                                    }

                                                    return (
                                                        <div 
                                                            key={i} 
                                                            className={`group p-5 rounded-2xl border transition-all flex items-center justify-between ${isDone ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-black/40 border-white/5 hover:border-white/20'}`}
                                                        >
                                                            <div className="flex items-center gap-4">
                                                                <div className={`w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0 border ${isDone ? 'bg-emerald-500/20 border-emerald-500/30' : 'bg-zinc-800/50 border-white/5'}`}>
                                                                    {img ? (
                                                                        <img src={img} alt="" className="w-8 h-8 object-contain" />
                                                                    ) : (
                                                                        isDungeon ? <Sword className="w-6 h-6 text-indigo-400" /> : <Package className="w-6 h-6 text-amber-400" />
                                                                    )}
                                                                </div>
                                                                <div>
                                                                    <div className={`text-[10px] uppercase font-black tracking-widest ${isDone ? 'text-emerald-500' : 'text-zinc-500'}`}>{subtitle}</div>
                                                                    <div className={`font-bold text-lg ${isDone ? 'text-emerald-400' : 'text-zinc-200'}`}>{name}</div>
                                                                </div>
                                                            </div>

                                                            <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${isDone ? 'bg-emerald-500 text-emerald-950' : 'bg-white/5 text-zinc-600'}`}>
                                                                {isDone ? <CheckCircle2 className="w-6 h-6" /> : <Circle className="w-6 h-6 opacity-40" />}
                                                            </div>
                                                        </div>
                                                    );
                                                });
                                            })()}
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex items-center justify-center h-full text-zinc-500">Sélectionnez une étape pour voir les détails.</div>
                                )}
                            </motion.div>
                        </AnimatePresence>
                    </div>

                </div>
            </div>
        );
    }

    // --- LIST VIEW ---
    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {initialGuides.map((guide) => (
                <div 
                    key={guide.id} 
                    onClick={() => handleSelectGuide(guide.slug)}
                    className="group relative bg-zinc-900 border border-white/5 rounded-[2.5rem] p-8 cursor-pointer hover:border-emerald-500/30 transition-all duration-500 hover:shadow-[0_20px_50px_rgba(0,0,0,0.5)] overflow-hidden"
                >
                    {/* Background Glow */}
                    <div className="absolute -top-24 -right-24 w-48 h-48 bg-emerald-500/10 blur-[80px] group-hover:bg-emerald-500/20 transition-all" />
                    
                    <div className="relative z-10 flex flex-col h-full">
                        <div className="w-14 h-14 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                             <Navigation className="w-8 h-8 text-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)]" />
                        </div>

                        <h3 className="text-2xl font-black text-white mb-2 group-hover:text-emerald-400 transition-colors uppercase tracking-tight">
                            {guide.name}
                        </h3>
                        <p className="text-zinc-500 text-sm line-clamp-2 mb-8 h-10">
                            {guide.description || "Un itinéraire complet et optimisé pour atteindre vos objectifs."}
                        </p>

                        <div className="mt-auto flex items-center justify-between">
                            <div className="flex items-center gap-4">
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest leading-none mb-1">Étapes</span>
                                    <span className="text-lg font-black text-white">{guide.steps?.length || 0}</span>
                                </div>
                                <div className="w-[1px] h-8 bg-white/5" />
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest leading-none mb-1">Type</span>
                                    <span className="text-lg font-black text-white">Route Opti</span>
                                </div>
                            </div>

                            <div className="w-12 h-12 rounded-full border border-white/10 flex items-center justify-center group-hover:bg-white/10 transition-all group-hover:translate-x-1">
                                <ChevronRight className="w-6 h-6 text-zinc-400" />
                            </div>
                        </div>
                    </div>
                </div>
            ))}

            {initialGuides.length === 0 && (
                <div className="col-span-full py-20 bg-white/5 border border-dashed border-white/10 rounded-[3rem] text-center flex flex-col items-center justify-center">
                    <Navigation className="w-12 h-12 text-zinc-600 mb-4 opacity-20" />
                    <h3 className="text-xl font-bold text-white/50">Aucun guide configuré</h3>
                    <p className="text-zinc-600 text-sm max-w-xs">Les administrateurs n'ont pas encore publié de routes optimisées.</p>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useTransition, useMemo, useCallback } from "react";
import { CheckCircle2, Circle, ChevronDown, ChevronUp, Swords, Star, Briefcase, Wand2, ListChecks, Shield, AlertCircle, MapPin, Lock, Copy, BookOpen, Users, Target, Navigation } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { toggleQuestStatus, getOtherMembersOnQuest, type MemberOnQuest } from "@/server/actions/dofus-quest-actions";
import type { DofusChainWithProgress, DofusEntryWithProgress } from "@/server/actions/dofus-quest-actions";
import { DofusQuestStatus } from "@prisma/client";
import { NpcName, ItemInline, ParsedObjective, copyWithToast, detectRealDungeons, extractObjectiveText } from "./dofus-resolvers";
import { QuestGuildStatus } from "./QuestGuildStatus";

// ─── Icons per quest type ────────────────────────────────────────────────────
function QuestTypeIcon({ type, className }: { type: string; className?: string }) {
    const cls = className || "w-3.5 h-3.5";
    switch (type) {
        case "DUNGEON":     return <Swords className={cls} />;
        case "ACHIEVEMENT": return <Star className={cls} />;
        case "JOB":         return <Briefcase className={cls} />;
        case "SPELL":       return <Wand2 className={cls} />;
        case "REQUIREMENT": return <AlertCircle className={cls} />;
        default:            return <ListChecks className={cls} />;
    }
}

// ─── Section type label ────────────────────────────────────────────────────────
function SectionBadge({ type }: { type: string }) {
    const map: Record<string, { label: string; color: string }> = {
        PREREQUISITE:  { label: "Prérequis",    color: "#f59e0b" },
        MAIN_CHAIN:    { label: "Les quêtes",   color: "#6366f1" },
        OPTIONAL:      { label: "Optionnel",    color: "#6b7280" },
    };
    const cfg = map[type] || { label: type, color: "#6b7280" };
    return (
        <span
            className="text-[10px] font-semibold uppercase tracking-wider px-2 py-0.5 rounded-full"
            style={{ background: `${cfg.color}22`, color: cfg.color, border: `1px solid ${cfg.color}44` }}
        >
            {cfg.label}
        </span>
    );
}

// ─── Single quest entry row ──────────────────────────────────────────────────
function QuestEntryRow({
    entry,
    guildId,
    dofusColor,
    completedIds,   // ← reactive set from the parent (includes local toggles)
    onToggle,       // ← callback to notify parent of status change
}: {
    entry: DofusEntryWithProgress;
    guildId: string;
    dofusColor: string;
    completedIds: Set<string>;
    onToggle: (id: string, newStatus: DofusQuestStatus) => void;
}) {
    // Mirror the initial status — parent drives it via completedIds
    const isCompleted = completedIds.has(entry.id);
    const [isPending, startTransition] = useTransition();
    const [showDetail, setShowDetail] = useState(false);

    // Lock if any QUEST requirement is not yet in completedIds
    const isLocked = useMemo(() => {
        const reqs = Array.isArray(entry.requirements) ? entry.requirements : [];
        if (reqs.length === 0) return false;
        return reqs.some((req: any) => {
            if (!req || typeof req !== "object" || req.type !== "QUEST") return false;
            const rid = req.id || req.dofusdbId;
            return !completedIds.has(String(rid));
        });
    }, [entry.requirements, completedIds]);

    // V3 structured dungeons
    const structuredDungeons: { id?: string; name: string; bossName?: string; level?: number; img?: string; idoleName?: string }[] =
        useMemo(() => (entry as any).dungeonsRequired ?? [], [entry]);

    // Fallback: text-parsed dungeons
    const dungeonInfos = useMemo(() => detectRealDungeons((entry as any).objectives ?? []), [entry]);
    const hasDungeons = structuredDungeons.length > 0 || dungeonInfos.length > 0;

    function handleToggle() {
        if (isLocked && !isCompleted) return;
        const newStatus: DofusQuestStatus = isCompleted ? "NOT_STARTED" : "COMPLETED";
        
        // Auto-collapse detail on completion
        if (newStatus === "COMPLETED") setShowDetail(false);
        
        // Optimistic: notify parent immediately so completedIds updates for siblings
        onToggle(entry.id, newStatus);
        startTransition(async () => {
            const res = await toggleQuestStatus(guildId, entry.id, newStatus);
            // On failure, revert
            if (!res.success) onToggle(entry.id, isCompleted ? "COMPLETED" : "NOT_STARTED");
        });
    }

    return (
        <div
            className={`group flex flex-col rounded-2xl transition-all duration-300 border ${
                isCompleted ? "bg-[#10b98108] border-[#10b98125]" : "bg-[#ffffff03] border-white/5 hover:border-white/10"
            } ${entry.isOptional ? "opacity-60" : ""} ${isPending ? "opacity-50 pointer-events-none" : ""}`}
        >
            {/* ── Header row ── */}
            <div
                className="flex items-center gap-3 px-4 py-3 cursor-pointer select-none"
                onClick={() => setShowDetail(!showDetail)}
            >
                {/* Checkbox */}
                <button
                    disabled={isPending || (!!isLocked && !isCompleted)}
                    onClick={(e) => { e.stopPropagation(); handleToggle(); }}
                    className={`flex-shrink-0 transition-all duration-150 z-10 ${
                        isLocked && !isCompleted ? "cursor-not-allowed opacity-20 grayscale" : "hover:scale-110"
                    }`}
                >
                    {isCompleted ? (
                        <CheckCircle2 className="w-5 h-5" style={{ color: dofusColor, filter: `drop-shadow(0 0 8px ${dofusColor}44)` }} />
                    ) : isLocked ? (
                        <Lock className="w-5 h-5 text-zinc-700" />
                    ) : (
                        <Circle className="w-5 h-5 text-white/10 group-hover:text-white/30 transition-colors" />
                    )}
                </button>

                {/* Type icon */}
                <span className={`flex-shrink-0 ${isCompleted ? "" : "text-white/20"}`} style={{ color: isCompleted ? dofusColor : undefined }}>
                    <QuestTypeIcon type={entry.questType} />
                </span>

                {/* Name */}
                <div className="flex-1 min-w-0">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-x-2">
                        <span className={`text-[14px] font-black italic tracking-tight transition-colors ${
                            isCompleted ? "text-white/30 line-through" : "text-white"
                        }`}>
                            {entry.name}
                        </span>
                        <div className="flex items-center gap-2">
                            {entry.zone && <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">{entry.zone}</span>}
                            {(entry as any).level != null && <span className="text-[10px] text-zinc-600 font-medium">Lvl {(entry as any).level}</span>}
                        </div>
                    </div>
                </div>

                {/* Badges */}
                <div className="flex items-center gap-2 flex-shrink-0">
                    {hasDungeons && <span className="text-[9px] text-rose-400/80 font-black uppercase">🏰 DJ</span>}
                    {entry.isLast && (
                        <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md" style={{ background: `${dofusColor}20`, color: dofusColor }}>
                            🎯 Final
                        </span>
                    )}
                    <div className={`text-white/10 group-hover:text-white/40 transition-all ${showDetail ? "rotate-180" : ""}`}>
                        <ChevronDown className="w-4 h-4" />
                    </div>
                </div>
            </div>

            {/* ── Expanded detail ── */}
            <AnimatePresence>
                {showDetail && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="overflow-hidden"
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div className="px-5 pb-5 pt-2 ml-[10px] sm:ml-[42px] border-l border-white/5 space-y-4">

                            {/* V3 Structured Dungeons */}
                            {structuredDungeons.map((d, dx) => (
                                <div key={`sd-${dx}`} className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3">
                                    <div className="w-12 h-12 rounded-xl bg-black/60 border border-rose-500/20 flex items-center justify-center p-1 shrink-0 overflow-hidden">
                                        {d.img ? (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img src={d.img} alt={d.name} className="w-full h-full object-contain" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                        ) : d.id ? (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img src={`https://api.dofusdb.fr/img/monsters/${d.id}.png`} alt={d.name} className="w-full h-full object-contain" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                        ) : (
                                            <span className="text-rose-400">🏰</span>
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="text-[9px] font-black text-rose-400 uppercase tracking-widest mb-0.5">🏰 Donjon requis</div>
                                        <div className="text-[13px] font-black text-white italic truncate">{d.name}</div>
                                        <div className="flex items-center gap-2 mt-0.5">
                                            {d.level && d.level > 0 && <span className="text-[9px] text-zinc-500 font-bold">Lvl {d.level}</span>}
                                            {d.bossName && <span className="text-[9px] text-zinc-600 italic">— {d.bossName}</span>}
                                            {d.idoleName && <span className="text-[8px] font-black text-amber-500 bg-amber-500/10 px-1 py-0.5 rounded">{d.idoleName}</span>}
                                        </div>
                                    </div>
                                    {(d as any).dplnUrl && (
                                        <Button
                                            asChild
                                            variant="sigil"
                                            className="h-10 px-4"
                                            onClick={(e) => e.stopPropagation()}
                                        >
                                            <a href={(d as any).dplnUrl} target="_blank" rel="noopener noreferrer">
                                                <BookOpen className="w-4 h-4 mr-2" />
                                                <span className="text-[10px] font-black uppercase tracking-widest">Stratégie</span>
                                            </a>
                                        </Button>
                                    )}
                                </div>
                            ))}

                            {/* Fallback text-parsed dungeons */}
                            {structuredDungeons.length === 0 && dungeonInfos.map((di, dx) => (
                                <div key={`di-${dx}`} className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3">
                                    {di.mapImg && (
                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img src={di.mapImg} alt={di.dungeonName} className="w-12 h-12 object-cover rounded-xl border border-rose-500/30" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                    )}
                                    <div className="flex-1">
                                        <div className="text-[9px] font-black text-rose-400 uppercase tracking-widest mb-0.5">🏰 Donjon</div>
                                        <div className="text-[13px] font-black text-white italic">{di.dungeonName}</div>
                                    </div>
                                    {di.x !== undefined && (
                                        <Link href={`/dashboard/${guildId}/worldmap?x=${di.x}&y=${di.y}&zoom=4&world=${di.worldId ?? 0}`}
                                            className="h-8 w-8 rounded-xl bg-rose-500 text-black flex items-center justify-center hover:scale-110 transition-transform flex-shrink-0"
                                            onClick={(e) => e.stopPropagation()}>
                                            <MapPin className="w-4 h-4" />
                                        </Link>
                                    )}
                                </div>
                            ))}

                            {/* NPC GPS */}
                            {(entry as any).coords && (
                                <div className="p-3 bg-zinc-900/50 rounded-2xl border border-white/5 flex items-center justify-between hover:bg-zinc-900 transition-all">
                                    <div className="flex items-center gap-3 cursor-pointer group/travel"
                                        onClick={(e) => { e.stopPropagation(); copyWithToast(`/travel ${(entry as any).coords.x} ${(entry as any).coords.y}`); }}>
                                        <div className="w-8 h-8 rounded-xl bg-indigo-500/10 flex items-center justify-center text-indigo-400">
                                            <Wand2 className="w-4 h-4" />
                                        </div>
                                        <div>
                                            <div className="text-[9px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-1.5">
                                                PNJ OBJECTIF
                                                <span className="text-[8px] bg-white/5 px-1 py-0.5 rounded opacity-0 group-hover/travel:opacity-100 transition-opacity flex items-center gap-0.5">
                                                    <Copy className="w-2.5 h-2.5" /> COPIER
                                                </span>
                                            </div>
                                            <div className="text-[12px] font-bold text-white italic group-hover/travel:text-emerald-400 transition-colors">
                                                {(() => {
                                                    const objectives = Array.isArray((entry as any).objectives) ? (entry as any).objectives : [];
                                                    const objWithNpc = objectives.find((o: any) => extractObjectiveText(o).includes("{npc,"));
                                                    const match = extractObjectiveText(objWithNpc).match(/\{npc,(\d+)\}/);
                                                    return match ? <NpcName npcId={match[1]} /> : ((entry as any).npcName || "PNJ");
                                                })()} <span className="text-zinc-500 font-normal">[{(entry as any).coords.x}, {(entry as any).coords.y}]</span>
                                            </div>
                                        </div>
                                    </div>
                                    <Link
                                        href={`/dashboard/${guildId}/worldmap?x=${(entry as any).coords.x}&y=${(entry as any).coords.y}&zoom=4&world=${(entry as any).coords.worldId ?? 0}`}
                                        className="h-8 w-8 rounded-lg bg-emerald-500 text-black flex items-center justify-center hover:scale-110 transition-transform shadow-[0_0_15px_rgba(16,185,129,0.3)]"
                                        onClick={(e) => e.stopPropagation()}
                                    >
                                        <MapPin className="w-4 h-4" />
                                    </Link>
                                </div>
                            )}

                            {/* Objectives */}
                            {Array.isArray((entry as any).objectives) && (entry as any).objectives.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest italic mb-2">Marche à suivre</div>
                                    {(entry as any).objectives.map((obj: any, i: number) => {
                                        const text = extractObjectiveText(obj);
                                        const isReturn = text.toLowerCase().includes("retour") || text.toLowerCase().includes("aller voir");
                                        return (
                                            <div key={i} className="flex gap-2 items-start py-0.5">
                                                <div className={`w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0 text-[8px] font-black mt-0.5 ${isReturn ? "animate-pulse" : ""}`}
                                                    style={{ background: isReturn ? `${dofusColor}40` : "rgba(255,255,255,0.05)", color: isReturn ? "#fff" : "rgba(255,255,255,0.4)" }}>
                                                    {i + 1}
                                                </div>
                                                <div className={`text-[12.5px] font-medium leading-relaxed ${isReturn ? "text-white" : "text-zinc-400"}`}>
                                                    <ParsedObjective text={obj} guildId={guildId} zone={entry.zone ?? undefined} />
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                            {/* Quick Links */}
                            <div className="pt-2">
                                <div className="grid grid-cols-2 gap-2">
                                    <Button
                                        asChild
                                        variant="sigil"
                                        className="h-20 flex-col gap-2 rounded-2xl bg-indigo-500/5 border-indigo-500/10"
                                        onClick={(e) => e.stopPropagation()}
                                    >
                                        <a href={`https://dofusdb.fr/fr/database/quest/${entry.dofusdbId || entry.id}`} target="_blank" rel="noopener noreferrer">
                                            <Target className="w-5 h-5" />
                                            <span className="text-[10px] font-black uppercase tracking-widest">DofusDB</span>
                                        </a>
                                    </Button>
                                    
                                    {entry.externalRef ? (
                                        <Button
                                            asChild
                                            variant="sigil"
                                            className="h-20 flex-col gap-2 rounded-2xl bg-amber-500/5 border-amber-500/10"
                                            onClick={(e) => e.stopPropagation()}
                                        >
                                            <a href={entry.externalRef} target="_blank" rel="noopener noreferrer">
                                                <BookOpen className="w-5 h-5" />
                                                <span className="text-[10px] font-black uppercase tracking-widest">Stratégie</span>
                                            </a>
                                        </Button>
                                    ) : (
                                        <Button
                                            asChild
                                            variant="sigil"
                                            className="h-20 flex-col gap-2 rounded-2xl bg-amber-500/5 border-amber-500/10"
                                            onClick={(e) => e.stopPropagation()}
                                        >
                                            <a href={`https://www.google.com/search?q=site:dofuspourlesnoobs.com+${encodeURIComponent(entry.name)}`} target="_blank" rel="noopener noreferrer">
                                                <BookOpen className="w-5 h-5" />
                                                <span className="text-[10px] font-black uppercase tracking-widest">Noobs</span>
                                            </a>
                                        </Button>
                                    )}

                                    {(entry as any).coords ? (
                                        <>
                                            <Button
                                                variant="sigil-emerald"
                                                className="h-20 flex-col gap-2 rounded-2xl"
                                                onClick={(e) => { e.stopPropagation(); const c = (entry as any).coords; copyWithToast(`/travel ${c.x} ${c.y}`); }}
                                            >
                                                <Navigation className="w-5 h-5" />
                                                <span className="text-[10px] font-black uppercase tracking-widest">Travel</span>
                                            </Button>
                                            <QuestGuildStatus 
                                                guildId={guildId} 
                                                questId={entry.id} 
                                                dofusColor={dofusColor} 
                                                variant="action"
                                            />
                                        </>
                                    ) : (
                                        <div className="col-span-2">
                                            <QuestGuildStatus 
                                                guildId={guildId} 
                                                questId={entry.id} 
                                                dofusColor={dofusColor} 
                                                variant="action"
                                            />
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

// ─── Chain section ─────────────────────────────────────────────────────────────
function ChainSection({
    chain,
    guildId,
    dofusColor,
    completedIds,
    onToggle,
}: {
    chain: DofusChainWithProgress;
    guildId: string;
    dofusColor: string;
    completedIds: Set<string>;
    onToggle: (id: string, newStatus: DofusQuestStatus) => void;
}) {
    const [collapsed, setCollapsed] = useState(false);
    const completedCount = (chain.entries || []).filter((e) => completedIds.has(e.id)).length;
    const total = (chain.entries || []).length;
    const allDone = completedCount === total && total > 0;

    return (
        <div className="flex flex-col gap-2">
            <button onClick={() => setCollapsed(!collapsed)} className="flex items-center gap-3 w-full text-left group">
                <SectionBadge type={chain.sectionType} />
                <span className="text-sm font-semibold text-white/80 flex-1">{chain.sectionName}</span>
                {chain.description && (
                    <span className="text-xs text-white/30 hidden sm:block truncate max-w-[180px]">{chain.description}</span>
                )}
                <span className="text-xs text-white/30 tabular-nums">{completedCount}/{total}</span>
                {allDone && <span style={{ color: dofusColor }}>✓</span>}
                {collapsed ? <ChevronDown className="w-4 h-4 text-white/30" /> : <ChevronUp className="w-4 h-4 text-white/30" />}
            </button>

            {!collapsed && (
                <div className="flex flex-col gap-1.5 ml-0 sm:ml-2">
                    {(chain.entries || []).map((entry: any) => (
                        <QuestEntryRow
                            key={entry.id}
                            entry={entry}
                            guildId={guildId}
                            dofusColor={dofusColor}
                            completedIds={completedIds}
                            onToggle={onToggle}
                        />
                    ))}
                    {total === 0 && (
                        <p className="text-sm text-white/20 text-center py-4">Aucune entrée pour cette section</p>
                    )}
                </div>
            )}
        </div>
    );
}

// ─── Main export ───────────────────────────────────────────────────────────────
interface QuestChecklistProps {
    chains: DofusChainWithProgress[];
    guildId: string;
    dofusColor: string;
    completedIds: Set<string>;
    onToggle: (id: string, newStatus: DofusQuestStatus) => void;
}

export function QuestChecklist({ chains, guildId, dofusColor, completedIds, onToggle }: QuestChecklistProps) {
    if (chains.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-16 gap-3">
                <ListChecks className="w-10 h-10 text-white/15" />
                <p className="text-white/30 text-sm">Guide de quêtes à venir — données en cours d&apos;intégration</p>
            </div>
        );
    }

    return (
        <div className="space-y-12">
            {(chains || []).map((chain) => (
                <div key={chain.id} className="space-y-6">
                    <ChainSection
                        chain={chain}
                        guildId={guildId}
                        dofusColor={dofusColor}
                        completedIds={completedIds}
                        onToggle={onToggle}
                    />
                </div>
            ))}
        </div>
    );
}

"use client";

import React, { useState } from "react";
import { Users } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { getOtherMembersOnQuest, type MemberOnQuest } from "@/server/actions/dofus-quest-actions";

interface QuestGuildStatusProps {
    guildId: string;
    questId: string;
    dofusColor: string;
    variant?: "default" | "action";
}

export function QuestGuildStatus({ guildId, questId, dofusColor, variant = "default" }: QuestGuildStatusProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [members, setMembers] = useState<MemberOnQuest[]>([]);
    const [isOpen, setIsOpen] = useState(false);

    async function handleToggle() {
        if (!isOpen) {
            setIsLoading(true);
            const res = await getOtherMembersOnQuest(guildId, questId);
            if (res.success && res.data) setMembers(res.data);
            setIsLoading(false);
        }
        setIsOpen(!isOpen);
    }

    const isAction = variant === "action";

    return (
        <div className={isAction ? "w-full" : "relative"}>
            <Button
                variant={isAction ? "sigil-destructive" : "ghost"}
                onClick={(e) => { e.stopPropagation(); handleToggle(); }}
