                                        )}
                                        style={{ gridColumnStart: slot.c, gridRowStart: slot.r }}
                                    >
                                        {item && (
                                            <>
                                                <NextImage
                                                    src={`https://www.dofusbook.net/static/dist/items/${item.picture}-70.webp`}
                                                    alt={item.name}
                                                    width={32}
                                                    height={32}
                                                    className="object-contain"
