                            {data ? (
                                <div className="grid grid-cols-6 grid-rows-5 gap-2 sm:gap-3.5 relative z-10">
                                    {[
                                        { s: 'am', c: 1, r: 1 }, { s: 'a1', c: 1, r: 2 }, { s: 'a2', c: 1, r: 3 }, { s: 'br', c: 1, r: 4 },
                                        { s: 'ch', c: 6, r: 1 }, { s: 'ca', c: 6, r: 2 }, { s: 'ce', c: 6, r: 3 }, { s: 'bo', c: 6, r: 4 },
                                        { s: 'ar', c: 3, r: 4 }, { s: 'fa', c: 4, r: 4 },
                                        { s: 'd1', c: 1, r: 5 }, { s: 'd2', c: 2, r: 5 }, { s: 'd3', c: 3, r: 5 },
                                        { s: 'd4', c: 4, r: 5 }, { s: 'd5', c: 5, r: 5 }, { s: 'd6', c: 6, r: 5 },
                                    ].map((slot) => {
                                        const item = slot.s === 'fa' ? (data.items?.['fa'] || data.items?.['mo']) : data.items?.[slot.s];
                                        return (
                                            <a
                                                key={slot.s}
                                                href={item ? `https://dofusdb.fr/fr/database/items?q=${encodeURIComponent(item.name)}` : "#"}
                                                target={item ? "_blank" : undefined}
                                                rel="noopener noreferrer"
                                                className={cn(
                                                    "w-[40px] h-[40px] sm:w-[50px] sm:h-[50px] rounded-xl sm:rounded-2xl flex items-center justify-center p-1.5 sm:p-2 relative transition-all duration-500 group/modal-slot",
                                                    item ? "bg-zinc-800/80 border border-white/20 shadow-2xl hover:border-emerald-500/50 hover:bg-zinc-700 hover:scale-110" : "bg-white/[0.02] border border-white/5 opacity-30 cursor-default"
                                                )}
                                                style={{ gridColumnStart: slot.c, gridRowStart: slot.r }}
                                                onClick={(e) => !item && e.preventDefault()}
                                            >
                                                {item && (
                                                    <>
                                                        <NextImage
                                                            src={`https://www.dofusbook.net/static/dist/items/${item.picture}-70.webp`}
                                                            alt={item.name}
                                                            width={44}
                                                            height={44}
                                                            className="object-contain drop-shadow-xl"
                                                            unoptimized
                                                        />
                                                        <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-zinc-900 border border-white/10 px-3 py-1.5 rounded-xl text-[10px] font-black text-white opacity-0 group-hover/modal-slot:opacity-100 transition-all scale-75 group-hover/modal-slot:scale-100 shadow-2xl z-50 whitespace-nowrap pointer-events-none">
                                                            {item.name} <span className="text-emerald-400 ml-1">→ DofusDB</span>
                                                        </div>
                                                    </>
                                                )}
                                            </a>
                                        );
                                    })}
                                </div>
                            ) : (
                                <div className="absolute inset-0 flex items-center justify-center p-8">
                                    {guessedClassId > 0 && (
                                        <NextImage
                                            src={`/assets/dofus/classes/${getIconId(guessedClassId)}.png`}
                                            alt="Classe"
                                            fill
                                            className="object-contain opacity-20 p-12"
                                        />
                                    )}
                                </div>
                            )}
                        </div>

                        {data && (
                            <div className="flex flex-col gap-2 bg-black/30 p-5 rounded-3xl border border-white/5">
                                {[
                                    { res: 'neutre', val: data.resists.neutre, label: 'Neutre', icon: (
                                        <svg viewBox="0 0 24 24" fill="none" className="w-[15px] h-[15px] drop-shadow-md">
                                            <circle cx="12" cy="12" r="11" fill="#E2E2E2" stroke="#000" strokeWidth="1" />
                                            <path d="M12 1A11 11 0 0 0 12 23A5.5 5.5 0 0 1 12 12A5.5 5.5 0 0 0 12 1Z" fill="#111" />
                                            <circle cx="12" cy="6.5" r="2" fill="#111" />
                                            <circle cx="12" cy="17.5" r="2" fill="#E2E2E2" />
                                        </svg>
                                    ) },
                                    { res: 'terre', val: data.resists.terre, label: 'Terre', icon: (
                                        <svg viewBox="0 0 24 24" fill="#9D753E" className="w-[15px] h-[15px] drop-shadow-md">
                                           <path d="M12 24L5 12H9V0H15V12H19L12 24Z" />
                                        </svg>
                                    ) },
                                    { res: 'feu', val: data.resists.feu, label: 'Feu', icon: (
                                        <svg viewBox="0 0 24 24" fill="#E33E19" className="w-[15px] h-[15px] drop-shadow-md">
                                           <path d="M12 0C12 0 3 8 3 15C3 20 7 24 12 24C17 24 21 20 21 15C21 8 12 0 12 0ZM12 20C10 20 8 18 8 16C8 14 12 10 12 10C12 10 16 14 16 16C16 18 14 20 12 20Z" />
                                        </svg>
                                    ) },
                                    { res: 'eau', val: data.resists.eau, label: 'Eau', icon: (
                                        <svg viewBox="0 0 24 24" fill="#5AC2FF" className="w-[15px] h-[15px] drop-shadow-md">
                                           <path d="M12 0C12 0 4 10 4 16C4 20.418 7.582 24 12 24C16.418 24 20 20.418 20 16C20 10 12 0 12 0Z" />
                                        </svg>
                                    ) },
                                    { res: 'air', val: data.resists.air, label: 'Air', icon: (
                                        <svg viewBox="0 0 24 24" fill="#88C72B" className="w-[15px] h-[15px] drop-shadow-md">
                                           <path d="M17 19C19.761 19 22 16.761 22 14C22 11.239 19.761 9 17 9C16.5 6 14 3 11 3C7 3 4 6 4 10C1.79 10 0 11.79 0 14C0 16.21 1.79 18 4 18H17Z" />
                                        </svg>
                                    ) },
                                ].map(({ res, val, icon, label }) => (
                                    <div key={res} className="flex items-center gap-3">
                                        <span className="w-8 text-right font-black text-white text-[15px]" style={{ textShadow: "0px 1px 2px rgba(0,0,0,0.8)" }}>{val}</span>
                                        <span className="flex items-center justify-center w-5 h-5">{icon}</span>
                                        <span className="text-blue-300 text-[14px] font-semibold tracking-wide leading-none" style={{ textShadow: "0px 1px 2px rgba(0,0,0,0.8)" }}>% Ré {label}</span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Right: Info & Stats Grid */}
                    <div className="flex-1 flex flex-col relative z-10">
                        <DialogHeader className="mb-6 lg:mb-8 text-left">
                            <div className="flex items-center gap-3">
                                <div className="flex-1">
                                    <div className="flex items-center gap-3 mb-2">
                                        <span className="px-2 py-0.5 bg-emerald-500/20 text-emerald-400 text-[10px] font-black rounded uppercase">Lvl {data?.level || "200"}</span>
                                        <span className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">{data?.className || getClassName(guessedClassId)}</span>
                                    </div>
                                    <DialogTitle className="text-2xl sm:text-3xl font-black text-white uppercase tracking-tight">{title || data?.name || "Sans nom"}</DialogTitle>
                                </div>
                                <Button 
                                    variant="outline" 
                                    size="sm" 
                                    onClick={(e) => {
                                        e.preventDefault();
                                        e.stopPropagation();
                                        fetchBuild(true);
                                    }}
                                    disabled={loading}
                                    className="bg-zinc-900 border-white/10 hover:bg-zinc-800 text-zinc-400 hover:text-white rounded-xl h-10 px-4"
                                >
                                    <RefreshCw className={cn("w-4 h-4 mr-2", loading && "animate-spin")} />
                                    Actualiser
                                </Button>
                            </div>
                            <DialogDescription asChild>
                                <div className="flex flex-wrap gap-2 mt-3">
                                    {tags.map(tagId => {
                                        const tagDef = DO_TAGS.find(t => t.id === tagId);
                                        return tagDef ? (
                                            <span key={tagId} className={cn("px-2 py-0.5 text-[9px] rounded font-black uppercase tracking-tighter", tagDef.className)}>
                                                {tagDef.text}
                                            </span>
                                        ) : null;
                                    })}
                                </div>
                            </DialogDescription>
                        </DialogHeader>

                        {data ? (
                            <div className="flex flex-col gap-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                                    {/* Bloc 1: Stats Primaires */}
                                    <div className="bg-[#2B2925] p-6 rounded-3xl border border-[#3B3831] shadow-inner flex flex-col h-full">
                                        <h4 className="text-[10px] font-black text-white/30 uppercase tracking-widest mb-6 flex items-center gap-2"><Move className="w-3.5 h-3.5"/> Caractéristiques</h4>
                                        <div className="grid grid-cols-2 gap-2 my-auto">
                                            {[
                                                { val: data.stats.vit, icon: "❤️", label: "PdV", color: "text-white" },
                                                { val: data.stats.pa, icon: "⭐", label: "PA", color: "text-[#008cfc]" },
                                                { val: data.stats.pm, icon: "🛹", label: "PM", color: "text-[#2cb14b]" },
                                                { val: data.stats.po, icon: "👁️", label: "PO", color: "text-[#389f81]" },
                                                { val: data.stats.pp, icon: "🔎", label: "Pros.", color: "text-[#5AC2FF]" },
                                                { val: data.stats.cc, icon: "🎯", label: "Crit.", color: "text-[#f24254]" },
                                                { val: data.stats.invo, icon: "🦊", label: "Invo.", color: "text-[#f59f0f]" },
                                                { val: data.stats.so, icon: "➕", label: "Soin", color: "text-[#ef3f3f]" },
                                            ].map((s, i) => (
                                                <div key={i} className="flex items-center justify-between bg-black/30 px-2 py-2 rounded-xl border border-white/[0.05] gap-1">
                                                    <div className="flex items-center gap-0.5">
                                                        <span className="text-[12px] opacity-60 shrink-0">{s.icon}</span>
                                                        <span className="text-zinc-500 text-[9px] font-bold uppercase tracking-tighter whitespace-nowrap">{s.label}</span>
                                                    </div>
                                                    <span className={cn("font-black text-[13px] shrink-0", s.color)}>{s.val}</span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>

                                    {/* Bloc 2: Éléments */}
                                    <div className="bg-[#2B2925] p-6 rounded-3xl border border-[#3B3831] shadow-inner flex flex-col h-full">
                                        <h4 className="text-[10px] font-black text-white/30 uppercase tracking-widest mb-6 flex items-center gap-2"><Zap className="w-3.5 h-3.5"/> Éléments</h4>
                                        <div className="flex flex-col gap-2 my-auto">
                                            {[
                                                { key: 'fo' as const, label: 'Force',        color: 'text-[#9D753E]' },
                                                { key: 'in' as const, label: 'Intelligence', color: 'text-[#E33E19]' },
                                                { key: 'ch' as const, label: 'Chance',       color: 'text-[#5AC2FF]' },
                                                { key: 'ag' as const, label: 'Agilité',      color: 'text-[#88C72B]' },
                                                { key: 'sa' as const, label: 'Sagesse',      color: 'text-[#a560df]' },
                                                { key: 'pu' as const, label: 'Puissance',    color: 'text-[#f59f0f]' },
                                            ].map(({ key, label, color }) => (
                                                <div key={key} className="flex justify-between items-center bg-black/20 px-3 py-2.5 rounded-xl border border-white/[0.02]">
                                                    <span className="text-zinc-400 text-[13px] font-medium">{label}</span>
                                                    <span className={cn("font-black text-[16px]", color)}>{data.elements[key] || 0}</span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                    
                                    {/* Bloc 3: Dommages */}
                                    <div className="bg-[#2B2925] p-6 rounded-3xl border border-[#3B3831] shadow-inner md:col-span-2 xl:col-span-1 flex flex-col h-full">
                                        <h4 className="text-[10px] font-black text-white/30 uppercase tracking-widest mb-6 flex items-center gap-2"><Zap className="w-3.5 h-3.5 fill-current"/> Dommages Fixes & %</h4>
                                        <div className="flex flex-col gap-4 my-auto">
                                            <div className="grid grid-cols-2 gap-x-6 gap-y-2.5">
                                                {[
                                                    { label: 'Neutre', k: "neutre" as const, c: 'text-[#E2E2E2]' },
                                                    { label: 'Terre', k: "terre" as const, c: 'text-[#9D753E]' },
                                                    { label: 'Feu', k: "feu" as const, c: 'text-[#E33E19]' },
                                                    { label: 'Eau', k: "eau" as const, c: 'text-[#5AC2FF]' },
                                                    { label: 'Air', k: "air" as const, c: 'text-[#88C72B]' },
                                                    { label: 'Généraux', k: "general" as const, c: 'text-white' },
                                                    { label: 'Crit.', k: "critique" as const, c: 'text-[#f24254]' },
                                                    { label: 'Poussée', k: "poussee" as const, c: 'text-zinc-400' },
                                                ].map(d => (
                                                    <div key={d.k} className="flex justify-between items-center text-[13px] border-b border-white/5 pb-1.5">
                                                        <span className="text-zinc-500 font-medium">{d.label}</span>
                                                        <span className={cn("font-black", d.c)}>{data.damages?.[d.k] || 0}</span>
                                                    </div>
                                                ))}
                                            </div>
                                            {/* % Section */}
                                            <div className="grid grid-cols-2 gap-2">
                                                {[
                                                    { label: '% Mêlée', k: "melee" as const },
                                                    { label: '% Dist.', k: "distance" as const },
                                                    { label: '% Armes', k: "armes" as const },
                                                    { label: '% Sorts', k: "sorts" as const },
                                                ].map(p => (
                                                    <div key={p.k} className="flex justify-between items-center text-[12px] bg-black/40 px-3 py-2 rounded-xl border border-white/5">
                                                        <span className="text-zinc-500">{p.label}</span>
                                                        <span className="font-black text-emerald-400 text-[13px]">{data.damages?.[p.k] || 0}%</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* Panoplies */}
                                {data.cloths && data.cloths.length > 0 && (
                                    <div className="pt-4 border-t border-white/5">
                                        <h4 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                                            <Shield className="w-3.5 h-3.5 text-emerald-500" /> Panoplies Associées
                                        </h4>
                                        <div className="flex flex-wrap gap-2">
                                            {data.cloths.map((cloth, i) => (
                                                <ClothBadge key={i} cloth={cloth} />
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex-1 flex flex-col items-center justify-center p-12 bg-white/[0.02] rounded-[3rem] border border-white/5 text-center gap-5">
                                <div className="w-16 h-16 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center">
                                    <ExternalLink className="w-8 h-8 text-zinc-500" />
                                </div>
                                <div className="max-w-xs">
                                    <h4 className="text-lg font-black text-white uppercase mb-2">Build Dofusbook</h4>
                                    <p className="text-sm text-zinc-500 leading-relaxed">
                                        Ce build n'a pas pu être chargé dynamiquement sur le dashboard.
                                    </p>
                                </div>
                            </div>
                        )}

                        <div className="mt-8">
                            <a
                                href={url}
                                target="_blank"
                                className="w-full sm:w-auto inline-flex px-8 py-4 bg-white text-black rounded-2xl text-center text-[12px] font-black uppercase tracking-widest hover:bg-zinc-200 transition-all items-center justify-center gap-3 shadow-xl shadow-white/5"
                            >
                                Ouvrir sur Dofusbook <ExternalLink className="w-4 h-4" />
                            </a>
                        </div>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
});

"use client";

import { useState, useEffect, useTransition, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { CheckCircle2, Circle, Trophy, Search, X, ChevronDown, Info } from "lucide-react";
import { toggleAchievementCompleted, getUserDungeonProgress, findMissingAchievements } from "@/server/actions/dungeon-finder-actions";
import { getDungeonsWithAchievements } from "@/server/actions/game-data-actions";
import { toast } from "sonner";

interface Achievement {
    id: string;
    points: number;
    challenge: { id: string; name: string; iconUrl?: string | null };
}

interface Dungeon {
    id: string;
    name: string;
    bossName: string;
    level: number;
    imageUrl?: string | null;
    achievements: Achievement[];
}

interface AchievementTrackerProps {
    guildId: string;
}

// Circular progress ring component
function ProgressRing({ pct, size = 48, stroke = 4, color = "#6366f1" }: {
    pct: number; size?: number; stroke?: number; color?: string;
}) {
    const r = (size - stroke * 2) / 2;
    const circ = 2 * Math.PI * r;
    const dash = circ - (pct / 100) * circ;

    return (
        <svg width={size} height={size} className="-rotate-90">
            <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={stroke} />
            <motion.circle
                cx={size / 2} cy={size / 2} r={r}
                fill="none" stroke={color} strokeWidth={stroke}
                strokeLinecap="round" strokeDasharray={circ}
                initial={{ strokeDashoffset: circ }}
                animate={{ strokeDashoffset: dash }}
                transition={{ duration: 1, ease: "easeOut" }}
            />
        </svg>
    );
}

export function AchievementTracker({ guildId }: AchievementTrackerProps) {
    const [dungeons, setDungeons] = useState<Dungeon[]>([]);
    const [completedIds, setCompletedIds] = useState<Set<string>>(new Set());
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [expandedDungeon, setExpandedDungeon] = useState<string | null>(null);
    const [missingData, setMissingData] = useState<Record<string, any[]>>({});
    const [filterStatus, setFilterStatus] = useState<"all" | "done" | "todo">("all");
    const [minLevel, setMinLevel] = useState(1);
    const [maxLevel, setMaxLevel] = useState(1000);
    const [isPending, startTransition] = useTransition();

    useEffect(() => {
        async function load() {
            const [dungeonsRes, progressRes] = await Promise.all([
                getDungeonsWithAchievements(),
                getUserDungeonProgress(guildId),
            ]);
            if (dungeonsRes.success && dungeonsRes.data) {
                const filtered = (dungeonsRes.data as Dungeon[]).filter((d) => d.achievements.length > 0);
                setDungeons(filtered.sort((a, b) => a.level - b.level));
            }
            if (progressRes.success && progressRes.data) {
                setCompletedIds(new Set(progressRes.data.map((p) => p.achievementId)));
            }
            setLoading(false);
        }
        load();
    }, [guildId]);

    async function expandDungeon(dungeonId: string) {
        if (expandedDungeon === dungeonId) { setExpandedDungeon(null); return; }
        setExpandedDungeon(dungeonId);
        if (!missingData[dungeonId]) {
            const res = await findMissingAchievements(guildId, dungeonId);
            if (res.success && res.data) setMissingData((p) => ({ ...p, [dungeonId]: res.data! }));
        }
    }

    function toggleAchievement(achievementId: string) {
        startTransition(async () => {
            const dungeon = dungeons.find((d) => d.achievements.some((a) => a.id === achievementId));
            if (!dungeon) return;
            const res = await toggleAchievementCompleted(guildId, dungeon.id, achievementId);
            if (res.success) {
                setCompletedIds((prev) => {
                    const next = new Set(prev);
                    res.data?.completed ? next.add(achievementId) : next.delete(achievementId);
                    return next;
                });
                setMissingData((prev) => { const next = { ...prev }; delete next[dungeon.id]; return next; });
            } else {
                toast.error(res.error);
            }
        });
    }

    function toggleDungeonAchievements(dungeon: Dungeon, checkAll: boolean) {
        startTransition(async () => {
            // Optimistic update
            const nextIds = new Set(completedIds);
            for (const a of dungeon.achievements) {
                if (checkAll) nextIds.add(a.id);
                else nextIds.delete(a.id);
            }
            setCompletedIds(nextIds);

            // Sequential calls (not ideal but server action limitation)
            // Or better: update all in one go if the server action supported it.
            // For now, let's just do them one by one but in the background.
            for (const a of dungeon.achievements) {
                const alreadyMatch = checkAll ? completedIds.has(a.id) : !completedIds.has(a.id);
                if (!alreadyMatch) {
                    await toggleAchievementCompleted(guildId, dungeon.id, a.id);
                }
            }
            setMissingData((prev) => { const next = { ...prev }; delete next[dungeon.id]; return next; });
        });
    }

    const totalAchievements = dungeons.reduce((acc, d) => acc + d.achievements.length, 0);
    const completedTotal = dungeons.reduce((acc, d) => acc + d.achievements.filter((a) => completedIds.has(a.id)).length, 0);
    const progressPct = totalAchievements > 0 ? Math.round((completedTotal / totalAchievements) * 100) : 0;

    const filteredDungeons = useMemo(() => {
        const term = search.toLowerCase();
        return dungeons.filter((d) => {
            const matchSearch = d.name.toLowerCase().includes(term) || d.bossName.toLowerCase().includes(term);
            const matchLevel = d.level >= minLevel && d.level <= maxLevel;
            if (!matchSearch || !matchLevel) return false;
            
            const done = d.achievements.filter((a) => completedIds.has(a.id)).length;
            if (filterStatus === "done") return done === d.achievements.length;
            if (filterStatus === "todo") return done < d.achievements.length;
            return true;
        });
    }, [dungeons, search, filterStatus, completedIds, minLevel, maxLevel]);

    if (loading) {
        return (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                {Array.from({ length: 10 }).map((_, i) => (
                    <div key={i} className="h-28 rounded-2xl bg-slate-900/40 border border-slate-800 animate-pulse" />
                ))}
            </div>
        );
    }

    return (
        <div className="space-y-5">
            {/* Global stats banner */}
            <div className="relative overflow-hidden bg-gradient-to-br from-slate-900 via-slate-900 to-indigo-950/30 border border-white/5 shadow-inner rounded-2xl p-5">
                <div className="absolute top-0 right-0 w-48 h-48 opacity-5">
                    <Trophy className="w-full h-full text-indigo-400" />
                </div>
                <div className="flex items-center gap-5">
                    {/* Big ring */}
                    <div className="relative shrink-0">
                        <ProgressRing pct={progressPct} size={72} stroke={5} color={progressPct === 100 ? "#22c55e" : "#818cf8"} />
                        <span className="absolute inset-0 flex items-center justify-center text-sm font-black text-white">
                            {progressPct}%
                        </span>
                    </div>
                    <div className="flex-1">
                        <p className="text-lg font-black text-white">
                            {completedTotal} <span className="text-slate-400 font-normal text-base">/ {totalAchievements}</span>
                        </p>
                        <p className="text-sm text-slate-400">succès de donjon cochés</p>
                        <p className="text-[11px] text-slate-600 mt-1.5 flex items-center gap-1">
                            <Info className="w-3 h-3" />
                            Coche les succès complétés pour trouver des co-équipiers dans la guilde.
                        </p>
                    </div>
                    {/* Mini stats */}
                    <div className="hidden sm:flex gap-4 shrink-0">
                        <div className="text-center">
                            <p className="text-xl font-black text-emerald-400">
                                {dungeons.filter((d) => d.achievements.every((a) => completedIds.has(a.id))).length}
                            </p>
                            <p className="text-[10px] text-slate-500">donjons finis</p>
                        </div>
                        <div className="text-center">
                            <p className="text-xl font-black text-slate-300">
                                {dungeons.filter((d) => !d.achievements.every((a) => completedIds.has(a.id))).length}
                            </p>
                            <p className="text-[10px] text-slate-500">à compléter</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Toolbar */}
            <div className="flex flex-col sm:flex-row gap-2">
                {/* Search */}
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input
                        type="text"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        placeholder="Chercher un donjon…"
                        className="w-full bg-slate-900/50 border border-white/5 rounded-xl pl-10 pr-8 py-2.5 text-sm text-white placeholder:text-slate-500 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 transition-all shadow-inner h-11"
                    />
                    {search && (
                        <button onClick={() => setSearch("")} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-600 hover:text-white">
                            <X className="w-3.5 h-3.5" />
                        </button>
                    )}
                </div>
                {/* Status filter */}
                <div className="flex gap-1 bg-slate-900/50 border border-white/5 shadow-inner rounded-xl p-1 shrink-0 h-11 items-center">
                    {[
                        { id: "all" as const, label: "Tous" },
                        { id: "todo" as const, label: "À faire" },
                        { id: "done" as const, label: "Complétés" },
                    ].map(({ id, label }) => (
                        <button
                            key={id}
                            onClick={() => setFilterStatus(id)}
                            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${filterStatus === id ? "bg-indigo-600 text-white shadow-lg" : "text-slate-500 hover:text-slate-300"
                                }`}
                        >
                            {label}
                        </button>
                    ))}
                </div>
            </div>

            {/* Level Presets Row */}
            <div className="flex flex-wrap items-center gap-1.5 p-1 bg-slate-900/40 border border-white/5 rounded-xl w-max">
                {[
                    { label: "Tout", min: 1, max: 1000 },
                    { label: "1-50", min: 1, max: 50 },
                    { label: "51-100", min: 51, max: 100 },
                    { label: "101-150", min: 101, max: 150 },
                    { label: "151-190", min: 151, max: 190 },
                    { label: "191-200", min: 191, max: 200 },
                ].map((preset) => {
                    const isActive = minLevel === preset.min && maxLevel === preset.max;
                    return (
                        <button
                            key={preset.label}
                            onClick={() => { setMinLevel(preset.min); setMaxLevel(preset.max); }}
                            className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all border ${isActive
                                ? "bg-indigo-500/20 text-indigo-300 border-indigo-500/30 shadow-indigo-900/10"
                                : "bg-white/5 text-slate-500 border-transparent hover:bg-white/10 hover:text-slate-300"
                                }`}
                        >
                            {preset.label === "Tout" ? "Tous Niveaux" : `Lvl ${preset.label}`}
                        </button>
                    );
                })}
            </div>

            {/* Grid */}
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                <AnimatePresence>
                    {filteredDungeons.map((dungeon, i) => {
                        const done = dungeon.achievements.filter((a) => completedIds.has(a.id)).length;
                        const pct = dungeon.achievements.length > 0 ? Math.round((done / dungeon.achievements.length) * 100) : 0;
                        const isComplete = done === dungeon.achievements.length;
                        const isExpanded = expandedDungeon === dungeon.id;
                        const missing = missingData[dungeon.id] ?? [];

                        return (
                            <motion.div
                                key={dungeon.id}
                                layout
                                initial={{ opacity: 0, scale: 0.95 }}
                                animate={{ opacity: 1, scale: 1 }}
                                exit={{ opacity: 0, scale: 0.95 }}
                                transition={{ delay: i * 0.02 }}
                                className={`col-span-1 ${isExpanded ? "sm:col-span-3 md:col-span-4 lg:col-span-5" : ""}`}
                            >
                                {isExpanded ? (
                                    /* Expanded view */
                                    <div className="bg-slate-900/90 border border-indigo-500/20 rounded-2xl overflow-hidden shadow-2xl shadow-indigo-900/10">
                                        {/* Expanded header */}
                                        <button
                                            onClick={() => expandDungeon(dungeon.id)}
                                            className="w-full flex items-center gap-4 p-4 hover:bg-slate-800/30 transition-colors text-left group"
                                        >
                                            <div className="w-16 h-16 rounded-xl overflow-hidden bg-slate-900 border border-white/5 shadow-inner shrink-0 flex items-center justify-center">
                                                {dungeon.imageUrl
                                                    ? <img src={dungeon.imageUrl} alt="" className="w-full h-full object-cover" />
                                                    : <Trophy className="w-7 h-7 text-slate-600" />
                                                }
                                            </div>
                                            <div className="flex-1">
                                                <p className="text-xl font-black text-white">{dungeon.name}</p>
                                                <p className="text-sm text-slate-500">Lvl {dungeon.level} · {dungeon.bossName}</p>
                                            </div>
                                            <div className="flex items-center gap-4">
                                                <div
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        toggleDungeonAchievements(dungeon, !isComplete);
                                                    }}
                                                    className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border transition-all ${isComplete
                                                        ? "bg-rose-500/10 text-rose-400 border-rose-500/20 hover:bg-rose-500/20"
                                                        : "bg-emerald-500/10 text-emerald-400 border-emerald-500/20 hover:bg-emerald-500/20"
                                                        }`}
                                                >
                                                    {isComplete ? "Décocher tout" : "Cocher tout"}
                                                </div>
                                                <div className="flex items-center gap-3">
                                                    <span className={`text-sm font-black ${isComplete ? "text-emerald-400" : "text-indigo-400"}`}>
                                                        {done}/{dungeon.achievements.length}
                                                    </span>
                                                    <ChevronDown className="w-4 h-4 text-slate-400 rotate-180 transition-transform group-hover:text-white" />
                                                </div>
                                            </div>
                                        </button>
                                        {/* Achievements */}
                                        <div className="border-t border-white/5 p-4 grid grid-cols-1 sm:grid-cols-2 gap-2">
                                            {dungeon.achievements.map((a) => {
                                                const isDone = completedIds.has(a.id);
                                                const missingInfo = missing.find((m) => m.achievementId === a.id);
                                                return (
                                                    <div key={a.id}>
                                                        <div
                                                            onClick={() => toggleAchievement(a.id)}
                                                            className={`flex items-center gap-3 p-2.5 rounded-xl cursor-pointer transition-all border ${isDone
                                                                ? "bg-emerald-500/8 border-emerald-500/15 hover:border-emerald-500/30"
                                                                : "bg-white/5 border-transparent hover:border-white/10 hover:bg-white/10"
                                                                }`}
                                                        >
                                                            {isDone
                                                                ? <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
                                                                : <Circle className="w-4 h-4 text-slate-600 shrink-0" />
                                                            }
                                                            {a.challenge.iconUrl && (
                                                                <img src={a.challenge.iconUrl} alt="" className="w-5 h-5 object-contain shrink-0" />
                                                            )}
                                                            <span className={`text-xs flex-1 leading-tight ${isDone ? "text-emerald-300 line-through opacity-60" : "text-slate-300"}`}>
                                                                {a.challenge.name}
                                                            </span>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                ) : (
                                    /* Card view */
                                    <button
                                        onClick={() => expandDungeon(dungeon.id)}
                                        className={`group w-full rounded-2xl border transition-all duration-200 overflow-hidden text-left hover:scale-[1.02] hover:shadow-xl ${isComplete
                                            ? "bg-emerald-950/20 border-emerald-700/30 hover:border-emerald-600/50 hover:shadow-emerald-900/20"
                                            : "bg-slate-900/40 border-white/5 hover:border-indigo-500/30 hover:bg-slate-900/60 shadow-sm"
                                            }`}
                                    >
                                        <div className="p-3 space-y-2">
                                            {/* Top: icon + progress ring */}
                                            <div className="flex items-start justify-between gap-2">
                                                {/* Icon */}
                                                <div className="w-14 h-14 rounded-xl overflow-hidden bg-slate-900 border border-white/5 shadow-inner shrink-0 flex items-center justify-center">
                                                    {dungeon.imageUrl
                                                        ? <img src={dungeon.imageUrl} alt="" className="w-full h-full object-cover" />
                                                        : <Trophy className="w-5 h-5 text-slate-600" />
                                                    }
                                                </div>
                                                {/* Progress ring */}
                                                <div className="relative shrink-0">
                                                    <ProgressRing
                                                        pct={pct}
                                                        size={34}
                                                        stroke={3}
                                                        color={isComplete ? "#22c55e" : "#818cf8"}
                                                    />
                                                    <span className="absolute inset-0 flex items-center justify-center text-[8px] font-black text-white">
                                                        {done}/{dungeon.achievements.length}
                                                    </span>
                                                </div>
                                            </div>
                                            {/* Name */}
                                            <div>
                                                <p className="text-xs font-bold text-white line-clamp-2 leading-tight group-hover:text-indigo-200 transition-colors">
                                                    {dungeon.name}
                                                </p>
                                                <p className="text-[10px] text-slate-500 mt-0.5">Lvl {dungeon.level}</p>
                                            </div>
                                            {/* Status */}
                                            {isComplete && (
                                                <div className="flex items-center gap-1">
                                                    <CheckCircle2 className="w-3 h-3 text-emerald-400" />
                                                    <span className="text-[10px] text-emerald-400 font-bold">Complété</span>
                                                </div>
                                            )}
                                        </div>
                                    </button>
                                )}
                            </motion.div>
                        );
                    })}
                </AnimatePresence>
            </div>

            {filteredDungeons.length === 0 && (
                <div className="py-16 text-center text-slate-600">
                    <Trophy className="w-10 h-10 mx-auto mb-3 opacity-20" />
                    <p className="font-medium">Aucun donjon trouvé.</p>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useTransition, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { CheckCircle2, Circle, Trophy, X, Loader2, Star, ShieldCheck, UserPlus, Search, ChevronDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { closeDjPostWithContributions, getDjGuildMembersForClose } from "@/server/actions/dungeon-finder-actions";
import { toast } from "sonner";
import type { DjPostWithDetails } from "@/server/actions/dungeon-finder-actions";

interface DjCloseModalProps {
    isOpen: boolean;
    post: DjPostWithDetails;
    guildId: string;
    onClose: () => void;
    onClosed: () => void;
}

type GuildMember = { id: string; name: string; image: string | null };

/** Mirror of server-side getContributionPoints */
function getPointsFromLevel(level?: number | null): number {
    if (!level) return 1;
    if (level >= 200) return 4;
    if (level >= 150) return 3;
    if (level >= 100) return 2;
    return 1;
}

export function DjCloseModal({ isOpen, post, guildId, onClose, onClosed }: DjCloseModalProps) {
    const [isPending, startTransition] = useTransition();

    // ── Participants qui se sont inscrits formellement ──────────────────────
    const acceptedParticipants = post.participants.filter(
        (p) => p.status === "ACCEPTED" && p.profile.id !== post.profileId
    );

    // IDs validés (cochés) : tous les inscrits par défaut
    const [validated, setValidated] = useState<Set<string>>(
        new Set(acceptedParticipants.map((p) => p.profile.id))
    );

    // ── Membres supplémentaires (hors-post) ─────────────────────────────────
    const [allMembers, setAllMembers] = useState<GuildMember[]>([]);
    const [extraMembers, setExtraMembers] = useState<GuildMember[]>([]);
    const [search, setSearch] = useState("");
    const [dropdownOpen, setDropdownOpen] = useState(false);
    const [loadingMembers, setLoadingMembers] = useState(false);
    const searchRef = useRef<HTMLInputElement>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);

    // Ferme la dropdown si on clique en dehors
    useEffect(() => {
        if (!dropdownOpen) return;
        function handler(e: MouseEvent) {
            if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
                setDropdownOpen(false);
                setSearch("");
            }
        }
        document.addEventListener("mousedown", handler);
        return () => document.removeEventListener("mousedown", handler);
    }, [dropdownOpen]);

    // Charge la liste des membres quand la modale s'ouvre
    useEffect(() => {
        if (!isOpen || allMembers.length > 0) return;
        setLoadingMembers(true);
        getDjGuildMembersForClose(guildId).then((res) => {
            if (res.success && res.data) setAllMembers(res.data);
            setLoadingMembers(false);
        });
    }, [isOpen, guildId, allMembers.length]);

    function toggle(profileId: string) {
        setValidated((prev) => {
            const next = new Set(prev);
            if (next.has(profileId)) next.delete(profileId);
            else next.add(profileId);
            return next;
        });
    }

    // IDs déjà dans la liste (formels + extra) pour éviter les doublons dans la dropdown
    const alreadyListedIds = new Set([
        post.profileId,
        ...acceptedParticipants.map((p) => p.profile.id),
        ...extraMembers.map((m) => m.id),
    ]);

    const filteredSuggestions = allMembers.filter(
        (m) => !alreadyListedIds.has(m.id) && m.name.toLowerCase().includes(search.toLowerCase())
    );

    function addExtra(member: GuildMember) {
        setExtraMembers((prev) => [...prev, member]);
        setValidated((prev) => new Set([...prev, member.id]));
        setSearch("");
        setDropdownOpen(false);
    }

    function removeExtra(id: string) {
        setExtraMembers((prev) => prev.filter((m) => m.id !== id));
        setValidated((prev) => {
            const next = new Set(prev);
            next.delete(id);
            return next;
        });
    }

    // ── Points & clôture ────────────────────────────────────────────────────
    const dungeonLevel = post.dungeon?.level ?? null;
    const pts = getPointsFromLevel(dungeonLevel);

    function handleConfirm() {
        startTransition(async () => {
            const res = await closeDjPostWithContributions(guildId, post.id, Array.from(validated));
            if (res.success) {
                const count = validated.size;
                const awarded = (res as any).data?.pointsAwarded ?? pts;
                toast.success(`Groupe clôturé ! ${count} membre${count > 1 ? "s ont" : " a"} reçu +${awarded} point${awarded > 1 ? "s" : ""} de contribution.`);
                onClosed();
                onClose();
            } else {
                toast.error(res.error);
            }
        });
    }

    const title = post.mode === "DONJON" ? post.dungeon?.name : post.questName;
    const validatedCount = validated.size;
    const totalListCount = acceptedParticipants.length + extraMembers.length;

    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed inset-0 z-50 flex items-center justify-center p-4"
                    onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
                >
                    {/* Backdrop */}
                    <div className="absolute inset-0 bg-black/70 backdrop-blur-md" />

                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 12 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 12 }}
                        transition={{ type: "spring", stiffness: 300, damping: 25 }}
                        className="relative w-full max-w-md bg-zinc-950 border border-white/10 rounded-2xl shadow-2xl overflow-hidden"
                    >
                        {/* Header glow */}
                        <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-violet-500/50 to-transparent" />

                        {/* Header */}
                        <div className="p-6 pb-4 border-b border-white/5 bg-slate-900/30">
                            <div className="flex items-start justify-between gap-3">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-violet-500/20 border border-violet-500/30 shadow-inner flex items-center justify-center shrink-0">
                                        <ShieldCheck className="w-5 h-5 text-violet-400" />
                                    </div>
                                    <div>
                                        <h2 className="text-base font-black text-white">Clôturer le groupe</h2>
                                        <p className="text-xs text-slate-500 mt-0.5 truncate max-w-[240px]">{title}</p>
                                    </div>
                                </div>
                                <button onClick={onClose} className="text-slate-600 hover:text-white transition-colors mt-0.5">
                                    <X className="w-4 h-4" />
                                </button>
                            </div>
                        </div>

                        {/* Body */}
                        <div className="p-6 space-y-5 max-h-[60vh] overflow-y-auto">
                            {/* Info banner */}
                            <div className="flex items-start gap-2.5 bg-violet-500/8 border border-violet-500/20 rounded-xl px-3.5 py-3">
                                <Trophy className="w-4 h-4 text-violet-400 mt-0.5 shrink-0" />
                                <p className="text-xs text-slate-300 leading-relaxed">
                                    Valide les membres qui ont <strong className="text-white">réellement participé</strong> pour leur attribuer{" "}
                                    <strong className="text-violet-300">+{pts} point{pts > 1 ? "s" : ""} de contribution</strong>.
                                    {post.dungeon && (
                                        <span className="ml-1 text-slate-500">(Donjon niveau {post.dungeon.level})</span>
                                    )}
                                    {" "}<span className="text-slate-500">Tu ne reçois pas de point en tant que créateur.</span>
                                </p>
                            </div>

                            {/* Participants inscrits */}
                            {totalListCount > 0 && (
                                <div className="space-y-2">
                                    <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest">
                                        Participants ({acceptedParticipants.length} inscrit{acceptedParticipants.length > 1 ? "s" : ""}{extraMembers.length > 0 ? ` + ${extraMembers.length} ajouté${extraMembers.length > 1 ? "s" : ""}` : ""})
                                    </p>

                                    {/* Inscrits formels */}
                                    {acceptedParticipants.map((p) => {
                                        const isVal = validated.has(p.profile.id);
                                        return (
                                            <button
                                                key={p.profile.id}
                                                onClick={() => toggle(p.profile.id)}
                                                className={`w-full flex items-center gap-3 p-3 rounded-xl border transition-all text-left group ${isVal
                                                    ? "bg-emerald-500/10 border-emerald-500/30 shadow-inner"
                                                    : "bg-slate-900/40 border-white/5 hover:bg-slate-900/60"
                                                    }`}
                                            >
                                                <div className="w-8 h-8 rounded-full overflow-hidden bg-slate-700 shrink-0">
                                                    {p.profile.user.image && (
                                                        <img src={p.profile.user.image} alt="" className="w-full h-full object-cover" />
                                                    )}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <p className="text-sm font-bold text-white truncate">
                                                        {p.profile.discordNickname || p.profile.pseudoDofus || (p.profile as any).dofusPseudo || "Membre"}
                                                    </p>
                                                    {p.classe && <p className="text-[10px] text-slate-500">{p.classe}</p>}
                                                </div>
                                                {isVal && (
                                                    <span className="flex items-center gap-1 text-[10px] font-black text-emerald-400 bg-emerald-500/20 px-2 py-0.5 rounded-md border border-emerald-500/30">
                                                        <Star className="w-2.5 h-2.5" /> +{pts} pt{pts > 1 ? "s" : ""}
                                                    </span>
                                                )}
                                                {isVal
                                                    ? <CheckCircle2 className="w-5 h-5 text-emerald-400 shrink-0" />
                                                    : <Circle className="w-5 h-5 text-slate-600 shrink-0" />
                                                }
                                            </button>
                                        );
                                    })}

                                    {/* Membres ajoutés manuellement */}
                                    {extraMembers.map((m) => {
                                        const isVal = validated.has(m.id);
                                        return (
                                            <div
                                                key={m.id}
                                                className="w-full flex items-center gap-3 p-3 rounded-xl border bg-amber-500/10 border-amber-500/30"
                                            >
                                                <div className="w-8 h-8 rounded-full overflow-hidden bg-slate-700 shrink-0">
                                                    {m.image && <img src={m.image} alt="" className="w-full h-full object-cover" />}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <p className="text-sm font-bold text-white truncate">{m.name}</p>
                                                    <p className="text-[10px] text-amber-400/70">Ajouté manuellement</p>
                                                </div>
                                                <button
                                                    onClick={() => toggle(m.id)}
                                                    className="shrink-0"
                                                >
                                                    {isVal
                                                        ? <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                                                        : <Circle className="w-5 h-5 text-slate-600" />
                                                    }
                                                </button>
                                                <button
                                                    onClick={() => removeExtra(m.id)}
                                                    className="text-slate-600 hover:text-rose-400 transition-colors shrink-0"
                                                >
                                                    <X className="w-4 h-4" />
                                                </button>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}

                            {/* Empty state quand aucun inscrit */}
                            {totalListCount === 0 && (
                                <div className="text-center py-4 text-slate-600">
                                    <Circle className="w-8 h-8 mx-auto mb-2 opacity-30" />
                                    <p className="text-sm">Aucun participant inscrit.</p>
                                    <p className="text-xs text-slate-700 mt-1">Tu peux en ajouter ci-dessous.</p>
                                </div>
                            )}

                            {/* ── Ajouter un membre hors-liste ─────────────────────────────── */}
                            <div className="pt-2 border-t border-white/5" ref={dropdownRef}>
                                <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest mb-2 flex items-center gap-1.5">
                                    <UserPlus className="w-3 h-3" />
                                    Ajouter un participant hors-liste
                                </p>
                                <div className="relative">
                                    <button
                                        type="button"
                                        onClick={() => {
                                            setDropdownOpen((v) => !v);
                                            setTimeout(() => searchRef.current?.focus(), 50);
                                        }}
                                        className="w-full flex items-center gap-2 px-3 py-2.5 bg-slate-900/60 border border-white/10 rounded-xl text-sm text-slate-400 hover:border-violet-500/40 hover:text-white transition-all"
                                    >
                                        <Search className="w-4 h-4 shrink-0" />
                                        <span className="flex-1 text-left truncate">
                                            {loadingMembers ? "Chargement…" : "Rechercher un membre de la guilde…"}
                                        </span>
                                        <ChevronDown className={`w-4 h-4 shrink-0 transition-transform ${dropdownOpen ? "rotate-180" : ""}`} />
                                    </button>

                                    <AnimatePresence>
                                        {dropdownOpen && (
                                            <motion.div
                                                initial={{ opacity: 0, y: -4 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                exit={{ opacity: 0, y: -4 }}
                                                transition={{ duration: 0.15 }}
                                                className="absolute z-10 top-full mt-1 w-full bg-zinc-900 border border-white/10 rounded-xl shadow-2xl overflow-hidden"
                                            >
                                                <div className="p-2 border-b border-white/5">
                                                    <div className="flex items-center gap-2 px-2">
                                                        <Search className="w-3 h-3 text-slate-500 shrink-0" />
                                                        <input
                                                            ref={searchRef}
                                                            type="text"
                                                            value={search}
                                                            onChange={(e) => setSearch(e.target.value)}
                                                            placeholder="Nom du membre…"
                                                            className="flex-1 bg-transparent text-sm text-white placeholder-slate-600 outline-none py-1"
                                                        />
                                                    </div>
                                                </div>
                                                <div className="max-h-48 overflow-y-auto">
                                                    {filteredSuggestions.length === 0 ? (
                                                        <p className="text-center text-xs text-slate-600 py-4 italic">
                                                            {search ? "Aucun résultat" : "Tous les membres sont déjà listés"}
                                                        </p>
                                                    ) : (
                                                        filteredSuggestions.map((m) => (
                                                            <button
                                                                key={m.id}
                                                                type="button"
                                                                onClick={() => addExtra(m)}
                                                                className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-white/5 transition-colors text-left"
                                                            >
                                                                <div className="w-7 h-7 rounded-full overflow-hidden bg-slate-700 shrink-0">
                                                                    {m.image && <img src={m.image} alt="" className="w-full h-full object-cover" />}
                                                                </div>
                                                                <span className="text-sm text-white font-medium truncate">{m.name}</span>
                                                            </button>
                                                        ))
                                                    )}
                                                </div>
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>
                            </div>

                            {/* Summary */}
                            {validatedCount > 0 && (
                                <p className="text-[11px] text-slate-500 text-center">
                                    <strong className="text-slate-300">{validatedCount}</strong> membre{validatedCount > 1 ? "s" : ""} recevra{validatedCount > 1 ? "ont" : ""}{" "}
                                    <strong className="text-violet-300">+{pts} point{pts > 1 ? "s" : ""} de contribution</strong>
                                </p>
                            )}
                        </div>

                        {/* Footer */}
                        <div className="px-6 pb-6 pt-4 flex gap-3 border-t border-white/5">
                            <Button
                                variant="ghost"
                                onClick={onClose}
                                disabled={isPending}
                                className="flex-1 border border-white/10 bg-white/5 text-slate-300 hover:text-white hover:bg-white/10 font-bold max-h-12 h-12 transition-all"
                            >
                                Annuler
                            </Button>
                            <Button
                                onClick={handleConfirm}
                                disabled={isPending}
                                className="flex-1 bg-violet-600 hover:bg-violet-500 text-white font-black max-h-12 h-12 shadow-md shadow-violet-900/20"
                            >
                                {isPending ? (
                                    <><Loader2 className="w-5 h-5 mr-2 animate-spin" /> Clôture…</>
                                ) : (
                                    <><ShieldCheck className="w-5 h-5 mr-2" /> Confirmer</>
                                )}
                            </Button>
                        </div>
                    </motion.div>
                </motion.div>
            )}
        </AnimatePresence>
    );
}

"use client";

import { useState, useTransition } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";
import { Pencil, CheckCircle2, CalendarClock, MessageSquare, Users, Swords, ScrollText, Link2 } from "lucide-react";
import { updateDjPost } from "@/server/actions/dungeon-finder-actions";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import type { DjPostWithDetails } from "@/server/actions/dungeon-finder-actions";
import { DateTimePicker } from "@/components/ui/date-time-picker";

interface DjEditModalProps {
    isOpen: boolean;
    post: DjPostWithDetails;
    guildId: string;
    onClose: () => void;
    onSaved: () => void;
}

export function DjEditModal({ isOpen, post, guildId, onClose, onSaved }: DjEditModalProps) {
    const [isPending, startTransition] = useTransition();

    // Pre-fill from existing post
    const [maxMembers, setMaxMembers] = useState(post.maxMembers);
    const [message, setMessage] = useState(post.message ?? "");
    const [targetDate, setTargetDate] = useState(
        post.targetDate ? new Date(post.targetDate).toISOString().slice(0, 16) : ""
    );
    const [selectedAchievements, setSelectedAchievements] = useState<string[]>(
        post.wantedAchievementIds ?? []
    );
    const [requiredClasses, setRequiredClasses] = useState<string[]>(
        post.requiredClasses ?? []
    );

    // Quête manuelle = pas de questId valide
    const isManualQuest = post.mode === "QUETE" && (!post.questId || post.questId <= 0);
    const [questName, setQuestName] = useState(post.questName ?? "");
    const [questUrl, setQuestUrl] = useState(post.questUrl ?? "");

    function toggleAchievement(id: string) {
        setSelectedAchievements(prev =>
            prev.includes(id) ? prev.filter(a => a !== id) : [...prev, id]
        );
    }

    function toggleClass(className: string) {
        setRequiredClasses(prev =>
            prev.includes(className) ? prev.filter(c => c !== className) : [...prev, className]
        );
    }

    function handleSave() {
        if (!targetDate) {
            toast.error("La date prévue est obligatoire.");
            return;
        }
        startTransition(async () => {
            const res = await updateDjPost(guildId, post.id, {
                maxMembers,
                message: message.trim() || null,
                targetDate: new Date(targetDate),
                wantedAchievementIds: selectedAchievements,
                requiredClasses,
                ...(isManualQuest && {
                    questName: questName.trim() || null,
                    questUrl: questUrl.trim() || null,
                }),
            });
            if (res.success) {
                toast.success("Post mis à jour !");
                onSaved();
                onClose();
            } else {
                toast.error(res.error ?? "Erreur lors de la modification.");
            }
        });
    }

    const title = post.mode === "DONJON" ? post.dungeon?.name : post.questName;
    const achievements = post.dungeon?.achievements ?? [];

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="w-[95vw] max-w-lg bg-zinc-950 border border-white/10 shadow-2xl rounded-2xl text-white max-h-[90vh] overflow-y-auto p-0 gap-0 custom-scrollbar">
                {/* Header */}
                <div className="p-5 pb-4 border-b border-white/5 bg-slate-900/30">
                    <DialogTitle className="text-base font-black flex items-center gap-3">
                        <div className="w-8 h-8 rounded-xl bg-indigo-500/20 border border-indigo-500/30 flex items-center justify-center shrink-0 shadow-inner">
                            <Pencil className="w-4 h-4 text-indigo-400" strokeWidth={2.5} />
                        </div>
                        <div>
                            <span className="text-white">Modifier le groupe</span>
                            <p className="text-xs font-medium text-slate-500 mt-0.5 truncate max-w-[300px]">{title}</p>
                        </div>
                    </DialogTitle>
                </div>

                {/* Body */}
                <div className="p-6 space-y-6">
                    {/* Date */}
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-1.5 flex items-center gap-1.5">
                            <CalendarClock className="w-3.5 h-3.5 text-indigo-400" />
                            Date prévue <span className="text-rose-500">*</span>
                            <span className="text-slate-600 font-normal text-[10px] normal-case ml-1">(heure optionnelle)</span>
                        </label>
                        <DateTimePicker
                            value={targetDate}
                            onChange={setTargetDate}
                            minDate={new Date()}
                            timeOptional={true}
                        />
                    </div>

                    {/* Nom et lien quête manuelle */}
                    {isManualQuest && (
                        <div className="p-4 bg-cyan-950/10 border border-cyan-900/30 rounded-xl space-y-4">
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-1.5 flex items-center gap-1.5">
                                    <ScrollText className="w-3.5 h-3.5 text-cyan-400" />
                                    Nom de la quête
                                </label>
                                <input
                                    type="text"
                                    value={questName}
                                    onChange={(e) => setQuestName(e.target.value)}
                                    maxLength={100}
                                    placeholder="Ex : Bijoux de famille"
                                    className="w-full bg-slate-900 border border-white/5 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:ring-1 focus:ring-cyan-500/50 shadow-inner transition-all"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-1.5 flex items-center gap-1.5">
                                    <Link2 className="w-3.5 h-3.5 text-amber-400" />
                                    Tutoriel Noobs
                                    <span className="text-[10px] text-slate-500 font-normal">(optionnel)</span>
                                </label>
                                <input
                                    type="url"
                                    value={questUrl}
                                    onChange={(e) => setQuestUrl(e.target.value)}
                                    placeholder="https://dofuspourlesnoobs.com/quetes/..."
                                    className="w-full bg-slate-900 border border-white/5 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:ring-1 focus:ring-cyan-500/50 shadow-inner transition-all"
                                />
                                {questUrl && !questUrl.includes("dofuspourlesnoobs") && (
                                    <p className="text-xs text-amber-500 font-medium">⚠️ Seuls les liens dofuspourlesnoobs.com sont affichés.</p>
                                )}
                            </div>
                        </div>
                    )}

                    {/* Group size */}
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-1.5 flex items-center gap-1.5">
                            <Users className="w-3.5 h-3.5 text-indigo-400" />
                            Taille du groupe
                        </label>
                        <div className="flex bg-slate-900/80 border border-white/5 rounded-xl p-1 shadow-inner h-12 items-center">
                            {[2, 3, 4, 5, 6, 7, 8].map((n) => (
                                <button
                                    key={n}
                                    onClick={() => setMaxMembers(n)}
                                    className={`flex-1 flex justify-center items-center h-full text-sm font-bold transition-all rounded-lg ${maxMembers === n ? "bg-indigo-500/20 text-indigo-300 border border-indigo-500/20 shadow-sm" : "text-slate-500 hover:text-slate-300 hover:bg-white/5"}`}
                                >
                                    {n}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Achievements */}
                    {post.mode === "DONJON" && achievements.length > 0 && (
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-1.5 flex items-center gap-1.5">
                                <Swords className="w-3.5 h-3.5 text-amber-400" />
                                Succès visés
                            </label>
                            <div className="flex flex-wrap gap-2">
                                {achievements.map((a) => {
                                    const selected = selectedAchievements.includes(a.id);
                                    return (
                                        <button
                                            key={a.id}
                                            onClick={() => toggleAchievement(a.id)}
                                            className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-[11px] font-bold transition-all ${selected
                                                ? "border-amber-500/40 bg-amber-500/10 text-amber-300"
                                                : "border-white/5 bg-slate-900/50 hover:bg-slate-800 text-slate-400 hover:text-slate-300"
                                                }`}
                                        >
                                            {a.challenge.iconUrl && (
                                                <img src={a.challenge.iconUrl} alt="" className="w-4 h-4 object-contain" />
                                            )}
                                            {a.challenge.name}
                                            {selected && <CheckCircle2 className="w-3.5 h-3.5 text-amber-500 ml-1" />}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {/* Required Classes */}
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex justify-between items-center mb-1.5">
                            Classes demandées
                            <span className="text-[10px] text-slate-500 font-normal normal-case">{requiredClasses.length} sélec.</span>
                        </label>
                        <div className="grid grid-cols-9 sm:grid-cols-10 gap-1.5 p-3 rounded-xl bg-slate-900 border border-slate-800">
                            {DOFUS_CLASSES.map((c) => {
                                const isSelected = requiredClasses.includes(c.name);
                                return (
                                    <button
                                        key={c.id}
                                        title={c.name}
                                        onClick={() => toggleClass(c.name)}
                                        className={`aspect-square rounded-lg flex items-center justify-center transition-all border ${isSelected
                                            ? "border-indigo-500/40 bg-indigo-500/20 shadow-inner"
                                            : "border-transparent opacity-40 hover:opacity-100 hover:bg-white/5"
                                            }`}
                                    >
                                        <img
                                            src={c.icon}
                                            alt={c.name}
                                            className="w-6 h-6 object-contain drop-shadow-md"
                                            onError={(e) => (e.currentTarget.style.display = "none")}
                                        />
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Message */}
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest block mb-1.5 flex items-center gap-1.5">
                            <MessageSquare className="w-3.5 h-3.5 text-slate-500" />
                            Message (optionnel)
                        </label>
                        <textarea
                            value={message}
                            onChange={(e) => setMessage(e.target.value)}
                            rows={2}
                            maxLength={500}
                            placeholder="Ex : Je cherche des gens stuffs pour clean vite…"
                            className="w-full bg-slate-900 border border-white/5 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:ring-1 focus:ring-indigo-500/50 shadow-inner resize-none transition-all"
                        />
                        <p className="text-[10px] text-slate-500 text-right font-medium">{message.length}/500</p>
                    </div>
                </div>

                {/* Footer */}
                <div className="px-6 pb-6 flex gap-3 border-t border-white/5 pt-5 bg-slate-900/30">
                    <Button
                        variant="ghost"
                        onClick={onClose}
                        disabled={isPending}
                        className="flex-1 border border-white/10 bg-white/5 text-slate-300 hover:text-white hover:bg-white/10 font-bold h-12 transition-all"
                    >
                        Annuler
                    </Button>
                    <Button
                        onClick={handleSave}
                        disabled={isPending}
                        className="flex-1 bg-indigo-600 hover:bg-indigo-500 text-white font-black h-12 shadow-md shadow-indigo-900/20"
                    >
                        {isPending ? "Sauvegarde…" : "Enregistrer"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useTransition } from "react";
import { motion } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
    Swords, Map, Users, Clock, Calendar, CheckCircle2,
    XCircle, LogIn, LogOut, Crown, Link2
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { closeDjPost, joinDjPost, leaveDjPost } from "@/server/actions/dungeon-finder-actions";
import { DjPostDetailModal } from "./DjPostDetailModal";
import { DjCloseModal } from "./DjCloseModal";
import type { DjPostWithDetails } from "@/server/actions/dungeon-finder-actions";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { getClass } from "@/lib/dofus-assets";

// -------------------------------------------------------
// Constants
// -------------------------------------------------------

const MODE_META: Record<string, { label: string; color: string; icon: React.ElementType }> = {
    DONJON: { label: "Donjon", color: "text-indigo-400 bg-indigo-500/10 border-indigo-500/20", icon: Swords },
    QUETE: { label: "Quête", color: "text-cyan-400 bg-cyan-500/10 border-cyan-500/20", icon: Map },
};

const STATUS_META: Record<string, { label: string; dot: string }> = {
    OPEN: { label: "Ouvert", dot: "bg-emerald-500" },
    FULL: { label: "Complet", dot: "bg-yellow-500" },
    CLOSED: { label: "Fermé", dot: "bg-zinc-500" },
    EXPIRED: { label: "Expiré", dot: "bg-zinc-600" },
};

// -------------------------------------------------------
// DjPostCard
// -------------------------------------------------------

interface DjPostCardProps {
    post: DjPostWithDetails;
    guildId: string;
    currentProfileId?: string;
    isAdmin?: boolean;
    onRefresh: () => void;
    isDiscordConfigured?: boolean;
}

export function DjPostCard({ post, guildId, currentProfileId, isAdmin, onRefresh, isDiscordConfigured }: DjPostCardProps) {
    const [isDetailOpen, setIsDetailOpen] = useState(false);
    const [isCloseModalOpen, setIsCloseModalOpen] = useState(false);
    const [isPending, startTransition] = useTransition();

    const isOwner = post.profileId === currentProfileId;
    const myParticipation = currentProfileId
        ? post.participants.find((p) => p.profile.id === currentProfileId)
        : null;

    const acceptedCount = post._acceptedCount + 1; // +1 creator
    const spotsLeft = post.maxMembers - acceptedCount;

    const modeMeta = MODE_META[post.mode] ?? MODE_META.DONJON;
    const ModIcon = modeMeta.icon;
    const statusMeta = STATUS_META[post.status] ?? STATUS_META.OPEN;

    // Quick-join (no modal)
    function handleQuickJoin() {
        startTransition(async () => {
            const res = await joinDjPost(guildId, post.id, {});
            if (res.success) {
                toast.success("Candidature envoyée !");
                onRefresh();
            } else {
                toast.error(res.error);
            }
        });
    }

    function handleLeave() {
        startTransition(async () => {
            const res = await leaveDjPost(guildId, post.id);
            if (res.success) {
                toast.success("Tu t'es retiré du post.");
                onRefresh();
            } else {
                toast.error(res.error);
            }
        });
    }

    function handleClose() {
        // Admin quick-close (no contribution modal)
        startTransition(async () => {
            const res = await closeDjPost(guildId, post.id);
            if (res.success) {
                toast.success("Post fermé.");
                onRefresh();
            } else {
                toast.error(res.error);
            }
        });
    }

    const title = post.mode === "DONJON" ? post.dungeon?.name : post.questName;
    const subtitle = post.mode === "DONJON" ? `${post.dungeon?.bossName} · Lvl ${post.dungeon?.level}` : "Quête";
    const coverImage = post.dungeon?.imageUrl;

    return (
        <>
            <motion.div
                layout
                initial={{ opacity: 0, y: 16 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className={`group relative rounded-2xl border bg-slate-900/60 backdrop-blur-md overflow-hidden transition-all duration-300 shadow-sm hover:shadow-xl flex flex-col ${post.status === "OPEN"
                    ? "border-white/10 hover:border-indigo-500/40 hover:bg-slate-900/80 h-full"
                    : "border-white/5 opacity-70 h-full"
                    }`}
            >
                {/* Glow accent (top-left) */}
                <div className="absolute -top-8 -left-8 w-32 h-32 rounded-full pointer-events-none"
                    style={{ background: post.status === "OPEN" ? "radial-gradient(circle, rgba(99,102,241,0.1) 0%, transparent 70%)" : "none" }}
                />

                {/* Banner */}
                <div className="relative h-24 bg-slate-950/80 overflow-hidden flex items-center shrink-0 border-b border-white/5">
                    {coverImage && (
                        <img
                            src={coverImage}
                            alt={subtitle}
                            className="absolute inset-0 w-full h-full object-cover opacity-25 scale-105 group-hover:scale-110 transition-transform duration-700"
                        />
                    )}
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/60 to-transparent" />

                    <div className="relative flex items-center gap-4 px-5 w-full">
                        <div className={`w-12 h-12 rounded-xl overflow-hidden shrink-0 flex flex-col items-center justify-center border shadow-lg ${post.mode === "DONJON" ? "bg-slate-800/80 border-white/10" : "bg-cyan-950/80 border-cyan-500/30 shadow-cyan-900/20"}`}>
                            {coverImage ? (
                                <img src={coverImage} alt={subtitle} className="w-full h-full object-cover" />
                            ) : (
                                <ModIcon className={`w-6 h-6 ${post.mode === "DONJON" ? "text-slate-400" : "text-cyan-400"}`} />
                            )}
                        </div>
                        <div className="min-w-0 pr-16 flex-1 drop-shadow-md">
                            <h3 className="font-black text-white text-[15px] truncate leading-tight" title={title || ""}>{title}</h3>
                            <p className="text-xs font-medium text-slate-300 truncate mt-0.5">{subtitle}</p>
                        </div>
                    </div>

                    {/* Status badge */}
                    <div className="absolute top-3 right-3 flex items-center gap-1.5 bg-slate-950/80 px-2.5 py-1 rounded-full border border-white/10 text-[10px] font-black uppercase tracking-wider text-slate-300 backdrop-blur-md">
                        <span className={`w-1.5 h-1.5 rounded-full ${statusMeta.dot} shadow-[0_0_8px_currentColor]`} />
                        {statusMeta.label}
                    </div>
                </div>

                {/* Content */}
                <div className="p-5 flex flex-col flex-1 gap-4">
                    {/* Mode + Slots */}
                    <div className="flex items-center justify-between">
                        <span className={`inline-flex items-center gap-1.5 text-[10px] uppercase font-black tracking-wider px-2.5 py-1 rounded-lg border ${modeMeta.color}`}>
                            <ModIcon className="w-3 h-3" strokeWidth={2.5} />
                            {modeMeta.label}
                        </span>
                        <div className="flex items-center gap-1.5 text-xs font-bold text-slate-400 bg-white/5 px-2.5 py-1 rounded-lg border border-white/5">
                            <Users className="w-3.5 h-3.5 text-slate-300" />
                            <span className={spotsLeft === 0 ? "text-amber-400" : "text-white"}>
                                {acceptedCount}/{post.maxMembers}
                            </span>
                            {spotsLeft > 0 && (
                                <span className="text-emerald-400 ml-1">+{spotsLeft}</span>
                            )}
                        </div>
                    </div>

                    {/* Participants Bubbles */}
                    <div className="flex -space-x-2 overflow-hidden py-1">
                        {/* Leader */}
                        <div key={post.profileId} className="relative group/avatar" title={`${post.profile.pseudoDofus || post.profile.discordNickname} (LEAD)`}>
                            <Avatar className="h-8 w-8 ring-2 ring-indigo-500/50 hover:ring-indigo-400 transition-all border-2 border-slate-950">
                                <AvatarImage src={post.profile.user.image || undefined} />
                                <AvatarFallback className="bg-indigo-950 text-indigo-300 text-[10px] font-black">
                                    {(post.profile.pseudoDofus || post.profile.discordNickname || "??").slice(0, 2).toUpperCase()}
                                </AvatarFallback>
                            </Avatar>
                            <div className="absolute -bottom-1 -right-1 bg-indigo-500 rounded-full p-0.5 border border-slate-950">
                                <Crown className="w-2 h-2 text-white" />
                            </div>
                        </div>

                        {/* Others */}
                        {post.participants.map((p) => (
                            <div key={p.id} className="relative group/avatar" title={p.profile.pseudoDofus || p.profile.discordNickname || "Membre"}>
                                <Avatar className="h-8 w-8 ring-2 ring-slate-800 hover:ring-indigo-500/30 transition-all border-2 border-slate-950">
                                    <AvatarImage src={p.profile.user.image || undefined} />
                                    <AvatarFallback className="bg-slate-800 text-slate-400 text-[10px] font-bold">
                                        {(p.profile.pseudoDofus || p.profile.discordNickname || "??").slice(0, 2).toUpperCase()}
                                    </AvatarFallback>
                                </Avatar>
                            </div>
                        ))}

                        {/* Empty Spots */}
                        {Array.from({ length: spotsLeft }).map((_, i) => (
                            <div key={`empty-${i}`} className="w-8 h-8 rounded-full border-2 border-dashed border-white/10 bg-white/[0.02] flex items-center justify-center">
                                <Users className="w-3 h-3 text-white/5" />
                            </div>
                        ))}
                    </div>

                    {/* Wanted achievements */}
                    {post.wantedAchievementIds.length > 0 && post.dungeon && (
                        <div className="flex gap-1 flex-wrap">
                            {post.dungeon.achievements
                                .filter((a) => post.wantedAchievementIds.includes(a.id))
                                .slice(0, 5)
                                .map((a) => (
                                    <div
                                        key={a.id}
                                        title={a.challenge.name}
                                        className="w-6 h-6 rounded bg-yellow-950/40 border border-yellow-900/40 p-0.5 shrink-0"
                                    >
                                        {a.challenge.iconUrl && (
                                            <img src={a.challenge.iconUrl} alt={a.challenge.name} className="w-full h-full object-contain" />
                                        )}
                                    </div>
                                ))}
                            {post.wantedAchievementIds.length > 5 && (
                                <div className="w-6 h-6 rounded bg-slate-800 flex items-center justify-center text-[9px] text-slate-500 border border-slate-700">
                                    +{post.wantedAchievementIds.length - 5}
                                </div>
                            )}
                        </div>
                    )}

                    {/* Required Classes */}
                    {post.requiredClasses && post.requiredClasses.length > 0 && (
                        <div className="flex flex-wrap gap-1">
                            {post.requiredClasses.map(c => {
                                const cls = getClass(c);
                                return (
                                    <div key={c} title={c} className="w-6 h-6 rounded-md bg-indigo-950/30 border border-indigo-900/30 p-0.5 overflow-hidden">
                                        {cls ? (
                                            <img src={cls.icon} alt={c} className="w-full h-full object-contain" />
                                        ) : (
                                            <span className="text-[8px] font-bold flex items-center justify-center h-full w-full rounded text-white"
                                                style={{ backgroundColor: `hsl(${(c.charCodeAt(0) * 47) % 360}, 55%, 35%)` }}>
                                                {c[0]?.toUpperCase()}
                                            </span>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    )}

                    {/* Quest link — Quête MANUELLE avec lien dofuspourlesnoobs */}
                    {post.mode === "QUETE" && (!post.questId || post.questId <= 0) && post.questUrl && post.questUrl.includes("dofuspourlesnoobs") && (
                        <a href={post.questUrl} target="_blank" rel="noopener noreferrer"
                            onClick={(e) => e.stopPropagation()}
                            className="inline-flex items-center gap-1.5 text-xs text-amber-400 hover:text-amber-300 font-medium bg-amber-950/20 border border-amber-900/30 rounded-lg px-2 py-1.5 w-max transition-colors">
                            <Link2 className="w-3.5 h-3.5 shrink-0" />
                            Voir la quête
                        </a>
                    )}

                    {/* Quest link — DofusDB (questId connu et valide) */}
                    {post.questId && post.questId > 0 && (post.mode === "QUETE" || post.mode === "DONJON") && (
                        <a href={`https://dofusdb.fr/fr/database/quest/${post.questId}`} target="_blank" rel="noopener noreferrer"
                            onClick={(e) => e.stopPropagation()}
                            className={`inline-flex items-center gap-1.5 text-[11px] font-medium rounded-lg px-2 py-1.5 w-max transition-colors border ${post.mode === "DONJON"
                                ? "text-cyan-400 hover:text-cyan-300 bg-cyan-500/5 border-cyan-500/20"
                                : "text-slate-400 hover:text-white bg-white/5 border-white/10"
                                }`}>
                            <Map className="w-3 h-3" />
                            {post.mode === "DONJON" && post.questName
                                ? <span className="truncate max-w-[120px]">{post.questName}</span>
                                : "Ouvrir sur DofusDB"
                            }
                        </a>
                    )}

                    {/* Message */}
                    {post.message && (
                        <div className="text-xs text-slate-300 italic border-l-2 border-indigo-500/50 pl-3 py-0.5 line-clamp-2 leading-relaxed opacity-90">
                            "{post.message}"
                        </div>
                    )}

                    <div className="flex-1" /> {/* Spacer */}

                    {/* Target date */}
                    {post.targetDate && (
                        <div className="flex items-center justify-center gap-2 text-[11px] text-indigo-200 font-bold bg-indigo-500/10 w-full px-3 py-2 rounded-xl border border-indigo-500/20">
                            <Calendar className="w-3.5 h-3.5 shrink-0 text-indigo-400" />
                            {new Date(post.targetDate).toLocaleDateString("fr-FR", {
                                weekday: "short", day: "numeric", month: "long", hour: "2-digit", minute: "2-digit"
                            }).replace(/, /g, " à ")}
                        </div>
                    )}

                    {/* Creator Header (pushed to bottom) */}
                    <div className="flex items-center gap-3 pt-4 border-t border-white/10 mt-2">
                        <div className="w-5 h-5 rounded-full overflow-hidden bg-slate-700 shrink-0 ring-1 ring-white/10">
                            {post.profile.user.image && (
                                <img src={post.profile.user.image} alt="" className="w-full h-full object-cover" />
                            )}
                        </div>
                        <span className="text-[11px] font-bold text-slate-300 truncate flex-1">
                            {isOwner && <Crown className="w-3 h-3 inline mr-1 text-yellow-500/80 -mt-0.5" />}
                            {post.profile.pseudoDofus || post.profile.discordNickname || "Inconnu"}
                        </span>
                        <span className="text-[10px] text-slate-500 flex items-center gap-1 shrink-0 font-medium">
                            <Clock className="w-2.5 h-2.5" />
                            {formatDistanceToNow(new Date(post.createdAt), { locale: fr, addSuffix: true })}
                        </span>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-2 pt-1">
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setIsDetailOpen(true)}
                            className="flex-1 h-9 text-xs font-bold bg-white/5 hover:bg-white/10 border border-white/5 text-slate-300"
                        >
                            Détails
                        </Button>

                        {post.status === "OPEN" && !isOwner && !myParticipation && (
                            <Button
                                size="sm"
                                onClick={handleQuickJoin}
                                disabled={isPending}
                                className={`flex-1 h-9 text-xs font-black text-white shadow-md ${post.mode === "DONJON" ? "bg-indigo-600 hover:bg-indigo-500" : "bg-cyan-600 hover:bg-cyan-500"}`}
                            >
                                <LogIn className="w-3.5 h-3.5 mr-1" />
                                Rejoindre
                            </Button>
                        )}

                        {myParticipation && myParticipation.status === "PENDING" && (
                            <Button
                                size="sm"
                                variant="outline"
                                onClick={handleLeave}
                                disabled={isPending}
                                className="flex-1 h-9 text-xs font-bold border-rose-900/50 text-rose-400 hover:text-rose-300 hover:bg-rose-950/30"
                            >
                                <LogOut className="w-3.5 h-3.5 mr-1" />
                                Annuler
                            </Button>
                        )}

                        {myParticipation?.status === "ACCEPTED" && (
                            <Badge className="flex-1 justify-center h-8 bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 font-bold text-[11px]">
                                <CheckCircle2 className="w-3 h-3 mr-1" /> Accepté
                            </Badge>
                        )}

                        {myParticipation?.status === "REJECTED" && (
                            <Badge className="flex-1 justify-center h-8 bg-red-500/10 text-red-400 border border-red-500/20 font-bold text-[11px]">
                                <XCircle className="w-3 h-3 mr-1" /> Refusé
                            </Badge>
                        )}

                        {isOwner && post.status === "OPEN" && (
                            <div className="flex flex-1 gap-2">
                                <Button
                                    size="sm"
                                    onClick={() => setIsCloseModalOpen(true)}
                                    disabled={isPending}
                                    title="Valider et donner des points"
                                    className="flex-1 h-8 text-[10px] font-black uppercase tracking-tight bg-violet-600/20 hover:bg-violet-600/40 text-violet-300 border border-violet-500/30 hover:border-violet-500/50"
                                >
                                    <CheckCircle2 className="w-3 h-3 mr-1" />
                                    Terminer
                                </Button>
                                <Button
                                    size="sm"
                                    variant="outline"
                                    onClick={handleClose}
                                    disabled={isPending}
                                    title="Fermer sans donner de points"
                                    className="h-8 px-2 text-[10px] font-bold border-rose-900/50 text-rose-400 hover:text-rose-300 hover:bg-rose-950/30"
                                >
                                    <XCircle className="w-3 h-3 h-3" />
                                </Button>
                            </div>
                        )}
                        {isAdmin && !isOwner && post.status === "OPEN" && (
                            <Button
                                size="sm"
                                variant="outline"
                                onClick={handleClose}
                                disabled={isPending}
                                className="flex-1 h-8 text-xs font-bold border-slate-700 text-slate-500 hover:text-red-400 hover:border-red-900"
                            >
                                <XCircle className="w-3 h-3 mr-1" />
                                Fermer
                            </Button>
                        )}
                    </div>
                </div>
            </motion.div>

            <DjPostDetailModal
                isOpen={isDetailOpen}
                onClose={() => setIsDetailOpen(false)}
                post={post}
                guildId={guildId}
                currentProfileId={currentProfileId}
                isAdmin={isAdmin}
                onRefresh={onRefresh}
            />

            {isOwner && (
                <DjCloseModal
                    isOpen={isCloseModalOpen}
                    post={post}
                    guildId={guildId}
                    onClose={() => setIsCloseModalOpen(false)}
                    onClosed={onRefresh}
                />
            )}
        </>
    );
}

"use client";

import { cn } from "@/lib/utils";


import { useState, useEffect, useTransition, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";
import {
    Plus, Search, Swords, Map,
    Users, CheckCircle2, X, Trophy, ChevronsUpDown, Check
} from "lucide-react";
import { createDjPost } from "@/server/actions/dungeon-finder-actions";
import { getDungeonsWithAchievements } from "@/server/actions/game-data-actions";
import { getDiscordRolesAction } from "@/server/actions/user-actions";
import { Switch } from "@/components/ui/switch";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { DateTimePicker } from "@/components/ui/date-time-picker";

interface Dungeon {
    id: string;
    name: string;
    bossName: string;
    level: number;
    imageUrl?: string | null;
    isExpedition: boolean;
    achievements: {
        id: string;
        points: number;
        challenge: { id: string; name: string; iconUrl?: string | null };
    }[];
}

interface DjPostCreateModalProps {
    guildId: string;
    isOpen: boolean;
    initialDungeonId?: string;
    isDiscordConfigured?: boolean;
    onClose: () => void;
    onCreated: () => void;
}

export function DjPostCreateModal({ guildId, isOpen, initialDungeonId, isDiscordConfigured, onClose, onCreated }: DjPostCreateModalProps) {
    // Top-Level Mode
    const [mode, setMode] = useState<"DONJON" | "QUETE">("DONJON");

    // Donjons
    const [dungeons, setDungeons] = useState<Dungeon[]>([]);
    const [loadingDungeons, setLoadingDungeons] = useState(false);
    const [dungeonSearch, setDungeonSearch] = useState("");
    const [selectedDungeon, setSelectedDungeon] = useState<Dungeon | null>(null);
    const [selectedAchievements, setSelectedAchievements] = useState<string[]>([]);

    // Quêtes
    const [questSearchQuery, setQuestSearchQuery] = useState("");
    const [questSearchResults, setQuestSearchResults] = useState<any[]>([]);
    const [isSearchingQuests, setIsSearchingQuests] = useState(false);
    const [selectedQuest, setSelectedQuest] = useState<{ id: number; name: string } | null>(null);
    const [questUrl, setQuestUrl] = useState("");

    // Optional quest linked to a DONJON post
    const [showLinkedQuest, setShowLinkedQuest] = useState(false);
    const [linkedQuestSearch, setLinkedQuestSearch] = useState("");
    const [linkedQuestResults, setLinkedQuestResults] = useState<any[]>([]);
    const [isSearchingLinkedQuest, setIsSearchingLinkedQuest] = useState(false);
    const [linkedQuest, setLinkedQuest] = useState<{ id: number; name: string } | null>(null);

    // Shared Config
    const [step, setStep] = useState(1); // 1 = Search (Donjon/Quete), 2 = Config
    const [maxMembers, setMaxMembers] = useState(4);
    const [message, setMessage] = useState("");
    const [targetDate, setTargetDate] = useState("");
    const [requiredClasses, setRequiredClasses] = useState<string[]>([]);
    const [isDiscordPublished, setIsDiscordPublished] = useState(false);
    const [mentionRoleId, setMentionRoleId] = useState<string | null>(null);
    const [discordRoles, setDiscordRoles] = useState<{ id: string, name: string, color: string }[]>([]);
    const [isLoadingRoles, setIsLoadingRoles] = useState(false);
    const [roleOpen, setRoleOpen] = useState(false);

    const [isPending, startTransition] = useTransition();

    // Reset all state on open, and re-check isDiscordConfigured when it changes
    useEffect(() => {
        if (isOpen) {
            setStep(1);
            setMode("DONJON");
            setDungeonSearch("");
            setSelectedDungeon(null);
            setSelectedAchievements([]);
            setQuestSearchQuery("");
            setQuestSearchResults([]);
            setSelectedQuest(null);
            setQuestUrl("");
            setShowLinkedQuest(false);
            setLinkedQuestSearch("");
            setLinkedQuestResults([]);
            setLinkedQuest(null);
            setMaxMembers(4);
            setMessage("");
            setTargetDate("");
            setRequiredClasses([]);
            setIsDiscordPublished(isDiscordConfigured === true);
            setMentionRoleId(null);
        }
    }, [isOpen, isDiscordConfigured]);

    // Fetch Discord Roles
    useEffect(() => {
        if (isOpen && isDiscordPublished && discordRoles.length === 0) {
            setIsLoadingRoles(true);
            getDiscordRolesAction(guildId)
                .then(res => {
                    if (res.success && res.roles) {
                        // Filter out @everyone if possible or just keep all
                        setDiscordRoles(res.roles.filter(r => r.name !== "@everyone") as any);
                    }
                })
                .catch(console.error)
                .finally(() => setIsLoadingRoles(false));
        }
    }, [isOpen, isDiscordPublished, guildId, discordRoles.length]);

    // Handle initialDungeonId when dungeons are loaded
    useEffect(() => {
        if (isOpen && initialDungeonId && dungeons.length > 0) {
            const found = dungeons.find(d => d.id === initialDungeonId);
            if (found) {
                setMode("DONJON");
                setSelectedDungeon(found);
                setStep(2); // Jump directly to config
            }
        }
    }, [isOpen, initialDungeonId, dungeons]);

    // Fetch Dungeons on open
    useEffect(() => {
        if (isOpen && dungeons.length === 0) {
            setLoadingDungeons(true);
            getDungeonsWithAchievements()
                .then(res => { if (res.success && res.data) setDungeons(res.data); })
                .catch(console.error)
                .finally(() => setLoadingDungeons(false));
        }
    }, [isOpen, dungeons.length]);

    // DofusDB Quest search debounce
    useEffect(() => {
        if (mode !== "QUETE" || questSearchQuery.trim().length < 3) {
            setQuestSearchResults([]);
            return;
        }

        const controller = new AbortController();
        setIsSearchingQuests(true);

        const timer = setTimeout(() => {
            fetch(`https://api.dofusdb.fr/quests?name.fr[$regex]=${encodeURIComponent(questSearchQuery)}&$limit=8`, {
                signal: controller.signal
            })
                .then(res => {
                    if (!res.ok) throw new Error("API DofusDB indisponible");
                    return res.json();
                })
                .then(data => {
                    if (data.data) setQuestSearchResults(data.data);
                })
                .catch(err => {
                    if (err.name !== "AbortError") console.error("Erreur DofusDB:", err);
                })
                .finally(() => setIsSearchingQuests(false));
        }, 400);

        return () => {
            clearTimeout(timer);
            controller.abort();
        };
    }, [questSearchQuery, mode]);

    // Linked quest search (DONJON mode optional quest)
    useEffect(() => {
        if (!showLinkedQuest || linkedQuestSearch.trim().length < 3) {
            setLinkedQuestResults([]);
            return;
        }
        const controller = new AbortController();
        setIsSearchingLinkedQuest(true);
        const timer = setTimeout(() => {
            fetch(`https://api.dofusdb.fr/quests?name.fr[$regex]=${encodeURIComponent(linkedQuestSearch)}&$limit=6`, {
                signal: controller.signal
            })
                .then(res => res.json())
                .then(data => { if (data.data) setLinkedQuestResults(data.data); })
                .catch(err => { if (err.name !== "AbortError") console.error(err); })
                .finally(() => setIsSearchingLinkedQuest(false));
        }, 400);
        return () => { clearTimeout(timer); controller.abort(); };
    }, [linkedQuestSearch, showLinkedQuest]);

    const filteredDungeons = useMemo(() => {
        if (!dungeonSearch.trim()) return dungeons;
        const q = dungeonSearch.toLowerCase();
        return dungeons.filter(d =>
            d.name.toLowerCase().includes(q) ||
            d.bossName.toLowerCase().includes(q)
        );
    }, [dungeons, dungeonSearch]);

    function handleClose() {
        if (!isPending) onClose();
    }

    function toggleAchievement(id: string) {
        setSelectedAchievements(prev =>
            prev.includes(id) ? prev.filter(a => a !== id) : [...prev, id]
        );
    }

    function toggleClass(className: string) {
        setRequiredClasses(prev =>
            prev.includes(className) ? prev.filter(c => c !== className) : [...prev, className]
        );
    }

    async function handleSubmit() {
        if (mode === "DONJON" && !selectedDungeon) {
            toast.error("Veuillez sélectionner un donjon.");
            return;
        }
        if (mode === "QUETE" && !selectedQuest) {
            toast.error("Veuillez choisir ou saisir manuellement une quête.");
            return;
        }
        if (!targetDate) {
            toast.error("Veuillez définir une date et une heure prévues.");
            return;
        }

        startTransition(async () => {
            const res = await createDjPost(guildId, {
                mode,
                dungeonId: mode === "DONJON" ? selectedDungeon!.id : null,
                questId: mode === "QUETE" ? selectedQuest!.id : (linkedQuest ? linkedQuest.id : null),
                questName: mode === "QUETE" ? selectedQuest!.name : (linkedQuest ? linkedQuest.name : null),
                questUrl: mode === "QUETE" && questUrl ? questUrl : null,
                wantedAchievementIds: mode === "DONJON" ? selectedAchievements : [],
                maxMembers,
                message: message ? message : null,
                targetDate: targetDate ? new Date(targetDate) : null,
                requiredClasses,
                isDiscordPublished,
                mentionRoleId,
            });

            if (res.success) {
                toast.success("Votre recherche de groupe est en ligne !");
                handleClose();
                onCreated();
            } else {
                toast.error(res.error || "Erreur lors de la publication.");
            }
        });
    }

    return (
        <Dialog open={isOpen} onOpenChange={handleClose}>
            <DialogContent className="w-[95vw] max-w-2xl bg-zinc-950 border border-white/10 shadow-2xl rounded-2xl text-white max-h-[90vh] overflow-y-auto p-0 gap-0 custom-scrollbar">
                <div className="p-6 pb-4 border-b border-white/5 bg-zinc-900/40 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/5 blur-3xl rounded-full -mr-16 -mt-16" />
                    <DialogTitle className="text-xl font-black flex items-center gap-3 relative z-10">
                        <div className="w-10 h-10 rounded-2xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center shadow-lg shadow-amber-900/10">
                            <Plus className="w-5 h-5 text-amber-500" />
                        </div>
                        <div className="flex flex-col">
                            <span className="text-xl tracking-tight text-white leading-none">
                                {mode === "DONJON" ? "Nouveau Groupe Donjon" : "Nouveau Groupe Quête"}
                            </span>
                            <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest mt-1">
                                Planifier une session de guilde
                            </span>
                        </div>
                    </DialogTitle>
                </div>

                {/* Content Area */}
                <div className="p-6">
                    <AnimatePresence mode="wait">
                        {step === 1 && (
                            <motion.div key="step1" initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.98 }} className="space-y-6">
                                {/* Mode Selector - Refined */}
                                <div className="grid grid-cols-2 bg-zinc-900/80 border border-white/5 p-1 rounded-2xl w-full shadow-inner relative overflow-hidden">
                                    <div className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-zinc-800 border border-white/10 rounded-xl transition-all duration-500 ease-out z-0 ${mode === "QUETE" ? "translate-x-full" : "translate-x-0"}`} />
                                    <button
                                        onClick={() => setMode("DONJON")}
                                        className={`relative z-10 flex items-center justify-center gap-2 py-3 text-sm font-bold transition-all ${mode === "DONJON" ? "text-white" : "text-zinc-500 hover:text-zinc-300"}`}
                                    >
                                        <Swords className={`w-4 h-4 transition-colors ${mode === "DONJON" ? "text-amber-500" : ""}`} />
                                        Mode Donjons
                                    </button>
                                    <button
                                        onClick={() => setMode("QUETE")}
                                        className={`relative z-10 flex items-center justify-center gap-2 py-3 text-sm font-bold transition-all ${mode === "QUETE" ? "text-white" : "text-zinc-500 hover:text-zinc-300"}`}
                                    >
                                        <Map className={`w-4 h-4 transition-colors ${mode === "QUETE" ? "text-emerald-500" : ""}`} />
                                        Mode Quêtes
                                    </button>
                                </div>

                                {/* Donjon Search */}
                                {mode === "DONJON" && (
                                    <div className="space-y-4">
                                        <div className="relative group">
                                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 group-focus-within:text-amber-500 transition-colors" />
                                            <input
                                                autoFocus
                                                type="text"
                                                value={dungeonSearch}
                                                onChange={(e) => setDungeonSearch(e.target.value)}
                                                placeholder="Rechercher un donjon ou un boss..."
                                                className="w-full bg-zinc-900 border border-white/5 rounded-2xl pl-11 pr-4 py-4 text-sm text-white focus:outline-none focus:border-amber-500/50 focus:ring-4 focus:ring-amber-500/5 transition-all placeholder:text-zinc-600 shadow-xl"
                                            />
                                        </div>

                                        {loadingDungeons ? (
                                            <div className="py-16 text-center text-zinc-500 animate-pulse bg-zinc-900/30 rounded-3xl border border-white/5">
                                                Consultation du bestiaire...
                                            </div>
                                        ) : (
                                            <div className="h-72 overflow-y-auto space-y-2 pr-2 custom-scrollbar p-1">
                                                {filteredDungeons.length === 0 ? (
                                                    <div className="text-center py-20 bg-zinc-900/30 rounded-3xl border border-white/5 border-dashed">
                                                        <Search className="w-8 h-8 mx-auto mb-3 text-zinc-700 opacity-50" />
                                                        <p className="text-zinc-500 text-sm">Aucun donjon trouvé pour "{dungeonSearch}"</p>
                                                    </div>
                                                ) : filteredDungeons.map((d) => (
                                                    <button
                                                        key={d.id}
                                                        onClick={() => { setSelectedDungeon(d); setStep(2); }}
                                                        className="w-full flex items-center gap-4 p-3 rounded-2xl bg-zinc-900/40 border border-white/5 hover:border-amber-500/30 hover:bg-zinc-800 transition-all group text-left relative overflow-hidden"
                                                    >
                                                        <div className="absolute inset-0 bg-gradient-to-r from-amber-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                                                        <div className="w-12 h-12 rounded-xl overflow-hidden bg-zinc-950 border border-white/10 shrink-0 relative z-10">
                                                            {d.imageUrl
                                                                ? <img src={d.imageUrl} alt={d.bossName} className="w-full h-full object-contain p-1 group-hover:scale-110 transition-transform duration-500" />
                                                                : <div className="w-full h-full flex items-center justify-center text-zinc-600"><Swords className="w-6 h-6" /></div>}
                                                        </div>
                                                        <div className="flex-1 min-w-0 relative z-10">
                                                            <div className="flex items-center gap-2">
                                                                <p className="text-sm font-black text-zinc-200 group-hover:text-white transition-colors truncate">{d.name}</p>
                                                                <span className="text-[9px] font-black bg-amber-500/10 text-amber-500 px-1.5 py-0.5 rounded border border-amber-500/20 shrink-0">Lvl {d.level}</span>
                                                            </div>
                                                            <p className="text-xs text-zinc-500 mt-0.5 truncate group-hover:text-zinc-400">{d.bossName}</p>
                                                        </div>
                                                        <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all group-hover:translate-x-0 translate-x-4 relative z-10 border border-white/10">
                                                            <Plus className="w-4 h-4 text-white" />
                                                        </div>
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                )}

                                {/* Quête Search */}
                                {mode === "QUETE" && (
                                    <div className="space-y-4">
                                        <div className="space-y-4 p-4 bg-slate-900 rounded-xl border border-slate-800">
                                            <div className="relative z-50">
                                                <p className="text-sm font-bold text-slate-300 mb-2">Rechercher une quête</p>

                                                {selectedQuest ? (
                                                    <div className="flex items-center justify-between bg-indigo-500/10 border border-indigo-500/30 rounded-lg p-3">
                                                        <div className="flex items-center gap-3 min-w-0">
                                                            <CheckCircle2 className="w-5 h-5 text-indigo-400 shrink-0" />
                                                            <span className="text-sm font-bold text-indigo-100 truncate">{selectedQuest.name}</span>
                                                            {selectedQuest.id === -1 && <span className="text-[10px] bg-slate-800 px-2 py-0.5 rounded text-slate-400 font-mono border border-slate-700 shrink-0">Saisie Libre</span>}
                                                        </div>
                                                        <Button variant="ghost" size="sm" onClick={() => setSelectedQuest(null)} className="text-slate-400 hover:text-white shrink-0 ml-2">Modifier</Button>
                                                    </div>
                                                ) : (
                                                    <div className="relative">
                                                        <Search className="absolute left-3 top-3 w-4 h-4 text-slate-500" />
                                                        <input
                                                            autoFocus
                                                            type="text"
                                                            value={questSearchQuery}
                                                            onChange={(e) => setQuestSearchQuery(e.target.value)}
                                                            placeholder="Ex: L'Étoile du Gerbé..."
                                                            className="w-full bg-slate-900 border border-white/5 rounded-lg pl-9 pr-4 py-3 text-sm text-white focus:outline-none focus:ring-1 focus:ring-cyan-500/50 transition-all placeholder:text-slate-600 shadow-inner"
                                                        />

                                                        {questSearchQuery.trim().length > 0 && (
                                                            <div className="mt-3 bg-slate-900/50 border border-slate-800 rounded-xl overflow-hidden custom-scrollbar max-h-64 overflow-y-auto relative shadow-inner">
                                                                <button
                                                                    onClick={() => setSelectedQuest({ id: -1, name: questSearchQuery.trim() })}
                                                                    className="w-full text-left px-4 py-3 text-sm font-bold text-indigo-400 bg-indigo-950/20 hover:bg-indigo-900/40 transition-colors border-b border-slate-700/50 flex items-center gap-2"
                                                                >
                                                                    <Plus className="w-4 h-4" />
                                                                    Saisir manuellement "{questSearchQuery}"
                                                                </button>

                                                                {questSearchQuery.length >= 3 && (
                                                                    <>
                                                                        {isSearchingQuests && <div className="p-4 text-sm text-slate-400 flex items-center gap-2"><div className="w-4 h-4 border-2 border-slate-500 border-t-indigo-500 rounded-full animate-spin" /> Recherche Base de Données...</div>}

                                                                        {!isSearchingQuests && questSearchResults.length === 0 && (
                                                                            <div className="p-4 text-sm text-slate-500">Aucune quête officielle trouvée sur DofusDB.</div>
                                                                        )}

                                                                        {!isSearchingQuests && questSearchResults.map(q => (
                                                                            <button
                                                                                key={q.id}
                                                                                onClick={() => setSelectedQuest({ id: q.id, name: q.name?.fr || "" })}
                                                                                className="w-full text-left px-4 py-3 text-sm text-slate-300 hover:bg-slate-700 hover:text-white transition-colors border-b border-slate-700/50 last:border-0 flex gap-3 truncate"
                                                                            >
                                                                                <span className="text-slate-500 font-mono text-[10px] w-10 shrink-0 pt-0.5">#{q.id}</span>
                                                                                <span className="truncate block font-medium">{q.name?.fr}</span>
                                                                            </button>
                                                                        ))}
                                                                    </>
                                                                )}
                                                            </div>
                                                        )}
                                                    </div>
                                                )}
                                            </div>
                                        </div>

                                        <Button
                                            className="w-full h-12 text-sm bg-indigo-600 hover:bg-indigo-500 font-bold disabled:opacity-50"
                                            disabled={!selectedQuest}
                                            onClick={() => setStep(2)}
                                        >
                                            Suivant
                                        </Button>
                                    </div>
                                )}
                            </motion.div>
                        )}

                        {step === 2 && (
                            <motion.div key="step2" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} className="space-y-6">
                                {/* Header Recap - Refined */}
                                <div className="flex items-center gap-4 bg-zinc-900/60 rounded-3xl p-5 border border-white/10 shadow-xl relative overflow-hidden group">
                                    <div className="absolute inset-0 bg-gradient-to-r from-amber-500/5 to-transparent opacity-50" />
                                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 border relative z-10 ${mode === "DONJON" ? "bg-zinc-950 border-white/10" : "bg-emerald-950/30 border-emerald-500/20"}`}>
                                        {mode === "DONJON" && selectedDungeon?.imageUrl ? (
                                            <img src={selectedDungeon.imageUrl} alt="" className="w-10 h-10 object-contain group-hover:scale-110 transition-transform duration-500" />
                                        ) : mode === "DONJON" ? (
                                            <Swords className="w-6 h-6 text-zinc-500" />
                                        ) : (
                                            <Map className="w-6 h-6 text-emerald-500" />
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0 relative z-10">
                                        <p className="font-black text-white text-lg tracking-tight truncate leading-tight">
                                            {mode === "DONJON" ? selectedDungeon?.name : selectedQuest?.name}
                                        </p>
                                        <div className="flex items-center gap-2 mt-1">
                                            {mode === "DONJON" ? (
                                                <>
                                                    <span className="text-[10px] font-black bg-amber-500/10 text-amber-500 px-1.5 py-0.5 rounded border border-amber-500/20">NIVEAU {selectedDungeon?.level}</span>
                                                    <span className="text-[11px] font-medium text-zinc-500 truncate">{selectedDungeon?.bossName}</span>
                                                </>
                                            ) : (
                                                <span className="text-[10px] font-black bg-emerald-500/10 text-emerald-500 px-1.5 py-0.5 rounded border border-emerald-500/20 uppercase tracking-widest">GROUPE QUÊTE</span>
                                            )}
                                        </div>
                                    </div>
                                    <Button variant="ghost" size="sm" onClick={() => setStep(1)} className="h-9 px-4 rounded-xl text-xs font-black text-zinc-500 hover:text-white bg-white/5 hover:bg-white/10 shrink-0 relative z-10">
                                        RETOUR
                                    </Button>
                                </div>

                                {/* Dynamic Fields depending on Mode */}
                                {mode === "DONJON" && selectedDungeon?.achievements.length ? (
                                    <div className="space-y-3">
                                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Succès visés (optionnel)</p>
                                        <div className="grid grid-cols-2 gap-2">
                                            {selectedDungeon.achievements.map((a) => {
                                                const selected = selectedAchievements.includes(a.id);
                                                return (
                                                    <button
                                                        key={a.id}
                                                        onClick={() => toggleAchievement(a.id)}
                                                        className={`flex items-center gap-3 px-3 py-2.5 rounded-xl border text-[11px] font-bold transition-all ${selected
                                                            ? "border-amber-500/40 bg-amber-500/10 text-amber-100 shadow-lg shadow-amber-900/5"
                                                            : "border-white/5 bg-zinc-900/50 hover:bg-zinc-800 text-zinc-400 hover:text-zinc-200"
                                                            }`}
                                                    >
                                                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 border ${selected ? "bg-amber-500/20 border-amber-500/20" : "bg-zinc-950 border-white/5"}`}>
                                                            {a.challenge.iconUrl ? <img src={a.challenge.iconUrl} alt="" className="w-5 h-5 object-contain" /> : <Trophy className="w-4 h-4" />}
                                                        </div>
                                                        <span className="flex-1 text-left truncate">{a.challenge.name}</span>
                                                        {selected && <CheckCircle2 className="w-3.5 h-3.5 text-amber-500" />}
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    </div>
                                ) : mode === "QUETE" && (
                                    <div className="space-y-3">
                                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Lien vers un Tutoriel (Optionnel)</p>
                                        <div className="relative group">
                                            <Map className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 group-focus-within:text-emerald-500 transition-colors" />
                                            <input
                                                type="url"
                                                value={questUrl}
                                                onChange={(e) => setQuestUrl(e.target.value)}
                                                placeholder="Ex: https://www.dofuspourlesnoobs.com/..."
                                                className="w-full bg-zinc-900 border border-white/5 rounded-xl pl-11 pr-4 py-4 text-sm text-white focus:outline-none focus:ring-1 focus:ring-emerald-500/50 transition-all placeholder:text-zinc-700 shadow-xl"
                                            />
                                        </div>
                                    </div>
                                )}

                                {/* Optional linked quest for DONJON mode */}
                                {mode === "DONJON" && (
                                    <div className="space-y-2">
                                        <button
                                            type="button"
                                            onClick={() => { setShowLinkedQuest(v => !v); setLinkedQuest(null); setLinkedQuestSearch(""); }}
                                            className="flex items-center gap-2 text-xs font-bold text-slate-500 hover:text-cyan-400 transition-colors"
                                        >
                                            <Map className="w-3.5 h-3.5" />
                                            {showLinkedQuest ? "▼ Masquer la quête liée" : "▶ Associer une quête (optionnel)"}
                                        </button>
                                        {showLinkedQuest && (
                                            <div className="bg-slate-900/60 border border-slate-700/60 rounded-xl p-3 space-y-2">
                                                {linkedQuest ? (
                                                    <div className="flex items-center justify-between bg-cyan-500/10 border border-cyan-500/20 rounded-lg px-3 py-2">
                                                        <span className="text-sm text-cyan-300 font-medium flex items-center gap-2">
                                                            <Map className="w-3.5 h-3.5" />
                                                            {linkedQuest.name}
                                                        </span>
                                                        <button onClick={() => setLinkedQuest(null)} className="text-slate-500 hover:text-red-400 text-xs">✕</button>
                                                    </div>
                                                ) : (
                                                    <>
                                                        <input
                                                            type="text"
                                                            value={linkedQuestSearch}
                                                            onChange={e => setLinkedQuestSearch(e.target.value)}
                                                            placeholder="Rechercher une quête sur DofusDB..."
                                                            className="w-full bg-slate-900 border border-white/5 rounded-lg px-3 py-2.5 text-sm text-white focus:outline-none focus:ring-1 focus:ring-cyan-500/50 transition-all placeholder:text-slate-600 shadow-inner"
                                                        />
                                                        {isSearchingLinkedQuest && <p className="text-xs text-slate-500 animate-pulse">Recherche...</p>}
                                                        {linkedQuestResults.length > 0 && (
                                                            <div className="space-y-1 max-h-32 overflow-y-auto">
                                                                {linkedQuestResults.map(q => (
                                                                    <button key={q.id} type="button"
                                                                        onClick={() => { setLinkedQuest({ id: q.id, name: q.name?.fr || "" }); setLinkedQuestResults([]); setLinkedQuestSearch(""); }}
                                                                        className="w-full text-left px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-sm text-slate-300 transition-colors"
                                                                    >
                                                                        {q.name?.fr}
                                                                        {q.levelMin && <span className="text-xs text-slate-500 ml-2">Niv. {q.levelMin}</span>}
                                                                    </button>
                                                                ))}
                                                            </div>
                                                        )}
                                                    </>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                )}

                                {/* Date & Membres */}
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                    <div className="space-y-3">
                                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Date & Heure prévue</p>
                                        <DateTimePicker
                                            value={targetDate}
                                            onChange={setTargetDate}
                                            minDate={new Date()}
                                            placeholder="Choisir date & heure"
                                            timeOptional={true}
                                        />
                                    </div>
                                    <div className="space-y-3">
                                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Taille du groupe</p>
                                        <div className="flex bg-zinc-900 border border-white/5 rounded-2xl p-1 shadow-inner h-[52px] items-center">
                                            {[2, 3, 4, 5, 6, 7, 8].map((n) => (
                                                <button
                                                    key={n}
                                                    onClick={() => setMaxMembers(n)}
                                                    className={`flex-1 flex justify-center items-center h-full text-xs font-black transition-all rounded-xl ${maxMembers === n ? "bg-zinc-800 text-white border border-white/10 shadow-lg" : "text-zinc-600 hover:text-zinc-400 hover:bg-white/5"}`}
                                                >
                                                    {n}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                {/* Classes Requises */}
                                <div className="space-y-3">
                                    <div className="flex items-center justify-between ml-1">
                                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Besoin spécifique (Options)</p>
                                        <span className="text-[9px] font-bold text-zinc-600 uppercase tracking-tighter bg-zinc-900 px-2 py-0.5 rounded border border-white/5">{requiredClasses.length} SÉLECTIONNÉES</span>
                                    </div>
                                    <div className="grid grid-cols-6 sm:grid-cols-10 gap-2 p-4 rounded-3xl bg-zinc-900/40 border border-white/5 backdrop-blur-sm">
                                        {DOFUS_CLASSES.map((c) => {
                                            const isSelected = requiredClasses.includes(c.name);
                                            return (
                                                <button
                                                    key={c.id}
                                                    title={c.name}
                                                    onClick={() => toggleClass(c.name)}
                                                    className={`aspect-square rounded-xl flex items-center justify-center transition-all border group/class ${isSelected 
                                                        ? "border-amber-500/50 bg-amber-500/10 shadow-[0_0_15px_-5px_var(--color-amber-500)] scale-105" 
                                                        : "border-transparent opacity-30 hover:opacity-100 hover:bg-zinc-800 hover:border-white/10"}`}
                                                >
                                                    <img src={c.icon} alt={c.name} className="w-7 h-7 object-contain drop-shadow-lg group-hover/class:scale-110 transition-transform" onError={(e) => e.currentTarget.style.display = 'none'} />
                                                </button>
                                            );
                                        })}
                                    </div>
                                </div>

                                {/* Message */}
                                <div className="space-y-3">
                                    <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Note pour la guilde</p>
                                    <textarea
                                        value={message}
                                        onChange={(e) => setMessage(e.target.value)}
                                        rows={3}
                                        placeholder="Ex: On cherche un tank pour clean les succès du premier coup..."
                                        className="w-full bg-zinc-900 border border-white/5 rounded-2xl px-5 py-4 text-sm text-white focus:outline-none focus:border-amber-500/50 focus:ring-4 focus:ring-amber-500/5 transition-all resize-none shadow-xl placeholder:text-zinc-700"
                                    />
                                </div>

                                {/* Footer Action - Refined */}
                                <div className="pt-8 flex flex-col sm:flex-row items-center justify-between gap-6 border-t border-white/5 mt-4 relative">
                                    <div className="flex items-center gap-4 bg-zinc-900/50 p-3 rounded-2xl border border-white/5 shadow-inner">
                                        <Switch
                                            checked={isDiscordPublished}
                                            onCheckedChange={setIsDiscordPublished}
                                            disabled={!isDiscordConfigured}
                                            className="data-[state=checked]:bg-indigo-500"
                                        />
                                        <div className="flex flex-col">
                                            <span className={`text-xs font-black uppercase tracking-widest ${isDiscordConfigured ? 'text-zinc-300' : 'text-zinc-600'}`}>Synchro Discord</span>
                                            {!isDiscordConfigured && (
                                                <span className="text-[8px] text-amber-500/70 font-black uppercase tracking-tighter">⚠️ Non configuré</span>
                                            )}
                                        </div>
                                    </div>

                                    {isDiscordPublished && discordRoles.length > 0 && (
                                        <div className="flex flex-col gap-2 min-w-[180px]">
                                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest ml-1">Mentionner un rôle</span>
                                            <Popover open={roleOpen} onOpenChange={setRoleOpen}>
                                                <PopoverTrigger asChild>
                                                    <Button
                                                        variant="outline"
                                                        role="combobox"
                                                        aria-expanded={roleOpen}
                                                        className="h-10 bg-zinc-900 border-white/10 text-xs font-bold rounded-xl justify-between group/role w-full"
                                                    >
                                                        <div className="flex items-center gap-2 truncate">
                                                            {mentionRoleId ? (
                                                                <>
                                                                    <div 
                                                                        className="w-2 h-2 rounded-full shrink-0" 
                                                                        style={{ backgroundColor: discordRoles.find(r => r.id === mentionRoleId)?.color === "#000000" ? "#9ca3af" : discordRoles.find(r => r.id === mentionRoleId)?.color }} 
                                                                    />
                                                                    <span className="truncate">{discordRoles.find(r => r.id === mentionRoleId)?.name}</span>
                                                                </>
                                                            ) : (
                                                                <span className="text-zinc-500 italic">Aucun ping</span>
                                                            )}
                                                        </div>
                                                        <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                                                    </Button>
                                                </PopoverTrigger>
                                                <PopoverContent className="w-[var(--radix-popover-trigger-width)] p-0 bg-zinc-950 border-white/10" align="end">
                                                    <Command className="bg-transparent text-white">
                                                        <CommandInput placeholder="Rechercher..." className="h-9 border-none focus:ring-0" />
                                                        <CommandList className="max-h-[280px] custom-scrollbar">
                                                            <CommandEmpty>Aucun rôle.</CommandEmpty>
                                                            <CommandGroup>
                                                                <CommandItem
                                                                    onSelect={() => {
                                                                        setMentionRoleId(null);
                                                                        setRoleOpen(false);
                                                                    }}
                                                                    className="text-zinc-500 italic focus:bg-white/10 cursor-pointer text-xs"
                                                                >
                                                                    <Check
                                                                        className={cn(
                                                                            "mr-2 h-3 h-3",
                                                                            !mentionRoleId ? "opacity-100" : "opacity-0"
                                                                        )}
                                                                    />
                                                                    Aucun ping
                                                                </CommandItem>
                                                                {discordRoles.map((role) => (
                                                                    <CommandItem
                                                                        key={role.id}
                                                                        onSelect={() => {
                                                                            setMentionRoleId(role.id);
                                                                            setRoleOpen(false);
                                                                        }}
                                                                        className="text-white focus:bg-white/10 cursor-pointer text-xs"
                                                                    >
                                                                        <Check
                                                                            className={cn(
                                                                                "mr-2 h-3 w-3",
                                                                                mentionRoleId === role.id ? "opacity-100" : "opacity-0"
                                                                            )}
                                                                        />
                                                                        <div className="flex items-center gap-2 flex-1 truncate font-bold">
                                                                            <div 
                                                                                className="w-2 h-2 rounded-full shrink-0" 
                                                                                style={{ backgroundColor: role.color === "#000000" ? "#9ca3af" : role.color }} 
                                                                            />
                                                                            <span className="truncate">{role.name}</span>
                                                                        </div>
                                                                    </CommandItem>
                                                                ))}
                                                            </CommandGroup>
                                                        </CommandList>
                                                    </Command>
                                                </PopoverContent>
                                            </Popover>
                                        </div>
                                    )}

                                    <Button
                                        className={`h-14 px-10 rounded-2xl font-black text-sm tracking-tight transition-all active:scale-95 shadow-2xl relative group overflow-hidden ${
                                            mode === "DONJON" 
                                                ? "bg-amber-500 hover:bg-amber-400 text-zinc-950 shadow-amber-900/20" 
                                                : "bg-emerald-500 hover:bg-emerald-400 text-zinc-950 shadow-emerald-900/20"
                                        }`}
                                        onClick={handleSubmit}
                                        disabled={isPending || (mode === "DONJON" && !selectedDungeon) || (mode === "QUETE" && !selectedQuest)}
                                    >
                                        <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-10 transition-opacity" />
                                        <div className="flex items-center gap-3 relative z-10">
                                            {isPending ? (
                                                <div className="w-5 h-5 border-3 border-zinc-950/20 border-t-zinc-950 rounded-full animate-spin" />
                                            ) : (
                                                <Users className="w-5 h-5" />
                                            )}
                                            {isPending ? "PUBLICATION..." : "LANCER LA SESSION"}
                                        </div>
                                    </Button>
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useTransition } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";
import {
    Users, CheckCircle2, XCircle, Crown, Swords, Clock,
    Trophy, Map, Link2, LogIn, LogOut, Trash2, Pencil
} from "lucide-react";
import {
    acceptDjParticipant,
    rejectDjParticipant,
    closeDjPost,
    joinDjPost,
    leaveDjPost,
    deleteDjPost,
} from "@/server/actions/dungeon-finder-actions";
import { DjCloseModal } from "./DjCloseModal";
import { DjEditModal } from "./DjEditModal";
import type { DjPostWithDetails } from "@/server/actions/dungeon-finder-actions";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { DOFUS_CLASSES, getClass } from "@/lib/dofus-assets";

const MODE_LABELS: Record<string, string> = {
    FARM: "Farm", SUCCES: "Succès", MIXED: "Mixte", QUETE: "Quête", DONJON: "Donjon",
};
const STATUS_COLORS: Record<string, string> = {
    PENDING: "text-yellow-400 bg-yellow-500/10 border-yellow-500/20",
    ACCEPTED: "text-emerald-400 bg-emerald-500/10 border-emerald-500/20",
    REJECTED: "text-red-400 bg-red-500/10 border-red-500/20",
};

// Helper: Discord server nick > Dofus pseudo (set on registration) > Dofus in-game pseudo
function displayName(profile: { discordNickname?: string | null; pseudoDofus?: string | null; dofusPseudo?: string | null }) {
    return profile.discordNickname || profile.pseudoDofus || profile.dofusPseudo || "Membre";
}

interface DjPostDetailModalProps {
    isOpen: boolean;
    onClose: () => void;
    post: DjPostWithDetails;
    guildId: string;
    currentProfileId?: string;
    isAdmin?: boolean;
    onRefresh: () => void;
}

export function DjPostDetailModal({
    isOpen, onClose, post, guildId, currentProfileId, isAdmin, onRefresh
}: DjPostDetailModalProps) {
    const [classe, setClasse] = useState("");
    const [message, setMessage] = useState("");
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isPending, startTransition] = useTransition();

    const isOwner = post.profileId === currentProfileId;
    const myParticipation = currentProfileId
        ? post.participants.find((p) => p.profile.id === currentProfileId)
        : null;

    // Creator counts as 1 slot, participants are separate
    const acceptedParticipants = post.participants.filter((p) => p.status === "ACCEPTED");
    const acceptedCount = acceptedParticipants.length + 1; // +1 for creator
    const spotsLeft = post.maxMembers - acceptedCount;

    function handleJoin() {
        startTransition(async () => {
            const res = await joinDjPost(guildId, post.id, { classe: classe || null, message: message || null });
            if (res.success) {
                toast.success("Candidature envoyée !");
                onRefresh();
                onClose();
            } else {
                toast.error(res.error);
            }
        });
    }

    function handleLeave() {
        startTransition(async () => {
            const res = await leaveDjPost(guildId, post.id);
            if (res.success) { toast.success("Parti du post."); onRefresh(); onClose(); }
            else toast.error(res.error);
        });
    }

    function handleDelete() {
        if (!confirm("Voulez-vous vraiment supprimer ce post définitivement ?")) return;
        startTransition(async () => {
            const res = await deleteDjPost(guildId, post.id);
            if (res.success) {
                toast.success("Post supprimé définitivement.");
                onRefresh();
                onClose();
            } else toast.error(res.error);
        });
    }

    function handleAccept(participantId: string) {
        startTransition(async () => {
            const res = await acceptDjParticipant(guildId, post.id, participantId);
            if (res.success) { toast.success("Participant accepté !"); onRefresh(); }
            else toast.error(res.error);
        });
    }

    function handleReject(participantId: string) {
        startTransition(async () => {
            const res = await rejectDjParticipant(guildId, post.id, participantId);
            if (res.success) { toast.success("Participant retiré."); onRefresh(); }
            else toast.error(res.error);
        });
    }

    const visibleParticipants = post.participants.filter(p => p.status !== "REJECTED");

    return (
        <>
            <Dialog open={isOpen} onOpenChange={onClose}>
                <DialogContent className="w-[95vw] max-w-2xl bg-zinc-950 border border-white/10 shadow-2xl rounded-2xl text-white overflow-y-auto max-h-[90vh] p-0 gap-0 custom-scrollbar">

                    {/* Hero Image / Banner */}
                    <div className="relative h-28 bg-slate-900 border-b border-white/5 overflow-hidden shrink-0">
                        {post.mode === "DONJON" && post.dungeon?.imageUrl && (
                            <img src={post.dungeon?.imageUrl} alt="" className="absolute inset-0 w-full h-full object-cover opacity-30" />
                        )}
                        <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 via-zinc-950/60 to-transparent" />

                        <div className="absolute bottom-4 left-4 right-4 flex items-end gap-4">
                            <div className={`w-14 h-14 rounded-xl overflow-hidden shrink-0 flex items-center justify-center border shadow-lg ${post.mode === "DONJON" ? "bg-slate-800/80 border-white/10" : "bg-cyan-950/80 border-cyan-500/30"}`}>
                                {post.mode === "DONJON" && post.dungeon?.imageUrl ? (
                                    <img src={post.dungeon?.imageUrl} alt="" className="w-full h-full object-cover" />
                                ) : post.mode === "DONJON" ? (
                                    <Swords className="w-6 h-6 text-slate-400" />
                                ) : (
                                    <Map className="w-6 h-6 text-cyan-400" />
                                )}
                            </div>
                            <div className="flex-1 min-w-0 pb-1">
                                <h2 className="text-xl font-black text-white truncate drop-shadow-md">
                                    {post.mode === "DONJON" ? post.dungeon?.name : post.questName || "Quête"}
                                </h2>
                                <p className="text-sm font-medium text-slate-300">
                                    {post.mode === "DONJON" ? `Niv. ${post.dungeon?.level} — ${post.dungeon?.bossName}` : "Mode Quête"}
                                </p>
                            </div>
                            <Badge className={`mb-1 text-[11px] font-black uppercase tracking-wider px-2.5 py-1 backdrop-blur-md ${post.status === "OPEN" ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20 shadow-[0_0_10px_rgba(16,185,129,0.1)]" : "bg-white/5 text-slate-400 border-white/10"}`}>
                                {post.status === "OPEN" ? "Ouvert" : post.status === "FULL" ? "Complet" : "Fermé"}
                            </Badge>
                        </div>
                    </div>

                    <div className="p-6 space-y-6">
                        {/* Info grid */}
                        <div className="grid grid-cols-2 gap-4 text-sm">
                            <div className="bg-slate-900/40 rounded-xl p-4 border border-white/5 shadow-inner">
                                <p className="text-slate-500 text-[10px] uppercase tracking-widest font-bold mb-1.5 flex items-center gap-1.5"><Swords className="w-3.5 h-3.5" /> Mode</p>
                                <p className="font-black text-white text-base">{MODE_LABELS[post.mode] ?? post.mode}</p>
                            </div>
                            <div className="bg-slate-900/40 rounded-xl p-4 border border-white/5 shadow-inner">
                                <p className="text-slate-500 text-[10px] uppercase tracking-widest font-bold mb-1.5 flex items-center gap-1.5"><Users className="w-3.5 h-3.5" /> Places</p>
                                <p className={`font-black text-base ${spotsLeft === 0 ? "text-amber-400" : "text-emerald-400"}`}>
                                    {acceptedCount}/{post.maxMembers} — {spotsLeft > 0 ? <span className="text-slate-300 font-medium">{`${spotsLeft} dispo${spotsLeft > 1 ? "s" : ""}`}</span> : "Complet"}
                                </p>
                            </div>
                            {post.targetDate && (
                                <div className="bg-indigo-500/5 rounded-xl p-4 border border-indigo-500/10 col-span-2 shadow-inner">
                                    <p className="text-indigo-400/80 text-[10px] uppercase tracking-widest font-bold mb-1.5 flex items-center gap-1.5"><Clock className="w-3.5 h-3.5" /> Date prévue</p>
                                    <p className="font-bold text-indigo-300">
                                        {new Date(post.targetDate).toLocaleDateString("fr-FR", {
                                            weekday: "long", day: "numeric", month: "long", hour: "2-digit", minute: "2-digit"
                                        }).replace(/, /g, " à ")}
                                    </p>
                                </div>
                            )}
                        </div>

                        {/* Quest info */}
                        {post.questName && (
                            <div className="bg-cyan-500/5 border border-cyan-500/20 rounded-xl p-4 flex flex-col sm:flex-row sm:items-center gap-3">
                                <div className="flex flex-1 items-center gap-3">
                                    <div className="w-8 h-8 rounded-lg bg-cyan-950/50 flex items-center justify-center shrink-0 border border-cyan-900/50">
                                        <Map className="w-4 h-4 text-cyan-400" />
                                    </div>
                                    <div>
                                        {post.mode === "DONJON" && (
                                            <p className="text-[10px] text-cyan-500/70 font-bold uppercase tracking-widest mb-0.5">Quête associée</p>
                                        )}
                                        <span className="text-sm text-cyan-300 font-bold">{post.questName}</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-2 shrink-0">
                                    {post.questUrl && post.questUrl.includes("dofuspourlesnoobs") && (
                                        <a href={post.questUrl} target="_blank" rel="noopener noreferrer"
                                            className="text-[11px] font-bold text-amber-400 hover:text-amber-300 border border-amber-900/40 hover:border-amber-500/50 bg-amber-950/20 rounded-md px-3 py-1.5 transition-colors flex items-center gap-1.5">
                                            <Link2 className="w-3.5 h-3.5" /> Tutoriel
                                        </a>
                                    )}
                                    {post.questId && post.questId !== -1 && (
                                        <a href={`https://dofusdb.fr/fr/database/quest/${post.questId}`} target="_blank" rel="noopener noreferrer"
                                            className="text-[11px] font-bold text-slate-300 hover:text-white border border-white/5 hover:border-white/10 bg-white/5 rounded-md px-3 py-1.5 transition-colors flex items-center gap-1.5">
                                            <Map className="w-3.5 h-3.5" /> DofusDB
                                        </a>
                                    )}
                                </div>
                            </div>
                        )}

                        {/* Message */}
                        {post.message && (
                            <div className="bg-slate-900/40 rounded-xl p-4 border-l-2 border-indigo-500 shadow-inner">
                                <p className="text-sm text-slate-300 leading-relaxed italic opacity-90">"{post.message}"</p>
                            </div>
                        )}

                        {/* Wanted achievements */}
                        {post.wantedAchievementIds.length > 0 && post.dungeon && (
                            <div className="space-y-2">
                                <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold flex items-center gap-1.5"><Trophy className="w-3.5 h-3.5" /> Succès visés</p>
                                <div className="flex gap-2 flex-wrap">
                                    {post.dungeon.achievements
                                        .filter((a) => post.wantedAchievementIds.includes(a.id))
                                        .map((a) => (
                                            <div key={a.id} className="flex items-center gap-2 bg-amber-500/10 border border-amber-500/20 rounded-lg px-2.5 py-1.5 shadow-sm">
                                                {a.challenge.iconUrl && (
                                                    <img src={a.challenge.iconUrl} alt="" className="w-4 h-4 object-contain" />
                                                )}
                                                <span className="text-xs text-amber-300 font-bold">{a.challenge.name}</span>
                                            </div>
                                        ))}
                                </div>
                            </div>
                        )}

                        {/* Required classes */}
                        {post.requiredClasses && post.requiredClasses.length > 0 && (
                            <div className="space-y-2">
                                <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold flex items-center gap-1.5"><Users className="w-3.5 h-3.5" /> Classes demandées</p>
                                <div className="flex gap-1.5 flex-wrap">
                                    {post.requiredClasses.map((c) => {
                                        const classData = getClass(c);
                                        return (
                                            <div key={c} className="flex items-center bg-indigo-500/10 border border-indigo-500/20 rounded-md p-1 shadow-sm px-2 gap-1.5">
                                                <div className="w-4 h-4 rounded overflow-hidden">
                                                    <img src={classData?.icon} alt={classData?.name || c} className="w-full h-full object-contain" onError={(e) => e.currentTarget.style.display = 'none'} />
                                                </div>
                                                <span className="text-[11px] text-indigo-200 font-medium">{classData?.name || c}</span>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}

                        {/* Participants list */}
                        <div>
                            <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold mb-2 flex items-center gap-2">
                                <Users className="w-3 h-3" /> Participants ({acceptedCount}/{post.maxMembers})
                            </p>
                            <div className="space-y-1.5">
                                {/* Creator row */}
                                <div className="flex items-center gap-4 bg-amber-500/5 rounded-xl p-3 border border-amber-500/10 shadow-sm relative overflow-hidden">
                                    <div className="w-10 h-10 rounded-full overflow-hidden shrink-0 ring-2 ring-amber-500/40 shadow-[0_0_10px_rgba(245,158,11,0.2)]">
                                        {post.profile.user.image && <img src={post.profile.user.image} alt="" className="w-full h-full object-cover" />}
                                    </div>
                                    <div className="flex-1 min-w-0 z-10">
                                        <p className="text-sm font-black text-white truncate drop-shadow-sm">{displayName(post.profile)}</p>
                                        <span className="text-[10px] text-amber-500/80 font-bold flex items-center mt-0.5"><Crown className="w-3 h-3 mr-1 inline" /> Créateur du groupe</span>
                                    </div>
                                    <div className="absolute right-0 top-0 bottom-0 w-24 bg-gradient-to-l from-amber-500/10 to-transparent pointer-events-none" />
                                </div>

                                {/* Participants */}
                                {visibleParticipants.map((p) => (
                                    <div key={p.id} className="flex flex-col sm:flex-row sm:items-center gap-3 bg-slate-900/40 rounded-xl p-3 border border-white/5 hover:bg-slate-900/60 transition-colors group">
                                        <div className="flex items-center gap-4 flex-1 min-w-0">
                                            <div className="w-10 h-10 rounded-full overflow-hidden bg-slate-800 shrink-0 ring-1 ring-white/10">
                                                {p.profile.user.image && <img src={p.profile.user.image} alt="" className="w-full h-full object-cover" />}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2">
                                                    <p className="text-sm font-bold text-slate-200 truncate group-hover:text-white transition-colors">{displayName(p.profile)}</p>
                                                    {p.classe && <Badge variant="outline" className="text-[9px] h-4 border-slate-700 text-slate-400 px-1.5">{p.classe}</Badge>}
                                                </div>
                                                {p.message && <p className="text-[11px] text-slate-500 italic truncate mt-0.5 leading-tight">"{p.message}"</p>}
                                            </div>
                                        </div>
                                        <div className="flex items-center justify-between sm:justify-end gap-2 shrink-0">
                                            <Badge className={`text-[10px] font-bold uppercase tracking-wider ${STATUS_COLORS[p.status] || STATUS_COLORS.PENDING}`}>
                                                {p.status === "PENDING" ? "En attente" : p.status === "ACCEPTED" ? "Approuvé" : "Refusé"}
                                            </Badge>

                                            {/* Owner actions */}
                                            {(isOwner || isAdmin) && post.status === "OPEN" && (
                                                <div className="flex gap-1 shrink-0 bg-slate-900/80 rounded-lg border border-white/5 opacity-100 sm:opacity-0 group-hover:opacity-100 transition-opacity p-0.5">
                                                    {p.status === "PENDING" && (
                                                        <Button size="icon" variant="ghost"
                                                            className="w-8 h-8 text-emerald-400 hover:bg-emerald-500/20 hover:text-emerald-300 rounded-md"
                                                            onClick={() => handleAccept(p.id)} disabled={isPending}>
                                                            <CheckCircle2 className="w-4 h-4" />
                                                        </Button>
                                                    )}
                                                    <Button size="icon" variant="ghost"
                                                        className="w-8 h-8 text-rose-400 hover:bg-rose-500/20 hover:text-rose-300 rounded-md"
                                                        onClick={() => handleReject(p.id)} disabled={isPending}
                                                        title={p.status === "PENDING" ? "Refuser" : "Retirer"}>
                                                        <Trash2 className="w-4 h-4" />
                                                    </Button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}

                                {visibleParticipants.length === 0 && (
                                    <p className="text-center text-sm text-slate-600 py-4">Aucun participant pour l'instant</p>
                                )}
                            </div>
                        </div>

                        {/* Join form */}
                        {!isOwner && !myParticipation && post.status === "OPEN" && spotsLeft > 0 && (
                            <div className="border-t border-white/5 pt-6 space-y-4">
                                <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">Candidature</p>
                                <div className="bg-slate-900/40 rounded-xl p-4 border border-white/5 grid grid-cols-1 sm:grid-cols-3 gap-4 shadow-inner">
                                    <div className="sm:col-span-1">
                                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-widest block mb-1.5">Ta classe</label>
                                        <select
                                            value={classe}
                                            onChange={(e) => setClasse(e.target.value)}
                                            className="w-full bg-slate-900 border border-white/10 rounded-lg px-3 py-2.5 text-sm text-slate-200 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 appearance-none shadow-inner"
                                        >
                                            <option value="">Sélectionner…</option>
                                            {DOFUS_CLASSES.map((c) => (
                                                <option key={c.id} value={c.name}>{c.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="sm:col-span-2">
                                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-widest block mb-1.5">Message (opt.)</label>
                                        <input
                                            type="text"
                                            value={message}
                                            onChange={(e) => setMessage(e.target.value.slice(0, 200))}
                                            placeholder="Ex: Dispo toute la soirée, j'ai le stuff..."
                                            className="w-full bg-slate-900 border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white placeholder:text-slate-600 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 shadow-inner"
                                        />
                                    </div>
                                </div>
                                <Button
                                    className="w-full bg-indigo-600 hover:bg-indigo-500 font-black h-12 shadow-lg shadow-indigo-900/20"
                                    onClick={handleJoin}
                                    disabled={isPending}
                                >
                                    <LogIn className="w-5 h-5 mr-2" />
                                    Envoyer ma candidature
                                </Button>
                            </div>
                        )}

                        {/* My pending status */}
                        {myParticipation?.status === "PENDING" && (
                            <div className="border-t border-white/5 pt-5 flex items-center justify-between">
                                <p className="text-sm font-bold text-amber-400 flex items-center gap-2">
                                    <Clock className="w-4 h-4" /> Candidature en cours d'examen...
                                </p>
                                <Button size="sm" variant="outline" onClick={handleLeave} disabled={isPending}
                                    className="border-rose-900/50 bg-rose-950/20 text-rose-400 hover:bg-rose-900/40 hover:text-rose-300">
                                    <LogOut className="w-4 h-4 mr-1.5" /> Se retirer
                                </Button>
                            </div>
                        )}

                        {/* Creator actions */}
                        {(isOwner || isAdmin) && post.status === "OPEN" && (
                            <div className="border-t border-white/5 pt-5 flex gap-3">
                                {isOwner && (
                                    <Button
                                        variant="outline"
                                        className="flex-1 border-white/10 bg-white/5 text-slate-300 hover:text-white hover:bg-white/10 font-bold h-11 transition-all"
                                        onClick={() => setIsEditModalOpen(true)}
                                        disabled={isPending}
                                    >
                                        <Pencil className="w-4 h-4 mr-2" strokeWidth={2.5} />
                                        Modifier le groupe
                                    </Button>
                                )}
                                <Button
                                    variant="outline"
                                    className="flex-1 border-rose-900/40 bg-rose-950/20 text-rose-400 hover:bg-rose-900/40 hover:text-rose-300 font-bold h-11 transition-all"
                                    onClick={handleDelete}
                                    disabled={isPending}
                                >
                                    <Trash2 className="w-4 h-4 mr-2" />
                                    Supprimer le groupe
                                </Button>
                            </div>
                        )}
                    </div>
                </DialogContent>
            </Dialog>

            {isOwner && (
                <DjEditModal
                    isOpen={isEditModalOpen}
                    post={post}
                    guildId={guildId}
                    onClose={() => setIsEditModalOpen(false)}
                    onSaved={() => { onRefresh(); }}
                />
            )}
        </>
    );
}

"use client";

import { useState, useEffect, useMemo, useTransition } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { toast } from "sonner";
import {
  Search,
  Users,
  Trophy,
  ChevronLeft,
  ChevronDown,
  CheckCircle2,
  Circle,
  Sword,
  Info,
  Map as MapIcon,
  Globe,
  Copy,
} from "lucide-react";
import {
  getDungeonsWithAchievements,
  getMonsterStats,
} from "@/server/actions/game-data-actions";
import { getDungeonDirectory } from "@/server/actions/dungeon-finder-actions";
import { Button } from "@/components/ui/button";
import { getClass } from "@/lib/dofus-assets";
import { MapViewer } from "@/components/worldmap/map-viewer";

function StatResist({
  label,
  value,
  color,
  border,
  text,
}: {
  label: string;
  value?: number;
  color: string;
  border: string;
  text: string;
}) {
  return (
    <div className={`flex flex-col items-center gap-1 group/res relative`}>
      <div
        className={`w-5 h-5 rounded border ${color} ${border} flex items-center justify-center transition-all group-hover/res:scale-110 shadow-sm overflow-hidden`}
      >
        <span className={`text-[8px] font-black ${text}`}>
          {value !== undefined ? `${value}%` : ""}
        </span>
      </div>
      <span className="text-[7px] font-bold text-slate-500 uppercase tracking-tighter">
        {label}
      </span>
    </div>
  );
}

interface Dungeon {
  id: string;
  name: string;
  bossName: string;
  level: number;
  imageUrl?: string | null;
}

interface AchievementDirectory {
  achievementId: string;
  achievementName: string;
  iconUrl: string | null;
  points: number;
  hasCompleted: {
    id: string;
    name: string;
    imageUrl: string | null;
    classe: string | null;
  }[];
  missing: {
    id: string;
    name: string;
    imageUrl: string | null;
    classe: string | null;
  }[];
}

interface DungeonDirectoryProps {
  guildId: string;
  onCreatePost?: (dungeonId: string) => void;
}

export function DungeonDirectory({
  guildId,
  onCreatePost,
}: DungeonDirectoryProps) {
  const [dungeons, setDungeons] = useState<Dungeon[]>([]);
  const [search, setSearch] = useState("");
  const [selectedDungeon, setSelectedDungeon] = useState<Dungeon | null>(null);
  const [bossStats, setBossStats] = useState<any | null>(null);
  const [selectedGrade, setSelectedGrade] = useState(4); // Default to G5 (index 4)
  const [directoryData, setDirectoryData] = useState<AchievementDirectory[]>(
    [],
  );
  const [memberSearch, setMemberSearch] = useState("");
  const [minLevel, setMinLevel] = useState(1);
  const [maxLevel, setMaxLevel] = useState(1000);
  const [selectedSpellId, setSelectedSpellId] = useState<number | null>(null);
  const [loadingDb, setLoadingDb] = useState(true);
  const [loadingDir, setLoadingDir] = useState(false);
  const [expandedAchv, setExpandedAchv] = useState<string | null>(null);

  useEffect(() => {
    getDungeonsWithAchievements().then((res) => {
      if (res.success && res.data) {
        const uniqueDungeons = Array.from(
          new Map(res.data.map((item: any) => [item.id, item])).values(),
        ) as Dungeon[];
        setDungeons(uniqueDungeons.sort((a, b) => b.level - a.level));
      }
      setLoadingDb(false);
    });
  }, []);

  const filteredDungeons = useMemo(() => {
    const term = search.toLowerCase();
    return dungeons.filter((d) => {
      const matchesSearch =
        d.name.toLowerCase().includes(term) ||
        d.bossName.toLowerCase().includes(term);
      const matchesLevel = d.level >= minLevel && d.level <= maxLevel;
      return matchesSearch && matchesLevel;
    });
  }, [dungeons, search, minLevel, maxLevel]);

  async function handleSelectDungeon(dungeon: Dungeon) {
    setSelectedDungeon(dungeon);
    setBossStats(null);
    setSelectedGrade(4);
    setSelectedSpellId(null);
    setLoadingDir(true);
    setDirectoryData([]);
    setExpandedAchv(null);
    setMemberSearch("");

    const [dirRes, statsRes] = await Promise.all([
      getDungeonDirectory(guildId, dungeon.id),
      getMonsterStats(dungeon.bossName),
    ]);

    if (dirRes.success && dirRes.data) {
      setDirectoryData(dirRes.data);
      if (dirRes.data.length > 0) {
        setExpandedAchv(dirRes.data[0].achievementId);
      }
    }

    if (statsRes.success && statsRes.data) {
      setBossStats(statsRes.data);
      // If monster has fewer than 5 grades, adjust selectedGrade
      if (statsRes.data.grades.length <= selectedGrade) {
        setSelectedGrade(statsRes.data.grades.length - 1);
      }
    }

    setLoadingDir(false);
  }

  const filteredDirectory = useMemo(() => {
    const term = memberSearch.toLowerCase();
    if (!term) return directoryData;

    return directoryData.map((achv) => ({
      ...achv,
      missing: achv.missing.filter(
        (m) =>
          m.name.toLowerCase().includes(term) ||
          (m.classe && m.classe.toLowerCase().includes(term)),
      ),
      hasCompleted: achv.hasCompleted.filter(
        (m) =>
          m.name.toLowerCase().includes(term) ||
          (m.classe && m.classe.toLowerCase().includes(term)),
      ),
    }));
  }, [directoryData, memberSearch]);

  if (loadingDb) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-slate-500 animate-pulse">
        <Users className="w-10 h-10 mb-4 opacity-50" />
        <p className="font-medium">Chargement de la base de données...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <AnimatePresence mode="wait">
        {!selectedDungeon ? (
          <motion.div
            key="list"
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.98 }}
            className="space-y-6"
          >
            {/* Header & Search */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-xl font-black text-white flex items-center gap-2">
                  <div className="w-8 h-8 rounded-xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center">
                    <Users className="w-4 h-4 text-indigo-400" />
                  </div>
                  Succès Commun
                </h2>
                <p className="text-sm text-slate-400 mt-1 ml-10">
                  Trouve qui a ou n'a pas encore validé chaque succès de donjon
                  dans la guilde.
                </p>
              </div>
              <div className="flex flex-wrap items-center gap-2">
                <div className="relative w-full md:w-64">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                  <input
                    type="text"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Rechercher un donjon…"
                    className="w-full bg-slate-900/50 border border-white/5 rounded-xl pl-10 pr-4 py-2.5 text-sm text-white placeholder:text-slate-500 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 backdrop-blur-sm transition-all shadow-inner h-11"
                  />
                </div>

                <div className="flex flex-wrap items-center gap-1.5 p-1 bg-slate-900/40 border border-white/5 rounded-xl">
                  {[
                    { label: "Tout", min: 1, max: 1000 },
                    { label: "1-50", min: 1, max: 50 },
                    { label: "51-100", min: 51, max: 100 },
                    { label: "101-150", min: 101, max: 150 },
                    { label: "151-190", min: 151, max: 190 },
                    { label: "191-200", min: 191, max: 200 },
                  ].map((preset) => {
                    const isActive =
                      minLevel === preset.min && maxLevel === preset.max;
                    return (
                      <button
                        key={preset.label}
                        onClick={() => {
                          setMinLevel(preset.min);
                          setMaxLevel(preset.max);
                        }}
                        className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all border ${
                          isActive
                            ? "bg-indigo-500/20 text-indigo-300 border-indigo-500/30"
                            : "bg-white/5 text-slate-500 border-transparent hover:bg-white/10 hover:text-slate-300"
                        }`}
                      >
                        {preset.label === "Tout"
                          ? "Tous Niveaux"
                          : `Lvl ${preset.label}`}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            {/* Grid of Dungeons */}
            {filteredDungeons.length > 0 ? (
              <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 xl:grid-cols-8 gap-2">
                {filteredDungeons.map((dungeon) => (
                  <motion.button
                    key={dungeon.id}
                    whileHover={{ y: -2, scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => handleSelectDungeon(dungeon)}
                    className="relative group overflow-hidden rounded-xl flex flex-col items-center text-center border border-white/5 bg-slate-900/40 hover:bg-slate-900/60 hover:border-indigo-500/40 shadow-sm transition-all p-2 pb-2.5"
                  >
                    {/* Image */}
                    <div className="w-full aspect-square flex items-center justify-center mb-1.5 relative">
                      {dungeon.imageUrl ? (
                        <img
                          src={dungeon.imageUrl}
                          alt={dungeon.name}
                          className="w-4/5 h-4/5 object-contain drop-shadow-lg group-hover:scale-110 transition-transform duration-300"
                        />
                      ) : (
                        <div className="w-12 h-12 rounded-xl bg-white/5 flex items-center justify-center shadow-inner border border-white/5">
                          <Search className="w-5 h-5 text-slate-600" />
                        </div>
                      )}
                    </div>

                    <div className="w-full">
                      <div className="inline-flex items-center justify-center px-1.5 py-0.5 rounded text-[9px] font-bold bg-indigo-500/10 text-indigo-300 border border-indigo-500/20 mb-1">
                        Lvl {dungeon.level}
                      </div>
                      <h3 className="text-[11px] font-bold text-slate-300 leading-tight line-clamp-2 group-hover:text-white transition-colors">
                        {dungeon.name}
                      </h3>
                    </div>
                  </motion.button>
                ))}
              </div>
            ) : (
              <div className="text-center py-12 text-slate-500">
                <Search className="w-8 h-8 mx-auto mb-3 opacity-20" />
                <p>Aucun donjon trouvé pour "{search}"</p>
              </div>
            )}
          </motion.div>
        ) : (
          <motion.div
            key="details"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="space-y-6"
          >
            {/* Back Button */}
            <div className="mb-2">
              <button
                onClick={() => setSelectedDungeon(null)}
                className="inline-flex items-center gap-2 px-4 py-2 rounded-full border border-white/10 bg-zinc-900/50 text-slate-300 hover:bg-zinc-800 hover:text-white transition-all shadow-sm"
              >
                <ChevronLeft className="w-4 h-4" /> Retour à l'annuaire
              </button>
            </div>
            <div className="relative rounded-3xl overflow-hidden border border-white/10 bg-gradient-to-b from-zinc-900 to-zinc-950 shadow-2xl">
              <div className="relative z-10 p-6 md:p-8 flex flex-col md:flex-row items-start gap-6 lg:gap-8">
                {/* Left Column: Info, Loot, Spells */}
                <div className="flex-1 space-y-6 min-w-0">
                  <div className="flex flex-col sm:flex-row gap-5 items-start sm:items-center">
                    {(bossStats?.imageUrl || selectedDungeon.imageUrl) && (
                      <div className="w-16 h-16 md:w-20 md:h-20 shrink-0 rounded-2xl bg-gradient-to-tr from-slate-950 to-slate-900 border border-white/10 flex items-center justify-center p-2 shadow-inner">
                        <img
                          src={bossStats?.imageUrl || selectedDungeon.imageUrl}
                          alt={bossStats?.name || "Boss"}
                          className="w-full h-full object-contain filter drop-shadow-lg"
                        />
                      </div>
                    )}
                    <div className="min-w-0">
                      <div className="flex items-center gap-2 mb-1 flex-wrap">
                        <span className="px-2 py-0.5 bg-indigo-500/10 border border-indigo-500/30 text-indigo-400 rounded-md text-[9px] font-black tracking-widest uppercase">
                          Niveau {selectedDungeon.level}
                        </span>
                        <span className="text-[9px] text-zinc-500 font-bold flex items-center gap-1.5 uppercase tracking-tighter">
                          <MapIcon className="w-2.5 h-2.5" /> Donjon Classique
                        </span>
                      </div>
                      <h2 className="text-2xl md:text-3xl font-black text-white drop-shadow-lg tracking-tight truncate">
                        {selectedDungeon.name}
                      </h2>
                      <p className="text-xs text-slate-400 font-medium flex items-center gap-1.5 mt-0.5">
                        Boss : <span className="text-white font-bold">{selectedDungeon.bossName}</span>
                      </p>
                    </div>
                  </div>

                  <div className="space-y-5">
                    {/* Drops Section: Ultra compact */}
                    {bossStats?.drops && bossStats.drops.length > 0 && (
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <h4 className="text-[8px] font-black uppercase tracking-[0.2em] text-indigo-400/60 ml-1">
                            Butins notables
                          </h4>
                        </div>
                        <div className="flex flex-wrap gap-1.5 max-h-24 overflow-y-auto pr-2 pt-1.5 custom-scrollbar">
                          {bossStats.drops.map((drop: any, idx: number) => (
                            <a
                              key={idx}
                              href={`https://dofusdb.fr/fr/database/item/${drop.objectId}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="group/drop relative bg-white/5 border border-white/5 rounded-md p-1 hover:bg-white/10 transition-all cursor-pointer flex items-center justify-center w-7 h-7 md:w-8 md:h-8 shrink-0"
                              title={`${drop.name} (Clic pour voir sur DofusDB) - Drop: ${drop.percent}%`}
                            >
                              <img
                                src={drop.imageUrl}
                                alt={drop.name}
                                className="w-full h-full object-contain filter drop-shadow-xs group-hover/drop:scale-110 transition-transform"
                              />
                              <div className="absolute -top-1.5 -right-1 bg-indigo-600 text-[7px] font-black px-1.5 py-0.5 rounded-sm shadow-xl opacity-0 group-hover/drop:opacity-100 transition-opacity whitespace-nowrap z-20 pointer-events-none origin-bottom-right">
                                {drop.percent}%
                              </div>
                            </a>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Spells Section: Smaller buttons */}
                    {bossStats?.spells && bossStats.spells.length > 0 && (
                      <div className="space-y-2">
                        <h4 className="text-[8px] font-black uppercase tracking-[0.2em] text-rose-400/60 ml-1">
                          Capacités du Boss
                        </h4>
                        <div className="flex flex-wrap gap-1.5">
                          {bossStats.spells.map((spell: any, idx: number) => {
                            const isActive = selectedSpellId === spell.id;
                            return (
                              <button
                                key={idx}
                                onClick={() => setSelectedSpellId(isActive ? null : spell.id)}
                                className={`flex items-center gap-2 border rounded-md px-1.5 py-1 transition-all outline-none group/spell ${
                                  isActive 
                                    ? "bg-rose-500/20 border-rose-500/40 text-rose-100 shadow-lg" 
                                    : "bg-white/5 border-white/5 text-slate-400 hover:bg-white/10 hover:text-slate-200"
                                }`}
                              >
                                <div className={`w-4 h-4 rounded overflow-hidden flex items-center justify-center p-0.5 transition-all ${isActive ? 'bg-rose-500/30' : 'bg-slate-900'}`}>
                                  {spell.imageUrl ? (
                                    <img src={spell.imageUrl} alt="" className="w-full h-full object-contain" />
                                  ) : (
                                    <Sword className="w-2.5 h-2.5 opacity-50" />
                                  )}
                                </div>
                                <span className={`text-[9px] font-black uppercase tracking-tight ${isActive ? 'text-rose-200' : 'text-slate-400 group-hover/spell:text-slate-200'}`}>
                                  {spell.name}
                                </span>
                              </button>
                            );
                          })}
                        </div>

                        {/* Spell Details: Inline and compact */}
                        <AnimatePresence mode="wait">
                          {selectedSpellId && (
                            <motion.div
                              initial={{ opacity: 0, height: 0 }}
                              animate={{ opacity: 1, height: "auto" }}
                              exit={{ opacity: 0, height: 0 }}
                              className="overflow-hidden"
                            >
                              <div className="bg-zinc-950/40 border border-white/5 rounded-xl p-3 mt-1.5 space-y-2.5 shadow-inner">
                                {(() => {
                                  const spell = bossStats.spells.find((s: any) => s.id === selectedSpellId);
                                  if (!spell) return null;
                                  return (
                                    <>
                                      <div className="flex items-center items-start justify-between gap-3">
                                        <div className="flex items-center gap-2.5">
                                          <div className="w-7 h-7 rounded bg-black/40 flex items-center justify-center border border-white/10 p-1">
                                            {spell.imageUrl ? <img src={spell.imageUrl} alt="" className="w-full h-full object-contain" /> : <Sword className="w-3.5 h-3.5 text-rose-500/50" />}
                                          </div>
                                          <div>
                                            <h5 className="text-xs font-black text-white">{spell.name}</h5>
                                            <div className="flex items-center gap-2 mt-0.5">
                                              <span className="text-[8px] font-black text-amber-500/70 bg-amber-500/5 px-1 py-0.5 rounded border border-amber-500/10 uppercase">{spell.apCost} PA</span>
                                              <span className="text-[8px] font-black text-indigo-400/70 bg-indigo-500/5 px-1 py-0.5 rounded border border-indigo-500/10 uppercase">{spell.minRange}-{spell.range} PO</span>
                                              <span className={`text-[8px] font-black px-1 py-0.5 rounded border uppercase ${spell.castTestLos ? 'text-emerald-500/70 bg-emerald-500/5 border-emerald-500/10' : 'text-rose-500/70 bg-rose-500/5 border-rose-500/10'}`}>
                                                {spell.castTestLos ? 'LDV' : 'S-LDV'}
                                              </span>
                                            </div>
                                          </div>
                                        </div>
                                      </div>
                                      <div className="text-[10px] text-slate-400 leading-snug bg-black/20 rounded-lg p-2 border border-white/5 font-medium">
                                        {spell.description}
                                      </div>
                                    </>
                                  );
                                })()}
                              </div>
                            </motion.div>
                          )}
                        </AnimatePresence>
                      </div>
                    )}
                  </div>
                </div>

                {/* Right Column: Sidebar (Minimap & Stats) */}
                <div className="md:w-56 lg:w-64 space-y-3 shrink-0">
                  {/* Integrated Mini Map */}
                  {bossStats?.coordinates && (
                    <div className="w-full h-60 rounded-2xl overflow-hidden border border-white/10 shadow-[0_0_15px_rgba(16,185,129,0.1)] group/map relative bg-slate-950">
                      <div className="absolute inset-x-0 bottom-0 z-10 pointer-events-none bg-gradient-to-t from-black/90 via-black/40 to-transparent flex items-end justify-between p-4">
                        <div className="flex items-center gap-2 text-[10px] font-black text-emerald-400 uppercase tracking-widest italic shrink-0">
                          <Globe className="w-3 h-3 animate-pulse" />
                          [{bossStats.coordinates.x}, {bossStats.coordinates.y}]
                        </div>
                        <button
                          onClick={() => {
                            const cmd = `/travel ${bossStats.coordinates.x} ${bossStats.coordinates.y}`;
                            navigator.clipboard.writeText(cmd);
                            toast.success("Command copiée !", { description: cmd });
                          }}
                          className="pointer-events-auto w-7 h-7 rounded-lg bg-emerald-500/20 hover:bg-emerald-500 text-emerald-400 hover:text-white border border-emerald-500/30 flex items-center justify-center transition-all shadow-lg active:scale-95 group/copy"
                          title="Copier /travel"
                        >
                          <Copy className="w-3.5 h-3.5 group-hover/copy:scale-110 transition-transform" />
                        </button>
                      </div>
                      <div className="w-full h-full transform transition-transform group-hover/map:scale-105 duration-1000">
                        <MapViewer
                          initialTab="map"
                          initialX={bossStats.coordinates.x}
                          initialY={bossStats.coordinates.y}
                          initialWorldId={bossStats.coordinates.worldMapId}
                          initialZoom={1}
                          hideUI={true}
                        />
                      </div>
                    </div>
                  )}

                  {/* Stats Card */}
                  <div className="bg-slate-950/30 border border-white/5 rounded-xl p-3 shadow-xl">
                    <div className="flex items-center justify-between mb-2.5 border-b border-white/5 pb-1.5">
                      <span className="text-[8px] font-black text-zinc-500 uppercase tracking-widest">Stats Boss</span>
                      <div className="flex gap-0.5">
                        {bossStats?.grades?.map((_: any, i: number) => (
                          <button
                            key={i}
                            onClick={() => setSelectedGrade(i)}
                            className={`w-3.5 h-3.5 rounded text-[7px] font-black flex items-center justify-center transition-all border ${
                              selectedGrade === i
                                ? "bg-indigo-600 border-indigo-500 text-white"
                                : "bg-white/5 border-white/5 text-slate-500 hover:text-slate-300"
                            }`}
                          >
                            {i + 1}
                          </button>
                        ))}
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-1.5 text-[9px]">
                      <div className="bg-black/30 p-1.5 rounded-lg border border-white/5">
                        <span className="text-[7px] font-bold text-zinc-600 uppercase block">Vie</span>
                        <span className="text-white font-black">{bossStats?.grades[selectedGrade]?.lifePoints?.toLocaleString() || "---"}</span>
                      </div>
                      <div className="bg-black/30 p-1.5 rounded-lg border border-white/5">
                        <span className="text-[7px] font-bold text-zinc-600 uppercase block">PA | PM</span>
                        <span className="text-white font-black">{bossStats ? `${bossStats.grades[selectedGrade]?.actionPoints} | ${bossStats.grades[selectedGrade]?.movementPoints}` : "---"}</span>
                      </div>
                      <div className="bg-black/30 p-2 rounded-lg border border-white/5 col-span-2">
                        <div className="flex justify-between items-center gap-1">
                          <StatResist label="N" value={bossStats?.grades[selectedGrade]?.resists.neutral} color="bg-zinc-500/20" border="border-zinc-500/20" text="text-zinc-400" />
                          <StatResist label="T" value={bossStats?.grades[selectedGrade]?.resists.earth} color="bg-orange-500/20" border="border-orange-500/20" text="text-orange-400" />
                          <StatResist label="F" value={bossStats?.grades[selectedGrade]?.resists.fire} color="bg-red-500/20" border="border-red-500/20" text="text-red-400" />
                          <StatResist label="E" value={bossStats?.grades[selectedGrade]?.resists.water} color="bg-blue-500/20" border="border-blue-500/20" text="text-blue-400" />
                          <StatResist label="A" value={bossStats?.grades[selectedGrade]?.resists.air} color="bg-emerald-400/20" border="border-emerald-400/20" text="text-emerald-400" />
                        </div>
                      </div>
                    </div>
                  </div>

                  {onCreatePost && (
                    <Button
                      onClick={() => onCreatePost(selectedDungeon.id)}
                      className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-black py-3 rounded-lg shadow-lg shadow-indigo-950/20 transition-all hover:scale-[1.01] active:scale-95 text-[10px] uppercase tracking-wider"
                    >
                      <Users className="w-3 h-3 mr-2" />
                      Créer un groupe
                    </Button>
                  )}
                </div>
              </div>
            </div>

            {/* Directory Content */}
            {loadingDir ? (
              <div className="flex flex-col items-center justify-center py-16 text-slate-500 animate-pulse bg-slate-900/30 rounded-3xl border border-slate-800/50">
                <Search className="w-8 h-8 mb-3 opacity-50" />
                <p>Analyse des succès de la guilde...</p>
              </div>
            ) : filteredDirectory.length === 0 ? (
              <div className="bg-amber-500/10 border border-amber-500/20 rounded-2xl p-6 text-center text-amber-200/80">
                <Info className="w-8 h-8 mx-auto mb-2 opacity-60 text-amber-500" />
                <p>Ce donjon ne possède aucun succès recensé dans la base.</p>
              </div>
            ) : (
              <div className="space-y-6">
                {/* Member Search */}
                <div className="relative max-w-sm ml-auto">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                  <input
                    type="text"
                    value={memberSearch}
                    onChange={(e) => setMemberSearch(e.target.value)}
                    placeholder="Chercher un membre (pseudo, classe)..."
                    className="w-full bg-slate-900 border border-white/5 rounded-xl pl-10 pr-4 py-2 text-sm text-white placeholder:text-slate-500 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 shadow-inner h-10 transition-all"
                  />
                </div>

                {filteredDirectory.map((achv) => {
                  const isExpanded = expandedAchv === achv.achievementId;
                  const totalMembers =
                    achv.hasCompleted.length + achv.missing.length;
                  const completionRate =
                    totalMembers > 0
                      ? Math.round(
                          (achv.hasCompleted.length / totalMembers) * 100,
                        )
                      : 0;

                  return (
                    <div
                      key={achv.achievementId}
                      className={`rounded-2xl transition-all duration-300 overflow-hidden border ${isExpanded ? "bg-slate-900/90 border-indigo-500/30 shadow-2xl shadow-indigo-900/10" : "bg-slate-900/40 border-white/5 hover:bg-slate-900/60 shadow-sm"}`}
                    >
                      <button
                        onClick={() =>
                          setExpandedAchv(
                            isExpanded ? null : achv.achievementId,
                          )
                        }
                        className="w-full flex items-center justify-between p-4 md:p-5 text-left focus:outline-none"
                      >
                        <div className="flex items-center gap-4 flex-1 min-w-0">
                          <div className="w-12 h-12 rounded-xl bg-slate-900 flex items-center justify-center shrink-0 border border-white/5 shadow-inner">
                            {achv.iconUrl ? (
                              <img
                                src={achv.iconUrl}
                                alt=""
                                className="w-7 h-7 object-contain"
                              />
                            ) : (
                              <Trophy className="w-6 h-6 text-indigo-400" />
                            )}
                          </div>
                          <div>
                            <h4 className="text-base font-bold text-white leading-snug">
                              {achv.achievementName}
                            </h4>
                            <div className="flex items-center gap-2 mt-0.5">
                              <span className="text-[11px] text-slate-500">
                                {completionRate}% de la guilde l'ont validé
                              </span>
                            </div>
                          </div>
                        </div>

                        <div className="flex items-center gap-4 shrink-0">
                          {/* Avatars Preview */}
                          {!isExpanded && achv.missing.length > 0 && (
                            <div className="hidden sm:flex -space-x-2 mr-2">
                              {achv.missing.slice(0, 3).map((m, i) => (
                                <div
                                  key={i}
                                  className="w-7 h-7 rounded-full border-2 border-slate-900 bg-slate-800 overflow-hidden relative"
                                >
                                  {m.imageUrl ? (
                                    <img
                                      src={m.imageUrl}
                                      alt=""
                                      className="w-full h-full object-cover"
                                    />
                                  ) : (
                                    <Users className="w-3 h-3 m-1.5 text-slate-500" />
                                  )}
                                </div>
                              ))}
                              {achv.missing.length > 3 && (
                                <div className="w-7 h-7 rounded-full border-2 border-slate-900 bg-slate-800 flex items-center justify-center text-[9px] font-bold text-slate-400 z-10">
                                  +{achv.missing.length - 3}
                                </div>
                              )}
                            </div>
                          )}

                          <div
                            className={`w-8 h-8 rounded-full flex items-center justify-center transition-colors ${isExpanded ? "bg-indigo-500/20 text-indigo-300" : "bg-white/5 text-slate-400 border border-white/5"}`}
                          >
                            <ChevronDown
                              className={`w-4 h-4 transition-transform duration-300 ${isExpanded ? "rotate-180" : ""}`}
                            />
                          </div>
                        </div>
                      </button>

                      <AnimatePresence>
                        {isExpanded && (
                          <motion.div
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: "auto", opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            className="overflow-hidden border-t border-white/5"
                          >
                            <div className="p-5 md:p-8 grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8 bg-slate-900/20 shadow-inner">
                              {/* Col 1: MISSING */}
                              <div className="bg-slate-900/60 border border-rose-900/20 rounded-2xl p-4">
                                <div className="flex items-center justify-between mb-4 pb-3 border-b border-slate-800">
                                  <div className="flex items-center gap-2 font-bold text-sm">
                                    <div className="w-6 h-6 rounded-lg bg-rose-500/10 border border-rose-500/20 flex items-center justify-center">
                                      <Circle className="w-3.5 h-3.5 text-rose-400" />
                                    </div>
                                    <span className="text-rose-300">
                                      Cherchent encore
                                    </span>
                                  </div>
                                  <span className="text-xs font-black bg-rose-500/10 text-rose-400 px-2 py-0.5 rounded-full border border-rose-500/20">
                                    {achv.missing.length}
                                  </span>
                                </div>

                                {achv.missing.length > 0 ? (
                                  <div className="grid grid-cols-[repeat(auto-fill,minmax(130px,1fr))] gap-2 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                                    {achv.missing.map((member) => (
                                      <MemberPill
                                        key={member.id}
                                        member={member}
                                        variant="missing"
                                      />
                                    ))}
                                  </div>
                                ) : (
                                  <p className="text-sm text-slate-500 italic text-center py-4">
                                    Tout le monde a validé ce succès ! 🎉
                                  </p>
                                )}
                              </div>

                              {/* Col 2: HAS COMPLETED */}
                              <div className="bg-emerald-950/10 border border-emerald-900/10 shadow-sm rounded-2xl p-4">
                                <div className="flex items-center justify-between mb-4 pb-3 border-b border-emerald-900/20">
                                  <div className="flex items-center gap-2 font-bold text-sm">
                                    <div className="w-6 h-6 rounded-lg bg-emerald-500/10 border border-emerald-500/20 shadow-inner flex items-center justify-center">
                                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                                    </div>
                                    <span className="text-emerald-300">
                                      Déjà validé
                                    </span>
                                  </div>
                                  <span className="text-xs font-black bg-emerald-500/10 text-emerald-500 px-2 py-0.5 rounded-full border border-emerald-500/20">
                                    {achv.hasCompleted.length}
                                  </span>
                                </div>

                                {achv.hasCompleted.length > 0 ? (
                                  <div className="grid grid-cols-[repeat(auto-fill,minmax(130px,1fr))] gap-2 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                                    {achv.hasCompleted.map((member) => (
                                      <MemberPill
                                        key={member.id}
                                        member={member}
                                        variant="completed"
                                      />
                                    ))}
                                  </div>
                                ) : (
                                  <p className="text-sm text-slate-600 italic text-center py-4">
                                    Personne n'a encore validé ce succès.
                                  </p>
                                )}
                              </div>
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                })}
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function MemberPill({
  member,
  variant,
}: {
  member: any;
  variant: "missing" | "completed";
}) {
  const isMissing = variant === "missing";

  return (
    <div
      className={`flex items-center gap-2 pl-1 pr-3 py-1 rounded-full border transition-colors ${
        isMissing
          ? "bg-slate-900/60 hover:bg-slate-900/80 border-white/5 hover:border-white/10 text-slate-200"
          : "bg-black/20 border-white/5 text-slate-400"
      }`}
    >
      <div
        className={`w-6 h-6 rounded-full overflow-hidden shrink-0 ${!member.imageUrl && "bg-slate-800 flex items-center justify-center border border-white/5"}`}
      >
        {member.imageUrl ? (
          <img
            src={member.imageUrl}
            alt={member.name}
            className="w-full h-full object-cover"
          />
        ) : (
          <Users className="w-3 h-3 text-slate-400" />
        )}
      </div>

      <span className="text-xs font-medium truncate max-w-[100px]">
        {member.name}
      </span>

      {member.classe &&
        (() => {
          const cls = getClass(member.classe);
          return cls ? (
            <img
              src={cls.icon}
              alt={member.classe}
              className={`w-3.5 h-3.5 object-contain opacity-60 ${isMissing ? "grayscale-0" : "grayscale"}`}
              title={member.classe}
            />
          ) : null;
        })()}
    </div>
  );
}

"use client";

import { useState, useCallback, useMemo, useTransition, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { io } from "socket.io-client";
import { buildWsUrl } from "@/lib/socket-utils";
import { Plus, Search, Trophy, Sword, RefreshCw, Frown, Users, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DjPostCard } from "./DjPostCard";
import { DjPostCreateModal } from "./DjPostCreateModal";
import { DjFiltersBar, type DjFiltersState } from "./DjFiltersBar";
import { AchievementTracker } from "./AchievementTracker";
import { DungeonDirectory } from "./DungeonDirectory";
import type { DjPostWithDetails } from "@/server/actions/dungeon-finder-actions";

const DEFAULT_FILTERS: DjFiltersState = {
    search: "",
    mode: "",
    minLevel: 1,
    maxLevel: 1000,
    showClosed: false,
    onlyWithAchievement: false,
    onlyWithSpots: false,
};

type Tab = "posts" | "tracker" | "directory";

interface DungeonFinderClientProps {
    guildId: string;
    initialPosts: DjPostWithDetails[];
    currentProfileId?: string;
    isAdmin?: boolean;
    // Server action bound at page level
    refreshPosts: () => Promise<DjPostWithDetails[]>;
    isDiscordConfigured?: boolean;
}

export function DungeonFinderClient({
    guildId,
    initialPosts,
    currentProfileId,
    isAdmin,
    refreshPosts,
    isDiscordConfigured,
}: DungeonFinderClientProps) {
    const [activeTab, setActiveTab] = useState<Tab>("posts");
    const [posts, setPosts] = useState<DjPostWithDetails[]>(initialPosts);
    const [isCreateOpen, setIsCreateOpen] = useState(false);
    const [filters, setFilters] = useState<DjFiltersState>(DEFAULT_FILTERS);
    const [isRefreshing, setIsRefreshing] = useState(false);
    const [initialDungeonId, setInitialDungeonId] = useState<string | undefined>(undefined);

    function handleCreateGroupDirect(dungeonId: string) {
        setInitialDungeonId(dungeonId);
        setIsCreateOpen(true);
    }

    async function handleRefresh() {
        setIsRefreshing(true);
        try {
            const fresh = await refreshPosts();
            setPosts(fresh);
        } catch {
            // Silently fail
        } finally {
            setIsRefreshing(false);
        }
    }

    // Real-time updates via WebSocket
    useEffect(() => {
        const socketUrl = buildWsUrl();
        const socket = io(socketUrl, {
            path: "/socket.io/",
            query: { guildId }
        });

        socket.on("connect", () => {
            console.log("[WS] 📡 Connecté pour Dungeon Finder");
        });

        socket.on("dj:finder:update", (data: any) => {
            console.log("[WS] 🔄 Update DJ reçu", data);
            handleRefresh();
        });

        return () => {
            socket.disconnect();
        };
    }, [guildId]);

    // Client-side filter
    const filteredPosts = useMemo(() => {
        const term = filters.search.toLowerCase();
        return posts.filter((p) => {
            if (!filters.showClosed && (p.status === "CLOSED" || p.status === "EXPIRED")) return false;
            if (filters.mode && p.mode !== filters.mode) return false;
            if (term) {
                const dName = p.dungeon?.name.toLowerCase() || "";
                const dBoss = p.dungeon?.bossName.toLowerCase() || "";
                const qName = p.questName?.toLowerCase() || "";
                if (!dName.includes(term) && !dBoss.includes(term) && !qName.includes(term)) return false;
            }
            if (p.dungeon) {
                if (p.dungeon.level < filters.minLevel || p.dungeon.level > filters.maxLevel) return false;
            }
            if (filters.onlyWithSpots) {
                const accepted = (p._acceptedCount ?? 0) + 1;
                if (accepted >= p.maxMembers) return false;
            }
            if (filters.onlyWithAchievement) {
                if (!p.wantedAchievementIds || p.wantedAchievementIds.length === 0) return false;
            }
            return true;
        });
    }, [posts, filters]);


    const myActivePosts = posts.filter((p) => p.profileId === currentProfileId && p.status === "OPEN");
    const canCreate = myActivePosts.length < 3;

    const TABS: { id: Tab; label: string; sub: string; icon: React.ElementType; color: string }[] = [
        { id: "posts", label: "Recherche DJ", sub: "Trouver un groupe", icon: Search, color: "zinc" },
        { id: "tracker", label: "Mes Succès", sub: "Ma progression", icon: Trophy, color: "amber" },
        { id: "directory", label: "Succès Commun", sub: "La guilde", icon: Users, color: "emerald" },
    ];

    return (
        <div className="space-y-8">
            {/* Dissociated Professional Tabs */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {TABS.map((tab) => {
                    const Icon = tab.icon;
                    const isActive = activeTab === tab.id;
                    const colorVariants = {
                        zinc: {
                            border: "border-white/20",
                            icon: "bg-white/10 border-white/20 text-white",
                            sub: "text-zinc-400",
                            glow: "bg-white",
                            shadow: "shadow-[0_0_20px_rgba(255,255,255,0.1)]"
                        },
                        amber: {
                            border: "border-amber-500/40",
                            icon: "bg-amber-500/10 border-amber-500/20 text-amber-400",
                            sub: "text-amber-400/80",
                            glow: "bg-amber-500",
                            shadow: "shadow-[0_0_15px_rgba(245,158,11,0.3)]"
                        },
                        emerald: {
                            border: "border-emerald-500/40",
                            icon: "bg-emerald-500/10 border-emerald-500/20 text-emerald-400",
                            sub: "text-emerald-400/80",
                            glow: "bg-emerald-500",
                            shadow: "shadow-[0_0_15px_rgba(16,185,129,0.3)]"
                        }
                    }[tab.color] || {
                        border: "border-white/20",
                        icon: "bg-white/10 border-white/20 text-white",
                        sub: "text-zinc-400",
                        glow: "bg-white",
                        shadow: "shadow-[0_0_20px_rgba(255,255,255,0.1)]"
                    };

                    return (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`relative group overflow-hidden flex items-center gap-4 p-5 rounded-2xl border transition-all duration-300 ${isActive
                                ? `bg-zinc-800/80 ${colorVariants.border} shadow-[0_20px_40px_-15px_rgba(0,0,0,0.7)] scale-[1.02]`
                                : "bg-zinc-900/20 border-white/5 hover:border-white/10 hover:bg-zinc-900/40"
                                }`}
                        >
                            {/* Top Indicator */}
                            {isActive && (
                                <motion.div 
                                    layoutId="active-pill"
                                    className={`absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-transparent via-${tab.color === 'zinc' ? 'white' : tab.color + '-500'} to-transparent`} 
                                />
                            )}

                            {/* Icon Box */}
                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 border transition-all duration-300 ${isActive
                                ? colorVariants.icon
                                : "bg-white/5 border-white/5 text-zinc-600 group-hover:text-zinc-400"
                                }`}>
                                <Icon className="w-5 h-5" />
                            </div>

                            {/* Labels */}
                            <div className="text-left">
                                <p className={`font-black text-xs uppercase tracking-[0.2em] transition-colors ${isActive ? "text-white" : "text-zinc-500"}`}>
                                    {tab.label}
                                </p>
                                <p className={`text-[10px] font-bold mt-0.5 transition-colors ${isActive ? colorVariants.sub : "text-zinc-600"}`}>
                                    {tab.sub}
                                </p>
                            </div>

                            {/* Accent Glow */}
                            {isActive && (
                                <div className={`absolute -bottom-2 -right-2 w-16 h-16 ${colorVariants.glow}/10 blur-2xl rounded-full`} />
                            )}
                        </button>
                    );
                })}
            </div>

            <div>
                {/* === POSTS TAB === */}
                {activeTab === "posts" && (
                    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        {/* Toolbar */}
                        <div className="flex flex-col xl:flex-row xl:items-start gap-4">
                            <div className="flex-1">
                                <DjFiltersBar
                                    filters={filters}
                                    onChange={setFilters}
                                    total={posts.filter((p) => p.status === "OPEN" || p.status === "FULL").length}
                                    filtered={filteredPosts.length}
                                />
                            </div>

                            <div className="flex items-center gap-2 shrink-0">
                                <Button
                                    variant="outline" size="icon"
                                    onClick={handleRefresh}
                                    disabled={isRefreshing}
                                    className="w-10 h-10 border-slate-700 text-slate-400 hover:text-white"
                                    title="Rafraîchir"
                                >
                                    <RefreshCw className={`w-4 h-4 ${isRefreshing ? "animate-spin" : ""}`} />
                                </Button>
                                <Button
                                    onClick={() => setIsCreateOpen(true)}
                                    disabled={!canCreate}
                                    title={canCreate ? "Créer un post" : "Tu as atteint la limite de 3 posts actifs"}
                                    className={`font-black h-10 gap-2 shadow-lg ${canCreate
                                        ? "bg-white hover:bg-zinc-200 text-zinc-900 shadow-white/5"
                                        : "bg-zinc-800/50 text-zinc-500 border border-white/5 cursor-not-allowed opacity-70"
                                        }`}
                                >
                                    {canCreate ? (
                                        <Plus className="w-4 h-4" />
                                    ) : (
                                        <AlertTriangle className="w-4 h-4" />
                                    )}
                                    Nouveau post
                                    {!canCreate && (
                                        <span className="ml-1 text-xs font-bold bg-amber-500/20 px-1.5 py-0.5 rounded">
                                            {myActivePosts.length}/3
                                        </span>
                                    )}
                                </Button>
                            </div>
                        </div>

                        {/* Anti-spam hint */}
                        {!canCreate && (
                            <div className="flex items-center gap-3 text-sm text-amber-400 bg-amber-500/8 border border-amber-500/20 rounded-xl px-4 py-3">
                                <AlertTriangle className="w-4 h-4 shrink-0" />
                                <span>
                                    Tu as <strong>{myActivePosts.length}/3</strong> posts actifs.{" "}
                                    <button
                                        onClick={() => setFilters({ ...DEFAULT_FILTERS, search: "" })}
                                        className="underline underline-offset-2 hover:text-amber-300 transition-colors"
                                    >
                                        Ferme ou expire un post existant
                                    </button>{" "}
                                    pour en créer un nouveau.
                                </span>
                            </div>
                        )}

                        {/* Posts grid */}
                        {filteredPosts.length === 0 ? (
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="flex flex-col items-center justify-center min-h-[320px] border border-dashed border-white/10 rounded-2xl bg-zinc-950/50 shadow-inner"
                            >
                                <div className="w-14 h-14 rounded-2xl bg-slate-900 border border-white/10 shadow-sm flex items-center justify-center mb-4">
                                    <Search className="w-6 h-6 text-slate-500" />
                                </div>
                                <h3 className="text-base font-bold text-slate-300 mb-1">Aucun post actif</h3>
                                <p className="text-sm text-slate-600 text-center max-w-xs">
                                    {filters.search || filters.mode
                                        ? "Modifie les filtres pour voir plus de posts."
                                        : "Sois le premier à créer un post de recherche de groupe !"}
                                </p>
                                {canCreate && (
                                    <Button
                                        className="mt-5 bg-white hover:bg-zinc-200 text-zinc-900 font-bold"
                                        onClick={() => setIsCreateOpen(true)}
                                    >
                                        <Plus className="w-4 h-4 mr-2" /> Créer un post
                                    </Button>
                                )}
                            </motion.div>
                        ) : (
                            <motion.div
                                layout
                                className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4"
                            >
                                <AnimatePresence>
                                    {filteredPosts.map((post) => (
                                        <DjPostCard
                                            key={post.id}
                                            post={post}
                                            guildId={guildId}
                                            currentProfileId={currentProfileId}
                                            isAdmin={isAdmin}
                                            onRefresh={handleRefresh}
                                            isDiscordConfigured={isDiscordConfigured}
                                        />
                                    ))}
                                </AnimatePresence>
                            </motion.div>
                        )}
                    </div>
                )}

                {/* === TRACKER TAB === */}
                {activeTab === "tracker" && (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <AchievementTracker guildId={guildId} />
                    </div>
                )}

                {/* === DIRECTORY TAB === */}
                {activeTab === "directory" && (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <DungeonDirectory guildId={guildId} onCreatePost={handleCreateGroupDirect} />
                    </div>
                )}
            </div>

            {/* Create modal */}
            <DjPostCreateModal
                guildId={guildId}
                isOpen={isCreateOpen}
                initialDungeonId={initialDungeonId}
                isDiscordConfigured={isDiscordConfigured}
                onClose={() => {
                    setIsCreateOpen(false);
                    setInitialDungeonId(undefined);
                }}
                onCreated={handleRefresh}
            />
        </div>
    );
}

"use client";

import { useEditor, EditorContent } from "@tiptap/react";
import { BubbleMenu } from "@tiptap/react/menus";
import StarterKit from "@tiptap/starter-kit";
import Link from "@tiptap/extension-link";
import Placeholder from "@tiptap/extension-placeholder";
import Typography from "@tiptap/extension-typography";
import { Color } from "@tiptap/extension-color";
import { TextStyle } from "@tiptap/extension-text-style";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { configureSlashCommand } from "./extensions/slash-command";
import { ResizableImage } from "./extensions/resizable-image";
import { uploadImageFile } from "./utils/image-upload";
import { Callout } from "./extensions/callout";
import {
    Bold,
    Italic,
    Strikethrough,
    Code,
    List,
    ListOrdered,
    Quote,
    Heading1,
    Heading2,
    Heading3,
    Undo,
    Redo,
    Smile,
    AlignLeft,
    AlignCenter,
    AlignRight,
    Palette,
    Image as ImageIcon
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { EmojiPicker } from "./emoji-picker";

interface AdvancedEditorProps {
    initialContent?: string;
    onChange: (content: string) => void;
    editable?: boolean;
    contentClassName?: string;
}

export function AdvancedEditor({ initialContent, onChange, editable = true, contentClassName }: AdvancedEditorProps) {
    // Force re-render on selection change to update toolbar state
    const [, forceUpdate] = useState(0);

    const editor = useEditor({
        immediatelyRender: false,
        extensions: [
            StarterKit.configure({
                heading: {
                    levels: [1, 2, 3],
                },
                // Prevent duplicate with standalone Link extension
                link: false,
            }),
            ResizableImage.configure({
                inline: true,
                allowBase64: true,
            }),
            Link.configure({
                openOnClick: false,
                HTMLAttributes: {
                    class: "text-primary underline decoration-primary/50 underline-offset-4 hover:decoration-primary transition-colors cursor-pointer",
                },
            }),
            Placeholder.configure({
                placeholder: "Tapez '/' pour les commandes ou commencez à écrire...",
            }),
            Typography,
            configureSlashCommand(),
            Callout,
            TextStyle,
            Color,
        ],
        content: initialContent,
        editable,
        editorProps: {
            attributes: {
                class: cn(
                    "prose prose-zinc dark:prose-invert max-w-none focus:outline-none min-h-[300px] px-4 py-2",
                    contentClassName
                ),
            },
            handlePaste: (view, event) => {
                const items = event.clipboardData?.items;
                if (!items) return false;

                for (const item of Array.from(items)) {
                    if (item.type.startsWith("image/")) {
                        event.preventDefault();
                        const file = item.getAsFile();
                        if (file) {
                            uploadImageFile(file).then((url) => {
                                if (url && editor) {
                                    editor.chain().focus().setImage({ src: url }).run();
                                }
                            });
                        }
                        return true;
                    }
                }
                return false;
            },
            handleDrop: (view, event) => {
                const files = event.dataTransfer?.files;
                if (!files?.length) return false;

                const imageFile = Array.from(files).find(f => f.type.startsWith("image/"));
                if (imageFile) {
                    event.preventDefault();
                    uploadImageFile(imageFile).then((url) => {
                        if (url && editor) {
                            editor.chain().focus().setImage({ src: url }).run();
                        }
                    });
                    return true;
                }
                return false;
            },
        },
        onUpdate: ({ editor }) => {
            onChange(editor.getHTML());
        },
        onSelectionUpdate: () => {
            forceUpdate(n => n + 1);
        }
    });

    if (!editor) {
        return null;
    }

    return (
        <div className="relative border border-white/10 rounded-2xl bg-zinc-950/50 flex flex-col h-full overflow-hidden shadow-2xl">
            {/* TOOLBAR (Sticky at top of editor) */}
            {editable && (
                <div className="flex items-center gap-1 p-2 border-b border-white/5 bg-zinc-900/95 backdrop-blur-md flex-wrap z-20">
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleBold().run()}
                        isActive={editor.isActive("bold")}
                        icon={Bold}
                        tooltip="Gras (Ctrl+B)"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleItalic().run()}
                        isActive={editor.isActive("italic")}
                        icon={Italic}
                        tooltip="Italique (Ctrl+I)"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleStrike().run()}
                        isActive={editor.isActive("strike")}
                        icon={Strikethrough}
                        tooltip="Barré"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()}
                        isActive={editor.isActive("heading", { level: 1 })}
                        icon={Heading1}
                        tooltip="Titre 1"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
                        isActive={editor.isActive("heading", { level: 2 })}
                        icon={Heading2}
                        tooltip="Titre 2"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}
                        isActive={editor.isActive("heading", { level: 3 })}
                        icon={Heading3}
                        tooltip="Titre 3"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleBulletList().run()}
                        isActive={editor.isActive("bulletList")}
                        icon={List}
                        tooltip="Liste à puces"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleOrderedList().run()}
                        isActive={editor.isActive("orderedList")}
                        icon={ListOrdered}
                        tooltip="Liste numérotée"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleBlockquote().run()}
                        isActive={editor.isActive("blockquote")}
                        icon={Quote}
                        tooltip="Citation"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleCodeBlock().run()}
                        isActive={editor.isActive("codeBlock")}
                        icon={Code}
                        tooltip="Bloc de code"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <input
                        type="color"
                        onInput={event => editor.chain().focus().setColor((event.target as HTMLInputElement).value).run()}
                        value={editor.getAttributes('textStyle').color || '#ffffff'}
                        className="w-8 h-8 rounded-lg bg-zinc-900 border border-white/10 cursor-pointer p-1 hover:bg-white/10 transition-colors"
                        title="Couleur du texte"
                    />
                    <ToolbarButton
                        onClick={() => {
                            const url = window.prompt("Entrez l'URL de l'image (ou laissez vide pour uploader):");
                            if (url) {
                                editor.chain().focus().setImage({ src: url }).run();
                                return;
                            }

                            const input = document.createElement("input");
                            input.type = "file";
                            input.accept = "image/*";
                            input.onchange = async () => {
                                if (input.files?.length) {
                                    const file = input.files[0];
                                    const uploadedUrl = await uploadImageFile(file);
                                    if (uploadedUrl) {
                                        editor.chain().focus().setImage({ src: uploadedUrl }).run();
                                    }
                                }
                            };
                            input.click();
                        }}
                        icon={ImageIcon}
                        tooltip="Insérer une image (Fichier ou URL)"
                    />
                    <EmojiPicker onSelect={(emoji) => editor.chain().focus().insertContent(emoji).run()} />
                    <div className="w-px h-6 bg-white/10 mx-1 ml-auto" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().undo().run()}
                        disabled={!editor.can().undo()}
                        icon={Undo}
                        tooltip="Annuler"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().redo().run()}
                        disabled={!editor.can().redo()}
                        icon={Redo}
                        tooltip="Rétablir"
                    />
                </div>
            )}

            {/* BUBBLE MENU (Floating on selection) */}
            {editable && editor && (
                <UnifiedBubbleMenu key="unified-editor-menu" editor={editor} />
            )}

            {/* EDITOR CONTENT (Scrollable area) */}
            <div className="flex-1 overflow-y-auto cursor-text bg-zinc-950/20" onClick={() => editor.chain().focus().run()}>
                <EditorContent editor={editor} className="min-h-full pb-32" />
            </div>

            <style jsx global>{`
                .ProseMirror p.is-editor-empty:first-child::before {
                    color: #71717a;
                    content: attr(data-placeholder);
                    float: left;
                    height: 0;
                    pointer-events: none;
                }
            `}</style>
        </div>
    );
}

function ToolbarButton({
    onClick,
    isActive,
    disabled,
    icon: Icon,
    tooltip,
    size = "default"
}: {
    onClick: () => void,
    isActive?: boolean,
    disabled?: boolean,
    icon: any,
    tooltip?: string,
    size?: "default" | "sm"
}) {
    return (
        <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={(e) => {
                onClick();
            }}
            onMouseDown={(e) => e.preventDefault()} // Prevent focus loss
            disabled={disabled}
            className={cn(
                "h-8 w-8 p-0 transition-all",
                isActive
                    ? "bg-indigo-500/20 text-indigo-400 hover:bg-indigo-500/30"
                    : "text-zinc-400 hover:bg-white/10 hover:text-zinc-100",
                size === "sm" && "h-7 w-7"
            )}
            title={tooltip}
        >
            <Icon className={cn("w-4 h-4", size === "sm" && "w-3 h-3")} />
        </Button>
    )
}

function UnifiedBubbleMenu({ editor }: { editor: any }) {
    if (!editor) return null;

    const isImage = editor.isActive("image");

    return (
        <BubbleMenu
            pluginKey="unified-menu-v3"
            editor={editor}
            className="flex items-center gap-1 overflow-hidden rounded-xl border border-white/10 bg-zinc-900/95 backdrop-blur-xl shadow-2xl p-1 animate-in fade-in zoom-in-95 duration-200"
            shouldShow={({ from, to }: any) => {
                // Determine if we should show the menu
                const isSelection = from !== to;
                const isImg = editor.isActive("image");
                return isImg || isSelection;
            }}
        >
            {isImage ? (
                <>
                    <button
                        type="button"
                        onClick={(e) => { e.preventDefault(); editor.chain().focus().updateAttributes("image", { layout: 'left' }).run(); }}
                        className={cn("p-2 rounded-lg transition-all hover:bg-white/10", editor.getAttributes("image").layout === 'left' ? "bg-indigo-500/20 text-indigo-400" : "text-zinc-400")}
                        title="Aligner à gauche (Habillage texte)"
                    >
                        <AlignLeft className="w-4 h-4" />
                    </button>
                    <button
                        type="button"
                        onClick={(e) => { e.preventDefault(); editor.chain().focus().updateAttributes("image", { layout: 'block' }).run(); }}
                        className={cn("p-2 rounded-lg transition-all hover:bg-white/10", (editor.getAttributes("image").layout === 'block' || !editor.getAttributes("image").layout) ? "bg-indigo-500/20 text-indigo-400" : "text-zinc-400")}
                        title="Centrer (Bloc)"
                    >
                        <AlignCenter className="w-4 h-4" />
                    </button>
                    <button
                        type="button"
                        onClick={(e) => { e.preventDefault(); editor.chain().focus().updateAttributes("image", { layout: 'right' }).run(); }}
                        className={cn("p-2 rounded-lg transition-all hover:bg-white/10", editor.getAttributes("image").layout === 'right' ? "bg-indigo-500/20 text-indigo-400" : "text-zinc-400")}
                        title="Aligner à droite (Habillage texte)"
                    >
                        <AlignRight className="w-4 h-4" />
                    </button>
                </>
            ) : (
                <>
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleBold().run()}
                        isActive={editor.isActive("bold")}
                        icon={Bold}
                        tooltip="Gras"
                        size="sm"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleItalic().run()}
                        isActive={editor.isActive("italic")}
                        icon={Italic}
                        tooltip="Italique"
                        size="sm"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleStrike().run()}
                        isActive={editor.isActive("strike")}
                        icon={Strikethrough}
                        tooltip="Barré"
                        size="sm"
                    />
                    <div className="w-px h-4 bg-white/10 mx-1" />
                    <input
                        type="color"
                        onInput={event => editor.chain().focus().setColor((event.target as HTMLInputElement).value).run()}
                        value={editor.getAttributes('textStyle').color || '#ffffff'}
                        className="w-6 h-6 rounded-md bg-zinc-950 border border-white/5 cursor-pointer p-0.5"
                    />
                    <EmojiPicker onSelect={(emoji) => editor.chain().focus().insertContent(emoji).run()} />
                </>
            )}
        </BubbleMenu>
    )
}

