                         {/* Spiral decorations */}
                         <div className="absolute top-0 left-0 w-full flex justify-around px-8 md:px-24 opacity-10 pointer-events-none mt-2">
                            {Array.from({length: 12}).map((_, i) => (
                                <div key={i} className="w-1.5 md:w-3.5 h-6 md:h-12 bg-black rounded-full -mt-3 md:-mt-6 shadow-inner" />
                            ))}
                        </div>

                        <div className="w-full h-full relative flex items-center justify-center">
                            <canvas
                                ref={canvasRef}
                                width={1200}
                                height={600}
                                className="w-full h-full object-contain touch-none cursor-crosshair drop-shadow-sm transition-transform active:scale-[1.005]"
                                style={{ cursor: isDrawer ? "crosshair" : "default" }}
                                {...(isDrawer ? handlers : {})}
                            />
                            <canvas
                                ref={overlayRef}
                                width={1200}
                                height={600}
                                className="absolute inset-0 w-full h-full pointer-events-none object-contain"
                            />
                        </div>

                        {submitted && (
                            <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center animate-in fade-in duration-500">
                                <div className="text-4xl md:text-7xl mb-1 md:mb-6 animate-bounce">🎨</div>
                                <h3 className="text-lg md:text-3xl font-black text-[#5d3fd3] uppercase italic tracking-tighter">C'EST ENVOYÉ !</h3>
                                <p className="text-slate-500 font-bold uppercase tracking-widest mt-0.5 md:mt-2 text-[6px] md:text-base">Attente des autres joueurs...</p>
                            </div>
                        )}
                    </div>

                    {/* RIGHT: Brush Sizes & Player Status */}
                    <div className="hidden lg:flex w-48 flex-col gap-6 shrink-0 min-h-0">
                         {/* Brush Sizes */}
                         <div className="bg-white/95 rounded-[2.5rem] p-8 flex flex-col items-center justify-center gap-8 shadow-2xl border-b-[10px] border-black/10">
                            {BRUSH_SIZES.map(size => (
                                <button
                                    key={size}
                                    onClick={() => setBrushSize(size)}
                                    className={cn(
                                        "rounded-full transition-all hover:scale-150",
                                        brushSize === size 
                                            ? "bg-[#5d3fd3] ring-[4px] ring-[#5d3fd3]/20 shadow-xl" 
                                            : "bg-slate-300 hover:bg-slate-400"
                                    )}
                                    style={{ width: size/2 + 8, height: size/2 + 8 }}
                                />
                            ))}
                        </div>

                        {/* Players */}
                        <div className="flex-1 bg-white/10 backdrop-blur-xl rounded-[2.5rem] border-4 border-white/20 p-6 flex flex-col shadow-2xl overflow-hidden min-h-0">
                             <div className="flex items-center gap-2 mb-6 px-1 shrink-0">
                                <div className="w-2 h-2 rounded-full bg-purple-400 animate-pulse" />
                                <span className="text-white/60 font-black text-xs uppercase tracking-[0.2em]">JOUEURS</span>
                            </div>
                            
                            <div className="flex flex-col gap-3 overflow-y-auto custom-scrollbar flex-1 pr-1">
                                {players.map(p => (
                                    <div key={p.id} className={cn(
                                        "flex items-center gap-4 p-4 rounded-2xl border-b-4 transition-all group",
                                        p.hasSubmitted 
                                            ? "bg-[#2ed573]/20 border-[#2ed573]/40 ring-1 ring-[#2ed573]/30" 
                                            : "bg-white/5 border-white/5 hover:bg-white/10"
                                    )}>
                                        <div className={cn(
                                            "w-3 h-3 rounded-full shadow-sm transition-all",
                                            p.hasSubmitted 
                                                ? "bg-[#2ed573] scale-110" 
                                                : "bg-white/20 animate-pulse group-hover:scale-125"
                                        )} />
                                        <span className={cn(
                                            "font-black text-sm truncate",
                                            p.hasSubmitted ? "text-white" : "text-white/40"
                                        )}>{p.username}</span>
                                        {voiceUserIds.includes((p as any).userId) && (
                                            <Mic size={12} className="text-emerald-400 ml-auto shrink-0" />
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

"use client";

import React, { useEffect, useRef, useState, useCallback, useMemo } from "react";
import { io, Socket } from "socket.io-client";
import { buildWsUrl } from "@/lib/socket-utils";
import { useSession } from "next-auth/react";
import { GarticLayout } from "./GarticLayout";
import { LobbyScreen } from "./LobbyScreen";
import { DrawingScreen } from "./DrawingScreen";
import { GuessingScreen } from "./GuessingScreen";
import { RevealScreen } from "./RevealScreen";
import { AtmosphericParticles } from "../ui/AtmosphericParticles";
import { Loader2, Plus, Users, ArrowRight, RefreshCw, Phone, Sparkles, X, ArrowRightCircle, Trophy, Crown, Home, LogOut, Mic, MicOff } from "lucide-react";
import { toast } from "sonner";
import { playSoundEffect } from "@/lib/sounds";
import { useRouter, useSearchParams } from "next/navigation";
import { cn } from "@/lib/utils";
import { useDiscordVoice } from "@/hooks/use-discord-voice";
import { DiscordVoiceOverlay } from "@/components/shared/DiscordVoiceOverlay";

interface AvailableRoom {
    roomId: string;
    playerCount: number;
    maxPlayers: number;
    mode: string;
}

export default function GarticGameWrapper({ roomId: initialRoomId, guildId, userName, userAvatar }: { roomId?: string, guildId: string, userName?: string, userAvatar?: string }) {
    const { data: session } = useSession();
    const router = useRouter();
    const searchParams = useSearchParams();
    const isSpectatorMode = searchParams.get('spectate') === 'true';

    const [phase, setPhase] = useState<"browse" | "game">(initialRoomId ? "game" : "browse");
    const [socket, setSocket] = useState<Socket | null>(null);
    const [gameState, setGameState] = useState<any>(null);
    const [currentRoomId, setCurrentRoomId] = useState<string | undefined>(initialRoomId);
    const [availableRooms, setAvailableRooms] = useState<AvailableRoom[]>([]);
    const [isCreating, setIsCreating] = useState(false);
    const [joiningId, setJoiningId] = useState<string | null>(null);
    const [isViewingGallery, setIsViewingGallery] = useState(false);

    // Discord Voice Monitoring
    const { voiceUsers } = useDiscordVoice(guildId, socket);
    const [showVoiceOverlay, setShowVoiceOverlay] = useState(true);

    // Active participants in game
    const gamePlayerIds = useMemo(() => 
        gameState?.players?.map((p: any) => p.userId).filter(Boolean) as string[] || [],
        [gameState?.players]
    );


    // Stable refs
    const sessionRef = useRef(session);
    useEffect(() => { sessionRef.current = session; }, [session]);

    const userNameRef = useRef(userName);
    useEffect(() => { userNameRef.current = userName; }, [userName]);

    const userAvatarRef = useRef(userAvatar);
    useEffect(() => { userAvatarRef.current = userAvatar; }, [userAvatar]);

    const currentRoomIdRef = useRef(currentRoomId);
    useEffect(() => { currentRoomIdRef.current = currentRoomId; }, [currentRoomId]);

    const lastHostId = useRef<string | null>(null);

    const getWsUrl = useCallback((): string => {
        return buildWsUrl();
    }, []);

    useEffect(() => {
        if (!session?.user?.id) return;

        const s = io(getWsUrl(), {
            path: "/socket.io/",
            transports: ["websocket", "polling"],
            reconnectionAttempts: 10,
            query: { guildId }
        });
        setSocket(s);

        s.on("connect", () => {
            const rId = currentRoomIdRef.current;
            const user = sessionRef.current?.user;
            if (!user) return;
            if (rId) {
                s.emit("gartic:room:join", { 
                    roomId: rId, 
                    playerObj: { 
                        userName: userName || user.name, 
                        userId: user.id, 
                        userAvatar: userAvatar || user.image,
                        isSpectator: isSpectatorMode
                    } 
                });
            } else {
                s.emit("gartic:room:list");
            }
        });

        s.on("gartic:room:list", (rooms: AvailableRoom[]) => {
            setAvailableRooms(rooms || []);
            setIsCreating(false);
            setJoiningId(null);
        });

        s.on("gartic:room:created", ({ roomId }: { roomId: string }) => {
            const user = sessionRef.current?.user;
            if (!user) return;
            setCurrentRoomId(roomId);
            setIsCreating(false); 
            const url = new URL(window.location.href);
            url.searchParams.set("room", roomId);
            window.history.replaceState(null, "", url.toString());
            s.emit("gartic:room:join", { 
                roomId, 
                playerObj: { userName: userName || user.name, userId: user.id, userAvatar: userAvatar || user.image } 
            });
        });

        s.on("gartic:state:update", (state: any) => {
            // Host migration notification
            if (lastHostId.current && state.hostId !== lastHostId.current) {
                const currentUserId = sessionRef.current?.user?.id;
                if (state.hostId === currentUserId || state.hostId === socket?.id) {
                    toast.success("Vous êtes maintenant l'hôte du salon !", { 
                        icon: <Crown className="text-yellow-400" />,
                        description: "Vous pouvez maintenant lancer la partie."
                    });
                    playSoundEffect("success");
                } else {
                    const newHost = state.players?.find((p: any) => p.id === state.hostId);
                    if (newHost) {
                        toast.info(`${newHost.username} est le nouvel hôte.`, { icon: "👑" });
                    }
                }
            }
            lastHostId.current = state.hostId;

            setGameState((prev: any) => {
                const phaseChanged = prev?.phase !== state.phase;
                if (phaseChanged) {
                    if (state.phase === "REVEAL") playSoundEffect("success");
                    else if (state.phase === "WRITING") playSoundEffect("ding");
                    else if (state.phase !== "LOBBY" && state.phase !== "STARTING") playSoundEffect("ding");
                }
                
                // Countdown sounds (3, 2, 1)
                if (state.phase === "STARTING" && state.timer !== prev?.timer) {
                    if (state.timer >= 1 && state.timer <= 3) {
                        playSoundEffect("count");
                    }
                }
                return state;
            });
            if (phase !== "game") setPhase("game");
        });

        s.on("gartic:error", (err: any) => {
            toast.error(err.message || "Une erreur est survenue");
            setIsCreating(false);
            setJoiningId(null);
        });

        s.on("gartic:sound:play", (soundName: "tick" | "ding" | "fail" | "success") => {
            playSoundEffect(soundName);
        });

        return () => { s.disconnect(); };
    }, [session?.user?.id, buildWsUrl]); // eslint-disable-line react-hooks/exhaustive-deps

    const handleCreate = useCallback(() => {
        if (!socket || isCreating) return;
        const user = sessionRef.current?.user;
        if (!user) return;
        setIsCreating(true);
        socket.emit("gartic:room:create", {
            maxPlayers: 14, drawTime: 60, mode: "NORMAL",
            userName: userNameRef.current || user.name, userId: user.id, userAvatar: userAvatarRef.current || user.image,
        });
    }, [socket, isCreating]);

    const handleJoin = useCallback((roomId: string, asSpectator: boolean = false) => {
        if (!socket || joiningId) return;
        const user = sessionRef.current?.user;
        if (!user) return;
        setJoiningId(roomId);
        setCurrentRoomId(roomId);
        socket.emit("gartic:room:join", { 
            roomId, 
            playerObj: { 
                userName: userNameRef.current || user.name, 
                userId: user.id, 
                userAvatar: userAvatarRef.current || user.image,
                isSpectator: asSpectator 
            } 
        });
    }, [socket, joiningId]);

    const handleRefresh = useCallback(() => { socket?.emit("gartic:room:list"); }, [socket]);

    const handleReturnToLobby = useCallback(() => {
        setPhase("browse");
        setGameState(null);
        setCurrentRoomId(undefined);
        const url = new URL(window.location.href);
        url.searchParams.delete("room");
        window.history.replaceState(null, "", url.toString());
        setTimeout(() => socket?.emit("gartic:room:list"), 300);
    }, [socket]);

    const handleExitToMenu = useCallback(() => {
        socket?.emit("gartic:room:leave");
        router.push(`/dashboard/${guildId}/mini-jeux#mini-jeux`);
    }, [socket, router, guildId]);

    // ── PHASE BROWSE ──
    if (phase === "browse" || !gameState) {
        return (
            <GarticLayout phase="BROWSE" onClose={handleExitToMenu}>
                <div className="flex flex-col items-center justify-start h-full min-h-full w-full max-w-4xl mx-auto md:gap-12 animate-in fade-in zoom-in duration-700 p-4 md:p-10 shrink-0">
                    {/* Header */}
                    <div className="text-center px-4">
                        <div className="inline-flex items-center gap-3 bg-white/10 backdrop-blur-md border border-white/20 px-6 py-2 rounded-full mb-8 shadow-xl">
                            <Sparkles size={18} className="text-[#a78bfa] animate-pulse" />
                            <span className="text-white font-black uppercase tracking-[0.3em] text-[10px] italic">SIGILOS ORIGINAL GAME</span>
                        </div>
                        
                        <div className="relative">
                            <h1 className="text-4xl md:text-8xl lg:text-9xl font-black italic text-white leading-none tracking-tighter drop-shadow-[0_10px_0_rgba(0,0,0,0.2)]">
                                SIGIL<span className="text-[#a78bfa]">PHONE</span>
                            </h1>
                            <div className="absolute -bottom-2 md:-bottom-4 left-1/2 -translate-x-1/2 w-24 md:w-48 h-2 md:h-3 bg-[#5d3fd3] rounded-full skew-x-[-20deg] shadow-lg" />
                        </div>
                        
                        <p className="mt-12 text-white/60 text-lg font-bold uppercase tracking-[0.2em] italic max-w-lg mx-auto leading-relaxed">
                            Le téléphone arabe version <span className="text-white underline decoration-purple-500 decoration-[4px] underline-offset-4">AMAKNA !</span> Écris, dessine, et rigole.
                        </p>
                    </div>

                    {!session ? (
                        <div className="bg-white/10 backdrop-blur-xl border-4 border-white/20 p-12 rounded-[3.5rem] flex flex-col items-center gap-6 shadow-2xl">
                            <Loader2 className="h-12 w-12 animate-spin text-[#a78bfa]" />
                            <p className="text-white font-black uppercase tracking-widest text-sm italic">Connexion au réseau...</p>
                        </div>
                    ) : (
                        <div className="w-full flex flex-col items-center gap-8">
                            <div className="w-full bg-white/10 backdrop-blur-xl border-[8px] border-white/10 rounded-[4rem] p-10 md:p-14 flex flex-col items-center gap-10 hover:bg-white/[0.15] transition-all group shadow-2xl relative overflow-hidden">
                                <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent pointer-events-none" />
                                
                                <div className="flex flex-col items-center gap-4 md:gap-6 z-10 transition-transform group-hover:scale-102 duration-500">
                                    <div className="w-16 h-16 md:w-20 md:h-20 bg-[#5d3fd3] rounded-2xl md:rounded-[1.5rem] flex items-center justify-center text-3xl md:text-5xl shadow-2xl border-b-4 md:border-b-8 border-black/20 group-hover:rotate-6 transition-all">
                                        🎮
                                    </div>
                                    <div className="text-center">
                                        <h3 className="text-white font-black text-xl md:text-3xl uppercase italic tracking-tighter">PRÊT POUR L'AVENTURE ?</h3>
                                        <p className="text-white/40 text-[9px] md:text-xs mt-2 font-black uppercase tracking-widest leading-none">Crée un salon et défie ta guilde !</p>
                                    </div>
                                </div>

                                <div className="w-full flex flex-col sm:flex-row gap-4 max-w-2xl">
                                    <button
                                        onClick={handleCreate}
                                        disabled={isCreating}
                                        className="flex-[2] py-5 md:py-7 rounded-2xl md:rounded-[2rem] bg-[#2ed573] hover:bg-[#26af5f] text-white font-black uppercase italic tracking-tighter text-lg md:text-2xl transition-all disabled:opacity-50 border-b-[6px] md:border-b-[10px] border-black/20 hover:translate-y-1 md:hover:translate-y-2 active:translate-y-2 active:border-b-0 shadow-2xl group flex items-center justify-center gap-4"
                                    >
                                        {isCreating ? (
                                            <Loader2 className="animate-spin h-6 w-6" />
                                        ) : (
                                            <>
                                                <span>NOUVEAU SALON</span>
                                                <ArrowRightCircle size={20} className="md:w-6 md:h-6 group-hover:translate-x-1 transition-transform" />
                                            </>
                                        )}
                                    </button>

                                    {availableRooms.length > 0 && (
                                        <div className="flex-[3] flex flex-col gap-3">
                                            {availableRooms.map(room => (
                                                <div key={room.roomId} className="bg-white/5 p-4 rounded-3xl border border-white/10 flex items-center justify-between group hover:bg-white/10 transition-all">
                                                    <div className="flex flex-col">
                                                        <span className="text-white font-black text-xs uppercase italic truncate max-w-[120px]">Salon de {room.roomId.slice(0, 6)}</span>
                                                        <span className="text-white/40 text-[9px] font-bold uppercase">{room.playerCount}/{room.maxPlayers} JOUEURS</span>
                                                    </div>
                                                    <div className="flex items-center gap-2">
                                                        <button 
                                                            onClick={() => handleJoin(room.roomId)}
                                                            className="px-4 py-2 bg-purple-500 hover:bg-purple-400 text-white font-black text-[10px] uppercase italic rounded-xl border-b-3 border-black/20 transition-all hover:scale-105"
                                                        >
                                                            Jouer
                                                        </button>
                                                        <button 
                                                            onClick={() => handleJoin(room.roomId, true)}
                                                            className="px-3 py-2 bg-white/5 hover:bg-white/10 text-white/40 hover:text-white font-black text-[9px] uppercase italic rounded-xl transition-all"
                                                        >
                                                            Regarder
                                                        </button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="flex items-center gap-8 text-white/20 font-black text-[10px] uppercase tracking-[0.4em] italic">
                                <span className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" /> SERVEUR : ACTIF</span>
                                <div className="w-1 h-1 rounded-full bg-white/20" />
                                <span>VERSION 2.0.4</span>
                            </div>
                        </div>
                    )}
                </div>
            </GarticLayout>
        );
    }

    // ── PHASE GAME ──
    const currentUserId = session?.user?.id;
    const isHost = (currentUserId && gameState.hostId === currentUserId) ||
        gameState.players?.find((p: any) => p.id === socket?.id)?.isHost ||
        gameState.players?.[0]?.id === socket?.id ||
        gameState.hostId === socket?.id;

    const isDrawer = !isSpectatorMode && !!gameState.task;

    const renderPhase = () => {
        switch (gameState.phase) {
            case "LOBBY":
                return (
                    <LobbyScreen
                        room={{
                            id: currentRoomId || gameState.id,
                            maxPlayers: gameState.maxPlayers || 14,
                            players: gameState.players,
                            mode: gameState.mode || "NORMAL"
                        }}
                        onStart={() => socket?.emit("gartic:game:start")}
                        onInvite={() => {
                            navigator.clipboard.writeText(window.location.href).catch(() => {});
                            toast.success("Lien d'invitation copié !");
                        }}
                        onClose={handleExitToMenu}
                        isHost={isHost}
                        voiceUsers={voiceUsers}
                    />
                );
            case "STARTING":
            case "INTERMISSION":
                return (
                    <div className="flex flex-col items-center justify-center h-full gap-4 md:gap-6 animate-pulse">
                        <div className="text-6xl md:text-9xl font-black text-purple-400 font-mono drop-shadow-xl mb-2 md:mb-4 text-white">
                             {gameState.timer || 0}
                        </div>
                        <h2 className="text-4xl font-black italic text-white uppercase tracking-tighter">
                            {gameState.phase === "STARTING" ? "La partie commence..." : "Préparation..."}
                        </h2>
                    </div>
                );
            case "WRITING":
                return (
                    <GuessingScreen
                        isDrawer={false}
                        isWriting={true}
                        wordCategory="Écris quelque chose !"
                        onSubmit={(text: string) => socket?.emit("gartic:text:submit", { text })}
                        socket={socket!}
                        timeLeft={gameState.timer || 0}
                        totalTime={gameState.maxTimer || 30}
                        round={gameState.round || 1}
                        totalRounds={gameState.players?.length || 1}
                        onClose={handleExitToMenu}
                        isSpectator={isSpectatorMode}
                        voiceUsers={voiceUsers}
                    />
                );
            case "DRAWING":
                return (
                    <DrawingScreen
                        key={gameState.round || 1}
                        isDrawer={isDrawer}
                        word={gameState.task?.content}
                        wordHint="C'est ton tour de dessiner !"
                        drawerName={session?.user?.name || "Moi"}
                        socket={socket!}
                        roomId={currentRoomId!}
                        timeLeft={gameState.timer || 0}
                        totalTime={gameState.maxTimer || 60}
                        players={gameState.players || []}
                        round={gameState.round || 1}
                        totalRounds={gameState.players?.length || 1}
                        onClose={handleExitToMenu}
                        isSpectator={isSpectatorMode}
                        voiceUsers={voiceUsers}
                    />
                );
            case "GUESSING":
                return (
                    <GuessingScreen
                        key={gameState.round || 1}
                        isDrawer={false}
                        wordHint="Devine ce qu'il a dessiné !"
                        wordCategory="Devinette"
                        currentWord={gameState.task?.content}
                        onSubmit={(text: string) => socket?.emit("gartic:text:submit", { text })}
                        socket={socket!}
                        timeLeft={gameState.timer || 0}
                        totalTime={gameState.maxTimer || 45}
                        round={gameState.round || 1}
                        totalRounds={gameState.players?.length || 1}
                        onClose={handleExitToMenu}
                        isSpectator={isSpectatorMode}
                        voiceUsers={voiceUsers}
                    />
                );
            case "REVEAL":
                return (
                    <RevealScreen
                        albums={gameState.albums || []}
                        revealIndex={gameState.revealIndex ?? 0}
                        isHost={isHost}
                        onNextAlbum={() => socket?.emit("gartic:reveal:next")}
                        onExit={handleExitToMenu}
                        players={gameState.players || []}
                    />
                );
            case "SCORES":
                return (
                    <div className={cn(
                        "flex flex-col items-center justify-start h-full min-h-full w-full max-w-5xl mx-auto md:gap-12 animate-in fade-in zoom-in duration-700 p-4 md:p-10 shrink-0 custom-scrollbar",
                        !isViewingGallery && "overflow-y-auto"
                    )}>
                        <div className="text-center px-4">
                            <div className="inline-flex items-center gap-3 bg-white/10 backdrop-blur-md border border-white/20 px-6 py-2 rounded-full mb-8 shadow-xl">
                                <Sparkles size={18} className="text-yellow-400 animate-pulse" />
                                <span className="text-white font-black uppercase tracking-[0.3em] text-[10px] italic">PARTIE TERMINÉE</span>
                            </div>
                            
                            <h2 className="text-3xl md:text-8xl font-black italic text-white uppercase leading-none tracking-tighter drop-shadow-[0_10px_0_rgba(0,0,0,0.2)] text-center">
                                MERCI D'AVOIR <span className="text-purple-300">JOUÉ !</span>
                            </h2>
                            <p className="mt-4 md:mt-8 text-white/60 text-sm md:text-xl font-bold uppercase tracking-[0.2em] italic max-w-2xl mx-auto leading-relaxed">
                                On espère que vous avez bien rigolé ! Prêt pour une autre session ?
                            </p>
                        </div>

                        {isViewingGallery ? (
                            <div className="w-full flex-1 min-h-[500px] animate-in fade-in slide-in-from-bottom-10 duration-700">
                                <div className="flex justify-end mb-4">
                                    <button 
                                        onClick={() => setIsViewingGallery(false)}
                                        className="px-6 py-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-black uppercase text-xs transition-all flex items-center gap-2"
                                    >
                                        <X size={16} /> Fermer la Galerie
                                    </button>
                                </div>
                                <RevealScreen 
                                    albums={gameState.albums || []}
                                    revealIndex={gameState.revealIndex || 0}
                                    isHost={false} // In scores, no auto-advance
                                    onNextAlbum={() => {}}
                                    onExit={() => setIsViewingGallery(false)}
                                    players={gameState.players}
                                />
                            </div>
                        ) : (
                            <>
                            <div className="w-full flex flex-wrap justify-center gap-6">
                                {gameState.players.map((p: any) => (
                                    <div 
                                        key={p.id} 
                                        className="flex flex-col items-center gap-3 group"
                                    >
                                        <div className="w-24 h-24 rounded-full border-[6px] border-white/10 bg-white/5 p-1 backdrop-blur-sm group-hover:scale-110 transition-transform duration-500">
                                            <img 
                                                src={p.userAvatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${p.username || p.userName}`} 
                                                alt="avatar" 
                                                className="w-full h-full object-cover rounded-full" 
                                            />
                                        </div>
                                        <span className="font-black text-white uppercase tracking-tighter text-sm italic group-hover:text-purple-300 transition-colors">
                                            {p.username || p.userName}
                                        </span>
                                    </div>
                                ))}
                            </div>

                            <button
                                onClick={() => setIsViewingGallery(true)}
                                className="w-full max-w-md py-6 rounded-[2.5rem] bg-white/10 hover:bg-white/20 text-white font-black uppercase italic tracking-widest text-lg transition-all border-b-[8px] border-black/20 hover:border-b-[4px] hover:translate-y-1 shadow-2xl flex items-center justify-center gap-4 group"
                            >
                                <Users size={24} className="group-hover:scale-110 transition-transform" />
                                <span>VOIR TOUT L'ALBUM</span>
                            </button>
                            </>
                        )}

                        <div className="flex flex-col sm:flex-row gap-4 md:gap-6 w-full max-w-2xl mt-4 md:mt-8">
                            <button 
                                onClick={handleReturnToLobby} 
                                className="flex-1 py-5 md:py-8 rounded-2xl md:rounded-[2.5rem] bg-[#2ed573] hover:bg-[#26af5f] text-white font-black uppercase italic tracking-tighter text-lg md:text-2xl transition-all border-b-[8px] md:border-b-[12px] border-black/20 hover:border-b-[4px] md:hover:border-b-[8px] hover:translate-y-1 active:translate-y-3 active:border-b-0 shadow-2xl flex items-center justify-center gap-3 md:gap-4 group"
                            >
                                <RefreshCw className="group-hover:rotate-180 transition-transform duration-700 w-6 h-6 md:w-8 md:h-8" />
                                <span>REOUVRIR</span>
                            </button>
                            
                            <button 
                                onClick={handleExitToMenu} 
                                className="flex-1 py-5 md:py-8 rounded-2xl md:rounded-[2.5rem] bg-[#ff4757] hover:bg-[#ff6b81] text-white font-black uppercase italic tracking-tighter text-lg md:text-2xl transition-all border-b-[8px] md:border-b-[12px] border-black/20 hover:border-b-[4px] md:hover:border-b-[8px] hover:translate-y-1 active:translate-y-3 active:border-b-0 shadow-2xl flex items-center justify-center gap-3 md:gap-4 group backdrop-blur-md"
                            >
                                <LogOut className="group-hover:-translate-x-1 transition-transform w-6 h-6 md:w-8 md:h-8" />
                                <span>QUITTER</span>
                            </button>
                        </div>
                    </div>
                );

            default:
                return (
                    <div className="flex flex-col items-center justify-center h-full text-white">
                        <Loader2 className="h-16 w-16 animate-spin mb-4" />
                        <h2 className="text-2xl font-black italic">Chargement...</h2>
                    </div>
                );
        }
    };

    return (
        <div className="relative">
            <GarticLayout 
                phase={gameState?.phase || "LOBBY"} 
                onClose={handleExitToMenu}
                spectators={gameState?.players?.filter((p: any) => p.isSpectator) || []}
                guildId={guildId}
                showVoiceOverlay={showVoiceOverlay}
                onToggleVoice={() => setShowVoiceOverlay(!showVoiceOverlay)}
            >
                {showVoiceOverlay && (
                    <DiscordVoiceOverlay 
                        users={voiceUsers} 
                        guildId={guildId}
                        gamePlayerIds={gamePlayerIds} 
                        currentUserId={(session?.user as any)?.discordId}
                    />
                )}
                {renderPhase()}
            </GarticLayout>
            <AtmosphericParticles />
        </div>
    );
}

"use client";

import React from "react";
import { GamePhase } from "../../types/socket-events";
import { LogOut, Mic, MicOff } from "lucide-react";

export const GarticStarDecorations = () => {
    return (
        <div className="absolute inset-0 pointer-events-none overflow-hidden">
            {/* Simulation of stars or background patterns */}
            <div className="absolute w-2 h-2 bg-white rounded-full top-10 left-10 opacity-20" />
            <div className="absolute w-3 h-3 bg-white rounded-full top-40 right-20 opacity-30" />
            <div className="absolute w-1 h-1 bg-white rounded-full bottom-20 left-1/3 opacity-10" />
        </div>
    );
};

export const GarticLayout = ({ 
    phase, 
    children, 
    onClose, 
    spectators = [], 
    guildId = "", 
    showVoiceOverlay = true, 
    onToggleVoice 
}: { 
    phase: string; 
    children: React.ReactNode; 
    onClose?: () => void; 
    spectators?: any[]; 
    guildId?: string; 
    showVoiceOverlay?: boolean; 
    onToggleVoice?: () => void; 
}) => {
    return (
        <div className="min-h-screen w-full relative bg-[#3d8be0] font-sans selection:bg-purple-500/30 select-none">
            {/* STABLE BACKGROUND LAYER (Overflow hidden to prevent scroll loops) */}
            <div className="absolute inset-0 overflow-hidden pointer-events-none z-0">
                {/* Base Gradient background */}
                <div className="absolute inset-0 bg-gradient-to-br from-[#3d8be0] via-[#5b96ea] to-[#8d69f1]" />
                
                {/* Sunburst/Radial rays effect */}
                <div 
                    className="absolute inset-x-[-50%] inset-y-[-50%] opacity-20"
                    style={{
                        background: 'conic-gradient(from 0deg, transparent 0deg, transparent 5deg, rgba(255,255,255,0.3) 10deg, transparent 15deg, transparent 20deg)',
                        backgroundSize: '100% 100%',
                        animation: 'spin 120s linear infinite'
                    }}
                />

                {/* Halftone/Dots pattern */}
                <div 
                    className="absolute inset-0 opacity-[0.15]"
                    style={{ 
                        backgroundImage: 'radial-gradient(rgba(0,0,0,0.5) 2px, transparent 2px)', 
                        backgroundSize: '24px 24px' 
                    }} 
                />
                
                <GarticStarDecorations />
            </div>

            <style jsx global>{`
                @keyframes spin {
                    from { transform: rotate(0deg); }
                    to { transform: rotate(360deg); }
                }
                body { overflow-x: hidden; }
            `}</style>

            {/* RETOUR SELECTION */}
            <div className="absolute top-2 left-2 md:top-6 md:left-6 z-[200] flex flex-col gap-2">
                <button 
                    onClick={() => window.location.href = `/dashboard/${guildId}/mini-jeux`}
                    className="group flex flex-col items-center justify-center w-10 h-10 md:w-16 md:h-16 bg-white/10 backdrop-blur-md rounded-xl md:rounded-2xl border border-white/10 shadow-lg transition-all hover:scale-110 active:scale-95 group"
                    title="Retour à la sélection"
                >
                    <div className="text-white transition-transform group-hover:rotate-12">
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="w-5 h-5 md:w-8 md:h-8">
                            <rect x="3" y="3" width="7" height="7" />
                            <rect x="14" y="3" width="7" height="7" />
                            <rect x="14" y="14" width="7" height="7" />
                            <rect x="3" y="14" width="7" height="7" />
                        </svg>
                    </div>
                </button>

                {onToggleVoice && (
                    <button 
                        onClick={onToggleVoice}
                        className={`group flex flex-col items-center justify-center w-10 h-10 md:w-16 md:h-16 backdrop-blur-md rounded-xl md:rounded-2xl border shadow-lg transition-all hover:scale-110 active:scale-95 group ${
                            showVoiceOverlay 
                                ? "bg-emerald-500/20 border-emerald-500/30 text-emerald-400" 
                                : "bg-white/10 border-white/10 text-white/40"
                        }`}
                        title={showVoiceOverlay ? "Masquer le vocal" : "Afficher le vocal"}
                    >
                        {showVoiceOverlay ? <Mic size={24} className="w-5 h-5 md:w-8 md:h-8" /> : <MicOff size={24} className="w-5 h-5 md:w-8 md:h-8" />}
                    </button>
                )}

                {/* Spectators bubbles - Below Home button */}
                {spectators.length > 0 && (
                    <div className="flex items-center gap-3 px-4 py-2 bg-white/10 backdrop-blur-md border border-white/10 rounded-2xl">
                        <div className="flex -space-x-2">
                            {spectators.slice(0, 5).map((s, idx) => (
                                <div key={s.id || idx} className="w-8 h-8 rounded-full border-2 border-white/20 bg-zinc-900 overflow-hidden grayscale opacity-60 hover:grayscale-0 hover:opacity-100 hover:z-10 transition-all cursor-help ring-2 ring-black/10" title={s.username || s.userName}>
                                    <img src={s.userAvatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${s.username || s.userName}`} className="w-full h-full object-cover rounded-full" alt="" />
                                </div>
                            ))}
                            {spectators.length > 5 && (
                                <div className="w-8 h-8 rounded-full bg-white/10 border-2 border-white/20 flex items-center justify-center text-[10px] font-black text-white/50 backdrop-blur-sm">
                                    +{spectators.length - 5}
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>

            {onClose && (
                <button 
                    onClick={onClose}
                    className="absolute top-2 right-2 md:top-6 md:right-6 z-[200] px-4 md:px-6 py-2 md:py-3 bg-red-500 hover:bg-red-400 text-white rounded-xl md:rounded-2xl border-b-4 border-black/20 transition-all hover:scale-105 active:scale-95 shadow-2xl flex items-center gap-2 font-black italic uppercase text-[10px] md:text-xs group"
                    title="Quitter la partie"
                >
                    <LogOut size={16} className="group-hover:-translate-x-1 transition-transform" />
                    <span className="hidden sm:inline">Quitter</span>
                    <span className="sm:hidden">Sortir</span>
                </button>
            )}

            <div className="w-full relative z-10 px-4 pt-10 md:pt-16 pb-20 md:pb-24 flex flex-col items-center">
                {children}
            </div>
        </div>
    );
};

"use client";

import React, { useState, useEffect, useRef } from "react";
import { Socket } from "socket.io-client";
import { ChatMessage } from "../../types/socket-events";
import { cn } from "@/lib/utils";
import { CircularTimer } from "./CircularTimer";
import { playSoundEffect } from "@/lib/sounds";

interface GuessingScreenProps {
    isDrawer: boolean;
    isWriting?: boolean;
    wordHint?: string;
    wordCategory?: string;
    currentWord?: string;
    onSubmit: (text: string) => void;
    socket: Socket;
    timeLeft: number;
    totalTime: number;
    playerClass?: string;
    round?: number;
    totalRounds?: number;
    onClose?: () => void;
    isSpectator?: boolean;
    voiceUsers?: any[];
}

export const GuessingScreen = ({ 
    isDrawer, 
    isWriting, 
    wordHint, 
    wordCategory, 
    currentWord, 
    onSubmit, 
    socket, 
    timeLeft, 
    totalTime, 
    playerClass,
    round = 1,
    totalRounds = 1,
    onClose,
    isSpectator,
    voiceUsers = []
}: GuessingScreenProps) => {
    const [guess, setGuess] = useState("");
    const [submitted, setSubmitted] = useState(false);
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const inputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (timeLeft === 10) {
            playSoundEffect("gartic-ring");
        }
    }, [timeLeft]);

    useEffect(() => {
        if (!socket) return;
        socket.on("gartic:chat:broadcast", (msg: ChatMessage) => {
            setMessages(prev => [...prev, msg]);
        });
        socket.on("gartic:guess:correct", ({ username, points }: any) => {
            setMessages(prev => [...prev, {
                type: "correct",
                content: `✅ ${username} a trouvé ! (+${points} pts)`,
                isCorrect: true,
            }]);
        });
        return () => {
            socket.off("gartic:chat:broadcast");
            socket.off("gartic:guess:correct");
        };
    }, [socket]);

    const handleSubmit = () => {
        if (!guess.trim() || submitted || isSpectator) return;
        onSubmit(guess);
        setSubmitted(true);
        setGuess("");
    };

    if (isDrawer || isSpectator) {
        const title = isSpectator ? "OBSERVATION EN COURS..." : "LES AUTRES DEVINENT...";
        const subtitle = isSpectator ? "Regarde les albums se former !" : "Tu as dessiné :";
        return (
            <div className="flex flex-col items-center justify-center h-full w-full animate-in zoom-in-95 duration-500 p-4">
                <div className="w-full max-w-4xl bg-white/10 backdrop-blur-md border-[4px] md:border-[6px] border-white/20 rounded-[2rem] md:rounded-[3rem] p-6 md:p-12 text-center flex flex-col items-center gap-4 md:gap-6 shadow-2xl overflow-hidden shrink-0">
                    <div className="text-4xl md:text-8xl animate-bounce drop-shadow-xl mb-1 md:mb-4">🎨</div>
                    <h2 className="text-white text-xl md:text-5xl font-black uppercase tracking-tighter italic leading-tight">
                        LES AUTRES DEVINENT...
                    </h2>
                    <p className="text-white/60 text-xs md:text-xl font-bold uppercase tracking-widest italic">
                        Tu as dessiné :
                    </p>
                    <div className="text-white text-xl md:text-6xl font-black bg-white/10 px-4 md:px-12 py-2 md:py-8 rounded-xl md:rounded-[2rem] border-[2px] md:border-4 border-white/20 shadow-2xl">
                        {currentWord}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="flex flex-col items-center justify-center w-full max-w-[98vw] animate-in zoom-in-95 duration-500 relative py-2 md:py-4 lg:py-6 overflow-hidden">
            {/* Top Bar - Round & Timer */}
            <div className="absolute top-2 md:top-4 inset-x-4 md:inset-x-8 z-50 flex items-center justify-between select-none pointer-events-none">
                <div className="flex flex-col items-start translate-y-1 md:translate-y-2">
                    <span className="text-white/40 font-black text-[8px] md:text-sm tracking-[0.2em] md:tracking-[0.3em] uppercase italic">ROUND</span>
                    <span className="text-white font-black text-xl md:text-5xl italic drop-shadow-[0_5px_0_rgba(0,0,0,0.2)]">
                        {round}<span className="text-white/30 text-sm md:text-3xl">/{totalRounds}</span>
                    </span>
                </div>
                
                <div className="scale-[0.6] md:scale-100 drop-shadow-2xl translate-y-2 md:translate-y-4">
                    <CircularTimer remaining={timeLeft} total={totalTime} />
                </div>
            </div>
 
            {/* Main Stage */}
            <div className="w-full bg-white/10 backdrop-blur-xl border-[4px] md:border-[8px] border-white/10 rounded-[1.5rem] md:rounded-[4rem] p-2 md:p-8 shadow-2xl flex flex-col items-center gap-2 md:gap-4 relative mt-10 md:mt-20 shrink-0 min-h-0 overflow-hidden grow">
                
                {/* Purple Card Header - Fluid */}
                <div className="w-full max-w-3xl bg-[#5d3fd3] rounded-[1.2rem] md:rounded-[2.5rem] p-3 md:p-6 relative shadow-2xl -mt-8 md:-mt-16 border-b-[4px] md:border-b-[10px] border-black/20 z-20 shrink-0">
                    <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 md:w-48 h-5 md:h-8 bg-black/20 rounded-b-[1.5rem] md:rounded-b-[2rem] flex items-center justify-center">
                        <span className="text-white/40 font-black text-[6px] md:text-[8px] tracking-[0.2em] md:tracking-[0.4em] uppercase italic">SIGIL PHONE</span>
                    </div>
 
                    <div className="mt-2 md:mt-4 text-center">
                        <h2 className="text-white text-lg md:text-3xl lg:text-4xl font-black uppercase tracking-tighter italic drop-shadow-lg leading-tight">
                            {isWriting ? "À TOI DE COMMENCER !" : "DÉCRIS CETTE SCÈNE !"}
                        </h2>
                    </div>
                </div>
 
                {/* Notebook Content Area - Adaptive */}
                <div className="w-full bg-white rounded-[1.2rem] md:rounded-[3rem] p-2 md:p-10 shadow-2xl border-b-[6px] md:border-b-[12px] border-black/10 flex items-center justify-center overflow-hidden relative grow min-h-[120px] md:min-h-[250px]">
                    {/* Spiral decorations for the notebook */}
                    <div className="absolute top-0 left-0 w-full flex justify-around px-8 md:px-24 opacity-10 pointer-events-none mt-2">
                        {Array.from({length: 12}).map((_, i) => (
                            <div key={i} className="w-2 md:w-3.5 h-8 md:h-12 bg-black rounded-full -mt-4 md:-mt-6 shadow-inner" />
                        ))}
                    </div>

                    {isWriting ? (
                        <div className="flex flex-col items-center gap-3 md:gap-10 py-2">
                            <div className="relative group shrink-0">
                                <div className="absolute inset-0 bg-purple-500/30 blur-[40px] md:blur-[100px] rounded-full group-hover:bg-purple-500/40 transition-all duration-1000" />
                                <img 
                                    src={`https://sigilos.fr/images/classes/${playerClass || '1'}_1.png`} 
                                    alt="Class Avatar" 
                                    className="w-20 h-20 md:w-56 md:h-56 object-contain animate-float drop-shadow-[0_25px_35px_rgba(0,0,0,0.3)] relative z-10 hover:scale-110 transition-transform duration-500"
                                    onError={(e) => {
                                        (e.target as HTMLImageElement).src = 'https://api.dicebear.com/7.x/bottts/svg?seed=sigil';
                                    }}
                                />
                            </div>
                            <div className="text-center flex flex-col gap-1 md:gap-2">
                                <p className="text-[#3d2080] font-black text-sm md:text-2xl uppercase tracking-tighter italic px-4">
                                    ÉCRIS UNE PHRASE !
                                </p>
                                <p className="text-slate-400 font-bold uppercase tracking-widest text-[6px] md:text-xs">SOIS CRÉATIF, SOIS DRÔLE !</p>
                            </div>
                        </div>
                    ) : (
                        <div className="w-full h-full flex items-center justify-center p-2">
                            {currentWord && currentWord.startsWith("data:") ? (
                                <img src={currentWord} alt="Guess this" className="max-w-full max-h-[250px] md:max-h-[500px] object-contain rounded-xl md:rounded-2xl drop-shadow-xl animate-in fade-in zoom-in-95 duration-700" />
                            ) : (
                                <div className="flex flex-col items-center gap-2">
                                    <div className="w-8 h-8 md:w-20 md:h-20 border-3 md:border-8 border-[#5d3fd3]/20 border-t-[#5d3fd3] rounded-full animate-spin" />
                                    <div className="text-[#a46522] font-black italic text-sm md:text-3xl uppercase tracking-widest animate-pulse">Chargement...</div>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Bottom Input Area - Adaptive */}
                <div className="w-full max-w-4xl flex flex-col md:flex-row gap-2 md:gap-6 mt-1 md:mt-4 shrink-0 pb-1 md:pb-0">
                    <div className="flex-1 bg-white/10 backdrop-blur-xl border-[4px] border-white/20 rounded-[1.2rem] md:rounded-[2.5rem] flex items-center px-4 md:px-10 shadow-2xl focus-within:bg-white/15 focus-within:border-white/30 transition-all group overflow-hidden">
                        <input
                            ref={inputRef}
                            value={guess}
                            onChange={(e) => setGuess(e.target.value)}
                            onKeyDown={(e) => e.key === "Enter" && handleSubmit()}
                            placeholder={submitted ? "Patientez..." : "Ta description ici..."}
                            disabled={submitted}
                            className="w-full bg-transparent border-none text-white text-lg md:text-2xl font-black placeholder:text-white/20 outline-none py-2 md:py-6 group-focus-within:translate-x-1 transition-transform"
                            autoFocus
                        />
                    </div>
                    <button
                        onClick={handleSubmit}
                        disabled={submitted || !guess.trim()}
                        className={cn(
                            "px-6 md:px-10 py-3 md:py-6 rounded-[1.2rem] md:rounded-[2.5rem] font-black text-white text-lg md:text-2xl tracking-tighter uppercase transition-all shadow-2xl group relative overflow-hidden shrink-0",
                            "bg-[#2ed573] hover:bg-[#26af5f]",
                            "border-b-[6px] md:border-b-[12px] border-[#1e9b53] active:border-b-0 active:translate-y-2 shadow-black/20",
                            (submitted || !guess.trim()) && "opacity-50 grayscale cursor-not-allowed translate-y-0"
                        )}
                    >
                        <div className="flex items-center gap-2 md:gap-4 relative z-10 justify-center">
                            {submitted ? (
                                <>
                                    <span className="text-xl md:text-4xl">✓</span>
                                    <span>ENVOYÉ</span>
                                </>
                            ) : (
                                <>
                                    <span>ENVOYER !</span>
                                    <div className="w-6 h-6 md:w-10 md:h-10 bg-white/20 rounded-full flex items-center justify-center group-hover:rotate-12 transition-transform hidden sm:flex">
                                        <span className="scale-100 md:scale-125">✅</span>
                                    </div>
                                </>
                            )}
                        </div>
                    </button>
                </div>
            </div>
        </div>
    );
};

