"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import {
    Settings,
    User,
    Search,
    ScrollText,
    Trophy,
    Sparkles,
    Crown,
    CheckSquare,
    LogOut,
    Home,
    Loader2,
    Users
} from "lucide-react";
import { useDebounce } from "use-debounce";
import { globalSearch, SearchResult } from "@/server/actions/search-actions";

import {
    CommandDialog,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
    CommandSeparator,
    CommandShortcut,
} from "@/components/ui/command";

interface CommandMenuProps {
    guildId: string;
}

export function CommandMenu({ guildId }: CommandMenuProps) {
    const [open, setOpen] = React.useState(false);
    const [query, setQuery] = React.useState("");
    const [debouncedQuery] = useDebounce(query, 300);
    const [results, setResults] = React.useState<SearchResult[]>([]);
    const [isLoading, setIsLoading] = React.useState(false);
    const router = useRouter();

    React.useEffect(() => {
        const down = (e: KeyboardEvent) => {
            if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                setOpen((open) => !open);
            }
        };

        const openMenu = () => setOpen(true);

        document.addEventListener("keydown", down);
        document.addEventListener("open-command-menu", openMenu);
        return () => {
            document.removeEventListener("keydown", down);
            document.removeEventListener("open-command-menu", openMenu);
        };
    }, []);

    React.useEffect(() => {
        if (debouncedQuery.length < 2) {
            setResults([]);
            return;
        }

        const performSearch = async () => {
            setIsLoading(true);
            try {
                const searchResults = await globalSearch(debouncedQuery, guildId);
                setResults(searchResults);
            } catch (error) {
                console.error("Search failed:", error);
            } finally {
                setIsLoading(false);
            }
        };

        performSearch();
    }, [debouncedQuery, guildId]);

    const runCommand = React.useCallback((command: () => void) => {
        setOpen(false);
        command();
    }, []);

    // Filter results by type
    const memberResults = results.filter(r => r.type === "MEMBER");
    const missionResults = results.filter(r => r.type === "MISSION");
    const pageResults = results.filter(r => r.type === "PAGE");

    return (
        <CommandDialog
            open={open}
            onOpenChange={setOpen}
            shouldFilter={false}
            className="bg-zinc-950 border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.5)] sm:max-w-[550px] rounded-2xl overflow-hidden p-0 gap-0"
        >
            <div className="relative">
                <div className="flex items-center border-b border-white/5 px-4 bg-white/[0.02]">
                    <Search className="mr-3 h-4 w-4 shrink-0 text-zinc-500" />
                    <CommandInput 
                        placeholder="Recherche globale..." 
                        className="h-14 font-medium flex-1 bg-transparent focus:ring-0 border-none outline-none text-sm text-zinc-200 placeholder:text-zinc-600" 
                        value={query}
                        onValueChange={setQuery}
                    />
                    {isLoading && (
                        <Loader2 className="ml-2 h-4 w-4 animate-spin text-zinc-500" />
                    )}
                </div>

                <CommandList className="max-h-[380px] premium-scrollbar p-2">
                    <CommandEmpty className="py-12 text-center text-xs text-zinc-600">
                        Aucun résultat pour "{query}"
                    </CommandEmpty>

                    {/* --- DYNAMIC RESULTS --- */}
                    {results.length > 0 && (
                        <>
                            {memberResults.length > 0 && (
                                <CommandGroup heading={<span className="text-zinc-500 font-black tracking-widest uppercase text-[9px] px-2 mb-2 block">Membres</span>}>
                                    {memberResults.map((r) => (
                                        <CommandItem 
                                            key={r.id} 
                                            onSelect={() => runCommand(() => router.push(r.href))}
                                            className="group mx-1 my-0.5 p-2.5 rounded-xl data-[selected=true]:bg-white/5 border border-transparent transition-all"
                                        >
                                            <div className="w-8 h-8 rounded-lg border border-white/5 bg-white/5 flex items-center justify-center mr-3 shrink-0">
                                                <Users className="h-4 w-4 text-zinc-400" />
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className="font-bold text-zinc-200 truncate text-sm">{r.title}</span>
                                                {r.subtitle && <span className="text-[10px] text-zinc-600 truncate">{r.subtitle}</span>}
                                            </div>
                                        </CommandItem>
                                    ))}
                                </CommandGroup>
                            )}

                            {missionResults.length > 0 && (
                                <CommandGroup heading={<span className="text-zinc-500 font-black tracking-widest uppercase text-[9px] px-2 mb-2 block">Missions</span>}>
                                    {missionResults.map((r) => (
                                        <CommandItem 
                                            key={r.id} 
                                            onSelect={() => runCommand(() => router.push(r.href))}
                                            className="group mx-1 my-0.5 p-2.5 rounded-xl data-[selected=true]:bg-white/5 border border-transparent transition-all"
                                        >
                                            <div className="w-8 h-8 rounded-lg border border-white/5 bg-white/5 flex items-center justify-center mr-3 shrink-0">
                                                <ScrollText className="h-4 w-4 text-zinc-400" />
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className="font-bold text-zinc-200 truncate text-sm">{r.title}</span>
                                                {r.subtitle && <span className="text-[10px] text-zinc-600 truncate">{r.subtitle}</span>}
                                            </div>
                                        </CommandItem>
                                    ))}
                                </CommandGroup>
                            )}

                            {pageResults.length > 0 && (
                                <CommandGroup heading={<span className="text-zinc-500 font-black tracking-widest uppercase text-[9px] px-2 mb-2 block">Pages</span>}>
                                    {pageResults.map((r) => (
                                        <CommandItem 
                                            key={r.id} 
                                            onSelect={() => runCommand(() => router.push(r.href))}
                                            className="group mx-1 my-0.5 p-2.5 rounded-xl data-[selected=true]:bg-white/5 border border-transparent transition-all"
                                        >
                                            <div className="w-8 h-8 rounded-lg border border-white/5 bg-white/5 flex items-center justify-center mr-3 shrink-0">
                                                <Sparkles className="h-4 w-4 text-zinc-400" />
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className="font-bold text-zinc-200 truncate text-sm">{r.title}</span>
                                            </div>
                                        </CommandItem>
                                    ))}
                                </CommandGroup>
                            )}
                            <CommandSeparator className="bg-white/5 my-2" />
                        </>
                    )}

                    <CommandGroup heading={<span className="text-zinc-500 font-black tracking-widest uppercase text-[9px] px-2 mb-2 block">Navigation</span>}>
                        <CommandItem 
                            onSelect={() => runCommand(() => router.push(`/dashboard/${guildId}`))}
                            className="mx-1 my-0.5 rounded-xl data-[selected=true]:bg-white/5 transition-all p-2.5"
                        >
                            <Home className="mr-3 h-3.5 w-3.5 text-zinc-500" />
                            <span className="font-semibold text-sm">Tableau de bord</span>
                        </CommandItem>
                        <CommandItem 
                            onSelect={() => runCommand(() => router.push(`/dashboard/${guildId}/missions`))}
                            className="mx-1 my-0.5 rounded-xl data-[selected=true]:bg-white/5 transition-all p-2.5"
                        >
                            <ScrollText className="mr-3 h-3.5 w-3.5 text-zinc-500" />
                            <span className="font-semibold text-sm">Missions</span>
                        </CommandItem>
                        <CommandItem 
                            onSelect={() => runCommand(() => router.push(`/dashboard/${guildId}/ladder`))}
                            className="mx-1 my-0.5 rounded-xl data-[selected=true]:bg-white/5 transition-all p-2.5"
                        >
                            <Trophy className="mr-3 h-3.5 w-3.5 text-zinc-500" />
                            <span className="font-semibold text-sm">Ladder</span>
                        </CommandItem>
                    </CommandGroup>

                    <CommandSeparator className="bg-white/5 my-2" />

                    <CommandGroup>
                        <CommandItem 
                            onSelect={() => runCommand(() => router.push("/api/auth/signout"))}
                            className="mx-1 my-0.5 rounded-xl data-[selected=true]:bg-red-500/10 text-red-500/80 transition-all p-2.5"
                        >
                            <LogOut className="mr-3 h-3.5 w-3.5" />
                            <span className="font-bold text-sm">Déconnexion</span>
                        </CommandItem>
                    </CommandGroup>
                </CommandList>

                <div className="p-3 bg-white/[0.02] border-t border-white/5 flex items-center justify-between text-[9px] font-black text-zinc-700 uppercase tracking-widest px-6">
                    <span>Recherche globale</span>
                    <span>v3.0</span>
                </div>
            </div>
        </CommandDialog>
    );
}

"use client";

import { useState, useEffect } from "react";
import { 
    Sheet, 
    SheetContent, 
    SheetHeader, 
    SheetTitle, 
    SheetTrigger 
} from "@/components/ui/sheet";
import { 
    ChevronRight, 
    LayoutDashboard, 
    Shield, 
    PlusCircle, 
    Crown, 
    ExternalLink,
    Loader2,
    Settings2
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { getGuildsSeparated } from "@/server/actions/user-actions";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";

interface DashboardDrawerProps {
    children: React.ReactNode;
    clientId?: string;
}

export function DashboardDrawer({ children, clientId = "1458259008355045519" }: DashboardDrawerProps) {
    const [open, setOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [guilds, setGuilds] = useState<{ active: any[], pending: any[] }>({ active: [], pending: [] });

    const loadGuilds = async () => {
        setLoading(true);
        try {
            const data = await getGuildsSeparated();
            setGuilds({ active: data.active, pending: data.pending });
        } catch (error) {
            console.error("Failed to load guilds for drawer:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (open) {
            loadGuilds();
        }
    }, [open]);

    // Auto-refresh when bot is successfully invited from the drawer link
    useEffect(() => {
        const handleMessage = (event: MessageEvent) => {
            if (event.data === "sigilos-bot-invited" && event.origin === window.location.origin) {
                window.location.reload();
            }
        };

        window.addEventListener("message", handleMessage);
        return () => window.removeEventListener("message", handleMessage);
    }, []);

    return (
        <Sheet open={open} onOpenChange={setOpen}>
            <SheetTrigger asChild>
                {children}
            </SheetTrigger>
            <SheetContent className="w-full sm:max-w-md bg-zinc-950/80 backdrop-blur-2xl border-l border-white/10 p-0 overflow-hidden flex flex-col">
                <div className="absolute inset-0 z-0 pointer-events-none">
                    <div className="absolute top-[-10%] right-[-10%] w-[300px] h-[300px] bg-emerald-500/10 rounded-full blur-[100px]" />
                    <div className="absolute bottom-[-10%] left-[-10%] w-[300px] h-[300px] bg-indigo-500/10 rounded-full blur-[100px]" />
                </div>

                <SheetHeader className="p-8 pb-4 relative z-10">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center shadow-lg">
                            <LayoutDashboard className="w-5 h-5 text-emerald-400" />
                        </div>
                        <SheetTitle className="text-2xl font-black text-white italic tracking-tighter uppercase">Gestion SigilOS</SheetTitle>
                    </div>
                    <p className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.3em]">Gestion Multi-Guilde & Déploiement</p>
                </SheetHeader>

                <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8 relative z-10">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center py-20 gap-4">
                            <Loader2 className="w-8 h-8 animate-spin text-emerald-500" />
                            <p className="text-xs font-black text-zinc-500 uppercase tracking-widest animate-pulse">Chargement de vos accès...</p>
                        </div>
                    ) : (
                        <>
                            {/* ACTIVE GUILDS */}
                            <div className="space-y-4">
                                <div className="flex items-center justify-between px-2">
                                    <h3 className="text-[11px] font-black text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-2">
                                        <Shield className="w-3 h-3" /> Vos Accès Actifs
                                    </h3>
                                    <span className="text-[10px] font-bold text-zinc-600 bg-white/5 px-2 py-0.5 rounded-full border border-white/5">{guilds.active.length}</span>
                                </div>

                                <div className="grid gap-3">
                                    <AnimatePresence mode="popLayout">
                                        {guilds.active.map((guild, i) => (
                                            <motion.div
                                                key={guild.id}
                                                initial={{ opacity: 0, x: 20 }}
                                                animate={{ opacity: 1, x: 0 }}
                                                transition={{ delay: i * 0.05 }}
                                            >
                                                <Link 
                                                    href={`/dashboard/${guild.id}`}
                                                    onClick={() => setOpen(false)}
                                                    className="group flex items-center gap-4 p-4 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 hover:border-emerald-500/30 transition-all shadow-xl"
                                                >
                                                    <Avatar className="h-12 w-12 rounded-xl border border-white/10 group-hover:border-emerald-500/50 transition-colors">
                                                        <AvatarImage src={guild.icon || ""} alt={guild.name} />
                                                        <AvatarFallback className="bg-zinc-900 text-zinc-500 font-black rounded-xl text-xs">
                                                            {guild.name.substring(0, 2).toUpperCase()}
                                                        </AvatarFallback>
                                                    </Avatar>
                                                    <div className="flex-1 min-w-0">
                                                        <div className="text-sm font-black text-white group-hover:text-emerald-400 transition-colors truncate uppercase italic tracking-tighter">
                                                            {guild.name}
                                                        </div>
                                                        <div className="flex items-center gap-2 mt-0.5">
                                                            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                                                            <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest truncate">
                                                                {guild.isAdmin ? "Administrateur" : "Membre Actif"}
                                                            </span>
                                                        </div>
                                                    </div>
                                                    <ChevronRight className="w-4 h-4 text-zinc-700 group-hover:text-emerald-400 group-hover:translate-x-1 transition-all" />
                                                </Link>
                                            </motion.div>
                                        ))}
                                    </AnimatePresence>

                                    {guilds.active.length === 0 && (
                                        <div className="p-8 text-center rounded-2xl border border-dashed border-white/5 bg-white/5">
                                            <p className="text-xs font-bold text-zinc-600 uppercase tracking-widest italic">Aucun accès détecté</p>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* PENDING / DEPLOYMENT */}
                            {guilds.pending.length > 0 && (
                                <div className="space-y-4 pt-4 border-t border-white/5">
                                    <div className="flex items-center justify-between px-2">
                                        <h3 className="text-[11px] font-black text-amber-500 uppercase tracking-[0.2em] flex items-center gap-2">
                                            <PlusCircle className="w-3 h-3" /> Déploiement Disponible
                                        </h3>
                                    </div>

                                    <div className="grid gap-3">
                                        {guilds.pending.map((guild, i) => (
                                            <motion.div
                                                key={guild.id}
                                                initial={{ opacity: 0, scale: 0.95 }}
                                                animate={{ opacity: 1, scale: 1 }}
                                                transition={{ delay: 0.2 + (i * 0.05) }}
                                                className="group flex items-center gap-4 p-4 rounded-2xl bg-amber-500/5 border border-amber-500/10 hover:bg-amber-500/10 transition-all border-dashed"
                                            >
                                                <Avatar className="h-10 w-10 rounded-xl border border-white/10 opacity-60">
                                                    <AvatarImage src={guild.icon || ""} alt={guild.name} />
                                                    <AvatarFallback className="bg-zinc-900 text-zinc-600 font-bold rounded-xl text-[10px]">
                                                        {guild.name.substring(0, 2).toUpperCase()}
                                                    </AvatarFallback>
