                                Support 24/7
                            </Link>
                            <Link href="/legal/faq" className="text-zinc-500 hover:text-white transition-colors text-xs font-bold uppercase tracking-widest">Centre d'aide</Link>
                            <div className="pt-2">
                                <BugReportButton />
                            </div>
