                                    )}
                                </div>
                            </div>
                        )}

                        {!isValidated && (
                            isPendingValidation ? (
                                <Button
                                    size="sm"
                                    variant="outline"
                                    className="h-9 px-4 text-[10px] font-black bg-red-500/5 text-red-400 border-red-500/20 hover:bg-red-500/10"
                                    onClick={handleCancel}
                                >
                                    ANNULER
                                </Button>
                            ) : (
                                <Button
                                    size="sm"
                                    className={cn(
                                        "h-9 px-5 text-[10px] font-black uppercase tracking-[2px] transition-all border",
