type ValidationCardProps = {
    submission: {
        id: string;
        createdAt: Date;
        proofUrl: string;
        mission: {
            category: MissionCategory;
            title: string | null;
            rank: number;
            xpReward: number | null;
            payload: any;
        };
        profile: {
            discordNickname: string | null;
            pseudoDofus: string | null;
            classe: string | null;
            isAdmin: boolean;
            user: {
                name: string | null;
                image: string | null;
            };
        };
        helpers: {
            id: string;
            pseudoDofus: string | null;
            user: {
                name: string | null;
                image: string | null;
            };
        }[];
    };
    onValidate: () => void;
    onReject: () => void;
    onZoom: () => void;
    isProcessing: boolean;
};

// Helper function for default level based on rank
function getDefaultLevel(rank: number): number {
    const levelMap: Record<number, number> = { 1: 50, 2: 100, 3: 150, 4: 180, 5: 200 };
    return levelMap[rank] || 50;
}

export function ValidationCard({ submission, onValidate, onReject, onZoom, isProcessing }: ValidationCardProps) {
    const config = CATEGORY_CONFIG[submission.mission.category];
    const Icon = config.icon;
    const payload = submission.mission.payload as any;
    const displayLevel = payload.level || getDefaultLevel(submission.mission.rank || 1);

    return (
        <Card className={cn(
            "flex flex-col relative overflow-hidden transition-all duration-500 group border-white/5 bg-[#121417] shadow-2xl",
            "hover:border-white/10 hover:shadow-[0_0_30px_rgba(0,0,0,0.5)]"
        )}>
            {/* ----------------- HEADER BAR (Full Width) ----------------- */}
            <div className={cn(
                "relative z-20 flex flex-wrap items-center gap-3 sm:gap-4 px-4 py-2.5 shadow-inner border-b border-white/5",
                "overflow-hidden transition-all duration-500"
            )}>
                {/* AI BACKGROUND BANNER */}
                <div className="absolute inset-0 z-0">
                    <Image
                        src={config.bannerImage}
                        alt="Banner"
                        fill
                        className="object-cover opacity-60 mix-blend-luminosity grayscale-[0.2]"
                        unoptimized={true}
                    />
                    <div className={cn(
                        "absolute inset-0 bg-gradient-to-r mix-blend-multiply opacity-90",
                        config.headerGradient
                    )} />
                </div>

                {/* Noise texture overlay */}
                <div className="absolute inset-0 opacity-[0.12] mix-blend-overlay pointer-events-none bg-[url(/noise.svg)] bg-repeat z-10" />

                {/* Visual indicator (Lueur) */}
                <div className="absolute inset-x-0 bottom-0 h-[1px] bg-white/20 blur-[1px] z-10" />

                <div className="relative shrink-0 z-10">
                    <div className="absolute inset-0 bg-white/20 blur-[8px] rounded-full scale-75 opacity-0 group-hover:opacity-100 transition-opacity" />
                    <div className="w-8 h-8 rounded-lg flex items-center justify-center bg-black/40 backdrop-blur-md border border-white/10 shadow-lg relative transition-transform group-hover:scale-105">
                        <Icon className={cn("w-4 h-4 text-white")} />
                    </div>
                </div>

                <div className="min-w-0 flex-1 relative z-10 break-words pr-2">
                    <h3 className="font-black text-xs sm:text-base text-white drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] tracking-tight uppercase leading-tight">
                        {submission.mission.title || "Mission Sans Titre"}
                    </h3>
                </div>

                {/* Rank, Level + Countdown */}
                <div className="ml-auto flex items-center gap-2 relative z-10 shrink-0">
                    <SubmissionCountdown createdAt={submission.createdAt} />
                    <div className="flex items-center bg-black/60 rounded px-2 h-6 border border-white/10 shrink-0">
                        <span className="text-[9px] font-black text-zinc-400 uppercase tracking-wider mr-1.5">RANG</span>
                        <span className="text-xs font-black text-white">{submission.mission.rank || 1}</span>
                    </div>
                    <div className="h-4 w-[1px] bg-white/10 shrink-0" />
                    <span className="text-zinc-300 font-bold italic text-xs tracking-tight shrink-0">
                        Niv. {displayLevel}
                    </span>
                </div>
            </div>

            {/* ----------------- USER INFO BAR ----------------- */}
            <div className="relative z-10 px-4 py-2 bg-zinc-950/50 border-b border-zinc-800/50 flex flex-wrap items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-zinc-800 overflow-hidden relative shrink-0 border border-white/10">
                    {submission.profile.user.image ? (
                        <Image
                            src={submission.profile.user.image}
                            alt={submission.profile.user.name || "User"}
                            fill
                            className="object-cover"
                            unoptimized={true}
                        />
                    ) : (
                        <div className="flex items-center justify-center h-full w-full text-zinc-600">
                            <UserIcon className="w-4 h-4" />
                        </div>
                    )}
                </div>
                <div className="flex flex-col min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                        <span className="text-xs font-semibold text-white truncate max-w-[120px]">
                            {submission.profile.discordNickname || submission.profile.user.name || "Membre Inconnu"}
                        </span>
                        {submission.profile.isAdmin && (
                            <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <ShieldCheck className="w-3 h-3 text-purple-400 drop-shadow-[0_0_8px_rgba(168,85,247,0.4)] shrink-0" />
                                    </TooltipTrigger>
                                    <TooltipContent side="top" className="bg-zinc-900 border-purple-500/30 text-purple-200 text-[10px] font-bold uppercase tracking-wider">
                                        Administration
                                    </TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        )}
                    </div>
                </div>
                
                <div className="flex flex-wrap items-center gap-2 ml-auto">
                    {submission.profile.pseudoDofus && (
                        <Badge variant="secondary" className="text-[10px] h-5 px-2 bg-zinc-800 text-zinc-400 font-normal shrink-0">
                            {submission.profile.pseudoDofus}
                        </Badge>
                    )}
                    {submission.profile.classe && (
                        <Badge variant="outline" className="text-[10px] h-5 px-2 border-zinc-700 text-zinc-500 font-normal shrink-0">
                            {submission.profile.classe}
                        </Badge>
                    )}
                </div>
            </div>

            {/* ----------------- CONTENT BODY ----------------- */}
            <CardContent className="p-4 space-y-3 flex-1 relative bg-gradient-to-b from-[#1a1c20] to-[#121417]">
                {/* Sub-Atmosphere Glow */}
                <div className={cn(
                    "absolute -bottom-10 -left-10 w-40 h-40 rounded-full opacity-10 blur-3xl pointer-events-none transition-all duration-1000 group-hover:scale-150",
                    config.bgColor
                )} />

                {/* Mission Rewards */}
                <div className="flex items-center gap-3 text-xs">
                    {submission.mission.xpReward && (
                        <div className="flex items-center gap-1 text-amber-400">
                            <Trophy className="w-3 h-3" />
                            <span className="font-mono">{submission.mission.xpReward} XP</span>
                        </div>
                    )}
                    {submission.mission.payload?.kamas && (
                        <div className="flex items-center gap-1 text-yellow-400">
                            <Target className="w-3 h-3" />
                            <span className="font-mono">{submission.mission.payload.kamas}k</span>
                        </div>
                    )}
                </div>

                {/* Contributors */}
                {submission.helpers && submission.helpers.length > 0 && (
                    <div className="flex items-center gap-2 pt-2 border-t border-zinc-800/50">
                        <Users className="w-3.5 h-3.5 text-indigo-400" />
                        <span className="text-[10px] text-zinc-500 font-medium">Contributeurs:</span>
                        <div className="flex items-center -space-x-2">
                            {submission.helpers.slice(0, 5).map((helper) => (
                                <TooltipProvider key={helper.id}>
                                    <Tooltip>
                                        <TooltipTrigger asChild>
                                            <Avatar className="w-6 h-6 border-2 border-zinc-900 ring-1 ring-indigo-500/30">
                                                <AvatarImage src={helper.user.image || undefined} />
                                                <AvatarFallback className="text-[8px] bg-zinc-800">
                                                    {(helper.pseudoDofus || helper.user.name || "?").slice(0, 2).toUpperCase()}
                                                </AvatarFallback>
                                            </Avatar>
                                        </TooltipTrigger>
                                        <TooltipContent side="top" className="text-xs">
                                            {helper.pseudoDofus || helper.user.name || "Membre"}
                                        </TooltipContent>
                                    </Tooltip>
                                </TooltipProvider>
                            ))}
                            {submission.helpers.length > 5 && (
                                <div className="w-6 h-6 rounded-full bg-zinc-800 border-2 border-zinc-900 flex items-center justify-center text-[8px] text-zinc-400 font-bold">
                                    +{submission.helpers.length - 5}
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {/* Proof Image Preview */}
                <div
                    className="relative aspect-video rounded-lg bg-black overflow-hidden border border-zinc-800 group mt-2 cursor-zoom-in"
                    onClick={onZoom}
                >
                    <Image
                        src={submission.proofUrl}
                        alt="Preuve"
                        fill
                        className="object-contain"
                        unoptimized={true}
                    />

                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white text-xs font-medium gap-2">
                        <ExternalLink className="w-4 h-4" />
                        Agrandir
                    </div>
                </div>
            </CardContent>

            {/* ----------------- FOOTER: ACTIONS ----------------- */}
            <CardFooter className="p-3 bg-zinc-950/30 border-t border-zinc-800/50 grid grid-cols-2 gap-3">
                <Button
                    variant="sigil-destructive"
                    onClick={onReject}
                    disabled={isProcessing}
                    className="h-10"
                >
                    <X className="w-4 h-4 mr-2" />
                    Refuser
                </Button>
                <Button
                    variant="sigil-emerald"
                    onClick={onValidate}
                    disabled={isProcessing}
                    className="h-10"
                >
                    <Check className="w-4 h-4 mr-2" />
                    Valider
                </Button>
            </CardFooter>
        </Card>
    );
}

'use client'

import { useState, useEffect, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent, CardFooter, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { validateSubmission } from "@/server/actions/mission-actions";
import { Submission, Mission, UserProfile, User, MissionCategory } from "@prisma/client";
import { Check, X, ExternalLink, Search, Filter as FilterIcon, User as UserIcon, RefreshCcw, ShieldCheck, Users, Target, Trophy } from "lucide-react";
import { toast } from "sonner";
import Image from "next/image";
import { cn } from "@/lib/utils";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { ValidationCard } from "./validation-card";

type ExtendedSubmission = Submission & {
    mission: Mission;
    profile: {
        id: string;
        userId: string;
        discordNickname: string | null;
        pseudoDofus: string | null;
        classe: string | null;
        discordRoleName: string | null;
        isAdmin: boolean;
        user: {
            id: string;
            name: string | null;
            image: string | null;
        };
    };
    helpers: {
        id: string;
        pseudoDofus: string | null;
        user: {
            name: string | null;
            image: string | null;
        };
    }[];
};

const CATEGORIES: { label: string; value: MissionCategory | 'ALL' }[] = [
    { label: "Toutes les catégories", value: "ALL" },
    { label: "Donjon", value: "DONJON" },
    { label: "Régulation", value: "REGULATION" },
    { label: "Anomalie", value: "ANOMALIE" },
    { label: "Songes", value: "SONGES" },
    { label: "Expédition", value: "EXPEDITION" },
    { label: "Événement", value: "EVENT" },
];

export function ValidationQueue({ submissions: initialSubmissions, guildId }: { submissions: ExtendedSubmission[], guildId: string }) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [submissions, setSubmissions] = useState(initialSubmissions);

    useEffect(() => {
        setSubmissions(initialSubmissions);
    }, [initialSubmissions]);
    const [processingId, setProcessingId] = useState<string | null>(null);

    // Filters
    const [searchTerm, setSearchTerm] = useState("");
    const [categoryFilter, setCategoryFilter] = useState<MissionCategory | 'ALL'>('ALL');

    const handleDecision = (id: string, status: "VALIDATED" | "REJECTED") => {
        setProcessingId(id);
        startTransition(async () => {
            const result = await validateSubmission(guildId, id, status);
            setProcessingId(null);

            if (result.success) {
                toast.success(status === "VALIDATED" ? "Validé avec succès" : "Refusé");
                setSubmissions(prev => prev.filter(s => s.id !== id));
                router.refresh(); // Ensure server state is synced
            } else {
                toast.error(result.error || "Erreur action");
            }
        });
    };

    const [selectedImage, setSelectedImage] = useState<string | null>(null);

    // Filter Logic
    const filteredSubmissions = submissions.filter(item => {
        const matchesCategory = categoryFilter === 'ALL' || item.mission.category === categoryFilter;

        const searchLower = searchTerm.toLowerCase();
        const matchesSearch =
            (item.profile.pseudoDofus || "").toLowerCase().includes(searchLower) ||
            (item.profile.user.name || "").toLowerCase().includes(searchLower) ||
            (item.mission.title || "").toLowerCase().includes(searchLower);

        return matchesCategory && matchesSearch;
    });

    return (
        <div className="space-y-6">
            {/* Toolbar: Stats & Filters */}
            <div className="flex flex-col md:flex-row gap-4 items-start md:items-center justify-between bg-zinc-900/50 p-4 rounded-xl border border-white/5">
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2 text-sm text-zinc-400 border-r border-white/10 pr-4">
                        <span className="text-white font-medium">{submissions.length}</span> en attente
                    </div>
                    <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 text-zinc-400 hover:text-white transition-colors"
                        onClick={() => startTransition(() => router.refresh())}
                        disabled={isPending}
                        title="Actualiser la liste"
                    >
                        <RefreshCcw className={cn("w-4 h-4", isPending && "animate-spin")} />
                    </Button>
                </div>

                <div className="flex flex-col sm:flex-row gap-2 w-full md:w-auto">
                    {/* Search */}
                    <div className="relative w-full sm:w-64">
                        <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-zinc-500" />
                        <Input
                            placeholder="Chercher membre ou mission..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="pl-9 h-9 bg-black/20 border-white/10"
                        />
                    </div>

                    {/* Category Filter */}
                    <Select value={categoryFilter} onValueChange={(v) => setCategoryFilter(v as any)}>
                        <SelectTrigger className="w-full sm:w-[180px] h-9 bg-black/20 border-white/10">
                            <FilterIcon className="w-3.5 h-3.5 mr-2 opacity-50" />
                            <SelectValue placeholder="Catégorie" />
                        </SelectTrigger>
                        <SelectContent className="max-h-[300px]">
                            {CATEGORIES.map(c => (
                                <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                </div>
            </div>

            {/* Grid */}
            {filteredSubmissions.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-[40vh] text-zinc-500 border border-dashed border-zinc-800 rounded-xl bg-zinc-900/20">
                    <Check className="w-12 h-12 mb-4 opacity-20" />
                    <p>Aucune soumission correspondante.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {filteredSubmissions.map((item) => (
                        <ValidationCard
                            key={item.id}
                            submission={item}
                            onValidate={() => handleDecision(item.id, "VALIDATED")}
                            onReject={() => handleDecision(item.id, "REJECTED")}
                            onZoom={() => setSelectedImage(item.proofUrl)}
                            isProcessing={processingId === item.id}
                        />
                    ))}
                </div>
            )}

            {/* Lightbox / Zoom Modal */}
            {selectedImage && (
                <div
                    className="fixed inset-0 z-50 bg-black/95 flex items-center justify-center p-4 cursor-zoom-out"
                    onClick={() => setSelectedImage(null)}
                >
                    <img
                        src={selectedImage}
                        className="max-w-full max-h-full object-contain shadow-2xl"
                        alt="Zoom"
                    />
                    <Button
                        variant="ghost"
                        size="icon"
                        className="absolute top-4 right-4 text-white hover:bg-white/10"
                        onClick={() => setSelectedImage(null)}
                    >
                        <X className="w-6 h-6" />
                    </Button>
                </div>
            )}
        </div>
    );
}

