                                                    {req.monsterName}
                                                </span>
                                            </div>
                                            
                                            {req.message && (
                                                <p className="text-[10px] text-zinc-600 italic bg-zinc-900/40 px-3 py-1 rounded-lg border border-white/5 truncate max-w-[200px] lg:max-w-xs">
