"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { Users, Plus, X, Save, Edit2, AlertCircle, Copy, Shield, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { DOFUS_CLASSES, getClass } from "@/lib/dofus-assets";
import NextImage from "next/image";

export type Mule = {
    id?: string;
    pseudo: string;
    classe?: string;
    level?: number;
};

interface AltPseudosProps {
    altPseudos?: any[];
    onSave?: (pseudos: Mule[]) => Promise<any>;
    readOnly?: boolean;
    maxPseudos?: number;
}

export function AltPseudos({
    altPseudos = [],
    onSave,
    readOnly = false,
    maxPseudos = 10,
}: AltPseudosProps) {
    const [isEditing, setIsEditing] = useState(false);
    const [localPseudos, setLocalPseudos] = useState<Mule[]>([]);

    const [newPseudo, setNewPseudo] = useState("");
    const [newClass, setNewClass] = useState<string>("cra");
    const [newLevel, setNewLevel] = useState<string>("200");
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Sync and normalize local state when props change
    useEffect(() => {
        const normalized = altPseudos.map(p => {
            if (typeof p === "string") {
                return { id: crypto.randomUUID(), pseudo: p, classe: "cra", level: 200 };
            }
            return {
                id: p.id || crypto.randomUUID(),
                pseudo: p.pseudo || "Inconnu",
                classe: p.classe || "cra",
                level: p.level !== undefined ? p.level : 200
            };
        });
        setLocalPseudos(normalized);
    }, [altPseudos]);

    const formatPseudo = (value: string) => {
        // Supprimer les chiffres et caractères spéciaux (autorise UNIQUEMENT lettres et tirets)
        const cleaned = value.replace(/[^a-zA-Z\u00C0-\u017F\u00DF\u00FF\u0100-\u017F-]/g, "");
        if (!cleaned) return "";
        
        // Formater : 1ère lettre majuscule, reste minuscule. Si '-', 1ère lettre après '-' majuscule.
        return cleaned
            .split("-")
            .map(part => {
                if (part.length === 0) return part;
                return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
            })
            .join("-");
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setNewPseudo(formatPseudo(e.target.value));
    };

    const validatePseudo = (pseudo: string): { valid: boolean; error?: string } => {
        if (pseudo.length < 3) return { valid: false, error: "Minimum 3 caractères" };
        if (pseudo.length > 20) return { valid: false, error: "Maximum 20 caractères" };
        // Le pseudo est déjà formaté par formatPseudo
        return { valid: true };
    };

    const handleAddPseudo = () => {
        const trimmed = newPseudo.trim();
        if (!trimmed) return;

        if (localPseudos.length >= maxPseudos) {
            toast.error(`Maximum ${maxPseudos} personnages`);
            return;
        }

        if (localPseudos.some(p => p.pseudo.toLowerCase() === trimmed.toLowerCase())) {
            toast.error("Ce pseudo est déjà ajouté");
            return;
        }

        const validation = validatePseudo(trimmed);
        if (!validation.valid) {
            toast.error(validation.error);
            return;
        }

        let lvl = parseInt(newLevel, 10);
        if (isNaN(lvl) || lvl < 0 || lvl > 200) lvl = 200;

        setLocalPseudos(prev => [...prev, { id: crypto.randomUUID(), pseudo: trimmed, classe: newClass, level: lvl }]);
        setNewPseudo("");
        setNewLevel("200");
    };

    const handleRemovePseudo = (idToRemove: string) => {
        setLocalPseudos(prev => prev.filter(p => p.id !== idToRemove));
    };

    const handleSave = async () => {
        setIsSubmitting(true);
        try {
            const finalPseudos = [...localPseudos];

            const trimmed = newPseudo.trim();
            if (trimmed) {
                const validation = validatePseudo(trimmed);
                if (validation.valid && !localPseudos.some(p => p.pseudo.toLowerCase() === trimmed.toLowerCase()) && localPseudos.length < maxPseudos) {
                    let lvl = parseInt(newLevel, 10);
                    if (isNaN(lvl) || lvl < 0 || lvl > 200) lvl = 200;
                    finalPseudos.push({ id: crypto.randomUUID(), pseudo: trimmed, classe: newClass, level: lvl });
                    setLocalPseudos(finalPseudos);
                    setNewPseudo("");
                } else if (!validation.valid) {
                    toast.error(validation.error);
                    setIsSubmitting(false);
                    return;
                }
            }

            if (onSave) {
                await onSave(finalPseudos);
            }
            setIsEditing(false);
            toast.success("Mules mises à jour");
        } catch (error) {
            console.error("Save alt pseudos error:", error);
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCancel = () => {
        // Renormalize from props
        const normalized = altPseudos.map(p => {
            if (typeof p === "string") return { id: crypto.randomUUID(), pseudo: p, classe: "cra", level: 200 };
            return p;
        });
        setLocalPseudos(normalized);
        setIsEditing(false);
        setNewPseudo("");
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === "Enter") {
            e.preventDefault();
            handleAddPseudo();
        }
    };

    return (
        <Card className="bg-zinc-900/40 backdrop-blur-md border-white/10 relative overflow-hidden group h-full flex flex-col">
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 rounded-full blur-3xl pointer-events-none -mr-8 -mt-8 opacity-0 group-hover:opacity-100 transition-opacity" />

            <CardHeader className="p-6 pb-4">
                <div className="flex items-center justify-between">
                    <CardTitle className="text-base font-semibold text-zinc-200 flex items-center gap-2">
                        <Users className="w-5 h-5 text-indigo-400" />
                        Mes Mules
                        {!readOnly && (
                            <span className="text-xs text-zinc-500 bg-zinc-950/50 border border-white/5 px-2 py-0.5 rounded shadow-sm">
                                {localPseudos.length}/{maxPseudos}
                            </span>
                        )}
                    </CardTitle>
                    {!readOnly && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => isEditing ? handleCancel() : setIsEditing(true)}
                            className={cn(
                                "h-8 px-3 text-[10px] font-black uppercase tracking-widest transition-all border shadow-lg rounded-xl",
                                isEditing
                                    ? "bg-zinc-800 text-zinc-200 border-white/10 hover:bg-zinc-700"
                                    : "bg-indigo-500/5 text-indigo-400 border-indigo-500/20 hover:bg-indigo-500 hover:text-white"
                            )}
                        >
                            {isEditing ? <X className="w-3 h-3 mr-2" /> : <Edit2 className="w-3 h-3 mr-2" strokeWidth={2.5} />}
                            {isEditing ? "Annuler" : "Gérer les Mules"}
                        </Button>
                    )}
                </div>
            </CardHeader>
            <CardContent className="p-6 pt-2 space-y-6 relative flex-1">
                {/* Bento Grid layout for Mules */}
                {localPseudos.length > 0 ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
                        {localPseudos.map((mule) => {
                            const cls = getClass(mule.classe || "cra") || DOFUS_CLASSES[0];
                            return (
                                <div
                                    key={mule.id}
                                    className="relative flex flex-col justify-between p-4 rounded-2xl bg-zinc-950/40 border border-white/5 hover:border-white/10 transition-all group/item overflow-hidden"
                                >
                                    {/* Background glow matching class color */}
                                    <div
                                        className="absolute -top-10 -right-10 w-32 h-32 rounded-full blur-3xl pointer-events-none opacity-20"
                                        style={{ backgroundColor: cls.color }}
                                    />

                                    <div className="flex items-start justify-between z-10 w-full overflow-hidden gap-2">
                                        <div className="flex items-center gap-3 w-full min-w-0">
                                            <div className="w-11 h-11 rounded-[10px] bg-black/40 border border-[currentColor]/20 flex items-center justify-center overflow-hidden shrink-0 shadow-inner" style={{ color: cls.color }}>
                                                <NextImage
                                                    src={cls.icon}
                                                    alt={cls.name}
                                                    width={32}
                                                    height={32}
                                                    className="object-contain scale-[1.15]"
                                                    unoptimized
                                                />
                                            </div>
                                            <div className="flex flex-col min-w-0 w-full overflow-hidden">
                                                <span className="font-semibold text-zinc-100 truncate w-full" title={mule.pseudo}>
                                                    {mule.pseudo}
                                                </span>
                                                <span className="text-[10px] text-zinc-400 uppercase tracking-wider font-medium flex items-center gap-1 mt-0.5" style={{ color: cls.color }}>
                                                    Nv. {mule.level !== undefined ? mule.level : 200}
                                                </span>
                                            </div>
                                        </div>

                                        <div className="flex flex-col gap-1.5 items-end shrink-0">
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                onClick={() => {
                                                    navigator.clipboard.writeText(`/w ${mule.pseudo} `);
                                                    toast.success("Commande copiée !", { description: `/w ${mule.pseudo}` });
                                                }}
                                                className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 transition-all bg-black/20 rounded-md"
                                                title="Copier /w"
                                            >
                                                <Copy className="w-3.5 h-3.5" />
                                            </Button>

                                            {isEditing && (
                                                <button
                                                    onClick={() => handleRemovePseudo(mule.id!)}
                                                    className="h-7 w-7 flex items-center justify-center text-red-500 hover:text-white hover:bg-red-500/80 rounded-md transition-all bg-red-500/10"
                                                    title="Supprimer"
                                                >
                                                    <Trash2 className="w-3.5 h-3.5" />
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    <div className="text-sm text-zinc-500 italic py-12 border border-dashed border-white/5 rounded-2xl flex flex-col items-center justify-center bg-zinc-950/20 gap-3">
                        <Users className="w-8 h-8 text-zinc-700" />
                        Aucune mule enregistrée
                    </div>
                )}

                {/* Edit Mode Inputs */}
                {isEditing && (
                    <div className="p-4 sm:p-5 bg-zinc-950/60 border border-white/10 rounded-2xl animate-in fade-in duration-200">
                        <h4 className="text-sm font-semibold text-zinc-200 mb-4 flex items-center gap-2">
                            <Plus className="w-4 h-4 text-emerald-400" />
                            Ajouter un personnage
                        </h4>

                        {localPseudos.length < maxPseudos ? (
                            <div className="flex flex-col gap-4">
                                <div className="grid gap-2 w-full">
                                    <label className="text-xs text-zinc-400 font-medium ml-1">Sélectionner une classe</label>
                                    <div className="flex bg-zinc-950/40 p-2 rounded-xl border border-white/5 overflow-x-auto gap-2 custom-scrollbar pb-3 snap-x">
                                        {DOFUS_CLASSES.map((cls) => (
                                            <button
                                                key={cls.id}
                                                type="button"
                                                onClick={() => setNewClass(cls.id)}
                                                className={cn(
                                                    "h-12 w-12 rounded-xl shrink-0 flex items-center justify-center transition-all border snap-center",
                                                    newClass === cls.id
                                                        ? "bg-zinc-800/80 border-white/20 scale-105 z-10"
                                                        : "bg-black/20 border-white/5 opacity-50 hover:opacity-100 hover:bg-zinc-800/50"
                                                )}
                                                style={{
                                                    boxShadow: newClass === cls.id ? `0 0 15px ${cls.color}30, inset 0 0 0 1px ${cls.color}50` : 'none'
                                                }}
                                                title={cls.name}
                                            >
                                                <NextImage
                                                    src={cls.icon}
                                                    alt={cls.name}
                                                    width={28}
                                                    height={28}
                                                    className="object-contain drop-shadow-md"
                                                    unoptimized
                                                />
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                <div className="flex flex-col sm:flex-row gap-4 items-end">

                                    <div className="grid gap-1.5 flex-[2] w-full relative">
                                        <label className="text-xs text-zinc-400 font-medium ml-1">Pseudo</label>
                                        <Input
                                            value={newPseudo}
                                            onChange={handleInputChange}
                                            onKeyDown={handleKeyDown}
                                            placeholder="Ex: Darksasuke"
                                            className="bg-zinc-900/80 border-white/10 h-10 pl-10 focus-visible:ring-emerald-500/50"
                                            maxLength={20}
                                        />
                                        <div className="absolute left-3 top-[34px] text-zinc-500 text-sm font-mono pointer-events-none">
                                            /w
                                        </div>
                                    </div>

                                    <div className="grid gap-1.5 w-full sm:w-24">
                                        <label className="text-xs text-zinc-400 font-medium ml-1">Niveau</label>
                                        <Input
                                            type="number"
                                            min={0}
                                            max={200}
                                            value={newLevel}
                                            onChange={(e) => {
                                                const val = e.target.value;
                                                if (val === "") { setNewLevel(""); return; }
                                                const num = parseInt(val, 10);
                                                if (!isNaN(num)) {
                                                    if (num > 200) setNewLevel("200");
                                                    else if (num < 0) setNewLevel("0");
                                                    else setNewLevel(num.toString());
                                                }
                                            }}
                                            onKeyDown={handleKeyDown}
                                            placeholder="200"
                                            className="bg-zinc-900/80 border-white/10 h-10 focus-visible:ring-emerald-500/50"
                                        />
                                    </div>

                                    <Button
                                        variant="sigil-emerald"
                                        onClick={handleAddPseudo}
                                        disabled={!newPseudo.trim()}
                                        className="h-10 px-6 w-full sm:w-auto"
                                    >
                                        <Plus className="w-4 h-4 mr-2" /> Ajouter
                                    </Button>
                                </div>
                            </div>
                        ) : (
                            <p className="text-xs text-amber-500/90 flex items-center gap-2 bg-amber-500/10 p-3 rounded-lg border border-amber-500/20">
                                <AlertCircle className="w-4 h-4" />
                                Limite de {maxPseudos} personnages atteinte.
                            </p>
                        )}

                        <div className="flex justify-end pt-4 mt-5 border-t border-white/5">
                            <Button
                                onClick={handleSave}
                                disabled={isSubmitting}
                                variant="sigil"
                                className="h-10 px-8 w-full sm:w-auto"
                            >
                                {isSubmitting ? (
                                    <Save className="w-4 h-4 mr-2 animate-spin" />
                                ) : (
                                    <Save className="w-4 h-4 mr-2" />
                                )}
                                {isSubmitting ? "Enregistrement..." : "Enregistrer les Mules"}
                            </Button>
                        </div>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useEffect, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Loader2, Gift, Copy, Check, Bug, ExternalLink } from "lucide-react";
import { getProfileMatchingArchis, type ProfileMatchData } from "@/server/actions/ocre-actions";
import { toast } from "sonner";

interface ArchiMatchingWidgetProps {
    guildId: string;
    profileId: string;
    ownerDisplayName: string;
}

export function ArchiMatchingWidget({
    guildId,
    profileId,
    ownerDisplayName
}: ArchiMatchingWidgetProps) {
    const [matchData, setMatchData] = useState<ProfileMatchData | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [copiedMsg, setCopiedMsg] = useState(false);

    const loadMatches = async () => {
        setLoading(true);
        setError(null);
        const result = await getProfileMatchingArchis({ guildId, targetProfileId: profileId });

        if (result.success) {
            setMatchData(result.data ?? null);
        } else {
            setError(result.error || "Erreur lors du chargement");
        }
        setLoading(false);
    };

    useEffect(() => {
        loadMatches();
    }, [guildId, profileId]);

    const handleCopyMP = () => {
        if (!matchData || matchData.matches.length === 0) return;

        const monsterNames = matchData.matches.slice(0, 3).map(m => m.nom).join(", ");
        const extra = matchData.matches.length > 3 ? ` et ${matchData.matches.length - 3} autres` : "";
        const message = `/w ${ownerDisplayName} Salut ! Tu aurais un de ces archis à échanger ? ${monsterNames}${extra} :)`;

        navigator.clipboard.writeText(message);
        setCopiedMsg(true);
        toast.success("Message copié !");
        setTimeout(() => setCopiedMsg(false), 2000);
    };

    // Don't render anything if no data or viewer doesn't have Metamob linked
    if (!loading && !matchData) {
        return null;
    }

    // Don't render if no matches
    if (!loading && matchData && matchData.matches.length === 0) {
        return null;
    }

    return (
        <Card className="border-primary/30 bg-gradient-to-br from-primary/5 to-transparent">
            <CardHeader className="pb-3">
                <CardTitle className="flex items-center gap-2 text-base">
                    <Gift className="h-5 w-5 text-primary" />
                    Échanges possibles
                </CardTitle>
            </CardHeader>
            <CardContent>
                {loading ? (
                    <div className="flex items-center justify-center py-6">
                        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                    </div>
                ) : error ? (
                    <p className="text-sm text-muted-foreground text-center py-4">{error}</p>
                ) : matchData && matchData.matches.length > 0 ? (
                    <div className="space-y-3">
                        <p className="text-sm text-muted-foreground">
                            <span className="font-medium text-foreground">{ownerDisplayName}</span> a{" "}
                            <span className="text-primary font-semibold">{matchData.matches.length}</span>{" "}
                            archi{matchData.matches.length > 1 ? "s" : ""} que vous recherchez :
                        </p>

                        <ScrollArea className="h-[160px]">
                            <div className="grid grid-cols-2 gap-2 pr-2">
                                {matchData.matches.map((match) => (
                                    <div
                                        key={match.id}
                                        className="flex items-center gap-2 p-2 rounded-lg bg-card/50 border border-border/50"
                                    >
                                        {match.imageUrl && (
                                            <div className="relative w-8 h-8 shrink-0 rounded overflow-hidden bg-black/20">
                                                <Image
                                                    src={match.imageUrl}
                                                    alt={match.nom}
                                                    fill
                                                    className="object-contain"
                                                    sizes="32px"
                                                />
                                            </div>
                                        )}
                                        <div className="flex-1 min-w-0">
                                            <p className="text-xs font-medium truncate">{match.nom}</p>
                                            <p className="text-[10px] text-muted-foreground truncate">
                                                {match.zone}
                                            </p>
                                        </div>
                                        <Badge
                                            variant="outline"
                                            className="shrink-0 text-[10px] px-1.5 bg-amber-500/10 text-amber-500 border-amber-500/30"
                                        >
                                            x{match.ownerQuantite}
                                        </Badge>
                                    </div>
                                ))}
                            </div>
                        </ScrollArea>

                        <div className="flex gap-2 pt-2 border-t border-border/30">
                            <Button
                                variant="outline"
                                size="sm"
                                className="flex-1 gap-2"
                                onClick={handleCopyMP}
                            >
                                {copiedMsg ? (
                                    <Check className="h-4 w-4 text-emerald-500" />
                                ) : (
                                    <Copy className="h-4 w-4" />
                                )}
                                Copier MP
                            </Button>
                            <Button
                                variant="default"
                                size="sm"
                                className="flex-1 gap-2"
                                asChild
                            >
                                <Link href={`/dashboard/${guildId}/archimonstres`}>
                                    <Bug className="h-4 w-4" />
                                    Bourse
                                </Link>
                            </Button>
                        </div>
                    </div>
                ) : null}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState, useCallback, useMemo, useEffect } from "react";
import { cn } from "@/lib/utils";
import { DAYS_OF_WEEK, TIME_SLOTS, type AvailabilityMap, type DayOfWeek, type TimeSlot, type GlobalAvailability } from "@/lib/dofus-assets";
import { useDebouncedCallback } from "use-debounce";
import { Clock, Sunrise, Sun, Moon, ChevronLeft, ChevronRight, CalendarDays, Plane } from "lucide-react";
import { format, addWeeks, startOfWeek, endOfWeek, isWithinInterval, getISOWeek, getYear } from "date-fns";
import { fr } from "date-fns/locale";

interface AvailabilityHeatmapProps {
    availability?: GlobalAvailability | AvailabilityMap; // Accept both for compatibility
    onSave?: (availability: GlobalAvailability) => void;
    readOnly?: boolean;
    vacationStart?: Date | null;
    vacationEnd?: Date | null;
}

const TIME_SLOT_LABELS: Record<TimeSlot, string> = {
    matin: "Matin",
    midi: "Après-midi",
    soir: "Soir",
    nuit: "Nuit"
};

const TIME_SLOT_HOURS: Record<TimeSlot, string> = {
    matin: "6h - 12h",
    midi: "12h - 18h",
    soir: "18h - 00h",
    nuit: "00h - 6h"
};

const TIME_SLOT_ICONS: Record<TimeSlot, React.ReactNode> = {
    matin: <Sunrise className="w-4 h-4" />,
    midi: <Sun className="w-4 h-4" />,
    soir: <Moon className="w-4 h-4" />,
    nuit: <Moon className="w-4 h-4 text-indigo-400" />
};

const TIME_SLOT_COLORS: Record<TimeSlot, { bg: string; border: string; glow: string; text: string }> = {
    matin: {
        bg: "bg-orange-500/20",
        border: "border-orange-500/50",
        glow: "shadow-[0_0_10px_rgba(249,115,22,0.3)]",
        text: "text-orange-400",
    },
    midi: {
        bg: "bg-amber-400/20",
        border: "border-amber-400/50",
        glow: "shadow-[0_0_10px_rgba(251,191,36,0.3)]",
        text: "text-amber-400",
    },
    soir: {
        bg: "bg-violet-500/20",
        border: "border-violet-500/50",
        glow: "shadow-[0_0_10px_rgba(139,92,246,0.3)]",
        text: "text-violet-400",
    },
    nuit: {
        bg: "bg-indigo-500/20",
        border: "border-indigo-500/50",
        glow: "shadow-[0_0_10px_rgba(99,102,241,0.3)]",
        text: "text-indigo-400",
    },
};

const DAY_LABELS: Record<DayOfWeek, string> = {
    lundi: "Lun",
    mardi: "Mar",
    mercredi: "Mer",
    jeudi: "Jeu",
    vendredi: "Ven",
    samedi: "Sam",
    dimanche: "Dim",
};

export function AvailabilityHeatmap({
    availability = {},
    onSave,
    readOnly = false,
    vacationStart,
    vacationEnd
}: AvailabilityHeatmapProps) {
    // -------------------------------------------------------------------------
    // STATE: MIGRATION & DATA
    // -------------------------------------------------------------------------

    // Normalize input data to GlobalAvailability structure
    const initialData: GlobalAvailability = useMemo(() => {
        // Check if it's legacy data (simple map)
        const isLegacy = Object.keys(availability).some(k => DAYS_OF_WEEK.includes(k as any));

        if (isLegacy) {
            return {
                template: availability as AvailabilityMap,
                weeks: {}
            };
        }

        return (availability as GlobalAvailability).template ? (availability as GlobalAvailability) : { template: {}, weeks: {} };
    }, [availability]);

    const [globalData, setGlobalData] = useState<GlobalAvailability>(initialData);

    // Week Navigation State (0 = current week)
    const [weekOffset, setWeekOffset] = useState(0);
    const [hoveredSlot, setHoveredSlot] = useState<{ day: DayOfWeek, slot: TimeSlot } | null>(null);

    // -------------------------------------------------------------------------
    // HELPERS: DATE & KEYS
    // -------------------------------------------------------------------------

    // Get current view's reference date (Monday of the selected week)
    const currentMonday = useMemo(() => {
        const now = new Date();
        const start = startOfWeek(now, { weekStartsOn: 1 }); // Monday
        return addWeeks(start, weekOffset);
    }, [weekOffset]);

    // Generate Key for current week: "YYYY-W#"
    const currentWeekKey = useMemo(() => {
        const year = getYear(currentMonday);
        const week = getISOWeek(currentMonday);
        return `${year}-W${week}`;
    }, [currentMonday]);

    // Get actual dates for headers
    const weekDates = useMemo(() => {
        const dates: Record<DayOfWeek, Date> = {} as any;
        DAYS_OF_WEEK.forEach((day, idx) => {
            const date = new Date(currentMonday);
            date.setDate(currentMonday.getDate() + idx);
            dates[day] = date;
        });
        return dates;
    }, [currentMonday]);

    // -------------------------------------------------------------------------
    // LOGIC: GET & SET SLOTS
    // -------------------------------------------------------------------------

    // Get effective availability for current view
    // Priority: Specific Week > Template > Empty
    const currentWeekData = useMemo(() => {
        return globalData.weeks?.[currentWeekKey] || globalData.template || {};
    }, [globalData, currentWeekKey]);

    const isSlotActive = useCallback((day: DayOfWeek, slot: TimeSlot) => {
        return currentWeekData[day]?.includes(slot) ?? false;
    }, [currentWeekData]);

    const isVacation = useCallback((day: DayOfWeek) => {
        if (!vacationStart || !vacationEnd) return false;
        const date = weekDates[day];
        // Normalize time for comparison
        const d = new Date(date); d.setHours(12, 0, 0, 0);
        const start = new Date(vacationStart); start.setHours(0, 0, 0, 0);
        const end = new Date(vacationEnd); end.setHours(23, 59, 59, 999);
        return d >= start && d <= end;
    }, [weekDates, vacationStart, vacationEnd]);

    const debouncedSave = useDebouncedCallback((data: GlobalAvailability) => {
        onSave?.(data);
    }, 1000);

    const toggleSlot = (day: DayOfWeek, slot: TimeSlot) => {
        if (readOnly) return;
        if (isVacation(day)) return;
        if (isPast(day)) return; // Prevent editing past dates

        setGlobalData(prev => {
            // ... (rest of logic same as before, just ensuring we don't break indentation, but since I'm replacing the whole function start, I need to be careful. Actually, I will just replace the specific lines in the loop and the toggle function, but this tool requires contiguous blocks. I'll split into two edits for safety or replace the whole block if confident.)
            // Wait, I can't replace `toggleSlot` AND the render loop in one contiguous block easily without including a huge chunk.
            // I will replace `toggleSlot` first.
            const existingWeekData = prev.weeks?.[currentWeekKey];
            const baseData = existingWeekData || prev.template || {};

            const currentSlots = baseData[day] || [];
            const newSlots = currentSlots.includes(slot)
                ? currentSlots.filter(s => s !== slot)
                : [...currentSlots, slot];

            const newWeekData = {
                ...baseData,
                [day]: newSlots
            };

            const newData = {
                ...prev,
                weeks: {
                    ...(prev.weeks || {}),
                    [currentWeekKey]: newWeekData
                }
            };

            debouncedSave(newData);
            return newData;
        });
    };

    // -------------------------------------------------------------------------
    // UI RENDER
    // -------------------------------------------------------------------------

    const isToday = (day: DayOfWeek) => {
        const today = new Date();
        const date = weekDates[day];
        return today.getDate() === date.getDate() &&
            today.getMonth() === date.getMonth() &&
            today.getFullYear() === date.getFullYear();
    };

    const isPast = (day: DayOfWeek) => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const date = new Date(weekDates[day]);
        date.setHours(0, 0, 0, 0);
        return date < today;
    };

    return (
        <div className="p-6 bg-black/20 backdrop-blur-md rounded-2xl border border-white/10 h-full flex flex-col relative overflow-hidden">

            {/* Header Controls */}
            <div className="flex flex-col sm:flex-row items-center justify-between mb-6 gap-4">
                <div className="flex items-center gap-2">
                    <Clock className="w-5 h-5 text-zinc-400" />
                    <div>
                        <h3 className="text-sm font-medium text-zinc-300">Disponibilités</h3>
                        <p className="text-xs text-zinc-500">
                            Semaine {getISOWeek(currentMonday)} • Année {getYear(currentMonday)}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-2 bg-zinc-950/50 p-1 rounded-lg border border-white/5">
                    <button
                        onClick={() => setWeekOffset(prev => prev - 1)}
                        className="p-1.5 hover:bg-white/5 rounded-md text-zinc-400 hover:text-white transition-colors"
                    >
                        <ChevronLeft className="w-4 h-4" />
                    </button>
                    <div className="px-2 text-xs font-medium text-zinc-300 min-w-[140px] text-center flex items-center justify-center gap-2">
                        <CalendarDays className="w-3.5 h-3.5 opacity-70" />
                        {weekOffset === 0 ? "Cette semaine" : format(currentMonday, "d MMMM", { locale: fr }) + " - " + format(endOfWeek(currentMonday, { weekStartsOn: 1 }), "d MMMM", { locale: fr })}
                    </div>
                    <button
                        onClick={() => setWeekOffset(prev => prev + 1)}
                        className="p-1.5 hover:bg-white/5 rounded-md text-zinc-400 hover:text-white transition-colors"
                    >
                        <ChevronRight className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Heatmap Grid */}
            <div className="flex-1 overflow-x-auto min-h-[220px] flex items-center justify-center">
                <div className="relative">
                    <table className="w-full border-separate border-spacing-1.5 ">
                        <thead>
                            <tr>
                                <th className="w-24"></th>
                                {DAYS_OF_WEEK.map(day => {
                                    const date = weekDates[day];
                                    const isVacationDay = isVacation(day);

                                    return (
                                        <th key={day} className="text-center w-14 pb-2 relative group">
                                            <div className={cn(
                                                "flex flex-col items-center gap-1 py-1 px-2 rounded-lg transition-colors border",
                                                isToday(day)
                                                    ? "bg-primary/10 border-primary/30"
                                                    : "border-transparent",
                                                isVacationDay && "opacity-50 grayscale"
                                            )}>
                                                <span className={cn(
                                                    "text-xs font-semibold uppercase tracking-wider",
                                                    isToday(day) ? "text-primary" : "text-zinc-500"
                                                )}>
                                                    {DAY_LABELS[day]}
                                                </span>
                                                <span className={cn(
                                                    "text-lg font-bold",
                                                    isToday(day) ? "text-primary" : "text-zinc-600"
                                                )}>
                                                    {date.getDate()}
                                                </span>
                                            </div>

                                            {/* Vacation Indicator Badge */}
                                            {isVacationDay && (
                                                <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-cyan-500/90 text-[9px] text-zinc-950 font-bold px-1.5 py-0.5 rounded-full z-10 flex items-center gap-1 shadow-lg">
                                                    <Plane className="w-2.5 h-2.5" />
                                                </div>
                                            )}
                                        </th>
                                    );
                                })}
                            </tr>
                        </thead>
                        <tbody>
                            {TIME_SLOTS.map(slot => {
                                const colors = TIME_SLOT_COLORS[slot];
                                return (
                                    <tr key={slot}>
                                        <td className="py-1 pr-3">
                                            <div className="flex items-center gap-2">
                                                <span className={cn("shrink-0", colors.text)}>
                                                    {TIME_SLOT_ICONS[slot]}
                                                </span>
                                                <div className="flex flex-col">
                                                    <span className="text-xs font-medium text-zinc-400">
                                                        {TIME_SLOT_LABELS[slot]}
                                                    </span>
                                                    <span className="text-[10px] text-zinc-600">
                                                        {TIME_SLOT_HOURS[slot]}
                                                    </span>
                                                </div>
                                            </div>
                                        </td>
                                        {DAYS_OF_WEEK.map(day => {
                                            const isActive = isSlotActive(day, slot);
                                            const isVacationDay = isVacation(day);
                                            const isPastDay = isPast(day);
                                            const isHovered = hoveredSlot?.day === day && hoveredSlot?.slot === slot;

                                            return (
                                                <td key={`${day}-${slot}`} className="p-0 relative">
                                                    <button
                                                        onClick={() => toggleSlot(day, slot)}
                                                        onMouseEnter={() => !readOnly && setHoveredSlot({ day, slot })}
                                                        onMouseLeave={() => !readOnly && setHoveredSlot(null)}
                                                        disabled={readOnly || isVacationDay || isPastDay}
                                                        className={cn(
                                                            "w-14 h-11 rounded-lg transition-all duration-200 border transform relative overflow-hidden",
                                                            // Normal State (Active Future)
                                                            !isVacationDay && !isPastDay && isActive
                                                                ? cn(colors.bg, colors.border, "shadow-sm")
                                                                : "bg-white/10 border-white/5",

                                                            // Hover States (Active Future)
                                                            !readOnly && !isVacationDay && !isPastDay && isHovered && !isActive && "scale-105 bg-white/20 border-white/20",
                                                            !readOnly && !isVacationDay && !isPastDay && isHovered && isActive && cn("scale-105", colors.bg, colors.border),

                                                            // Past State
                                                            isPastDay && "cursor-not-allowed opacity-30 grayscale brightness-50 border-transparent",

                                                            // Vacation State (High Contrast Fix)
                                                            isVacationDay && !isPastDay && "cursor-not-allowed opacity-70 bg-red-900/10 border-red-500/20 grayscale-0",
                                                            readOnly && "cursor-default"
                                                        )}
                                                    >
                                                        {/* Active Dot */}
                                                        <div className={cn(
                                                            "w-full h-full flex items-center justify-center transition-all",
                                                            isActive && !isVacationDay ? "opacity-100" : "opacity-0"
                                                        )}>
                                                            <div className={cn(
                                                                "w-2.5 h-2.5 rounded-full shadow-sm",
                                                                slot === "matin" && "bg-orange-400",
                                                                slot === "midi" && "bg-amber-400",
                                                                slot === "soir" && "bg-violet-400",
                                                                slot === "nuit" && "bg-indigo-400"
                                                            )} />
                                                        </div>

                                                        {/* Vacation Strikethrough (Brighter Red) */}
                                                        {isVacationDay && (
                                                            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                                                                <div className="w-[140%] h-[2px] bg-red-500/60 rotate-45 transform shadow-[0_0_4px_rgba(239,68,68,0.4)]" />
                                                            </div>
                                                        )}
                                                    </button>
                                                </td>
                                            );
                                        })}
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Minimal Legend */}
            <div className="flex items-center justify-center gap-4 mt-6 pt-4 border-t border-white/5 text-[10px] text-zinc-500">
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-orange-400" /> Matin</div>
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-amber-400" /> Midi</div>
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-violet-400" /> Soir</div>
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-indigo-400" /> Nuit</div>
                <div className="flex items-center gap-1.5 ml-4 text-cyan-500/50"><Plane className="w-3 h-3" /> Absent (Congés)</div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Link2, Trash2, Plus, Pencil, ShieldAlert, RefreshCw, Copy, Megaphone } from "lucide-react";
import NextImage from "next/image";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { updateDofusBookLinks } from "@/server/actions/profile-actions";
import { shareGalleryItemOnDiscord } from "@/server/actions/gallery-actions";
import { DofusbookPreview } from "@/components/dofus/dofusbook-preview";
import { DO_TAGS } from "@/lib/dofus-tags";
import type { BUILD_TAG_TYPE } from "@/lib/dofus-tags";

export type DofusBookLink = {
    id: string;
    url: string;
    name: string;
    tags?: string[];
    classId?: number;
    previewData?: any; // Cached build info
};

const ClassSelector = ({ 
    selectedId, 
    onSelect, 
    classes 
}: { 
    selectedId: number | null, 
    onSelect: (id: number) => void,
    classes: { id: number, name: string }[]
}) => {
    const [hoveredClassId, setHoveredClassId] = useState<number | null>(null);
    const activeClass = classes.find(c => c.id === (hoveredClassId || selectedId));

    return (
        <div className="flex flex-col gap-3">
            <div className="grid grid-cols-5 sm:grid-cols-7 gap-2">
                {classes.map((cls) => {
                    const colors: Record<number, string> = {
                        1: "#8b5cf6", 2: "#f59e0b", 3: "#10b981", 4: "#6366f1", 5: "#3b82f6",
                        6: "#ef4444", 7: "#ec4899", 8: "#f97316", 9: "#84cc16", 10: "#059669",
                        11: "#dc2626", 12: "#4ade80", 13: "#7c3aed", 14: "#1e40af", 15: "#0ea5e9",
                        16: "#2563eb", 17: "#9333ea", 18: "#ea580c", 19: "#06b6d4"
                    };
                    const color = colors[cls.id] || "#10b981";
                    const isSelected = selectedId === cls.id;

                    return (
                        <button
                            key={cls.id}
                            type="button"
                            onClick={() => onSelect(cls.id)}
                            onMouseEnter={() => setHoveredClassId(cls.id)}
                            onMouseLeave={() => setHoveredClassId(null)}
                            className={cn(
                                "relative aspect-square rounded-xl border transition-all duration-300 flex items-center justify-center group overflow-hidden",
                                isSelected 
                                    ? "border-white/40 shadow-xl scale-105" 
                                    : "bg-zinc-900/50 border-white/5 hover:border-white/20 hover:scale-105"
                            )}
                            style={{ 
                                backgroundColor: isSelected ? `${color}22` : undefined,
                                boxShadow: isSelected ? `0 0 20px ${color}33` : undefined
                            }}
                        >
                            {/* Background Glow on Selection */}
                            {isSelected && (
                                <div className="absolute inset-0 opacity-40 blur-xl pointer-events-none" style={{ backgroundColor: color }} />
                            )}

                            <div className={cn(
                                "relative w-7 h-7 sm:w-9 sm:h-9 transition-all duration-500 z-10",
                                isSelected ? "scale-110 drop-shadow-[0_0_8px_rgba(255,255,255,0.4)]" : "grayscale opacity-30 group-hover:grayscale-0 group-hover:opacity-100 group-hover:scale-110"
                            )}>
                                <NextImage
                                    src={`/assets/dofus/classes/${cls.id === 19 ? 20 : cls.id}.png`}
                                    alt={cls.name}
                                    fill
                                    className="object-contain"
                                />
                            </div>
                        </button>
                    );
                })}
            </div>
            
            {/* Dynamic Class Name Preview */}
            <div className="flex items-center justify-center h-6">
                {activeClass ? (
                    <span className="text-xs font-bold px-3 py-1 bg-white/10 rounded-full text-white tracking-wide shadow-inner animate-in fade-in zoom-in duration-200">
                        {activeClass.name}
                    </span>
                ) : (
                    <span className="text-xs font-medium text-zinc-600 italic">
                        Survolez pour voir la nom de la classe
                    </span>
                )}
            </div>
        </div>
    );
};

interface BuildsCardProps {
    links: DofusBookLink[];
    onSave: (links: DofusBookLink[]) => void;
    readOnly?: boolean;
    guildId: string;
    targetUserId?: string;
}

export function BuildsCard({ links = [], onSave, readOnly = false, guildId, targetUserId }: BuildsCardProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [newLinkName, setNewLinkName] = useState("");
    const [newLinkUrl, setNewLinkUrl] = useState("");
    const [newLinkTags, setNewLinkTags] = useState<string[]>([]);
    const [newLinkClassId, setNewLinkClassId] = useState<number | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [editingLink, setEditingLink] = useState<DofusBookLink | null>(null);
    const [selectedTagFilter, setSelectedTagFilter] = useState<string | null>(null);

    const DOFUS_CLASSES = [
        { id: 1, name: "Féca" }, { id: 2, name: "Osamodas" }, { id: 3, name: "Enutrof" },
        { id: 4, name: "Sram" }, { id: 5, name: "Xélor" }, { id: 6, name: "Écaflip" },
        { id: 7, name: "Éniripsa" }, { id: 8, name: "Iop" }, { id: 9, name: "Crâ" },
        { id: 10, name: "Sadida" }, { id: 11, name: "Sacrieur" }, { id: 12, name: "Pandawa" },
        { id: 13, name: "Roublard" }, { id: 14, name: "Zobal" }, { id: 15, name: "Steamer" },
        { id: 16, name: "Éliotrope" }, { id: 17, name: "Huppermage" }, { id: 18, name: "Ouginak" },
        { id: 19, name: "Forgelance" }
    ];

    const handleAddLink = async () => {
        if (!newLinkName.trim() || !newLinkUrl.trim()) {
            toast.error("Veuillez remplir tous les champs");
            return;
        }

        // Strict Validation (supports /private/, etc.)
        const urlPattern = /^https:\/\/(www\.)?(d-bk\.net|dofusbook\.net)\/(fr|en|es|pt|de)\/(?:private\/)?[a-zA-Z0-9-_\/]+$/;
        if (!urlPattern.test(newLinkUrl.trim())) {
            toast.error("Format de lien invalide (d-bk.net ou dofusbook.net requis avec langue)");
            return;
        }

        if (links.length >= 20) {
            toast.error("Limite de 20 builds atteinte");
            return;
        }

        setIsSubmitting(true);


        const newLink: DofusBookLink = {
            id: crypto.randomUUID(),
            name: newLinkName.trim(),
            url: newLinkUrl.trim(),
            tags: newLinkTags,
            classId: newLinkClassId || undefined,
            previewData: null
        };

        const updatedLinks = [...links, newLink];

        try {
            const result = await updateDofusBookLinks({
                guildId,
                links: updatedLinks,
                targetUserId
            });
            if (result.success) {
                onSave(updatedLinks);
                setIsOpen(false);
                setNewLinkName("");
                setNewLinkUrl("");
                setNewLinkTags([]);
                setNewLinkClassId(null);
                toast.success("Build ajouté");
            } else {
                toast.error(result.error || "Erreur lors de l'ajout");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleEditLink = async () => {
        if (!editingLink) return;
        if (!editingLink.name.trim() || !editingLink.url.trim()) {
            toast.error("Veuillez remplir tous les champs");
            return;
        }
        const urlPattern = /^https:\/\/(www\.)?(d-bk\.net|dofusbook\.net)\/(fr|en|es|pt|de)\/(?:private\/)?[a-zA-Z0-9-_\/]+$/;
        if (!urlPattern.test(editingLink.url.trim())) {
            toast.error("Format de lien invalide (d-bk.net ou dofusbook.net requis)");
            return;
        }
        setIsSubmitting(true);

        const updatedLinks = links.map(l =>
            l.id === editingLink.id ? editingLink : l
        );

        setIsSubmitting(true);
        try {
            const result = await updateDofusBookLinks({
                guildId,
                links: updatedLinks,
                targetUserId
            });
            if (result.success) {
                onSave(updatedLinks);
                setEditingLink(null);
                toast.success("Build mis à jour");
            } else {
                toast.error(result.error || "Erreur lors de la mise à jour");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleDeleteLink = async (id: string) => {
        if (readOnly) return;
        const updatedLinks = links.filter(l => l.id !== id);

        // Optimistic update
        onSave(updatedLinks);

        const result = await updateDofusBookLinks({ guildId, links: updatedLinks, targetUserId });
        if (!result.success) {
            toast.error("Erreur lors de la suppression");
            // Revert (not easily done without local state refetch, but acceptable for now)
        } else {
            toast.success("Build supprimé");
        }
    };

    const handleForceBake = async (link: DofusBookLink) => {
        setIsSubmitting(true);
        toast.info(`Synchronisation en cours...`);
        
        // Clear previewData to force re-fetch on next server bake
        const updatedLinks = links.map(l => l.id === link.id ? { ...l, previewData: null } : l);
        
        try {
            const result = await updateDofusBookLinks({ guildId, links: updatedLinks, targetUserId });
            if (result.success) {
                onSave(updatedLinks); 
                // Check if the build actually got baked (previewData will be set by server if successful)
                toast.success("Synchronisation effectuée");
            } else {
                toast.error(result.error || "Échec de la synchronisation");
            }
        } catch {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCopyLink = (url: string) => {
        navigator.clipboard.writeText(url);
        toast.success("Lien copié !");
    };

    if (readOnly && links.length === 0) return null;

    const filteredLinks = selectedTagFilter
        ? links.filter(l => l.tags?.includes(selectedTagFilter))
        : links;

    return (
        <div className="p-6 bg-zinc-900/40 backdrop-blur-md rounded-2xl border border-white/10 transition-all hover:border-white/20 group h-full flex flex-col">
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-2">
                    <Link2 className="w-5 h-5 text-emerald-400" />
                    <h3 className="text-base font-semibold text-zinc-200">Mes Builds</h3>
                    {!readOnly && (
                        <span className="text-xs text-zinc-500 bg-zinc-950/50 px-2 py-0.5 rounded border border-white/5">
                            {links.length}/20
                        </span>
                    )}
                </div>

                {!readOnly && links.length < 20 && (
                    <Dialog open={isOpen} onOpenChange={setIsOpen}>
                        <DialogTrigger asChild>
                            <Button variant="sigil-emerald" size="sm" className="gap-2 h-9 px-4">
                                <Plus className="w-4 h-4" />
                                <span className="hidden sm:inline">Ajouter un Build</span>
                            </Button>
                        </DialogTrigger>
                        <DialogContent className="bg-zinc-950 border-white/10 text-zinc-200 sm:max-w-xl max-h-[90vh] overflow-y-auto">
                            <DialogHeader>
                                <DialogTitle>Ajouter un Build DofusBook</DialogTitle>
                                <DialogDescription className="text-zinc-400">
                                    Copiez le lien de partage de votre stuff (d-bk.net ou dofusbook.net).
                                </DialogDescription>
                            </DialogHeader>

                            <div className="grid gap-4 py-4">
                                <div className="grid gap-2">
                                    <Label htmlFor="name">Nom du build (Max 30)</Label>
                                    <Input
                                        id="name"
                                        placeholder="Ex: Cra Terre 200"
                                        maxLength={30}
                                        value={newLinkName}
                                        onChange={(e) => setNewLinkName(e.target.value)}
                                        className="bg-zinc-900 border-white/10"
                                    />
                                </div>
                                <div className="grid gap-2">
                                    <Label htmlFor="url">Lien DofusBook</Label>
                                    <Input
                                        id="url"
                                        placeholder="https://d-bk.net/fr/d/..."
                                        value={newLinkUrl}
                                        onChange={(e) => setNewLinkUrl(e.target.value)}
                                        className="bg-zinc-900 border-white/10 font-mono text-xs"
                                    />
                                    <p className="text-[10px] text-zinc-500 flex items-center gap-1">
                                        <ShieldAlert className="w-3 h-3" />
                                        Seuls les liens d-bk.net et dofusbook.net sécurisés (https) sont acceptés.
                                    </p>
                                </div>
                                <div className="grid gap-2">
                                    <Label>Tags (Optionnel, max 3)</Label>
                                    <div className="flex flex-wrap gap-2">
                                        {DO_TAGS.map(tag => {
                                            const isSelected = newLinkTags.includes(tag.id);
                                            return (
                                                <button
                                                    key={tag.id}
                                                    type="button"
                                                    onClick={() => {
                                                        if (isSelected) {
                                                            setNewLinkTags(prev => prev.filter((t: string) => t !== tag.id));
                                                        } else if (newLinkTags.length < 3) {
                                                            setNewLinkTags(prev => [...prev, tag.id]);
                                                        }
                                                    }}
                                                    className={cn(
                                                        "px-2.5 py-1 text-[10px] sm:text-xs rounded-full transition-all border font-medium select-none",
                                                        isSelected
                                                            ? tag.className
                                                            : "bg-zinc-900 border-white/5 text-zinc-500 hover:border-white/20 hover:text-zinc-300 opacity-60 hover:opacity-100"
                                                    )}
                                                >
                                                    {tag.text}
                                                </button>
                                            );
                                        })}
                                    </div>
                                </div>
                                <div className="grid gap-2">
                                    <Label>Icône de classe (Recommandé)</Label>
                                    <ClassSelector 
                                        selectedId={newLinkClassId} 
                                        onSelect={setNewLinkClassId} 
                                        classes={DOFUS_CLASSES} 
                                    />
                                    <p className="text-[10px] text-zinc-500">
                                        Sélectionnez la classe pour assurer une belle preview, même si Dofusbook est lent.
                                    </p>
                                </div>
                            </div>

                            <DialogFooter>
                                <Button variant="ghost" onClick={() => setIsOpen(false)}>Annuler</Button>
                                <Button onClick={handleAddLink} disabled={isSubmitting} variant="sigil-emerald" className="h-10 px-6">
                                    {isSubmitting ? "Ajout..." : "Ajouter"}
                                </Button>
                            </DialogFooter>
                        </DialogContent>
                    </Dialog>
                )}
            </div>

            {/* Tag Filter UI Premium */}
            {links.length > 0 && (
                <div className="bg-zinc-950/80 backdrop-blur-2xl border border-white/10 rounded-[1.5rem] px-5 py-4 shadow-2xl flex flex-col xl:flex-row xl:items-center justify-between gap-4 mb-6">
                    {/* Left: Filters */}
                    <div className="flex items-center gap-3 flex-wrap">
                        {/* 1. Primary Elements */}
                        <div className="flex items-center gap-1.5 bg-black/40 p-1 rounded-2xl border border-white/5 flex-wrap">
                            <button
                                onClick={() => setSelectedTagFilter(null)}
                                className={cn(
                                    "h-8 px-4 rounded-xl text-[11px] font-black transition-all shrink-0",
                                    !selectedTagFilter ? "bg-white text-black shadow-md" : "text-zinc-500 hover:text-white hover:bg-white/10"
                                )}
                            >
                                Tous
                            </button>

                            {["eau","feu","terre","air","multi"].map(id => {
                                const tag = DO_TAGS.find(t => t.id === id)!;
                                const hasTag = links.some(l => l.tags?.includes(id));
                                if (!hasTag) return null;

                                return (
                                    <button
                                        key={id}
                                        onClick={() => setSelectedTagFilter(selectedTagFilter === id ? null : id)}
                                        className={cn(
                                            "h-8 px-3 rounded-xl text-[11px] font-bold transition-all shrink-0",
                                            selectedTagFilter === id ? `${tag.className} shadow-lg ring-1 ring-white/20` : "text-zinc-500 hover:text-white hover:bg-white/10"
                                        )}
                                    >
                                        {tag.text}
                                    </button>
                                );
                            })}
                        </div>

                        {/* 2. Advanced / Specialities (only if user has links with these) */}
                        {links.some(l => l.tags?.some(tagId => !["eau","feu","terre","air","multi"].includes(tagId))) && (
                            <>
                                <div className="w-px h-6 bg-white/10 shrink-0 hidden sm:block" />
                                <div className="flex items-center gap-1.5 bg-black/40 p-1 rounded-2xl border border-white/5 flex-wrap">
                                    {DO_TAGS.filter(t => !["eau","feu","terre","air","multi"].includes(t.id)).map(tag => {
                                        const hasTag = links.some(l => l.tags?.includes(tag.id));
                                        if (!hasTag) return null;

                                        return (
                                            <button
                                                key={tag.id}
                                                onClick={() => setSelectedTagFilter(selectedTagFilter === tag.id ? null : tag.id)}
                                                className={cn(
                                                    "h-8 px-3 rounded-xl text-[11px] font-bold transition-all shrink-0",
                                                    selectedTagFilter === tag.id ? `${tag.className} shadow-lg ring-1 ring-white/20` : "text-zinc-500 hover:text-white hover:bg-white/10"
                                                )}
                                            >
                                                {tag.text}
                                            </button>
                                        );
                                    })}
                                </div>
                            </>
                        )}
                    </div>

                    {/* Right: Count */}
                    <div className="flex items-center gap-4 shrink-0 bg-black/40 px-4 py-2 rounded-2xl border border-white/5">
                        <p className="text-[11px] text-zinc-500 flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-emerald-500/50 animate-pulse" />
                            <span className="text-white font-black">{filteredLinks.length}</span>
                            <span> sur {links.length} build{links.length !== 1 ? "s" : ""}</span>
                        </p>
                    </div>
                </div>
            )}

            {/* List or Grid */}
            <div className={cn(
                "grid gap-6 w-full",
                filteredLinks.length > 0 ? "grid-cols-1 md:grid-cols-2 xl:grid-cols-3" : "grid-cols-1"
            )}>
                {filteredLinks.length > 0 ? (
                    filteredLinks.map(link => (
                        <div key={link.id} className="relative group/card h-full flex flex-col">
                            <DofusbookPreview url={link.url} title={link.name} tags={link.tags} classId={link.classId} initialData={(link as any).previewData} />

                            <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover/card:opacity-100 transition-all z-20 pointer-events-none">
                                <div className="flex gap-1 pointer-events-auto">
                                    <button
                                        onClick={() => handleCopyLink(link.url)}
                                        className="p-2 bg-zinc-800/90 hover:bg-emerald-500 text-zinc-400 hover:text-white rounded-xl border border-white/10 shadow-xl transition-all"
                                        title="Copier le lien"
                                    >
                                        <Copy className="w-4 h-4" />
                                    </button>
                                    <button
                                        onClick={async () => {
                                            const res = await shareGalleryItemOnDiscord(guildId, link.id, "STUFF", undefined /*targetUserId || "unknown"*/);
                                            if (res.success) toast.success("Partagé sur Discord !");
                                            else toast.error(res.error || "Erreur lors du partage");
                                        }}
                                        className="p-2 bg-zinc-800/90 hover:bg-indigo-500 text-indigo-400 hover:text-white rounded-xl border border-white/10 shadow-xl transition-all"
                                        title="Partager sur Discord"
                                    >
                                        <Megaphone className="w-4 h-4" />
                                    </button>
                                </div>
                                {!readOnly && (
                                    <>
                                    <button
                                        onClick={() => handleForceBake(link)}
                                        disabled={isSubmitting}
                                        className="p-2 bg-zinc-800/90 hover:bg-emerald-500 text-zinc-400 hover:text-white rounded-xl border border-white/10 shadow-xl transition-all disabled:opacity-50"
                                        title="Récupérer les données (Baking)"
                                    >
                                        <RefreshCw className={cn("w-4 h-4", isSubmitting && "animate-spin")} />
                                    </button>
                                    <button
                                        onClick={() => setEditingLink({ ...link })}
                                        className="p-2 bg-zinc-800/90 hover:bg-indigo-500 text-white/50 hover:text-white rounded-xl border border-white/10 shadow-xl transition-all"
                                        title="Modifier ce build"
                                    >
                                        <Pencil className="w-4 h-4" strokeWidth={2.5} />
                                    </button>
                                    <button
                                        onClick={() => handleDeleteLink(link.id)}
                                        className="p-2 bg-red-500/10 hover:bg-red-500 text-red-500 hover:text-white rounded-xl border border-red-500/20 transition-all shadow-xl"
                                        title="Supprimer ce build"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                    </>
                                )}
                            </div>
                        </div>
                    ))
                ) : (
                    <div className="text-center py-16 bg-zinc-950/40 rounded-[2rem] border-2 border-dashed border-white/5 flex flex-col items-center justify-center gap-6 relative overflow-hidden group/empty">
                        <div className="absolute inset-0 bg-gradient-to-b from-emerald-500/5 to-transparent opacity-0 group-hover/empty:opacity-100 transition-all duration-700" />
                        
                        <div className="relative">
                            <div className="w-20 h-20 rounded-3xl bg-emerald-500/10 flex items-center justify-center border border-emerald-500/20 rotate-3 group-hover/empty:rotate-6 transition-all duration-500 shadow-2xl">
                                <Link2 className="w-10 h-10 text-emerald-400 group-hover/empty:scale-110 transition-all" />
                            </div>
                            <div className="absolute -bottom-2 -right-2 w-8 h-8 rounded-full bg-zinc-900 border border-white/10 flex items-center justify-center animate-bounce shadow-xl">
                                <Plus className="w-4 h-4 text-emerald-400" />
                            </div>
                        </div>

                        <div className="space-y-2 relative px-6">
                            <h4 className="text-white font-black uppercase tracking-widest text-sm">Aucun build Dofusbook</h4>
                            <p className="text-zinc-500 text-xs leading-relaxed max-w-sm mx-auto font-medium">
                                Partagez vos stuffs pour que les autres membres puissent s'en inspirer ou vous aider à les optimiser.
                                <br />
                                <span className="text-zinc-600 italic">C'est ici que vous lorgnez le stuff des autres !</span>
                            </p>
                        </div>

                        {!readOnly && (
                            <Button 
                                variant="sigil-emerald" 
                                size="xl"
                                onClick={() => setIsOpen(true)}
                                className="h-14"
                            >
                                <Plus className="w-5 h-5 mr-3" />
                                Importer mon premier stuff
                            </Button>
                        )}
                    </div>
                )}
            </div>

            {/* Edit Dialog */}
            <Dialog open={!!editingLink} onOpenChange={(open) => !open && setEditingLink(null)}>
                <DialogContent className="bg-zinc-950 border-white/10 text-zinc-200 sm:max-w-xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>Modifier le Build</DialogTitle>
                        <DialogDescription className="text-zinc-400">
                            Modifiez le nom ou le lien de votre build.
                        </DialogDescription>
                    </DialogHeader>
                    {editingLink && (
                        <div className="grid gap-4 py-4">
                            <div className="grid gap-2">
                                <Label htmlFor="edit-name">Nom du build (Max 30)</Label>
                                <Input
                                    id="edit-name"
                                    maxLength={30}
                                    value={editingLink.name}
                                    onChange={(e) => setEditingLink(prev => prev ? { ...prev, name: e.target.value } : null)}
                                    className="bg-zinc-900 border-white/10"
                                />
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="edit-url">Lien DofusBook</Label>
                                <Input
                                    id="edit-url"
                                    value={editingLink.url}
                                    onChange={(e) => setEditingLink(prev => prev ? { ...prev, url: e.target.value } : null)}
                                    className="bg-zinc-900 border-white/10 font-mono text-xs"
                                />
                            </div>
                            <div className="grid gap-2">
                                <Label>Tags (Optionnel, max 3)</Label>
                                <div className="flex flex-wrap gap-2">
                                    {DO_TAGS.map(tag => {
                                        const tagsArray = editingLink.tags || [];
                                        const isSelected = tagsArray.includes(tag.id);
                                        return (
                                            <button
                                                key={tag.id}
                                                type="button"
                                                onClick={() => {
                                                    setEditingLink(prev => {
                                                        if (!prev) return prev;
                                                        const curTags = prev.tags || [];
                                                        if (isSelected) {
                                                            return { ...prev, tags: curTags.filter((t: string) => t !== tag.id) };
                                                        } else if (curTags.length < 3) {
                                                            return { ...prev, tags: [...curTags, tag.id] };
                                                        }
                                                        return prev;
                                                    });
                                                }}
                                                className={cn(
                                                    "px-2.5 py-1 text-[10px] sm:text-xs rounded-full transition-all border font-medium select-none",
                                                    isSelected
                                                        ? tag.className
                                                        : "bg-zinc-900 border-white/5 text-zinc-500 hover:border-white/20 hover:text-zinc-300 opacity-60 hover:opacity-100"
                                                )}
                                            >
                                                {tag.text}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                            <div className="grid gap-2">
                                <Label>Icône de classe (Recommandé)</Label>
                                <ClassSelector 
                                    selectedId={editingLink.classId || null} 
                                    onSelect={(id) => setEditingLink(prev => prev ? { ...prev, classId: id } : null)} 
                                    classes={DOFUS_CLASSES} 
                                />
                                <p className="text-[10px] text-zinc-500">
                                    Sélectionnez la classe pour assurer une belle preview.
                                </p>
                            </div>
                        </div>
                    )}
                    <DialogFooter>
                        <Button variant="ghost" onClick={() => setEditingLink(null)}>Annuler</Button>
                        <Button onClick={handleEditLink} disabled={isSubmitting} variant="sigil" className="h-10 px-6">
                            {isSubmitting ? "Sauvegarde..." : "Enregistrer"}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogClose, DialogDescription } from "@/components/ui/dialog";
import { Pencil, Info, Plus, UserCircle } from "lucide-react";
import { DOFUS_CLASSES, getClass } from "@/lib/dofus-assets";
import { cn, formatDofusPseudo } from "@/lib/utils";
import { ClassIcon } from "@/components/shared/class-icon";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";

interface ClassDisplayProps {
    pseudoDofus?: string | null;
    mainClass?: string | null;
    onSave?: (mainClass: string, pseudoDofus: string) => void;
    readOnly?: boolean;
}

export function ClassDisplay({
    pseudoDofus,
    mainClass,
    onSave,
    readOnly = false,
}: ClassDisplayProps) {
    const searchParams = useSearchParams();
    const [isOpen, setIsOpen] = useState(false);
    const [selectedMain, setSelectedMain] = useState<string>(mainClass || "");
    const [localPseudo, setLocalPseudo] = useState<string>(pseudoDofus || "");

    // Auto-open if redirected with ?edit=identity (Security: check readOnly)
    useEffect(() => {
        if (!readOnly && searchParams.get("edit") === "identity") {
            setIsOpen(true);
            handleOpen();
        }
    }, [searchParams, readOnly]);

    const mainClassData = getClass(mainClass || "");

    const handleSave = () => {
        onSave?.(selectedMain, localPseudo);
        setIsOpen(false);
    };

    const handleOpen = () => {
        setSelectedMain(mainClass || "");
        setLocalPseudo(pseudoDofus || "");
    };

    return (
        <div className="p-4 bg-zinc-900/40 backdrop-blur-md rounded-xl border border-white/10 transition-all hover:border-white/20 group">
            <Dialog open={isOpen} onOpenChange={setIsOpen}>
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-base font-semibold text-zinc-200 flex items-center gap-2">
                        Identité de Combat
                    </h3>
                    {!readOnly && (
                        <DialogTrigger asChild>
                            <Button 
                                variant="ghost" 
                                size="icon" 
                                className="h-8 w-8 text-zinc-400 hover:text-amber-400 hover:bg-amber-500/10 border border-transparent hover:border-amber-500/20 transition-all duration-300"
                                onClick={handleOpen}
                            >
                                <Pencil className="w-4 h-4" strokeWidth={2.5} />
                            </Button>
                        </DialogTrigger>
                    )}
                </div>

                {/* Main Class Display - Premium Card COMPACT */}
                {mainClassData ? (
                    <div className="relative overflow-hidden rounded-lg border border-white/5 bg-gradient-to-br from-zinc-900 to-black p-4 mb-3 group-hover:border-white/10 transition-colors">
                        {/* Background Glow - Reduced blur/size */}
                        <div className="absolute -top-10 -right-10 w-24 h-24 rounded-full blur-[50px] opacity-15 pointer-events-none"
                            style={{ backgroundColor: mainClassData.color }}
                        />

                        <div className="relative flex items-center gap-4">
                            <div className="relative flex items-center justify-center w-14 h-14 rounded-xl bg-zinc-950 border border-white/10 shadow-lg shrink-0">
                                <ClassIcon classId={mainClassData.id} size={36} className="drop-shadow-[0_0_10px_rgba(0,0,0,0.5)]" />
                                <div className="absolute inset-0 rounded-xl ring-1 ring-inset ring-white/5" />
                            </div>

                            <div className="flex-1 space-y-1.5">
                                <div className="flex items-baseline gap-2">
                                    <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest shrink-0">Pseudo en jeu</span>
                                    {pseudoDofus ? (
                                        <span className="text-lg font-black text-amber-500 italic tracking-tight drop-shadow-[0_0_8px_rgba(245,158,11,0.3)]">
                                            {pseudoDofus}
                                        </span>
                                    ) : (
                                        <span className="text-xs font-black text-amber-500/80 animate-pulse uppercase tracking-widest">
                                            Non renseigné
                                        </span>
                                    )}
                                </div>

                                <div className="flex items-baseline gap-2">
                                    <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest shrink-0">Classe principale</span>
                                    <span className="text-base font-black text-white tracking-wide" style={{ textShadow: `0 0 15px ${mainClassData.color}50` }}>
                                        {mainClassData.name}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="flex flex-col gap-4">
                        {!readOnly ? (
                            <DialogTrigger asChild>
                                <button
                                    onClick={handleOpen}
                                    className="w-full p-6 text-center border-2 border-dashed border-zinc-800 hover:border-amber-500/50 hover:bg-amber-500/5 rounded-xl mb-4 transition-all group/cta relative overflow-hidden"
                                >
                                    <div className="absolute inset-0 bg-gradient-to-br from-amber-500/0 via-amber-500/0 to-amber-500/5 opacity-0 group-hover/cta:opacity-100 transition-opacity" />
                                    <div className="relative z-10 flex flex-col items-center gap-2">
                                        <div className="w-10 h-10 rounded-full bg-zinc-900 border border-white/5 flex items-center justify-center group-hover/cta:scale-110 transition-transform">
                                            <Plus className="w-5 h-5 text-amber-500" />
                                        </div>
                                        <p className="text-sm font-black text-zinc-300 uppercase tracking-widest">Configurer mon Identité</p>
                                        <p className="text-xs text-zinc-500 font-bold uppercase tracking-tighter">Pseudo Dofus & Classe requis</p>
                                    </div>
                                </button>
                            </DialogTrigger>
                        ) : (
                            <div className="w-full p-6 text-center border-2 border-zinc-800/50 rounded-xl mb-4 bg-zinc-900/10">
                                <p className="text-sm font-black text-zinc-600 uppercase tracking-widest italic">Profil non configuré</p>
                            </div>
                        )}
                    </div>
                )}

                <DialogContent className="max-w-4xl w-[95vw] h-[90vh] flex flex-col p-0 gap-0 bg-zinc-950 border-zinc-800 rounded-3xl overflow-hidden shadow-2xl">
                    <DialogHeader className="p-8 pb-4 border-b border-white/5 shrink-0">
                        <DialogTitle className="text-2xl font-black">Modifier votre profil</DialogTitle>
                        <DialogDescription className="text-base text-zinc-400">Définissez votre identité en jeu.</DialogDescription>
                    </DialogHeader>

                    <div className="px-8 pt-6 pb-2 shrink-0">
                        <div className="space-y-3">
                            <label className="text-sm font-bold text-zinc-300 uppercase tracking-widest flex items-center gap-2 pl-1">
                                <UserCircle className="w-5 h-5" />
                                Pseudo Dofus Exact
                            </label>
                            <div className="relative">
                                <Input
                                    value={localPseudo}
                                    onChange={(e) => {
                                        setLocalPseudo(formatDofusPseudo(e.target.value));
                                    }}
                                    placeholder="Votre pseudo en jeu..."
                                    className="bg-zinc-900/50 border-white/10 h-14 focus:ring-primary/20 pr-16 text-lg font-semibold"
                                    maxLength={50}
                                />
                                <div className="absolute right-4 top-1/2 -translate-y-1/2 text-sm font-mono text-zinc-500">
                                    {localPseudo.length}/50
                                </div>
                            </div>
                            <p className="text-sm text-zinc-500 pl-1">
                                Ce pseudo doit être <strong className="text-zinc-300">unique</strong> dans la guilde. Caractères autorisés : lettres, espaces et tirets (-).
                            </p>
                        </div>
                    </div>

                    <div className="flex-1 min-h-0 overflow-hidden px-8 flex flex-col">
                        <h4 className="text-xs font-bold text-zinc-400 uppercase tracking-widest mt-6 mb-2 pl-1">Classe Principale</h4>
                        <div className="flex-1 overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-zinc-700 scrollbar-track-transparent">
                            <div className="grid grid-cols-4 sm:grid-cols-5 gap-3 py-4 pb-24">
                                {DOFUS_CLASSES.map(c => {
                                    const isSelected = selectedMain === c.id;
                                    return (
                                        <button
                                            key={c.id}
                                            onClick={() => setSelectedMain(c.id)}
                                            className={cn(
                                                "group relative flex flex-col items-center justify-center p-2 rounded-xl border-2 transition-all duration-300 aspect-square overflow-hidden",
                                                isSelected
                                                    ? "border-white/40 shadow-[0_0_20px_-5px_rgba(255,255,255,0.2)]"
                                                    : "border-zinc-800 bg-zinc-900/30 hover:border-zinc-700 hover:bg-zinc-900/60"
                                            )}
                                            style={isSelected ? {
                                                borderColor: c.color,
                                                backgroundColor: `${c.color}25`,
                                                boxShadow: `0 0 20px -5px ${c.color}60`
                                            } : undefined}
                                        >
                                            <div className={cn("mb-2 transform transition-transform group-hover:scale-110 duration-300", isSelected ? "scale-110" : "")}>
                                                <ClassIcon classId={c.id} size={36} />
                                            </div>
                                            <span className={cn("w-full px-1 text-[10px] sm:text-xs font-black uppercase tracking-tight sm:tracking-wider transition-colors truncate text-center", isSelected ? "text-white" : "text-zinc-500")}
                                                style={isSelected ? { color: 'white', textShadow: `0 0 10px ${c.color}` } : undefined}
                                            >
                                                {c.name}
                                            </span>

                                            {isSelected && (
                                                <>
                                                    <div className="absolute top-1.5 right-1.5 w-2.5 h-2.5 rounded-full bg-white flex items-center justify-center shadow-[0_0_10px_rgba(255,255,255,0.5)]"
                                                        style={{ backgroundColor: c.color }}
                                                    >
                                                        <div className="w-1 h-1 rounded-full bg-white" />
                                                    </div>
                                                    <div className="absolute inset-0 rounded-xl ring-2 ring-inset ring-white/20" />
                                                </>
                                            )}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    </div>

                    <div className="p-6 border-t border-white/5 bg-zinc-900/40 flex justify-end gap-3 shrink-0">
                        <DialogClose asChild>
                            <Button variant="ghost" className="text-zinc-400 hover:text-white">
                                Annuler
                            </Button>
                        </DialogClose>
                        <Button 
                            onClick={handleSave} 
                            variant="sigil"
                            size="xl"
                        >
                            Confirmer les changements
                        </Button>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Crown,
    Settings,
    Users,
    MoreHorizontal,
    ArrowRight,
    ShieldAlert,
    ExternalLink
} from "lucide-react";
import { Button } from "@/components/ui/button";

interface DiscordOwnershipModalProps {
    isOpen: boolean;
    onClose: () => void;
    guildName: string;
}

export function DiscordOwnershipModal({ isOpen, onClose, guildName }: DiscordOwnershipModalProps) {
    const steps = [
        {
            icon: <Settings className="w-5 h-5 text-zinc-400" />,
            title: "Paramètres du serveur",
            desc: "Cliquez sur le nom de votre serveur sur Discord, puis sur l'icône de rouage."
        },
        {
            icon: <Users className="w-5 h-5 text-zinc-400" />,
            title: "Onglet Membres",
            desc: "Faites défiler tout en bas de la colonne de gauche jusqu'à 'Membres'."
        },
        {
            icon: <MoreHorizontal className="w-5 h-5 text-zinc-400" />,
            title: "Options du membre",
            desc: "Choisissez votre successeur, passez la souris sur son nom et cliquez sur les trois petits points."
        },
        {
            icon: <Crown className="w-5 h-5 text-amber-400" />,
