                                        </p>
                                    </div>
                                    {idx < steps.length - 1 && (
                                        <div className="absolute -bottom-2 left-7 w-px h-2 bg-white/5" />
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Footer */}
                    <div className="pt-2 flex flex-col gap-3">
                        <Button
                            onClick={onClose}
                            className="h-12 w-full bg-white text-black font-black uppercase tracking-tight hover:bg-zinc-200 transition-all rounded-xl active:scale-95"
                        >
                            J'ai compris
                        </Button>
                        <a
                            href="https://support.discord.com/hc/fr/articles/216273938-Comment-transf%C3%A9rer-la-propri%C3%A9t%C3%A9-d-un-serveur"
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center justify-center gap-2 py-2 text-[10px] font-bold text-zinc-500 hover:text-white transition-colors uppercase tracking-widest"
                        >
                            Voir l'aide officielle Discord
                            <ExternalLink className="w-3 h-3" />
                        </a>
                    </div>
                </div>

                {/* Bottom decorative bar */}
                <div className="h-1.5 bg-gradient-to-r from-red-500 via-amber-500 to-red-500 opacity-50" />
            </DialogContent>
        </Dialog>
    );
}

'use client'

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { getMemberDreamRuns } from "@/server/actions/songes/dream-run-actions";
import { Loader2, History, Trophy, Skull, Ban } from "lucide-react";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import Image from "next/image";

export function DreamRunHistory({ guildId, userId }: { guildId: string, userId?: string }) {
    const [runs, setRuns] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        async function fetchHistory() {
            const res = await getMemberDreamRuns(guildId, userId);
            if (res.success && res.runs) {
                setRuns(res.runs);
            }
            setIsLoading(false);
        }
        fetchHistory();
    }, [guildId, userId]);

    if (isLoading) {
        return (
            <div className="flex items-center justify-center p-8">
                <Loader2 className="w-6 h-6 animate-spin text-zinc-500" />
            </div>
        );
    }

    if (runs.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-8 text-center space-y-3 bg-zinc-900/50 rounded-xl border border-dashed border-zinc-800">
                <History className="w-8 h-8 text-zinc-700" />
                <p className="text-sm text-zinc-500 font-medium">Aucun historique de Songes pour le moment.</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {runs.map((run) => {
                const difficultyColor = run.difficulty.startsWith('CAUCHEMAR') ? "text-red-400" :
                    run.difficulty.startsWith('PARADOXE') ? "text-amber-400" :
                        "text-cyan-400";

                return (
                    <Card key={run.id} className="bg-zinc-900/40 border-zinc-800 hover:border-zinc-700 transition-all group overflow-hidden">
                        <CardContent className="p-4 flex flex-col sm:flex-row items-center justify-between gap-4">
                            <div className="flex items-center gap-4 w-full">
                                <div className={cn(
                                    "w-10 h-10 rounded-lg flex items-center justify-center shrink-0 border shadow-inner",
                                    run.status === 'COMPLETED' ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-400" :
                                        run.status === 'FAILED' ? "bg-red-500/10 border-red-500/30 text-red-400" :
                                            "bg-zinc-500/10 border-zinc-500/30 text-zinc-400"
                                )}>
                                    {run.status === 'COMPLETED' ? <Trophy className="w-5 h-5" /> :
                                        run.status === 'FAILED' ? <Skull className="w-5 h-5" /> :
                                            <Ban className="w-5 h-5" />}
                                </div>

                                <div className="min-w-0 flex-grow">
                                    <div className="flex flex-wrap items-center gap-2">
                                        <h4 className={cn("font-bold truncate", difficultyColor)}>
                                            {run.difficulty.replace('_', ' ')}
                                        </h4>
                                        <Badge variant="outline" className="text-[10px] uppercase font-black tracking-tight bg-zinc-900/50">
                                            {run._count.floors} ÉTAGES
                                        </Badge>
                                        <Badge variant="secondary" className={cn(
                                            "text-[9px] h-4 px-1.5 font-bold",
                                            run.status === 'COMPLETED' ? "bg-emerald-500/20 text-emerald-300" :
                                                run.status === 'FAILED' ? "bg-red-500/20 text-red-300" :
                                                    "bg-zinc-800 text-zinc-400"
                                        )}>
                                            {run.status === 'COMPLETED' ? 'SUCCÈS' : run.status === 'FAILED' ? 'ÉCHEC' : 'ABANDON'}
                                        </Badge>
                                    </div>
                                    <div className="text-[11px] font-medium text-zinc-500 mt-0.5">
                                        {run.completedAt ? format(new Date(run.completedAt), "d MMM yyyy 'à' HH:mm", { locale: fr }) : 'Date inconnue'}
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-6 w-full sm:w-auto justify-between sm:justify-end">
                                <div className="flex -space-x-2 overflow-hidden">
                                    {run.members.map((member: any) => {
                                        const profile = member.user?.profiles?.[0];
                                        const pseudo = profile?.pseudoDofus || member.user?.name || "?";
                                        const classe = profile?.classe;

                                        return (
                                            <div
                                                key={member.id}
                                                className="relative inline-block h-8 w-8 rounded-full ring-2 ring-zinc-900 bg-zinc-800 flex items-center justify-center overflow-hidden hover:z-10 transition-all border border-white/5"
                                                title={`${pseudo} (${classe || "Inconnue"})`}
                                            >
                                                {member.user?.image ? (
                                                    <Image src={member.user.image} alt={pseudo} fill className="object-cover opacity-60 group-hover:opacity-100 transition-opacity" />
                                                ) : (
                                                    <div className="text-[10px] font-bold text-zinc-600 uppercase">{pseudo.slice(0, 2)}</div>
                                                )}
                                                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent pointer-events-none" />
                                                <div className="absolute bottom-0 inset-x-0 h-0.5 bg-indigo-500 opacity-0 group-hover:opacity-100" />
                                            </div>
                                        );
                                    })}
                                </div>

                                <div className="text-right shrink-0">
                                    <div className="text-sm font-black text-rose-500 leading-none">
                                        {run.pointsReve || 0} PR
                                    </div>
                                    <div className="text-[10px] font-bold text-zinc-600 uppercase tracking-tighter mt-1">
                                        SCORE FINAL
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                );
            })}
        </div>
    );
}

"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Crown, Palmtree, Award, Medal, Star, ShieldCheck, Sparkles, UserCircle } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import type { ContributorTier } from "@/server/actions/profile-actions";

// Tier configuration
const TIER_CONFIG = {
    LEGENDE: {
        label: "Légende",
        icon: Crown,
        bgColor: "bg-amber-500/15",
        textColor: "text-amber-400",
        borderColor: "border-amber-500/30",
        hoverColor: "hover:bg-amber-500/20",
        iconFill: "fill-amber-500/20",
    },
    CHAMPION: {
        label: "Champion",
        icon: Award,
        bgColor: "bg-slate-400/15",
        textColor: "text-slate-300",
        borderColor: "border-slate-400/30",
        hoverColor: "hover:bg-slate-400/20",
        iconFill: "fill-slate-400/20",
    },
    PILIER: {
        label: "Pilier",
        icon: Medal,
        bgColor: "bg-orange-600/15",
        textColor: "text-orange-400",
        borderColor: "border-orange-600/30",
        hoverColor: "hover:bg-orange-600/20",
        iconFill: "fill-orange-600/20",
    },
} as const;

interface HeroHeaderProps {
    avatarUrl?: string | null;
    displayName: string;
    roleColor?: number;
    contributorTier?: ContributorTier | null;
    rank?: number;
    isOnVacation?: boolean;
    isUpcomingVacation?: boolean;
    vacationStart?: Date | null;
    vacationEnd?: Date | null;
    joinedAt?: string | Date | null;
    isAdmin?: boolean;
    canViewMissions?: boolean;
    canViewLadder?: boolean;
    guildName?: string;
    sigilRoles?: any[];
    discordRoleName?: string;
    discordRoleColor?: number;
    welcomeBadgeName?: string | null;
}

export function HeroHeader({
    avatarUrl,
    displayName,
    roleColor = 0,
    contributorTier = null,
    rank,
    isOnVacation = false,
    isUpcomingVacation = false,
    vacationStart,
    vacationEnd,
    joinedAt,
    isAdmin = false,
    canViewMissions = true,
    canViewLadder = true,
    guildName = "Guilde",
    sigilRoles = [],
    discordRoleName,
    discordRoleColor,
    welcomeBadgeName,
}: HeroHeaderProps) {
    const roleHexColor = roleColor > 0
        ? `#${roleColor.toString(16).padStart(6, "0")}`
        : "#8b5cf6"; // Default purple

    const tierConfig = contributorTier ? TIER_CONFIG[contributorTier] : null;
    const TierIcon = tierConfig?.icon || Star;

    return (
        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-gradient-to-br from-zinc-900/90 to-zinc-950/90 backdrop-blur-xl">
            {/* Background Gradient */}
            <div
                className="absolute inset-0 opacity-30"
                style={{
                    background: `linear-gradient(135deg, ${roleHexColor}15 0%, transparent 50%, ${roleHexColor}10 100%)`
                }}
            />

            {/* Content */}
            <div className="relative z-10 p-6 md:p-8">
                <div className="flex flex-col md:flex-row gap-6 items-center md:items-start">
                    {/* Avatar Section */}
                    <div className="relative shrink-0">
                        {/* Glow Effect */}
                        <div
                            className="absolute inset-0 rounded-full blur-2xl opacity-40"
                            style={{ backgroundColor: roleHexColor }}
                        />

                        <Avatar
                            className="relative w-24 h-24 md:w-28 md:h-28 border-[3px] shadow-2xl"
                            style={{ borderColor: roleHexColor }}
                        >
                            <AvatarImage src={avatarUrl || ""} alt={displayName} className="object-cover" />
                            <AvatarFallback className="text-3xl font-bold bg-zinc-900 text-zinc-300">
                                {displayName?.[0]?.toUpperCase() ?? "?"}
                            </AvatarFallback>
                        </Avatar>

                        {/* Badges on Avatar */}
                        {tierConfig && (
                            <div className={cn("absolute -top-2 -right-2 p-1.5 bg-zinc-900 rounded-full shadow-lg", tierConfig.borderColor, "border")} title={tierConfig.label}>
                                <TierIcon className={cn("w-5 h-5", tierConfig.textColor, tierConfig.iconFill)} />
                            </div>
                        )}
                        {isAdmin && (
                            <div className="absolute -top-2 -left-2 p-1.5 bg-zinc-900 rounded-full border border-purple-500/40 shadow-[0_0_10px_rgba(168,85,247,0.3)] shadow-lg" title="Administration">
                                <ShieldCheck className="w-5 h-5 text-purple-400 fill-purple-500/10" />
                            </div>
                        )}
                        {isOnVacation && (
                            <div className="absolute -bottom-2 -right-2 p-1.5 bg-zinc-900 rounded-full border border-cyan-500/40 shadow-lg" title="En Vacances">
                                <Palmtree className="w-5 h-5 text-cyan-400 fill-cyan-400/20" />
                            </div>
                        )}
                        {welcomeBadgeName && sigilRoles.some(g => g.role?.slug === "probation") && (
                            <div className="absolute -bottom-2 -left-2 p-1.5 bg-zinc-900 rounded-full border border-indigo-500/40 shadow-[0_0_15px_rgba(99,102,241,0.3)] shadow-lg animate-pulse" title={welcomeBadgeName}>
                                <Sparkles className="w-5 h-5 text-indigo-400 fill-indigo-500/10" />
                            </div>
                        )}
                    </div>

                    {/* Info Section */}
                    <div className="flex-1 min-w-0 text-center md:text-left">
                        {/* Name */}
                        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-3 mb-2">
                            <h1
                                className="text-3xl md:text-4xl font-bold tracking-tight truncate leading-tight"
                                style={{ color: roleHexColor }}
                            >
                                {displayName}
                            </h1>
                        </div>

                        {/* Status Badges */}
                        <div className="flex flex-wrap gap-2 justify-center md:justify-start mb-4">
                            {isAdmin && (
                                <Badge className="bg-purple-500/15 text-purple-300 border-purple-500/30 hover:bg-purple-500/20 font-black uppercase tracking-[0.1em] text-[10px] py-1">
                                    <ShieldCheck className="w-3.5 h-3.5 mr-1.5" />
                                    Administration
                                </Badge>
                            )}
                            {tierConfig && (
                                <Badge className={cn(tierConfig.bgColor, tierConfig.textColor, tierConfig.borderColor, tierConfig.hoverColor)}>
                                    <TierIcon className="w-3 h-3 mr-1" />
                                    {tierConfig.label}
                                    {rank && <span className="ml-1 opacity-70">#{rank}</span>}
                                </Badge>
                            )}
                            {isOnVacation && (
                                <Badge className="bg-cyan-500/15 text-cyan-400 border-cyan-500/30 hover:bg-cyan-500/20">
                                    <Palmtree className="w-3 h-3 mr-1" />
                                    En Congés
                                </Badge>
                            )}
                            {isUpcomingVacation && vacationStart && (
                                <Badge variant="outline" className="bg-orange-500/10 text-orange-400 border-orange-500/30 hover:bg-orange-500/20">
                                    <Palmtree className="w-3 h-3 mr-1" />
                                    Absence : {vacationStart.toLocaleDateString("fr-FR", { day: 'numeric', month: 'short' })}
                                </Badge>
                            )}
                            {joinedAt && (
                                <Badge variant="outline" className="bg-white/5 text-zinc-400 border-white/10">
                                    Membre depuis {new Date(joinedAt).toLocaleDateString("fr-FR", { month: 'long', year: 'numeric' })}
                                </Badge>
                            )}

                            {sigilRoles.filter(g => g.role?.slug !== "probation").map((grant: any) => (
                                <Badge
                                    key={grant.id}
                                    className="bg-amber-500/15 text-amber-300 border-amber-500/30 hover:bg-amber-500/20 font-black uppercase tracking-[0.1em] text-[10px] py-1 gap-1.5"
                                >
                                    <Sparkles className="w-3 h-3" />
                                    {grant.label}
                                    {grant.expiresAt && (
                                        <span className="opacity-50 text-[9px] font-medium lowercase italic">
                                            expire {formatDistanceToNow(new Date(grant.expiresAt), { addSuffix: true, locale: fr })}
                                        </span>
                                    )}
                                </Badge>
                            ))}

                            {/* Specific NEW/PROBATION Badge - High Visibility */}
                            {welcomeBadgeName && sigilRoles.filter(g => g.role?.slug === "probation").map((grant: any) => (
                                <Badge
                                    key={grant.id}
                                    className="bg-indigo-500/30 text-indigo-300 border-indigo-500/40 hover:bg-indigo-500/40 font-black uppercase tracking-[0.1em] text-[11px] py-1 gap-2 shadow-[0_0_20px_rgba(99,102,241,0.2)]"
                                >
                                    <Sparkles className="w-3.5 h-3.5 fill-indigo-400/20" />
                                    {welcomeBadgeName}
                                    {grant.expiresAt && (
                                        <span className="opacity-60 text-[9px] font-medium lowercase italic border-l border-indigo-500/30 pl-2">
                                            expire {formatDistanceToNow(new Date(grant.expiresAt), { addSuffix: true, locale: fr })}
                                        </span>
                                    )}
                                </Badge>
                            ))}

                            {discordRoleName && (
                                <Badge
                                    variant="outline"
                                    className="font-bold uppercase tracking-[0.1em] text-[10px] py-1 border-white/10 bg-white/5"
                                    style={{
                                        color: discordRoleColor && discordRoleColor > 0
                                            ? `#${discordRoleColor.toString(16).padStart(6, "0")}`
                                            : "#94a3b8"
                                    }}
                                >
                                    <UserCircle className="w-3.5 h-3.5 mr-1.5" />
                                    {discordRoleName}
                                </Badge>
                            )}
                        </div>

                        {/* Stats Grid Removed - Redundant with Stats Tab */}
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Crown, Palmtree } from "lucide-react";
import { cn } from "@/lib/utils";

interface IdentityCardProps {
    avatarUrl?: string | null;
    displayName: string;
    roleColor?: number;
    isTopContributor?: boolean;
    isOnVacation?: boolean;
    joinedAt?: Date | null;
}

export function IdentityCard({
    avatarUrl,
    displayName,
    roleColor = 0,
    isTopContributor = false,
    isOnVacation = false,
    joinedAt,
}: IdentityCardProps) {
    const borderColor = roleColor > 0
        ? `#${roleColor.toString(16).padStart(6, "0")}`
        : undefined;

    return (
        <div className="relative overflow-hidden p-6 bg-zinc-900/60 rounded-2xl border border-white/5 h-full flex flex-col items-center justify-between group">

            {/* Background Gradient Effect */}
            <div
                className="absolute inset-x-0 -top-24 h-48 bg-gradient-to-b from-primary/10 to-transparent blur-3xl opacity-50 pointer-events-none group-hover:opacity-75 transition-opacity duration-700"
                style={borderColor ? { background: `linear-gradient(to bottom, ${borderColor}20, transparent)` } : undefined}
            />

            <div className="flex flex-col items-center w-full z-10">
                {/* Avatar with Role Border and Badges */}
                <div className="relative mb-4 ring-offset-[3px] ring-offset-zinc-950/0 rounded-full transition-all duration-500 hover:scale-105">
                    {/* Glow behind Avatar */}
                    <div
                        className="absolute inset-0 rounded-full blur-[20px] opacity-20 transition-opacity duration-500 group-hover:opacity-40"
                        style={{ backgroundColor: borderColor || "#ffffff" }}
                    />

                    <Avatar
                        className="w-28 h-28 border-[3px] shadow-2xl relative z-10"
                        style={{ borderColor: borderColor || "rgba(255,255,255,0.1)" }}
                    >
                        <AvatarImage src={avatarUrl || ""} alt={displayName} className="object-cover" />
                        <AvatarFallback className="text-4xl font-bold bg-zinc-900 text-zinc-300">
                            {displayName?.[0]?.toUpperCase() ?? "?"}
                        </AvatarFallback>
                    </Avatar>

                    {/* Top Contributor Crown Badge */}
                    {isTopContributor && (
                        <div className="absolute -top-1 -right-1 z-20 p-1.5 bg-zinc-900 rounded-full border border-amber-500/30 shadow-lg shadow-amber-500/20" title="Top Contributeur">
                            <Crown className="w-5 h-5 text-amber-500 fill-amber-500/20" />
                        </div>
                    )}

                    {/* Vacation Badge */}
                    {isOnVacation && (
                        <div className="absolute -bottom-1 -right-1 z-20 p-1.5 bg-zinc-900 rounded-full border border-cyan-500/30 shadow-lg shadow-cyan-500/20" title="En Vacances">
                            <Palmtree className="w-5 h-5 text-cyan-400 fill-cyan-400/20" />
                        </div>
                    )}
                </div>

                {/* Name */}
                <h2 className="text-2xl font-bold text-white tracking-tight text-center mb-1">
                    {displayName}
                </h2>

                {roleColor > 0 && (
                    <div className="h-1 w-12 rounded-full mb-4 opacity-50" style={{ backgroundColor: borderColor }} />
                )}

                {/* Badges Row - Only if badges exist */}
                {(isTopContributor || isOnVacation) && (
                    <div className="flex flex-wrap gap-2 justify-center mb-2">
                        {isTopContributor && (
                            <Badge variant="secondary" className="bg-amber-500/10 text-amber-500 hover:bg-amber-500/20 border-amber-500/20">
                                Top Contributeur
                            </Badge>
                        )}
                        {isOnVacation && (
                            <Badge variant="secondary" className="bg-cyan-500/10 text-cyan-400 hover:bg-cyan-500/20 border-cyan-500/20">
                                En Congés
                            </Badge>
                        )}
                    </div>
                )}
            </div>

            {/* Footer: Member Since */}
            {joinedAt && (
                <div className="w-full mt-6 pt-6 border-t border-white/5 flex flex-col items-center gap-1 z-10">
                    <p className="text-xs font-medium text-zinc-500 uppercase tracking-widest">
                        Membre depuis
                    </p>
                    <p className="text-zinc-300 font-medium">
                        {new Date(joinedAt).toLocaleDateString("fr-FR", { day: 'numeric', month: 'long', year: 'numeric' })}
                    </p>
                </div>
            )}

            {!joinedAt && (
                <div className="flex-1" /> // Spacer if no date
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Save, Loader2, Info, MessageSquare, Sparkles, Smile } from "lucide-react";
import { toast } from "sonner";
import { saveMemberIntroduction } from "@/server/actions/onboarding-admin-actions";
import { EmojiPicker } from "../editor/emoji-picker";
import { cn } from "@/lib/utils";

interface IntroductionCardProps {
    introduction?: string;
    onSave: (text: string) => void;
    readOnly?: boolean;
    guildId: string;
    displayName: string;
    targetUserId?: string;
}

export function IntroductionCard({
    introduction = "",
    onSave,
    readOnly = false,
    guildId,
    displayName,
    targetUserId
}: IntroductionCardProps) {
    const [text, setText] = useState(introduction);
    const [isEditing, setIsEditing] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const MAX_CHARS = 5000;

    const handleEmojiSelect = (emoji: string) => {
        setText(prev => prev + emoji);
    };

    const handleSave = async () => {
        setIsSaving(true);
        try {
            const res = await saveMemberIntroduction(guildId, text, targetUserId);
            if (res.success) {
                onSave(text);
                setIsEditing(false);
                toast.success("Présentation enregistrée !");
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setIsSaving(false);
        }
    };

    if (!isEditing && !readOnly && !introduction) {
        return (
            <Card className="p-12 bg-zinc-900/40 border-white/5 flex flex-col items-center justify-center text-center space-y-6 relative overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent pointer-events-none" />
                <div className="w-16 h-16 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center group-hover:scale-110 transition-transform duration-500">
                    <Sparkles className="w-8 h-8 text-emerald-400" />
                </div>
                <div className="space-y-2 max-w-sm">
                    <h3 className="text-xl font-black text-white">Parle-nous de toi !</h3>
                    <p className="text-sm text-zinc-500">
                        Ajoute une présentation pour que les autres membres de la guilde apprennent à te connaître.
                    </p>
                </div>
                <Button
                    onClick={() => setIsEditing(true)}
                    variant="sigil-emerald"
                    size="xl"
                >
                    Commencer ma présentation
                </Button>
            </Card>
        );
    }

    return (
        <Card className="bg-zinc-950/20 backdrop-blur-sm border-white/5 space-y-4 relative overflow-hidden group hover:border-white/10 transition-all rounded-3xl">
            <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 via-transparent to-transparent pointer-events-none" />

            <div className="p-5 space-y-4">
                <div className="flex items-center justify-between relative">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
                            <MessageSquare className="w-5 h-5 text-emerald-400" />
                        </div>
                        <div>
                            <h3 className="text-sm font-bold text-white tracking-tight">Ma Présentation</h3>
                            <p className="text-[10px] text-zinc-500 uppercase tracking-widest font-black opacity-60">Bio de {displayName}</p>
                        </div>
                    </div>
                    {!readOnly && !isEditing && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setIsEditing(true)}
                            className="text-[10px] font-black uppercase tracking-widest text-zinc-400 hover:text-white h-7 px-3 rounded-lg"
                        >
                            Modifier
                        </Button>
                    )}
                </div>

                <div className="relative">
                    {isEditing ? (
                        <div className="space-y-3 animate-in fade-in zoom-in-95 duration-200">
                            <div className="relative rounded-2xl border border-white/10 bg-black/40 overflow-hidden focus-within:border-emerald-500/30 transition-all">
                                <div className="flex items-center justify-between px-3 py-2 border-b border-white/5 bg-white/5">
                                    <div className="flex items-center gap-1">
                                        <EmojiPicker onSelect={handleEmojiSelect} />
                                        <span className="text-[10px] font-bold text-zinc-500 uppercase ml-2">Apparence & Bio</span>
                                    </div>
                                    <div className={cn(
                                        "text-[10px] font-black tabular-nums transition-colors px-2 py-1 rounded",
                                        text.length > MAX_CHARS ? "text-rose-500 bg-rose-500/10" : "text-zinc-500 bg-black/20"
                                    )}>
                                        {text.length} / {MAX_CHARS}
                                    </div>
                                </div>
                                <Textarea
                                    value={text}
                                    onChange={(e) => setText(e.target.value)}
                                    placeholder="Partage ton histoire, tes objectifs ou tes passions..."
                                    className="bg-transparent border-none min-h-[160px] max-h-[400px] resize-y p-4 focus-visible:ring-0 text-[13px] leading-relaxed placeholder:text-zinc-700"
                                />
                            </div>

                            <div className="flex items-center justify-between pt-1">
                                <p className="text-[10px] text-zinc-500 italic flex items-center gap-1.5 opacity-60">
                                    <Info className="w-3 h-3 text-emerald-500/50" />
                                    Visible par toute la guilde. Markdown supporté.
                                </p>
                                <div className="flex gap-2">
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={() => {
                                            setText(introduction || "");
                                            setIsEditing(false);
                                        }}
                                        disabled={isSaving}
                                        className="text-[11px] font-bold text-zinc-400 hover:text-white"
                                    >
                                        Annuler
                                    </Button>
                                    <Button
                                        onClick={handleSave}
                                        disabled={isSaving || text.length > MAX_CHARS}
                                        variant="sigil-emerald"
                                        className="h-9 px-5"
                                    >
                                        {isSaving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
                                        Enregistrer
                                    </Button>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="p-6 rounded-2xl bg-black/40 border border-white/5 text-zinc-300 text-sm leading-relaxed whitespace-pre-wrap min-h-[80px] group-hover:bg-black/60 transition-colors">
                            {introduction ? (
                                <div className="text-[13px] text-zinc-300/90 tracking-wide font-medium italic">
                                    "{introduction}"
                                </div>
                            ) : (
                                <span className="text-zinc-600 italic text-xs">Aucune présentation enregistrée.</span>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* Corner Accent */}
            <div className="absolute top-0 right-0 p-3 opacity-[0.03] pointer-events-none group-hover:opacity-[0.06] transition-opacity">
                <Sparkles className="w-20 h-20 text-white" />
            </div>
        </Card>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogClose, DialogDescription } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import Image from "next/image";
import { Pencil, Check, X, Hammer, Info } from "lucide-react";
import { DOFUS_JOBS, getForgemagieStatus, type ForgemagieStatusId, hasAnyForgemagie } from "@/lib/dofus-assets";
import { cn } from "@/lib/utils";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface JobsGridProps {
    jobs?: string[];
    forgemagieStatus?: ForgemagieStatusId;
    fmPriceClassic?: number | null;
    fmPriceTrans?: number | null;
    fmPriceExo?: number | null;
    onSaveJobs?: (jobs: string[]) => void;
    onSaveForgemagieStatus?: (status: ForgemagieStatusId) => void;
    onSaveForgemagiePrices?: (prices: { classic: number | null, trans: number | null, exo: number | null }) => void;
    readOnly?: boolean;
}

export function JobsGrid({
    jobs = [],
    forgemagieStatus = "UNAVAILABLE",
    fmPriceClassic = null,
    fmPriceTrans = null,
    fmPriceExo = null,
    onSaveJobs,
    onSaveForgemagieStatus,
    onSaveForgemagiePrices,
    readOnly = false,
}: JobsGridProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [selectedJobs, setSelectedJobs] = useState<string[]>(jobs);

    const [prices, setPrices] = useState({
        classic: fmPriceClassic,
        trans: fmPriceTrans,
        exo: fmPriceExo
    });

    const userHasFMJobs = hasAnyForgemagie(jobs);

    const toggleJob = (jobId: string) => {
        if (selectedJobs.includes(jobId)) {
            setSelectedJobs(prev => prev.filter(j => j !== jobId));
        } else {
            setSelectedJobs(prev => [...prev, jobId]);
        }
    };

    const handleSave = () => {
        onSaveJobs?.(selectedJobs);
        setIsOpen(false);
    };

    const handleOpen = () => {
        setSelectedJobs(jobs);
    };

    const formatKamas = (value: number | null | undefined) => {
        if (value === null || value === undefined) return "Non défini";
        if (value === 0) return "Gratuit";
        return new Intl.NumberFormat('fr-FR').format(value) + " k";
    };

    const handlePriceChange = (type: 'classic' | 'trans' | 'exo', value: string) => {
        const num = value === "" ? null : parseInt(value);
        if (num !== null && (isNaN(num) || num < 0)) return;
        setPrices(prev => ({ ...prev, [type]: num }));
    };

    const handleSavePrices = () => {
        onSaveForgemagiePrices?.(prices);
    };

    const allJobs = Object.values(DOFUS_JOBS).flat();
    const activeJobsData = allJobs.filter(j => jobs.includes(j.id));

    return (
        <div className="p-6 bg-zinc-900/40 backdrop-blur-md rounded-2xl border border-white/10 transition-all hover:border-white/20 group h-full flex flex-col">
            <div className="flex items-center justify-between mb-6">
                <h3 className="text-base font-semibold text-zinc-200">Maîtrise artisanale</h3>
                {!readOnly && (
                    <Dialog open={isOpen} onOpenChange={setIsOpen}>
                        <DialogTrigger asChild>
                            <Button 
                                variant="ghost" 
                                size="icon" 
                                className="h-8 w-8 text-zinc-400 hover:text-amber-400 hover:bg-amber-500/10 border border-transparent hover:border-amber-500/20 transition-all duration-300" 
                                onClick={handleOpen}
                            >
                                <Pencil className="w-4 h-4" strokeWidth={2.5} />
                            </Button>
                        </DialogTrigger>
                        <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-0 gap-0 bg-zinc-950 border-zinc-800">
                            <DialogHeader className="p-6 pb-2 border-b border-white/5">
                                <DialogTitle className="text-xl">Gérer vos métiers (Niveau 200)</DialogTitle>
                                <DialogDescription>Sélectionnez les métiers que vous maîtrisez au niveau maximum.</DialogDescription>
                            </DialogHeader>
                            <div className="flex-1 overflow-hidden p-6">
                                <Tabs defaultValue="Récolte" className="h-full flex flex-col">
                                    <TabsList className="grid w-full grid-cols-4 mb-6 bg-zinc-900/50">
                                        <TabsTrigger value="Récolte">Récolte</TabsTrigger>
                                        <TabsTrigger value="Artisanat">Artisanat</TabsTrigger>
                                        <TabsTrigger value="Forgemagie">Forgemagie</TabsTrigger>
                                        <TabsTrigger value="Élevage">Élevage</TabsTrigger>
                                    </TabsList>
                                    {Object.entries(DOFUS_JOBS).map(([category, categoryJobs]) => (
                                        <TabsContent key={category} value={category} className="flex-1 overflow-hidden mt-0">
                                            <ScrollArea className="h-[50vh] pr-4">
                                                <div className="grid grid-cols-3 sm:grid-cols-4 gap-4 pb-4">
                                                    {categoryJobs.map(job => {
                                                        const isSelected = selectedJobs.includes(job.id);
                                                        return (
                                                            <button
                                                                key={job.id}
                                                                onClick={() => toggleJob(job.id)}
                                                                className={cn(
                                                                    "group relative flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all duration-300 aspect-square",
                                                                    isSelected
                                                                        ? "border-amber-500/50 bg-amber-500/10 shadow-[0_0_15px_-5px_rgba(245,158,11,0.3)]"
                                                                        : "border-zinc-800 bg-zinc-900/30 hover:border-zinc-700 hover:bg-zinc-900/60"
                                                                )}
                                                            >
                                                                <div className="mb-3 transform transition-transform group-hover:scale-110 duration-300">
                                                                    {job.icon.startsWith("/") ? (
                                                                        <Image
                                                                            src={job.icon}
                                                                            alt={job.name}
                                                                            width={48}
                                                                            height={48}
                                                                            className="w-12 h-12 object-contain drop-shadow-[0_0_10px_rgba(0,0,0,0.5)]"
                                                                        />
                                                                    ) : (
                                                                        <span className="text-3xl">{job.icon}</span>
                                                                    )}
                                                                </div>
                                                                <span className={cn("text-xs font-semibold uppercase tracking-wider text-center", isSelected ? "text-amber-200" : "text-zinc-500")}>
                                                                    {job.name}
                                                                </span>
                                                                {isSelected && (
                                                                    <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.5)]" />
                                                                )}
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </ScrollArea>
                                        </TabsContent>
                                    ))}
                                </Tabs>
                            </div>
                            <div className="p-6 border-t border-white/5 bg-zinc-900/30 flex justify-end gap-3">
                                <DialogClose asChild>
                                    <Button variant="ghost" className="text-zinc-400 hover:text-white">Annuler</Button>
                                </DialogClose>
                                <Button onClick={handleSave} variant="sigil" className="px-8">
                                    Enregistrer
                                </Button>
                            </div>
                        </DialogContent>
                    </Dialog>
                )}
            </div>

            {jobs.length > 0 ? (
                <div className="relative overflow-hidden rounded-xl border border-white/5 bg-gradient-to-br from-zinc-900 to-black p-6 mb-6 group-hover:border-white/10 transition-colors">
                    <div className="absolute -top-20 -right-20 w-40 h-40 rounded-full blur-[80px] bg-amber-500/10 pointer-events-none" />
                    <div className="relative flex items-center gap-5">
                        <div className="relative flex items-center justify-center w-20 h-20 rounded-2xl bg-zinc-950 border border-white/10 shadow-xl shrink-0">
                            <Hammer className="w-10 h-10 text-amber-500 drop-shadow-[0_0_15px_rgba(245,158,11,0.5)]" />
                            <div className="absolute inset-0 rounded-2xl ring-1 ring-inset ring-white/5" />
                        </div>
                        <div>
                            <p className="text-xs font-medium text-zinc-500 uppercase tracking-widest mb-1">Niveau 200</p>
                            <h2 className="text-3xl font-bold text-white tracking-tight">
                                {jobs.length} Métier{jobs.length > 1 ? 's' : ''}
                            </h2>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="p-8 text-center border-2 border-dashed border-zinc-800 rounded-xl mb-6 flex-1 flex items-center justify-center">
                    <p className="text-zinc-500">Aucun métier renseigné</p>
                </div>
            )}

            <div className="flex-1 content-start mb-6">
                {activeJobsData.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 mb-4">
                        {activeJobsData.slice(0, 12).map(job => (
                            <div key={job.id} className="flex items-center gap-1.5 px-2 py-1 rounded bg-zinc-900 border border-white/5 hover:border-white/10 transition-colors">
                                <span className="flex items-center justify-center">
                                    {job.icon.startsWith("/") ? (
                                        <Image src={job.icon} alt={job.name} width={20} height={20} className="w-5 h-5 object-contain" />
                                    ) : (
                                        <span className="text-base">{job.icon}</span>
                                    )}
                                </span>
                                <span className="text-xs font-medium text-zinc-300">{job.name}</span>
                            </div>
                        ))}
                        {activeJobsData.length > 12 && (
                            <Badge variant="outline" className="text-zinc-500 bg-zinc-900/50">+{activeJobsData.length - 12}</Badge>
                        )}
                    </div>
                )}
            </div>

            {userHasFMJobs && (
                <div className="border-t border-white/5 pt-4 mt-auto">
                    <div className="flex items-center gap-2 mb-3">
                        <Hammer className="w-3 h-3 text-amber-500" />
                        <p className="text-xs font-semibold text-zinc-300 uppercase tracking-wider">Tarifs Forgemagie</p>
                    </div>

                    {!readOnly ? (
                        <div className="flex flex-col gap-4">
                            <div className="grid grid-cols-1 gap-3">
                                <div className="flex items-center gap-3">
                                    <Label className="text-xs text-zinc-500 w-24 shrink-0">FM Classique</Label>
                                    <div className="relative flex-1">
                                        <Input
                                            type="number"
                                            placeholder="Gratuit"
                                            className="h-7 text-xs bg-zinc-900/50 border-zinc-800 text-right pr-6"
                                            min={0}
                                            value={prices.classic === null ? "" : prices.classic}
                                            onChange={(e) => handlePriceChange("classic", e.target.value)}
                                        />
                                        <span className="absolute right-2 top-1.5 text-[10px] text-zinc-500 font-bold">K</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <Label className="text-xs text-zinc-500 w-24 shrink-0">Passage Trans</Label>
                                    <div className="relative flex-1">
                                        <Input
                                            type="number"
                                            placeholder="Gratuit"
                                            className="h-7 text-xs bg-zinc-900/50 border-zinc-800 text-right pr-6"
                                            min={0}
                                            value={prices.trans === null ? "" : prices.trans}
                                            onChange={(e) => handlePriceChange("trans", e.target.value)}
                                        />
                                        <span className="absolute right-2 top-1.5 text-[10px] text-zinc-500 font-bold">K</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <Label className="text-xs text-zinc-500 w-24 shrink-0">Tenta Exo</Label>
                                    <div className="relative flex-1">
                                        <Input
                                            type="number"
                                            placeholder="Gratuit"
                                            className="h-7 text-xs bg-zinc-900/50 border-zinc-800 text-right pr-6"
                                            min={0}
                                            value={prices.exo === null ? "" : prices.exo}
                                            onChange={(e) => handlePriceChange("exo", e.target.value)}
                                        />
                                        <span className="absolute right-2 top-1.5 text-[10px] text-zinc-500 font-bold">K</span>
                                    </div>
                                </div>
                            </div>
                            <Button
                                onClick={handleSavePrices}
                                variant="sigil"
                                className="w-full h-8 text-[11px]"
                            >
                                Sauvegarder les tarifs
                            </Button>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-3 pt-2">
                            <div className="flex justify-between items-center p-2 rounded-lg bg-white/5 border border-white/5 hover:border-white/10 transition-colors">
                                <span className="text-zinc-400 text-sm font-medium">Classique</span>
                                <span className="font-mono text-amber-400 font-semibold text-sm">{formatKamas(fmPriceClassic)}</span>
                            </div>
                            <div className="flex justify-between items-center p-2 rounded-lg bg-white/5 border border-white/5 hover:border-white/10 transition-colors">
                                <span className="text-zinc-400 text-sm font-medium">Passage Trans</span>
                                <span className="font-mono text-cyan-400 font-semibold text-sm">{formatKamas(fmPriceTrans)}</span>
                            </div>
                            <div className="flex justify-between items-center p-2 rounded-lg bg-white/5 border border-white/5 hover:border-white/10 transition-colors">
                                <span className="text-zinc-400 text-sm font-medium">Tenta Exo</span>
                                <span className="font-mono text-purple-400 font-semibold text-sm">{formatKamas(fmPriceExo)}</span>
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

"use client";

import { BarChart3, Star, Coins, CheckCircle2, Target, Moon, CalendarDays, HandHeart, Trophy } from "lucide-react";
import StatCard from "@/app/dashboard/[guildId]/stats/_components/stat-card";
import ActivityChart from "@/app/dashboard/[guildId]/stats/_components/activity-chart";
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from "recharts";

interface MemberStatsProps {
    stats: {
        xp: number;
        weeklyXp: number;
        guildatons: number;
        missionsValidated: number;
        weeklyMissions: number;
        rank?: number;
        weeklyActivity: { week: string; submissions: number; validated: number }[];
        missionsByCategory: { category: string; count: number; validated: number }[];
    };
}

const CATEGORY_LABELS: Record<string, string> = {
    DONJON: "Donjon",
    REGULATION: "Régulation",
    ANOMALIE: "Anomalie",
    SONGES: "Songes",
    EXPEDITION: "Expédition",
    EVENT: "Événement",
};

const COLORS = ["#8b5cf6", "#14b8a6", "#f59e0b", "#ef4444", "#06b6d4", "#ec4899"];

export function MemberStats({ stats }: MemberStatsProps) {
    const pieData = stats.missionsByCategory.map(c => ({
        name: CATEGORY_LABELS[c.category] || c.category,
        value: c.count,
    }));

    const validationRate = stats.missionsByCategory.reduce((acc, curr) => acc + curr.count, 0) > 0
        ? Math.round((stats.missionsValidated / stats.missionsByCategory.reduce((acc, curr) => acc + curr.count, 0)) * 100)
        : 0;

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-12">
            {/* KPI Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <StatCard icon={Star} label="XP Total" value={stats.xp} accent="violet" />
                <StatCard icon={Trophy} label="Rang XP" value={stats.rank ? `#${stats.rank}` : "---"} accent="teal" />
                <StatCard icon={Target} label="Missions (Total)" value={stats.missionsValidated} accent="emerald" />
                <StatCard icon={HandHeart} label="Taux réussite" value={`${validationRate}%`} accent="rose" />
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <StatCard icon={Star} label="XP Semaine" value={`+${stats.weeklyXp}`} accent="violet" />
                <StatCard icon={Target} label="Missions Semaine" value={stats.weeklyMissions} accent="emerald" />
                <StatCard icon={Coins} label="Guildatons" value={stats.guildatons} accent="amber" />
                <StatCard icon={CalendarDays} label="Participation" value="---" accent="sky" />
            </div>

            {/* Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Activity Trend */}
                <div className="lg:col-span-2 rounded-[2rem] border border-white/5 bg-black/40 backdrop-blur-xl p-8 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-violet-500/5 rounded-full blur-[100px] pointer-events-none transition-all group-hover:bg-violet-500/10" />
                    <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 mb-8 flex items-center gap-3 italic">
                        <div className="w-1.5 h-1.5 rounded-full bg-violet-500 shadow-[0_0_10px_rgba(139,92,246,0.5)]" />
                        Courbe d'Activité Personnelle
                    </h3>
                    <div className="mt-4">
                        <ActivityChart data={stats.weeklyActivity} />
                    </div>
                </div>

                {/* Categories Breakdown */}
                <div className="rounded-[2rem] border border-white/5 bg-black/40 backdrop-blur-xl p-8 relative overflow-hidden group flex flex-col">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/5 rounded-full blur-[100px] pointer-events-none transition-all group-hover:bg-emerald-500/10" />
                    <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 mb-8 flex items-center gap-3 italic">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]" />
                        Répartition des Missions
                    </h3>
                    
                    {pieData.length === 0 ? (
                        <div className="flex-1 flex items-center justify-center text-zinc-600 text-[10px] uppercase font-bold italic tracking-widest bg-white/[0.02] rounded-3xl border border-dashed border-white/5 mt-4 min-h-[200px]">
                            Aucune mission validée
                        </div>
                    ) : (
                        <>
                            <div className="h-[220px] relative mt-4">
                                <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                                    <PieChart>
                                        <Pie
                                            data={pieData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={65}
                                            outerRadius={90}
                                            paddingAngle={8}
                                            dataKey="value"
                                            stroke="none"
                                            animationDuration={1500}
                                        >
                                            {pieData.map((_, i) => (
                                                <Cell key={i} fill={COLORS[i % COLORS.length]} className="focus:outline-none" />
                                            ))}
                                        </Pie>
                                        <Tooltip 
                                            contentStyle={{ 
                                                backgroundColor: 'rgba(9,9,11,0.95)', 
                                                border: '1px solid rgba(255,255,255,0.1)',
                                                borderRadius: '12px',
                                                fontSize: '11px',
                                                fontWeight: 'bold',
                                                textTransform: 'uppercase'
                                            }}
                                        />
                                    </PieChart>
                                </ResponsiveContainer>
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center">
                                    <span className="text-3xl font-black text-white italic leading-none tracking-tighter">
                                        {pieData.reduce((acc, curr) => acc + curr.value, 0)}
                                    </span>
                                    <span className="text-[9px] text-zinc-600 uppercase font-black tracking-widest mt-1">Total</span>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8">
                                {pieData.map((entry, i) => (
                                    <div key={entry.name} className="flex items-center gap-2">
                                        <div className="w-1.5 h-1.5 rounded-full shadow-[0_0_8px_rgba(0,0,0,0.5)]" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
                                        <span className="text-[10px] font-black text-zinc-400 uppercase italic truncate">{entry.name}</span>
                                        <span className="text-[10px] font-black text-white ml-auto">{entry.value}</span>
                                    </div>
                                ))}
                            </div>
                        </>
                    )}
                </div>
            </div>

            {/* Bottom Note */}
            <div className="flex items-center justify-center gap-3 py-6 border-t border-white/5 opacity-50">
                <BarChart3 className="w-4 h-4 text-zinc-600" />
                <p className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-600 italic">
                    Données certifiées • Synchronisation temps-réel via Robot SigilOS
                </p>
            </div>
        </div>
    );
}

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { CheckCircle2, ExternalLink, Loader2, RefreshCw, Unlink, Link2, Crown, ArrowRightLeft, ShieldCheck, AlertCircle, Settings, MoreVertical } from "lucide-react";
import { linkOcreAccount, unlinkOcreAccount, forceRefreshOcre, getAvailableOcreQuests, switchOcreQuest } from "@/server/actions/ocre-actions";
import { toast } from "sonner";
import Link from "next/link";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import type { UserQuest } from "@/lib/metamob-client";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

interface MetamobLinkProps {
    guildId: string;
    metamobPseudo?: string | null;
    metamobVerified?: boolean;
    metamobLastSync?: Date | null;
    readOnly?: boolean;
    isAdmin?: boolean;
    targetUserId?: string;
}

export function MetamobLink({
    guildId,
    metamobPseudo,
    metamobVerified = false,
    metamobLastSync,
    readOnly = false,
    isAdmin = false,
    targetUserId,
}: MetamobLinkProps) {
    const [isLinked, setIsLinked] = useState(Boolean(metamobPseudo && metamobVerified));
    const [currentPseudo, setCurrentPseudo] = useState(metamobPseudo || "");
    const [inputPseudo, setInputPseudo] = useState("");
    const [inputApiKey, setInputApiKey] = useState("");
    const [isLinking, setIsLinking] = useState(false);
    const [isUnlinking, setIsUnlinking] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);
    const [showLinkDialog, setShowLinkDialog] = useState(false);
    const [showUnlinkDialog, setShowUnlinkDialog] = useState(false);
    const [linkError, setLinkError] = useState<string | null>(null);
    const [forceLink, setForceLink] = useState(false);
    const [linkStep, setLinkStep] = useState(1);

    // Multi-Quest Support
    const [showSwitchDialog, setShowSwitchDialog] = useState(false);
    const [isSwitching, setIsSwitching] = useState(false);
    const [availableQuests, setAvailableQuests] = useState<UserQuest[]>([]);
    const [questsLoading, setQuestsLoading] = useState(false);

    const handleLink = async (force: boolean = false) => {
        if (!inputPseudo.trim()) {
            setLinkError("Veuillez entrer un pseudo");
            return;
        }

        setIsLinking(true);
        setLinkError(null);
        setForceLink(false);

        const result = await linkOcreAccount({
            guildId,
            pseudo: inputPseudo.trim(),
            apiKey: inputApiKey.trim() || undefined,
            force,
            targetUserId,
        });

        if (result.success && result.data) {
            setIsLinked(true);
            setCurrentPseudo(result.data.pseudo);
            setShowLinkDialog(false);
            setInputPseudo("");
            setInputApiKey("");
            setForceLink(false);
            const serverInfo = result.data.serverName ? ` (${result.data.serverName})` : "";
            toast.success(`Compte Metamob "${result.data.pseudo}" lié${serverInfo} !`);
        } else {
            setLinkError(result.error || "Erreur lors de la liaison du compte");
            // Detect if it's an ownership error and user is admin
            if (result.error?.includes("déjà lié") && isAdmin) {
                setForceLink(true);
            }
        }

        setIsLinking(false);
    };

    const handleUnlink = async () => {
        setIsUnlinking(true);

        const result = await unlinkOcreAccount({ guildId, targetUserId });

        if (result.success) {
            setIsLinked(false);
            setCurrentPseudo("");
            setShowUnlinkDialog(false);
            toast.success("Compte Metamob délié");
        } else {
            toast.error(result.error || "Erreur lors de la suppression");
        }

        setIsUnlinking(false);
    };

    const handleRefresh = async () => {
        setIsRefreshing(true);

        const result = await forceRefreshOcre(guildId, targetUserId);

        if (result.success) {
            toast.success("Données Metamob actualisées");
        } else {
            toast.error(result.error || "Erreur lors du rafraîchissement");
        }

        setIsRefreshing(false);
    };

    const handleOpenSwitch = async () => {
        setQuestsLoading(true);
        setShowSwitchDialog(true);
        const result = await getAvailableOcreQuests(guildId, targetUserId);
        if (result.success && result.data) {
            setAvailableQuests(result.data.sort((a, b) => b.quest_template.id - a.quest_template.id)); // Unity first? Or by date?
        } else {
            toast.error("Impossible de charger les quêtes");
            setShowSwitchDialog(false);
        }
        setQuestsLoading(false);
    };

    const handleSwitch = async (questSlug: string) => {
        setIsSwitching(true);
        const result = await switchOcreQuest(guildId, questSlug, targetUserId);
        if (result.success) {
            toast.success("Quête active mise à jour !");
            setShowSwitchDialog(false);
            // Refresh page to show new data? Client side navigation sufficient?
            // forceRefreshOcre was already called inside switchOcreQuest (revalidatePath)
            // But we might need to update UI if it depends on quest details not in this component.
            // This component only shows pseudo.
        } else {
            toast.error(result.error || "Impossible de changer de quête");
        }
        setIsSwitching(false);
    };

    return (
        <Card className="border-white/10 bg-black/20 backdrop-blur-md overflow-hidden relative group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/5 rounded-full blur-3xl pointer-events-none -mr-10 -mt-10" />

            <CardContent className="p-5 flex flex-col sm:flex-row gap-5 items-center justify-between">
                <div className="flex items-center gap-4">
                    <div className="relative">
                        <div className="w-12 h-12 rounded-xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20 shadow-[0_0_15px_-5px_rgba(245,158,11,0.3)] shrink-0">
                            <Crown className="h-6 w-6 text-amber-500" />
                        </div>
                        {isLinked && (
                            <div className="absolute -bottom-1 -right-1 bg-zinc-950 rounded-full border border-zinc-900 p-0.5">
                                <CheckCircle2 className="w-4 h-4 text-emerald-500 fill-emerald-500/20" />
                            </div>
                        )}
                    </div>

                    <div>
                        <h3 className="text-base font-semibold text-zinc-200">Metamob</h3>
                        <div className="flex items-center gap-2 mt-0.5">
                            {isLinked ? (
                                <p className="text-sm text-zinc-400">
                                    Lié à <span className="text-zinc-200 font-medium">{currentPseudo}</span>
                                </p>
                            ) : (
                                <span className="text-xs text-zinc-500 italic">Non relié</span>
                            )}
                        </div>
                    </div>
                </div>

                {isLinked ? (
                    <div className="flex flex-1 flex-wrap gap-4 w-full items-center justify-between sm:justify-end">
                        {metamobLastSync && (
                            <div className="flex items-center gap-2 text-xs text-zinc-500 mr-auto sm:mr-0">
                                <span className="relative flex h-2 w-2">
                                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                                    <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                                </span>
                                <span>
                                    Synchro {formatDistanceToNow(new Date(metamobLastSync), { addSuffix: true, locale: fr })}
                                </span>
                            </div>
                        )}

                        <div className="flex items-center gap-2 w-full sm:w-auto">
                            <Button size="sm" asChild className="h-9 bg-amber-600 hover:bg-amber-700 text-white shadow-lg shadow-amber-900/20 border border-amber-500/20 flex-1 sm:flex-none">
                                <Link href={`/dashboard/${guildId}/quete-ocre`}>
                                    <Crown className="h-3.5 w-3.5 mr-2" />
                                    Avancement Ocre
                                </Link>
                            </Button>

                            <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                    <Button variant="outline" size="icon" className="h-9 w-9 bg-black/20 border-white/10 hover:bg-white/5 hover:border-white/20 text-zinc-400 hover:text-white">
                                        <Settings className="h-4 w-4" />
                                    </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end" className="w-56">
                                    <DropdownMenuLabel className="text-foreground font-bold">Mon compte Metamob</DropdownMenuLabel>
                                    <DropdownMenuSeparator className="bg-white/10" />

                                    <DropdownMenuItem asChild>
                                        <a
                                            href={`https://www.metamob.fr/profile/${encodeURIComponent(currentPseudo)}`}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="cursor-pointer"
                                        >
                                            <ExternalLink className="h-4 w-4 mr-2" />
                                            Voir sur Metamob.fr
                                        </a>
                                    </DropdownMenuItem>

                                    {!readOnly && (
                                        <>
                                            <DropdownMenuSeparator className="bg-white/10" />
                                            <DropdownMenuItem onClick={handleRefresh} disabled={isRefreshing} className="cursor-pointer">
                                                <RefreshCw className={cn("h-4 w-4 mr-2", isRefreshing ? "animate-spin" : "")} />
                                                Forcer la synchro
                                            </DropdownMenuItem>
                                            <DropdownMenuItem onClick={handleOpenSwitch} className="cursor-pointer">
                                                <ArrowRightLeft className="h-4 w-4 mr-2" />
                                                Changer de quête
                                            </DropdownMenuItem>
                                            <DropdownMenuSeparator className="bg-white/10" />
                                            <DropdownMenuItem onClick={() => setShowUnlinkDialog(true)} className="text-red-400 focus:text-red-400 focus:bg-red-950/30 cursor-pointer">
                                                <Unlink className="h-4 w-4 mr-2" />
                                                Délier le compte
                                            </DropdownMenuItem>
                                        </>
                                    )}
                                </DropdownMenuContent>
                            </DropdownMenu>

                            {/* Dialogs kept in DOM but triggered via state/menu */}
                            <Dialog open={showSwitchDialog} onOpenChange={setShowSwitchDialog}>
                                <DialogContent className="max-w-md">
                                    <DialogHeader>
                                        <DialogTitle>Choisir la quête active</DialogTitle>
                                        <DialogDescription>
                                            Sélectionnez la quête Ocre que vous souhaitez suivre sur SigilOS.
                                        </DialogDescription>
                                    </DialogHeader>

                                    <div className="space-y-3 py-2 max-h-[60vh] overflow-y-auto">
                                        {questsLoading ? (
                                            <div className="flex justify-center py-8">
                                                <Loader2 className="h-8 w-8 text-amber-500 animate-spin" />
                                            </div>
                                        ) : availableQuests.length === 0 ? (
                                            <div className="text-center py-6 text-muted-foreground">
                                                Aucune quête Ocre trouvée.
                                            </div>
                                        ) : (
                                            availableQuests.map((quest) => (
                                                <div
                                                    key={quest.slug}
                                                    onClick={() => handleSwitch(quest.slug)}
                                                    className="flex items-center justify-between p-3 rounded-xl border border-white/5 bg-white/5 hover:bg-white/10 hover:border-amber-500/30 cursor-pointer transition-all group"
                                                >
                                                    <div className="flex flex-col gap-1">
                                                        <div className="flex items-center gap-2">
                                                            <span className="font-medium text-zinc-200">{quest.server.name}</span>
                                                            <Badge variant="secondary" className="text-[10px] h-5 bg-black/20">
                                                                {quest.quest_template.id === 1 ? "Unity" : quest.quest_template.id === 2 ? "Rétro" : "Custom"}
                                                            </Badge>
                                                        </div>
                                                        <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                                            <UserCircle className="h-3.5 w-3.5" />
                                                            <span>{quest.character_name}</span>
                                                        </div>
                                                    </div>
                                                    <div className="flex flex-col items-end gap-1">
                                                        <Badge className={cn("bg-amber-500/10 text-amber-500 hover:bg-amber-500/20 border-amber-500/20")}>
                                                            Étape {quest.current_step}
                                                        </Badge>
                                                    </div>
                                                </div>
                                            ))
                                        )}
                                    </div>
                                </DialogContent>
                            </Dialog>

                            <Dialog open={showUnlinkDialog} onOpenChange={setShowUnlinkDialog}>
                                <DialogContent>
                                    <DialogHeader>
                                        <DialogTitle>Délier le compte Metamob ?</DialogTitle>
                                        <DialogDescription>
                                            Vous ne pourrez plus accéder à la Quête Ocre via SigilOS.
                                        </DialogDescription>
                                    </DialogHeader>
                                    <DialogFooter>
                                        <Button variant="ghost" onClick={() => setShowUnlinkDialog(false)}>
                                            Annuler
                                        </Button>
                                        <Button variant="destructive" onClick={handleUnlink} disabled={isUnlinking}>
                                            {isUnlinking && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                                            Délier
                                        </Button>
                                    </DialogFooter>
                                </DialogContent>
                            </Dialog>
                        </div>
                    </div>
                ) : (
                    !readOnly && (
                        <div className="flex flex-col gap-4 w-full sm:w-auto">
                            <Dialog open={showLinkDialog} onOpenChange={(open) => {
                                setShowLinkDialog(open);
                                if (!open) {
                                    setLinkError(null);
                                    setInputPseudo("");
                                    setInputApiKey("");
                                    setForceLink(false);
                                    setLinkStep(1);
                                }
                            }}>
                                <DialogTrigger asChild>
                                    <Button className="bg-amber-600 hover:bg-amber-700 text-white font-medium shadow-lg shadow-amber-900/20 w-full sm:w-auto">
                                        <Link2 className="h-4 w-4 mr-2" />
                                        Connecter Metamob
                                    </Button>
                                </DialogTrigger>
                                <DialogContent className="sm:max-w-2xl bg-zinc-950 border-white/10 shadow-2xl overflow-hidden p-0 gap-0">
                                    <div className="absolute top-0 left-0 w-64 h-64 bg-amber-500/5 rounded-full blur-[100px] pointer-events-none -ml-32 -mt-32" />
                                    
                                    <DialogHeader className="p-8 border-b border-white/5 relative z-10">
                                        <DialogTitle className="text-2xl font-black text-white flex items-center gap-3">
                                            <div className="p-2 rounded-lg bg-amber-500/20 text-amber-500 border border-amber-500/20">
                                                <Link2 className="h-6 w-6" />
                                            </div>
                                            Lier votre compte Metamob
                                        </DialogTitle>
                                        <DialogDescription className="text-base text-zinc-400 mt-2">
                                            {linkStep === 1
                                                ? "Entrez votre pseudo Metamob pour commencer la synchronisation."
                                                : "Votre clé API personnelle (V2) est indispensable pour accéder à vos données privées."}
                                        </DialogDescription>
                                    </DialogHeader>

                                    <div className="p-8 space-y-8 relative z-10">
                                        {/* Step indicator */}
                                        <div className="flex items-center gap-4">
                                            <div className={cn("flex items-center gap-2.5 text-xs font-black uppercase tracking-[0.2em] px-4 py-2 rounded-xl transition-all", linkStep === 1 ? "bg-amber-500/20 text-amber-400 border border-amber-500/30 shadow-[0_0_15px_-5px_rgba(245,158,11,0.5)]" : "bg-emerald-500/20 text-emerald-400 border border-emerald-500/30")}>
                                                {linkStep === 1 ? <span className="w-5 h-5 rounded-full bg-amber-500 text-black flex items-center justify-center font-bold">1</span> : <CheckCircle2 className="w-5 h-5" />}
                                                <span>Pseudo</span>
                                            </div>
                                            <div className="h-0.5 flex-1 bg-gradient-to-r from-amber-500/20 to-zinc-800" />
                                            <div className={cn("flex items-center gap-2.5 text-xs font-black uppercase tracking-[0.2em] px-4 py-2 rounded-xl transition-all", linkStep === 2 ? "bg-amber-500/20 text-amber-400 border border-amber-500/30 shadow-[0_0_15px_-5px_rgba(245,158,11,0.5)]" : "bg-zinc-900 text-zinc-600 border border-white/5")}>
                                                <span className={cn("w-5 h-5 rounded-full flex items-center justify-center font-bold", linkStep === 2 ? "bg-amber-500 text-black" : "bg-zinc-800")}>2</span>
                                                <span>Clé API</span>
                                            </div>
                                        </div>

                                        <div className="space-y-6">
                                            {linkStep === 1 ? (
                                                /* STEP 1: Pseudo */
                                                <div className="space-y-5">
                                                    <div className="space-y-3">
                                                        <label htmlFor="metamob-pseudo" className="text-base font-bold text-zinc-200 block ml-1">
                                                            Pseudo Metamob
                                                        </label>
                                                        <Input
                                                            id="metamob-pseudo"
                                                            placeholder="Ex: MonPseudo"
                                                            value={inputPseudo}
                                                            onChange={(e) => {
                                                                setInputPseudo(e.target.value);
                                                                setLinkError(null);
                                                                setForceLink(false);
                                                            }}
                                                            onKeyDown={(e) => {
                                                                if (e.key === "Enter" && inputPseudo.trim()) {
                                                                    setLinkStep(2);
                                                                }
                                                            }}
                                                            className="h-14 bg-zinc-900/50 border-zinc-800 text-lg font-medium px-4 focus:ring-amber-500/20"
                                                            autoFocus
                                                        />
                                                    </div>
                                                    
                                                    {inputPseudo.trim() && (
                                                        <div className="flex items-center gap-3 p-4 bg-amber-500/5 rounded-2xl border border-amber-500/10 text-sm text-zinc-400">
                                                            <ExternalLink className="w-4 h-4 text-amber-500 shrink-0" />
                                                            <span>Votre profil : <b className="text-zinc-100 font-bold">metamob.fr/profile/{inputPseudo.trim()}</b></span>
                                                        </div>
                                                    )}
                                                    
                                                    <p className="text-xs text-zinc-500 ml-1">
                                                        Pas de compte ? <a href="https://www.metamob.fr/register" target="_blank" className="text-amber-500 font-bold hover:underline">Inscrivez-vous sur Metamob.fr</a>
                                                    </p>
                                                </div>
                                            ) : (
                                                /* STEP 2: API Key (Required) */
                                                <div className="space-y-6">
                                                    <div className="p-4 bg-emerald-500/5 rounded-2xl border border-emerald-500/10 flex items-center gap-4 group">
                                                        <div className="w-10 h-10 rounded-xl bg-emerald-500/20 flex items-center justify-center border border-emerald-500/20 shrink-0">
                                                            <CheckCircle2 className="w-6 h-6 text-emerald-400" />
                                                        </div>
                                                        <div className="flex flex-col">
                                                            <span className="text-[10px] font-black uppercase tracking-widest text-emerald-500/60 leading-none mb-1">Cible</span>
                                                            <span className="text-lg font-black text-white">{inputPseudo}</span>
                                                        </div>
                                                        <Button variant="ghost" size="sm" className="h-10 ml-auto px-4 bg-zinc-900/50 border border-white/5 text-zinc-400 hover:text-white" onClick={() => setLinkStep(1)}>
                                                            Modifier
                                                        </Button>
                                                    </div>

                                                    <div className="space-y-3">
                                                        <div className="flex items-center justify-between ml-1">
                                                            <label htmlFor="metamob-key" className="text-base font-bold text-zinc-200 flex items-center gap-2">
                                                                Clé API
                                                                <Badge variant="outline" className="text-[10px] border-red-500/30 text-red-400 bg-red-500/10 uppercase tracking-tighter h-5">Requis</Badge>
                                                            </label>
                                                            <a
                                                                href="https://www.metamob.fr/settings#api"
                                                                target="_blank"
                                                                className="text-xs text-amber-500 font-bold hover:underline flex items-center gap-1.5"
                                                            >
                                                                Récupérer ma clé <ExternalLink className="h-3.5 w-3.5" />
                                                            </a>
                                                        </div>
                                                        <Input
                                                            id="metamob-key"
                                                            type="password"
                                                            placeholder="Ex: 8a7f...d2c1 (64 caractères)"
                                                            value={inputApiKey}
                                                            onChange={(e) => setInputApiKey(e.target.value)}
                                                            className="h-14 bg-zinc-900/50 border-zinc-800 text-lg font-mono focus:ring-amber-500/20"
                                                        />
                                                    </div>

                                                    <div className="p-5 bg-zinc-900/80 rounded-2xl border border-white/5 space-y-3 shadow-inner">
                                                        <p className="text-sm font-black text-amber-500 flex items-center gap-2">
                                                            <Settings className="w-4 h-4" />
                                                            GUIDE D’INSTALLATION
                                                        </p>
                                                        <ul className="space-y-2.5">
                                                            <li className="flex items-start gap-3 text-xs text-zinc-400">
                                                                <span className="w-5 h-5 rounded-full bg-zinc-800 text-white flex items-center justify-center shrink-0 font-bold text-[10px]">1</span>
                                                                <span>Allez dans <a href="https://www.metamob.fr/settings#api" target="_blank" className="text-amber-500 font-bold hover:underline">Paramètres → API</a></span>
                                                            </li>
                                                            <li className="flex items-start gap-3 text-xs text-zinc-400">
                                                                <span className="w-5 h-5 rounded-full bg-zinc-800 text-white flex items-center justify-center shrink-0 font-bold text-[10px]">2</span>
                                                                <span>Copiez la <b>Clé API V2</b> (elle fait 64 caractères)</span>
                                                            </li>
                                                            <li className="flex items-start gap-3 text-xs text-zinc-400">
                                                                <span className="w-5 h-5 rounded-full bg-zinc-800 text-white flex items-center justify-center shrink-0 font-bold text-[10px]">3</span>
                                                                <span>Collez-la dans le champ ci-dessus pour finaliser</span>
                                                            </li>
                                                        </ul>
                                                    </div>
                                                </div>
                                            )}

                                            {linkError && (
                                                <div className="animate-in fade-in slide-in-from-top-4 duration-500">
                                                    <div className="flex items-start gap-4 p-5 rounded-2xl bg-red-500/10 text-red-400 border border-red-500/20 shadow-lg shadow-red-950/20">
                                                        <AlertCircle className="h-6 w-6 shrink-0 mt-0.5" />
                                                        <div className="space-y-4 flex-1">
                                                            <p className="text-base font-bold leading-tight">{linkError}</p>
                                                        </div>
                                                    </div>

                                                    {linkError.toLowerCase().includes("déjà lié") && !isAdmin && (
                                                        <div className="mt-4 p-5 bg-blue-500/10 border border-blue-500/20 rounded-2xl">
                                                            <p className="font-black text-sm text-blue-400 mb-2 flex items-center gap-2">
                                                                <ShieldCheck className="h-4 w-4" />
                                                                PROTECTION DE COMPTE
                                                            </p>
                                                            <p className="text-sm text-zinc-400 leading-relaxed">
                                                                Ce compte Metamob est déjà associé à un autre membre. 
                                                                Si vous avez changé de compte Discord, contactez un <b>Administrateur</b>.
                                                            </p>
                                                        </div>
                                                    )}

                                                    {forceLink && isAdmin && (
                                                        <div className="mt-4 p-5 bg-amber-500/10 border border-amber-500/20 rounded-2xl shadow-xl">
                                                            <h4 className="text-sm font-black text-amber-500 mb-2 flex items-center gap-2">
                                                                <ShieldCheck className="h-4 w-4" />
                                                                MODÉRATEUR : ACTION FORCÉE
                                                            </h4>
                                                            <p className="text-sm text-zinc-400 mb-4 leading-relaxed">
                                                                Vous pouvez écraser la liaison existante. L&apos;ancien utilisateur perdra son accès immédiat.
                                                            </p>
                                                            <Button
                                                                size="lg"
                                                                variant="destructive"
                                                                onClick={() => handleLink(true)}
                                                                disabled={isLinking}
                                                                className="w-full h-12 font-black uppercase tracking-widest text-[10px]"
                                                            >
                                                                {isLinking && <Loader2 className="h-4 w-4 mr-3 animate-spin" />}
                                                                Forcer le transfert de propriété
                                                            </Button>
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    <DialogFooter className="p-8 bg-zinc-900/30 border-t border-white/5 relative z-10 flex flex-col sm:flex-row gap-3">
                                        {linkStep === 1 ? (
                                            <Button 
                                                onClick={() => setLinkStep(2)} 
                                                disabled={!inputPseudo.trim()}
                                                className="w-full sm:w-auto px-10 h-12 bg-zinc-100 text-zinc-950 hover:bg-white font-black uppercase tracking-widest text-[10px]"
                                            >
                                                Étape suivante
                                                <ArrowRightLeft className="w-4 h-4 ml-3" />
                                            </Button>
                                        ) : (
                                            <div className="flex gap-3 w-full">
                                                <Button 
                                                    variant="ghost" 
                                                    onClick={() => setLinkStep(1)} 
                                                    className="flex-1 h-12 border border-white/5 hover:bg-white/5 text-zinc-400 font-bold"
                                                >
                                                    Retour
                                                </Button>
                                                {!forceLink && (
                                                    <Button 
                                                        onClick={() => handleLink(false)} 
                                                        disabled={isLinking || !inputPseudo.trim() || !inputApiKey.trim()} 
                                                        className="flex-[2] h-12 bg-amber-600 hover:bg-amber-500 text-white font-black uppercase tracking-widest text-[10px] shadow-xl shadow-amber-900/30"
                                                    >
                                                        {isLinking ? <Loader2 className="h-4 w-4 mr-3 animate-spin" /> : <ShieldCheck className="w-4 h-4 mr-3" />}
                                                        Vérifier & Lier le compte
                                                    </Button>
                                                )}
                                            </div>
                                        )}
                                    </DialogFooter>
                                </DialogContent>
                            </Dialog>

                            {/* Helper Text for Unlinked State */}
                            <p className="text-[10px] text-zinc-500 text-right max-w-[200px]">
                                Liez votre compte pour accéder aux échanges d'archimonstres.
                            </p>
                        </div>
                    )
                )}
            </CardContent>
        </Card>
    );
}

function UserCircle({ className }: { className?: string }) {
    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            className={className}
        >
            <circle cx="12" cy="12" r="10" />
            <circle cx="12" cy="10" r="3" />
            <path d="M7 20.662V19a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v1.662" />
        </svg>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { HeroHeader } from "./hero-header";
import { ClassDisplay } from "./class-display";
import { JobsGrid } from "./jobs-grid";
import { AvailabilityHeatmap } from "./availability-heatmap";
import { VacationMode } from "./vacation-mode";
import { MetamobLink } from "./metamob-link";
import { AltPseudos } from "./alt-pseudos";
import { BuildsCard } from "./builds-card";
import { SuccessSync } from "./success-sync";
import { UserSettings } from "./user-settings";
import { IntroductionCard } from "./introduction-card";
import { MemberStats } from "./member-stats";
import { SkinLibrary } from "./skin-library";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { updateUserProfile, updateAvailability, updateVacationMode, updateForgemagieStatus, updateAltPseudos, type ContributorTier } from "@/server/actions/profile-actions";
import { toast } from "sonner";
import { UserCircle, LayoutDashboard, Shield, Sparkles, Users, Calendar, Trophy, BarChart3, Settings } from "lucide-react";
import { cn } from "@/lib/utils";
import { motion } from "framer-motion";
import type { AvailabilityMap, ForgemagieStatusId, GlobalAvailability } from "@/lib/dofus-assets";

interface ProfileBentoGridProps {
    profile: {
        id: string;
        userId?: string;
        pseudoDofus?: string | null;
        classe?: string | null;
        classeSecondaires?: string[] | null;
        metiers?: string[] | null;
        forgemagieStatus?: string | null;
        fmPriceClassic?: number | null;
        fmPriceTrans?: number | null;
        fmPriceExo?: number | null;
        availability?: GlobalAvailability | AvailabilityMap | null;
        vacationStart?: Date | null;
        vacationEnd?: Date | null;
        vacationNotify?: boolean;
        metamobPseudo?: string | null;
        metamobVerified?: boolean;
        metamobLastSync?: Date | null;
        altPseudos?: string[] | null;
        dofusBookLinks?: { id: string; url: string; name: string }[] | null;
        successPoints?: number | null;
        lastLadderUpdate?: Date | null;
        notificationPrefs?: {
            missions?: boolean;
            songes?: boolean;
            events?: boolean;
            ladder?: boolean;
            polls?: boolean;
            admin_validations?: boolean;
        } | null;
        pendingSubmission?: {
            id: string;
            points: number;
            ocrScore: number;
            createdAt: Date;
        } | null;
        roleGrants?: any[];
        introduction?: string | null;
        showPresence?: boolean;
        skins?: any[];
    };
    user: {
        name?: string | null;
        image?: string | null;
    };
    stats: {
        xp: number;
        weeklyXp: number;
        guildatons: number;
        missionsValidated: number;
        weeklyMissions: number;
        joinedAt: string | Date | null;
        lastActivity: { description: string; date: string | Date } | null;
        isTopContributor: boolean;
        contributorTier?: ContributorTier;
        rank?: number;
        weeklyActivity: { week: string; submissions: number; validated: number }[];
        missionsByCategory: { category: string; count: number; validated: number }[];
    };
    guildId: string;
    discordNickname?: string | null;
    readOnly?: boolean;
    isAdmin?: boolean;
    permissions?: {
        canViewOcre?: boolean;
        canViewSonges?: boolean;
        canViewLadder?: boolean;
        canSyncLadder?: boolean;
        canManualSyncLadder?: boolean;
        canViewMissions?: boolean;
    };
    guildName?: string;
    dofusServerId?: string | null;
    roleName?: string;
    roleColor?: number;
    welcomeBadgeName?: string | null;
    isSuperAdmin?: boolean;
}

export function ProfileBentoGrid({
    profile,
    user,
    stats,
    guildId,
    discordNickname,
    readOnly = false,
    isAdmin = false,
    permissions = {},
    guildName,
    dofusServerId,
    roleName = "Membre",
    roleColor = 0,
    welcomeBadgeName,
    isSuperAdmin = false,
}: ProfileBentoGridProps) {
    const [localProfile, setLocalProfile] = useState(profile);
    const searchParams = useSearchParams();
    const initialTab = searchParams.get("tab") || "overview";
    const [activeTab, setActiveTab] = useState(initialTab);

    // Default permissions to true if not provided (internal consistency)
    const { 
        canViewOcre = true, 
        canViewSonges = true, 
        canViewLadder = true, 
        canViewMissions = true,
        canSyncLadder = false,
        canManualSyncLadder = true
    } = permissions;

    // Sync state if URL param changes (optional but good for UX)
    useEffect(() => {
        const tab = searchParams.get("tab");
        if (tab) setActiveTab(tab);
    }, [searchParams]);

    const [visitedTabs, setVisitedTabs] = useState<Set<string>>(new Set([initialTab]));

    useEffect(() => {
        setVisitedTabs(prev => {
            if (prev.has(activeTab)) return prev;
            return new Set(prev).add(activeTab);
        });
    }, [activeTab]);

    const displayName = discordNickname || profile.pseudoDofus || user.name || "Voyageur";

    const now = new Date();
    const startDate = localProfile.vacationStart ? new Date(localProfile.vacationStart) : null;
    const endDate = localProfile.vacationEnd ? new Date(localProfile.vacationEnd) : null;

    const isUpcoming = Boolean(startDate && startDate > now);
    const isOnVacation = Boolean(startDate && startDate <= now && (!endDate || endDate >= now));

    // canEdit logic: Normal users can only edit if NOT readOnly. 
    // SuperAdmins can ALWAYS edit (God Mode).
    const canEdit = !readOnly || isSuperAdmin;
    const targetUserId = isSuperAdmin ? profile.userId : undefined;

    // Handlers
    const handleClassSave = async (mainClass: string, pseudo: string) => {
        setLocalProfile(prev => ({
            ...prev,
            classe: mainClass,
            pseudoDofus: pseudo
        }));

        const res = await updateUserProfile({
            guildId,
            classe: mainClass,
            // classeSecondaires: [], // Reset/Clear secondary classes
            pseudoDofus: pseudo,
            targetUserId
        });

        if (res.success) {
            toast.success("Profil mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleJobsSave = async (jobs: string[]) => {
        setLocalProfile(prev => ({ ...prev, metiers: jobs }));
        const res = await updateUserProfile({
            guildId,
            metiers: jobs,
            targetUserId
        });
        if (res.success) {
            toast.success("Métiers mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleForgemagieStatusSave = async (status: ForgemagieStatusId) => {
        setLocalProfile(prev => ({ ...prev, forgemagieStatus: status }));
        const res = await updateForgemagieStatus({ guildId, status, targetUserId });
        if (res.success) {
            toast.success("Statut Forgemagie mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleForgemagiePricesSave = async (prices: { classic: number | null, trans: number | null, exo: number | null }) => {
        setLocalProfile(prev => ({
            ...prev,
            fmPriceClassic: prices.classic,
            fmPriceTrans: prices.trans,
            fmPriceExo: prices.exo
        }));

        const res = await updateUserProfile({
            guildId,
            fmPriceClassic: prices.classic,
            fmPriceTrans: prices.trans,
            fmPriceExo: prices.exo,
            targetUserId
        });

        if (res.success) {
            toast.success("Tarifs Forgemagie mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleAvailabilitySave = async (availability: GlobalAvailability) => {
        setLocalProfile(prev => ({ ...prev, availability: availability as any }));
        const res = await updateAvailability({ guildId, availability, targetUserId });
        if (res.success) {
            toast.success("Disponibilités mises à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleVacationSave = async (data: { start: Date | null; end: Date | null; notify: boolean; noEndDate: boolean }) => {
        setLocalProfile(prev => ({
            ...prev,
            vacationStart: data.start,
            vacationEnd: data.noEndDate ? null : data.end,
            vacationNotify: data.notify,
        }));
        const res = await updateVacationMode({
            guildId,
            vacationStart: data.start?.toISOString() ?? null,
            vacationEnd: data.noEndDate ? null : (data.end?.toISOString() ?? null),
            vacationNotify: data.notify,
            targetUserId
        });
        if (res.success) {
            toast.success("Mode vacances mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleAltPseudosSave = async (altPseudos: any[]) => {
        const res = await updateAltPseudos({ guildId, altPseudos, targetUserId });
        if (res.success) {
            setLocalProfile(prev => ({ ...prev, altPseudos }));
        } else {
            toast.error(res.error || "Erreur lors de la sauvegarde");
            throw new Error(res.error); // Allow component to handle error
        }
    };

    const handlePresenceToggle = async (enabled: boolean) => {
        setLocalProfile(prev => ({ ...prev, showPresence: enabled }));
        const res = await updateUserProfile({ guildId, showPresence: enabled, targetUserId });
        if (res.success) {
            toast.success(enabled ? "Visibilité de l'activité activée" : "Visibilité de l'activité désactivée");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleNotificationPrefsSave = (prefs: any) => {
        setLocalProfile(prev => ({
            ...prev,
            notificationPrefs: {
                ...(prev.notificationPrefs || {}),
                ...prefs
            }
        }));
    };

    return (
        <div className="flex flex-col gap-6">
            {/* Hero Header (Glass) */}
            <div className="rounded-3xl overflow-hidden border border-white/10 shadow-2xl bg-black/40 backdrop-blur-md">
                <HeroHeader
                    avatarUrl={user.image}
                    displayName={displayName}
                    roleColor={roleColor}
                    contributorTier={stats.contributorTier}
                    rank={stats.rank}
                    isOnVacation={isOnVacation}
                    isUpcomingVacation={isUpcoming}
                    vacationStart={startDate}
                    vacationEnd={endDate}
                    joinedAt={stats.joinedAt}
                    canViewMissions={permissions.canViewMissions}
                    canViewLadder={canViewLadder}
                    guildName={guildName}
                    sigilRoles={localProfile.roleGrants || []}
                    discordRoleName={roleName}
                    discordRoleColor={roleColor}
                    welcomeBadgeName={welcomeBadgeName}
                />
            </div>

            {/* Sigma 2026 Adaptive Layout */}
            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                <div className="grid lg:grid-cols-[280px_1fr] grid-cols-1 gap-8 items-start">
                
                {/* Sidebar Navigation (Sticky on Desktop, Scrollable on Mobile) */}
                <aside className="lg:sticky lg:top-24 z-20 min-w-0 w-full">
                    <TabsList className="bg-transparent flex lg:flex-col flex-row flex-nowrap overflow-x-auto lg:overflow-visible gap-2 p-1 h-auto justify-start border-none w-full scrollbar-width-none [&::-webkit-scrollbar]:hidden">
                        {[
                            { id: "overview", label: "Général", icon: UserCircle, color: "emerald text-emerald-500" },
                            { id: "intro", label: "Présentation", icon: LayoutDashboard, color: "emerald text-emerald-500" },
                            { id: "combat", label: "Stuffs", icon: Shield, color: "indigo text-indigo-500" },
                            { id: "skins", label: "Skins", icon: Sparkles, color: "pink text-pink-500" },
                            { id: "mules", icon: Users, label: "Mules", color: "indigo text-indigo-500" },
                            { id: "planning", label: "Planning", icon: Calendar, color: "amber text-amber-500" },
                            { id: "achievements", label: "Succès", icon: Trophy, color: "amber text-amber-500" },
                            { id: "stats", label: "Statistiques", icon: BarChart3, color: "cyan text-cyan-500" },
                            ...(canEdit ? [{ id: "settings", label: "Réglages", icon: Settings, color: "zinc text-zinc-400" }] : []),
                        ].map((tab) => (
                            <TabsTrigger
                                key={tab.id}
                                value={tab.id}
                                className={cn(
                                    "relative flex items-center justify-start gap-3 min-w-[max-content] lg:w-full px-4 py-3 rounded-2xl transition-all duration-300 group shrink-0 overflow-hidden",
                                    "bg-zinc-900/40 backdrop-blur-md border border-white/5",
                                    "data-[state=active]:border-white/10 data-[state=active]:shadow-[0_0_20px_rgba(0,0,0,0.3)]",
                                    "hover:bg-white/[0.07] hover:border-white/10 active:scale-[0.98]"
                                )}
                            >
                                {/* Active Background Slide */}
                                {activeTab === tab.id && (
                                    <motion.div 
                                        layoutId="profile-tab-active"
                                        className="absolute inset-0 bg-white/5 z-0"
                                        transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
                                    />
                                )}

                                {/* Hover Glow (Pre-click highlight) */}
                                <div className="absolute inset-x-0 bottom-0 h-0.5 bg-gradient-to-r from-transparent via-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

                                <div className={cn(
                                    "p-2 rounded-xl transition-all duration-500 z-10",
                                    "bg-zinc-800/50 group-data-[state=active]:scale-110 group-data-[state=active]:translate-x-1",
                                    activeTab === tab.id ? `text-${tab.color.split(' ')[0]}-400 shadow-[0_0_15px_rgba(0,0,0,0.3)]` : "text-zinc-500 group-hover:text-zinc-300"
                                )}>
                                    <tab.icon className="w-5 h-5" />
                                </div>
                                
                                <span className={cn(
                                    "text-sm font-black uppercase tracking-widest transition-all duration-300 z-10",
                                    activeTab === tab.id ? "text-white translate-x-1" : "text-zinc-400 group-hover:text-zinc-200 group-hover:translate-x-0.5"
                                )}>
                                    {tab.label}
                                </span>
...
                                {/* Neon Indicator (Sigma 2026 Core) */}
                                {activeTab === tab.id && (
                                    <div className={cn(
                                        "absolute left-0 w-1 h-6 rounded-full z-10",
                                        `bg-${tab.color.split(' ')[0]}-500 shadow-[0_0_10px_rgba(0,0,0,0.5)] shadow-${tab.color.split(' ')[0]}-500/50`
                                    )} />
                                )}
                            </TabsTrigger>
                        ))}
                    </TabsList>
                </aside>

                {/* Main Content Area */}
                <div className="min-w-0 space-y-8">

                {/* OVERVIEW TAB */}
                <TabsContent value="overview" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 items-start">
                        <div className="flex flex-col gap-6">
                            {/* Classes */}
                            <ClassDisplay
                                pseudoDofus={localProfile.pseudoDofus}
                                mainClass={localProfile.classe}
                                onSave={handleClassSave}
                                readOnly={!canEdit}
                            />

                            {/* Metamob */}
                            {canViewOcre && (
                                <MetamobLink
                                    guildId={guildId}
                                    metamobPseudo={profile.metamobPseudo}
                                    metamobVerified={profile.metamobVerified}
                                    metamobLastSync={profile.metamobLastSync}
                                    readOnly={!canEdit}
                                    isAdmin={isAdmin}
                                    targetUserId={targetUserId}
                                />
                            )}
                        </div>

                        {/* Jobs */}
                        <JobsGrid
                            jobs={localProfile.metiers || []}
                            forgemagieStatus={(localProfile.forgemagieStatus as ForgemagieStatusId) || "UNAVAILABLE"}
                            fmPriceClassic={localProfile.fmPriceClassic}
                            fmPriceTrans={localProfile.fmPriceTrans}
                            fmPriceExo={localProfile.fmPriceExo}
                            onSaveJobs={handleJobsSave}
                            onSaveForgemagieStatus={handleForgemagieStatusSave}
                            onSaveForgemagiePrices={handleForgemagiePricesSave}
                            readOnly={!canEdit}
                        />
                    </div>
                </TabsContent>

                {/* INTRODUCTION TAB */}
                <TabsContent value="intro" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("intro") && (
                        <IntroductionCard
                            introduction={localProfile.introduction || ""}
                            onSave={(text: string) => setLocalProfile(prev => ({ ...prev, introduction: text }))}
                            readOnly={!canEdit}
                            guildId={guildId}
                            displayName={displayName}
                            targetUserId={targetUserId}
                        />
                    )}
                </TabsContent>

                {/* COMBAT TAB (Stuffs) */}
                <TabsContent value="combat" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("combat") && (
                        <div className="w-full">
                            <BuildsCard
                                links={localProfile.dofusBookLinks as any || []}
                                onSave={(links) => setLocalProfile(prev => ({ ...prev, dofusBookLinks: links }))}
                                readOnly={!canEdit}
                                guildId={guildId}
                                targetUserId={targetUserId}
                            />
                        </div>
                    )}
                </TabsContent>

                {/* SKINS TAB */}
                <TabsContent value="skins" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("skins") && (
                        <div className="w-full">
                            <SkinLibrary 
                                initialSkins={localProfile.skins || []}
                                guildId={guildId}
                                readOnly={!canEdit}
                                profileId={localProfile.id}
                            />
                        </div>
                    )}
                </TabsContent>

                {/* MULES TAB */}
                <TabsContent value="mules" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("mules") && (
                        <div className="w-full">
                            <AltPseudos
                                altPseudos={localProfile.altPseudos as any || []}
                                onSave={handleAltPseudosSave}
                                readOnly={!canEdit}
                            />
                        </div>
                    )}
                </TabsContent>

                {/* PLANNING TAB */}
                <TabsContent value="planning" className="animate-in fade-in slide-in-from-bottom-4 duration-500 flex flex-col gap-6">
                    {visitedTabs.has("planning") && (
                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                            <div className="lg:col-span-2">
                                <AvailabilityHeatmap
                                    availability={localProfile.availability || {}}
                                    onSave={handleAvailabilitySave}
                                    readOnly={!canEdit}
                                    vacationStart={localProfile.vacationStart}
                                    vacationEnd={localProfile.vacationEnd}
                                />
                            </div>
                            <div>
                                <VacationMode
                                    vacationStart={localProfile.vacationStart}
                                    vacationEnd={localProfile.vacationEnd}
                                    vacationNotify={localProfile.vacationNotify}
                                    onSave={handleVacationSave}
                                    readOnly={!canEdit}
                                    guildId={guildId}
                                    pseudo={displayName}
                                    profileId={profile.id}
                                />
                            </div>
                        </div>
                    )}
                </TabsContent>

                {/* ACHIEVEMENTS TAB */}
                <TabsContent value="achievements" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("achievements") && (
                        <SuccessSync
                            pseudoDofus={localProfile.pseudoDofus}
                            guildId={guildId}
                            dofusServerId={dofusServerId}
                            successPoints={localProfile.successPoints}
                            lastUpdate={localProfile.lastLadderUpdate}
                            readOnly={!canEdit}
                            onTabChange={setActiveTab}
                            onSuccess={(points) => {
                                setLocalProfile(prev => ({
                                    ...prev,
                                    successPoints: points,
                                    lastLadderUpdate: new Date(),
                                    pendingSubmission: null
                                }));
                            }}
                            pendingSubmission={localProfile.pendingSubmission}
                            onCancel={() => {
                                setLocalProfile(prev => ({
                                    ...prev,
                                    pendingSubmission: null
                                }));
                            }}
                            targetUserId={targetUserId}
                            canSyncLadder={canSyncLadder}
                            canManualSync={canManualSyncLadder}
                            isSuperAdmin={isSuperAdmin}
                            isAdmin={isAdmin}
                        />
                    )}
                </TabsContent>

                {/* STATS TAB */}
                <TabsContent value="stats" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("stats") && (
                        <MemberStats stats={stats} />
                    )}
                </TabsContent>

                {/* SETTINGS TAB */}
                {canEdit && (
                    <TabsContent value="settings" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                        {visitedTabs.has("settings") && (
                            <UserSettings
                                guildId={guildId}
                                guildName={guildName || "la guilde"}
                                profileId={profile.id}
                                notificationPrefs={localProfile.notificationPrefs as any}
                                onNotificationPrefsSave={handleNotificationPrefsSave}
                                showPresence={localProfile.showPresence ?? true}
                                onPresenceToggle={handlePresenceToggle}
                                isAdmin={isAdmin}
                                targetUserId={targetUserId}
                            />
                        )}
                    </TabsContent>
                )}
                </div>
            </div>
            </Tabs>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import { UserProfile } from "@prisma/client";
import { updateUserProfile } from "@/server/actions/profile-actions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { MultiSelect } from "@/components/ui/multi-select";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { DOFUS_CLASSES, DOFUS_JOBS } from "@/lib/dofus-data";
import { Loader2, Save, User as UserIcon } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { formatDofusPseudo } from "@/lib/utils";

interface ExtendedProfile extends UserProfile {
    user: { name: string | null; image: string | null };
    xp: number;
    guildatons: number;
}

interface ProfileEditorProps {
    profile: any; // Bypass stale type
    guildId: string;
}

export function ProfileEditor({ profile: rawProfile, guildId }: ProfileEditorProps) {
    const profile = rawProfile as ExtendedProfile;
    const [isPending, startTransition] = useTransition();

    const [pseudo, setPseudo] = useState(profile.pseudoDofus || "");
    const [classe, setClasse] = useState(profile.classe || "");
    // Helper to safely parse JSONB
    const initialJobs = Array.isArray(profile.metiers) ? (profile.metiers as string[]) : [];
    const [jobs, setJobs] = useState<string[]>(initialJobs);

    const handleSave = () => {
        if (!pseudo) {
            toast.error("Le pseudo est obligatoire");
            return;
        }

        startTransition(async () => {
            const result = await updateUserProfile({
                guildId,
                pseudoDofus: pseudo,
                classe: classe || undefined,
                metiers: jobs
            });

            if (result.success) {
                toast.success("Profil mis à jour avec succès");
            } else {
                toast.error(result.error || "Erreur lors de la mise à jour");
            }
        });
    };

    const jobOptions = DOFUS_JOBS.map(job => ({ label: job, value: job }));

    return (
        <div className="grid gap-6 md:grid-cols-2">

            {/* ID CARD */}
            <Card className="bg-black/40 border-white/10 backdrop-blur-sm h-fit">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <UserIcon className="w-5 h-5 text-primary" />
                        Identité Visuelle
                    </CardTitle>
                    <CardDescription>
                        Aperçu de votre carte de membre dans l'annuaire.
                    </CardDescription>
                </CardHeader>
                <CardContent className="flex flex-col items-center justify-center py-6 gap-4">
                    <div className="relative group">
                        <Avatar className="w-32 h-32 border-4 border-white/10 shadow-xl group-hover:border-primary transition-colors">
                            <AvatarImage src={profile.user.image || ""} />
                            <AvatarFallback className="text-4xl bg-zinc-800 text-zinc-400">
                                {profile.user.name?.[0]?.toUpperCase() || "?"}
                            </AvatarFallback>
                        </Avatar>
                        {/* Placeholder for future avatar upload */}
                    </div>

                    <div className="text-center space-y-1">
                        <h3 className="text-2xl font-bold text-white tracking-tight">
                            {pseudo || profile.user.name || "Inconnu"}
                        </h3>
                        <p className="text-primary font-medium">{classe || "Classe inconnue"}</p>

                        {/* Stats Badges */}
                        <div className="flex items-center justify-center gap-3 mt-4 text-xs font-mono">
                            <div className="px-3 py-1 rounded-full bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">
                                ✨ {profile.xp} XP
                            </div>
                            <div className="px-3 py-1 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/30">
                                🪙 {profile.guildatons} G
                            </div>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* FORM */}
            <Card className="bg-zinc-900/50 border-white/10">
                <CardHeader>
                    <CardTitle>Configuration du Profil</CardTitle>
                    <CardDescription>
                        Ces informations permettent aux autres membres de vous trouver.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">

                    <div className="space-y-2">
                        <Label>Pseudo en jeu (Obligatoire)</Label>
                        <Input
                            value={pseudo}
                            onChange={(e) => setPseudo(formatDofusPseudo(e.target.value))}
                            placeholder="Ex: Dark-Sasuké"
                            className="bg-zinc-950/50 border-white/10 focus:border-primary/50"
                        />
                        <p className="text-xs text-muted-foreground">Utilisé pour la validation des preuves.</p>
                    </div>

                    <div className="space-y-2">
                        <Label>Classe</Label>
                        <Select value={classe} onValueChange={setClasse}>
                            <SelectTrigger className="bg-zinc-950/50 border-white/10">
                                <SelectValue placeholder="Sélectionner une classe" />
                            </SelectTrigger>
                            <SelectContent>
                                {DOFUS_CLASSES.map((c) => (
                                    <SelectItem key={c} value={c}>
                                        {c}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="space-y-2">
                        <Label>Métiers (Niveau 200)</Label>
                        <MultiSelect
                            options={jobOptions}
                            selected={jobs}
                            onChange={setJobs}
                            placeholder="Sélectionner vos métiers"
                        />
                        <p className="text-xs text-muted-foreground">
                            Sélectionnez uniquement vos métiers maîtrisés.
                        </p>
                    </div>

                </CardContent>
                <CardFooter className="flex justify-between border-t border-white/5 pt-6">
                    <Button variant="ghost" onClick={() => setPseudo(profile.pseudoDofus || "")}>
                        Annuler
                    </Button>
                    <Button onClick={handleSave} disabled={isPending} className="min-w-[140px]">
                        {isPending ? (
                            <>
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                Sauvegarde...
                            </>
                        ) : (
                            <>
                                <Save className="w-4 h-4 mr-2" />
                                Enregistrer
                            </>
                        )}
                    </Button>
                </CardFooter>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { 
    Sparkles, 
    Plus, 
    Trash2, 
    ExternalLink, 
    Eye, 
    LayoutGrid, 
    Info, 
    Loader2, 
    Copy, 
    RefreshCw, 
    HelpCircle, 
    Globe, 
    Search, 
    X, 
    Megaphone, 
    Send, 
    Pencil,
    Mars,
    Venus
} from "lucide-react";
import { ClassFilter, GenderFilter } from "@/components/gallery/gallery-filters";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import NextImage from "next/image";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { addUserSkin, deleteUserSkin, getSkinPreview, type SkinData, updateUserSkin } from "@/server/actions/skin-actions";
import { shareGalleryItemOnDiscord } from "@/server/actions/gallery-actions";

interface Skin {
    id: string;
    name: string;
    url: string;
    provider: string;
    thumbnailUrl: string | null;
    equipment?: any;
    colors?: any;
    metadata?: any;
    createdAt: Date | string;
}

interface SkinLibraryProps {
    initialSkins: Skin[];
    guildId: string;
    readOnly?: boolean;
    profileId: string;
}

export function SkinLibrary({ initialSkins, guildId, readOnly = false, profileId }: SkinLibraryProps) {
    const [skins, setSkins] = useState<Skin[]>(initialSkins);
    const [isAddOpen, setIsAddOpen] = useState(false);
    const [newSkinUrl, setNewSkinUrl] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedSkin, setSelectedSkin] = useState<Skin | null>(null);
    const [previewData, setPreviewData] = useState<SkinData | null>(null);
    const [isPreviewLoading, setIsPreviewLoading] = useState(false);

    const [isEditOpen, setIsEditOpen] = useState(false);
    const [skinToEdit, setSkinToEdit] = useState<Skin | null>(null);
    const [editedName, setEditedName] = useState("");
    const [editedUrl, setEditedUrl] = useState("");

    // Filter State
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [selectedGender, setSelectedGender] = useState<string | null>(null);

    // Client-side filtering logic
    const filteredSkins = useMemo(() => {
        const normalize = (s: string) => s ? s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim() : "";

        return skins.filter(skin => {
            // 1. Search filter
            if (searchQuery) {
                const q = searchQuery.toLowerCase();
                const matchesTitle = skin.name.toLowerCase().includes(q);
                const matchesAuthor = skin.metadata?.author?.toLowerCase().includes(q);
                if (!matchesTitle && !matchesAuthor) return false;
            }

            // 2. Class filter
            if (selectedClass) {
                // Handle both numerical (Dofus IDs) and string class names
                const skinClass = skin.metadata?.class;
                if (!skinClass) return false;
                
                // Mapping is done by name for now as metadata.class stores names
                const targetClass = DOFUS_CLASSES.find((c: any) => {
                    const match = c.icon.match(/classes\/(\d+)\.png/);
                    return match && match[1] === selectedClass;
                });
                
                if (!targetClass) return false;
                
                const matchesId = skinClass === selectedClass;
                const matchesName = normalize(skinClass).includes(normalize(targetClass.name));
                
                if (!matchesId && !matchesName) return false;
            }

            // 3. Gender filter
            if (selectedGender) {
                const skinGender = skin.metadata?.gender; // Normalized to M/F by scraper now, but handle legacy
                if (!skinGender) return false;
                
                const mValues = ["M", "Homme", "♂", "Mâle", "Male"];
                const fValues = ["F", "Femme", "♀", "Femelle"];
                const valuesToMatch = selectedGender === "M" ? mValues : fValues;
                
                const normalizedSearch = valuesToMatch.map(v => normalize(v));
                if (!normalizedSearch.includes(normalize(skinGender))) return false;
            }

            return true;
        });
    }, [skins, searchQuery, selectedClass, selectedGender]);


    // Live Preview Effect
    useEffect(() => {
        if (!newSkinUrl.trim() || newSkinUrl.length < 15) {
            setPreviewData(null);
            return;
        }

        const timer = setTimeout(async () => {
            const isSupported = newSkinUrl.includes("barbofus.com") || 
                              newSkinUrl.includes("dofusskinmanga.com");
            
            if (!isSupported) return;

            setIsPreviewLoading(true);
            try {
                const res = await getSkinPreview(newSkinUrl.trim());
                if (res.success && res.data) {
                    setPreviewData(res.data);
                }
            } finally {
                setIsPreviewLoading(false);
            }
        }, 800);

        return () => clearTimeout(timer);
    }, [newSkinUrl]);

    const handleAddSkin = async () => {
        if (!newSkinUrl.trim()) {
            toast.error("Veuillez entrer une URL");
            return;
        }

        setIsSubmitting(true);
        try {
            const res = await addUserSkin({ guildId, url: newSkinUrl.trim() });
            if (res.success && res.data) {
                toast.success("Skin ajouté à votre bibliothèque !");
                setIsAddOpen(false);
                setNewSkinUrl("");
                setSkins(prev => [res.data, ...prev]);
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCopyLink = (url: string) => {
        navigator.clipboard.writeText(url);
        toast.success("Lien copié !");
    };

    const handleRefreshMetadata = async (skinId: string, url: string) => {
        setIsSubmitting(true);
        toast.info("Mise à jour des données...");
        try {
            const res = await addUserSkin({ guildId, url: url.trim(), existingSkinId: skinId });
            if (res.success && res.data) {
                setSkins(prev => prev.map(s => s.id === skinId ? res.data : s));
                toast.success("Données actualisées !");
            } else {
                toast.error(res.error || "Erreur lors de la mise à jour");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const [isDeleteOpen, setIsDeleteOpen] = useState(false);
    const [skinToDelete, setSkinToDelete] = useState<string | null>(null);

    const handleDeleteSkin = async () => {
        if (readOnly || !skinToDelete) return;
        
        setIsSubmitting(true);
        try {
            const res = await deleteUserSkin(guildId, skinToDelete);
            if (res.success) {
                setSkins(prev => prev.filter(s => s.id !== skinToDelete));
                toast.success("Skin supprimé avec succès");
                setIsDeleteOpen(false);
                setSkinToDelete(null);
            } else {
                toast.error(res.error || "Erreur lors de la suppression");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleUpdateSkin = async () => {
        if (!skinToEdit || !editedName.trim()) return;

        setIsSubmitting(true);
        try {
            const res = await updateUserSkin(guildId, skinToEdit.id, { 
                name: editedName.trim(),
                url: editedUrl.trim() 
            });
            if (res.success && res.data) {
                // If URL changed, we use the full returned object in case metadata changed
                setSkins(prev => prev.map(s => s.id === skinToEdit.id ? res.data : s));
                toast.success("Skin mis à jour avec succès !");
                setIsEditOpen(false);
                setSkinToEdit(null);
            } else {
                toast.error(res.error || "Erreur lors de la modification");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };


    const getProviderIcon = (provider: string) => {
        switch (provider) {
            case "BARBOFUS": return "/assets/ui/icons/barbofus.png";
            case "DOFUSSKINMANGA": return "/assets/ui/icons/dofusskinmanga.png"; 
            default: return null;
        }
    };

    return (
        <div className="flex flex-col gap-6">
            {/* Header / Actions */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-zinc-900/40 backdrop-blur-md p-6 rounded-3xl border border-white/10">
                <div className="flex items-center gap-3">
                    <div className="p-3 bg-pink-500/10 rounded-2xl border border-pink-500/20">
                        <Sparkles className="w-6 h-6 text-pink-400" />
                    </div>
                    <div>
                        <div className="flex items-center gap-4">
                            <h3 className="text-xl font-bold text-white">Ma Garde-Robe</h3>
                            <Popover>
                                <PopoverTrigger asChild>
                                    <Button variant="outline" size="sm" className="h-8 rounded-xl border-pink-500/30 bg-pink-500/5 text-pink-400 hover:bg-pink-500 hover:text-white transition-all gap-2 text-[10px] font-black uppercase tracking-widest shadow-lg shadow-pink-500/10">
                                        <HelpCircle className="w-3.5 h-3.5" />
                                        Comment ça marche ?
                                    </Button>
                                </PopoverTrigger>
                                <PopoverContent className="w-80 bg-zinc-950 border-white/10 p-0 rounded-[2rem] shadow-2xl overflow-hidden border-2 border-pink-500/20">
                                    <div className="bg-gradient-to-r from-pink-500/20 to-purple-500/20 p-5 border-b border-white/5">
                                        <h4 className="font-black text-xs uppercase tracking-widest text-white flex items-center gap-2">
                                            <Sparkles className="w-4 h-4 text-pink-400" />
                                            Guide Mode & Skins
                                        </h4>
                                    </div>
                                    <div className="p-6 space-y-8">
                                        <div className="space-y-4">
                                            <p className="text-[10px] text-zinc-500 font-black uppercase tracking-[0.2em]">1. Choisir un site</p>
                                            <div className="grid grid-cols-1 gap-3">
                                                <a 
                                                    href="https://barbofus.com" 
                                                    target="_blank" 
                                                    rel="noopener noreferrer"
                                                    className="flex items-center justify-between p-4 bg-white/5 hover:bg-pink-500/10 rounded-2xl border border-white/5 hover:border-pink-500/30 transition-all group"
                                                >
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-10 h-10 rounded-xl bg-pink-500/10 flex items-center justify-center border border-pink-500/20 shadow-inner overflow-hidden">
                                                            <img src="https://www.google.com/s2/favicons?domain=barbofus.com&sz=64" alt="Barbofus" className="w-6 h-6 object-contain" />
                                                        </div>
                                                        <div className="flex flex-col">
                                                            <span className="text-xs font-black text-white uppercase tracking-wider">Barbofus</span>
                                                            <span className="text-[9px] text-zinc-500">Le roi des skins</span>
                                                        </div>
                                                    </div>
                                                    <ExternalLink className="w-4 h-4 text-zinc-600 group-hover:text-pink-400 transition-colors" />
                                                </a>
                                                <a 
                                                    href="https://dofusskinmanga.com" 
                                                    target="_blank" 
                                                    rel="noopener noreferrer"
                                                    className="flex items-center justify-between p-4 bg-white/5 hover:bg-emerald-500/10 rounded-2xl border border-white/5 hover:border-emerald-500/30 transition-all group"
                                                >
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center border border-emerald-500/20 shadow-inner overflow-hidden">
                                                            <img src="https://www.google.com/s2/favicons?domain=dofusskinmanga.com&sz=64" alt="SkinManga" className="w-6 h-6 object-contain" />
                                                        </div>
                                                        <div className="flex flex-col">
                                                            <span className="text-xs font-black text-white uppercase tracking-wider">SkinManga</span>
                                                            <span className="text-[9px] text-zinc-500">Inspiration & Manga</span>
                                                        </div>
                                                    </div>
                                                    <ExternalLink className="w-4 h-4 text-zinc-600 group-hover:text-emerald-400 transition-colors" />
                                                </a>
                                            </div>
                                        </div>

                                        <div className="space-y-4">
                                            <p className="text-[10px] text-zinc-500 font-black uppercase tracking-[0.2em]">2. Méthode Express</p>
                                            <div className="space-y-5">
                                                {[
                                                    { step: 1, text: "Crée ton skin sur un site.", sub: "Personalise tout à fond !" },
                                                    { step: 2, text: "Copie l'URL de la page.", sub: "L'adresse dans ton navigateur." },
                                                    { step: 3, text: "Colle le lien sur SigilOS.", sub: "On récupère tout auto !" }
                                                ].map((s) => (
                                                    <div key={s.step} className="flex gap-4">
                                                        <div className="w-6 h-6 rounded-lg bg-pink-500 text-white text-[10px] font-black flex items-center justify-center shrink-0 shadow-lg shadow-pink-500/20 uppercase">
                                                            {s.step}
                                                        </div>
                                                        <div className="flex flex-col gap-0.5">
                                                            <p className="text-[11px] text-zinc-200 font-bold leading-tight">{s.text}</p>
                                                            <p className="text-[9px] text-zinc-500 italic">{s.sub}</p>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="bg-white/5 p-4 border-t border-white/5 flex items-center justify-center gap-2">
                                        <div className="w-1.5 h-1.5 rounded-full bg-pink-500 animate-pulse" />
                                        <p className="text-[9px] text-zinc-400 font-bold uppercase tracking-widest text-center">Magie SigilOS Activée</p>
                                    </div>
                                </PopoverContent>
                            </Popover>
                        </div>
                        <p className="text-zinc-500 text-sm">Gérez et listez vos plus beaux skins communautaires.</p>
                    </div>
                </div>

                {!readOnly && (
                    <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
                        <DialogTrigger asChild>
                            <Button variant="sigil" size="lg" className="rounded-2xl gap-2 shadow-lg shadow-pink-500/20">
                                <Plus className="w-5 h-5" />
                                Importer un Skin
                            </Button>
                        </DialogTrigger>
                        <DialogContent className="bg-zinc-950 border-white/10 text-white sm:max-w-md">
                            <DialogHeader>
                                <DialogTitle>Ajouter un nouveau skin</DialogTitle>
                                <DialogDescription className="text-zinc-400">
                                    Collez un lien Barbofus ou DofusSkinManga.
                                </DialogDescription>
                            </DialogHeader>
                            <div className="grid gap-4 py-4">
                                <div className="space-y-2">
                                    <Label htmlFor="url">URL du Skin</Label>
                                    <Input
                                        id="url"
                                        placeholder="https://barbofus.com/skinator/view/..."
                                        value={newSkinUrl}
                                        onChange={(e) => setNewSkinUrl(e.target.value)}
                                        className="bg-zinc-900 border-white/10 focus:border-pink-500/50 transition-colors"
                                    />
                                </div>

                                {/* Preview Area */}
                                {(isPreviewLoading || previewData) && (
                                    <div className="bg-zinc-900/50 border border-white/5 rounded-2xl p-4 animate-in fade-in zoom-in duration-300">
                                        <div className="flex items-center gap-4">
                                            <div className="w-16 h-16 bg-black/40 rounded-xl relative flex items-center justify-center border border-white/10 overflow-hidden">
                                                {isPreviewLoading ? (
                                                    <Loader2 className="w-6 h-6 text-pink-500 animate-spin" />
                                                ) : previewData?.thumbnailUrl ? (
                                                    <NextImage 
                                                        src={previewData.thumbnailUrl} 
                                                        alt="Preview" 
                                                        fill 
                                                        className="object-contain p-1" 
                                                        unoptimized
                                                    />
                                                ) : (
                                                    <Sparkles className="w-6 h-6 text-zinc-700" />
                                                )}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                {isPreviewLoading ? (
                                                    <div className="space-y-2">
                                                        <div className="h-4 bg-zinc-800 rounded animate-pulse w-3/4" />
                                                        <div className="h-3 bg-zinc-800 rounded animate-pulse w-1/2" />
                                                    </div>
                                                ) : (
                                                    <>
                                                        <p className="text-sm font-bold text-white truncate">{previewData?.name}</p>
                                                        <div className="flex items-center gap-2 mt-1">
                                                            <span className="text-[10px] font-black text-pink-500 uppercase tracking-tighter">
                                                                {previewData?.provider}
                                                                {(previewData?.equipment?.length > 0 || Object.keys(previewData?.colors || {}).length > 0) && " + Détails détectés"}
                                                            </span>
                                                        </div>
                                                    </>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                )}

                                <div className="bg-pink-500/5 border border-pink-500/10 rounded-xl p-3 flex gap-3">
                                    <Info className="w-5 h-5 text-pink-400 shrink-0" />
                                    <p className="text-[11px] text-zinc-400 leading-relaxed">
                                        Nous irons chercher automatiquement la miniature et les informations du skin pour vous.
                                    </p>
                                </div>
                            </div>
                            <DialogFooter className="gap-2 sm:gap-0">
                                <Button 
                                    variant="ghost" 
                                    onClick={() => setIsAddOpen(false)} 
                                    disabled={isSubmitting}
                                    className="rounded-xl hover:bg-white/5 text-zinc-400 hover:text-white transition-all active:scale-95"
                                >
                                    Annuler
                                </Button>
                                <Button 
                                    variant="sigil" 
                                    onClick={handleAddSkin} 
                                    disabled={isSubmitting}
                                    className="rounded-xl relative overflow-hidden group/btn active:scale-95 transition-all shadow-lg shadow-pink-500/20"
                                >
                                    {/* Shine Effect on Hover/Active */}
                                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent translate-x-[-100%] group-hover/btn:translate-x-[100%] transition-transform duration-700 ease-in-out pointer-events-none" />
                                    
                                    <span className="relative z-10 flex items-center justify-center font-black uppercase tracking-widest text-[11px]">
                                        {isSubmitting ? (
                                            <>
                                                <Loader2 className="w-3.5 h-3.5 mr-2 animate-spin text-white" /> 
                                                <span className="animate-pulse">Importation...</span>
                                            </>
                                        ) : "Importer le Skin"}
                                    </span>
                                </Button>
                            </DialogFooter>
                        </DialogContent>
                    </Dialog>
                )}
            </div>

            {/* Filters Bar */}
            <div className="flex flex-col xl:flex-row items-center gap-4 bg-zinc-950/60 p-4 rounded-2xl border border-white/5 shadow-inner">
                <div className="relative w-full xl:w-80 group">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 group-focus-within:text-pink-400 transition-colors" />
                    <Input 
                        placeholder="Filtrer par nom, auteur..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="bg-black/40 border-white/5 pl-10 h-10 rounded-xl focus:border-pink-500/50 transition-all text-xs"
                    />
                </div>

                <div className="flex items-center gap-3 w-full xl:w-auto">
                    <ClassFilter selectedClass={selectedClass} onSelectClass={(id) => setSelectedClass(id as string)} />
                    <GenderFilter selectedGender={selectedGender} onSelectGender={setSelectedGender} />
                    
                    {(searchQuery || selectedClass || selectedGender) && (
                        <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => { setSearchQuery(""); setSelectedClass(null); setSelectedGender(null); }}
                            className="ml-auto xl:ml-0 h-10 px-4 rounded-xl text-zinc-500 hover:text-white hover:bg-white/5 gap-2 text-[10px] font-black uppercase tracking-widest"
                        >
                            <RefreshCw className="w-3 h-3" />
                            Reset
                        </Button>
                    )}
                </div>

                <div className="ml-auto hidden xl:flex items-center gap-2">
                    <p className="text-[10px] text-zinc-600 font-black uppercase tracking-widest">
                        <span className="text-pink-500">{filteredSkins.length}</span> Skins trouvés
                    </p>
                </div>
            </div>

            {/* Empty State */}
            {skins.length === 0 && (
                <div className="flex flex-col items-center justify-center p-20 bg-zinc-900/20 rounded-[2.5rem] border-2 border-dashed border-white/5 group">
                    <div className="relative mb-6">
                        <div className="p-8 bg-zinc-900/50 rounded-full border border-white/5 transition-transform group-hover:scale-110 duration-500">
                            <LayoutGrid className="w-12 h-12 text-zinc-700" />
                        </div>
                        <Sparkles className="absolute -top-2 -right-2 w-8 h-8 text-pink-500/30 animate-pulse" />
                    </div>
                    <h4 className="text-white font-black uppercase tracking-widest text-lg mb-2">Ta Garde-Robe est vide</h4>
                    <p className="text-zinc-500 text-center max-w-sm text-sm mb-8 leading-relaxed">
                        Crée tes skins sur nos sites partenaires et importe-les ici pour les partager avec ta guilde.
                    </p>

                    <div className="flex flex-wrap items-center justify-center gap-4">
                        <a 
                            href="https://barbofus.com" 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="px-6 py-3 bg-white/5 hover:bg-pink-500/20 rounded-2xl border border-white/5 hover:border-pink-500/40 text-xs font-black text-white uppercase tracking-widest transition-all flex items-center gap-3 group"
                        >
                            <img src="https://www.google.com/s2/favicons?domain=barbofus.com&sz=64" alt="Barbofus" className="w-5 h-5 object-contain opacity-50 group-hover:opacity-100 transition-opacity" />
