                        {/* Footer removed for Ultra-Clean UX 2026 */}
                    </div>
                ))}
            </div>

            {/* View Modal */}
            <Dialog open={!!selectedSkin} onOpenChange={(open) => !open && setSelectedSkin(null)}>
                <DialogContent className="bg-zinc-950/95 backdrop-blur-2xl border-white/10 text-white sm:max-w-xl w-[95vw] h-auto max-h-[90vh] p-0 rounded-[2rem] overflow-hidden shadow-2xl">
                    <DialogTitle className="sr-only">Détails du Skin</DialogTitle>
                    <DialogDescription className="sr-only">Aperçu et métadonnées du skin sélectionné.</DialogDescription>
                    {selectedSkin && (
                        <div className="flex flex-col h-full max-h-[90vh]">
                            {/* Visual Header - Fixed height */}
                            <div className="relative aspect-video bg-black/40 flex items-center justify-center shrink-0 border-b border-white/5">
                                {selectedSkin.thumbnailUrl ? (
                                    <NextImage 
                                        src={selectedSkin.thumbnailUrl} 
                                        alt={selectedSkin.name}
                                        fill
                                        className="object-contain p-6"
                                        unoptimized
                                    />
                                ) : (
                                    <Sparkles className="w-16 h-16 text-zinc-800" />
                                )}
                                
                                <div className="absolute top-4 left-4 flex flex-col gap-2">
                                    <div className="bg-pink-500/20 backdrop-blur-xl px-3 py-1 rounded-full border border-pink-500/30 w-fit">
                                        <span className="text-[10px] font-black text-pink-400 tracking-widest uppercase">
                                            {selectedSkin.provider}
                                        </span>
                                    </div>
                                    {selectedSkin.metadata?.author && (
                                        <div className="bg-zinc-950/80 backdrop-blur-xl px-3 py-1 rounded-xl border border-white/10 w-fit shadow-2xl">
                                            <span className="text-[10px] font-black text-zinc-400 tracking-tighter uppercase">
                                                Créé par <span className="text-white">{selectedSkin.metadata.author}</span>
                                            </span>
                                        </div>
                                    )}
                                </div>
                            </div>
 
                            {/* Scrollable Content Area */}
                            <div className="flex-1 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10 hover:scrollbar-thumb-white/20">
                                <div className="p-6 space-y-8">
                                    <div>
                                        <h2 className="text-2xl font-black text-white uppercase tracking-tight leading-none">
                                            {selectedSkin.name}
                                        </h2>
                                        <div className="flex flex-wrap items-center gap-3 mt-4">
                                            {selectedSkin.metadata?.class && (
                                                <div className="flex items-center gap-2 px-3 py-1.5 bg-pink-500/10 text-pink-400 border border-pink-500/20 rounded-xl shadow-inner">
                                                    <span className="text-[10px] font-black uppercase tracking-widest">
                                                        {(() => {
                                                            const classData = DOFUS_CLASSES.find(c => {
                                                                const match = c.icon.match(/\/(\d+)\.png$/);
                                                                return match && match[1] === String(selectedSkin.metadata.class);
                                                            });
                                                            return classData ? classData.name : selectedSkin.metadata.class;
                                                        })()}
                                                    </span>
                                                </div>
                                            )}
                                            {selectedSkin.metadata?.gender && (
                                                <div className="flex items-center gap-2 px-3 py-1.5 bg-sky-500/10 text-sky-400 border border-sky-500/20 rounded-xl shadow-inner">
                                                    <span className="text-[10px] font-black uppercase tracking-widest">
                                                        {selectedSkin.metadata.gender}
                                                    </span>
                                                </div>
                                            )}
                                            {selectedSkin.metadata?.head && (
                                                <div className="flex items-center gap-2 px-1 py-1 pr-3 bg-zinc-900/80 text-zinc-300 border border-white/5 rounded-xl shadow-inner group/head">
                                                    <div className="w-6 h-6 rounded-lg overflow-hidden bg-black/40 border border-white/5">
                                                        {selectedSkin.metadata.head.startsWith('http') ? (
                                                            <NextImage src={selectedSkin.metadata.head} alt="Head" width={24} height={24} className="object-cover group-hover/head:scale-110 transition-transform" unoptimized />
                                                        ) : (
                                                            <div className="w-full h-full flex items-center justify-center text-[8px] font-bold text-zinc-600">
                                                                #{selectedSkin.metadata.head}
                                                            </div>
                                                        )}
                                                    </div>
                                                    <span className="text-[9px] font-black uppercase tracking-widest opacity-70">
                                                        Visage {selectedSkin.metadata.head.startsWith('http') ? "" : selectedSkin.metadata.head}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Colors Section */}
                                    {selectedSkin.colors && Object.keys(selectedSkin.colors).length > 0 && (
                                        <div className="space-y-4">
                                            <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.3em] flex items-center gap-2">
                                                <div className="w-1 h-1 rounded-full bg-pink-500" />
                                                Couleurs du Skin
                                            </h3>
                                            <div className="grid grid-cols-2 gap-2">
                                                {Object.entries(selectedSkin.colors).map(([label, hex]) => (
                                                    <div key={label} className="bg-white/5 border border-white/5 rounded-xl p-2 flex items-center gap-3 hover:bg-white/10 transition-colors">
                                                        <div 
                                                            className="w-8 h-8 rounded-lg shadow-inner border border-white/10 shrink-0"
                                                            style={{ backgroundColor: hex as string }}
                                                        />
                                                        <div className="min-w-0">
                                                            <p className="text-[9px] font-bold text-zinc-500 truncate uppercase tracking-tighter">{label}</p>
                                                            <p className="text-[11px] font-black text-white uppercase font-mono">{hex as string}</p>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Equipment Section */}
                                    {selectedSkin.equipment && Array.isArray(selectedSkin.equipment) && selectedSkin.equipment.length > 0 && (
                                        <div className="space-y-4 pb-4">
                                            <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.3em] flex items-center gap-2">
                                                <div className="w-1 h-1 rounded-full bg-emerald-500" />
                                                Équipements
                                            </h3>
                                            <div className="grid grid-cols-1 gap-2">
                                                {selectedSkin.equipment.map((item: any, idx: number) => (
                                                    <div key={idx} className="bg-zinc-900/40 border border-white/5 rounded-xl p-2.5 flex items-center justify-between group/item hover:bg-zinc-900/80 transition-all">
                                                        <div className="flex items-center gap-3">
                                                            <div className="w-10 h-10 bg-black/40 rounded-lg flex items-center justify-center p-1 border border-white/5">
                                                                {item.icon ? (
                                                                    <NextImage src={item.icon} alt={item.name} width={32} height={32} unoptimized />
                                                                ) : (
                                                                    <Sparkles className="w-5 h-5 text-zinc-800" />
                                                                )}
                                                            </div>
                                                            <div>
                                                                <p className="text-[12px] font-bold text-white group-hover/item:text-emerald-400 transition-colors leading-tight">{item.name}</p>
                                                                <p className="text-[9px] text-zinc-500 font-medium uppercase tracking-wider">{item.type}</p>
                                                            </div>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Sticky Footer Actions */}
                            <div className="p-4 bg-zinc-900/80 backdrop-blur-lg border-t border-white/5 grid grid-cols-2 gap-3 shrink-0">
                                <Button 
                                    asChild
                                    variant="outline" 
                                    className="rounded-xl border-white/5 bg-white/5 hover:bg-white/10 hover:border-white/10 h-12 text-xs"
                                >
                                    <a href={selectedSkin.url} target="_blank" rel="noopener noreferrer" className="gap-2">
                                        <ExternalLink className="w-4 h-4" />
                                        Voir plus
                                    </a>
                                </Button>
                                <Button 
                                    variant="outline" 
                                    className="rounded-xl border-white/5 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white h-12 text-xs"
                                    onClick={() => handleCopyLink(selectedSkin.url)}
                                >
                                    <Copy className="w-4 h-4 mr-2" />
                                    Copier lien
                                </Button>
                                <Button 
                                    variant="outline" 
                                    className="rounded-xl border-indigo-500/30 bg-indigo-500/5 text-indigo-400 hover:bg-indigo-500 hover:text-white h-12 text-xs font-black uppercase tracking-widest"
                                    onClick={async () => {
                                        const res = await shareGalleryItemOnDiscord(guildId, selectedSkin.id, "SKIN", profileId);
                                        if (res.success) toast.success("Partagé sur Discord !");
                                        else toast.error(res.error || "Erreur lors du partage");
                                    }}
                                >
                                    <Megaphone className="w-4 h-4 mr-2" />
                                    Partager Discord
                                </Button>
                                <Button 
                                    variant="sigil" 
                                    className="rounded-xl h-12 text-xs font-black uppercase tracking-widest"
                                    onClick={() => setSelectedSkin(null)}
                                >
                                    Fermer
                                </Button>
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Modal */}
            <Dialog open={isDeleteOpen} onOpenChange={setIsDeleteOpen}>
                <DialogContent className="bg-zinc-950/95 backdrop-blur-2xl border-2 border-red-500/20 text-white sm:max-w-md p-0 rounded-[2.5rem] overflow-hidden shadow-[0_0_50px_-12px_rgba(239,68,68,0.3)]">
                    <DialogTitle className="sr-only">Confirmer la suppression</DialogTitle>
                    <DialogDescription className="sr-only">Cette action est irréversible.</DialogDescription>
                    
                    <div className="p-8 flex flex-col items-center text-center">
                        <div className="w-20 h-20 bg-red-500/10 rounded-3xl flex items-center justify-center border border-red-500/20 mb-6 group">
                            <Trash2 className="w-10 h-10 text-red-500 group-hover:scale-110 transition-transform duration-500" />
                        </div>
                        
                        <h3 className="text-xl font-black uppercase tracking-tight mb-2">Supprimer ce skin ?</h3>
                        <p className="text-zinc-500 text-sm leading-relaxed">
                            Êtes-vous sûr de vouloir retirer ce chef-d'œuvre de votre bibliothèque ? Cette action est irréversible.
                        </p>
                    </div>

                    <div className="p-4 bg-red-500/5 border-t border-white/5 grid grid-cols-2 gap-3">
                        <Button 
                            variant="ghost" 
                            onClick={() => setIsDeleteOpen(false)}
                            className="rounded-2xl hover:bg-white/5 text-zinc-400 font-bold uppercase tracking-widest text-[10px]"
                        >
                            Annuler
                        </Button>
                        <Button 
                            variant="destructive"
                            onClick={handleDeleteSkin}
                            disabled={isSubmitting}
                            className="rounded-2xl bg-red-500 hover:bg-red-600 font-black uppercase tracking-widest text-[10px] shadow-lg shadow-red-500/20 active:scale-95 transition-all"
                        >
                            {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : "Oui, Supprimer"}
                        </Button>
                    </div>
                </DialogContent>
            </Dialog>

            {/* Edit Name Modal */}
            <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
                <DialogContent className="bg-zinc-950 border-white/10 text-white sm:max-w-md">
                    <DialogHeader>
                        <DialogTitle>Renommer votre skin</DialogTitle>
                        <DialogDescription className="text-zinc-400">
                            Donnez un nom unique à votre création pour la galerie.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                        <div className="space-y-2">
                            <Label htmlFor="edit-name">Nom du Look</Label>
                            <Input
                                id="edit-name"
                                value={editedName}
                                onChange={(e) => setEditedName(e.target.value)}
                                className="bg-zinc-900 border-white/10 focus:border-amber-500/50 transition-colors"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="edit-url">Lien du Skin (Barbofus / Manga)</Label>
                            <Input
                                id="edit-url"
                                value={editedUrl}
                                onChange={(e) => setEditedUrl(e.target.value)}
                                className="bg-zinc-900 border-white/10 focus:border-amber-500/50 transition-colors"
                                placeholder="https://..."
                            />
                            {editedUrl !== skinToEdit?.url && (
                                <p className="text-[10px] text-amber-500/80 font-medium italic">
                                    Note : Changer le lien actualisera automatiquement la miniature et les détails.
                                </p>
                            )}
                        </div>
                    </div>
                    <DialogFooter className="gap-2 sm:gap-0">
                        <Button 
                            variant="ghost" 
                            onClick={() => setIsEditOpen(false)}
                            disabled={isSubmitting}
                            className="rounded-xl hover:bg-white/5 text-zinc-400 hover:text-white transition-all"
                        >
                            Annuler
                        </Button>
                        <Button 
                            variant="sigil" 
                            onClick={handleUpdateSkin}
                            disabled={isSubmitting || !editedName.trim() || !editedUrl.trim() || (editedName === skinToEdit?.name && editedUrl === skinToEdit?.url)}
                            className="rounded-xl bg-amber-500 hover:bg-amber-600 text-white shadow-lg shadow-amber-500/20 active:scale-95 transition-all font-black uppercase tracking-widest text-[10px]"
                        >
                            {isSubmitting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : "Enregistrer"}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Trophy, Upload, Loader2, CheckCircle2, AlertCircle, Sparkles, Clock } from "lucide-react";
import { syncMemberSuccessPoints, refreshUserSuccessPoints, getLadderPreview } from "@/server/actions/profile-actions";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import Link from "next/link";
import { cancelAchievementSubmission } from "@/server/actions/achievement-actions";

interface SuccessSyncProps {
    guildId: string;
    pseudoDofus?: string | null;
    dofusServerId?: string | null;
    successPoints?: number | null;
    lastUpdate?: Date | null;
    readOnly?: boolean;
    onTabChange?: (tab: string) => void;
    onSuccess?: (points: number) => void;
    pendingSubmission?: {
        id: string;
        points: number;
        ocrScore: number;
        createdAt: Date;
    } | null;
    onCancel?: () => void;
    targetUserId?: string;
    canSyncLadder?: boolean;
    canManualSync?: boolean;
    isSuperAdmin?: boolean;
    isAdmin?: boolean;
}

import { ALL_DOFUS_SERVERS, DOFUS_UNITY_SERVERS } from "@/lib/presentation-constants";
import { getClass } from "@/lib/dofus-assets";
import { ExternalLink, Info, MapPin, MousePointer2, UserSearch, RefreshCw, Edit2 } from "lucide-react";

export function SuccessSync({
    guildId,
    pseudoDofus,
    dofusServerId,
    successPoints = 0,
    lastUpdate,
    readOnly = false,
    onTabChange,
    onSuccess,
    pendingSubmission,
    onCancel,
    targetUserId,
    canSyncLadder = false,
    canManualSync = true,
    isSuperAdmin = false,
    isAdmin = false
}: SuccessSyncProps) {
    const [isUploading, setIsUploading] = useState(false);
    const [dragActive, setDragActive] = useState(false);
    const [lastScanResult, setLastScanResult] = useState<{ points?: number, error?: string, pending?: boolean, confidence?: number, debugImage?: string } | null>(
        pendingSubmission ? { points: pendingSubmission.points, pending: true, confidence: pendingSubmission.ocrScore } : null
    );

    const [previewData, setPreviewData] = useState<{ 
        points: number, 
        level: number, 
        className?: string, 
        rank?: number,
        guildRank?: number
    } | null>(null);
    const [loadingPreview, setLoadingPreview] = useState(false);
    const [previewFetched, setPreviewFetched] = useState(false);

    useEffect(() => {
        if (!pseudoDofus || previewFetched || readOnly) return;
        let isMounted = true;
        
        const fetchPreview = async () => {
            setLoadingPreview(true);
            const res = await getLadderPreview(guildId);
            if (isMounted) {
                if (res.success && res.data) {
                    setPreviewData(res.data);
                }
                setPreviewFetched(true);
                setLoadingPreview(false);
            }
        };

        fetchPreview();
        return () => { isMounted = false; };
    }, [pseudoDofus, previewFetched, readOnly, guildId]);

    // Use provided server ID from guild config or fallback to Draconiros (295)
    const serverId = dofusServerId || "295";
    const serverName = [...Object.values(DOFUS_UNITY_SERVERS).flat()].find(s => s.id.toString() === serverId)?.name || "Draconiros";

    const ladderUrl = pseudoDofus ? `https://www.dofus.com/fr/mmorpg/communaute/ladder/succes?server_id=${serverId}&name=${pseudoDofus}#jt_list` : null;

    const handleCancel = async () => {
        setIsUploading(true);
        const res = await cancelAchievementSubmission(guildId, targetUserId);
        setIsUploading(false);
        if (res.success) {
            toast.success("Demande annulée");
            setLastScanResult(null);
            onCancel?.();
        } else {
            toast.error(res.error || "Erreur lors de l'annulation");
        }
    };

    const handleLadderSync = async () => {
        if (isUploading || lastScanResult?.pending) return;

        setIsUploading(true);
        try {
            const res = await refreshUserSuccessPoints(guildId);
            if (res.success && res.data) {
                toast.success(`Succès synchronisés via Ladder : ${res.data.points} points ! (Niv. ${res.data.level})`);
                setLastScanResult({ points: res.data.points });
                onSuccess?.(res.data.points);
            } else {
                toast.error(res.error || "Échec de la synchronisation via Ladder.");
            }
        } catch (err) {
            toast.error("Une erreur est survenue lors de la synchronisation.");
        } finally {
            setIsUploading(false);
        }
    };

    const handleFile = async (file: File) => {
        if (lastScanResult?.pending) {
            toast.error("Vous avez déjà une demande en cours.");
            return;
        }
        if (!file.type.startsWith("image/")) {
            toast.error("Veuillez sélectionner une image.");
            return;
        }

        // 🛡️ NSFW Safety Check
        const { analyzeImageSafety } = await import("@/lib/safety-client");
        const safety = await analyzeImageSafety(file);
        if (!safety.isSafe) {
            toast.error(safety.reason || "Contenu inapproprié détecté. L'image a été bloquée.");
            return;
        }

        setIsUploading(true);
        const reader = new FileReader();
        reader.readAsDataURL(file);

        reader.onload = async () => {
            // const base64 = reader.result as string; // OLD
            try {
                // NEW: Compression
                const { compressImage } = await import("@/lib/image-compression");
                const compressedBase64 = await compressImage(file, {
                    maxWidth: 1920,
                    maxHeight: 1080,
                    quality: 0.8
                });

                const res = await syncMemberSuccessPoints({
                    guildId,
                    imageData: compressedBase64,
                    targetUserId,
                });

                if (res.success) {
                    if (res.data?.pending) {
                        const conf = Math.round(res.data.confidence || 0);
                        toast.info("Votre capture est en cours de vérification par le staff.");
                        setLastScanResult({
                            points: res.data?.points,
                            pending: true,
                            confidence: res.data?.confidence,
                            debugImage: res.data?.debugImage
                        });
                    } else {
                        toast.success(`Succès synchronisés : ${res.data?.points} points !`);
                        setLastScanResult({ points: res.data?.points, debugImage: res.data?.debugImage });
                        if (res.data?.points) {
                            onSuccess?.(res.data.points);
                        }
                    }
                } else {
                    toast.error(res.error || "Échec de la synchronisation.");
                    setLastScanResult({ error: res.error });
                }
            } catch (err) {
                toast.error("Une erreur est survenue lors de l'envoi.");
            } finally {
                setIsUploading(false);
                setDragActive(false);
            }
        };
    };

    const handleBrowseClick = () => {
        const fileInput = document.getElementById("success-upload-input");
        if (fileInput) fileInput.click();
    };


    const onDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setDragActive(true);
    };

    const onDragLeave = () => {
        setDragActive(false);
    };

    const onDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            handleFile(e.dataTransfer.files[0]);
        }
    };

    // START: Clipboard Paste Support
    useEffect(() => {
        if (readOnly) return;

        const handlePaste = (e: ClipboardEvent) => {
            if (e.clipboardData && e.clipboardData.files.length > 0) {
                const file = e.clipboardData.files[0];
                if (file.type.startsWith("image/")) {
                    e.preventDefault();
                    handleFile(file);
                    toast.info("Image collée depuis le presse-papier ! 📋");
                }
            }
        };

        window.addEventListener("paste", handlePaste);
        return () => window.removeEventListener("paste", handlePaste);
    }, [readOnly, isUploading, lastScanResult]); // Re-bind if these change, though handleFile uses them
    // END: Clipboard Paste Support

    if (readOnly && !successPoints) return null;

    return (
        <Card className="overflow-hidden border-white/10 bg-black/20 backdrop-blur-md">
            <CardHeader className="pb-2">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <div className="p-2 rounded-lg bg-amber-500/20 text-amber-400">
                            <Trophy className="w-5 h-5" />
                        </div>
                        <div>
                            <CardTitle className="text-lg">Points de Succès</CardTitle>
                            <CardDescription>Synchronisation des points</CardDescription>
                        </div>
                    </div>
                    {successPoints ? (
                        <div className="text-2xl font-bold text-amber-400">
                            {successPoints.toLocaleString()}
                        </div>
                    ) : null}
                </div>
            </CardHeader>
            <CardContent className="space-y-4">
                {!readOnly && canManualSync && (
                    <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-500">
                        <div
                            onDragOver={onDragOver}
                            onDragLeave={onDragLeave}
                            onDrop={onDrop}
                            className={cn(
                                "relative group flex flex-col items-center justify-center gap-3 p-6 border-2 border-dashed rounded-xl transition-all",
                                dragActive ? "border-amber-500 bg-amber-500/10" : "border-white/10 hover:border-white/20 hover:bg-white/5",
                                (isUploading || lastScanResult?.pending) && "opacity-50 pointer-events-none cursor-not-allowed"
                            )}
                        >
                            {lastScanResult?.pending ? (
                                <div className="flex flex-col items-center gap-2 p-4 text-center">
                                    <Clock className="w-8 h-8 text-blue-400 animate-pulse" />
                                    <p className="text-sm font-bold text-blue-200 uppercase">Demande en attente</p>
                                    <p className="text-xs text-blue-300/60 max-w-[200px]">Une capture est déjà en cours de validation par le staff.</p>
                                </div>
                            ) : isUploading ? (
                                <div className="flex flex-col items-center gap-2 animate-pulse">
                                    <Loader2 className="w-8 h-8 text-amber-500 animate-spin" />
                                    <span className="text-sm font-medium text-amber-200">Synchronisation en cours...</span>
                                </div>
                            ) : (
                                <>
                                    <div className="p-3 rounded-full bg-white/5 group-hover:scale-110 transition-transform">
                                        <Upload className="w-6 h-6 text-white/40 group-hover:text-amber-400" />
                                    </div>
                                    <div className="text-center space-y-1">
                                        <p className="text-base font-bold text-white/90">Déposez votre capture</p>
                                        <p className="text-sm text-white/40">
                                            coller (CTRL+V) ou{" "}
                                            <button
                                                type="button"
                                                onClick={handleBrowseClick}
                                                className="text-amber-400 hover:text-amber-300 font-medium hover:underline focus:outline-none"
                                            >
                                                cliquez pour sélectionner
                                            </button>
                                        </p>
                                    </div>
                                    <input
                                        id="success-upload-input"
                                        type="file"
                                        className="hidden"
                                        onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
                                        accept="image/*"
                                    />
                                </>
                            )}
                        </div>

                        {/* Instructional Tip with Full Examples */}
                        <div className="p-5 rounded-2xl bg-zinc-900/50 border border-white/5 space-y-4">
                            <div className="flex items-center gap-2 text-amber-400">
                                <div className="p-2 rounded-lg bg-amber-500/10">
                                    <MousePointer2 className="w-5 h-5" />
                                </div>
                                <span className="text-sm font-bold uppercase tracking-wider">Bien cadrer la capture</span>
                            </div>
                            <p className="text-sm text-zinc-300 leading-relaxed font-medium">
                                Ne prenez pas tout l'écran ! Utilisez un outil de capture d'écran (Snipping Tool, Greenshot, etc) pour détourer uniquement la zone avec vos points. Si vous incluez la barre de progression à droite de vos points, l'IA sera encore plus précise.
                            </p>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-xl mx-auto">
                                <div className="rounded-xl overflow-hidden border border-white/10 bg-black/40 flex items-center justify-center p-2">
                                    <img
                                        src="/assets/ladder/exemple-succes.png"
                                        alt="Exemple valide 1"
                                        className="w-full h-auto rounded-lg"
                                    />
                                </div>
                                <div className="rounded-xl overflow-hidden border border-white/10 bg-black/40 flex items-center justify-center p-2">
                                    <img
                                        src="/assets/ladder/exemple4.png"
                                        alt="Exemple valide 2"
                                        className="w-full h-auto rounded-lg"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Pseudo Configuration Instruction */}
                        {!pseudoDofus && (
                            <div className="p-5 rounded-2xl bg-amber-500/5 border border-amber-500/10 flex items-start gap-5">
                                <div className="p-3 rounded-2xl bg-amber-500/10 text-amber-400 shrink-0">
                                    <UserSearch className="w-6 h-6" />
                                </div>
                                <div className="space-y-2">
                                    <p className="text-base font-bold text-amber-200 uppercase tracking-tight">Pseudo Dofus requis</p>
                                    <p className="text-sm text-amber-400/80 leading-relaxed font-medium">
                                        Pour activer le lien direct vers le ladder officiel, rendez-vous dans l'onglet{" "}
                                        <button
                                            onClick={() => onTabChange?.('overview')}
                                            className="text-amber-200 underline decoration-amber-200/30 underline-offset-4 hover:text-white transition-colors cursor-pointer"
                                        >
                                            Général
                                        </button>
                                        {" "}et modifiez votre bloc{" "}
                                        <button
                                            onClick={() => onTabChange?.('overview')}
                                            className="text-amber-200 underline decoration-amber-200/30 underline-offset-4 hover:text-white transition-colors cursor-pointer text-left"
                                        >
                                            Identité de Combat
                                        </button>
                                        {" "}pour y ajouter votre pseudo exact.
                                    </p>
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {/* Ladder Sync Button (if enabled) */}
                {!readOnly && canSyncLadder && (
                    <div className="pt-2 animate-in fade-in slide-in-from-bottom-2 duration-700">
                        <Button
                            onClick={handleLadderSync}
                            disabled={isUploading || !pseudoDofus || (lastScanResult?.pending ?? false)}
                            className="w-full h-12 bg-amber-500 hover:bg-amber-600 text-black font-black uppercase tracking-widest shadow-[0_0_20px_rgba(245,158,11,0.3)] transition-all active:scale-95 disabled:opacity-50 group gap-3"
                        >
                            {isUploading ? (
                                <Loader2 className="w-5 h-5 animate-spin" />
                            ) : (
                                <RefreshCw className="w-5 h-5 group-hover:rotate-180 transition-transform duration-500" />
                            )}
                            <span>Synchroniser via Ladder</span>
                        </Button>
                        {!pseudoDofus && (
                            <p className="text-[10px] text-zinc-500 text-center mt-2 italic font-medium">
                                Le pseudo Dofus est requis pour la synchronisation automatique.
                            </p>
                        )}
                    </div>
                )}

                {lastScanResult?.pending && (
                    <div className="relative overflow-hidden p-5 rounded-2xl bg-blue-500/10 text-blue-300 border border-blue-500/20 animate-in fade-in zoom-in-95 duration-500">
                        {/* Status bar background */}
                        <div className="absolute top-0 left-0 h-1 bg-blue-500/10 w-full" />
                        <div
                            className="absolute top-0 left-0 h-1 bg-blue-400 shadow-[0_0_10px_rgba(96,165,250,0.5)] transition-all duration-1000"
                            style={{ width: `${Math.round(lastScanResult.confidence || 0)}%` }}
                        />

                        <div className="flex flex-col gap-4 relative z-10">
                            <div className="flex items-start gap-3">
                                <Clock className="w-5 h-5 mt-1 shrink-0 text-blue-400" />
                                <div className="flex-1 space-y-1">
                                    <p className="text-xs leading-relaxed opacity-80 font-medium">
                                        Votre capture est en cours de vérification par le staff.
                                    </p>
                                </div>
                            </div>

                            <div className="flex items-center justify-end gap-3 pt-2">
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-8 text-[10px] font-bold text-white/40 hover:text-red-400 hover:bg-red-500/10"
                                    onClick={handleCancel}
                                    disabled={isUploading}
                                >
                                    Annuler la demande
                                </Button>
                                <Button
                                    className="h-8 text-[10px] font-bold bg-blue-500/20 hover:bg-blue-500/30 text-blue-200 border border-blue-500/30 pointer-events-none"
                                >
                                    Attente Staff
                                </Button>
                            </div>
                        </div>
                    </div>
                )}

                {lastUpdate && (
                    <div className="flex items-center justify-between text-sm text-white/50 bg-white/5 p-3 rounded-xl border border-white/5">
                        <span className="font-medium">Dernière synchronisation</span>
                        <span className="font-bold text-white/90">{new Date(lastUpdate).toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
                    </div>
                )}

                {/* Ladder Link Option */}
                {!readOnly && (
                    <div className="pt-2 border-t border-white/5 space-y-3">
                        <div className="flex flex-col gap-4 bg-white/5 p-4 rounded-xl border border-white/10 hover:border-amber-500/30 transition-colors">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="p-2.5 rounded-xl bg-blue-500/20 text-blue-400 border border-blue-500/10 shadow-lg shadow-blue-500/5">
                                        <ExternalLink className="w-5 h-5" />
                                    </div>
                                    <div className="flex flex-col gap-0.5">
                                        <div className="flex items-center gap-2.5">
                                            <span className="text-base font-bold text-white tracking-tight">Lien Ladder Officiel</span>
                                            <span className="px-2 py-0.5 rounded-md bg-zinc-800 text-[11px] font-black text-zinc-300 border border-white/10 uppercase tracking-wider">
                                                {serverName}
                                            </span>
                                        </div>
                                        <span className="text-sm text-zinc-400 font-medium">Consulter vos points en temps réel sur Ankama</span>
                                    </div>
                                </div>
                                {pseudoDofus ? (
                                    <Button
                                        variant="outline"
                                        size="default"
                                        className="h-10 border-white/10 hover:bg-white/10 text-sm font-bold min-w-[100px]"
                                        asChild
                                    >
                                        <a href={ladderUrl!} target="_blank" rel="noopener noreferrer">
                                            Ouvrir
                                        </a>
                                    </Button>
                                ) : (
                                    <span className="text-[10px] text-white/20 italic">Pseudo requis</span>
                                )}
                            </div>

                            {pseudoDofus && (
                                <div className="px-3 py-2 bg-black/60 rounded-lg border border-white/10 overflow-hidden transition-all hover:border-white/20">
                                    <p className="text-[11px] text-zinc-400 truncate font-mono select-all leading-none">
                                        {ladderUrl}
                                    </p>
                                </div>
                            )}

                            {pseudoDofus && (
                                <div className="mt-2 p-3 rounded-xl border border-white/5 bg-zinc-950/50 flex flex-col gap-2">
                                    <div className="flex justify-between items-center text-xs font-semibold uppercase text-zinc-500 tracking-wider">
                                        <div className="flex items-center gap-2">
                                            <span>Aperçu en Direct</span>
                                            {loadingPreview && <Loader2 className="w-3 h-3 animate-spin" />}
                                        </div>
                                        
                                        {!readOnly && (
                                            <button
                                                onClick={() => onTabChange?.('overview')}
                                                className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest text-zinc-400 hover:text-amber-400 transition-all bg-white/5 hover:bg-amber-500/10 px-3 py-1.5 rounded-xl border border-white/5 hover:border-amber-500/30 shadow-lg"
                                                title="Modifier l'identité de combat"
                                            >
                                                <Edit2 className="w-3 h-3" strokeWidth={2.5} />
                                                <span>Éditer</span>
                                            </button>
                                        )}
                                    </div>
                                    {loadingPreview && !previewData && (
                                        <div className="h-10 flex items-center justify-center">
                                            <span className="text-xs text-zinc-500 font-medium">Recherche du personnage...</span>
                                        </div>
                                    )}
                                    {!loadingPreview && !previewData && previewFetched && (
                                        <div className="h-10 flex flex-col items-center justify-center text-zinc-500">
                                            <span className="text-xs font-medium">Personnage introuvable ou erreur.</span>
                                            <span className="text-[10px] italic">Vérifiez les majuscules et le serveur.</span>
                                        </div>
                                    )}
                                    {previewData && (() => {
                                        const dofusClass = previewData.className ? getClass(previewData.className.trim()) : null;
                                        return (
                                        <div className="flex items-center justify-between mt-1 px-1">
                                            <div className="flex items-center gap-3">
                                                {/* Class Icon */}
                                                <div className="relative group/icon">
                                                    <div className="absolute inset-0 bg-white/10 blur-md rounded-full scale-0 group-hover/icon:scale-110 transition-transform duration-500" />
                                                    {dofusClass?.icon ? (
                                                        <img 
                                                            src={dofusClass.icon} 
                                                            alt={previewData.className} 
                                                            className="w-10 h-10 object-contain relative z-10 drop-shadow-[0_0_8px_rgba(0,0,0,0.5)]" 
                                                        />
                                                    ) : (
                                                        <div className="w-10 h-10 rounded-full bg-zinc-800 flex items-center justify-center border border-white/5 relative z-10">
                                                            <UserSearch className="w-5 h-5 text-zinc-600" />
                                                        </div>
                                                    )}
                                                </div>

                                                <div className="flex flex-col">
                                                    <div className="flex items-center gap-2">
                                                        <span className="text-sm font-black text-amber-50">{pseudoDofus}</span>
                                                    </div>
                                                    <span className={cn(
                                                        "text-[10px] font-medium transition-colors flex items-center gap-1",
                                                        dofusClass ? "text-amber-400/80" : "text-zinc-500"
                                                    )}>
                                                        {dofusClass?.name || previewData.className || "Classe Inconnue"} • {previewData.level > 200 ? (
                                                            <span className="font-bold text-sky-400 drop-shadow-[0_0_8px_rgba(56,189,248,0.4)]">
                                                                Ω {previewData.level - 200}
                                                            </span>
                                                        ) : (
                                                            `Niveau ${previewData.level}`
                                                        )}
                                                    </span>
                                                </div>
                                            </div>
                                            
                                            {/* Visual Connector with Centered Server */}
                                            <div className="flex-1 mx-6 flex items-center justify-center gap-3">
                                                <div className="border-b border-dashed border-white/10 flex-1" />
                                                <span className="font-mono text-[9px] font-bold text-zinc-500 uppercase tracking-widest text-center">
                                                    SERVEUR {serverName}
                                                </span>
                                                <div className="border-b border-dashed border-white/10 flex-1" />
                                            </div>

                                            <div className="flex items-center gap-6 text-right shrink-0">
                                                <div className="flex flex-col items-end">
                                                    <span className="text-[10px] uppercase font-bold text-zinc-500 leading-none mb-1">Points</span>
                                                    <span className="text-sm font-black text-amber-500 tabular-nums">{previewData.points.toLocaleString()}</span>
                                                </div>
                                                
                                                <div className="flex gap-3">
                                                    <div className="flex flex-col items-end border-l border-white/5 pl-3">
                                                        <span className="text-[9px] uppercase font-bold text-zinc-600 leading-none mb-1">Monde</span>
                                                        <span className="text-[11px] font-black text-white/90 tabular-nums">
                                                            {previewData.rank ? `#${previewData.rank.toLocaleString()}` : '—'}
                                                        </span>
                                                    </div>
                                                    <div className="flex flex-col items-end border-l border-white/5 pl-3">
                                                        <span className="text-[9px] uppercase font-bold text-zinc-600 leading-none mb-1">Guilde</span>
                                                        <span className={cn(
                                                            "text-sm font-black tabular-nums",
                                                            previewData.guildRank === 1 ? "text-yellow-400 drop-shadow-[0_0_8px_rgba(250,204,21,0.4)]" : "text-white/90"
                                                        )}>
                                                            #{previewData.guildRank || '—'}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        );
                                    })()}
                                </div>
                            )}
                        </div>

                        {!pseudoDofus && (
                            <div className="p-4 rounded-xl border border-amber-500/20 bg-amber-500/10 flex flex-col sm:flex-row items-center justify-between gap-4">
                                <div className="flex items-center gap-3 text-amber-400">
                                    <Info className="w-5 h-5 shrink-0" />
                                    <div className="space-y-0.5">
                                        <p className="text-sm font-bold">Pseudo Dofus requis</p>
                                        <p className="text-xs text-amber-400/80">Configurez votre identité pour débloquer le lien officiel.</p>
                                    </div>
                                </div>
                                <Button 
                                    onClick={() => onTabChange?.('overview')}
                                    className="bg-amber-500 hover:bg-amber-600 text-black font-black uppercase text-xs w-full sm:w-auto shadow-[0_0_15px_rgba(245,158,11,0.2)]"
                                >
                                    Configurer
                                </Button>
                            </div>
                        )}
                    </div>
                )}

                {/* Link to Guild Ladder Module */}
                <div className="pt-4 mt-2 border-t border-white/5">
                    <Button
                        asChild
                        variant="sigil"
                        className="w-full h-11"
                    >
                        <Link href={`/dashboard/${guildId}/ladder`}>
                            <Trophy className="w-5 h-5" />
                            <span>VOIR LE CLASSEMENT DE GUILDE</span>
                        </Link>
                    </Button>
                </div>

                {!successPoints && !readOnly && (
                    <div className="flex items-start gap-3 p-4 rounded-xl bg-blue-500/10 text-blue-300 border border-blue-500/20">
                        <AlertCircle className="w-5 h-5 mt-0.5 shrink-0" />
                        <div className="space-y-1">
                            <p className="text-sm font-bold text-blue-200">Ladder vide</p>
                            <p className="text-sm leading-relaxed opacity-80">Synchronisez vos points pour apparaître dans le classement mondial et de guilde.</p>
                        </div>
                    </div>
                )}
            </CardContent>
        </Card >
    );
}

"use client";

import { useState, useEffect } from "react";
import {
    AlertTriangle,
    Zap,
    UserMinus,
    Trash2,
    ShieldAlert,
    Info,
    Bell,
    MessageSquare,
    Swords,
    Trophy,
    Calendar,
    Target,
    Flame,
    PieChart,
    ShieldCheck
} from "lucide-react";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
    AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import { archiveProfile, handleGdprDeletionRequest } from "@/server/actions/lifecycle-actions";
import { useRouter } from "next/navigation";
import { signOut } from "next-auth/react";
import { DiscordOwnershipModal } from "./discord-ownership-modal";
import { updateNotificationPrefs } from "@/server/actions/profile-actions";

interface NotificationPrefs {
    missions: boolean;
    songes: boolean;
    donjons: boolean;
    events: boolean;
    ladder: boolean;
    polls: boolean;
    admin_validations: boolean;
    ocre: boolean;
}

interface UserSettingsProps {
    guildId: string;
    guildName: string;
    profileId: string;
    notificationPrefs?: NotificationPrefs | null;
    onNotificationPrefsSave?: (prefs: any) => void;
    isAdmin: boolean;
    targetUserId?: string;
    showPresence: boolean;
    onPresenceToggle: (enabled: boolean) => void;
}

export function UserSettings({
    guildId,
    guildName,
    profileId,
    notificationPrefs,
    onNotificationPrefsSave,
    isAdmin,
    targetUserId,
    showPresence,
    onPresenceToggle
}: UserSettingsProps) {
    const [performanceMode, setPerformanceMode] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);
    const [showOwnershipModal, setShowOwnershipModal] = useState(false);
    const [loading, setLoading] = useState(false); // Added loading state
    const router = useRouter();

    // Default values: true if not specified
    const prefs = {
        missions: notificationPrefs?.missions ?? true,
        songes: notificationPrefs?.songes ?? true,
        donjons: notificationPrefs?.donjons ?? true,
        events: notificationPrefs?.events ?? true,
        ladder: notificationPrefs?.ladder ?? true,
        polls: notificationPrefs?.polls ?? true,
        admin_validations: notificationPrefs?.admin_validations ?? true,
        ocre: notificationPrefs?.ocre ?? true,
    };

    const handleUpdatePrefs = async (newPrefs: Partial<NotificationPrefs>) => { // Renamed and updated signature
        setLoading(true);
        onNotificationPrefsSave?.(newPrefs);

        const res = await updateNotificationPrefs({
            guildId,
            prefs: newPrefs,
            targetUserId
        });

        if (res.success) {
            toast.success("Préférences enregistrées");
        } else {
            toast.error(res.error || "Erreur");
            // Rollback on fail
            onNotificationPrefsSave?.(Object.fromEntries(
                Object.entries(newPrefs).map(([key, value]) => [key, !value])
            ));
        }
        setLoading(false);
    };

    // Load performance mode from localStorage
    useEffect(() => {
        const saved = localStorage.getItem("sigilos-performance-mode") === "true";
        setPerformanceMode(saved);
        if (saved) document.documentElement.classList.add("reduce-motion");
    }, []);

    const togglePerformanceMode = (enabled: boolean) => {
        setPerformanceMode(enabled);
        localStorage.setItem("sigilos-performance-mode", String(enabled));

        if (enabled) {
            document.documentElement.classList.add("reduce-motion");
            toast.info("Mode Performance activé : Animations réduites.");
        } else {
            document.documentElement.classList.remove("reduce-motion");
            toast.info("Mode Performance désactivé.");
        }
    };

    const [archiveDuration, setArchiveDuration] = useState<number>(3); // Default 3 months

    const handleLeaveGuild = async () => {
        setIsDeleting(true);
        try {
            const res = await archiveProfile(guildId, undefined, archiveDuration);
            if (res.success) {
                toast.success(`Vous avez archivé votre profil sur ${guildName} pour ${archiveDuration} mois.`);
                router.push("/dashboard");
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        } catch (error) {
            toast.error("Erreur de communication avec le serveur");
        } finally {
            setIsDeleting(false);
        }
    };

    const handleDeleteAccount = async () => {
        setIsDeleting(true);
        try {
            const res = await handleGdprDeletionRequest();
            if (res.success) {
                toast.success("Compte supprimé définitivement. Déconnexion...");
                await signOut({ callbackUrl: "/" });
            } else {
                const isOwnershipError = res.error?.toLowerCase().includes("proprié");
                if (isOwnershipError) {
                    setShowOwnershipModal(true);
                } else {
                    toast.error(res.error || "Une erreur est survenue");
                }
            }
        } catch (error) {
            toast.error("Erreur de communication avec le serveur");
        } finally {
            setIsDeleting(false);
        }
    };

    return (
        <div className="flex flex-col gap-8">
            {/* TOP ROW: Performance & Notifications */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 items-start">
                {/* PERFORMANCE SECTION */}
                <div className="bg-black/40 backdrop-blur-md border border-white/10 rounded-3xl p-6 shadow-xl space-y-6">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-amber-500/10 rounded-xl">
                            <Zap className="w-5 h-5 text-amber-400" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-white">Interface & Performance</h3>
                            <p className="text-sm text-zinc-400">Optimisez votre lecture</p>
                        </div>
                    </div>

                    <div className="space-y-4 pt-4 border-t border-white/5">
                        <div className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 group hover:border-amber-500/30 transition-all">
                            <div className="space-y-1">
                                <Label htmlFor="perf-mode" className="text-sm font-medium text-zinc-200 group-hover:text-white transition-colors">
                                    Mode Performance
                                </Label>
                                <p className="text-[10px] text-zinc-500 leading-tight">
                                    Réduit les animations et flous.
                                </p>
                            </div>
                            <Switch
                                id="perf-mode"
                                checked={performanceMode}
                                onCheckedChange={togglePerformanceMode}
                            />
                        </div>

                        <div className="flex items-start gap-3 p-4 bg-blue-500/5 rounded-2xl border border-blue-500/10">
                            <Info className="w-5 h-5 text-blue-400 mt-0.5" />
                            <p className="text-xs text-blue-300/80 leading-relaxed">
                                Ce réglage est sauvegardé localement sur ce navigateur. Il n'affecte pas votre profil sur d'autres appareils.
                            </p>
                        </div>
                    </div>
                </div>

                {/* NOTIFICATIONS SECTION */}
                <div className="bg-black/40 backdrop-blur-md border border-white/10 rounded-3xl p-6 shadow-xl space-y-6">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-indigo-500/10 rounded-xl">
                            <Bell className="w-5 h-5 text-indigo-400" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-white">Notifications</h3>
                            <p className="text-sm text-zinc-400">Gérez vos alertes in-app</p>
                        </div>
                    </div>

                    <div className="pt-4 border-t border-white/5">
                        <TooltipProvider delayDuration={0}>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                            {/* MISSIONS */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-white/5 group hover:border-blue-500/30 transition-all cursor-default">
                                        <div className="flex items-center gap-2 min-w-0 flex-1">
                                            <div className="w-8 h-8 rounded-lg bg-blue-500/10 flex items-center justify-center shrink-0">
                                                <Target className="w-4 h-4 text-blue-400" />
                                            </div>
                                            <div className="min-w-0 pr-2">
                                                <p className="text-[11px] font-semibold text-zinc-200 truncate">Missions</p>
                                                <p className="text-[9px] text-zinc-500 truncate">Nouvelles & validations</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={prefs.missions}
                                            onCheckedChange={(checked) => handleUpdatePrefs({ missions: checked })}
                                            disabled={loading}
                                        />
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                    Notifications Missions
                                </TooltipContent>
                            </Tooltip>

                            {/* SONGES */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-white/5 group hover:border-emerald-500/30 transition-all cursor-default">
                                        <div className="flex items-center gap-2 min-w-0 flex-1">
                                            <div className="w-8 h-8 rounded-lg bg-emerald-500/10 flex items-center justify-center shrink-0">
                                                <Flame className="w-4 h-4 text-emerald-400" />
                                            </div>
                                            <div className="min-w-0 pr-2">
                                                <p className="text-[11px] font-semibold text-zinc-200 truncate">Songes</p>
                                                <p className="text-[9px] text-zinc-500 truncate">Invitations & candidatures</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={prefs.songes}
                                            onCheckedChange={(checked) => handleUpdatePrefs({ songes: checked })}
                                            disabled={loading}
                                        />
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                    Notifications Songes
                                </TooltipContent>
                            </Tooltip>

                            {/* DONJONS */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-white/5 group hover:border-indigo-500/30 transition-all cursor-default">
                                        <div className="flex items-center gap-2 min-w-0 flex-1">
                                            <div className="w-8 h-8 rounded-lg bg-indigo-500/10 flex items-center justify-center shrink-0">
                                                <Swords className="w-4 h-4 text-indigo-400" />
                                            </div>
                                            <div className="min-w-0 pr-2">
                                                <p className="text-[11px] font-semibold text-zinc-200 truncate">Donjons & Quêtes</p>
                                                <p className="text-[9px] text-zinc-500 truncate">Entrée en groupe</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={prefs.donjons}
                                            onCheckedChange={(checked) => handleUpdatePrefs({ donjons: checked })}
                                            disabled={loading}
                                        />
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                    Notifications Donjons
                                </TooltipContent>
                            </Tooltip>

                            {/* EVENTS */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-white/5 group hover:border-purple-500/30 transition-all cursor-default">
                                        <div className="flex items-center gap-2 min-w-0 flex-1">
                                            <div className="w-8 h-8 rounded-lg bg-purple-500/10 flex items-center justify-center shrink-0">
                                                <Calendar className="w-4 h-4 text-purple-400" />
                                            </div>
                                            <div className="min-w-0 pr-2">
                                                <p className="text-[11px] font-semibold text-zinc-200 truncate">Événements</p>
                                                <p className="text-[9px] text-zinc-500 truncate">Rappels de guilde</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={prefs.events}
                                            onCheckedChange={(checked) => handleUpdatePrefs({ events: checked })}
                                            disabled={loading}
                                        />
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                    Notifications Événements
                                </TooltipContent>
                            </Tooltip>

                            {/* LADDER */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-white/5 group hover:border-red-500/30 transition-all cursor-default">
                                        <div className="flex items-center gap-2 min-w-0 flex-1">
                                            <div className="w-8 h-8 rounded-lg bg-red-500/10 flex items-center justify-center shrink-0">
                                                <Trophy className="w-4 h-4 text-red-400" />
                                            </div>
                                            <div className="min-w-0 pr-2">
                                                <p className="text-[11px] font-semibold text-zinc-200 truncate">Succès & Ladder</p>
                                                <p className="text-[9px] text-zinc-500 truncate">Validations & rangs</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={prefs.ladder}
                                            onCheckedChange={(checked) => handleUpdatePrefs({ ladder: checked })}
                                            disabled={loading}
                                        />
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                    Notifications Classement
                                </TooltipContent>
                            </Tooltip>

                            {/* POLLS */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-white/5 group hover:border-orange-500/30 transition-all cursor-default">
                                        <div className="flex items-center gap-2 min-w-0 flex-1">
                                            <div className="w-8 h-8 rounded-lg bg-orange-500/10 flex items-center justify-center shrink-0">
                                                <PieChart className="w-4 h-4 text-orange-400" />
                                            </div>
                                            <div className="min-w-0 pr-2">
                                                <p className="text-[11px] font-semibold text-zinc-200 truncate">Sondages</p>
                                                <p className="text-[9px] text-zinc-500 truncate">Nouveaux votes</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={prefs.polls}
                                            onCheckedChange={(checked) => handleUpdatePrefs({ polls: checked })}
                                            disabled={loading}
                                        />
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                    Notifications Sondages
                                </TooltipContent>
                            </Tooltip>

                            {/* OCRE */}
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-white/5 group hover:border-emerald-700/30 transition-all cursor-default">
                                        <div className="flex items-center gap-2 min-w-0 flex-1">
                                            <div className="w-8 h-8 rounded-lg bg-emerald-700/10 flex items-center justify-center shrink-0">
                                                <Trophy className="w-4 h-4 text-emerald-500" />
                                            </div>
                                            <div className="min-w-0 pr-2">
                                                <p className="text-[11px] font-semibold text-zinc-200 truncate">Quête Ocre</p>
                                                <p className="text-[9px] text-zinc-500 truncate">Échanges</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={prefs.ocre}
                                            onCheckedChange={(checked) => handleUpdatePrefs({ ocre: checked })}
                                            disabled={loading}
                                        />
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                    Notifications Échanges Ocre
                                </TooltipContent>
                            </Tooltip>

                            {isAdmin && (
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <div className="flex items-center justify-between p-2.5 border border-white/5 rounded-2xl bg-zinc-400/5 group hover:border-zinc-300/30 transition-all cursor-default">
                                            <div className="flex items-center gap-2 min-w-0 flex-1">
                                                <div className="w-8 h-8 rounded-lg bg-zinc-400/10 flex items-center justify-center shrink-0">
                                                    <ShieldCheck className="w-4 h-4 text-zinc-400" />
                                                </div>
                                                <div className="min-w-0 pr-2">
                                                    <p className="text-[11px] font-semibold text-zinc-200 truncate">Alertes Admin</p>
                                                    <p className="text-[9px] text-zinc-500 truncate">Missions en attente</p>
                                                </div>
                                            </div>
                                            <Switch
                                                checked={prefs.admin_validations}
                                                onCheckedChange={(checked) => handleUpdatePrefs({ admin_validations: checked })}
                                                disabled={loading}
                                            />
                                        </div>
                                    </TooltipTrigger>
                                    <TooltipContent side="top" className="bg-zinc-900 border-white/10 text-white font-bold uppercase tracking-wider text-[9px] px-3 py-1.5 shadow-xl">
                                        Notifications Administration
                                    </TooltipContent>
                                </Tooltip>
                            )}
                        </div>
                        </TooltipProvider>
                    </div>
                </div>

            </div>

            {/* BOTTOM ROW: GDPR / LIFECYCLE SECTION (Full width, divided in 2) */}
            <div className="bg-black/40 backdrop-blur-md border border-white/10 rounded-3xl p-4 sm:p-6 lg:p-8 shadow-xl space-y-8">
                <div className="flex items-center gap-4 border-b border-white/5 pb-6">
                    <div className="p-3 bg-red-500/10 rounded-2xl border border-red-500/20">
                        <ShieldAlert className="w-6 h-6 text-red-400" />
                    </div>
                    <div>
                        <h3 className="text-xl font-bold text-white">Gestion du Compte & Confidentialité (RGPD)</h3>
                        <p className="text-sm text-zinc-400">Prenez le contrôle de vos données personnelles et de votre présence sur SigilOS</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-8 items-stretch">
                    {/* LEAVE GUILD — Safe, Reversible */}
                    <div className="flex flex-col p-5 sm:p-6 lg:p-8 bg-zinc-900/60 rounded-3xl border border-emerald-500/20 hover:border-emerald-500/40 transition-all relative overflow-hidden group shadow-lg">
                        <div className="absolute -top-10 -right-10 p-8 opacity-5 group-hover:opacity-10 transition-opacity pointer-events-none rotate-12">
                            <UserMinus className="w-64 h-64 text-emerald-500" />
                        </div>
                        
                        <div className="flex-1 space-y-4 relative z-10">
                            <div className="flex items-center gap-3">
                                <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded-full border border-emerald-500/20">
                                    Action Réversible
                                </span>
                            </div>
                            
                            <div>
                                <h4 className="text-2xl font-bold text-white mb-2">Archiver mon profil</h4>
                                <p className="text-sm text-zinc-400 leading-relaxed text-balance">
                                    Mettez votre profil en pause uniquement pour la guilde <b className="text-zinc-200">{guildName}</b>. Vos points d'expérience, missions et inventaires sont soigneusement conservés en sécurité pendant une durée configurée au cas où vous changeriez d'avis. 
                                </p>
                            </div>
                            
                            <ul className="space-y-2 mt-4 text-sm text-zinc-300">
                                <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-emerald-500" /> Vous conservez vos données intactes</li>
                                <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-emerald-500" /> Vos autres guildes fonctionnent toujours</li>
                                <li className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-emerald-500" /> Réactivation sur simple demande</li>
                            </ul>
                        </div>

                        <div className="mt-8 pt-6 border-t border-white/5 relative z-10">
                            <AlertDialog>
                                <AlertDialogTrigger asChild>
                                    <Button variant="sigil-destructive" className="w-full h-auto min-h-[3rem] py-2 whitespace-normal text-[10px] sm:text-xs md:text-sm gap-2 font-bold bg-white/5 hover:bg-emerald-500/20 text-white hover:text-emerald-400 border border-white/10 hover:border-emerald-500/50 transition-all flex items-center justify-center text-center">
                                        <UserMinus className="w-4 h-4 shrink-0" />
                                        ARCHIVER MON PROFIL SUR <span className="block sm:inline">{guildName.toUpperCase()}</span>
                                    </Button>
                                </AlertDialogTrigger>
                                <AlertDialogContent className="bg-zinc-900 border-white/10 text-white">
                                    <AlertDialogHeader>
                                        <AlertDialogTitle>Archiver votre profil sur {guildName} ?</AlertDialogTitle>
                                        <AlertDialogDescription asChild>
                                            <div className="text-zinc-400 space-y-3">
                                                <p>Votre profil de guilde sera <b className="text-zinc-200">archivé</b>, pas supprimé.</p>
                                                <div className="bg-zinc-800/50 rounded-xl p-3 space-y-1.5 text-xs">
                                                    <p className="flex items-center gap-2"><span className="text-emerald-400">✅</span> Vos XP et données sont conservées</p>
                                                    <p className="flex items-center gap-2"><span className="text-emerald-400">✅</span> Vous pouvez rejoindre à tout moment via Discord</p>
                                                    <p className="flex items-center gap-2"><span className="text-amber-400">⚠️</span> Vous perdez l&apos;accès au tableau de bord de cette guilde</p>
                                                    <p className="flex items-center gap-2"><span className="text-blue-400">ℹ️</span> Vos autres guildes ne sont pas affectées</p>
                                                </div>
                                                <div className="pt-2 space-y-2">
                                                    <p className="text-xs font-bold text-zinc-300">Durée d'archivage (avant suppression définitive) :</p>
                                                    <div className="grid grid-cols-3 gap-2">
                                                        {[3, 6, 12].map(duration => (
                                                            <button
                                                                key={duration}
                                                                type="button"
                                                                onClick={() => setArchiveDuration(duration)}
                                                                className={`p-2 rounded-xl text-xs font-bold transition-all border ${
                                                                    archiveDuration === duration 
                                                                        ? "bg-emerald-500/20 text-emerald-400 border-emerald-500/50 ring-1 ring-emerald-500/30" 
                                                                        : "bg-zinc-800/50 text-zinc-400 border-white/5 hover:bg-white/10"
                                                                }`}
                                                            >
                                                                {duration} Mois
                                                            </button>
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                        </AlertDialogDescription>
                                    </AlertDialogHeader>
                                    <AlertDialogFooter>
                                        <AlertDialogCancel className="bg-transparent border-white/10">Annuler</AlertDialogCancel>
                                        <AlertDialogAction
                                            onClick={handleLeaveGuild}
                                            disabled={isDeleting}
                                            variant="sigil-destructive"
                                            className="h-10 px-6"
                                        >
                                            Confirmer l'archivage
                                        </AlertDialogAction>
                                    </AlertDialogFooter>
                                </AlertDialogContent>
                            </AlertDialog>
                        </div>
