const BOOK_STAT_NAMES: Record<string, string> = {
    "vi": "Vitalité",
    "fo": "Force",
    "sa": "Sagesse",
    "ag": "Agilité",
    "in": "Intelligence",
    "ch": "Chance",
    "pu": "Puissance",
