    "pm": "PM",
    "ta": "Tacle",
    "fu": "Fuite",
    "so": "Soins",
    "rpa": "Retrait PA",
    "epa": "Esquive PA",
    "rpm": "Retrait PM",
    "epm": "Esquive PM",
