                                                            </span>
                                                        </div>
                                                    ))
                                                ) : (
                                                    <div className="py-10 text-center opacity-20">
                                                        <Zap className="h-8 w-8 mx-auto mb-2" />
                                                        <p className="text-[10px] font-black uppercase">Aucun effet</p>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Recipe Card */}
                                    <div className="space-y-6">
                                        <div className="p-8 rounded-[2.5rem] bg-white/[0.03] border border-white/5 shadow-inner">
                                            <div className="flex items-center gap-3 mb-8">
                                                <Scroll className="h-5 w-5 text-zinc-500" />
                                                <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-zinc-500">Fabrication</h4>
                                            </div>

                                            {recipe ? (
                                                <div className="space-y-4">
                                                    <div className="grid grid-cols-1 gap-3">
                                                        {recipe.ingredients.map((ing, i) => (
                                                            <div key={i} className="flex items-center gap-4 p-3 rounded-2xl bg-black/50 border border-white/5 group/ing hover:border-white/10 transition-all">
                                                                <div className="w-12 h-12 rounded-xl bg-zinc-950 flex items-center justify-center shrink-0">
                                                                    <Image src={ing.img || `https://static.dofusdb.fr/items/${ing.id}.png`} alt="Ingredient" width={32} height={32} unoptimized />
                                                                </div>
                                                                <div className="flex-1 min-w-0">
                                                                    <div className="text-[12px] font-bold text-zinc-200 truncate group-hover/ing:text-white transition-colors">{ing.name.fr}</div>
                                                                    <div className="text-[11px] font-black text-emerald-400">x {recipe.quantities[i]}</div>
                                                                </div>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="py-20 border border-dashed border-white/5 rounded-3xl flex flex-col items-center justify-center opacity-20 capitalize">
                                                    <PackageOpen className="h-10 w-10 mb-3" />
                                                    <p className="text-[11px] font-black tracking-widest">Pas de recette disponible</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useParams } from "next/navigation";
import { getGuildKralamoureEvents } from "@/server/actions/ocre-actions";
import { Anchor, Clock, MapPin, Users, ExternalLink, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

// Interface for type safety
interface KralamoureEvent {
    id: number;
    event_datetime: string;
    description?: string | null;
    creator: string;
    participants_count?: number;
    character_count?: number;
    messages_count?: number;
    server: {
        id: number;
        name: string;
        community: string;
    };
}

export function KralamoureWidget() {
    const params = useParams();
    const guildId = params.guildId as string;

    const [events, setEvents] = useState<KralamoureEvent[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (!guildId) return;
        const fetchKrala = async () => {
            setLoading(true);
            try {
                const res = await getGuildKralamoureEvents(guildId);
                if (res.success && res.data) {
                    setEvents(res.data);
                } else {
                    setError("Impossible de charger les événements.");
                }
            } catch (e) {
                setError("Erreur de connexion.");
            } finally {
                setLoading(false);
            }
        };
        fetchKrala();
    }, [guildId]);

    // Format utility
    const formatDate = (isoString: string) => {
        const d = new Date(isoString);
        return new Intl.DateTimeFormat('fr-FR', {
            weekday: 'short',
            day: '2-digit',
            month: 'short',
            hour: '2-digit',
            minute: '2-digit'
        }).format(d);
    };

    if (loading) {
        return (
            <div className="flex-1 min-h-[140px] rounded-2xl bg-white/5 animate-pulse border border-white/5 flex items-center justify-center">
                <Loader2 className="h-5 w-5 text-emerald-500 animate-spin opacity-50" />
            </div>
        );
    }

    if (error || events.length === 0) {
        return (
            <div className="flex-1 rounded-2xl bg-gradient-to-br from-emerald-950/20 to-black border border-emerald-900/30 p-5 flex flex-col items-center justify-center text-center">
                <Anchor className="h-8 w-8 text-emerald-500/30 mb-2" />
                <h4 className="text-sm font-bold text-white mb-1">Antre du Kralamoure Géant</h4>
                <p className="text-xs text-zinc-500">Aucune ouverture prévue sur votre serveur via Metamob pour le moment.</p>
                <a href="https://metamob.fr/" target="_blank" rel="noopener noreferrer" className="mt-3 text-[10px] uppercase font-bold tracking-widest text-emerald-500 hover:text-emerald-400 flex items-center gap-1 transition-colors">
                    Consulter Metamob <ExternalLink className="h-3 w-3" />
                </a>
            </div>
        );
    }

    // Sort events by date
    const sortedEvents = [...events].sort((a, b) => new Date(a.event_datetime).getTime() - new Date(b.event_datetime).getTime());
    const nextEvent = sortedEvents[0];
    const isImminent = new Date(nextEvent.event_datetime).getTime() - Date.now() < 3600000 * 24; // Less than 24h

    return (
        <div
            className="flex-1 rounded-2xl relative overflow-hidden group/krala"
            style={{
                background: "linear-gradient(135deg, rgba(6,78,59,0.3) 0%, rgba(2,44,34,0.8) 100%)",
                border: "1px solid rgba(16, 185, 129, 0.2)",
            }}
        >
            {/* Background Glow */}
            <div className="absolute top-0 right-0 w-32 h-32 rounded-full blur-[40px] opacity-20 pointer-events-none"
                style={{ background: "#10b981", transform: "translate(30%, -30%)" }} />

            <div className="p-4 relative z-10 flex flex-col h-full">
                {/* Header */}
                <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded-lg bg-emerald-500/15 flex items-center justify-center border border-emerald-500/20 shadow-inner">
                            <Anchor className="h-4 w-4 text-emerald-400" />
                        </div>
                        <div>
                            <h3 className="text-xs font-black uppercase tracking-[0.2em] text-white flex items-center gap-2">
                                Kralamoure Géant
                                <span className="px-1.5 py-0.5 rounded text-[8px] tracking-widest bg-emerald-500/20 text-emerald-300">
                                    {nextEvent.server.name}
                                </span>
                            </h3>
                            <p className="text-[10px] text-zinc-400 font-medium tracking-wide">Prochaine ouverture Prévue</p>
                        </div>
                    </div>
                </div>

                {/* Event Info */}
                <div className="bg-black/40 rounded-xl p-3 border border-white/5 flex-1 flex flex-col justify-center relative overflow-hidden">
                    {isImminent && (
                        <div className="absolute top-0 inset-x-0 h-0.5 bg-gradient-to-r from-transparent via-emerald-500 to-transparent opacity-50" />
                    )}

                    <div className="flex items-center gap-3">
                        <div className="h-10 w-10 rounded-full bg-emerald-950 flex items-center justify-center flex-shrink-0 border border-emerald-800/50">
                            <Clock className={cn("h-5 w-5 text-emerald-400", isImminent && "animate-pulse text-emerald-300")} />
                        </div>
                        <div>
                            <div className="text-emerald-100 font-bold text-sm tracking-wide capitalize">
                                {formatDate(nextEvent.event_datetime)}
                            </div>
                            <div className="flex items-center gap-3 mt-1 text-[10px] font-medium text-emerald-400/70">
                                <span className="flex items-center gap-1"><Users className="h-3 w-3" /> {nextEvent.participants_count ?? 0} Inscrits</span>
                                <span className="flex items-center gap-1"><MapPin className="h-3 w-3" /> Tourbière [-60,-8]</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer Action */}
                <div className="mt-3 text-center">
                    <a
                        href={`https://metamob.fr/krala/${nextEvent.id}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-widest text-emerald-500 hover:text-emerald-400 transition-colors"
                    >
                        S'inscrire sur Metamob <ExternalLink className="h-3 w-3 mb-0.5" />
                    </a>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { ExternalLink, Newspaper, Zap, Scroll, Shield, Sparkles, Globe2, ChevronDown, RefreshCw, Rss, Send, Globe, CheckCircle2, XCircle, Bell, Megaphone } from "lucide-react";
import { cn } from "@/lib/utils";
import { KralamoureWidget } from "@/components/ressources/KralamoureWidget";
import { useParams } from "next/navigation";
import { getUserContext, type UserContext } from "@/server/actions/user-actions";
import { sendNewsToDiscord, broadcastNewsToAllGuilds, type DiscordNewsItem } from "@/server/actions/news-discord-actions";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

interface NewsItem {
    title: string;
    link: string;
    pubDate: string;
    description: string;
    imageUrl?: string;
    category?: string;
}

// ─── Feed options ─────────────────────────────────────────────────────────────

const FEEDS = [
    { key: "news", label: "Actualités", icon: Rss, color: "#3b82f6" },
    { key: "changelog", label: "Changelog", icon: Scroll, color: "#10b981" },
    { key: "devblog", label: "Devblog", icon: Zap, color: "#a855f7" },
    { key: "dpln", label: "Guides & Quêtes (DPLN)", icon: Scroll, color: "#f59e0b" },
] as const;

type FeedKey = typeof FEEDS[number]["key"];

// ─── Helpers ──────────────────────────────────────────────────────────────────

const MONTHS_FR = ["jan.", "fév.", "mar.", "avr.", "mai", "jun.", "jul.", "aoû.", "sep.", "oct.", "nov.", "déc."];

function formatPubDate(raw: string): string {
    if (!raw) return "";
    const d = new Date(raw);
    if (isNaN(d.getTime())) return "";
    return `${d.getDate()} ${MONTHS_FR[d.getMonth()]} ${d.getFullYear()}`;
}

const CARD_PALETTE = [
    { from: "#1a0a2e", accent: "#a855f7", icon: Sparkles },
    { from: "#0a1a2e", accent: "#3b82f6", icon: Zap },
    { from: "#1a1000", accent: "#f59e0b", icon: Scroll },
    { from: "#0a1a10", accent: "#10b981", icon: Shield },
    { from: "#1a0a10", accent: "#ef4444", icon: Globe2 },
    { from: "#0f0a1a", accent: "#8b5cf6", icon: Zap },
];

// ─── News Actions Subcomponent ────────────────────────────────────────────────

function NewsActions({ 
    item, 
    userCtx, 
    sending, 
    handleSendToDiscord, 
    handleBroadcast, 
    broadcasting,
    variant = "default"
}: { 
    item: NewsItem; 
    userCtx: UserContext | null; 
    sending: string | null;
    handleSendToDiscord: (item: NewsItem) => void;
    handleBroadcast: (item: NewsItem) => void;
    broadcasting: boolean;
    variant?: "default" | "minimal"
}) {
    // Only show to admins if enabled, or if SuperAdmin
    if (!userCtx?.isAdmin) return null;
    if (!userCtx.newsBroadcastEnabled && !userCtx.isSuperAdmin) return null;

    const isSending = sending === item.link;

    return (
        <div className={cn(
            "flex items-center gap-2 transition-all duration-300",
            variant === "default" ? "opacity-0 group-hover:opacity-100" : "opacity-40 group-hover:opacity-100"
        )}>
            <button
                onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleSendToDiscord(item); }}
                disabled={isSending}
                className={cn(
                    "rounded-lg transition-all disabled:opacity-50",
                    variant === "default" 
                        ? "p-2 bg-[#5865F2]/10 border border-[#5865F2]/20 text-[#5865F2] hover:bg-[#5865F2] hover:text-white"
                        : "p-1.5 bg-white/5 border border-white/10 text-zinc-400 hover:text-[#5865F2] hover:border-[#5865F2]/30"
                )}
                title="Partager sur Discord"
            >
                <Bell className={cn(variant === "default" ? "w-4 h-4" : "w-3.5 h-3.5", isSending && "animate-spin")} />
            </button>
            
            {userCtx?.isSuperAdmin && (
                <button
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleBroadcast(item); }}
                    disabled={broadcasting}
                    className={cn(
                        "rounded-lg transition-all disabled:opacity-50",
                        variant === "default" 
                            ? "p-2 bg-amber-500/10 border border-amber-500/20 text-amber-500 hover:bg-amber-500 hover:text-black"
                            : "p-1.5 bg-white/5 border border-white/10 text-zinc-400 hover:text-amber-500 hover:border-amber-500/30"
                    )}
                    title="Diffuser à toutes les guildes (GOD MODE)"
                >
                    <Megaphone className={cn(variant === "default" ? "w-4 h-4" : "w-3.5 h-3.5", broadcasting && "animate-pulse")} />
                </button>
            )}
        </div>
    );
}

// ─── Featured card ────────────────────────────────────────────────────────────

function FeaturedCard({ 
    item, 
    feedColor, 
    feedLabel,
    userCtx,
    sending,
    handleSendToDiscord,
    handleBroadcast,
    broadcasting
}: { 
    item: NewsItem; 
    feedColor: string; 
    feedLabel: string;
    userCtx: UserContext | null;
    sending: string | null;
    handleSendToDiscord: (item: NewsItem) => void;
    handleBroadcast: (item: NewsItem) => void;
    broadcasting: boolean;
}) {
    const [imgError, setImgError] = useState(false);
    const grad = CARD_PALETTE[0];

    return (
        <a
            href={item.link}
            target="_blank"
            rel="noopener noreferrer"
            className="group relative overflow-hidden rounded-2xl cursor-pointer block"
            style={{
                background: `linear-gradient(135deg, ${grad.from} 0%, #0d1117 100%)`,
                border: `1px solid ${feedColor}20`,
            }}
        >
            {/* Ambient glow on hover */}
            <div
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none rounded-2xl"
                style={{ background: `radial-gradient(ellipse at 20% 50%, ${feedColor}12, transparent 60%)` }}
            />

            {/* Image / Placeholder */}
            <div className="relative h-52 lg:h-60 overflow-hidden">
                {item.imageUrl && !imgError ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img
                        src={item.imageUrl}
                        alt={item.title}
                        referrerPolicy="no-referrer"
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700"
                        onError={() => setImgError(true)}
                    />
                ) : (
                    <div className="relative w-full h-full flex items-center justify-center overflow-hidden"
                        style={{ background: `linear-gradient(135deg, ${grad.from}, #0d1117)` }}>
                        {/* Decorative orbs */}
                        <div className="absolute w-48 h-48 rounded-full blur-3xl opacity-20"
                            style={{ background: feedColor, top: "10%", left: "20%" }} />
                        <div className="absolute w-32 h-32 rounded-full blur-2xl opacity-10"
                            style={{ background: feedColor, bottom: "10%", right: "15%" }} />
                        {/* SVG lines */}
                        <svg className="absolute inset-0 w-full h-full opacity-10" viewBox="0 0 400 240">
                            <path d="M0 120 L400 80" stroke={feedColor} strokeWidth="1" />
                            <path d="M0 160 L400 120" stroke={feedColor} strokeWidth="0.5" />
                            <circle cx="200" cy="120" r="60" fill="none" stroke={feedColor} strokeWidth="0.5" />
                            <circle cx="200" cy="120" r="100" fill="none" stroke={feedColor} strokeWidth="0.3" />
                        </svg>
                        {/* Center icon / Logo */}
                        <div className="relative z-10 flex flex-col items-center gap-3">
                            <div className="w-20 h-20 rounded-2xl flex items-center justify-center overflow-hidden bg-black/40 border border-white/10 group-hover:scale-110 transition-transform duration-500 shadow-2xl">
                                <img src="/assets/ui/logo-v2.png" alt="SigilOS" className="w-12 h-12 object-contain" />
                            </div>
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40">{feedLabel}</span>
                        </div>
                    </div>
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-[#0d1117] via-transparent to-transparent pointer-events-none" />
                
                {/* ACTIONS TOP RIGHT */}
                <div className="absolute top-4 right-4 z-20">
                    {feedLabel !== "Changelog" && (
                        <NewsActions 
                            item={item} 
                            userCtx={userCtx} 
                            sending={sending} 
                            handleSendToDiscord={handleSendToDiscord} 
                            handleBroadcast={handleBroadcast} 
                            broadcasting={broadcasting}
                        />
                    )}
                </div>
            </div>

            {/* Content */}
            <div className="relative p-5 space-y-3">
                <div className="flex items-center gap-2 flex-wrap">
                    {item.category && (
                        <span className="text-[9px] font-black uppercase tracking-[0.25em] px-2 py-0.5 rounded-full"
                            style={{ background: `${feedColor}15`, color: feedColor, border: `1px solid ${feedColor}30` }}>
                            {item.category}
                        </span>
                    )}
                    {item.pubDate && (
                        <span className="text-[10px] text-zinc-600">{formatPubDate(item.pubDate)}</span>
                    )}
                </div>
                <h3 className="text-lg font-bold text-white leading-tight line-clamp-3 group-hover:opacity-80 transition-opacity">
                    {item.title}
                </h3>
                {item.description && (
                    <p className="text-zinc-400 text-sm leading-relaxed line-clamp-2">{item.description}</p>
                )}
                <div className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider group-hover:gap-3 transition-all"
                    style={{ color: feedColor }}>
                    Lire l&apos;article <ExternalLink className="h-3 w-3" />
                </div>
            </div>
        </a>
    );
}

// ─── Side card ────────────────────────────────────────────────────────────────

function SideCard({ 
    item, 
    idx, 
    feedColor,
    userCtx,
    sending,
    handleSendToDiscord,
    handleBroadcast,
    broadcasting
}: { 
    item: NewsItem; 
    idx: number; 
    feedColor: string;
    userCtx: UserContext | null;
    sending: string | null;
    handleSendToDiscord: (item: NewsItem) => void;
    handleBroadcast: (item: NewsItem) => void;
    broadcasting: boolean;
}) {
