// ─── Main Component ───────────────────────────────────────────────────────────

export function NewsGrid({
    defaultFeed = "news",
    hideSelector = false,
    title,
    maxItems = 8,
    showKralamoure = false,
    layout = "grid"
}: {
    defaultFeed?: FeedKey;
    hideSelector?: boolean;
    title?: string;
    maxItems?: number;
    showKralamoure?: boolean;
    layout?: "grid" | "list";
}) {
    const [activeFeed, setActiveFeed] = useState<FeedKey>(defaultFeed);
    const [dropdownOpen, setDropdownOpen] = useState(false);
    const [items, setItems] = useState<NewsItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [userCtx, setUserCtx] = useState<UserContext | null>(null);
    const [sending, setSending] = useState<string | null>(null); // URL of item being sent
    const [broadcasting, setBroadcasting] = useState(false);

    const params = useParams();
    const discordGuildId = params.guildId as string;

    useEffect(() => {
        getUserContext(discordGuildId).then(setUserCtx);
    }, [discordGuildId]);

    const currentFeed = FEEDS.find(f => f.key === activeFeed) ?? FEEDS[0];

    const handleSendToDiscord = async (item: NewsItem) => {
        if (!discordGuildId) return;
        setSending(item.link);
        
        try {
            const res = await sendNewsToDiscord(discordGuildId, {
                title: item.title,
                url: item.link,
                imageUrl: item.imageUrl,
                description: item.description,
                pubDate: item.pubDate,
                category: currentFeed.label
            });

            if (res.success) {
                toast.success("Envoyé sur Discord !");
            } else {
                toast.error("Échec de l'envoi: " + (res.error || "Une erreur est survenue."));
            }
        } catch (err) {
            toast.error("Impossible de contacter l'API Discord.");
        } finally {
            setSending(null);
        }
    };

    const handleBroadcast = async (item: NewsItem) => {
        if (!userCtx?.isSuperAdmin) return;
        if (!confirm(`Voulez-vous vraiment diffuser cette annonce à TOUTES les guildes actives (${item.title}) ?`)) return;
        
        setBroadcasting(true);
        try {
            const res = await broadcastNewsToAllGuilds({
                title: item.title,
                url: item.link,
                imageUrl: item.imageUrl,
                description: item.description,
                pubDate: item.pubDate,
                category: currentFeed.label
            });

            if (res.success) {
                toast.success(`Diffusion terminée ! (${res.results?.success} guildes)`);
            }
        } catch (err) {
            toast.error("Échec de la diffusion critique.");
        } finally {
            setBroadcasting(false);
        }
    };

    const fetchNews = useCallback(async (feedKey: FeedKey) => {
        setLoading(true);
        setError(null);
        try {
            const res = await fetch(`/api/resources/news?feed=${feedKey}`, {
                cache: "no-store",
            });
            const data = await res.json() as { items: NewsItem[]; error?: string };
            if (data.error && !data.items?.length) {
                setError("Flux temporairement indisponible.");
            } else {
                setItems(data.items ?? []);
            }
        } catch {
            setError("Impossible de charger le flux RSS.");
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchNews(activeFeed);
    }, [activeFeed, fetchNews]);

    const [featured, ...rest] = items;

    return (
        <div className="space-y-4">
            {/* ── Header / Selector ─────────────────────────────────────── */}
            <div className="flex items-center justify-between gap-4 flex-wrap">
                {title ? (
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg flex items-center justify-center" style={{ background: `${currentFeed.color}15`, border: `1px solid ${currentFeed.color}30` }}>
                            <currentFeed.icon className="h-4 w-4" style={{ color: currentFeed.color }} />
                        </div>
                        <h3 className="text-sm font-black uppercase tracking-widest text-white">{title}</h3>
                    </div>
                ) : !hideSelector ? (
                    <div className="relative">
                        <button
                            onClick={() => setDropdownOpen(o => !o)}
                            className="flex items-center gap-2.5 px-4 py-2.5 rounded-xl text-sm font-bold transition-all hover:bg-white/5"
                            style={{
                                background: `${currentFeed.color}10`,
                                border: `1px solid ${currentFeed.color}25`,
                                color: currentFeed.color,
                            }}
                        >
                            <currentFeed.icon className="h-3.5 w-3.5" />
                            {currentFeed.label}
                            <ChevronDown className={cn("h-3.5 w-3.5 transition-transform", dropdownOpen && "rotate-180")} />
                        </button>

                        {dropdownOpen && (
                            <div
                                className="absolute top-full mt-2 left-0 z-50 min-w-[160px] rounded-xl overflow-hidden shadow-2xl"
                                style={{ background: "#13171A", border: "1px solid rgba(255,255,255,0.08)" }}
                            >
                                {FEEDS.map((feed) => (
                                    <button
                                        key={feed.key}
                                        onClick={() => { setActiveFeed(feed.key); setDropdownOpen(false); }}
                                        className={cn(
                                            "w-full flex items-center gap-3 px-4 py-3 text-sm text-left transition-all hover:bg-white/5",
                                            activeFeed === feed.key ? "font-bold" : "font-medium text-zinc-400"
                                        )}
                                        style={activeFeed === feed.key ? { color: feed.color } : {}}
                                    >
                                        <feed.icon className="h-3.5 w-3.5" />
                                        {feed.label}
                                        {activeFeed === feed.key && (
                                            <span className="ml-auto w-1.5 h-1.5 rounded-full" style={{ background: feed.color }} />
                                        )}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                ) : (
                    <div />
                )}

                {/* Refresh */}
                <button
                    onClick={() => fetchNews(activeFeed)}
                    disabled={loading}
                    className="flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-bold text-zinc-500 hover:text-white transition-all hover:bg-white/5 disabled:opacity-40"
                    style={{ border: "1px solid rgba(255,255,255,0.06)" }}
                >
                    <RefreshCw className={cn("h-3.5 w-3.5", loading && "animate-spin")} />
                    Rafraîchir
                </button>
            </div>

            {/* ── Content ───────────────────────────────────────────── */}
            {loading ? (
                <Skeleton />
            ) : error || !items.length ? (
                <div
                    className="rounded-2xl p-10 flex flex-col items-center justify-center min-h-[200px] text-center gap-4"
                    style={{ background: "rgba(255,255,255,0.02)", border: "1px solid rgba(255,255,255,0.05)" }}
                >
                    <div className="w-14 h-14 rounded-2xl flex items-center justify-center"
                        style={{ background: `${currentFeed.color}10`, border: `1px solid ${currentFeed.color}20` }}>
                        <currentFeed.icon className="h-7 w-7" style={{ color: currentFeed.color }} />
                    </div>
                    <div>
                        <p className="text-white font-semibold">
                            {error ?? "Aucun article trouvé"}
                        </p>
                        <p className="text-zinc-500 text-sm mt-1">
                            Essaie un autre flux ou rafraîchis
                        </p>
                    </div>
                    <button
                        onClick={() => fetchNews(activeFeed)}
                        className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all"
                        style={{
                            background: `${currentFeed.color}15`,
                            color: currentFeed.color,
                            border: `1px solid ${currentFeed.color}30`,
                        }}
                    >
                        <RefreshCw className="h-3.5 w-3.5" /> Réessayer
                    </button>
                </div>
            ) : layout === "list" ? (
                <div className="flex flex-col gap-2 relative">
                    {/* Vertical line connector */}
                    <div className="absolute left-[31px] top-6 bottom-6 w-px bg-white/5" />
                    
                    {items.slice(0, maxItems).map((item, i) => (
                        <ListCard 
                            key={i} 
                            item={item} 
                            currentFeed={currentFeed}
                            userCtx={userCtx}
                            sending={sending}
                            handleSendToDiscord={handleSendToDiscord}
                            handleBroadcast={handleBroadcast}
                            broadcasting={broadcasting}
                        />
                    ))}
                </div>
            ) : (
                <div className="grid gap-4 grid-cols-1 lg:grid-cols-5 items-stretch">
                    {featured && (
                        <div className="lg:col-span-3">
                            <FeaturedCard 
                                item={featured} 
                                feedColor={currentFeed.color} 
                                feedLabel={currentFeed.label} 
                                userCtx={userCtx}
                                sending={sending}
                                handleSendToDiscord={handleSendToDiscord}
                                handleBroadcast={handleBroadcast}
                                broadcasting={broadcasting}
                            />
                            {showKralamoure && <div className="mt-3"><KralamoureWidget /></div>}
                        </div>
                    )}
                    <div className="lg:col-span-2 flex flex-col gap-1 max-h-[500px] lg:max-h-none overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-white/10 hover:scrollbar-thumb-white/20">
                        {rest.slice(0, maxItems - 1).map((item, i) => (
                            <SideCard 
                                key={i} 
                                item={item} 
                                idx={i} 
                                feedColor={currentFeed.color} 
                                userCtx={userCtx}
                                sending={sending}
                                handleSendToDiscord={handleSendToDiscord}
                                handleBroadcast={handleBroadcast}
                                broadcasting={broadcasting}
                            />
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Clock, Wrench, RefreshCw, AlertCircle, Zap, ShieldAlert } from "lucide-react";

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Obtenir l'heure courante à Paris */
function getParisTime() {
    return new Date(new Date().toLocaleString("en-US", { timeZone: "Europe/Paris" }));
}

/** Formater hh:mm:ss */
function formatTimeLeft(ms: number) {
    if (ms <= 0) return "En cours...";
    const s = Math.floor((ms / 1000) % 60);
    const m = Math.floor((ms / 1000 / 60) % 60);
    const h = Math.floor((ms / 1000 / 60 / 60) % 24);
    const d = Math.floor(ms / 1000 / 60 / 60 / 24);

    if (d > 0) return `${d}j ${h}h ${m}m`;
    return `${h}h ${m}m ${s}s`;
}

/** Prochaine occurence d'un jour donné (0=Dim, 1=Lun, 2=Mar...) à une heure donnée (en Paris time) */
function getNextDayTime(dayOfWeek: number, hour: number, minute: number = 0) {
    const now = getParisTime();
    const result = new Date(now);
    result.setHours(hour, minute, 0, 0);

    // Si on est déjà passé ou que c'est pas le bon jour
    if (now.getDay() !== dayOfWeek || now.getTime() >= result.getTime()) {
        const offset = (dayOfWeek + 7 - now.getDay()) % 7;
        const daysToAdd = offset === 0 ? 7 : offset;
        result.setDate(result.getDate() + daysToAdd);
    }
    return result;
}

/** Prochaine occurrence de minuit (Paris time) */
function getNextMidnight() {
    const now = getParisTime();
    const next = new Date(now);
    next.setHours(24, 0, 0, 0); // Passe au lendemain minuit
    return next;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function ServerTimersPanel() {
    const [now, setNow] = useState<Date | null>(null);

    // Refresh every second
    useEffect(() => {
        setNow(getParisTime());
        const i = setInterval(() => setNow(getParisTime()), 1000);
        return () => clearInterval(i);
    }, []);

    if (!now) return <div className="min-h-[420px]" />; // SSR / hydration wait

    // Timers targets
    const tNextMidnight = getNextMidnight().getTime() - now.getTime();
    const tNextMaintenance = getNextDayTime(2, 8, 0).getTime() - now.getTime(); // Mardi 8h00
    const isMaintenanceTime = now.getDay() === 2 && now.getHours() >= 8 && now.getHours() < 11; // Grosso modo

    return (
        <div
            className="flex flex-col rounded-2xl overflow-hidden shadow-2xl relative"
            style={{
                background: "linear-gradient(160deg, #13171a 0%, #0d1012 100%)",
                border: "1px solid rgba(255,255,255,0.08)",
                minHeight: 420,
            }}
        >
            {/* Decos */}
            <div className="absolute top-0 right-0 w-32 h-32 rounded-full blur-3xl opacity-10 bg-emerald-500 pointer-events-none" />
            <svg className="absolute inset-0 w-full h-full opacity-[0.03] pointer-events-none" viewBox="0 0 100 100" preserveAspectRatio="none">
                <line x1="0" y1="0" x2="100" y2="100" stroke="#fff" strokeWidth="0.5" />
                <line x1="0" y1="100" x2="100" y2="0" stroke="#fff" strokeWidth="0.5" />
            </svg>

            {/* Header = Real Time Server Clock */}
            <div className="px-6 py-5 flex items-center justify-between relative z-10"
                style={{ background: "rgba(0,0,0,0.3)", borderBottom: "1px solid rgba(255,255,255,0.05)" }}>
                <div>
                    <h3 className="text-[10px] font-black uppercase tracking-[0.25em] text-emerald-400 mb-1 flex items-center gap-2">
                        <Clock className="h-3 w-3" /> Heure Dofus (Paris)
                    </h3>
                    <div className="text-3xl font-black text-white tracking-widest tabular-nums leading-none">
                        {now.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit", second: "2-digit" })}
                    </div>
                </div>
                {/* Petit pulse vert = serveur UP */}
                <div className="flex items-center gap-2 bg-emerald-500/10 border border-emerald-500/20 px-3 py-1.5 rounded-full">
                    <span className="relative flex h-2 w-2">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
                        <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500" />
                    </span>
                    <span className="text-[9px] font-bold uppercase tracking-widest text-emerald-400">En ligne</span>
                </div>
            </div>

            {/* Timers List */}
            <div className="flex-1 p-5 space-y-3 relative z-10 overflow-hidden">
                <div className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-4">
                    Échéances du moment
                </div>

                {/* Maintenance Mardi */}
                <div className="group relative overflow-hidden rounded-xl p-4 transition-all hover:bg-white/5 border border-white/5">
                    <div className="absolute top-0 right-0 w-16 h-16 rounded-full blur-2xl opacity-10 bg-fuchsia-500 transition-opacity group-hover:opacity-20 pointer-events-none" />
                    <div className="flex justify-between items-end">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <div className="w-6 h-6 rounded-md bg-fuchsia-500/10 flex items-center justify-center border border-fuchsia-500/20">
                                    <Wrench className="h-3 w-3 text-fuchsia-400" />
                                </div>
                                <span className="text-[10px] font-black uppercase tracking-widest text-fuchsia-400">
                                    Maintenance
                                </span>
                            </div>
                            <div className="text-sm font-semibold text-white">Sauvegarde Dofus</div>
                            <div className="text-[10px] text-zinc-500 mt-0.5">Mardi, estimé 08:00 - 10:30</div>
                        </div>
                        <div className="text-right">
                            <div className="text-[9px] text-zinc-500 uppercase tracking-widest mb-1 font-bold">Dans :</div>
                            <div className="text-lg font-black text-fuchsia-300 tabular-nums">
                                {isMaintenanceTime ? "En cours ⏳" : formatTimeLeft(tNextMaintenance)}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Reset Journalier */}
                <div className="group relative overflow-hidden rounded-xl p-4 transition-all hover:bg-white/5 border border-white/5">
                    <div className="absolute top-0 right-0 w-16 h-16 rounded-full blur-2xl opacity-10 bg-amber-500 transition-opacity group-hover:opacity-20 pointer-events-none" />
                    <div className="flex justify-between items-end">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <div className="w-6 h-6 rounded-md bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                                    <RefreshCw className="h-3 w-3 text-amber-400" />
                                </div>
                                <span className="text-[10px] font-black uppercase tracking-widest text-amber-400">
                                    Quotidien
                                </span>
                            </div>
                            <div className="text-sm font-semibold text-white">Reset Journalier</div>
                            <div className="text-[10px] text-zinc-500 mt-0.5">Almanax, Dopeuls, Quêtes répétables</div>
                        </div>
                        <div className="text-right">
                            <div className="text-[9px] text-zinc-500 uppercase tracking-widest mb-1 font-bold">Dans :</div>
                            <div className="text-lg font-black text-amber-300 tabular-nums">
                                {formatTimeLeft(tNextMidnight)}
                            </div>
                        </div>
                    </div>
                </div>

            </div>

            {/* Note en bas */}
            <div className="px-5 py-3 border-t border-white/5 text-[9px] text-zinc-600 flex items-center justify-center gap-1.5 bg-black/20">
                <ShieldAlert className="w-3 h-3 text-zinc-500" />
                Les durées de maintenance sont approximatives selon Ankama.
            </div>
        </div>
    );
}

"use client";

