"use client";

import { motion } from "framer-motion";
import { cn } from "@/lib/utils";
import { BarChart3, Clock, Users, Lock, CheckCircle2, XCircle, MessageSquare, ChevronRight, Crown } from "lucide-react";
import Link from "next/link";
const POLL_CATEGORIES = ["SUGGESTION", "AMELIORATION", "EVENT", "MISSION", "AUTRE"] as const;
type PollCategory = (typeof POLL_CATEGORIES)[number];

const POLL_STATUSES = ["DRAFT", "ACTIVE", "CLOSED", "CANCELLED"] as const;
type PollStatus = (typeof POLL_STATUSES)[number];
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

// Category styling config
const CATEGORY_CONFIG: Record<PollCategory, {
    label: string;
    emoji: string;
    color: string;
    bgColor: string;
    borderColor: string;
    glowColor: string;
}> = {
    SUGGESTION: {
        label: "Suggestion", emoji: "💡",
        color: "text-cyan-400", bgColor: "bg-cyan-500/10",
        borderColor: "border-cyan-500/30", glowColor: "rgba(6,182,212,0.4)",
    },
    AMELIORATION: {
        label: "Amélioration", emoji: "🔧",
        color: "text-emerald-400", bgColor: "bg-emerald-500/10",
        borderColor: "border-emerald-500/30", glowColor: "rgba(16,185,129,0.4)",
    },
    EVENT: {
        label: "Événement", emoji: "🎉",
        color: "text-amber-400", bgColor: "bg-amber-500/10",
        borderColor: "border-amber-500/30", glowColor: "rgba(245,158,11,0.4)",
    },
    MISSION: {
        label: "Mission", emoji: "🎯",
        color: "text-rose-400", bgColor: "bg-rose-500/10",
        borderColor: "border-rose-500/30", glowColor: "rgba(244,63,94,0.4)",
    },
    AUTRE: { label: "Autre", emoji: "📁", color: "text-zinc-400", bgColor: "bg-zinc-500/10", borderColor: "border-zinc-500/20", glowColor: "rgba(161, 161, 170, 0.4)" },
};

const STATUS_CONFIG: Record<PollStatus, { label: string; color: string; icon: React.ElementType }> = {
    DRAFT: { label: "Brouillon", color: "text-zinc-400", icon: Clock },
    ACTIVE: { label: "En cours", color: "text-emerald-400", icon: BarChart3 },
    CLOSED: { label: "Terminé", color: "text-amber-400", icon: CheckCircle2 },
    CANCELLED: { label: "Annulé", color: "text-red-400", icon: XCircle },
};

interface PollOption {
    id: string;
    label: string;
    emoji: string | null;
    order: number;
    _count: { votes: number };
}

interface PollCardProps {
    poll: {
        id: string;
        title: string;
        description: string | null;
        category: PollCategory;
        status: PollStatus;
        creatorName: string;
        allowMultipleVotes: boolean;
        isAnonymous: boolean;
        expiresAt: string | null;
        closedAt: string | null;
        createdAt: string;
        outcome: string | null;
        options: PollOption[];
        _count: { options: number };
    };
    guildId: string;
    index?: number;
}

export function PollCard({ poll, guildId, index = 0 }: PollCardProps) {
    const cat = CATEGORY_CONFIG[poll.category];
    const status = STATUS_CONFIG[poll.status];
    const StatusIcon = status.icon;

    const totalVotes = poll.options.reduce((sum, o) => sum + o._count.votes, 0);
    const maxVotes = Math.max(...poll.options.map(o => o._count.votes), 1);

    const isActive = poll.status === "ACTIVE";
    const timeLeft = poll.expiresAt ? getTimeLeft(poll.expiresAt) : null;

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.06, duration: 0.4, ease: "easeOut" }}
        >
            <Link href={`/dashboard/${guildId}/sondages/${poll.id}`}>
                <div className={cn(
                    "group relative overflow-hidden rounded-[2rem] border transition-all duration-500",
                    "bg-[#030303]/40 backdrop-blur-md hover:bg-[#050505]/60",
                    "hover:scale-[1.01] hover:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.6)] cursor-pointer",
                    isActive ? cat.borderColor : "border-white/5",
                )}>
                    {/* Category glow */}
                    <div
                        className="absolute -top-20 -right-20 w-48 h-48 rounded-full blur-[80px] opacity-0 group-hover:opacity-20 transition-opacity duration-1000 pointer-events-none"
                        style={{ backgroundColor: cat.glowColor }}
                    />

                    {/* Header bar */}
                    <div className={cn(
                        "flex items-center justify-between px-6 py-3.5 border-b relative z-10",
                        isActive ? "border-white/5" : "border-white/[0.03]",
                    )}>
                        <div className="flex items-center gap-2.5">
                            <span className="text-lg drop-shadow-lg">{cat.emoji}</span>
                            <span className={cn("text-[10px] font-black uppercase tracking-[0.2em]", cat.color)}>{cat.label}</span>
                        </div>
                        <div className="flex items-center gap-4">
                            {poll.isAnonymous && (
                                <TooltipProvider>
                                    <Tooltip>
                                        <TooltipTrigger asChild>
                                            <Lock className="w-4 h-4 text-zinc-600 hover:text-zinc-400 transition-colors" />
                                        </TooltipTrigger>
                                        <TooltipContent side="bottom" className="bg-zinc-900 border-white/10 text-[10px] uppercase font-bold tracking-widest">
                                            Votes anonymes
                                        </TooltipContent>
                                    </Tooltip>
                                </TooltipProvider>
                            )}
                            <div className={cn("flex items-center gap-2 text-[10px] font-black uppercase tracking-widest", status.color)}>
                                <StatusIcon className="w-3.5 h-3.5" />
                                {status.label}
                            </div>
                        </div>
                    </div>

                    {/* Body */}
                    <div className="px-6 py-7 space-y-7 relative z-10">
                        {/* Background category image with mask */}
                        <div className="absolute inset-0 z-[-1] opacity-40 group-hover:opacity-50 transition-opacity duration-700 pointer-events-none">
                            <img
                                src={`/assets/sondages/${poll.category === 'EVENT' ? 'evenement' :
                                    poll.category === 'AUTRE' ? 'autres' :
                                        poll.category.toLowerCase()
                                    }.png`}
                                alt=""
                                className="w-full h-full object-cover grayscale brightness-[0.3] contrast-[1.2] scale-105 group-hover:scale-110 transition-transform duration-[2s]"
                            />
                            <div className="absolute inset-0 bg-gradient-to-t from-[#030303] via-[#030303]/60 to-transparent" />
                        </div>

                        {poll.outcome && (
                            <div className="flex items-center gap-2 px-3.5 py-1.5 w-fit rounded-full bg-emerald-500/10 border border-emerald-500/20 backdrop-blur-md">
                                <Crown className="w-3.5 h-3.5 text-emerald-400" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Décision validée</span>
                            </div>
                        )}

                        <div>
                            <h3 className="text-white font-black text-2xl sm:text-3xl tracking-tighter group-hover:text-cyan-400 transition-colors line-clamp-2 leading-[1.05]">
                                {poll.title}
                            </h3>
                            {poll.description && (
                                <p className="text-zinc-500 text-sm mt-4 line-clamp-2 leading-relaxed font-medium max-w-[90%]">
                                    {poll.description}
                                </p>
                            )}
                        </div>

                        {/* Mini result bars */}
                        <div className="space-y-4">
                            {poll.options.slice(0, 3).map((option) => {
                                const percent = totalVotes > 0 ? (option._count.votes / totalVotes) * 100 : 0;
                                const isWinning = option._count.votes === maxVotes && totalVotes > 0;
                                return (
                                    <div key={option.id} className="relative group/option">
                                        <div className="flex items-center justify-between text-[10px] uppercase tracking-[0.2em] font-black mb-2.5 px-0.5">
                                            <span className={cn(
                                                "truncate max-w-[80%] transition-all",
                                                isWinning ? "text-white scale-105 origin-left" : "text-zinc-600 group-hover/option:text-zinc-400"
                                            )}>
                                                {option.emoji && <span className="mr-2 text-sm opacity-80">{option.emoji}</span>}
                                                {option.label}
                                            </span>
                                            <span className={cn("tabular-nums font-black", isWinning ? cat.color : "text-zinc-700")}>
                                                {Math.round(percent)}%
                                            </span>
                                        </div>
                                        <div className="h-1.5 rounded-full bg-white/[0.02] border border-white/5 overflow-hidden">
                                            <motion.div
                                                className={cn(
                                                    "h-full rounded-full relative",
                                                    isWinning ? "shadow-[0_0_15px_rgba(255,255,255,0.05)]" : "opacity-20"
                                                )}
                                                style={{
                                                    background: isWinning
                                                        ? `linear-gradient(90deg, ${cat.glowColor.replace("0.4", "1")}, ${cat.glowColor.replace("0.4", "0.6")})`
                                                        : cat.glowColor.replace("0.4", "0.3")
                                                }}
                                                initial={{ width: 0 }}
                                                animate={{ width: `${percent}%` }}
                                                transition={{ delay: index * 0.06 + 0.3, duration: 1.2, ease: [0.16, 1, 0.3, 1] }}
                                            />
                                        </div>
                                    </div>
                                );
                            })}
                            {poll.options.length > 3 && (
                                <p className="text-zinc-700 text-[9px] font-black uppercase tracking-[0.4em] text-center pt-2 italic opacity-60 group-hover:opacity-100 transition-opacity">
                                    + {poll.options.length - 3} options supplémentaires
                                </p>
                            )}
                        </div>
                    </div>

                    {/* Footer */}
                    <div className={cn(
                        "flex items-center justify-between px-6 py-4 border-t relative z-10",
                        "border-white/[0.03] bg-white/[0.01]",
                    )}>
                        <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-[10px] font-black uppercase tracking-widest text-zinc-600">
                            <span className="flex items-center gap-2">
                                <span className="opacity-40">Par</span>
                                <span className="text-zinc-400 group-hover:text-cyan-400 transition-colors decoration-cyan-500/30 underline-offset-4 decoration-dotted underline">{poll.creatorName}</span>
                            </span>
                            <div className="flex items-center gap-5">
                                <span className="flex items-center gap-2 text-zinc-500 border-l border-white/5 pl-5 first:border-0 first:pl-0">
                                    <Users className="w-3.5 h-3.5 opacity-50" />
                                    {totalVotes} <span className="opacity-40 font-bold">votes</span>
                                </span>
                                {timeLeft && isActive && (
                                    <span className="flex items-center gap-2 text-amber-500/60 border-l border-white/5 pl-5">
                                        <Clock className="w-3.5 h-3.5 opacity-50" />
                                        {timeLeft}
                                    </span>
                                )}
                            </div>
                        </div>
                        <ChevronRight className="w-5 h-5 text-zinc-800 group-hover:text-cyan-500 group-hover:translate-x-1.5 transition-all duration-300" />
                    </div>
                </div>
            </Link>
        </motion.div>
    );
}

function getTimeLeft(expiresAt: string): string {
    const now = new Date();
    const end = new Date(expiresAt);
    const diff = end.getTime() - now.getTime();
    if (diff <= 0) return "Expiré";
    const hours = Math.floor(diff / (1000 * 60 * 60));
    const days = Math.floor(hours / 24);
    if (days > 0) return `${days}j restant${days > 1 ? "s" : ""}`;
    if (hours > 0) return `${hours}h restante${hours > 1 ? "s" : ""}`;
    const mins = Math.floor(diff / (1000 * 60));
    return `${mins}min`;
}

"use client";

import { useState, useTransition, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";
import {
    Plus,
    Sparkles,
    Send,
    Clock,
    Users,
    Lock,
    Megaphone,
    Trash2,
    GripVertical,
    AtSign,
    Info
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { createPoll, acquirePollCreatorRole, getMicroStatus, releasePollCreatorRole } from "@/server/actions/poll-actions";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

interface PollCreatorProps {
    guildId: string;
    discordChannels?: { id: string; name: string }[];
    discordRoles?: { id: string; name: string; color: number }[];
    initialMicroStatus: {
        holder: { id: string; name: string; image?: string } | null;
        expiresAt?: string;
        isMicroHolder: boolean;
        isAdmin: boolean;
        isSuperAdmin: boolean;
    } | null;
    editPoll?: any; // Existing poll to edit
    trigger?: React.ReactNode; // Custom trigger button
    onSuccess?: () => void;
}

const CATEGORIES = [
    { value: "SUGGESTION", label: "💡 Suggestion", color: "text-cyan-400" },
    { value: "AMELIORATION", label: "🔧 Amélioration", color: "text-emerald-400" },
    { value: "EVENT", label: "🎉 Événement", color: "text-amber-400" },
    { value: "MISSION", label: "🎯 Mission", color: "text-red-400" },
    { value: "AUTRE", label: "📋 Autres", color: "text-violet-400" },
];

const DEFAULT_EMOJIS = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"];

export function PollCreator({
    guildId,
    discordChannels = [],
    discordRoles = [],
    initialMicroStatus,
    editPoll,
    trigger,
    onSuccess
}: PollCreatorProps) {
    const [open, setOpen] = useState(false);
    const [isPending, startTransition] = useTransition();
    const router = useRouter();

    // Micro / Droit de Parole State
    const [microStatus, setMicroStatus] = useState<{ holder: any; isMicroHolder: boolean; isAdmin?: boolean; isSuperAdmin?: boolean } | null>(initialMicroStatus || null);
    const [isAcquiring, setIsAcquiring] = useState(false);

    // Form state
    const [title, setTitle] = useState("");
    const [description, setDescription] = useState("");
    const [category, setCategory] = useState("SUGGESTION");
    const [options, setOptions] = useState([
        { label: "", emoji: "1️⃣" },
        { label: "", emoji: "2️⃣" },
    ]);
    const [allowMultipleVotes, setAllowMultipleVotes] = useState(false);
    const [isAnonymous, setIsAnonymous] = useState(false);
    const [hasExpiry, setHasExpiry] = useState(false);
    const [expiryHours, setExpiryHours] = useState(24);

    // Discord
    const [publishToDiscord, setPublishToDiscord] = useState(true);
    const [channelId, setChannelId] = useState("none");
    const [mentionEveryone, setMentionEveryone] = useState(false);
    const [discordSetup, setDiscordSetup] = useState<{ channelId: string | null } | null>(null);

    const isEdit = !!editPoll;

    useEffect(() => {
        if (editPoll) {
            setTitle(editPoll.title);
            setDescription(editPoll.description || "");
            setCategory(editPoll.category);
            setOptions(editPoll.options.map((o: any) => ({ label: o.label, emoji: o.emoji || "" })));
            setAllowMultipleVotes(editPoll.allowMultipleVotes);
            setIsAnonymous(editPoll.isAnonymous);
            setHasExpiry(!!editPoll.expiresAt);
            if (editPoll.expiresAt) {
                const hours = Math.round((new Date(editPoll.expiresAt).getTime() - new Date(editPoll.createdAt).getTime()) / (1000 * 60 * 60));
                setExpiryHours(hours > 0 ? hours : 24);
            }
        }
    }, [editPoll]);

    useEffect(() => {
        if (open) {
            refreshMicroStatus();
            const interval = setInterval(refreshMicroStatus, 10000);
            return () => clearInterval(interval);
        }
    }, [open]);

    const refreshMicroStatus = async () => {
        const [microRes, settingsRes] = await Promise.all([
            getMicroStatus(guildId),
            import("@/server/actions/poll-actions").then(m => m.getPollSettings(guildId))
        ]);

        if (microRes.success && microRes.data) {
            setMicroStatus(microRes.data);
        }
        if (settingsRes.success && settingsRes.data) {
            setDiscordSetup({ channelId: settingsRes.data.pollsNotifyChannelId });
            if (!settingsRes.data.pollsNotifyChannelId) {
                setPublishToDiscord(false);
            }
        }
    };

    const handleAcquireMicroStatus = async () => {
        setIsAcquiring(true);
        try {
            const res = await acquirePollCreatorRole(guildId);
            if (res.success) {
                toast.success("Droit de parole déverrouillé ! Vous avez 1 heure.");
                refreshMicroStatus();
                router.refresh();
            } else {
                toast.error(res.error || "Erreur d'acquisition");
            }
        } finally {
            setIsAcquiring(false);
        }
    };

    const handleReleaseMicro = async () => {
        setIsAcquiring(true);
        try {
            const res = await releasePollCreatorRole(guildId);
            if (res.success) {
                toast.success("Micro relâché !");
                refreshMicroStatus();
                router.refresh();
            } else {
                toast.error(res.error || "Erreur lors de la libération");
            }
        } finally {
            setIsAcquiring(false);
        }
    };

    const addOption = () => {
        if (options.length >= 10) return;
        setOptions([...options, { label: "", emoji: DEFAULT_EMOJIS[options.length] || "🔹" }]);
    };

    const removeOption = (index: number) => {
        if (options.length <= 2) return;
        setOptions(options.filter((_, i) => i !== index));
    };

    const updateOption = (index: number, field: "label" | "emoji", value: string) => {
        const updated = [...options];
        updated[index] = { ...updated[index], [field]: value };
        setOptions(updated);
    };

    const resetForm = () => {
        setTitle("");
        setDescription("");
        setCategory("SUGGESTION");
        setOptions([{ label: "", emoji: "1️⃣" }, { label: "", emoji: "2️⃣" }]);
        setAllowMultipleVotes(false);
        setIsAnonymous(false);
        setHasExpiry(false);
        setExpiryHours(24);
        setPublishToDiscord(true);
        setChannelId("none");
        setMentionEveryone(false);
    };

    const handleSubmit = () => {
        if (!title.trim()) return toast.error("Le titre est obligatoire");
        if (options.filter(o => o.label.trim()).length < 2) return toast.error("Minimum 2 options requises");

        const expiresAt = hasExpiry
            ? new Date(Date.now() + expiryHours * 60 * 60 * 1000).toISOString()
            : null;

        startTransition(async () => {
            const pollData = {
                guildId,
                title: title.trim(),
                description: description.trim() || undefined,
                category: category as any,
                options: options.filter(o => o.label.trim()).map(o => ({
                    label: o.label.trim(),
                    emoji: o.emoji || undefined,
                })),
                allowMultipleVotes,
                isAnonymous,
                expiresAt,
                publishToDiscord: isEdit ? false : publishToDiscord,
                discordChannelId: channelId === "none" ? undefined : channelId,
                mentionEveryone,
            };

            const res = isEdit
                ? await (import("@/server/actions/poll-actions").then(m => m.updatePoll({ ...pollData, pollId: editPoll.id })))
                : await createPoll(pollData);

            if (res.success) {
                toast.success(isEdit ? "Sondage mis à jour !" : "Sondage créé avec succès !");
                setOpen(false);
                if (!isEdit) resetForm();
                if (onSuccess) onSuccess();
                router.refresh();
            } else {
                toast.error(res.error || "Erreur");
            }
        });
    };

    const isValid = title.trim().length >= 3 && options.filter(o => o.label.trim()).length >= 2;

    return (
        <Dialog open={open} onOpenChange={(v) => { setOpen(v); if (!v && !isEdit) resetForm(); }}>
            <DialogTrigger asChild>
                {trigger || (
                    <Button
                        disabled={microStatus?.holder && !microStatus?.isMicroHolder}
                        className={cn(
                            "gap-2 transition-all font-bold uppercase tracking-wider text-[10px] h-11 px-6 rounded-xl",
                            microStatus?.holder && !microStatus?.isMicroHolder
                                ? "bg-zinc-800 text-zinc-600 border border-white/5 cursor-not-allowed"
                                : "bg-cyan-600 hover:bg-cyan-500 text-white shadow-lg shadow-cyan-900/20"
                        )}
                    >
                        {microStatus?.holder && !microStatus?.isMicroHolder ? (
                            <>
                                <Lock className="w-3.5 h-3.5" />
                                Micro occupé
                            </>
                        ) : (
                            <>
                                <Plus className="w-4 h-4" />
                                Nouveau sondage
                            </>
                        )}
                    </Button>
                )}
            </DialogTrigger>

            <DialogContent className="sm:max-w-5xl w-[95vw] max-h-[95vh] bg-zinc-950 border-white/10 p-0 overflow-y-auto flex flex-col sm:flex-row shadow-2xl scrollbar-thin scrollbar-thumb-white/10">
                {/* Side Explanation (Micro Logic) */}
                <div className="w-full sm:w-[320px] bg-zinc-900/50 border-r border-white/5 p-8 flex flex-col gap-8 shrink-0 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-cyan-500/5 blur-3xl rounded-full -mr-16 -mt-16" />

                    <div className="space-y-4 relative z-10">
                        <div className="p-3 rounded-xl bg-cyan-500/10 border border-cyan-500/20 w-fit">
                            <Lock className="w-5 h-5 text-cyan-400" />
                        </div>
                        <h3 className="text-xl font-bold text-white tracking-tight leading-tight">Droit de Parole</h3>
                        <p className="text-xs text-zinc-400 leading-relaxed">
                            Le <span className="text-cyan-400 font-bold">Droit de Parole</span> est une exclusivité d&apos;une heure pour créer un sondage.
                        </p>
                        <p className="text-xs text-zinc-400 leading-relaxed">
                            Un membre à la fois gère l&apos;attention de la guilde pour éviter la saturation.
                        </p>
                    </div>

                    <div className="mt-auto space-y-4 relative z-10">
                        {microStatus?.holder && (
                            <div className="p-4 rounded-2xl bg-white/[0.03] border border-white/5 space-y-4">
                                <div className="flex items-center gap-3">
                                    <div className="relative">
                                        {microStatus.holder.image ? (
                                            <img src={microStatus.holder.image} className="w-10 h-10 rounded-full border border-cyan-500/30 p-0.5" alt="" />
                                        ) : (
                                            <div className="w-10 h-10 rounded-full bg-zinc-800 border border-cyan-500/30 flex items-center justify-center text-cyan-400 font-bold text-xs">
                                                {microStatus.holder.name[0]}
                                            </div>
                                        )}
                                    </div>
                                    <div className="min-w-0">
                                        <p className="text-[9px] font-bold uppercase tracking-tight text-zinc-500 mb-0.5">Occupé par</p>
                                        <p className="text-sm font-bold text-white truncate">{microStatus.holder.name}</p>
                                    </div>
                                </div>
                                {microStatus.isMicroHolder && (
                                    <div className="flex flex-col gap-2">
                                        <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-cyan-500/10 text-cyan-400 text-[10px] font-bold uppercase tracking-tight border border-cyan-500/20">
                                            <Clock className="w-3.5 h-3.5" />
                                            Vous avez le micro
                                        </div>
                                        <Button
                                            onClick={handleReleaseMicro}
                                            variant="ghost"
                                            size="sm"
                                            className="h-8 w-full rounded-lg bg-white/5 hover:bg-red-500/10 text-zinc-400 hover:text-red-400 text-[10px] font-bold uppercase transition-all"
                                        >
                                            Relâcher
                                        </Button>
                                    </div>
                                )}
                            </div>
                        )}

                        {(!microStatus?.holder || microStatus?.isSuperAdmin) && !microStatus?.isMicroHolder && (
                            <Button
                                onClick={handleAcquireMicroStatus}
                                disabled={isAcquiring}
                                className={cn(
                                    "w-full h-12 rounded-xl font-bold uppercase tracking-wide text-[10px] shadow-lg transition-all",
                                    "bg-cyan-600 hover:bg-cyan-500 text-white shadow-cyan-900/10"
                                )}
                            >
                                {isAcquiring ? "Attente..." : microStatus?.holder ? "Reprendre le Micro" : "Prendre le Micro"}
                            </Button>
                        )}
                        <p className="text-[10px] text-center text-zinc-600 font-bold italic uppercase tracking-tight">
                            Libre après 1h ou publication.
                        </p>
                    </div>
                </div>

                {/* Main Form */}
                <div className="flex-1 min-w-0 p-6 sm:p-10 relative">
                    {!microStatus?.isMicroHolder && !microStatus?.isSuperAdmin && (
                        <div className="absolute inset-0 z-50 bg-zinc-950/40 backdrop-blur-[4px] flex items-center justify-center p-8 text-center">
                            <div className="max-w-xs space-y-6">
                                <div className="p-8 rounded-2xl bg-zinc-900 border border-white/5 shadow-2xl space-y-6">
                                    <div className="w-16 h-16 rounded-xl bg-cyan-500/10 flex items-center justify-center mx-auto">
                                        <Lock className="w-8 h-8 text-cyan-400" />
                                    </div>
                                    <h4 className="text-xl font-bold text-white tracking-tight px-4">Accès Restreint</h4>
                                    <p className="text-[11px] text-zinc-500 leading-relaxed">
                                        {microStatus?.holder
                                            ? <><span className="text-cyan-400 font-bold">{microStatus.holder.name}</span> a actuellement le micro. Attendez qu&apos;il se libère !</>
                                            : <>Vous devez posséder le <span className="text-cyan-400 font-bold decoration-cyan-500/30">Droit de Parole</span> pour lancer une consultation.</>
                                        }
                                    </p>
                                    <Button
                                        onClick={handleAcquireMicroStatus}
                                        disabled={isAcquiring || (!!microStatus?.holder && !microStatus?.isSuperAdmin)}
                                        className="w-full h-12 bg-cyan-600 hover:bg-cyan-500 text-white font-bold uppercase rounded-xl shadow-lg shadow-cyan-900/20 disabled:opacity-50 text-[10px]"
                                    >
                                        {microStatus?.holder && !microStatus?.isSuperAdmin ? "Micro occupé" : "Prendre le Micro"}
                                    </Button>
                                </div>
                            </div>
                        </div>
                    )}

                    <DialogHeader className="mb-8">
                        <DialogTitle className="flex items-center gap-3 text-2xl font-bold text-white tracking-tight">
                            <Sparkles className="w-6 h-6 text-cyan-400" />
                            {isEdit ? "Modifier le sondage" : "Lancer un sondage"}
                        </DialogTitle>
                    </DialogHeader>

                    <div className="space-y-10">
                        {/* Title + Category */}
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-500 ml-1">Question de la consultation</label>
                                <Input
                                    value={title}
                                    onChange={(e) => setTitle(e.target.value)}
                                    placeholder="Ex: Quelle refonte pour les grades ?"
                                    maxLength={200}
                                    className="h-14 bg-white/5 border-white/5 text-white placeholder:text-zinc-700 text-lg font-bold rounded-xl focus:ring-cyan-500/20 focus:border-cyan-500/30 transition-all shadow-inner"
                                />
                            </div>
                            <div className="space-y-3">
                                <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-500 ml-1">Thématique</label>
                                <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
                                    {CATEGORIES.map((c) => {
                                        const isSelected = category === c.value;
                                        return (
                                            <button
                                                key={c.value}
                                                type="button"
                                                onClick={() => setCategory(c.value)}
                                                className={cn(
                                                    "relative flex flex-col items-center justify-center p-3 rounded-xl border transition-all",
                                                    isSelected
                                                        ? "bg-white/10 border-white/20 shadow-lg"
                                                        : "bg-white/[0.02] border-white/5 hover:bg-white/5 opacity-60"
                                                )}
                                            >
                                                <span className="text-xl mb-1">{c.label.split(" ")[0]}</span>
                                                <span className={cn(
                                                    "text-[9px] font-bold uppercase tracking-tight text-center",
                                                    isSelected ? c.color : "text-zinc-500"
                                                )}>
                                                    {c.label.split(" ").slice(1).join(" ")}
                                                </span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>

                        {/* Options */}
                        <div className="space-y-4">
                            <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-500 ml-1">Options ({options.length}/10)</label>
                            <div className="space-y-3">
                                <AnimatePresence mode="popLayout">
                                    {options.map((opt, i) => (
                                        <motion.div
                                            key={i}
                                            layout
                                            initial={{ opacity: 0, y: 10 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            exit={{ opacity: 0, scale: 0.95 }}
                                            className="flex items-center gap-2 p-1.5 rounded-xl bg-white/[0.02] border border-white/5 focus-within:border-cyan-500/30 transition-all font-bold"
                                        >
                                            <div className="w-10 h-10 rounded-lg bg-zinc-900 border border-white/5 flex items-center justify-center shrink-0">
                                                <GripVertical className="w-4 h-4 text-zinc-700" />
                                            </div>
                                            <input
                                                value={opt.emoji}
                                                onChange={(e) => updateOption(i, "emoji", e.target.value)}
                                                className="w-10 h-10 bg-transparent border-none text-center text-xl focus:ring-0 outline-none"
                                            />
                                            <Input
                                                value={opt.label}
                                                onChange={(e) => updateOption(i, "label", e.target.value)}
                                                placeholder={`Option ${i + 1}`}
                                                maxLength={100}
                                                className="flex-1 bg-transparent border-none text-white placeholder:text-zinc-800 h-10 font-bold text-md focus-visible:ring-0"
                                            />
                                            {options.length > 2 && (
                                                <button
                                                    type="button"
                                                    onClick={() => removeOption(i)}
                                                    className="w-10 h-10 flex items-center justify-center rounded-lg text-zinc-700 hover:text-red-400 hover:bg-red-500/10 transition-all"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            )}
                                        </motion.div>
                                    ))}
                                </AnimatePresence>

                                <button
                                    type="button"
                                    onClick={addOption}
                                    disabled={options.length >= 10}
                                    className={cn(
                                        "flex items-center gap-2 w-full justify-center py-4 rounded-xl border border-dashed transition-all",
                                        options.length >= 10
                                            ? "border-white/5 opacity-20"
                                            : "border-white/10 text-zinc-500 hover:text-cyan-400 hover:border-cyan-500/30 bg-white/[0.01]"
                                    )}
                                >
                                    <Plus className="w-4 h-4" />
                                    <span className="text-[10px] font-bold uppercase tracking-widest">
                                        {options.length >= 10 ? "Maximum 10 options" : "Ajouter un choix"}
                                    </span>
                                </button>
                            </div>
                        </div>

                        {/* Settings Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="p-6 rounded-2xl bg-white/[0.02] border border-white/5 space-y-6">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2.5 rounded-xl bg-purple-500/10">
                                            <Users className="w-4 h-4 text-purple-400" />
                                        </div>
                                        <div>
                                            <p className="text-[11px] font-bold text-white uppercase tracking-tight">Votes multiples</p>
                                            <p className="text-[9px] text-zinc-500 font-medium tracking-tight">Plusieurs choix possibles</p>
                                        </div>
                                    </div>
                                    <Switch checked={allowMultipleVotes} onCheckedChange={setAllowMultipleVotes} className="scale-90" />
                                </div>

                                <div className="space-y-4">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="p-2.5 rounded-xl bg-amber-500/10">
                                                <Clock className="w-4 h-4 text-amber-400" />
                                            </div>
                                            <div>
                                                <p className="text-[11px] font-bold text-white uppercase tracking-tight">Expiration</p>
                                                <p className="text-[9px] text-zinc-500 font-medium tracking-tight">Fin automatique</p>
                                            </div>
                                        </div>
                                        <Switch checked={hasExpiry} onCheckedChange={setHasExpiry} className="scale-90" />
                                    </div>

                                    <AnimatePresence mode="wait">
                                        {hasExpiry && (
                                            <motion.div
                                                initial={{ opacity: 0, height: 0 }}
                                                animate={{ opacity: 1, height: "auto" }}
                                                exit={{ opacity: 0, height: 0 }}
                                                className="overflow-hidden"
                                            >
                                                <div className="grid grid-cols-3 gap-2 p-1 rounded-xl bg-zinc-900/80 border border-white/5 mt-3">
                                                    {[
                                                        { value: 24, label: "24h", emoji: "⏳" },
                                                        { value: 48, label: "48h", emoji: "⌛" },
                                                        { value: 168, label: "7j", emoji: "📅" }
                                                    ].map((opt) => (
                                                        <button
                                                            key={opt.value}
                                                            type="button"
                                                            onClick={() => setExpiryHours(opt.value)}
                                                            className={cn(
                                                                "relative py-3 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all",
                                                                expiryHours === opt.value
                                                                    ? "text-cyan-400"
                                                                    : "text-zinc-600 hover:text-zinc-400 hover:bg-white/5"
                                                            )}
                                                        >
                                                            {expiryHours === opt.value && (
                                                                <motion.div
                                                                    layoutId="expiry-bg"
                                                                    className="absolute inset-0 bg-cyan-500/10 border border-cyan-500/20 rounded-lg"
                                                                    transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
                                                                />
                                                            )}
                                                            <span className="relative z-10 flex flex-col items-center gap-1">
                                                                <span className="text-sm opacity-80">{opt.emoji}</span>
                                                                <span>{opt.label}</span>
                                                            </span>
                                                        </button>
                                                    ))}
                                                </div>
                                            </motion.div>
                                        )}
                                    </AnimatePresence>
                                </div>
                            </div>

                            <div className="p-6 rounded-2xl bg-[#5865F2]/5 border border-[#5865F2]/10 space-y-6">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2.5 rounded-xl bg-[#5865F2]/20">
                                            <Megaphone className="w-4 h-4 text-[#5865F2]" />
                                        </div>
                                        <div>
                                            <p className="text-[11px] font-bold text-white uppercase tracking-tight">Annonce Discord</p>
                                            <p className="text-[9px] text-zinc-500 font-medium tracking-tight">Alerte interactive</p>
                                        </div>
                                    </div>
                                    <Switch
                                        disabled={!discordSetup?.channelId}
                                        checked={publishToDiscord}
                                        onCheckedChange={setPublishToDiscord}
                                        className="scale-90"
                                    />
                                </div>

                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2.5 rounded-xl bg-zinc-800">
                                            <AtSign className="w-4 h-4 text-zinc-500" />
                                        </div>
                                        <div>
                                            <p className="text-[11px] font-bold text-white uppercase tracking-tight">@everyone</p>
                                            <p className="text-[9px] text-zinc-600 font-medium tracking-tight">Notification globale</p>
                                        </div>
                                    </div>
                                    <Switch disabled={!publishToDiscord} checked={mentionEveryone} onCheckedChange={setMentionEveryone} className="scale-90" />
                                </div>

                                {!discordSetup?.channelId && (
                                    <div className="flex items-start gap-3 p-4 rounded-xl bg-[#5865F2]/5 border border-[#5865F2]/10 animate-in fade-in slide-in-from-top-2">
                                        <Info className="w-4 h-4 text-[#5865F2]/80 shrink-0 mt-0.5" />
                                        <p className="text-[10px] font-bold text-[#5865F2]/80 uppercase tracking-tight leading-relaxed">
                                            Le salon Discord n&apos;est pas configuré. Activez-le dans l&apos;admin pour publier vos sondages.
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="pt-8 border-t border-white/5">
                            <Button
                                onClick={handleSubmit}
                                disabled={isPending || !isValid || !microStatus?.isMicroHolder}
                                className={cn(
                                    "w-full h-12 gap-3 text-xs font-bold uppercase tracking-widest transition-all",
                                    "bg-cyan-600 hover:bg-cyan-500 text-white shadow-lg shadow-cyan-900/10 rounded-xl",
                                    "disabled:opacity-20 translate-y-0 active:translate-y-0.5"
                                )}
                            >
                                {isPending ? (
                                    <>
                                        <Clock className="w-4 h-4 animate-spin" />
                                        Publication...
                                    </>
                                ) : (
                                    <>
                                        <Send className="w-4 h-4" />
                                        {isEdit ? "Enregistrer les modifications" : "Publier le sondage"}
                                    </>
                                )}
                            </Button>
                        </div>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useTransition, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";
import {
    BarChart3, Clock, Users, Lock, CheckCircle2, XCircle, ArrowLeft,
    Crown, Trash2, AlertTriangle, Edit2, Megaphone, Send, Info
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { castVote, closePoll, deletePoll } from "@/server/actions/poll-actions";
import { PollCreator } from "./poll-creator";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";

type PollCategory = "SUGGESTION" | "AMELIORATION" | "EVENT" | "MISSION" | "AUTRE";
type PollStatus = "DRAFT" | "ACTIVE" | "CLOSED" | "CANCELLED";

const CATEGORY_CONFIG: Record<string, {
    label: string; emoji: string; color: string;
    gradient: string; glowColor: string; barColor: string;
}> = {
    SUGGESTION: { label: "Suggestion", emoji: "💡", color: "text-cyan-400", gradient: "from-cyan-500 to-cyan-600", glowColor: "rgba(6,182,212,0.4)", barColor: "bg-cyan-500" },
    AMELIORATION: { label: "Amélioration", emoji: "🔧", color: "text-emerald-400", gradient: "from-emerald-500 to-emerald-600", glowColor: "rgba(16,185,129,0.4)", barColor: "bg-emerald-500" },
    EVENT: { label: "Événement", emoji: "🎉", color: "text-amber-400", gradient: "from-amber-500 to-amber-600", glowColor: "rgba(245,158,11,0.4)", barColor: "bg-amber-500" },
    MISSION: { label: "Mission", emoji: "🎯", color: "text-rose-400", gradient: "from-rose-500 to-rose-600", glowColor: "rgba(244,63,94,0.4)", barColor: "bg-rose-500" },
    AUTRE: { label: "Autres", emoji: "📋", color: "text-indigo-400", gradient: "from-indigo-500 to-indigo-600", glowColor: "rgba(99,102,241,0.4)", barColor: "bg-indigo-500" },
};

interface PollOption {
    id: string;
    label: string;
    emoji: string | null;
    order: number;
    voteCount: number;
    votes: { id: string; voterId: string; voterName: string; createdAt: string }[];
}

interface PollDetailProps {
    poll: {
        id: string;
        title: string;
        description: string | null;
        category: PollCategory;
        status: PollStatus;
        creatorName: string;
        creatorId: string;
        allowMultipleVotes: boolean;
        isAnonymous: boolean;
        expiresAt: string | null;
        closedAt: string | null;
        createdAt: string;
        discordMessageId: string | null;
        discordChannelId: string | null;
        outcome: string | null;
        options: PollOption[];
        userVotedOptionIds: string[];
        totalVotes: number;
    };
    guildId: string;
    isAdmin: boolean;
    currentProfileId?: string;
    hasMicro?: boolean;
    isDiscordConfigured?: boolean;
}

export function PollDetail({ poll, guildId, isAdmin, currentProfileId, hasMicro, isDiscordConfigured }: PollDetailProps) {
    const [isPending, startTransition] = useTransition();
    const [votedOptionIds, setVotedOptionIds] = useState<string[]>(poll.userVotedOptionIds);
    const [localOptions, setLocalOptions] = useState(poll.options);
    const [localTotalVotes, setLocalTotalVotes] = useState(poll.totalVotes);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const router = useRouter();

    const cat = CATEGORY_CONFIG[poll.category];
    const isActive = poll.status === "ACTIVE";
    const isCreator = currentProfileId === poll.creatorId;
    const canManage = isAdmin || isCreator;
    const maxVotes = Math.max(...localOptions.map(o => o.voteCount), 1);

    const handleVote = useCallback((optionId: string) => {
        if (!isActive) return;

        startTransition(async () => {
            const res = await castVote(guildId, optionId);
            if (res.success) {
                const data = res.data as { action: string } | undefined;
                const action = data?.action;
                if (action === "voted") {
                    toast.success("Vote enregistré !");
                    if (!poll.allowMultipleVotes) {
                        setLocalOptions(prev => prev.map(o => {
                            if (votedOptionIds.includes(o.id) && o.id !== optionId) {
                                return { ...o, voteCount: Math.max(0, o.voteCount - 1) };
                            }
                            if (o.id === optionId) {
                                return { ...o, voteCount: o.voteCount + 1 };
                            }
                            return o;
                        }));
                        setLocalTotalVotes(prev => votedOptionIds.length > 0 ? prev : prev + 1);
                        setVotedOptionIds([optionId]);
                    } else {
                        setLocalOptions(prev => prev.map(o =>
                            o.id === optionId ? { ...o, voteCount: o.voteCount + 1 } : o
                        ));
                        setLocalTotalVotes(prev => prev + 1);
                        setVotedOptionIds(prev => [...prev, optionId]);
                    }
                } else {
                    toast.info("Vote retiré");
                    setLocalOptions(prev => prev.map(o =>
                        o.id === optionId ? { ...o, voteCount: Math.max(0, o.voteCount - 1) } : o
                    ));
                    setLocalTotalVotes(prev => Math.max(0, prev - 1));
                    setVotedOptionIds(prev => prev.filter(id => id !== optionId));
                }
                router.refresh();
            } else {
                toast.error(res.error || "Erreur lors du vote");
            }
        });
    }, [guildId, isActive, poll.allowMultipleVotes, votedOptionIds, router]);

    const [outcomeText, setOutcomeText] = useState("");
    const [notifyDiscord, setNotifyDiscord] = useState(!!isDiscordConfigured);
    const [showOutcomeModal, setShowOutcomeModal] = useState(false);

    const handleClose = (outcome?: string) => {
        startTransition(async () => {
            const res = await closePoll(guildId, poll.id, outcome, notifyDiscord);
            if (res.success) {
                toast.success(outcome ? "Sondage clôturé avec décision !" : "Sondage fermé !");
                setShowOutcomeModal(false);
                router.refresh();
            } else {
                toast.error(res.error || "Erreur");
            }
        });
    };

    const handleDelete = () => {
        startTransition(async () => {
            const res = await deletePoll(guildId, poll.id);
            if (res.success) {
                toast.success("Sondage supprimé !");
                router.push(`/dashboard/${guildId}/sondages`);
            } else {
                toast.error(res.error || "Erreur");
            }
        });
    };

    return (
        <div className="max-w-4xl mx-auto space-y-12">
            {/* Back Hero */}
            <div className="flex items-center justify-between px-2">
                <Link
                    href={`/dashboard/${guildId}/sondages`}
                    className="flex items-center gap-3 text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 hover:text-white transition-all group"
                >
                    <div className="h-8 w-8 rounded-full border border-white/5 bg-zinc-900/50 flex items-center justify-center group-hover:bg-white/5 transition-all group-hover:-translate-x-1">
                        <ArrowLeft className="h-4 w-4" />
                    </div>
                    Retour à la liste
                </Link>

                <div className="flex items-center gap-4">
                    {canManage && isActive && (isAdmin || (isCreator && hasMicro)) && (
                        <PollCreator
                            guildId={guildId}
                            editPoll={poll}
                            initialMicroStatus={null}
                            trigger={
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-8 gap-2 text-[10px] font-black uppercase tracking-widest text-zinc-500 hover:text-cyan-400 hover:bg-cyan-500/5"
                                >
                                    <Edit2 className="w-3 h-3" />
                                    Modifier
                                </Button>
                            }
                        />
                    )}
                    {canManage && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setShowDeleteConfirm(true)}
                            className="h-8 gap-2 text-[10px] font-black uppercase tracking-widest text-zinc-500 hover:text-red-400 hover:bg-red-500/5 underline decoration-red-500/30 decoration-dotted"
                        >
                            <Trash2 className="w-3 h-3" />
                            Supprimer
                        </Button>
                    )}
                </div>
            </div>

            {/* Main Content Card */}
            <div className="relative">
                {/* Visual Accent */}
                <div
                    className="absolute -top-[10%] -right-[5%] w-[40%] h-[60%] blur-[120px] opacity-20 pointer-events-none rounded-full"
                    style={{ backgroundColor: cat.glowColor }}
                />

                <div className="relative overflow-hidden rounded-[2.5rem] border border-white/5 bg-[#030303]/60 backdrop-blur-md shadow-2xl">
                    <div className="p-8 md:p-12 space-y-10">
                        {/* Status + Category Row */}
                        <div className="flex items-center justify-between flex-wrap gap-4">
                            <div className={cn(
                                "flex items-center gap-3 px-4 py-2 rounded-2xl border text-[10px] font-black uppercase tracking-[0.15em]",
                                cat.color,
                                "bg-white/[0.03] border-white/5"
                            )}>
                                <span className="text-sm">{cat.emoji}</span>
                                {cat.label}
                            </div>

                            <div className="flex items-center gap-2">
                                {poll.isAnonymous && (
                                    <TooltipProvider>
                                        <Tooltip>
                                            <TooltipTrigger className="bg-white/[0.03] border border-white/5 p-2 rounded-xl text-zinc-500 hover:text-zinc-300 transition-colors">
                                                <Lock className="w-4 h-4" />
                                            </TooltipTrigger>
                                            <TooltipContent className="bg-zinc-950 border-white/10 text-[10px] uppercase font-bold tracking-widest">Votes anonymes</TooltipContent>
                                        </Tooltip>
                                    </TooltipProvider>
                                )}
                                {poll.allowMultipleVotes && (
                                    <TooltipProvider>
                                        <Tooltip>
                                            <TooltipTrigger className="bg-white/[0.03] border border-white/5 p-2 rounded-xl text-zinc-500 hover:text-zinc-300 transition-colors">
                                                <Users className="w-4 h-4" />
                                            </TooltipTrigger>
                                            <TooltipContent className="bg-zinc-950 border-white/10 text-[10px] uppercase font-bold tracking-widest">Multi-vote activé</TooltipContent>
                                        </Tooltip>
                                    </TooltipProvider>
                                )}
                                <div className={cn(
                                    "px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-lg",
                                    isActive ? "bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 shadow-emerald-900/10" :
                                        poll.status === "CLOSED" ? "bg-amber-500/10 border border-amber-500/20 text-amber-400 shadow-amber-900/10" :
                                            "bg-red-500/10 border border-red-500/20 text-red-400 shadow-red-900/10"
                                )}>
                                    {isActive ? "Sondage Ouvert" : poll.status === "CLOSED" ? "Archivé / Terminé" : "Consultation Annulée"}
                                </div>
                            </div>
                        </div>

                        {/* Title & Description */}
                        <div className="space-y-6">
                            <h1 className="text-4xl md:text-5xl font-black text-white tracking-tighter leading-[0.95] max-w-2xl">
                                {poll.title}
                            </h1>
                            {poll.description && (
                                <p className="text-zinc-400 text-base md:text-lg leading-relaxed max-w-3xl font-medium">
                                    {poll.description}
                                </p>
                            )}
                        </div>

                        {/* Meta Grid */}
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 pt-4 border-t border-white/[0.03]">
                            <div className="space-y-1">
                                <p className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest">Initiateur</p>
                                <p className="text-sm text-zinc-300 font-bold flex items-center gap-2 group cursor-default">
                                    <span className="w-5 h-5 rounded-full bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                                        <Crown className="w-3 h-3 text-amber-500" />
                                    </span>
                                    <span className="group-hover:text-cyan-400 transition-colors">{poll.creatorName}</span>
                                </p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest">Date</p>
                                <p className="text-sm text-zinc-300 font-bold flex items-center gap-2">
                                    <Clock className="w-4 h-4 text-zinc-700" />
                                    {new Date(poll.createdAt).toLocaleDateString("fr-FR", { day: "numeric", month: "short", year: "numeric" })}
                                </p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest">Participation</p>
                                <p className="text-sm text-zinc-300 font-bold flex items-center gap-2">
                                    <BarChart3 className="w-4 h-4 text-zinc-700" />
                                    {localTotalVotes} votant{localTotalVotes !== 1 ? "s" : ""}
                                </p>
                            </div>
                            {poll.expiresAt && isActive && (
                                <div className="space-y-1">
                                    <p className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest">Status temps</p>
                                    <p className="text-sm text-amber-500/80 font-bold border-l-2 border-amber-500/30 pl-3">
                                        Fin {new Date(poll.expiresAt).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Outcome Display (Professional) */}
            <AnimatePresence>
                {poll.outcome && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.98, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        className="bg-emerald-500/5 border border-emerald-500/10 rounded-[2.5rem] p-8 md:p-12 relative overflow-hidden shadow-2xl shadow-emerald-950/20"
                    >
                        <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none">
                            <CheckCircle2 className="w-32 h-32 text-emerald-400" />
                        </div>

                        <div className="max-w-3xl relative z-10">
                            <div className="flex items-center gap-4 mb-6">
                                <div className="bg-emerald-500/20 p-3 rounded-2xl border border-emerald-500/30">
                                    <Crown className="w-6 h-6 text-emerald-400" />
                                </div>
                                <div>
                                    <h4 className="text-emerald-400 font-black tracking-widest text-[10px] uppercase">Décision Officielle</h4>
                                    <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-tighter">Status: Clôturé avec succès</p>
                                </div>
                            </div>
                            <p className="text-zinc-100 text-xl md:text-2xl leading-relaxed italic font-bold max-w-[90%] decoration-emerald-500/20 underline decoration-double underline-offset-8">
                                &quot;{poll.outcome}&quot;
                            </p>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Voting Section */}
            <div className="grid grid-cols-1 gap-4">
                <div className="flex items-center justify-between mb-4 px-4">
                    <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-zinc-600">Propositions et resultats</h2>
                    {isActive && (
                        <span className="flex items-center gap-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-cyan-500 animate-pulse" />
                            <span className="text-[10px] font-bold text-cyan-400 uppercase tracking-widest">En direct</span>
                        </span>
                    )}
                </div>

                <div className="space-y-4">
                    {localOptions.map((option, i) => {
                        const percent = localTotalVotes > 0 ? (option.voteCount / localTotalVotes) * 100 : 0;
                        const isVoted = votedOptionIds.includes(option.id);
                        const isWinning = option.voteCount === maxVotes && localTotalVotes > 0;

                        return (
                            <motion.button
                                key={option.id}
                                onClick={() => handleVote(option.id)}
                                disabled={!isActive || isPending}
                                initial={{ opacity: 0, y: 15 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: i * 0.05 }}
                                className={cn(
                                    "w-full group relative overflow-hidden rounded-3xl border transition-all duration-500 text-left",
                                    "bg-zinc-900/40 backdrop-blur-sm",
                                    isActive
                                        ? "hover:bg-zinc-900/80 cursor-pointer"
                                        : "cursor-default opacity-80",
                                    isVoted
                                        ? "border-cyan-500/30 shadow-lg shadow-cyan-900/10"
                                        : "border-white/5"
                                )}
                            >
                                {/* Results fill */}
                                <div className="absolute inset-0">
                                    <motion.div
                                        className={cn(
                                            "h-full transition-colors",
                                            isVoted ? "bg-cyan-500/10" : "bg-white/[0.03]"
                                        )}
                                        initial={{ width: 0 }}
                                        animate={{ width: `${percent}%` }}
                                        transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1], delay: i * 0.05 + 0.2 }}
                                    />
                                    {isWinning && localTotalVotes > 0 && (
                                        <div className="absolute inset-0 border-2 border-amber-500/10 rounded-3xl pointer-events-none" />
                                    )}
                                </div>

                                <div className="relative z-10 flex items-center justify-between p-6">
                                    <div className="flex items-center gap-6 flex-1 min-w-0">
                                        {/* Status Icon / Index */}
                                        <div className={cn(
                                            "w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-500 shrink-0",
                                            isVoted
                                                ? "bg-cyan-500 text-white shadow-lg shadow-cyan-500/20 scale-110"
                                                : "bg-white/[0.05] text-zinc-600 group-hover:bg-white/10"
                                        )}>
                                            {isVoted ? <CheckCircle2 className="w-6 h-6" /> : <div className="text-xl font-black">{option.emoji || (i + 1)}</div>}
                                        </div>

                                        <div className="min-w-0">
                                            <p className={cn(
                                                "text-lg font-black transition-colors truncate",
                                                isVoted ? "text-white" : "text-zinc-300 group-hover:text-white"
                                            )}>
                                                {option.label}
                                            </p>

                                            {/* Voters preview */}
                                            {!poll.isAnonymous && option.votes.length > 0 && (
                                                <div className="flex items-center gap-2 mt-2">
                                                    <div className="flex -space-x-1.5">
                                                        {option.votes.slice(0, 4).map((v) => (
                                                            <div key={v.id} className="w-5 h-5 rounded-full bg-zinc-800 border-2 border-zinc-900 flex items-center justify-center text-[8px] font-black text-zinc-400 uppercase">
                                                                {v.voterName.charAt(0)}
                                                            </div>
                                                        ))}
                                                    </div>
                                                    {option.votes.length > 4 && (
                                                        <span className="text-[9px] text-zinc-600 font-black uppercase tracking-tighter">
                                                            +{option.votes.length - 4} autres
                                                        </span>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Stats block */}
                                    <div className="flex items-center gap-6 shrink-0 md:pl-8 border-l border-white/[0.03]">
                                        <div className="text-right">
                                            <div className={cn(
                                                "text-2xl font-black tabular-nums leading-none tracking-tighter",
                                                isWinning ? (isVoted ? "text-cyan-400" : "text-amber-400") : "text-zinc-700"
                                            )}>
                                                {Math.round(percent)}%
                                            </div>
                                            <p className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest mt-1">
                                                {option.voteCount} vote{option.voteCount !== 1 ? "s" : ""}
                                            </p>
                                        </div>
                                        {isWinning && localTotalVotes > 0 && (
                                            <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/20">
                                                <Crown className="w-5 h-5 text-amber-500/60" />
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </motion.button>
                        );
                    })}
                </div>
            </div>

            {/* Footer Admin Actions */}
            {canManage && isActive && (
                <div className="pt-12 border-t border-white/5">
                    <div className="flex flex-col sm:flex-row items-center justify-between gap-6 bg-zinc-900/40 p-10 rounded-[2.5rem] border border-white/5">
                        <div className="space-y-2 text-center sm:text-left">
                            <h3 className="text-white font-black text-xl tracking-tight">Fin de consultation ?</h3>
                            <p className="text-zinc-500 text-[11px] font-medium max-w-xs">
                                Clôturez le sondage pour valider une décision officielle et notifier les membres sur Discord.
                            </p>
                        </div>

                        <div className="flex gap-4">
                            <Dialog open={showOutcomeModal} onOpenChange={setShowOutcomeModal}>
                                <DialogTrigger asChild>
                                    <Button
                                        className="h-14 px-8 rounded-2xl bg-emerald-600 hover:bg-emerald-500 text-white font-black uppercase tracking-widest text-[11px] shadow-lg shadow-emerald-900/20 gap-3"
                                    >
                                        <CheckCircle2 className="w-5 h-5" />
                                        Clôturer avec décision
                                    </Button>
                                </DialogTrigger>
                                <DialogContent className="bg-zinc-950 border-white/10 max-w-xl p-8 rounded-[2rem]">
                                    <DialogHeader className="mb-6">
                                        <DialogTitle className="flex items-center gap-4 text-emerald-400 text-2xl font-black tracking-tighter">
                                            <Megaphone className="w-8 h-8" />
                                            Acter la décision
                                        </DialogTitle>
                                    </DialogHeader>

                                    <div className="space-y-8">
                                        <div className="space-y-3">
                                            <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 ml-1">Conclusion de la guilde</Label>
                                            <Textarea
                                                placeholder="Ex: Suite aux votes, nous lançons l'extension du coffre dès demain !"
                                                value={outcomeText}
                                                onChange={(e) => setOutcomeText(e.target.value)}
                                                className="bg-zinc-900/80 border-white/5 focus:border-emerald-500/30 min-h-[160px] rounded-2xl p-4 text-white font-medium text-base resize-none"
                                            />
                                        </div>

                                        <div className="p-6 rounded-2xl bg-[#5865F2]/5 border border-[#5865F2]/10 flex items-center justify-between">
                                            <div className="flex items-center gap-4">
                                                <div className="bg-[#5865F2]/20 p-3 rounded-xl">
                                                    <Megaphone className="w-5 h-5 text-[#5865F2]" />
                                                </div>
                                                <div>
                                                    <p className="text-sm font-black text-white uppercase tracking-tight">Annonce Discord</p>
                                                    <p className="text-[10px] text-zinc-500">Notifier tous les membres instantanément</p>
                                                </div>
                                            </div>
                                            <Switch
                                                disabled={!isDiscordConfigured}
                                                checked={notifyDiscord}
                                                onCheckedChange={setNotifyDiscord}
                                                className="data-[state=checked]:bg-[#5865F2]"
                                            />
                                        </div>

                                        {!isDiscordConfigured && (
                                            <div className="flex items-start gap-3 p-4 rounded-xl bg-amber-500/5 border border-amber-500/10 animate-in fade-in slide-in-from-top-2">
                                                <Info className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
                                                <p className="text-[10px] font-bold text-amber-500/80 uppercase tracking-tight leading-relaxed">
                                                    Le salon Discord pour les sondages n&apos;est pas configuré. L&apos;annonce ne sera pas envoyée.
                                                </p>
                                            </div>
                                        )}

                                        <div className="grid grid-cols-2 gap-4">
                                            <Button
                                                variant="outline"
                                                onClick={() => handleClose()}
                                                disabled={isPending}
                                                className="h-14 rounded-2xl border-white/5 text-zinc-500 hover:text-white uppercase font-black text-[10px] tracking-widest"
                                            >
                                                Fermer sans texte
                                            </Button>
                                            <Button
                                                onClick={() => handleClose(outcomeText)}
                                                disabled={isPending || !outcomeText.trim()}
                                                className="h-14 rounded-2xl bg-emerald-600 hover:bg-emerald-500 text-white shadow-xl shadow-emerald-950/40 uppercase font-black text-[10px] tracking-widest gap-2"
                                            >
                                                {isPending ? "Publication..." : <>Valider <Send className="w-4 h-4" /></>}
                                            </Button>
                                        </div>
                                    </div>
                                </DialogContent>
                            </Dialog>
                        </div>
                    </div>
                </div>
            )}

            {/* Delete Confirmation */}
            <Dialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
                <DialogContent className="bg-zinc-950 border-white/10 max-w-md rounded-[2rem]">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-3 text-red-400 font-black text-xl">
                            <AlertTriangle className="w-6 h-6" />
                            Suppression Définitive
                        </DialogTitle>
                    </DialogHeader>
                    <div className="space-y-6 pt-4">
                        <p className="text-zinc-400 text-sm leading-relaxed font-medium">
                            Vous êtes sur le point de supprimer <span className="text-white font-bold">&quot;{poll.title}&quot;</span>. 
                            Cette action effacera également les votes et l&apos;embed Discord associé.
                        </p>
                        <div className="grid grid-cols-2 gap-4">
                            <Button variant="ghost" onClick={() => setShowDeleteConfirm(false)} className="h-12 rounded-xl text-zinc-500 hover:text-white uppercase font-black text-[10px] tracking-widest">
                                Annuler
                            </Button>
                            <Button
                                onClick={handleDelete}
                                disabled={isPending}
                                className="h-12 rounded-xl bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 uppercase font-black text-[10px] tracking-widest"
                            >
                                {isPending ? "..." : "Confirmer"}
                            </Button>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import {
    BarChart3,
    Filter,
    X,
    ArrowUpDown,
    TrendingUp,
    Clock,
    CheckCircle,
    Mic2,
    Timer,
    LayoutGrid,
    ListFilter,
    ChevronRight,
    History,
    Info,
    AlertTriangle
} from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter,
} from "@/components/ui/dialog";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { Badge } from "@/components/ui/badge";
import { PollCard } from "./poll-card";
import { EmptyState } from "@/components/ui/empty-state";
import { cn } from "@/lib/utils";
import { getMicroStatus, acquirePollCreatorRole, releasePollCreatorRole } from "@/server/actions/poll-actions";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";

interface PollListProps {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    polls: any[];
    guildId: string;
    initialStatus?: StatusFilter;
}

type SortKey = "newest" | "oldest" | "most_votes" | "most_active";
type CategoryFilter = "ALL" | "SUGGESTION" | "AMELIORATION" | "EVENT" | "MISSION" | "AUTRE";
type StatusFilter = "ALL" | "ACTIVE" | "CLOSED" | "CANCELLED";

const SORT_OPTIONS: { value: SortKey; label: string; icon: React.ElementType }[] = [
    { value: "most_active", label: "En cours d'abord", icon: CheckCircle },
    { value: "newest", label: "Plus récents", icon: Clock },
    { value: "oldest", label: "Plus anciens", icon: Clock },
    { value: "most_votes", label: "Plus votés", icon: TrendingUp },
];

const CATEGORY_FILTERS: { value: CategoryFilter; label: string; emoji: string }[] = [
