    { value: "AMELIORATION", label: "Améliorations", emoji: "🔧" },
    { value: "EVENT", label: "Événements", emoji: "🎉" },
    { value: "MISSION", label: "Missions", emoji: "🎯" },
    { value: "AUTRE", label: "Autres", emoji: "📋" },
];

const STATUS_FILTERS: { value: StatusFilter; label: string }[] = [
