export function CreateRunButton({ guildId, isDiscordConfigured }: { guildId: string; isDiscordConfigured?: boolean }) {
    const [open, setOpen] = useState(false);
    const [mode, setMode] = useState<"standard" | "epreuve">("standard");

    // Standard mode
    const [difficulty, setDifficulty] = useState<DifficultyKey>("REVE_III");
    const [objectives, setObjectives] = useState<ObjectiveKey[]>([]);

    // Épreuve mode
    const [selectedEpreuve, setSelectedEpreuve] = useState<EpreuveCode | null>(null);

    // Shared
    const [publishToDiscord, setPublishToDiscord] = useState(!!isDiscordConfigured);
    const [isScheduled, setIsScheduled] = useState(false);
    const [scheduledDate, setScheduledDate] = useState<Date | undefined>(new Date());
    const [scheduledTime, setScheduledTime] = useState("20:00");
    const [error, setError] = useState<string | null>(null);
    const [rateLimitReset, setRateLimitReset] = useState<number | null>(null); // timestamp ms
    const [countdown, setCountdown] = useState<string | null>(null);
    const [mentionRoleId, setMentionRoleId] = useState<string | null>(null);
    const [discordRoles, setDiscordRoles] = useState<{ id: string, name: string, color: string }[]>([]);
    const [isLoadingRoles, setIsLoadingRoles] = useState(false);
    const [roleOpen, setRoleOpen] = useState(false);
    const router = useRouter();
    const [isPending, startTransition] = useTransition();

    // Countdown timer tick
    useEffect(() => {
        if (!rateLimitReset) { setCountdown(null); return; }
        const tick = () => {
            const remaining = rateLimitReset - Date.now();
            if (remaining <= 0) { setRateLimitReset(null); setCountdown(null); setError(null); return; }
            const m = Math.floor(remaining / 60000);
            const s = Math.floor((remaining % 60000) / 1000);
            setCountdown(m > 0 ? `${m}m ${s.toString().padStart(2, "0")}s` : `${s}s`);
        };
        tick();
        const id = setInterval(tick, 1000);
        return () => clearInterval(id);
    }, [rateLimitReset]);

    // Fetch Discord Roles
    useEffect(() => {
        if (open && publishToDiscord && discordRoles.length === 0) {
            setIsLoadingRoles(true);
            getDiscordRolesAction(guildId)
                .then(res => {
                    if (res.success && res.roles) {
                        setDiscordRoles(res.roles.filter(r => r.name !== "@everyone") as any);
                    }
                })
                .catch(console.error)
                .finally(() => setIsLoadingRoles(false));
        }
    }, [open, publishToDiscord, guildId, discordRoles.length]);

    const handleCreate = () => {
        if (mode === "standard") {
            if (objectives.length === 0) {
                setError("Veuillez sélectionner au moins un objectif.");
                return;
            }
            setError(null);
            startTransition(async () => {
                let scheduledAt: Date | null = null;
                if (isScheduled && scheduledDate) {
                    const [hours, minutes] = scheduledTime.split(":").map(Number);
                    scheduledAt = new Date(scheduledDate);
                    scheduledAt.setHours(hours, minutes, 0, 0);
                }

                const result = await createDreamRun(guildId, {
                    difficulty,
                    objectives, 
                    publishToDiscord,
                    scheduledAt,
                    mentionRoleId
                });
                if (result.success) {
                    toast.success("Run créée avec succès !");
                    setOpen(false);
                    setObjectives([]);
                    router.refresh();
                } else if (result.resetAt) {
                    setRateLimitReset(result.resetAt);
                    toast.error("Limite atteinte", { description: "Tu as créé trop de runs récemment. Patiente un peu." });
                } else {
                    setError(result.error || "Erreur inconnue");
                }
            });
        } else {
            // Épreuve mode
            if (!selectedEpreuve) {
                setError("Veuillez sélectionner une épreuve.");
                return;
            }
            const epreuve = EPREUVES_SONGE.find(e => e.code === selectedEpreuve)!;
            setError(null);
            startTransition(async () => {
                let scheduledAt: Date | null = null;
                if (isScheduled && scheduledDate) {
                    const [hours, minutes] = scheduledTime.split(":").map(Number);
                    scheduledAt = new Date(scheduledDate);
                    scheduledAt.setHours(hours, minutes, 0, 0);
                }

                const result = await createDreamRun(guildId, {
                    difficulty: epreuve.difficulty,
                    objectives: ["SUCCES_NO_ACHAT"],
                    publishToDiscord,
                    epreuveCode: epreuve.code,
                    scheduledAt,
                    mentionRoleId
                });
                if (result.success) {
                    toast.success(`Épreuve ${epreuve.code} lancée !`);
                    setOpen(false);
                    setSelectedEpreuve(null);
                    router.refresh();
                } else if (result.resetAt) {
                    setRateLimitReset(result.resetAt);
                    toast.error("Limite atteinte", { description: "Tu as créé trop de runs récemment. Patiente un peu." });
                } else {
                    setError(result.error || "Erreur inconnue");
                }
            });
        }
    };

    const toggleObjective = (obj: ObjectiveKey) => {
        setObjectives(prev =>
            prev.includes(obj) ? prev.filter(o => o !== obj) : [...prev, obj]
        );
    };

    const isParadoxeOrMore = difficulty.startsWith("PARADOXE") || difficulty.startsWith("CAUCHEMAR");

    const availableObjectives = Object.entries(OBJECTIVES).filter(([key]) => {
        if (key === "FUN") return false;
        if (key === "DROP_LEGENDE" || key === "SUCCES_NO_ACHAT") return isParadoxeOrMore;
        return true;
    });

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button className="h-14 px-8 text-lg bg-purple-600 hover:bg-purple-500 text-white gap-3 font-black uppercase tracking-wider flex-1 min-w-[240px] shadow-[0_0_20px_rgba(147,51,234,0.3)] hover:shadow-[0_0_25px_rgba(147,51,234,0.4)] transition-all">
                    <Plus className="w-6 h-6" />
                    Créer une Run
                </Button>
            </DialogTrigger>

            <DialogContent className="bg-[#0c0514] border-white/10 text-white max-w-lg shadow-2xl shadow-black/60">
                <DialogHeader>
                    <DialogTitle className="text-xl flex items-center gap-2 text-white">
                        🌙 Nouvelle Run Songes
                    </DialogTitle>
                </DialogHeader>

                <Tabs value={mode} onValueChange={(v) => { setMode(v as "standard" | "epreuve"); setError(null); }} className="pt-2">
                    <TabsList className="w-full bg-white/5 border border-white/8 p-1 rounded-lg mb-4">
                        <TabsTrigger
                            value="standard"
                            className="flex-1 gap-2 data-[state=active]:bg-purple-600 data-[state=active]:text-white data-[state=active]:shadow-[0_0_15px_rgba(147,51,234,0.4)] text-white/50 font-bold uppercase tracking-wide text-xs transition-all rounded"
                        >
                            <Swords className="w-3.5 h-3.5" />
                            Run Standard
                        </TabsTrigger>
                        <TabsTrigger
                            value="epreuve"
                            className="flex-1 gap-2 data-[state=active]:bg-amber-600 data-[state=active]:text-white data-[state=active]:shadow-[0_0_15px_rgba(217,119,6,0.4)] text-white/50 font-bold uppercase tracking-wide text-xs transition-all rounded"
                        >
                            <Trophy className="w-3.5 h-3.5" />
                            Épreuve de Songe
                        </TabsTrigger>
                    </TabsList>

                    {/* ─── MODE STANDARD ─── */}
                    <TabsContent value="standard" className="space-y-4 mt-0">
                        {/* Difficulty */}
                        <div className="space-y-2">
                            <Label className="text-white/60 text-xs uppercase tracking-widest font-bold">Difficulté</Label>
                            <Select value={difficulty} onValueChange={(v) => {
                                setDifficulty(v as DifficultyKey);
                                const isNewParadoxe = v.startsWith("PARADOXE") || v.startsWith("CAUCHEMAR");
                                if (!isNewParadoxe) {
                                    setObjectives(prev => prev.filter(o => o !== "DROP_LEGENDE" && o !== "SUCCES_NO_ACHAT"));
                                }
                            }}>
                                <SelectTrigger className="bg-white/5 border-white/10 text-white hover:bg-white/8 transition-colors">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent className="bg-[#0c0514] border-white/10">
                                    {Object.entries(DIFFICULTIES).map(([key, value]) => (
                                        <SelectItem key={key} value={key} className="text-white focus:bg-white/10">
                                            <div className="flex items-center gap-2">
                                                <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: value.couleur }} />
                                                {value.label}
                                                <span className="text-white/40 text-xs">({value.xpBonus}% XP/Butin)</span>
                                            </div>
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        {/* Objectives */}
                        <div className="space-y-2">
                            <Label className="text-white/60 text-xs uppercase tracking-widest font-bold">Objectifs (Choix multiple)</Label>
                            <div className="grid grid-cols-1 gap-1.5">
                                {availableObjectives.map(([key, value]) => {
                                    const isSelected = objectives.includes(key as ObjectiveKey);
                                    return (
                                        <div
                                            key={key}
                                            onClick={() => toggleObjective(key as ObjectiveKey)}
                                            className={cn(
                                                "flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-all",
                                                isSelected
                                                    ? "bg-purple-600/25 border-purple-500/60 text-purple-100"
                                                    : "bg-white/3 border-white/8 text-white/50 hover:bg-white/6 hover:text-white/70"
                                            )}
                                        >
                                            <div className="text-lg">{value.icon}</div>
                                            <div className="text-sm font-medium">{value.label}</div>
                                            {isSelected && (
                                                <div className="ml-auto w-2 h-2 rounded-full bg-purple-400 shadow-[0_0_8px_rgba(192,132,252,0.8)]" />
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </TabsContent>

                    {/* ─── MODE ÉPREUVE ─── */}
                    <TabsContent value="epreuve" className="mt-0">
                        <p className="text-xs text-white/30 mb-3 leading-relaxed">
                            Parcours prédéfinis liés à des succès en jeu. La difficulté et le mode sont imposés par l'épreuve choisie.
                        </p>
                        <div className="space-y-2 max-h-72 overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent">
                            {EPREUVES_SONGE.map((epreuve) => {
                                const isSelected = selectedEpreuve === epreuve.code;
                                const badgeColor = getDifficultyBadgeColor(epreuve.difficulty);
                                return (
                                    <div
                                        key={epreuve.code}
                                        onClick={() => setSelectedEpreuve(isSelected ? null : epreuve.code)}
                                        className={cn(
                                            "relative flex items-start gap-3 p-3 rounded-xl border cursor-pointer transition-all duration-200 group",
                                            isSelected
                                                ? "border-amber-500/50 bg-amber-900/15 shadow-[0_0_20px_rgba(217,119,6,0.1)]"
                                                : "border-white/8 bg-white/3 hover:border-white/15 hover:bg-white/5"
                                        )}
                                    >
                                        {/* Barre colorée latérale */}
                                        <div
                                            className="absolute left-0 top-0 bottom-0 w-0.5 rounded-l-xl transition-opacity"
                                            style={{
                                                backgroundColor: epreuve.color,
                                                opacity: isSelected ? 1 : 0.3,
                                            }}
                                        />

                                        {/* Icône */}
                                        <div className={cn(
                                            "w-10 h-10 rounded-xl flex items-center justify-center text-xl shrink-0 transition-all",
                                            isSelected ? "bg-amber-500/20 border border-amber-500/30" : "bg-white/5 border border-white/8"
                                        )}>
                                            {epreuve.icon}
                                        </div>

                                        {/* Content */}
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-2 flex-wrap">
                                                <span className={cn("text-sm font-bold", isSelected ? "text-amber-200" : "text-white/80")}>
                                                    {epreuve.label}
                                                </span>
                                                <span className={cn("text-[10px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded border", badgeColor)}>
                                                    {epreuve.difficultyLabel}
                                                </span>
                                            </div>
                                            <p className="text-[11px] text-white/35 leading-relaxed mt-0.5 line-clamp-2">
                                                {epreuve.description}
                                            </p>
                                            {/* Succès associé */}
                                            <div className="flex items-center gap-1.5 mt-1.5">
                                                <Trophy className="w-3 h-3 text-amber-500/60" />
                                                <span className="text-[10px] text-amber-500/50 font-semibold">
                                                    Succès : Épreuve {epreuve.code}
                                                </span>
                                            </div>
                                        </div>

                                        {/* Selected indicator */}
                                        {isSelected && (
                                            <div className="w-2 h-2 rounded-full bg-amber-400 shadow-[0_0_8px_rgba(251,191,36,0.8)] shrink-0 mt-1" />
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    </TabsContent>
                </Tabs>

                {/* ─── DISCORD TOGGLE (commun aux 2 modes) ─── */}
                <div className="space-y-2">
                    <div className="flex items-center justify-between p-3 rounded-lg border border-white/8 bg-white/3">
                        <div className="flex items-center gap-3">
                            <MessageSquare className="w-5 h-5 text-[#5865F2]" />
                            <div>
                                <p className="text-sm font-medium text-white/80">Publier sur Discord</p>
                                <p className="text-xs text-white/35">Embed avec boutons rejoindre/quitter</p>
                            </div>
                        </div>
                        <Switch
                            checked={publishToDiscord}
                            onCheckedChange={setPublishToDiscord}
                            disabled={!isDiscordConfigured}
                            className="data-[state=checked]:bg-[#5865F2]"
                        />
                    </div>
                    {!isDiscordConfigured && (
                        <p className="text-[10px] text-amber-500/80 font-bold uppercase tracking-tight italic px-2">
                            ⚠️ Salon Discord non configuré par l'admin. Publication impossible.
                        </p>
                    )}
                </div>

                {/* ─── ROLE MENTION ─── */}
                {publishToDiscord && discordRoles.length > 0 && (
                    <div className="space-y-2 animate-in fade-in slide-in-from-top-2 duration-200">
                        <Label className="text-white/60 text-[10px] uppercase tracking-widest font-bold ml-1">Rôle Discord à notifier</Label>
                        <Popover open={roleOpen} onOpenChange={setRoleOpen}>
                            <PopoverTrigger asChild>
                                <Button
                                    variant="outline"
                                    role="combobox"
                                    aria-expanded={roleOpen}
                                    className="w-full justify-between bg-white/5 border-white/10 text-white hover:bg-white/8 transition-colors font-medium h-10"
                                >
                                    <div className="flex items-center gap-2 truncate">
                                        {mentionRoleId ? (
                                            <>
                                                <div 
                                                    className="w-2 h-2 rounded-full shrink-0" 
                                                    style={{ backgroundColor: discordRoles.find(r => r.id === mentionRoleId)?.color === "#000000" ? "#9ca3af" : discordRoles.find(r => r.id === mentionRoleId)?.color }} 
                                                />
                                                <span className="truncate">{discordRoles.find(r => r.id === mentionRoleId)?.name}</span>
                                            </>
                                        ) : (
                                            <span className="text-white/40 italic">Aucun ping</span>
                                        )}
                                    </div>
                                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                                </Button>
                            </PopoverTrigger>
                            <PopoverContent className="w-[var(--radix-popover-trigger-width)] p-0 bg-[#0c0514] border-white/10" align="start">
                                <Command className="bg-transparent text-white">
                                    <CommandInput placeholder="Rechercher un rôle..." className="h-9 border-none focus:ring-0" />
                                    <CommandList className="max-h-[280px] custom-scrollbar">
                                        <CommandEmpty>Aucun rôle trouvé.</CommandEmpty>
                                        <CommandGroup>
                                            <CommandItem
                                                onSelect={() => {
                                                    setMentionRoleId(null);
                                                    setRoleOpen(false);
                                                }}
                                                className="text-white/50 italic focus:bg-white/10 cursor-pointer"
                                            >
                                                <Check
                                                    className={cn(
                                                        "mr-2 h-4 w-4",
                                                        !mentionRoleId ? "opacity-100" : "opacity-0"
                                                    )}
                                                />
                                                Aucun ping
                                            </CommandItem>
                                            {discordRoles.map((role) => (
                                                <CommandItem
                                                    key={role.id}
                                                    onSelect={() => {
                                                        setMentionRoleId(role.id);
                                                        setRoleOpen(false);
                                                    }}
                                                    className="text-white focus:bg-white/10 cursor-pointer"
                                                >
                                                    <Check
                                                        className={cn(
                                                            "mr-2 h-4 w-4",
                                                            mentionRoleId === role.id ? "opacity-100" : "opacity-0"
                                                        )}
                                                    />
                                                    <div className="flex items-center gap-2 flex-1 truncate">
                                                        <div 
                                                            className="w-2 h-2 rounded-full shrink-0" 
                                                            style={{ backgroundColor: role.color === "#000000" ? "#9ca3af" : role.color }} 
                                                        />
                                                        <span className="truncate">{role.name}</span>
                                                    </div>
                                                </CommandItem>
                                            ))}
                                        </CommandGroup>
                                    </CommandList>
                                </Command>
                            </PopoverContent>
                        </Popover>
                    </div>
                )}

                {/* ─── SCHEDULE TOGGLE ─── */}
                <div className="space-y-3">
                    <div className="flex items-center justify-between p-3 rounded-lg border border-white/8 bg-white/3">
                        <div className="flex items-center gap-3">
                            <CalendarIcon className="w-5 h-5 text-purple-400" />
                            <div>
                                <p className="text-sm font-medium text-white/80">Planifier la Run</p>
                                <p className="text-xs text-white/35">Définir une date et une heure</p>
                            </div>
                        </div>
                        <Switch
                            checked={isScheduled}
                            onCheckedChange={setIsScheduled}
                            className="data-[state=checked]:bg-purple-600"
                        />
                    </div>

                    {isScheduled && (
                        <div className="grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-200">
                            <div className="space-y-1.5">
                                <Label className="text-[10px] text-white/40 uppercase font-bold ml-1">Date</Label>
                                <Popover>
                                    <PopoverTrigger asChild>
                                        <Button
                                            variant="outline"
                                            className={cn(
                                                "w-full h-10 justify-start text-left font-normal bg-white/5 border-white/10 text-white hover:bg-white/8",
                                                !scheduledDate && "text-white/40"
                                            )}
                                        >
                                            <CalendarIcon className="mr-2 h-4 w-4 text-purple-400" />
                                            {scheduledDate ? format(scheduledDate, "d MMM yyyy", { locale: fr }) : "Choisir une date"}
                                        </Button>
                                    </PopoverTrigger>
                                    <PopoverContent className="w-auto p-0 bg-[#0c0514] border-white/10" align="start">
                                        <Calendar
                                            mode="single"
                                            selected={scheduledDate}
                                            onSelect={setScheduledDate}
                                            disabled={(date) => date < new Date() && date.toDateString() !== new Date().toDateString()}
                                            initialFocus
                                            className="bg-transparent text-white"
                                        />
                                    </PopoverContent>
                                </Popover>
                            </div>

                            <div className="space-y-1.5">
                                <Label className="text-[10px] text-white/40 uppercase font-bold ml-1">Heure</Label>
                                <div className="relative">
                                    <Clock className="absolute left-3 top-3 h-4 w-4 text-purple-400" />
                                    <Input
                                        type="time"
                                        value={scheduledTime}
                                        onChange={(e) => setScheduledTime(e.target.value)}
                                        className="h-10 pl-10 bg-white/5 border-white/10 text-white focus:border-purple-500/50"
                                    />
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Note épreuve */}
                {mode === "epreuve" && selectedEpreuve && (
                    <p className="text-[10px] text-white/25 flex items-center gap-1.5">
                        <Trophy className="w-3 h-3 text-amber-500/40" />
                        Pas de butin ni d&apos;expérience pour les Épreuves.
                    </p>
                )}

                {/* Error / Rate Limit countdown */}
                {countdown && (
                    <div className="flex items-center gap-3 px-4 py-3 rounded-xl border border-amber-500/25 bg-amber-950/30 text-sm">
                        <Timer className="w-5 h-5 text-amber-400 shrink-0 animate-pulse" />
                        <div className="flex-1">
                            <p className="text-amber-300 font-bold text-sm">Limite de création atteinte</p>
                            <p className="text-amber-500/70 text-xs mt-0.5">Disponible dans <span className="font-mono font-black text-amber-300">{countdown}</span></p>
                        </div>
                    </div>
                )}
                {!countdown && error && (
                    <div className="text-red-400 text-sm bg-red-900/15 p-3 rounded-lg border border-red-500/25">
                        {error}
                    </div>
                )}

                {/* Submit */}
                <Button
                    onClick={handleCreate}
                    disabled={isPending}
                    className={cn(
                        "w-full font-bold",
                        mode === "epreuve"
                            ? "bg-gradient-to-r from-amber-600 to-orange-600 hover:from-amber-500 hover:to-orange-500"
                            : "bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500"
                    )}
                >
                    {isPending ? (
                        <><Loader2 className="w-4 h-4 animate-spin mr-2" />Création...</>
                    ) : mode === "epreuve" ? (
                        <><Trophy className="w-4 h-4 mr-2" />Lancer l&apos;Épreuve</>
                    ) : (
                        "Créer la Run"
                    )}
                </Button>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState } from "react";
import Image from "next/image";

type RoomType = "combat" | "fontaine" | "faveur" | "boss";

interface DreamMap2DProps {
    currentFloor: number;
    isLeader?: boolean;
    onFloorSelect?: (floor: number) => void;
}

// Room type for each floor - simplified version following Dofus Songes pattern
// Floors 1-3: Combat only (Palier I)
// Floors 4-9: Combat + occasional Fontaine/Faveur (Palier II)
// Floors 10-15: Combat + more variety (Palier III)
// Floors 16-21: Combat + more variety (Palier IV)
// Floors 22-25: Combat + variety (Palier V)
// Floor 26: Boss (always)
const getFloorType = (floor: number): RoomType => {
    if (floor === 26) return "boss";
    if (floor <= 3) return "combat";
    // Mix of room types for other floors
    const types: RoomType[] = ["combat", "combat", "combat", "fontaine", "faveur"];
    return types[(floor * 7) % types.length]; // Pseudo-random based on floor
};

const ROOM_IMAGES: Record<RoomType, string> = {
    combat: "/songes/salle_combat.png",
    fontaine: "/songes/salle_fontaine.png",
    faveur: "/songes/salle_faveur.png",
    boss: "/songes/salle_boss.png",
};

const ROOM_LABELS: Record<RoomType, string> = {
    combat: "Combat",
    fontaine: "Fontaine Onirique",
    faveur: "Faveur Onirique",
    boss: "Fin du Rêve",
};

// Palier definitions
const PALIERS = [
    { name: "Pensées oniriques", floors: [1, 2, 3], color: "#a78bfa" },
    { name: "Balades fantastiques", floors: [4, 5, 6, 7, 8, 9], color: "#60a5fa" },
    { name: "Espaces imaginaires", floors: [10, 11, 12, 13, 14, 15], color: "#34d399" },
    { name: "Concepts brumeux", floors: [16, 17, 18, 19, 20, 21], color: "#fbbf24" },
    { name: "Abstractions chimériques", floors: [22, 23, 24, 25, 26], color: "#f87171" },
];

export function DreamMap2D({ currentFloor, isLeader, onFloorSelect }: DreamMap2DProps) {
    const [hoveredFloor, setHoveredFloor] = useState<number | null>(null);

    return (
        <div className="rounded-xl bg-gradient-to-b from-[#0a0118] to-[#1a0933] border border-purple-500/30 p-6 overflow-hidden">
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h2 className="text-xl font-bold text-white">Carte des Songes</h2>
                    <p className="text-purple-300/70 text-sm">Progression: {currentFloor} / 26 étages</p>
                </div>
                <div className="text-center">
                    <div className="text-3xl font-bold text-amber-400">{currentFloor}</div>
                    <div className="text-xs text-purple-300/50">Étage actuel</div>
                </div>
            </div>

            {/* Progress bar */}
            <div className="mb-6">
                <div className="h-3 bg-purple-900/50 rounded-full overflow-hidden">
                    <div
                        className="h-full bg-gradient-to-r from-purple-500 via-blue-500 to-amber-500 transition-all duration-500"
                        style={{ width: `${(currentFloor / 26) * 100}%` }}
                    />
                </div>
            </div>

            {/* Palier sections with floor grid */}
            <div className="space-y-4 max-h-[350px] overflow-y-auto pr-2">
                {PALIERS.map((palier, palierIdx) => (
                    <div key={palierIdx} className="relative">
                        {/* Palier header */}
                        <div
                            className="flex items-center gap-2 mb-2 sticky top-0 bg-[#0d0520] py-1 z-10"
                            style={{ borderLeftColor: palier.color }}
                        >
                            <div
                                className="w-2 h-2 rounded-full"
                                style={{ backgroundColor: palier.color }}
                            />
                            <span className="text-sm font-medium" style={{ color: palier.color }}>
                                Palier {palierIdx + 1}: {palier.name}
                            </span>
                        </div>

                        {/* Floors grid */}
                        <div className="grid grid-cols-6 gap-2">
                            {palier.floors.map((floor) => {
                                const roomType = getFloorType(floor);
                                const isCompleted = floor < currentFloor;
                                const isCurrent = floor === currentFloor;
                                const isNext = floor === currentFloor + 1;
                                const isHovered = hoveredFloor === floor;
                                const canClick = isLeader && (floor === currentFloor - 1 || floor === currentFloor + 1);

                                return (
                                    <div
                                        key={floor}
                                        className={`relative aspect-square rounded-lg border-2 overflow-hidden transition-all duration-200 cursor-pointer
                                            ${isCurrent
                                                ? "border-amber-400 ring-2 ring-amber-400/50 scale-105 z-10"
                                                : isCompleted
                                                    ? "border-green-500/50 opacity-60"
                                                    : isNext && isLeader
                                                        ? "border-purple-400/50 hover:border-purple-400"
                                                        : "border-purple-700/30"
                                            }
                                            ${canClick ? "hover:scale-105 hover:z-10" : ""}
                                        `}
                                        onMouseEnter={() => setHoveredFloor(floor)}
                                        onMouseLeave={() => setHoveredFloor(null)}
                                        onClick={() => canClick && onFloorSelect?.(floor)}
                                    >
                                        {/* Room image */}
                                        <Image
                                            src={ROOM_IMAGES[roomType]}
                                            alt={ROOM_LABELS[roomType]}
                                            fill
                                            className={`object-cover ${isCompleted ? "grayscale" : ""}`}
                                            sizes="80px"
                                        />

                                        {/* Floor number overlay */}
                                        <div className="absolute inset-0 flex items-center justify-center">
                                            <span className={`text-xs font-bold px-1.5 py-0.5 rounded bg-black/60
                                                ${isCurrent ? "text-amber-400" : isCompleted ? "text-green-400" : "text-white"}
                                            `}>
                                                {floor}
                                            </span>
                                        </div>

                                        {/* Completed checkmark */}
                                        {isCompleted && (
                                            <div className="absolute top-1 right-1 w-4 h-4 bg-green-500 rounded-full flex items-center justify-center">
                                                <span className="text-white text-xs">✓</span>
                                            </div>
                                        )}

                                        {/* Current indicator */}
                                        {isCurrent && (
                                            <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-0 h-0 
                                                border-l-[6px] border-l-transparent 
                                                border-r-[6px] border-r-transparent 
                                                border-b-[8px] border-b-amber-400
                                                rotate-180"
                                            />
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>

            {/* Hover tooltip */}
            {hoveredFloor !== null && (
                <div className="mt-4 p-3 rounded-lg bg-purple-900/50 border border-purple-500/30">
                    <div className="flex items-center justify-between">
                        <div>
                            <span className="text-white font-medium">Étage {hoveredFloor}</span>
                            <span className="text-purple-300/70 ml-2">
                                {ROOM_LABELS[getFloorType(hoveredFloor)]}
                            </span>
                        </div>
                        {isLeader && (hoveredFloor === currentFloor - 1 || hoveredFloor === currentFloor + 1) && (
                            <span className="text-xs text-amber-400">Cliquez pour naviguer</span>
                        )}
                    </div>
                </div>
            )}

            {/* Legend */}
            <div className="mt-4 flex flex-wrap gap-3 text-xs">
                {Object.entries(ROOM_LABELS).map(([type, label]) => (
                    <div key={type} className="flex items-center gap-1.5">
                        <div className="w-4 h-4 rounded overflow-hidden relative">
                            <Image
                                src={ROOM_IMAGES[type as RoomType]}
                                alt={label}
                                fill
                                className="object-cover"
                                sizes="16px"
                            />
                        </div>
                        <span className="text-purple-300/70">{label}</span>
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Users, Check, X, Loader2, MessageSquare } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    getPendingJoinRequests,
    respondToJoinRequest
} from "@/server/actions/songes/dream-run-actions";
import { ClassIcon } from "@/components/shared/class-icon";

interface JoinRequest {
    id: string;
    userId: string;
    classe: string;
    message: string | null;
    createdAt: Date;
    displayName?: string; // Discord pseudo or Dofus pseudo
}

interface JoinRequestsPanelProps {
    guildId: string;
    runId: string;
    isLeader: boolean;
}

export function JoinRequestsPanel({ guildId, runId, isLeader }: JoinRequestsPanelProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [requests, setRequests] = useState<JoinRequest[]>([]);
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    const loadRequests = async () => {
        const result = await getPendingJoinRequests(guildId, runId);
        if (result.success && result.requests) {
            setRequests(result.requests as JoinRequest[]);
        }
        setLoading(false);
    };

    useEffect(() => {
        loadRequests();
        // No polling - will refresh on actions or manual page reload
    }, [runId]);

    const handleRespond = (requestId: string, accept: boolean) => {
        setActionLoading(requestId);
        startTransition(async () => {
            await respondToJoinRequest(guildId, { requestId, accept });
            // Reload to refresh list
            await loadRequests();
            setActionLoading(null);
            // Refresh the entire page to update team members display
            router.refresh();
        });
    };

    // Tous les membres peuvent voir ce panneau (UI modifiée)

    if (loading) {
        return (
            <div className="rounded-xl bg-gradient-to-b from-[#1a0933] to-[#0d0520] border border-purple-500/30 p-4">
                <div className="flex items-center justify-center py-4 text-purple-400">
                    <Loader2 className="w-5 h-5 animate-spin mr-2" />
                    Chargement des candidatures...
                </div>
            </div>
        );
    }

    return (
        <div className="rounded-xl bg-gradient-to-b from-[#1a0933] to-[#0d0520] border border-purple-500/30 p-4">
            <h3 className="text-lg font-semibold text-white flex items-center gap-2 mb-4">
                <Users className="w-5 h-5 text-amber-400" />
                Candidatures ({requests.length})
            </h3>

            {requests.length === 0 ? (
                <div className="text-center py-6 text-purple-300/50">
                    <Users className="w-8 h-8 mx-auto mb-2 opacity-50" />
                    <p className="text-sm">Aucune candidature en attente</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {requests.map((request) => (
                        <div
                            key={request.id}
                            className="p-3 rounded-lg bg-purple-900/30 border border-purple-500/30"
                        >
                            <div className="flex items-start justify-between gap-2">
                                <div className="min-w-0 flex-1">
                                    {/* Candidate Name */}
                                    <h4 className="font-medium text-white mb-1">
                                        {request.displayName || "Joueur"}
                                    </h4>
                                    <div className="flex items-center gap-2 mb-1">
                                        <Badge variant="secondary" className="bg-blue-600/20 text-blue-300 border-blue-500/30">
                                            <ClassIcon classId={request.classe} size={14} className="mr-1.5" />
                                            {request.classe}
                                        </Badge>
                                        <span className="text-xs text-purple-300/50">
                                            {new Date(request.createdAt).toLocaleDateString("fr-FR")}
                                        </span>
                                    </div>

                                    {request.message && (
                                        <div className="flex items-start gap-1 text-sm text-purple-200 mt-2">
                                            <MessageSquare className="w-4 h-4 text-purple-400 mt-0.5 shrink-0" />
                                            <span className="line-clamp-2">{request.message}</span>
                                        </div>
                                    )}
                                </div>

                                {/* Action Buttons */}
                                {isLeader && (
                                    <div className="flex gap-1 shrink-0">
                                        <Button
                                            size="icon"
                                            variant="ghost"
                                            className="h-8 w-8 bg-green-900/30 hover:bg-green-600 text-green-400 hover:text-white"
                                            onClick={() => handleRespond(request.id, true)}
                                            disabled={actionLoading === request.id || isPending}
                                        >
                                            {actionLoading === request.id ? (
                                                <Loader2 className="w-4 h-4 animate-spin" />
                                            ) : (
                                                <Check className="w-4 h-4" />
                                            )}
                                        </Button>
                                        <Button
                                            size="icon"
                                            variant="ghost"
                                            className="h-8 w-8 bg-red-900/30 hover:bg-red-600 text-red-400 hover:text-white"
                                            onClick={() => handleRespond(request.id, false)}
                                            disabled={actionLoading === request.id || isPending}
                                        >
                                            <X className="w-4 h-4" />
                                        </Button>
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import Image from "next/image";
import { useParams, useRouter } from "next/navigation";
import { 
    Users, 
    Loader2, 
    Crown, 
    Trash2, 
    UserPlus, 
    Clock, 
    LogOut, 
    Bell, 
    Check, 
    X, 
    ShieldCheck, 
    Sparkles, 
    TrendingUp,
    MessageSquare,
    CalendarCheck
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
    sendJoinRequest,
    deleteDreamRun,
    getMemberProfiles,
    getMyJoinRequestStatus,
    cancelJoinRequest,
    leaveDreamRun,
    respondToJoinRequest
} from "@/server/actions/songes/dream-run-actions";
import { 
    DIFFICULTIES, 
    OBJECTIVES, 
    DOFUS_CLASSES, 
    type DifficultyKey, 
    type ObjectiveKey, 
    type DofusClass, 
    getEpreuve 
} from "@/lib/songes/types";
import { ClassIcon } from "@/components/shared/class-icon";
import { RunCloseModal } from "@/components/songes/RunCloseModal";
import { RunProgressModal } from "@/components/songes/RunProgressModal";
import { RunLeaderActions } from "@/components/songes/RunLeaderActions";
import type { DreamRun, DreamRunMember, DreamWaitlist } from "@prisma/client";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";

type RunWithRelations = DreamRun & {
    members: DreamRunMember[];
    waitlist: DreamWaitlist[];
    joinRequests?: { id: string; userId: string; message: string | null; classe: string }[];
    _count: { floors: number; bonuses: number };
};

interface MemberProfile {
    userId: string;
    pseudoDofus: string | null;
    classe: string | null;
    discordNickname: string | null;
    isAdmin?: boolean;
    avatar?: string | null;
}

interface RunCardProps {
    run: RunWithRelations;
    currentUserId?: string;
    canJoinSonges?: boolean;
    isAdmin?: boolean;
    isDiscordConfigured?: boolean;
}

export function RunCard({ run, currentUserId, canJoinSonges = true, isAdmin = false, isDiscordConfigured = false }: RunCardProps) {
    const params = useParams();
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [loading, setLoading] = useState(false);
    const [joinDialogOpen, setJoinDialogOpen] = useState(false);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [closeModalOpen, setCloseModalOpen] = useState(false);
    const [progressModalOpen, setProgressModalOpen] = useState(false);
    const [selectedClasse, setSelectedClasse] = useState<DofusClass>("Cra");
    const [message, setMessage] = useState("");
    const [profiles, setProfiles] = useState<MemberProfile[]>([]);
    const [pendingRequest, setPendingRequest] = useState(false);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    const difficulty = DIFFICULTIES[run.difficulty as DifficultyKey];
    const objective = OBJECTIVES[run.objective as ObjectiveKey];
    const isLeader = currentUserId === run.leaderId;
    const isMember = run.members.some((m) => m.userId === currentUserId);
    const epreuve = getEpreuve((run as any).epreuveCode);

    const progress = (run.currentFloor / 26) * 100;
    const canApplyConditions = !isMember && !isLeader && run.members.length < 4 && !pendingRequest;
    const canApply = canApplyConditions && canJoinSonges;

    useEffect(() => {
        async function loadData() {
            const candidateIds = run.joinRequests?.map(r => r.userId) || [];
            const allUserIds = [...new Set([run.leaderId, ...run.members.map((m) => m.userId), ...candidateIds])];
            if (allUserIds.length > 0) {
                const result = await getMemberProfiles(params.guildId as string, allUserIds);
                if (result.success && result.profiles) {
                    setProfiles(result.profiles as MemberProfile[]);
                }
            }
            if (!isMember && currentUserId && !isLeader) {
                const requestStatus = await getMyJoinRequestStatus(params.guildId as string, run.id);
                setPendingRequest(requestStatus.success && requestStatus.status === "PENDING");
            }
        }
        loadData();
    }, [run.members, run.id, currentUserId, isMember, isLeader, run.joinRequests]);

    const getDisplayName = (userId: string): string => {
        const profile = profiles.find((p) => p.userId === userId);
        return profile?.pseudoDofus || profile?.discordNickname || "Joueur";
    };

    const handleSendJoinRequest = async () => {
        setLoading(true);
        const result = await sendJoinRequest(params.guildId as string, { runId: run.id, classe: selectedClasse, message: message || undefined });
        if (result.success) {
            toast.success("Candidature envoyée !");
            setJoinDialogOpen(false);
            setPendingRequest(true);
            router.refresh();
        } else {
            toast.error(result.error);
        }
        setLoading(false);
    };

    const handleCancelRequest = () => {
        startTransition(async () => {
            await cancelJoinRequest(params.guildId as string, run.id);
            setPendingRequest(false);
            router.refresh();
        });
    };

    const handleDelete = async () => {
        setLoading(true);
        await deleteDreamRun(params.guildId as string, run.id);
        setDeleteDialogOpen(false);
        router.refresh();
        setLoading(false);
    };

    const handleLeave = () => {
        startTransition(async () => {
            await leaveDreamRun(params.guildId as string, run.id);
            router.refresh();
        });
    };

    const handleRespondCandidacy = async (requestId: string, accept: boolean) => {
        setActionLoading(requestId);
        const result = await respondToJoinRequest(params.guildId as string, { requestId, accept });
        if (result.success) {
            toast.success(accept ? "Candidat accepté !" : "Candidature refusée");
            router.refresh();
        } else {
            toast.error(result.error);
        }
        setActionLoading(null);
    }

    return (
        <div className="group relative overflow-hidden rounded-3xl bg-[#0d0d12] border border-white/5 p-7 transition-all duration-500 hover:border-white/20 hover:shadow-[0_0_60px_rgba(255,255,255,0.03)]">
            
            {/* Background Decor */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 blur-[100px] rounded-full pointer-events-none" />

            {/* --- HEADER --- */}
            <div className="relative z-10 flex justify-between items-center gap-4 mb-8">
                <div className="flex items-center gap-4 min-w-0">
                    <div className="relative w-12 h-12 shrink-0 bg-white/5 rounded-xl border border-white/10 p-2 flex items-center justify-center overflow-hidden">
                        <Image
                            src={`/assets/missions/${
                                run.difficulty?.toLowerCase()
                                    .replace('_iv', '4')
                                    .replace('_iii', '3')
                                    .replace('_ii', '2')
                                    .replace('_i', '1') || 'reve1'
                            }.png`}
                            alt="Portal"
                            width={32}
                            height={32}
                            className="object-contain"
                        />
                    </div>
                    <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                            <h3 className="text-xl font-black uppercase tracking-tight text-white leading-none truncate">{difficulty?.label || run.difficulty}</h3>
                            <div className="px-2 py-0.5 rounded-md bg-white/5 border border-white/10 shadow-sm">
                                <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">{objective?.label}</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-2 text-[10px] font-black text-white/30 uppercase tracking-[0.2em]">
                            <Users className="w-3 h-3" /> {run.members.length}/4
                            <span className="opacity-20">•</span>
                            <span className="flex items-center gap-1.5">
                                Leader <span className="text-white/60">{getDisplayName(run.leaderId)}</span>
                            </span>
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    {(isLeader || isAdmin) && (
                        <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
                            <DialogTrigger asChild>
                                <Button size="icon" variant="ghost" className="h-8 w-8 text-white/10 hover:text-red-400 hover:bg-red-500/10 transition-colors rounded-lg">
                                    <Trash2 className="w-4 h-4" />
                                </Button>
                            </DialogTrigger>
                            <DialogContent className="bg-[#0a0514] border-white/10 text-white max-w-sm rounded-2xl">
                                <DialogHeader>
                                    <DialogTitle className="flex items-center gap-2 text-red-500 text-lg font-black uppercase">
                                        <Trash2 className="w-5 h-5" /> Supprimer ?
                                    </DialogTitle>
                                </DialogHeader>
                                <p className="text-sm text-white/50 leading-relaxed py-4 italic">
                                    Confirmer la suppression ?
                                </p>
                                <div className="flex gap-3">
                                    <Button variant="ghost" className="flex-1 rounded-xl h-10" onClick={() => setDeleteDialogOpen(false)}>Annuler</Button>
                                    <Button variant="destructive" className="flex-1 font-black uppercase text-[10px] rounded-xl h-10" onClick={handleDelete} disabled={loading}>
                                        Supprimer
                                    </Button>
                                </div>
                            </DialogContent>
                        </Dialog>
                    )}
                </div>
            </div>

            {/* --- ÉPREUVE BOX --- */}
            {epreuve && (
                <div className="relative z-10 p-4 rounded-2xl border border-white/5 bg-white/5 mb-6 backdrop-blur-sm">
                    <div className="flex items-center gap-2 mb-1.5">
                        <span className="text-xl">{epreuve.icon}</span>
                        <span className="text-[10px] font-black uppercase tracking-widest" style={{ color: epreuve.color }}>{epreuve.label}</span>
                    </div>
                    <p className="text-[11px] text-white/40 leading-relaxed">{epreuve.description}</p>
                </div>
            )}

            {/* --- PROGRESSION --- */}
            <div className="relative z-10 mb-8">
                <div className="flex justify-between items-end mb-3">
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-widest text-white/30 mb-1">Étage Actuel</span>
                        <div className="flex items-baseline gap-2">
                           <span className="text-4xl font-black text-white">{run.currentFloor}</span>
                           <span className="text-sm font-bold text-white/10 uppercase">/ 26</span>
                        </div>
                    </div>
                    <div className="flex flex-col items-end flex-1 ml-8">
                        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden p-0.5 border border-white/5">
                            <div 
                                className="h-full rounded-full bg-gradient-to-r from-white/20 via-white/40 to-white/20 bg-[length:200%_auto] animate-[gradient_3s_linear_infinite] shadow-[0_0_15px_rgba(255,255,255,0.1)] transition-all duration-1000"
                                style={{ width: `${progress}%` }}
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* --- MEMBERS --- */}
            <div className="relative z-10 space-y-3 mb-8">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {[1, 2, 3, 4].map((slot) => {
                        const member = run.members.find((m) => m.slot === slot);
                        const pseudo = member ? getDisplayName(member.userId) : "Libre";
                        const profile = profiles.find(p => p.userId === member?.userId);
                        
                        return (
                            <div key={slot} className={cn(
                                "flex items-center gap-3 px-4 py-3 rounded-[1rem] border transition-all truncate",
                                member ? "bg-white/5 border-white/10 shadow-lg" : "bg-black/20 border-white/5 border-dashed"
                            )}>
                                <div className="w-8 h-8 rounded-lg shrink-0 flex items-center justify-center bg-zinc-900 border border-white/10 overflow-hidden">
                                    {member ? (
                                        <Avatar className="w-full h-full">
                                            <AvatarImage src={profile?.avatar || undefined} />
                                            <AvatarFallback className="text-[10px] font-black">
                                                {profile?.pseudoDofus?.charAt(0) || "?"}
                                            </AvatarFallback>
                                        </Avatar>
                                    ) : <UserPlus className="w-3.5 h-3.5 text-white/10" />}
                                </div>
                                <span className={cn(
                                    "text-xs font-black truncate",
                                    member ? "text-white" : "text-white/10"
                                )}>
                                    {pseudo}
                                </span>
                                {member?.userId === run.leaderId && <Crown className="w-3.5 h-3.5 text-amber-500 shrink-0 ml-auto" />}
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* --- CANDIDACIES SECTION --- */}
            {isLeader && run.joinRequests && run.joinRequests.length > 0 && (
                <div className="relative z-10 p-5 rounded-2xl bg-amber-500/5 border border-amber-500/10 mb-6 animate-in slide-in-from-bottom-2 duration-300">
                    <div className="flex items-center gap-2 mb-4">
                        <Bell className="w-3.5 h-3.5 text-amber-500" />
                        <p className="text-[10px] font-black uppercase tracking-widest text-amber-500/70">Candidatures</p>
                    </div>

                    <div className="space-y-3">
                        {run.joinRequests.map((c) => {
                            const profile = profiles.find(p => p.userId === c.userId);
                            const name = profile?.pseudoDofus || profile?.discordNickname || "Candidat";
                            return (
                                <div key={c.id} className="p-3 rounded-xl bg-black/40 border border-white/5 flex flex-col gap-3">
                                    <div className="flex items-center justify-between gap-3">
                                        <div className="flex items-center gap-3 min-w-0">
                                            <Avatar className="w-9 h-9 border border-white/10 rounded-xl">
                                                <AvatarImage src={profile?.avatar || undefined} />
                                                <AvatarFallback className="bg-zinc-800 text-[10px] font-bold">{name.charAt(0)}</AvatarFallback>
                                            </Avatar>
                                            <div className="min-w-0">
                                                <p className="text-sm font-black text-white truncate">{name}</p>
                                                <div className="flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest text-white/30">
                                                    <ClassIcon classId={c.classe as DofusClass} size={12} />
                                                    {c.classe}
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex gap-1.5 shrink-0">
                                            <Button 
                                                size="icon" 
                                                className="w-8 h-8 rounded-lg bg-green-500 hover:bg-green-400 text-black shadow-lg shadow-green-500/20" 
                                                onClick={() => handleRespondCandidacy(c.id, true)} 
                                                disabled={!!actionLoading}
                                            >
                                                {actionLoading === c.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <Check className="w-4 h-4" />}
                                            </Button>
                                            <Button 
                                                size="icon" 
                                                variant="ghost" 
                                                className="w-8 h-8 rounded-lg text-white/20 hover:text-rose-500 hover:bg-rose-500/10" 
                                                onClick={() => handleRespondCandidacy(c.id, false)} 
                                                disabled={!!actionLoading}
                                            >
                                                <X className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    </div>
                                    {c.message && (
                                        <div className="relative p-2.5 rounded-xl bg-white/5 border-l-2 border-amber-500/50">
                                            <p className="text-[10px] italic text-white/50 leading-relaxed font-medium">“{c.message}”</p>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* --- ACTIONS --- */}
            <div className="relative z-10 flex flex-wrap gap-3">
                {isLeader ? (
                    <>
                        <div className="w-full sm:w-auto flex-1">
                             <RunLeaderActions 
                                guildId={params.guildId as string} 
                                runId={run.id} 
                                variant="full" 
                                isDiscordConfigured={isDiscordConfigured}
                             />
                        </div>
                        
                        <Button 
                            variant="secondary" 
                            className="flex-1 h-11 bg-white/5 hover:bg-white/10 border-white/10 text-white font-black uppercase tracking-widest text-[10px] rounded-xl"
                            onClick={() => setProgressModalOpen(true)}
                        >
                            <TrendingUp className="w-4 h-4 mr-2" />
                            Avancement
                        </Button>
                        <Button 
                            className="flex-1 h-11 bg-amber-500 hover:bg-amber-400 text-black font-black uppercase tracking-widest text-[10px] shadow-lg rounded-xl transition-all"
                            onClick={() => setCloseModalOpen(true)}
                        >
                            <Check className="w-4 h-4 mr-2" />
                            Clôturer
                        </Button>
                    </>
                ) : isMember ? (
                    <Button 
                        variant="ghost" 
                        className="flex-1 h-11 bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 border border-rose-500/20 font-black uppercase tracking-widest text-[10px] rounded-xl"
                        onClick={handleLeave}
                    >
                        <LogOut className="w-4 h-4 mr-2" />
                        Quitter
                    </Button>
                ) : pendingRequest ? (
                    <div className="flex-1 flex gap-2">
                        <div className="flex-1 h-11 flex items-center justify-center rounded-xl bg-amber-500/10 text-amber-500 border border-amber-500/20 font-black uppercase tracking-widest text-[10px] animate-pulse">
                            <Clock className="w-4 h-4 mr-2" />
                            En attente
                        </div>
                        <Button 
                            variant="ghost" 
                            className="h-11 w-11 rounded-xl border border-white/5 text-white/20 hover:text-rose-500"
                            onClick={handleCancelRequest}
                        >
                            <X className="w-4 h-4" />
                        </Button>
                    </div>
                ) : canApply ? (
                    <Button 
                        className="flex-1 h-11 bg-white/10 hover:bg-white/20 text-white font-black uppercase tracking-widest text-[10px] rounded-xl border border-white/10 shadow-lg transition-all"
                        onClick={() => setJoinDialogOpen(true)}
                    >
                        <UserPlus className="w-4 h-4 mr-2" />
                        Postuler
                    </Button>
                ) : (
                    <div className="flex-1 h-11 flex items-center justify-center rounded-xl bg-white/5 text-white/20 text-[10px] font-black uppercase tracking-widest border border-white/5">
                        <ShieldCheck className="w-4 h-4 mr-2" />
                        Équipe complète
                    </div>
                )}
            </div>

            {/* --- MODALS --- */}
            <Dialog open={joinDialogOpen} onOpenChange={setJoinDialogOpen}>
                <DialogContent className="bg-[#0a0514] border-white/10 text-white max-w-sm rounded-[2rem] p-0 overflow-hidden shadow-2xl">
                    <div className="p-8">
                        <DialogHeader className="mb-8">
                            <DialogTitle className="flex items-center gap-3 text-2xl font-black uppercase tracking-tighter">
                                <UserPlus className="w-6 h-6 text-white/50" /> Postuler
                            </DialogTitle>
                        </DialogHeader>
                        <div className="space-y-6">
                            <div className="space-y-3">
                                <Label className="text-[10px] font-black uppercase tracking-[0.3em] text-white/30">Classe Dofus</Label>
                                <Select value={selectedClasse} onValueChange={(v) => setSelectedClasse(v as DofusClass)}>
                                    <SelectTrigger className="bg-white/5 border-white/10 h-12 rounded-xl">
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent className="bg-[#0a0514] border-white/10">
                                        {DOFUS_CLASSES.map((classe) => (
                                            <SelectItem key={classe} value={classe} className="focus:bg-white/5">
                                                <div className="flex items-center gap-3">
                                                    <ClassIcon classId={classe} size={20} />
                                                    <span className="text-sm font-black">{classe}</span>
                                                </div>
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="space-y-3">
                                <Label className="text-[10px] font-black uppercase tracking-[0.3em] text-white/30">Note de motivation</Label>
                                <Textarea
                                    placeholder="Dis-nous pourquoi on doit te prendre..."
                                    value={message}
                                    onChange={(e) => setMessage(e.target.value)}
                                    maxLength={100}
                                    className="bg-white/5 border-white/10 min-h-[100px] text-sm resize-none rounded-xl p-4"
                                />
                            </div>
                            <Button onClick={handleSendJoinRequest} disabled={loading} className="w-full bg-white/10 hover:bg-white/20 text-white border border-white/10 font-black uppercase tracking-[0.2em] h-14 rounded-xl shadow-xl">
                                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : "Envoyer ma candidature"}
                            </Button>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>

            <RunProgressModal
                isOpen={progressModalOpen}
                onClose={() => setProgressModalOpen(false)}
                guildId={params.guildId as string}
                runId={run.id}
                currentFloor={run.currentFloor}
                onUpdate={() => router.refresh()}
            />

            <RunCloseModal
                isOpen={closeModalOpen}
                runId={run.id}
                guildId={params.guildId as string}
                difficulty={run.difficulty}
                memberUserIds={run.members.filter(m => m.userId !== run.leaderId).map(m => m.userId)}
                onClose={() => setCloseModalOpen(false)}
                onClosed={() => { setCloseModalOpen(false); router.refresh(); }}
            />
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { ArrowLeft, Crown, Users, Clock, CheckCircle2, Loader2, PlayCircle, Trophy, Target, BookOpen } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { DIFFICULTIES, OBJECTIVES, getEpreuve, type DifficultyKey, type ObjectiveKey } from "@/lib/songes/types";
import { closeDreamRun } from "@/server/actions/songes/dream-run-actions";
import type { DreamRun, DreamRunMember } from "@prisma/client";
import { cn } from "@/lib/utils";

type RunWithMembers = DreamRun & {
    members: DreamRunMember[];
};

interface RunDetailHeaderProps {
    run: RunWithMembers;
    guildId: string;
    isLeader?: boolean;
    leaderName?: string;
    optimisticStatus: string;
    onStatusChange: (status: string) => void;
    onOpenBossGuide?: () => void;
}

export function RunDetailHeader({ run, guildId, isLeader, leaderName, optimisticStatus, onStatusChange, onOpenBossGuide }: RunDetailHeaderProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [closeDialogOpen, setCloseDialogOpen] = useState(false);
    const isCompleted = optimisticStatus === "COMPLETED";
    const [loading, setLoading] = useState(false);

    const difficulty = DIFFICULTIES[run.difficulty as DifficultyKey];
    const objective = OBJECTIVES[run.objective as ObjectiveKey];
    const epreuve = getEpreuve((run as any).epreuveCode);

    const formatDate = (date: Date | null) => {
        if (!date) return "-";
        return new Date(date).toLocaleDateString("fr-FR", {
            day: "numeric",
            month: "short",
            hour: "2-digit",
            minute: "2-digit",
        });
    };

    const handleCloseRun = () => {
        // Optimistic Update
        const previousStatus = optimisticStatus;
        onStatusChange("COMPLETED"); // Tell parent we are now completed
        setCloseDialogOpen(false);
        setLoading(true);

        startTransition(async () => {
            try {
                const result = await closeDreamRun(guildId, run.id);
                if (result.success) {
                    router.refresh();
                    // Keep completed state
                } else {
                    // Rollback on error
                    onStatusChange(previousStatus);
                    console.error(result.error);
                }
            } catch (e) {
                onStatusChange(previousStatus);
            }
            setLoading(false);
        });
    };

    const handleReopenRun = () => {
        const previousStatus = optimisticStatus;
        onStatusChange("IN_PROGRESS"); // Tell parent we are active again
        setLoading(true);

        startTransition(async () => {
            try {
                const { reopenDreamRun } = await import("@/server/actions/songes/dream-run-actions");
                const result = await reopenDreamRun(guildId, run.id);
                if (result.success) {
                    router.refresh();
                } else {
                    onStatusChange(previousStatus);
                    console.error(result.error);
                }
            } catch (e) {
                onStatusChange(previousStatus);
            }
            setLoading(false);
        });
    };

    const getDiffImage = (key: string | undefined) => {
        if (!key) return "reve1";
        const map: Record<string, string> = {
            REVE_I: "reve1", REVE_II: "reve2", REVE_III: "reve3",
            PARADOXE_I: "paradoxe1", PARADOXE_II: "paradoxe2", PARADOXE_III: "paradoxe3", PARADOXE_IV: "paradoxe4",
            CAUCHEMAR_I: "cauchemar1", CAUCHEMAR_II: "cauchemar2", CAUCHEMAR_III: "cauchemar3"
        };
        return map[key] || "reve1";
    };

    return (
        <div className="relative w-full overflow-hidden rounded-2xl border border-white/5 bg-[#09090b] shadow-2xl transition-all duration-500">
            {/* Background Effects */}
            <div className="absolute inset-0 bg-gradient-to-r from-emerald-900/10 via-blue-900/5 to-transparent pointer-events-none" />
            <div
                className="absolute -top-24 -right-24 w-64 h-64 rounded-full blur-[100px] opacity-30 pointer-events-none transition-all duration-700"
                style={{
                    backgroundColor: difficulty?.couleur || '#a855f7',
                    opacity: isCompleted ? 0 : 0.3 // Fade out glow when completed
                }}
            />

            {/* Subtle Premium Watermark pattern instead of giant text */}
            {isCompleted && (
                <div className="absolute inset-0 z-0 pointer-events-none overflow-hidden">
                    <div className="absolute top-4 right-4 animate-in fade-in zoom-in duration-700">
                        <div className="relative border border-amber-500/30 bg-amber-500/5 px-4 py-1 rounded-full backdrop-blur-sm flex items-center gap-2 shadow-[0_0_30px_rgba(245,158,11,0.1)]">
                            <Trophy className="w-4 h-4 text-amber-500" />
                            <span className="text-xs font-bold text-amber-500 uppercase tracking-widest">Run Terminée</span>
                        </div>
                    </div>
                    {/* Diagonal scanlines or subtle texture */}
                    <div className="absolute inset-0 bg-[url(/scanlines.png)] opacity-20 mix-blend-overlay" />
                    <div className="absolute -right-20 -bottom-20 w-80 h-80 bg-amber-500/5 blur-[80px] rounded-full" />
                </div>
            )}

            <div className={`relative p-6 md:p-8 flex flex-col gap-8 z-10 transition-opacity duration-500 ${isCompleted ? "opacity-90 grayscale-[0.3]" : ""}`}>
                {/* Top Row: Back link & Title Row */}
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-white/5 pb-6">
                    <div className="flex flex-col gap-3">
                        <Link href={`/dashboard/${guildId}/songes`} className="text-xs text-white/40 font-bold hover:text-white transition-colors flex items-center gap-1 group uppercase tracking-widest">
                            <ArrowLeft className="w-3 h-3 transition-transform group-hover:-translate-x-1" />
                            RETOUR AUX SONGES
                        </Link>
                        <div className="flex items-center gap-4">
                            <div className={cn(
                                "w-3 h-3 rounded-full shadow-[0_0_15px_currentColor] transition-colors duration-500",
                                optimisticStatus === "IN_PROGRESS" ? "bg-emerald-400 text-emerald-400 animate-pulse" :
                                    optimisticStatus === "RECRUITING" ? "bg-blue-400 text-blue-400" :
                                        optimisticStatus === "COMPLETED" ? "bg-amber-500 text-amber-500" : "bg-red-500 text-red-500"
                            )} />
                            <Image
                                src={`/assets/missions/${getDiffImage(run.difficulty)}.png`}
                                alt={difficulty?.label || "Difficulté"}
                                width={56}
                                height={56}
                                className="object-contain drop-shadow-[0_0_10px_rgba(255,255,255,0.2)]"
                            />
                            <h1 className={cn(
                                "text-3xl md:text-5xl font-black tracking-tighter transition-colors duration-500 uppercase",
                                isCompleted ? "text-amber-500/80" : "text-white"
                            )}>
                                {difficulty?.label || "Rêve Inconnu"}
                            </h1>
                            {optimisticStatus === "IN_PROGRESS" && (
                                <span className="text-[10px] font-black px-2 py-1 rounded bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 uppercase tracking-[0.2em] transform -translate-y-1">
                                    En cours
                                </span>
                            )}
                            {/* NEW: Objective Badge for Standard runs */}
                            {!epreuve && objective && (
                                <div className="flex items-center gap-2 bg-purple-500/10 px-3 py-1 rounded-full border border-purple-500/20 text-purple-300 text-[10px] font-black uppercase tracking-widest ml-2">
                                    {objective.icon}
                                    <span>{objective.label}</span>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Floor Counter - Integrated into top row but on the right */}
                    <div className="flex items-center gap-4 self-start md:self-end bg-white/5 px-6 py-3 rounded-2xl border border-white/10 backdrop-blur-md shadow-xl">
                        <div className="flex flex-col items-center leading-none">
                            <span className="text-[10px] uppercase text-white/30 font-black tracking-widest mb-1">Étage Actuel</span>
                            <span className={cn(
                                "text-4xl font-black transition-all duration-500",
                                isCompleted ? "text-amber-500" : "text-white"
                            )}>
                                {run.currentFloor}
                            </span>
                        </div>
                        <div className="h-8 w-px bg-white/10" />
                        <div className="flex flex-col items-center leading-none">
                            <span className="text-[10px] uppercase text-white/30 font-black tracking-widest mb-1">Objectif</span>
                            <span className="text-lg font-black text-white/60">26</span>
                        </div>
                    </div>
                </div>

                {/* Main Grid: Left (Guides/Rules) | Right (Meta/Actions) */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

                    {/* LEFT COLUMN: 8/12 - GUIDES & RULES */}
                    <div className="lg:col-span-12 xl:col-span-8 flex flex-col gap-6">
                        <div className="flex flex-wrap gap-4">
                            {/* Guide Songes */}
                            <a
                                href="https://www.dofuspourlesnoobs.com/songes-infinis.html"
                                target="_blank"
                                rel="noopener noreferrer"
                                className="flex items-center gap-4 px-8 py-5 rounded-2xl border-2 border-blue-500/30 bg-blue-600/10 text-blue-200 hover:bg-blue-500/20 hover:text-white hover:border-blue-400 hover:-translate-y-1 shadow-[0_0_20px_rgba(59,130,246,0.2)] transition-all group font-black text-lg uppercase tracking-wider flex-1 min-w-[280px]"
                            >
                                <div className="w-2.5 h-2.5 rounded-full bg-blue-400 shadow-[0_0_10px_rgba(96,165,250,1)] animate-pulse" />
                                <span>Guide Songes</span>
                                <ArrowLeft className="w-5 h-5 rotate-[135deg] ml-auto transition-transform group-hover:translate-x-1 group-hover:-translate-y-1" />
                            </a>

                            {/* Guide Boss Button */}
                            {onOpenBossGuide && (
                                <button
                                    onClick={onOpenBossGuide}
                                    className="flex items-center gap-4 px-8 py-5 rounded-2xl border-2 border-emerald-500/30 bg-emerald-600/10 text-emerald-200 hover:bg-emerald-500/20 hover:text-white hover:border-emerald-400 hover:-translate-y-1 shadow-[0_0_20px_rgba(16,185,129,0.2)] transition-all group font-black text-lg uppercase tracking-wider flex-1 min-w-[280px]"
                                >
                                    <BookOpen className="w-6 h-6 group-hover:rotate-12 transition-transform drop-shadow-[0_0_10px_rgba(217,70,239,1)]" />
                                    <span>Guide Boss Songes</span>
                                    <ArrowLeft className="w-5 h-5 rotate-[135deg] ml-auto opacity-40" />
                                </button>
                            )}
                        </div>

                        {/* Rules/Épreuve Block */}
                        {epreuve && (
                            <div
                                className="relative overflow-hidden p-5 rounded-3xl border-2 backdrop-blur-sm group"
                                style={{
                                    borderColor: `${epreuve.color}30`,
                                    backgroundColor: `${epreuve.color}05`,
                                }}
                            >
                                <div className="absolute -right-4 -bottom-4 text-8xl opacity-[0.03] transition-transform group-hover:scale-110 pointer-events-none">
                                    {epreuve.icon}
                                </div>
                                <div className="flex flex-col md:flex-row gap-5 items-start">
                                    <div className="w-14 h-14 rounded-2xl flex items-center justify-center text-3xl shrink-0"
                                        style={{ backgroundColor: `${epreuve.color}20`, border: `1px solid ${epreuve.color}40` }}>
                                        {epreuve.icon}
                                    </div>
                                    <div className="flex-1">
                                        <div className="flex items-center gap-3 mb-2">
                                            <span className="text-[10px] font-black uppercase tracking-[0.3em]" style={{ color: epreuve.color }}>
                                                Règle spéciale — Épreuve
                                            </span>
                                            <div className="h-px flex-1" style={{ backgroundColor: `${epreuve.color}20` }} />
                                        </div>
                                        <h3 className="text-xl font-black text-white/90 mb-2 uppercase tracking-tight">{epreuve.label}</h3>
                                        <p className="text-sm text-white/50 leading-relaxed max-w-2xl">
                                            {epreuve.description}
                                        </p>
                                        <div className="mt-4 flex items-center gap-2">
                                            <Trophy className="w-4 h-4" style={{ color: epreuve.color }} />
                                            <span className="text-[11px] font-bold italic opacity-40">Aucun butin ni expérience durant cette épreuve.</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* RIGHT COLUMN: 4/12 - ACTIONS & METADATA */}
                    <div className="lg:col-span-12 xl:col-span-4 flex flex-col gap-6 lg:border-l lg:border-white/5 lg:pl-8">
                        {/* Leader Actions */}
                        {isLeader && (
                            <div className="flex flex-col gap-3">
                                <span className="text-[10px] font-black text-white/20 uppercase tracking-widest pl-1">Actions Chef de Run</span>
                                {optimisticStatus === "IN_PROGRESS" && (
                                    <Dialog open={closeDialogOpen} onOpenChange={setCloseDialogOpen}>
                                        <DialogTrigger asChild>
                                            <Button
                                                className="w-full bg-amber-500 hover:bg-amber-400 text-black font-black uppercase tracking-widest h-14 shadow-lg shadow-amber-900/20 active:scale-95"
                                            >
                                                <CheckCircle2 className="w-5 h-5 mr-3" />
                                                Clôturer la Run
                                            </Button>
                                        </DialogTrigger>
                                        <DialogContent className="bg-[#09090b] border-white/10 text-white sm:max-w-md">
                                            <DialogHeader>
                                                <DialogTitle className="text-xl font-black flex items-center gap-2 uppercase tracking-tight">
                                                    <Trophy className="w-5 h-5 text-amber-500" />
                                                    Confirmer la Clôture
                                                </DialogTitle>
                                            </DialogHeader>
                                            <div className="py-4 space-y-3">
                                                <p className="text-white/80">Voulez-vous vraiment terminer cette aventure ?</p>
                                                <p className="text-xs text-white/40 leading-relaxed bg-white/5 p-3 rounded-lg">
                                                    Une fois clôturée, la run est archivée dans l'historique et les récompenses finales sont figées.
                                                </p>
                                            </div>
                                            <div className="flex justify-end gap-3 mt-4">
                                                <Button variant="ghost" onClick={() => setCloseDialogOpen(false)}>Annuler</Button>
                                                <Button onClick={handleCloseRun} disabled={loading} className="bg-amber-600 hover:bg-amber-500 text-white">
                                                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : "Terminer la Run"}
                                                </Button>
                                            </div>
                                        </DialogContent>
                                    </Dialog>
                                )}
                                {optimisticStatus === "COMPLETED" && (
                                    <Button
                                        onClick={handleReopenRun}
                                        disabled={loading}
                                        className="w-full bg-white/5 hover:bg-white/10 text-white font-black uppercase tracking-widest h-14 border border-white/10"
                                    >
                                        {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <PlayCircle className="w-5 h-5 mr-3" />}
                                        Réouvrir la Run
                                    </Button>
                                )}
                            </div>
                        )}

                        {/* Metadata Card */}
                        <div className="bg-white/3 rounded-2xl p-5 border border-white/5 flex flex-col gap-4">
                            <span className="text-[10px] font-black text-white/20 uppercase tracking-widest">Détails de l'expédition</span>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="flex flex-col gap-1.5 col-span-2">
                                    <div className="flex items-center gap-2 text-amber-500/60">
                                        <Crown className="w-3.5 h-3.5" />
                                        <span className="text-[10px] font-bold uppercase tracking-tighter">Chef d'expédition</span>
                                    </div>
                                    <span className="text-sm font-black text-white/90">{leaderName || "Chargement..."}</span>
                                </div>
                                <div className="h-px bg-white/5 col-span-2 my-1" />
                                <div className="flex flex-col gap-1.5">
                                    <div className="flex items-center gap-2 text-white/40">
                                        <Users className="w-3.5 h-3.5" />
                                        <span className="text-[10px] font-bold uppercase tracking-tighter">Équipage</span>
                                    </div>
                                    <span className="text-sm font-black text-white/80">{run.members.length} / 4</span>
                                </div>
                                <div className="flex flex-col gap-1.5">
                                    <div className="flex items-center gap-2 text-white/40">
                                        <Clock className="w-3.5 h-3.5" />
                                        <span className="text-[10px] font-bold uppercase tracking-tighter">Créée</span>
                                    </div>
                                    <span className="text-sm font-black text-white/80">{formatDate(run.createdAt)}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { GlassPanel } from "@/components/ui/glass-panel";
import { Button } from "@/components/ui/button";
import { Bell, Calendar as CalendarIcon, Clock, Send, Loader2 } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { triggerRunNotification } from "@/server/actions/songes/dream-run-actions";
import { toast } from "sonner";

interface RunLeaderActionsProps {
    guildId: string;
    runId: string;
    isDiscordConfigured?: boolean;
    variant?: "full" | "minimal";
}

export function RunLeaderActions({ guildId, runId, isDiscordConfigured = false, variant = "full" }: RunLeaderActionsProps) {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState("On se prépare pour la run !");
    const [date, setDate] = useState<Date | undefined>(new Date());
    const [time, setTime] = useState("21:00");

    const handleSendReminder = async () => {
        if (!message) {
            toast.error("Veuillez saisir un message");
            return;
        }

        setLoading(true);
        try {
            let scheduledDate: Date | undefined = undefined;

            if (date) {
                scheduledDate = new Date(date);
                const [hours, minutes] = time.split(":").map(Number);
                scheduledDate.setHours(hours, minutes, 0, 0);
            }

            const result = await triggerRunNotification(guildId, runId, message, scheduledDate);

            if (result.success) {
                toast.success("Rappel envoyé avec succès !");
                setIsModalOpen(false);
            } else {
                toast.error(result.error || "Une erreur est survenue");
            }
        } catch (error) {
            toast.error("Erreur lors de l'envoi du rappel");
        } finally {
            setLoading(false);
        }
    };

    if (variant === "minimal") {
        return (
            <>
                <Button
                    variant="ghost"
                    size="icon"
                    onClick={(e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        setIsModalOpen(true);
                    }}
                    className="h-8 w-8 text-purple-400 hover:text-purple-300 hover:bg-purple-500/10"
                    title="Envoyer un rappel aux membres"
                >
                    <Bell className="h-4 w-4" />
                </Button>

                {renderModal()}
            </>
        );
    }

    // Only hide if Discord is NOT configured AND we are in full variant (to avoid empty space)? 
    // Actually, following "Zero Config, Zero Button" policy, but we might want to keep internal notices.
    // DECISION: Show button but add alert inside modal + disclaimer in text.
    // if (!isDiscordConfigured) return null;

    return (
        <>
            <GlassPanel className="p-4 border-purple-500/20 bg-purple-500/5">
                <div className="flex flex-col gap-3">
                    <div className="flex items-center gap-2 text-purple-300 font-semibold mb-1">
                        <Bell className="w-4 h-4 text-purple-400" />
                        <span>Gestion Leader</span>
                    </div>

                    <p className="text-xs text-muted-foreground mb-1">
                        {isDiscordConfigured 
                            ? "Envoyez un ping Discord et une notification dashboard à tous les membres de l'équipe."
                            : "Envoyez une notification dashboard à tous les membres de l'équipe."}
                    </p>

                    <Button
                        onClick={() => setIsModalOpen(true)}
                        variant="outline"
                        className="w-full border-purple-500/30 hover:bg-purple-500/10 text-purple-200 gap-2"
                    >
                        <Send className="w-4 h-4" />
                        Envoyer un rappel
                    </Button>
                </div>
            </GlassPanel>

            {renderModal()}
        </>
    );

    function renderModal() {
        return (
            <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
                <DialogContent className="sm:max-w-[425px] bg-[#0a0a0c] border-white/10 text-white" onClick={(e) => e.stopPropagation()}>
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2 text-purple-400">
                            <Bell className="w-5 h-5" />
                            Planifier un rappel
                        </DialogTitle>
                        <DialogDescription className="text-muted-foreground text-xs">
                            {isDiscordConfigured 
                                ? "Ceci enverra un ping Discord à tous les membres et une notification interne SigilOS."
                                : "Ceci enverra une notification interne SigilOS aux membres."}
                        </DialogDescription>
                    </DialogHeader>

                    {!isDiscordConfigured && (
                        <div className="mx-0 mt-2 px-3 py-2 bg-amber-500/10 border border-amber-500/20 rounded-lg flex items-start gap-2.5">
                            <Bell className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
                            <div className="text-[10px] text-amber-200/80 leading-relaxed font-medium">
                                <span className="text-amber-500 font-bold block mb-0.5">Configuration Discord absente</span>
                                Le salon de notification des Songes n&apos;est pas configuré. Seule la notification interne SigilOS sera envoyée.
                            </div>
                        </div>
                    )}

                    <div className="grid gap-4 py-4">
                        <div className="space-y-2">
                            <label className="text-xs font-medium text-purple-300/80 uppercase tracking-wider">Message</label>
                            <Textarea
                                placeholder="Ex: On commence dans 15 minutes, tout le monde en jeu !"
                                value={message}
                                onChange={(e) => setMessage(e.target.value)}
                                className="bg-white/5 border-white/10 focus:border-purple-500/50 min-h-[80px] text-sm"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-2">
                                <label className="text-xs font-medium text-purple-300/80 uppercase tracking-wider">Date</label>
                                <Popover>
                                    <PopoverTrigger asChild>
                                        <Button
                                            variant={"outline"}
                                            className={cn(
                                                "w-full justify-start text-left font-normal bg-white/5 border-white/10 text-xs",
                                                !date && "text-muted-foreground"
                                            )}
                                        >
                                            <CalendarIcon className="mr-2 h-3.5 w-3.5" />
                                            {date ? format(date, "PPP", { locale: fr }) : <span>Choisir</span>}
                                        </Button>
                                    </PopoverTrigger>
                                    <PopoverContent className="w-auto p-0 bg-black border-white/10 z-[100]">
                                        <Calendar
                                            mode="single"
                                            selected={date}
                                            onSelect={setDate}
                                            initialFocus
                                            className="bg-black text-white"
                                        />
                                    </PopoverContent>
                                </Popover>
                            </div>

                            <div className="space-y-2">
                                <label className="text-xs font-medium text-purple-300/80 uppercase tracking-wider">Heure</label>
                                <div className="relative">
                                    <Clock className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
                                    <Input
                                        type="time"
                                        value={time}
                                        onChange={(e) => setTime(e.target.value)}
                                        className="bg-white/5 border-white/10 pl-9 text-xs"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

                    <DialogFooter>
                        <Button
                            variant="ghost"
                            onClick={() => setIsModalOpen(false)}
                            className="text-white/60 hover:text-white"
                        >
                            Annuler
                        </Button>
                        <Button
                            onClick={handleSendReminder}
                            disabled={loading}
                            className="bg-purple-600 hover:bg-purple-500 text-white min-w-[120px]"
                        >
                            {loading ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                                "Envoyer le ping"
                            )}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        );
    }
}

"use client";

import { useState } from "react";
import Image from "next/image";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/dialog";
import { updateCurrentFloor } from "@/server/actions/songes/dream-run-actions";
import { PALIERS } from "@/lib/songes/types";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { Loader2, CheckCircle2, ChevronRight, Sparkles } from "lucide-react";

interface RunProgressModalProps {
    isOpen: boolean;
    onClose: () => void;
    guildId: string;
    runId: string;
    currentFloor: number;
    onUpdate?: () => void;
}

export function RunProgressModal({
    isOpen,
    onClose,
    guildId,
    runId,
    currentFloor,
    onUpdate,
}: RunProgressModalProps) {
    const [isUpdating, setIsUpdating] = useState(false);

    const handleFloorClick = async (floor: number) => {
        if (floor === currentFloor) return;
        
        setIsUpdating(true);
        try {
            const result = await updateCurrentFloor(guildId, runId, floor);
            if (result.success) {
                toast.success(`Étage ${floor} défini`);
                onUpdate?.();
                onClose();
            } else {
                toast.error(result.error || "Erreur lors de la mise à jour");
            }
        } catch (error) {
            toast.error("Erreur de communication avec le serveur");
        } finally {
            setIsUpdating(false);
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="sm:max-w-2xl bg-[#0a0514] border-white/10 text-white overflow-hidden p-0">
                {/* Background Decor */}
                <div className="absolute inset-0 z-0 opacity-20 pointer-events-none">
                    <div className="absolute top-0 left-1/4 w-64 h-64 bg-purple-600/30 blur-[100px] rounded-full" />
                    <div className="absolute bottom-0 right-1/4 w-64 h-64 bg-blue-600/30 blur-[100px] rounded-full" />
                </div>

                <div className="relative z-10 p-6">
                    <DialogHeader className="mb-6">
                        <DialogTitle className="text-2xl font-black uppercase tracking-tighter flex items-center gap-2">
                            <Sparkles className="w-6 h-6 text-purple-400" />
                            Progression du Rêve
                        </DialogTitle>
                        <DialogDescription className="text-white/50 font-medium">
                            Sélectionnez l'étage actuel de la run pour mettre à jour la progression.
                        </DialogDescription>
                    </DialogHeader>

                    <div className="space-y-6 max-h-[60vh] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent">
                        {PALIERS.map((palier, idx) => {
                            const isCurrentPalier = palier.etages.includes(currentFloor as never);
                            const lastFloor = palier.etages[palier.etages.length - 1];
                            const isCompleted = currentFloor > lastFloor;

                            return (
                                <div key={palier.id} className="relative group">
                                    <div className="flex items-center gap-3 mb-3">
                                        <div 
                                            className={cn(
                                                "relative w-10 h-10 rounded-lg border-2 flex items-center justify-center overflow-hidden transition-all",
                                                isCurrentPalier ? "scale-110 shadow-[0_0_15px_rgba(var(--color),0.4)] border-current" : "opacity-40 border-white/10"
                                            )}
                                            style={{ 
                                                color: palier.couleur,
                                                borderColor: isCurrentPalier ? palier.couleur : undefined,
                                                // @ts-ignore
                                                "--color": palier.couleur
                                            }}
                                        >
                                            <div className="absolute inset-0 opacity-40">
                                                <Image
                                                    src={`/assets/missions/${
                                                        palier.id <= 3 ? `reve${palier.id}` : 
                                                        palier.id === 4 ? "paradoxe1" : "cauchemar1"
                                                    }.png`}
                                                    alt="Icon"
                                                    fill
                                                    className="object-contain p-1"
                                                />
                                            </div>
                                            <span className="relative z-10 text-[10px] font-black drop-shadow-md">
                                                {["I", "II", "III", "IV", "V"][idx]}
                                            </span>
                                        </div>
                                        <h3 className={cn(
                                            "text-xs font-black uppercase tracking-[0.2em] transition-opacity",
                                            isCurrentPalier ? "opacity-100" : "opacity-40"
                                        )} style={{ color: palier.couleur }}>
                                            {palier.nom}
                                        </h3>
                                        {isCompleted && <CheckCircle2 className="w-4 h-4 text-emerald-500 opacity-50" />}
                                    </div>

                                    <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 gap-2">
                                        {palier.etages.map((floor) => {
                                            const isActive = floor === currentFloor;
                                            const isDone = floor < currentFloor;

                                            return (
                                                <button
                                                    key={floor}
                                                    disabled={isUpdating}
                                                    onClick={() => handleFloorClick(floor)}
                                                    className={cn(
                                                        "relative h-12 flex flex-col items-center justify-center rounded-xl border transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:hover:scale-100",
                                                        isActive 
                                                            ? "bg-white text-black border-white shadow-[0_0_20px_rgba(255,255,255,0.3)] z-10" 
                                                            : isDone
                                                                ? "bg-white/5 border-white/10 text-white/30"
                                                                : "bg-black/40 border-white/5 text-white/60 hover:border-white/20 hover:bg-white/10"
                                                    )}
                                                >
                                                    <span className="text-sm font-black">{floor}</span>
                                                    {isDone && <div className="absolute top-1 right-1 w-1.5 h-1.5 rounded-full bg-emerald-500/40" />}
                                                </button>
                                            );
                                        })}
                                    </div>
                                    
                                    {idx < PALIERS.length - 1 && (
                                        <div className="flex justify-center my-4 opacity-10">
                                            <ChevronRight className="w-4 h-4 rotate-90" />
                                        </div>
                                    )}
                                </div>
                            );
                        })}

                        {/* Special Floor: Final Boss */}
                        <div className="pt-4 border-t border-white/5">
                            <button
                                disabled={isUpdating}
                                onClick={() => handleFloorClick(26)}
                                className={cn(
                                    "w-full h-16 rounded-2xl border-2 flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-50",
                                    currentFloor === 26
                                        ? "bg-amber-500 text-black border-amber-400 shadow-[0_0_40px_rgba(245,158,11,0.4)]"
                                        : "bg-amber-500/10 border-amber-500/20 text-amber-500 hover:bg-amber-500/20"
                                )}
                            >
                                <div className="flex items-center gap-4">
                                    <div className="relative w-10 h-10 shrink-0">
                                        <Image
                                            src="/songes/boss_token.png"
                                            alt="Boss"
                                            fill
                                            className="object-contain"
                                        />
                                    </div>
                                    <div className="flex flex-col items-start">
                                        <span className="text-lg font-black uppercase tracking-[0.2em]">Combat Final</span>
                                        <span className="text-[10px] font-bold opacity-60 uppercase tracking-widest">Étage 26+</span>
                                    </div>
                                </div>
                                {currentFloor === 26 && <CheckCircle2 className="w-6 h-6 animate-in zoom-in" />}
                            </button>
                        </div>
                    </div>

                    {/* Loader Overlay */}
                    {isUpdating && (
                        <div className="absolute inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center animate-in fade-in">
                            <div className="flex flex-col items-center gap-3">
                                <Loader2 className="w-10 h-10 text-purple-400 animate-spin" />
                                <span className="text-xs font-black uppercase tracking-[0.3em] text-purple-400/80">Modification...</span>
                            </div>
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Crown, User, LogOut, UserMinus, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { PALIERS, getPalierFromFloor } from "@/lib/songes/types";
import { getMemberProfiles, kickMember, leaveDreamRun } from "@/server/actions/songes/dream-run-actions";
import type { DreamRun, DreamRunMember } from "@prisma/client";

type RunWithMembers = DreamRun & {
    members: DreamRunMember[];
};

interface MemberProfile {
    userId: string;
    pseudoDofus: string | null;
    classe: string | null;
    discordNickname: string | null;
}

interface RunStatsPanelProps {
    guildId: string;
    run: RunWithMembers;
    currentUserId?: string;
    isLeader?: boolean;
}

export function RunStatsPanel({ guildId, run, currentUserId, isLeader = false }: RunStatsPanelProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [profiles, setProfiles] = useState<MemberProfile[]>([]);
    const [loadingAction, setLoadingAction] = useState<string | null>(null);

    const currentPalier = getPalierFromFloor(run.currentFloor || 1);
    const progress = (run.currentFloor / 26) * 100;
    const isMember = run.members.some((m) => m.userId === currentUserId);

    // Load member profiles with Dofus pseudos
    useEffect(() => {
        async function loadProfiles() {
            const userIds = run.members.map((m) => m.userId);
            if (userIds.length > 0) {
                const result = await getMemberProfiles(guildId, userIds);
                if (result.success && result.profiles) {
                    setProfiles(result.profiles as MemberProfile[]);
                }
            }
        }
        loadProfiles();
    }, [run.members]);

    const getDisplayName = (userId: string) => {
        const profile = profiles.find((p) => p.userId === userId);
        if (profile?.pseudoDofus) return profile.pseudoDofus;
        if (profile?.discordNickname) return profile.discordNickname;
        return "Joueur";
    };

    const getClasse = (userId: string) => {
        const profile = profiles.find((p) => p.userId === userId);
        return profile?.classe || null;
    };

    const handleKick = (targetUserId: string) => {
        setLoadingAction(targetUserId);
        startTransition(async () => {
            await kickMember(guildId, run.id, targetUserId);
            router.refresh();
            setLoadingAction(null);
        });
    };

    const handleLeave = async () => {
        setLoadingAction("leave");
        await leaveDreamRun(guildId, run.id);
        // Redirect to songes list after leaving
        router.push(`/dashboard/${guildId}/songes`);
    };

    return (
        <div className="rounded-xl bg-gradient-to-b from-[#1a0933] to-[#0d0520] border border-purple-500/30 p-4">
            <h3 className="text-lg font-semibold text-white mb-4">📊 Statistiques</h3>

            {/* Progress */}
            <div className="mb-4">
                <div className="flex justify-between text-sm mb-2">
                    <span className="text-purple-200">Progression globale</span>
                    <span className="text-amber-400">{Math.round(progress)}%</span>
                </div>
                <div className="h-3 bg-purple-900/50 rounded-full overflow-hidden">
                    <div
                        className="h-full bg-gradient-to-r from-green-500 via-purple-500 to-amber-500 transition-all"
                        style={{ width: `${progress}%` }}
                    />
                </div>
            </div>

            {/* Current Palier */}
            <div className="p-3 rounded-lg bg-purple-900/30 border border-purple-500/20 mb-4">
                <div className="text-sm text-purple-300">Palier actuel</div>
                <div className="text-lg font-bold" style={{ color: currentPalier.couleur }}>
                    {currentPalier.nom}
                </div>
                <div className="text-sm text-purple-300/70">
                    Étages {currentPalier.etages[0]} - {currentPalier.etages[currentPalier.etages.length - 1]}
                </div>
            </div>

            {/* Team with Dofus Pseudos */}
            <div className="mb-4">
                <h4 className="text-sm font-medium text-purple-200 mb-2">Équipe</h4>
                <div className="space-y-2">
                    {run.members.map((member) => {
                        const displayName = getDisplayName(member.userId);
                        const classe = getClasse(member.userId);
                        const isCurrentUser = member.userId === currentUserId;
                        const memberIsLeader = member.userId === run.leaderId;

                        return (
                            <div
                                key={member.id}
                                className="flex items-center gap-2 p-2 rounded-lg bg-purple-900/20 border border-purple-500/20"
                            >
                                <div className="w-8 h-8 rounded-full bg-purple-600/50 flex items-center justify-center">
                                    {memberIsLeader ? (
                                        <Crown className="w-4 h-4 text-amber-400" />
                                    ) : (
                                        <User className="w-4 h-4 text-purple-300" />
                                    )}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="text-sm text-white truncate">{displayName}</div>
                                    <div className="text-xs text-purple-300/70">
                                        {classe && <span className="mr-2">{classe}</span>}
                                        {memberIsLeader ? "👑 Leader" : "Membre"}
                                    </div>
                                </div>

                                {/* Actions */}
                                {!memberIsLeader && (
                                    <>
                                        {/* Kick button (leader only) */}
                                        {isLeader && !isCurrentUser && (
                                            <Button
                                                size="icon"
                                                variant="ghost"
                                                className="h-7 w-7 text-red-400 hover:text-red-300 hover:bg-red-900/30"
                                                onClick={() => handleKick(member.userId)}
                                                disabled={loadingAction === member.userId}
                                            >
                                                {loadingAction === member.userId ? (
                                                    <Loader2 className="w-3 h-3 animate-spin" />
                                                ) : (
                                                    <UserMinus className="w-3 h-3" />
                                                )}
                                            </Button>
                                        )}

                                        {/* Leave button (for current user, if not leader) */}
                                        {isCurrentUser && (
                                            <Button
                                                size="icon"
                                                variant="ghost"
                                                className="h-7 w-7 text-orange-400 hover:text-orange-300 hover:bg-orange-900/30"
                                                onClick={handleLeave}
                                                disabled={loadingAction === "leave"}
                                            >
                                                {loadingAction === "leave" ? (
                                                    <Loader2 className="w-3 h-3 animate-spin" />
                                                ) : (
                                                    <LogOut className="w-3 h-3" />
                                                )}
                                            </Button>
                                        )}
                                    </>
                                )}
                            </div>
                        );
                    })}

                    {/* Empty slots (not clickable) */}
                    {[...Array(4 - run.members.length)].map((_, i) => (
                        <div
                            key={`empty-${i}`}
                            className="flex items-center gap-2 p-2 rounded-lg border border-dashed border-purple-700/50 text-purple-500/50"
                        >
                            <div className="w-8 h-8 rounded-full bg-purple-900/20 flex items-center justify-center text-purple-600">
                                +
                            </div>
                            <div className="text-sm">Slot libre</div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Points de Rêve (Removed per request) */}
        </div>
    );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { updateCurrentFloor } from "@/server/actions/songes/dream-run-actions";
import Image from "next/image";
import { Loader2, CheckCircle2, PlayCircle, Waves, ChevronRight } from "lucide-react";
import { type RoomTypeKey } from "@/lib/songes/types";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";

interface RunTreeProps {
    guildId: string;
    currentFloor: number;
    runId: string;
    isLeader: boolean;
    runStatus: string;
    leaderName: string;
    onStatusChange?: (status: string | null) => void;
    onUpdate?: () => void;
}

const PALIERS_DATA = [
    { id: 1, nom: "Les Pensées oniriques", floors: [1, 2, 3], color: "#10b981", hex: "10b981" },
    { id: 2, nom: "Les Balades fantastiques", floors: [4, 5, 6, 7, 8, 9], color: "#3b82f6", hex: "3b82f6" },
    { id: 3, nom: "Les Espaces imaginaires", floors: [10, 11, 12, 13, 14, 15], color: "#ec4899", hex: "ec4899" },
    { id: 4, nom: "Les Concepts brumeux", floors: [16, 17, 18, 19, 20, 21], color: "#ef4444", hex: "ef4444" },
    { id: 5, nom: "Les Abstractions chimériques", floors: [22, 23, 24, 25], color: "#f59e0b", hex: "f59e0b" },
] as const;

// Chiffres romains
const ROMAN = ["I", "II", "III", "IV", "V"] as const;

/* ─────────────────────────────────────────────── */
/*  Tilt Card — réutilisable                       */
/* ─────────────────────────────────────────────── */
function TiltCard({
    className,
    children,
    onClick,
    disabled,
}: {
    className?: string;
    children: React.ReactNode;
    onClick?: () => void;
    disabled?: boolean;
}) {
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const mouseX = useSpring(x, { stiffness: 600, damping: 120 });
    const mouseY = useSpring(y, { stiffness: 600, damping: 120 });
    const rotateX = useTransform(mouseY, [-0.5, 0.5], ["12deg", "-12deg"]);
    const rotateY = useTransform(mouseX, [-0.5, 0.5], ["-12deg", "12deg"]);

    function onMouseMove(e: React.MouseEvent<HTMLDivElement>) {
        const rect = e.currentTarget.getBoundingClientRect();
        x.set((e.clientX - rect.left) / rect.width - 0.5);
        y.set((e.clientY - rect.top) / rect.height - 0.5);
    }
    function onMouseLeave() { x.set(0); y.set(0); }

    return (
        <motion.div
            onClick={disabled ? undefined : onClick}
            onMouseMove={onMouseMove}
            onMouseLeave={onMouseLeave}
            style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
            className={cn("transition-transform duration-200", className)}
        />
    );
}

/* ─────────────────────────────────────────────── */
/*  Floor Node                                     */
/* ─────────────────────────────────────────────── */
interface FloorNodeProps {
    floor: number;
    isCurrent: boolean;
    isCompleted: boolean;
    isLocked: boolean;
    isLeader: boolean;
    palierColor: string;
    onClick: () => void;
}

function FloorNode({ floor, isCurrent, isCompleted, isLocked, isLeader, palierColor, onClick }: FloorNodeProps) {
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const mouseX = useSpring(x, { stiffness: 500, damping: 100 });
    const mouseY = useSpring(y, { stiffness: 500, damping: 100 });
    const rotateX = useTransform(mouseY, [-0.5, 0.5], ["14deg", "-14deg"]);
    const rotateY = useTransform(mouseX, [-0.5, 0.5], ["-14deg", "14deg"]);

    const canClick = isLeader || (!isLocked && isCurrent);

    function onMouseMove(e: React.MouseEvent<HTMLDivElement>) {
        const rect = e.currentTarget.getBoundingClientRect();
        x.set((e.clientX - rect.left) / rect.width - 0.5);
        y.set((e.clientY - rect.top) / rect.height - 0.5);
    }
    function onMouseLeave() { x.set(0); y.set(0); }

    return (
        <div className="flex flex-col items-center gap-3 perspective-[1000px]">
            <motion.div
                onClick={canClick ? onClick : undefined}
                onMouseMove={onMouseMove}
                onMouseLeave={onMouseLeave}
                style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
                className={cn(
                    "relative w-16 h-16 flex items-center justify-center transition-all duration-200",
                    canClick ? "cursor-pointer" : "cursor-default",
                    isLocked && !isLeader && "opacity-40 grayscale-[0.6]",
                )}
            >
                {/* Shadow / glow */}
                {isCurrent && (
                    <div
                        className="absolute inset-0 rounded-full blur-[20px] opacity-40 animate-pulse pointer-events-none"
                        style={{ background: palierColor, transform: "translateZ(-20px) scale(1.4)" }}
                    />
                )}

                {/* Token image */}
                <div
                    className="relative w-14 h-14"
                    style={{
                        transform: "translateZ(20px)",
                        maskImage: "radial-gradient(circle at center, black 55%, transparent 72%)",
                        WebkitMaskImage: "radial-gradient(circle at center, black 55%, transparent 72%)",
                    }}
                >
                    <Image
                        src="/songes/combat_token.png"
                        alt={`Étage ${floor}`}
                        fill
                        className={cn("object-contain", isCurrent && "brightness-110")}
                    />
                </div>

                {/* Checkmark */}
                {isCompleted && (
                    <div className="absolute -bottom-1 -right-1 z-10" style={{ transform: "translateZ(30px)" }}>
                        <div className="bg-emerald-500 rounded-full p-0.5 border border-black/60 shadow">
                            <CheckCircle2 className="w-3.5 h-3.5 text-white" />
                        </div>
                    </div>
                )}
            </motion.div>

            {/* Label étage */}
            <span
                className={cn(
                    "text-xs font-black tracking-widest uppercase px-3 py-1 rounded-full border transition-all",
                    isCurrent
                        ? "bg-white text-black border-white shadow-[0_0_14px_rgba(255,255,255,0.4)] scale-110"
                        : isCompleted
                            ? "bg-white/15 text-white/70 border-white/15"
                            : "bg-black/40 text-white/35 border-white/10"
                )}
            >
                {floor}
            </span>
        </div>
    );
}

/* ─────────────────────────────────────────────── */
/*  Boss Node (MAJ 3.5 — Vagues infinies)          */
/* ─────────────────────────────────────────────── */
function BossNode({ isCurrent, isCompleted, isLeader, onClick }: {
    isCurrent: boolean;
    isCompleted: boolean;
    isLeader: boolean;
    onClick: () => void;
}) {
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const mouseX = useSpring(x, { stiffness: 500, damping: 100 });
    const mouseY = useSpring(y, { stiffness: 500, damping: 100 });
    const rotateX = useTransform(mouseY, [-0.5, 0.5], ["12deg", "-12deg"]);
    const rotateY = useTransform(mouseX, [-0.5, 0.5], ["-12deg", "12deg"]);

    function onMouseMove(e: React.MouseEvent<HTMLDivElement>) {
        const rect = e.currentTarget.getBoundingClientRect();
        x.set((e.clientX - rect.left) / rect.width - 0.5);
        y.set((e.clientY - rect.top) / rect.height - 0.5);
    }
    function onMouseLeave() { x.set(0); y.set(0); }

    return (
        <div className="flex flex-col items-center gap-4 perspective-[1200px]">
            <motion.div
                onClick={(isLeader || isCompleted) ? onClick : undefined}
                onMouseMove={onMouseMove}
                onMouseLeave={onMouseLeave}
                style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
                className={cn(
                    "relative w-52 h-52 flex items-center justify-center",
                    (isLeader || isCompleted) ? "cursor-pointer" : "cursor-default"
                )}
            >
                {/* Aura */}
                <div
                    className={cn(
                        "absolute inset-8 rounded-full bg-amber-500/20 blur-[50px] transition-all duration-700",
                        isCurrent && "bg-amber-500/40 blur-[70px]"
                    )}
                    style={{ transform: "translateZ(-40px)" }}
                />
                {/* Orbital rings */}
                <div className="absolute inset-0 rounded-full border border-dashed border-amber-500/15 animate-[spin_40s_linear_infinite] pointer-events-none" />
                <div className="absolute inset-4 rounded-full border border-amber-500/10 animate-[spin_25s_linear_infinite_reverse] pointer-events-none" />

                {/* Token */}
                <div
                    className="relative w-40 h-40"
                    style={{
                        transform: "translateZ(20px)",
                        maskImage: "radial-gradient(circle at center, black 60%, transparent 72%)",
                        WebkitMaskImage: "radial-gradient(circle at center, black 60%, transparent 72%)",
                    }}
                >
                    <Image
                        src="/songes/boss_token.png"
                        alt="Combat Final"
                        fill
                        className={cn("object-contain", isCurrent && "brightness-110")}
                        priority
                    />
                </div>

                {/* Checkmark */}
                {isCompleted && (
                    <div className="absolute bottom-6 right-6 z-10" style={{ transform: "translateZ(50px)" }}>
                        <div className="bg-amber-500 text-black rounded-full p-2 shadow-lg animate-in zoom-in spin-in-180">
                            <CheckCircle2 className="w-6 h-6" />
                        </div>
                    </div>
                )}
            </motion.div>

            {/* Label boss */}
            <div className="text-center space-y-1">
                <h4 className="text-3xl font-black text-transparent bg-clip-text bg-gradient-to-b from-amber-100 to-amber-600 uppercase tracking-[0.25em] drop-shadow-[0_4px_12px_rgba(245,158,11,0.5)]">
                    Combat Final
                </h4>
                {/* Badge MAJ 3.5 */}
                <div className="flex items-center justify-center gap-2">
                    <Waves className="w-3.5 h-3.5 text-amber-400/70" />
                    <span className="text-[11px] font-bold text-amber-400/70 uppercase tracking-wider">
                        Vagues infinies
                    </span>
                    <Waves className="w-3.5 h-3.5 text-amber-400/70" />
                </div>
                <p className="text-[10px] text-white/25 tracking-wider">
                    Enchaînez les vagues pour maximiser vos Bribes de Rêve
                </p>
            </div>
        </div>
    );
}

/* ─────────────────────────────────────────────── */
/*  RunTree principal                              */
/* ─────────────────────────────────────────────── */
export function RunTree({ guildId, currentFloor, runId, isLeader, runStatus, leaderName, onStatusChange, onUpdate }: RunTreeProps) {
    const [updating, setUpdating] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);
    const activeRef = useRef<HTMLDivElement>(null);

    // Auto-scroll vers l'étage actif au chargement et au changement
    useEffect(() => {
        if (activeRef.current && scrollRef.current) {
            // Légère temporisation pour laisser le DOM se stabiliser
            const timer = setTimeout(() => {
                activeRef.current?.scrollIntoView({
                    behavior: "smooth",
                    block: "center",
                });
            }, 300);
            return () => clearTimeout(timer);
        }
    }, [currentFloor]);

    const handleCloseRun = async () => {
        const prevStatus = runStatus;
        onStatusChange?.("COMPLETED");
        setUpdating(true);
        const { closeDreamRun } = await import("@/server/actions/songes/dream-run-actions");
        const result = await closeDreamRun(guildId, runId);
        if (result.success) { toast.success("Run clôturée"); onUpdate?.(); }
        else { onStatusChange?.(prevStatus); toast.error(result.error); }
        setUpdating(false);
    };

    const handleReopenRun = async () => {
        const prevStatus = runStatus;
        onStatusChange?.("IN_PROGRESS");
        setUpdating(true);
        const { reopenDreamRun } = await import("@/server/actions/songes/dream-run-actions");
        const result = await reopenDreamRun(guildId, runId);
        if (result.success) { toast.success("Run réouverte"); onUpdate?.(); }
        else { onStatusChange?.(prevStatus); toast.error(result.error); }
        setUpdating(false);
    };

    const handleNodeClick = async (floor: number) => {
        if (!isLeader) return;
        setUpdating(true);
        const result = await updateCurrentFloor(guildId, runId, floor);
        setUpdating(false);
        if (!result.success) toast.error(result.error);
        else { toast.success(`Étage ${floor === 0 ? "Portail" : floor === 26 ? "Combat Final" : floor} défini`); onUpdate?.(); }
    };

    const isBossActive = currentFloor === 26;
    const isBossCompleted = currentFloor > 26;

    return (
        <div className="w-full bg-[#05010a] rounded-xl border border-white/10 flex flex-col relative overflow-hidden shadow-2xl">
            {/* ── Background ── */}
            <div className="absolute inset-0 z-0 pointer-events-none">
                <Image
                    src="/songes/background_dreams.png"
                    alt="Background"
                    fill
                    className="object-cover opacity-50 mix-blend-lighten"
                    quality={80}
                />
                <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_30%,rgba(5,1,10,0.85)_80%)]" />
                <div className="absolute inset-x-0 top-0 h-24 bg-gradient-to-b from-[#05010a] to-transparent" />
                <div className="absolute inset-x-0 bottom-0 h-24 bg-gradient-to-t from-[#05010a] to-transparent" />
                {/* Watermark si run terminée */}
                {runStatus === "COMPLETED" && (
                    <div className="absolute inset-0 z-10 flex items-center justify-center overflow-hidden">
                        <span className="text-8xl font-black text-amber-500/4 uppercase tracking-[0.4em] -rotate-45 select-none whitespace-nowrap">
                            Terminée
                        </span>
                    </div>
                )}
            </div>

            {/* ── Header ── */}
            <div className="relative z-20 px-6 pt-6 pb-2 text-center">
                <h2 className="text-3xl font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-white/80 to-white/40 uppercase tracking-[0.12em] transition-all">
                    Run de {leaderName || "L'Inconnu"}
                </h2>
                <div className="flex items-center justify-center gap-3 mt-1">
                    <div className="h-px w-10 bg-white/15" />
                    <p className="text-white/30 text-xs font-mono uppercase tracking-[0.3em]">
                        Puits des Songes Infinis
                    </p>
                    <div className="h-px w-10 bg-white/15" />
                </div>
            </div>

            {/* ── Scrollable Timeline ── */}
            <div
                ref={scrollRef}
                className="relative z-20 overflow-y-auto max-h-[800px] py-8 px-4 scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent scroll-smooth"
            >
                {/* ── Portail d'entrée ── */}
                <div
                    ref={currentFloor === 0 ? activeRef : undefined}
                    className="flex flex-col items-center mb-10"
                >
                    <div
                        onClick={isLeader ? () => handleNodeClick(0) : undefined}
                        className={cn(
                            "relative w-20 h-20 rounded-full flex items-center justify-center border-2 transition-all duration-300 backdrop-blur-md",
                            isLeader && "cursor-pointer",
                            currentFloor === 0
                                ? "bg-cyan-950/80 border-cyan-400 shadow-[0_0_40px_rgba(6,182,212,0.5)] scale-110"
                                : "bg-black/60 border-cyan-900/50 hover:border-cyan-600/50"
                        )}
                    >
                        <div className="absolute inset-0 rounded-full border border-dashed border-cyan-400/20 animate-[spin_20s_linear_infinite]" />
                        <div className="absolute inset-0 bg-cyan-500/10 blur-xl rounded-full animate-pulse" />
                        <div className="relative z-10 w-12 h-12">
                            <Image
                                src="/assets/songes/départ.png"
                                alt="Départ"
                                fill
                                className="object-contain"
                            />
                        </div>
                        {currentFloor > 0 && (
                            <div className="absolute -bottom-1 -right-1 bg-black rounded-full p-0.5 border border-cyan-500/50">
                                <CheckCircle2 className="w-4 h-4 text-cyan-400" />
                            </div>
                        )}
                    </div>
                    <span className="mt-2 text-[10px] font-black uppercase tracking-[0.25em] text-cyan-700">
                        Portail Dimensionnel
                    </span>
                    {/* Connecteur vers palier I */}
                    <TimelineConnector />
                </div>

                {/* ── Paliers I à V ── */}
                {PALIERS_DATA.map((palier, palierIdx) => {
                    const palierMin = palier.floors[0];
                    const palierMax = palier.floors[palier.floors.length - 1];
                    const isActivePalier = currentFloor >= palierMin && currentFloor <= palierMax;
                    const isPalierCompleted = currentFloor > palierMax;

                    return (
                        <div key={palier.id} className="relative flex gap-4 mb-0">
                            {/* ── Barre latérale colorée (palier indicator) ── */}
                            <div className="flex flex-col items-center shrink-0 w-10">
                                {/* Numéro du palier */}
                                <div
                                    className={cn(
                                        "w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-black border-2 transition-all duration-500 shrink-0",
                                        isActivePalier
                                            ? "scale-110 shadow-[0_0_15px_var(--p-glow)] border-current"
                                            : isPalierCompleted
                                                ? "opacity-50 border-white/10"
                                                : "opacity-30 border-white/5"
                                    )}
                                    style={{
                                        color: palier.color,
                                        borderColor: isActivePalier ? palier.color : undefined,
                                        // @ts-ignore
                                        "--p-glow": palier.color + "66",
                                    }}
                                >
                                    {ROMAN[palierIdx]}
                                </div>

                                {/* Ligne verticale colorée */}
                                <div
                                    className="w-0.5 flex-1 min-h-[120px] transition-opacity duration-500"
                                    style={{
                                        background: `linear-gradient(to bottom, ${palier.color}${isActivePalier ? "80" : "20"}, ${palier.color}10)`,
                                    }}
                                />
                            </div>

                            {/* ── Contenu du palier ── */}
                            <div className="flex-1 pb-8">
                                {/* Nom du palier */}
                                <p
                                    className={cn(
                                        "text-sm font-black uppercase tracking-[0.12em] mb-4 transition-all duration-500",
                                        isActivePalier ? "opacity-100" : isPalierCompleted ? "opacity-50" : "opacity-30"
                                    )}
                                    style={{ color: palier.color }}
                                >
                                    Palier {ROMAN[palierIdx]} — {palier.nom}
                                </p>

                                {/* Grille d'étages */}
                                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-x-4 gap-y-6">
                                    {palier.floors.map((floor) => {
                                        const isActive = currentFloor === floor;
                                        const isDone = floor < currentFloor;
                                        const isLocked = floor > currentFloor;

                                        return (
                                            <div
                                                key={floor}
                                                ref={isActive ? activeRef : undefined}
                                            >
                                                <FloorNode
                                                    floor={floor}
                                                    isCurrent={isActive}
                                                    isCompleted={isDone}
                                                    isLocked={isLocked}
                                                    isLeader={isLeader}
                                                    palierColor={palier.color}
                                                    onClick={() => handleNodeClick(floor)}
                                                />
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>
                    );
                })}

                {/* ── Connecteur vers Boss ── */}
                <div className="ml-10 pl-4">
                    <TimelineConnector color="rgba(245,158,11,0.4)" />
                </div>

                {/* ── Combat Final (Salle 26 — Vagues Infinies) ── */}
                <div
                    ref={isBossActive ? activeRef : undefined}
                    className="flex flex-col items-center mt-4 pb-8"
                >
                    <BossNode
                        isCurrent={isBossActive}
                        isCompleted={isBossCompleted}
                        isLeader={isLeader}
                        onClick={() => handleNodeClick(26)}
                    />

                    {/* ── Actions du leader ── */}
                    {isLeader && currentFloor >= 26 && (
                        <div className="mt-8 flex flex-col items-center gap-3 animate-in fade-in slide-in-from-bottom-4 duration-700">
                            {runStatus === "IN_PROGRESS" && (
                                <>
                                    <p className="text-amber-500/50 text-xs uppercase tracking-widest text-center">
                                        Le rêve touche à sa fin
                                    </p>
                                    <button
                                        onClick={handleCloseRun}
                                        disabled={updating}
                                        className="flex items-center gap-2 px-8 py-3 bg-[#05010a] border border-amber-500/50 text-amber-500 font-bold uppercase tracking-widest text-sm hover:bg-amber-500 hover:text-black transition-all duration-300 shadow-[0_0_20px_rgba(245,158,11,0.2)] hover:shadow-[0_0_40px_rgba(245,158,11,0.5)] disabled:opacity-50"
                                    >
                                        {updating ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle2 className="w-4 h-4" />}
                                        Clôturer la run
                                    </button>
                                </>
                            )}
                            {runStatus === "COMPLETED" && (
                                <>
                                    <p className="text-white/30 text-xs uppercase tracking-widest text-center">
                                        Le rêve est scellé
                                    </p>
                                    <button
                                        onClick={handleReopenRun}
                                        disabled={updating}
                                        className="flex items-center gap-2 px-8 py-3 bg-[#05010a] border border-white/20 text-white font-bold uppercase tracking-widest text-sm hover:bg-white hover:text-black transition-all duration-300 shadow-lg disabled:opacity-50"
                                    >
                                        {updating ? <Loader2 className="w-4 h-4 animate-spin" /> : <PlayCircle className="w-4 h-4" />}
                                        Réouvrir le portail
                                    </button>
                                </>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* ── Legend compacte en bas ── */}
            <div className="relative z-20 border-t border-white/5 px-5 py-3 flex items-center gap-4 flex-wrap">
                <LegendItem color="bg-emerald-500" label="Étage actif" />
                <LegendItem color="bg-white/20" label="Terminé" />
                <LegendItem color="bg-white/5" label="Verrouillé" />
                {isLeader && (
                    <span className="ml-auto text-[10px] text-white/20 uppercase tracking-widest">
                        {isLeader && "Cliquer pour définir l'étage"}
                    </span>
                )}
            </div>

            {/* ── Overlay chargement ── */}
            {updating && (
                <div className="absolute inset-0 bg-black/80 z-50 flex items-center justify-center backdrop-blur-sm animate-in fade-in duration-300">
                    <div className="flex flex-col items-center gap-4">
                        <div className="relative">
                            <div className="absolute inset-0 bg-cyan-500/20 blur-xl rounded-full animate-pulse" />
                            <Loader2 className="w-12 h-12 text-cyan-400 animate-spin relative z-10" />
                        </div>
                        <span className="text-white/60 font-medium tracking-[0.3em] uppercase text-xs animate-pulse">
                            Voyage Onirique...
                        </span>
                    </div>
                </div>
            )}
        </div>
    );
}

/* ─────────────────────────────────────────────── */
/*  Helpers UI                                     */
/* ─────────────────────────────────────────────── */
function TimelineConnector({ color = "rgba(139,92,246,0.3)" }: { color?: string }) {
    return (
        <div className="flex flex-col items-center my-1" style={{ minHeight: "32px" }}>
            <div className="w-px h-6" style={{ background: `linear-gradient(to bottom, ${color}, transparent)` }} />
            <ChevronRight className="w-3 h-3 rotate-90 opacity-20" style={{ color }} />
        </div>
    );
}

function LegendItem({ color, label }: { color: string; label: string }) {
    return (
        <div className="flex items-center gap-1.5">
            <div className={cn("w-2 h-2 rounded-full", color)} />
            <span className="text-[10px] text-white/25 uppercase tracking-wider">{label}</span>
        </div>
    );
}

"use client"

import * as React from "react"
import { Check, ChevronsUpDown, Loader2 } from "lucide-react"
import { useDebounce } from "use-debounce"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"

export interface ComboboxItem {
    value: string
    label: string
    subLabel?: string
}

interface AsyncComboboxProps {
    value?: string
    onSelect: (value: string) => void
    fetcher: (query: string) => Promise<ComboboxItem[]>
    placeholder?: string
    searchPlaceholder?: string
    emptyText?: string
    renderItem?: (item: ComboboxItem) => React.ReactNode
    disabled?: boolean
    className?: string
}

export function AsyncCombobox({
    value,
    onSelect,
    fetcher,
    placeholder = "Sélectionner...",
    searchPlaceholder = "Rechercher...",
    emptyText = "Aucun résultat.",
    renderItem,
    disabled = false,
    className
}: AsyncComboboxProps) {
    const [open, setOpen] = React.useState(false)
    const [inputValue, setInputValue] = React.useState("")
    const [debouncedValue] = useDebounce(inputValue, 300)
    const [items, setItems] = React.useState<ComboboxItem[]>([])
    const [loading, setLoading] = React.useState(false)
    const [selectedLabel, setSelectedLabel] = React.useState<string>("")

    // Fetch items when search changes
    React.useEffect(() => {
        let mounted = true

        const loadItems = async () => {
            setLoading(true)
            try {
                const results = await fetcher(debouncedValue)
                if (mounted) setItems(results)
            } catch (error) {
                console.error("AsyncCombobox fetch error:", error)
            } finally {
                if (mounted) setLoading(false)
            }
        }

        if (open) {
            loadItems()
        }

        return () => {
            mounted = false
        }
    }, [debouncedValue, open, fetcher])

    // Update label when value changes or items load
    React.useEffect(() => {
        if (value) {
            // Try to find label in current items
            const item = items.find(i => i.value === value)
            if (item) {
                setSelectedLabel(item.label)
            } else if (!selectedLabel) {
                // If we have a value but no label (initial load), we might want to fetch the specific item
                // For now, we'll just show the value or rely on the parent to pass the initial label 
                // effectively, this component assumes 'fetcher' returns relevant items including the selected one if hinted
                // or simplistic approach:
                // Currently do nothing, label will be empty until user searches or parent handles it.
                // IMPROVEMENT: Add an `initialLabel` prop if needed.
            }
        } else {
            setSelectedLabel("")
        }
    }, [value, items])

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className={cn("justify-between bg-zinc-950 border-zinc-800 text-zinc-300 w-full hover:bg-zinc-900 hover:text-white", className)}
                    disabled={disabled}
                >
                    {selectedLabel || value ? (selectedLabel || "Chargement...") : placeholder}
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="p-0 bg-zinc-950 border-zinc-800 text-zinc-300" align="start">
                <Command shouldFilter={false}>
                    <CommandInput
                        placeholder={searchPlaceholder}
                        value={inputValue}
                        onValueChange={setInputValue}
                        className="border-none focus:ring-0"
                    />
                    <CommandList>
                        {loading && (
                            <div className="flex items-center justify-center p-4">
                                <Loader2 className="h-4 w-4 animate-spin text-zinc-500" />
                            </div>
                        )}
                        {!loading && items.length === 0 && (
                            <CommandEmpty>{emptyText}</CommandEmpty>
                        )}
                        {!loading && items.length > 0 && (
                            <CommandGroup>
                                {items.map((item) => (
                                    <CommandItem
                                        key={item.value}
                                        value={item.value}
                                        onSelect={(currentValue) => {
                                            onSelect(item.value)
                                            setSelectedLabel(item.label)
                                            setOpen(false)
                                        }}
                                        className="aria-selected:bg-zinc-900 aria-selected:text-white hover:bg-zinc-900 cursor-pointer"
                                    >
                                        <Check
                                            className={cn(
                                                "mr-2 h-4 w-4",
                                                value === item.value ? "opacity-100" : "opacity-0"
                                            )}
                                        />
                                        {renderItem ? renderItem(item) : (
                                            <div className="flex flex-col">
                                                <span>{item.label}</span>
                                                {item.subLabel && <span className="text-xs text-zinc-500">{item.subLabel}</span>}
                                            </div>
                                        )}
                                    </CommandItem>
                                ))}
                            </CommandGroup>
                        )}
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    )
}

"use client";

import { cn } from "@/lib/utils";
import React, { ReactNode } from "react";

interface AuroraBackgroundProps extends React.HTMLProps<HTMLDivElement> {
    children?: ReactNode;
    showRadialGradient?: boolean;
}

export const AuroraBackground = ({
    className,
    children,
