import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
        sigil: "group relative bg-gradient-to-br from-amber-500 to-amber-700 text-white font-bold overflow-hidden shadow-[0_0_20px_-5px_rgba(245,158,11,0.5)] hover:shadow-[0_0_30px_-5px_rgba(245,158,11,0.8)] border-t border-white/20 active:scale-95 transition-all duration-300 uppercase tracking-wide",
        "sigil-emerald": "group relative bg-gradient-to-br from-emerald-500 to-emerald-700 text-white font-bold overflow-hidden shadow-[0_0_20px_-5px_rgba(16,185,129,0.5)] hover:shadow-[0_0_30px_-5px_rgba(16,185,129,0.8)] border-t border-white/20 active:scale-95 transition-all duration-300 uppercase tracking-wide",
        "sigil-destructive": "group relative bg-gradient-to-br from-rose-500 to-rose-700 text-white font-bold overflow-hidden shadow-[0_0_20px_-5px_rgba(244,63,94,0.5)] hover:shadow-[0_0_30px_-5px_rgba(244,63,94,0.8)] border-t border-white/20 active:scale-95 transition-all duration-300 uppercase tracking-wide",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        xl: "h-12 rounded-xl px-10 text-base",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"
  const isSigil = variant && (variant as string).startsWith("sigil")

  const shimmer = isSigil ? (
    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/30 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000 ease-in-out pointer-events-none" />
  ) : null
  const pulse = isSigil ? (
    <div className="w-1.5 h-1.5 rounded-full bg-white animate-pulse shadow-[0_0_8px_white] shrink-0" />
  ) : null

  if (asChild) {
    const child = React.isValidElement(children) ? children : null;
    
    if (!child) return null;

    return (
      <Slot
        data-slot="button"
        data-variant={variant}
        data-size={size}
        className={cn(buttonVariants({ variant, size, className }))}
        {...props}
      >
        {isSigil ? React.cloneElement(child as any, {
          children: (
            <>
              {shimmer}
              {(child as any).props.children}
              {pulse}
            </>
          )
        }) : child}
      </Slot>
    )
  }

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    >
      {shimmer}
      {children}
      {pulse}
    </Comp>
  )
}

export { Button, buttonVariants }

"use client";

import * as React from "react";
import { Check, ChevronsUpDown, X } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";

export type Option = {
    label: string;
    value: string;
    color?: number; // Optional color for badges
    icon?: string | null; // Optional icon URL
};

type Props = {
    options: Option[];
    selected: string[];
    onChange: (selected: string[]) => void;
    placeholder?: string;
    className?: string;
};

export function MultiSelect({
    options,
    selected,
    onChange,
    placeholder = "Select options...",
    className,
}: Props) {
    const [open, setOpen] = React.useState(false);

    const handleUnselect = (item: string) => {
        onChange(selected.filter((i) => i !== item));
    };

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className={cn("w-full justify-between min-h-[40px] h-auto", className)}
                >
                    <div className="flex gap-1 flex-wrap">
                        {selected.length === 0 && <span className="text-muted-foreground font-normal">{placeholder}</span>}
                        {selected.length > 0 && selected.length <= 5 && (
                            selected.map((itemValue) => {
                                const option = options.find((o) => o.value === itemValue);
                                return (
                                    <Badge
                                        variant="secondary"
                                        key={itemValue}
                                        className="mr-1 mb-1 pr-1"
                                        style={option?.color ? {
                                            borderColor: `#${option.color.toString(16).padStart(6, '0')}`,
                                            borderLeftWidth: '4px'
                                        } : {}}
                                    >
                                        {option?.icon && (
                                            <img src={option.icon} alt="" className="w-3.5 h-3.5 mr-1.5 object-contain" />
                                        )}
                                        {option?.label || itemValue}
                                        <div
                                            className="ml-1 ring-offset-background rounded-full outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 cursor-pointer p-0.5 hover:bg-slate-700/50"
                                            onKeyDown={(e) => {
                                                if (e.key === "Enter") {
                                                    handleUnselect(itemValue);
                                                    e.stopPropagation();
                                                }
                                            }}
                                            onMouseDown={(e) => {
                                                e.preventDefault();
                                                e.stopPropagation();
                                            }}
                                            onClick={() => handleUnselect(itemValue)}
                                        >
                                            <X className="h-3 w-3 text-muted-foreground hover:text-foreground" />
                                        </div>
                                    </Badge>
                                );
                            })
                        )}
                        {selected.length > 5 && (
                            <Badge variant="secondary" className="mr-1 mb-1">
                                {selected.length} séléctionnés
                            </Badge>
                        )}
                    </div>
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[300px] p-0 z-[10000] shadow-2xl border-slate-700 bg-slate-900" align="start" sideOffset={5}>
                <Command className="bg-slate-900 text-slate-200">
                    <CommandInput placeholder="Rechercher..." className="border-none focus:ring-0 text-white" />
                    <CommandList>
                        <CommandEmpty>Aucun résultat.</CommandEmpty>
                        <CommandGroup className="max-h-64 overflow-auto">
                            {options.map((option) => (
                                <CommandItem
                                    key={option.value}
                                    value={option.label}
                                    onSelect={() => {
                                        onChange(
                                            selected.includes(option.value)
                                                ? selected.filter((item) => item !== option.value)
                                                : [...selected, option.value]
                                        );
                                    }}
                                    className="data-[selected=true]:bg-slate-800 text-slate-200 cursor-pointer"
                                >
                                    <Check
                                        className={cn(
                                            "mr-2 h-4 w-4",
                                            selected.includes(option.value) ? "opacity-100" : "opacity-0"
                                        )}
                                    />
                                    {option.icon ? (
                                        <img src={option.icon} alt="" className="w-5 h-5 mr-2 object-contain bg-slate-800 rounded p-0.5" />
                                    ) : (
                                        <span
                                            className="w-2 h-2 rounded-full mr-2"
                                            style={{ backgroundColor: option.color ? `#${option.color.toString(16).padStart(6, '0')}` : 'gray' }}
                                        />
                                    )}
                                    {option.label}
                                </CommandItem>
                            ))}
                        </CommandGroup>
                    </CommandList>
                </Command>
            </PopoverContent>
        </Popover>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
    X, Sword, Users, Trophy, ChevronDown, CheckCircle2, Circle, Info, Loader2,
    MapPin, Crown, ChevronRight
} from "lucide-react";
import { getDungeonDirectory } from "@/server/actions/dungeon-finder-actions";
import { searchDungeons } from "@/server/actions/game-data-actions";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { getClass } from "@/lib/dofus-assets";

interface Dungeon {
    id: string | number;
    name: any;
    bossName: string;
    level: number;
    imageUrl?: string | null;
}

interface AchievementDirectory {
    achievementId: string;
    achievementName: string;
    iconUrl: string | null;
    points: number;
    hasCompleted: { id: string; name: string; imageUrl: string | null; classe: string | null }[];
    missing: { id: string; name: string; imageUrl: string | null; classe: string | null }[];
}

interface DungeonDetailModalProps {
    isOpen: boolean;
    onClose: () => void;
    dungeons: Dungeon[];
    guildId: string;
}

export function DungeonDetailModal({ isOpen, onClose, dungeons, guildId }: DungeonDetailModalProps) {
    const [selectedDungeonIndex, setSelectedDungeonIndex] = useState(0);
    const [directoryData, setDirectoryData] = useState<AchievementDirectory[]>([]);
    const [resolvedDj, setResolvedDj] = useState<any>(null);
    const [loading, setLoading] = useState(false);
    const [expandedAchv, setExpandedAchv] = useState<string | null>(null);

    const dungeon = dungeons[selectedDungeonIndex];

    useEffect(() => {
        if (isOpen && dungeon) {
            setLoading(true);
            setDirectoryData([]);
            setExpandedAchv(null);
            setResolvedDj(null);
            
            const dName = typeof dungeon.name === 'string' ? dungeon.name : dungeon.name?.fr;
            
            // Resolve real DJ info for official boss name, image, etc.
            searchDungeons(dName || dungeon.id.toString()).then(res => {
                if (res.success && res.data && res.data.length > 0) {
                    setResolvedDj(res.data[0]);
                }
            });

            getDungeonDirectory(guildId, dungeon.id.toString(), dName).then((res) => {
                if (res.success && res.data) {
                    setDirectoryData(res.data);
                    if (res.data.length > 0) {
                        setExpandedAchv(res.data[0].achievementId);
                    }
                }
                setLoading(false);
            });
        }
    }, [isOpen, dungeon, guildId]);

    if (!isOpen || !dungeon) return null;

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent showCloseButton={false} className="w-[95vw] max-w-2xl bg-[#0a0f18]/95 backdrop-blur-3xl border border-white/10 shadow-[0_50px_100px_rgba(0,0,0,0.8)] rounded-[2.5rem] text-white overflow-hidden p-0 gap-0 custom-scrollbar">
                
                {/* Header with Background Image */}
                <div className="relative h-48 bg-slate-950 border-b border-white/5 overflow-hidden shrink-0">
                    {(resolvedDj?.imageUrl || dungeon.imageUrl) && (
                        <motion.img 
                            initial={{ scale: 1.1, opacity: 0 }}
                            animate={{ scale: 1, opacity: 0.3 }}
                            src={resolvedDj?.imageUrl || dungeon.imageUrl} 
                            alt="" 
                            className="absolute inset-0 w-full h-full object-cover" 
                        />
                    )}
                    <div className="absolute inset-0 bg-gradient-to-t from-[#0a0f18] via-[#0a0f18]/40 to-transparent" />
                    
                    <button 
                        onClick={onClose}
                        className="absolute top-6 right-6 p-2 rounded-xl bg-white/5 hover:bg-white/10 border border-white/10 text-white/50 hover:text-white transition-all z-20"
                    >
                        <X size={20} />
                    </button>

                    <div className="absolute bottom-6 left-8 right-8 flex items-end justify-between gap-4 z-10">
                        <div className="flex items-center gap-6">
                            <div className="w-20 h-20 rounded-2xl bg-slate-900/80 border border-white/10 shadow-2xl overflow-hidden flex items-center justify-center shrink-0">
                                {(resolvedDj?.imageUrl || dungeon.imageUrl) ? (
                                    <img src={resolvedDj?.imageUrl || dungeon.imageUrl} alt="" className="w-full h-full object-cover" />
                                ) : (
                                    <Sword className="w-8 h-8 text-slate-400" />
                                )}
                            </div>
                            <div className="min-w-0">
                                <div className="flex items-center gap-3 mb-1">
                                    <span className="px-2 py-0.5 rounded-lg bg-amber-500/20 border border-amber-500/30 text-amber-500 text-[10px] font-black uppercase tracking-widest italic">
                                        Donjon Niveau {resolvedDj?.level || dungeon.level}
                                    </span>
                                </div>
                                <h2 className="text-3xl font-black text-white truncate drop-shadow-2xl uppercase italic tracking-tighter">
                                    {resolvedDj?.name || (typeof dungeon.name === 'string' ? dungeon.name : dungeon.name?.fr || "Donjon")}
                                </h2>
                                <p className="text-sm font-bold text-white/40 flex items-center gap-2 uppercase tracking-[0.2em]">
                                    <Sword size={14} className="text-amber-500" /> {resolvedDj?.bossName || "Boss Inconnu"}
                                </p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Navigation if multiple dungeons */}
                {dungeons.length > 1 && (
                    <div className="flex bg-black/40 border-b border-white/5 p-2 gap-2 overflow-x-auto custom-scrollbar">
                        {dungeons.map((d, idx) => (
                            <button
                                key={d.id}
                                onClick={() => setSelectedDungeonIndex(idx)}
                                className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase italic transition-all whitespace-nowrap ${
                                    selectedDungeonIndex === idx 
                                        ? "bg-amber-600 text-white shadow-lg shadow-amber-600/20" 
                                        : "bg-white/5 text-white/30 hover:bg-white/10 hover:text-white/50 border border-white/5"
                                }`}
                            >
                                {typeof d.name === 'string' ? d.name : d.name?.fr || "Donjon"}
                            </button>
                        ))}
                    </div>
                )}

                {/* Content */}
                <div className="p-8 space-y-6 overflow-y-auto max-h-[60vh] custom-scrollbar bg-[#0a0f18]/20">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center py-20 gap-4">
                            <Loader2 className="w-10 h-10 text-amber-500 animate-spin" />
                            <p className="text-white/20 font-black uppercase text-[10px] tracking-[0.3em] animate-pulse">Analyse des Succès de Guilde...</p>
                        </div>
                    ) : directoryData.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-16 gap-4 bg-white/[0.02] border border-dashed border-white/5 rounded-3xl">
                            <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center border border-white/5">
                                <Info className="text-white/20" size={24} />
                            </div>
                            <p className="text-white/30 font-bold text-sm italic">Aucun succès répertorié pour ce donjon.</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            <div className="flex items-center gap-4 mb-6">
                                <h3 className="text-white/20 font-black uppercase text-[10px] tracking-[0.3em]">Répertoire des Succès</h3>
                                <div className="flex-1 h-px bg-white/5" />
                            </div>

                            {directoryData.map((achv) => {
                                const isExpanded = expandedAchv === achv.achievementId;
                                const completionRate = Math.round((achv.hasCompleted.length / (achv.hasCompleted.length + achv.missing.length)) * 100);

                                return (
                                    <div 
                                        key={achv.achievementId}
                                        className={`rounded-[1.5rem] border transition-all duration-500 overflow-hidden ${
                                            isExpanded 
                                                ? "bg-white/[0.03] border-amber-500/30 shadow-2xl" 
                                                : "bg-white/[0.01] border-white/5 hover:border-white/10 hover:bg-white/[0.02]"
