                                </div>
                                <div className="flex items-center gap-2">
                                    <div className="flex items-center gap-1 mr-2 border-r border-white/10 pr-3">
                                        <button
                                            onClick={() => setMinimapRecenterTrigger(t => t + 999)} // Use specific pattern for zoom in
