"use client";

import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import { Loader2 } from "lucide-react";

// Dynamically import InteractiveMap to avoid SSR issues with Leaflet interacting with `window`
const MapWithNoSSR = dynamic<any>(
    () => import('./interactive-map-v2'),
    {
        ssr: false,
        loading: () => (
            <div className="w-full h-full flex items-center justify-center bg-[#111] rounded-xl border border-white/10">
                <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
        )
    }
);
export function MapViewer({ 
    initialLadder, 
    initialTab, 
    gameStatuses,
    initialX,
    initialY,
    initialZoom,
    initialWorldId,
    hideUI,
    userName,
    userAvatar,
    isAdmin
}: { 
    initialLadder?: any[], 
    initialTab?: 'map' | 'games', 
    gameStatuses?: any[],
    initialX?: number,
    initialY?: number,
    initialZoom?: number,
    initialWorldId?: number,
    hideUI?: boolean,
    userName?: string,
    userAvatar?: string,
    isAdmin?: boolean
}) {
    const [data, setData] = useState<any>(null);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchMapData() {
            try {
                const [resMap, resWorlds] = await Promise.all([
                    fetch('/game-data/worldmap.json'),
                    fetch('/game-data/worlds.json')
                ]);

                if (!resMap.ok || !resWorlds.ok) throw new Error("Could not load map data");

                const mapData = await resMap.json();
                const worldsData = await resWorlds.json();

                setData({
                    ...mapData,
                    worlds: worldsData
                });
            } catch (err: any) {
                setError(err.message || "Failed to load map data");
            } finally {
                setLoading(false);
            }
        }
        fetchMapData();
    }, []);

    if (error) {
        return (
            <div className="p-4 bg-red-500/10 border border-red-500/50 rounded-lg text-red-500 text-sm">
                Erreur de chargement de la carte : {error}
            </div>
        );
    }

    if (loading || !data) {
        return (
            <div className="w-full h-[70vh] flex flex-col items-center justify-center bg-[#111] rounded-xl border border-white/10">
                <Loader2 className="h-8 w-8 animate-spin text-teal-500 mb-4" />
                <p className="text-zinc-400 text-sm font-bold uppercase tracking-widest italic opacity-50">Synchronisation du Monde...</p>
            </div>
        );
    }

    return (
        <MapWithNoSSR 
            worldMap={data} 
            initialLadder={initialLadder} 
            initialTab={initialTab} 
            gameStatuses={gameStatuses} 
            initialX={initialX}
            initialY={initialY}
            initialZoom={initialZoom}
            initialWorldId={initialWorldId}
            hideUI={hideUI}
            userName={userName}
            userAvatar={userAvatar}
            isAdmin={isAdmin}
        />
    );
}

import { useEffect, useState } from "react";
// @ts-ignore
import { useSocket } from "@/hooks/use-socket"; // Assuming this exists, if not I will adapt

export interface VoiceUser {
    userId: string;
    userName: string;
    avatar: string | null;
    channelId: string;
    channelName: string;
    isMute: boolean;
    isDeaf: boolean;
    isSpeaking?: boolean;
}

export function useDiscordVoice(guildId: string | undefined, socket: any) {
    const [voiceUsers, setVoiceUsers] = useState<VoiceUser[]>([]);

    useEffect(() => {
        if (!socket || !guildId || guildId === "undefined") return;

        // Listener for voice updates
        const handleUpdate = (data: { guildId: string; users: VoiceUser[] }) => {
            if (data.guildId === guildId) {
                setVoiceUsers(data.users);
            }
        };

        socket.on("discord:voice:update", handleUpdate);
        
        // Request immediate sync now that listener is ready
        socket.emit("discord:voice:request", { guildId });

        // Optional: request initial state? 
        // For now we wait for the next push or assume the server pushes regularly.
        
        return () => {
            socket.off("discord:voice:update", handleUpdate);
        };
    }, [socket, guildId]);

    return { voiceUsers };
}

