 * Focus: Monstres, Dofus, Ressources, Items (stuff de panoplie)
 * Exclut: Panoplies complètes, Archimonstres, Donjons, Quêtes, Succès
 * Inclut: URLs d'icônes pour les indices visuels
 */

async function fetchFromDofusDB(endpoint: string, maxEntries: number = 2000) {
  let allData: any[] = [];
  const limit = 50;
  
  console.log(`📡 Récupération de ${endpoint} (jusqu'à ${maxEntries})...`);

  for (let skip = 0; skip < maxEntries; skip += limit) {
    const url = `https://api.dofusdb.fr/${endpoint}?lang=fr&$limit=${limit}&$skip=${skip}`;
    try {
      const res = await fetch(url);
      if (!res.ok) break;
      const json = await res.json() as { data: any[] };
      const batchSize = json.data?.length || 0;
      if (!json.data || batchSize === 0) break;
      allData = [...allData, ...json.data];
      
      if (skip % 1000 === 0 && skip > 0) {
        console.log(`  > ${skip} éléments récupérés...`);
      }
      
      if (batchSize < limit) break;
    } catch (error) {
      break;
    }
  }
  return allData;
}

function classifyWord(name: string, level: number = 1): "facile" | "moyen" | "difficile" {
  const length = name.length;
  // Facile: Niveaux < 60, noms courts (< 12)
  if (level < 60 && length < 12) return "facile";
  // Moyen: Niveaux < 180, noms moyens (< 20)
  if (level < 180 && length < 20) return "moyen";
  // Difficile: Le reste
  return "difficile";
}

async function generateWords() {
  console.log("🚀 Lancement de la génération massive (DofusDB Explorer)...");
  
  // Les monstres sont moins nombreux que les items (environ 3000-4000 réels)
  const monsters = await fetchFromDofusDB("monsters", 5000);
  // Les items sont extrêmement nombreux (plus de 25000)
  const items = await fetchFromDofusDB("items", 25000);

  const words = {
    facile: new Map<string, any>(),
    moyen: new Map<string, any>(),
    difficile: new Map<string, any>()
  };

  // 1. Monstres
  monsters.forEach(m => {
    const name = m.name?.fr;
    // On ignore les noms trop courts (<2), trop longs (>25) ou techniques
    if (!name || name.includes("Archimonstre") || name.length < 2 || name.length > 25) return;
    const lowerName = name.toLowerCase();
    
    // Filtres d'exclusion
    if (lowerName.includes("donjon") || lowerName.includes("quête") || lowerName.includes("succès") || lowerName.includes("pnj") || lowerName.includes("test")) return;
    if (name.startsWith("Panoplie")) return;

    const iconUrl = m.img || (m.ankamaId ? `https://static.dofusdb.fr/monsters/${m.ankamaId}.png` : null);
    if (!iconUrl || iconUrl.includes("undefined")) return;

    const difficulty = classifyWord(name, m.level);
    words[difficulty].set(name, { word: name, iconUrl });
  });

  // 2. Items & Dofus & Ressources
  items.forEach(i => {
    const name = i.name?.fr;
    if (!name || name.length < 3 || name.length > 25) return;
    
    // Filtrage thématique strict
    const lowerName = name.toLowerCase();
    if (name.startsWith("(") || name.includes("Test") || lowerName.includes("quête") || lowerName.includes("succès") || lowerName.includes("pnj") || lowerName.includes("[")) return;
    if (name.startsWith("Panoplie")) return;

    const iconUrl = i.img || (i.ankamaId ? `https://static.dofusdb.fr/items/${i.ankamaId}.png` : null);
    if (!iconUrl || iconUrl.includes("/0.png") || iconUrl.includes("undefined")) return;

    // Priorité Dofus (toujours en difficile ou moyen si petit)
    if (lowerName.includes("dofus")) {
        words.difficile.set(name, { word: name, iconUrl });
        return;
    }

    const difficulty = classifyWord(name, i.level);
    words[difficulty].set(name, { word: name, iconUrl });
  });

  // Export & Stats
  const result = {
    facile: Array.from(words.facile.values()).sort((a, b) => a.word.localeCompare(b.word)),
    moyen: Array.from(words.moyen.values()).sort((a, b) => a.word.localeCompare(b.word)),
    difficile: Array.from(words.difficile.values()).sort((a, b) => a.word.localeCompare(b.word))
  };

  const total = result.facile.length + result.moyen.length + result.difficile.length;
  console.log(`✅ Génération GÉANTE terminée !`);
  console.log(`📊 Statistiques finales :`);
  console.log(`  - Facile    : ${result.facile.length}`);
  console.log(`  - Moyen     : ${result.moyen.length}`);
  console.log(`  - Difficile : ${result.difficile.length}`);
  console.log(`  - TOTAL     : ${total} mots avec icônes.`);

  const outputPath = path.resolve(process.cwd(), "src/server/games/SigilSkribbl/generated-words.json");
  fs.writeFileSync(outputPath, JSON.stringify(result, null, 2));
}

generateWords().catch(console.error);

export const HONEYPOT_FIELD_NAME = "hp_ignore_field";

/**
 * Validate honeypot field
 * Returns true if it's a human (field is empty), false if it's a bot (field is filled)
 */
export function validateHoneypot(formData: FormData | Record<string, any>): boolean {
    const value = formData instanceof FormData 
        ? formData.get(HONEYPOT_FIELD_NAME) 
        : formData[HONEYPOT_FIELD_NAME];
    
    // If the field is present and NOT empty, it's likely a bot
    return !value;
}

import { writeFile, mkdir } from "fs/promises";
import { dirname } from "path";
import sharp from "sharp";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB before optimization

// Optimization settings per type
const IMAGE_SIZES = {
    monster: 512,      // Monsters: 512px max
    achievement: 256,  // Achievements: 256px max (icons)
    dungeon: 512,      // Dungeons: 512px max
    item: 256          // Items/Bonuses: 256px max
};

type ImageType = "monster" | "achievement" | "dungeon" | "item";

export async function downloadExternalImage(
    url: string,
    destinationPath: string,
    type: ImageType
): Promise<{ success: boolean; path?: string; error?: string; sizeReduction?: string }> {
    try {
        // 1. Fetch image (no domain restriction - super admin can download from anywhere)
        const response = await fetch(url, {
            headers: {
                "User-Agent": "SigilOS/1.0",
                "Accept": "image/*"
            }
        });

        if (!response.ok) {
            return { success: false, error: `HTTP ${response.status}: ${response.statusText}` };
        }

        // 2. Validate content-type
        const contentType = response.headers.get("content-type");
        if (!contentType?.startsWith("image/")) {
            return { success: false, error: `Not an image (got ${contentType})` };
        }

        // 3. Get buffer and check size
        const buffer = Buffer.from(await response.arrayBuffer());
        const originalSize = buffer.length;

        if (originalSize > MAX_FILE_SIZE) {
            return { success: false, error: `File too large (${(originalSize / 1024 / 1024).toFixed(2)} MB)` };
        }

        // 5. Optimize image with sharp
        const maxSize = IMAGE_SIZES[type];
        const optimizedBuffer = await sharp(buffer)
            .resize(maxSize, maxSize, {
                fit: "inside",           // Preserve aspect ratio
                withoutEnlargement: true // Don't upscale small images
            })
            .webp({ quality: 80 })     // Convert to WebP @ 80% quality
            .toBuffer();

        const optimizedSize = optimizedBuffer.length;
        const reduction = ((1 - optimizedSize / originalSize) * 100).toFixed(0);

        // 6. Ensure directory exists
        const dir = dirname(destinationPath);
        await mkdir(dir, { recursive: true });

        // 7. Write optimized file (force .webp extension)
        const webpPath = destinationPath.replace(/\.(png|jpg|jpeg|gif)$/i, ".webp");
        await writeFile(webpPath, optimizedBuffer);

        // 8. Return relative path for DB (extract from absolute Windows path)
        // webpPath = "A:\SigilOS\public\game-data\monsters\blop.webp"
        // We want: "/game-data/monsters/blop.webp"
        const pathParts = webpPath.split("public");
        const relativePath = pathParts.length > 1
            ? pathParts[1].replace(/\\/g, "/")  // Replace backslashes with forward slashes
            : webpPath.replace(/\\/g, "/");


        return {
            success: true,
            path: relativePath,
            sizeReduction: `${reduction}% (${(originalSize / 1024).toFixed(0)}KB → ${(optimizedSize / 1024).toFixed(0)}KB)`
        };
    } catch (error: any) {
        console.error("[ImageDownloader] Error:", error);
        return { success: false, error: error.message || "Unknown error" };
    }
}

/**
 * LLM-based OCR Service using OCR.space API
 * 
 * Uses OCR.space (Free Tier) for image text extraction:
 * - Simple REST API
 * - Supports French language ('fre')
 * - Rate limit: ~25,000 requests/month (Free) -> We track this locally
 * - Built-in content moderation
 * - Rate limit fallback to manual validation
 * 
 * @module lib/llm-ocr
 */

import { createHash } from 'crypto';
import sharp from 'sharp';
import { db } from '@/lib/prisma';
import { logger } from '@/lib/logger';

// =============================================================================
// API USAGE TRACKING
// =============================================================================

/**
 * Track OCR.space API usage for monitoring on /god page.
 * Increments daily counter per endpoint using upsert.
 */
export async function trackOcrApiUsage(endpoint: string): Promise<void> {
    try {
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        await db.ocrApiUsage.upsert({
            where: {
                date_endpoint: { date: today, endpoint }
            },
            update: {
                count: { increment: 1 }
            },
            create: {
                date: today,
                endpoint,
                count: 1
            }
        });
    } catch (error) {
        logger.warn('[LLM-OCR] Failed to track API usage', { error });
        // Don't fail the OCR call if tracking fails
    }
}

// =============================================================================
// TYPES
// =============================================================================

export interface OcrResult {
    success: boolean;

    // Extracted text content
    text: string;

    // Confidence score (0-100)
    confidence: number;

    // Did the model detect victory indicators?
    isVictory: boolean;

    // Content moderation flags
    moderation: {
        isAppropriate: boolean;
        reason?: string;
    };

    // Raw model response for debugging
    rawResponse?: string;

    // Error message if failed
    error?: string;
}

export interface OcrRequest {
    // Base64 encoded image data
    imageBase64: string;

    // MIME type (image/png, image/jpeg, image/webp)
    mimeType: string;

    // Optional context hint for better accuracy
    context?: 'mission' | 'achievement' | 'ladder';
}

// =============================================================================
// CONFIGURATION & ENVIROMENT
// =============================================================================

const OCR_SPACE_API_KEY = process.env.OCR_SPACE_API_KEY || 'helloworld';
const OCR_SPACE_URL = 'https://api.ocr.space/parse/image';
const AUTO_VALIDATE_THRESHOLD = parseInt(process.env.OCR_AUTO_VALIDATE_THRESHOLD || '70', 10);

// Default timeout for OCR calls
const OCR_TIMEOUT_MS = 30000;

/**
 * Interface for OCR.space response
 */
interface OcrSpaceResponse {
    ParsedResults?: Array<{
        ParsedText: string;
        ErrorMessage?: string;
        ErrorDetails?: string;
    }>;
    IsErroredOnProcessing: boolean;
    ErrorMessage?: string[];
    ErrorDetails?: string;
    ProcessingTimeInMilliseconds?: string;
}


// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * Call OCR.space API
 */
async function callOcrSpace(
    imageBase64: string,
    language: string = 'fre'
): Promise<string> {
    if (!OCR_SPACE_API_KEY) {
        throw new Error('OCR_SPACE_API_KEY is not configured');
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), OCR_TIMEOUT_MS);

    try {

        // OCR.space expects base64 with data URI prefix or a multipart upload
        const formData = new URLSearchParams();
        formData.append('apikey', OCR_SPACE_API_KEY);
        formData.append('base64Image', `data:image/jpeg;base64,${imageBase64}`);
        formData.append('language', language);
        formData.append('isOverlayRequired', 'false');
        formData.append('OCREngine', '2'); // Engine 2 is usually better for numbers/tables

        const response = await fetch(OCR_SPACE_URL, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: formData,
            signal: controller.signal,
        });

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`OCR.space API error: ${response.status} - ${errorText}`);
        }

        const result: OcrSpaceResponse = await response.json();

        if (result.IsErroredOnProcessing) {
            throw new Error(`OCR.space processing error: ${result.ErrorMessage?.join(', ') || 'Unknown error'}`);
        }

        const text = result.ParsedResults?.[0]?.ParsedText || '';

        // Track API usage (fire-and-forget)
        trackOcrApiUsage('ocr.space').catch(() => { });

        return text;

    } finally {
        clearTimeout(timeoutId);
    }
}

/**
 * Check if OCR service is configured
 */
export async function checkOcrHealth(): Promise<{
    available: boolean;
    error?: string;
}> {
    if (!OCR_SPACE_API_KEY || OCR_SPACE_API_KEY === 'helloworld') {
        return {
            available: false,
            error: 'OCR_SPACE_API_KEY not configured or using demo key',
        };
    }

    return {
        available: true,
    };
}

// =============================================================================
// MAIN OCR FUNCTION
// =============================================================================

/**
 * Analyze an image using Qwen2-VL vision model
 * 
 * @param request - Image data and context
 * @returns OCR result with text, confidence, and moderation flags
 */
export async function analyzeImage(request: OcrRequest): Promise<OcrResult> {
    // DEV MODE: Skip OCR when Ollama is not available
    const skipOcr = process.env.DEV_SKIP_OCR === 'true';
    if (skipOcr) {
        return {
            success: true,
            text: '[DEV MODE] OCR skipped - manual validation required',
            confidence: 0, // Low confidence forces manual validation
            isVictory: false,
            moderation: { isAppropriate: true },
            rawResponse: 'DEV_SKIP_OCR',
        };
    }

    try {
        // Optimize image (resize & compress) to reduce API payload
        const optimizedImage = await optimizeImage(request.imageBase64);

        // Call OCR.space instead of Gemini
        const response = await callOcrSpace(optimizedImage, 'fre');


        // Parse the text response
        const parsed = parseModelResponse(response);



        return {
            success: true,
            text: parsed.extractedText,
            confidence: parsed.confidence,
            isVictory: parsed.isVictory,
            moderation: {
                isAppropriate: parsed.isAppropriate,
                reason: parsed.inappropriateReason || undefined,
            },
            rawResponse: response,
        };

    } catch (error: unknown) {
        logger.error('[LLM-OCR] Analysis failed', { error });

        // CONNECTION ERROR: Fallback to manual validation
        const isConnectionError = error instanceof Error &&
            (error.message.includes('ECONNREFUSED') ||
                error.message.includes('fetch failed') ||
                error.name === 'AbortError' ||
                error.message.includes('aborted') ||
                error.message.includes('timeout'));

        if (isConnectionError) {
            logger.warn('[LLM-OCR] OCR Service unreachable - falling back to manual validation');
            return {
                success: true,
                text: '[OCR indisponible] Validation manuelle requise',
                confidence: 0,
                isVictory: false,
                moderation: { isAppropriate: true },
                error: 'OCR service unreachable - manual validation required',
            };
        }

        return {
            success: false,
            text: '',
            confidence: 0,
            isVictory: false,
            moderation: { isAppropriate: true },
            error: error instanceof Error ? error.message : 'Unknown error',
        };
    }
}


// =============================================================================
// RESPONSE PARSING
// =============================================================================

interface ParsedModelResponse {
    extractedText: string;
    isVictory: boolean;
    victoryIndicators: string[];
    confidence: number;
    isAppropriate: boolean;
    inappropriateReason: string | null;
}

function parseModelResponse(rawResponse: string): ParsedModelResponse {
    const text = rawResponse.toLowerCase();

    // 1. EXTRACT SCORE (Dofus Success Points)
    // Goal: Handle "7 704", "15000", and "7 7049" (where 9 is a trophy)

    // Clean text: replace commas/dots often read as thousand separators by spaces
    const cleanRaw = rawResponse.replace(/[,]/g, ' ').replace(/\./g, ' ');

    // Find all digit groups
    const digitGroups = cleanRaw.match(/\d+/g) || [];

    const candidates: number[] = [];

    // Case A: Number is split by space (e.g., "7 704")
    for (let i = 0; i < digitGroups.length - 1; i++) {
        const combined = digitGroups[i] + digitGroups[i + 1];
        const val = parseInt(combined, 10);
        if (val > 0 && val < 300000) candidates.push(val);
    }

    // Case B: Simple numbers
    digitGroups.forEach(g => {
        const val = parseInt(g, 10);
        if (val > 0) candidates.push(val);
    });

    // Case C: Full string of digits (ignoring everything else)
    const allDigits = rawResponse.replace(/[^\d]/g, '');
    if (allDigits && allDigits.length >= 3 && allDigits.length <= 5) candidates.push(parseInt(allDigits, 10));

    // Filter and sanitize candidates based on Dofus max score (~23,000)
    const MAX_DOFUS_SCORE = 24000;

    let bestScore = 0;
    candidates.forEach(score => {
        let s = score;

        // TROPHY ICON FIX: if score is > MAX and ends with a digit, 
        // it's likely the trophy icon was read as a digit (e.g., 7704 + 🏆(9) = 77049)
        if (s > MAX_DOFUS_SCORE && s < MAX_DOFUS_SCORE * 10) {
            const truncated = Math.floor(s / 10);
            if (truncated > 0 && truncated <= MAX_DOFUS_SCORE) {
                s = truncated;
            }
        }

        if (s > 0 && s <= MAX_DOFUS_SCORE) {
            if (s > bestScore) bestScore = s;
        }
    });

    // 2. DETECT VICTORY (Missions)
    const victoryKeywords = [
        'success', 'succes', 'succès',
        'victory', 'victoire',
        'unlocked', 'déverrouillé',
        'achieved', 'accompli',
        'terminé', 'valide', 'validé'
    ];
    const foundIndicators = victoryKeywords.filter(kw => text.includes(kw));
    const isVictory = foundIndicators.length > 0;

    // 3. CALC CONFIDENCE
    let confidence = 0;

    // Base confidence if we found a plausible score
    if (bestScore > 0) {
        confidence += 40; // Base score (not enough for auto-validate)
    }

    // Context Keywords (Dofus UI elements)
    // Finding these proves it's likely a real screenshot and not MS Paint
    const contextKeywords = [
        // UI Headers
        'success', 'succes', 'succès', 'points', 'total',
        'niveau', 'level', 'rang', 'rank', 'compte', 'account',
        'serveur', 'server', 'xp', 'kamas', 'ladder',
        // Classes
        'feca', 'osamodas', 'enutrof', 'sram', 'xelor', 'ecaflip',
        'eniripsa', 'iop', 'cra', 'sadida', 'sacrieur', 'pandawa',
        'roublard', 'zobal', 'steamer', 'eliotrope', 'huppermage', 'ouginak', 'forgelance',
        // Servers
        'draconiros', 'tal kasha', 'hell mina', 'imagiro',
        'orukam', 'tylezia', 'ombre', 'shadow',
        // Missions - General
        'rang', 'rank', 'niv', 'niveau', 'level', 'vaincre', 'monstres',
        // Missions - Types
        'anomalie', 'gardien', 'donjon', 'zone', // Anom
        'régulation', 'regulation', 'brikoléreux', 'sanguinaires', // Regulation
        'expédition', 'expedition', 'bravoure', 'audace', // Expedition
        'songe', 'dream', 'rêve', 'reve', 'paradoxe', 'cauchemar', // Songes
        'palier', 'pensées', 'pensees', 'balades', 'espaces', 'concepts', 'abstractions' // Songes Paliers
    ];

    const foundContext = contextKeywords.filter(kw => text.includes(kw));
    const hasContext = foundContext.length > 0;

    // Detect if valid Mission Context specifically (Rang/Niv/Vaincre...)
    // To avoid confusing "1000 XP" with "1000 Success Points"
    const missionSpecificKeywords = [
        'rang', 'rank', 'niv', 'niveau', 'level', 'vaincre', 'monstres',
        'anomalie', 'gardien', 'donjon', 'zone',
        'régulation', 'regulation',
        'expédition', 'expedition',
        'songe', 'dream', 'rêve', 'reve', 'paradoxe', 'cauchemar',
        'palier'
    ];
    const hasMissionContext = missionSpecificKeywords.some(kw => text.includes(kw));

    // Extract Mission Details for Manual Review (Rang/Niv)
    const rankMatch = text.match(/rang\s*(\d+)/i);
    const levelMatch = text.match(/niv\.?\s*(\d+)/i);
    let extraInfo = "";
    if (rankMatch) extraInfo += ` | Rang: ${rankMatch[1]}`;
    if (levelMatch) extraInfo += ` | Niv: ${levelMatch[1]}`;

    // Songes Specifics (Difficulty & Floor)
    // Matches: "Paradoxe III", "Rêve I", etc.
    const songeDiffMatch = text.match(/(rêve|reve|paradoxe|cauchemar)\s*(i{1,3}|iv|v)\b/i);
    if (songeDiffMatch) extraInfo += ` | Diff: ${songeDiffMatch[1]} ${songeDiffMatch[2].toUpperCase()}`;

    const songeFloorMatch = text.match(/palier\s*(\d+|i{1,3}|iv|v)/i);
    if (songeFloorMatch) extraInfo += ` | Palier: ${songeFloorMatch[1]}`;

    // Expedition Specifics (Mode)
    if (text.includes('bravoure')) extraInfo += ` | Mode: Bravoure`;
    else if (text.includes('audace')) extraInfo += ` | Mode: Audace`;

    // Victory keywords are decent indicators (Keep generic ones like "Terminé")
    if (isVictory) {
        confidence += 30;
    }

    // Boost confidence if we find Mission Keywords
    // NOTE: We do NOT validate based on 'Progression' (0/50) as it's unreliable.
    // If we identify it's a valid Mission Screenshot, we give high confidence 
    // to confirm it's a Dofus image, but Validation might still depend on human review 
    // unless we find explicit "Success" text.
    if ((bestScore > 0 || hasContext) && hasContext) {
        confidence += 50;
        // 40 (Base) + 50 = 90 (High Confidence it's a Mission Image)
    }

    // ACHIEVEMENT CONTEXT BOOST
    // If we find a score AND UI elements like 'points' or 'total', it's very likely valid.
    if (bestScore > 0 && (text.includes('points') || text.includes('total') || text.includes('succès') || text.includes('succes'))) {
        confidence += 20;
    }

    const finalConfidence = Math.min(100, confidence);

    // DETERMINING VICTORY STATUS
    // 1. If it's a Mission (hasMissionContext):
    //    - We IGNORE bestScore (could be XP/Kamas).
    //    - We rely ONLY on explicit victory keywords (Terminé, Validé...) or Manual Review.
    // 2. If it's NOT a Mission (Standard Success Sheet):
    //    - We accept bestScore > 0 as a victory indicator (Success Points).
    let finalIsVictory = isVictory;
    if (!hasMissionContext && bestScore > 0) {
        finalIsVictory = true;
    }

    return {
        extractedText: (bestScore > 0 ? `Points: ${bestScore}\n` : '') +
            `Brut: ${rawResponse}\n` +
            (extraInfo ? `Detected: ${extraInfo}` : ''),
        isVictory: finalIsVictory,
        victoryIndicators: foundIndicators,
        confidence: finalConfidence,
        isAppropriate: true,
        inappropriateReason: null,
    };
}

// =============================================================================
// IMAGE HASHING (Anti-Duplicate)
// =============================================================================

/**
 * Generate a Perceptual Hash (dHash) of an image buffer.
 * This is robust against resizing, compression, and slight color changes.
 * Returns a 64-bit hex string (16 chars).
 */
export async function hashImage(imageBuffer: Buffer): Promise<string> {
    try {
        // 1. Resize to 9x8, grayscale, and raw pixel output
        const { data, info } = await sharp(imageBuffer)
            .resize(9, 8, { fit: 'fill' })
            .grayscale()
            .raw()
            .toBuffer({ resolveWithObject: true });

        // 2. Compute dHash (Difference Hash)
        // Compare adjacent pixels in each row (9 pixels -> 8 comparisons)
        let hash = "";
        for (let row = 0; row < 8; row++) {
            let rowBinary = 0;
            for (let col = 0; col < 8; col++) {
                const left = data[row * 9 + col];
                const right = data[row * 9 + col + 1];
                if (left > right) {
                    rowBinary |= (1 << (7 - col));
                }
            }
            // Convert byte to hex (2 chars)
            hash += rowBinary.toString(16).padStart(2, '0');
        }

        return hash;
    } catch (error) {
        logger.error('[LLM-OCR] Perceptual hashing failed, fallback to SHA-256', { error });
        // Fallback to SHA-256 if sharp fails
        return createHash('sha256').update(imageBuffer).digest('hex');
    }
}

// =============================================================================
// VALIDATION HELPERS
// =============================================================================

/**
 * Check if the OCR result meets auto-validation criteria
 */
export function shouldAutoValidate(result: OcrResult, context?: 'mission' | 'achievement' | 'ladder'): {
    autoValidate: boolean;
    reason: string;
} {
    // Content moderation check first
    if (!result.moderation.isAppropriate) {
        return {
            autoValidate: false,
            reason: `Contenu inapproprié détecté: ${result.moderation.reason || 'Non spécifié'}`
        };
    }

    // Check if OCR succeeded
    if (!result.success) {
        return { autoValidate: false, reason: 'Échec de l\'analyse de l\'image' };
    }

    // Check confidence threshold
    if (result.confidence < AUTO_VALIDATE_THRESHOLD) {
        return {
            autoValidate: false,
            reason: `Score de confiance insuffisant (${result.confidence}% < ${AUTO_VALIDATE_THRESHOLD}%)`
        };
    }

    // For achievements/ladder: a valid score + sufficient confidence is enough.
    // isVictory keywords are mission-specific ("terminé", "validé"...) and don't apply here.
    if (context === 'achievement' || context === 'ladder') {
        return {
            autoValidate: true,
            reason: `Auto-validé avec ${result.confidence}% de confiance (succès)`
        };
    }

    // For missions: also require explicit victory indicators
    if (!result.isVictory) {
        return {
            autoValidate: false,
            reason: 'Aucun indicateur de victoire détecté'
        };
    }

    return {
        autoValidate: true,
        reason: `Auto-validé avec ${result.confidence}% de confiance`
    };
}

export function getAutoValidateThreshold(): number {
    return AUTO_VALIDATE_THRESHOLD;
}

/**
 * Optimize image for Ollama (Resize & Compress)
 * - Resize to max 1024x1024 (Moondream works well with this resolution)
 * - Convert to JPEG (smaller payload than PNG/WebP)
 * - Remove metadata
 */
async function optimizeImage(base64Image: string): Promise<string> {
    try {
        // Remove data URL prefix if present
        const base64Data = base64Image.replace(/^data:image\/\w+;base64,/, '');
        const buffer = Buffer.from(base64Data, 'base64');

        const originalSize = buffer.length;

        // Process with sharp
        const optimizedBuffer = await sharp(buffer)
            .resize({
                width: 1024,
                height: 1024,
                fit: 'inside', // Maintain aspect ratio
                withoutEnlargement: true // Don't upscale small images
            })
            .jpeg({
                quality: 80, // Good balance of quality/size
                mozjpeg: true // Better compression
            })
            .toBuffer();

        const newSize = optimizedBuffer.length;
        const reduction = Math.round((1 - newSize / originalSize) * 100);


        return optimizedBuffer.toString('base64');
    } catch (error: unknown) {
        logger.warn('[LLM-OCR] Image optimization failed, using original', { error });
        return base64Image; // Fallback to original if sharp fails
    }
}

/**
 * Structured Logger Abstraction
 * Production-safe logging with automatic redaction and structured output
 */

type LogLevel = 'debug' | 'info' | 'warn' | 'error';

interface LogContext {
    [key: string]: any;
}

/**
 * Structured logger with environment-aware output
 * - Development: Pretty console output
 * - Production: Structured JSON (ready for log aggregation)
 */
class Logger {
    private isDevelopment = process.env.NODE_ENV === 'development';
    private sensitiveKeys = ['password', 'token', 'secret', 'authorization', 'cookie', 'apiKey'];

    /**
     * Redact sensitive information from log context
     */
    private redact(context: LogContext): LogContext {
        const redacted: LogContext = {};

        for (const [key, value] of Object.entries(context)) {
            const lowerKey = key.toLowerCase();
            const isSensitive = this.sensitiveKeys.some(k => lowerKey.includes(k));

            if (isSensitive) {
                redacted[key] = '[REDACTED]';
            } else if (typeof value === 'object' && value !== null) {
                redacted[key] = this.redact(value);
            } else {
                redacted[key] = value;
            }
        }

        return redacted;
    }

    /**
     * Format log message with context
     */
    private format(level: LogLevel, message: string, context?: LogContext): string {
        const timestamp = new Date().toISOString();

        if (this.isDevelopment) {
            // Pretty format for development
            const emoji = {
                debug: '🐛',
                info: 'ℹ️',
                warn: '⚠️',
                error: '❌'
            }[level];

            return context
                ? `${emoji} [${level.toUpperCase()}] ${message} ${JSON.stringify(this.redact(context), null, 2)}`
                : `${emoji} [${level.toUpperCase()}] ${message}`;
        } else {
            // Structured JSON for production (ready for log aggregation like Datadog, Splunk, etc.)
            return JSON.stringify({
                timestamp,
                level,
                message,
                ...(context ? { context: this.redact(context) } : {})
            });
        }
    }

    /**
     * Debug log (development only)
     */
    debug(message: string, context?: LogContext): void {
        if (this.isDevelopment) {
            console.log(this.format('debug', message, context));
        }
    }

    /**
     * Info log (always logged)
     */
    info(message: string, context?: LogContext): void {
        console.log(this.format('info', message, context));
    }

    /**
     * Warning log (always logged)
     */
    warn(message: string, context?: LogContext): void {
        console.warn(this.format('warn', message, context));
    }

    /**
     * Error log (always logged)
     */
    error(message: string, context?: LogContext): void {
        console.error(this.format('error', message, context));
    }
}

// Export singleton instance
export const logger = new Logger();

/**
 * mergeCellEdges
 * Merges adjacent grid cells into one or more polygons (boundary paths).
 * Useful for "pixel-perfect" map zone rendering.
 */
export function mergeCellEdges(cells: { x: number, y: number }[]): { x: number, y: number }[][] {
    if (!cells || cells.length === 0) return [];

    // 1. Map edges to their occurence count
    // Edge key format: "x1,y1|x2,y2" where points are sorted to ensure uniqueness
    const edgeCount = new Map<string, number>();
    const edges: [number, number, number, number][] = [];

    const getEdgeKey = (x1: number, y1: number, x2: number, y2: number) => {
        if (x1 < x2 || (x1 === x2 && y1 < y2)) {
            return `${x1},${y1}|${x2},${y2}`;
        }
        return `${x2},${y2}|${x1},${y1}`;
    };

    for (const cell of cells) {
        const { x, y } = cell;
        const cellEdges = [
            [x, y, x + 1, y],         // Top
            [x + 1, y, x + 1, y + 1], // Right
            [x + 1, y + 1, x, y + 1], // Bottom
            [x, y + 1, x, y]          // Left
        ];

        for (const [x1, y1, x2, y2] of cellEdges) {
            const key = getEdgeKey(x1, y1, x2, y2);
            edgeCount.set(key, (edgeCount.get(key) || 0) + 1);
        }
    }

    // 2. Keep only unique edges (the boundary)
    const boundaryEdges: [number, number, number, number][] = [];
    edgeCount.forEach((count, key) => {
        if (count === 1) {
            const [p1, p2] = key.split('|');
            const [x1, y1] = p1.split(',').map(Number);
            const [x2, y2] = p2.split(',').map(Number);
            boundaryEdges.push([x1, y1, x2, y2]);
        }
    });

    if (boundaryEdges.length === 0) return [];

    // 3. Chain edges into polygons
    const polygons: { x: number, y: number }[][] = [];
    while (boundaryEdges.length > 0) {
        const polygon: { x: number, y: number }[] = [];
        const currentEdge = boundaryEdges.shift()!;
        const [startX, startY] = [currentEdge[0], currentEdge[1]];
        let [endX, endY] = [currentEdge[2], currentEdge[3]];
        polygon.push({ x: startX, y: startY });
        polygon.push({ x: endX, y: endY });

        let found = true;
        while (found) {
            found = false;
            for (let i = 0; i < boundaryEdges.length; i++) {
                const [x1, y1, x2, y2] = boundaryEdges[i];
                if (x1 === endX && y1 === endY) {
                    endX = x2; endY = y2;
                    polygon.push({ x: endX, y: endY });
                    boundaryEdges.splice(i, 1);
                    found = true;
                    break;
                } else if (x2 === endX && y2 === endY) {
                    endX = x1; endY = y1;
                    polygon.push({ x: endX, y: endY });
                    boundaryEdges.splice(i, 1);
                    found = true;
                    break;
                }
            }
            // Check if we closed the loop
            if (endX === startX && endY === startY) break;
        }
        polygons.push(polygon);
    }

    return polygons;
}

