    reason?: string;
    predictions?: any[];
}

let cachedModel: any = null;
let isLoadingModel = false;

/**
 * 🛡️ SigilOS Safety Core
 * Replaced the stub with real TensorFlow + NSFWJS analysis.
 */
export async function analyzeImageSafety(file: File): Promise<SafetyResult> {
    try {
        // 1. Check if feature is globally toggled (cached for current session? No, let's just fetch once or rely on server action caching)
        const configRes = await getPlatformConfig();
        if (configRes.success && configRes.config?.nsfwFilterEnabled === false) {
            return { isSafe: true, predictions: [] };
        }

        // 2. Load dependencies lazily
        const [nsfwjs, tf] = await Promise.all([
            import("nsfwjs"),
            import("@tensorflow/tfjs")
        ]);

        await tf.ready();

        // 3. Singleton model loading
        if (!cachedModel && !isLoadingModel) {
            isLoadingModel = true;
            try {
                cachedModel = await nsfwjs.load(); // mobilenet_v2 is standard
            } finally {
                isLoadingModel = false;
            }
        }

        // Wait if loading
        while (isLoadingModel) {
            await new Promise(r => setTimeout(r, 100));
        }

        if (!cachedModel) return { isSafe: true };

        // 4. Create image and classify
        const img = new Image();
        const objectUrl = URL.createObjectURL(file);
        img.src = objectUrl;

        return new Promise((resolve) => {
            img.onload = async () => {
                try {
                    const predictions = await cachedModel.classify(img);
                    URL.revokeObjectURL(objectUrl);

                    const porn = predictions.find((p: any) => p.className === "Porn")?.probability || 0;
                    const hentai = predictions.find((p: any) => p.className === "Hentai")?.probability || 0;
                    const sexy = predictions.find((p: any) => p.className === "Sexy")?.probability || 0;

                    // Calibrated thresholds for Dofus False Positives
                    const isNsfw = porn > 0.75 || hentai > 0.75 || sexy > 0.95;

                    if (isNsfw) {
                        resolve({ 
                            isSafe: false, 
                            reason: "Contenu inapproprié détecté par l'IA.",
                            predictions 
                        });
                    } else {
                        resolve({ isSafe: true, predictions });
                    }
                } catch (err) {
                    URL.revokeObjectURL(objectUrl);
                    resolve({ isSafe: true });
                }
            };
            img.onerror = () => {
                URL.revokeObjectURL(objectUrl);
                resolve({ isSafe: true });
            };
        });
    } catch (e) {
        console.error("[Safety Engine] Fatal error:", e);
        return { isSafe: true };
    }
}

import DOMPurify from 'isomorphic-dompurify';

/**
 * Configure DOMPurify globally to secure all anchor tags.
 * Empêche les attaques de type "Reverse Tabnabbing" (HIGH-05).
 */
DOMPurify.addHook('afterSanitizeAttributes', function (node) {
    if (node.tagName && node.tagName.toLowerCase() === 'a') {
        node.setAttribute('target', '_blank');
        node.setAttribute('rel', 'noopener noreferrer');
    }
});

/**
 * Shared Security Utilities
 */

/**
 * Sanitize HTML/Markdown input to prevent XSS
 * - Uses isomorphic-dompurify for robust DOM-based sanitization
 * 
 * @param input The raw string to sanitize
 * @param maxLength Optional max length constraint
 * @param strict If true, strips ALL HTML tags except basic formatting (b, i, u, br). Default false for Docs.
 */
export function sanitizeHtml(input: string | null, maxLength: number = 100000, strict: boolean = false): string | null {
    if (!input) return null;

    // Limit length first
    const truncated = input.slice(0, maxLength);

    // Strict mode for Presentation (Bio/Description)
    const config: any = strict
        ? { ALLOWED_TAGS: ['b', 'i', 'u', 'strong', 'em', 'br'] }
        : { ADD_ATTR: ['target'] }; // Normal mode allows safe HTML (h1, img, etc.)

    return DOMPurify.sanitize(truncated, config) as unknown as string;
}

/**
 * Sanitize Discord invite link - strict validation
 */
export function sanitizeDiscordLink(url: string | null): string | null {
    if (!url) return null;
    const cleaned = url.trim();
    if (!cleaned) return null;

    // Strict regex for Discord invite links only
    // Supports discord.gg, discord.com/invite
    const discordInviteRegex = /^https?:\/\/(discord\.gg|discord\.com\/invite)\/[\w-]+$/i;

    if (!discordInviteRegex.test(cleaned)) {
        return null;
    }

    if (cleaned.includes('<') || cleaned.includes('>') || cleaned.includes('"') || cleaned.includes("'")) {
        return null;
    }

    return cleaned;
}

/**
 * Sanitize simple name/title input
 */
export function sanitizeName(name: string | null, maxLength: number = 50): string | null {
    if (!name) return null;
    return name
        .trim()
        .replace(/[<>"'&]/g, "") // Remove HTML special chars, keep ( ) and space
        .slice(0, maxLength);
}

// Singleton AudioContext — browsers block new AudioContext until a user gesture
let _audioCtx: AudioContext | null = null;

export const resumeAudioContext = async (): Promise<AudioContext | null> => {
    if (typeof window === 'undefined') return null;
    try {
        const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
        if (!AudioContextClass) return null;
        if (!_audioCtx) _audioCtx = new AudioContextClass();
        if (_audioCtx && _audioCtx.state === 'suspended') {
            await _audioCtx.resume();
        }
        return _audioCtx;
    } catch {
        return null;
    }
};

// Call this on first user interaction to unlock audio early
export const unlockAudio = () => {
    resumeAudioContext().catch(() => {});
};

export const playSoundEffect = async (type: 'tick' | 'ding' | 'fail' | 'success' | 'gartic-ring' | 'count' | 'ranking') => {
    if (typeof window === 'undefined') return;

    // Handle MP3 sounds separately
    if (type === 'gartic-ring') {
        const audio = new Audio('/sounds/garticohone-ring.mp3');
        audio.volume = 0.4;
        audio.play().catch(e => console.error("Error playing gartic-ring:", e));
        return;
    }

    const ctx = await resumeAudioContext();
    if (!ctx) return;

    try {
        const playOscillator = (freq: number, oscType: OscillatorType, duration: number, vol: number = 0.1) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            
            osc.type = oscType;
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            
            gain.gain.setValueAtTime(vol, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
            
            osc.connect(gain);
            gain.connect(ctx.destination);
            
            osc.start();
            osc.stop(ctx.currentTime + duration);
        };

        switch (type) {
            case 'tick':
                playOscillator(800, 'square', 0.05, 0.05);
                break;
            case 'ding':
                playOscillator(1200, 'sine', 0.3, 0.1);
                setTimeout(() => playOscillator(1600, 'sine', 0.4, 0.1), 50);
                break;
            case 'success':
                playOscillator(440, 'sine', 0.5, 0.1);
                playOscillator(554, 'sine', 0.5, 0.1);
                playOscillator(659, 'sine', 0.5, 0.1);
                setTimeout(() => {
                    playOscillator(554, 'sine', 0.6, 0.1);
                    playOscillator(659, 'sine', 0.6, 0.1);
                    playOscillator(880, 'sine', 0.6, 0.1);
                }, 150);
                break;
            case 'count':
                playOscillator(600, 'sine', 0.1, 0.05);
                break;
            case 'ranking':
                playOscillator(523.25, 'sine', 0.2, 0.1); // C5
                setTimeout(() => playOscillator(659.25, 'sine', 0.2, 0.1), 100); // E5
                setTimeout(() => playOscillator(783.99, 'sine', 0.2, 0.1), 200); // G5
                setTimeout(() => playOscillator(1046.50, 'sine', 0.4, 0.1), 300); // C6
                break;
            case 'fail': {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(300, ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.5);
                gain.gain.setValueAtTime(0.1, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start();
                osc.stop(ctx.currentTime + 0.5);
                break;
            }
        }
    } catch (e) {
        console.error("Audio playback error:", e);
    }
};

import { unlink, rmdir } from "fs/promises";
import { join, dirname, normalize } from "path";
import { logger } from "@/lib/logger";
import { createHmac } from "crypto";

/**
 * Deletes a proof file from the filesystem and cleans up empty parent directories.
 * Supports all upload paths under /uploads/:
 *   - /uploads/proofs/{discordGuildId}/        (missions)
 *   - /uploads/guilds/{prismaId}/proofs/       (kamas)
 *   - /uploads/guilds/{prismaId}/achievements/ (succès)
 */
export async function deleteProofFile(proofUrl: string) {
    if (!proofUrl) return;

    // Accept both legacy /uploads/ and new /api/storage/ paths
    let relativePath = "";
    if (proofUrl.startsWith("/uploads/")) {
        relativePath = proofUrl.replace(/^\/uploads\//, "");
    } else if (proofUrl.startsWith("/api/storage/")) {
        relativePath = proofUrl.replace(/^\/api\/storage\//, "");
    } else {
        return; // Ignore any other paths
    }

    // Normalize and secure path
    const safePath = normalize(relativePath).replace(/^(\.\.(\/|\\|$))+/, "");
    const absolutePath = join(process.cwd(), "private_uploads", safePath);
    const uploadsRoot = join(process.cwd(), "private_uploads");

    if (!absolutePath.startsWith(uploadsRoot)) {
        logger.warn(`[Storage] Path traversal attempt blocked`, { proofUrl });
        return;
    }

    try {
        // 1. Delete the file
        await unlink(absolutePath);
        logger.info(`[Storage] Deleted proof file`, { proofUrl });

        // 2. Safely attempt to delete the parent directory if empty
        try {
            const dirPath = dirname(absolutePath);
            await rmdir(dirPath);
            // Optional: Try to remove the grandparent if also empty
            const grandParentDirPath = dirname(dirPath);
            await rmdir(grandParentDirPath);
        } catch {
            // Ignore — directory not empty, that's fine
        }
    } catch (error: any) {
        if (error.code !== "ENOENT") {
            logger.warn(`[Storage] Failed to delete file`, { proofUrl, error });
        }
        // ENOENT = already deleted, silently ignore
    }
}

/**
 * Generates a signature for a storage path to allow public access with a valid token.
 */
export function signStorageUrl(path: string): string {
    const secret = process.env.AUTH_SECRET || "default_internal_secret_change_me_sigil_os_storage";
    const hmac = createHmac("sha256", secret);
    hmac.update(path);
    return hmac.digest("hex");
}

/**
 * Verifies if a token is valid for a given storage path.
 */
export function verifyStorageToken(path: string, token: string): boolean {
    const expected = signStorageUrl(path);
    if (!token || !expected) return false;
    return token === expected;
}

/**
 * Generates an absolute URL with a security token for Discord to access a private asset.
 */
export function getDiscordPublicUrl(proofUrl: string | null | undefined): string | undefined {
    if (!proofUrl) return undefined;
    
    const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr";
    const baseUrl = proofUrl.startsWith("http") ? proofUrl : `${appUrl}${proofUrl}`;
    
    // Extract path for signature (part after /api/storage/)
    const pathOnly = proofUrl.replace(/^\/api\/storage\//, "");
    const token = signStorageUrl(pathOnly);
    
    return `${baseUrl}${baseUrl.includes('?') ? '&' : '?'}token=${token}`;
}

