﻿"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { NotificationType } from "@prisma/client";
import { createNotification } from "@/server/actions/notification-actions";
import { PERMISSIONS } from "@/lib/permissions";
import { checkGuildPermission } from "@/server/actions/user-actions";
import { deleteProofFile } from "@/lib/storage-utils";
import { createAuditLog } from "@/server/actions/audit-actions";

export type ActionResponse<T = null> = {
    success: boolean;
    error?: string;
    data?: T;
};

/**
 * Validate or Reject an achievement submission
 */
export async function validateAchievementSubmission(
    submissionId: string,
    status: "VALIDATED" | "REJECTED"
): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    try {
        const submission = await (db as any).achievementSubmission.findUnique({
            where: { id: submissionId },
            include: { guild: true, profile: true }
        });

        if (!submission) return { success: false, error: "Demande introuvable" };

        // Check if user has permission to validate (using same permission as missions for now or a specific one)
        const guard = await checkGuildPermission(session, submission.guild.discordGuildId, PERMISSIONS.MISSIONS_OFFICER);
        if (!guard.allowed) return { success: false, error: "Permissions insuffisantes." };

        if (status === "VALIDATED") {
            // Update User Profile
            await db.userProfile.update({
                where: { id: submission.profileId },
                data: {
                    successPoints: submission.points,
                    lastLadderUpdate: new Date()
                }
            });

            // Notify user
            await createNotification(
                submission.profile.userId,
                "SYSTEM_INFO" as NotificationType,
                "[Ladder] Points validés",
                `Vos ${submission.points} points de succès ont été validés par le staff.`,
                undefined,
                submission.guild.discordGuildId
            );
        } else {
            // Notify user of rejection
            await createNotification(
                submission.profile.userId,
                "SYSTEM_INFO" as NotificationType,
                "[Ladder] Points refusés",
                `Votre demande de mise à jour des points de succès a été refusée par le staff.`,
                undefined,
                submission.guild.discordGuildId
            );
        }

        // Delete Discord embed (dashboard validation path)
        if (submission.discordMessageId?.includes(":")) {
            const [channelId, msgId] = submission.discordMessageId.split(":");
            if (channelId && msgId) {
                try {
                    const { deleteChannelMessage } = await import("@/server/discord");
                    await deleteChannelMessage(channelId, msgId);
                } catch (e) {
                    console.error("[Achievement] Failed to delete Discord embed:", e);
                }
            }
        }

        // Cleanup: Delete file and image hash
        if (submission.proofUrl) {
            await deleteProofFile(submission.proofUrl);
        }

        // Delete image hash to allow retry
        await (db as any).imageHash.deleteMany({
            where: { guildId: submission.guildId, sourceType: "ACHIEVEMENT", sourceId: submissionId },
        });

        // Update submission status
        const updated = await (db as any).achievementSubmission.update({
            where: { id: submissionId },
            data: {
                status,
                validatorId: session.user.id,
                validatedAt: new Date(),
                proofUrl: "" // Clear URL after deletion
            },
            include: { profile: { include: { user: true } } }
        });

        // Audit Log
        await createAuditLog({
            guildId: submission.guild.discordGuildId,
            actorUserId: session.user.id,
            actorName: session.user.name || "Admin",
            action: (status === "VALIDATED" ? "SUCCESS_SYNC" : "MISSION_REJECTED") as any,
            targetType: "PROFILE" as any,
            targetId: submission.profileId,
            metadata: {
                points: submission.points,
                submitterName: updated.profile.pseudoDofus || updated.profile.discordNickname || updated.profile.user.name,
                status,
                source: "dashboard",
                description: `Mise à jour Ladder (${submission.points} pts)`
            }
        });

        revalidatePath(`/dashboard/${submission.guild.discordGuildId}/ladder`);
        revalidatePath(`/dashboard/${submission.guild.discordGuildId}/profile`);

        return { success: true };
    } catch (error) {
        console.error("[Achievement] Validation error:", error);
        return { success: false, error: "Erreur lors de la validation." };
    }
}

/**
 * Get pending achievement submissions for a guild
 */
export async function getPendingAchievements(guildId: string) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    // Lazy cleanup of old pending submissions (24h)
    await cleanupExpiredAchievements(guildId);

    try {
        const guild = await db.guildConfig.findUnique({ 
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guild) return { success: false, error: "Guilde introuvable" };

        const guard = await checkGuildPermission(session, guildId, PERMISSIONS.SYSTEM_CONFIG);
        if (!guard.allowed) return { success: false, error: "Accès refusé" };

        const submissions = await (db as any).achievementSubmission.findMany({
            where: {
                guildId: guild.id,
                status: "PENDING"
            },
            include: {
                profile: {
                    select: {
                        discordNickname: true,
                        pseudoDofus: true,
                        user: { select: { image: true } }
                    }
                }
            },
            orderBy: { createdAt: "desc" }
        });

        return { success: true, data: submissions };
    } catch (error) {
        return { success: false, error: "Erreur lors de la récupération des demandes." };
    }
}

/**
 * Cleanup pending achievement submissions older than 24h
 */
export async function cleanupExpiredAchievements(guildId: string) {
    const EXPIRATION_MS = 24 * 60 * 60 * 1000;
    const thresholdDate = new Date(Date.now() - EXPIRATION_MS);

    try {
        const guild = await db.guildConfig.findUnique({ 
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guild) return;

        const expired = await (db as any).achievementSubmission.findMany({
            where: {
                guildId: guild.id,
                status: "PENDING",
                createdAt: { lt: thresholdDate }
            }
        });

        if (expired.length > 0) {
            for (const sub of expired) {
                if (sub.proofUrl) {
                    await deleteProofFile(sub.proofUrl);
                }
                await (db as any).achievementSubmission.delete({ where: { id: sub.id } });
            }
        }
    } catch (error) {
        console.error("[Cleanup] Achievement cleanup error:", error);
    }
}
/**
 * Cancel a pending achievement submission (User action)
 */
export async function cancelAchievementSubmission(guildId: string, targetUserId?: string): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    try {
        // DB / RBAC Check
        const { getUserContext } = await import("@/server/actions/user-actions");
        const user = await getUserContext(guildId);
        if (!user.isAuthenticated) return { success: false, error: "Unauthorized" };

        const effectiveUserId = (targetUserId && user.isSuperAdmin) ? targetUserId : session.user.id;

        const profile = await db.userProfile.findFirst({
            where: {
                userId: effectiveUserId,
                guild: { discordGuildId: guildId }
            }
        });

        if (!profile) return { success: false, error: "Profil introuvable" };

        const pending = await (db as any).achievementSubmission.findFirst({
            where: {
                profileId: profile.id,
                status: "PENDING"
            }
        });

        if (!pending) return { success: false, error: "Aucune demande en attente" };

        // 1. Cleanup file
        if (pending.proofUrl) {
            await deleteProofFile(pending.proofUrl);
        }

        // 2. Delete from DB
        await (db as any).achievementSubmission.delete({
            where: { id: pending.id }
        });

        // 3. Delete Image Hash to allow retry
        await (db as any).imageHash.deleteMany({
            where: {
                guildId: profile.guildId,
                sourceType: "ACHIEVEMENT",
                sourceId: pending.id
            }
        });


        revalidatePath(`/dashboard/${guildId}/profile`);
        return { success: true };
    } catch (error) {
        console.error("[Achievement] Cancel error:", error);
        return { success: false, error: "Erreur lors de l'annulation" };
    }
}

"use server";

import { db } from "@/lib/prisma";

/**
 * Immutable activity logger for the Services module.
 * Creates audit entries that are NEVER deleted or modified.
 * Visible to involved parties for dispute resolution.
 */

type LogModule = "SERVICE" | "LOAN" | "VAULT";
type LogAction = "CREATED" | "UPDATED" | "DELETED" | "STATUS_CHANGE" | "RETURNED" | "CANCELLED" | "PARTIAL_RETURN";

interface LogEntry {
    guildId: string;     // Internal Prisma guild ID
    actorId: string;     // Profile ID of the actor
    module: LogModule;
    action: LogAction;
    entityId: string;
    summary: string;     // Human-readable summary
    details?: string;    // JSON with before/after state
    metadata?: string;   // Extra JSON (screenshot URLs, etc.)
}

export async function logServiceActivity(entry: LogEntry): Promise<void> {
    try {
        await db.serviceActivityLog.create({
            data: {
                guildId: entry.guildId,
                actorId: entry.actorId,
                module: entry.module,
                action: entry.action,
                entityId: entry.entityId,
                summary: entry.summary,
                details: entry.details || null,
                metadata: entry.metadata || null,
            },
        });
    } catch (error) {
        // Never let logging failure break the main operation
        console.error("[ServiceActivityLog] Failed to log:", error);
    }
}

/**
 * Get activity logs for a specific entity (service/loan/vault entry).
 * Returns chronological timeline visible to all guild members.
 */
export async function getActivityLogs(
    guildId: string,
    entityId: string
): Promise<{
    id: string;
    module: string;
    action: string;
    summary: string;
    details: string | null;
    metadata: string | null;
    createdAt: Date;
    actor: {
        pseudoDofus: string | null;
        discordNickname: string | null;
        user: { name: string | null; image: string | null };
    };
}[]> {
    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true },
        });
