/**
 * Report a security incident (e.g. NSFW upload attempt)
 * Accessible by authenticated users, but rate-limited + audited
 */
export async function reportSecurityIncident(
    guildId: string,
    incidentType: string,
    description: string,
    metadata: Record<string, any> = {}
): Promise<ActionResponse> {
    const session = await auth();

    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    try {
        // Try to get internal user details, but don't block on it
        let actorName = session.user.name || "Unknown User";
        try {
            const user = await db.user.findUnique({
                where: { id: session.user.id },
                select: { name: true }
            });
            if (user?.name) actorName = user.name;
        } catch (e) {
            console.warn("[Security] User lookup failed, using session name", e);
        }

        // 🛡️ FORENSICS: Get real security headers
        const { headers } = await import("next/headers");
        const headersList = await headers();
        const ip = headersList.get("x-forwarded-for")?.split(",")[0] || "127.0.0.1";

        const result = await createAuditLog({
            guildId,
            actorUserId: session.user.id,
            actorName,
            action: "SECURITY_ALERT",
            targetType: "CONTENT_SAFETY",
            targetId: incidentType,
            metadata: {
                description,
                ...metadata,
                ip: ip.substring(0, 45),
                severity: "HIGH"
            }
        });

        // 🔔 TRIGGER DISCORD ALERT
        if (result.success) {
            const { sendSecurityAlert } = await import("@/server/discord");
            let guildName = "Unknown Guild";
            try {
                const config = await db.guildConfig.findUnique({
                    where: { discordGuildId: guildId },
                    select: { name: true }
                });
                if (config?.name) guildName = config.name;
            } catch {}

            await sendSecurityAlert({
                type: incidentType,
                description,
                severity: "HIGH",
                guildName,
                userName: actorName,
                metadata: {
                    ...metadata,
                    logId: result.data?.logId
                }
            });
        }

        return { success: true };
    } catch (error) {
        console.error("Failed to report security incident:", error);
        return { success: false, error: "Internal Error" };
    }
}

