/**
 * Get the dungeon directory for a specific dungeon.
 * Returns two lists of members per achievement: those who have it, and those who don't.
 */
export async function getDungeonDirectory(
    guildId: string,
    dungeonId: string,
    dungeonName?: string
): Promise<ActionResponse<{
    achievementId: string;
    achievementName: string;
    iconUrl: string | null;
    points: number;
    hasCompleted: { id: string; name: string; imageUrl: string | null; classe: string | null }[];
    missing: { id: string; name: string; imageUrl: string | null; classe: string | null }[];
}[]>> {
    const user = await getUserContext(guildId);
    if (!user.canViewFinder) return { success: false, error: "Accès refusé" };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true },
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        // 1. Get all achievements for this dungeon
        let targetDjId = dungeonId;

        // If dungeonId looks like a Dofus numeric ID or if no achievements found, try name lookup
        if (dungeonName || !dungeonId.startsWith('c')) {
            const resolvedDungeon = await db.dungeon.findFirst({
                where: {
                    OR: [
                        { name: { contains: dungeonName || dungeonId, mode: 'insensitive' } },
                        { bossName: { contains: dungeonName || dungeonId, mode: 'insensitive' } }
                    ]
                },
                select: { id: true }
            });
            if (resolvedDungeon) {
                targetDjId = resolvedDungeon.id;
            }
        }

        const dungeonAchievements = await (db as any).dungeonAchievement.findMany({
            where: { dungeonId: targetDjId },
            include: { challenge: { select: { name: true, iconUrl: true } } },
        });

        if (dungeonAchievements.length === 0) {
            return { success: true, data: [] };
        }

        // 2. Get all ACTIVE members of the guild
        const activeMembers = await db.userProfile.findMany({
            where: { guildId: guildConfig.id, status: "ACTIVE" },
            select: {
                id: true,
                discordNickname: true,
                pseudoDofus: true,
                classe: true,
                user: { select: { image: true } },
            },
        });

        // 3. Get all progress for these achievements within the guild
        const achievementIds = dungeonAchievements.map((a: any) => a.id);
        const allProgress = await (db as any).userDungeonProgress.findMany({
            where: {
                achievementId: { in: achievementIds },
                profile: { guildId: guildConfig.id, status: "ACTIVE" },
            },
            select: { profileId: true, achievementId: true },
        });

        // 4. Map them out
        const result = dungeonAchievements.map((a: any) => {
            const completedProfileIds = new Set(
                allProgress.filter((p: any) => p.achievementId === a.id).map((p: any) => p.profileId)
            );

            const hasCompleted: any[] = [];
            const missing: any[] = [];

            activeMembers.forEach((member) => {
                const memberData = {
                    id: member.id,
                    name: member.pseudoDofus || member.discordNickname || "Inconnu",
                    imageUrl: member.user.image,
                    classe: member.classe,
                };

                if (completedProfileIds.has(member.id)) {
                    hasCompleted.push(memberData);
                } else {
                    missing.push(memberData);
                }
            });

            // Sort alphabetically
            hasCompleted.sort((a: any, b: any) => a.name.localeCompare(b.name));
            missing.sort((a: any, b: any) => a.name.localeCompare(b.name));

            return {
                achievementId: a.id,
                achievementName: a.challenge.name,
                iconUrl: a.challenge.iconUrl,
                points: a.points,
                hasCompleted,
                missing,
            };
        });

        return { success: true, data: result };
    } catch (error) {
        console.error("[getDungeonDirectory]", error);
        return { success: false, error: "Erreur lors du chargement de l'annuaire" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { redis } from "@/lib/redis";

import { getKralamoureEvents, getKralamoureEventDetails, MetamobApiError } from "@/lib/metamob-client";
import { decrypt } from "@/lib/encryption";

export type UpcomingEvent = {
    id: string;
    title: string;
    startDate: string; // ISO string — Date objects crash Next.js server→client serialization
    type: string;
    participantsCount: number;
    metadata?: any;
};

export async function getUpcomingGuildEvents(guildId: string, limit = 5): Promise<UpcomingEvent[]> {
    const session = await auth();
    if (!session?.user?.id) return [];

    // 1. Get Guild Config (Internal ID) AND User's Server ID for Metamob
    // We try to find the server ID from the user's profile first.
    const [guildConfig, userProfile] = await Promise.all([
        db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        }),
        db.userProfile.findFirst({
            where: {
                userId: session.user.id,
                guild: { discordGuildId: guildId }
            },
            select: { metamobServerId: true, metamobApiKey: true }
        })
    ]);

    if (!guildConfig) return [];

    const now = new Date();

    // 2. Fetch Internal Guild Events
    const dbEventsPromise = db.guildEvent.findMany({
        where: {
            guildId: guildConfig.id,
            startDate: { gte: now },
            status: { not: "CANCELLED" }
        },
        orderBy: { startDate: "asc" },
        take: limit, // Fetch more than needed to allow merging
        select: {
            id: true,
            title: true,
            startDate: true,
            type: true,
            metadata: true,
            _count: {
                select: { participants: { where: { status: "REGISTERED" } } }
            }
        }
    });

    // 3. Fetch Kralamoure Events (if user has a server configured)
    let kralaEvents: any[] = [];
    if (userProfile?.metamobServerId) {
        const cacheKey = `krala:events:${userProfile.metamobServerId}`;
        const apiKey = userProfile.metamobApiKey;
        
        try {
            // Check Redis cache first (short TTL: 60s)
            const cached = await redis.get(cacheKey);
            if (cached) {
                kralaEvents = JSON.parse(cached);
            } else {
                const results = await getKralamoureEvents({
                    serverId: userProfile.metamobServerId,
                    from: now.toISOString(),
                    guildApiKey: apiKey
                });
                
                if (results) {
                    kralaEvents = results;
                    await redis.set(cacheKey, JSON.stringify(kralaEvents), "EX", 60).catch(() => {});
                }
            }
        } catch (err) {
            console.error("[getUpcomingGuildEvents] Failed to fetch Kralamoure events:", err);
            kralaEvents = [];
        }
    }

    const dbEvents = await dbEventsPromise;

    // 4. Normalize & Merge
    const normalizedDbEvents: UpcomingEvent[] = dbEvents.map(e => {
        const meta = e.metadata as any;
        return {
            id: e.id,
            title: e.title,
            startDate: e.startDate.toISOString(),
            type: e.type,
            participantsCount: ((e.type as any) === "KRALAMOURE" || meta?.isKralamoure) 
                ? (meta?.metamobParticipantsCount || e._count.participants) 
                : e._count.participants
        };
    });

    const normalizedKralaEvents: UpcomingEvent[] = kralaEvents.map((k: any) => ({
        id: `krala-${k.id}`,
        title: `Ouverture Kralamoure`,
        startDate: new Date(k.event_datetime).toISOString(),
        type: "KRALAMOURE",
        participantsCount: k.participants_count || 0
    }));

    // 6. Fetch Active Game Sessions from Redis
    const [skribblRooms, garticRooms, geoRooms] = await Promise.all([
        redis.get(`guild:${guildId}:skribbl:rooms`),
        redis.get(`guild:${guildId}:gartic:rooms`),
        redis.get(`guild:${guildId}:geoguesser:rooms`),
    ]);

    const sessions: UpcomingEvent[] = [];



    const getGameTitle = (type: string, hostName: string) => {
        switch (type) {
            case 'SKRIBBL': return `🎨 Skribbl (${hostName})`;
            case 'GARTIC': return `📱 Phone (${hostName})`;
            case 'GEOGUESSER': return `🌍 Guesser (${hostName})`;
            default: return `🎮 ${type} (${hostName})`;
        }
    };

    const parseGameRooms = (rawData: string | null, type: string) => {
        if (!rawData) return;
        try {
            const rooms = JSON.parse(rawData);
            rooms.forEach((r: any) => {
                const roomId = r.roomId || r.id; // Support both naming variants
                sessions.push({
                    id: `game-${type}-${roomId}`,
                    title: getGameTitle(type, r.hostName || 'Inconnu'),
                    startDate: new Date().toISOString(), // Active now
                    type: `GAME_${type}`,
                    participantsCount: r.playerCount || 0,
                    metadata: {
                        roomId: roomId,
                        isLive: true,
                        state: r.state || 'LOBBY', // Needed to know if we can join or just spec
                    }
                });
            });
        } catch (e) {}
    };

    parseGameRooms(skribblRooms, 'SKRIBBL');
    parseGameRooms(garticRooms, 'GARTIC');
    parseGameRooms(geoRooms, 'GEOGUESSER');

    // 7. Combine, Sort, and Limit (Prioritize live games)
    const allEvents = [...sessions, ...normalizedDbEvents].sort((a, b) => {
        // Priority to live games
        const aLive = (a.metadata as any)?.isLive;
        const bLive = (b.metadata as any)?.isLive;
        if (aLive && !bLive) return -1;
        if (!aLive && bLive) return 1;
        
        return new Date(a.startDate).getTime() - new Date(b.startDate).getTime();
    });

    return allEvents.slice(0, limit);
}

import { logger } from "@/lib/logger";

export async function getExternalKralamoureDetails(kralaId: number, guildId: string) {
    const session = await auth();
    if (!session?.user?.id) return null;

    // SECURITY: Ensure user is a member of the requested guild
    const { getUserContext } = await import("@/server/actions/user-actions");
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated || !ctx.isMember) return null;

    // We need an API key. Try user's key first, then any member's key.
    const userProfile = await db.userProfile.findFirst({
        where: { userId: session.user.id, guildId: ctx.guildId },
        select: { metamobApiKey: true }
    });

    let apiKey = userProfile?.metamobApiKey;
    let keySource = userProfile?.metamobApiKey ? "user" : "none";

    // Fallback: grab any guild member's key if we still have none
    if (!apiKey) {
        const anyMemberWithKey = await db.userProfile.findFirst({
            where: { guildId: ctx.guildId, metamobApiKey: { not: null }, status: "ACTIVE" },
            select: { metamobApiKey: true },
        });
        apiKey = anyMemberWithKey?.metamobApiKey;
        keySource = anyMemberWithKey ? "fallback-member" : "none";
    }

    logger.error("[getExternalKralamoureDetails] Key resolution:", {
        kralaId,
        guildId,
        keySource,
        hasKey: !!apiKey,
        keyPreview: apiKey ? `${apiKey.substring(0, 8)}...` : "null",
    });

    if (!apiKey) return null; // No key anywhere — can't fetch

    try {
        const details = await getKralamoureEventDetails(kralaId, { guildApiKey: apiKey });
        logger.error("[getExternalKralamoureDetails] SUCCESS:", {
            kralaId,
            participantsCount: details.participants_count,
            participantsList: details.participants?.length,
        });
        return details;
    } catch (error) {
        logger.error("[getExternalKralamoureDetails] Failed:", { error, kralaId, guildId, keySource });
        return null;
    }
}

"use server";

type AlmanaxData = {
    bonus: {
        description: string;
        type: {
            name: string;
            id: string;
        };
    };
    tribute: {
        item: {
            name: string;
            image_urls: {
                icon: string;
            };
        };
        quantity: number;
    };
    date: string;
};

/**
 * Calculate seconds until midnight in Paris timezone
 */
function getSecondsUntilMidnight(): number {
    const now = new Date();
    // Get current time in Paris timezone
    const parisTime = new Date(now.toLocaleString("en-US", { timeZone: "Europe/Paris" }));

    // Calculate midnight Paris time
    const midnight = new Date(parisTime);
    midnight.setDate(midnight.getDate() + 1);
    midnight.setHours(0, 0, 0, 0);

    // Calculate difference in seconds, add 60s buffer to ensure API has updated
    const secondsUntilMidnight = Math.floor((midnight.getTime() - parisTime.getTime()) / 1000) + 60;

    // Minimum 60 seconds, maximum 24 hours
    return Math.max(60, Math.min(secondsUntilMidnight, 86400));
}

export async function getAlmanaxData(): Promise<{
    success: boolean;
    data?: AlmanaxData;
    error?: string;
    secondsUntilMidnight?: number;
}> {
    try {
        // Use Paris timezone for date to match Dofus game day
        const parisDate = new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Paris" }); // YYYY-MM-DD format
        const secondsUntilMidnight = getSecondsUntilMidnight();
        const url = `https://api.dofusdu.de/dofus2/fr/almanax/${parisDate}`;

        let res = await fetch(url, {
            headers: {
                "Accept": "application/json",
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"
            },
            next: { revalidate: secondsUntilMidnight }, // Dynamic cache until midnight
        });

        if (!res.ok) {
            console.warn(`Direct fetch for Almanax data failed (${res.status}), trying proxy...`);
            const proxyUrl = `https://api.allorigins.win/get?url=${encodeURIComponent(url)}`;
            res = await fetch(proxyUrl, {
                headers: { "User-Agent": "SigilOS/1.0" },
                next: { revalidate: secondsUntilMidnight }
            });

            if (res.ok) {
                const text = await res.text();
                try {
                    const json = JSON.parse(text);
                    if (json.contents) {
                        return { success: true, data: JSON.parse(json.contents), secondsUntilMidnight };
                    }
                } catch (e) {
                    throw new Error(`Proxy returned invalid JSON: ${text.slice(0, 100)}`);
                }
            }
            throw new Error(`Proxy fallback failed. Status: ${res.status}`);
        }

        const data = await res.json();
        return { success: true, data, secondsUntilMidnight };
    } catch (error) {
        console.error("Almanax Fetch Error:", error);
        return { success: false, error: "Impossible de charger l'Almanax" };
    }
}

