import { type ModuleKey, type GuildModulesState, DEFAULT_MODULES } from "@/lib/module-types";

const UpdateModulesSchema = z.object({
    // Général
    presentation: z.boolean(),
    roster: z.boolean(),
    stats: z.boolean(),
    calendar: z.boolean(),
    // Fonctionnalités
    missions: z.boolean(),
    songes: z.boolean(),
    ocre: z.boolean(),
    ladder: z.boolean(),
    // Outils
    services: z.boolean(),
    donjons: z.boolean(),
    profile: z.boolean(),
    docs: z.boolean(),
    polls: z.boolean(),
    // Admin
    logs: z.boolean(),
    admin: z.boolean(),
    // Coming Soon
    quests: z.boolean(),
    worldmap: z.boolean(),
    resources: z.boolean(),
    // Nouveau
    gallery: z.boolean(),
    ladderSync: z.boolean(),
    manualLadderSync: z.boolean(),
    minigames: z.boolean(),
});

type ActionResponse<T = undefined> = {
    success: boolean;
    error?: string;
    data?: T;
};

import { cache } from "react";

// In-memory cache for module states (30s TTL)
const moduleCache = new Map<string, { data: GuildModulesState, expiresAt: number }>();
const MODULE_CACHE_TTL = 30_000;

/**
 * Invalidate modules cache for a guild
 */
export async function invalidateModuleCache(discordGuildId: string) {
    moduleCache.delete(discordGuildId);
}

export const getGuildModules = cache(async (discordGuildId: string): Promise<GuildModulesState> => {
    const now = Date.now();
    const cached = moduleCache.get(discordGuildId);

    if (cached && cached.expiresAt > now) {
        return cached.data;
    }

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId },
            include: { modules: true },
        });

        const modules = guildConfig?.modules as any;
        const data = !modules ? DEFAULT_MODULES : {
            presentation: modules.presentation,
            roster: modules.roster,
            stats: modules.stats,
            calendar: modules.calendar,
            missions: modules.missions,
            songes: modules.songes,
            ocre: modules.ocre,
            ladder: modules.ladder,
            services: modules.services,
            donjons: modules.donjons,
            profile: modules.profile,
            docs: modules.docs,
            polls: modules.polls,
            logs: modules.logs,
            admin: modules.admin,
            quests: modules.quests,
            worldmap: modules.worldmap,
            resources: modules.resources,
            gallery: modules.gallery,
            ladderSync: modules.ladderSync,
            manualLadderSync: modules.manualLadderSync ?? true,
            minigames: modules.minigames ?? true,
        };

        moduleCache.set(discordGuildId, { data, expiresAt: now + MODULE_CACHE_TTL });
        return data;
    } catch {
        return DEFAULT_MODULES;
    }
});

export async function isModuleEnabled(
    discordGuildId: string,
    module: ModuleKey
): Promise<boolean> {
    const modules = await getGuildModules(discordGuildId);
    return modules[module];
}

// ============================================================================
// MUTATIONS (Admin only)
// ============================================================================

export async function updateGuildModules(
    discordGuildId: string,
    newModules: GuildModulesState
): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    const user = await getUserContext(discordGuildId);
    if (!user.isAdmin) return { success: false, error: "Accès non autorisé" };

    const parsed = UpdateModulesSchema.safeParse(newModules);
    if (!parsed.success) return { success: false, error: "Données invalides" };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId },
            include: { modules: true },
        });

        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const oldModules = guildConfig.modules ?? DEFAULT_MODULES;

        await db.guildModules.upsert({
            where: { guildId: guildConfig.id },
            create: {
                guildId: guildConfig.id,
                ...parsed.data,
                updatedBy: session.user.id,
            },
            update: {
                ...parsed.data,
                updatedBy: session.user.id,
            },
        });

        // 🛡️ CRITICAL: Invalidate Server-side memory caches
        await invalidateModuleCache(discordGuildId);
        const { invalidateGuildCache } = await import("./user-actions");
        await invalidateGuildCache(discordGuildId);

        await createAuditLog({
            guildId: discordGuildId,
            actorUserId: session.user.id,
            actorName: session.user.name || "Admin",
            action: "CONFIG_UPDATED",
            targetType: "CONFIG",
            targetId: "MODULES",
            oldValue: oldModules,
            newValue: parsed.data,
        });

        revalidatePath(`/dashboard/${discordGuildId}/admin/modules`);
        // BUGFIX: Invalider le layout pour répercuter les changements de modules sur tout le dashboard
        revalidatePath(`/dashboard/${discordGuildId}`, "layout");


        return { success: true };
    } catch (error) {
        console.error("[updateGuildModules] Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { isSuperAdmin } from "./super-admin-actions";
import { getUserContext } from "./user-actions";
import { sendChannelMessage } from "@/server/discord";
import { revalidatePath } from "next/cache";
import { getAppBaseUrl } from "@/lib/utils";

export type DiscordNewsItem = {
    title: string;
    url: string;
    imageUrl?: string;
    description?: string;
    pubDate: string;
    category: string;
};

/**
 * Common Embed formatter for Dofus News/Changelogs
 */
function createNewsEmbed(item: DiscordNewsItem) {
    const isChangelog = item.category === "Changelog" || item.title.toLowerCase().includes("patch notes");
    
    return {
        embedTitle: item.title,
        embedUrl: item.url,
        embedColor: isChangelog ? 0x10b981 : 0x3b82f6, // Emerald for changelog, Blue for news
        embedDescription: item.description || "Consulter le détail de la mise à jour sur le site officiel de Dofus.",
        embedThumbnail: `${getAppBaseUrl()}/assets/ui/logo-v2.png`, // SigilOS Logo
        embedImage: item.imageUrl,
        embedFooter: `SigilOS · Actualités Dofus · ${new Date(item.pubDate).toLocaleDateString('fr-FR')}`,
        embedAuthor: {
            name: isChangelog ? "Dofus — Patch Notes" : "Dofus — Actualités",
            iconUrl: "https://static.ankama.com/ankama/cms/images/282/2026/01/21/1765851.jpg"
        }
    };
}

/**
 * Send a news item to a specific guild's system channel
 */
export async function sendNewsToDiscord(guildId: string, item: DiscordNewsItem) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    // Use the central security guard to check permissions
    const ctx = await getUserContext(guildId);

    if (!ctx.isMember) return { success: false, error: "Non membre de cette guilde" };
    if (!ctx.isAdmin && !ctx.isSuperAdmin) return { success: false, error: "Permissions insuffisantes (Admin requis)" };

    const config = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { systemNotifyChannelId: true, isActive: true }
    });

    if (!config || !config.isActive) return { success: false, error: "Configuration de guilde introuvable ou inactive" };

    const targetChannelId = config.systemNotifyChannelId;
    if (!targetChannelId) return { success: false, error: "Aucun salon de notifications système configuré" };

    try {
        const messageId = await sendChannelMessage(
            targetChannelId,
            "",
            createNewsEmbed(item)
        );

        if (!messageId) throw new Error("Erreur Discord API");

        return { success: true, messageId };
    } catch (error) {
        console.error("[News Discord] Error sending to guild:", error);
        return { success: false, error: "Échec de l'envoi sur Discord" };
    }
}

/**
 * SuperAdmin Only: Broadcast a news item to ALL active guilds
 */
export async function broadcastNewsToAllGuilds(item: DiscordNewsItem) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: "Unauthorized" };

    const guilds = await db.guildConfig.findMany({
        where: { isActive: true, systemNotifyChannelId: { not: null } },
        select: { discordGuildId: true, systemNotifyChannelId: true, name: true }
    });

    const results = {
        total: guilds.length,
        success: 0,
        failed: 0,
        errors: [] as string[]
    };

    const embed = createNewsEmbed(item);

    // Batch sending (serial to avoid brutal rate limits, though sendChannelMessage has retry logic)
    for (const guild of guilds) {
        try {
            const mid = await sendChannelMessage(guild.systemNotifyChannelId!, "", embed);
            if (mid) results.success++;
            else throw new Error(`API null response for ${guild.name}`);
        } catch (e) {
            results.failed++;
            results.errors.push(`${guild.name}: ${(e as Error).message}`);
        }
    }

    return { success: true, results };
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { NotificationType, NotificationCategory } from "@prisma/client";
import { revalidatePath } from "next/cache";

// --- Types ---

export type Notification = {
    id: string;
    title: string;
    message: string;
    type: NotificationType;
    category: NotificationCategory;
    read: boolean;
    link: string | null;
    createdAt: Date;
};

// --- Helpers ---

/**
 * Infer category from notification type or content for legacy support
 */
function inferCategory(type: NotificationType, title: string): NotificationCategory {
    if (["MISSION_VALIDATED", "MISSION_REJECTED"].includes(type)) return "MISSION";
    if (["ACHIEVEMENT_VALIDATED", "ACHIEVEMENT_REJECTED"].includes(type)) return "SUCCESS";
    if (type === "NEW_SUBMISSION_PENDING") return "ADMIN_ALERT";
    if (type === "SONGES_JOIN_REQUEST" || title.toLowerCase().includes("songes")) return "SONGES";
    if (type === "EVENT_REMINDER" || title.toLowerCase().includes("rappel") || title.toLowerCase().includes("event")) return "EVENT";
    if (type === "POLL_CREATED" || type === "POLL_CLOSED" || title.toLowerCase().includes("sondage")) return "POLL";
    if (type.startsWith("OCRE_") || title.toLowerCase().includes("ocre")) return "OCRE";
    if (type.startsWith("FINDER_") || title.toLowerCase().includes("donjon")) return "DONJONS";
    return "SYSTEM";
}

// --- Actions ---

export async function getUnreadNotifications(): Promise<{ success: boolean; data?: Notification[]; error?: string }> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    try {
        const notifications = await db.notification.findMany({
            where: {
                userId: session.user.id,
                read: false
            },
            orderBy: { createdAt: "desc" },
            take: 50, // PERF: limit results to prevent unbounded accumulation
        });

        return { success: true, data: notifications as Notification[] };
    } catch (error) {
        console.error("Get Notifications Error:", error);
        return { success: false, error: "Database error" };
    }
}

export async function markAsRead(notificationId: string) {
    const session = await auth();
    if (!session?.user?.id) return;

    try {
        await db.notification.update({
            where: { id: notificationId, userId: session.user.id },
            data: { read: true }
        });
        revalidatePath("/");
    } catch (error) {
        console.error("Mark Read Error:", error);
    }
}

export async function markAllAsRead() {
    const session = await auth();
    if (!session?.user?.id) return;

    try {
        await db.notification.updateMany({
            where: { userId: session.user.id, read: false },
            data: { read: true }
        });
        revalidatePath("/");
    } catch (error) {
        console.error("Mark All Read Error:", error);
    }
}

/**
 * Internal Helper to create notification
 * Respects user preferences stored in UserProfile
 */
export async function createNotification(
    userId: string,
    type: NotificationType,
    title: string,
    message: string,
    link?: string,
    guildId?: string,
    category?: NotificationCategory
) {
    try {
        const finalCategory = category || inferCategory(type, title);

        // 1. Check Preferences if guildId is provided
        if (guildId) {
            let internalGuildId = guildId;
            if (guildId.length > 15) { // Discord ID lookup
                const guild = await db.guildConfig.findUnique({ where: { discordGuildId: guildId }, select: { id: true } });
                if (guild) internalGuildId = guild.id;
            }

            const profile = await db.userProfile.findUnique({
                where: { userId_guildId: { userId, guildId: internalGuildId } },
                select: { notificationPrefs: true }
            });

            if (profile?.notificationPrefs) {
                const prefs = profile.notificationPrefs as any;

                // Stop if preference is explicitly false
                if (finalCategory === "MISSION" && prefs.missions === false) return;
                if (finalCategory === "SUCCESS" && prefs.ladder === false) return; 
                if (finalCategory === "SONGES" && prefs.songes === false) return;
                if (finalCategory === "EVENT" && prefs.events === false) return;
                if (finalCategory === "POLL" && prefs.polls === false) return;
                if (finalCategory === "OCRE" && prefs.ocre === false) return;
                if (finalCategory === "DONJONS" && prefs.donjons === false) return;
                if (finalCategory === "ADMIN_ALERT" && prefs.admin_validations === false) return;
            }
        }

        // 2. Create Notification
        await db.notification.create({
            data: {
                userId,
                type,
                category: finalCategory,
                title,
                message,
                link: link || null
            }
        });
    } catch (error) {
        console.error("[Notification] Creation Failed:", error);
    }
}

