export async function acceptTradeRequest(rawData: z.infer<typeof ActionTradeSchema>): Promise<ActionResponse> {
    try {
        const session = await auth();
        if (!session?.user?.id) return { success: false, error: "Non authentifiÃ©" };

        const parsed = ActionTradeSchema.safeParse(rawData);
        if (!parsed.success) return { success: false, error: "DonnÃ©es invalides" };
        const { guildId, requestId } = parsed.data;

        const guildConfig = await db.guildConfig.findUnique({ where: { discordGuildId: guildId }, select: { id: true } });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const tradeRequest = await (db as any).ocreTradeRequest.findUnique({
            where: { id: requestId },
            include: { target: true, requester: true }
        });

        if (!tradeRequest || tradeRequest.guildId !== guildConfig.id) return { success: false, error: "Demande introuvable" };
        if (tradeRequest.target.userId !== session.user.id) return { success: false, error: "Non autorisÃ©" };
        if (tradeRequest.status !== "PENDING") return { success: false, error: "Demande dÃ©jÃ  traitÃ©e" };

        // Mark as Accepted
        await (db as any).ocreTradeRequest.update({
            where: { id: requestId },
            data: { status: "ACCEPTED" }
        });

        // Notify Requester
        await (db.notification as any).create({
            data: {
                userId: tradeRequest.requester.userId,
                type: "OCRE_TRADE_ACCEPTED",
                title: "Ã‰change AcceptÃ©",
                message: `${tradeRequest.target.discordNickname || tradeRequest.target.metamobPseudo || "Un membre"} a acceptÃ© votre Ã©change !`,
                link: `/dashboard/${guildId}/quete-ocre`,
            }
        });

        // Metamob Auto-Update
        try {
            const { getUserMonsters, updateMonsterQuantity } = await import("@/lib/metamob-client");

            // 1. Update Requester (Gains 1 monster)
            if (tradeRequest.requester.metamobApiKey && tradeRequest.requester.metamobQuestSlug && tradeRequest.requester.metamobVerified) {
                const reqMonsters = await getUserMonsters(tradeRequest.requester.metamobPseudo, { guildApiKey: tradeRequest.requester.metamobApiKey });
                const reqMonster = reqMonsters.find(m => m.id === tradeRequest.monsterId);
                const reqCurrent = reqMonster ? reqMonster.quantite : 0;
                await updateMonsterQuantity(
                    tradeRequest.requester.metamobPseudo,
                    tradeRequest.requester.metamobQuestSlug,
                    tradeRequest.monsterId,
                    reqCurrent + 1,
                    { guildApiKey: tradeRequest.requester.metamobApiKey }
                );
            }

            // 2. Update Target (Loses 1 monster)
            if (tradeRequest.target.metamobApiKey && tradeRequest.target.metamobQuestSlug && tradeRequest.target.metamobVerified) {
                const targetMonsters = await getUserMonsters(tradeRequest.target.metamobPseudo, { guildApiKey: tradeRequest.target.metamobApiKey });
                const targetMonster = targetMonsters.find(m => m.id === tradeRequest.monsterId);
                const targetCurrent = targetMonster ? targetMonster.quantite : 0;
                if (targetCurrent > 0) {
                    await updateMonsterQuantity(
                        tradeRequest.target.metamobPseudo,
                        tradeRequest.target.metamobQuestSlug,
                        tradeRequest.monsterId,
                        targetCurrent - 1,
                        { guildApiKey: tradeRequest.target.metamobApiKey }
                    );
                }
            }
        } catch (syncError) {
            console.error("[acceptTradeRequest] Auto-sync to Metamob failed:", syncError);
            // We do not fail the trade just because Metamob API failed, the users can do it manually worst case
        }

        revalidatePath(`/dashboard/${guildId}/quete-ocre`);

        // Trigger live update via socket
        try {
            const redis = (await import("@/lib/redis")).default;
            await redis.publish("ocre:trade:update", JSON.stringify({ guildId, type: "ACCEPTED", requestId }));
        } catch (e) { }

        return { success: true };
    } catch (error) {
        console.error("[acceptTradeRequest] Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

export async function getPendingTradeRequests(guildId: string): Promise<ActionResponse<any>> {
    try {
        const session = await auth();
        if (!session?.user?.id) return { success: false, error: "Non authentifiÃ©" };

        const guildConfig = await db.guildConfig.findUnique({ where: { discordGuildId: guildId }, select: { id: true } });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const userProfile = await db.userProfile.findFirst({
            where: { userId: session.user.id, guildId: guildConfig.id, status: "ACTIVE" }
        });

        if (!userProfile) return { success: false, error: "Profil introuvable" };

        const incomingRaw = await (db as any).ocreTradeRequest.findMany({
            where: { targetId: userProfile.id, status: "PENDING" },
            include: { requester: { select: { discordNickname: true, metamobPseudo: true, user: { select: { name: true, image: true } } } } },
            orderBy: { createdAt: "desc" }
        });

        const outgoingRaw = await (db as any).ocreTradeRequest.findMany({
            where: { requesterId: userProfile.id, status: "PENDING" },
            include: { target: { select: { discordNickname: true, metamobPseudo: true, user: { select: { name: true, image: true } } } } },
            orderBy: { createdAt: "desc" }
        });

        const { getMonster } = await import("@/lib/metamob-client");
        const enrichRequests = async (reqs: any[]) => {
            return Promise.all(reqs.map(async (req) => {
                // Determine if we need to fetch info
                const isPlaceholder = !req.monsterName || req.monsterName.includes("#");
                const hasImage = !!req.monsterImageUrl;

                // Return immediately if enrichment already happened accurately
                if (!isPlaceholder && hasImage) {
                    return req;
                }

                let monsterName = req.monsterName || `Monstre #${req.monsterId}`;
                let monsterImageUrl = req.monsterImageUrl || "";
                
                try {
                    const m = await getMonster(req.monsterId);
                    if (m && m.name) {
                        monsterName = m.name.fr || m.name.en || monsterName;
                        monsterImageUrl = m.image ? (m.image.startsWith('http') ? m.image : `https://www.metamob.fr/img/monsters/${m.image}`) : monsterImageUrl;
                        
                        // Background update: fill missing info in DB to avoid future API calls
                        (db as any).ocreTradeRequest.update({
                            where: { id: req.id },
                            data: { monsterName, monsterImageUrl }
                        }).catch(() => {}); // Fire and forget
                    }
                } catch (e) {
                    console.error(`[getPendingTradeRequests] Failed to enrich monster ${req.monsterId}:`, e);
                }

                return { ...req, monsterName, monsterImageUrl };
            }));
        };

        const [incoming, outgoing] = await Promise.all([
            enrichRequests(incomingRaw),
            enrichRequests(outgoingRaw)
        ]);

        return { success: true, data: { incoming, outgoing } };
    } catch (error) {
        console.error("[getPendingTradeRequests] Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

/** Get archmonsters for a specific zone from the user's Metamob progress */
export async function getZoneArchmonsters(guildId: string, zoneName: string): Promise<ActionResponse<OcreMonster[]>> {
    try {
        const res = await getMyOcreProgress(guildId);
        if (!res.success || !res.data) {
            // Forward "Compte non lié" specific message so the frontend can catch it
            return { success: false, error: res.error === "Compte non lié" ? "Compte non lié" : res.error || "Impossible de récupérer la progression Ocre" };
        }

        const normalizedZone = zoneName.toLowerCase().trim();
        const zoneArchis = res.data.monsters.filter(m => {
            if (m.type !== "archimonstre") return false;

            const search = normalizedZone;
            const mZone = (m.zone || "").toLowerCase();
            const mSubzone = (m.subzone || "").toLowerCase();

            // Split zones by comma to handle multi-zone monsters
            const monsterZones = mZone.split(",").map(z => z.trim()).filter(Boolean);
            const monsterSubzones = mSubzone.split(",").map(z => z.trim()).filter(Boolean);

            // Strict: exact equality only (avoids "Incarnam" matching "Champs de l'Incarnam")
            const matchesZone = monsterZones.some(mz => mz === search);
            const matchesSubzone = monsterSubzones.some(msz => msz === search);

            return matchesZone || matchesSubzone;
        });

        // Sort: Missing first, then by name
        const sorted = zoneArchis.sort((a, b) => {
            if (a.state === "MANQUANT" && b.state !== "MANQUANT") return -1;
            if (a.state !== "MANQUANT" && b.state === "MANQUANT") return 1;
            return a.name.localeCompare(b.name);
        });

        return { success: true, data: sorted };
    } catch (error) {
        console.error("[getZoneArchmonsters] Error:", error);
        return { success: false, error: "Erreur lors du filtrage des archimonstres" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { getUserContext } from "./user-actions";
import { revalidatePath } from "next/cache";
import { getDofusWeek } from "@/lib/date-utils";

export type OnboardingProgress = {
    steps: {
        id: string;
        title: string;
        description: string;
        status: "COMPLETED" | "IN_PROGRESS" | "TO_DO";
        points: number;
        href: string;
    }[];
    totalPoints: number;
    maxPoints: number;
    isFinished: boolean;
};

export async function getGettingStartedProgress(guildId: string): Promise<OnboardingProgress> {
    const user = await getUserContext(guildId);
    if (!user.isAdmin) {
        throw new Error("Unauthorized");
    }

    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        include: {
            modules: true,
            _count: {
                select: {
                    profiles: true,
                    missions: {
                        where: {
                            weekNumber: getDofusWeek().week,
                            year: getDofusWeek().year,
                        }
                    }
                }
            }
        }
    });

    if (!guild) {
        throw new Error("Guild not found");
    }

    const steps: OnboardingProgress["steps"] = [
        {
            id: "discord",
            title: "Lier le Bot Discord",
            description: "Le cœur de SigilOS est son lien avec Discord. Assurez-vous d'avoir configuré un salon de notifications.",
            status: guild.missionNotifyChannelId ? "COMPLETED" : "TO_DO",
            points: 20,
            href: `/dashboard/${guildId}/admin/settings`,
        },
        {
            id: "modules",
            title: "Configurer les Modules",
            description: "Activez les fonctionnalités dont votre guilde a besoin (Missions, Songes, Ocre...).",
            status: guild.modules && countEnabledModules(guild.modules) > 4 ? "COMPLETED" : "IN_PROGRESS",
            points: 20,
            href: `/dashboard/${guildId}/admin/modules`,
        },
        {
            id: "presentation",
            title: "Page de Présentation",
            description: "Personnalisez votre page publique pour attirer de nouveaux membres.",
            status: guild.presentationEnabled && guild.presentationHistory ? "COMPLETED" : "IN_PROGRESS",
            points: 20,
            href: `/dashboard/${guildId}/admin/presentation`,
        },
        {
            id: "missions",
            title: "Premières Missions",
            description: "Lancez l'activité en publiant des missions hebdomadaires pour vos membres.",
            status: guild._count.missions > 0 ? "COMPLETED" : "TO_DO",
            points: 20,
            href: `/dashboard/${guildId}/missions/manage`,
        },
        {
            id: "members",
            title: "Inviter les Membres",
            description: "Partagez l'accès au Dashboard à vos membres pour qu'ils commencent à gagner de l'XP.",
            status: guild._count.profiles > 1 ? "COMPLETED" : "IN_PROGRESS",
            points: 20,
            href: `/dashboard/${guildId}/admin/settings#membres`,
        },
    ];

    const totalPoints = steps.reduce((acc, step) => acc + (step.status === "COMPLETED" ? step.points : 0), 0);
    const maxPoints = steps.reduce((acc, step) => acc + step.points, 0);

    return {
        steps,
        totalPoints,
        maxPoints,
        isFinished: totalPoints === maxPoints,
    };
}

export async function markWelcomeAsSeen(guildId: string) {
    const user = await getUserContext(guildId);
    if (!user.isAuthenticated) return { success: false, error: "Unauthorized" };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });

        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        await db.userProfile.update({
            where: {
                userId_guildId: {
                    userId: user.id!,
                    guildId: guildConfig.id,
                },
            },
            data: {
                hasSeenWelcome: true,
            },
        });

        // 🛡️ CRITICAL: Invalidate Server-side memory cache
        const { invalidateUserContextCache } = await import("./user-actions");
        await invalidateUserContextCache(user.id!, guildConfig.id, guildId);

        revalidatePath(`/dashboard/${guildId}`);
        return { success: true };
    } catch (e) {
        console.error("Failed to mark welcome as seen", e);
        return { success: false, error: "Database error" };
    }
}

function countEnabledModules(modules: any): number {
    let count = 0;
    const keys = ["presentation", "roster", "stats", "calendar", "missions", "songes", "ocre", "ladder", "services", "donjons", "profile", "docs", "polls", "admin"];
    for (const key of keys) {
        if (modules[key] === true) count++;
    }
    return count;
}


export async function sendWelcomeNotifications(guildConfig: any, profileId: string, displayName: string) {
    if (!guildConfig) return;

    // Helper to strip HTML tags
    const stripHtml = (html: string) => {
        if (!html) return "";
        return html
            .replace(/<p>/g, "")
            .replace(/<\/p>/g, "\n")
            .replace(/<br\s*\/?>/g, "\n")
            .replace(/<strong>/g, "**")
            .replace(/<\/strong>/g, "**")
            .replace(/<em>/g, "_")
            .replace(/<\/em>/g, "_")
            .replace(/<[^>]*>?/gm, "")
            .trim();
    };

    // Fetch user profile to get Discord ID if needed for pinging
    const profile = await db.userProfile.findUnique({
        where: { id: profileId },
        select: {
            userId: true,
            user: {
                select: {
                    image: true,
                    accounts: {
                        where: { provider: "discord" },
                        select: { providerAccountId: true },
                        take: 1
                    }
                }
            }
        },
    });

    const discordUserId = profile?.user?.accounts?.[0]?.providerAccountId;

    // 1. Dashboard Welcome Post
    if (guildConfig.welcomeDashboardEnabled) {
        const template = guildConfig.welcomeMessageTemplate || "<p>🎉 Bienvenue à <strong>{member}</strong> parmi nous !</p>";
        const content = template
            .replace(/{member}/g, `**${displayName}**`)
            .replace(/{user}/g, `**${displayName}**`)
            .replace(/{nickname}/g, `**${displayName}**`)
            .replace(/{guild}/g, `**${guildConfig.name || "la guilde"}**`)
            .replace(/{server}/g, `**${guildConfig.name || "la guilde"}**`);

        try {
            await Promise.all([
                db.memberWelcome.create({
                    data: {
                        guildId: guildConfig.id,
                        profileId: profileId,
                        content: content
                    }
                }),
                db.guildActivity.create({
                    data: {
                        guildId: guildConfig.id,
                        type: "NEW_MEMBER",
                        actorName: displayName,
                        meta: { message: stripHtml(content), profileId }
                    }
                })
            ]);
        } catch (e) {
            console.error("[Welcome] Failed to create welcome records", e);
        }
    }

    // 2. Global In-App Notification (Small bell for everyone)
    try {
        const { createNotification } = await import("@/server/actions/notification-actions");

        const activeMembers = await db.userProfile.findMany({
            where: {
                guildId: guildConfig.id,
                status: "ACTIVE",
                id: { not: profileId }
            },
            select: { userId: true }
        });

        if (activeMembers.length > 0) {
            const notificationTitle = "✨ Arrivée d'un nouveau membre";
            const notificationMessage = `${displayName} vient d'intégrer le Dashboard ! 👋`;

            const notificationPromises = activeMembers.map(m =>
                createNotification(
                    m.userId,
                    "SYSTEM_INFO",
                    notificationTitle,
                    notificationMessage,
                    `/dashboard/${guildConfig.discordGuildId}/welcome`,
                    guildConfig.discordGuildId,
                    "SYSTEM"
                )
            );

            const CHUNK_SIZE = 50;
            for (let i = 0; i < notificationPromises.length; i += CHUNK_SIZE) {
                await Promise.all(notificationPromises.slice(i, i + CHUNK_SIZE));
            }
        }
    } catch (e) {
        console.error("[Welcome] Failed to send global notifications", e);
    }

    // 3. Discord Welcome Ping
    if (guildConfig.welcomeDiscordEnabled && guildConfig.welcomeNotifyChannelId) {
        const { sendChannelMessage } = await import("@/server/discord");

        const rawTemplate = guildConfig.welcomeDiscordMessageTemplate || guildConfig.welcomeMessageTemplate || "🎉 Bienvenue à {member} !";
        const template = stripHtml(rawTemplate);

        const memberMention = discordUserId ? `<@${discordUserId}>` : `**${displayName}**`;

        const content = template
            .replace(/{member}/g, memberMention)
            .replace(/{user}/g, memberMention)
            .replace(/{nickname}/g, memberMention)
            .replace(/{guild}/g, `**${guildConfig.name || "la guilde"}**`)
            .replace(/{server}/g, `**${guildConfig.name || "la guilde"}**`);

        // Pings go outside the embed (trigger notification)
        let mentionContent = "";
        if (guildConfig.welcomeMentionRoleId) {
            mentionContent = guildConfig.welcomeMentionRoleId === "everyone"
                ? "@everyone"
                : `<@&${guildConfig.welcomeMentionRoleId}>`;
        }

        // Combine role ping and user ping for maximum attention
        const pings = [mentionContent, memberMention].filter(Boolean).join(" ");

        try {
            await sendChannelMessage(guildConfig.welcomeNotifyChannelId, pings, {
                embedTitle: `🌟 NOUVELLE ARRIVÉE !`,
                embedDescription: content,
                embedColor: 0xf59e0b, // Amber 500
                embedThumbnail: profile?.user?.image || "https://beta.sigilos.fr/assets/ui/logo-v2.png",
                embedFooter: "SigilOS Onboarding System"
            });
        } catch (e) {
            console.error("[Welcome] Failed to send Discord welcome message", e);
        }
    }
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { getUserContext } from "./user-actions";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { ActionResponse } from "./admin-actions";
import { sendChannelMessage, fetchGuildRoles, validateChannelBelongsToGuild } from "@/server/discord";
import { emitGuildActivity } from "./activity-actions";

const WelcomeSettingsSchema = z.object({
    guildId: z.string(),
    enabled: z.boolean(),
    channelId: z.string().nullable(),
    template: z.string().nullable(),
    discordTemplate: z.string().nullable(),
    mentionRoleId: z.string().nullable(),
    dashboardEnabled: z.boolean().default(true),
    discordEnabled: z.boolean().default(false),
});

const WelcomeBadgeSchema = z.object({
    guildId: z.string(),
    badgeName: z.string().min(1).max(50),
});

const GrantBadgeSchema = z.object({
    guildId: z.string(),
    profileId: z.string(),
    days: z.number().min(1).max(365),
});

export async function getOnboardingSettings(guildId: string) {
    const user = await getUserContext(guildId);
    if (!user.isAdmin) return { success: false, error: "Unauthorized" };

    try {
        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: {
                welcomeEnabled: true,
                welcomeNotifyChannelId: true,
                welcomeMessageTemplate: true,
                welcomeDiscordMessageTemplate: true,
                welcomeMentionRoleId: true,
                welcomeDashboardEnabled: true,
                welcomeDiscordEnabled: true,
                welcomeBadgeName: true,
            }
        });

        if (!guild) return { success: false, error: "Guild not found" };

        // 3. Fetch Discord Roles for selection
        const roles = await fetchGuildRoles(guildId, { excludeManaged: true }).catch(() => []);

        return JSON.parse(JSON.stringify({
            success: true,
            data: {
                enabled: guild.welcomeEnabled,
                channelId: guild.welcomeNotifyChannelId,
                template: guild.welcomeMessageTemplate,
                discordTemplate: guild.welcomeDiscordMessageTemplate,
                mentionRoleId: guild.welcomeMentionRoleId,
                dashboardEnabled: guild.welcomeDashboardEnabled,
                discordEnabled: guild.welcomeDiscordEnabled,
                welcomeBadgeName: guild.welcomeBadgeName,
                availableRoles: roles.map(r => ({ id: r.id, name: r.name })),
            }
        }));
    } catch (e) {
        console.error("Failed to get onboarding settings", e);
        return { success: false, error: "Database error" };
    }
}

export async function updateWelcomeSettings(data: z.infer<typeof WelcomeSettingsSchema>) {
    const user = await getUserContext(data.guildId);
    if (!user.isAdmin) return { success: false, error: "Unauthorized" };

    try {
        // SECURITY: Validate that the channel belongs to the guild
        if (data.channelId && data.discordEnabled) {
            const isValid = await validateChannelBelongsToGuild(data.channelId, data.guildId);
            if (!isValid) {
                return { success: false, error: "Le salon Discord saisi n'appartient pas à ce serveur." };
            }
        }

        await db.guildConfig.update({
            where: { discordGuildId: data.guildId },
            data: {
                welcomeEnabled: data.enabled,
                welcomeNotifyChannelId: data.channelId,
                welcomeMessageTemplate: data.template,
                welcomeDiscordMessageTemplate: data.discordTemplate,
                welcomeMentionRoleId: data.mentionRoleId,
                welcomeDashboardEnabled: data.dashboardEnabled,
                welcomeDiscordEnabled: data.discordEnabled,
            }
        });

        // 🛡️ CRITICAL: Invalidate Server-side memory cache
        const { invalidateGuildCache } = await import("./user-actions");
        await invalidateGuildCache(data.guildId);

        revalidatePath(`/dashboard/${data.guildId}/admin/settings`);
        return { success: true };
    } catch (e) {
        console.error("Failed to update welcome settings", e);
        return { success: false, error: "Database error" };
    }
}

export async function updateWelcomeBadgeName(data: z.infer<typeof WelcomeBadgeSchema>) {
    const user = await getUserContext(data.guildId);
    if (!user.isAdmin) return { success: false, error: "Unauthorized" };

    try {
        const guildConfig = await db.guildConfig.update({
            where: { discordGuildId: data.guildId },
            data: {
                welcomeBadgeName: data.badgeName,
            },
            select: { id: true }
        });

        if (guildConfig) {
            await db.sigilRole.upsert({
                where: {
                    guildId_slug: {
                        guildId: guildConfig.id,
