export async function grantWelcomeBadge(data: z.infer<typeof GrantBadgeSchema>) {
    const user = await getUserContext(data.guildId);
    if (!user.isAdmin) return { success: false, error: "Unauthorized" };

    try {
        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId: data.guildId },
            select: { id: true, welcomeBadgeName: true }
        });
        if (!guild) return { success: false, error: "Guild not found" };

        const role = await db.sigilRole.upsert({
            where: {
                guildId_slug: {
                    guildId: guild.id,
                    slug: "probation"
                }
            },
            update: { label: guild.welcomeBadgeName },
            create: {
                guildId: guild.id,
                slug: "probation",
                label: guild.welcomeBadgeName,
                permissions: [],
                color: "#f59e0b"
            }
        });

        const expiresAt = new Date();
        expiresAt.setDate(expiresAt.getDate() + data.days);

        await db.sigilRoleGrant.upsert({
            where: {
                roleId_profileId: {
                    roleId: role.id,
                    profileId: data.profileId
                }
            },
            update: {
                expiresAt,
                revokedAt: null,
                grantedBy: user.profileId!
            },
            create: {
                roleId: role.id,
                profileId: data.profileId,
                expiresAt,
                grantedBy: user.profileId!
            }
        });

        revalidatePath(`/dashboard/${data.guildId}/profile`);
        revalidatePath(`/dashboard/${data.guildId}/members`);
        return { success: true };
    } catch (e) {
        console.error("Failed to grant welcome badge", e);
        return { success: false, error: "Database error" };
    }
}

export async function sendWelcomeMessage(guildId: string, memberProfileId: string) {
    const user = await getUserContext(guildId);
    if (!user.isAdmin) return { success: false, error: "Unauthorized" };

    try {
        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            include: { modules: true },
        });

        if (!guild) return { success: false, error: "Guild not found" };

        const memberProfile = await db.userProfile.findUnique({
            where: { id: memberProfileId },
            include: { user: true }
        });

        if (!memberProfile) return { success: false, error: "Membre introuvable" };

        const channelId = guild.welcomeNotifyChannelId;
        const template = guild.welcomeMessageTemplate || "Bienvenue {member} parmi nous !";
        const discordTemplate = guild.welcomeDiscordMessageTemplate || template;

        // 1. Emit Guild Activity (for Dashboard feed)
        await emitGuildActivity(
            guild.id,
            "NEW_MEMBER",
            memberProfile.pseudoDofus || memberProfile.discordNickname || memberProfile.user.name || "Nouveau membre",
            memberProfile.user.image,
            { message: template.replace(/{member}/g, "").replace(/{user}/g, "").replace(/{guild}/g, guild.name) }
        );

        // 2. Publish to Dashboard if configured
        if (guild.welcomeDashboardEnabled) {
            const memberName = memberProfile.pseudoDofus || memberProfile.discordNickname || memberProfile.user.name || "Nouveau membre";
            const content = template
                .replace(/{member}/g, `**${memberName}**`)
                .replace(/{user}/g, `**${memberName}**`)
                .replace(/{nickname}/g, `**${memberName}**`)
                .replace(/{guild}/g, `**${guild.name}**`)
                .replace(/{server}/g, `**${guild.name}**`);

            await db.memberWelcome.create({
                data: {
                    guildId: guild.id,
                    profileId: memberProfile.id,
                    content: content,
                }
            });
        }

        // 3. Publish to Discord if configured
        if (guild.welcomeDiscordEnabled && channelId) {
            // Fetch Discord Account ID for real mention
            const discordAccount = await db.account.findFirst({
                where: { userId: memberProfile.userId, provider: "discord" }
            });

            const memberName = memberProfile.pseudoDofus || memberProfile.discordNickname || memberProfile.user.name || "Nouveau membre";
            const memberMention = discordAccount ? `<@${discordAccount.providerAccountId}>` : `**${memberName}**`;

            // Keep the welcome text clean for the embed description
            const welcomeDescription = discordTemplate
                .replace(/{member}/g, memberMention)
                .replace(/{user}/g, memberMention)
                .replace(/{nickname}/g, memberMention)
                .replace(/{guild}/g, `**${guild.name}**`)
                .replace(/{server}/g, `**${guild.name}**`);

            // Pings go outside the embed (trigger notification)
            const mentionRoleId = guild.welcomeMentionRoleId;
            let groupPing = "";
            if (mentionRoleId === "everyone") groupPing = "@everyone";
            else if (mentionRoleId) groupPing = `<@&${mentionRoleId}>`;

            // Combine role ping and user ping for maximum attention
            const pings = [groupPing, discordAccount ? memberMention : ""].filter(Boolean).join(" ");

            await sendChannelMessage(channelId, "", {
                mentionContent: pings,
                embedTitle: `✨ Une nouvelle légende rejoint ${guild.name} !`,
                embedDescription: welcomeDescription,
                embedColor: 0xf59e0b, // Amber 500
                embedThumbnail: memberProfile.user.image || undefined,
                embedImage: (guild as any).presentationBannerUrl || undefined,
                embedFooter: `Souhaité par ${user.name} • SigilOS`,
            });
        }

        revalidatePath(`/dashboard/${guildId}`);
        return { success: true };
    } catch (e) {
        console.error("Failed to send welcome message", e);
        return { success: false, error: "Database error" };
    }
}

const IntroductionSchema = z.string().max(5000, "La présentation est trop longue (max 5000 caractères)");

export async function saveMemberIntroduction(guildId: string, introduction: string, targetUserId?: string) {
    const session = await auth();
    if (!session?.user) return { success: false, error: "Non autorisé" };

    try {
        // Validation & Sanitization
        const validation = IntroductionSchema.safeParse(introduction);
        if (!validation.success) {
            return { success: false, error: validation.error.errors[0].message };
        }

        // Simple HTML stripping to ensure double-layer security (client-side React already escapes)
        const sanitized = introduction.replace(/<[^>]*>?/gm, '').trim();

        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guild) return { success: false, error: "Guilde introuvable" };

        // --- SECURITY: RBAC / OWNERSHIP CHECK ---
        const user = await getUserContext(guildId);
        if (!user.isAuthenticated) return { success: false, error: "Unauthorized" };

        const effectiveUserId = (user.isSuperAdmin && targetUserId) ? targetUserId : session.user.id;
        const isOwner = effectiveUserId === session.user.id;
        const isGod = user.isSuperAdmin;

        if (!isOwner && !isGod) {
            return { success: false, error: "Vous n'avez pas la permission de modifier cette présentation." };
        }

        await db.userProfile.update({
            where: {
                userId_guildId: {
                    userId: effectiveUserId as string,
                    guildId: guild.id
                }
            },
            data: { introduction: sanitized }
        });

        revalidatePath(`/dashboard/${guildId}/profile`);
        return { success: true };
    } catch (e) {
        console.error("Failed to save introduction", e);
        return { success: false, error: "Erreur lors de la sauvegarde" };
    }
}

export async function getWelcomePosts(guildId: string) {
    try {
        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guild) return { posts: [], reactorNames: {} };

        const posts = await db.memberWelcome.findMany({
            where: { guildId: guild.id },
            include: {
                profile: {
                    include: { user: true }
                }
            },
            orderBy: { createdAt: "desc" },
            take: 50
        });

        // Collect names of all reactors for tooltips
        const allReactorIds = new Set<string>();
        posts.forEach(post => {
            const reactions = (post.reactions as Record<string, string[]>) || {};
            Object.values(reactions).flat().forEach(id => {
                if (id) allReactorIds.add(id);
            });
        });

        const reactorProfiles = await db.userProfile.findMany({
            where: { id: { in: Array.from(allReactorIds) } },
            select: { 
                id: true, 
                pseudoDofus: true, 
                discordNickname: true,
                user: { select: { name: true } } 
            }
        });

        const reactorNames: Record<string, string> = {};
        reactorProfiles.forEach(p => {
            reactorNames[p.id] = p.pseudoDofus || p.discordNickname || p.user.name || "Inconnu";
        });

        return {
            posts: JSON.parse(JSON.stringify(posts, (_, v) => typeof v === "bigint" ? v.toString() : v)),

            reactorNames
        };
    } catch (e) {
        console.error("Failed to get welcome posts", e);
        return { posts: [], reactorNames: {} };
    }
}

export async function toggleWelcomeReaction(welcomeId: string, emoji: string) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    // Input validation
    if (!welcomeId || typeof emoji !== "string" || emoji.length > 10) {
        return { success: false, error: "Paramètres invalides" };
    }

    try {
        const welcome = await db.memberWelcome.findUnique({
            where: { id: welcomeId },
            include: { guild: true }
        });
        if (!welcome) return { success: false, error: "Post non trouvé" };

        // FIX: Use direct DB lookup instead of getUserContext (avoids Discord API calls on every emoji click
        // which caused race conditions / "Non membre" errors under spam)
        const profile = await db.userProfile.findUnique({
            where: {
                userId_guildId: {
                    userId: session.user.id,
                    guildId: welcome.guild.id
                }
            },
            select: { id: true, status: true }
        });

        if (!profile || profile.status !== "ACTIVE") {
            return { success: false, error: "Non membre" };
        }

        const profileId = profile.id;
        const reactions = (welcome.reactions as Record<string, string[]>) ?? {};

        if (!reactions[emoji]) {
            reactions[emoji] = [profileId];
        } else {
            const index = reactions[emoji].indexOf(profileId);
            if (index > -1) {
                reactions[emoji].splice(index, 1);
                if (reactions[emoji].length === 0) delete reactions[emoji];
            } else {
                reactions[emoji].push(profileId);
            }
        }

        await db.memberWelcome.update({
            where: { id: welcomeId },
            data: { reactions }
        });

        revalidatePath(`/dashboard/${welcome.guild.discordGuildId}`);
        revalidatePath(`/dashboard/${welcome.guild.discordGuildId}/welcome`);
        return { success: true };
    } catch (e) {
        console.error("[toggleWelcomeReaction] Failed", e);
        return { success: false, error: "Erreur serveur, réessaie dans un instant." };
    }
}

"use server";
// Force reload after schema update


import { db } from "@/lib/prisma";
import { getUserContext } from "./user-actions";
import { auth } from "@/auth";
import { isSuperAdmin } from "./super-admin-actions";
import { revalidatePath } from "next/cache";

/**
 * Récupère tous les guides disponibles.
 */
export async function getOptimizedGuides(guildId?: string) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Non authentifié");

  const isGod = await isSuperAdmin();
  let isAdmin = isGod;

  if (!isGod && guildId) {
    const ctx = await getUserContext(guildId);
    isAdmin = ctx.isAdmin;
  }

  // Si admin, on fetch tout. Sinon, seulement les actifs
  const whereCl = isAdmin ? {} : { isActive: true };

  const guides = await db.optimizedGuide.findMany({
    where: whereCl,
    include: {
      steps: {
        orderBy: { order: "asc" },
      },
    },
    orderBy: { createdAt: "asc" },
  });

  return { success: true, guides };
}

/**
 * Récupère un guide spécifique avec les détails de toutes les quêtes référencées.
 */
export async function getOptimizedGuideDetail(slug: string, guildId: string) {
  const ctx = await getUserContext(guildId);
  if (!ctx.isAuthenticated) throw new Error("Non autorisé");

  const guide = await db.optimizedGuide.findUnique({
    where: { slug },
    include: {
      steps: {
        orderBy: { order: "asc" },
      },
    },
  });

  if (!guide) return { success: false, error: "Guide introuvable" };

  // Collect all DofusQuestEntry IDs from all steps (looking at both questIds legacy and objectives)
  const allQuestIds = guide.steps.flatMap((step: any) => {
    const qids = step.questIds || [];
    const objQids = (step.objectives as any[])?.filter(o => o.type === 'QUEST').map(o => o.id) || [];
    return [...new Set([...qids, ...objQids])];
  });
  
  // Fetch detailed quests with their respective Dofus chain information
  const questsDetail = await db.dofusQuestEntry.findMany({
    where: { id: { in: allQuestIds } },
    include: {
      chain: {
        include: {
          dofus: true,
        },
      },
      playerProgress: {
        where: {
          profileId: ctx.id,
          characterName: "PRINCIPAL",
        },
      },
    },
  });

  return { success: true, guide, questsDetail };
}

/**
 * (Admin) Créer ou mettre à jour un guide.
 */
export async function upsertOptimizedGuide(
  guildId: string | undefined,
  data: {
    id?: string;
    slug: string;
    name: string;
    description?: string;
    imageUrl?: string;
    isActive: boolean;
    steps: {
      id?: string;
      order: number;
      title: string;
      description?: string;
      questIds: string[];
      objectives?: any[];
      customTasks?: any;
    }[];
  }
) {
  const isGod = await isSuperAdmin();
  if (!isGod) {
    if (!guildId) throw new Error("Guild ID requis");
    const ctx = await getUserContext(guildId);
    if (!ctx.isAdmin) throw new Error("Droits administrateur requis");
  }

  const { id, steps, ...guideData } = data;

  if (id) {
    // Update
    const guide = await db.optimizedGuide.update({
      where: { id },
      data: guideData,
    });

    // Delete existing steps completely (it's simpler to rebuild)
    await db.optimizedGuideStep.deleteMany({
      where: { guideId: id },
    });

    // Create steps
    if (steps && steps.length > 0) {
      await db.optimizedGuideStep.createMany({
        data: steps.map((s) => ({
          ...s,
          id: undefined, 
          guideId: id,
          // Migration logic: if objectives is missing but questIds exists, convert it
          objectives: s.objectives || (s.questIds ? s.questIds.map(qid => ({ type: 'QUEST', id: qid })) : []),
          customTasks: s.customTasks || []
        })),
      });
    }

    revalidatePath(`/god/dofus-guides`);
    if (guildId) revalidatePath(`/dashboard/${guildId}/quetes-dofus/routes/${guideData.slug}`);
    return { success: true, guide };
  } else {
    // Create
    const guide = await db.optimizedGuide.create({
      data: {
        ...guideData,
        steps: {
          create: steps.map((s) => ({ 
            ...s, 
            id: undefined,
            objectives: s.objectives || (s.questIds ? s.questIds.map(qid => ({ type: 'QUEST', id: qid })) : []),
            customTasks: s.customTasks || []
          })),
        },
      },
    });

    revalidatePath(`/god/dofus-guides`);
    return { success: true, guide };
  }
}

/**
 * (Admin) Supprimer un guide.
 */
export async function deleteOptimizedGuide(guildId: string | undefined, guideId: string) {
  const isGod = await isSuperAdmin();
  if (!isGod) {
      if (!guildId) throw new Error("Guild ID requis");
      const ctx = await getUserContext(guildId);
      if (!ctx.isAdmin) throw new Error("Droits administrateur requis");
  }

  await db.optimizedGuide.delete({
    where: { id: guideId },
  });

  revalidatePath(`/god/dofus-guides`);
  return { success: true };
}

/**
 * Calcule à quelle étape de la route se trouve chaque membre de la guilde.
 */
export async function getGuildOptimizedGuideProgress(slug: string, guildId: string) {
  const ctx = await getUserContext(guildId);
  if (!ctx.isAuthenticated) throw new Error("Non autorisé");

  const guide = await db.optimizedGuide.findUnique({
    where: { slug },
    include: {
      steps: { orderBy: { order: "asc" } },
    },
  });

  if (!guide) return { success: false, error: "Guide introuvable" };

  const allQuestIds = guide.steps.flatMap((step: any) => {
    const qids = step.questIds || [];
    const objQids = (step.objectives as any[])?.filter(o => o.type === 'QUEST').map(o => o.id) || [];
    return [...new Set([...qids, ...objQids])];
  });
  if (allQuestIds.length === 0) return { success: true, memberProgress: [] };

  // Récupérer toutes les quêtes complétées pour ce guide
  const allCompletedQuests = await db.playerDofusQuestProgress.findMany({
    where: {
      guildId,
      questId: { in: allQuestIds },
      characterName: "PRINCIPAL",
      status: "COMPLETED",
    },
    include: {
      profile: {
        include: { user: true },
      },
    },
  });

  // Grouper par profile
  const progressByProfile = new Map<string, { profile: any; completedIds: Set<string> }>();
  for (const progress of allCompletedQuests) {
    if (!progressByProfile.has(progress.profileId)) {
      progressByProfile.set(progress.profileId, {
        profile: progress.profile,
        completedIds: new Set(),
      });
    }
    progressByProfile.get(progress.profileId)!.completedIds.add(progress.questId);
  }

  // Déterminer l'étape pour chaque profile
  const memberProgress: {
    profile: any;
    currentStepIndex: number; // 0 = Etape 1, -1 = Fini
    isFinished: boolean;
  }[] = [];

  for (const [_, data] of progressByProfile.entries()) {
    let currentStepIndex = 0;
    let isFinished = false;

    // Itérer sur les étapes dans l'ordre pour trouver la première non complétée à 100%
    for (const [idx, step] of guide.steps.entries()) {
      const stepQuestIds = [
        ...(step.questIds || []),
        ...((step.objectives as any[])?.filter(o => o.type === 'QUEST').map(o => o.id) || [])
      ];
      const uniqueStepQuests = [...new Set(stepQuestIds)];
      if (uniqueStepQuests.length === 0) continue;

      const hasMissingQuest = uniqueStepQuests.some((qid) => !data.completedIds.has(qid));
      if (hasMissingQuest) {
        currentStepIndex = idx;
        break;
      }

      // Si on arrive à la dernière étape et pas de missing quests, c'est fini
      if (idx === guide.steps.length - 1 && !hasMissingQuest) {
        currentStepIndex = idx;
        isFinished = true;
      }
    }

    memberProgress.push({
      profile: data.profile,
      currentStepIndex,
      isFinished,
    });
  }

  return { success: true, memberProgress };
}

﻿"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { logger } from "@/lib/logger";
import { PERMISSIONS } from "@/lib/permissions";
import { getAppBaseUrl } from "@/lib/utils";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { checkGuildPermission, getUserContext } from "@/server/actions/user-actions";
// Local types to avoid Prisma export issues
type PollCategory = "SUGGESTION" | "AMELIORATION" | "EVENT" | "MISSION" | "AUTRE";
type PollStatus = "DRAFT" | "ACTIVE" | "CLOSED" | "CANCELLED";
import { sendChannelMessage, deleteChannelMessage, validateChannelBelongsToGuild } from "@/server/discord";
import { createAuditLog } from "@/server/actions/audit-actions";
import { sanitizeHtml, sanitizeName } from "@/lib/security";

/**
 * Generates a visual progress bar for Discord embeds.
 */
function getProgressBar(percentage: number, length = 12): string {
    const filledLength = Math.max(0, Math.min(length, Math.round((percentage / 100) * length)));
    const emptyLength = length - filledLength;
    // Using standard Discord emojis for better compatibility
    const filled = "🟩".repeat(filledLength);
    const empty = "⬜".repeat(emptyLength);
    return filled + empty;
}

// --- Types ---

export type ActionResponse<T = unknown> = {
    success: boolean;
    error?: string;
    data?: T;
};

// --- Settings Actions ---

export async function getPollSettings(guildId: string): Promise<ActionResponse<{
    pollsNotifyChannelId: string | null;
    pollsNotifyRoleId: string | null;
}>> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    const { requireGuildAdmin } = await import("./guards");
    const guard = await requireGuildAdmin(guildId, "Lecture des paramètres de Sondage");
    if (!guard.isAuthorized) return { success: false, error: guard.error };

    try {
        const config = await (db.guildConfig as any).findUnique({
            where: { discordGuildId: guildId },
            select: { pollsNotifyChannelId: true, pollsNotifyRoleId: true }
        });

        if (!config) return { success: false, error: "Guilde introuvable" };

        return {
            success: true,
            data: {
                pollsNotifyChannelId: config.pollsNotifyChannelId,
                pollsNotifyRoleId: config.pollsNotifyRoleId
            }
        };
    } catch (error) {
        console.error("Get Poll Settings Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

export async function updatePollSettings(
    guildId: string,
    data: { pollsNotifyChannelId: string | null; pollsNotifyRoleId: string | null }
): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    const { requireGuildAdmin } = await import("./guards");
    const guard = await requireGuildAdmin(guildId, "Mise à jour des paramètres de Sondage");
    if (!guard.isAuthorized) return { success: false, error: guard.error };

    try {
        // SECURITY: Validate channel (if provided)
        if (data.pollsNotifyChannelId) {
            const { validateChannelBelongsToGuild } = await import("@/server/discord");
            const isValidChannel = await validateChannelBelongsToGuild(data.pollsNotifyChannelId, guildId);
            if (!isValidChannel) {
                return { success: false, error: "Ce salon n'appartient pas à votre serveur Discord" };
            }
        }

        await (db as any).guildConfig.update({
            where: { discordGuildId: guildId },
            data: {
                pollsNotifyChannelId: data.pollsNotifyChannelId,
                pollsNotifyRoleId: data.pollsNotifyRoleId
            }
        });

        revalidatePath(`/dashboard/${guildId}/admin/settings`);
        return { success: true };
    } catch (error) {
        console.error("Update Poll Settings Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

// --- Zod Schemas ---

const CreatePollSchema = z.object({
    guildId: z.string().min(1),
    title: z.string().min(3).max(200),
    description: z.string().max(2000).optional(),
    category: z.enum(["SUGGESTION", "AMELIORATION", "EVENT", "MISSION", "AUTRE"]),
    options: z.array(z.object({
        label: z.string().min(1).max(200),
        emoji: z.string().max(10).optional(),
    })).min(2).max(10), // Limited to 10 options for better UX
    allowMultipleVotes: z.boolean().default(false),
    isAnonymous: z.boolean().default(false),
    expiresAt: z.string().datetime().optional().nullable(),
    // Discord publish config
    publishToDiscord: z.boolean().default(false),
    discordChannelId: z.string().optional(),
    mentionEveryone: z.boolean().default(false),
    mentionRoleId: z.string().optional(),
}).strict();

const UpdatePollSchema = z.object({
    pollId: z.string().min(1),
    guildId: z.string().min(1),
    title: z.string().min(3).max(200).optional(),
    description: z.string().max(2000).optional().nullable(),
    category: z.enum(["SUGGESTION", "AMELIORATION", "EVENT", "MISSION", "AUTRE"]).optional(),
    allowMultipleVotes: z.boolean().optional(),
    isAnonymous: z.boolean().optional(),
    expiresAt: z.string().datetime().optional().nullable(),
}).strict();

