    });

    revalidatePath(`/dashboard/${ctx.guildId}/songes`);
    return { success: true };
}

// ============================================
// NOTIFY MEMBERS ACTION
// ============================================

export async function triggerRunNotification(guildId: string, runId: string, message: string, scheduledAt?: Date) {
    const ctx = await getGuildUserContext(guildId);
    if (!ctx) return { success: false, error: "Non authentifié ou non autorisé" };

    const run = await db.dreamRun.findFirst({
        where: { id: runId, guildId: ctx.guildId },
        include: { members: true }
    });

    if (!run) return { success: false, error: "Run non trouvée" };
    if (run.leaderId !== ctx.userId) return { success: false, error: "Seul le leader peut notifier les membres" };

    // Spam Protection: 15 minutes cooldown
    const COOLDOWN_MS = 15 * 60 * 1000;
    if (run.lastReminderAt && (Date.now() - run.lastReminderAt.getTime() < COOLDOWN_MS)) {
        const remainingMinutes = Math.ceil((COOLDOWN_MS - (Date.now() - run.lastReminderAt.getTime())) / 60000);
        return { success: false, error: `Anti-spam : Veuillez attendre ${remainingMinutes} minute(s) avant le prochain rappel.` };
    }

    // Dashboard notifications for each member
    const notificationPromises = run.members.map(member =>
        createNotification(
            member.userId,
            "SYSTEM_INFO",
            "Rappel Songes",
            scheduledAt
                ? `RDV à ${scheduledAt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} • ${message}`
                : `Message du leader : ${message}`,
            `/dashboard/${ctx.guildId}/songes/${runId}`,
            guildId
        )
    );

    await Promise.all(notificationPromises);

    // Update last reminder timestamp
    await db.dreamRun.update({
        where: { id: runId },
        data: { lastReminderAt: new Date() }
    });

    // Discord Ping
    const { notifyRunMembers } = await import("@/server/songes-service");

    // Format message for Discord with timestamp if provided
    let discordMessage = message;
    if (scheduledAt) {
        const unixTimestamp = Math.floor(scheduledAt.getTime() / 1000);
        discordMessage = `🕒 **Rendez-vous prévu :** <t:${unixTimestamp}:F> (<t:${unixTimestamp}:R>)\n\n${message}`;
    }

    const result = await notifyRunMembers(ctx.guildId, runId, discordMessage);

    // Track leader reminders for later cleanup
    if (result.success && result.messageId && run.discordChannelId) {
        await db.dreamRunReminder.create({
            data: {
                runId: runId,
                discordMessageId: result.messageId,
                discordChannelId: run.discordChannelId
            }
        });
    }

    return result;
}

// ============================================
// CONTRIBUTION POINTS — CLOSE RUN WITH DISTRIBUTION
// ============================================

/**
 * Returns contribution points based on Songes difficulty.
 * - Rêve I/II/III      → 1 pt
 * - Paradoxe I/II/III/IV → 2 pts
 * - Cauchemar I/II/III → 3 pts
 * Épreuves are excluded (handled separately by caller).
 */
function getSongesContributionPoints(difficulty: string): number {
    if (difficulty.startsWith("CAUCHEMAR")) return 3;
    if (difficulty.startsWith("PARADOXE")) return 2;
    return 1; // REVE_*
}

/**
 * Lightweight guild member list for the Songes close modal.
 * Returns id (profileId), name, and avatar of active guild members.
 */
export async function getSongesGuildMembersForClose(
    guildId: string
): Promise<{ success: boolean; data?: { id: string; userId: string; name: string; image: string | null }[]; error?: string }> {
    const ctx = await getGuildUserContext(guildId);
    if (!ctx) return { success: false, error: "Non authentifié ou non autorisé" };

    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true },
    });
    if (!guildConfig) return { success: false, error: "Guilde introuvable" };

    const profiles = await db.userProfile.findMany({
        where: { guildId: guildConfig.id, status: "ACTIVE" },
        select: {
            id: true,
            userId: true,
            discordNickname: true,
            pseudoDofus: true,
            user: { select: { name: true, image: true } },
        },
        orderBy: { pseudoDofus: "asc" },
    });

    return {
        success: true,
        data: profiles.map((p) => ({
            id: p.id,           // profileId (used for contribution points)
            userId: p.userId,   // internal userId (used to match run members)
            name: p.discordNickname || p.pseudoDofus || p.user.name || "Membre",
            image: p.user.image,
        })),
    };
}

/**
 * Close a Songes run and award contribution points to validated participants.
 * - Only available for non-épreuve runs (caller must check epreuveCode === null)
 * - Leader (creator) does NOT receive points
 * - Members are identified by their internal profile ID
 * @param validatedProfileIds - profileIds of participants to reward
 */
export async function closeRunWithContributions(
    guildId: string,
    runId: string,
    validatedProfileIds: string[]
): Promise<{ success: boolean; data?: { pointsAwarded: number }; error?: string }> {
    const ctx = await getGuildUserContext(guildId);
    if (!ctx) return { success: false, error: "Non authentifié ou non autorisé" };

    // Load run with guildId isolation
    const run = await db.dreamRun.findFirst({
        where: { id: runId, guildId: ctx.guildId },
        include: { members: true },
    });

    if (!run) return { success: false, error: "Run non trouvée" };

    // Only leader can close with contribution distribution
    if (run.leaderId !== ctx.userId) {
        return { success: false, error: "Seul le leader peut valider la clôture avec distribution" };
    }

    // Security: skip point distribution for épreuves
    if (run.epreuveCode) {
        return { success: false, error: "Les runs épreuve ne distribuent pas de points de contribution" };
    }

    const pts = getSongesContributionPoints(run.difficulty);

    // Get internal guildConfig to resolve profile IDs
    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true },
    });
    if (!guildConfig) return { success: false, error: "Guilde introuvable" };

    // Determine the leader's profile ID to exclude them from rewards
    const leaderProfile = await db.userProfile.findFirst({
        where: { userId: run.leaderId, guildId: guildConfig.id },
        select: { id: true },
    });
    const leaderProfileId = leaderProfile?.id ?? null;

    // Filter out the leader from point distribution
    const toReward = validatedProfileIds.filter(
        (pid) => pid !== leaderProfileId
    );

    // Delete the run (Ménage Time)
    await db.dreamRun.delete({
        where: { id: runId },
    });

    // Award contribution points
    if (toReward.length > 0) {
        await db.userProfile.updateMany({
            where: {
                id: { in: toReward },
                guildId: guildConfig.id, // guild isolation
            },
            data: { contributionPoints: { increment: pts } },
        });
    }

    // Remove Discord embed (fire-and-forget)
    try {
        const { deleteDiscordRunEmbed } = await import("@/server/songes-service");
        await deleteDiscordRunEmbed(ctx.guildId, runId);
    } catch (_) {
        // Non-fatal
    }

    // Audit log
    try {
        await db.auditLog.create({
            data: {
                guildId: guildConfig.id,
                actorUserId: ctx.userId,
                actorName: ctx.name || "Leader",
                action: "SONGES_RUN_CLOSED_WITH_CONTRIBUTIONS",
                targetType: "DREAM_RUN",
                targetId: runId,
                metadata: {
                    difficulty: run.difficulty,
                    pointsAwarded: pts,
                    rewardedCount: toReward.length,
                } as any,
            },
        });
    } catch (_) {
        // Non-fatal audit log failure
    }

    revalidatePath(`/dashboard/${ctx.guildId}/songes`);
    return { success: true, data: { pointsAwarded: pts } };
}

/**
 * Fetch past dream runs for a specific member
 */
export async function getMemberDreamRuns(guildId: string, userId?: string) {
    const ctx = await getGuildUserContext(guildId);
    if (!ctx) return { success: false, error: "Non authentifié ou non autorisé" };

    const targetUserId = userId || ctx.userId;

    const runs = await db.dreamRun.findMany({
        where: {
            guildId: ctx.guildId,
            members: {
                some: { userId: targetUserId }
            },
            status: { in: ["COMPLETED", "FAILED", "ABANDONED"] }
        },
        include: {
            members: {
                orderBy: { slot: "asc" },
                include: {
                    user: {
                        select: {
                            id: true,
                            name: true,
                            image: true,
                            profiles: {
                                where: { guildId: ctx.guildId },
                                select: { pseudoDofus: true, classe: true }
                            }
                        }
                    }
                }
            },
            _count: {
                select: { floors: true }
            }
        },
        orderBy: { completedAt: "desc" },
        take: 20
    });

    return { success: true, runs };
}

"use server";

import { db } from "@/lib/prisma";
import { redis } from "@/lib/redis";
import { sendChannelMessage, updateChannelMessage } from "@/server/discord";
import { isSuperAdmin } from "./super-admin-actions";

const REDIS_STATUS_MSG_KEY = process.env.NODE_ENV === "production" ? "sigilos:discord_status_message_id_prod" : "sigilos:discord_status_message_id_beta";

/**
 * 🛰️ Envoie un ping d'état des services sur Discord
 * Version "Premium" avec Living Status (mis à jour du même message si possible).
 */
export async function sendGlobalStatusPing(
    isTestRequest = false, 
    mode?: 'living' | 'notification', 
    isLite?: boolean,
    targetChannelId?: string
) {
    if (isTestRequest) {
        const isAdmin = await isSuperAdmin();
        if (!isAdmin) throw new Error("Accès refusé : Super-admin requis");
    }

    try {
        const config = await db.platformConfig.findUnique({ 
            where: { id: "singleton" },
            select: { 
                serviceStatusChannelId: true,
                statusIsLite: true,
                statusMode: true,
                statusMention: true
            }
        });

        const channelId = targetChannelId || config?.serviceStatusChannelId;

        if (!channelId) {
            return { success: false, error: "Salon d'état des services non configuré." };
        }

        const effectiveMode = mode || (config?.statusMode as 'living' | 'notification') || 'living';
        const effectiveLite = isLite !== undefined ? isLite : (config?.statusIsLite || false);

        // 1. Health Checks
        const startDb = performance.now();
        await db.$queryRaw`SELECT 1`;
        const dbLatency = Math.round(performance.now() - startDb);
        const isDbOk = dbLatency < 500;

        let isRedisOk = false;
        let redisLatency = 0;
        try {
            const startRedis = performance.now();
            const pong = await redis.ping();
            redisLatency = Math.round(performance.now() - startRedis);
            isRedisOk = pong === "PONG";
        } catch (e) {
            console.error("[Status Ping] Redis error:", e);
        }

        // 2. Dynamic Info
        const isBeta = process.env.NEXT_PUBLIC_APP_URL?.includes("beta") || process.env.NODE_ENV !== "production";
        const envName = isBeta ? "Beta / Test" : "Production";
        
        // Calculate Uptime
        const uptimeSeconds = process.uptime();
        const uptimeDays = Math.floor(uptimeSeconds / (24 * 3600));
        const uptimeHours = Math.floor((uptimeSeconds % (24 * 3600)) / 3600);
        const uptimeFormatted = uptimeDays > 0 ? `${uptimeDays}j ${uptimeHours}h` : `${uptimeHours}h ${Math.floor((uptimeSeconds % 3600) / 60)}m`;

        const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr";
        const statusUrl = `${appUrl}/status`;
        
        // Final Health Calc
        const systemStatus = isDbOk && isRedisOk ? "OPERATIONAL" : (!isDbOk && !isRedisOk ? "CRITICAL" : "DEGRADED");
        const statusColor = systemStatus === "OPERATIONAL" ? 0x10b981 : (systemStatus === "DEGRADED" ? 0xf59e0b : 0xef4444);

        // 3. Build the Embed (Standard Pro)
        const fields = effectiveLite ? [
            {
                name: "Système",
                value: systemStatus === "OPERATIONAL" ? "✅ Opérationnel" : "⚠️ Perturbé",
                inline: true
            },
            {
                name: "Environnement",
                value: `\`${envName}\``,
                inline: true
            }
        ] : [
            {
                name: "📡 État des Services",
                value: systemStatus === "OPERATIONAL" ? "✅ Tous les systèmes sont opérationnels." : "⚠️ Certains services rencontrent des difficultés.",
                inline: false
            },
            {
                name: "🌍 Environnement",
                value: `\`${envName}\``,
                inline: true
            },
            {
                name: "📦 Version",
                value: `\`v${process.env.npm_package_version || "0.1.0"}\``,
                inline: true
            }
        ];

        const embed = {
            embedTitle: `🛰️ SigilOS — État des Systèmes`,
            embedUrl: statusUrl,
            embedDescription: !effectiveLite && systemStatus !== "OPERATIONAL" 
                ? "Nos équipes (enfin, le robot de maintenance) analysent actuellement l'incident."
                : undefined,
            embedColor: statusColor,
            embedThumbnail: effectiveLite ? undefined : "https://sigilos.fr/assets/ui/logo-v2.png",
            fields,
            embedFooter: `SigilOS Status • Mise à jour auto`,
        };

        // 3. Dispatch Logic
        const previousMessageId = await redis.get(REDIS_STATUS_MSG_KEY);
        let actionTaken = "created";
        let finalMessageId: string | null = null;

        // Mode 'living': try to update the old message
        if (effectiveMode === 'living' && previousMessageId) {
            try {
                const updated = await updateChannelMessage(channelId, previousMessageId, "", embed);
                if (updated) {
                    finalMessageId = previousMessageId;
                    actionTaken = "updated";
                }
            } catch (e) {
                console.warn("[Status Ping] Update failed, sending new message", e);
            }
        }

        // Mode 'notification' OR update failed: send a new message
        if (!finalMessageId) {
            const mentionContent = config?.statusMention === 'none' ? "" : (config?.statusMention || "");
            finalMessageId = await sendChannelMessage(channelId, mentionContent, embed);
            if (finalMessageId && effectiveMode === 'living') {
                // Only save specifically for living status
                await redis.set(REDIS_STATUS_MSG_KEY, finalMessageId, "EX", 60 * 60 * 24 * 30);
            }
        }

        return { 
            success: true, 
            action: actionTaken,
            messageId: finalMessageId,
            stats: { 
                systemStatus, 
                dbLatency, 
                redisLatency,
                channelId
            }
        };

    } catch (error: any) {
        console.error("[Status Action] Critical Failure:", error);
        return { success: false, error: error.message || "Erreur de connexion Discord (vérifiez l'ID du salon)" };
    }
}

"use server";

import { logger } from "@/lib/logger";

import { isSuperAdmin } from "./super-admin-actions";
import { db } from "@/lib/prisma";
import { PrismaClient } from "@prisma/client";
import { readdir, stat, unlink } from "fs/promises";
import { join, normalize } from "path";
import { existsSync } from "fs";

const kamaDb = db as unknown as PrismaClient;

export type PendingFile = {
    filename: string;
    url: string;
    sizeBytes: number;
    createdAt: Date;
    expiresAt: Date;
    submissionId: string;
    type: "MISSION" | "KAMA" | "ACHIEVEMENT";
    memberName: string;
};

export type GuildAsset = {
    type: "ICON" | "BANNER" | "PHOTO";
    url: string;
    label: string;
    isLocal: boolean;
    dbField?: AssetDbField; // used to clear the DB field after VPS deletion
};

export interface DiskFile {
    filename: string;
    url: string;
    sizeBytes: number;
    modifiedAt: Date;
    isPending?: boolean;
    expiresAt?: Date | string;
}

export type StorageGuildEntry = {
    guildId: string;
    discordGuildId: string;
    name: string;
    // disk stats
    missionsDir: string;
    missionsCount: number;
    missionsBytes: number;
    missionsFiles: DiskFile[];
    kamaDir: string;
    kamaCount: number;
    kamaBytes: number;
    kamaFiles: DiskFile[];
    achievementDir: string;
    achievementCount: number;
    achievementBytes: number;
    achievementFiles: DiskFile[];
    // preuves prêts & coffre
    loansProofsDir: string;
    loansProofsCount: number;
    loansProofsBytes: number;
    loansProofsFiles: DiskFile[];
    presentationDir: string;
    presentationCount: number;
    presentationBytes: number;
    presentationFiles: DiskFile[];
    activeLoanProofs: number; // nb de prêts/coffre actifs avec proofUrl en DB
    // pending
    pendingMissions: number;
    pendingKamas: number;
    pendingFiles: PendingFile[];
    // guild assets
    assets: GuildAsset[];
};

export type StorageOverview = {
    guilds: StorageGuildEntry[];
    totalBytes: number;
    totalFiles: number;
    orphanFiles: DiskFile[];
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

async function dirList(dirPath: string, urlBase: string): Promise<{ count: number; bytes: number; files: DiskFile[] }> {
    if (!existsSync(dirPath)) return { count: 0, bytes: 0, files: [] };
    try {
        const entries = await readdir(dirPath, { withFileTypes: true });
        const files: DiskFile[] = [];
        let bytes = 0;
        for (const f of entries) {
            if (!f.isFile()) continue;
            const s = await stat(join(dirPath, f.name));
            bytes += s.size;
            files.push({
                filename: f.name,
                url: `${urlBase}/${f.name}`,
                sizeBytes: s.size,
                modifiedAt: s.mtime,
            });
        }
        // Sort newest first
        files.sort((a, b) => b.modifiedAt.getTime() - a.modifiedAt.getTime());
        return { count: files.length, bytes, files };
    } catch (err) { 
        logger.error(`[StorageScan] Error readdir ${dirPath}`, { error: String(err) });
        return { count: 0, bytes: 0, files: [] }; 
    }
}

async function getPendingFilesForGuild(
    guildId: string,
    discordGuildId: string,
    cwd: string
): Promise<PendingFile[]> {
    const EXPIRY_MS = 24 * 60 * 60 * 1000;
    const pendingFiles: PendingFile[] = [];

    try {
        const missionSubs = await db.submission.findMany({
            where: { mission: { guildId }, status: "PENDING", proofUrl: { not: "" } },
            select: {
                id: true, proofUrl: true, createdAt: true,
                profile: { select: { discordNickname: true, pseudoDofus: true } },
            },
            orderBy: { createdAt: "asc" },
        });
        for (const sub of missionSubs) {
            if (!sub.proofUrl) continue;
            try {
                // Determine physical path from URL - Missions/Achiev are in /public/uploads/proofs/
                const fileName = sub.proofUrl.split("/").pop();
                const physicalPath = join(cwd, "public", "uploads", "proofs", discordGuildId, fileName || "");
                const s = await stat(physicalPath);
                pendingFiles.push({
                    filename: fileName || sub.id,
                    url: sub.proofUrl, sizeBytes: s.size,
                    createdAt: sub.createdAt,
                    expiresAt: new Date(sub.createdAt.getTime() + EXPIRY_MS),
                    submissionId: sub.id, type: "MISSION",
                    memberName: sub.profile?.discordNickname || sub.profile?.pseudoDofus || "Membre",
                });
            } catch (err) { }
        }
    } catch { }

    try {
        const kamaSubs = await (kamaDb as any).kamaDonation.findMany({
            where: { guildId, status: "PENDING", proofUrl: { not: "" } },
            select: {
                id: true, proofUrl: true, createdAt: true,
                profile: { select: { discordNickname: true, pseudoDofus: true } },
            },
            orderBy: { createdAt: "asc" },
        });
        for (const donation of kamaSubs) {
            if (!donation.proofUrl) continue;
            try {
                // Kamas are in /private_uploads/guilds/{id}/proofs/
                const fileName = donation.proofUrl.split("/").pop();
                const physicalPath = join(cwd, "private_uploads", "guilds", guildId, "proofs", fileName || "");
                const s = await stat(physicalPath);
                pendingFiles.push({
                    filename: fileName || donation.id,
                    url: donation.proofUrl, sizeBytes: s.size,
                    createdAt: donation.createdAt,
                    expiresAt: new Date(donation.createdAt.getTime() + EXPIRY_MS),
                    submissionId: donation.id, type: "KAMA",
                    memberName: donation.profile?.discordNickname || donation.profile?.pseudoDofus || "Membre",
                });
            } catch (err) { }
        }
    } catch { }

    try {
        const achSubs = await (db as any).achievementSubmission.findMany({
            where: { guildId, status: "PENDING", proofUrl: { not: "" } },
            select: {
                id: true, proofUrl: true, createdAt: true,
                profile: { select: { discordNickname: true, pseudoDofus: true } },
            },
            orderBy: { createdAt: "asc" },
        });
        for (const sub of achSubs) {
            if (!sub.proofUrl) continue;
            try {
                const physicalPath = sub.proofUrl.replace(/^\/uploads\//, "").replace(/^\/api\/storage\//, "");
                const s = await stat(join(cwd, "private_uploads", physicalPath));
                pendingFiles.push({
                    filename: sub.proofUrl.split(/[/\\]/).pop() || sub.id,
                    url: sub.proofUrl, sizeBytes: s.size,
                    createdAt: sub.createdAt,
                    expiresAt: new Date(sub.createdAt.getTime() + EXPIRY_MS),
                    submissionId: sub.id, type: "ACHIEVEMENT",
                    memberName: sub.profile?.discordNickname || sub.profile?.pseudoDofus || "Membre",
                });
            } catch { }
        }
    } catch { }

    return pendingFiles;
}

// ─── Main action ──────────────────────────────────────────────────────────────

export async function getStorageOverview(): Promise<{ success: boolean; data?: StorageOverview; error?: string }> {
    if (!(await isSuperAdmin())) return { success: false, error: "Super admin requis" };

    try {
        const guilds = await db.guildConfig.findMany({
            select: {
                id: true, discordGuildId: true, name: true,
                iconUrl: true,
                presentationBannerUrl: true,
                presentationBannerType: true,
                presentationPhotoUrl: true,
            } as any,
            orderBy: { name: "asc" },
        });

        const cwd = process.cwd();

        const entries: StorageGuildEntry[] = await Promise.all(
            guilds.map(async (g: any) => {
                const missionsDir = join(cwd, "private_uploads", "proofs", g.discordGuildId);
                const kamaDir = join(cwd, "private_uploads", "guilds", g.id, "proofs");
                const achievementDir = join(cwd, "private_uploads", "guilds", g.id, "achievements");
                const presentationDir = join(cwd, "private_uploads", "guilds", g.id); // Root of guild folder for presentation assets

                const missionsUrlBase = `/uploads/proofs/${g.discordGuildId}`;
                const kamaUrlBase = `/uploads/guilds/${g.id}/proofs`;
                const achievementUrlBase = `/uploads/guilds/${g.id}/achievements`;
                const presentationUrlBase = `/uploads/guilds/${g.id}`;

                const [missionsList, kamaList, achievementList, presentationList, pendingFiles] = await Promise.all([
                    dirList(missionsDir, missionsUrlBase),
                    dirList(kamaDir, kamaUrlBase),
                    dirList(achievementDir, achievementUrlBase),
                    dirList(presentationDir, presentationUrlBase),
                    getPendingFilesForGuild(g.id, g.discordGuildId, cwd),
                ]);

                // Enrich disk files with pending status and expiry info
                const enrich = (files: DiskFile[]) => {
                    return files.map(df => {
                        const pending = (pendingFiles || []).find(pf => pf.filename === df.filename);
                        if (pending) {
                            return { ...df, isPending: true, expiresAt: pending.expiresAt };
                        }
                        return df;
                    });
                };

                // Les fichiers du dossier /proofs/ sont partagés entre Kama Donations et Prêts/Coffre
                const activeLoanProofs = await Promise.all([
                    db.guildLoan.count({ where: { guildId: g.id, proofUrl: { not: null } } }),
                    db.vaultEntry.count({ where: { guildId: g.id, proofUrl: { not: null } } }),
                ]).then(([loans, vault]) => loans + vault);

                const [pendingMissions, pendingKamas] = await Promise.all([
                    db.submission.count({ where: { mission: { guildId: g.id }, status: "PENDING" } }),
                    (kamaDb as any).kamaDonation
                        ? (kamaDb as any).kamaDonation.count({ where: { guildId: g.id, status: "PENDING" } }).catch(() => 0)
                        : Promise.resolve(0),
                ]);

                // Collect guild assets (icon, banner, photo)
                const assets: GuildAsset[] = [];
                if (g.iconUrl) assets.push({
                    type: "ICON", url: g.iconUrl, label: "Icône",
                    isLocal: g.iconUrl.startsWith("/"),
                    dbField: "iconUrl",
                });
                if (g.presentationBannerUrl) assets.push({
                    type: "BANNER", url: g.presentationBannerUrl,
                    label: "Bannière de guilde",
                    isLocal: g.presentationBannerUrl.startsWith("/") || g.presentationBannerType === "local",
                    dbField: "presentationBannerUrl",
                });
                if (g.presentationPhotoUrl) assets.push({
                    type: "PHOTO", url: g.presentationPhotoUrl,
                    label: "Photo de guilde",
                    isLocal: g.presentationPhotoUrl.startsWith("/"),
                    dbField: "presentationPhotoUrl",
                });

                return {
                    guildId: g.id,
                    discordGuildId: g.discordGuildId,
                    name: g.name || g.discordGuildId,
                    missionsDir: `${missionsUrlBase}/`,
                    missionsCount: missionsList.count,
                    missionsBytes: missionsList.bytes,
                    missionsFiles: enrich(missionsList.files),
                    kamaDir: `${kamaUrlBase}/`,
                    kamaCount: kamaList.count,
                    kamaBytes: kamaList.bytes,
                    kamaFiles: enrich(kamaList.files),
                    achievementDir: `${achievementUrlBase}/`,
                    achievementCount: achievementList.count,
                    achievementBytes: achievementList.bytes,
                    achievementFiles: enrich(achievementList.files),
                    loansProofsDir: `${kamaUrlBase}/`, // share same dir as kama proofs
                    loansProofsCount: kamaList.count,
                    loansProofsBytes: kamaList.bytes,
                    loansProofsFiles: enrich(kamaList.files),
                    presentationDir: `${presentationUrlBase}/`,
                    presentationCount: presentationList.count,
                    presentationBytes: presentationList.bytes,
                    presentationFiles: enrich(presentationList.files),
                    activeLoanProofs,
                    pendingMissions,
                    pendingKamas,
                    pendingFiles,
                    assets,
                };
            })
        );


        // Calculate true orphan files
        // First get all valid DB references
        const dbProofsArray = await Promise.all([
            db.submission.findMany({ where: { proofUrl: { not: "" } }, select: { proofUrl: true } }),
            (db as any).achievementSubmission.findMany({ where: { proofUrl: { not: "" } }, select: { proofUrl: true } }),
            (kamaDb as any).kamaDonation ? (kamaDb as any).kamaDonation.findMany({ where: { proofUrl: { not: "" } }, select: { proofUrl: true } }).catch(() => []) : Promise.resolve([]),
            db.guildLoan.findMany({ where: { proofUrl: { not: null } }, select: { proofUrl: true } }),
            db.vaultEntry.findMany({ where: { proofUrl: { not: null } }, select: { proofUrl: true } })
        ]);

        const allValidUrls = new Set<string>();
        dbProofsArray.flat().forEach((entry: any) => {
            if (entry.proofUrl) {
                // Keep only the filename for easy cross-referencing to avoid path discrepancies
                const filename = entry.proofUrl.split(/[/\\]/).pop();
                if (filename) allValidUrls.add(filename);
            }
        });

        const totalBytes = entries.reduce((s, e) => s + e.missionsBytes + e.kamaBytes + e.achievementBytes, 0);
        const totalFiles = entries.reduce((s, e) => s + e.missionsCount + e.kamaCount + e.achievementCount, 0);
        
        const orphanFiles: DiskFile[] = [];
        const now = Date.now();
        const FOUR_HOURS_MS = 4 * 60 * 60 * 1000;

        entries.forEach(e => {
            const diskFiles = [...e.missionsFiles, ...e.kamaFiles, ...e.achievementFiles];
            diskFiles.forEach(df => {
                const isPending = e.pendingFiles.some(pf => pf.filename === df.filename);
                // ONLY count as orphans if no DB reference, not pending, AND older than 4 hours (safety margin)
                if (!allValidUrls.has(df.filename) && !isPending) {
                    if (now - df.modifiedAt.getTime() > FOUR_HOURS_MS) {
                        orphanFiles.push(df);
                    }
                }
            });
        });

        return { success: true, data: { guilds: entries, totalBytes, totalFiles, orphanFiles } };
    } catch (error) {
        logger.error("[getStorageOverview]", { error });
        return { success: false, error: "Erreur serveur" };
    }
}

// ─── Auto-Deletion / Garbage Collection ──────────────────────────────────────

/**
 * Triggers a global garbage collection of all uploaded files.
 * Scans the physical disk and safely removes any files older than 4 hours 
 * that have no corresponding record in the database.
 */
export async function cleanOrphanStorage(): Promise<{ success: boolean; deletedCount?: number; freedBytes?: number; error?: string }> {
    if (!(await isSuperAdmin())) return { success: false, error: "Super admin requis" };

    try {
        const overviewRes = await getStorageOverview();
        if (!overviewRes.success || !overviewRes.data) throw new Error("Could not fetch storage overview");

        const data = overviewRes.data;

        // Fetch valid DB references again to be 100% sure before deletion
        const dbProofsArray = await Promise.all([
            db.submission.findMany({ where: { proofUrl: { not: "" } }, select: { proofUrl: true } }),
            (db as any).achievementSubmission.findMany({ where: { proofUrl: { not: "" } }, select: { proofUrl: true } }),
            (kamaDb as any).kamaDonation ? (kamaDb as any).kamaDonation.findMany({ where: { proofUrl: { not: "" } }, select: { proofUrl: true } }).catch(() => []) : Promise.resolve([]),
            db.guildLoan.findMany({ where: { proofUrl: { not: null } }, select: { proofUrl: true } }),
            db.vaultEntry.findMany({ where: { proofUrl: { not: null } }, select: { proofUrl: true } })
        ]);

        const validFilenames = new Set<string>();
        dbProofsArray.flat().forEach((entry: any) => {
            if (entry.proofUrl) validFilenames.add(entry.proofUrl.split(/[/\\]/).pop());
        });

        let deletedCount = 0;
        let freedBytes = 0;
        const now = Date.now();
        const FOUR_HOURS_MS = 4 * 60 * 60 * 1000;

        for (const guild of data.guilds) {
            const allDiskFiles = [...guild.missionsFiles, ...guild.kamaFiles, ...guild.achievementFiles];
            const pendingFilenames = new Set(guild.pendingFiles.map(f => f.filename));

            for (const file of allDiskFiles) {
                // Ensure the file is not actively attached to a DB record and not pending
                if (!validFilenames.has(file.filename) && !pendingFilenames.has(file.filename)) {
                    // Safety check: Only delete if older than 4 hours (grace period for uploads in progress)
                    if (now - file.modifiedAt.getTime() > FOUR_HOURS_MS) {
                        // Normalize path join to avoid any leading slash issues
                        const relativeFileUrl = file.url.replace(/^\/uploads\//, "").replace(/^\/api\/storage\//, "");
                        const physicalPath = normalize(join(process.cwd(), "private_uploads", relativeFileUrl));
                        
                        try {
                            if (existsSync(physicalPath)) {
                                await unlink(physicalPath);
                                deletedCount++;
                                freedBytes += file.sizeBytes;
                            }
                        } catch (err) {
                            logger.error(`[StorageCleanup] Failed to unlink ${physicalPath}`, { error: String(err) });
                        }
                    }
                }
            }
        }

        if (deletedCount > 0) {
            logger.info(`[StorageCleanup] Cleaned ${deletedCount} orphan files (${(freedBytes/1024/1024).toFixed(2)} MB freed).`);
        }

        return { success: true, deletedCount, freedBytes };
    } catch (error) {
        logger.error("[cleanOrphanStorage]", { error: String(error) });
        return { success: false, error: "Erreur lors du nettoyage" };
    }
}

// ─── God-only: delete a file directly from VPS + clear DB field ──────────────

export type AssetDbField = "iconUrl" | "presentationBannerUrl" | "presentationPhotoUrl";

export async function godDeleteFile(
    fileUrl: string,
    dbClear?: { guildId: string; field: AssetDbField }
): Promise<{ success: boolean; error?: string; message?: string; deletedPath?: string }> {
    if (!(await isSuperAdmin())) return { success: false, error: "Super admin requis" };

    if (!fileUrl.startsWith("/uploads/") && !fileUrl.startsWith("/api/storage/")) {
        return { success: false, error: "Chemin non autorisé (doit commencer par /uploads/ ou /api/storage/)" };
    }

    const physicalPath = fileUrl.replace(/^\/uploads\//, "").replace(/^\/api\/storage\//, "");
    const absolutePath = normalize(join(process.cwd(), "private_uploads", physicalPath));
    const storageRoot = normalize(join(process.cwd(), "private_uploads"));

    if (!absolutePath.startsWith(storageRoot)) {
        return { success: false, error: "Path traversal détecté — opération refusée." };
    }

    try {
        await unlink(absolutePath);
        logger.info(`[God] Superadmin deleted file: ${fileUrl} (target: ${absolutePath})`);
    } catch (error: any) {
        if (error.code !== "ENOENT") {
            logger.error(`[God] Failed to delete file: ${absolutePath}`, { error });
            return { success: false, error: `Erreur suppression physique (${error.code}) sur : ${absolutePath}` };
        }
        // ENOENT = already gone
        logger.warn(`[God] File already missing on disk: ${absolutePath}`);
    }

    // Clear the DB field so the asset disappears from the panel immediately
    const allowedFields: AssetDbField[] = ["iconUrl", "presentationBannerUrl", "presentationPhotoUrl"];
    if (dbClear?.guildId && dbClear?.field && allowedFields.includes(dbClear.field)) {
        try {
            await (db as any).guildConfig.update({
                where: { id: dbClear.guildId },
                data: { [dbClear.field]: null },
            });
            logger.info(`[God] Cleared DB field ${dbClear.field} for guild ${dbClear.guildId}`);
        } catch (dbErr) {
            logger.error("[God] Failed to clear DB field:", { error: dbErr });
        }
    }

    return { 
        success: true, 
        message: "Opération terminée", 
        deletedPath: absolutePath 
    };
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { logAction } from "./audit-actions";

/**
 * RECOMPILE TRIGGER: 2026-03-11 02:22
 * This file MUST be async because it is marked with "use server".
 */

// Super-admin Discord IDs (from environment) - Forced async
export async function getSuperAdminIds(): Promise<string[]> {
    const envVar = process.env.SUPER_ADMIN_IDS;
    if (!envVar) return [];
    return envVar.split(",").map(id => id.trim()).filter(Boolean);
}

/**
 * Check if a Discord ID belongs to a super-admin
 */
export async function isDiscordSuperAdmin(discordId: string): Promise<boolean> {
    const superAdminIds = await getSuperAdminIds();
    return superAdminIds.includes(discordId);
}

/**
 * Check if the current user is a super-admin (platform-level)
 * Reads discordId from the JWT session — no DB call needed.
 */
export async function isSuperAdmin(): Promise<boolean> {
    const session = await auth();
    if (!session?.user?.id) return false;

    // discordId is stored in the JWT token by auth.ts jwt() callback
    // Reading it from session avoids a db.account.findFirst() on every request
    const discordId = (session as any).user?.discordId;
    if (!discordId) return false;

    const superAdminIds = await getSuperAdminIds();
    return superAdminIds.includes(discordId);
}

/**
 * Get all allowed guilds (platform whitelist)
 */
export async function getAllowedGuilds() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized: Super-admin access required");

    return db.allowedGuild.findMany({
        orderBy: { addedAt: "desc" }
    });
}

/**
 * Add a guild to the platform whitelist
 */
export async function addAllowedGuild(data: {
    discordGuildId: string;
    name?: string;
    tier?: string;
    notes?: string;
    expiresAt?: Date | null;
}) {
    const session = await auth();
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized: Super-admin access required");

    // Get super-admin's Discord ID
    const account = await db.account.findFirst({
        where: { userId: session!.user!.id, provider: "discord" }
    });

    if (!account?.providerAccountId) throw new Error("Discord account not found");

    // Check if already exists
    const existing = await db.allowedGuild.findUnique({
        where: { discordGuildId: data.discordGuildId }
    });

    if (existing) {
        throw new Error("Cette guilde est déjà dans la liste blanche");
    }

    const guild = await db.allowedGuild.create({
        data: {
            discordGuildId: data.discordGuildId,
            name: data.name || null,
            tier: data.tier || "BETA",
            notes: data.notes || null,
            expiresAt: data.expiresAt || null,
            addedBy: account.providerAccountId,
        }
    });

    // 📝 LOG ACTION (Professional Verbose)
    if (session?.user?.id) {
        await logAction({
            guildId: data.discordGuildId,
            action: "GOD_GUILD_WHITELIST",
            targetType: "WHITELIST",
            targetId: data.discordGuildId,
            newValue: { name: data.name, tier: data.tier, expiresAt: data.expiresAt },
            metadata: { operation: "ADD_TO_WHITELIST", guildName: data.name }
        });
    }

    revalidatePath("/god");
    return guild;
}

/**
 * Remove a guild from the platform whitelist
 */
export async function removeAllowedGuild(discordGuildId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized: Super-admin access required");

    await db.allowedGuild.delete({
        where: { discordGuildId }
    });

    // 📝 LOG ACTION
    const session = await auth();
    if (session?.user?.id) {
        await logAction({
            guildId: discordGuildId,
            action: "GOD_GUILD_WHITELIST",
            targetType: "WHITELIST",
            targetId: discordGuildId,
            metadata: { operation: "REMOVE_FROM_WHITELIST" }
        });
    }

    revalidatePath("/god");
    return { success: true };
}

/**
 * Toggle guild active status
 */
export async function toggleGuildActive(discordGuildId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized: Super-admin access required");

    const guild = await db.allowedGuild.findUnique({
        where: { discordGuildId }
    });

    if (!guild) throw new Error("Guilde non trouvée");

    const updated = await db.allowedGuild.update({
        where: { discordGuildId },
        data: { isActive: !guild.isActive }
    });

    // 📝 LOG ACTION
    const session = await auth();
    if (session?.user?.id) {
        await logAction({
            guildId: discordGuildId,
            action: "GOD_GUILD_WHITELIST",
            targetType: "WHITELIST",
            targetId: discordGuildId,
            oldValue: { isActive: guild.isActive },
            newValue: { isActive: updated.isActive },
            metadata: { operation: "TOGGLE_ACTIVE_STATUS" }
        });
    }

    revalidatePath("/god");
    return updated;
}

