};

// Rate limiting for interactions (prevent Discord embed hammer)
const interactionCooldowns = new Map<string, number>();
const INTERACTION_COOLDOWN_MS = 10 * 1000; // 10 seconds

export async function processRegistration(guildId: string, eventId: string, userId: string, data?: { classe?: string; comment?: string }) {
    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true }
    });
    if (!guildConfig) return { success: false, error: "Guilde non trouvée" };

    const event = await db.guildEvent.findUnique({
        where: { id: eventId, guildId: guildConfig.id },
        include: {
            _count: { select: { participants: { where: { status: "REGISTERED" } } } },
            participants: { where: { userId: userId } }
        }
    });

    if (!event) return { success: false, error: "Événement introuvable" };
    if (event.status !== "PUBLISHED") return { success: false, error: "Inscriptions fermées" };

    // Anti-spam check (User-Event based cooldown)
    const cooldownKey = `${userId}:${eventId}`;
    const lastAction = interactionCooldowns.get(cooldownKey) || 0;
    if (Date.now() - lastAction < INTERACTION_COOLDOWN_MS) {
        return { success: false, error: "Doucement ! Patiente quelques secondes entre tes actions." };
    }
    interactionCooldowns.set(cooldownKey, Date.now());

    if (event.participants.length > 0) return { success: false, error: "Déjà inscrit" };

    // Check raid 1/week rule
    if (event.type === "RAID_OFFICIAL") {
        const weekStart = new Date();
        weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1);
        weekStart.setHours(0, 0, 0, 0);

        const existingRaid = await db.eventParticipant.findFirst({
            where: {
                userId: userId,
                status: "REGISTERED",
                event: {
                    guildId: guildConfig.id,
                    type: "RAID_OFFICIAL",
                    status: "COMPLETED",
                    startDate: { gte: weekStart }
                }
            }
        });

        if (existingRaid) {
            return { success: false, error: "Tu as déjà participé à un Raid cette semaine" };
        }
    }

    // Determine position
    const currentCount = event._count.participants;
    const maxParticipants = event.maxParticipants || 999;
    const isReserve = currentCount >= maxParticipants;

    await db.eventParticipant.create({
        data: {
            eventId,
            userId: userId,
            status: isReserve ? "RESERVE" : "REGISTERED",
            position: currentCount + 1,
            classe: data?.classe,
            comment: data?.comment
        }
    });

    // Update Discord Embed (Fire and Forget)
    updateDiscordEventEmbed(guildId, eventId).catch(err => console.error("Background Embed Update Error:", err));

    // Revalidate Calendar Page AND Dashboard Layout (for Ticker)
    revalidatePath(`/dashboard/${guildId}/calendar`);
    revalidatePath(`/dashboard/${guildId}`, "layout");
    return { success: true, isReserve };
}

export async function processUnregistration(guildId: string, eventId: string, userId: string) {
    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true }
    });
    if (!guildConfig) return { success: false, error: "Guilde non trouvée" };

    const participant = await db.eventParticipant.findUnique({
        where: { eventId_userId: { eventId, userId } },
        include: { event: true }
    });

    if (!participant) return { success: false, error: "Non inscrit" };

    // Anti-spam check
    const cooldownKey = `${userId}:${eventId}`;
    const lastAction = interactionCooldowns.get(cooldownKey) || 0;
    if (Date.now() - lastAction < INTERACTION_COOLDOWN_MS) {
        return { success: false, error: "Patiente quelques secondes avant d'annuler." };
    }
    interactionCooldowns.set(cooldownKey, Date.now());

    const wasRegistered = participant.status === "REGISTERED";

    // Delete participation
    await db.eventParticipant.delete({
        where: { id: participant.id }
    });

    // Auto-promote first reserve if was registered
    if (wasRegistered) {
        const firstReserve = await db.eventParticipant.findFirst({
            where: { eventId, status: "RESERVE" },
            orderBy: { position: "asc" }
        });

        if (firstReserve) {
            await db.eventParticipant.update({
                where: { id: firstReserve.id },
                data: {
                    status: "REGISTERED",
                    promotedAt: new Date()
                }
            });
            // Optional: Send DM to promoted user
        }
    }

    // Reorder positions
    const participants = await db.eventParticipant.findMany({
        where: { eventId },
        orderBy: { position: "asc" }
    });

    for (let i = 0; i < participants.length; i++) {
        await db.eventParticipant.update({
            where: { id: participants[i].id },
            data: { position: i + 1 }
        });
    }

    // Update Discord Embed (Fire and Forget)
    updateDiscordEventEmbed(guildId, eventId).catch(err => console.error("Background Embed Update Error:", err));

    // Revalidate Calendar Page AND Dashboard Layout (for Ticker)
    revalidatePath(`/dashboard/${guildId}/calendar`);
    revalidatePath(`/dashboard/${guildId}`, "layout");
    return { success: true };
}

export async function publishDiscordEvent(guildId: string, eventId: string) {
    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, calendarNotifyChannelId: true }
        });

        if (!guildConfig || !guildConfig.calendarNotifyChannelId) {
            return { success: false, error: "Canal Discord non configuré" };
        }

        const event = await db.guildEvent.findUnique({
            where: { id: eventId },
            include: {
                // Include participants count for initial render
                _count: { select: { participants: true } }
            }
        });

        if (!event) return { success: false, error: "Événement introuvable" };

        // 1. Prepare Payload
        const typeConfig = EVENT_CONFIG[event.type] || { emoji: "📅", color: 0x9333ea, label: event.type };
        const imageName = EVENT_IMAGES[event.type] || "calendar_event_guild.png";
        const publicUrl = getAppBaseUrl();
        const imageUrl = `${publicUrl}/assets/calendar/${imageName}`;

        // Fixed Timezone Handling via Discord Dynamic Timestamps
        const startTs = Math.floor(new Date(event.startDate).getTime() / 1000);
        const endTs = Math.floor(new Date(event.endDate).getTime() / 1000);

        const fields = [
            { name: "📅 Date", value: `<t:${startTs}:d> (<t:${startTs}:D>)`, inline: true },
            { name: "⏰ Horaire", value: `<t:${startTs}:t> - <t:${endTs}:t> (<t:${startTs}:R>)`, inline: true },
            { name: "👥 Places", value: `0/${event.maxParticipants || "∞"}`, inline: true },
            { name: "🔗 Lien", value: `[Voir l'événement](${publicUrl}/dashboard/${guildId}/calendar?event=${event.id})`, inline: true },
            { name: "📝 Description", value: event.description || "*Pas de description*", inline: false },
            { name: `✅ Inscrits (0)`, value: "*Aucun inscrit*", inline: true },
            { name: `⏳ File d'attente (0)`, value: "*Personne en file d'attente*", inline: true },
        ];

        const components = [
            {
                type: 1,
                components: [
                    { type: 2, style: 1, label: "S'inscrire", emoji: { name: "✅" }, custom_id: `calendar:join:${event.id}` },
                    { type: 2, style: 4, label: "Se désinscrire", emoji: { name: "🚪" }, custom_id: `calendar:leave:${event.id}` }
                ]
            }
        ];

        // 2. Send Message
        const messageId = await sendChannelMessage(
            guildConfig.calendarNotifyChannelId,
            "",
            {
                embedTitle: `${typeConfig.emoji} ${event.title}`,
                embedColor: typeConfig.color,
                embedImage: imageUrl,
                fields: fields,
                embedFooter: "Statut: 🟢 Ouvert",
                components: components
            }
        );

        if (messageId) {
            // 3. Save Message ID and Channel ID
            await db.guildEvent.update({
                where: { id: eventId },
                data: {
                    discordMessageId: messageId,
                    discordChannelId: guildConfig.calendarNotifyChannelId,
                    status: "PUBLISHED"
                }
            });
            return { success: true };
        } else {
            return { success: false, error: "Erreur lors de l'envoi Discord" };
        }

    } catch (error) {
        console.error("[Calendar Service] publishDiscordEvent Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

export async function updateDiscordEventEmbed(guildId: string, eventId: string) {
    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, calendarNotifyChannelId: true }
        });
        if (!guildConfig || !guildConfig.calendarNotifyChannelId) return;

        const event = await db.guildEvent.findUnique({
            where: { id: eventId },
            include: {
                participants: {
                    include: {
                        user: {
                            select: {
                                id: true,
                                name: true,
                                profiles: {
                                    where: { guildId: guildConfig.id },
                                    select: { discordNickname: true }
                                }
                            }
                        }
                    },
                    orderBy: { position: "asc" }
                }
            }
        });

        if (!event || !event.discordMessageId || !event.discordChannelId) return;

        // Visual Config
        const typeConfig = EVENT_CONFIG[event.type] || { emoji: "📅", color: 0x9333ea, label: event.type };
        const imageName = EVENT_IMAGES[event.type] || "calendar_event_guild.png";
        const publicUrl = getAppBaseUrl();
        const imageUrl = `${publicUrl}/assets/calendar/${imageName}`;

        // Build Participant Lists
        const registered = event.participants.filter(p => p.status === "REGISTERED" || p.status === "CONFIRMED");
        const reserve = event.participants.filter(p => p.status === "RESERVE");

        // Helper to format names
        const formatParticipant = (p: any) => {
            const name = p.user.profiles[0]?.discordNickname || p.user.name || "Inconnu";
            const classe = p.classe ? `(${p.classe})` : "";
            return `• ${name} ${classe}`;
        };

        const registeredList = registered.length > 0
            ? registered.map(formatParticipant).join("\n")
            : "*Aucun inscrit*";

        const reserveList = reserve.length > 0
            ? reserve.map(formatParticipant).join("\n")
            : "*Personne en file d'attente*";

        // Fixed Timezone Handling via Discord Dynamic Timestamps
        const startTs = Math.floor(new Date(event.startDate).getTime() / 1000);
        const endTs = Math.floor(new Date(event.endDate).getTime() / 1000);

        const fields = [
            { name: "📅 Date", value: `<t:${startTs}:d> (<t:${startTs}:D>)`, inline: true },
            { name: "⏰ Horaire", value: `<t:${startTs}:t> - <t:${endTs}:t> (<t:${startTs}:R>)`, inline: true },
            { name: "👥 Places", value: `${registered.length}/${event.maxParticipants || "∞"}`, inline: true },
            { name: "🔗 Lien", value: `[Voir l'événement](${publicUrl}/dashboard/${guildId}/calendar?event=${event.id})`, inline: true },
            { name: "📝 Description", value: event.description || "*Pas de description*", inline: false },
            // SEPARATED LISTS
            { name: `✅ Inscrits (${registered.length})`, value: registeredList, inline: true },
            { name: `⏳ File d'attente (${reserve.length})`, value: reserveList, inline: true },
        ];

        // Interactive Buttons
        const components = [
            {
                type: 1, // Action Row
                components: [
                    {
                        type: 2, // Button
                        style: 1, // Primary (Blurple)
                        label: "S'inscrire",
                        emoji: { name: "✅" },
                        custom_id: `calendar:join:${event.id}`
                    },
                    {
                        type: 2, // Button
                        style: 4, // Danger (Red)
                        label: "Se désinscrire",
                        emoji: { name: "🚪" },
                        custom_id: `calendar:leave:${event.id}`
                    }
                ]
            }
        ];

        await updateChannelMessage(
            event.discordChannelId,
            event.discordMessageId,
            "", // No plain content update
            {
                embedTitle: `${typeConfig.emoji} ${event.title}`,
                embedColor: typeConfig.color,
                embedImage: imageUrl,
                fields: fields,
                embedFooter: `Statut: ${event.status === "PUBLISHED" ? "🟢 Ouvert" : "🔴 Fermé"}`,
                components: components
            }
        );

    } catch (error) {
        console.error("[Calendar Service] updateDiscordEventEmbed Error:", error);
    }
}

const MAX_RETRIES = 3;
const RETRY_DELAY = 1000;

// =============================================================================
// In-Memory Cache (TTL-based) for Discord API hot paths
// Prevents hammering Discord API on every page load / server action
// =============================================================================
type CacheEntry<T> = { data: T; expiresAt: number };
const discordCache = new Map<string, CacheEntry<unknown>>();

function getCached<T>(key: string): T | null {
    const entry = discordCache.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
        discordCache.delete(key);
        return null;
    }
    return entry.data as T;
}

function setCached<T>(key: string, data: T, ttlMs: number): void {
    discordCache.set(key, { data, expiresAt: Date.now() + ttlMs });
}

export function invalidateDiscordCache(pattern?: string): void {
    if (!pattern) {
        discordCache.clear();
        return;
    }
    for (const key of discordCache.keys()) {
        if (key.includes(pattern)) discordCache.delete(key);
    }
}

/**
 * SECURITY: Sanitize user input to prevent unwanted @everyone or @here pings
 * Inserts a zero-width space (U+200B) between the '@' and the word.
 */
export function sanitizeMentions(text: string | null | undefined): string {
    if (!text) return "";
    return text
        .replace(/@everyone/gi, "@\u200beveryone")
        .replace(/@here/gi, "@\u200bhere");
}


async function fetchWithRetry(url: string, options: RequestInit): Promise<Response> {
    let lastError: Error | null = null;

    for (let i = 0; i < MAX_RETRIES; i++) {
        try {
            const res = await fetch(url, options);

            // If success or client error (4xx) that is not 429, return immediately.
            // We only retry on server errors (5xx) or rate limits (429).
            if (res.ok || (res.status >= 400 && res.status < 500 && res.status !== 429)) {
                return res;
            }

            // 429 Rate Limit: Wait for retry-after if available, else default delay
            if (res.status === 429) {
                const retryAfter = res.headers.get("Retry-After");
                const waitTime = retryAfter ? parseInt(retryAfter) * 1000 : RETRY_DELAY * Math.pow(2, i);
                console.warn(`[Discord API] Rate limited. Retrying after ${waitTime}ms...`);
                await new Promise(resolve => setTimeout(resolve, waitTime));
                continue;
            }

            // 5xx Server Error: Standard backoff
            if (res.status >= 500) {
                console.warn(`[Discord API] Server error ${res.status}. Retrying (${i + 1}/${MAX_RETRIES})...`);
                await new Promise(resolve => setTimeout(resolve, RETRY_DELAY * Math.pow(2, i)));
                continue;
            }

        } catch (error) {
            lastError = error as Error;
            console.warn(`[Discord API] Network error: ${error}. Retrying (${i + 1}/${MAX_RETRIES})...`);
            await new Promise(resolve => setTimeout(resolve, RETRY_DELAY * Math.pow(2, i)));
        }
    }

    throw lastError || new Error(`Failed to fetch ${url} after ${MAX_RETRIES} retries`);
}

export async function fetchGuildRoles(guildId: string, options: { excludeManaged?: boolean } = { excludeManaged: true }) {
    // In-memory cache — next: { revalidate } is ignored in Server Actions context
    const cacheKey = `roles:${guildId}`;
    const cached = getCached<Array<{ id: string; name: string; color: number; position: number; managed: boolean; permissions: string }>>(cacheKey);
    if (cached !== null) {
        const result = options.excludeManaged ? cached.filter(r => !r.managed) : cached;
        return result;
    }

    const token = process.env.DISCORD_BOT_TOKEN;
    if (!token) throw new Error("Missing DISCORD_BOT_TOKEN");

    const res = await fetchWithRetry(`https://discord.com/api/v10/guilds/${guildId}/roles`, {
        headers: {
            Authorization: `Bot ${token}`,
        },
        cache: "no-store"
    });

    if (!res.ok) {
        if (res.status === 401 || res.status === 403) {
            throw new Error("Bot lacks permissions or invalid token.");
        }
        throw new Error(`Failed to fetch roles: ${res.statusText}`);
    }

    const roles = (await res.json()) as Array<{
        id: string;
        name: string;
        color: number;
        position: number;
        managed: boolean;
        permissions: string;
    }>;

    // Cache the raw (unfiltered) list so both managed/unmanaged callers benefit
    // TTL: 60 seconds (reduced from 5min to avoid onboarding lags)
    setCached(cacheKey, roles, 60 * 1000);

    const result = options.excludeManaged ? roles.filter(r => !r.managed) : roles;
    return result.sort((a, b) => b.position - a.position);
}

export async function fetchGuild(guildId: string) {
    // In-memory cache — next: { revalidate } is ignored in Server Actions context
    const cacheKey = `guild:${guildId}`;
    const cached = getCached<{ id: string; name: string; icon: string | null; owner_id?: string }>(cacheKey);
    if (cached !== null) return cached;

    const token = process.env.DISCORD_BOT_TOKEN;
    if (!token) throw new Error("Missing DISCORD_BOT_TOKEN");

    const res = await fetchWithRetry(`https://discord.com/api/v10/guilds/${guildId}`, {
        headers: { Authorization: `Bot ${token}` },
        cache: "no-store"
    });

    if (!res.ok) {
        throw new Error(`Failed to fetch guild: ${res.statusText}`);
    }

    const data = (await res.json()) as {
        id: string;
        name: string;
        icon: string | null;
        owner_id?: string;
        system_channel_id?: string | null;
    };

    // TTL: 120 seconds (reduced from 10min)
    setCached(cacheKey, data, 120 * 1000);
    return data;
}

export async function fetchBotGuilds() {
    const token = process.env.DISCORD_BOT_TOKEN;
    if (!token) throw new Error("Missing DISCORD_BOT_TOKEN");

    const res = await fetchWithRetry(`https://discord.com/api/v10/users/@me/guilds`, {
        headers: { Authorization: `Bot ${token}` },
        cache: "no-store"
    });

    if (!res.ok) throw new Error(`Failed to fetch bot guilds: ${res.statusText}`);

    return (await res.json()) as Array<{ id: string; name: string; icon: string | null }>;
}

export async function fetchGuildMember(guildId: string, userId: string) {
    const cacheKey = `member:${guildId}:${userId}`;
    const cached = getCached<{ 
        user?: { id: string; username: string; global_name?: string; avatar?: string | null }; 
        nick?: string | null; 
        avatar?: string | null;
        roles: string[]; 
        joined_at?: string 
    } | null>(cacheKey);
    if (cached !== null) return cached;

    const token = process.env.DISCORD_BOT_TOKEN;
    if (!token) throw new Error("Missing DISCORD_BOT_TOKEN");

    const res = await fetchWithRetry(`https://discord.com/api/v10/guilds/${guildId}/members/${userId}`, {
        headers: { Authorization: `Bot ${token}` },
        cache: "no-store"
    });

    if (!res.ok) {
        if (res.status === 404) {
            setCached(cacheKey, null, 15 * 1000); // Short TTL for 404 (important for onboarding)
            return null;
        }
        throw new Error(`Failed to fetch member: ${res.statusText}`);
    }

    const data = await res.json() as {
        user?: { id: string; username: string; global_name?: string; avatar?: string | null };
        nick?: string | null;
        avatar?: string | null;
        roles: string[];
        joined_at?: string;
    };

    // TTL: 60 seconds (reduced from 5min to avoid onboarding lags)
    setCached(cacheKey, data, 60 * 1000);
    return data;
}

export async function listGuildMembers(guildId: string, limit = 1000) {
    const cacheKey = `members:${guildId}:${limit}`;
    const cached = getCached<Array<{ user: { id: string; username: string; global_name?: string }; nick?: string | null; roles: string[]; joined_at?: string }>>(cacheKey);
    if (cached !== null) return cached;

    const token = process.env.DISCORD_BOT_TOKEN;
    if (!token) throw new Error("Missing DISCORD_BOT_TOKEN");

    const res = await fetchWithRetry(`https://discord.com/api/v10/guilds/${guildId}/members?limit=${limit}`, {
        headers: { Authorization: `Bot ${token}` },
    });

    if (!res.ok) {
        throw new Error(`Failed to list members: ${res.statusText}`);
    }

    const data = await res.json() as Array<{
        user: { id: string; username: string; global_name?: string; bot?: boolean };
        nick?: string | null;
        roles: string[];
        joined_at?: string;
    }>;

    setCached(cacheKey, data, 10 * 60 * 1000); // TTL: 10 minutes
