import { Client, GatewayIntentBits, VoiceState, Collection } from "discord.js";
import { logger } from "../../lib/logger";

export interface VoiceUser {
    userId: string;
    userName: string;
    avatar: string | null;
    channelId: string;
    channelName: string;
    isMute: boolean;
    isDeaf: boolean;
    isSpeaking?: boolean;
}

/**
 * DiscordVoiceService - Gateway-based voice monitoring
 * Tracks real-time voice states across guilds.
 */
export class DiscordVoiceService {
    private static instance: DiscordVoiceService;
    private client: Client;
    private voiceStates: Map<string, Map<string, VoiceUser>> = new Map();
    private onUpdateCallback: ((guildId: string, users: VoiceUser[]) => void) | null = null;

    private constructor() {
        this.client = new Client({
            intents: [
                GatewayIntentBits.Guilds,
                GatewayIntentBits.GuildVoiceStates,
                GatewayIntentBits.GuildMembers, // Needed to resolve nicknames
            ],
        });

        this.setupEvents();
    }

    public static getInstance(): DiscordVoiceService {
        if (!DiscordVoiceService.instance) {
            DiscordVoiceService.instance = new DiscordVoiceService();
        }
        return DiscordVoiceService.instance;
    }

    public async start() {
        const token = process.env.DISCORD_BOT_TOKEN;
        if (!token) {
            logger.warn("[DiscordVoice] ⚠️ Missing DISCORD_BOT_TOKEN. Voice monitoring disabled.");
            return;
        }

        try {
            await this.client.login(token);
            logger.info("[DiscordVoice] 🚀 Gateway connected.");
        } catch (error) {
            logger.error("[DiscordVoice] ❌ Login failed:", error as any);
        }
    }

    private setupEvents() {
        this.client.on("ready", () => {
            logger.info(`[DiscordVoice] Logged in as ${this.client.user?.tag}`);
            // Initial scan of guilds already in cache
            this.client.guilds.cache.forEach(guild => this.refreshGuild(guild.id));
        });

        this.client.on("voiceStateUpdate", (oldState, newState) => {
            const guildId = newState.guild?.id || oldState.guild?.id;
            if (guildId) {
                this.refreshGuild(guildId);
            }
        });

        // Speaking events require a connection to voice, which we don't have.
        // We'll stick to basic VoiceStates (mute/deaf/channel).
    }

    private async refreshGuild(guildId: string) {
        const guild = this.client.guilds.cache.get(guildId);
        if (!guild) return;

        const guildMap = new Map<string, VoiceUser>();
        
        guild.voiceStates.cache.forEach((vs: VoiceState) => {
            if (!vs.member || vs.member.user.bot) return;
            
            const channel = vs.channel;
            if (!channel) return;

            guildMap.set(vs.id, {
                userId: vs.id,
                userName: vs.member.displayName,
                avatar: vs.member.user.displayAvatarURL({ extension: 'png', size: 64 }),
                channelId: channel.id,
                channelName: channel.name,
                isMute: vs.selfMute || vs.serverMute || false,
                isDeaf: vs.selfDeaf || vs.serverDeaf || false,
            });
        });

        this.voiceStates.set(guildId, guildMap);

        // Notify subscribers
        if (this.onUpdateCallback) {
            this.onUpdateCallback(guildId, Array.from(guildMap.values()));
        }
    }

    public setOnUpdate(callback: (guildId: string, users: VoiceUser[]) => void) {
        this.onUpdateCallback = callback;
    }

    public getVoiceUsers(guildId: string): VoiceUser[] {
        const map = this.voiceStates.get(guildId);
        return map ? Array.from(map.values()) : [];
    }

    public async stop() {
        await this.client.destroy();
    }
}

import { Server, Socket } from "socket.io";
import { SigilBombRoom } from "./SigilBombRoom";
import { logger } from "@/lib/logger";

export class BombManager {
    private rooms: Map<string, SigilBombRoom> = new Map();
    private socketToRoom: Map<string, string> = new Map(); // socketId -> roomId
    private userToRoom: Map<string, string> = new Map();   // userId -> roomId

    constructor(private io: Server) {}

    public registerSocket(socket: Socket) {
        socket.on("bomb:room:join",     (data) => this.joinRoom(socket, data));
        socket.on("bomb:room:leave",    ()     => this.leaveRoom(socket));
        socket.on("bomb:room:list",     ()     => this.listRooms(socket));
        socket.on("bomb:start-game",    ()     => this.startGame(socket));
        socket.on("bomb:toggle-ready",  ()     => this.toggleReady(socket));
        socket.on("bomb:update-config", (cfg)  => this.updateConfig(socket, cfg));
        socket.on("bomb:submit-word",   (word) => this.submitWord(socket, word));
        socket.on("bomb:typing",        (text) => this.getRoom(socket)?.handleTyping(socket.id, text));
        socket.on("bomb:restart",       ()     => this.getRoom(socket)?.resetToLobby());
        socket.on("bomb:leave",         ()     => this.leaveRoom(socket));
    }

    public handleDisconnect(socket: Socket) {
        this.leaveRoom(socket);
    }

    private joinRoom(socket: Socket, data: any) {
        const { roomId, playerObj } = data;
        if (!playerObj?.userId) return;
        const userId = playerObj.userId;

        // 1. Leave previous room if it's NOT the same one
        const existingRoomId = this.userToRoom.get(userId);
        if (existingRoomId && existingRoomId !== roomId) {
            this.cleanupRoom(existingRoomId, "TRANSFER"); // Special flag to signify we are moving
        }

        const isNewRoom = !this.rooms.has(roomId);
        let room = this.rooms.get(roomId);
        if (!room) {
            room = new SigilBombRoom(this.io, {
                id: roomId,
                guildId: playerObj.guildId
            });
            this.rooms.set(roomId, room);
            logger.info(`[SigilBomb] Room Created: ${roomId} by ${playerObj.userName}`);
        }
        
        room.join(socket, playerObj);
        this.socketToRoom.set(socket.id, roomId);
        this.userToRoom.set(userId, roomId);

        // If the player created this room in solo mode, apply config synchronously
        // (host is guaranteed to be set after join above)
        if (isNewRoom && playerObj.isSoloMode === true) {
            logger.info(`[SigilBomb] Solo mode detected for new room ${roomId} — adding bot.`);
            room.updateConfig(socket.id, { isSoloMode: true });
        }
    }

    private leaveRoom(socket: Socket) {
        const roomId = this.socketToRoom.get(socket.id);
        if (roomId) {
            this.cleanupRoom(roomId, socket.id);
        }
    }

    private cleanupRoom(roomId: string, socketIdOrFlag: string) {
        const room = this.rooms.get(roomId);
        if (room) {
            if (socketIdOrFlag !== "TRANSFER") {
                room.leave(socketIdOrFlag);
                this.socketToRoom.delete(socketIdOrFlag);
            }
            
            // Re-calculate room visibility or cleanup
            const activePlayers = room.getPlayers().filter(p => !p.isBot && p.isConnected);
            
            // If room is empty, destroy it after a small grace period (10s)
            if (activePlayers.length === 0) {
                setTimeout(() => {
                    const r = this.rooms.get(roomId);
                    if (r) {
                        const stillEmpty = r.getPlayers().filter(p => !p.isBot && p.isConnected).length === 0;
                        if (stillEmpty) {
                            // Cleanup user mappings for all players who were in this room
                            r.getPlayers().forEach(p => {
                                if (p.userId) this.userToRoom.delete(p.userId);
                            });
                            this.rooms.delete(roomId);
                            logger.info(`[SigilBomb] Room Destroyed: ${roomId}`);
                        }
                    }
                }, 10000); 
            }
        }
    }

    private toggleReady(socket: Socket) {
        this.getRoom(socket)?.toggleReady(socket.id);
    }

    private updateConfig(socket: Socket, cfg: any) {
        this.getRoom(socket)?.updateConfig(socket.id, cfg);
    }

    private startGame(socket: Socket) {
        this.getRoom(socket)?.startGame(socket.id);
    }

    private submitWord(socket: Socket, word: string) {
        this.getRoom(socket)?.submitWord(socket.id, word);
    }

    private getRoom(socket: Socket): SigilBombRoom | undefined {
        const roomId = this.socketToRoom.get(socket.id);
        return roomId ? this.rooms.get(roomId) : undefined;
    }

    private listRooms(socket: Socket) {
        const list = Array.from(this.rooms.values())
            .filter(r => r.getState() === 'LOBBY' && r.getPlayers().some(p => !p.isBot))
            .map(r => r.getPublicInfo());
        socket.emit("bomb:room:list", list);
    }
}

import { Server, Socket } from "socket.io";
import { logger } from "@/lib/logger";
import * as fs from "fs";
import * as path from "path";

type GameState = "LOBBY" | "PLAYING" | "GAME_END";

interface Player {
    id: string; // Socket ID
    userId?: string;
    discordId?: string; // NEW — Snowflake Discord ID for voice matching
    userName: string;
    userAvatar?: string;
    lives: number;
    isConnected: boolean;
    isSpectator: boolean;
    wordsFound: number;
    alphabet: string[];
    isReady: boolean;
    isBot: boolean;
}

interface RoomConfig {
    startingLives: number;
    turnTime: number;
    dictionaryMode: "dofus" | "mixed" | "fr";
    syllableDifficulty: "easy" | "medium" | "hard";
    minWordLength: number;
    isSoloMode: boolean;
    minTurnDuration: number; // Minimum time given to next player (JKLM style)
}

// ── Dofus class names always accepted ────────────────────────────
const ALWAYS_VALID = new Set([
    "IOP","CRA","KAMA","XELOR","ENUTROF","SACRIEUR","OUGINAK",
    "ELIOTROPE","HUPPERMAGE","ZOBAL","STEAMER","SADIDA",
    "FECA","SRAM","ROUBLARD","ECAFLIP","PANDAWA","OSAMODAS",
    "MASQUERAIDER","FORGELANCE","TWILIGHT","TEMPORAL","KROSMAGE",
    "GUILDE","ALLIANCE","PERCEPTEUR","BONTARIEN","BRAKMARIEN",
]);

export class SigilBombRoom {
    // ── Shared dictionary (static, loaded once) ──────────────────
    private static dictionaryDofus: string[] = [];
    private static dictionaryMixed: string[] = [];
    private static dictionaryCategories: Record<string, string> = {};
    private static dictionaryLoaded = false;

    private id: string;
    private guildId: string;
    private state: GameState = "LOBBY";
    private players: Player[] = [];
    private hostId: string | null = null; // Current Socket ID of host
    private hostUserId: string | null = null; // Permanent User ID of host

    private config: RoomConfig = {
        startingLives: 3,
        turnTime: 12,
        dictionaryMode: "dofus",
        syllableDifficulty: "medium",
        minWordLength: 1,
        isSoloMode: false,
        minTurnDuration: 2,
    };

    private currentTurnIndex = 0;
    private currentSyllable = "";
    private currentSyllableCategory: string | null = null;
    private timeLeft = 0;
    private tickInterval: NodeJS.Timeout | null = null;
    private botTimeout: NodeJS.Timeout | null = null;
    private usedWordsInSession = new Set<string>();
    private lastFoundWords: { word: string; playerName: string; playerId: string }[] = [];
    private static deconstructedWords: Map<string, string[]> = new Map();
    private currentSyllablePartCount = 1;
    private currentSyllableHintParts: string[] = [];

    constructor(private io: Server, config: { id: string; guildId: string }) {
        this.id = config.id;
        this.guildId = config.guildId;
        this.loadDictionary();
    }

    // ── Unicode normalization ──────────────────────────────────────
    private static normalize(word: string): string {
        return word
            .trim()
            .toUpperCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, ""); // strip diacritics
    }

    // ── Dictionary ────────────────────────────────────────────────
    private loadDictionary() {
        if (SigilBombRoom.dictionaryLoaded) return;
        try {
            const dofusPath = path.join(process.cwd(), "public/game-data/bomb-dictionary.json");
            const mixedPath = path.join(process.cwd(), "public/game-data/bomb-dictionary-mixed.json");
            
            if (fs.existsSync(dofusPath)) {
                const data = JSON.parse(fs.readFileSync(dofusPath, "utf-8"));
                SigilBombRoom.dictionaryDofus = (data.words || []).map((w: string) => SigilBombRoom.normalize(w));
                if (data.categories) {
                    SigilBombRoom.dictionaryCategories = data.categories;
                    
                    // ── Post-process categories (Fix Bosses miscategorized as Sorts) ──
                    const BOSS_KEYWORDS = [
                        "HAREBOURG", "KORRIANDRE", "MAITRECORBAC", "BWORKER", "MINOTOROR", 
                        "MINOTOT", "DRACOUSSAL", "TANTGUEUL", "GEANT", "KRALAMOURE",
                        "DAZAK", "CONTEUR", "KLIME", "NILEZA", "SYLARGH", "MISSIZ", "FRIZZ"
                    ];
                    
                    for (const [word, category] of Object.entries(SigilBombRoom.dictionaryCategories)) {
                        if (category === "Sort") {
                            const upperWord = word.toUpperCase();
                            if (BOSS_KEYWORDS.some(k => upperWord.includes(k))) {
                                SigilBombRoom.dictionaryCategories[word] = "Monstre (Boss)";
                            }
                        }
                    }
                }
            }
            if (fs.existsSync(mixedPath)) {
                const data = JSON.parse(fs.readFileSync(mixedPath, "utf-8"));
                SigilBombRoom.dictionaryMixed = (data.words || []).map((w: string) => SigilBombRoom.normalize(w));
            }
            
            SigilBombRoom.dictionaryLoaded = true;
            logger.info(`[SigilBomb] Dictionaries loaded: Dofus(${SigilBombRoom.dictionaryDofus.length}), Mixed(${SigilBombRoom.dictionaryMixed.length})`);
            
            // ── Deconstruct words for multi-word support ──
            this.buildDeconstructions();
        } catch (e) {
            logger.error("[SigilBomb] Failed to load dictionaries:", e as any);
        }
    }

    private buildDeconstructions() {
        const dofusWords = new Set(SigilBombRoom.dictionaryDofus);
        const allWords = new Set([...SigilBombRoom.dictionaryDofus, ...SigilBombRoom.dictionaryMixed]);
        
        // We focus on dofus words as they are the ones most likely to be "stuck" compounds
        const wordsToProcess = SigilBombRoom.dictionaryDofus.filter(w => w.length >= 7);

        logger.info(`[SigilBomb] Building deconstructions for ${wordsToProcess.length} words...`);
        let compoundCount = 0;

        for (const word of wordsToProcess) {
            const parts: string[] = [];
            let remaining = word;
            let possible = true;

            while (remaining.length > 0) {
                let found = false;
                // Try longest possible base word first (from current length down to 3)
                for (let len = Math.min(remaining.length, 12); len >= 3; len--) {
                    const sub = remaining.substring(0, len);
                    if (allWords.has(sub)) {
                        parts.push(sub);
                        remaining = remaining.substring(len);
                        found = true;
                        break;
                    }
                }

                if (!found) {
                    // Try tiny common particles
                    const tinyWords = ["DE", "LE", "LA", "DU", "DES", "AU", "AUX", "EN"];
                    for (const tiny of tinyWords) {
                        if (remaining.startsWith(tiny)) {
                            parts.push(tiny);
                            remaining = remaining.substring(tiny.length);
                            found = true;
                            break;
                        }
                    }
                }

                if (!found) { possible = false; break; }
            }

            if (possible && parts.length >= 2) {
                SigilBombRoom.deconstructedWords.set(word, parts);
                compoundCount++;
            }
        }
        logger.info(`[SigilBomb] Deconstruction complete. Found ${compoundCount} compound words.`);
    }

    private getActiveDictionary(): string[] {
        if (this.config.dictionaryMode === "fr") {
            return SigilBombRoom.dictionaryMixed;
        } else if (this.config.dictionaryMode === "mixed") {
            return [...SigilBombRoom.dictionaryDofus, ...SigilBombRoom.dictionaryMixed];
        }
        return SigilBombRoom.dictionaryDofus;
    }

    // ── Join / Leave ──────────────────────────────────────────────
    public join(socket: Socket, playerObj: any) {
        const existing = this.players.find((p) => p.userId === playerObj.userId);
        if (existing) {
            // Reconnection — update socket id
            existing.id = socket.id;
            existing.isConnected = true;
            
            // CRITICAL FIX: If this user is the permanent host, update hostId to new socket
            if (existing.userId === this.hostUserId) {
                this.hostId = socket.id;
                logger.info(`[SigilBomb:${this.id}] Host ${existing.userName} reconnected with new socket.`);
            } else {
                logger.info(`[SigilBomb:${this.id}] ${existing.userName} reconnected.`);
            }
        } else {
            // Check capacity (8 participants max for circular UI logic)
            const participants = this.players.filter(p => !p.isSpectator).length;
            if (participants >= 8 && !playerObj.isSpectator) {
                socket.emit("bomb:word-error", { 
                    message: "La salle est complète (Maximum 8 joueurs)." 
                });
                return;
            }

            const isSpectator = this.state !== "LOBBY" || !!playerObj.isSpectator;
            const newPlayer: Player = {
                id: socket.id,
                userId: playerObj.userId,
                discordId: playerObj.discordId,
                userName: playerObj.userName,
                userAvatar: playerObj.userAvatar,
                lives: this.config.startingLives,
                isConnected: true,
                isSpectator,
                wordsFound: 0,
                alphabet: [],
                isReady: false,
                isBot: false,
            };
            this.players.push(newPlayer);
            if (!this.hostUserId && !isSpectator) {
                this.hostId = socket.id;
                this.hostUserId = playerObj.userId;
                newPlayer.isReady = true; // host auto-ready
                logger.info(`[SigilBomb:${this.id}] Initial host assigned: ${newPlayer.userName} (${newPlayer.userId})`);
            }
        }

        socket.join(this.id);
        this.syncState();
    }

    public leave(socketId: string) {
        const player = this.players.find((p) => p.id === socketId);
        if (player) {
            player.isConnected = false;
            if (this.state === "LOBBY") {
                this.players = this.players.filter((p) => p.id !== socketId);
            }
        }
        // Transfer host if current host socket leaves and no reconnection for a while?
        // For now, only transfer if really necessary
        if (this.hostId === socketId) {
            const next = this.players.find((p) => p.isConnected && !p.isSpectator && !p.isBot);
            if (next) {
                this.hostId = next.id;
                this.hostUserId = next.userId || null;
                next.isReady = true;
            } else {
                this.hostId = null;
                this.hostUserId = null;
            }
        }
        this.syncState();
    }

    // ── Config & Ready ────────────────────────────────────────────
    public toggleReady(socketId: string) {
        const player = this.players.find((p) => p.id === socketId);
        if (player && this.state === "LOBBY" && !player.isSpectator) {
            // Host is always ready
            if (player.id === this.hostId) { player.isReady = true; }
            else { player.isReady = !player.isReady; }
            this.syncState();
        }
    }

    public updateConfig(socketId: string, cfg: Partial<RoomConfig>) {
        if (this.hostId !== socketId) return;
        this.config = { ...this.config, ...cfg };

        // Handle bot
        if (this.config.isSoloMode) {
            if (!this.players.some((p) => p.isBot)) {
                this.players.push({
                    id: "bot-" + Math.random().toString(36).substring(2, 7),
                    userId: "bot",
                    userName: "Robot Crâ-Mée",
                    userAvatar: "/assets/dofus/classes/9.png",
                    lives: this.config.startingLives,
                    isConnected: true,
                    isSpectator: false,
                    wordsFound: 0,
                    alphabet: [],
                    isReady: true,
                    isBot: true,
                });
            }
        } else {
            this.players = this.players.filter((p) => !p.isBot);
        }

        // Reset lives on config change (lobby only)
        if (this.state === "LOBBY") {
            this.players.forEach((p) => { p.lives = this.config.startingLives; });
        }
        this.syncState();

        // Auto-start in solo mode is now disabled to allow users to change settings in the lobby first.
        // The host must manually click "Lancer l'Épreuve".
    }

    // ── Start Game ────────────────────────────────────────────────
    public startGame(socketId: string) {
        if (this.hostId !== socketId) return;
        const participants = this.players.filter((p) => !p.isSpectator);
        const allReady = participants.every((p) => p.isReady || p.isBot);
        if (!allReady || participants.length === 0) {
            this.io.to(socketId).emit("bomb:word-error", {
                message: "Tous les joueurs doivent être prêts !",
            });
            return;
        }

        this.state = "PLAYING";
        this.usedWordsInSession.clear();
        participants.forEach((p) => {
            p.lives = this.config.startingLives;
            p.wordsFound = 0;
            p.alphabet = [];
        });
        this.lastFoundWords = [];

        this.currentTurnIndex = this.players.findIndex((p) => !p.isSpectator && p.lives > 0);
        this.startNewTurn();
    }

    // ── Turn Logic ────────────────────────────────────────────────
    private startNewTurn(isSuccess = false) {
        if (this.state !== "PLAYING") return;

        const { syllable, partCount, hintParts } = this.generateSyllableWithMetadata();
        this.currentSyllable = syllable;
        this.currentSyllablePartCount = partCount;
        this.currentSyllableHintParts = hintParts;
        
        // JKLM Logic: If it was a success, we might want to carry over time OR reset to max.
        // For now, we reset to max, but respect the minTurnDuration "bump" if we were to implement carry-over.
        // Standard behavior: Reset to turnTime.
        this.timeLeft = this.config.turnTime;
        
        // Clean typing for everyone on new turn
        this.io.to(this.id).emit("bomb:typing-reset");

        // 1. Start Clock (This cleans up previous intervals/timeouts)
        this.startTimer();

        // 2. Sync
        this.syncState();

        // 3. Bot logic (MUST BE AFTER startTimer to avoid immediate clearing)
        const currentPlayer = this.players[this.currentTurnIndex];
        if (currentPlayer?.isBot && currentPlayer.isConnected) {
            const delay = 1500 + Math.random() * 2500;
            if (this.botTimeout) clearTimeout(this.botTimeout);
            this.botTimeout = setTimeout(() => this.handleBotTurn(), delay);
        }
    }

    public handleTyping(socketId: string, text: string) {
        if (this.state !== "PLAYING") return;
        const player = this.players.find(p => p.id === socketId);
        if (!player || player.isSpectator || player.lives <= 0) return;

        // Broadcast typing to everyone else
        this.io.to(this.id).emit("bomb:typing-update", {
            playerId: socketId,
            text: text.substring(0, 30) // Limit length
        });
    }

    private handleBotTurn() {
        if (this.state !== "PLAYING") return;
        const current = this.players[this.currentTurnIndex];
        if (!current?.isBot) return;

        const syllable = SigilBombRoom.normalize(this.currentSyllable);
        const dict = this.getActiveDictionary();
        const possible = dict.filter(
            (w) => w.includes(syllable) && !this.usedWordsInSession.has(w)
        );

        if (possible.length > 0) {
            const word = possible[Math.floor(Math.random() * possible.length)];
            this.submitWord(current.id, word);
        }
        // If no word found, bot just lets the timer run out (explosion)
    }

    private generateSyllableWithMetadata(): { syllable: string; partCount: number; hintParts: string[] } {
        const dict = this.getActiveDictionary();
        this.currentSyllableCategory = null;

        if (!SigilBombRoom.dictionaryLoaded || dict.length === 0) {
            return { syllable: "RA", partCount: 1, hintParts: [] };
        }

        let syllable = "";
        let selectedWord = "";
        let attempts = 0;
        
        while (attempts < 100) {
            selectedWord = dict[Math.floor(Math.random() * dict.length)];
            if (selectedWord.length < 3) { attempts++; continue; }
            const len = Math.random() > 0.7 ? 3 : 2;
            const start = Math.floor(Math.random() * (selectedWord.length - len + 1));
            syllable = selectedWord.substring(start, start + len);
            
            if (syllable.length >= 2 && dict.some(w => w.includes(syllable))) {
                this.currentSyllableCategory = SigilBombRoom.dictionaryCategories[selectedWord] || null;
                if (!this.currentSyllableCategory && this.config.dictionaryMode === "dofus") {
                    this.currentSyllableCategory = "Lore Dofus";
                }
                break;
            }
            attempts++;
        }

        syllable = syllable || "RA";
        
        // Metadata
        const parts = SigilBombRoom.deconstructedWords.get(selectedWord) || [selectedWord];
        const partCount = parts.length;
        let hintParts: string[] = [];
        
        if (partCount > 1) {
            // Pick 2 random parts as hints
            const indices = Array.from({ length: partCount }, (_, i) => i);
            const shuffled = indices.sort(() => 0.5 - Math.random());
            const selectedIndices = shuffled.slice(0, 2).sort((a,b) => a - b);
            
            hintParts = parts.map((p, i) => selectedIndices.includes(i) ? p : "");
        }

        return { syllable, partCount, hintParts };
    }

    // ── Timer ─────────────────────────────────────────────────────
    private startTimer() {
        this.stopTimer();
        this.tickInterval = setInterval(() => {
            this.timeLeft--;
            // Emit a lightweight tick (not full sync) so the client timer updates every second
            this.io.to(this.id).emit("bomb:tick", { timeLeft: this.timeLeft });
            if (this.timeLeft <= 0) this.handleExplosion();
        }, 1000);
    }

    private stopTimer() {
        if (this.tickInterval) { clearInterval(this.tickInterval); this.tickInterval = null; }
        if (this.botTimeout)   { clearTimeout(this.botTimeout);  this.botTimeout = null; }
    }

    // ── Explosion ─────────────────────────────────────────────────
    private handleExplosion() {
        this.stopTimer();
        const current = this.players[this.currentTurnIndex];
        const syllable = SigilBombRoom.normalize(this.currentSyllable);

        // Find a valid hint word that wasn't used yet
        const dict = this.getActiveDictionary();
        let hintWord = dict.find(
            (w) => w.includes(syllable) && !this.usedWordsInSession.has(w)
        ) || null;

        // Decouple hint word if compound
        if (hintWord) {
            const parts = SigilBombRoom.deconstructedWords.get(hintWord);
            if (parts) {
                hintWord = parts.join(" ");
            }
        }

        if (current && !current.isSpectator && current.lives > 0) {
            current.lives--;
            this.io.to(this.id).emit("bomb:explosion", {
                playerId: current.id,
                playerName: current.userName,
                lives: current.lives,
                syllable: this.currentSyllable,
                hintWord, // Word they could have said
            });
        }

        const participants = this.players.filter((p) => !p.isSpectator);
        const survivors = participants.filter((p) => p.lives > 0);

        // Win Condition: 
        // 1. More than one player started, but only 1 (or 0) remains.
        // 2. Or no one remains.
        const shouldEnd = (participants.length > 1 && survivors.length <= 1) || (survivors.length === 0);

        if (shouldEnd) {
            logger.info(`[SigilBomb:${this.id}] Ending game (Survivors: ${survivors.length})`);
            this.endGame();
        } else {
            this.nextTurn();
        }
    }

    private nextTurn() {
        let idx = (this.currentTurnIndex + 1) % this.players.length;
        for (let i = 0; i < this.players.length; i++) {
            const p = this.players[idx];
            if (p && !p.isSpectator && p.lives > 0 && p.isConnected) {
                this.currentTurnIndex = idx;
                this.startNewTurn();
                return;
            }
            idx = (idx + 1) % this.players.length;
        }
        this.endGame();
    }

    // ── Submit Word ───────────────────────────────────────────────
    public submitWord(socketId: string, word: string) {
        if (this.state !== "PLAYING") return;
        const current = this.players[this.currentTurnIndex];
        if (!current || current.id !== socketId || current.lives <= 0) return;

        // Normalize and remove internal spaces for dictionary check
        let normalizedWord = SigilBombRoom.normalize(word);
        const glueWord = normalizedWord.replace(/\s+/g, "");
        const normalizedSyllable = SigilBombRoom.normalize(this.currentSyllable);

        // 1. Must contain syllable
        if (!normalizedWord.includes(normalizedSyllable)) {
            this.io.to(socketId).emit("bomb:word-error", {
                message: `Le mot doit contenir "${this.currentSyllable}" !`,
            });
            return;
        }

        // 2. Must not have been used already
        if (this.usedWordsInSession.has(glueWord)) {
            this.io.to(socketId).emit("bomb:word-error", { message: "Déjà utilisé !" });
            return;
        }

        // 3. Must be in dictionary or whitelist
        const dict = this.getActiveDictionary();
        const isValid = dict.includes(glueWord) || ALWAYS_VALID.has(glueWord);
        if (!isValid) {
            this.io.to(socketId).emit("bomb:word-error", {
                message: this.config.dictionaryMode === "mixed" 
                    ? "Mot inconnu au dictionnaire !" 
                    : "Ce mot n'existe pas dans le monde des Douze !",
            });
            return;
        }

        // ── SUCCESS ──
        this.usedWordsInSession.add(glueWord);
        normalizedWord = glueWord; // Use the glued version for internal tracking if needed
        current.wordsFound++;

        // Add to history
        this.lastFoundWords.unshift({ 
            word: normalizedWord, 
            playerName: current.userName, 
            playerId: current.id 
        });
        if (this.lastFoundWords.length > 5) this.lastFoundWords.pop();

        // Track alphabet
        for (const char of normalizedWord) {
            if (char >= "A" && char <= "Z" && !current.alphabet.includes(char)) {
                current.alphabet.push(char);
            }
        }
        // Bonus life on full alphabet
        if (current.alphabet.length === 26) {
            current.lives++;
            current.alphabet = [];
            this.io.to(this.id).emit("bomb:bonus-life", { playerId: current.id });
        }

        this.io.to(this.id).emit("bomb:word-success", {
            word: normalizedWord,
            playerId: current.id,
        });

        // Safety bump: If we had a carry-over system, we'd use minTurnDuration here.
        // Since we reset to full, we just go to next turn.
        this.stopTimer();
        this.nextTurn();
    }

    // ── End Game ─────────────────────────────────────────────────
    private endGame() {
        try {
            this.state = "GAME_END";
            this.stopTimer();

            const participants = this.players.filter((p) => !p.isSpectator);
            const survivors = participants.filter((p) => p.lives > 0);
            
            // Winner is the last survivor, or the person with most words if everyone died
            const winner = survivors[0] || [...participants].sort((a, b) => b.wordsFound - a.wordsFound)[0];

            // Full leaderboard sorted by rank (wordsFound desc)
            const leaderboard = [...participants]
                .sort((a, b) => (b.wordsFound - a.wordsFound))
                .map((p, i) => ({
                    rank: i + 1,
                    id: p.id,
                    name: p.userName,
                    avatar: p.userAvatar,
                    wordsFound: p.wordsFound,
                    lives: p.lives,
                    isBot: p.isBot,
                }));

            logger.info(`[SigilBomb:${this.id}] Game Ended. Winner: ${winner?.userName || 'None'}`);

            // Emit explicit event then sync full state
            this.io.to(this.id).emit("bomb:game-end", {
                winnerId: winner?.id,
                winnerName: winner?.userName,
                wordsFound: winner?.wordsFound,
                leaderboard,
            });

            this.syncState();
        } catch (error) {
            logger.error(`[SigilBomb:${this.id}] Error in endGame:`, error as any);
            // Emergency fallback to Lobby to avoid bricking the room
            this.resetToLobby();
        }
    }

    // ── Restart ───────────────────────────────────────────────────
    public resetToLobby() {
        this.stopTimer();
        this.state = "LOBBY";
        this.currentSyllable = "";
        this.currentSyllableCategory = null;
        this.currentTurnIndex = 0;
        this.timeLeft = 0;
        this.usedWordsInSession.clear();
        // Keep connected players, reset stats
        this.players = this.players.filter((p) => p.isConnected || p.isBot);
        this.players.forEach((p) => {
            p.lives = this.config.startingLives;
            p.wordsFound = 0;
            p.isReady = p.isBot || p.id === this.hostId;
        });
        // Reassign host if needed
        if (!this.players.find((p) => p.id === this.hostId && p.isConnected)) {
            const next = this.players.find((p) => p.isConnected && !p.isBot);
            if (next) { 
                this.hostId = next.id; 
                this.hostUserId = next.userId || null;
                next.isReady = true; 
            }
        }
        this.syncState();
    }

    // ── State Sync ────────────────────────────────────────────────
    public syncState() {
        this.io.to(this.id).emit("bomb:sync", {
            id: this.id,
            state: this.state,
            players: this.players,
            hostId: this.hostId,
            config: this.config,
            currentSyllable: this.currentSyllable,
            currentSyllableCategory: this.currentSyllableCategory,
            currentSyllablePartCount: this.currentSyllablePartCount,
            currentSyllableHintParts: this.currentSyllableHintParts,
            currentTurnIndex: this.currentTurnIndex,
            timeLeft: this.timeLeft,
            lastFoundWords: this.lastFoundWords,
        });
    }

    // ── Public Getters ────────────────────────────────────────────
    public getPublicInfo() {
        const host = this.players.find((p) => p.id === this.hostId);
        return {
            roomId: this.id,
            playerCount: this.players.length,
            state: this.state,
            hostName: host?.userName || "Inconnu",
        };
    }

    public getPlayers() { return this.players; }
    public getState()   { return this.state;   }
}

import { Server, Socket } from "socket.io";
import { redis } from "@/lib/redis";
import { GarticRoom, RoomConfig } from "./Room";
import { GarticDrawSchema, GarticTextSchema } from "../../websocket/schemas";

function generateShortId() {
    return "PHONE-" + Math.random().toString(36).substring(2, 6).toUpperCase();
}

export class GameManager {
    private rooms = new Map<string, GarticRoom>();
    private userToRoom = new Map<string, string>(); // userId -> roomId

    constructor(private io: Server) { }

    public registerSocket(socket: Socket) {
        socket.on("gartic:room:create", (config) => this.createRoom(socket, config));
        socket.on("gartic:room:join", ({ roomId, playerObj }) => this.joinRoom(socket, roomId, playerObj));
        socket.on("gartic:room:leave", () => this.handleLeaveRoom(socket));
        socket.on("gartic:room:list", () => this.handleRoomList(socket));
        
        socket.on("gartic:text:submit", ({ text }) => this.handleTextSubmit(socket, text));
        socket.on("gartic:draw:submit", ({ dataUrl }) => this.handleDrawSubmit(socket, dataUrl));
        
        socket.on("gartic:game:start", () => this.startGame(socket));
        socket.on("gartic:room:delete", () => this.handleDeleteRoom(socket));
        socket.on("gartic:reveal:next", () => this.handleRevealNext(socket));
    }

    private async delSocketData(socketId: string) {
        try {
            await redis.del(`socket:gartic:${socketId}:room`);
            await redis.del(`socket:gartic:${socketId}:user`);
        } catch (e) {}
    }

    private async setSocketData(socketId: string, roomId: string, userId: string) {
        try {
            await redis.set(`socket:gartic:${socketId}:room`, roomId, "EX", 3600);
            await redis.set(`socket:gartic:${socketId}:user`, userId, "EX", 3600);
        } catch (e) {}
    }

    private async handleRoomList(socket: Socket) {
        const guildId = (socket.handshake.query.guildId as string) || "global";
        const rooms: any[] = [];
        this.rooms.forEach((room, roomId) => {
            if (!room.isEmpty() && room.getGuildId() === guildId) {
                rooms.push(room.getPublicInfo(roomId));
            }
        });
        socket.emit("gartic:room:list", rooms);
    }

    private async broadcastRoomList(guildId?: string) {
        if (!guildId) return;
        const rooms: any[] = [];
        this.rooms.forEach((room, roomId) => {
            if (!room.isEmpty() && room.getGuildId() === guildId) {
                rooms.push(room.getPublicInfo(roomId));
            }
        });
        this.io.to(`guild:${guildId}`).emit("gartic:room:list", rooms);

        // Internal Redis broadcast for Dashboard EventTicker
        if (guildId !== "global") {
            await redis.set(`guild:${guildId}:gartic:rooms`, JSON.stringify(rooms), "EX", 3600);
        }
    }

    private deleteRoomInternal(roomId: string) {
        const room = this.rooms.get(roomId);
        if (room) {
            const hostId = room.getHostId();
            const guildId = room.getGuildId();
            room.destroy();
            this.rooms.delete(roomId);
            if (hostId) {
                this.userToRoom.delete(hostId);
                redis.del(`user:${hostId}:gartic:room`).catch(() => {});
            }
            this.broadcastRoomList(guildId);
        }
    }

    private async createRoom(socket: Socket, config: any) {
        try {
            const userId = config.userId || socket.id;
            const guildId = socket.handshake.query.guildId as string;
            
            // 1. One room max per user
            const existingRoomId = this.userToRoom.get(userId);
            if (existingRoomId && this.rooms.has(existingRoomId)) {
                // If the user already has a room, destroy it to avoid "infinites salons"
                console.log(`[GarticManager] 🧹 Cleaning up old room ${existingRoomId} for user ${userId}`);
                this.deleteRoomInternal(existingRoomId);
            }

            const roomId = generateShortId();
            const room = new GarticRoom(this.io, { ...config, id: roomId, guildId });
            this.rooms.set(roomId, room);
            this.userToRoom.set(userId, roomId);

            await redis.set(`user:${userId}:gartic:room`, roomId, "EX", 7200);
            socket.emit("gartic:room:created", { roomId });
            
            // Join host
            await this.joinRoom(socket, roomId, { 
                userName: config.userName || config.pseudo,
                userId,
                userAvatar: config.userAvatar
            });
        } catch (e) {
            console.error("[GarticManager] createRoom error:", e);
        }
    }

    private async joinRoom(socket: Socket, roomId: string, playerObj: any) {
        const room = this.rooms.get(roomId);
        if (!room) {
            socket.emit("gartic:error", { message: "Salon introuvable ou fermé." });
            return;
        }

        const socketGuildId = (socket.handshake.query.guildId as string) || "global";
        if (room.getGuildId() !== socketGuildId) {
            console.warn(`[GarticManager] ❌ Guild mismatch: ${socket.id} tried to join ${roomId}`);
            socket.emit("gartic:error", { message: "Ce salon n'appartient pas à votre guilde." });
            return;
        }

        const userId = playerObj.userId || socket.id;
        socket.join(roomId);
        await this.setSocketData(socket.id, roomId, userId);

        // SECURITY: Force spectator if game is already active
        const isSpectator = !!playerObj.isSpectator || !room.isInLobby();

        room.addPlayer(socket, playerObj.userName || playerObj.pseudo, userId, playerObj.userAvatar || playerObj.avatarUrl, isSpectator);
        this.broadcastRoomList(room.getGuildId());
    }

    private async handleLeaveRoom(socket: Socket) {
        const roomId = await redis.get(`socket:gartic:${socket.id}:room`);
        const userId = await redis.get(`socket:gartic:${socket.id}:user`);
        
        if (roomId) {
            socket.leave(roomId);
            const room = this.rooms.get(roomId);
            if (room) {
                const guildId = room.getGuildId();
                room.handlePlayerDisconnect(socket.id);
                if (room.isEmpty()) {
                    room.destroy();
                    this.rooms.delete(roomId);
                }
                this.broadcastRoomList(guildId);
            }
        }
        
        if (userId) {
            const activeRoomId = this.userToRoom.get(userId);
            if (activeRoomId === roomId) {
                this.userToRoom.delete(userId);
                await redis.del(`user:${userId}:gartic:room`);
            }
        }
        await this.delSocketData(socket.id);
    }

    public async handleDisconnect(socket: Socket) {
        try {
            const roomId = await redis.get(`socket:gartic:${socket.id}:room`);
            const userId = await redis.get(`socket:gartic:${socket.id}:user`);
            
            if (roomId) {
                const room = this.rooms.get(roomId);
                if (room) {
                    const guildId = room.getGuildId();
                    room.handlePlayerDisconnect(socket.id);
                    if (room.isEmpty()) {
                        setTimeout(async () => {
                            const refreshedRoom = this.rooms.get(roomId);
                            if (refreshedRoom && refreshedRoom.isEmpty()) {
                                refreshedRoom.destroy();
                                this.rooms.delete(roomId);
                                this.broadcastRoomList(guildId);
                            }
                        }, 30000);
                    } else {
                        this.broadcastRoomList(guildId);
                    }
                }
            }

            if (userId && roomId) {
                 const activeRoomId = await redis.get(`user:${userId}:gartic:room`);
                 if (activeRoomId === roomId) {
                     await redis.del(`user:${userId}:gartic:room`);
                 }
            }
            await this.delSocketData(socket.id);
        } catch (e) {}
    }

    private async handleTextSubmit(socket: Socket, text: string) {
        const validation = GarticTextSchema.safeParse({ text });
        if (!validation.success) return;

        const roomId = await redis.get(`socket:gartic:${socket.id}:room`);
        if (roomId) {
            const room = this.rooms.get(roomId);
            if (room && !room.isSpectator(socket.id)) {
                room.handleTextSubmit(socket, text);
            }
        }
    }
    
    private async handleDrawSubmit(socket: Socket, dataUrl: string) {
        const validation = GarticDrawSchema.safeParse({ dataUrl });
        if (!validation.success) return;

        const roomId = await redis.get(`socket:gartic:${socket.id}:room`);
        if (roomId) {
            const room = this.rooms.get(roomId);
            if (room && !room.isSpectator(socket.id)) {
                room.handleDrawSubmit(socket, dataUrl);
            }
        }
    }

    private async startGame(socket: Socket) {
        const roomId = await redis.get(`socket:gartic:${socket.id}:room`);
        const room = roomId ? this.rooms.get(roomId) : null;
        if (room) {
            if (room.isHost(socket.id)) {
                room.startGame();
            } else {
                console.warn(`[GarticManager] Player ${socket.id} tried to start game in room ${roomId} but is not host.`);
                socket.emit("gartic:error", { message: "Seul l'hôte peut lancer la partie." });
            }
        }
    }

    private async handleRevealNext(socket: Socket) {
        const roomId = await redis.get(`socket:gartic:${socket.id}:room`);
        if (roomId) {
            const room = this.rooms.get(roomId);
            if (room && room.isHost(socket.id)) {
                room.handleRevealNext();
            }
        }
    }

    private async handleDeleteRoom(socket: Socket) {
        try {
            const roomId = await redis.get(`socket:gartic:${socket.id}:room`);
            if (!roomId) return;
            const room = this.rooms.get(roomId);
            if (room) {
                const hostId = room.getHostId();
                this.io.to(roomId).emit("gartic:error", { message: "Le salon a été fermé par l'hôte." });
                room.destroy();
                this.rooms.delete(roomId);
                if (hostId) await redis.del(`user:${hostId}:gartic:room`);
                this.broadcastRoomList(room.getGuildId());
            }
        } catch (e) {}
    }
}

import { Server, Socket } from "socket.io";
import { redis } from "@/lib/redis";
import { createActor, Snapshot, Actor } from "xstate";
import { garticMachine, GameContext, Player } from "./StateMachine";
import { StrokeData, Album, GamePhase, GameMode } from "../../../types/socket-events";
import { db } from "@/lib/prisma";

export interface RoomConfig {
    id: string;
    maxPlayers: number;
    maxRounds: number;
    drawTime: number;
    mode: GameMode;
}

export class GarticRoom {
    private state!: GameContext;
    private machine: Actor<typeof garticMachine>;
    private io: Server;
    private timers: Map<string, NodeJS.Timeout> = new Map();
    private guildId: string;

    constructor(io: Server, config: RoomConfig & { guildId: string }) {
        this.io = io;
        this.guildId = config.guildId;
        this.machine = createActor(garticMachine, {
            input: { roomId: config.id, ...config },
        });
        this.machine.start();
        this.machine.subscribe(this.onStateChange.bind(this));
    }

    public getGuildId() {
        return this.guildId;
    }

    private async onStateChange(snapshot: any) {
        const snap = snapshot;
        const phase = snap.value as GamePhase;
        this.state = snap.context;

        // Emit general state to everyone
        const basicState = {
            id: this.state.roomId,
            phase,
            currentRound: this.state.currentRound,
            maxRounds: this.state.maxRounds,
            timer: this.state.timer,
            maxTimer: this.state.maxTimer,
            hostId: this.state.hostId,
            players: Array.from(this.state.players.values()).map(p => ({
                id: p.id,
                username: p.username,
                dofusClass: p.dofusClass,
                score: p.score,
                isHost: p.id === this.state.hostId || p.userId === this.state.hostId,
                hasSubmitted: this.state.submittedThisRound.has(p.id),
                userAvatar: p.userAvatar,
                isSpectator: p.isSpectator
            })),
        };
        
        if (phase === "REVEAL" || phase === "SCORES") {
            (basicState as any).albums = Array.from(this.state.chains.entries()).map(([ownerId, entries]) => ({
                owner: { username: this.state.players.get(ownerId)?.username || "Inconnu" },
                entries: entries.map(e => ({
                    ...e,
                    author: { username: this.state.players.get(e.playerId)?.username || "Inconnu" }
                }))
            }));
            if (phase === "REVEAL") (basicState as any).revealIndex = this.state.revealIndex;
        }

        if (phase === "SCORES") {
            // HALL OF FAME: Save stats
            const validPlayers = Array.from(this.state.players.values()).filter(p => !p.isSpectator && p.userId);
            if (validPlayers.length > 1) {
                for (const p of validPlayers) {
                    try {
                        const drawings = Array.from(this.state.chains.values())
                            .flat()
                            .filter(e => e.type === "drawing" && e.playerId === p.id).length;
                        const guesses = Array.from(this.state.chains.values())
                             .flat()
                             .filter(e => e.type === "text" && e.playerId === p.id).length;

                        await db.garticPlayerStats.upsert({
                            where: { userId: p.userId! },
                            create: {
                                userId: p.userId!,
                                totalGames: 1,
                                drawingsCreated: drawings,
                                correctGuesses: guesses, // For Phone, all text entries are "guesses" in the stats sense
                            },
                            update: {
                                totalGames: { increment: 1 },
                                drawingsCreated: { increment: drawings },
                                correctGuesses: { increment: guesses }
                            }
                        });
                    } catch (err) {
                        console.error(`[GarticRoom] Error saving stats for ${p.username}:`, err);
                    }
                }
            }
        }

        // For each player, send custom task data
        this.state.players.forEach(player => {
            const chainId = this.state.assignments.get(player.id);
            let task = null;

            if (chainId && (phase === "DRAWING" || phase === "GUESSING")) {
                const chain = this.state.chains.get(chainId) || [];
                // IMPORTANT: The task is always the entry from the PREVIOUS round
                const taskEntry = chain[this.state.currentRound - 1]; 
                if (taskEntry) {
                    task = {
                        type: taskEntry.type,
                        content: taskEntry.content
                    };
                }
            }

            this.io.to(player.id).emit("gartic:state:update", {
                ...basicState,
                task
            });
        });

        // Trigger phase-specific countdown
        if (["STARTING", "WRITING", "DRAWING", "GUESSING", "INTERMISSION"].includes(phase)) {
            if (!this.timers.has(`timer_${phase}`)) {
                this.startCountdown(this.state.maxTimer, phase);
            }
        }
    }

    public addPlayer(socket: Socket, userName: string = "Anonyme", userId?: string, userAvatar?: string, isSpectator: boolean = false) {
        this.machine.send({
            type: "PLAYER_JOIN",
            player: {
                id: socket.id,
                userId,
                username: userName,
                userAvatar,
                dofusClass: (Math.floor(Math.random() * 18) + 1).toString(),
                isReady: false,
                score: 0,
                isSpectator
            }
        });
    }

    public startGame() {
        const activePlayers = Array.from(this.state.players.values()).filter(p => !p.isSpectator);
        if (activePlayers.length < 1) {
            this.io.to(this.state.roomId).emit("gartic:error", { message: "Il faut au moins 1 joueur (hors spectateurs) !" });
            return;
        }
        this.machine.send({ type: "START_GAME" });
    }

    public isHost(socketId: string): boolean {
        const player = this.state.players.get(socketId);
        if (!player) return false;
        return this.state.hostId === player.id || this.state.hostId === player.userId;
    }

    public isSpectator(socketId: string): boolean {
        return this.state?.players.get(socketId)?.isSpectator || false;
    }

    public handleTextSubmit(socket: Socket, text: string) {
        this.machine.send({ type: "SUBMIT_TEXT", playerId: socket.id, text });
    }

    public handleDrawSubmit(socket: Socket, dataUrl: string) {
        // SECURITY: Limit drawing size to 1MB to prevent DOS (RAM exhaustion)
        if (dataUrl && dataUrl.length > 1024 * 1024) {
            console.warn(`[GarticRoom:${this.state.roomId}] ⚠️ Drawing rejected: Payload too large (${Math.round(dataUrl.length / 1024)}KB)`);
            socket.emit("gartic:error", { message: "Le dessin est trop lourd ! (Max 1Mo)" });
            return;
        }
        this.machine.send({ type: "SUBMIT_DRAW", playerId: socket.id, dataUrl });
    }

    public getHostId() {
        return this.state.hostId;
    }

    public isEmpty() {
        return (this.state?.players?.size ?? 0) === 0;
    }

    public isInLobby(): boolean {
        return this.machine.getSnapshot().value === "LOBBY";
    }

    public getPublicInfo(roomId: string) {
        const host = Array.from(this.state.players.values()).find(p => p.id === this.state.hostId || p.userId === this.state.hostId);
        const players = Array.from(this.state.players.values());
        return {
            roomId,
            playerCount: players.filter(p => !p.isSpectator).length,
            spectatorCount: players.filter(p => p.isSpectator).length,
            maxPlayers: this.state?.maxPlayers ?? 14,
            mode: this.state?.mode ?? "NORMAL",
            hostName: host?.username || "Hôte"
        };
    }

    public handleRevealNext() {
        this.machine.send({ type: "NEXT_REVEAL" });
    }

    public handlePlayerDisconnect(socketId: string) {
        this.machine.send({ type: "PLAYER_LEAVE", playerId: socketId });
    }

    public destroy() {
        this.timers.forEach((t) => clearInterval(t));
        this.machine.stop();
    }

    private sendAlbums(ctx: GameContext) {
        const albums = Array.from(ctx.chains.entries()).map(([ownerId, entries]) => ({
            owner: ctx.players.get(ownerId)?.username || "Inconnu",
            entries: entries.map(e => ({
                ...e,
                author: ctx.players.get(e.playerId)?.username || "Inconnu"
            }))
        }));

        this.io.to(ctx.roomId).emit("gartic:reveal:ready", { albums });
    }

    private startCountdown(duration: number, phase: string) {
        const key = `timer_${phase}`;
        console.log(`[Room:${this.state.roomId}] startCountdown for ${phase} with duration: ${duration} (maxTimer: ${this.state.maxTimer})`);
        
        // Clean up ALL active timers for this room to prevent memory leaks
        this.timers.forEach((t) => clearInterval(t));
        this.timers.clear();

        let remaining = duration;
        const interval = setInterval(() => {
            remaining--;
            try {
                this.machine.send({ type: "TICK", remaining });
                // console.log(`[Room:${this.state.roomId}] TICK ${phase}: ${remaining}`);
            } catch (e) {
                 console.error(`[Room:${this.state.roomId}] TICK error:`, e);
            }

            if (remaining <= 0) {
                console.log(`[Room:${this.state.roomId}] Timer ${phase} ended, sending TIMER_END_${phase}`);
                clearInterval(interval);
                this.timers.delete(key);
                this.machine.send({ type: `TIMER_END_${phase}` as any });
            }
        }, 1000);

        this.timers.set(key, interval);
        this.machine.send({ type: "TICK", remaining });
    }
}

import { createMachine, assign } from "xstate";
import { GamePhase, GameMode, AlbumEntry, StrokeData, PublicPlayer } from "../../../types/socket-events";
import { getDofusPrompt } from "../../game/PromptBank";

export interface ChainEntry {
    type: "text" | "drawing";
    content: string;
    playerId: string; // The person who CREATED this entry
    timestamp: number;
}

export interface Player {
    id: string; // Socket ID
    userId?: string;
    username: string;
    userAvatar?: string;
    dofusClass: string;
    isReady: boolean;
    score: number;
    isSpectator?: boolean;
}

export interface GameContext {
    roomId: string;
    players: Map<string, Player>;
    currentRound: number; // Also used as 'step' in the chain
    maxRounds: number;
    timer: number;
    maxTimer: number; // For progress bar/camembert
    drawTime: number; // From config
    mode: GameMode;
    maxPlayers: number;
    hostId: string | null;
    
    // Gartic Phone Specific
    chains: Map<string, ChainEntry[]>; // chainId (original author) -> entries[]
    assignments: Map<string, string>; // playerId -> chainId (what they are working on NOW)
    submittedThisRound: Set<string>; // playerId
    
    // Results
    scores: Map<string, number>;
    revealIndex: number; // Current album being shown in the gallery
}

// ... existing helper (no change) ...
function computeAssignments(players: Player[], step: number): Map<string, string> {
    const activePlayers = players.filter(p => !p.isSpectator);
    const N = activePlayers.length;
    const assignments = new Map<string, string>();
    activePlayers.forEach((player, index) => {
        const chainIndex = (index + step) % N;
        const targetPlayer = activePlayers[chainIndex];
        assignments.set(player.id, targetPlayer.id);
    });
    return assignments;
}

export const garticMachine = createMachine({
    types: {} as {
        context: GameContext;
        input: Partial<GameContext> & { maxPlayers?: number };
        events: 
          | { type: "START_GAME" }
          | { type: "SUBMIT_TEXT"; playerId: string; text: string }
          | { type: "SUBMIT_DRAW"; playerId: string; dataUrl: string }
          | { type: "TICK"; remaining: number }
          | { type: "TIMER_END_STARTING" }
          | { type: "TIMER_END_WRITING" }
          | { type: "TIMER_END_DRAWING" }
          | { type: "TIMER_END_GUESSING" }
          | { type: "TIMER_END_INTERMISSION" }
          | { type: "PLAYER_JOIN"; player: Player }
          | { type: "PLAYER_LEAVE"; playerId: string }
          | { type: "NEXT_REVEAL" }
          | { type: "PLAY_AGAIN" };
    },
    id: "sigilGartic",
    initial: "LOBBY",
    context: ({ input }) => ({
        roomId: input.roomId ?? "",
        players: new Map(),
        currentRound: 0,
        maxRounds: input.maxRounds ?? 3,
        maxPlayers: input.maxPlayers ?? 14,
        timer: 0,
        maxTimer: 0,
        drawTime: input.drawTime ?? 60,
        mode: input.mode ?? "NORMAL",
        hostId: null,
        chains: new Map(),
        assignments: new Map(),
        submittedThisRound: new Set(),
        scores: new Map(),
        revealIndex: 0,
    }),
    states: {
        LOBBY: {
            on: {
                START_GAME: {
                    target: "STARTING",
                    actions: assign({ 
                        currentRound: 0,
                        maxRounds: ({ context }) => Array.from(context.players.values()).filter(p => !p.isSpectator).length,
                        assignments: ({ context }) => computeAssignments(Array.from(context.players.values()), 0),
                        submittedThisRound: new Set(),
                        chains: new Map(),
                        revealIndex: 0,
                    }),
                },
            },
        },
        STARTING: {
            entry: assign({ timer: 5, maxTimer: 5 }),
            on: {
                TIMER_END_STARTING: "WRITING",
            }
        },
        WRITING: {
            entry: assign({ 
                timer: 45, 
                maxTimer: 45 
            }),
            on: {
                SUBMIT_TEXT: {
                    actions: assign({
                        chains: ({ context, event }) => {
                            const newChains = new Map(context.chains);
                            newChains.set(event.playerId, [{
                                type: "text",
                                content: event.text || getDofusPrompt(),
                                playerId: event.playerId,
                                timestamp: Date.now()
                            }]);
                            return newChains;
                        },
                        submittedThisRound: ({ context, event }) => {
                            const newSet = new Set(context.submittedThisRound);
                            newSet.add(event.playerId);
                            return newSet;
                        }
                    })
                },
                TIMER_END_WRITING: "INTERMISSION",
            },
            always: {
                target: "INTERMISSION",
                guard: ({ context }) => {
                    // Only wait for players who are actually in the assignment pool for this game
                    const validParticipants = Array.from(context.players.values()).filter(p => !p.isSpectator);
                    const participantCount = validParticipants.length;
                    return participantCount > 0 && context.submittedThisRound.size >= participantCount;
                }
            }
        },
        INTERMISSION: {
            entry: assign({ timer: 5, maxTimer: 5 }),
            on: {
                TIMER_END_INTERMISSION: [
                    { target: "REVEAL", guard: ({ context }) => context.currentRound >= context.maxRounds - 1 },
                    { 
                        target: "PREPARE_NEXT",
                        guard: ({ context }) => context.currentRound < context.maxRounds - 1
                    }
                ]
            }
        },
        PREPARE_NEXT: {
            entry: assign({
                currentRound: ({ context }) => context.currentRound + 1,
                submittedThisRound: new Set(),
                assignments: ({ context }) => computeAssignments(Array.from(context.players.values()), context.currentRound + 1)
            }),
            always: [
                { target: "DRAWING", guard: ({ context }) => context.currentRound % 2 !== 0 },
                { target: "GUESSING", guard: ({ context }) => context.currentRound % 2 === 0 }
            ]
        },
        DRAWING: {
            entry: assign({ 
                timer: 60, 
                maxTimer: 60 
            }),
            on: {
                SUBMIT_DRAW: {
                    actions: assign({
                        chains: ({ context, event }) => {
                            const newChains = new Map(context.chains);
                            const assignedChainId = context.assignments.get(event.playerId);
                            if (assignedChainId) {
                                const chain = [...(newChains.get(assignedChainId) || [])];
                                chain.push({
                                    type: "drawing",
                                    content: event.dataUrl,
                                    playerId: event.playerId,
                                    timestamp: Date.now()
                                });
                                newChains.set(assignedChainId, chain);
                            }
                            return newChains;
                        },
                        submittedThisRound: ({ context, event }) => {
                            const newSet = new Set(context.submittedThisRound);
                            newSet.add(event.playerId);
                            return newSet;
                        }
                    })
                },
                TIMER_END_DRAWING: "INTERMISSION",
            },
            always: {
                target: "INTERMISSION",
                guard: ({ context }) => {
                    // Only count players who were assigned a chain this round
                    const assignedPlayerCount = context.assignments.size;
                    return assignedPlayerCount > 0 && context.submittedThisRound.size >= assignedPlayerCount;
                }
            }
        },
        GUESSING: {
            entry: assign({ 
                timer: 45, 
                maxTimer: 45 
            }),
            on: {
                SUBMIT_TEXT: {
                    actions: assign({
                        chains: ({ context, event }) => {
                            const newChains = new Map(context.chains);
                            const assignedChainId = context.assignments.get(event.playerId);
                            if (assignedChainId) {
                                const chain = [...(newChains.get(assignedChainId) || [])];
                                chain.push({
                                    type: "text",
                                    content: event.text || "...",
                                    playerId: event.playerId,
                                    timestamp: Date.now()
                                });
                                newChains.set(assignedChainId, chain);
                            }
                            return newChains;
                        },
                        submittedThisRound: ({ context, event }) => {
                            const newSet = new Set(context.submittedThisRound);
                            newSet.add(event.playerId);
                            return newSet;
                        }
                    })
                },
                TIMER_END_GUESSING: "INTERMISSION",
            },
            always: {
                target: "INTERMISSION",
                guard: ({ context }) => {
                    const assignedPlayerCount = context.assignments.size;
                    return assignedPlayerCount > 0 && context.submittedThisRound.size >= assignedPlayerCount;
                }
            }
        },
        REVEAL: {
            entry: assign({ timer: 0, maxTimer: 0 }),
            on: {
                // Move to next album, or go to SCORES when all albums have been shown
                NEXT_REVEAL: [
                    { 
                        target: "REVEAL", 
                        guard: ({ context }) => context.revealIndex < context.chains.size - 1,
                        actions: assign({ revealIndex: ({ context }) => context.revealIndex + 1 })
                    },
                    { target: "SCORES" }
                ],
                PLAY_AGAIN: "LOBBY"
            }
        },
        SCORES: {
            on: {
                PLAY_AGAIN: {
                    target: "LOBBY",
                    actions: assign({
                        currentRound: 0,
                        revealIndex: 0,
                        submittedThisRound: new Set(),
                        chains: new Map(),
                        assignments: new Map()
                    })
                }
            }
        }
    },
    on: {
        PLAYER_JOIN: {
            actions: assign({
                players: ({ context, event }) => {
                    const newPlayers = new Map(context.players);
                    
                    // If player has a userId, check for existing session and remove old socket entry
                    if (event.player.userId) {
                        const existingEntry = Array.from(newPlayers.entries())
                            .find(([_, p]) => p.userId === event.player.userId);
                        
                        if (existingEntry) {
                            const [oldSocketId] = existingEntry;
                            if (oldSocketId !== event.player.id) {
                                newPlayers.delete(oldSocketId);
                            }
                        }
                    }

                    newPlayers.set(event.player.id, event.player);
                    return newPlayers;
                },
                hostId: ({ context, event }) => context.hostId || event.player.userId || event.player.id
            })
        },
        TICK: {
            actions: assign({
                timer: ({ event }) => event.remaining
            })
        },
        PLAYER_LEAVE: {
            actions: assign({
                players: ({ context, event }) => {
                    const newPlayers = new Map(context.players);
                    newPlayers.delete(event.playerId);
                    return newPlayers;
                },
                // Clean up assignments if a player leaves during a round to avoid getting stuck
                assignments: ({ context, event }) => {
                    const newAssignments = new Map(context.assignments);
                    newAssignments.delete(event.playerId);
                    return newAssignments;
                },
                hostId: ({ context, event }) => {
                    if (context.hostId === event.playerId) {
                         // Pick next player as host (not spectator)
                         const next = Array.from(context.players.values()).find(p => p.id !== event.playerId && !p.isSpectator);
                         return next ? (next.userId || next.id) : null;
                    }
                    return context.hostId;
                }
            })
        }
    }
});

import { Server, Socket } from "socket.io";
import { redis } from "@/lib/redis";
import { GeoguesserRoom } from "./GeoguesserRoom";
import { WorldMapService } from "./WorldMapService";
import { GeoguesserGuessSchema } from "../../websocket/schemas";
import { db } from "@/lib/prisma";

// Simple random ID generator (or reuse DB ID)
function generateShortId() {
    return "GEO-" + Math.random().toString(36).substring(2, 6).toUpperCase();
}

export class GeoguesserManager {
    private rooms = new Map<string, GeoguesserRoom>();
    private syncInterval: NodeJS.Timeout | null = null;

    constructor(private io: Server) { 
        console.log("[GeoguesserManager] 🚀 Initialisé (V1.2 - SOLO ALLOWED)");
        this.startBlacklistSync();
    }

    public registerSocket(socket: Socket) {
        socket.on("geoguesser:room:join", (data) => this.joinRoom(socket, data));
        socket.on("geoguesser:room:leave", () => this.leaveRoom(socket));
        socket.on("geoguesser:game:start", (data) => this.startGame(socket, data));
        socket.on("geoguesser:guess:submit", (data) => this.handleGuess(socket, data));
        socket.on("geoguesser:room:settings", (data) => this.updateSettings(socket, data));
        socket.on("geoguesser:game:next-round", () => this.triggerNextRound(socket));
        socket.on("geoguesser:room:list", () => this.handleRoomList(socket));
        socket.on("geoguesser:map:report", (data) => this.reportMap(socket, data));
    }

    private async updateSettings(socket: Socket, data: any) {
        const roomId = await this.getSocketRoom(socket.id);
        if (!roomId) return;
        const room = this.rooms.get(roomId);
        if (!room || !room.isHost(socket.id)) return;

        if (data.maxRounds) room.setMaxRounds(data.maxRounds);
        if (data.timePerRound) room.setTimePerRound(data.timePerRound);
        if (data.gameMode) room.setGameMode(data.gameMode);
        // Difficulty setting removed
    }

    private async triggerNextRound(socket: Socket) {
        const roomId = await this.getSocketRoom(socket.id);
        if (!roomId) return;
        const room = this.rooms.get(roomId);
        if (!room) return;
        room.triggerNextRound(socket);
    }

    private async setSocketRoom(socketId: string, roomId: string) {
        await redis.set(`socket:${socketId}:georoom`, roomId, "EX", 3600);
    }

    private async getSocketRoom(socketId: string) {
        return await redis.get(`socket:${socketId}:georoom`);
    }

    private async delSocketRoom(socketId: string) {
        await redis.del(`socket:${socketId}:georoom`);
    }

    private async handleRoomList(socket: Socket) {
        const guildId = (socket.handshake.query.guildId as string) || "global";
        const rooms: any[] = [];
        this.rooms.forEach((room, roomId) => {
            if (room.guildId === guildId && !room.isEmpty()) {
                rooms.push(room.getPublicInfo(roomId));
            }
        });
        socket.emit("geoguesser:room:list", rooms);
    }

    private async broadcastRoomList(guildId?: string) {
        if (!guildId) return;
        const rooms: any[] = [];
        this.rooms.forEach((room, roomId) => {
            if (room.guildId === guildId && !room.isEmpty()) {
                rooms.push(room.getPublicInfo(roomId));
            }
        });
        this.io.to(`guild:${guildId}`).emit("geoguesser:room:list", rooms);

        // Internal Redis broadcast for Dashboard EventTicker
        if (guildId !== "global") {
            await redis.set(`guild:${guildId}:geoguesser:rooms`, JSON.stringify(rooms), "EX", 3600);
        }
    }

    private async joinRoom(socket: Socket, data: any) {
        const { roomId, pseudo, userId, avatarUrl, maxRounds, timePerRound } = data;
        const guildId = (socket.handshake.query.guildId as string) || "global";

        let room = this.rooms.get(roomId);
        if (!room) {
            room = new GeoguesserRoom(this.io, {
                id: roomId,
                guildId,
                maxRounds: maxRounds || 5,
                timePerRound: timePerRound || 30
            });
            this.rooms.set(roomId, room);
        } else {
            // SECURITY: Check guild isolation
            if (room.guildId !== guildId) {
                console.warn(`[GeoguesserManager] ❌ Guild mismatch: ${socket.id} tried to join ${roomId}`);
                socket.emit("geoguesser:error", { message: "Ce salon n'appartient pas à votre guilde." });
                return;
            }
        }

        socket.join(roomId);
        await this.setSocketRoom(socket.id, roomId);

        // Geoguesser allows mid-game participation, so we only force spectator if requested
        const isSpectator = !!data.isSpectator;

        room.addPlayer(socket, { 
            userName: pseudo, 
            userId, 
            userAvatar: avatarUrl,
            isSpectator 
        });
        room.handleLateJoin(socket);

        socket.emit("geoguesser:room:joined", { roomId });
        this.broadcastRoomList(guildId);
    }

    private async leaveRoom(socket: Socket) {
        const roomId = await this.getSocketRoom(socket.id);
        if (!roomId) return;

        const room = this.rooms.get(roomId);
        if (room) {
            const guildId = room.guildId;
            room.removePlayer(socket.id);
            socket.leave(roomId);
            await this.delSocketRoom(socket.id);

            if (room.isEmpty()) {
                room.destroy();
                this.rooms.delete(roomId);
            }
            this.broadcastRoomList(guildId);
        }
    }

    private async startGame(socket: Socket, data: any) {
        const { targetMapIds } = data;
        const roomId = await this.getSocketRoom(socket.id);
        console.log(`[Geoguesser] 🚀 Tentative de lancement - Room: ${roomId}, Socket: ${socket.id}`);

        if (!roomId) {
            console.error(`[Geoguesser] ❌ Pas de roomId trouvé en Redis pour le socket ${socket.id}`);
            return;
        }

        const room = this.rooms.get(roomId);
        if (!room) {
            console.error(`[Geoguesser] ❌ Instance de room ${roomId} introuvable en mémoire.`);
            return;
        }

        if (room.isHost(socket.id)) {
            const publicInfo = room.getPublicInfo(roomId);
            const activeCount = room.getPublicInfo(roomId).playerCount;
            
            if (activeCount < 1) {
                console.warn(`[Geoguesser] ⚠️ Lancement refusé : Personne dans la room ${roomId}`);
                socket.emit("geoguesser:error", { message: "Il faut au moins 1 joueur (hors spectateurs) !" });
                return;
            }

            console.log(`[Geoguesser] ✅ Lancement autorisé (Joueurs: ${activeCount})`);
            if (data.maxRounds) room.setMaxRounds(data.maxRounds);
            if (data.timePerRound) room.setTimePerRound(data.timePerRound);
            // Difficulty setting removed
            room.startGame();
        } else {
            console.warn(`[Geoguesser] ⚠️ Le socket ${socket.id} n'est pas l'hôte de la room ${roomId}`);
        }
    }

    private async handleGuess(socket: Socket, data: any) {
        // SECURITY: Validate coordinates
        const validation = GeoguesserGuessSchema.safeParse(data);
        if (!validation.success) {
            console.warn(`[GeoguesserManager] ❌ Invalid guess from ${socket.id}`, validation.error.format());
            return;
        }

        const { x, y, score, distance, round, mapId, worldId } = data;
        const roomId = await this.getSocketRoom(socket.id);
        if (!roomId) return;

        const room = this.rooms.get(roomId);
        if (!room || room.isSpectator(socket.id)) return;

        room.handleGuess(socket, { x, y, score, distance, mapId, worldId } as any);
    }

    public async handleDisconnect(socket: Socket, reason: string) {
        const roomId = await this.getSocketRoom(socket.id);
        if (!roomId) return;

        const room = this.rooms.get(roomId);
        if (room) {
            const guildId = room.guildId;
            room.handlePlayerDisconnect(socket.id, reason);
            await this.delSocketRoom(socket.id);

            if (room.isEmpty()) {
                setTimeout(() => {
                    const currentRoom = this.rooms.get(roomId);
                    if (currentRoom && currentRoom.isEmpty()) {
                        currentRoom.destroy();
                        this.rooms.delete(roomId);
                        this.broadcastRoomList(guildId);
                    }
                }, 10000);
            } else {
                this.broadcastRoomList(guildId);
            }

        } else {
            await this.delSocketRoom(socket.id);
        }
    }

    private async reportMap(socket: Socket, data: any) {
        let mapId = data?.mapId;
        
        // If mapId is missing from data, try to find it from the room state (more secure)
        if (!mapId) {
            const roomId = await this.getSocketRoom(socket.id);
            if (roomId) {
                const room = this.rooms.get(roomId);
                if (room) {
                    mapId = room.getCurrentMapId();
                }
            }
        }

        if (mapId) mapId = Number(mapId);
        
        if (!mapId || isNaN(mapId)) {
            console.warn(`[GeoguesserManager] 🚩 Report ignored: No valid mapId provided and no active room found for ${socket.id}`);
            return;
        }

        try {
            // Use upsert to ensure the singleton exists even if god hasn't visited the dashboard yet
            const config = await db.platformConfig.upsert({
                where: { id: "singleton" },
                update: {},
                create: { id: "singleton" }
            });
            
            const reported = (config.geoguesserReportedMaps as number[]) || [];
            if (!reported.includes(mapId)) {
                reported.push(mapId);
                await db.platformConfig.update({
                    where: { id: "singleton" },
                    data: { geoguesserReportedMaps: reported }
                });
                console.log(`[GeoguesserManager] 🚩 Map ${mapId} reported by ${socket.id}`);
                
                // Trigger revalidation for the God Dashboard - REMOVED: Since we use auto-polling, we don't need this, and it crashes the WebSocket server process.

                // [NEW] GLOBAL GOD NOTIFICATION
                if ((config as any).godNotifyChannelId) {
                    const { sendChannelMessage } = await import("@/server/discord");
                    const ping = (config as any).godNotifyRoleId ? `<@&${(config as any).godNotifyRoleId}>` : "";
                    
                    await sendChannelMessage((config as any).godNotifyChannelId, ping, {
                        embedTitle: "🚩 Signalement Map SigilGuesser",
                        embedColor: 0xef4444,
                        embedDescription: [
                            `Une map a été signalée comme étant buggée ou mal placée.`,
                            "",
                            `**Map ID :** \`${data.mapId}\``,
                            `**Signalé par :** \`${socket.id}\``,
                            "",
                            `▸ [Gérer les maps sur Dashboard](https://sigilos.fr/god/mini-games?game=SigilGuesser)`,
                        ].join("\n"),
                        embedFooter: "SigilOS Administration · SigilGuesser",
                        embedThumbnail: "https://sigilos.fr/assets/ui/icons/geoguesser.png"
                    });
                }
            }
        } catch (e) {
            console.error(`[GeoguesserManager] ❌ Error reporting map:`, e);
        }
    }

    private async startBlacklistSync() {
        const sync = async () => {
            try {
                const config = await db.platformConfig.findUnique({
                    where: { id: "singleton" },
                    select: { geoguesserBlacklist: true }
                });
                if (config) {
                    WorldMapService.getInstance().setBlacklist(config.geoguesserBlacklist);
                }
            } catch (e) {
                console.error("[GeoguesserManager] ❌ Blacklist sync failed:", e);
            }
        };

        // Initial sync
        await sync();
        // Periodically sync (every 5 mins)
        this.syncInterval = setInterval(sync, 5 * 60 * 1000);
    }
}

import { Server, Socket } from "socket.io";
import { db } from "@/lib/prisma";
import { WorldMapService } from "./WorldMapService";
import { logger } from "@/lib/logger";

type GameState = "LOBBY" | "COUNTDOWN" | "IN_PROGRESS" | "RESULT" | "FINISHED";
type GameMode = "NORMAL" | "SPECIAL";

interface Player {
    id: string; // Socket ID
    userId: string;
    userName: string;
    userAvatar?: string;
    score: number;
    hasGuessed: boolean;
    isConnected: boolean;
    isSpectator: boolean;
    lastGuess?: {
        x: number;
        y: number;
        worldId?: number;
        mapId?: number;
        distance: number;
        score: number;
    } | null;
}

export class GeoguesserRoom {
    public id: string;
    public guildId: string;
    private maxRounds: number = 5;
    private timePerRound: number = 30; // secondes
    private difficulty = "easy" as const;

    private state: GameState = "LOBBY";
    private players: Player[] = [];
    private hostId: string | null = null;
    private gameMode: GameMode = "NORMAL";

    private currentRound: number = 0;
    private targetMapIds: number[] = [];

    private roundTimer: NodeJS.Timeout | null = null;
    private timeLeft: number = 0;

    constructor(private io: Server, config: any) {
        this.id = config.id;
        this.guildId = config.guildId;
        if (config.maxRounds) this.setMaxRounds(config.maxRounds);
        if (config.timePerRound) this.setTimePerRound(config.timePerRound);
        if (config.gameMode) this.setGameMode(config.gameMode);
        // Difficulty setting removed as per user request

    }

    private emitToAll(event: string, data?: any) {
        if (data) this.io.to(this.id).emit(event, data);
        else this.io.to(this.id).emit(event);
    }

    private emitTo(socketId: string, event: string, data?: any) {
        this.io.to(socketId).emit(event, data);
    }

    public getEffectiveHostId(): string | null {
        // Trouve le joueur actif le plus ancien si l'hôte est déco
        const activePlayers = this.players.filter(p => p.isConnected && !p.isSpectator);
        if (activePlayers.length === 0) return null;

        const currentHost = activePlayers.find(p => p.userId === this.hostId);
        if (currentHost) return this.hostId;

        return activePlayers[0].userId;
    }

    public isHost(socketId: string) {
        const player = this.players.find(p => p.id === socketId);
        if (!player) return false;
        
        const effectiveHostId = this.getEffectiveHostId();
        return player.userId === effectiveHostId;
    }

    public getCurrentMapId() {
        if (this.currentRound > 0 && this.currentRound <= this.targetMapIds.length) {
            return this.targetMapIds[this.currentRound - 1];
        }
        return null;
    }


    public setMaxRounds(rounds: number) {
        this.maxRounds = rounds;
        this.syncState();
    }


    public setTimePerRound(time: number) {
        this.timePerRound = time;
        this.syncState();
    }

    public setGameMode(mode: GameMode) {
        this.gameMode = mode;
        this.syncState();
    }

    public isEmpty() {
        const connectedCount = this.players.filter(p => p.isConnected).length;
        return connectedCount === 0;
    }

    public addPlayer(socket: Socket, playerObj: { userName: string, userId: string, userAvatar?: string, isSpectator?: boolean }) {
        if (!playerObj.userId) {
            logger.error(`[GeoRoom:${this.id}] ❌ Tentative d'ajout de joueur sans userId !`, { socketId: socket.id });
            return;
        }

        const existing = this.players.find(p => p.userId === playerObj.userId);

        if (existing) {
            logger.info(`[GeoRoom:${this.id}] 🔄 Reconnexion de ${playerObj.userName} (${playerObj.userId})`);
            existing.isConnected = true;
            existing.id = socket.id;
        } else {

            const newPlayer: Player = {
                id: socket.id,
                userId: playerObj.userId,
                userName: playerObj.userName,
                userAvatar: playerObj.userAvatar,
                score: 0,
                hasGuessed: false,
                isConnected: true,
                isSpectator: !!(playerObj as any).isSpectator,
                lastGuess: null
            };
            this.players.push(newPlayer);
            if (!this.hostId && !newPlayer.isSpectator) this.hostId = playerObj.userId;
            
            // Notification join
            this.emitToAll("geoguesser:player:joined", { 
                userName: playerObj.userName, 
                userId: playerObj.userId,
                isSpectator: !!playerObj.isSpectator
            });
        }

        this.syncState();
    }

    public handleLateJoin(socket: Socket) {
        this.syncState();
    }

    public removePlayer(socketId: string) {
        const index = this.players.findIndex(p => p.id === socketId);
        if (index !== -1) {
            const player = this.players[index];
            logger.info(`[GeoRoom:${this.id}] ➖ Déconnexion de ${player.userName}`);
            
            this.emitToAll("geoguesser:player:left", {
                userName: player.userName,
                userId: player.userId
            });

            if (this.state === "LOBBY") {
                this.players.splice(index, 1);
            } else {
                player.isConnected = false;
            }

            if (this.hostId === player.userId) {
                const nextHost = this.players.find(p => p.isConnected && !p.isSpectator);
                this.hostId = nextHost ? nextHost.userId : null;
                logger.info(`[GeoRoom:${this.id}] 👑 Nouvel hôte: ${this.hostId}`);
            }

            if (this.state === "IN_PROGRESS") {
                // Check if the remaining players have all guessed, allowing the round to end early.
                this.checkRoundEndConditions();
            }

            this.syncState();
        }
    }

    public syncState() {
        const basePayload = {
            id: this.id,
            guildId: this.guildId,
            state: this.state,
            hostId: this.getEffectiveHostId(), // Utiliser l'hôte effectif pour le sync
            currentRound: this.currentRound,
            maxRounds: this.maxRounds,
            difficulty: this.difficulty,
            timeLeft: this.timeLeft,
            timePerRound: this.timePerRound,
            // SECURITY: Never send the full target list to clients to prevent F12 cheating. 
            // Only send the map ID for the current round if we are IN_PROGRESS.
            currentMapId: (this.state === "IN_PROGRESS" || this.state === "RESULT") ? this.targetMapIds[this.currentRound - 1] : undefined,
            gameMode: this.gameMode
        };

        const participantsBase = this.players.map(p => ({
            id: p.id,
            userId: String(p.userId),
            userName: p.userName,
            userAvatar: p.userAvatar,
            score: p.score,
            hasGuessed: p.hasGuessed,
            isConnected: p.isConnected,
            isSpectator: p.isSpectator,
            // Hidden for everyone else in IN_PROGRESS
            lastGuess: (this.state === "RESULT" || this.state === "FINISHED") ? p.lastGuess : (p.hasGuessed ? { hidden: true } : null)
        }));

        this.players.forEach(p => {
            if (!p.isConnected) return;
            
            // Build tailored list for this specific player
            const tailoredParticipants = participantsBase.map(other => {
                // If it's the current player, show them their own guess data
                if (String(other.userId) === String(p.userId)) {
                    return { ...other, lastGuess: p.lastGuess };
                }
                return other;
            });

            this.io.to(p.id).emit("geoguesser:state:sync", {
                ...basePayload,
                participants: tailoredParticipants
            });
        });
    }

    public async startGame() {
        logger.info(`[GeoRoom:${this.id}] 🎬 Démarrage/Relance du jeu.`);
        
        // SECURITY: Server ALWAYS selects the maps to prevent client-side target manipulation
        this.targetMapIds = WorldMapService.getInstance().getRandomMaps(this.maxRounds, this.gameMode);
        
        this.currentRound = 0;
        this.players.forEach(p => {
            p.score = 0;
            p.lastGuess = null;
            p.hasGuessed = false;
        });

        // Update DB status (use updateMany to avoid P2025 if session was already deleted)
        try {
            await db.geoguesserSession.updateMany({
                where: { id: this.id },
                data: { status: 'IN_PROGRESS', targetMapIds: this.targetMapIds }
            });
        } catch (e) {
            logger.error(`[GeoRoom:${this.id}] ❌ Erreur DB status START:`, { error: e });
        }

        // START COUNTDOWN instead of round 1
        this.state = "COUNTDOWN";
        this.timeLeft = 3;
        this.syncState();

        this.startTimer(() => {
            logger.info(`[GeoRoom:${this.id}] 🚀 Countdown fini, lancement du Round 1`);
            this.startNextRound();
        });
    }

    public startNextRound() {
        this.currentRound++;
        logger.info(`[GeoRoom:${this.id}] 🚩 Round ${this.currentRound} démarré.`);
        if (this.currentRound > this.maxRounds || this.currentRound > this.targetMapIds.length) {
            this.endGame();
            return;
        }

        this.state = "IN_PROGRESS";
        this.players.forEach(p => {
            p.hasGuessed = false;
            p.lastGuess = null;
        });

        this.timeLeft = this.gameMode === 'SPECIAL' ? 10 : this.timePerRound;
        this.syncState();

        this.startTimer(() => {
            logger.warn(`[GeoRoom:${this.id}] 🕒 Timeout reached for round ${this.currentRound}`);
            this.handleRoundFinish();
        });
        
        // Safety: Initial sync to make sure clients get the new timeLeft immediately
        this.syncState();
    }

    public triggerNextRound(socket: Socket) {
        if (this.isHost(socket.id) && !this.isSpectator(socket.id) && this.state === "RESULT") {
            this.startNextRound();
        }
    }

    public handleGuess(socket: Socket, data: { x: number, y: number, worldId?: number }) {
        const player = this.players.find(p => p.id === socket.id);
        if (!player || player.isSpectator) {
            logger.error(`[GeoRoom:${this.id}] ❌ Tentative de guess par un joueur inconnu ou spectateur`, { socketId: socket.id });
            return;
        }

        if (player.hasGuessed) {
            logger.warn(`[GeoRoom:${this.id}] ⚠️ Guess ignoré : ${player.userName} a déjà joué ce round.`);
            return;
        }

        if (this.state !== "IN_PROGRESS") {
            logger.warn(`[GeoRoom:${this.id}] ⚠️ Guess ignoré : le round n'est pas en cours`, { state: this.state });
            return;
        }

        // --- SECURITY: RECALCULATE SCORE SERVER-SIDE ---
        const currentTargetId = this.targetMapIds[this.currentRound - 1];
        const { distance: calculatedDist, score: calculatedScore } = WorldMapService.getInstance().calculateScore(
            currentTargetId,
            Number(data.x),
            Number(data.y),
            data.worldId ? Number(data.worldId) : 1
        );

        player.hasGuessed = true;
        player.score += calculatedScore;
        player.lastGuess = {
            x: Number(data.x),
            y: Number(data.y),
            worldId: data.worldId ? Number(data.worldId) : undefined,
            mapId: (data as any).mapId ? Number((data as any).mapId) : undefined,
            score: calculatedScore,
            distance: calculatedDist
        };

        logger.info(`[GeoRoom:${this.id}] 🎯 Guess de ${player.userName}: ${calculatedScore} pts (reste ${this.timeLeft}s)`);

        this.syncState();
        this.checkRoundEndConditions();
    }

    private checkRoundEndConditions() {
        const activeGuessers = this.players.filter(p => p.isConnected && !p.isSpectator);
        const allGuessed = activeGuessers.every(p => p.hasGuessed);

        if (allGuessed && activeGuessers.length > 0) {
            logger.info(`[GeoRoom:${this.id}] ✅ Tous les joueurs ont joué.`);
            this.stopTimer();
            this.handleRoundFinish();
        }
    }

    private handleRoundFinish() {
        this.state = "RESULT";
        this.timeLeft = 10;
        this.syncState();

        this.startTimer(() => {
            if (this.currentRound >= this.maxRounds) {
                this.endGame();
            } else {
                this.startNextRound();
            }
        });
    }

    private async endGame() {
        logger.info(`[GeoRoom:${this.id}] 🏆 Fin du jeu.`);
        this.state = "FINISHED";
        this.stopTimer();
        this.timeLeft = 0;
        this.syncState();

        // Update DB status to FINISHED (use updateMany to avoid P2025 if session was already deleted)
        try {
            const updated = await db.geoguesserSession.updateMany({
                where: { id: this.id },
                data: { status: 'FINISHED' }
            });

            if (updated.count > 0) {
                // Update individual total scores in DB for final result
                for (const p of this.players) {
                    await db.geoguesserSessionPlayer.updateMany({
                        where: { sessionId: this.id, userId: p.userId },
                        data: { totalScore: p.score }
                    });
                }
                
                // --- UPDATE HALL OF FAME ---
                // Only count players that are not spectators.
                const validPlayers = this.players.filter(p => !p.isSpectator && p.userId);
                logger.info(`[GeoRoom:${this.id}] 🏆 Fin de partie. Joueurs valides pour le Hall of Fame: ${validPlayers.length} (Total: ${this.players.length})`);
                
                // Exclude solo games (must have > 1 valid players)
                if (validPlayers.length > 1) {
                    for (const p of validPlayers) {
                        try {
                            logger.info(`[GeoRoom:${this.id}] 💾 Persistance du score pour ${p.userName} (${p.userId}): ${p.score} pts`);
                            // 1. Sauvegarder le score de cette partie (Historique)
                            await db.geoguesserScore.create({
                                data: {
                                    guildId: this.guildId,
                                    userId: p.userId,
                                    userName: p.userName || "Inconnu",
                                    userAvatar: p.userAvatar,
                                    score: p.score,
                                    distance: p.lastGuess?.distance || 0 
                                }
                            });

                            // 2. Mettre à jour le classement global (Hall of Fame)
                            const rank = await db.geoguesserRank.upsert({
                                where: {
                                    guildId_userId: { guildId: this.guildId, userId: p.userId }
                                },
                                create: {
                                    guildId: this.guildId,
                                    userId: p.userId,
                                    userName: p.userName || "Inconnu",
                                    userAvatar: p.userAvatar,
                                    bestScore: p.score,
                                    totalPoints: p.score,
                                    gamesPlayed: 1,
                                    avgDistance: p.lastGuess?.distance || 0 
                                },
                                update: {
                                    totalPoints: { increment: p.score },
                                    gamesPlayed: { increment: 1 },
                                    userName: p.userName || "Inconnu",
                                    userAvatar: p.userAvatar,
                                }
                            });
                            
                            // Empêcher la régression du bestScore
                            if (p.score > rank.bestScore) {
                                await db.geoguesserRank.update({
                                    where: { id: rank.id },
                                    data: { bestScore: p.score }
                                });
                            }
                        } catch (err) {
                            logger.error(`[GeoRoom:${this.id}] ❌ Erreur mise à jour Hall of Fame pour ${p.userName}:`, { error: err });
                        }
                    }
                } else {
                    logger.info(`[GeoRoom:${this.id}] ℹ️ Partie ignorée par le Hall of Fame (Mode Solo ou moins de 2 joueurs).`);
                }
            } else {
                logger.warn(`[GeoRoom:${this.id}] ⚠️ Session DB introuvable lors de endGame (déjà supprimée?). Scores non persistés.`);
            }
        } catch (e) {
            logger.error(`[GeoRoom:${this.id}] ❌ Erreur DB status END:`, { error: e });
        }

        setTimeout(() => {
            if (this.state === "FINISHED") {
                this.state = "LOBBY";
                this.syncState();
            }
        }, 30000);
    }

    private startTimer(onTimeout: () => void) {
        this.stopTimer();
        this.roundTimer = setInterval(() => {
            this.timeLeft--;
            
            // CRITICAL: Must sync state every tick so clients see the countdown
            this.syncState();
            
            if (this.timeLeft <= 0) {
                logger.debug(`[GeoRoom:${this.id}] 🕒 Timer auto-timeout.`);
                this.stopTimer();
                onTimeout();
            }
        }, 1000);
    }

    private stopTimer() {
        if (this.roundTimer) {
            clearInterval(this.roundTimer);
            this.roundTimer = null;
        }
    }

    public handlePlayerDisconnect(socketId: string, reason: string) {
        this.removePlayer(socketId);
    }

    public async destroy() {
        this.stopTimer();
        logger.info(`[GeoRoom:${this.id}] 🔥 Salle détruite.`);
        try {
            // SECURITY: Delete session data instead of leaving finished records
            await db.geoguesserSession.deleteMany({
                where: { id: this.id }
            });
        } catch (e) {
            // Silently fail if already deleted
        }
    }

    public isSpectator(socketId: string) {
        return this.players.find(p => p.id === socketId)?.isSpectator || false;
    }

    public getState(): GameState {
        return this.state;
    }

    public getPublicInfo(roomId: string) {
        return {
            id: roomId,
            roomId,
            playerCount: this.players.filter(p => p.isConnected && !p.isSpectator).length,
            maxPlayers: 8,
            hostName: this.players.find(p => p.userId === this.hostId)?.userName || "Hôte",
            maxRounds: this.maxRounds,
            difficulty: this.difficulty,
            state: this.state,
            gameMode: this.gameMode
        };
    }
}

import fs from 'fs';
import path from 'path';

export interface MapData {
    id: number;
    x: number;
    y: number;
    worldMap: number;
    outdoor: boolean;
    subAreaId: number;
}

export class WorldMapService {
    private static instance: WorldMapService;
    private maps = new Map<number, MapData>();
    private playableMaps: MapData[] = [];
    private blacklist = new Set<number>();
    private isLoaded = false;

    private constructor() {}

    public static getInstance(): WorldMapService {
        if (!WorldMapService.instance) {
            WorldMapService.instance = new WorldMapService();
        }
        return WorldMapService.instance;
    }

    public loadData() {
        if (this.isLoaded) return;
        try {
            const filePath = path.join(process.cwd(), 'public', 'game-data', 'worldmap.json');
            const fileContent = fs.readFileSync(filePath, 'utf8');
            const data = JSON.parse(fileContent);

            const excludedKeywords = [
                // General Interiors/Dungeons
                "donjon", "tunnel", "souterrain", "cave", "crypt", "labyrinthe", 
                "bâtiment", "intérieur", "tactique", "défis", "arène", "mine", 
                "égout", "cellule", "prison", "temple", "salle", "château",
                "laboratoire", "secret", "caché", "salle du trône", "boss",
                "technique", "combat", "kolizéum", "kolyzéum", "tutoriel", "test", "base",
                "map de combat", "salle de boss", "salle du boss",
                
                // Divine Dimensions (Usually hard to guess/find)
                "dimension", "ecaflipus", "enutrosor", "srambad", "xelorium", 
                "écafli", "énutro", "sram", "xélor", "défi",
                
                // Specific Bosses/Areas
                "chaloeil", "vortex", "nidas", "reine des voleurs", "koutoulou", 
                "dantinéa", "meno", "merkab", "trône", "sommet", "antre",
                "fond de la mer", "profondeurs", "obscur", "sombre", "cachot",
                "laboratoire", "infirmerie", "forge", "atelier", "bibliothèque",
                "taverne", "maison", "villa", "palais", "résidence"
            ];

            const subAreaNames = new Map<number, string>();
            if (data.subareas) {
                // Also load subarea names from a different property if possible
                data.subareas.forEach((s: any) => {
                    const nameFR = s.nameFR || s.name_fr || (typeof s.name === 'string' ? s.name : s.name?.fr || "");
                    const name = nameFR.toLowerCase();
                    subAreaNames.set(s.id, name);
                });
            }

            this.playableMaps = []; // Clear current list for reload
            if (data.maps) {
                data.maps.forEach((m: any) => {
                    const subAreaName = subAreaNames.get(m.subAreaId) || "";
                    const isExcluded = excludedKeywords.some(key => subAreaName.includes(key));

                    // Strict check: must be outdoor AND from a primary world map AND not excluded by keyword
                    // We only allow World 1 (Amakna) and World 2 (Incarnam) as "Playable" origins for special mode
                    // Tunnels (World 3) and small labyrinths (World 4, 5, 6...) are excluded.
                    const isMainWorld = m.worldMap === 1 || m.worldMap === 2;
                    
                    // HEURISTIC: Tactical maps often have IDs in specific extreme ranges or are marked technical.
                    // If we imported Dofus 2.x data, IDs >= 200,000,000 are often technical/tactical maps.
                    const isTechnicalMap = m.id >= 200000000;
                    
                    if (m.outdoor && m.worldMap !== -1 && isMainWorld && !isExcluded && !isTechnicalMap) {
                        this.playableMaps.push({
                            id: m.id,
                            x: m.x,
                            y: m.y,
                            worldMap: m.worldMap,
                            outdoor: m.outdoor,
                            subAreaId: m.subAreaId
                        });
                    }
                    
                    this.maps.set(m.id, {
                        id: m.id,
                        x: m.x,
                        y: m.y,
                        worldMap: m.worldMap,
                        outdoor: m.outdoor,
                        subAreaId: m.subAreaId
                    });
                });
            }
            this.isLoaded = true;
            
            const stats: Record<number, number> = {};
            this.playableMaps.forEach(m => {
                stats[m.worldMap] = (stats[m.worldMap] || 0) + 1;
            });
            console.log(`[WorldMapService] 🗺️ ${this.maps.size} maps loaded. Playable stats:`, stats);
        } catch (error) {
            console.error('[WorldMapService] ❌ Failed to load worldmap data:', error);
        }
    }

    public getMap(id: number): MapData | undefined {
        return this.maps.get(id);
    }

    public getRandomMaps(count: number, mode: 'NORMAL' | 'SPECIAL' = 'NORMAL'): number[] {
        let filtered = this.playableMaps;
        
        // Apply blacklist filtering
        if (this.blacklist.size > 0) {
            filtered = filtered.filter(m => !this.blacklist.has(m.id));
        }

        if (mode === 'NORMAL') {
            // Normal mode is World of Twelve (Amakna)
            filtered = filtered.filter(m => m.worldMap === 1);
        } else {
            // Mode SPECIAL: Include Incarnam (World 2) and others if allowed, 
            // but we usually want to stay on identifiable maps.
            // Exclude World 1, World 19 (Mappemondes), World 29 (Ecaflip City)
            filtered = filtered.filter(m => m.worldMap !== 1 && m.worldMap !== 19 && m.worldMap !== 29);
        }

        if (filtered.length === 0) return [];

        const result: number[] = [];
        const usedSubAreas = new Set<number>();
        const copy = [...filtered];
        
        while (result.length < count && copy.length > 0) {
            const idx = Math.floor(Math.random() * copy.length);
            const selectedMap = copy[idx];
            copy.splice(idx, 1); // Avoid duplicates
            
            // In NORMAL mode, ensure unique subArea per party
            if (mode === 'NORMAL' && selectedMap.subAreaId) {
                if (usedSubAreas.has(selectedMap.subAreaId)) {
                    continue; // Skip because we already have a map from this zone
                }
                usedSubAreas.add(selectedMap.subAreaId);
            }
            
            result.push(selectedMap.id);
        }
        
        // Fallback if we couldn't find enough unique zones (highly unlikely)
        if (result.length < count) {
            const remaining = count - result.length;
            const fallbackFiltered = filtered.filter(m => !result.includes(m.id));
            for (let i = 0; i < remaining; i++) {
                if (fallbackFiltered.length === 0) break;
                const idx = Math.floor(Math.random() * fallbackFiltered.length);
                result.push(fallbackFiltered[idx].id);
                fallbackFiltered.splice(idx, 1);
            }
        }
        
        return result;
    }

    public calculateScore(mapId: number, guessX: number, guessY: number, guessWorldId: number): { distance: number, score: number } {
        const target = this.getMap(mapId);
        if (!target) return { distance: 1000, score: 0 };

        let distance = 1000;
        if (target.worldMap === guessWorldId) {
            const dx = guessX - target.x;
            const dy = guessY - target.y;
            // Dofus uses Manhattan distance for maps
            distance = Math.abs(dx) + Math.abs(dy);
        }

        const maxDistPossible = 100;
        let score = 0;
        if (distance < maxDistPossible) {
            score = Math.round(1000 * Math.pow(1 - distance / maxDistPossible, 2));
        }

        // Difficulty Bonus for exact guesses
        if (distance === 0) {
            // Standard bonus for server-side score calculation
            score += 250; 
        }

        return { distance, score };
    }

    public setBlacklist(ids: number[]) {
        this.blacklist = new Set(ids);
        console.log(`[WorldMapService] 🚫 Blacklist updated with ${ids.length} maps.`);
    }
}

import { Server, Socket } from "socket.io";
import { logger } from "@/lib/logger";

export class InvaderManager {
    constructor(private io: Server) {}

    public registerSocket(socket: Socket) {
        socket.on("invader:room:join", (roomId: string) => {
            socket.join(`invader:room:${roomId}`);
            logger.info(`[Invader] Socket ${socket.id} joined room ${roomId}`);
        });

        socket.on("invader:pos:sync", (data: any) => {
            const { roomId, userId, ...posData } = data;
            if (roomId) {
                // Broadcast to everyone else in the room
                socket.to(`invader:room:${roomId}`).emit("invader:pos:update", {
                    userId: userId || socket.id, 
                    ...posData
                });
            }
        });

        socket.on("invader:bot:sync", (data: any) => {
            const { roomId, ...botData } = data;
            if (roomId) {
                socket.to(`invader:room:${roomId}`).emit("invader:bot:update", botData);
            }
        });

        socket.on("invader:obstacles:sync", (data: any) => {
            const { roomId, obstacles } = data;
            if (roomId) {
                socket.to(`invader:room:${roomId}`).emit("invader:obstacles:update", { obstacles });
            }
        });
    }

    public handleDisconnect(socket: Socket) {
        // No complex state to cleanup here since it's mostly ephemeral broadcast
    }
}

import { Server, Socket } from "socket.io";
import { redis } from "@/lib/redis";
import { SkribblRoom } from "./SkribblRoom";
import { logger } from "@/lib/logger";
import { SkribblDrawSchema, SkribblGuessSchema } from "../../websocket/schemas";

function generateShortId() {
    return "DRAW-" + Math.random().toString(36).substring(2, 6).toUpperCase();
}

export class SkribblManager {
    private rooms = new Map<string, SkribblRoom>();
    private userToRoom = new Map<string, string>(); // userId -> roomId

    constructor(private io: Server) { }

    public registerSocket(socket: Socket) {
        // Enregistrement des événements via le namespace skribbl
        socket.on("skribbl:room:create", (config) => this.createRoom(socket, config));
        socket.on("skribbl:room:join", ({ roomId, playerObj }) => this.joinRoom(socket, roomId, playerObj));
        socket.on("skribbl:room:leave", () => this.handleLeaveRoom(socket));
        socket.on("skribbl:room:list", () => this.handleRoomList(socket));

        socket.on("skribbl:draw:stroke", (data) => this.relayToRoom(socket, "skribbl:draw:stroke", data));
        socket.on("skribbl:draw:clear", () => this.relayToRoom(socket, "skribbl:draw:clear"));
        socket.on("skribbl:draw:undo", () => this.relayToRoom(socket, "skribbl:draw:undo"));
        socket.on("skribbl:draw:fill", (data) => this.relayToRoom(socket, "skribbl:draw:fill", data));

        socket.on("skribbl:chat:guess", ({ text }) => this.handleGuess(socket, text));
        socket.on("skribbl:game:start", () => this.handleStart(socket));
        socket.on("skribbl:word:select", ({ word }) => this.handleWordChoice(socket, word));
        socket.on("skribbl:word:choose", ({ word }) => this.handleWordChoice(socket, word)); // Alias client
        socket.on("skribbl:word:reroll", () => this.handleWordReroll(socket));
        socket.on("skribbl:room:delete", () => this.handleDeleteRoom(socket));
        socket.on("skribbl:room:settings", (config) => this.handleUpdateSettings(socket, config));
    }

    private async handleUpdateSettings(socket: Socket, config: any) {
        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        if (!roomId) return;
        const room = this.rooms.get(roomId);
        if (room && room.isHost(socket.id)) {
            room.updateSettings(config);
        }
    }

    private async broadcastRoomList(guildIdCandidate?: string) {
        let guildId = guildIdCandidate || "global";
        if (guildId === "undefined" || guildId === "null") guildId = "global";

        const rooms: any[] = [];
        this.rooms.forEach((room, roomId) => {
            if (room.getGuildId() === guildId && !room.isEmpty()) {
                rooms.push(room.getPublicInfo(roomId));
            }
        });
        this.io.to(`guild:${guildId}`).emit("skribbl:room:list", rooms);
        
        // Internal Redis broadcast for Dashboard EventTicker
        if (guildId !== "global") {
            await redis.set(`guild:${guildId}:skribbl:rooms`, JSON.stringify(rooms), "EX", 3600);
        }
    }

    private handleRoomList(socket: Socket) {
        const guildId = (socket.handshake.query.guildId as string) || "global";

        const rooms: any[] = [];
        this.rooms.forEach((room, roomId) => {
            if (room.getGuildId() === guildId && !room.isEmpty()) {
                rooms.push(room.getPublicInfo(roomId));
            }
        });
        socket.emit("skribbl:room:list", rooms);
    }

    private async handleLeaveRoom(socket: Socket) {
        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        const userId = await redis.get(`socket:skribbl:${socket.id}:user`);

        if (roomId) {
            socket.leave(roomId);
            const room = this.rooms.get(roomId);
            if (room) {
                const guildId = room.getGuildId();
                room.removePlayer(socket.id);
                if (room.isEmpty()) {
                    room.destroy();
                    this.rooms.delete(roomId);
                }
                this.broadcastRoomList(guildId);
            }
        }
        
        if (userId) {
            const activeRoomId = this.userToRoom.get(userId);
            if (activeRoomId === roomId) {
                this.userToRoom.delete(userId);
                await redis.del(`user:${userId}:skribbl:room`);
            }
        }
        await this.delSocketData(socket.id);
    }

    private deleteRoomInternal(roomId: string) {
        const room = this.rooms.get(roomId);
        if (room) {
            const hostId = room.getHostId();
            const guildId = room.getGuildId();
            room.destroy();
            this.rooms.delete(roomId);
            if (hostId) {
                this.userToRoom.delete(hostId);
                redis.del(`user:${hostId}:skribbl:room`).catch(() => {});
            }
            this.broadcastRoomList(guildId);
        }
    }

    private async handleDeleteRoom(socket: Socket) {
        try {
            const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
            if (!roomId) return;
            const room = this.rooms.get(roomId);
            if (room && room.isHost(socket.id)) {
                this.io.to(roomId).emit("skribbl:error", { message: "Le salon a été fermé par l'hôte." });
                this.deleteRoomInternal(roomId);
            }
        } catch (e) {
            console.error("[SkribblManager] handleDeleteRoom error:", e);
        }
    }

    private async delSocketData(socketId: string) {
        try {
            await redis.del(`socket:skribbl:${socketId}:room`);
            await redis.del(`socket:skribbl:${socketId}:user`);
        } catch (e) {}
    }

    private async setSocketData(socketId: string, roomId: string, userId: string) {
        try {
            await redis.set(`socket:skribbl:${socketId}:room`, roomId, "EX", 3600);
            await redis.set(`socket:skribbl:${socketId}:user`, userId, "EX", 3600);
        } catch (e) {}
    }

    private async createRoom(socket: Socket, config: any) {
        try {
            const userId = config.playerObj?.userId || socket.id;
            let guildId = (socket.handshake.query.guildId as string);
            if (!guildId || guildId === "undefined" || guildId === "null") guildId = "global";

            // 1. One room max per user
            const existingRoomId = this.userToRoom.get(userId);
            if (existingRoomId && this.rooms.has(existingRoomId)) {
                // If the user already has a room, destroy it to avoid "infinites salons"
                console.log(`[SkribblManager] 🧹 Cleaning up old room ${existingRoomId} for user ${userId}`);
                this.deleteRoomInternal(existingRoomId);
            }

            const roomId = generateShortId();
            const room = new SkribblRoom(this.io, this, { ...config, id: roomId, guildId });
            this.rooms.set(roomId, room);
            this.userToRoom.set(userId, roomId);

            await redis.set(`user:${userId}:skribbl:room`, roomId, "EX", 7200);
            socket.emit("skribbl:room:created", { roomId });
            this.broadcastRoomList(guildId);
        } catch (e) {
            console.error("[SkribblManager] createRoom error:", e);
        }
    }

    private async joinRoom(socket: Socket, roomId: string, playerObj: any) {
        const room = this.rooms.get(roomId);
        if (!room) {
            socket.emit("skribbl:error", { message: "Salon introuvable ou fermé." });
            return;
        }

        const socketGuildId = (socket.handshake.query.guildId as string) || "global";
        if (room.getGuildId() !== socketGuildId) {
            console.warn(`[SkribblManager] ❌ Guild mismatch: ${socket.id} tried to join ${roomId}`);
            socket.emit("skribbl:error", { message: "Ce salon n'appartient pas à votre guilde." });
            return;
        }

        const userId = playerObj.userId || socket.id;
        socket.join(roomId);
        await this.setSocketData(socket.id, roomId, userId);
        
        // SECURITY: If game is not in lobby, force spectator mode
        const isSpectator = !!playerObj.isSpectator || room.getState() !== "LOBBY";

        room.addPlayer(socket, { 
            userName: playerObj.userName || playerObj.pseudo, 
            userId: userId, 
            userAvatar: playerObj.userAvatar || playerObj.avatarUrl,
            isSpectator // Correctement passé ici
        } as any);
        this.broadcastRoomList(room.getGuildId());
    }

    private async relayToRoom(socket: Socket, event: string, data?: any) {
        // SECURITY: Validate drawing data
        if (event === "skribbl:draw:stroke" || event === "skribbl:draw:fill") {
            const validation = SkribblDrawSchema.safeParse(data);
            if (!validation.success) {
                console.warn(`[SkribblManager] ❌ Invalid draw data from ${socket.id}`, validation.error.format());
                return;
            }
        }

        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        if (!roomId) return;

        const room = this.rooms.get(roomId);
        if (!room) return;

        // SECURITY: Spectators can never draw
        if (room.isSpectator(socket.id)) {
            console.warn(`[SkribblManager] 🚫 Spectator ${socket.id} tried to draw in ${roomId}`);
            return;
        }

        if (event === "skribbl:draw:undo") {
            room.undoCanvasAction();
            return;
        }

        if (event.startsWith("skribbl:draw:")) {
            const actionType = event.replace("skribbl:draw:", "");
            if (actionType === "stroke" && Array.isArray(data)) {
                // For batched strokes, we store the data as-is if it's an array
                room.addCanvasAction(data);
            } else {
                room.addCanvasAction({ type: actionType, ...data });
            }
        }

        if (data !== undefined) {
            socket.to(roomId).emit(event, data);
        } else {
            socket.to(roomId).emit(event);
        }
    }

    private async handleGuess(socket: Socket, text: string) {
        // SECURITY: Validate guess text
        const validation = SkribblGuessSchema.safeParse({ text });
        if (!validation.success) return;

        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        if (!roomId) return;
        const room = this.rooms.get(roomId);
        if (room) {
            // SECURITY: Spectators cannot guess
            if (room.isSpectator(socket.id)) {
                console.warn(`[SkribblManager] 🚫 Spectator ${socket.id} tried to guess in room ${roomId}`);
                return;
            }
            room.handleGuess(socket, text);
        }
    }

    private async handleStart(socket: Socket) {
        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        if (!roomId) return;
        const room = this.rooms.get(roomId);
        if (room) {
            if (room.isHost(socket.id)) {
                room.startGame();
            } else {
                console.warn(`[SkribblManager] Player ${socket.id} tried to start game in room ${roomId} but is not host.`);
                socket.emit("skribbl:error", { message: "Seul l'hôte peut lancer la partie." });
            }
        }
    }

    private async handleWordChoice(socket: Socket, word: string) {
        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        if (!roomId) return;
        const room = this.rooms.get(roomId);
        if (room) room.handleWordChoice(socket.id, word);
    }

    private async handleWordReroll(socket: Socket) {
        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        if (!roomId) return;
        const room = this.rooms.get(roomId);
        if (room) room.handleWordReroll(socket.id);
    }

    public async handleDisconnect(socket: Socket, reason: string) {
        const roomId = await redis.get(`socket:skribbl:${socket.id}:room`);
        const userId = await redis.get(`socket:skribbl:${socket.id}:user`);

        if (roomId) {
            const room = this.rooms.get(roomId);
            if (room) {
                const guildId = room.getGuildId();
                room.removePlayer(socket.id);
                
                if (room.isEmpty()) {
                    // Grace period of 10 seconds before destroying the room
                    setTimeout(() => {
                        const currentRoom = this.rooms.get(roomId);
                        if (currentRoom && currentRoom.isEmpty()) {
                            currentRoom.destroy();
                            this.rooms.delete(roomId);
                            this.broadcastRoomList(guildId);
                            console.log(`[SkribblManager] Room ${roomId} destroyed after grace period.`);
                        }
                    }, 10000);
                } else {
                    this.broadcastRoomList(guildId);
                }
            }
        }

        if (userId && roomId) {
            const activeRoomId = await redis.get(`user:${userId}:skribbl:room`);
            if (activeRoomId === roomId) {
                await redis.del(`user:${userId}:skribbl:room`);
            }
        }
        await this.delSocketData(socket.id);
    }
}

import { Server, Socket } from "socket.io";
import { getDofusWords, type SkribblWord } from "./words";
import { logger } from "@/lib/logger";
import { db } from "@/lib/prisma";
import type { SkribblManager } from "./SkribblManager";

type GameState = "LOBBY" | "SELECTING_WORD" | "DRAWING" | "ROUND_END" | "GAME_END";

interface Player {
    id: string; // Socket ID
    userId?: string;
    userName: string;
    userAvatar?: string;
    score: number;
    hasGuessed: boolean;
    isDrawing: boolean;
    isConnected: boolean;
    isSpectator: boolean;
}

// Fonction utilitaire pour enlever les accents
function removeAccents(str: string) {
    return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

// Outil basique de distance de Levenshtein (insensible à la casse et aux accents)
function levenshteinDistance(a: string, b: string): number {
    a = removeAccents(a.toLowerCase().trim());
    b = removeAccents(b.toLowerCase().trim());
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;
    const matrix = [];
    for (let i = 0; i <= b.length; i++) matrix[i] = [i];
    for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
    for (let i = 1; i <= b.length; i++) {
        for (let j = 1; j <= a.length; j++) {
            if (b.charAt(i - 1) === a.charAt(j - 1)) {
                matrix[i][j] = matrix[i - 1][j - 1];
            } else {
                matrix[i][j] = Math.min(
                    matrix[i - 1][j - 1] + 1, // substitution
                    Math.min(matrix[i][j - 1] + 1, // insertion
                        matrix[i - 1][j] + 1) // deletion
                );
            }
        }
    }
    return matrix[b.length][a.length];
}

export class SkribblRoom {
    private id: string;
    private guildId: string;
    private maxRounds: number = 3;
    private roundDuration: number = 90; // Increased to 90s for more drawing time
    private difficulty: "facile" | "moyen" | "difficile" = "moyen";
    private allowedCategories: string[] = [];

    private state: GameState = "LOBBY";
    private players: Player[] = [];
    private hostId: string | null = null;

    // État du jeu en cours
    private currentRound: number = 0;
    private drawerIndex: number = -1;
    private currentWord: string = "";
    private currentWordIcon?: string;
    private currentWordCategory?: string;
    private currentWordMask: string = "";
    private wordChoices: SkribblWord[] = [];
    private revealedHints: Set<number> = new Set();
    private revealedHintIndexes: Set<number> = new Set(); // Indice des lettres révélées
    private showIconHint: boolean = false;
    private guessedPlayersCount: number = 0;
    private guessersScoresThisRound: number[] = [];

    private roundTimer: NodeJS.Timeout | null = null;
    private timeLeft: number = 0;
    private hasRerolledThisTurn: boolean = false;

    // Canvas history pour les spectateurs qui rejoignent en retard
    private canvasActions: any[] = [];
    private usedWords: Set<string> = new Set();
    private gameHistory: any[] = []; // Stores summaries of finished rounds

    constructor(private io: Server, private manager: SkribblManager, config: any) {
        this.id = config.id;
        this.guildId = config.guildId;
        if (config.rounds) this.maxRounds = config.rounds;
        if (config.duration) this.roundDuration = config.duration;
        if (config.difficulty) this.difficulty = config.difficulty;
        if (config.categories) this.allowedCategories = config.categories;
    }

    public getGuildId() {
        return this.guildId;
    }

    private emitToAll(event: string, data?: any) {
        if (data) this.io.to(this.id).emit(event, data);
        else this.io.to(this.id).emit(event);
    }

    private emitTo(socketId: string, event: string, data?: any) {
        this.io.to(socketId).emit(event, data);
    }

    public isHost(socketId: string) {
        const player = this.players.find(p => p.id === socketId);
        return player ? this.hostId === (player.userId || player.id) : false;
    }

    public getHostId() {
        return this.hostId;
    }

    public isEmpty() {
        return this.players.filter(p => p.isConnected).length === 0;
    }

    public addPlayer(socket: Socket, playerObj: { userName: string, userId?: string, userAvatar?: string, isSpectator?: boolean }) {
        const existing = this.players.find(p => p.id === socket.id || (playerObj.userId && p.userId === playerObj.userId));

        if (existing) {
            existing.isConnected = true;
            existing.id = socket.id; // Mise à jour du socket
        } else {
            const newPlayer: Player = {
                id: socket.id,
                userId: playerObj.userId,
                userName: playerObj.userName || `Joueur ${this.players.length + 1}`,
                userAvatar: playerObj.userAvatar,
                score: 0,
                hasGuessed: false,
                isDrawing: false,
                isConnected: true,
                isSpectator: !!playerObj.isSpectator
            };
            this.players.push(newPlayer);
            if (!this.hostId && !newPlayer.isSpectator) this.hostId = playerObj.userId || socket.id;
        }

        this.syncState();

        // Dire à tout le monde qu'il a rejoint (Chat system)
        this.emitToAll("skribbl:chat:message", { type: "system", text: `${playerObj.userName} a rejoint la salle.` });

        // Si la partie en est cours de dessin, envoyer l'état du canvas à ce joueur
        if (this.state === "DRAWING" && this.canvasActions.length > 0) {
            this.emitTo(socket.id, "skribbl:canvas:restore", { actions: this.canvasActions });
        }
    }

    public removePlayer(socketId: string) {
        const player = this.players.find(p => p.id === socketId);
        if (player) {
            player.isConnected = false;
            this.emitToAll("skribbl:chat:message", { type: "system", text: `${player.userName} a quitté la salle.` });

            // Si c'était l'hôte, on passe le lead
            if (this.hostId === (player.userId || player.id)) {
                const nextHost = this.players.find(p => p.isConnected && !p.isSpectator);
                this.hostId = nextHost ? (nextHost.userId || nextHost.id) : null;
            }

            // Si c'était le dessinateur, on skip le tour !
            if (this.state === "DRAWING" || this.state === "SELECTING_WORD") {
                if (player.isDrawing) {
                    this.emitToAll("skribbl:chat:message", { type: "system", text: `Le dessinateur a fui ! Fin du tour.` });
                    this.endRound();
                } else if (this.state === "DRAWING") {
                    this.checkRoundEndConditions();
                }
            }
            this.syncState();
        }
    }

    public addCanvasAction(action: any) {
        if (action.type === "clear") {
            this.canvasActions = [];
        } else {
            this.canvasActions.push(action);
        }
    }

    public undoCanvasAction() {
        if (this.canvasActions.length === 0) return;
        const lastAction = this.canvasActions[this.canvasActions.length - 1];
        const lastPathId = lastAction.pathId;
        if (lastPathId) {
            this.canvasActions = this.canvasActions.filter(a => a.pathId !== lastPathId);
        } else {
            this.canvasActions.pop();
        }
        this.emitToAll("skribbl:draw:undo");
        // [Hotfix] Automatically restore the canvas layout internally for all clients when undoing
        this.emitToAll("skribbl:canvas:restore", { actions: this.canvasActions });
    }

    public syncState() {
        const publicPlayers = this.players.map(p => ({
            id: p.id,
            userName: p.userName,
            userAvatar: p.userAvatar,
            score: p.score,
            hasGuessed: p.hasGuessed,
            isDrawing: p.isDrawing,
            isConnected: p.isConnected
        }));

        const publicState = {
            id: this.id,
            state: this.state,
            hostId: this.hostId,
            currentRound: this.currentRound,
            maxRounds: this.maxRounds,
            timeLeft: this.timeLeft,
            currentWord: (this.state === "DRAWING" || this.state === "ROUND_END" || this.state === "GAME_END") ? this.currentWord : "",
            currentWordMask: this.currentWordMask,
            wordChoices: this.wordChoices,
            hasRerolled: this.hasRerolledThisTurn,
            difficulty: this.difficulty,
            allowedCategories: this.allowedCategories,
            showIconHint: this.showIconHint,
            currentWordIcon: (this.showIconHint || this.state === "ROUND_END" || this.state === "GAME_END") ? this.currentWordIcon : undefined,
            currentWordCategory: this.currentWordCategory,
            players: this.players.map(p => ({
                id: p.id,
                userId: p.userId,
                userName: p.userName,
                userAvatar: p.userAvatar,
                score: p.score,
                isDrawing: p.isDrawing,
                hasGuessed: p.hasGuessed,
                isConnected: p.isConnected,
                isSpectator: p.isSpectator
            })),
            drawerId: this.players.find(p => p.isDrawing)?.id || null,
            drawerUserId: this.players.find(p => p.isDrawing)?.userId || null,
            gameHistory: this.state === "GAME_END" ? this.gameHistory : [],
        };

        // On ne doit pas envoyer currentWord à tout le monde
        const isRevealPhase = (this.state === "ROUND_END" || this.state === "GAME_END");

        this.players.forEach(p => {
            const personalState = { ...publicState };
            
            // Drawer identification
            const drawingPlayer = this.players.find(p => p.isDrawing);
            const drawerUserId = drawingPlayer?.userId;
            const isActuallyDrawing = p.isDrawing || (drawerUserId && p.userId === drawerUserId);

            // Obfucation du mot et des choix
            if (!isActuallyDrawing && !isRevealPhase) {
                personalState.currentWord = "";
                if (this.state === "SELECTING_WORD") personalState.wordChoices = [];
                // L'icône n'est révélée qu'aux devineurs si showIconHint est vrai
                if (!this.showIconHint) personalState.currentWordIcon = undefined;
            }
            
            if (isActuallyDrawing) {
                personalState.currentWordIcon = this.currentWordIcon;
                personalState.currentWord = this.currentWord;
            }
            
            this.emitTo(p.id, "skribbl:state:sync", personalState);
        });
    }

    public updateSettings(config: any) {
        if (this.state !== "LOBBY") return;
        if (config.rounds !== undefined) this.maxRounds = config.rounds;
        if (config.difficulty !== undefined) this.difficulty = config.difficulty;
        if (config.categories !== undefined) this.allowedCategories = config.categories;
        this.syncState();
    }

    public startGame() {
        if (this.state !== "LOBBY") return;
        if (this.players.filter(p => p.isConnected && !p.isSpectator).length < 1) {
            this.emitToAll("skribbl:chat:message", { type: "system", text: "Il faut au moins 1 joueur pour lancer la partie." });
            return;
        }

        this.state = "SELECTING_WORD";
        this.currentRound = 1;
        this.drawerIndex = -1; // Sera incrémenté dans startNextTurn
        this.startNextTurn();
    }

    private startNextTurn(originalDrawerIndex?: number): void {
        const connectedPlayers = this.players.filter(p => p.isConnected && !p.isSpectator);
        if (connectedPlayers.length < 1) {
            console.warn(`[Skribbl:${this.id}] ⚠️ No eligible players (connected & not spectator). Returning to Lobby.`);
            this.state = "LOBBY";
            this.syncState();
            return;
        }

        // Initialize original index on first call of this turn
        if (originalDrawerIndex === undefined) {
            originalDrawerIndex = this.drawerIndex;
        }

        this.drawerIndex++;
        // Si on a fait le tour de tous les joueurs, c'est la fin du round !
        if (this.drawerIndex >= this.players.length) {
            this.drawerIndex = 0;
            this.currentRound++;
        }
        
        if (this.currentRound > this.maxRounds) {
            this.endGame();
            return;
        }

        const nextDrawer = this.players[this.drawerIndex];

        // S'il est déco ou spectateur, on skip à la récursion suivante
        if (!nextDrawer || !nextDrawer.isConnected || nextDrawer.isSpectator) {
            // Safety break: If we've looped back to the start without finding anyone
            if (this.drawerIndex === originalDrawerIndex) {
                 console.error(`[Skribbl:${this.id}] ❌ Loop error: No eligible drawer found in a full cycle.`);
                 this.state = "LOBBY";
                 this.syncState();
                 return;
            }
            return this.startNextTurn(originalDrawerIndex);
        }

        this.players.forEach(p => {
            p.hasGuessed = false;
            p.isDrawing = false; // Reset all, then set for current drawer
        });

        this.currentWord = "";
        this.currentWordIcon = undefined;
        this.currentWordMask = "";
        this.canvasActions = [];
        this.emitToAll("skribbl:draw:clear");
        this.revealedHints.clear();
        this.showIconHint = false;
        this.guessedPlayersCount = 0;
        this.hasRerolledThisTurn = false;
        const currentDrawer = this.players[this.drawerIndex];
        currentDrawer.isDrawing = true;
        this.state = "SELECTING_WORD";
        this.timeLeft = 15; // 15s pour choisir un mot
        this.emitTo(nextDrawer.id, "skribbl:sound:play", "success");

        this.wordChoices = getDofusWords(3, this.difficulty, this.usedWords, this.allowedCategories);
        console.log(`[Skribbl] Word choices for ${nextDrawer.userName}:`, JSON.stringify(this.wordChoices));

        this.emitToAll("skribbl:chat:message", { type: "system", text: `${nextDrawer.userName} choisit un mot...` });
        this.syncState();

        // 15 secondes pour choisir, sinon ça choisit au pif
        this.startTimer(() => {
            const fallback = this.wordChoices[0] || { word: "Iop" };
            this.handleWordChoice(nextDrawer.id, fallback.word);
        });
    }

    public handleWordChoice(socketId: string, word: string) {
        if (this.state !== "SELECTING_WORD") return;
        const drawer = this.players[this.drawerIndex];
        if (!drawer || drawer.id !== socketId) return;

        const choice = this.wordChoices.find(c => c.word === word);
        if (!choice) {
            console.warn(`[SkribblRoom:${this.id}] ⚠️ Word choice rejected: ${word} was not in choices.`);
            this.emitTo(socketId, "skribbl:chat:message", { type: "system", text: "Ce mot n'était pas dans la liste !" });
            return;
        }
        
        this.currentWord = choice.word;
        this.currentWordIcon = choice.iconUrl;
        this.currentWordCategory = choice.category;
        console.log(`[SkribblRoom:${this.id}] 📝 Set word: "${this.currentWord}" (Category: ${this.currentWordCategory})`);
        
        this.usedWords.add(this.currentWord.toLowerCase()); // On retient qu'il a été utilisé
        this.currentWordMask = this.currentWord.replace(/[a-zA-ZÀ-ÿ0-9]/g, "_");
        this.revealedHintIndexes.clear();
        this.state = "DRAWING";

        this.emitToAll("skribbl:chat:message", { type: "system", text: `${drawer.userName} dessine !` });
        this.emitTo(drawer.id, "skribbl:word:start", { word: this.currentWord }); // Lui dire quel mot c'est

        this.syncState();

        this.timeLeft = this.roundDuration;
        this.startTimer(() => {
            this.endRound();
        });
    }

    public handleWordReroll(socketId: string) {
        if (this.state !== "SELECTING_WORD" || this.hasRerolledThisTurn) return;
        const drawer = this.players[this.drawerIndex];
        if (!drawer || drawer.id !== socketId) return;

        this.hasRerolledThisTurn = true;
        this.wordChoices = getDofusWords(3, this.difficulty, this.usedWords, this.allowedCategories);
        this.syncState();
    }

    public handleGuess(socket: Socket, text: string) {
        const player = this.players.find(p => p.id === socket.id);
        if (!player || player.isDrawing || player.hasGuessed || player.isSpectator || this.state !== "DRAWING") return;

        const guess = text.trim();
        const dist = levenshteinDistance(guess, this.currentWord);
        const maxLen = Math.max(guess.length, this.currentWord.length);

        // Distance stricte == 0 -> Exact !
        if (dist === 0) {
            player.hasGuessed = true;
            this.guessedPlayersCount++;

            // Score du devineur basé sur la vitesse (max 1000)
            const timeRatio = this.timeLeft / this.roundDuration;
            const baseScore = Math.round(timeRatio * 900) + 100;
            const penalty = (this.guessedPlayersCount - 1) * 50;
            const points = Math.max(50, baseScore - penalty);

            player.score += points;
            this.guessersScoresThisRound.push(points);

            this.emitToAll("skribbl:chat:message", { type: "success", text: `${player.userName} a trouvé le mot !` });
            this.emitTo(socket.id, "skribbl:sound:play", "success");
            this.emitToAll("skribbl:sound:play", "ding"); // Notifier tout le monde joyeusement
            this.syncState();

            this.checkRoundEndConditions();
        }
        // Distance proche (faute de frappe)
        else if (dist <= 2 && maxLen > 4) {
            // Seulement visible pour le joueur qui a presque trouvé
            this.emitToAll("skribbl:chat:message", { type: "guess", text: `${player.userName}: ${guess}` });
            this.emitTo(socket.id, "skribbl:chat:message", { type: "warning", text: `'${guess}' est presque exact !` });
        }
        // Différence de 1 lettre autorisée pour "C'est presque ça !"
        else if (dist === 1 && text.length > 3) {
            this.emitTo(socket.id, "skribbl:chat:message", { type: "system", text: `'${text}' est presque correct !` });
            return;
        }

        // Sinon message normal
        this.emitToAll("skribbl:chat:message", {
            sender: player.userName,
            text,
            userId: player.userId
        });
        
        // Son de "raté" pour celui qui a tapé (si c'est pas le mot exact)
        this.emitTo(socket.id, "skribbl:sound:play", "fail");
    }

    private checkRoundEndConditions() {
        // Si tout le monde (sauf le dessinateur et spectateurs) a trouvé, round end
        const activeGuessers = this.players.filter(p => p.isConnected && !p.isDrawing && !p.isSpectator);
        const allGuessed = activeGuessers.every(p => p.hasGuessed);

        if (allGuessed && activeGuessers.length > 0) {
            this.endRound();
        }
    }

    private endRound() {
        this.stopTimer();
        
        // Store round in history before clearing
        this.gameHistory.push({
            word: this.currentWord,
            drawer: this.players[this.drawerIndex]?.userName || "Inconnu",
            canvasActions: [...this.canvasActions]
        });

        this.state = "ROUND_END";

        // Logic for drawer points
        const drawer = this.players[this.drawerIndex];
        if (drawer) {
            if (this.guessersScoresThisRound.length > 0) {
                const totalGuessersPoints = this.guessersScoresThisRound.reduce((a, b) => a + b, 0);
                const avgGuesserPoints = totalGuessersPoints / this.guessersScoresThisRound.length;
                
                // Le dessinateur gagne une portion du score moyen
                const drawerPoints = Math.round(avgGuesserPoints * 0.75);
                drawer.score += drawerPoints;

                this.emitToAll("skribbl:chat:message", { 
                    type: "system", 
                    text: `${drawer.userName} (Dessinateur) gagne +${drawerPoints} points !` 
                });
            } else {
                this.emitToAll("skribbl:chat:message", { 
                    type: "system", 
                    text: `Personne n'a trouvé ! 0 points pour ${drawer.userName}.` 
                });
            }
        }

        // Fin de round, montrer le mot
        if (this.currentWord) {
            this.currentWordMask = this.currentWord;
            this.emitToAll("skribbl:chat:message", { type: "system", text: `Le mot était : ${this.currentWord}` });
        } else {
             this.emitToAll("skribbl:chat:message", { type: "system", text: `Le tour est annulé (dessinateur absent).` });
        }
        this.syncState();

        this.guessersScoresThisRound = [];

        setTimeout(() => {
            if (this.state === "ROUND_END") {
                this.startNextTurn();
            }
        }, 5000);
    }

    private async endGame() {
        this.state = "GAME_END";
        this.emitToAll("skribbl:chat:message", { type: "system", text: "La partie est terminée !" });
        
        // Trier les joueurs par score
        const winners = [...this.players].sort((a, b) => b.score - a.score);
        if (winners.length > 0) {
            this.emitToAll("skribbl:chat:message", { type: "system", text: `Le vainqueur est ${winners[0].userName} avec ${winners[0].score} kamas !` });
        }
        
        this.syncState();

        // --- HALL OF FAME PERSISTENCE ---
        try {
            const validPlayers = this.players.filter(p => !p.isSpectator && p.userId);
            // On ne compte que si il y a au moins 2 joueurs (pas de solo)
            if (validPlayers.length > 1) {
                for (const p of validPlayers) {
                    // 1. Sauvegarder le score individuel
                    await db.skribblScore.create({
                        data: {
                            guildId: this.guildId,
                            userId: p.userId!,
                            userName: p.userName,
                            userAvatar: p.userAvatar,
                            score: p.score
                        }
                    });

                    // 2. Mettre à jour le rang global
                    const rank = await db.skribblRank.upsert({
                        where: { guildId_userId: { guildId: this.guildId, userId: p.userId! } },
                        create: {
                            guildId: this.guildId,
                            userId: p.userId!,
                            userName: p.userName,
                            userAvatar: p.userAvatar,
                            bestScore: p.score,
                            totalPoints: p.score,
                            gamesPlayed: 1
                        },
                        update: {
                            userName: p.userName,
                            userAvatar: p.userAvatar,
                            totalPoints: { increment: p.score },
                            gamesPlayed: { increment: 1 }
                        }
                    });

                    // Update bestScore if needed
                    if (p.score > rank.bestScore) {
                        await db.skribblRank.update({
                            where: { id: rank.id },
                            data: { bestScore: p.score }
                        });
                    }
                }
            }
        } catch (error) {
            console.error("[SkribblRoom] Error saving Hall of Fame:", error);
        }
        
        setTimeout(() => {
            this.state = "LOBBY";
            this.currentRound = 0;
            this.drawerIndex = -1;
            this.players.forEach(p => p.score = 0);
            this.usedWords.clear();
            this.gameHistory = [];
            this.syncState();
        }, 10000); // 10 sec de podium
    }

    private checkHintReveal() {
        if (!this.currentWord || this.currentWord.length <= 2) return;
        const totalDuration = this.roundDuration;
        const elapsed = totalDuration - this.timeLeft;
        const ratio = elapsed / totalDuration;

        let shouldRevealCount = 0;
        if (ratio >= 0.35) shouldRevealCount = 1;
        if (ratio >= 0.65) shouldRevealCount = 2; // ~21s left
        if (this.timeLeft <= 15) shouldRevealCount = 3; // Final rush hint!
        
        // Very long words can have an extra hint
        if (ratio >= 0.85 && this.currentWord.length >= 8) shouldRevealCount = 4;

        if (this.revealedHintIndexes.size < shouldRevealCount) {
            const chars = this.currentWord.split("");
            const unrevealed = chars
                .map((c, i) => i)
                .filter(i => chars[i] !== " " && chars[i] !== "-" && chars[i] !== "'" && !this.revealedHintIndexes.has(i));
            
            if (unrevealed.length > 0) {
                const idx = unrevealed[Math.floor(Math.random() * unrevealed.length)];
                this.revealedHintIndexes.add(idx);
                
                const charArray = this.currentWordMask.split("");
                charArray[idx] = this.currentWord[idx];
                this.currentWordMask = charArray.join("");
                
                console.log(`[SkribblRoom:${this.id}] 💡 Revealed hint at index ${idx}: "${this.currentWord[idx]}" -> ${this.currentWordMask}`);
                this.syncState(); 
            }
        }

        // Hint Visuel (Icône) après ratio >= 0.4 (~24s écoulées -> 36s restantes)
        if (ratio >= 0.4 && !this.showIconHint && this.currentWordIcon) {
            this.showIconHint = true;
            this.emitToAll("skribbl:chat:message", { type: "system", text: "🚨 UN INDICE VISUEL EST APPARU !" });
            this.syncState();
        }
        
        // Message spécial quand il reste peu de temps
        if (this.timeLeft === 15) {
            this.emitToAll("skribbl:chat:message", { type: "warning", text: "Plus que 15 secondes ! Dépêchez-vous !" });
        }
    }

    private getWordMask(): string {
        return this.currentWordMask;
    }

    private startTimer(onTimeout: () => void) {
        this.stopTimer(); // Sécurité
        // Envoyer un tick toutes les secondes
        this.roundTimer = setInterval(() => {
            this.timeLeft--;
            if (this.timeLeft <= 0) {
                this.stopTimer();
                onTimeout();
            } else {
                if (this.state === "DRAWING") {
                    this.checkHintReveal();
                }
                if (this.timeLeft <= 10 && this.state === "DRAWING") {
                    this.emitToAll("skribbl:sound:play", "tick");
                }
                this.emitToAll("skribbl:time:tick", { timeLeft: this.timeLeft });
            }
        }, 1000);
    }

    private stopTimer() {
        if (this.roundTimer) {
            clearInterval(this.roundTimer);
            this.roundTimer = null;
        }
    }

    public isSpectator(socketId: string): boolean {
        return this.players.find(p => p.id === socketId)?.isSpectator || false;
    }

    public getState(): GameState { return this.state; }

    public getConnectedPlayerCount(): number {
        return this.players.filter(p => p.isConnected && !p.isSpectator).length;
    }

    public getSpectatorCount(): number {
        return this.players.filter(p => p.isConnected && p.isSpectator).length;
    }

    public getHostName(): string {
        const host = this.players.find(p => p.userId === this.hostId || p.id === this.hostId);
        return host?.userName || "Hôte";
    }

    public getPublicInfo(roomId: string) {
        return {
            roomId,
            playerCount: this.getConnectedPlayerCount(),
            spectatorCount: this.getSpectatorCount(),
            maxPlayers: 8,
            hostName: this.getHostName(),
            rounds: this.maxRounds,
        };
    }

    public destroy() {
        this.stopTimer();
    }
}

